COLLDATA("sh23799","ar",[[1,"ـ[معرفة أنواع علوم الحديث]ـ"],[2,"المؤلف: عثمان بن عبد الرحمن، أبوعمرو، تقي الدين المعروف بابن الصلاح (المتوفى: ٦٤٣هـ)"],[3,"المحقق: عبد اللطيف الهميم - ماهر ياسين الفحل"],[4,"الناشر: دار الكتب العلمية"],[5,"الطبعة: الأولى"],[6,"سنة النشر: ١٤٢٣ هـ / ٢٠٠٢ م"],[7,"عدد الأجزاء: ١"],[8,"[ترقيم الكتاب موافق للمطبوع، ومذيل بالحواشي]"],[9,"أعده للشاملة: أسامة بن الزهراء، فريق عمل المكتبة الشاملة بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ"],[10,"إنَّ الحمد لله نحمده ونستعينه ونستغفره، ونعوذ بالله من شرور أنفسنا وسيئات أعمالنا، من يهده الله فلا مضل له، ومن يضلل فلا هادي له، ونشهد أن لا إله إلا الله وحده لا شريك له."],[11,"«ونشهد أنَّ محمدًا عبده ورسوله، وأمينه على وحيه، وخيرته من خلقه وسفيره بينه وبين عباده، المبعوث بالدين القويم، والمنهج المستقيم، أرسله الله رحمة للعالمين، وإمامًا للمتقين، وحجةً على الخلائق أجمعين» (١)."],[12,"﴿يا أَيُّهَا الَّذِيْنَ آمَنُوا اتَّقُوا اللهَ حَقَّ تُقَاتِهِ وَلاَ تَمُوْتُنَّ إِلاَّ وَأَنْتُمْ مُسْلِمُوْنَ﴾."],[13,"آل عمران: ١٠٢."],[14,"﴿يا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَاءً واتَّقُوا اللهَ الَّذِي تَسَاءلُوْنَ بهِ وَالأَرْحَامِ إنَّ اللهَ كَانَ عَلَيْكُمْ رَقِيْبًا﴾. النساء: ١."],[15,"﴿يا أَيُّهَا الَّذِيْنَ آمَنُوا اتَّقُوا اللهَ وَقُوْلُوا قَوْلًا سَدِيْدًا * يُصْلِحْ لَكُمْ أَعْمَالَكُمْ ويَغْفِرْ لَكُمْ ذُنُوْبَكُمْ وَمَنْ يُطِعِ اللهَ وَرَسُوْلَهُ فَقَدْ فَازَ فَوْزًا عَظِيْمًا﴾. الأحزاب: ٧٠ - ٧١."],[16,"أما بعد:"],[17,"فقد اصطفى الله تعالى هذه الأمة، وشرّفها إذ اختار لها هذا الدين القويم، وجعل أساسها المشيد وركنها الركين «كتابه العزيز»، وهيَّأ هذه الأمة لتضطلع بتلك المهمة، ألا وهي حفظ هذا الكتاب الذي تعهد الله تبارك وتعالى سلفًا بحفظه، فقال:"],[18,"﴿إنَّا نَحْنُ نَزَّلنَا الذِّكْرَ وإنَّا لَهُ لَحافِظُونَ﴾. الحجر: ٩، فرزقها جودة الفهم وقوة الحافظة، ووفور الذهن، فلم يتمكن أحد - بحمد الله - من أن يجرأ فيزيد أو ينقص حرفًا أو حركةً منه.","",{"fn":"من مقدمة زاد المعاد ١/ ٣٤ للعلامة ابن القيم."}],[19,"ولما تعهَّد الله تعالى بحفظ القرآن الكريم، كان مما احتواه هذا العهد ضمنًا حفظ سنة رسول الله - صلى الله عليه وآله وسلم -، ومن ذلك حفظ أحاديث المصطفى - صلى الله عليه وآله وسلم - بأسانيدها فكان الإسناد أحد الخصائص التي اختص الله تعالى بها أمة صفيِّه - صلى الله عليه وآله وسلم -."],[20,"ولقد أدرك الصدر الأول أهمية ذلك، فروى الإمام مسلم (١) وغيره عن محمد ابن سيرين أنه قَالَ: «إنَّ هذا العلم دين، فانظروا عمن تأخذون دينكم» وروى (٢) عنه أنه قال: «لم يكونوا يسألون عن الإسناد، فلما وقعت الفتنة، قالوا: سمّوا لنا رجالكم، فينظر إلى أهل السنة فيؤخذ حديثهم، وينظر إلى أهل البدع فلا يؤخذ حديثهم»."],[21,"ومن ثَمَّ افتقر الأمر إلى معرفة ضبط الراوي وصدقه، فكانت الحاجة ماسة إلى استكمال هذا الأمر، فكان نشوء «علم الجرح والتعديل» أو «علم الرجال»."],[22,"وعلى الرغم من أن هذا العلم لم يكن فجائي الظهور، إلا أنه لا مناص من القول بأنه كان مبكر الظهور جدًا، وينجلي ذلك مما نقلناه سالفًا عن ابن سيرين، وقد كان المسلمون مطمئنين إلى أن الله تعالى يهيئ لهذا الأمر من يقوم به ويتحمل أعباء هذه المهمة الجسيمة، فقد أسند ابن عدي في مقدمة \" الكامل \" (٣)، وابن الجوزي في مقدمة \" الموضوعات \" (٤) أنه قيل لعبد الله بن المبارك: هذه الأحاديث المصنوعة؟ فَقَالَ: تعيش لها الجهابذة، ﴿إنَّا نَحْنُ نَزَّلنَا الذِّكْرَ وإنَّا لَهُ لَحافِظُونَ﴾."],[23,"وعلم الحديث دراية ورواية من أشرف العلوم وأجلِّها، بل هو أجلها عَلَى الإطلاق بعد العلم بالقرآن الكريم الذي هو أصل الدين ومنبع الطريق المستقيم، فالحديث هو المصدر الثاني للتشريع الإسلامي بعضه يستقل بالتشريع، وكثير منه شارح لكتاب الله تَعَالَى مبين له قال تَعَالَى: ﴿وأَنْزَلْنا إِلَيْكَ الذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ﴾ (٥) وعلم الحديث تتفرع تحته علوم كثيرة ومن تلك العلوم: علم مصطلح الحديث وهو العلم الذي يكشف عن مصطلحات المحدِّثين التي يتداولونها في مصنفاتهم ودروسهم، وكتاب ابن الصلاح هذا كان واحدًا من أحسن الكُتُب التي أُلِّفَتْ في علم مصطلح الحديث. قال الحافظ العراقي: «أحسن ما صنف أهل الحديث في معرفة الاصطلاح كتاب علوم الحديث لابن الصلاح» (١)، وربما كان ذَلِكَ لما حبا الله به ابن الصلاح من فطنة عالية، وجودة ذهن، وحسن قريحة، وسلاسة أسلوب، واستفادته من لَمِّ شتات كتب من سبقه بهذا الباب، قال الحافظ ابن حجر العسقلاني: «من أول من صنف في ذَلِكَ (٢) القاضي أبو مُحَمَّد الرامهرمزي كتابه \" الْمُحَدِّث الفاصل \" لكنه لَمْ يستوعب، والحاكم أبو عبد الله النيسابوري، لكنه لَمْ يهذب ولم يرتب، وتلاه أبو نعيم الأصبهاني، فعمل عَلَى كتابه مستخرجًا وأبقى أشياء للمتعقب. ثُمَّ جاء بعدهم الخطيب أبو بكر البغدادي، فصنف في قوانين الرواية كتابًا سماه \" الجامع لآداب الشَّيْخ والسامع ...، ثُمَّ جاء بعدهم بعض من تأخر عن الخطيب فأخذ من هذا العلم بنصيب: فجمع القاضي عياضٌ كتابًا لطيفًا سماه \" الإلماع \" وأبو حفص الميانجي جزءًا سماه \" مالايسع الْمُحَدِّث جهله \" وأمثال ذَلِكَ من التصانيف التي اشتهرت وبسطت ليتوفر علمها واختصرت ليتيسر فهمها إلى أن جاء الحافظ الفقيه تقي الدين أبو عمرو عثمان بن الصلاح عبد الرحمان الشهرزوري نزيل دمشق - فجمع لما ولي تدريس الحديث بالمدرسة الأشرفية - كتابه المشهور، فهذَّب فنونه وأملاه شيئًا بعد شيء؛ فلهذا لَمْ يحصل ترتيبه عَلَى الوضع المتناسب، واعتنى بتصانيف الخطيب المتفرقة فجمع شتات مقاصدها وضمَّ إليها من غيرها نخب فوائدها، فاجتمع في كتابه ما تفرَّقَ في غيره، فلهذا عكف الناس عليه وساروا بسيره، فلا يحصى كم ناظم له ومختصر ومستدرك عليه ومقتصر ومعارض له ومنتصر» (٣).","",{"fn":"مقدمة صحيح مسلم ١/ ١٤ طبعة عبد الباقي.\nالمصدر السابق ١/ ١٥.\n١/ ١٩٢.\n١/ ٤٦.\nالنحل: ٤٤"}],[24,"ونحن نكتفي بقول الحافظ ابن حجر عن سوق أقوال أئمة آخرين في بيان أهمية وجودة هذا الكتاب، وعَلَى الرغم من نفاسة هذا الكتاب وأهميته البالغة فإنه لم يطبع طبعة علمية محققة تتجلى من خلالها نصوص الكتاب، وتضبط بالشكل، ويتكلم في إيضاح مسائله وغوامضه والتنكيت والتعقيب على بعض ما انتقد عَلَى المصنف. من هنا شمّرنا عن ساعد الجدِّ في تحقيق نص الكتاب وضبطه وضبط نص الكتاب عَلَى ثلاث نسخ خطية مع الإفادة من الطبعات المتداولة، وكان من أفضل الطبعات السابقة لهذا الكتاب:","",{"fn":"التقييد والإيضاح: ١١.\nيعني: المصطلح.\nنزهة النظر: ٤٦ - ٥١، تحقيق: علي الحلبي."}],[25,"أولًا: طبعة الدكتور الفاضل نور الدين عتر: سنة ١٩٦٦، نشر المكتبة العلمية بالمدينة المنورة، وهي طبعة جيدة قياسًا عَلَى سوابقها، لكن مع الجهد الذي قام به الدكتور الفاضل إلاَّ أنَّهُ حصل في نشرته بعض سقط وزيادات وتصحيفات وراجع عَلَى سبيل المثال تعليقنا على الصفحات الآتية:"],[26,"٧١، ٧٣، ٧٤، ٧٦، ٩٥، ٢٣٢، ٢٤٤، ٢٥٠، ٢٦٣، ٢٦٤، ٢٧١، ٢٨٦، ٢٩٠، ٢٩٧، ٢٩٨، ٣٠٦، ٣٠٩، ٣١٣، ٣١٩، ٣٢٠، ٣٢١، ٣٢٣، ٣٢٥، ٣٢٦، ٣٢٩، ٣٣١، ٣٣٣، ٣٣٤، ٣٣٥، ٣٣٧، ٣٣٩، ٣٤٠، ٣٤٧، ٣٥١، ٣٥٣، ٣٥٤، ٣٥٥، ٣٦٧، ٣٨٤، ٣٩٢، ٣٩٥، ٤٠١."],[27,"ثانيًا: طبعة الدكتورة الفاضلة عائشة عبد الرحمان (بنت الشاطئ): فقد حققت الدكتورة الفاضلة عائشة كتاب \"محاسن الاصطلاح\" للبلقيني سنة ١٩٧٤ م، وطبعت معه كتاب \"معرفة أنواع علم الحديث\" لابن الصلاح، وجعلته متنًا في الأعلى وجعلت المحاسن في الحاشية، وهذه الطبعة دون الطبعة السابقة، وقد حصل فيها كسابقتها بعض سقط وتصحيف وزيادات، راجع على سبيل المثال الصفحات الآتية:"],[28,"٧١، ٧٣، ٧٤، ٧٥، ٧٦، ٧٧، ٧٨، ٨٢، ٨٥، ٨٧، ٩٧، ٢٤٢، ٢٤٦، ٢٥٣، ٢٥٦، ٢٥٨، ٢٦٢، ٢٦٥، ٢٦٦، ٢٦٧، ٢٦٨، ٢٧١، ٢٧٤، ٢٧٥، ٢٧٨، ٢٧٩، ٢٨١، ٢٨٢، ٢٨٣، ٢٨٤، ٢٨٧، ٢٨٨، ٢٩٣، ٢٩٤، ٢٩٧، ٣٠٣، ٣٠٤، ٣٠٥، ٣٠٧، ٣٠٩، ٣١١، ٣١٢، ٣١٤، ٣١٦، ٣١٧، ٣١٨، ٣٢٢، ٣٢٤، ٣٢٦، ٣٢٩، ٣٣٢، ٣٣٤، ٣٣٦، ٣٤٥، ٣٤٨، ٣٥٢، ٣٦٢، ٣٦٥، ٣٦٧، ٣٦٩، ٣٧٢، ٣٧٣، ٣٧٥، ٣٧٧، ٣٨٢، ٣٨٥، ٣٨٩، ٣٩١، ٣٩٢، ٣٩٥، ٣٩٨، ٤٠١، ٤٠٩."],[29,"كان هذا وأمثاله هو الدافع الوحيد الذي جعلنا نعيد تحقيق الكتاب عَلَى أحسن الطرق العصرية في تحقيق النص وضبطه مزدانًا بالشكل التام للكلمات مع التخريج الوافر والتعليق النافع مع تتبع من عقَّب ونكَّت على ابن الصلاح، بالإضافة إلى تحلية الكتاب بالفهارس المتنوعة المتقنة."],[30,"وقد رأينا أن نقدَّم لهذا الكتاب بدراسة متوسطة دالة على سيرة ابن الصلاح ومنهجه في هذا الكتاب، وقد جعلناها في أربعة فصول:"],[31,"تكلمنا في الفصل الأول عن سيرته، وتناولنا في الفصل الثاني ثقافته، وذكرنا في الفصل الثالث دراسة وافية عن الكتاب، وختمناه بالفصل الرابع الذي تكلمنا فيه عن تحقيق الكتاب والمنهج الذي سرنا عليه."],[32,"وبعد:"],[33,"فهذا كتاب \" معرفة أنواع علم الحديث \" لابن الصلاح، نقدمه لمحبي المصطفى - صلى الله عليه وآله وسلم - السائرين على هديه الراجين شفاعته يوم القيامة، قد خدمناه الخدمة التي توازي تعلقنا بسيدنا المصطفى - صلى الله عليه وآله وسلم -، بذلنا فيه ما وسعنا من جهد ومال ووقت، ولم نبخل عليه"],[34,"بشيء، وكان الوقت الذي قضّيناه فيه كله مباركًا."],[35,"وآخِر دعوانا أن الحمد لله ربِّ العالمين والصلاة والسلام على سيدنا محمد وعلى آله وصحبه والتابعين لهم بإحسان إلى يوم الدين"],[36,"المحققان"],[37,"١/ ٩ / ٢٠٠١"],[38,"الفصل الأول: سيرته"],[39,"المبحث الأول: اسمه ونسبه وكنيته"],[40,"هو تقي الدين أبو عمرو عثمان بن صلاح الدين أبي القاسم عبد الرحمان بن عثمان ابن موسى بن أبي نصر النصري الكردي الشرخاني الشهرزوري الأصل، الموصلي النشأة، الدمشقي الموطن والوفاة، الشافعي المذهب (١)."],[41,"والنَّصْري: بفتح النون وسكون الصاد المهملة وبعدها راء مهملة أيضًا؛ نسبة إلى جدِّه «أبي نصر» (٢)."],[42,"والشَّرَخاني: بفتح الشين المعجمة والراء المهملة والخاء المعجمة؛ نسبة إلى"],[43,"«شرخان» قرية من قرى شهرزور (٣)."],[44,"والشَّهْرَزُوري: بفتح الشين المعجمة وسكون الهاء وفتح الراء وضم الزاي وسكون الواو وفي آخرها راء مهملة. وهي كورة واسعة بين إربل وهمدان، تنسب إلى بانيها"],[45,"(زور بن الضحاك) (٤).","",{"fn":"انظر: وفيات الأعيان ٣/ ٢٤٣، وسير أعلام النبلاء ٢٣/ ١٤٠، وتذكرة الحفاظ ٤/ ١٤٣٠، والعبر ٥/ ١٧٧، ومرآة الجنان ٤/ ٨٤ - ٨٥، وطبقات الشافعية الكبرى ٨/ ٣٢٦، وطبقات الشافعية للإسنوي ٢/ ١٣٣، والبداية والنهاية ١٣/ ١٤٢، والنجوم الزاهرة ٦/ ٣٥٤، وطبقات الحفاظ: ٤٩٩، والدارس ١/ ١٦، وطبقات المفسرين للداوودي ١/ ٣٧٧، وطبقات الشافعية لابن هداية الله: ٢٢٠، وشذرات الذهب ٥/ ٢٢١، والأعلام ٤/ ٤٠٧.\nانظر: اللباب ٣/ ٣١١، ووفيات الأعيان ٣/ ٢٤٥.\nوفيات الأعيان ٣/ ٢٤٥.\nانظر: اللباب ٢/ ٢١٦، ومعجم البلدان ٣/ ٣٧٥، ومراصد الاطلاع ٢/ ٨٢٢."}],[46,"المبحث الثاني: مولده"],[47,"اتفق كل مَنْ ترجم لابن الصلاح على أن مولده كان سنة (٥٧٧ هـ) (١)، لا خلاف بينهم في ذلك، وإنما الخلاف كان في مكان ولادته، فالجمهور على أن ولادته كانت في مدينة «شهرزور» (٢)."],[48,"وانفرد تلميذه ابن خلّكان (٣) بالقول أن مولده كان في «شرخان»، وعلى الرغم من أن هذا الاختلاف ليس بذي بالٍ في إظهار خلافٍ ما، إلاَّ أن هذا الاختلاف - على تقدير وجوده - لا يلبث أن يزول إذا ما علمنا أن «شرخان» قرية تابعة إلى «شهرزور»، فمَنْ نَسَبَ إلى الأول فقد دقق، ومَنْ نَسَبَ إلى الثاني فقد اكتفى بذكر القطر الأعم، والله أعلم."],[49,"المبحث الثالث: أسرته ونشأته وطلبه للعلم"],[50,"لَمْ توفّر المصادر التي بين أيادينا مادة علمية عن أفراد أسرة مترجمنا، بل قصارى ما عرفناه عنهم: ما كان يتبؤه والده من المكانة الاجتماعية والمركز العلمي المرموق. ولا ضير في أن نتعرض لترجمة مقتضبة لوالده فنقول: لَمْ يكن والده صلاح الدين أبو القاسم عبد الرحمان يعرف تاريخ مولده على وجه الدقة، بل كان يخمن أنه ولد سنة"],[51,"(٥٣٩ هـ) (٤)، وطلب العلم لاسيما الفقه، وبرع فيه حتَّى «كان من جلة مشايخ الأكراد المشار إليهم» (١)، ومن ثَمَّ تقلبت به صروف الدهر ما بين موطنه والموصل، حتَّى استقر به الأمر في حلب (٢)، فتولَّى هناك التدريس في المدرسة الأسدية (٣)، حَتَّى تُوفِّي بحلب في ذي القعدة سنة (٦١٨هـ) (٤).","",{"fn":"انظر: وفيات الأعيان ٣/ ٢٢٤، وسير أعلام النبلاء ٢٣/ ١٤٠، وتذكرة الحفاظ ٤/ ١٤٣٠، والعبر ٥/ ١٧٧، وطبقات الشافعية الكبرى ٨/ ٣٢٦، والنجوم الزاهرة ٦/ ٣٥٤، والدارس ١/ ١٦، وشذرات الذهب ٥/ ٢٢١.\nانظر: المصادر السابقة.\nوفيات الأعيان ٣/ ٢٤٤، وتابعه الزركلي في الأعلام ٤/ ٢٠٧.\nانظر: وفيات الأعيان ٣/ ٢٤٤ - ٢٤٥."}],[52,"ولقد رعى الوالد ولده وأحسن تربيته، فلقَّن ابنه - الذي ظهرت عليه مخايل النباهة وعلوُّ الهمة وعظيم النشاط - الفقه، ومما يدل على ذلك ما روي عنه أنه أعاد قراءة كتاب \" المهذب \" على والده أكثر من مرة ولم يختط شاربه بعد (٥)."],[53,"والذي يبدو لنا: أن الوالد لما أحسَّ بنهم ولده للعلم، اكتفى بأن أعطاه مبادئ العلوم الأولية، ومن ثم ترك لولده مهمة اختيار طبيعة دروسه، فلم يهمل الولد تنويع مصادر معرفته، فطلب على مشايخ بلده الذين كان غالبهم من الأكراد (٦)."],[54,"وبعد أن أدرك أبو القاسم أن تطلّعات ولده تسمو به عن أن يفي بها معلمو قريته الصغيرة، فسافر به إلى مدينة الموصل (٧) - إحدى أكبر حواضر الإسلام - ولم يطل المقام به كثيرًا فيها (٨)، فما هو إلاَّ أن اشتدَّ عوده وقوي على تحمّل أعباء الحياة، حَتَّى يمَّم وجهه صوب قبلة العلم وجوهرة الشرق دار السلام \"بغداد\" (٩)، التي كانت آنذاك تعجّ بمظاهر العِلْم، وصنوف أرباب المعرفة وطلابهم، فوردها تقي الدين وسمع بها من جملة من المشايخ (١)، ثُمَّ بعد أن أحسَّ أن الرحلة سنة من يطلب هذا الشأن (الحديث)، شدَّ رحاله إلى بلاد العجم، ولزم فيها الإمام الرافعي (٢) وبه تفقه وبرع في مذهب الشافعي (٣).","",{"fn":"وفيات الأعيان ٣/ ٢٤٣.\nانظر: تاريخ الإسلام وفيات (٦١٨ هـ) ص: ٣٦٤، الترجمة (٥٣٢).\nانظر: سير أعلام النبلاء ٢٢/ ١٤٨. وهذه المدرسة منسوبة إلى بانيها أسد الدين شيركوه بن شاذي. ولم يبقَ منها اليوم سوى قبلتها وقبة، وقد رمّمت فيها سنة (١٣١٦هـ) ثماني حجرات. انظر: وفيات الأعيان ٣/ ٢٤٣، وخطط الشام ٦/ ١٠٤.\nانظر: تاريخ الإسلام وفيات (٦١٨ هـ)، وسير أعلام النبلاء ٢٢/ ١٤٨.\nانظر: وفيات الأعيان ٣/ ٢٤٣.\nانظر: مقدمتنا لشرح التبصرة والتذكرة ١/ ١١.\nانظر: سير أعلام النبلاء ٢٣/ ١٤٠.\nانظر: تذكرة الحفاظ ٤/ ١٤٣٠.\nانظر: الدارس ١/ ١٦، وتاريخ علماء بغداد: ١٤٠."}],[55,"ثُمَّ أجاب أبو عمرو داعي العلم في خراسان حيث الأسانيد العالية التي يرغب فيها أهل الحديث، فدخل نيسابور، ومرو، وهمذان، إلاَّ أن أبرز مَنْ لَقِيَ من المشايخ هناك: الإمام أبا الْمُظَفَّر السمعاني (٤)، وبعد أن سمع وحصّل «الكثير بالموصل وبغداد ودنيسر (٥) ونيسابور ومرو وهمذان ودمشق وحران» (٦)، وتأهّل لأن يكون إمامًا يشار إليه بالبنان. عاد أدراجه بعد رحلة طويلة جال فيها أهم مراكز العلم في بلاد المشرق الإسلامي، فدخل دمشق وقد ناهز السادسة والثلاثين من عمره الذي كانت عدد سنواته (ستة وستين عامًا)، وكان ذلك في حوالي سنة (٦١٣ هـ) (٧)."],[56,"ثُمَّ قصد القدس فأقام بها (٨)، ودرَّس في المدرسة الصلاحية وتسمى الناصرية أيضًا (٩)، ثُمَّ لما أمر الملك المعظم بهدم سور القدس (١٠)، نزح إلى دمشق مستقرًّا بها (١١)، وذلك في حدود سنة (٦٣٠ هـ) (١٢)."],[57,"ولا نُغْفِل أن أبا عمرٍو سافر إلى الحرمين حاجًّا، - قَبْلَ استقراره في دمشق وبعدها - وهو لَمْ يعدم في سفرته هذه علمًا يضيفه إلى مخزون علمه (١٣).","",{"fn":"انظر: سير أعلام النبلاء ٢٣/ ١٤١.\nستأتي ترجمته في مبحث: شيوخه.\nانظر: طبقات الشافعية لابن هداية الله: ٢٢١.\nستأتي ترجمته في مبحث: شيوخه.\nبضم أوله: بلدة عظيمة مشهورة من نواحي الجزيرة، وتدعى: قوج حصار. معجم البلدان ٢/ ٤٧٨.\nطبقات الشافعية للإسنوي: ٢/ ١١٣.\nانظر: سير أعلام النبلاء ٢٣/ ١٤٢.\nانظر: الأنس الجليل ٢/ ١٠٤.\nانظر: مرآة الجنان ٤/ ٨٥، والبداية والنهاية ١٣/ ١٤٢.\nانظر: سير أعلام النبلاء ٢٣/ ١٤١.\nانظر: شذرات الذهب ٥/ ٢٢١.\nانظر: طبقات الشافعية للإسنوي ٢/ ١٣٣.\nانظر: مقدمتنا لشرح التبصرة والتذكرة ١/ ١٢."}],[58,"المبحث الرابع: وفاته"],[59,"بعد ستة وستين من الأعوام، جاءت سكرة الموت بالحق، فاختار الله تعالى ابن الصلاح إلى جواره الكريم، ففاضت روحه في صباح (١) يوم الأربعاء الخامس والعشرين من شهر ربيع الآخر (٢)."],[60,"وقيل: ستة وعشرون (٣)، في حين اكتفى بعض المؤرخين بذكر الشهر من غير تعيين يوم منه (٤)."],[61,"وعلى كل التقديرات فإنهم متّفقون على أن وفاته كانت سنة (٦٤٣ هـ) (٥)، وكثر التأسف عليه وحمل نعشه على رؤوس الناس، وازدحم على سريره الخلق، وكان على جنازته هيبة وخشوع، فَصُلِّي عليه بجامع دمشق بعد الظهر، وشُيِّع إلى داخل باب الفرج وصُلِّي عليه هناك ثانية، ولم يقدر الناس على الخروج لدفنه؛ لأن دمشق كانت محاصرة من الخوارزمية (٦)، وَلَمْ يخرج مَعَهُ إلاَّ نحو عشرة أَنْفُس مخاطرين حَتَّى دفنوه في مقابر الصوفية خارج باب النصر (٧)، فرحمه الله (٨).","",{"fn":"وقال الذهبي: «في السحر». سير أعلام النبلاء ٢٣/ ١٤٣، وقال ابن كثير: «ليلة الأربعاء». البداية والنهاية ١٣/ ١٤٢.\nانظر: وفيات الأعيان ٣/ ٢٤٤، وتذكرة الحفاظ ٤/ ١٤٣١، وطبقات الشافعية الكبرى ٨/ ٣٢٧، وطبقات الشافعية للإسنوي ٢/ ١٣٤، والبداية والنهاية ١٣/ ١٤٢، وطبقات الحفاظ: ٥٠٣، وطبقات الشافعية لابن هداية الله: ٢٢١، وشذرات الذهب ٥/ ٢٢٢.\nانظر: الذيل على الروضتين: ١٧٥، والعبر ٥/ ١٧٨، والدارس ١/ ١٧.\nانظر: مرآة الجنان ٤/ ٨٥، وطبقات الشافعية لابن قاضي شهبة ٢/ ١١٥، والنجوم الزاهرة ٦/ ٣٥٤.\nانظر: المصادر السابقة جميعها.\nهم أقوام ينسبون إلى «خوارزم»، وهي سلطنة نشأة في القرون الوسطى، وكان دخولهم إلى الإسلام بواسطة السلاجقة الأتراك، وقد استعان بهم الملك الصالح أيوب صاحب مصر لأخذ دمشق من يد عمِّهِ الملك الصالح إسماعيل. انظر: سير أعلام النبلاء ٢٣/ ١٤٣، ومرآة الجنان ٤/ ٨٣ - ٨٤.\nقال السبكي: «قبره على الطريق في طرفها الغربي، ظاهر يزار ويتبرك به». طبقات الشافعية الكبرى ٨/ ٣٢٨. قال شعيب الأرناؤوط: «وقد درست، وقام مكانها عمائر ومستشفى ومسجد». هامش سير أعلام النبلاء ٢٣/ ١٤٣.\nانظر: وفيات الأعيان ٣/ ٢٤٣، وسير أعلام النبلاء ٢٣/ ١٤٣، وتذكرة الحفاظ ٤/ ١٤٣١ والعبر ٥/ ١٧٨، ومرآة الجنان ٤/ ٨٥، وطبقات الشافعية الكبرى ٨/ ٣٢٧، وطبقات الشافعية = =للإسنوي ٢/ ١٣٤، والبداية والنهاية ١٣/ ١٤٢، وطبقات الشافعية لابن قاضي شهبة ٢/ ١١٥، والنجوم الزاهرة ٦/ ٣٥٤، وطبقات الحفاظ: ٥٠٣، والدارس ١/ ١٧، وطبقات المفسرين للداوودي ١/ ٣٧٧، وطبقات الشافعية لابن هداية الله: ٢٢١، وشذرات الذهب ٥/ ٢٢٢، والأعلام ٤/ ٢٠٧."}],[62,"الفصل الثاني: ثقافته"],[63,"المبحث الأول: شيوخه"],[64,"حرص المترجَم على أن يتلقى العلم من أفواه الرجال على ما جرت به عادة أهل الإسلام، فرحل في سبيل ذلك - كما قدّمنا - إلى كثير من الأقطار، فبعد إقامته بالموصل «دخل بغداد، وطاف البلاد، وسمع من خلق كثير وجمٍّ غفير ببغداد، وهمذان، ونيسابور، ومرو، وحران، وغير ذلك، ودخل الشام مرتين» (١)."],[65,"لذا رأينا أن نذكرهم على حسب بلدانهم التي سمع فيها منهم المترْجَم:"],[66,"الموصل:"],[67,"١. عماد الدين أبو حامد مُحَمَّد بن يونس بن منعة الإربلي ثُمَّ الموصلي الفقيه الشافعي، ت (٦٠٨ هـ) (٢)."],[68,"٢. أبو جعفر عبيد الله بن أحمد المشهور بـ: ابن السَّمين (٣)، ت (٥٨٨ هـ) (٤)، وهو أقدم شيخ له (٥)."],[69,"٣. نصر بن سلامة الهيتي (٦).","",{"fn":"مرآة الجنان ٤/ ٨٥ - ٨٦، وانظر: طبقات الشافعية لابن قاضي شهبة ٢/ ١١٣، والدارس ١/ ١٦.\nانظر: وفيات الأعيان ٣/ ٢٤٣، وتذكرة الحفاظ ٤/ ١٤٣٠، وترجمته في: الكامل لابن الأثير ١٢/ ١٤٣، والتكملة لوفيات النقلة ترجمة (١١٩٨)، ووفيات الأعيان ٤/ ٢٥٣، وسير أعلام النبلاء ٢١/ ٤٩٨، وطبقات الشافعية الكبرى ٥/ ٤٥، والبداية والنهاية ١٣/ ٦٢.\nانظر: سير أعلام النبلاء ٢٣/ ١٤٠، وطبقات الشافعية الكبرى ٨/ ٣٢٦.\nانظر: سير أعلام النبلاء ٢١/ ٢٢٩.\nانظر: طبقات الشافعية الكبرى ٨/ ٣٢٦.\nانظر: سير أعلام النبلاء ٢٣/ ١٤٠، وطبقات الشافعية الكبرى ٨/ ٣٢٦."}],[70,"٤. محمود بن علي الموصلي (١)."],[71,"٥. عبد المحسن بن الطوسي (٢)."],[72,"٦. أبو الْمُظَفَّر بن البرني (٣)."],[73,"بغداد:"],[74,"٧. أبو أحمد ضياء الدين عبد الوهاب بن أبي منصور علي بن عبيد الله بن سكينة البغدادي الصوفي الشافعي (٤)، شيخ الشيوخ الإمام العالم الفقيه المحدِّث الثقة المعمر القدوة الكبير شيخ الإسلام مفخرة العراق، ت (٦٠٧ هـ) (٥)."],[75,"٨. أبو حفص عمر بن مُحَمَّد بن مُعَمَّر بن أحمد البغدادي الدارقزي المؤدب المشهور بـ: ابن طَبَرْزَذ (٦) الشَّيْخ المسند الكبير الرحلة، ت (٦٠٧ هـ) (٧)."],[76,"بلاد العجم:"],[77,"٩. أبو القاسم عبد الكريم بن أبي الفضل محمد بن عبد الكريم بن الفضل بن الحسين الرافعي القزويني (٨) شيخ الشافعية عالم العجم والعرب إمام الدين، ت (٦٢٣ هـ) (٩).","",{"fn":"انظر: سير أعلام النبلاء ٢٣/ ١٤٠، وطبقات الشافعية الكبرى ٨/ ٣٢٦.\nانظر: المصدرين السابقين.\nانظر: ما سبق.\nانظر: سير أعلام النبلاء ٢٣/ ١٤٠، وتذكرة الحفاظ ٤/ ١٤٣٠.\nترجمته في: الكامل ١٢/ ١٢٢، والتكملة (١١٤٦)، وسير أعلام النبلاء ٢١/ ٥٠٢، والبداية والنهاية ١٣/ ٦١.\nانظر: سير أعلام النبلاء ٢٣/ ١٤٠، وتذكرة الحفاظ ٤/ ١٤٣٠.\nترجمته في: الكامل ١٢/ ١٢٢، والتكملة (١١٥٨)، ووفيات الأعيان ٣/ ٤٥٢، وسير أعلام النبلاء ٢١/ ٥٠٧، والبداية والنهاية ١٣/ ٦١، والنجوم الزاهرة ٦/ ٢٠١، وشذرات الذهب ٥/ ٢٦.\nانظر: طبقات الشافعية الكبرى ٨/ ٢٨٣.\nترجمته في: تهذيب الأسماء واللغات ٢/ ٢٦٤، وسير أعلام النبلاء ٢٢/ ٢٥٢، والعبر ٥/ ٩٤، وفوات الوفيات ٢/ ٧، ومرآة الجنان ٤/ ٤٥، والنجوم الزاهرة ٦/ ٢٦٦."}],[78,"مرو:"],[79,"١٠. أبو الْمُظَفَّر فخر الدين عبد الرحيم بن الحافظ الكبير أبي سعد عبد الكريم بن محمد ابن منصور السمعاني المروزي الشافعي (١) الشَّيْخ الإمام العلاَّمة المفتي المحدِّث،"],[80,"ت (٦١٧ هـ) أو (٦١٨ هـ) (٢)."],[81,"١١. محمد بن عمر المسعودي (٣)."],[82,"١٢. مُحَمَّد بن إسماعيل الموسوي (٤)."],[83,"١٣. أبو جعفر مُحَمَّد بن مُحَمَّد السنجي (٥)."],[84,"نيسابور:"],[85,"١٤. أبو بكر، وأبو الفتح، وأبو القاسم: منصور بن مسند وقته أبي المعالي عبد المنعم ابن المحدِّث أبي البركات عبد الله بن فقيه الحرم أبي عبد الله مُحَمَّد بن الفضل بن أحمد الصاعدي الفراوي ثُمَّ النيسابوري (٦). الشَّيْخ الجليل العدل المسند، ت (٦٠٨ هـ) (٧)."],[86,"١٥. رضي الدين أبو الحسن المؤيد بن مُحَمَّد بن علي بن حسن الطُّوسي ثُمَّ النيسابوري (٨) الشَّيْخ الإمام المقرئ الْمُعَمَّر مسند خراسان، ت (٦١٧ هـ) (٩).","",{"fn":"انظر: سير أعلام النبلاء ٢٣/ ١٤١، وتذكرة الحفاظ ٤/ ١٤٣٠. وانظر: معرفة أنواع علم الحديث: ٣١٤ من هذه الطبعة.\nانظر ترجمته في: سير أعلام النبلاء ٢٢/ ١٠٧، والعبر ٥/ ٦٨، وميزان الاعتدال ٢/ ٦٠٦، ولسان الميزان ٤/ ٦، وشذرات الذهب ٥/ ٧٥.\nانظر: سير أعلام النبلاء ٢٣/ ١٤٢، وطبقات الشافعية الكبرى ٨/ ٣٢٦.\nانظر: سير أعلام النبلاء ٢٣/ ١٤٢.\nانظر: المصدر السابق.\nانظر: سير أعلام النبلاء ٢٣/ ١٤٠ - ١٤١، وتذكرة الحفاظ ٤/ ١٤٣٠.\nترجمته في: التكملة (١٢٠٢)، وتاريخ الإسلام وفيات (٦٠٨)، وسير أعلام النبلاء ٢١/ ٤٩٤، والنجوم الزاهرة ٦/ ٢٠٤، وشذرات الذهب ٥/ ٣٤.\nانظر: سير أعلام النبلاء ٢٣/ ١٤٠ - ١٤١، وتذكرة الحفاظ ٤/ ١٤٣٠، وتاريخ الإسلام وفيات (٦١٧).\nترجمته في: التكملة (١٧٦٥)، ووفيات الأعيان ٥/ ٣٤٥، وتاريخ الإسلام وفيات\n، وسير أعلام النبلاء ٢٢/ ١٠٤ - ١٠٥، والنجوم الزاهرة ٦/ ٢٥١، وشذرات الذهب ٥/ ٧٨."}],[87,"١٦. حُرَّة ناز أم المؤيد زينب بنت أبي القاسم عبد الرحمان بن الحسن بن أَحْمَد الجرجانية الأصل النيسابورية الشعرية (١) الشيخة الجليلة مسندة خراسان،"],[88,"ت (٦١٥ هـ) (٢)."],[89,"١٧. شهاب الدين أبو بكر القاسم بن الشَّيْخ أبي سعد عبد الله بن الفقيه عمر بن أَحْمَد النيسابوري ابن الصفَّار (٣) الإمام الفقيه الشافعي المسند الجليل مفتي خراسان،"],[90,"ت (٦١٨ هـ) (٤)."],[91,"١٨. مُحَمَّد بن الحسن الصرَّام (٥)."],[92,"١٩. أبو المعالي بن ناصر الأنصاري (٦)."],[93,"٢٠. إسماعيل بن عثمان بن إسماعيل بن أبي القاسم بن أبي بكر (٧)، أبو النجيب القارئ النيسابوري، ت (٦١٧ هـ) أو (٦١٨ هـ) (٨)."],[94,"همذان:"],[95,"٢١. أبو الفضل عبد الرحمان بن عبد الوهاب بن أبي زيد الْمُعَزِّم الهمذاني"],[96,"الفقيه (٩)، ت (٦٠٩ هـ) (١٠).","",{"fn":"انظر: سير أعلام النبلاء ٢٣/ ١٤٠، وتذكرة الحفاظ ٤/ ١٤٣٠.\nترجمتها في: التكملة (١٦٤٨)، ووفيات الأعيان ٢/ ٣٤٤، وتاريخ الإسلام وفيات\nانظر: سير أعلام النبلاء ٢٣/ ١٤١، وتذكرة الحفاظ ٤/ ١٤٣٠.\nترجمته في: التكملة (١٨٦٠)، وتاريخ الإسلام وفيات (٦١٨)، وسير أعلام النبلاء ٢٢/ ١٠٩، وطبقات الشافعية الكبرى ٥/ ١٤٨، والنجوم الزاهرة ٦/ ٢٥٣، وشذرات الذهب ٥/ ٨١ - ٨٢.\nانظر: سير أعلام النبلاء ٢٣/ ١٤١، وتذكرة الحفاظ ٤/ ١٤٣٠.\nانظر: المصدرين السابقين.\nانظر: المصدرين نفسيهما.\nترجمته في تاريخ الإسلام وفيات (٦١٧ هـ)، ص: ٢٩٧ - ٢٩٨ الترجمة (٤٣٧).\nانظر: تذكرة الحفاظ ٤/ ١٤٣٠، وطبقات المفسرين للداوودي ١/ ٣٧٧.\nترجمته في: التكملة (١٢٣٦)، وتاريخ الإسلام وفيات (٦٠٩ هـ)، وسير أعلام النبلاء ٢٢/ ٢٠، وشذرات الذهب ٥/ ٣٧.\n، وسير أعلام النبلاء ٢٢/ ٨٥، والنجوم الزاهرة ٦/ ٢٢٦، وشذرات الذهب ٥/ ٦٣."}],[97,"حران:"],[98,"٢٢. أبو مُحَمَّد عبد القادر بن عبد الله بن عبد الرحمان الرُّهاوي الحنبلي السفار (١) الإمام الحافظ المحدِّث الرَّحَّال الجوَّال محدِّث الجزيرة، ت (٦١٢هـ) (٢)."],[99,"دمشق:"],[100,"٢٣. فخر الدين أبو منصور عبد الرحمان بن مُحَمَّد بن الحسين بن هبة الله بن عبد الله الدمشقي الشافعي (٣) بن عساكر، الشَّيْخ الإمام العالم القدوة المفتي شيخ الشافعية، ت (٦٢٠ هـ) (٤)."],[101,"٢٤. موفق الدين أبو مُحَمَّد عبد الله بن أحمد بن مُحَمَّد بن قدامة المقدسي الجَمَّاعيلي ثُمَّ الدمشقي الصالحي الحنبلي (٥)، الشَّيْخ الإمام القدوة العلاَّمة المجتهد شيخ الإسلام، ت (٦٢٠ هـ) (٦)."],[102,"٢٥. جمال الدين أبو القاسم عبد الصمد بن مُحَمَّد بن أبي الفضل بن علي الأنصاري الدمشقي الشافعي ابن الحرستاني (٧)، الشَّيْخ الإمام العالم المفتي المعمَّر الصالح مسند الشام شيخ الإسلام قاضي القضاة، ت (٦٢٤ هـ) (٨).","",{"fn":"انظر: سير أعلام النبلاء ٢٣/ ١٤١، وتذكرة الحفاظ ٤/ ١٤٣٠.\nترجمته في: التكملة (١٣٩٩)، وتذكرة الحفاظ ٤/ ١٣٨٧، وتاريخ الإسلام وفيات (٦١٢ هـ)، وسير أعلام النبلاء ٢٢/ ٧١، والبداية والنهاية ١٣/ ٦٩، وذيل طبقات الحنابلة ... ٢/ ٨٢ - ٨٦، وشذرات الذهب ٥/ ٥٠ - ٥١.\nانظر: سير أعلام النبلاء ٢٣/ ١٤١.\nترجمته في: الكامل ١٢/ ١٧٢، والتكملة لوفيات النقلة (١٩٣٥)، ووفيات الأعيان ٣/ ١٣٥، وتاريخ الإسلام وفيات (٦٢٠ هـ)، وسير أعلام النبلاء ٢٢/ ١٨٧، وطبقات الشافعية الكبرى ٥/ ٦٦، والبداية والنهاية ١٣/ ١٠١.\nانظر: سير أعلام النبلاء ٢٣/ ١٤١.\nترجمته في: معجم البلدان ٢/ ١١٣، والتكملة (١٩٤٤)، وتاريخ الإسلام وفيات\nانظر: تذكرة الحفاظ ٤/ ١٤٣٠.\nترجمته في: معجم البلدان ٢/ ٢٤١، والتكملة (١٥٦٨)، وتاريخ الإسلام وفيات\n، وسير أعلام النبلاء ٢٢/ ١٦٥، والبداية والنهاية ١٣/ ٩٩، وذيل طبقات الحنابلة ٢/ ١٣٣، وشذرات الذهب ٥/ ٨٨.\n، وسير أعلام النبلاء ٢٢/ ٨٠، والبداية والنهاية ١٣/ ٧٨، والنجوم الزاهرة ٦/ ٢٢٠، وشذرات الذهب ٥/ ٦٠."}],[103,"حلب:"],[104,"٢٦. زين الدين أبو مُحَمَّد عبد الله بن عبد الرحمان بن عبد الله بن علوان الأسدي الشافعي (١) الشهير بـ: ابن الأستاذ، قاضي حلب. ت (٦٣٥ هـ) (٢). وغيرهم أعرضنا عن ذكرهم اختصارًا للمقام."],[105,"المبحث الثاني: تلامذته"],[106,"ما كاد ابن الصلاح يلقي عصا ترحاله مستقرًا بالقدس أوَّلًا، ثُمَّ دمشق ثانيًا، حَتَّى تقاطر عليه طلبة العلم من كل صوب، يحدوهم أمل أن يفوزوا بالتَّتلمذ على يديه، والاغتراف من معين علمه. وما كان ابن الصلاح ليتمتَّع بهذا الفضل الذي يشهد به العدو قبل الصديق، والفضل ما شهدت به الأعداء - كما يقولون - لولا صفات أهَّلته لأن يكون مَوْئِل الباحثين عن الحقيقة الناشدين عن المعرفة؛ فبات من العسير علينا أن نحصيَ تلامذة إمام بهذا المستوى؛ لذا ارتأينا الاقتصار عَلَى أشهرهم، وهم:"],[107,"١. شمس الدين أبو العباس أَحْمَد بن مُحَمَّد بن إبراهيم بن أبي بكر بن خلكان البرمكي الإربلي الشَّافِعِيّ (٣) قاضي القضاة، ت (٦٨١ هـ) صاحب الكِتَاب المَشْهُوْر"],[108,"\" وفيات الأعيان \" (٤)."],[109,"٢. عبد الرحمان بن نوح بن مُحَمَّد شمس الدين التركماني المقدسي ثُمَّ الدمشقي، أخذ عن ابن الصلاح (٥)، وكان أعرف تلاميذه بمذهب الشافعي، مولده سنة (٥٩٧ هـ)، سمع الكثير من الحديث، ودرَّس بالرواحية، وكان ذا هيبة ووقار وسمت حسن وخشوع، توفي سنة (٦٥٤ هـ)، وكان قد بلغ الخمسة والثمانين عامًا (٦).","",{"fn":"انظر: سير أعلام النبلاء ٢٣/ ١٤١، وتذكرة الحفاظ ٤/ ١٤٣٠.\nترجمته في: تاريخ الإسلام وفيات (٦٣٥ هـ)، ص: ٢٢٠ - ٢٢١، الترجمة (٣٣٣).\nانظر: وفيات الأعيان ٣/ ٢٤٣.\nترجمته في: طبقات الشافعية الكبرى ٢/ ١٦٦، والبداية والنهاية ١٣/ ٣٨، والنجوم الزاهرة ٧/ ٣٥٣.\nانظر: تذكرة الحفاظ ٤/ ١٤٧١.\nترجمته في: طبقات الشافعية الكبرى ٨/ ١٨٨، والبداية والنهاية ١٣/ ١٩٥، والدارس ١/ ٤٩، وشذرات الذهب ٥/ ٢٦٥."}],[110,"٣. كمال الدين أبو الفضائل سلار بن الحسن بن عمر الإربلي، أخذ عن ابن الصلاح (١)، قال النووي: «هو شيخنا المجمع على إمامته وجلالته وتقدمه في علم المذهب عَلَى أهل عصره، والمرجع إليه في حلِّ مشكلاته» (٢). كان مفتي الشام، وتوفي سنة (٦٧٠ هـ) عن بضع وستين سنة (٣)."],[111,"٤. كمال الدين أبو إبراهيم إسحاق بن أحمد بن عثمان المغربي ثُمَّ المقدسي، أخذ العلم عن الفخر بن عساكر ثُمَّ عن ابن الصلاح (٤)، وأعاد بعد ابن الصلاح بالرواحية عشرين سنة، توفي سنة (٦٥٠ هـ)، ودفن إلى جانب ابن الصلاح (٥)."],[112,"٥. أبو الفتح عمر بن بندار بن عمر التفليسي الشافعي القاضي، أخذ عن ابن الصلاح (٦)، وسمع الحديث وتفقه في مذهب الشافعي وبرع فيه، ولي قضاء دمشق نيابة، ثُمَّ ترك الشام وتوجه إلى مصر فأدركته المنية هناك سنة (٦٧٢ هـ) (٧)."],[113,"٦. شمس الدين أحمد بن علي بن الزبير بن سليمان القاضي الجيلي الدمشقي الشافعي الشاهد الصوفي، سمع عَلَى ابن الصلاح (٨)، توفي سنة (٧٢٤ هـ) (٩)."],[114,"٧. رشيد الدين إسماعيل بن عثمان بن مُحَمَّد بن عبد الكريم الحنفي، المعروف بـ: ابن المعلّم، كَانَ فاضلًا في مذهب الحنفية، سَمِعَ ابن الصَّلاَح (١٠) قَالَ الذهبي: كَانَ ديِّنًا مقتصدًا في لباسه متزهِّدًا، غادر دمشق ودخل القاهرة وظل فِيْهَا حَتَّى توفي سنة (٧١٤ هـ) (١).","",{"fn":"انظر: سير أعلام النبلاء ٢٣/ ١٤١، وتذكرة الحفاظ ٤/ ١٤٣١.\nتهذيب الأسماء واللغات ١/ ١٨، وانظر: طبقات الشافعية الكبرى ٨/ ١٤٩.\nترجمته في: العبر ٥/ ٢٩٣، وطبقات الشافعية الكبرى ٨/ ١٤٩، وطبقات الشافعية لابن قاضي شهبة ٢/ ١٣٢، وتهذيب الأسماء واللغات ١/ ١٨، وشذرات الذهب ٥/ ٣٣١.\nانظر: سير أعلام النبلاء ٢٣/ ١٤١.\nترجمته في: العبر ٥/ ٢٢٧، وطبقات الشافعية الكبرىللإسنوي ١/ ١٤١ - ١٤٢، والبداية والنهاية ١٣/ ٢١٣، وطبقات الشافعية لابن قاضي شهبة ٢/ ١٠٢.\nانظر: شذرات الذهب ٥/ ٣٣٧.\nترجمته في: طبقات الشافعية الكبرى ٨/ ٣٠٩، والبداية والنهاية ١٣/ ٢٦٧، وطبقات الشافعية لابن قاضي شهبة ٢/ ١٤٣، وشذرات الذهب ٥/ ٣٣٧.\nانظر: الدرر الكامنة ١/ ٢٠٩.\nترجمته في: الدرر الكامنة ١/ ٢٠٩، وشذرات الذهب ٣/ ٦٣.\nانظر: الدرر الكامنة ١/ ٤٦٩."}],[115,"٨. زين الدين أبو مُحَمَّد عبد الله بن مروان بن عبد الله بن فيروز الفارقي خطيب دمشق وشيخ دار الحديث، سمع ابن الصلاح (٢)، قال الذهبي: «كان فصيحًا متقنًا متحرّيًا لديه فضيلة جيدة مع دين وصيانة وقوة في الحق»، توفي سنة (٧٠٣ هـ) (٣)."],[116,"٩. ناصر الدين مُحَمَّد بن يوسف بن مُحَمَّد بن عبد الله المصري الأصل الدمشقي، المشهور بـ: ابن المهتار، سَمِعَ ابن الصَّلاَح (٤)، توفي سنة (٧١٥ هـ) (٥)."],[117,"١٠. عماد الدين يَحْيَى بن أَحْمَد بن يوسف بن كامل الحسيني البصروي، سَمِعَ ابن الصَّلاَح (٦)، وكان خيّرًا متواضعًا سنيًّا شافعيًّا، توفي سنة (٧٠٥هـ) (٧). وغيرهم كثير."],[118,"المبحث الثالث: نشره للعلم"],[119,"مرَّ بنا أن ابن الصلاح استوطن أولًا القدس، ومن ثم نزح إلى دمشق متخذًا مِنْهَا مستقرًّا وموطنًا، وكان المترْجَم منذ نعومة أظفاره قد تعوّد الدرس والتدريس، فعندما كان في مقتبل عمره ولا يزال غضّ العود طري البنية، وفي أول سفر له إلى الموصل، ولاَّه شيخه عماد الدين بن يونس الإعادة في درسه (١)، ثُمَّ لما اشتدّ عوده وصلب وبعد أن جمع شتات العلوم وأصبح علمًا يشار إليه، أسندت إليه مهمة التدريس في المدارس التي كانت بمثابة جامعات تُخَرِّج علماء في مختلف التخصصات، ومن تلك المدارس التي درَّس فيها أبو عمرو هي:","",{"fn":"ترجمته في: الدرر الكامنة ١/ ٤٦٩.\nانظر: الدرر الكامنة ٢/ ٣٠٤ - ٣٠٥.\nترجمته في: طبقات الشافعية الكبرى ١٠/ ٤٤، وطبقات الشافعية لابن قاضي شهبة ٢/ ٢١٥، والدرر الكامنة ٢/ ٣٠٤ - ٣٠٥، وشذرات الذهب ٣/ ٨.\nانظر: سير أعلام النبلاء ٢٣/ ١٤١.\nترجمته في: الدرر الكامنة ٤/ ٣١٣.\nانظر: الدرر الكامنة ٤/ ٤١٣.\nترجمته في: المصدر السابق."}],[120,"١. المدرسة الصلاحية (٢): وتسمَّى الناصرية أيضًا (٣)، تقع في القدس وتنسب إلى بانيها السلطان الملك الناصر صلاح الدين أبو الْمُظَفَّر يوسف بن أيوب ابن شاذي الدويني الكردي الأصل التكريتي المولد (٤)، وكان إنشاؤها سنة (٥٨٣ هـ) للشافعية، وكانت كنيسة فهدمها وبناها مدرسة (٥)، وهي الآن كنيسة للنصارى (٦)."],[121,"٢. المدرسة الرواحية (٧): وتنسب إلى بانيها زكي الدين أبي القاسم هبة الله ابن مُحَمَّد بن رواحة الحموي التاجر المعدَّل، ت (٦٢٢ هـ) (٨)، وابن الصلاح أوَّل مَنْ درَّس فيها (٩)، وتقع شرقي مسجد ابن عروة بالجامع الأموي ولصيقه، شمالي جيرون، وغربي الدولعية، وقبلي السيفية الحنبلية (١٠)، وهي الآن دار (١١).","",{"fn":"انظر: وفيات الأعيان ٣/ ٢٤٣، وتذكرة الحفاظ ٤/ ١٤٣٠.\nانظر: وفيات الأعيان ٣/ ٢٤٤، والدارس ١/ ٢٥١.\nانظر: البداية والنهاية ١٢/ ٢٨٩، وفي المطبوع من شذرات الذهب ٥/ ٢٢١: «النظامية»، وهو خطأ طباعي.\nانظر: العبر ٤/ ٢٧٠.\nانظر: البداية والنهاية ١٢/ ٢٨٩.\nانظر: خطط الشام ٦/ ١٢١.\nانظر: طبقات الشافعية للإسنوي ٢/ ١٣٣، والدارس ١/ ٢١.\nانظر: الدارس ١/ ٢٦٥، وترجمته في: العبر ٥/ ٩٢، وتاريخ الإسلام وفيات (٦٢٢ هـ) ص: ١٢٦، الترجمة (١٤٨).\nانظر: طبقات الشافعية للإسنوي ٢/ ١٣٣، والدارس ١/ ٢١.\nانظر: الدارس ١/ ٢٦٥ - ٢٦٦.\nانظر: خطط الشام ٦/ ٧٩."}],[122,"٣. دار الحديث الأشرفية (١): تقع بجوار باب القلعة الشرقي غربي المدرسة العصرونية وشمالي المدرسة القايمازية (٢)، تنسب إلى بانيها الملك الأشرف مظفر الدين موسى بن الملك العادل بن أيوب، ت (٦٣٥ هـ)، وافتتحت سنة (٦٣٠هـ)، بعد أن استغرق بناؤها سنتين، ووقف عليها أوقافًا، وأول من ولي مشيختها أبو عمرو بن الصلاح، وبقي فيها ثلاث عشرة سنة (٣)، وهي لا تزال مدرسة حَتَّى اليوم (٤)."],[123,"٤. مدرسة ست الشام زمرد خاتون (٥): وتسمَّى الشامية الجوَّانية (٦) والشامية الصغرى (٧)، وتقع قبلي المارستان النوري، تنسب إلى منشئتها ست الشام زمرد خاتون بنت نجم الدين أيوب بن شاذي بن مروان، ت (٦١٦هـ) (٨)، قال مُحَمَّد كرد علي: «وقد خربت هذه المدرسة ولم يبقَ فيها سوى بابها وواجهتها الحجرية واتخذت دارًا» (٩)."],[124,"المبحث الرابع: آثاره العلمية"],[125,"على الرغم من كل الظروف العصيبة والمهمات العديدة التي كانت تقع على عاتق ابن الصلاح؛ فإنه قد ترك لنا ثروة علمية لا يستهان بها، يمكن من خلالها أن نتصور ما كان يتمتع به هذا الإمام من عقلية صلبة وفكر فسيح، خصب الزرع وارق النتاج. ولم يكن لمشاغله المتعددة بَيْنَ تدريس في المدارس الثلاث والإفتاء ومراعاة أحوال الناس عائق في وجه شلال فكره الهادر، فكانت ثماره عظيمة أغنت المكتبة الإسلامية ببحوث إن لَمْ تكن مستوفية، فإنها كانت ذات جدة وأصالة في أكثر موضوعاتها، ففتحت الباب لمن جاء بعده لتكون تلك الآثار محور تدور في فلكه كثير من المؤلفات.","",{"fn":"انظر: سير أعلام النبلاء ٢٣/ ١٤١.\nانظر: الدارس ١/ ١٩.\nانظر: العبر ٥/ ١٧٨، طبقات الشافعية للإسنوي ٢/ ١٣٣، والدارس ١/ ٢١.\nانظر: خطط الشام ٦/ ٧٢.\nانظر: سير أعلام النبلاء ٢٣/ ١٤١.\nانظر: طبقات الشافعية الكبرى ٨/ ٣٢٧، والبداية والنهاية ١٣/ ١٦٨، وطبقات الشافعية لابن قاضي شهبة ١/ ٤٤٥.\nانظر: تذكرة الحفاظ ٤/ ١٤٣٠، وسير أعلام النبلاء ٢٣/ ١٤١، وطبقات المفسرين ١/ ٣٧٧.\nانظر: وفيات الأعيان ٣/ ٢٤٤، والدارس ١/ ٣٠١.\nخطط الشام ٦/ ٧٩."}],[126,"واستطعنا أن نقف له على ما يربو على العشرين مؤلفًا، هي:"],[127,"١. أحاديث في فضل الإسكندرية وعسقلان (١)."],[128,"٢. الأحاديث الكلية (٢)."],[129,"٣. أدب المفتي والمستفتي (٣)."],[130,"٤. الأمالي (٤)."],[131,"٥. حديث الرحمة (٥)."],[132,"٦. حكم صلاة الرغائب (٦)."],[133,"٧. حلية الإمام الشافعي (٧)."],[134,"٨. شرح معرفة علوم الحديث، للحاكم النيسابوري (٨)."],[135,"٩. شرح الورقات لإمام الحرمين في أصول الفقه (٩)."],[136,"١٠. صلة الناسك في صفة المناسك (١٠)."],[137,"١١. صيانة صحيح مسلم من الإخلال والغلط وحمايته من الإسقاط والسقط (١١).","",{"fn":"توجد منه نسخة خطية في برلين برقم (؟؟؟؟؟؟ spr). انظر: الفهرس الشامل للتراث الإسلامي (قسم الحديث) ٣/ ١٤٥٧.\nذكره ابن رجب في جامع العلوم والحكم: ٣.\nطبع بتحقيق الدكتور: موفق بن عبد الله بن عبد القادر.\nمنه نسخة في المكتبة الأزهرية برقم [(٣٧٤٩) ٩٠٣٠]. انظر: الفهرس الشامل ١/ ٢٤١.\nانظر: صلة الخلف بموصول السلف: ٣٩٨.\nانظر: صلة الخلف بموصول السلف: ٢١٥.\nمنه نسخة خطية في الظاهرية (مجموع ٥٩). انظر: الفهرس الشامل ١/ ٦٣٣.\nملء العيبة ٣/ ٢١٨.\nتوجد منه نسخ خطية. انظر: تاريخ الأدب العربي لبروكلمان ٦/ ٢١١.\nمنه نسخة خطية في دار الكتب المصرية برقم (٢١٩ م مجاميع). انظر: الفهرس الشامل ٢/ ١٠٥٢.\nطبع بتحقيق الدكتور: موفق بن عبد الله بن عبد القادر."}],[138,"١٢. طبقات فقهاء الشافعية (١)."],[139,"١٣. معرفة أنواع علم الحديث (٢)."],[140,"١٤. الفتاوى (٣)."],[141,"١٥. فوائد الرحلة (٤)."],[142,"١٦. مختصر في أحاديث الأحكام (٥)."],[143,"١٧. مشكل الوسيط (٦)."],[144,"١٨. مشكلات البخاري (٧)."],[145,"١٨. المؤتلف والمختلف في أسماء الرجال (٨)."],[146,"١٩. النكت على المهذب (٩)."],[147,"٢٠. وصل بلاغات الموطأ (١٠)."],[148,"٢١. وقف دار الحديث الأشرفية (١١).","",{"fn":"فُقِدَ ولم يبقَ سوى مختصره للنووي.\nوهو كتابنا هذا، وسنفصل القول فيه فيما يأتي.\nطبع بتحقيق الطبيب: عبد المعطي أمين قلعجي، وكان قد طبع من قبل في إدارة المطبعة المنيرية ضمن مجموعة الرسائل المنيرية.\nانظر: طبقات الشافعية الكبرى ٨/ ٣٢٧، والتقييد والإيضاح: ٣٩، والنكت على كتاب ابن الصلاح ٢/ ٥٧٣.\nتوجد نسخته الخطية في مكتبة راغب باشا برقم (١٤٧٠ مجاميع). انظر: الفهرس الشامل ٣/ ١٤٠٨.\nانظر: وفيات الأعيان ٣/ ٢٤٤، وسير أعلام النبلاء ٢٣/ ١٤٢.\nمنه نسخة خطية فريدة في مكتبة جلبي عبد الله أفندي برقم (٧٦). انظر: الفهرس الشامل ٣/ ١٤٨٦.\nتوجد منه نسخة في المكتبة الظاهرية برقم (عام ٦٨٩٧). انظر: الفهرس الشامل ٣/ ١٥٤٠.\nانظر: طبقات الشافعية للإسنوي ٢/ ١٣٤، والأنس الجليل ٢/ ١٠١.\nوهو مطبوع بعناية أبي الفضل عبد الله بن محمد بن الصديق الغماري. وطبع مرة أخرى في آخر توجيه النظر مع تعليقات الشيخ عبد الفتاح أبو غدة - يرحمه الله -.\nانظر: البداية والنهاية ١٣/ ١٦٨."}],[149,"المبحث الخامس: مكانته العلمية وثناء العلماء عليه"],[150,"أطنب العلماء في الثناء عَلَى ابن الصلاح ثناءً منقطع النظير، يدل على ما تمتع به هذا الرجل من مكانة في قلوب الناس، وما تبوَّأه من المكانة المرموقة عندهم. ويتضح هذا جليًّا من أقوالهم التي نوردها، ومنها:"],[151,"١. قول أبي عمرو بن الحاجب: «إمام ورع، وافر العقل، حسن السمت متبحر في الأصول والفروع، بالغ في الطلب حَتَّى صار يضرب به المثل، وأجهد نفسه في الطاعة والعبادة» (١)."],[152,"٢. وقول شمس الدين بن خلكان: «كان أحد فضلاء عصره في التفسير والحديث والفقه وأسماء الرجال، وما يتعلق بعلم الحديث ونقل اللغة، وكانت له مشاركة في فنون عديدة، وكانت فتاويه مسددة» (٢)."],[153,"٣. وثناء صفي الدين المراغي بقوله: «أحد الأئمة المشهورين، والعلماء العاملين، والحفاظ المذكورين، جمع بَيْنَ علوم متعددة: علم الفقه وعلم أصوله وعلم الحديث وعلم العربية، مع ما أوتي من التحري والإتقان، مضافًا إلى سلوك طريقة السلف، معظمًا عند الخاص والعام» (٣)."],[154,"٤. وأطنب الذهبي في مدحه فقال: «الإمام الحافظ العلاّمة شيخ الإسلام ... كان ذا جلالة عجيبة ووقار وهيبة، وفصاحة، وعلم نافع، وكان متين الديانة، سلفي الجُمْلة، صحيح النحلة، كافًا عن الخوض في مزلات الأقدام، مؤمنًا بالله وبما جاء عن الله من أسمائه ونعوته، حسن البزة، وافر الحرمة، معظَّمًا عند السلطان ... وكان مع تبحّره في الفقه مجوِّدًا لما ينقله، قوي المادة من اللغة والعربية، متفنّنًا في الحديث، متصونًا مُكِبًا على العلم، عديم النظير في زمانه» (١).","",{"fn":"سير أعلام النبلاء ٢٣/ ١٤٢.\nوفيات الأعيان ٣/ ٢٤٣.\nتاريخ علماء بغداد: ١٣٢."}],[155,"٥. ونقل اليافعي عن بعضهم أنه قال فيه: «كان إمامًا بارعًا حجة متبحرًا في العلوم الدينية بصيرًا بالمذهب وأصوله وفروعه، له يد طولى في العربية والحديث والتفسير، مع عبادة وتهجد وورع ونسك وتعبد، وملازمة للخير على طريقة السلف في الاعتقاد» (٢)."],[156,"٦. وقال السبكي: «الشَّيْخ العلاّمة تقي الدين أحد أئمة المسلمين علمًا ودينًا ... وتفقه عليه خلائق، وكان إمامًا كبيرًا فقيهًا محدِّثًا زاهدًا ورعا، مفيدًا معلمًا استوطن دمشق يعيد زمان السالفين ورعا، ويزيد بهجتها بروضة علم جنى كل طالب جناها ورعا، ويفيد أهلها فما مِنْهُم إلاَّ من اغترف من بحره واعترف بدُرِّهِ وحفظ جانب مثله"],[157,"ورعا» (٣)."],[158,"٧. واختصر الإسنوي وصفه فقال: «كان إمامًا في الفقه والحديث، عارفًا بالتفسير والأصول والنحو، ورعًا زاهدًا، ملازمًا لطريقة السلف الصالح» (٤)."],[159,"٨. وقال ابن كثير: «الإمام العلاّمة مفتي الشام ومحدّثها ... وكان ديّنًا زاهدًا ورعًا ناسكًا، على طريقة السلف الصالح، كما هو طريقة متأخري أكثر المحدِّثين مع الفضيلة التامة في فنون كثيرة، ولم يزل على طريقة جيدة حَتَّى كانت وفاته» (٥)."],[160,"٩. وقال ابن قاضي شهبة: «الإمام العلاّمة مفتي الإسلام ... الإمام"],[161,"البارع» (٦)."],[162,"١٠. وقال السيوطي: «الإمام الحافظ شيخ الإسلام ... يضرب به المثل، سلفيًا زاهدًا حسن الاعتقاد وافر الجلالة» (٧).","",{"fn":"سير أعلام النبلاء ٢٣/ ١٤٠ - ١٤٢.\nمرآة الجنان ٤/ ٨٥.\nطبقات الشافعية الكبرى ٨/ ٣٢٦ - ٣٢٧.\nطبقات الشافعية ٢/ ١٣٣.\nالبداية والنهاية ١٣/ ١٤٢.\nطبقات الشافعية ٢/ ١١٣.\nطبقات الحفاظ: ٥٠٣."}],[163,"الفصل الثالث: دراسة الكتاب"],[164,"المبحث الأول: أهمية الكتاب"],[165,"لَمْ تعد أهمية كتاب ابن الصلاح أمرًا خافيًا أو شيئًا غامضًا يحتاج إلى إيضاح وتفصيل، ولنا أن نجزم بأن كتابه هو المحور الذي دارت في فلكه تصانيف كل مَنْ أتى بعده، وأنه واسطةُ عقدِها، ومصدر ما تفرع عنها. ولم يكن لمن بعده سوى إعادة الترتيب في بعض الأحيان، أو التسهيل عن طريق الاختصار أو النظم، أو إيضاح بعض مقاصده التي قد تخفى عَلَى بعض المطالعين عن طريق التنكيت."],[166,"وقد رزق الله تَعَالَى كتاب ابن الصلاح القبول بَيْنَ الناس، حَتَّى صار مدرس مَنْ يروم الدخول في هذا الشأن، ولا يتوصّل إليه إلاَّ عن طريقه، فهو الفاتح لما أغلق من معانيه والشارح بما أجمل من مبانيه."],[167,"ولم تقتصر قيمة الكتاب العلمية عَلَى جانب تفرده في مصطلح الحديث وبيان مبادئه، وإنما عُدّت من بدايات الكتابات في علمٍ نعتقد أنه ظهر عند الغرب في وقت متأخر، ألاَ وهو علم تحقيق النصوص وتوثيق المرويات، ولعلنا لا نبالغ إذا قلنا: إنه لا يزال متفردًا بخصائصه التي تتصل بهذا الموضوع. وما دام تخصصه قد امتدَّ إلى هذا الباب فليس غريبًا أن تكون له مباحثات فيما يتصل بعلم التاريخ."],[168,"ولعل المؤلف ابن الصلاح عنى ذلك بقوله: «فحينَ كادَ الباحثُ عنْ مُشْكلِهِ لا يُلْفِي لهُ كاشفًا، والسائلُ عنْ علمِهِ لا يَلْقى بهِ عارفًا، مَنَّ اللهُ الكريمُ - تبارك وتعالى - عليَّ - ولَهُ الحمدُ - أجمعُ بكتابٍ \" معرفةَ أنواعِ علمِ الحديثِ \"، هذا الذي باحَ بأسرارهِ الخفيَّةِ، وكشفَ عَنْ مشكلاتِهِ الأبيَّةِ، وأحكمَ معاقدَهُ، وقعَّدَ قواعدَهُ، وأنارَ معالِمَهُ، وبيَّنَ أحكامَهُ، وفصَّلَ أقسامَهُ، وأوضحَ أصولَهُ، وشرحَ فروعَهُ وفصولَهُ، وجمعَ شتاتَ علومِهِ وفوائدَهُ، وقنصَ شواردَ نُكتِهِ وفرائدَهُ» (١).","",{"fn":"انظر: ٧٤ من طبعتنا هذه."}],[169,"ومما يجلِّي الأمر أكثر ويجعلنا أمام صورة واضحة عن أهمية هذا التصنيف أن ننقل جملة من أقوال العلماء فيه:"],[170,"١. فقد قال الإمام النووي (ت٦٧٦هـ): «هو كتاب كثير الفوائد، عظيم العوائد، قد نبَّه المصنِّف -رحمه الله- في مواضع من الكتاب وغيره، عَلَى عظم شأنه، وزيادة حسنه وبيانه، وكفى بالمشاهدة دليلًا قاطعًا، وبرهانًا صادعًا» (١)."],[171,"٢. وقال الخويي (٢) (ت ٦٩٣ هـ) في منظومته (٣):"],[172,"وخير ما صنف فيها واشتهر ... كتاب شيخنا الإمام المعتبر"],[173,"وهو الذي بابن الصلاح يعرف ... فليس من مثله مصنف (٤)"],[174,"٣. وقال ابن رشيد (ت ٧٢١ هـ):"],[175,"«الذي وقفت عليه وتحصل عندي من تصانيف هذا الإمام الأوحد أبي عمرو ابن الصلاح - رحمه الله - كتابه البارع في معرفة أنواع علم الحديث وإنّه كلّما كتبت عليه متمثلًا:"],[176,"لكل أناس جوهر متنافس ... وأنت طراز الآنسات الملائح» (٥)"],[177,"٤. وقال ابن جماعة (ت٧٣٣ هـ):"],[178,"«واقتفى آثارهم الشَّيْخ الإمام الحافظ تقي الدين أبو عمرو بن الصلاح بكتابه"],[179,"الذي أوعى فيه الفوائد وجمع، وأتقن في حسن تأليفه ما صنع» (٦).","",{"fn":"إرشاد طلاب الحقائق ١/ ١٠٨.\nنسبة إلى خوي، بلدة من بلاد أذربيجان. انظر: الأنساب ٢/ ٤٧٩، والمراصد ١/ ٤٩٣.\nانظر: مقدمتنا لشرح التبصرة والتذكرة ١/ ٢١.\nنقلا عن مقدمة محاسن الاصطلاح: ٣٣.\nملء العيبة ٣/ ٢١١.\nالمنهل الروي: ٢٦."}],[180,"٥. قال ابن كثير (ت ٧٧٤ هـ):"],[181,"«ولما كان الكتاب الذي اعتنى بتهذيبه الشَّيْخ الإمام العلاَّمة أبو عمرو بن الصلاح - تغمَّده الله برحمته - من مشاهير المصنفات في ذلك بَيْنَ الطلبة لهذا الشأن وربَّما عني بحفظه بعض المهرة من الشبَّان، سلكت وراءه واحتذيت حذاءه» (١)."],[182,"٦. وقال الزركشي (ت ٧٩٤ هـ):"],[183,"«وجاء بعدهم الإمام أبو عَمْرو بن الصَّلاَح فجمع مفرّقهم، وحقّق طرقهم، وأجلب بكتابه بدائع العجب، وأتى بالنكت والنخب، حَتَّى استوجب أن يكتب بذوب الذهب» (٢)."],[184,"٧. وقال الأبناسي (ت ٨٠٢ هـ):"],[185,"«وأحسن تصنيف فِيْهِ وأبدع، وأكثر فائدة وأنفع: \" علوم الْحَدِيْث \" للشيخ العلاّمة الحافظ تقي الدين أبي عمرو بن الصلاح فإنّه فتح مغلق كنوزه، وحلّ مشكل رموزه» (٣)."],[186,"٨. وقال ابن الملقن (ت ٨٠٤ هـ):"],[187,"«ومن أجمعها: كتاب العلامة الحافظ تقي الدين أبي عمرو بن الصلاح -سقى الله ثراه، وجعل الجنة مأواه - فإنه جامع لعيونها ومستوعب لفنونها» (٤)."],[188,"٩. وقال العراقي (ت ٨٠٦ هـ):"],[189,"«أحسن ما صنف أهل الْحَدِيْث في مَعْرِفَة الاصطلاح كتاب \" علوم الْحَدِيْث \" لابن الصَّلاَح، جمع فِيْهِ غرر الفوائد فأوعى، ودعا لَهُ زمر الشوارد فأجابت طوعًا» (٥).","",{"fn":"اختصار علوم الحديث ١/ ٩٥ - ٩٦.\nالنكت على مقدمة ابن الصلاح ١/ ٩ - ١٠.\nالشذا الفياح ١/ ٦٣.\nالمقنع في علوم الحديث ١/ ٣٩.\nالتقييد والإيضاح: ١١."}],[190,"١٠. وقال ابن حجر (ت ٨٥٢ هـ):"],[191,"«فجمع شتات مقاصدها، وضمَّ إليها من غيرها نخب فوائدها، فاجتمع في كتابه ما تفرق في غيره، فلهذا عكف الناس عليه وساروا بسيره، فلا يحصى كم ناظم له ومختصر، ومستدرك عليه ومقتصر، ومعارض له ومنتصر» (١)."],[192,"١١. وقال السيوطي (ت ٩١١ هـ):"],[193,"«عكف الناس عليه، واتخذوه أصلًا يرجع إليه» (٢)."],[194,"وبهذا نكاد أن ننقل إجماع الأئمة، منذ أن رأى كتاب \"معرفة أنواع علم الحديث\" النور إلى يوم الناس هذا، دليلًا على مكانته، وغزارة علمه وفوائده شاهدًا على علوِّ كعبه ونصرة حزبه، فرحم الله مؤلفه وجامعه، وأسبل عليه نعمه وفضائله، إنّه سميع مجيب."],[195,"المبحث الثاني: سمات منهج ابن الصلاح"],[196,"عَلَى الرغم من أن المؤلفين القدامى لا سيَّما المتأخرون الذين يصنفون لا عَلَى الأسانيد منهم لا يفصحون بمناهجهم التأليفية إلاَّ قليلًا، لكن المتتبع لتصرفاتهم في تصانيفهم لا يعدم وصفًا تقريبيًا لسمات مناهجهم التأليفية، وابن الصلاح ليس استثناءً من هذه القاعدة التي أوشكت أن تكون عامة."],[197,"وقد استطعنا - بحمد الله - أن نحدد بعض الملامح لمنهج ابن الصلاح في تصنيفه هذا وسنعرضها مدعمة بالأمثلة:"],[198,"١. إتيانه بالتعريفات للأنواع التي هو بصدد توضيحها، واهتمامه بهذا الجانب جدًا، ولعل ذلك راجع إلى تأثره بالنَّزعة الأصولية التي تهتم بضبط التعاريف، وأيًّا ما يكون الدافع فقد بدا هذا الأمر واضحًا جليًا في كتابته، إلاَّ أن منهجه في هذا الجانب قد تنوع عَلَى النحو الآتي:","",{"fn":"نزهة النظر: ٥١.\nالبحر الذي زخر ١/ ٢٣٥."}],[199,"أ. ابتكاره تعاريف لَمْ يسبق إليها، كما في تعريف الحسن (١)، والمعلَّل (٢)، والمضطرب (٣)، والمخضرم (٤)، وغيرها."],[200,"ب. كان حريصًا عَلَى بيان ماهية المعرَّف، وكان يلجأ في بعض الأحيان إلى التمثيل من غير ذكر للحدِّ، كما في المقلوب إذ عرَّف به بقوله: «هو نحو حَدِيْث مشهور عن سالم جعل عن نافع ليصير بذلك غريبًا مرغوبًا به» (٥)."],[201,"فتعقّبه الزركشي فقال: «وهذا التعريف غير وافٍ بحقيقة المقلوب، وإنما هو تفسير لنوع منه» (٦)، وبنحوه قال ابن حجر (٧). وكما في النوع الخامس عشر: معرفة الاعتبار والمتابعات والشواهد (٨)."],[202,"ج. إذا كان للنوع أقسام فإنه يذكرها معرفًا بها، كما في النوع الرابع والعشرين: معرفة كيفية سماع الحديث وتحمله وصفة ضبطه (٩)."],[203,"فإنه مشتمل عَلَى فروع ثمانية هي أنواع التحمل والأداء، فعرَّف بكل منها (١٠). وإذا كان الفرع يضم أقسامًا فإنه يعرف بها أيضًا كما في الإجازة (١١).","",{"fn":"انظر: معرفة أنواع علم الحديث: ٩٩.\nالمصدر نفسه: ١٨٦.\nالمصدر نفسه: ١٩٢.\nالمصدر نفسه: ٤٠٧.\nالمصدر نفسه: ٢٠٨.\nنكت الزركشي ٢/ ٢٩٩.\nالنكت عَلَى كتاب ابن الصلاح ٢/ ٨٦٤.\nانظر: معرفة أنواع علم الحديث: ١٧٣.\nانظر: المصدر السابق: ٢٤٧ وما بعدها.\nالمصدر نفسه: ٢٤٧، ٢٥١، ٢٦٥ ... الخ.\nانظر: المصدر نفسه: ٢٦٥، ٢٦٧، ٢٦٨، ٢٧١ ... الخ."}],[204,"د. وربما كان للمعرَّف أكثر من تعريف، فكان المؤلِّف يوردها جميعًا ولكنه في أكثر أحيانه لا يبقي الأمر هملًا، ولكنه يرجح شيئًا يستعين به الباحث، كما في تعريف الحسن (١)، والمسند (٢)، والمنقطع (٣)، والشاذ (٤)، وغيرها."],[205,"هـ. في بعض الأحيان - وإمعانًا منه في إيضاح ماهية المعرَّف - يبين محترزات التعريف، حَتَّى يسلم من الاعتراضات، كما في تعريف الصحيح (٥)، والمرفوع (٦)، وغيرهما."],[206,"٢. استحداثه - في بعض الأنواع - لأقسام غير مسبوق بها، تسهيلًا لتلك المباحث وإعانة للقارئ عَلَى فهمها جيدًا، كما في تقسيمات الصحيح (٧)، وتقسيم"],[207,"الحسن (٨)، والشاذ (٩)، والمنكر (١٠)، والأسماء والكنى (١١)، وغيرها."],[208,"٣. كان أبو عمرو ذا عقلية متفتحة ونظر سليم، قادرًا عَلَى التمحيص وتمييز ما في أقوال من سبقه من خطأ، والتعرف على مواطن الخلل لذا كان موقفه متباينًا منها، فتارة يتولاها بالنقد، وتارة يستدرك أمورًا، وتارة يوضح المقصد من الكلام، وعلى كلٍّ فقد برزت الصور الآتية في منهجه التأليفي في إطار هذه النقطة:","",{"fn":"انظر: معرفة أنواع علم الحديث: ١٠٠.\nالمصدر نفسه: ١١٤.\nالمصدر نفسه: ١٣٢.\nالمصدر نفسه: ١٦٤.\nالمصدر نفسه: ٧٩.\nالمصدر نفسه: ١١٦.\nالمصدر نفسه: ٩٦ - ٩٧.\nالمصدر نفسه: ١٠٠.\nالمصدر نفسه: ١٦٨.\nالمصدر نفسه: ١٧٠ - ١٧٢.\nالمصدر نفسه: ٤٣٥ وما بعدها."}],[209,"أ. كان يتعقب عَلَى بعض اختيارت العلماء، مثل تعقبه عَلَى اختيار بعض المغاربة تفضيل صحيح مُسْلِم عَلَى البُخَارِيّ، بسبب أنَّهُ ليس فيه بعد خطبته إلا الحديث الصحيح سردًا."],[210,"فقال: «وليس يلزم منه أن كتاب مُسْلِم أرجح فيما يرجع إلى نفس الصحيح عَلَى كتاب البُخَارِيّ، وإن كان المراد به أن كتاب مُسْلِم أصح صحيحًا، فهذا مردود عَلَى من يقوله» (١)."],[211,"وكتعقبه عَلَى تعاريف الحسن بقوله: «كل هذا مستبهم لايشفي الغليل» (٢) وتعقب أيضًا من اختار من أهل المغرب والقاضي الرامهرمزي من أهل الشرق في اللحق أن يكتب في نهايته الكلمة المتصلة به في موضع التخريج لتدل عَلَى اتصال الكلام، فقال: «وليس ذَلِكَ بمرضي، إذ رب كلمة تجيء في الكلام مكررة حقيقة، ... الخ كلامه» (٣)."],[212,"ب. لقد مثّل ابن الصلاح الذروة في فهم مضامين كلام العلماء الذين سبقوه، ونجد ذَلِكَ واضحًا في توجيهه لقول الحافظ أبي علي النيسابوري: «ما تحت أديم السماء كتاب أصح من كتاب مُسْلِم بن الحجاج». قائلًا: «فهذا وقول من فضَّلَ من شيوخ المغرب كتاب مُسْلِم عَلَى كتاب البُخَارِيّ إن كان المراد به أن كتاب مُسْلِم يترجح بأنه لَمْ يمازجه غير الصحيح، فإنه ليس فيه بعد خطبته إلا الحديث الصحيح مسرودًا غير ممزوج بمثل ما في كتاب البُخَارِيّ في تراجم أبوابه من الأشياء التي لَمْ يسندها على الوصف المشروط في الصحيح، فهذا لا بأس به» (٤).","",{"fn":"معرفة أنواع علم الحديث: ٨٥.\nالمصدر السابق: ١٠٠.\nالمصدر نفسه: ٣٠٤.\nالمصدر نفسه: ٨٥."}],[213,"وتوجيهه لقول مُسْلِم: «ليس كل شيء عندي صحيح وضعته هاهنا إنما وضعت هاهنا ما أجمعوا عليه."],[214,"قائلًا: أراد - والله أعلم - أنه لَمْ يضع في كتابه إلا الأحاديث التي وجد عنده فيها شرائط الصحيح المجمع عليه، وإن لَمْ يظهر اجتماعها في بعضها عِنْدَ بعضهم» (١)."],[215,"وَوَجَّه قول البخاري: «أحفظ مئة ألف حديث صحيح، ومئتي ألف حديث غير صحيح»."],[216,"بأن «هذه العبارة قد يندرج تحتها عندهم آثار الصحابة والتابعين، وربما عُدَّ الحديث الواحد المروي بإسنادين حديثين» (٢)."],[217,"ج. ومن أجل تكامل البحث العلمي والاستفادة من جهود السابقين، لَمْ يهمل أبو عمرو أقوال من سبقه إهمالًا كليًا، وإنما كان يوردها ثُمَّ يزيد عليها ما يراه مكملًا لما يرمي إلى إيضاحه فكرًا أو تطبيقًا، كما توضحه الأمثلة الآتية:"],[218,"بعد أن بيَّن حكم الأحاديث التي يوردها الحاكم في المستدرك بأنها إن لَمْ تكن صحيحة فهي حسنة، إلاَّ أن تظهر فيها علة توجب ضعفها!!! قال: «ويقاربه في حكمه \" صحيح أبي حاتم بن حبان البستي \"» (٣)."],[219,"وبعد أن نقل عن الخطيب جواز كتابة طباق التسميع في بداية الكتاب أو في حاشية الصفحة الأولى قال: «ولا بأس بكتبته آخر الكتاب وفي ظهره وحيث لا يخفى موضعه» (٤)."],[220,"٤. هناك صفة تميز كتابات ابن الصلاح، وهي بحد ذاتها دالة عَلَى سعة أفقه ووفور درايته، وهي تعكس من وجه آخر حجم الثروة العلمية التي وفّرها لنفسه كمخزون ثقافي، ألاَّ وهي إكثاره من نقل مذاهب العلماء في كافة المسائل التي يتعرض لبحثها، وهذا أمر نراه واضحًا ملموسًا مبثوثًا في أثناء هذا الكتاب.","",{"fn":"معرفة أنواع علم الحديث: ٨٥ - ٨٦.\nالمصدر نفسه: ٨٧.\nالمصدر نفسه: ٩٠.\nالمصدر نفسه: ٣١٣."}],[221,"٥. لَمْ يكن ابن الصلاح قاصرًا عن الإدلاء بدلوه في القضايا التي ينقدها، سواء أكانت تلك المسائل خلافية أم وفاقية، فقد كان يطالعنا باختيارات وآراء جديدة بين الفينة والأخرى، وهي كثيرة جدًا نكتفي منها بالأمثلة الآتية:"],[222,"في معرض تحدّثه عن المعلق ووقوعه في الصحيحين، قال مبينًا حكمه:"],[223,"«وينبغي أن نقول: ما كان من ذلك ونحوه بلفظ فيه جزم وحكم به على من علَّقه عنه، فقد حكم بصحته عنه» (١)."],[224,"وتقريرًا لكلام أبي داود في رسالته بشأن السنن، والأحاديث التي سكت عنها فيها، قال: «فعلى هذا ما وجدناه في كتابه مذكورًا مطلقًا وليس في واحد من الصحيحين، ولا نصَّ عَلَى صحته أحد ممن يميز بين الصحيح والحسن، عرفناه بأنه من الحسن عِنْدَ أبي داود» (٢)."],[225,"٦. جمع ابن الصلاح شتات علوم متفرقة، وقد وظَّف تقي الدين هذا الجانب من معرفته في أبحاثه هذه، وذلك من خلال ربطه بَيْنَ القضايا الفقهية ومباحث علوم الحديث، مثل ربطه بين حجية الحديث المرسل عِنْدَ المحدّثين وحجيته عِنْدَ الفقهاء وبيان الفرق بين رواية المستور، وبين شهادة المستور (٣)."],[226,"وفي تعريف الموقوف قال: «وموجود في اصطلاح الفقهاء الخراسانيين تعريف الموقوف باسم الأثر ...» (٤).","",{"fn":"معرفة أنواع علم الحديث: ٩٣.\nالمصدر السابق: ١٠٦.\nالمصدر نفسه: ١٠٣.\nالمصدر نفسه: ١١٨."}],[227,"٧. لما كان ابن الصلاح في إطار تقعيد القواعد في طريقه لتقنينها كقوانين تحكم هذا"],[228,"العلم، كان من كمال علمه وتكميله لتلك الأساسيات يورد ما يتوقع أن يعترض به عليه، ثُمَّ يتولى جوابه بما يسلم معه من النقد."],[229,"مثل قوله في بحثه لتقوي الضعيف بكثرة الطرق:"],[230,"«لعل الباحث الفهم يقول: إنا نجد أحاديث محكومًا بضعفها مع كونها قد رويت بأسانيد كثيرة من وجوه عديدة، مثل حديث: «الأذنان من الرأس»، ونحوه، فهلاَّ جعلتم ذَلِكَ وأمثاله من نوع الحسن؛ لأن بعض ذَلِكَ عضَّد بعضًا، كما قلتم في نوع الحسن عَلَى ما سَبَقَ آنفًا؟؟"],[231,"وجواب ذَلِكَ أنَّهُ ليس كل ضعف في الحديث يزول بمجيئه من وجوه، ... الخ كلامه» (١)."],[232,"وكما في جوابه عن الإشكال المتوقع من جمع الترمذي بَيْنَ الحسن والصحة في وصف حديث واحد؛ لأن الحسن قاصر عن الصحيح، فكيف يستقيم الجمع بَيْنَ نفي القصور وإثباته؟؟"],[233,"فقال: «وجوابه: أن ذَلِكَ راجع إلى الإسناد ... الخ» (٢)."],[234,"٨. بيانه مراتب بعض الكُتُب المصنفة، إرشادًا للطالب في كيفية الاعتماد عليها ونمثل لذلك بما يأتي:"],[235,"فبعد أن بيَّن حكم مستدرك الحاكم والأحاديث الواردة فيه، بيَّن حكم صحيح ابن حبان قائلًا: «ويقاربه في حكمه صحيح أبي حاتم بن حبان البستي» (٣)."],[236,"ونراه قد سرد عددًا لا بأس به من المسانيد، مُصدِّرًا ذلك بقوله: «كتب المساند غير ملتحقة بالكتب الخمسة» (٤)، وعلَّل هذا الحكم بأنهم: «يخرِّجُوا في مسند كل صحابي ما رووه من حديثه غير متقيدين بأن يكون حديثًا محتجًّا به، فلهذا تأخَّرت مرتبتها - وإن جلَّت لجلالة مؤلفيها - عن مرتبة الكتب الخمسة وما التحق بها من الكتب المصنَّفة على الأبواب» (١).","",{"fn":"معرفة أنواع علم الحديث: ١٠٣ - ١٠٤.\nالمصدر السابق: ١١٠.\nالمصدر نفسه: ٩٠.\nالمصدر نفسه: ١٠٨."}],[237,"٩. عدم إهماله لبعض الإشارات التي تتصل بمسائل لغوية وهي ذات دلالة أوَّلًا وآخِرًا على عمق ثروته اللغوية، مثل تعقبه عَلَى المحدِّثين في استخدامهم مصطلح «معضل»، فَقَالَ: «وأصحاب الحديث يقولون: أعضَله فهو معضل - بفتح الضاد - وهو اصطلاح مشكل المأخذ من حيث اللغة، وبحثت فوجدت له قولهم: «أمر عضيل»، أي: مستغلق شديد، ولا التفات في ذلك إلى مُعْضِل - بكسر الضاد - وإن كان مثل عضيل في المعنى» (٢)."],[238,"ومثل بيانه لمعنى الإجازة في اللغة نقلًا عن ابن فارس قائلًا: «معنى الإجازة في كلام العرب مأخوذ من جواز الماء الذي يسقاه المال من الماشية والحرث، يقال منه: استجزت فلانًا فأجازني إذا أسقاك ماءً ... الخ كلامه» (٣)."],[239,"وبيانه لمعنى الوجادة في اللغة بقوله: «هي مصدر لـ: «وَجَدَ يَجِدُ» مولد غير مسموع من العرب ...» (٤)."],[240,"١٠. كان دأب ابن الصلاح الإرشاد والتنبيه على أهمية الأنواع التي يبحثها استكمالًا لجوانب البحث العلمي الذي كان حريصًا على إظهاره بالشكل الأتم، ومما يدلل على هذا أن نسوق أمثلة لها."],[241,"فابن الصلاح وهو بصدد بحثه لمعرفة زيادات الثقات يقول عنه منبهًا عَلَى أهميته:"],[242,"«وذلك فن لطيف تستحسن العناية به» (٥).","",{"fn":"معرفة أنواع علم الحديث: ١٠٩.\nالمصدر السابق: ١٣٦.\nالمصدر نفسه: ٢٧٦.\nالمصدر نفسه: ٢٨٨.\nالمصدر نفسه: ١٧٦."}],[243,"وقال في نوع المعلل مرشدًا إلى عظيم خطره: «اعلم أن معرفة علل الحديث من أجلِّ علوم الحديث وأدقِّها وأشرفها، وإنما يضطلع بذلك أهل الحفظ والخبرة والفهم الثاقب» (١)."],[244,"وقال في معرفة غريب الحديث: «هذا فنٌّ مهمٌّ يقبح جهله بأهل الحديث"],[245,"خاصة» (٢)."],[246,"١١. تنبيهه على استعمالات المحدِّثين أو الحكمة في صنيعهم أو إيضاح اصطلاحاتهم مثل: توضيحه لما اصطلح عليه البغوي في كتابه \" مصابيح السنة \" (٣)، وكما في توضيحه لسبب جعل علامة التضبيب كأنها صاد (٤) وعلة استعمال المحدِّثين لعلامة التحويل في الإسناد (ح) مهملة (٥)."],[247,"١٢. عَلَى الرغم من أن ابن الصلاح كان من منهجه الاختصار كلما وجد إلى ذلك"],[248,"سبيلًا؛ إلاَّ أنَّهُ لَمْ يغفل أن يسوق بَيْنَ تارة وأخرى إسنادًا له، ينقل به حديثًا أو طُرفةً أو قولًا أو شعرًا، يؤنس به المطالعين، ويذكّر به سنة السالفين (٦)."],[249,"١٣. قد كان أبو عمرو طيلة صفحات الكتاب ذا شخصية بارزة واضحة متميزة وذلك من خلال إبداء آرائه الجديدة، وقدرته على المناقشة والتصويب وترجيح ما يراه راجحًا من الآراء (٧).","",{"fn":"معرفة أنواع علم الحديث: ١٨٧.\nالمصدر السابق: ٣٧٥.\nالمصدر نفسه: ١٠٧.\nالمصدر نفسه: ٣٠٦.\nالمصدر نفسه: ٣١٣.\nانظر: المصدر نفسه: ٣١٣ و٣٣٩ و٣٤٧ و٣٥٨، وغيرها.\nانظر: المصدر نفسه: ٨٨ و٩٦ و١٢١ و٣١٣ و٣١٨ و٣١٩ و٣٢٣ و٣٢٦ و٣٢٩ مثلًا."}],[250,"١٤. كان من منهج ابن الصلاح أن يعزز ما يختاره من المذاهب التي يذكرها في المسائل الخلافية بأقوال العلماء، ونجد ذلك واضحًا في طيات كتابه، ولا ضير في التمثيل لبعضها."],[251,"ففي معرض تقريره لجواز أن يثبت الراوي سماعه للكتاب بخطه من غير حاجة إلى أن يكتبه الشَّيْخ الْمُسْمِع، في حالة كون الراوي موثوقًا به، أورد أن عبد الرحمان بن منده سأل أبا أحمد الفرضي أن يكتب له سماعه في جزء سمعه منه، فقال أبو أَحْمَد:"],[252,"«يا بني! عليك بالصدق، فإنك إذا عرفت به لا يكذبك أحد ... الخ» (١)."],[253,"وقرر أن الإبطاء بإعادة الكتب التي فيها سماعات لأصحابها أمر قبيح، وأورد قول الزهري: «إيَّاك وغلول الكتب. قيل: وما غلول الكتب؟ قَالَ: حبسها عَلَى"],[254,"أصحابها» (٢)."],[255,"١٥. تنبيهه عَلَى من صنَّف في الأنواع التي يبحثها (٣)."],[256,"١٦. بروز الجانب التطبيقي عنده، وذلك من خلال ما يعرضه من الأمثلة التي ملأت صفحات كتابه."],[257,"١٧. كل مَنْ يقرأ كتاب ابن الصلاح لا يملك إلا أن يعترف بأدبه الجمِّ الذي زخرت به كتاباته، تعبيرًا عمَّا يكنه في نفسه من تقوى وورع، واعتراف بفضل السابقين، فلا تجده يذكر سم الله تعالى من غير ثناء، ولا يكاد يذكر اسم رسول الله - صلى الله عليه وآله وسلم - إلا مقرونًا بالصلاة عليه، وكذلك الصحابة والتابعون والعلماء ممن بعدهم لا يذكرهم إلا مترضِّيًا عليهم أو مترحِّمًا.","",{"fn":"معرفة أنواع علم الحديث: ٣١٤.\nالمصدر السابق: ٣١٤.\nانظر: المصدر نفسه: ٣٨٣ و٤١٥ و٤٣٠ و٤٤٥ و٤٦٣ و٤٧٠ مثلًا."}],[258,"ومما يعدُّ من خصائصه الأسلوبية، أنه لا يكاد ينهي فقرة إلاَّ ويقول في ختامها:"],[259,"«والله أعلم»، تواضعًا منه واعترافًا بضمون قوله جلَّ ذكره: ﴿وَمَا أُوتِيْتُمْ مِنَ العِلْمِ إلاَّ قَلِيْلًا﴾. الإسراء: ٨٥."],[260,"المبحث الثالث: مصادره وموارده"],[261,"تعددت مصادر ابن الصلاح تبعًا لتعدد جوانب ثقافته المتنوعة التي تتطلبها طبيعة الكتابة في ميدان يشابه الميدان الذي خاض غماره وسبر أغواره ابن الصلاح، فجاءت ثمرته ناضجة آتت أكلها والحمد لله."],[262,"ومن خلال نظرة فاحصة نلقيها عَلَى هذا التصنيف، يمكننا أن نميّز نوعين من تِلْكَ المصادر:"],[263,"الأول: المصادر الشفوية."],[264,"الثاني: المصادر الكتابية."],[265,"وسنعرض لكل منهما في مطلب مستقل:"],[266,"المطلب الأول: المصادر الشفوية"],[267,"مرَّ بنا فيما مضى أن ابن الصلاح جال بلادًا كثيرة، وطلب عَلَى أيادي علماء عصره، فجمع علومًا وظَّفها لخدمة منهجه التأليفي، وهي تلك المعلومات التي استمدها شفاهًا من شيوخه، ويمكننا جعلها عَلَى قسمين:"],[268,"الأول: ما أبهم فيه مصدره فلم يصرح بطريق نقله، مثل:"],[269,"قوله: وأنبأني من سأل الحازمي أبا بكر عن الإجازة العامة ...» (١)."],[270,"وقوله: «وأخبرني من أُخبر عن القاضي عياض بن موسى من فضلاء وقته ...» (٢). ونحو ذلك قوله: «وأخبرني بعض أشياخنا عمن أخبره عن القاضي ...» (٣).","",{"fn":"معرفة أنواع علم الحديث: ٢٦٩.\nالمصدر السابق: ٢٧٤.\nالمصدر نفسه: ٣٢٨."}],[271,"الثاني: ما صرح فيه بذكر شيخه وسلسلة إسناده، مثل:"],[272,"قوله: «كمثل ما حدثنيه الشَّيْخ أبو الْمُظَفَّر، عن أبيه الحافظ أبي سعد السمعاني ...» (١)."],[273,"وكمثل قوله: «حدثني بمرو الشَّيْخ أبو المظفر بن الحافظ أبي سعد المروزي، عن أبيه ...» (٢)."],[274,"وكقوله: «أخبرنا أبو بكر بن أبي المعالي الفراوي قراءة عليه، قال: أخبرنا الإمام جدي ...» (٣). وغيرها كثير."],[275,"المطلب الثاني: المصادر الكتابية"],[276,"اعتمد أبو عمرو على مصادر كتابية كثيرة في مختلف المواضيع كالحديث دراية ورواية والتفسير وعلوم القرآن والتاريخ وكتب الرجال والأدب والنحو واللغة وغريب الحديث وغيرها مما هو موضح في الفهرس الذي خصصناه بها فلا حاجة إلى التطويل بذكرها هنا."],[277,"ولكن نود هنا أن ننبه على أن أكثر تعويل ابن الصلاح كان على عالمين اثنين هما:"],[278,"الأول: الحاكم أبو عبد الله النيسابوري الحافظ، وذلك من خلال كتابه \" معرفة علوم الحديث \"، حيث ضمَّن كثيرًا من أفكاره في كتابه، فضلًا عن كثير من النصوص التي نقلها منه."],[279,"الثاني: الخطيب البغدادي الحافظ، إذ كان تعويله في أكثر مباحث كتابه على كتاب الخطيب \" الكفاية \"، ويجد القارئ مصداق ذلك في عشرات النقول التي خرجناها من الكفاية، بله لا تخلو صفحة - لا سيما مباحث ما قبل نصف الكتاب - عن ذَكَرَ الكفاية.","",{"fn":"معرفة أنواع علم الحديث: ٢٣٨.\nالمصدر السابق: ٣١٤.\nالمصدر نفسه: ٣٢٥ - ٣٢٦."}],[280,"وكذلك عوَّل على بقية كتبه كالجامع لأخلاق الراوي وآداب السامع (١)، وتلخيص المتشابه (٢)، وتالي تلخيص المتشابه (٣)، ورافع الارتياب، وغيرها."],[281,"المبحث الرابع: جهود العلماء في خدمة كتاب ابن الصلاح"],[282,"لعلّ كتابًا في مصطلح الحديث لم يخدم كما خدم كتاب ابن الصلاح إذ كان هو المحرك الفعلي الذي تولدت عنه عشرات بل مئات المؤلفات التي أغنت المكتبة الإسلامية، وساهمت بمجموعها في إكمال حلقات هذا العلم المبارك."],[283,"وقد اختلفت اتجاهات المؤلفين في طبيعة بحوثهم لتطوير وتعزيز القيمة العلمية لهذا الكتاب فمنهم الناظم، ومنهم الشارح، ومنهم المختصر، ومنهم المنكِّت توضيحًا أو استدراكًا فلهذا ارتأينا - خدمة لتقسيمات البحث العلمي المنظم - أن نوزعها على النحو الآتي، وبالله التوفيق."],[284,"أ. المختصرات:"],[285,"لعلّ هذا الطابع من التصنيف الذي كان كتاب ابن الصلاح المحفِّز لها هو الأكثر، نظرًا إلى أن من ألّف في هذا اللون يبغي تقليص حجم الكتاب الأصلي؛ وذلك باختزال الألفاظ وتكثيف الفكر والمعاني، وحذف الأمثلة التي لا حاجة لها والابتعاد عن المناقشات غير الضرورية، وزيادة الفوائد والآراء، مع مخالفة ترتيب الأصل أحيانًا، تسهيلًا لطلبة العلم وغيرهم."],[286,"ومن أبرز تلك المختصرات:","",{"fn":"طبع ثلاث طبعات بتحقيقات مختلفة.\nطبع بتحقيق الأستاذة سكينة الشهابي.\nطبع بتحقيق مشهور حسن سلمان وأحمد الشقيرات."}],[287,"١. إرشاد طلاب الحقائق إلى معرفة سنن خير الخلائق، للإمام النووي ... (ت ٦٧٦ هـ) (١)."],[288,"٢. التقريب والتيسير لمعرفة سنن البشير النذير، للإمام النووي أيضًا (٢) وهو اختصار لكتابه السابق."],[289,"٣. المنهج المبهج عند الاستماع، لمن رغب في علوم الحديث على الاطلاع، لقطب الدين القسطلاني (ت ٦٨٦ هـ) (٣)."],[290,"٤. أصول علم الحديث، لعلي بن أبي الحزم القرشي الطبيب المشهور بابن النفيس (ت ٦٨٩ هـ) (٤)."],[291,"٥. الاقتراح، للإمام ابن دقيق العيد (ت ٧٠٢ هـ) (٥)."],[292,"٦. الملخص، لرضي الدين الطبري (ت ٧٢٢ هـ) (٦)."],[293,"٧. رسوم التحديث، للجعبري (ت ٧٣٢هـ) (٧)."],[294,"٨. المنهل الروي، لبدر الدين بن جماعة (ت ٧٣٣ هـ) (٨)."],[295,"٩. مشكاة الأنوار، للبارزي (ت ٧٣٨ هـ) (٩)."],[296,"١٠. الخلاصة في علوم الحديث، للطيبي (ت ٧٤٣ هـ) (١٠).","",{"fn":"طبع بتحقيق عبد الباري فتح الله السلفي عن مكتبة الإيمان سنة (١٤٠٨ هـ- ١٩٨٧ م).\nطبع مستقلًا ومع شرح السيوطي، ونحن بسبيل طبعه محققًا على نسختين خطيتين.\nذكره السيوطي في البحر الذي زخر ١/ ٢٣٦، وانظر: قواعد التحديث: ٤١ وقد شرحه عبد الهادي الأبياري (ت ١٣٠٥ هـ) منه نسخة في المكتبة السليمانية بتركيا برقم (١٦٧).\nذكره السيوطي في البحر الذي زخر ١/ ٢٣٧، ولا نعلم عنه شيئًا.\nطبع بتحقيق د. قحطان عبد الرحمان الدوري في بغداد سنة (١٤٠٢ هـ - ١٩٨٢م).\nذكره السيوطي في البحر الذي زخر ١/ ٢٣٦ ومنه نسخة خطية بإسبانيا في مكتبة الأسكوريال برقم (ثان ١٦١٥/ ١).\nمنه نسخة خطية في المكتبة الأحمدية بحلب، برقم (١٤٢٨).\nطبع بتحقيق د. محيي الدين عبد الرحمان رمضان سنة ١٣٩٥ هـ - ١٩٧٥ م.\nذكره السيوطي في البحر الذي زخر ١/ ٢٣٧ - ٢٣٨ ولا نعلم عنه شيئًا.\nطبع بتحقيق السيد صبحي السامرائي سنة ١٣٩١ هـ - ١٩٧١."}],[297,"١١. الكافي، لتاج الدين التبريزي (ت ٧٤٦ هـ) (١)."],[298,"١٢. الموقظة، للإمام الذهبي (ت ٧٤٨ هـ) (٢)."],[299,"١٣. المختصر، لعلاء الدين المارديني المشهور بابن التركماني (ت٧٥٠ هـ) (٣)."],[300,"١٤. مختصر، لشهاب الدين الأندرشي الأندلسي (ت ٧٥٠ هـ) (٤)."],[301,"١٥. مختصر، للحافظ العلائي (ت ٧٦١ هـ) (٥)."],[302,"١٦. الإقناع، لعز الدين بن جماعة (ت ٧٦٧ هـ) (٦)."],[303,"١٧. اختصار علوم الحديث، للحافظ ابن كثير (ت ٧٧٤ هـ) (٧)."],[304,"١٨. التذكرة في علوم الحديث، لسراج الدين ابن الملقن (ت ٨٠٤ هـ) (٨)."],[305,"١٩. المقنع في علوم الحديث، لسراج الدين ابن الملقن أيضًا (٩)."],[306,"٢٠. نخبة الفكر، للحافظ ابن حجر العسقلاني (ت ٨٥٢ هـ) (١٠)."],[307,"٢١. المختصر، للكافيجي (ت ٨٧٩ هـ) (١١)."],[308,"٢٢. مختصر بهاء الدين الأندلسي (...؟) (١٢).","",{"fn":"منه نسخة خطية بإستانبول.\nطبع بتحقيق الشيخ عبد الفتاح أبي غدة سنة ١٤٠٥ هـ/ ١٩٨٥ م وهو في الحقيقة اختصار لكتاب ابن دقيق العيد \" الاقتراح \"، وفي خزانتنا نسخة خطية متقنة منه.\nمنه نسختان خطيتان: الأولى بالمكتبة الأحمدية بحلب برقم (٢٨٣) والثانية في مكتبة لاله لي برقم (٣٩٠/ ١٥).\nذكره حاجي خليفة في كشف الظنون ٢/ ١١٦٢.\nذكره السيوطي في البحر الذي زخر ١/ ٢٣٨ - ٢٣٩.\nذكره السيوطي في البحر الذي زخر ١/ ٢٣٩ - ٢٤٠.\nطبع مع شرح العلاَّمة أحمد محمد شاكر -رحمه الله- المسمى \" الباعث الحثيث \".\nطبع بتحقيق علي حسن علي عبد الحميد الحلبي في دار عمار - الأردن.\nطبع بتحقيق عبد الله يوسف الجديع سنة ١٤١٣ هـ - ١٩٩٢ م.\nطبعت عدة مرات.\nطبع بتحقيق د. علي زوين سنة ١٤٠٧ هـ - ١٩٨٧ م.\nمجهول الوفاة، وراجع مقدمة التدريب: ٧."}],[309,"ب. المنظومات:"],[310,"ظهر منذ عهد مبكر نسبيًا، تيّار في الشعر العربي، انتقل إلى علماء الفنون المختلفة يسمى: الشعر التعليمي، خصّص نطاق عمله في نظم الكتب المهمة في مجالات العلم تسهيلًا لطالبي العلوم في حفظها، ومن ثَمَّ الغوص في معانيها. وعلى أي حال فقد كان نصيب كتاب \" علوم الحديث \" لابن الصلاح عددًا من المنظومات التي لا يستهان بها، وسواء أكانت تلك المنظومات ذات جدة وحداثة أم لا؟ فإنّها مثّلت جانبًا من جوانب اهتمام العلماء واعتنائهم بهذا السفر العظيم. والذي يهمنا هنا أن نسلِّط الضوء عليها كوصلاتٍ في تاريخ هذا العلم المبارك، وليس من شرطنا أن تكون هذه المنظومة قد احتوت كل المادة العلمية لكتاب ابن الصلاح، بل يكفي أن يكون هذا الكتاب هو المرجع الأول بالنسبة لها، وعلى هذا نجد أن بعض هذه المنظومات مطوّلة، وبعضها مختصرة، وبعضها متوسطة، ولعلّ من أبرز من نظمه:"],[311,"١. شمس الدين الخُوَيي (ت ٦٩٣ هـ)، وسمّى منظومته باسم \" أقصى الأمل والسول في علوم حديث الرسول \"، توجد منه عدة نسخ خطية (١)."],[312,"٢. أبو عثمان سعد بن أحمد بن ليون التجيبي (ت ٧٥٠ هـ) (٢)."],[313,"٣. زين الدين العراقي (ت ٨٠٦ هـ) المسمّى: التبصرة والتذكرة (٣)."],[314,"٤. مُحَمَّد بن عبد الرحمان بن عبد الخالق المصري البرشنسي (ت ٨٠٨ هـ) وسمّى منظومته: \" المورد الأصفى في علم حديث المصطفى \" (٤).","",{"fn":"راجع كارل بروكلمان: تاريخ الأدب العربي ٦/ ٢٠٨.\nذكره السيوطي في البحر الذي زخر ١/ ٢٤٠.\nطبعت بتحقيقنا.\nذكره السيوطي في البحر الذي زخر ١/ ٢٤١ وقد شرحها الناظم نفسه انظر: شذرات الذهب ٧/ ٧٩، ومعجم المؤلفين ١٠/ ١٤٢."}],[315,"٥. شمس الدين محمد بن محمد بن محمد الدمشقي المعروف بابن الجزري"],[316,"(ت ٨٣٣ هـ) وسمّى منظومته \" الهداية في علم الرواية \" (١)."],[317,"٦. جلال الدين عبد الرحمان بن أبي بكر السيوطي (ت ٩١١ هـ) ومنظومته مشهورة باسم \" الألفية \" (٢)."],[318,"٧. رضي الدين محمد بن محمد الغزي (ت ٩٣٥ هـ)، وسمّى نظمه \" سلك الدرر في مصطلح أهل الأثر \" (٣)."],[319,"٨. منصور سبط الناصر الطبلاوي (ت ١٠١٤ هـ) (٤)."],[320,"ج. الشروح:"],[321,"قد كان للجانب الشمولي في كتاب ابن الصلاح أثره الواضح في أن أحدًا لم يتصدَّ لشرح الكتاب نفسه، وإنما انعكس هذا الجانب على شرح مختصراته ومنظوماته، لذا سنتناول أبرزها على اعتبار أن أصلها الأصيل هو كتاب ابن الصلاح، ومن ذلك:"],[322,"١. شروح ألفية العراقي."],[323,"٢. نزهة النظر، للحافظ ابن حجر (ت ٨٥٢ هـ) وما يتعلق بها (٥)."],[324,"٣. تدريب الراوي للسيوطي (ت ٩١١ هـ) (٦)."],[325,"٤. البحر الذي زخر، للسيوطي (ت ٩١١ هـ) شرح فيه ألفيته (٧).","",{"fn":"لها عدة نسخ خطية انظر: الفهرس الشامل للتراث الإسلامي ٣/ ١٧٢٥ وقد شرحها غير واحد، وفي خزانتنا نسخة خطية من الهداية.\nطبعت مجودة الشكل مع شرح العلامة أحمد محمد شاكر، ومع شرح محمد محيي الدين عبد الحميد، ومع شرح السيوطي نفسه.\nانظر: تاريخ الأدب العربي ٦/ ٢٠٨.\nالمصدر السابق ٦/ ٢١٠.\nطبعت عدة مرات، وانظر: مقدمة علي الحلبي في تحقيقه لنزهة النظر: ٥ - ٢٦.\nطبع بتحقيق عبد الوهاب عبد اللطيف أكثر من مرة، وقد ذكر حاجي خليفة في كشف الظنون ١/ ٤٦٥ شروحًا أخرى للتقريب.\nطبع بتحقيق أنيس أحمد طاهر سنة ١٤٢٠ هـ - ١٩٩٩ م."}],[326,"د. التنكيت:"],[327,"النُّكَت: جمع نُكْتَةٍ، وهي مشتقة من الفعل الثلاثي الصحيح (نَكَتَ)، وهو ذو اشتقاقات مختلفة، أجملها ابن فارس فَقَالَ: «النون والكاف والتاء أصل واحد يدلّ على تأثير يسير في الشيء كالنكتة ونحوها، ونكت في الأرض بقضيبه ينكت: إذا أثّر فيها» (١)."],[328,"أما في الاصطلاح فالنكتة: مسألة لطيفة أخرجت بدقة نظر وإمعان فكر، من نكت رمحه بأرض إذا أثر فيها، وسميت المسألة الدقيقة نكتةً؛ لتأثير الخواطر في استنباطها (٢)."],[329,"وقد كان نصيب كتاب ابن الصلاح من كتب النكت شيئًا دلّ على مدى تعمّق الدارسين في فهم معانيه ومدلولاته، حسب اللون العلمي الذي يغلب على ذلك المنكِّت، فنرى الأصولي يُغَلِّب المباحث الأصولية في طريق تقرير مسائل الكتاب المهمة، وهذا ما نلمسه جليًا في نكت الزركشي، والْمُحَدِّث يجعل همّه المباحثات الحديثية، وهو منهج واضح نراه في نكت العراقي وشيخه مغلطاي، وهكذا بالنسبة إلى الفقيه كما وقع للبلقيني وابن جماعة وغيرهم."],[330,"وعلّ الفطن من القرّاء عرف من العرض السابق أسماء بعض من كتب نكتًا على كتاب ابن الصلاح، ولكننا نودّ أن نجعل الأمر استقصائيًا استقرائيًا، فجمعنا مَن وقع في علمنا أنه ساهم في هذا الجانب، سواء عن طريق الكتابة والبحث المباشر على كتاب ابن الصلاح أو العمل غير المباشر عن طريق التعليق على فروع كتاب ابن الصلاح، وأهم هذه الكتب:"],[331,"١. إصلاح كتاب ابن الصلاح، لشمس الدين محمد بن أحمد بن عبد المؤمن الأسعردي الدمشقي ثُمَّ المصري المشهور بابن اللبان (ت ٧٤٩ هـ) (٣).","",{"fn":"مقاييس اللغة ٥/ ٤٧٥.\nالتعريفات للجرجاني: ١٣٤، وانظر: تاج العروس ٥/ ١٢٨ (نكت).\nنكت الزركشي ١/ ١٠، وطبقات ابن قاضي شهبة ٣/ ٦٩، والبحر الذي زخر ١/ ٢٤١."}],[332,"٢. إصلاح كتاب ابن الصلاح، للإمام العلاّمة علاء الدين أبي عبد الله مغلطاي بن قليج بن عبد الله البكجري الحنفي (ت ٧٦٢ هـ) (١)."],[333,"٣. النكت عَلَى مقدمة ابن الصَّلاَح، للإمام بدر الدين أبي عَبْد الله مُحَمَّد بن"],[334,"عبد الله بن بهادر الزركشي (ت ٧٩٤ هـ) (٢)."],[335,"٤. الشذا الفياح من علوم ابن الصلاح، للشيخ برهان الدين إبراهيم بن موسى بن أيوب الأبناسي (ت ٨٠٢ هـ) (٣)."],[336,"٥. محاسن الاصطلاح وتضمين كتاب ابن الصلاح، لسراج الدين أبي حفص عمر ابن رسلان البلقيني (ت ٨٠٥ هـ) (٤)."],[337,"٦. التقييد والإيضاح لما أطلق وأغلق من كتاب ابن الصلاح، للحافظ زين الدين عبد الرحيم بن الحسين العراقي (ت ٨٠٦ هـ) (٥)."],[338,"٧. شرح علوم الحديث، لعز الدين مُحَمَّد ابن أبي بكر بن عبد العزيز بن جماعة الحموي (ت ٨١٩ هـ) (٦)."],[339,"٨. النكت عَلَى كتاب ابن الصلاح، للحافظ أبي الفضل أحمد بن علي بن مُحَمَّد ابن حجر العسقلاني (ت ٨٥٢ هـ) (٧).","",{"fn":"انظر: نكت الزركشي ١/ ١٠، ومنه نسخة خطية في دار الكتب المصرية برقم (١/ ٢٣٢).\nطبع بتحقيق د. زين العابدين بن محمد بلا فريح سنة ١٤١٩ هـ- ١٩٩٨ م.\nوإنما عددناه في النكت؛ لكونه زاد بعض الزيادات التي خطرت له، والكتاب طبع بتحقيق صلاح فتحي هلل سنة ١٤١٨ هـ- ١٩٩٨ م.\nطبع مع مقدمة ابن الصلاح بتحقيق د. عائشة عبد الرحمان (بنت الشاطئ) سنة ١٩٧٤م.\nطبع قديمًا بتحقيق عبد الرحمان محمد عثمان، وهي إلى السقم أقرب، وقد أعددناه للطبع على نسخ إحداها عليها خط المؤلف، ومن الله التوفيق.\nانظر: بغية الوعاة ١/ ٦٣.\nطبع بتحقيق د. ربيع بن هادي عمير. سنة ١٤٠٨ هـ - ١٩٨٨ م."}],[340,"الفصل الرابع: تحقيق الكتاب ومنهجنا فيه"],[341,"المبحث الأول: اسم الكتاب"],[342,"قد بات شيئًا مهمًّا في قواعد علم تحقيق المخطوطات ونشرها، أن يثبت المحقق الاسم الصحيح للكتاب الذي أسماه به مؤلفه، إذ قد تتقاذف الكتاب أيادي الدهر وتتقادم عليه الأيام والسنون، فيبلى بمرورها اسمه ويندثر رسمه، ومن تلك المصنفات التي جرت عليها هذه الجواري كتابنا هذا، فقد اشتهر بين الناس أن اسمه \" مقدمة ابن الصلاح \" أو \" علوم الحديث \"، والحق أن واحدًا من هذين الاسمين لَمْ يسمه به مؤلفه، وقد حقق هذا تحقيقًا علميًا الدكتور موفق بن عبد الله بن عبد القادر في فصل نفيس ضمَّنه كتابه القيم \" توثيق النصوص وضبطها عن المحدِّثين \" (١)، رأينا أن ننقله بنصّه إذ لا مزيد عَلَى ما أتى به فقال - أيده الله -:"],[343,"«ومثاله أيضًا كتاب \" معرفة أنواع علوم الحديث \" للإمام الحافظ أبي عمرو عثمان ابن عبد الرحمان الشهرزوري المتوفَّى سنة (٦٤٣ هـ). فإن هذا الكتاب عُرِف واشتُهِر بين طلاَّب العلم باسم \"مقدِّمة ابن الصلاح\" فَمِنْ أينَ جاءته هذه التسمية؟"],[344,"١. إن المصنِّف - رَحِمَهُ اللهُ تَعَالَى - لَمْ يسمِّ كتابه بـ \" المقدمة \" كما أن أحدًا من أهل العلم ممَّن جاء بعد الصلاح لَمْ يسمِّ كتاب [ابن] (٢) الصلاح بـ \" المقدِّمة \"."],[345,"٢. إن ابن الصلاح قد سمَّى كتابه ونص عَلَى هذه التسمية في فاتحة كتابه فقال: «... فحين كاد الباحث عن مشكلة لا يلقى له كاشفًا، والسائل عن علمه لا يلقى به عارفًا، مَنَّ الله الكريم - تبارك وتعالى -، وله الحمد أجمع بكتاب: \" معرفة أنواع علم الحديث \"، هذا الذي باح بأسراره الخفية ...» (٣).","",{"fn":"١٠٢ - ١٠٨.\nسقطت من الأصل.\nمعرفة أنواع علم الحديث: ٧٤ من طبعتنا هذه."}],[346,"٣. إن نسخة إستانبول المحفوظة في المكتبة السليمانية برقم (٣٥١)، والتي كان الفراغ من قراءتها عَلَى المصنِّف سنة (٦٤١ هـ) أي: قبل وفاة ابن الصلاح بعام واحد ونيِّف، والتي أثبت ابن الصلاح - رَحِمَهُ اللهُ تَعَالَى - خطّه عليها في عدّة مواضع جاء في صورة السماع: «سَمِعَ جميع هذا الكتاب وهو كتاب \" معرفة أنواع علم الحديث \" على مصنِّفه ...». وكتب ابن الصلاح - رحمه الله - في آخر طبق السماع:"],[347,"«صحَّ ذَلِكَ نفعه الله وبلَّغه ...»."],[348,"٤. وجاء اسم الكتاب في سماع النسخة المحفوظة بدار الكتب المصرية تحت رقم: (١٥٥) مصطلح الحديث، وهي نسخة قيمة وموثقة: «سمعت جميع هذا الكتاب المترجم بكتاب \" معرفة أنواع علم الحديث \" ...»."],[349,"٥. أطلق كثير من العلماء عَلَى الكتاب اسم \" علوم الحديث \" عَلَى اعتبار مضمونه ومادته العلمية."],[350,"٦. ومن هؤلاء الإمام محيي الدين يحيى بن زكريا النووي المتوفَّى سنة (٦٦٧ هـ) في كتابه \" التقريب \" (١)، وفي \" إرشاد طلاب الحقائق \" سمّاه \"معرفة علوم الْحَدِيْث \" (٢)."],[351,"٧. وقال تلميذ ابن الصلاح شمس الدين أحمد بن مُحَمَّد بن خلكان المتوفَّى سنة (٦٨١هـ) في ترجمة ابن الصلاح: «وصنّف في علوم الحديث كتابًا نافعًا ...» (٣)."],[352,"٨. واختصره الحافظ عماد الدين أبو الفداء إسماعيل بن عمر الدمشقي المعروف بـ: ابن كَثِيْر المتوفَّى سنة (٧٧٤ هـ) وسمّى هذا المختصر \"اختصار علوم الحديث\"."],[353,"٩. وكذا سمّاه \" علوم الحديث \" الإمام الحافظ أحمد بن محمد بن عثمان الذهبي المتوفَّى سنة (٧٤٨ هـ) في كتابه \" سير أعلام النبلاء \" (٤).","",{"fn":"تدريب الراوي في شرح تقريب النواوي ١/ ٦١.\nإرشاد طلاب الحقائق ١/ ١٠٧.\nوفيات الأعيان ٣/ ٢٤٤.\n٢٣/ ١٤١."}],[354,"١٠. وكذا قال قاضي القضاة عز الدين عبد العزيز بن مُحَمَّد بن إبراهيم بن جماعة المتوفَّى سنة (٧٦٧هـ) فألَّف كتاب \"الجواهر الصحاح في شرح علوم الحديث لابن الصلاح\"، وله نسخة خطية في دار الكُتُب المصرية تحت رقم (٨٧٣ هـ) مصطلح الحديث."],[355,"١١. وكذا سمَّاه الحافظ زين الدين عبد الرحيم بن الحسين العراقي المتوفَّى سنة (٨٠٦ هـ) في كتابه \" التقييد والإيضاح لما أُطلِق وأُغلِقَ من كتاب ابن الصلاح\" (١)."],[356,"١٢. وكذا سمَّاه \" علوم الحديث \" مصطفى بن عبد الله القسطنطيني الشهير بالملاَّ كاتب الجلبي والمعروف بحاجي خليفة المتوفَّى سنة (١٠٦٧ هـ) في كتابه: \" كشف الظنون عن أسامي الكُتُب والفنون \" (٢)."],[357,"١٣. وكذا سمّاه \" علوم الحديث \" مُحَمَّد بن سليمان الروداني في \" صلة الخلف بموصول السلف \" (٣)."],[358,"١٤. وكذا سمّاه \"علوم الحديث\"السيد مُحَمَّد بن جعفر الكتَّاني في كتابه \" الرسالة المستطرفة \" (٤)."],[359,"١٥. وكذا عبد الحي بن عبد الكبير الكتاني المتوفَّى سنة (١٣٨٢ هـ) في كتابه \" فهرس الفهارس والأثبات \" (٥)."],[360,"١٦. وجاء اسم الكتاب على لوحة العنوان في النسخة الموصلية المحفوظة بخزانة دار الكتب المصرية تحت رقم (١) مصطلح الحديث \" علوم الحديث \"."],[361,"وجاءت في اللوحة الأخيرة: «تمت أنواع علوم الحديث بمشيئة الله تعالى عَلَى يدي عليِّ بن يوسف الموصليِّ - عفا الله عنه - في مستهل جُمادَى الآخرة سنة إحدى وستين وست مئة ...»، وهي نسخة قديمة وقَيِّمة ومنقولة من أصل عليه سماعات «وعرضًا في مجالس آخرها يوم الأحد التاسع من جمادى الأولى سنة إحدى وأربعين وست مئة». وفي آخرها توقيع ابن الصلاح بخطه وجاء فيه: «هذا صحيح نفعه الله وبلّغه وإياي، وكتب مؤلفه - عفا الله عنه وعنهم -».","",{"fn":"التقييد والإيضاح: ٢.\nكشف الظنون ٢/ ١١٦١.\nصلة الخلف: ٣٠٦.\nالرسالة المستطرفة: ٢١٤.\nفهرس الفهارس والأثبات ٢/ ٧٢٢، ٨١٦."}],[362,"١٧. إن \" المقدمة \" في \" علوم الحديث \" هو اسم لـ\" المقدمة \" التي كتبها الإمام الحافظ مجد الدين أبو السعادات المبارك بن مُحَمَّد المعروف بـ: ابن الأثير الجزري المتوفَّى سنة (٦٠٦ هـ) في \" مقدمة \" كتابه الجليل \" جامع الأصول في أحاديث الرسول \" ١/ ٣٥ - ١٧٨."],[363,"فإنه قال في فاتحة كتابه \" جامع الأصول \" الباب الأول: في الباعث عَلَى عمل الكتاب، وفيه مقدمة (١) وأربعة فصول \" المقدمة \" (٢)."],[364,"وقال في آخر \" المقدمة \" وهي مقَدمة في \" علوم الحديث \": «هذا آخر القول في الباب الثالث من هذه المقدمة»"],[365,"١٨. لذا لا يمكن التسليم من الناحية العلمية أن كتاب \" معرفة أنواع علم الحديث \" للإمام الحافظ ابن الصلاح أنّه «شهير، أو معروف بالمقدمة»."],[366,"١٩. ويبقى السؤال قائمًا: مَن الذي سمّى كتاب ابن الصلاح \"معرفة أنواع علم الحديث\" بـ \" المقدمة \"؟"],[367,"والجواب عَلَى ذَلِكَ:"],[368,"أ. إنّ أول من طبع الكتاب عَلَى الحجر هم الهنود سنة (١٣٠٤هـ) بعناية الشَّيْخ عبد الحي اللكنوي باسم \" مقدمة ابن الصلاح \"."],[369,"ب. ثُمَّ طبع للمرة الثانية في مطبعة السعادة بالقاهرة سنة (١٣٢٦هـ) بتصحيح الشَّيْخ محمود السكري الحلبي، بعنوان: \" كتاب علوم الحديث المعروف بمقدمة ابن الصلاح\" كما كتب اسم الكتاب بأعلى كل صفحة منها \"مقدمة ابن الصلاح\".","",{"fn":"جامع الأصول ١/ ٣٥.\nالمصدر السابق ١/ ١٧٨."}],[370,"ج. ثُمَّ نشر الكتاب في المطبعة العلمية بحلب سنة (١٣٥٠ هـ) بعناية السيد مُحَمَّد راغب الطباخ ومذيلًا بذيلين أحدهما كتاب \" التقييد والإيضاح لما أُطلِق وأُغلِق من كتاب ابن الصلاح \" للحافظ العراقي، والثاني \" المصباح عَلَى مقدمة ابن الصلاح \" للشيخ مُحَمَّد راغب الطبَّاخ، غير أن الشيخ مُحَمَّد راغب الطبَّاخ سمَّى كتاب \" التقييد \" بـ: \" التقييد والإيضاح شرح مقدمة ابن الصَّلاَح \"، وأطلق عَلَى كتاب \" مَعْرِفَة أنواع علم الْحَدِيْث\" لابن الصَّلاَح اسم \" المقدمة \" (١)."],[371,"د. ثُمَّ جاءت المحقِّقة الفاضلة الدكتورة عائشة عبد الرحمان (بنت الشاطئ) فطبعت كتاب ابن الصلاح مذيلًا بكتاب \" محاسن الاصطلاح \" للحافظ سراج الدين البلقيني سنة (١٣٩٣ هـ- ١٩٧٤ م) تحت عنوان \" مقدمة ابن الصلاح ومحاسن الاصطلاح \" في حين أن اسم الكتاب عَلَى لوحة المخطوط هو \" محاسن الاصطلاح وتضمين كتاب ابن الصلاح \"."],[372,"وهكذا اشتُهِر الكتاب باسم \"المقدمة\" تبعًا لطبعتي الهند (١٣٠٤، ١٣٥٧هـ)، وطبعة القاهرة (١٣٢٦ هـ)، والطبعة الحلبية الأولى (١٣٥٠ هـ)، والحلبية الثانية (١٣٨٦ هـ)."],[373,"هـ. أمَّا ما جاء عن أرجوزة قاضي القضاة شهاب الدين أبي عبد الله مُحَمَّد بن أحمد بن أحمد بن خليل الخويِّي المتوفَّى سنة (٦٩٣هـ)، والمسمَّاة بـ\" أقصى الأمل والسول في أحاديث الرَّسُوْل \"، والموجود منها نسخة في دار الكُتُب المصرية تحت رقم (٢٥٦) مصطلح حديث من القول: «هي أرجوزة نظم فيها مقدمة ابن الصلاح» (٢)، فهذا القول قاله مؤلفو كتاب \" فهرست المخطوطات \" لدار الكُتُب المصرية."],[374,"و. وكذا ما جاء في تسمية كتاب قاضي القضاة مُحَمَّد بن إبراهيم ابن جماعة المتوفَّى سنة (٧٣٣هـ) \"مختصر تلخيص مقدمة ابن الصلاح في معرفة أنواع علوم الحديث\" الموجودة في دار الكتب المصرية تحت رقم (٣٥٢) مصطلح حديث فإن هذه التسمية هي تسمية النسَّاخ وصانعو فهرست دار الكتب المصرية (٣). وأن اسم الكتاب هو \"المنهل الروي في الحديث النبوي\" كما جاء في النسخة المحفوظة بدار الكتب المصرية تحت رقم (٢١٧ طلعت) (١) وتحت هذا الاسم نشر الكتاب.","",{"fn":"انظر: ٢، ٤، ٦، ١٤، ١٦، ٤١٩.\nفهرست دار الكتب المصرية: ١٦٠.\nفهرست المخطوطات، دار الكتب المصرية، المجلد الأول، مصطلح الحديث: ٢٨٨."}],[375,"لذا فإن الصواب في اسم كتاب ابن الصلاح هو \" معرفة أنواع علم الحديث \" وأن تسميته بـ: \" المقدمة \" هُوَ اجتهاد من ناشري الكِتَاب في الطبعة الهندية الأولى"],[376,"والثانية، وكذا الطبعة المصرية ... ثُمَّ سار الناس عَلَى هذه التسمية، وهي تسمية حديثة لَمْ يقلها أحد من أهل العلم» (٢)."],[377,"المبحث الثاني: توثيق نسبته إلى مؤلفه"],[378,"هذا الكتاب مقطوع بصحة نسبته الى ابن الصلاح، ويدل عَلَى ذَلِكَ دلالة صحيحة الأمور الآتية:"],[379,"١. أن النسخ الثلاث اتفقت طررها عَلَى إثبات اسم ابن الصلاح عليها، بالإضافة إلى أن نسخة (ج) احتوت عَلَى سند الرواية إلى ابن الصلاح، وفي ختام النسخ الثلاث أيضًا تكرر ذكر اسمه ثانية."],[380,"٢. أن الأسانيد التي في داخل الكتاب هي أسانيد أبي عمرو والشيوخ فيها هم شيوخ ابن الصلاح أنفسهم."],[381,"٣. تشابه الأسلوب في كتابه هذا المصنف مع بقية مصنفات ابن الصلاح."],[382,"٤. كل من ترجم له ذكر له هذا التأليف (٣)، بل صار يعرف به فيقال: صاحب كتاب \" علوم الحديث \" (٤)."],[383,"٥. ما تولّد عنه من دراسات - عرضنا لها فيما سبق -."],[384,"كل هذا يجعلنا أمام علم ضروري بأن صاحب هذا الكتاب أبو عمرو بن الصلاح.","",{"fn":"فهرست المخطوطات ١/ ٣١٠ (مصطلح الحديث).\nلذا سمينا نشرتنا هذه بـ: \" معرفة أنواع علم الحديث \".\nانظر: وفيات الأعيان ٣/ ٢٤٣، وسير أعلام النبلاء ٢٣/ ١٤٠، وتذكرة الحفاظ ٤/ ١٤٣٠، والعبر ٥/ ١٧٧، ومرآة الجنان ٤/ ٨٤ - ٨٥، وطبقات الشافعية الكبرى ٨/ ٣٢٦، وطبقات الشافعية للإسنوي ٢/ ١٣٣، والبداية والنهاية ١٣/ ١٤٢، والنجوم الزاهرة ٦/ ٣٥٤ وطبقات الحفاظ: ٤٩٩، والدارس ١/ ١٦، وطبقات المفسرين للداوودي ١/ ٣٧٧، وطبقات الشافعية لابن هداية الله: ٢٢٠، وشذرات الذهب ٥/ ٢٢١، والأعلام ٤/ ٤٠٧.\nانظر: تذكرة الحفاظ ٤/ ١٤٣٠."}],[385,"المبحث الثالث: وصف النسخ الخطية المعتمدة في التحقيق"],[386,"بعيدًا عن مصادر ابن الصلاح التي اعتبرناها مصادر ثانوية وروافد في عملنا والتي كنا حريصين على مراجعتها سواء أكانت كتب متون أم أسانيد أم رجال أم تواريخ أو غيرها، فقد اعتمدنا ما يأتي:"],[387,"أولا: النسخ الخطية:"],[388,"اعتمدنا عَلَى ثلاث نسخ خطية - وهي وإن لَمْ تكن عتيقة - لكنها كافية في تصورنا لإخراج نص سليم قويم - إن شاء الله تَعَالَى - وفيما يأتي وصف موجز لكل منها (١):"],[389,"١. نسخة خطية محفوظة في مكتبة الأوقاف العامة الكائنة في مدينة السلام بغداد"],[390,"- حرسها الله - برقم (١/ ٢٨٩٩ مجاميع) تقع في (١٠٤ ورقة) تحوي كل ورقة صفحتين، في كل صفحة واحد وعشرون سطرًا، بمعدل تسع كلمات في السطر الواحد، كتبت بدايات الأنواع بالمداد الأحمر، خطّها نسخي جميل واضح ومقروء، وقع الفراغ من نسخها سنة (١٢١٠ هـ). تظهر عليها آثار المقابلة، وهي غير مشكولة، ناسخها غير معروف، ورمزنا لها بالرمز (أ)."],[391,"٢. نسخة ثانية محفوظة في مكتبة الأوقاف العامة في بغداد - حرسها الله - تحت الرقم (٢٩٤٩) وعدد أوراقها (١١٩ ورقة)، تحوي كل ورقة صفحتين في كل صفحة واحد وعشرون سطرًا، بمعدل عشر كلمات في كل سطر، عليها حواشٍ وآثار مقابلة، خطها نسخي عادي واضح ومقروء، يعود تاريخ نسخها إلى سنة (٨٠٧ هـ) إذ نسخت في رباط النورية في محلة الشونيزية في بغداد على يد مُحَمَّد ابن عبد الرحمان ابن مُحَمَّد بن عبد الرحمان الإسفراييني، وهي قليلة الخطأ نادرة السقط، وقد رمزنا لها بالرمز (ب).","",{"fn":"انظر: فهرس مخطوطات مكتبة الأوقاف العامة في بغداد ١/ ٢٦٩ - ٢٧٠."}],[392,"٣. نسخة ثالثة محفوظة في مكتبة الأوقاف العامة أيضًا بغداد، برقم (٣/ ٢٧٧٣ مجاميع) في (١١١ ورقة)، تحوي كل ورقة صفحتين في كل صفحة ثلاثة وعشرون سطرًا، بمعدل تسع كلمات في السطر الواحد، في بعض الأحيان عليها حواشٍ، خطها واضح ومقروء، وهي حديثة العهد إذ نسخت سنة (١١٢٥ هـ)، في مدينة انطاكية عَلَى يد أبي بكر بن حاج أحمد بن شيخ مُحَمَّد المؤذن بجامع الصوفية، ورمزنا لها بالرمز (ج)."],[393,"ثانيا: النسخ المطبوعة"],[394,"بغية التوصل إلى نص صحيح اعتمدنا عَلَى نسخ مطبوعة، ولا سيّما أن كلًا مِنْهُم اعتمد نسخًا خطيةً أُخْرَى لضبط النص، وهذه النسخ هي:"],[395,"١. النسخة المطبوعة بتحقيق الدكتور نور الدين عتر، والتي نشرتها المكتبة العلمية في المدينة المنورة سنة (١٣٨٦هـم) ورمزنا لها بالرمز (ع)."],[396,"٢. النص المطبوع مع كتاب محاسن الاصطلاح للبلقيني بتحقيق الدكتورة عائشة"],[397,"عَبْد الرحمان (بنت الشاطئ) نشر وطباعة دار الكتب في بيروت سنة"],[398,"(١٩٧٤ م)، ورمزنا لها بالرمز (م)."],[399,"٣. النص المطبوع مع كتاب التقييد والإيضاح للحافظ العراقي، بتحقيق عبد الرحمن مُحَمَّد عثمان، المطبوع في مطبعة العاصمة في القاهرة ونشرته المكتبة السلفية في المدينة المنورة سنة (١٣٨٩هـ- ١٩٧٠ م)، ورمزنا لها بـ: (التقييد)."],[400,"٤. النص الَّذِي ضمّنه الأبناسي في كتابه \" الشذا الفياح \"، والذي حققه صلاح فتحي هلل، نشر مكتبة الرشد بالاشتراك مَعَ شركة الرياض في المملكة العربية السعودية، سنة (١٤١٨ هـ١٩٩٨ م)، ورمزنا لها بـ: (الشذا)."],[401,"المبحث الرابع: منهج التحقيق"],[402,"يمكننا أن نلخص منهج التحقيق الذي سرنا عليه والتزمناه في تحقيقنا لكتاب"],[403,"\" معرفة أنواع علم الحديث \" في ما يأتي:"],[404,"١. حاولنا ضبط النص قدر المستطاع معتمدين على النسخ الخطية، ومستعينين بما نثق به من الكتب والطبعات السابقة للكتاب، مع مراجعة المصادر المباشرة للمؤلف، ككتب المتون والأسانيد، وكتب الرجال على اختلاف ألوانها."],[405,"٢. خرّجنا الآيات الكريمات من مواطنها في المصحف، مع الإشارة إلى اسم السورة ورقم الآية."],[406,"٣. خرّجنا الأحاديث النبوية الكريمة تخريجًا مستوعبًا حسب الطاقة، وبينا ما فيها من نكت حديثية، ونبّهنا على مواطن الضعف، وكوامن العلل مستعينين بما ألّفه الأئمة الأعلام جهابذة الحديث ونقّاد الأثر في هذا المجال."],[407,"٤. خرّجنا أكثر نقولاته عن العلماء وذلك بعزوها إلى كتبهم."],[408,"٥. تتبّعنا المصنف فيما يورده من المذاهب سواء أكانت لغوية أم فقهية أم غيرها؟ ووثّقناها من المصادر التي تعنى بتلك العلوم."],[409,"٦. لم يكن من وكدنا أن نترجم للأعلام الذين يذكرهم المصنف رغم فائدتها التي لا تخفى، مقدمين دفع مفسدة تضخم الكتاب، على مصلحة التعريف بهؤلاء الأعلام، على أن الكتاب لا يخلو من التعريف ببعضهم."],[410,"٧. قدّمنا للكتاب بدراسة نراها - حسب اعتقادنا - كافية كمدخل إليه."],[411,"٨. لم نألوا جهدًا في تقديم أي عمل يخدم الكتاب، وهذا يتجلى في الفهارس المتنوعة التي ألحقناها بالكتاب، بغية توفير الوقت والجهد على الباحث."],[412,"٩. قمنا بشكل النص شكلًا كاملًا."],[413,"١٠. علّقنا على المواطن التي نعتقد أنها بحاجة إلى مزيد إيضاح وبيان."],[414,"١١. ذيّلنا الشرح بالمهم من نكت وتعليقات، ممّا أغنى الكتاب وتمّم مقاصده."],[415,"١٢. حاولنا جاهدين إيراد النكت والتعقبات وأجوبتها في أكثر الأحيان من مصادرها الأصيلة كـ\" نكت الزركشي \" و\" نكت العراقي \" و\"نكت ابن حجر\" و\" البحر الذي زخر \" وغيرها."],[416,"وبعد هذا كلّه، فلسنا من الذين يدّعون الكمال لأنفسهم أو أعمالهم، وليتذكر من يقف على هفوة أو شطحة قلم أن يقدّم النظر بعين الرضا على الانتقاد بعين السخط، وليضع قول الإمام الشافعي - رحمه الله - نصب عينيه إذ يقول:"],[417,"وَعَيْنُ الرِّضَا عَنْ كُلِّ عَيْبٍ كَلِيْلَةٌ ... ولَكِنَّ عَيْنَ السُّخْطِ تُبْدِي المَسَاويَا (١)"],[418,"سبحان ربك ربّ العزة عمّا يصفون، وسلام على المرسلين، والحمد لله ربّ العالمين، وآخر دعوانا أن الحمد لله رب العالمين.","",{"fn":"ديوان الإمام الشافعي: ٩١."}],[419,"صور للمخطوطات بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ (١)"],[420,"﴿رَبَّنَا آتِنَا مِنْ لَدُنْكَ رَحْمَةً وَهَيِّئ لَنَا مِنْ أَمْرِنَا رَشَدًا﴾ (٢)"],[421,"الحمدُ للهِ الْهَادِي مَنِ اسْتَهْدَاهُ، الواقِي (٣) مَنِ اتَّقاهُ، الكافي مَنْ تحرّى رضاهُ، حمدًا بالغًا أمدَ التمامِ ومنتهاهُ (٤). والصلاةُ والسلامُ الأتمَّانِ (٥) الأكملانِ على نبيِّنا والنبيِّينَ (٦)، وآلِ كُلٍّ (١) ما رجى راجٍ مغفرتَهُ ورحماهُ، آمينَ.","",{"fn":"ورد في نسخة (جـ) سند النسخة المنقولة عَنْهَا هذِهِ النسخة عَلَى النحو الآتي: «الحمد لله ربِّ العالمين، وصلَّى الله عَلَى سيدنا مُحَمَّد وعلى آله وصحبه وسلّم، قرأت عَلَى الشَّيْخ الإمام الحبر ابن مُحَمَّد أحمد بن قاسم بن عَبْد الرحمان بن أبي بَكْر الحرازي جَمِيْع \" علوم الحَدِيْث \" لابن الصَّلاح بمكة المشرفة في شهور سنة خمس وخمسين وسبع مئة، قَالَ: قرأت عَلَى العلاَّمة رضي الدين إبراهيم بن مُحَمَّد بن إبراهيم الطبري جميعه في سنة ثلاث عَشْرَة وسبع مئة، قَالَ: أنبأنا الإمام الحافظ تقي الدين ابن (كذا، والصواب أبو) عمرو عثمان بن عبد الرحمان بن عثمان بن موسى بن نصر النصري الشهرزوري الشافعي المعروف بـ (ابن الصلاح) إجازة. قال: وأخبرنا عنه سماعًا الإمام أمين الدين عبد الصمد بن عبد الوهاب بن أبي البركات الحسن ابن عساكر قال: أملى علينا ابن الصلاح - نوّر الله بالعلم صدره ورفع بالعمل الصالح في الدارين قدره - بمدينة دمشق بدار السنة الأشرفية، وكان ابتداء إملائه علينا ونحن نسمع بعد صلاة الجمعة السابع من رمضان المعظّم من عام ثلاثين وست مئة، فقال: ...».\nالكهف: ١٠. ولم ترد الآية الكريمة في (أ) و(ب)، وهي من (جـ) و(ع) و(م).\nقال الحافظ ابن حجر في نكته ١/ ٢٢٣: «بالقاف، وهو مشتق من قوله تعالى: ﴿فَوَقَاهُ اللهُ﴾ عملًا بأحد المذهبين في الأسماء الحسنى - والأصحّ عند المحققيين: أنها توقيفية. وأمّا قوله سبحانه وتعالى: ﴿وَمَا لَهُم مِنَ اللهِ مِنْ وَاقٍ﴾ فلا توقيف فيه على ذلك؛ لكن اختيار الغزالي: أن التوقيف مختص بالأسماء دون الصفات، وهو اختيار الإمام فخر الدين أيضًا. وعلى ذلك يحمل عمل المصنف وغيره من الأئمة». وانظر: القواعد المثلى ص ١٣، وص ٢٨.\nقال الحافظ ابن حجر في نكته ١/ ٢٢٣: «اعترض عليه بأن هذه دعوى لا تصح وكيف يتخيل شخص أنه يمكنه أن يحمد الله حمدًا يبلغ منتهى التمام. والفرض أن الخلق كلهم لو اجتمع حمدهم لم يبلغ بعض ما يستحقه تعالى من الحمد فضلًا عن تمامه والنبي - صلى الله عليه وآله وسلم - يقول: «لا أحصي ثناءً عليك»، مع ما صح عنه في حديث الشفاعة: «أن الله يفتح عليه بمحامد لم يسبق إليها». والجواب: أن المصنف لم يدَّعِ أن الحمد الصادر منه بلغ ذلك، وإنما أخبر أن الحمد الذي يجب لله هذه صفته، وكأنه أراد أن الله مستحقٌ لتمام الحمد، وهذا بيِّن من سياق كلامه».\nلم ترد في النسخ الخطية و(م)، وهي من (ع) والتقييد.\nللحافظ ابن حجر تعليق حول هذا التعبير. انظره في نكته ١/ ٢٢٤."}],[422,"هذا (٢)، وإنَّ عِلْمَ الحديثِ (٣) مِنْ أفضلِ العلومِ الفاضلةِ، وأنفعِ الفنونِ النافعةِ، يُحبُّهُ ذكورُ الرجالِ وفحولَتُهُم (٤)، ويُعْنَى (٥) بهِ محقِّقُو العلماءِ وكَمَلَتُهُم، ولا يكرهُهُ مِنَ الناسِ إلاَّ رُذالتُهم (٦) وسَفِلتُهُم (٧)."],[423,"وهو مِنْ أكثرِ العلومِ تولُّجًا (٨) في فنونها، لا سيَّما الفقهُ (٩) الذي هو إنسانُ عُيونِها؛ ولذلكَ كَثُرَ غَلطُ العاطلينَ (١) منهُ مِنْ مُصَنِّفِي الفقهاءِ، وظهرَ الخللُ في كلامِ الْمُخلِّينَ بهِ مِنَ العلماءِ. ولقدْ كانَ شأنُ الحديثِ فِيْمَا مَضَى عظيمًا، عظيمةً جموعُ طَلبَتِهِ (٢)، رفيعةً مقاديرُ حُفَّاظِهِ وحملَتِهِ. وكانتْ علومُهُ بحياتِهِم حيَّةً، وأفنانُ فنونِهِ (٣) ببقائِهِم غَضَّةً (٤)، ومغانيهِ (٥) بأهلِهِ آهِلَةً (٦). فلمْ يزالُوا في انقراضٍ، ولَمْ يزلْ في اندراسٍ حتَّى آضتْ (٧) بهِ الحالُ إلى أنْ صارَ أهلُهُ إنَّما هُمْ شِرْذِمةٌ (٨) قليلةُ العَدَدِ (٩)","",{"fn":"قوله: «وآل كل»، أضافه إلى الظاهر، ولم يقل: وآلهم؛ خروجًا من الخلاف؛ لأن بعضهم لا يجيز إضافته إلى المضمر. وانظر: نكت الزركشي ١/ ١٣ مع حاشية المحقق، ونكت ابن حجر ١/ ٢٢٥.\nقال الزركشي في نكته ١/ ١٣: «هو فاصل عن الكلام السابق للدخول في غرض آخر، ونظيره في التخلص قوله تعالى: ﴿هَذَا وَإِنَّ لِلطَّاغِيْنَ لَشَرَّ مَآبٍ﴾، ولعل هذا السبب في أن المصنف لم يذكر (أما بعد)، وإن ورد أن النبي كان يقولها في خطبه». فهذا إذن من التفنن الذي لا حجر فيه، على قول ابن حجر في نكته ١/ ٢٢٥.\nقال ابن حجر في نكته ١/ ٢٢٥: «أولى التعاريف لعلم الحديث - يريد علم الحديث دراية -: معرفة القواعد التي يتوصل بها إلى معرفة حال الراوي والمروي». وانظر: تفصيل هذا في البحر الذي زخر ١/ ٢٢٦، وتدريب الراوي ١/ ٤٠.\nورد هذا المعنى في كلام الزهري - رحمه الله -. انظر: نكت الزركشي ١/ ١٤.\nهو بضم الياء وفتح النون على البناء للمفعول (المجهول)، وهو من الأفعال الملازمة للبناء للمفعول، ويجوز فيه البناء للفاعل (المعلوم) أيضًا، ولكن البناء للمفعول أفصح. انظر: الصحاح ٦/ ٢٤٤٠، واللسان ١٥/ ١٠٤، ونكت الزركشي ١/ ٢١، والتقييد والإيضاح: ١٢.\nالرُّذَالة: -بضمِّ الراء وفتح الذال- هو الرديء، والرذل: الدون والخسيس، يقال: رجل رذل ومرذول، وهو الدون في منظره وحالاته. انظر: أساس البلاغة: ٢٢٩، واللسان ١١/ ٢٨٠، ونكت الزركشي١/ ٢٣.\nالسَّفِلة: - بفتح السين وكسر الفاء - هم السُّقاط من الناس، والمراد: أسافل الناس وغوغاؤهم. انظر: اللسان ١١/ ٣٣٧، ونكت الزركشي ١/ ٢٣.\nقال ابن حجر في نكته ١/ ٢٢٧: «أي دخولًا في فنونها، والمراد بالعلوم هنا الشرعية، وهي: التفسير والحديث والفقه؛ وإنما صار أكثر لاحتياج كل من العلوم الثلاثة إليه. أمّا الحديث: فظاهر. وأمّا التفسير: فإنّ أولى ما فسر به كلام الله تعالى، ما ثبت عن نبيه - صلى الله عليه وآله وسلم -، ويحتاج الناظر في ذلك إلى معرفة ما ثبت مما لم يثبت. وأمّا الفقه: فلاحتياج الفقيه إلى الاستدلال بما ثبت من الحديث دون ما لم يثبت، ولا يتبين ذلك إلا بعلم الحديث».\nالاسم الواقع بعد (لا سيَّما) إذا كان معرفة جاز فيه وجهان: الجر والرفع، أما إذا كان نكرة ففيه ثلاثة أوجه: الجر والرفع والنصب، وليس هذا محل توجيه ذلك. = =والمشهور في استعمالها أن يقال: (ولا سيَّما)، وذكروا أنها تخفّف وقد تحذف الواو، وربّما حذفوا (لا) فيقال: (سيما)، وهي لغة ضعيفة. انظر توجيه هذا الكلام وشواهده في اللسان ١٤/ ٤١١، ونكت الزركشي ١/ ٢٥ مع حاشية المحقق، ومتن اللغة ٣/ ٢٥٨.\nفي جميع النسخ الخطية: «الغالطين»، وأشار ناسخ (أ) إلى أنها في نسخة: «العاطلين»، وما أثبتناه من (م) و(ع) والتقييد، وهو الأجود معنًى.\nقال الزركشي في نكته ١/ ٢٧: «وهذا شيء كالمتواتر عند من نظر تراجمهم وأحوالهم» ثمَّ ساق أمثلة كثيرة على ذلك، فراجعه تجد فائدة.\nقال ابن حجر في نكته ١/ ٢٢٧: «الأفنان: جمع فنن - بفتحتين - وهو الغصن، والفنون: جمع فنّ، وهو الضرب من الشيء، أي: النوع. ويجمع أيضًا على أفنان؛ لكن المراد هنا بالأفنان جمع فنن كما تقدّم». وانظر: اللسان ١٣/ ٣٢٦.\nقال ابن حجر في نكته ١/ ٢٢٧: «غضّة، أي: طرية، وهي استعارة مناسبة للفنن، وفيه الجناس بين أفنان وفنون». وانظر: الصحاح ٣/ ١٠٩٥.\nفي (أ): «معانيه» بالمهملة. قال ابن حجر ١/ ٢٢٨: «المغاني - بالغين المعجمة -: جمع مغنى مقصور، وهو المكان الذي كان مسكونًا، ثمَّ انتقل أهله عنه؛ فكأنه أطلق عليه (مغنى)؛ باعتبار ما آل إليه الأمر، وكان قبل ذلك مسكونًا بأهله المستحقين له لا بغيرهم». وانظر: اللسان ١٥/ ١٣٩.\nقال ابن حجر ١/ ٢٢٨: «فيه جناس خطي في قوله: بأهله آهلة، بوزن فاعلة». وعن مصطلح الجناس الخطي ومفهومه، انظر: الإيضاح في علوم البلاغة ٢١٧.\nالأيض: العود إلى الشيء، يقال: آضَ يئيضُ أيْضًا، أي: عاد. والأيض: الرجوع، يقال: آض فلان إلى أهله، أي: رجع إليهم، وآض كذا، أي: صار. وأصل الأيض: العود، تقول: فعل ذلك أيضًا، إذا فعله مُعاودًا له، راجعًا إليه. انظر: تاج العروس ١٨/ ٢٣٥.\nالشرذمة - والدال لغة فيها -: الجماعة القليلة من الناس، ومنه قوله تعالى: ﴿وإِنَّهُمْ لَشِرْذِمَةٌ لَنَا غَائِضُونَ﴾. وانظر: مقاييس اللغة ٣/ ٢٧٣، ومتن اللغة ٣/ ٣٠٠.\nفي (جـ): القدر."}],[424,"ضعيفةُ العُدَدِ، لا تُعْنى على الأغلبِ في تحمُّلِهِ بأكثرَ مِنْ سماعهِ غُفْلًا (١)، ولا تتعنَّى في تقييدِهِ بأكثَرَ مِنْ كتابتِهِ عُطْلًا (٢)، مُطَّرِحِيْنَ علومَهُ التي بها جُلَّ قدرُهُ، مباعدينَ معارفَهُ التي بها فُخِّمَ أمرُهُ."],[425,"فحينَ كادَ الباحثُ عنْ مُشْكلِهِ لا يُلْفِي لهُ كاشفًا، والسائلُ عنْ علمِهِ لا يَلْقى بهِ عارفًا، مَنَّ اللهُ الكريمُ - تبارك وتعالى - عليَّ (٣) - ولَهُ الحمدُ أجمعُ (٤) - بكتابِ ... \" معرفةَ أنواعِ علمِ الحديثِ \"، هذا الذي باحَ (٥) بأسرارهِ الخفيَّةِ، وكشفَ عَنْ مشكلاتِهِ الأبيَّةِ، وأحكمَ (٦) معاقدَهُ، وقعَّدَ قواعدَهُ، وأنارَ معالِمَهُ، وبيَّنَ أحكامَهُ (٧)، وفصَّلَ أقسامَهُ، وأوضحَ أصولَهُ، وشرحَ فروعَهُ وفصولَهُ، وجمعَ شتاتَ علومِهِ (٨) وفوائدَهُ، وقنصَ شواردَ نُكتِهِ وفرائدَهُ (٩). فاللهَ العظيمَ الذي بيدِهِ الضّرُّ والنَّفْعُ والإعطاءُ والمنعُ أسألُ، وإليهِ أضَّرَّعُ وأبتهلُ، متوسلًا إليهِ بكلِّ وسيلةٍ، متشفِّعًا (١٠» إليهِ بكلِّ شفيعٍ، أنْ يجعلَهُ مَلِيًّا بذلكَ وأملى (١)، وافيًا بكلِّ ذلكَ وأوفى، وأنْ يُعَظِّمَ الأجرَ والنَّفْعَ بهِ في الدارَينِ، إنَّهُ قريبٌ مجيبٌ، وما توفيقي إلاَّ باللهِ عليهِ توكَّلْتُ وإليهِ أُنيبُ.","",{"fn":"الغُفْل - بضمِّ الغين وسكون الفاء - هو الذي لا علامة به، يقال: أرضٌ غُفْلٌ، لا عَلَمَ بها ولا أثر عمارة، وأرضٌ غُفْلٌ: لم تمطر، ورجلٌ غُفْلٌ: لم يجرِّب الأمور. قال ابن حجر ١/ ٢٢٨: «وهي استعارة، يقال: أرض غُفْلٌ: لا عَلَمَ بها ولا أثر عمارة، فكأنه شبَّه الكتاب بالأرض، والتقييد بالنقط والشكل والضبط بالعمران». وانظر: الصحاح ٥/ ١٧٨٣، ونكت الزركشي ١/ ٤٠.\nعُطُل: بضمتين، ويجوز إسكان الطاء، معناه: الخلو من الشيء، وأصل استعماله في الحَلي، ويقال: عَطِلَ من المال والأدب، فهو عُطْلٌ. انظر: مقاييس اللغة ٤/ ٣٥١، واللسان ١١/ ٤٥٤، ونكت الزركشي ١/ ٤٠. ولا بدَّ من التنبيه على أن المصنِّف أشار بذلك إلى أن الاقتصار على السماع والكتابة أدنى درجات علم الحديث. وانظر تفصيل ذلك في: نكت الزركشي ١/ ٤١، ونكت ابن حجر ١/ ٢٢٨.\nليست في (جـ) و(م).\nفي (ع) والتقييد: «أن أجمع». ولم ترد (أن) في شيء من النسخ الخطية ولا (م).\nفي (م): «أباح».\nفي (أ) حاشية نصها: «أي أتقن المسائل المقررة».\nساقطة من ب.\n«شتات علومه»، سقطت من (ب).\nساقطة من (أ)، وفي (جـ): «وفريده»، وفي التقييد: «وفوائده».\nفي (ب) و(جـ): «مستشفعًا»، وسقطت: «بكل وسيلة» من (ب)."}],[426,"وهذهِ فِهْرِسْتُ (٢) أنواعِهِ:"],[427,"فالأوَّلُ منها: معرفةُ الصحيحِ مِنَ الحديثِ."],[428,"الثاني: معرفةُ الحسَنِ منهُ."],[429,"الثالثُ: معرفةُ الضعيفِ منهُ."],[430,"الرابعُ: معرفةُ الْمُسْنَدِ."],[431,"الخامسُ: معرفةُ الْمُتَّصِلِ."],[432,"السادسُ: معرفةُ المرفوعِ."],[433,"السابعُ: معرفةُ الموقوفِ."],[434,"الثامنُ: معرفةُ المقطوعِ، وهو غيرُ المنقطعِ (٣)."],[435,"التاسعُ: معرفةُ المرسلِ."],[436,"العاشرُ: معرفةُ المنقطعِ."],[437,"الحادي عشرَ: معرفةُ الْمُعْضَلِ، ويليهِ تفريعاتٌ، منها: في الإسنادِ الْمُعَنْعَنِ، ومنها: في التعليقِ."],[438,"الثاني عشرَ: معرفةُ التدليسِ وحكمُ الْمُدَلَّسِ."],[439,"الثالثَ عشرَ: معرفةُ الشَّاذِّ.","",{"fn":"قال العراقي في التقييد: ١٣: «استعمل المصنِّف هنا «مليًا وأملى» بغير همز على التخفيف، وكتبه بالياء لمناسبة قوله: «وفيًا وأوفى»، وإلاّ فالأول مهموز من قولهم: مَلُؤَ الرجلُ - بضم اللام وبالهمز - أي: صار مليئًا، أي: ثقة، وهو مَلِئٌ بَيِّن الملاء والملاءة، ممدودان، قاله الجوهري». وانظر: الصحاح ١/ ٧٣.\nفي (م) والتقييد: «فهرسة» بالتاء المربوطة. قال ابن حجر ١/ ٢٣١: «الصواب أنها بالتاء المثناة وقوفًا وإدماجًا، وربما وقف عليها بعضهم بالهاء وهو خطأ. قال صاحب تثقيف اللسان: فهرست -بإسكان السين- والتاء فيه أصلية، ومعناها في اللغة: جملة العدد للكتب، لفظة فارسية، قال: واستعمل الناس منها فهرسَ الكتبَ يفهرسها فهرسة، مثل دَحْرَجَ. وإنما الفهرست: اسم جملة العدد، والفهرسة: المصدر، كالفذلكة، يقال: فذلكت إذا وقفت على جملته». وجاء في القاموس المحيط وشرحه التاج ١٦/ ٣٤٩: «الفِهْرِس - بالكسر - قال الليث: هو الكتاب الذي تجمع فيه الكتب، وقال: ليس بعربي محض، ولكنّه معرَّب، وقال غيره: هو معرَّب فِهْرِسْت، وقد اشتقّوا منه الفِعْل فقالوا: فَهْرَسَ كتابَهُ فَهْرَسَةً، وجمعُ الفَهْرَسَةِ: فهارِس». وانظر: نكت الزركشي ١/ ٥٥، والنكت الوفية ٢٥٤ ب و٢٥٩ ب، والمعجم الوسيط ٢/ ٧٠٤.\nفي (م): «المتقطع»."}],[440,"الرابعَ عشرَ: معرفةُ الْمُنْكَرِ."],[441,"الخامسَ عشرَ: معرفةُ الاعتبارِ والمتابعاتِ والشواهدِ."],[442,"السادسَ عشرَ: معرفةُ زياداتِ الثقاتِ وحكمِها."],[443,"السابعَ عشرَ: معرفةُ الأَفرادِ."],[444,"الثامنَ عشرَ: معرفةُ الحديثِ المعلَّلِ."],[445,"التاسعَ عشرَ: معرفةُ الْمُضْطَرِبِ مِنَ الحديثِ."],[446,"العشرونَ: معرفةُ الْمُدْرَجِ منَ الحديثِ."],[447,"الحادي والعشرونَ: معرفةُ الحديثِ الموضوعِ."],[448,"الثاني والعشرونَ: معرفةُ المقلوبِ."],[449,"الثالثُ والعشرونَ: معرفةُ صِفَةِ مَنْ تُقبَلُ روايتُهُ وَمَنْ تُرَدُّ روايتُهُ."],[450,"الرابعُ والعشرونَ: معرفةُ كيفيةِ سماعِ الحديثِ وتحمّلِهِ، وفيهِ: بيانُ أنواعِ الإجازةِ وأحكامِها، وسائرِ وجوهِ الأخذِ والتحمُّلِ، وعِلْمٌ جَمٌّ (١)."],[451,"الخامسُ والعشرونَ: معرفةُ كتابةِ الحديثِ وكيفيّةِ ضَبْطِ الكتابِ وتقييدِهِ، وفيهِ معارفُ مهمّةٌ رائقةٌ."],[452,"السادسُ والعشرونَ: معرفةُ كيفيّةِ روايةِ الحديثِ وشرطِ أدائهِ وما يتعلَّقُ بذلكَ، وفيهِ كثيرٌ من نفائسِ هذا العلمِ."],[453,"السابعُ والعشرونَ: معرفةُ آدابِ المحدِّثِ."],[454,"الثامنُ والعشرونَ: معرفةُ آدابِ طالبِ الحديثِ."],[455,"التاسعُ والعشرونَ: معرفةُ الإسنادِ العالي والنازلِ."],[456,"النوعُ (٢) الْمُوَفِّي ثلاثينَ: معرفةُ المشهورِ مِنَ الحديثِ."],[457,"الحادي والثلاثونَ: معرفةُ الغريبِ والعزيزِ منَ الحديثِ."],[458,"الثاني والثلاثونَ: معرفةُ غريبِ الحديثِ."],[459,"الثالثُ والثلاثونَ: معرفةُ الْمُسَلْسَلِ."],[460,"الرابعُ والثلاثونَ: معرفةُ ناسخِ الحديثِ ومنسوخِهِ.","",{"fn":"في (ع): «فيه علم جم»، وكلمة: «فيه» لم ترد في شيء من النسخ و(م) والتقييد.\nسقطت من (ع) و(م)، وهي من جميع النسخ والتقييد."}],[461,"الخامسُ والثلاثونَ: معرفةُ الْمُصَحَّفِ منَ أسانيدِ الأحاديثِ ومتونِها."],[462,"السادسُ والثلاثونَ: معرفةُ مُخْتَلِفِ الحديثِ."],[463,"السابعُ والثلاثونَ: معرفةُ المزيدِ في متَّصِلِ الأسانيدِ."],[464,"الثامنُ والثلاثونَ: معرفةُ المراسيلِ الخفيِّ إرسالُهَا."],[465,"التاسِعُ والثلاثونَ: معرفةُ الصحابةِ - رضي الله عنهم -."],[466,"الموفِّي أربعينَ: معرفةُ التابعينَ - رضي الله عنهم -."],[467,"الحادي والأربعونَ: معرفةُ الأكابرِ مِنَ الرّواةِ (١) عنِ الأصاغرِ."],[468,"الثاني والأربعونَ: معرفةُ الْمُدَبَّجِ وما سواهُ منْ روايةِ الأقرانِ بعضُهُم عَنْ بعضٍ."],[469,"الثالثُ والأربعونَ: معرفةُ الإخوةِ والأخواتِ مِنَ العلماءِ والرواةِ."],[470,"الرابعُ والأربعونَ: معرفةُ روايةِ الآباءِ عَنِ الأبناءِ."],[471,"الخامسُ والأربعونَ: عكسُ ذلكَ (٢): معرفةُ روايةِ الأبناءِ عنِ الآباءِ."],[472,"السادسُ والأربعونَ: معرفةُ (٣) مَنِ اشتركَ في الروايةِ عنهُ راويانِ متقدِّمٌ ومتأخِّرٌ تباعدَ ما بينَ وفاتَيْهِما."],[473,"السابعُ والأربعونَ: معرفةُ مَنْ لَمْ يروِ عنهُ إلاَّ راوٍ واحدٌ."],[474,"الثامنُ والأربعونَ: معرفةُ مَنْ ذُكِرَ بأسماءٍ مختلفةٍ أو نعوتٍ متعدِّدَةٍ."],[475,"التاسعُ والأربعونَ: معرفةُ (٤) المفرداتِ مِنْ أسماءِ الصحابةِ والرواةِ والعلماءِ."],[476,"الْمُوَفِّي خمسينَ: معرفةُ الأسماءِ والكُنَى."],[477,"الحادي والخمسونَ: معرفةُ كنى المعروفينَ بالأسماءِ دونَ الكنى."],[478,"الثاني والخمسونَ: معرفةُ ألقابِ المحدِّثينَ."],[479,"الثالثُ والخمسونَ: معرفةُ المؤتَلِفِ والمختَلِفِ."],[480,"الرابعُ والخمسونَ: معرفةُ المتَّفِقِ والمفترِقِ."],[481,"الخامسُ والخمسونَ: نوعٌ يتركَّبُ مِنْ هذينِ النوعينِ.","",{"fn":"في (أ) و(ع): «الأكابر الرواة»، وفي (م) والتقييد: «أكابر الرواة»، وما أثبتناه من (ب) و(ج).\n«عكس ذلك» لَم ترد في (ب).\nفي (أ): «معرفةُ رواية».\nساقطة من (ب)."}],[482,"السادسُ والخمسونَ: معرفةُ الرواةِ المتشابهينَ في الاسمِ والنَّسبِ المتمايزِينَ بالتقديمِ والتأخيرِ في الابن والأبِ."],[483,"السابعُ والخمسونَ: معرفةُ المنسوبينَ إلى غيرِ آبائهِم."],[484,"الثامنُ والخمسونَ: معرفةُ الأنسابِ التي باطنُها على خلافِ ظاهرِها."],[485,"التاسعُ والخمسونَ: معرفةُ المبهماتِ."],[486,"الْمُوَفِّي ستينَ: معرفةُ تواريخِ الرواةِ في الوَفَياتِ وغيرِها."],[487,"الحادي والستونَ: معرفةُ الثِّقَاتِ والضُّعفاءِ مِنَ الرواةِ."],[488,"الثاني والستونَ: معرفةُ مَنْ خَلَطَ في آخرِ عمرِهِ مِنَ الثقاتِ."],[489,"الثالثُ والستونَ: معرفةُ طبقاتِ الرواةِ والعلماءِ."],[490,"الرابعُ والستونَ: معرفةُ الموالي مِنَ الرواةِ والعلماءِ."],[491,"الخامسُ والستونَ: معرفةُ أوطانِ الرُّواةِ وبلدانِهِم."],[492,"وذلكَ آخِرُها، وليسَ بآخرِ الممكنِ في ذلكَ فإنَّهُ قابلٌ للتنويعِ (١) إلى ما لا يحصى، إذ لا تُحصى أحوالُ رواةِ الحديثِ وصفاتُهُم، ولا أحوالُ متونِ الحديثِ وصفاتُهُا، وما مِنْ حالةٍ منها ولا صفةٍ إلاَّ وهيَ بصدَدِ أنْ تُفْرَدَ بالذِّكْرِ وأهلُها، فإذا هيَ نوعٌ على"],[493,"حِيالِهِ (٢) ولكنَّهُ نَصَبٌ من غيرِ أَرَبٍ، وحسبُنَا اللهُ ونِعْمَ الوكيلُ.","",{"fn":"كانت للمنكتين والشرّاح والمختصرين لكتاب ابن الصلاح في هذا المقام اعتراضات، ذكرها الزركشي في نكته ١/ ٥٦، ومن ثَمَّ أجملها ابن حجر ١/ ٢٣٢، وهي: أ. تداخل بعض الأنواع مع بعضها الآخر. انظر: اختصار علوم الحديث لابن كثير ١/ ٩٨. ب. عدم الدِّقَّة في الترتيب. جـ. إهماله أنواعًا أخر. ثُمَّ تولَّى الإجابة عن كلّ واحد منها، ولولا خشية الإطالة لنقلنا لك كلامه، فعُدْ إليه فإنّه نفيس قلَّ أن تجده. قلنا: ولذلك نجد بعض من اختصر كتاب ابن الصلاح خالفه في ترتيب مباحث الكتاب، كما فعل ابن جماعة في المنهل الروي، وابن حجر في النخبة وغيرهما. أمَّا كونه قد أهمل بعض الأنواع؛ فَقَدْ زاد البلقيني في محاسنه خمسة أنواع مَعَ الشرح والأمثلة ٦١٢ - ٦٧٤. وزاد الزَّرْكَشِيّ في نكته أنواعًا أخر مَعَ أمثلتها وشرحها ١/ ٥٦ - ٨٥، ثُمَّ أشار ابن حجر في نكته ١/ ٢٣٣ إلى إمكان الزيادة عَلَى مَا ذكره ابن الصَّلاح، ووعد بأنه سيذكر أنواعًا عندما يفرغ من النكت مَعَ الكلام عَلَى كُلّ نَوْع بما لا يقصر، ونجد مِثْل تِلْكَ الزوائد والفوائد في النزهة: ٥٤؛ لذا كان أمام السيوطي سعة في الأمر ليقول في البحر الذي زخر ١/ ٢٤٨ - ٢٥١: «وزدت أنواعًا فتمّت مئة» ثُمَّ سردها. ولكنَّ المتأمّل لكلام ابن الصلاح يجد أنه سدّ الباب على من يروم الاستدراك عليه، فقال في نهاية كلامه: «ولكنّه نصب من غير أرب».\nفي (جـ): «خياله»، وفي (م): «حاله»."}],[494,"النوع الأول من أنواع علوم الحديث معرفة الصحيح من الحديث"],[495,"(١)"],[496,"اعلمْ - عَلَّمَكَ اللهُ وإيَّايَ (٢) - أنَّ الحديثَ عندَ أهلِهِ ينقسِمُ إلى صَحيحٍ، وحَسَنٍ، وضَعيْفٍ (٣)."],[497,"أمَّا (٤) الحديثُ الصحيحُ: فهو الحديثُ المسنَدُ الذي يتَّصِلُ إسنادُهُ بنقلِ العَدْلِ الضابطِ عنِ العَدْلِ الضابطِ إلى منتهاهُ، ولا يكونُ شاذًّا، ولا مُعلَّلًا (٥). وفي هذهِ الأوصافِ احترازٌ عَنِ المرسَلِ، والمنقطعِ، والمعضلِ، والشَّاذِّ، وما فيهِ عِلَّةٌ قادحةٌ، وما في راويهِ (٦) نوعُ جرحٍ. وهذهِ أنواعٌ يأتي ذكرُهَا إنْ شاءَ اللهُ تبارك وتعالى.","",{"fn":"انظر في الصحيح: معرفة علوم الحديث: ٥٨، وجامع الأصول ١/ ١٦٠، وإرشاد طلاب الحقائق ١/ ١١٠ - ١٣٦، والتقريب: ٣١ - ٤٢، والاقتراح: ١٥٢، والمنهل الروي: ٣٣، والخلاصة: ٣٥، والموقظة: ٢٤، واختصار علوم الحديث: ٢١، والمقنع ١/ ٤١ وشرح التبصرة والتذكرة ١/ ١١٠، ونزهة النظر: ٨٢، والمختصر للكافيجي: ١١٣، وفتح المغيث ١/ ١٧ وألفية السيوطي: ٣ - ١٥، وشرح السيوطي على ألفية العراقي: ٩٨، وتوضيح الأفكار ١/ ٧، وظفر الأماني: ١٢٠، وقواعد التحديث: ٧٩.\nاعترض على ابن الصلاح في هذا، أن قدّم الدعاء لغيره على الدعاء لنفسه، إن الأولى: أن يُعْكَسَ فإن السُّنَّة في البداءة بالدعاء أن يكون بنفسه ثمَّ بغيرهِ؛ لذا كانت هنا مناقشات ومباحثات، وتفاصيل طويلة، انظرها إن شئت في: نكت الزركشي ١/ ٨٨، والتقييد والإيضاح ١٨، والشذا الفياح ١/ ٦٧.\nقال الحافظ ابن كثير ١/ ٩٩ - معترضًا-: «هذا التقسيم إن كان بالنسبة إلى ما في نفس الأمر، فليس إلاَّ صحيح وضعيف. وإن كان بالنسبة إلى اصطلاح المحدِّثينَ، فالحديث ينقسم عندهم إلى أكثر من ذلك». قلنا: هذا اعتراض الحافظ ابن كثير، وقد نوقش فيه، وَوُجِّه مراد ابن الصلاح، فانظر: نكت الزركشي ١/ ٩١، ومحاسن الاصطلاح: ٨٢، والتقييد والإيضاح: ١٩.\nفي (ب): «فأما».\nتعقَّب بعض الناس - على ما حكاه ابن حجر ١/ ٢٣٤ - ابن الصلاح بأن في تعريفه هذا تكرارًا، كان بإمكانه اجتنابه لو قال: المسند المتصل ... الخ، فيستغني عن تكرار لفظ الإسناد. وأجاب عن هذا: بأنّه إنما أراد وصف الحديث المرفوع؛ لأنه الأصل الذي يتكلّم عَلَيْهِ. والمختار في وصف المُسْنَد: أنه الحَدِيْث الذي يرفعه الصَّحَابيّ مَعَ ظهور الاتصال في باقي الإسناد. فعلى هَذَا لابدّ من التعرض لاتصال الإسناد في شرط الصَّحِيح. وانظر في محترزات وقيود ومناقشات هَذَا التعريف: الاقتراح ١٥٢، ونكت الزَّرْكَشِيّ ١/ ٩٧، والتقييد والإيضاح: ٢٠، ونكت ابن حجر ١/ ٢٣٥، والبحر الذي زخر ١/ ٣١٠.\nفي (ب) و(جـ): «روايته»."}],[498,"فهذَا (١) هو الحديثُ الذي يُحكمُ لهُ بالصِّحَّةِ بلا خلافٍ بينَ أهلِ الحديثِ (٢). وقدْ يختلفونَ في صِحَّةِ بعضِ الأحاديثِ؛ لاختلافِهِم في وجودِ هذهِ الأوصافِ فيهِ (٣) أو لاختلافِهِم في اشتراطِ بعضِ هذهِ الأوصافِ كما في المرسَلِ."],[499,"ومتى قالُوا: «هذا حديثٌ (٤) صحيحٌ» فمعناهُ: أنَّهُ اتَّصَلَ سَندُهُ معَ سائرِ الأوصافِ المذكورةِ، وليسَ مِنْ شرطِهِ أنْ يكونَ مقطوعًا بهِ في نفس الأمرِ، إذْ منهُ ما ينفردُ بروايتهِ عدْلٌ واحدٌ، وليسَ مِنَ الأخبارِ التي أجمعَتِ (٥) الأمّةُ عَلَى تَلَقِّيها بالقبولِ. وكذلكَ إذا قالوا في حديثٍ: «إنَّهُ غيرُ صحيحٍ» فليسَ ذلكَ قطعًا بأنَّهُ كذبٌ في نفس الأمرِ، إذْ قدْ يكونُ صِدقًا في نفسِ الأمرِ، وإنَّما المرادُ بهِ: أنَّهُ لَمْ يصحَّ إسنادُهُ على الشرطِ المذكورِ (٦)، واللهُ أعلمُ."],[500,"فَوَائِدُ مُهِمَّةٌ:"],[501,"إحداها: الصحيحُ يتنوَّعُ إلى متَّفَقٍ عليهِ، ومُخْتَلَفٍ فيهِ (٧)، كما سبقَ ذِكرُهُ، ويتنوَّعُ إلى مشهُورٍ، وغريبٍ، وبَيْنَ ذلكَ. ثُمَّ إنَّ درجاتِ الصحيحِ تتفاوتُ في القوَّةِ بحَسَبِ تمكُّنِ الحديثِ مِنَ الصفاتِ المذكورةِ التي تَنْبَنِي (١) الصِّحَّةُ عليها، وتنقسمُ باعتبارِ ذلكَ إلى أقسامٍ يُسْتَعْصَى إحْصاؤُها على العادِّ الحاصرِ.","",{"fn":"في (أ): «هذا».\nقال العراقي في التقييد: ٢٠: «إنما قيّد الخلاف بأهل الحديث؛ لأن غير أهل الحديث قد يشترطون في الصحيح شروطًا زائدة على هذه، كاشتراط العدد في الرواية كما في الشهادة، فقد حكى الحازمي في شروط الأئمة (ص ٦١) عن بعض متأخري المعتزلة، على أنه قد حُكِيَ أيضًا عن بعض أصحاب الحديث». وانظر: نكت الزركشي ١/ ١١٣، ونكت ابن حجر ١/ ٢٣٨.\nقال العراقي في التقييد: ٢١: «يريد بقوله: هذه الأوصاف، أي: أوصاف القبول التي ذكرها في حدِّ الصحيح، وإنّما نبَّهت على ذلك - وإن كان واضحًا -؛ لأني رأيت بعضهم قد اعترض عليه، فقال: إنه يعني الأوصاف المتقدّمة من إرسال وانقطاع وعضل وشذوذ وشبهها ... إلى آخر كلامه، فراجعه فإنه مفيد، وانظر: نكت الزركشي ١/ ١١٥.\nفي (جـ): «الحديث».\nفي (أ): «اجتمعت».\nانظر: نكت الزركشي ١/ ١١٧ - ١٢٤.\nانظر تفصيل ذلك في المدخل إلى كتاب الإكليل: ٢٩ - ٤٣، ونكت الزركشي ١/ ١٢٥ - ١٢٨."}],[502,"ولهذا نرى الإمساكَ عَنِ الحكمِ لإسنادٍ أو حديثٍ بأنَّهُ الأصحُّ على الإطلاقِ (٢) على أنَّ جماعةً مِنْ أئِمَّةِ الحديثِ خاضُوا غَمْرَةَ (٣) ذلكَ، فاضطربَتْ أقوالُهُم. فَرُوِّيْنا (٤) عنْ إسحاقَ بنِ راهَوَيْهِ (٥) أنَّهُ قالَ: «أصحُّ الأسانيدِ كلِّها: الزُّهريُّ عنْ سالمٍ عنْ أبيهِ» (١)، وَرُوِّيْنا نحوَهُ عنْ أحمدَ بنِ حنبلٍ (٢). وَرُوِّيْنا عنْ عمرِو بنِ عليٍّ الفلاَّسِ أنَّهُ قالَ: «أصحُّ الأسانيدِ: محمدُ بنُ سيرينَ عنْ عَبيدةَ (٣) عنْ عليٍّ» (٤)، وَرُوِّيْنا نحوَهُ عنْ عليِّ بنِ المدِينيِّ (٥)، ورُويَ ذلكَ عنْ غيرِهِما.","",{"fn":"في (أ): «تنبئ»، وفي (ب): «يبتني»، وفي (جـ): «تبنى»، وما أثبتناه من (ع) و(م) والتقييد والشذا الفياح.\nقال العراقي في شرح التبصرة ١/ ١١٤ (بتحقيقنا): «القول المعتمد عليه المختار: أنّه لا يطلق على إسناد معين بأنّه أصحّ الأسانيد مطلقًا؛ لأنّ تفاوت مراتب الصحَّة مترتب على تمكُّن الإسناد من شروط الصحة؛ ويعزّ وجود أعلى درجات القبول في كلّ فردٍ فردٍ من ترجمة واحدة بالنسبة لجميع الرواة». وانظر: نكت الزركشي ١/ ١٣١ - ١٥٧، والتقييد والإيضاح ٢٢، ونكت ابن حجر ١/ ٢٤٧ - ٢٦٢.\nخاضوا، أي: اقتحموا. انظر: التاج ١٨/ ٣٢٢. والغَمْرُ مِنَ الماءِ: خلافُ الضَّحْل، وهو الذي يعلو مَنْ يدخله ويغطّيه. وغَمْرُ البحرِ: معظمه، والغَمْرة: الشدَّة، والماء الكثير. انظر: اللسان ٥/ ٢٩، والمعجم الوسيط ١/ ٢٦٢. وبيَّن السيوطي في شرح ألفية العراقي (ص ١٠٠) معنى هذا فقال: «أي: مشوا فيه، من تشبيه المعقول بالمحسوس، للإشارة إلى أن المتكلّم في ذلك كالخائض في الماء، الماشي في غير مظنة المشي، وهو يؤذن بعدم التمكن، ولهذا اختلفوا فيه على أقوال كثيرة».\nقال البقاعي في النكت الوفية ٢٩٤ ب: «قوله: رُوِّيْنا، مضبوط في نسخ عديدة - بضمِّ الراء وتشديد الواو المكسورة - وهذا اصطلاح لابن الصلاح، سَلَكَهُ؛ لشدّة التَّحرِّي، وَهُوَ أنه إذا حدّث بما حمَلَهُ [ممّن لَقِيَهُ هو وسَمِعَ منه مباشرةً] قال: رَوَيْنا - بالفتح والتخفيف - أي: نَقَلْنَا لغَيْرِنا، وإلاّ قال بالضمِّ - رُوِّيْنا - أي: نقل لنا شيوخُنا» أ. هـ. وما بين المعكوفتين من كلام أبي غدّة، وانظر: نكت الزركشي ١/ ١٢٨، وتوجيه النظر ٢/ ٩٢١ مع تعليق المحقّق. قال الزمخشري: «ومنه قولهم: هو راوية للحديث، وروى الحديثَ: حمله، من قولهم: البعير يروي الماءَ، أي: يحمله، وحديثٌ مروِيٌّ، وهم رواة الأحاديث وراووها: حاملوها، كما يقال: رواة الماء». أساس البلاغة: ٢٦٠. قال الزركشي ١/ ١٢٩: «ولهذا أطلقوا على المزادة التي يحمل فيها: راوية من باب مجاز المجاورة، فإن راوية صيغة مبالغة، وهي حقيقة للجمل، فإطلاقه على ظرف الماء مجاز، وليس هذا من باب: أروي الرباعي حتّى يستحقه الماء دون الجمل؛ لأن اسم الفاعل منه: مَرْوٍ لا راوية، وإنما يأتي راوية من الثلاثي». وانظر: اللسان ١٤/ ٣٤٨.\nقال الزركشي في نكته ١/ ١٢٩: «يجوز في (راهويه) فتح الهاء والواو وإسكان الياء، ويجوز ضمُّ الهاء وإسكان الواو وفتح الياء، وهذا الثاني هو المختار. وعن الحافظ جمال الدين المزّي أنّه قال: غالب ما عند المحدّثين (فعلويه) - بضم ما قبل الواو - إلاّ (راهويه) فالأغلب فيه عندهم فتح ما قبل الواو». وانظر: الأنساب ٣/ ٣٧، وسير أعلام النبلاء ١١/ ٣٥٨، وتدريب الراوي ١/ ٣٣٨. = =أمّا معناه فقد قال الزركشي ١/ ١٣١: «واعلم أن (راهويه) لقب لجده، وسمِّي بذلك؛ لأنه وُلِدَ في الطريق، والرهو: الطريق، وكان أبوه يكره أن يسمّى به». وانظر: تهذيب الكمال ١/ ١٧٦."}],[503,"ثمَّ منهم (٦) مَنْ عَيَّنَ (٧) الراويَ عنْ محمدٍ وجعلَهُ أيُّوبَ السَّخْتِيانيَّ (٨)، ومنهم (٩) مَنْ جعلَهُ ابنَ عَوْنٍ. وفيما نرويهِ عَنْ يحيى بنِ مَعِينٍ أنَّهُ قالَ: «أجودُها: الأعمشُ عنْ إبراهيمَ عَنْ عَلْقَمةَ عنْ عبدِ اللهِ (١٠) ٠») (١١) ١)، وَرُوِّيْنا عنْ أبي بكرِ بنِ أبي شَيبةَ أنَّهُ (١٢) ٢) قالَ: «أصحُّ الأسانيدِ كُلِّها: الزهريُّ عنْ عليِّ بنِ الحسينِ، عنْ أبيهِ، عنْ عليٍّ (١٣) ٣») (١٤) ٤). وَرُوِّيْنا عن أبي عبدِ اللهِ البخاريِّ - صاحبِ \" الصحيحِ \" - أنَّهُ قالَ: أصحُّ الأسانيدِ كُلِّها: مالكٌ عنْ نافِعٍ عنْ ابنِ عمرَ» (١٥) ٥). وبنى الإمامُ أبو منصورٍ عبدُ القاهرِ بنِ طاهرٍ التَّمِيْمِيُّ (١) ١) على ذلكَ أنَّ أجلَّ الأسانيدِ «الشافعيُّ، عنْ مالكٍ، عنْ نافعٍ، عنْ ابنِ","",{"fn":"معرفة علوم الحديث: ٥٤، والكفاية: (٥٦٣ ت - ٣٩٧ هـ).\nمعرفة علوم الحديث: ٥٤.\nهو بفتح العين وكسر الباء، بوزن سفينة. انظر: تبصير المنتبه ٣/ ٩١٣، والتاج ٨/ ٣٤٥.\nمعرفة علوم الحديث ٥٤.\nالمصدر السابق.\nهو سليمان بن حرب. انظر: شرح التبصرة والتذكرة ١/ ١٢٠.\nفي (م): «غيَّر».\nهو بفتح السين وسكون الخاء وكسر التاء، هذه النسبة إلى عمل السِّخْتِيان وبيعها، وهي جلود الماعز إذا دُبِغَتْ. انظر: الأنساب ٣/ ٢٥٥، والتاج ٤/ ٥٥٤.\nهو علي بن المديني. انظر: شرح التبصرة والتذكرة ١/ ١٢٠.\nفي (جـ) زيادة: «ابن مسعود». وفي (م): «عُبيد الله»، مصغَّر محرف.\nمعرفة علوم الحديث: ٥٤.\nساقطة من (ع) والتقييد.\nفي (أ): «عن أبيه علي».\nمعرفة علوم الحديث: ٥٣. وهو قول عبد الرزاق الصنعاني. انظر: الكفاية (٥٦٣ ت، ٣٩٧ هـ).\nمعرفة علوم الحديث: ٥٣، والكفاية: (٥٦٣ ت، ٣٩٨ هـ)."}],[504,"عمرَ»، واحْتَجَّ بإجماعِ أصحابِ الحديثِ على أنَّهُ لَمْ يكنْ في الرّواةِ عَنْ مالكٍ أجلُّ مِنَ الشافعيِّ - رضي الله عنهم أجمعينَ -، واللهُ أعلمُ (٢)."],[505,"الثانيةُ (٣): إذا وجدنا فيما يُروى مِنْ أجزاءِ الحديثِ وغيرِهَا حديثًا صحيحَ الإسنادِ، ولَمْ نجدْهُ في أحدِ «الصحيحينِ»، ولا منصوصًا على صِحَّتِهِ في شيءٍ مِنْ مُصَنَّفَاتِ أئمَّةِ الحديثِ المعتمدةِ المشهورةِ، فإنَّا لا نتجاسرُ على جَزْمِ الْحُكْمِ بصِحَّتِهِ (٤)، فقدْ تَعَذَّرَ في هذهِ الأعصارِ الاستقلالُ بإدراكِ الصحيحِ بمجَرَّدِ اعتبارِ الأسانيدِ؛ لأنَّهُ مَا مِنْ إسنادٍ مِنْ ذلكَ إلاَّ وتجدُ في رجالِهِ مَنِ اعْتَمَدَ في روايتِهِ عَلَى مَا في كتابِهِ عَرِيًّا عمَّا يُشترطُ في الصحيحِ مِنَ الحِفْظِ والضَّبْطِ والإتْقَانِ. فآلَ الأمرُ - إذنْ - في معرفةِ الصحيحِ والحسنِ، إلى الاعتمادِ عَلَى مَا نصَّ عليهِ أئمَّةُ الحديثِ في تصانيفِهِم المعتمدةِ المشهورةِ، الَّتِي يُؤمَنُ فِيْهَا؛ لِشُهْرَتِها مِنَ التَّغييرِ والتَّحريفِ، وصارَ مُعظمُ المقصودِ بما يُتَدَاولُ مِنَ الأسانيدِ خارجًا عنْ ذلكَ، إبقاءَ سلسلةِ الإسنادِ التي خُصَّتْ بها هذهِ الأُمّةُ (٥)، زادها اللهُ تعالى شرفًا، آمينَ.","",{"fn":"هو عبد القاهر بن طاهر البغدادي، عالم متقن من أئمة الأصول، له مؤلفات منها: الفرق بين الفرق، ونفي خلق القرآن، ومعيار النظر وغيرها، توفي سنة (٤٢٩ هـ). وفيات الأعيان ١/ ٢٩٨، طبقات السبكي ٣/ ٢٣٨، الأعلام ٤/ ١٧٣.\nانظر عن هذه المسألة: نكت الزركشي ١/ ١٤١، ومحاسن الاصطلاح: ٨٦، ونكت ابن حجر ١/ ٢٦٢.\nراجع فيما يخصّ التصحيح في العصور المتأخرة: نكت الزركشي ١/ ١٥٨، والتقييد والإيضاح: ٢٣، ونكت ابن حجر ١/ ٢٦٦. وكَتَبَ محقّق الشذا الفياح ١/ ٧١ تعليقًا موفقًا جدًا، وقد نقلناه في شرح التبصرة ١/ ١٥٠، فراجعه فإنه نفيس.\nفي (ب): «على صحته».\nخالف الإمامُ النوويُّ ابنَ الصلاحِ فيما ذهب إليه، فقالَ في التقريب: ٤١: «والأظهر عندي جوازه لمن تمكن وقويت معرفته». قال العراقي في التقييد: ٢٣: «وما رجَّحه الإمام النووي هو الذي عليه عمل أهل الحديث، فقد صحَّحَ جماعة من المتأخّرين أحاديث لم نجد لمن تقدّمهم فيها تصحيحًا ...». وقالَ الشيخ أحمد شاكر في الباعث الحثيث: ٢٩: «هذا هو الصواب»، ثمَّ علَّل ما ذهب إليه ابن الصلاح فقال: والذي أراه أنَّ ابن الصلاح ذهب إلى ما ذهب إليه بناء على القول بمنع الاجتهاد بعد الأئمة، فكما حظروا الاجتهاد في الفقه، أراد ابن الصلاح أن يمنع الاجتهاد في الحديث. وهيهات!!! فالقول بمنع الاجتهاد قول باطل لا برهان عليه من كتاب ولا سنة، ولا تجد له شبه دليل»، وقارن بما سبق. وانظر: التعليق على شرح التبصرة والتذكرة ١/ ١٥٠ - ١٥٤."}],[506,"الثالثةُ: أوَّلُ مَنْ صَنَّفَ الصحيحَ البخاريُّ أبو عبدِ اللهِ محمدُ بنُ إسماعيلَ الْجُعْفِيُّ مولاهُم (١)، وتلاهُ أبو الحسينِ مُسْلِمُ بنُ الحَجَّاجِ النَّيْسابوريُّ القُشَيْريُّ مِنْ أَنْفُسِهِم (٢)."],[507,"ومسلمٌ معَ أنَّهُ أخذَ عنِ البخاريِّ واستفادَ منهُ يشاركُهُ في أكثرِ (٣) شيوخِهِ. وكتاباهُما أصحُّ الكُتُبِ بعدَ كتابِ اللهِ العزيزِ (٤). وأمَّا ما رُوِّيْناهُ عنِ الشافعيِّ - رضي الله عنه - مِنْ أنَّهُ قالَ: «ما أعلمُ في الأرضِ كتابًا في العلمِ أكثرَ صوابًا مِنْ كتابِ مالكٍ» (٥) ومنهم مَنْ رواهُ بغيرِ هذا اللفظِ (٦)، فإنَّما قالَ ذلكَ قبلَ وجودِ كتابَي البخاريِّ ومسلمٍ.","",{"fn":"قال العراقي في التقييد ٢٥: «اعترض عليه بأن مالكًا صنَّف الصحيح قبله. والجواب: أن مالكًا - رحمه الله - لم يفرد الصحيح، بل أدخل فيه المرسل والمنقطع والبلاغات، ومن بلاغاته أحاديث لا تعرف، كما ذكره ابن عبد البرّ، فلم يفرد الصحيح إذن، والله أعلم». ولمزيد الفائدة انظر: نكت الزركشي ١/ ١٦١، نكت ابن حجر ١/ ٢٧٦ - ٢٨١.\nأي: من بني قشير، لا من مواليهم، كما في حاشية المحاسن: ٨٩.\nفي (أ) و(ع): «كثير من».\nقال الزركشي في نكته ١/ ١٦٣: «قال النووي: باتفاق العلماء فإن قيل: قد روى مسلم في صحيحه عن جماعة من الضعفاء أو المتوسطين: أهل الطبقة الثانية الذين ليسوا من شيوخ الصحيح قال النووي: فجوابه من أوجه ذكرها ابن الصلاح: أحدها: أن ذلك فيمن هو ضعيف عند غيره ثقة عنده، ولا يقال: الجرح مقدم؛ لأن شرط قبوله بيان السبب. الثاني: أن ذِكْرَ الضعفاء في كتابيهما لم يوجد محتجًا به، بل وقع متابعة واستشهادًا كمطر الورَّاق وبقيّة وابن إسحاق وعبد الله بن عمر العمري ونعمان بن راشد وغيرهم. الثالث: أن يكون الضعف طرأ عليهم بعد أخذه عنهم، باختلاط حديث لم يقدح فيما رواه عنهم قبل ذلك، كرواية مسلم عن أحمد بن عبد الرحمان بن وهب بن أخي عبد الله بن وهب، فذكر الحاكم أنه اختلط بعد الخمسين، وما بُيِّن بعد خروج مسلم من مصر. الرابع: أن يقصد علو الإسناد بالرجل الضعيف، والحديث عنده من رواية الثقات نازل فيقتصر على العالي، ولا يطول بإضافة النازل إليه مكتفيًا بمعرفة أهل الشأن ذلك، وهذا العذر قد رويناه عنه تنصيصًا». قلنا: الأمر كما ذكر الزركشي عن النووي؛ ولكن لا بدّ من التنبيه على أن الشيخين ينتقيان من حديث الثقات، وكذا من حديث الضعيف مما علما أنه لم يخطأ فيه. وانظر: ما علقناه على شرح التبصرة والتذكرة ١/ ١٤٤.\nأسنده ابن أبي حاتم في تقدمة الجرح والتعديل ١/ ١٢، والبيهقي في آداب الشافعي: ١٩٥، ... وابن حبان في المجروحين ١/ ٤١، وابن عبد البر في التمهيد ١/ ٧٧.\nانظر عن هذا اللفظ: نكت الزركشي ١/ ١٦٥، ونكت ابن حجر ١/ ٢٨١، وحاشية محققة المحاسن: ٩٠."}],[508,"ثُمَّ إنَّ كتابَ البخاريِّ أصحُّ الكتابَيْنِ صحيحًا وأكثرُهُما فوائدَ (١). وأمَّا ما رُوِّيْناهُ عنْ أبي عليٍّ الحافظِ النَّيْسابوريِّ أستاذِ الحاكمِ أبي عبدِ اللهِ (٢) الحافِظِ مِنْ أنَّهُ قالَ: «ما تحتَ أديمِ السماءِ كتابٌ أصحُّ مِنْ كتابِ مُسلمِ بنِ الحجَّاجِ» (٣) فهذا وقولُ مَنْ فضَّلَ مِن شيوخِ المغربِ كتابَ مسلمٍ على كتابِ البخاريِّ إن كانَ المرادُ بهِ أنَّ كتابَ مسلمٍ يترجَّحُ بأنَّهُ لَمْ يُمَازجْهُ غيرُ الصحيحِ، فإنَّهُ ليسَ فيهِ بعدَ خُطبتِهِ إلاَّ الحديثُ الصحيحُ مسرودًا غيرَ ممزوجٍ بمثلِ ما في كتابِ البخاريِّ في تراجمِ أبوابِهِ مِنَ الأشياءِ التي لَمْ يُسندْها على الوصفِ المشروطِ في الصحيحِ فهذا لا بأسَ بهِ (٤). وليسَ يلزمُ منهُ أنَّ كتابَ مسلمٍ أرجحُ فيما يرجعُ إلى نفسِ الصحيحِ على كتاب البخاريِّ، وإنْ كانَ المرادُ بهِ أنَّ كتابَ مسلمٍ أصحُّ صحيحًا، فهذا مردودٌ على مَنْ يقولُهُ، واللهُ أعلمُ."],[509,"الرابعةُ: لَمْ يَستوعبا الصحيحَ في صحيحَيْهِما ولا التزما ذلكَ (٥)، فقدْ رُوِّيْنا عنِ البخاريِّ أنَّهُ (٦) قالَ: «ما أدخلْتُ في كتابي \" الجامعِ \" إلاَّ ما صحَّ، وتركْتُ مِنَ الصِّحَاحِ لحالِ الطُّولِ» (٧). ورُوِّيْنا عنْ مسلمٍ أنَّهُ قالَ: «ليسَ كُلُّ شيءٍ عندي، صحيحٍ وَضَعْتُهُ هاهُنا - يعني: في كتابِهِ (١) الصحيحِ - إنَّما وضعْتُ هَاهُنا مَا أجْمعُوا عليهِ» (٢). قلتُ: أرادَ - واللهُ أعلمُ - أنَّهُ لَمْ يَضعْ في كتابِهِ إلاَّ الأحاديثَ التي وجدَ عندهُ فيها شرائطَ الصحيحِ الْمُجْمَعِ عليهِ، وإنْ لَمْ يظهرْ اجتماعُها في بعضِها عندَ بعضِهِم (٣).","",{"fn":"انظر في المفاضلة بين الصحيحين: نكت الزركشي ١/ ١٦٥، ونكت ابن حجر ١/ ٢٨١، والبحر الذي زخر ٢/ ٥٣٠.\n«أستاذ الحاكم أبي عبد الله» سقطت من (ب).\nأسنده الخطيب في تاريخ بغداد ١٣/ ١٠١ بمعناه. وللعلماء في توجيه هذا الكلام مباحثات. انظر: صيانة صحيح مسلم: ٦٩، وسير أعلام النبلاء ١٦/ ٥٥، وهدي الساري: ١٢، والنزهة: ٨٦، وتدريب الراوي ١/ ٩٣ - ٩٥.\nقال العراقي في التقييد ٢٦: «قلت: قد روى مسلم بعد الخطبة في كتاب الصلاة بإسناده إلى يحيى بن أبي كثير أنه قال: «لا يستطاع العلم براحة الجسم»، فقد مزجه بغير الأحاديث، ولكنه نادر جدًا بخلاف البخاري، والله أعلم». قلنا انظر: صحيح مسلم ٢/ ١٠٥ ط إستانبول، و١/ ٤٢٨ (١٧٥) ط عبد الباقي.\nانظر: نكت الزركشي ١/ ١٧٢ - ١٧٥.\nفي (م): «أن» تحريف.\nرواه ابن عدي في الكامل ١/ ٢٢٦، وفي أسماء مَن روى عنهم البخاري (٤ أ)، والخطيب في تاريخ بغداد ٢/ ٨ - ٩، والحازمي في شروط الأئمة الخمسة: ٦٢ - ٦٣، وانظر: هدي الساري ١٨."}],[510,"ثُمَّ إنَّ أبا عبدِ اللهِ بنَ الأخرمِ الحافظَ قالَ: «قَلَّمَا يَفُوتُ البخاريَّ ومسلمًا ممَّا يَثْبُتُ مِنْ الحدِيْثِ» (٤) يعني: في كتابَيْهِما. ولِقائلٍ أنْ يقولَ: ليسَ ذلكَ بالقليلِ، فإنَّ"],[511,"\"المستدركَ على الصحيحينِ\" للحاكمِ أبي عبدِ اللهِ كتابٌ كبيرٌ يشتملُ ممَّا فاتهما علىشيءٍ كثير وإنْ يكنْ عليهِ في بعضِهِ مقالٌ، فإنَّهُ يصفو لهُ منهُ صحيحٌ كثيرٌ. وقدْ قالَ البخاريُّ: «أحفظُ مئةَ ألفِ حديثٍ صحيحٍ، ومئتي ألفِ حديثٍ غيرِ صحيحٍ» (٥).","",{"fn":"في (أ): خلال كتابه.\nصحيح مسلم ٢/ ١٥ عقيب (٤٠٤).\nهذا أحد محملين حمل ابن الصلاح كلام مسلم عليهما، والثاني: أنه لم يضع في كتابه ما اختلف فيه الثقات في نفس الحديث متنًا أو إسنادًا. ولم يرد بكلامه هذا ما كان اختلافهم فيه في توثيق بعض رواته وتضعيفهم. ورجَّحَ ابن الصلاح هذا الاحتمال الثاني. انظر: صيانة صحيح مُسْلِم: ٧٤ - ٧٥. ولكن ابن الصلاح استدرك فقال: «ومع هذا فقد اشتمل كتابه على أحاديث اختلفوا في متنها أو إسنادها، وفي ذلك ذهول منه عن هذا الشرط أو سبب آخر، وقد استدركت وعلَّلت». وقد قيل في معناه أقوال أخر، إذ قال القرطبي في مفهمه: «مراده إجماع من لقيه من أهل النقل والعلم بالحديث». انظر: البحر الذي زخر ٢/ ٥٧٠. وقال الميانشي: «يعني -[إجماع]- أئمة الحديث كمالك، والثوري، وشعبة، وأحمد بن حنبل، وابن مهدي وغيرهم». ما لا يسع المحدّث جهله ٢٧. وقال البلقيني في محاسنه ٩١: «وقيل: أراد مسلم بقوله: «ما أجمعوا عليه» أربعة: أحمد بن حنبل، ويحيى بن معين، وعثمان بن أبي شيبة، وسعيد بن منصور الخراساني».\nانظر: نكت الزركشي ١/ ١٧٩ - ١٨٨. فقد أطال النفس بكلام نفيس. وانظر أيضًا: نكت ابن حجر ١/ ٢٩٧.\nأسنده ابن عدي في تقدمة الكامل ١/ ٢٢٦، والخطيب في تاريخه ٢/ ٢٥، والحازمي في شروط الأئمة ٦١، وابن نقطة في التقييد: ٣٣. قال الزركشي ١/ ١٧٨: «وقيل: إنه أراد المبالغة في الكثرة، وهذا ضعيف، بل أراد التحديد، وقد نقل عن غيره من الحفّاظ ما هو أكثر من ذلك، وعلى هذا ففيه وجهان: أحدهما: أنه أراد به تعدد الطرق والأسانيد. والثاني: أن مراده بالأحاديث ما هو أعمّ من المرفوع والموقوف وأقاويل السلف، وعلى هذا حمل البيهقي - في مناقب أحمد - قول أحمد: «صحّ من الحديث سبع مئة ألف»، على أنه أراد أحاديث رسول الله - صلى الله عليه وآله وسلم -، وأقاويل الصحابة والتابعين، فإن قلت: قد قال: ومئتي ألف غير صحيح، فما فائدة حفظه لذلك؟؟ قلت: التمييز بينهما». = =قلنا: وقد يراد الأمران كما أشار إليه المصنف، وتابعه عليه العراقي في شرح التبصرة والتذكرة ١/ ١٣٠، والسيوطي في البحر الذي زخر ٢/ ٧٣٦."}],[512,"وجملةُ ما في كتابِهِ الصحيحِ سبعةُ آلافٍ ومئتانِ وخمسةٌ وسبعونَ حديثًا بالأحاديثِ المكرَّرَةِ. وقدْ قيلَ: إنَّها بإسقاطِ المكرَّرَةِ أربعةُ آلافِ حديثٍ (١)، إلاَّ أنَّ هذهِ العبارةَ قدْ يندرجُ تحتَها عندهم آثارُ الصحابَةِ والتابعينَ، وربَّما عُدَّ الحديثُ الواحدُ المرويُّ بإسنادينِ حديثينِ."],[513,"ثُمَّ إنَّ الزيادةَ في الصحيحِ (٢) على ما في الكتابينِ (٣) يَتلقَّاهَا طالبُهَا ممَّا اشْتَمَلَ عليهِ أحدُ الْمُصَنَّفَاتِ المعتمدةِ المشتهرةِ (٤) لأئمّةِ الحديثِ كأبي داودَ السِّجْسِتانيِّ، وأبي عيسى التِّرمِذيِّ، وأبي عبدِ الرحمانِ النَّسائيِّ (٥) وأبي بكرِ بنِ خُزيمةَ، وأبي الحسنِ الدَّارَقُطنيِّ وغيرِهِم، منصوصًا على صحَّتِهِ فيها. ولا يكفي في ذلكَ مجرَّدُ كونِهِ موجودًا في كتابِ أبي داودَ، وكتابِ الترمذيِّ، وكتابِ النَّسائيِّ، وسائرِ مَنْ جمعَ في كتابِهِ بينَ الصحيحِ وغيرِهِ، ويكفي مجرَّدُ كونِهِ موجودًا في كتبِ مَنِ اشْتَرَطَ منهم الصحيحَ فيما جمَعَهُ ككتابِ ابنِ خُزَيمةَ، وكذلكَ ما يوجدُ في الكُتبِ المخرَّجَةِ على كتابِ البخاريِّ وكتابِ مسلمٍ، ك: كتابِ أبي عَوَانةَ الإسفرايينيِّ، وكتابِ أبي بكرٍ (٦) الإسماعيليِّ (٧)، وكتابِ أبي بكرٍ البَرْقانيِّ، وغيرِها مِنْ تَتِمَّةٍ لمحذوفٍ أو زيادةِ شَرْحٍ في كثيرٍ مِنْ أحاديثِ \"الصحيحينِ\". وكثيرٌ من هذا موجودٌ في \" الجمعِ بينَ الصحيحينِ \" لأبي عبدِ اللهِ الْحُمَيديِّ (١).","",{"fn":"للاطّلاع على إحصائيات المتقدّمين لأحاديث الصحيحين، انظر: نكت الزركشي ١/ ١٨٩، ومحاسن الاصطلاح: ٩٢، والتقييد والإيضاح: ٢٧، وشرح التبصرة والتذكرة ١/ ١٣١، والبحر الذي زخر ٢/ ٧١٩. وقد قام السيد محمد فؤاد عبد الباقي بترقيم أحاديث البخاري \" فتح الباري \" فبلغت (٧٥٦٣) ورقم أحاديث صحيح مسلم فبلغت (٣٠٣٣). وذكر الحافظ العراقي في شرح التبصرة ١/ ١٣١، أن ابن الصلاح لم يذكر عدة أحاديث مسلم قلنا: ولعله اكتفى بما ذكره في كتابه \" صيانة صحيح مسلم \": ١٠١ – ١٠٢، وانظر لزامًا تعليقنا على شرح التبصرة ١/ ١٣١ هامش: (٤).\nفي (م): «الصحيح المروي».\nراجع ما كتبه الزركشي في نكته ١/ ١٩٤، والعراقي في التقييد ٢٧، وابن حجر في نكته ١/ ٢٨٩.\nفي (أ): «المشهورة».\nفي (أ) و(جـ): «النسوي».\nبفتح الباء، وبعضهم يكسره. انظر: الأنساب ١/ ٣٣٦، ومراصد الاطلاع ١/ ١٨٦، والتاج ٢٥/ ٤٠.\n«وكتاب أبي بكر الإسماعيلي»، ساقطة من (ب)."}],[514,"واعتنى الحاكمُ أبو عبدِ اللهِ الحافظُ بالزيادةِ في عددِ الحديثِ الصحيحِ على ما في الصحيحينِ، وجَمَعَ ذلكَ في كتابٍ سمَّاهُ \" المستدركَ \" أودَعَهُ ما ليسَ في واحدٍ مِنَ"],[515,"\" الصحيحينِ \" ممَّا رآهُ على شرطِ الشيخينِ قدْ أخرجا عنْ رواتِهِ في كتابَيْهِما، أو على شرطِ البخاريِّ وَحْدَهُ، أو على شرطِ مسلمٍ وحدَهُ، وما أدَّى اجتهادُهُ إلى تصحيحهِ وإنْ لَمْ يكُنْ على شرطِ واحدٍ منهما (٢).","",{"fn":"قال العراقي في التقييد ٢٨: «وهو يقتضي أن ما وجد من الزيادات على الصحيحين في كتاب الحميدي: يحكم بصحته، وليس كذلك؛ لأن المستخرجات المذكورة قد رووها بأسانيدهم الصحيحة، فكانت الزيادات التي تقع فيها صحيحة لوجودها بإسناد صحيح في كتاب مشهور على رأي المصنِّف. وأما الذي زاده الحميدي في \" الجمع بين الصحيحين \" فإنه لم يروه بإسناده حتى ينظر فيه، ولا أظهر لنا اصطلاحًا أنه يزيد فيه زوائد التزم فيها الصحة ... فيقلد فيها. وإنما جمع بين كتابين، وليست تلك الزيادات في واحد من الكتابين، فهي غير مقبولة حتى توجد في غيره بإسناد صحيح، والله أعلم. وقد نصَّ المصنِّف بعد هذا في الفائدة الخامسة التي تلي هذه أن مَن نقل شيئًا من زيادات الحميدي عن الصحيحين أو أحدهما فهو مخطئ، وهو كما ذكر فمن أنزله (كذا) أن تلك الزيادات محكوم بصحتها بلا مستند، فالصواب ما ذكرناه، والله أعلم». قلنا: قد تعقّب العراقيَّ تلميذُهُ ابنُ حجر في كلامِهِ هذا ببحث نفيس طويل فانظره في نكته ١/ ٣٠٠ - ٣١٠، وانظر: تعليقنا على شرح التبصرة والتذكرة ١/ ١٤٠.\nقال الزركشي في نكته ١/ ١٩٧: «فيه أمران: أحدهما: نوزع في قوله: «أودعه ما ليس في واحد منهما»، فإنَّهُ قد أودعه أحاديث في الصحيحين، وهذا عجيب، فإن هذه الأحاديث وقعت له سهوًا، على خلاف شرطه، ولم يكن موضوع الكتاب لذلك، ولا هو مقصوده؛ إذ لا يكون ذلك استدراكًا حينئذٍ. فكلام المصنف صحيح. الثاني: ما ذكره في شرطه، قد تبعه عليه النووي وابن دقيق العيد وغيرهما، وكأنهم لم يقفوا على شرط الحاكم، والذي في خطبة المستدرك ما نصه: «وأنا أستعين الله على إخراج أحاديث رواتها ثقات قد احتج بمثلها الشيخان أو أحدهما» انتهى. وقال النووي: «المراد بقولهم: «على شرطهما»: أن يكون رجال إسناده في كتابيهما؛ لأنه ليس لهما شرط في كتابيهما ولا في غيرهما». وعلى هذا عمل الشيخ تقي الدين ابن دقيق العيد؛ فإنَّه ينقل عن الحاكم تصحيحه لحديث على شرط البخاري - مثلًا - ثم يعترض عليه بأن فيه فلانًا ولم يخرج له البخاري، وكذلك فعل الحافظ الذهبي في مختصر المستدرك، وليس ذلك منهم بحسن، لما ذكرنا من كلام الحاكم في خطبته أنه لم يشترط نفس الرجال المخرج لهم في الصحيح، بل اشترط رواة احتج بمثلهم الشيخان أو أحدهما، وإنما ينبغي منازعته في تحقيق المماثلة بين رجاله ورجال الصحيحين. ="}],[516,"وهوَ واسعُ الخَطْوِ في شرطِ الصحيحِ، متساهِلٌ في القضاءِ بهِ (١). فالأَوْلَى أنْ نتوسَّطَ (٢) في أمرِهِ فنقولَ: مَا حَكَمَ بصِحَّتِهِ وَلَمْ نَجِدْ (٣) ذلكَ فيهِ لغيرِهِ مِنَ الأئمَّةِ، إنْ لَمْ يكُنْ مِنْ قَبِيْلِ الصحيحِ فَهوَ مِنْ قَبيلِ الحسنِ يُحتجُّ بهِ ويُعْملُ بهِ، إلاَّ أنْ تظهرَ فيهِ عِلَّةٌ تُوجِبُ ضَعْفَهُ (٤) ويُقَاربُهُ في حُكْمِهِ \" صحيحُ أبي حاتِمِ بنِ حِبَّانَ البُسْتِيِّ \" (٥) -رحمهم الله أجمعينَ- واللهُ أعلمُ.","",{"fn":"قال الذهبي في سير أعلام النبلاء ١٧/ ١٧٥: «في المستدرك شيء كثير على شرطهما، وشيء كثير على شرط أحدهما، ولعل مجموع ذلك ثلث الكتاب بل أقل، فإن في كثير من ذلك أحاديث في الظاهر على شرط أحدهما أو كليهما، وفي الباطن لها علل خفية مؤثرة، وقطعة من الكتاب إسنادها صالح وحسن وجيد، وذلك نحو ربعه، وباقي الكتاب مناكير وعجائب، وفي غضون ذلك أحاديث نحو المئة يشهد القلب ببطلانها». وقد قسم ابن حجر في نكته ١/ ٣١٤ - ٣١٩: المستدرك إلى أقسام فانظرها فإنها مفيدة.\nفي (ب): يتوسط.\nفي (ج): «يجد».\nقال ابن جماعة: «الحق أن يتتبع ويحكم عليه بما يليق بحاله من الحسن أو الصحة أو الضعف». قال العراقي في نكته ٣٠: «وهذا هو الصواب». وانظر: نكت الزركشي ١/ ٢٢٦، والبحر الذي زخر ٢/ ٨٤٥ - ٨٤٦.\nقال الزركشي في نكته ١/ ٢٢٦: «أي: يقاربه فيما ذكر، وليس كما قال، بل صحيح ابن حبان أصح منه بكثير». وانظر: التقييد والإيضاح ٣٠ - ٣١، وشرح التبصرة والتذكرة ١/ ١٣٥."}],[517,"الخامِسَةُ: الكتبُ الْمُخَرَّجَةُ (١) على كتابِ البخاريِّ أو كتابِ مسلمٍ -رضي الله عنهما- لَمْ يلتزمْ مصنِّفُوها فيها موافقَتَهما في ألفاظِ الأحاديثِ بعينِها مِنْ غيرِ زيادةٍ ونقصانٍ؛ لكونِهِم رَوَوْا تلكَ الأحاديثَ مِنْ غيرِ جهةِ البخاريِّ ومسلمٍ طَلَبًا لِعُلُوِّ الإسنادِ، فحصلَ فيها بعضُ التفاوُتِ في الألفاظِ. وهكذا ما أخرجَهُ المؤلِّفُونَ في تصانيفِهِم المستَقِلَّة ك\" السُّنَنِ الكَبِير \" للبَيْهقيِّ، و\" شرحِ السُّنَّةِ \" لأبي محمدٍ البَغَوِيِّ، وغيرِهِما ممَّا (٢) قالوا فيهِ: «أخرجهُ البخاريُّ أو مسلمٌ»، فلا يُسْتَفَادُ (٣) بذلكَ أكثرَ من أنَّ البخاريَّ أو مسلمًا أخرجَ أصلَ ذلكَ الحديثِ، مَعَ احتِمالِ أنْ يكونَ بينهما تفاوُتٌ في اللَّفظِ، وربَّما كان تفاوتًا في بعضِ المعنى، فقدْ وجدْتُ في ذلكَ ما فيهِ بعضُ التَّفاوتِ مِنْ حيثُ المعنى. وإذا كانَ الأمرُ في ذلكَ على هذا فليسَ لكَ أنْ تنقُلَ حديثًا منها وتقولَ: هو على هذا الوجهِ في كتابِ البخاريِّ، أو كتابِ مسلمٍ، إلاَّ أنْ تُقَابِلَ لفظَهُ، أو يكونَ الذي خرَّجهُ قد قالَ: أخرجهُ البخاريُّ بهذا اللَّفظِ (٤). بخلافِ الكُتبِ المختصَرَةِ منَ الصحيحينِ، فإنَّ مصنِّفِيها نقلُوا فيها ألفاظَ الصحيحينِ أو أحدهما (٥)، غيرَ أنَّ \" الجمعَ بينَ الصحيحينِ \"","",{"fn":"«وحقيقته: أن يأتي المصنِّف إلى كتاب البخاري أو مسلم فيخرج أحاديثه بأسانيد لنفسه من غير طريق البخاري أو مسلم، فيجتمع إسناد المصنف مع إسناد البخاري أو مسلم في شيخه أو من فوقه». أفاده الزركشي في نكته ١/ ٢٢٩.\nفي (ج): «ما».\nفي (أ) و(ج): «فلا تستفيد»، وفي (ب): فلا يستفيد»، وما أثبتناه من (ع) و(م) والتقييد.\nقال ابن حجر في نكته ١/ ٣١٠: «قلت: محصل هذا أن مُخَرِّج الحديث إذا نسبه إلى تخريج بعض المصنفين، فلا يخلو: إما أن يصرّح بالمرادفة أو بالمساواة أو لا يصرّح. إن صرّح فذاك، وإن لَم يصرّح كان على الاحتمال. فإذا كان على الاحتمال فليس لأحد أن ينقل الحديث منها ويقول: هو على هذا الوجه فيهما، لكن هل له أن ينقل منه ويطلق كما أطلق؟ هذا محل بحث وتأمل».\nقال ابن حجر في نكته ١/ ٣١٢: «محصله أن اللفظ إن كان متفقًا فذاك وإن كان مختلفًا فتارة يحكيه على وجهه، وتارة يقتصر على لفظ أحدهما، ويبقى ما إذا كان كل منهما أخرج من الحديث جملة لم يخرجها الآخر، فهل للمختصر أن يسوق الحديث مساقًا واحدًا وينسبه إليهما ويطلق ذلك، أو عليه أن يبيّن؟ هذا محل تأمّل، ولا يخفى الجواز، وقد فعله غير واحد، والله أعلم»."}],[518,"لِلحُمَيديِّ الأندلسيِّ منها يشتملُ على زيادةِ تتمَّاتٍ لبعضِ الأحاديثِ كما قدَّمنا ذكرَهُ (١)، فربَّما نَقَلَ مَنْ لا يُمَيِّزُ بعضَ ما يجدهُ فيهِ عنِ الصحيحينِ أو أحدِهما، وهو مخطِئٌ؛ لكونِهِ مِنْ تلكَ الزياداتِ (٢) التي لا وجودَ لها في واحدٍ (٣) مِنَ الصحيحينِ. ثُمَّ إنَّ التخاريجَ المذكورةَ على الكتابينِ يُستفادُ منها فائدتانِ (٤):"],[519,"إحداهُما: عُلُوُّ الإسنادِ."],[520,"والثانيةُ: الزيادةُ في قدْرِ الصحيحِ لما يقعُ فيها مِنْ ألفاظٍ زائدةٍ وتَتِمَّاتٍ في بعضِ الأحاديثِ تُثْبِتُ (٥) صِحَّتَها بهذهِ التخاريجِ؛ لأنَّها واردةٌ بالأسانيدِ الثابتةِ في الصحيحينِ أو أحدِهِما وخارجةٌ مِنْ ذلكَ المَخْرَجِ الثابتِ، واللهُ أعلمُ."],[521,"السادسةُ: ما أسنَدَهُ البخاريُّ ومسلمٌ – رحمهما اللهُ – في كتابَيْهِمَا بالإسنادِ المتَّصِلِ فذلكَ الذي حَكما بصحَّتِهِ بلا إشكالٍ. وأمَّا [المعلَّقُ وهو] (٦) الذي حُذِفَ مِنْ مبتدإِ إسنادِهِ واحدٌ أو أكثرُ، وأغلبُ ما وقَعَ ذلكَ في كتابِ البخاريِّ (٧) وهو في كتابِ مسلمٍ قليلٌ جدًّا (١) ففي بعضِهِ نَظَرٌ. وينبغي أنْ نقولَ: ما كانَ مِنْ ذلكَ ونحوِهِ بلفظٍ فيهِ جَزْمٌ وحُكْمٌ بهِ على مَنْ عَلَّقَهُ عَنْهُ، فقدْ حَكَمَ بصِحَّتِهِ عَنْهُ (٢)، مثالُهُ: قالَ رسولُ اللهِ - صلى الله عليه وآله وسلم - كَذا وكذا، قالَ ابنُ عبَّاسٍ: كذا، قالَ مجاهدٌ: كذا، قالَ عَفَّانُ: كذا، قالَ القَعْنَبِيُّ: كذا (٣)، روى أبو هريرةَ: كذا وكذا، وما أشبهَ ذلكَ مِنَ العباراتِ. فكلُّ ذلكَ حُكْمٌ مِنْهُ على مَنْ ذَكرَهُ عنهُ بأنَّهُ (١) قدْ قالَ ذلكَ ورَوَاهُ؛ فلنْ يَسْتَجِيْزَ إطلاقَ ذلكَ إلاَّ إذا صحَّ عِندَهُ ذلكَ عنهُ، ثمَّ إذا كانَ الذي علَّقَ الحديثَ عنهُ دُوْنَ الصحابةِ فالحُكْمُ بصِحَّتِهِ يتوقَّفُ على اتِّصَالِ الإسنادِ بينَهُ وبينَ الصحابيِّ.","",{"fn":"قال الزركشي ١/ ٢٣٠ – ٢٣١: «ومن هاهنا اعترض عليه – [يعني: الحميدي] – في إدخاله تلك الزيادات في الكتاب، فإنَّه لم يذكرْها بإسناد لتتميز عن إيراد الصحيحين، وذكرها في ذيل الحديث موهمًا أنها في الصحيح، فليحذر من ذلك. وهذا بخلاف \" الجمع بين الصحيحين \" لعبد الحق ونحوه، فإنه لا يأتي بغير لفظ الصحيح. وظاهر كلام ابن الصلاح أن الزيادات الواقعة في كتاب الحميدي لها حكم الصحيح، وليس كذلك؛ لأنه لم يروها بسند كالمستخرج، ولا ذكر أنه يزيد ألفاظًا ويشترط فيها الصحة حتى يقلد في ذلك».\nفي (جـ): «الزيادة».\nفي (أ): «أحد».\nانظر عن فوائد المستخرجات: نكت الزركشي ١/ ٢٣١، والتقييد والإيضاح ٣٢، وشرح التبصرة والتذكرة ١/ ١٣٧ – ١٣٨، ونكت ابن حجر ١/ ٣٢١.\nفي (ب): «ثبتت».\nما بين المعكوفتين من (ع) و(م) والتقييد. وراجع في تفصيل أحكام التعاليق في الصحيحين: نكت الزركشي ١/ ٢٣٢، والتقييد والإيضاح: ٣٢، وشرح التبصرة والتذكرة ١/ ١٥٦، ونكت ابن حجر ١/ ٣٢٤.\nقال ابن حجر في هدي الساري ٤٦٩: «فجملة ما في الكتاب من التعاليق ألف وثلاث مئة وواحد وأربعون حديثًا وأكثرها مكرّر، مُخَرَّجٌ في الكتاب أصول متونه، وليس فيه من المتون التي لم تخرج في الكتاب ولو من طريق أخرى إلا مئة وستون حديثًا». قلنا: وله كتاب فريد في بابه في وصل التعاليق التي في صحيح البخاري: تغليق التعليق، طبع بتحقيق: د. سعيد عبد الرحمن موسى القزقي، ولخّصه الحافظ نفسه في هدي الساري ١٧–٧٠.\nبلغ ثلاثة مواضع فقط، وصل اثنان منها في صحيحه، ثمَّ لَمَّا احتاج تكرارها علَّقها فلم يبقَ فيه غير حديث واحد معلّق غير موصول، وهو حديث أبي الجهيم بن الحارث «أقبل رسول الله - صلى الله عليه وآله وسلم - من نحو بئر جمل ... الحديث»، حيث علَّقه مسلم بلفظ: «وروى الليث بن سعد، عن جعفر بن ربيعة، عن عبد الرحمن بن هرمز، عن عمير مولى ابن عباس أنه سمعه يقول: أقبلت أنا وعبد الرحمن بن يسار-مولى ميمونة زوج النبي - صلى الله عليه وآله وسلم - حتَّى دخلنا على أبي الجهيم فقال: ... الحديث» صحيح مسلم ١/ ١٩٤ (٣٦٩). وهذا الحديث وصله أحمد ٤/ ١٦٩ من طريق أخرى، وهي طريق الحسن بن موسى، عن ابن لهيعة، عن الأعرج. ومن طريق الليث وصله: البخاري ١/ ٩٢ (٣٣٧)، وأبو داود (٣٢٩)، والنسائي ١/ ١٦٥، وفي الكبرى (٣٠٧)، وابن خزيمة (٢٧٤)، وأبو عوانة ١/ ٣٠٧. تنبيه: جميع من وصل الحديث ذكر: عبد الله بن يسار، وانفرد مسلم بقوله: عبد الرحمان بن يسار. وانظر: التقييد والإيضاح: ٣٢ - ٣٣، ونكت ابن حجر ١/ ٣٤٤ - ٣٥٣، وشرح السيوطي على ألفية العراقي: ١١٨.\nقال الزركشي في نكته ١/ ٢٣٦: «وهذا الذي ذكره من أن صيغة الجزم تدل على صحة الحديث، والتمريض على ضعفه، قد تبعه عليه أكثر الناس، وقد اعترض عليه من جهتين: من جهة الصناعة، ومن جهة الاستقراء. فإن كان هذا قاله من جهة الصناعة فلا شكَّ أن قول البخاري - مثلًا -: «قال» بصيغة الجزم ليس ما يرى من قول التابعي الكبير: قال رسول الله - صلى الله عليه وآله وسلم - بلفظ الجزم، وهو لا يقتضي صحة الحديث، فبذلك ترى البخاري إذا علَّق الحديث لم يفد الصحة». ثمَّ قال: «وأما الاستقراء فلا يساعده، فقد قال البخاري في كتاب العلم في باب الخروج في طلب العلم: رحل جابر بن عبد الله مسيرة شهر إلى عبد الله بن أنيس في حديث واحد. انتهى. هكذا جزم به، ثم ذكره بصيغة التمريض في آخر الكتاب في الرد على الجهمية، فقال: «ويذكر عن جابر بن عبد الله، عن عبد الله بن أنيس سمعت النبي - صلى الله عليه وآله وسلم - يقول: ... فذكره. فدلّ على استواء الصيغتين عنده، وإلاّ يلزم أن يكون الحديث الواحد ضعيفًا حسنًا»، وقد ردَّ ابن حجر في الفتح ١/ ١٧٤ على قول الزركشي هذا فانظره، وتأمل!! وانظر: تعليقنا على شرح التبصرة والتذكرة ١/ ١٦٣ - ١٦٥.\nقال العراقي في التقييد والإيضاح: ٣٣: «أن قوله - في أمثلة ما حذف من مبتدأ إسناده واحد فأكثر -: قال عفان: كذا، قال القعنبي: كذا، ليس بصحيح، ولم يسقط من هذا الإسناد شيء، فإن عفان والقعنبي كلاهما من شيوخ البخاري الذين سمع منهم، فما روى عنهما -ولو بصيغة لا تقضي التصريح= =بالسماع - فهو محمول على الاتصال، وقد ذكره ابن الصلاح كذلك على الصواب في النوع الحادي عشر من كتابه في الرابع من التفريعات التي ذكرها فيه ...» إلى آخر كلامه."}],[522,"وأمَّا ما لَمْ يَكُنْ في لفظِهِ جَزْمٌ وحُكْمٌ، مثلُ: رُويَ عنْ رسولِ اللهِ - صلى الله عليه وآله وسلم -: كذا وكذا، أو رُويَ (٢) عنْ فلانٍ: كذا وكذا (٣) أو في البابِ عنِ النبيِّ - صلى الله عليه وآله وسلم -: كذا وكذا، فهذا وما أشْبَهَهُ مِنَ الألفاظِ ليسَ في شيءٍ منهُ (٤) حُكْمٌ منهُ (٥) بصحَّةِ ذلكَ عمَّنْ ذكَرَهُ عنهُ؛ لأنَّ مثلَ هذهِ العباراتِ تُستَعملُ في الحديثِ الضعيفِ أيضًا، ومعَ ذلكَ فإيرادُهُ لهُ في أثناءِ الصحيحِ مُشْعِرٌ بصِحَّةِ أصْلِهِ إشعارًا يُؤْنَسُ بهِ ويُرْكَنُ إليهِ، واللهُ أعلمُ."],[523,"ثُمَّ إنَّ ما يتقاعدُ مِنْ ذلكَ عنْ شَرطِ الصحيحِ قليلٌ (٦)، يوجَدُ في كتابِ البخاريِّ في مواضعَ مِنْ تراجمِ الأبوابِ دونَ مقاصِدِ الكتابِ وموضوعِهِ الذي يُشْعِرُ بهِ اسمُهُ الذي سمَّاهُ بهِ، وهوَ \" الجامعُ المُسْنَدُ الصحيحُ المختصرُ مِنْ أُمورِ رسولِ اللهِ - صلى الله عليه وآله وسلم - وسُنَنِهِ وأيَّامِهِ \". وإلى الخصوصِ الذي بيَّناهُ يرجعُ مطلقُ قولِهِ: «ما أدخلْتُ في كتابِ الجامعِ إلاَّ ما صحَّ». وكذلكَ مُطْلَقُ قولِ الحافظِ أبي نَصْرٍ الوايليِّ السِّجْزِيِّ (٧): «أجمعَ أهلُ العِلْمِ - الفقهاءُ (٨)","",{"fn":"في (جـ): «كأن».\nفي (ب): «وروي».\n«كذا» الثانية من (ب) و(جـ) و(ع) فقط.\n«منه» سقطت من (ب).\nكذلك.\nقال ابن حجر في نكته ١/ ٣٢٤: «أقول: بل الذي يتقاعد عن شرط البخاري كثير ليس بالقليل إلا أن يريد بالقلة قلة نسبية إلى باقي ما في الكتاب فيتجه، بل جزم أبو الحسن بن القطان بأن التعاليق التي لم يوصل البخاري إسنادها ليست على شرطه ...» إلى آخر كلامه فانظره فإنه بحث ممتع.\nالسِّجْزِي - بكسر السين وسكون الجيم -: نسبة إلى سِجِستان على غير قياس. انظر: الأنساب ٣/ ٢٤٦، وانظر: التعليق في: ٤٨٩ من هذا الكتاب.\nفي (جـ): «والفقهاء»."}],[524,"وغيرُهُم (١) – أنَّ رَجُلًا لَو حَلَفَ بالطَّلاَقِ أنَّ جميعَ ما في كتابِ البخاريِّ ممَّا رُويَ عنِ النبيِّ - صلى الله عليه وآله وسلم - قدْ صحَّ عنهُ، ورسولُ اللهِ - صلى الله عليه وآله وسلم - قالَهُ (٢) لا شَكَّ فيهِ أنَّهُ لا يَحْنَثُ (٣)، والمرأةُ بحالِها في حِبَالتِهِ (٤» (٥)."],[525,"وكذلكَ ما ذكرَهُ أبو عبدِ اللهِ الْحُمَيديُّ في كتابِهِ \" الجمعِ بينَ الصحيحينِ \" من قولِهِ: «لَمْ نجدْ مِنَ الأئمَّةِ الماضينَ – رضي الله عنهم أجمعينَ – مَنْ أفصَحَ لنا في جميعِ ما جمَعَهُ بالصِّحَّةِ إلاَّ هذينِ الإمامَيْنِ» (٦). فإنَّما المرادُ بكلِّ ذلكَ مقاصدُ الكتابِ وموضوعُهُ ومتونُ الأبوابِ، دونَ التراجمِ ونحوُهَا؛ لأنَّ في بعضِها مَا ليسَ مِنْ ذلكَ قطعًا، مثلُ: قولِ البخاريِّ: «بابُ مَا يُذكَرُ في الفَخِذِ، ويُروى عنِ ابنِ عبَّاسٍ، وجَرْهَدٍ (٧)، ومحمدِ بنِ جَحْشٍ، عنِ النبيِّ - صلى الله عليه وآله وسلم -: الفَخِذُ عوْرَةٌ» (٨)، وقولُهُ في أوَّلِ بابٍ من أبوابِ الغُسْلِ: «وقالَ بَهْزُ [بنُ حَكِيْمٍ] (١)، عنْ أبيهِ، عنْ جَدِّهِ، عنِ النبيِّ - صلى الله عليه وآله وسلم - اللهُ أحقُّ أنْ يُسْتَحيى منهُ» (٢). فهذا قطعًا ليسَ مِنْ شرطِهِ؛ ولذلكَ (٣) لَمْ يورِدْهُ الحُمَيديُّ في \" جمعهِ بينَ الصحيحينِ \"، فاعلمْ ذلكَ فإنَّهُ مهمٌّ خافٍ، واللهُ أعلمُ (٤).","",{"fn":"بعد هذا في (ع) زيادة: «على».\nفي (ب): «قد قاله».\nالحِنْث: الخُلْفُ في اليمين، حَنِثَ في يمينِهِ حِنْثًا وحَنَثًا: لَمْ يبرَّ فيها. لسان العرب ٢/ ١٥١.\nالحِبالة – بالكسر –: هي ما يصاد بها من أي شيء كانت، والجمع: حبائل، ومنه: ما روي: «النساء حبائل الشيطان» أي: مصايده، والمراد هنا: في عصمته. انظر: النهاية ١/ ٣٣٣ واللسان ١١/ ١٣٦.\nانظر: نكت الزركشي ١/ ٢٤٩، والتقييد والإيضاح: ٣٨.\nانظر: الجمع بين الصحيحين ٣ أ.\nبفتح الجيم وسكون الراء وفتح الهاء. انظر: فتح الباري ١/ ٤٧٨.\nصحيح البخاري ١/ ١٠٣ عقيب (٣٧٠). وحديث ابن عباس: أخرجه أحمد ١/ ٢٧٥، والترمذي (٢٧٩٦)، والطحاوي في شرح المعاني ١/ ٤٧٤، والبيهقي ٢/ ٢٢٨. من طريق أبي يحيى، عن مجاهد، عن ابن عباس، مرفوعًا. وسنده ضعيف؛ لضعف أبي يحيى القتات. ليَّنه الحافظ في التقريب (٨٤٤٤). وحديث جرهد: أخرجه عبد الرزاق (١١١٥) و(١٩٨٨)، والحميدي (٨٥٧)، وابن أبي شيبة (٢٦٦٩٢)، وأحمد ٣/ ٤٧٨ و٤٧٩، والدارمي (٢٦٥٠)، والبخاري في تاريخه الكبير ٥/ (١٥٤)، وأبو داود (٤٠١٤)، والترمذي (٢٧٩٥)، والطحاوي في شرح المشكل (١٧٠١) و(١٧٠٢)، وفي شرح المعاني ١/ ٤٧٥، وابن حبان (١٧١٠) والطبراني في الكبير (٢١٣٨) – (٢١٥١)، والدارقطني ١/ ٢٢٤، والبيهقي ٢/ ٢٢٨. وحديثه مضطرب جدًا. قال ابن عبد البر في الاستيعاب ١/ ٢٥٥ متحدّثًا عن جرهد: «لا تكاد تثبت له صحبة روى عن النبي - صلى الله عليه وآله وسلم -: «الفخذ عورة»، وقد رواه غيره جماعة، وحديثه ذلك مضطرب». = =وانظر فيه: بيان الوهم والإيهام ٣/ ٣٣٨ (١٠٨٢) و(١٠٨٣) فقد أطال النفس فيه، ونصب الراية ١/ ٢٤١ – ٢٤٢، وأثر علل الحديث ٢٤٣ – ٢٤٦. وحديث محمد بن جحش: أخرجه أحمد ٥/ ٢٨٩ – ٢٩٠، وعبد بن حميد (٣٦٧)، والنسائي ٧/ ٣١٤، والحاكم ٤/ ١٨٠، والبغوي (٢٢٥١). قال الزيلعي في نصب الراية ٤/ ٢٤٥ عن إسناد أحمد: «هذا مسند صالح». قلنا: وكذلك ورد من حديث عمرو بن شعيب، عن أبيه، عن جده، مرفوعًا. بلفظ: «إذا أنكح أحدكم عبده أو أجيره، فلا ينظر إلى شيء من عورته؛ فإنَّما أسفل من سرته إلى ركبتيه من عورته». أخرجه أحمد ٢/ ١٨٧، وأبو داود (٤٩٦)، والبيهقي ٢/ ٢٢٨ – ٢٢٩، وسنده قوي."}],[526,"السابعةُ: وإذا انتهى الأمرُ في مَعْرِفَةِ الصحيحِ إلى ما خرَّجَهُ الأئمَّةُ في تصانيفِهِم الكافلةِ ببيانِ ذلكَ كما سبقَ ذِكرُهُ، فالحاجَةُ ماسَّةٌ إلى التنبيه على أقسامِهِ باعتبارِ ذلكَ (٥):"],[527,"فأوَّلُها: صحيحٌ أخرجَهُ البخاريُّ ومسلمٌ جميعًا."],[528,"الثاني: صحيحٌ انفَرَدَ بهِ البخاريُّ، أيْ: عنْ مسلمٍ."],[529,"الثالثُ: صحيحٌ انفَرَدَ بهِ مسلمٌ، أيْ: عنِ البخاريِّ."],[530,"الرابعُ: صحيحٌ على شرطِهِما لَمْ يُخَرِّجاهُ."],[531,"الخامسُ: صحيحٌ على شرطِ البخاريِّ لَمْ يخرِّجْهُ.","",{"fn":"لَم ترد في النسخ الخطية ولا في متن البخاري المطبوع، وهي من (ع) و(م) والتقييد ونكت الزركشي.\nصحيح البخاري ١/ ٧٨ عقيب (٢٧٧). وقد وصله عبد الرزاق (١١٠٦)، وأحمد ٥/ ٣ و٤، وأبو دواد (٤٠١٧)، وابن ماجه (١٩٢٠)، والترمذي (٢٧٦٩) و(٢٧٩٤)، والنسائي في الكبرى (٨٩٧٢)، والحاكم ٤/ ١٧٩، وأبو نعيم ٧/ ١٢١، والبيهقي ١/ ١٩٩، والخطيب في تاريخه ٣/ ٢٦١. وقال اللكنوي في ظفر الأماني ١٦٤: «هو حديث حسن مشهور».\nفي (ب): «وكذلك».\nراجع نكت الزركشي: ١/ ٢٥٢ – ٢٥٤.\nتعقَّب بعضُ العلماء ابنَ الصلاح حول هذا التقسيم، ودارت بينهم مناقشات، انظرها في: نكت الزركشي ١/ ٢٥٤، وشرح التبصرة والتذكرة ١/ ١٤٢ مع تعليقنا، ونكت ابن حجر ١/ ٣٦٣، وتوجيه النظر ١/ ٢٩٠ مع تعليقات محققه."}],[532,"السادسُ: صحيحٌ على شرطِ مسلمٍ لَمْ يُخَرِّجْهُ."],[533,"السابعُ: صحيحٌ عندَ غيرِهما، وليسَ على شرطِ واحدٍ منهما."],[534,"هذهِ أمَّهاتُ أقسامِهِ وأعلاهَا: الأوَّلُ وهو الذي يقولُ فيهِ أهلُ الحديثِ كثيرًا: «صحيحٌ متَّفَقٌ عليهِ» يُطْلِقُونَ ذلكَ ويَعْنونَ بهِ اتِّفاقَ البخاريِّ ومسلمٍ، لا اتِّفاقَ الأمَّةِ (١) عليهِ، لكنَّ اتِّفَاقَ الأمَّةِ عليهِ لازمٌ منْ ذلكَ، وحاصِلٌ معهُ؛ لاتِّفاقِ (٢) الأمَّةِ على تلقِّي ما اتَّفَقا عليهِ بالقبولِ."],[535,"وهذا القسمُ جميعُهُ مقطوعٌ بصِحَّتِهِ، والعِلْمُ اليقينيُّ النَّظريُّ واقعٌ بهِ، خلافًا لقولِ مَنْ نَفَى ذلكَ، مُحْتَجًّا بأنَّهُ لا يُفيدُ في أصلِهِ إلاَّ الظَّنَّ (٣)، وإنَّما تلقَّتْهُ الأمَّةُ (٤) بالقبولِ؛ لأنَّهُ يجبُ عليهمُ العملُ بالظَّنِّ، والظَّنُّ قَدْ يُخْطِئُ. وقدْ كنتُ أميلُ إلى هذا، وأحسبُهُ قويًّا ثُمَّ بانَ لي أنَّ المذهبَ الذي اخْتَرْناهُ أوَّلًا هوَ الصحيحُ؛ لأنَّ ظَنَّ مَنْ هوَ معصومٌ مِنَ الخطأِ لا يُخْطِئُ، والأمَّةُ في إجماعِها مَعْصومةٌ مِنَ الخطأِ، ولهذا كانَ الإجماعُ الْمُبْتَنَى (٥) على الاجتهادِ حُجَّةً مقطوعًا بها، وأكثرُ إجماعاتِ العلماءِ كذلكَ."],[536,"وهذهِ نكتَةٌ نفيسةٌ نافعةٌ، ومِنْ فوائدِها: القولُ بأنَّ ما انفردَ بهِ البخاريُّ أو مسلمٌ مندرجٌ في قبيلِ ما يُقْطَعُ بصِحَّتِهِ؛ لتَلَقِّي الأمَّةِ كلَّ واحدٍ من كتابَيْهما بالقبولِ على الوجهِ الذي فصَّلناهُ مِنْ حالِهِما فيما سبقَ، سوى أحرفٍ يسيرةٍ (٦) تكلَّمَ عليها بعضُ أهلِ النَّقْدِ مِنَ الحفَّاظِ كالدَّارقطنيِّ وغيرِهِ، وهي معروفةٌ عِندَ أهلِ هذا الشأْنِ، واللهُ أعلمُ.","",{"fn":"في (أ) و(ب): «الأئمَّة».\nفي (م): «باتفاق».\nينظر عن مسألة إفادة أحاديث الصحيحينِ لليقين أو الظنِّ: نكت الزركشي ١/ ٢٧٦، ومحاسن الاصطلاح: ١٠١، ونكت ابن حجر ١/ ٣٧١، والبحر الذي زخر ١/ ٣٣٥، وتوجيه النظر: ٣٠٧.\nفي (جـ): «الأئمة».\nفي (م): «المبني».\nهي ليست باليسيرة، فقد بلغت انتقادات الدارقطني وحده (٢١٨)، وهذا فيما سوى ما انتقده أبو مسعود الدمشقي، وأبو الفضل بن عمار، وأبو علي الجياني. = =ولربما أراد ابن الصلاح أنها يسيرة نسبيًا إلى ما لا انتقاد عليه. والحقيقة أن هذهِ الانتقادات تتفرع عن الأقسام الآتية: أ- الزيادة التي تقع في بعض الأحاديث. إذ قد ينفرد ثقة بزيادة لا يذكرها من هو مثله أو أحفظ منه، فتحميل هذا الثقة تبعه أنه قد يكون غلط؛ ظن مجرد، وغاية ما فيها أنها زيادة ثقة لا تنافي رواية الأحفظ والأكثر. ب- الحديث الذي قد يرويه تابعي، المشهور أن روايته عن صحابي معين سمع منه، فيروي الحديث بواسطة عن ذلك الصحابي، فيعلل الأول بزيادة الراوي في الطريق الثانية. وهذا مندفع بأنه لا مانع من كون ذلك التابعي قد سمع ذلك الحديث بعينه من ذلك الصحابي مباشرة ثم سمعه بواسطة وهكذا يكون الأمر فيمن بعدهم. جأن يشير صاحب الصحيح إلى علته، كأن يرويه مسندًا ثم يذكر أنه روي مرسلًا، فهذا من صاحب الصحيح ترجيح لرواية الواصل على المرسل. د- ما يكون مدارًا للاجتهاد وتكون علته مرجوحة بالنسبة إلى صحته. وانظر: نكت الزركشي ١/ ٢٨٧، والتقييد والإيضاح: ٤٢، وابن حجر ١/ ٣٨٠."}],[537,"الثامنةُ: إذا ظهرَ بما قدَّمناهُ انحصارُ طريقِ معرفةِ الصحيحِ والحسنِ الآنَ في مراجعةِ الصحيحينِ وغيرِهما مِنَ الكتبِ الْمُعتمَدةِ، فسبيلُ مَنْ أرادَ العملَ أو الاحتجاجَ بذلكَ إذا كانَ (١) ممَّنْ يسوغُ لهُ العملُ بالحديثِ أو الاحتجاجُ بهِ لذي مَذْهَبٍ أنْ يرجعَ إلى أصلٍ قدْ قابَلَهُ هو أو ثقةٌ غيرُهُ بأصولٍ صحيحةٍ متعدِّدةٍ (٢) مرويةٍ برواياتٍ متنوعةٍ (٣)؛ ليحصلَ لهُ بذلكَ – مَعَ اشتهارِ هذهِ الكتبِ وبُعْدِها عنْ أنْ تُقصَدَ بالتبديلِ والتحريفِ – الثقةُ بصِحَّةِ ما اتَّفَقَتْ عليهِ تلكَ الأصولُ، واللهُ أعلمُ.","",{"fn":"«إذا كان»: ساقطة من (جـ).\nفي (جـ): «معددة».\nقال العراقي في التقييد: ٤٣: «ما اشترطه المصنِّف من المقابلة بأصول متعددة، قد خالفه فيه الشيخ محيي الدين النووي، فقال: وإن قابلها بأصل معتمد محقق أجزأه. قلت: وفي كلام ابن الصلاح في موضع آخر ما يدل على عدم اشتراط تعدد الأصل، فإنه حين تكلم في نوع الحسن أن نسخ الترمذي تختلف في قوله: حسن أو حسن صحيح، ونحو ذلك. قال: فينبغي أن تصحح أصلك بجماعة أصول وتعتمد على ما اتفقت عليه. فقوله هنا: ينبغي، يعطي عدم اشتراط، والله أعلم». قلنا: تعقبه تلميذه ابن حجر فقال في نكته ١/ ٣٨٤: «أقول: ليس بين كلاميه مناقضة، بل كلامه هنا مبني على ما ذهب إليه من عدم الاستقلال بإدراك الصحيح بمجرد اعتبار الأسانيد؛ لأنه علل صحة ذلك بأنه ما من إسناد إلا ونجد فيه خللًا، فقضية ذلك أن لا يعتمد على أحدهما بل يعتمد على مجموع ما تتفق عليه الأصول المتعددة؛ ليحصل بذلك جبر الخلل الواقع في أثناء الأسانيد. وأما قوله في الموضع الآخر: ينبغي أن تصحح أصلك بعدة أصول، فلا ينافي قوله المتقدم؛ لأن هذِهِ العبارة تستعمل في اللازم أيضًا، والله أعلم». وانظر: التقريب والتيسير: ٤٢."}],[538,"النَّوْعُ الثَّانِي"],[539,"مَعْرِفَةُ الْحَسَنِ (١) مِنَ الحَدِيْثِ"],[540,"رُوِّينا عَنْ أبي سُليمانَ الخطَّابيِّ - رحمه الله - أنَّهُ قالَ - بعدَ حكايتِهِ -: إنَّ الحديثَ عِندَ أهلِهِ ينقسِمُ إلى الأقسامِ الثلاثةِ التي قدَّمنا ذِكْرَها: «الحسَنُ: ما عُرِفَ مَخْرَجُهُ (٢) واشتَهَرَ رِجَالُهُ» (٣) - قالَ -: «وعليهِ مَدَارُ أكثَرِ الحديْثِ وهوَ الذي يَقْبَلُهُ (٤) أكثَرُ (٥) العلماءِ، ويستعمِلُهُ عامَّةُ الفقهاءِ» (٦)."],[541,"ورُوِّينا عَنْ أبي عيسى التِّرمِذِيِّ - رضي الله عنه - أنَّهُ يريدُ بالحسَنِ: «أنْ لاَ يكونَ في إسنادِهِ مَنْ يُتَّهَمُ بالكَذبِ، ولاَ يكونَ حديثًا شاذًّا، ويُروَى مِنْ غيرِ وجهٍ نحوَ ذلكَ (٧» (٨).","",{"fn":"انظر في الحسن: إرشاد طلاب الحقائق ١/ ١٣٧ - ١٥٢، والتقريب: ٤٢ - ٤٩، والاقتراح: ١٦٢، والمنهل الروي: ٣٥، والخلاصة: ٣٨، والموقظة: ٢٦، واختصار علوم الحديث: ٣٧، والمقنع ١/ ٨٣، وشرح التبصرة والتذكرة ١/ ١٧٧، ونزهة النظر: ٩١، والمختصر: ٧٣، وفتح المغيث ١/ ٦١، وألفية السيوطي: ١٥ - ١٩، وشرح السيوطي على ألفية العراقي: ١٢٦، وفتح الباقي ١/ ٨٤، وتوضيح الأفكار ١/ ١٥٤، وظفر الأماني: ١٧٤، وقواعد التحديث: ١٠٥.\nبفتح الميم والراء، بمعنى خروجه، وهو: رجاله الراوون له؛ لأنه خَرَجَ مِنْهُمْ. قواعد التحديث: ٢١٩. وَقَالَ البقاعي: «رِجَالُهَ الذين يدور عَلَيْهِمْ، فكل واحد من رِجَال السَّنَد «مَخْرَج» خَرَجَ مِنْهُ الحَدِيْث». النكت الوفية ٥٩ ب.\nاعترض غير واحد من العلماء على هذا التعريف، وعلى تعريف الحسن عمومًا، انظر: نكت الزركشي ١/ ٣٠٤، والتقييد والإيضاح ٤٣، وشرح التبصرة والتذكرة ١/ ١٧٧ مع تعليقاتنا هناك، ونكت ابن حجر ١/ ٣٨٥، وقد أطال السيوطي النفس فيه في كتابه البحر الذي زخر ٣/ ٩٥٠ فما بعدها.\nفي (ب): «تقبله».\nسقطت من (جـ).\nمعالم السنن ١/ ١١. وهذا التعريف نقله الحافظ المزي في تهذيب الكمال ١/ ١٠.\nفي (ع): «ذاك».\nالجامع الكبير ٦/ ٢٥١ (العلل). وللزركشي تعليق لطيف هنا، رأينا أن ننقل بعضه، قال رحمه الله ١/ ٣٠٧: «قوله أن لا يكون في إسناده من يتهم بالكذب. احترز به عمّا في سنده متهم، فإنه ضعيف. وقوله: «مَن لا يتهم بالكذب»: يتناول مشهور العدالة، لكنه غير مراد، بل المراد المستور. واحترز بقوله: «ولا يكون حديثًا شاذًا» عن الشاذ، وهو ما خالف فيه الثقة روايات الثقات. وقوله: «ويروى من غير وجه» عمّا لم يرد إلا من وجه واحد فإنه لا يكون حسنًا؛ لأن تعدد الروايات يقوي ظنّ الصحة واتحادها ممّا يؤثر ضعفًا» وانظر: نظرات جديدة في علوم الحديث ٣٣."}],[542,"وقالَ بعضُ المتأخِّرينَ (١): «الحديثُ الذي فيهِ ضَعْفٌ قريبٌ مُحتَملٌ هو الحديثُ الحسنُ، ويَصْلُحُ للعملِ بهِ»."],[543,"قلتُ: كُلُّ هذا مُسْتَبْهَمٌ لا يَشْفِي الغليلَ، وليسَ فيما ذَكَرَهُ التِّرمذيُّ والخطَّابيُّ ما يَفْصِلُ الحسَنَ مِنَ الصحيحِ. وقدْ أمعَنْتُ (٢) النَّظَرَ في ذلكَ والبحثَ جامعًا بينَ أطرافِ كلامِهِم، ملاحظًا مواقعَ استعمالِهم؛ فتنَقَّحَ لي (٣) واتَّضَحَ أنَّ الحديثَ الحسَنَ قِسْمانِ (٤):"],[544,"أحدُهُما: الحديثُ الذي لا يخلو رجالُ إسنادِهِ مِنْ مستورٍ لَمْ تَتَحَقَّقْ أهليَّتُهُ، غيرَ أنَّهُ ليسَ مُغَفَّلًا كثيرَ الخطأِ فيما يَرْويهِ، ولا هوَ متَّهَمٌ بالكذبِ في الحديثِ، أي: لَمْ يَظهرْ منهُ تَعمُّدُ (٥) الكذبِ في الحديثِ ولا سببٌ آخرُ مفسِّقٌ، ويكونُ متنُ الحديثِ معَ ذلكَ قد عُرِفَ بأنْ رُوِيَ مِثْلُهُ أو نحوُهُ مِنْ وجهٍ آخرَ أو أكثرَ، حتَّى اعتضَدَ بمتابعةِ مَنْ تابعَ راويَهُ على مثلِهِ، أو بما لَهُ مِنْ شاهِدٍ، وهوَ ورُودُ حديثٍ آخرَ بنحوِهِ، فيَخْرُجُ بذلكَ عَنْ أنْ يكونَ شاذًّا ومُنْكَرًا. وكلامُ الترمِذِيِّ على هذا القسمِ يتَنَزَّلُ."],[545,"القسمُ الثاني: أنْ يكونَ راوِيْهِ مِنَ المشهورينَ بالصدقِ والأمانةِ، غيرَ أنَّهُ لَمْ يبلغْ درجَةَ رجالِ الصحيحِ؛ لكونِهِ يقصُرُ عنهم في الحفظِ والإتقانِ، وهو معَ ذلكَ يرتفِعُ عَنْ حالِ مَنْ يُعَدُّ ما ينفرِدُ بهِ مِنْ حديثِهِ مُنكرًا، ويُعْتَبَرُ في كلِّ هذا معَ سلامةِ الحديثِ مِنْ أنْ يكونَ شاذًّا ومُنكَرًا (١): سلاَمَتُهُ مِنْ أنْ يكونَ معلَّلًا. وعلى القسمِ الثاني يتَنَزَّلُ كلامُ الخطَّابيِّ.","",{"fn":"هو ابن الجوزي. انظر: الموضوعات ١/ ٣٥، نكت الزركشي ١/ ٣١٠. قال السخاوي ١/ ٦٥: «هذا كلام صحيح في نفسه، لكنه ليس على طريقة التعاريف».\nقال الزركشي ١/ ٣١٢: «المعروف في اللغة: أنعمت - بتقديم النون - بمعنى: بالغت، يقال: أنعم في الشيء إذا بالغ فيه ...، وأما أمعنت، فقال ابن الأنباري في الزاهر: يقال: قد أمعن لي بحقي، أي: اعترف به وأظهره. قال أبو العباس: هو مأخوذ من الماء المعين، وهو الجاري الظاهر. وقال ابن فارس في المقاييس: معن: مادته تدلّ على سهولة في جريان، يقال: مَعَنَ الماءُ: إذا جرى، وأمعن الفرس في عَدْوِهِ، وأمعنَ بحقي: ذهب به. وأمعنت الأرض رَوِيَتْ. انتهى. وعلى هذا يتخرج كلام المصنِّف». قلنا: انظر: الزاهر ٢/ ٥٩٢، ومقاييس اللغة ٥/ ٣٥٥، والصحاح ٦/ ٢٢٠٥، والتقييد والإيضاح: ٤٦، وشرح التبصرة ١/ ١٨٦.\nساقطة من (م).\nاعترض على ابن الصلاح في تقسيمه هذا باعتراضات، أوردها الزركشي مع أجوبته عنها. فانظر: نكته ١/ ٣١٣ - ٣١٧.\nفي (جـ): «تعهد»."}],[546,"فهذا الذي ذكرناهُ جامعٌ لِمَا تفرَّقَ في كلامِ مَنْ بَلَغنا كلامُهُ في ذلكَ (٢)، وكأنَّ الترمذيَّ ذَكَرَ أحدَ نَوْعَيِ الحسَنِ، وذَكَرَ الخطَّابيُّ النوعَ الآخرَ، مُقْتصِرًا كلُّ واحدٍ منهما على ما رأى أنَّهُ يُشْكِلُ، مُعْرِضًا عمَّا رأى أنَّهُ لا يُشْكِلُ أو أنَّهُ غَفَلَ عَنْ البعضِ وذهلَ (٣)، واللهً أعلمُ، هذا تأصيلُ ذلكَ، ونُوضِحُهُ بتنبيهاتٍ وتفريعاتٍ:","",{"fn":"في (ب): «أو منكرًا».\nقال محقق شرح السيوطي: ١٢٨ - ١٢٩: «عرَّفه البدر ابن جماعة - ورجَّحه اللكنوي - بأنه: «كل حديث خالٍ عن العلل، وفي سنده المتصل مستور له به شاهد، أو مشهور قاصر عن درجة الإتقان». وقد انتقد ابن حجر هذا التعريف بوجوه واردة عليه. والحقيقة: أن الحديث الحسن درجة وسطى بين الصحيح والضعيف؛ ولهذا تضاربت الأقوال في تعريفه. ونصَّ غير واحد عَلَى تعسّر حده، فقال ابن دقيق العيد: «وفي تحقيق معناه اضطراب». وعلّل ذَلِكَ ابن كثير فقال: «وذلك لأنه أمر نسبي، شيء ينقدح عِنْدَ الحافظ، ربما تقصر عبارته عنه». وقال البلقيني: «لما توسط بَيْنَ الصحيح والضعيف عِنْدَ الناظر؛ كان شيئًا ينقدح في نفس الحافظ قد تقصر عبارته عنه، كما قيل في الاستحسان، فلذلك صعب تعريفه». ولعلَّ رسم ابن حجر للحديث الحسن كان أنسب من غيره، فإنه قال: «وخبر الآحاد بنقل عدل تام الضبط، متصل السند غير معلّل ولا شاذّ: هو الصحيح لذاته ...» ثمّ قال: «فإن خفَّ الضبط فالحسن لذاته». فهذا ما مشى عليه علماء المصطلح، وإن نبَّه السخاوي على أن خفة الضبط في تعريف ابن حجر غير منضبطة بضابط، ولكن يمكن أن يقال: إن مراد الحافظ خفة ضبط معلومة لمن مارس هذا الفن وداخل كيانه، واعتاد أقوال أئمته، فعرف أصحاب الضبط التام ومن في حفظه شيء ومن هو سيء الحفظ. ونحن نقرُّ أن هناك بعض الجزئيات لا تدخل في رسم ابن حجر للحديث الحسن، وهو مصداق لقول الإمام الذهبي - وهو من أهل الاستقراء التام كما يقول ابن حجر-: «ثمَّ لا تطمع بأن للحسن قاعدة تندرج كل الأحاديث الحسان فيها، فأنا على إياس من ذلك». ثُمَّ إنَّ الحسن مراتب -كما أن الصحيح مراتب- وبعضها أقوى في نفس الناقد من بعض. انظر: الاقتراح: ١٦٢، المنهل الروي: ٣٦، الموقظة: ٢٨، اختصار علوم الحَدِيْث: ٣٧، شرح علل التِّرْمِذِي: ٢٨٧ - ٢٨٩، محاسن الاصطلاح: ١٠٥، النكت على كتاب ابن الصلاح ١/ ٤٦ نزهة النظر: ٨٢، ٩١، فتح المغيث ١/ ٦٦، ظفر الأماني: ١٨٦، ماهية الحَدِيْث الحَسَن: ١٠، والتعليق على شرح التبصرة والتذكرة ١/ ١٧٧ - ١٨٠.\nمن ينعم النظر في تعريفي الترمذي والخطابي، يجد بينهما بونًا شاسعًا، منشؤه اختلاف القصد من إيراد التعريف، فالخطابي قصد تعريف الأنواع الثلاثة عند أهل الحديث، فعرَّف الصحيح والضعيف إضافة إلى الحسن، وإنما لم يعرّف حديث المستور إذا اعتضدت روايته من غير وجه؛ لأنه داخل عنده ضمن الحَسَن. وإذا لَمْ تعتضد فهي عنده من الضَّعِيف، إذ أطلق القَوْل بردِّ رِوَايَة المجهول، والمستور قِسْم من المجهول. ="}],[547,"أحدُها: الْحَسَنُ يتقاصَرُ عَنِ الصحيحِ (١) في أنَّ الصحيحَ مِنْ شرطِهِ: أنْ يكونَ جميعُ رواتِهِ قَدْ ثَبَتَتْ عدالَتُهُم وضَبْطُهُم وإتقانُهُم؛ إمَّا بالنقلِ الصريحِ أو بطريقِ الاستفاضةِ عَلَى مَا سنبيِّنُهُ - إنْ شاءَ اللهُ تَعَالَى -، وذلكَ غيرُ مُشتَرَطٍ في الحسَنِ؛ فإنَّهُ يُكْتَفَى فيهِ بما سبقَ ذِكْرُهُ مِنْ مجيءِ الحديثِ مِنْ وجوهٍ، وغيرِ ذلكَ ممَّا تقدَّمَ شرحُهُ (٢)."],[548,"وإذا اسْتَبْعَدَ ذلكَ من الفقهاءِ الشافعيةِ مستبعدٌ ذَكَرْنا لهُ نصَّ الشافعيِّ - رضي الله عنه - في مراسيلِ التابعينَ أنَّهُ يُقبَلُ منها المرسلُ الذي جاءَ نحوُهُ مسنَدًا، وكذلكَ لو وافقَهُ مُرسلٌ آخرُ أرسلَهُ مَنْ أخذَ العلمَ عَنْ (٣) غيرِ رجالِ التابعيِّ (٤) الأوَّلِ في كلامٍ لهُ ذكرَ فيهِ وجوهًا مِنَ الاستدلالِ على صِحَّةِ مَخرجِ المرسلِ بمجيئِهِ (١) مِنْ وجهٍ آخرَ (٢)، وذكرنا لهُ أيضًا ما حكاهُ الإمامُ أبو الْمُظَفَّرِ السَّمْعانيُّ وغيرُهُ عَنْ بعضِ (٣) أصحابِ الشافعيِّ مِنْ أنَّهُ تقبلُ روايةُ المستورِ وإنْ لَمْ تُقبلْ شهادةُ المستورِ (٤)؛ ولذلكَ وجهٌ متَّجِهٌ، كيفَ وإنَّا لَمْ نكْتَفِ في الحديثِ الحسَنِ بمجرَّدِ روايةِ المستورِ على ما سبقَ آنِفًا؟ واللهُ أعلمُ.","",{"fn":"قال الزركشي ١/ ٣١٨: «يعني من جهة الرتبة حتى ولو تعارض حسن وصحيح قُدِّم الصحيح وإلا فهما مستويان في الاحتجاج بهما - كما سيأتي في التاسع من كلامه - وكان ينبغي له تقديم التاسع إلى هاهنا فإنه أنسب».\nقال العراقي ٤٧ - ٤٨: «فيه أمران: أحدهما: أنه قد اعترض عليه بأن جميع رواة الصحيح لا توجد فيهم هذه الشروط، إلاَّ في النزر اليسير. انتهى. والجواب: أن العدالة تثبت إما بالتنصيص عليها كالمصرح بتوثيقهم وهُم كثير، أو بتخريج من التزم الصحة في كتابه له فالعدالة أيضًا تثبت بذلك، وكذلك الضبط والإتقان درجاته متفاوتة، فلا يشترط أعلى وجوه الضبط كمالك وشعبة، بل المراد بالضبط أن لا يكون مغفلًا كثير الغلط، وذلك بأن يعتبر حديثه بحديث أهل الضبط والإتقان، فإن وافقهم غالبًا فهو ضابط كما ذكره المصنِّف في المسألة الثانية من النوع الثالث والعشرين، وإذا كان كذلك فلا مانع من وجود هذه الصفات في رواة صحيح الأحاديث، والله أعلم. الأمر الثاني: أن قوله في الحسن: إنه يكتفى فيه بما سبق ذكره من مجيء الحديث من وجوه. فيه نظر، إذ لم يسبق اشتراط مجيئه من وجوه، بل من غير وجه كما سبق ذلك في كلام الترمذي، وعلى هذا فمجيئه من وجهين كافٍ في حدِّ الحديث الحسن، والله أعلم».\nفي (جـ): «من». وكذلك في الرسالة.\nفي (ب): «التابعين»."}],[549,"الثاني: لعلَّ الباحثَ الفَهِمَ يقولُ: إنَّا نجدُ أحاديثَ محكومًا بضَعْفِها معَ كونِها قدْ رُويَتْ بأسانيدَ كثيرةٍ مِنْ وجوهٍ عديدةٍ، مثلُ حديثِ (٥): «الأُذُنانِ مِنَ الرَّأسِ» (٦)","",{"fn":"في (ع): «لمجيئه».\nانظر: الرسالة ٤٦١ - ٤٦٣ (الفقرات ١٢٦٤ - ١٢٧٤). وانظر عن شروط الشافعي في قبول المرسل: نكت الزركشي ١/ ٤١٩، والتقييد والإيضاح: ٤٨، ونكت ابن حجر ١/ ٤٠٨.\nليست في (جـ).\nقال الزركشي ١/ ٣١٩: «لم أجده في القواطع لابن السمعاني، لكن نقله المازري في شرح البرهان عن ابن فورك».\nساقطة من (ب).\nهذا حديث روي عن عدّة من الصحابة منهم: أبو أمامة: رواه أحمد ٥/ ٢٥٨ و٢٦٤ و٢٦٨، وأبو داود (١٣٤)، والترمذي (٣٧)، وابن ماجه\n، والطحاوي ١/ ٣٣، والطبراني في الكبير ٨/ ١٢١، والدارقطني ١/ ١٠٣، والبيهقي ١/ ٦٦. وأبو هريرة: أخرجه ابن ماجه (٤٤٥)، وأبو يعلى (٦٣٧٠)، وابن حبان في المجروحين ٢/ ١١٠، والدارقطني ١/ ١٠١ - ١٠٢. وعبد الله بن زيد: أخرجه ابن ماجه (٤٤٣)، والبيهقي ١/ ٦٥. وعبد الله بن عمر: رواه الدارقطني ١/ ٩٧. وعائشة: رواه الدارقطني ١/ ١٠٠. وعبد الله بن عباس: رواه الدارقطني ١/ ٩٩. وهو مروي من حديث غيرهم. قال ابن حجر في النكت ١/ ٤١٥ بعد أن أورد الروايات وتكلم عليها: «وإذا نظر المنصف إلى مجموع هذه الطرق علم أن للحديث أصلًا، وأنه ليس ممَّا يطرح، وقد حسنوا أحاديث كثيرة باعتبار طرق لها دون هذه، والله أعلم». وانظر: عنه نكت الزركشي ١/ ٣٢٠، والتقييد: ٥٠، ونكت ابن حجر ١/ ٤٠٩."}],[550,"ونحوِهِ، فهلاَّ جَعَلْتُم ذلكَ وأمثالَهُ مِنْ نوعِ الحسَنِ؛ لأنَّ بعضَ ذلكَ عَضَدَ بَعْضًا، كما قلتُم في نوعِ الحسَنِ على ما سبقَ آنفًا."],[551,"وجوابُ ذلكَ أنَّهُ ليسَ كلُّ ضَعْفٍ في الحديثِ يزولُ بمجيئِهِ مِنْ وجوهٍ، بلْ ذلكَ يتفاوتُ: فمنهُ (١) ضَعْفٌ يُزيلُهُ ذلكَ، بأنْ يكونَ ضَعْفُهُ ناشئًا مِنْ ضَعْفِ حفظِ راويهِ مَعَ كونِهِ مِنْ أهلِ الصِّدقِ والديانةِ. فإذا رأينا ما رواهُ قدْ جاءَ مِنْ وجهٍ آخرَ، عَرَفنا أنَّهُ ممَّا قدْ حفظَهُ، ولَمْ يختلَّ فيهِ ضبطُهُ لهُ. وكذلكَ إذا كانَ ضَعْفُهُ مِنْ حيثُ الإرسالُ، زالَ بنحوِ ذلكَ، كما في المرسلِ الذي يُرسِلُهُ إمامٌ حافظٌ، إذ فيهِ ضَعْفٌ قليلٌ يزولُ بروايتِهِ منْ وجهٍ آخرَ، ومِنْ ذلكَ ضَعفٌ لا يزولُ بنحوِ ذلكَ لقوّةِ الضَّعْفِ وتقاعدِ هذا الجابرِ عَنْ جَبْرِهِ ومقاومَتِهِ، وذلكَ كالضَّعْفِ الذي ينشأُ مِنْ كونِ الراوي متَّهَمًا بالكذِبِ أو كونِ الحديثِ شاذًّا. وهذهِ جملةٌ تفاصيلُها تُدْرَكُ بالمباشرةِ والبحثِ، فاعلمْ ذلكَ فإنَّهُ مِنَ النَّفائِسِ العزيزةِ، واللهُ أعلمُ (٢)."],[552,"الثالثُ: إذا كانَ راوي الحديثِ متأخِّرًا عَنْ درجةِ أهلِ الحفظِ والإتقانِ غيرَ أنَّهُ مِنَ المشهورينَ بالصِّدْقِ والسِّتْرِ ورُوِيَ معَ ذلكَ حديثُهُ مِنْ غيرِ وجهٍ فقدِ اجتمعتْ لهُ القوَّةُ مِنَ الجهتينِ، وذلكَ يُرقِّي حديثَهُ مِنْ درجةِ الحسَنِ إلى درجةِ الصحيحِ."],[553,"مثالُهُ: «حديثُ محمّدِ بنِ عَمْرٍو، عن أبي سَلَمَةَ، عن أبي هُريرةَ، أنَّ رسولَ اللهِ - صلى الله عليه وآله وسلم - قالَ: «لولا أنْ أشُقَّ على أُمَّتِي لأَمَرْتُهُم بالسِّواكِ عِنْدَ كُلِّ صلاةٍ» (٣). فمحمّدُ بنُ عمرِو بنِ علقَمةَ مِنَ المشهورينَ بالصِّدْقِ والصِّيانةِ (٤)، لكنَّهُ لَمْ يكنْ مِنْ أهلِ الإتقانِ، حتَّى ضَعَّفَهُ بعضُهُم مِنْ جِهةِ سُوءِ حفظِهِ، ووثَّقَهُ بعضُهُم؛ لِصِدْقِهِ وجلالَتِهِ، فحديثُهُ مِنْ هذهِ الجهةِ حَسَنٌ، فلمَّا انضمَّ إلى ذلكَ كونُهُ رُويَ مِنْ أوجهٍ أُخَرَ (١)، زالَ بذلكَ ما كنَّا نخشاهُ عليهِ مِنْ جهةِ سوءِ حفظِهِ، وانجبرَ بهِ ذلكَ النقصُ اليسيرُ، فصحَّ هذا الإسنادُ والتحقَ بدرجةِ الصحيحِ (٢)، واللهُ أعلمُ.","",{"fn":"في (م): «فمن».\nقال ابن حجر ١/ ٤٠٩: «لم يذكر للجابر ضابطًا يعلم منه ما يصلح أن يكون جابرًا أو لا، والتحرير فيه أن يقال: إنه يرجع إلى الاحتمال في طرفي القبول والردِّ، فحيث يستوي الاحتمال فيهما فهو الذي يصلح لأن ينجبر، وحيث يقوى جانب الردِّ فهو الذي لا ينجبر. وأمَّا إذا رجّح جانب القبول فليس من هذا، بل ذاك في الحسن الذاتي، والله أعلم».\nأخرجه أحمد ٢/ ٥٨ و٢٨٧ و٣٩٩ و٤٢٩، والترمذي (٢٢)، والطحاوي في شرح المعاني ١/ ٤٤، والطبراني في الأوسط (٧٤٢٠)، والبيهقي ١/ ٣٧، وأبو نعيم في الحلية ٨/ ٣٨٦.\nمحمد بن عمرو بن علقمة: «حسن الحديث». كما قال الذهبي في الميزان ٣/ ١٦٧، وقال الحافظ في التقريب (٦١٨٨): «صدوق له أوهام»، وقال في أجوبته التي في آخر المشكاة ٣/ ٣١٠: «صدوق= =في حفظه شيء، وحديثه في مرتبة الحسن». وقال في هدي الساري ٤٤١: «صدوق تكلم فيه بعضهم من قبل حفظه»."}],[554,"الرابعُ: كتابُ أبي عيسى التِّرمِذيِّ -رحمه الله - أصلٌ في معرفةِ الحديثِ الحسَنِ، وهو الذي نَوَّهَ باسمِهِ وأكثرَ مِنْ ذِكْرِهِ في \" جامِعِهِ \". ويوجدُ في متفرقاتٍ منْ كلامِ بعضِ مشايخِهِ، والطبقةِ التي قبلَهُ كأحمدَ بنِ حنبلٍ، والبخاريِّ، وغيرِهِما (٣) وتختلفُ النُّسَخُ مِنْ كتابِ الترمذيِّ في قولِهِ: «هذا حديثٌ حسَنٌ»، أو «هذا حديثٌ حسَنٌ صحيحٌ»، ونحوِ ذلكَ (٤). فيَنْبَغِي أنْ تُصَحِّحَ أصلَكَ بهِ (٥) بجماعةِ أصولٍ وتعتمدَ على ما اتَّفَقَتْ عليهِ."],[555,"ونصَّ الدَّارَقطنيُّ في \" سُنَنِهِ \" على كثيرٍ مِنْ ذلكَ (٦). ومِنْ مظَانِّهِ (٧) \" سننُ أبي داودَ \" السِّجستانيِّ (١) - رحمه الله - رُوِّيْنا عنهُ أنَّهُ (٢) قالَ: «ذكرْتُ فيهِ الصحيحَ، وما يُشْبِهُهُ ويُقَارِبُهُ» (٣). ورُوِّيْنا عنهُ أيضًا ما معناهُ أنَّهُ يذكرُ في كلِّ بابٍ أصحَّ ما عَرَفَهُ في ذلكَ البابِ. وقالَ: «ما كانَ في كتابي مِنْ حديثٍ فيهِ وَهْنٌ شديدٌ فقدْ بيَّنْتُهُ (٤) وما لَمْ أذكرْ فيهِ شيئًا فهوَ صالِحٌ، وبعضها أصحُّ مِنْ بعضٍ» (٥).","",{"fn":"في (ب): «وجه آخر».\nانظر فيما يتعلق بهذا الحديث: نكت الزركشي ١/ ٣٣٠، ونكت ابن حجر ١/ ٤١٦.\nوجد التعبير بالحسن في كلام من هو أقدم منهما كالشافعي ومالك، بل من هو أقدم كإبراهيم النخعي وشعبة وعلي بن المديني وغيرهم. ولكن الملاحظ على تعابيرهم: أن منهم من أراد المعنى الاصطلاحي، ومنهم من لم يُرده. انظر: نكت الزركشي ١/ ٣٣١، والتقييد ٥٢، ونكت ابن حجر ١/ ٤٢٤.\nنقل الزركشي ١/ ٣٣٤ عن ابن دقيق العيد أنه قال: «إن النُّسَخ من كتاب الترمذي تختلف في قوله: حسن صحيح، أو حسن، وأكثر ما يعتمده المتأخرون رواية الكروخي وهي مخالفة في التصحيح لرواية المبارك بن عبد الجبار».\nليست في (ب).\nأي: من الحسن. انظر: نكت الزركشي ١/ ٣٣٦.\nمَظِنَّة الشيء: الموضع الذي يُظنُّ كونه فيه، قال الجوهري: «ومَظِنَّةُ الشيء: موضعه ومألفه الذي يُظنُّ كونه فيه، والجمع: المَظانُّ». وفي اللسان: «المظانُّ: جمع مَظِنَّة - بكسر الظاء -: وهي موضع الشيء ومَعْدِنه - مَفْعِلَة - من الظنّ بمعنى: العلم، قال ابن الأثير: وكان القياس فتح الظاء، وإنما كُسِرت لأجل الهاء، قال: ويجوز أن تكون من الظنّ بمعنى العلم والميم زائدة». انظر: الصحاح ٦/ ٢١٦٠، والنهاية ٣/ ١٦٤، واللسان ١٣/ ٢٧٤."}],[556,"قلتُ: فعلى هذا ما وجدناهُ في كتابِهِ مذكورًا (٦) مطلقًا وليسَ في واحدٍ"],[557,"مِنَ الصحيحينِ، ولا نصَّ على صِحَّتِهِ أحدٌ ممَّنْ يُمَيِّزُ بينَ الصحيحِ والحسَنِ، عرَّفناهُ"],[558,"بأنَّهُ مِنَ الحسَنِ عندَ أبي داودَ (٧)، وقدْ يكونُ في ذلكَ ما ليسَ بحسنِ عندَ غيرِهِ (١)، ولا مندرجٍ فيما حقَّقنا ضَبْطَ الحسَنِ بهِ على ما سبقَ، إذْ حكى أبو عبدِ اللهِ بنِ مَنْده (٢) الحافظُ: أنَّهُ سَمِعَ محمّدَ بنَ سَعْدٍ الباوَرْدِيَّ بمصرَ يقولُ: «كانَ مِنْ مذهبِ أبي عبدِ الرحمانِ النَّسائيِّ أنْ يُخرِجَ عَنْ كلِّ مَنْ لَمْ يُجمَعْ على تركِهِ» (٣)، قالَ ابنُ مَنْده:","",{"fn":"بكسر السين والجيم، وسكون السين الثانية. انظر: الأنساب ٣/ ٢٤٨.\nفي (م): «أن».\nهذا النص الذي يذكر في كتب المصطلح بلفظ: «ذكرت فيه الصحيح وما يشبهه وما يقاربه». لم نجده في رسالة أبي داود إلى أهل مكة المطبوعة مع مقدمة بذل المجهود ١/ ٣٥، ولا في المطبوعة بتحقيق الدكتور محمد لطفي الصباغ، على الرغم من تظافر العديد من كتب المصطلح على نسبته إلى الرسالة. انظر: التقييد والإيضاح: ٥٥، وفتح المغيث ١/ ٧٧، وكشف الظنون ٢/ ١٠٠٥. وقد رواه الخطيب في تاريخ بغداد ٩/ ٥٧ من طريق ابن داسة عنه، من غير عزو إلى رسالته، والذي يدلّ عليه صنيع الحازمي في شروط الأئمة الخمسة ٦٧ - ٦٨: أن هذا المقطع ليس في رسالة أبي داود، فإنه نقل نصًا من الرسالة ثمَّ قال عقبه: «وقد روينا عن أبي بكر ابن داسة أنه قال: سمعت أبا داود يقول: ...» فذكره. وهذا هو مقصد ابن الصلاح، فإنه قال: «روينا عنه أنه قال: ذكرت فيه الصحيح ...» ثم قال: «روينا عنه أيضًا ما معناه: أنه يذكر في كل باب أصحّ ما عرفه»، وهذا النقل الثاني عن رسالة أبي داود ١/ ٣٥ فكأنه يشير إلى أن الأول ليس في الرسالة. فرحمه الله ما أنبل قصده وأدق مسلكه». انظر تعليقنا على شرح التبصرة ١/ ١٩٦.\nقال ابن حجر ١/ ٤٣٥: «وفي قول أبي داود: «وما كان فيه وهن شديد بينته» ما يفهم أن الذي يكون فيه وهن غير شديد أنه لا يبينه».\nرسالة أبي داود إلى أهل مكة١/ ٣٥ مع بذل المجهود. وفي نص الرسالة التي ساقها السيوطي بسنده في كتابه البحر الذي زخر ٣/ ١١١٧. وانظر: النفح الشذي ١/ ٢٠٨، ونكت الزركشي ١/ ٣٣٦ - ٣٤٢.\nفي (أ): «ما وجدناه مذكورًا في كتابه مطلقًا».\nفيه نظر، بل هو خطأ محض؛ لعدة أمور، مِنْها: اختلاف روايات السُّنَن، ففي بَعْض الروايات من أقوال أبي دَاوُد مَا لَيْسَ في الأخرى، ثُمَّ إن أبا دَاوُد قد يُضعّف الحَدِيْث بالراوي، فإذا جاء هَذَا الرَّاوِي في حَدِيث آخر سكت عَنْهُ؛ لأنه تقدم الكلام عَلَيْهِ، ثُمَّ إن أبا عبيد الآجري في سؤالاته ينقل كثيرًا من تضعيف أبي دَاوُد لبعض الأحاديث، وَهُوَ قد سكت عَنْهَا في سننه. وَقَدْ أطال الحافظ ابن حجر في نكته عَلَى ابن الصَّلاح ١/ ٤٣٢ - ٤٤٥ في بحث هذِهِ المسألة، وذكر أمثلتها. ="}],[559,"«وكذلكَ أبو داودَ السِّجِسْتانيُّ يأخذُ مأخَذهُ ويُخَرِّجُ الإسنادَ الضعيفَ إذا لَمْ يجدْ في البابِ غيرَهُ؛ لأنَّهُ أقوى عِنْدَهُ مِنْ رأي الرِّجالِ» (٤)، واللهُ أعلمُ."],[560,"الخامسُ: ما صارَ إليهِ صاحبُ \" المصابيحِ \" -رحمه الله- مِنْ تقسِيْمِ أحاديثِهِ إلى نوعينِ: الصِّحَاحِ، والحِسَانِ، مُريدًا بالصِّحَاحِ: ما وردَ في أحدِ الصحيحينِ أو فيهما، وبالحِسَانِ: ما أوردَهُ أبو داودَ والتِّرمذيُّ وأشباهُهما في تصانيفِهِم (٥)، فهذا اصطلاحٌ لا يُعْرَفُ، وليسَ الحسَنُ عِندَ أهلِ الحديثِ عبارةً عَنْ ذلكَ. وهذهِ (٦) الكُتُبُ تشتملُ على حَسَنٍ وغيرِ حَسَنٍ كما سَبَقَ بيانُهُ، واللهُ أعلمُ (٧).","",{"fn":"أشار محقق (ع) إلى أنه في بعض نسخه: «عنده»، وهذا ما نصره العلاّمة عبد الفتاح أبو غدة - يرحمه الله - في تحقيقه لتوجيه النظر ١/ ٣٦٥، ومن تأمل السياق علم أن ما نصره الشيخ خلاف ما قصده ابن الصلاح تمامًا، كما أن كل من نقل عنه أو اختصر كلامه نقل ما أثبتناه. والله أعلم.\nبفتح الميم والدال المهملة، بينهما نون ساكنة، وآخره هاء ساكنة. هكذا ضبطه ابن خلكان ٤/ ٢٨٩.\nانظر: شروط الأئمة الستة لابن طاهر: ١٩.\nشروط الأئمة: ٧٣، وانظر: نكت الزركشي ١/ ٣٤٢.\nانظر: مصابيح السنة ١/ ٢ و١٨٩.\nفي (ب): «فهذه».\nقال الزركشي ١/ ٣٤٢: «قد تبعه النووي وغيره في الاعتراض على البغوي، وهو عجيب؛ لأن البغوي لَم يقل: إن مراد الأئمة بالصحاح كذا، وبالحسان كذا، وإنما اصطلح على هذا رعاية للاختصار، ولا مشاحة في الاصطلاح». قال ابن حجر ١/ ٤٤٦: «قلت: ومما يشهد لصحة كونه أراد بقوله الحسان اصطلاحًا خاصًّا له أن يقول في مواضع من قسم الحسان: هذا صحيح تارة، وهذا ضعيف تارة، بحسب ما يظهر له من ذلك. ولو كان أراد بالحسان الاصطلاح العام ما نوّعه في كتابه إلى الأنواع الثلاثة، وحتى لو كان عليه في بعض ذلك مناقشة بالنسبة إلى الإطلاق، فذلك يكون لأمر خارجي حتى يرجع إلى الذهول ولا يضر فيما نحن فيه، والله أعلم». وانظر: التقييد ٥٥، وتعليقنا على شرح التبصرة ١/ ٢٠٢ - ٢٠٣."}],[561,"السادسُ: كُتُبُ المسانِدِ (١) غيرُ مُلْتَحِقةٍ بالكتبِ الخمسةِ التي هيَ: \" الصحيحانِ \" و\" سننُ أبي داودَ \" و\" سننُ النَّسائيِّ \" و\" جامعُ التِّرمذيِّ \"، وما جَرَى مَجْرَاها في الاحتجاجِ بها والرُّكُونِ إلى ما يورَدُ فيها مُطلقًا، كـ \" مُسْنَدِ أبي داودَ الطيالسيِّ \" (٢) و\" مُسْنَدِ عُبيدِ اللهِ بنِ موسى \" (٣) و\" مُسندِ أحمدَ بنِ حنبلٍ \" (٤) و\" مسندِ إسحاقَ بنِ راهَوَيْهِ \" (٥) و\" مسندِ عَبْدِ بنِ حُمَيْدٍ \" و\" مسندِ الدَّارميِّ \" (٦) و\" مسندِ أبي يعلى الموصلِيِّ \" و\" مسندِ الحسنِ بن سُفيانَ \" و\" مسندِ البزَّارِ أبي بكرٍ \" (١)، وأشباهِها، فهذهِ عادتُهُم فيها أنْ يُخَرِّجُوا في مُسندِ كُلِّ صحابيٍّ ما رَوَوهُ مِنْ حديثِهِ غَيْرَ مُتَقيِّدينَ بأنْ يكونَ حديثًا محتَجًّا بهِ؛ فلهذا تأخَّرَتْ مرتبَتُها - وإنْ جَلَّتْ لِجلالةِ مؤلِّفيها - عنْ مرتبةِ الكُتُبِ الخمسةِ وما التحقَ بها مِنَ الكُتُبِ المصنَّفَةِ على الأبوابِ، واللهُ أعلمُ.","",{"fn":"في (جـ) و(م): «المسانيد». قال الزركشي ١/ ٣٤٣: «يجوز لك إثبات الياء في الجمع ويجوز حذفها، وكذلك مراسيل ومراسل، والأولى الحذف، قال تعالى: ﴿مَا إنَّ مَفَاتِحَهُ﴾. والإثبات عند البصريين موقوف على السماع، وعند الكوفيين جائز، ذكر ذلك سيبويه في أول كتابه في باب الضرورات وأنشد: تَنْفِي يَدَاهَا الحَصَى فِي كُلِّ هَاجِرَةٍ ... نَفْيَ الدَّنَانِيْرِ تَنقَادُ الصَّيَارِيْفِ وجعل بعضهم منه قوله تعالى: ﴿وَلَوْ أَلْقَى مَعَاذِيْرَهُ﴾. قال: وقياسه معاذر؛ لكنه أشبع الكسرة فتولدت الياء». انظر: الكتاب لسيبويه ١/ ٢٨، ومحاسن الاصطلاح ١١٢، والبحر الذي زخر ٣/ ١٢٠٥، وتاج العروس ٨/ ٢١٧.\nقال الزركشي ١/ ٣٤٨: «هو سليمان بن داود، وليس المسند له، وإنما هو ليونس بن حبيب بن عبد القاهر العجلي، سمعه في أصفهان منه فنسبه إليه». قال البقاعي: «إنه ليس من تصنيف أبي داود، وإنما هو جمع بعض الحفَّاظ الخراسانيين جمع فيه ما رواه يونس بن حبيب خاصة عن أبي داود، ولأبي داود من الأحاديث التي لم تدخل هذا المسند قدره أو أكثر، بل قد شذّ عنه كثير من رواية يونس عن أبي داود». النكت الوفية ٨١ أ.\nقال الزركشي ١/ ٣٤٩: «هو أحد شيوخ البخاري، قال ابن الجوزي في المشكل: «أوّل من صنف المسند على تراجم الرجال عبيد الله بن موسى العبسي، وأبو داود الطيالسي»، قلت: ولهذا صدَّر المصنِّف بالتمثيل بهما».\nأطال النفس في الكلام عن مسند الإمام أحمد ومدى أصحية مروياته. الزركشي في نكته ١/ ٣٥١، والعراقي في التقييد: ٥٦، وابن حجر في النكت ١/ ٤٤٧، وإياك أن تغتر بأحكام شعيب الأرنؤوط وجماعة في أحكامهم على أحاديث المسند!!\nروي عن ابن راهويه أنه قال: «خرجت عن كل صحابي (بمعنى: الصحابي) أمثل ما ورد عنه»، نكت الزركشي ١/ ٣٦٦. قال العراقي ٥٨: «وأما مسند إسحاق بن راهويه ففيه الضعيف، ولا يلزم من كونه يخرج أمثل ما يجد عن الصحابي، أن يكون جميع ما خرجه صحيحًا، بل هو أمثل بالنسبة لما تركه».\nقال الزركشي ١/ ٣٥٠: «وينتقد على المصنف في ذكره هنا من وجهين: = = أحدهما: أن مسند الدارمي مرتب على الأبواب لا على المسانيد، إلاّ أن يقصد الاسم المشهور به. الثاني: جعله دون الكتب الخمسة، وقد أطلق جماعة عليه اسم الصحيح»."}],[562,"السابعُ: قولُهُم: «هذا (٢) حديثٌ صحيحُ الإسنادِ أو حسنُ الإسنادِ» دونَ قولِهِم: «هذا حديثٌ صحيحٌ أو حديثٌ حسَنٌ»؛ لأنَّهُ قَدْ يُقالُ: «هذا حديثٌ صحيحُ الإسنادِ» ولا يصحُّ؛ لكونِهِ شاذًّا أو معلَّلًا غيرَ أنَّ المصنِّفَ المعتمدَ منهم إذا اقتصَرَ على قولهِ: إنَّهُ صحيحُ الإسنادِ ولَمْ يَذكرْ لهُ عِلَّةً، ولَمْ يَقدحْ فيهِ فالظاهِرُ منهُ الحكمُ لهُ بأنَّهُ صحيحٌ في نفسِهِ؛ لأنَّ عَدَمَ العلَّةِ والقادِحِ هوَ الأصلُ والظاهرُ (٣)، واللهُ أعلمُ.","",{"fn":"قال الزركشي ١/ ٣٦٦: «هو يبين فيه الكلام على علل الأحاديث والمتابعات والتفردات، قال الدارقطني: «لكنه يخطئ». وقال العراقي ٥٨: «وأما مسند البزَّار فإنه مجملًا يبين الصحيح من الضعيف إلاّ قليلًا، إلاَّ أنه يتكلم في تفرد بعض رواة الحديث به، ومتابعة غيره عليه». وقد أكد ابن حجر في نكته ١/ ٤٤٧ على وجود الضعيف فيه، فقال: «وقد صرَّح ببعض ذلك في عدة مواضع من مسنده، فيخرج الإسناد الذي فيه مقال ويذكر علته، ويعتذر عن تخريجه بأنه لم يعرفه إلا من ذلك الوجه». ونقل السيوطي في البحر الذي زخر ٣/ ١٢٠١ عن أبي الحسن الشاري في فهرسته أنه قال: «مسند البزار عندي من أحسن المسندات لما اشتمل عليه من الكلام على علل الحديث، وإن كان قد تكلّم بعض الناس في البزار بما لم يعتمد عليه أهل التحقيق».\nليست في (جـ).\nقال التاج التبريزي: «ولقائل أن يقول: لا نسلّم أن قولهم: هذا حديث صحيح الإسناد يحتمل كونه شاذًّا أو معلّلًا مردودًا؛ ليكون دون قولهم: هذا حديث صحيح، فإن صحة الإسناد مستلزمة بصحة المتن دون العكس، والحكم بصحة الإسناد مع احتمال عدم صحته بعيد جدًا». البحر الذي زخر ٣/ ١٢٤٩ - ١٢٥٠. قال الزركشي ١/ ٣٦٧ منتصرًا لابن الصلاح: «هذا فيه نظر، وقد تقدّم في كلام المصنف أنهم إذا قالوا: «هذا حديث صحيح»، فمرادهم اتصال سنده، لا أنه مقطوع به في نفس الأمر، وقد تكرر في كلام المزي والذهبي وغيرهما من المتأخرين «إسناده صالح والمتن منكر». ="}],[563,"الثامِنُ: في قولِ الترمذيِّ وغيرِهِ: «هذا حديثٌ حسنٌ صحيحٌ» (١) إشكالٌ؛ لأنَّ الْحَسَنَ قاصِرٌ عَنِ الصحيحِ كما سبقَ إيضاحُهُ، ففي الْجَمْعِ بينهما في حديثٍ واحدٍ جَمْعٌ بينَ نَفْيِ ذلكَ القصورِ وإثباتِهِ؟! وجوابُهُ: أنَّ ذلكَ راجعٌ إلى الإسنادِ، فإذا رُويَ الحديثُ الواحدُ بإسنادينِ، أحدُهما إسنادٌ حَسَنٌ والآخرُ إسنادٌ صحيحٌ، استقامَ أنْ يقالَ فيهِ: إنَّهُ حديثٌ حَسَنٌ صحيحٌ، أي (٢) إنَّهُ حسَنٌ بالنسبةِ إلى إسنادٍ صحيحٌ بالنسبةِ إلى إسنادٍ آخرَ. على أنَّهُ غيرُ مُسْتَنكَرٍ أنْ يكونَ بعضُ مَنْ قالَ ذلكَ، أرادَ بالحسنِ معناهُ اللغويَّ، وهو ما تَمِيلُ إليهِ النَّفْسُ ولا يأباهُ القلبُ، دونَ المعنى الاصطلاحيِّ الذي نحنُ بصَدَدِهِ، فاعلمْ ذلكَ، واللهُ أعلمُ."],[564,"التاسعُ: مِنْ أهلِ الحديثِ مَنْ لا يُفردُ نوعَ الحسَنِ ويجْعَلُهُ مُندرِجًا في أنواعِ الصحيحِ؛ لاندراجِهِ في أنواعِ مَا يُحتجُّ بهِ (٣)، وَهُوَ الظاهرُ مِنْ كلامِ الحاكمِ أبي عبدِ اللهِ الحافظِ في تصرفاتِهِ، وإليهِ يومئُ في تسميتِهِ كتابَ الترمذيِّ بـ\" الجامعِ الصحيحِ \" (١).","",{"fn":"للعلماء في هذه المسألة أجوبة واعتراضات ومناقشات. انظر: الاقتراح: ١٧٤، ونكت الزركشي ١/ ٣٦٨، ومحاسن الاصطلاح: ١١٤، والتقييد والإيضاح: ٥٨، ونكت ابن حجر١/ ٤٧٥، والبحر الذي زخر٣/ ١٢٠٩.\nعبارة: «أن يقال فيه: أنه حديث حسن صحيح، أي» ليست في (جـ).\nبل قال شيخ الإسلام أبو العباس بن تيمية: «قسمة الحديث إلى صحيح وحسن وضعيف فهذا أول من عرف أنه قسمه هذه القسمة أبو عيسى الترمذي، ولم تعرف هذه القسمة عن أحد قبله». ثم قال: «وأمَّا مَنْ قبل الترمذي من العلماء فما عرف عنهم هذا التقسيم الثلاثي لكن كانوا يقسمونه إلى صحيح وضعيف، والضعيف عندهم نوعان: ضعيف ضعفًا لا يمتنع العمل به، وهو يشبه الحسن في اصطلاح الترمذي، وضعيف ضعفًا يوجب تركه وهو الواهي». مجموع الفتاوى ١٨/ ١٧، ١٨. وانظر: ١٨/ ١٤٠ منه. وقال العراقي في التقييد: ١٩: «لم أرَ من سبق الخطابي إلى تقسيمه ذلك، وإن كان في كلام المتقدّمين ذكر الحسن». وقال ابن حجر في نكته ١/ ٤٧٩: «هذا ينبغي أن يقيّد به إطلاقه في أول الكلام على نوع الصحيح، وهو قوله: الحديث ينقسم عند أهله إلى صحيح وحسن وضعيف»."}],[565,"وأطلقَ الخطيبُ أبو بكرٍ أيضًا عليهِ اسمَ الصحيحِ، وعلى كتابِ النَّسائيِّ. وذكرَ الحافظُ أبو طاهرٍ السِّلَفيُّ (٢) الكتبَ الخمسةَ (٣) وقالَ: «اتَّفَقَ على صِحَّتِها علماءُ الشرقِ والغربِ» (٤). وهذا تساهلٌ؛ لأنَّ فيها ما صرَّحُوا بكونِهِ ضعيفًا أو منكرًا أو نحوَ ذلكَ مِنْ أوصافِ الضعيفِ. وصرَّحَ أبو داودَ فيما قدَّمْنا روايتَهُ عنهُ بانقسامِ ما في كتابِهِ إلى صحيحٍ وغيرِهِ، والترمذيُّ مُصَرِّحٌ فيما (٥) في كتابِهِ بالتمييزِ بينَ الصحيحِ والحسَنِ. ثُمَّ إنَّ مَنْ سَمَّى الحسَنَ صحيحًا لا يُنكِرُ أنَّهُ دونَ الصحيحِ الْمُقَدَّمِ الْمُبَيَّنِ أوَّلًا، فهذا إذنْ اختلافٌ في العبارةِ دونَ المعنى، واللهُ أعلمُ."],[566,"النوع الثالث معرفة الضعيف من الحديث"],[567,"(٦)","",{"fn":"قال ابن حجر في نكته ١/ ٤٧٩: «إنما جعله يومئ إليه؛ لأن ذلك مقتضاه، وذلك أن كتاب الترمذي مشتمل على الأنواع الثلاثة، لكن المقبول فيه - وهو الصحيح والحسن - أكثر من المردود فحكم للجميع بالصحة بمقتضى الغلبة». وانظر: ١/ ٤٧٩ - ٤٨١ منه.\nبكسر السين وفتح اللام، وانظر في سبب هذه النسبة: الأنساب ٣/ ٢٩٧، ووفيات الأعيان ١/ ١٠٧، ونكت الزركشي ١/ ٣٨١، ونكت ابن حجر ١/ ٤٨٩، وتاج العروس ٢٣/ ٤٦٠.\nهي الكتب الستة (البخاري ومسلم وأبو داود والترمذي والنسائي، بدون ابن ماجة، إذ لم تضف إلى الخمسة إلاّ في القرن السادس الهجري.\nقد أجاب الحافظ العراقي عن قول السلفي هذا في نكته على ابن الصَّلاح: ٦٢، فقال: «إنما قال السلفي بصحة أصولها»، ثم قال: «ولا يلزم من كون الشيء له أصل صحيح أن يكون هو صحيحًا». وانظر: نكت الزركشي ١/ ٣٨٠، ونكت ابن حجر ١/ ٤٨١.\nساقطة من (جـ).\nانظر في الضعيف: معرفة علوم الحديث: ٥٨، والجامع لأخلاق الراوي وآداب السامع ٢/ ١٩٢، إرشاد طلاب الحقائق ١/ ١٥٣، والتقريب: ٤٩، والاقتراح: ١٧٧، والمنهل الروي: ٣٨، والخلاصة: ٤٤، والموقظة: ٣٣، واختصار علوم الحديث: ٤٤، والمقنع ١/ ١٠٣، شرح التبصرة ١/ ٢١٦، والمختصر: ١١٧، وفتح المغيث ١/ ٩٣، وألفية السيوطي: ١٩ - ٢١، والبحر الذي زخر ٣/ ١٢٨٣، وشرح السيوطي على ألفية العراقي ١٤١، وفتح الباقي ١/ ١١١، وتوضيح الأفكار ١/ ٢٤٦، وظفر الأماني: ٢٠٦، وقواعد التحديث: ١٠٨، وتوجيه النظر ٢/ ٥٤٦."}],[568,"كُلُّ حديثٍ لَمْ يَجتمعْ (١) فيهِ صفاتُ الحديثِ الصحيحِ، ولا صفاتُ الحديثِ الحسَنِ - المذكوراتُ فيما تقدَّمَ - فهو حديثٌ ضعيفٌ (٢). وأطنبَ أبو حاتِمِ بنِ حِبَّانَ البُسْتِيُّ في تقسيمِهِ، فبلغَ بهِ خمسينَ قسمًا إلاَّ واحدًا (٣)، وما ذكرتُهُ ضابطٌ جامعٌ لجميعِ ذلكَ."],[569,"وسبيلُ مَنْ أرادَ البَسْطَ (٤) أنْ يَعْمَدَ إلى صفةٍ مُعَيَّنةٍ منها؛ فيجعلَ ما عُدِمَتْ فيهِ مِنْ غيرِ أنْ يَخلُفَها جابرٌ -على حسبِ ما تقرَّرَ في نوعِ الحسَنِ-: قسمًا واحدًا، ثُمَّ ما عُدِمَتْ فيهِ تلكَ الصفةُ معَ صفةٍ أخرى معيَّنةٍ: قسمًا ثانيًا، ثمَّ ما عُدِمَتْ فيهِ معَ صفتينِ معيَّنَتَيْنِ: قسمًا ثالثًا، ...، وهكذا إلى أن يستوفيَ (٥) الصفاتِ المذكوراتِ جُمَعَ (٦)، ثُمَّ يَعودَ ويُعيِّنَ مِنَ الابتداءِ صفةً غيرَ التي عيَّنها أوَّلًا، ويجعلَ ما عُدِمَتْ فيهِ وَحْدَها قِسْمًا، ثُمَّ القسمَ الآخرَ ما عُدِمَتْ فيهِ مَعَ عدمِ صفةٍ أخرى، ولتكنِ الصفةُ الأخرى غيرَ الصفةِ الأولى المبدوءِ بها؛ لكونِ ذلكَ سبَقَ في أقسامِ عدمِ الصفةِ الأولى، وهكذا هَلُمَّ جَرًّا (٧) إلى آخرِ الصفاتِ.","",{"fn":"في (أ) و(م): «تجتمع».\nللعلماء مباحثات ومناقشات حول هذا التعريف، انظرها في: نكت الزركشي ١/ ٣٨٩، والتقييد والإيضاح: ٦٣، ونكت ابن حجر ١/ ٤٩١، والبحر الذي زخر ٣/ ١٢٨٣.\nقال ابن حجر في نكته ١/ ٤٩٢: «لم أقف على كلام ابن حبان في ذلك». وقال الزركشي في نكته ١/ ٣٩١: «أي: في أول كتابه في الضعفاء». قال ابن حجر مستدركًا على الزركشي في مقالته هذه ومشيرًا إلى عدم إصابته: «لم يصب في ذلك، فإن الذي قسمه ابن حبان في مقدمة كتاب الضعفاء له تقسيم الأسباب الموجبة لتضعيف الرواة، لا تقسيم الحديث الضعيف، ثُمَّ إنه أبلغ الأسباب المذكورة عشرين قسمًا لا تسعة وأربعين، والحاصل أن الموضع الذي ذكر ابن حبان فيه ذلك ما عرفنا مظنته، والله الموفق».\nقلنا: قد أطال في بسطها العراقي في شرح التبصرة ١/ ٢١٧، والبقاعي في النكت الوفية ٩٠ / أ.\nفي (أ): «تستوفي».\nفي (ب): «جميعًا»، وفي إحدى نسخ (ع): «جمعاء». وانظر: تاج العروس ٢٠/ ٤٥٩.\nهذا تعبير يقال لاستدامة الأمر واتِّصاله. يقال: كان عامًا أوَّل كذا وكذا وهَلُمَّ جَرًّا. وانظر في تفصيل اشتقاق هذا التعبير وانتصاب «جرًّا»: الزاهر ١/ ٤٧٦، ولسان العرب ٤/ ١٣١، ونكت الزركشي ١/ ٣٩٢، ونكت ابن حجر ١/ ٥٠٣، وتاج العروس ١٥/ ٤١٢، والمعجم الوسيط ١/ ١١٦."}],[570,"ثُمَّ ما عُدِمَ فيهِ جميعُ الصفاتِ هوَ القسمُ الأَخِرُ (١) الأرذَلُ. وما كانَ مِنَ الصِّفاتِ لهُ شروطٌ، فاعملْ في شروطِهِ نحوَ ذلكَ، فتتضاعفَ بذلكَ الأقسامُ."],[571,"والذي لهُ لقَبٌ خاصٌّ معروفٌ منْ أقسامِ ذلكَ: الموضوعُ، والمقلوبُ، والشاذُّ، والمعلَّلُ، والمضطربُ والمُرسلُ، والمنقطِعُ، والمُعضلُ - في أنواعٍ - سيأتي عليها الشرحُ إنْ شاءَ (٢) اللهُ تعالى."],[572,"والملحوظُ فيما نورِدُهُ مِنَ الأنواعِ: عمومُ أنواعِ علومِ (٣) الحديثِ لا خصوصُ أنواعِ التقسيمِ الذي فرَغْنا الآنَ مِنْ أقسامِهِ (٤)، ونسألُ اللهَ تبارك وتعالى تعميمَ النَّفْعِ بهِ في الدارينِ، آمينَ."],[573,"النوع الرابع معرفة المسند"],[574,"(٥)","",{"fn":"قال الحافظ العراقي في التقييد: ٦٣: «بقصر الهمز على وزن الفَخِذ، وهو بمعنى الأرذل». وقيل: بمد الهمز أيضًا. انظر تفصيل ذلك في: لسان العرب ٤/ ١٥، ونكت الزركشي ١/ ٣٩٣، والنكت الوفية: ١٧٦ / ب، وتاج العروس ١٠/ ٣٨، وتعليقنا على شرح التبصرة والتذكرة ١/ ٤١٤.\nسقطت من (م)، وهو خلل فاحش، أفسد النص وأتلف المعنى.\nسقطت من (جـ).\nفي (ع) هنا زيادة: «مفرقة»، ولم ترد في نسخنا الخطية أو المطبوعة. قال ابن حجر ١/ ٥٠٤: «هذا جواب عن سؤال مقدر، وهو: أنه ذكر في أول الكتاب أن الحديث ينقسم إلى ثلاثة أقسام، ثمَّ سمَّى الأقسام الثلاثة أنواعًا، ثمَّ ذكر بعد ذلك أشياء أخر سمَّاها أنواعًا، فأين صحة دعوى الحصر في الثلاثة؟ والجواب: بأن هذه الأنواع التي يذكرها بعد الثلاثة المراد بها أنواع علم الحديث لا أنواع أقسام الحديث. وحاصله: أن هذه الأنواع في الحقيقة ترجع إلى تلك الثلاثة: منها ما يرجع إلى أحدها. ومنها ما يرجع إلى المجموع، وذلك واضح، والله أعلم». قلنا: هذا استفاده ابن حجر ممّا علّقه الزركشي في نكته ١/ ٤٠٣.\nقال الزركشي في نكته ١/ ٤٠٥: «وهو مأخوذ من السند، وهو ما ارتفع وعلا عن سفح الجبل؛ لأن المسنِّد يرفعه إلى قائله، ويجوز أن يكون مأخوذًا من قولهم: فلان سند، أي: معتمد. فسمِّيَ الإخبار عن طريق المتن مسندًا؛ لاعتماد النقّاد في الصحة والضعف عليه، وفي أدب الرواية للحفيد: أسندت الحديث أسنده وعزوته أعزوه وأعزيه، والأصل في الحرف راجع إلى المسند وهو الدهر، فيكون معنى إسناد الحديث اتِّصاله في الرواية اتِّصال أزمنة الدهر بعضها ببعض. وحاصل ما حكاه المصنِّف في تعريفه ثلاثة أقوال: ="}],[575,"ذكرَ أبو بكرٍ الخطيبُ الحافظُ - رحمه الله - أنَّ المسندَ عِندَ أهلِ الحديثِ: هوَ الذي اتَّصلَ إسنادُهُ مِنْ راويهِ إلى مُنتهَاهُ، وأكثرُ مَا يستعملُ ذلكَ فِيْمَا جاءَ عنْ رسولِ اللهِ - صلى الله عليه وآله وسلم - دونَ مَا جاءَ عنِ الصحابةِ وغيرِهِم (١). وذكرَ أبو عمرَ بنُ عبدِ البرِّ الحافظُ (٢) أنَّ المسندَ: «مَا رُفِعَ إلى النَّبيِّ صَلَّى اللهُ عَلَيْهِ وآلِهِ وصَحْبِهِ وسَلَّمَ خَاصَّةً. وَقَدْ يكونُ متَّصِلًا، مثلُ: «مالكٍ، عنْ نافعٍ، عنِ ابنِ عمرَ، عنْ رسولِ اللهِ - صلى الله عليه وآله وسلم -»، وقدْ يكونُ منقطعًا، مثلُ: «مالكٍ، عنْ الزهريِّ، عنِ ابنِ عبَّاسٍ، عنْ رسولِ اللهِ - صلى الله عليه وآله وسلم -». فهذا مسندٌ؛ لأنَّهُ قدْ أُسْنِدَ إلى رسولِ اللهِ - صلى الله عليه وآله وسلم -، وهوَ منقطعٌ؛ لأنَّ الزُّهريَّ لَمْ يسمعْ مِنِ ابنِ عبَّاسٍ - رضي الله عنهم - (١).","",{"fn":"انظر: الكفاية (٥٨ ت - ٢١ هـ)، والجامع لأخلاق الراوي ٢/ ١٨٩. قال الزركشي ١/ ٤٠٦: «عبارة الخطيب في الكفاية: «إلا أن أكثر استعمالهم هذه العبارة فيما أسنده عن النبي - صلى الله عليه وآله وسلم - خاصة». انتهى. فشرط الإسناد لم يعتبر اتصال الإسناد فيه بأن يكون كل واحد من رواته سمعه ممن فوقه حتى ينتهي ذلك إلى آخره، وإن لم يبين فيه السماع، بل اقتصر على العنعنة».\nانظر: التمهيد ١/ ٢١."}],[576,"وحكى أبو عُمَرَ عنْ قومٍ أنَّ المسندَ لا يقعُ إلاَّ عَلَى مَا اتَّصلَ مرفوعًا إلى"],[577,"النبيِّ - صلى الله عليه وآله وسلم - (٢). قلتُ: وبهذا قَطَعَ الحاكمُ أبو عبدِ اللهِ الحافظُ ولَمْ يَذْكُرْ (٣) في كتابِهِ"],[578,"غيرَهُ (٤). فهذهِ أقوالٌ ثلاثةٌ مختلفةٌ (٥)، واللهُ أعلمُ (٦)."],[579,"النوع الخامس معرفة المتصل"],[580,"(٧)","",{"fn":"قال الزركشي في نكته ١/ ٤٠٧: «هذا القول صحّحه المحب الطبري في كتابه \" المعتصر \" الملخص من هذا الكتاب. وهو الظاهر من حال تصرف الأئمة المصنِّفينَ للمسندات، كأحمد بن حنبل، وابن أبي شيبة، والبزار، وغيرهم. وقال صاحب كتاب الوصول: إنه الأرجح؛ لعدم تداخل الصنفين، أي: المسند والمتصل. وحكى أبو عمر عن قوم أن المسند لا يقع إلا على ما اتصل مرفوعًا، هذا القول جزم به أبو الحسن بن الحصار في كتابه \" تقريب المدارك \"، وأبو عمرو عثمان بن سعيد المقرئ في جزء له جمعه في رسوم الحديث، وابن خلفون في المنتقى، وهو ظاهر كلام السمعاني في القواطع».\nالتمهيد ١/ ٢٥.\nفي (ب) و(جـ): «يذكره».\nمعرفة علوم الحديث ١٧.\nفي (م) هنا زيادة: «والقول الأول أعدل وأولى».\nعبارة: «والله أعلم» ليست في (جـ)، وفي (ب): «والله تعالى أعلم».\nقال البلقيني: «يخرج بذلك المرسل والمنقطع والمعضل والمعلق ونحوها». محاسن الاصطلاح: ١٢١. وقال الزركشي ١/ ٤١٠: «وقد يطلقونه على المنقطع مقيدًا، كقولهم: هذا متصل إلى سعيد، أو إلى الزهري، أو إلى مالك ونحوه». وانظر في المُتَصل والموصول: التمهيد ١/ ٢٣، وإرشاد طلاب الحقائق ١/ ١٥٦، والتقريب: ٥٠، والاقتراح: ١٩٥، والمنهل الروي: ٤٠، والخلاصة: ٤٦، والموقظة: ٤٢، واختصار علوم الحديث: ٤٥، والمقنع ١/ ١١٢، وشرح التبصرة والتذكرة ١/ ٢٢٧، ونزهة النظر: ٨٣، والمختصر: ١١٩، وفتح المغيث ١/ ١٠٢، وألفية السيوطي: ٢٤، وشرح السيوطي على ألفية العراقي: ١٤٥، وفتح الباقي ١/ ١٢١، وتوضيح الأفكار ١/ ٢٦٠، وظفر الأماني: ٢٢٦، وقواعد التحديث: ١٢٣."}],[581,"ويقالُ فيهِ أيضًا: الموصولُ (١)، ومُطلقُهُ يقعُ على المرفوعِ والموقوفِ وهو الذي اتَّصَلَ إسنادُهُ، فكانَ (٢) كُلُّ واحِدٍ مِنْ رواتِهِ قَدْ سَمِعَهُ ممَّنْ فَوقَهُ حَتَّى ينتهِيَ إلى منتهاهُ."],[582,"مثالُ المتَّصِلِ المرفوعِ مِنَ \" الموطَّأِ \": «مالكٌ، عنْ ابنِ شهابٍ، عنْ سالِمِ ابنِ"],[583,"عبدِ اللهِ، عنْ أبيهِ، عنْ رسولِ اللهِ - صلى الله عليه وآله وسلم -» (٣)، ومثالُ المتَّصِلِ الموقوفِ: «مالكٌ، عنْ نافعٍ، عنِ ابنِ عُمَرَ، عنْ عمرَ قولَهُ» (٤)، واللهُ أعلمُ."],[584,"النوع السادس معرفة المرفوع"],[585,"(٥)"],[586,"وهوَ ما أُضِيفَ إلى رسولِ اللهِ - صلى الله عليه وآله وسلم - خاصَّةً، ولا يَقَعُ مُطلقُهُ على غيرِ ذلكَ نحوُ الموقوفِ على الصحابةِ وغيرِهِم (٦). ويدخُلُ في المرفوعِ: المتصلُ، والمنقطِعُ، والمرسَلُ، ونحوُها، فهو والمسندُ عندَ قومٍ (٧) سواءٌ، والانقطاعُ والاتصالُ يَدخلانِ عليهِما جميعًا.","",{"fn":"قال الزركشي ١/ ٤١٠: «قلت: والموتصل، وهي عبارة الشافعي - رضي الله تعالى عنه - كما نقله البيهقي، وقال ابن الحاجب: في تصريفه: هي لغة الشافعي». وقال ابن حجر ١/ ٥١٠: «قلت: ويقال له: المؤتصل - بالفك والهمز - وهي عبارة الشافعي في الأم في مواضع. وقال ابن الحاجب في التصريف له: «هي لغة الشافعي، وهي عبارة عن ما سمعه كل راوٍ من شيخه في سياق الإسناد من أوله إلى منتهاه. فهو أعم من ... المرفوع». قلنا: انظر في إطلاق الشافعي: الأم ٤/ ١٤، ٦/ ١٠٣ و١٠٤، والرسالة: ٤٦٤ الفقرة (١٢٧٥)، وسنن البيهقي الكبرى ٨/ ١٢٥.\nفي (ب): «وكان»، وفي الشذا الفياح: «فكأنَّ» بتشديد النون.\nانظر: الموطأ (١٩٦) و(١١٩١) و(٢٦٣٥) و(٢٧٨٧) مثلًا.\nانظر: الموطأ (٧٦٧) مثلًا.\nانظر في المرفوع: الكفاية: (٥٨ ت، ٢١ هـ)، والتمهيد ١/ ٢٥، إرشاد طلاب الحقائق ١/ ١٥٧، والتقريب: ٥٠ - ٥١، والاقتراح: ١٩٥، والمنهل الروي: ٤٠، والخلاصة: ٤٦، والموقظة: ٤١، واختصار علوم الحديث: ٤٥، والمقنع ١/ ٧٣، وشرح التبصرة والتذكرة ١/ ٢٢٢، ونزهة النظر: ١٤٠، والمختصر: ١١٩، وفتح المغيث ١/ ٩٨، وألفية السيوطي: ٢١، وشرح السيوطي على ألفية العراقي: ١٤٣، وفتح الباقي ١/ ١١٦، وتوضيح الأفكار ١/ ٢٥٤، وظفر الأماني: ٢٢٧، وقواعد التحديث: ١٢٣.\nفي نسخة (جـ)، جاءت حاشية نصّها: «قال المؤلف: رأيت في كتاب الضعفاء لعلي بن المديني تسمية قول الحسن البصري قال رسول الله - صلى الله عليه وآله وسلم - مرفوعًا».\nكابن عبد البر كما تقدم في الكلام على المسند (ص: ١٣٣)."}],[587,"وعندَ قومٍ يفترقانِ في أنَّ (١) الانقطاعَ والاتصالَ يدخلانِ على المرفوعِ ولا يقعُ المسندُ إلاَّ على المتَّصِلِ المضافِ (٢) إلى رسولِ اللهِ - صلى الله عليه وآله وسلم -. وقالَ الحافظُ أبو بكرِ بنِ ثابتٍ: «المرفوعُ: ما أخبرَ فيهِ الصحابيُّ عنْ قولِ الرسولِ (٣) - صلى الله عليه وآله وسلم - أو فِعلِهِ» (٤). فخصَّصَهُ بالصحابةِ، فَيَخْرُجُ (٥) عنهُ مُرسَلُ التابعيِّ عنْ رسولِ اللهِ - صلى الله عليه وآله وسلم - (٦)."],[588,"قلتُ: ومَنْ جَعلَ مِنْ أهلِ الحديثِ: المرفوعَ في مقابلةِ المرسَلِ، فقدْ عَنَى"],[589,"بالمرفوعِ: المتصلَ، واللهُ أعلمُ."],[590,"النوع السابع معرفة الموقوف"],[591,"(٧)"],[592,"وهوَ ما يُروَى عنِ الصحابَةِ - رضي الله عنهم - مِنْ أقوالِهِم، أو أفعالِهِم (٨) ونَحْوِها، فيُوقَفُ عَلَيْهِم ولا يُتَجَاوَزُ بهِ إلى رسولِ اللهِ - صلى الله عليه وآله وسلم - (٩). ثُمَّ إنَّ منهُ ما يتَّصِلُ الإسنادُ فيهِ إلى الصحابيِّ فيكونُ مِنَ (١) الموقوفِ الموصولِ. ومنهُ ما لا يتَّصلُ إسنادُهُ فيكُونُ مِنَ الموقوفِ غيرِ الموصولِ، على حَسَبِ ما عُرِفَ مِثْلُهُ في المرفوعِ إلى رسولِ اللهِ - صلى الله عليه وآله وسلم -، واللهُ أعلمُ.","",{"fn":"ليست في (أ).\nسقطت من (ب).\nفي (ب): «قول رسول الله».\nالكفاية: (٥٨ ت - ٢١ هـ)\nفي (م): «فخرج».\nقال الزركشي ١/ ٤١١: «هذا فيه قصور بل يخرج عنه ما لم يكن فيه الصحابي مرسلًا كان أو غيره». وانظر: محاسن الاصطلاح: ١٢٢، ونكت ابن حجر ١/ ٥١١.\nانظر في الموقوف: معرفة علوم الحديث: ١٩، والكفاية: (٥٨ ت، ٢١ هـ)، والتمهيد ١/ ٢٥، والإرشاد ١/ ١٥٨، والتقريب: ٥١ - ٥٣، والاقتراح: ١٩٤، والمنهل الروي: ٤٠، والخلاصة: ٦٤، والموقظة: ٤١، واختصار علوم الحديث: ٤٥، والمقنع ١/ ١١٣، وشرح التبصرة والتذكرة ١/ ٢٢٩، ونزهة النظر: ١٥٤، والمختصر: ١٤٥، وفتح المغيث ١/ ١٠٣، وألفية السيوطي ٢١ - ٢٣، وشرح السيوطي على ألفية العراقي ١٤٦، وفتح الباقي ١/ ١٢٣، وتوضيح الأفكار ١/ ٢٦١، وظفر الأماني: ٣٢٥، وقواعد التحديث: ١٣٠.\nفي (أ) و(ب): «وأفعالهم».\nانظر: الكفاية (٥٨ ت، ٢١ هـ). قال الزركشي ١/ ٤١٢: «هذا التعريف غير صالح، إذ ليس كل ما يروى عن الصحابي من قوله موقوفًا، كقول عائشة - رضي الله عنها -: «فرضت الصلاة ركعتين ركعتين ...»، ولهذا احتج الشافعي بمثل هذا في الجديد وأعطاه حكم المرفوع، مع نصّه على أن قول الصحابي ليس بحجة»."}],[593,"وما ذكرناهُ مِنْ تخصيصِهِ بالصحابيِّ، فذلكَ إذا ذُكِرَ الموقوفُ مطلقًا، وقدْ يُستعملُ مقَيَّدًا في غيرِ الصحابيِّ (٢)، فيقالُ: «حديثُ كذا وكذا، وقفَهُ فلانٌ على عطاءٍ أو علَى طاوسٍ أو نحوِ هذا»، واللهُ أعلمُ (٣)."],[594,"وموجودٌ في اصطلاحِ الفقهاءِ الْخُراسانيينَ تعريفُ الموقوفِ باسمِ (٤) الأثرِ (٥)"],[595,"قالَ (٦) أبو القاسمِ الفُوْرَانيُّ (٧) - منهم - فيما بَلَغَنا عنهُ: الفقهاءُ يقولونَ: «الخبرُ:"],[596,"ما يُروى (٨) عنِ النبيِّ - صلى الله عليه وآله وسلم -، والأثَرُ: ما يُرْوى (٩) عنِ الصحابةِ - رضي الله عنهم -» (١٠».","",{"fn":"سقطت من (أ).\nهذا صريح في أن القيد لا يتقيد بالتابعي، بل يقال: موقوف على الثوري وعلى مالك وعلى الشافعي، ونحوه. أفاده الزركشي ١/ ٤١٧.\nعبارة: «والله أعلم» سقطت من (ع) والتقييد.\nفي (أ): «تعريفه باسم».\nقلنا: ورد ذلك أيضًا في كلام الشافعي. انظر: الرسالة الفقرات (٥٩٧) و(١٤٦٨).\nفي (أ): «وقال».\nهو القاضي أبو القاسم عبد الرحمان بن محمد بن أحمد الفوراني، توفي سنة (٤٦١ هـ). والفُوْرَاني - بضم الفاء وسكون الواو وفتح الراء وبعد الألف نون -: نسبة إلى جده فوران. انظر: الأنساب ٤/ ٣٨٥، ووفيات الأعيان ٣/ ١٣٢، والسير ١٨/ ٢٦٤، والتاج ١٣/ ٣٥١.\nفي (ب): «روي».\nكذلك.\nقال ابن حجر ١/ ٥١٣: «هذا قد وجد في عبارة الشافعي - رضي الله تعالى عنه - في مواضع، والأثر في الأصل: العلامة والبقية والرواية، ونقل النووي عن أهل الحديث أنهم يطلقون الأثر على المرفوع والموقوف معًا، ويؤيده تسمية أبي جعفر الطبري كتابه \"تهذيب الآثار\" وهو مقصور على المرفوعات وإنما يورد فيه الموقوفات تبعًا. وأما كتاب \" شرح معاني الآثار \" للطحاوي فمشتمل على المرفوع والموقوف - أيضًا - والله تعالى الموفق». وانظر: الرسالة للإمام الشافعي الفقرات (٥٩٧) و(١٤٦٨) - كما تقدمت قبل قليل الإشارة إليه -، ونكت الزركشي ١/ ٤١٧."}],[597,"النوع الثامن معرفة المقطوع"],[598,"(١)"],[599,"وهوَ غيرُ المنقطعِ الذي يأتي ذكرُهُ إنْ شاءَ اللهُ تعالى، ويقالُ في جمعِهِ: المقاطِيعُ والمقاطِعُ (٢)، وهوَ ما جاءَ عنِ التابعينَ موقوفًا عليْهِم مِنْ أقواِلهِم أو أفعالِهِمْ (٣). قال الخطيبُ أبو بكرٍ الحافظُ في \" جامِعِهِ \": «مِنَ الحديثِ: المقطوعُ» (٤)، وقالَ: «المقاطِعُ: هيَ الموقوفاتُ على التابعينَ» (٥)."],[600,"قلتُ: وقدْ وجدْتُ التعبيرَ بالمقطوعِ عنِ المنقطعِ غيرِ الموصولِ في كلامِ الإمامِ (٦) الشافعيِّ، وأبي القاسمِ الطبرانيِّ وغيرِهِما (٧)، واللهُ أعلمُ.","",{"fn":"انظر في المقطوع: الجامع لأخلاق الراوي ١/ ١٩١، وإرشاد طلاب الحقائق ١/ ١٦٦، والتقريب: ٥٣، والاقتراح: ١٩٤، والمنهل الروي: ٤٢، والخلاصة: ٦٥، واختصار علوم الحديث: ٤٦، والمقنع ١/ ١١٦، وشرح التبصرة والتذكرة ١/ ٢٣١، ونزهة النظر: ١٥٤، والمختصر: ١٣١، وفتح المغيث ١/ ١٠٥، وألفية السيوطي: ٢١ - ٢٣، وشرح السيوطي على ألفية العراقي: ١٤٦، وفتح الباقي ١/ ١٢٤، وتوضيح الأفكار ١/ ٢٤٩، وظفر الأماني: ٣٤٢، وقواعد التحديث: ١٣٠.\nوكلاهما جائز كما تقدّم في المساند والمسانيد. انظر: نكت الزركشي ١/ ٤٢٠، ومحاسن الاصطلاح: ١٢٥، ونكت ابن حجر ٢/ ٥١٤.\nقال الزركشي ١/ ٤٢١: «قلت: في إدخاله في أنواع الحديث تسامح كثير، فإن أقوال التابعين ومذاهبهم لا مدخل لها في الحديث، فكيف يكون نوعًا منه؟ نعم، يجئ هنا ما بُيِّنَ في الموقوف من أنه إذا كان ذلك لا مجال للاجتهاد فيه أن يكون في حكم المرفوع، وبه صرّح ابن العربي وادّعى أنه مذهب مالك، ولهذا أدخل عن سعيد بن المسيب: «صلاة الملائكة خلف المصلي». وقد نوَّهَ ابن حجر بفائدة كتابة المقاطيع في النكت ٢/ ٥١٤ فقال: «وذكر الخطيب أن الفائدة في كتابه المقاطيع ليتخير المجتهد من أقوالهم ولا يخرج عن جملتهم، والله أعلم».\nالجامع لأخلاق الراوي ٢/ ١٨٨ عقب (١٧٥١)، بتصرف.\nالجامع لأخلاق الراوي ٢/ ١٩١ عقب (١٥٧٧)، بتصرف. وورد في (ع) بعد كلام الخطيب عبارة: «والله أعلم»، ولم ترد في نسختنا الخطية ولا في (م)، وهي ثابتة في التقييد.\nليست في (ب).\nقال ابن حجر ٢/ ٥١٤: «عنى به الدارقطني والحميدي، فقد وجد التعبير في كلامهما بالمقطوع في مقام المنقطع. وأفاد شيخنا - أي: العراقي-في منظومته: أنه وجد التعبير بالمنقطع في كلام البرديجي في مقام المقطوع على عكس الأول ...». وانظر: شرح التبصرة والتذكرة ١/ ٢٣١، وتدريب الراوي ١/ ١٩٤."}],[601,"تفريعات"],[602,"أحدُها: قولُ الصَّحابيِّ: «كُنَّا نَفْعَلُ كذا أو كنَّا نقولُ كذا» (١) إنْ لَمْ يُضِفْهُ إلى زمانِ رسولِ اللهِ (٢) - صلى الله عليه وآله وسلم - فهوَ مِنْ قبيلِ الموقوفِ، وإنْ أضافَهُ إلى زمانِ رسولِ اللهِ - صلى الله عليه وآله وسلم -، فالذي قَطَعَ بهِ أبو عبدِ اللهِ بنُ البَيِّعِ (٣) الحافظُ وغيرُهُ مِنْ أهلِ الحديثِ وغيرِهِم أنَّ ذلكَ مِنْ قبيلِ المرفوعِ (٤)."],[603,"وبَلَغَني عَنْ أبي بكرٍ البَرْقانيِّ أنَّهُ سألَ أبا بكرٍ الإسماعيليَّ الإمامَ عنْ ذلكَ فأنكرَ كونَهُ مِنَ المرفوعِ. والأوَّلُ هوَ الذي عَليْهِ (٥) الاعتمادُ؛ لأنَّ ظاهرَ ذلكَ مُشْعِرٌ بأنَّ رسولَ اللهِ - صلى الله عليه وآله وسلم - اطَّلَعَ على ذلكَ وقرَّرَهُم عليهِ، وتقريرُهُ أحدُ وجوهِ السُّنَنِ المرفوعةِ؛ فإنَّها أنواعٌ منها: أقوالُهُ - صلى الله عليه وآله وسلم -، ومنها: أفعالُهُ (٦)، ومنها: تقريرُهُ وسكوتُهُ عنِ الإنكارِ بعدَ اطِّلاعِهِ. ومِنْ هذا القبيلِ قولُ الصحابيِّ: «كُنَّا لا نرى بأسًا بكذا ورسولُ اللهِ - صلى الله عليه وآله وسلم - فِيْنا، أو كانَ يقالُ: كذا وكذا على عهدِهِ، أو كانُوا يفعلونَ: كذا وكذا في حياتِهِ - صلى الله عليه وآله وسلم -». فكلُّ ذلكَ وشبهُهُ مرفوعٌ مُسْنَدٌ مُخَرَّجٌ في كتبِ المساندِ (١).","",{"fn":"قال الزركشي ١/ ٤٢١ - ٤٢٣: «حاصله: حكاية قولين: الوقف مطلقًا، والتفصيل بأن تضيفه إلى زمان النبي - صلى الله عليه وآله وسلم - أو لا، وأهمل مذاهب: أحدها: أنه مرفوع مطلقًا، وبه قال الحاكم ورجّحه من الأصوليين الإمام الرازي. وقال ابن الصباغ في العدة: إنه الظاهر، ومثّله بقول عائشة: «كانت اليد لا تقطع في الشيء التافه» وحكاه النووي في شرحه على البخاري والوسيط عن ظاهر كلام كثير من المحدّثين والفقهاء، وقال: وهو قوي، فإن ظاهره أنه فعله على وجه يحتج به، ولا يكون إلا برفعه. والثاني: التفصيل بين أن يكون ذلك الفعل مما لا يخفى غالبًا فمرفوع، وإلاّ فموقوف، وبه قطع الشيخ أبو إسحاق وغيره، حكاه النووي في أوائل شرح مسلم. وقال غيره: أما إذا كان في القصة اطِّلاعه - صلى الله عليه وآله وسلم - فلا شكَّ في رفعه، كقول ابن عمر: «كنا نقول ورسول الله - صلى الله عليه وآله وسلم - حيٌّ: أفضل هذه الأمة بعد نبيها أبو بكر وعمر وعثمان ويسمع ذلك رسول الله - صلى الله عليه وآله وسلم - فلا ينكره». رواه الطبراني في المعجم الكبير، وأصله في الصحيح. والثالث: إن ذكره الصحابي في معرض الحجة، حمل على الرفع، وإلاّ فعلى الوقف، حكاه القرطبي في أصوله». وانظر: التقييد والإيضاح ٦٦، ونكت ابن حجر ٢/ ٥١٥.\nفي (ب): «النبي».\nبفتح الباء وكسر الياء المشددة، بعدها عين مهملة. ويقال له أيضًا: ابن البَيَّاع، وهذه اللفظة تقال لمن يتولى البياعة والتوسط في الخانات بين البائع والمشتري من التجار للأمتعة. انظر: الأنساب ١/ ٤٤٨، ووفيات الأعيان ٤/ ٢٨١، وسير أعلام النبلاء ١٧/ ١٦٣، والتاج ٢٥/ ٣٦٨.\nانظر: معرفة علوم الحديث ٢٢.\nعبارة: «الذي عليه» ليست في (م).\nقوله: «ومنها أفعاله» ساقطة من (م)."}],[604,"وذكرَ الحاكمُ أبو عبدِ اللهِ فيما رُوِّيْناهُ عَنِ المغيرةِ بنِ شُعْبَةَ قالَ: «كانَ أصحابُ رسولِ اللهِ - صلى الله عليه وآله وسلم - يَقْرَعُونَ بابَهُ بالأظافيرِ» (٢): أنَّ هذا يتوهَّمُهُ مَنْ ليسَ مِنْ أهلِ الصَّنْعَةِ مُسْنَدًا - يعني: مرفوعًا - لِذِكْرِ رسولِ اللهِ - صلى الله عليه وآله وسلم - فيهِ وليسَ بِمُسْنَدٍ بلْ هوَ موقوفٌ (١). وذكرَ الخطيبُ أيضًا نحوَ ذلكَ في جامعِهِ (٢).","",{"fn":"في (ب) و(جـ) و(م): «المسانيد»، وفي (أ): «المسانيد» وكتب فوقها: «المساند».\nرواه الحاكم في معرفة علوم الحديث: ١٩، ومن طريقه البيهقي في المدخل: ٣٨١ (٦٥٩) من طريق محمد بن أحمد الزيبقي البصري، عن زكريا بن يحيى المنقري، عن الأصمعي، عن كيسان مولى هشام بن حسان، عن محمد بن حسان، عن محمد بن سيرين، عن المغيرة، به. قلنا: الزيبقي لم نقف على حاله، لكن ذكره ابن ماكولا في الإكمال ٤/ ٢٢٨ من غير أن يذكر فيه جرحًا أو تعديلًا. والمنقري: ذكره ابن حبان في ثقاته ٨/ ٢٥٥، وكذا الخطيب في تاريخه ٨/ ٤٥٩ من غير أن يذكر فيه جرحًا أو تعديلًا. وكيسان - مولى هشام بن حسان -: ذكره البخاري في التاريخ الكبير ٧/ ٢٣٥، وابن أبي حاتم ٦/ ١٦٦، ولم يذكر فيه جرحًا ولا تعديلًا. وذكره ابن حبان في الثقات ٧/ ٣٥٨. ومحمد بن حسان، قال الحاكم فيه: حسن الحديث. هكذا نقل السخاوي في فتح المغيث ١/ ١٣٨. ونقل الزركشي عنه ١/ ٤٢٦ أنه قال: «غريب الحديث». ونقل البيهقي عنه أنه قال: «عزيز الحديث». المدخل (٦٥٩). وقد روي من حديث أنس، أخرجه البخاري في الأدب المفرد (١٠٨٠)، والخطيب في الجامع ١/ ١٦١ (٢٢٣)، من طريق مالك بن إسماعيل، عن المطلب بن زياد، عن أبي بكر بن عبد الله الأصبهاني، عن محمد بن مالك بن المنتصر، عن أنس، به. قلنا: المطلب بن زياد الكوفي: وثَّقه ابن معين وأحمد، وقال أبو حاتم: لا يحتج به، وقال ابن سعد: ضعيف. ميزان الاعتدال ٤/ ١٢٨، وقال ابن حجر: صدوق ربما وهم. التقريب (٦٧٠٩). وأبو بكر بن عبد الله الثقفي الأصبهاني: قال الذهبي فيه: أصبهاني غير معروف، روى عنه المطلب بن زياد فقط. ميزان الاعتدال ٤/ ٥٠٦. وقال ابن حجر: مجهول، من السابعة، ووهم مَن زعم أنه يعقوب القمي. التقريب (٧٩٧٥). ومحمد بن مالك بن المنتصر: قال الذهبي: لا يعرف. ميزان الاعتدال ٤/ ٢٣. وقال ابن حجر: مجهول. التقريب (٦٢٦٠). وذكره ابن حبان في ثقاته ٥/ ٣٧١، كما هي عادته في توثيق المجاهيل، ولكنه شكك في سماعه من أنس، فقال معرفًا به: يروي عن أنس بن مالك إن كان سمع منه. ورواه الخطيب في جامعه ١/ ١٦٢ (٢٢٤) من طريق حميد بن الربيع، عن المطلب بن زياد، عن عمر بن سويد، عن أنس بن مالك، به. ="}],[605,"قلتُ: بلْ هوَ مرفوعٌ كما سبقَ ذِكْرُهُ، وهوَ بأنْ يكونَ مرفوعًا أحرَى؛ لكونِهِ أحرَى باطِّلاعِهِ - صلى الله عليه وآله وسلم - عليهِ (٣)، والحاكمُ مُعْتَرِفٌ بكونِ ذلكَ مِنْ قبيل المرفوعِ، وقدْ كنَّا عَدَدْنا هذا فيما أخذناهُ عليهِ. ثُمَّ تأوَّلناهُ لهُ على أنَّهُ أرادَ أنَّهُ ليسَ بِمُسْندٍ لفظًا، بلْ هوَ موقوفٌ لفظًا، وكذلكَ سائرُ ما سبقَ موقوفٌ لفظًا، وإنَّما جعلناهُ مرفوعًا مِنْ حيثُ المعنى، واللهُ أعلمُ."],[606,"الثاني: قولُ الصحابيِّ: «أُمِرْنا بكذا (٤) أو نُهِيْنا عَنْ كذا» مِنْ نوعِ المرفوعِ والمسنَدِ عندَ أصحابِ الحديثِ وهوَ قولُ أكثرِ أهلِ العلمِ (٥)، وخالفَ في ذلكَ فريقٌ منهم أبو بكرٍ الإسماعيليُّ (١)، والأوَّلُ هوَ (٢) الصحيحُ؛ لأنَّ مطلقَ ذلكَ ينصرفُ بظاهرِهِ إلى مَنْ إليهِ الأمرُ والنَّهْيُ، وَهُوَ رسولُ الله - صلى الله عليه وآله وسلم -، وهكذا قَوْل الصحابيِّ «مِنَ السُّنَّةِ كَذَا» (٣)، فالأصحُّ أنَّهُ مُسنَدٌ مرفوعٌ؛ لأنَّ الظاهرَ أنَّهُ لا يريدُ بهِ إلاَّ سُنَّةَ رسولِ اللهِ - صلى الله عليه وآله وسلم - وما يجبُ اتِّباعُهُ (٤). وكذلكَ قول أنسٍ - رضي الله عنه -: «أُمِرَ بلالٌ أنْ يَشْفَعَ الأَذانَ ويُوتِرَ الإِقامةَ» (٥)، وسائرُ ما جانسَ ذلكَ، ولا فرْقَ بينَ أنْ يقولَ ذلكَ في زمانِ رسولِ اللهِ - صلى الله عليه وآله وسلم -، وبعدَهُ (٦) - صلى الله عليه وآله وسلم - (٧)، واللهُ أعلمُ (١).","",{"fn":"قال الزركشي ١/ ٤٢٥: «تبع الحاكم في ذلك أبو عمرو عثمان بن سعيد المقرئ، وحكاه المصنف عن الخطيب أيضًا».\nقال البلقيني في محاسنه: ١٢٧: «ما ذكر عن الخطيب أنه ذكر في \" جامعه \" نحو ما ذكر الحاكم لم أقف عليه في \" جامع الخطيب \" فلينظر. نعم وجدت في \" جامع الخطيب \" حديث القرع بالأظافير من حديث «أنس» ولم يتعرض لقوله موقوفًا». قلنا: بل هو في جامع الخطيب ١/ ٢٩١ عقب (١٨٩٠). وانظر: نكت الزركشي ١/ ٤٢٥، ونكت ابن حجر ٢/ ٥١٨.\nسقطت من (جـ).\nانظر: نكت الزركشي ١/ ٤٢٦.\nنسب إليهم الخطيب في الكفاية: (٥٩٢ ت-٤٢١هـ)، والنووي في المجموع ١/ ٥٩، والآمدي في الإحكام ٢/ ٨٧، والأسنوي في نهاية السول ٣/ ١٨٧، وابن السبكي في الإبهاج ٢/ ٣٢٩.\nوكذلك أبو بكر الصيرفي من الشافعية، وأبو الحسن الكرخي والرازي من الحنفية، وابن حزم والغزالي وجماعة من الأصوليين، وأكثر مالكية بغداد، وحكاه إمام الحرمين عن المحققين، وذكر الزركشي أنه قول إمام الحرمين، بل حكى ابن فورك وسليم الرازي وابن القطان والصيدلاني: أنه الجديد من مذهب الشافعي وكذا نسبه المازري إلى أحد قولي الشافعي. انظر: البرهان ١/ ٦٤٩، والمنخول: ٢٧٨، والتبصرة في أصول الفقه: ٣٣١، وإحكام الأحكام ٢/ ٨٧، والإبهاج ٢/ ٣٢٨، والبحر المحيط ٤/ ٣٧٥، وشرح التبصرة والتذكرة ١/ ٢٣٥، ونكت ابن حجر ٢/ ٥٢٣، وشرح السيوطي: ١٤٩، وهو الخلاف نفسه الذي يأتي في قول الصحابي: «من السنة كذا ...». وانظر: نكت ابن حجر ٢/ ٥٢٠.\nليست في (أ).\nانظر: نكت الزركشي ١/ ٤٢٨، ونكت ابن حجر ٢/ ٥٢٣.\nقال الحاكم: «وقد أجمعوا على أن قول الصحابي: سنة: حديث مسند». المستدرك ١/ ٣٥٨. وقال البيهقي: «لا خلاف بين أهل النقل أن الصحابي - رضي الله عنه - إذا قال: أُمِرنا، أو نُهِينا، أو من السنة كذا، أنه يكون حديثًا مسندًا». نكت ابن حجر ٢/ ٥٢٢.\nأخرجه الطيالسي (٢٠٩٥)، وعبد الرزاق (١٧٩٤)، وابن أبي شيبة ١/ ٢٠٥، وأحمد ٣/ ١٠٣ و١٨٩، والدارمي (١١٩٦) و(١١٩٧)، والبخاري ١/ ١٥٧ (٦٠٣)، و١/ ١٥٨ (٦٠٦)، ومسلم ٢/ ٢ (٣٧٨)، وأبو داود (٥٠٨)، وابن ماجه (٧٢٩) والترمذي (١٩٣)، والنسائي ٢/ ٣، وأبو يعلى (٢٧٩٢)، وابن خزيمة (٣٦٦)، وأبو عوانة ١/ ٣٢٧، والطحاوي في شرح المعاني ١/ ١٣٢، وابن حبان (١٦٧٥)، والدارقطني ١/ ٢٣٩، والحاكم ١/ ١٩٨، والبيهقي ١/ ٣٩٠، والبغوي (٤٠٣) من طرق عن أبي قلابة، عن أنس.\nفي (ع): «أو بعده».\nقال الزركشي ١/ ٤٣١: «قلت: يقتضيه تساوي الأمرين، وهذا صحيح بالنسبة إلى أصل الاحتجاج إلاَّ أنهما يتفاوتان في القوة، فإنه يحتمل أن يكون الآمر والناهي من أدرك الخلفاء؛ لكن احتمال إرادته النبي - صلى الله عليه وآله وسلم - أظهر، قلت: والخلاف في هذا قريب منه في الذي قبله. فائدة: ويلتحق بقول الصحابي «من السنة كذا»: «لا تلبسوا علينا سنة نبينا». كما رواه أبو داود عن عمرو بن العاص في عدة أم الولد. وقوله: «أصبت السنة»، كما رواه الدارقطني عن عمر في المسح على الخفين، وكذا قوله: «سنة أبي القاسم - صلى الله عليه وآله وسلم -» في حديث ابن عباس في متعة الحاج. وأقربها للرفع: «سنة أبي القاسم»، ثمَّ: «ولا تلبسوا»، ثمَّ: «أصبت السنة». وأما حديث أبي هريرة في الخارج من المسجد بعد الأذان: «أما هذا فقد عصى أبا القاسم»، وقوله: «من لم يجب الدعوة فقد عصى الله= =ورسوله»، فحكى المنذري عن بعضهم أنه موقوف، وذكر ابن عبد البر أنه مسند عندهم، قال ولا يختلفون في هذا وذاك أنهما مسندان مرفوعان» ويلتحق به قول عمار في صوم يوم الشك». وانظر: محاسن الاصطلاح: ١٢٨."}],[607,"الثالثُ: ما قِيلَ مِنْ أنَّ تفسيرَ الصحابيِّ (٢) حديثٌ مسندٌ فإنَّما ذلكَ في تفسيرٍ"],[608,"يتعلَّقُ بسببِ نزولِ آيةٍ يُخبرُ بهِ الصحابيُّ أو نحوِ ذلكَ (٣) كقولِ جابرٍ - رضي الله عنه -: «كانتْ اليهودُ تقولُ: مَنْ أتى امرأتَهُ مِنْ دُبُرِها في قُبُلِها جاءَ الولدُ أحولَ؛ فأنزلَ اللهُ عز وجل"],[609,"﴿نِسَاؤُكُمْ حَرْثٌ لَكُمْ (٤) ... الآيةَ﴾ (٥) فأمَّا سائرُ تفاسيرِ الصحابةِ الَّتِي لا تشتملُ عَلَى إضافةِ شيءٍ (١) إلى رسولِ اللهِ - صلى الله عليه وآله وسلم - فمعدودةٌ في (٢) الموقوفاتِ (٣)، واللهُ أعلمُ.","",{"fn":"عبارة: «والله أعلم» ليست في (ع)، وهي من جميع النسخ المعتمدة.\nقال الزركشي ١/ ٤٣٤: «ما اختاره في تفسير الصحابي سبقه إليه الخطيب وكذلك الأستاذ أبو منصور البغدادي، قال: إذا أخبر الصحابي عن سبب وقع في عهد النبي - صلى الله عليه وآله وسلم - أو أخبر عن نزول آية فيه فذلك مسند، لكن قال الحاكم في المستدرك: تفسير الصحابي الذي شهد الوحي والتنزيل عند البخاري ومسلم حديث مسند». والتحقيق أن يقال: إن كان ذلك التفسير مما لا مجال للاجتهاد فيه فهو في حكم المرفوع، وإن كان يمكن أن يدخله الاجتهاد فلا يحكم عليه بالرفع. ومما أهمله المصنف ويليق ذكره هنا تأويل الصحابي الخبر على أحد محتمليه، وقال الشيخ أبو إسحاق في اللمع: إذا احتمل اللفظ أمرين احتمالًا واحدًا فصرفه إلى أحدهما - كما روي عن عمر أنه حمل قوله - صلى الله عليه وآله وسلم -: «الذهب بالذهب ربًا إلا هاء وهاء» على القبض في المجلس - فقد قيل: يقبل؛ لأنه أعرف بمعنى الخطاب. وفيه نظر عندي». انتهى. وقال شيخه القاضي أبو الطيب: يجب قبوله على المذهب كتفسير ابن عمر التفرق بالأبدان دون الأقوال». قلنا: فصَّل ابن حجر في نكته ٢/ ٥٣٠ هذا الأمر تفصيلًا أوسع على نحو ما قال الزركشي.\nأطلق كثير ممن صنّف في علوم الحديث عن الحاكم القول بأنه يرى تفسير الصحابي مرفوعًا، وهذه الدعوى يسعفها كلامه في المستدرك ١/ ٢٧ و١٢٣ و٥٤٢ وغيرها. لكن الذي ينبغي التنبيه عليه أن الحاكم ليس من مذهبه الإطلاق الذي حكى عنه، وإنما خصّه بأسباب النزول - كَمَا اختاره ابن الصَّلاح هنا - فَقَالَ في مَعْرِفَة علوم الحَدِيْث: ٢٠ بعد أن روى حديثًا في التفسير عن أبي هريرة: «فأما ما نقول في تفسير الصحابي: مسند، فإنما نقوله في غير هذا النوع»، ثم ساق حديثًا عن جابر في سبب نزول آية، فقال: «هذا الحديث وأشبهه مسندة عن آخرها وليست بموقوفة، فإن الصحابي الذي شهد الوحي والتنزيل فأخبر عن آية من القرآن أنها نزلت في كذا وكذا، فإنه حديث مسند». وانظر: تدريب الراوي ١/ ١٩٠، وشرح السيوطي: ١٥٤.\nالبقرة: ٢٢٣.\nأخرجه الحميدي (١٢٦٣)، وابن أبي شيبة ٤/ ٢٢٩، والدارمي (٢٢٢٠)، والبخاري ٦/ ٣٦ (٤٥٢٨)، ومسلم ٤/ ١٥٦ (١٤٣٥)، وأبو داود (٢١٦٣)، وابن ماجه (١٩٢٥)، والترمذي (٢٩٧٨)، والنسائي في تفسيره (٥٨) و(٥٩)، وأبو يعلى (٢٠٢٤)، والطحاوي ٣/ ٤٠، وفي شرح المشكل (٦١١٩)، وابن حبان (٤١٦٦). كلهم من طرق عن جابر، به."}],[610,"الرابعُ: مِنْ قبيلِ المرفوعِ، الأحاديثُ التي قِيْلَ في أسانيدِها عِندَ ذِكْرِ الصحابيِّ:"],[611,"«يَرْفُعُ الحديثَ، أو يبْلُغُ بهِ، أو يَنْمِيْهِ (٤)، أو رِوَايَةً»، مثالُ ذلكَ: «سُفيانُ بنُ عُيينةَ، عَنْ أبي الزِّنادِ، عنِ الأعرجِ، عنْ أبي هريرةَ، رِوَايةً: «تُقَاتِلُونَ قَوْمًا صِغَارَ الأعيُنِ ... الحديثَ» (٥). وبهِ «عنْ أبي هريرةَ يَبْلُغُ بهِ، قالَ: «النَّاسُ تَبَعٌ لِقُرَيْشٍ ... الحديثَ» (٦)، فكلُّ ذلكَ وأمثالُهُ كِنايةٌ عنْ رفعِ الصحابيِّ الحديثَ إلى رسولِ اللهِ - صلى الله عليه وآله وسلم -، وحكمُ ذلكَ عندَ أهلِ العلمِ (٧) حُكْمُ المرفوعِ صريحًا."],[612,"قلتُ: وإذا قالَ الراوي عَنِ التابِعيِّ: «يَرْفُعُ الحديثَ أو يَبْلُغُ بهِ»، فذلكَ أيضًا مرفوعٌ، ولكنَّهُ مرفوعٌ مرسَلٌ (٨)، واللهُ أعلمُ.","",{"fn":"أي: لا حكمًا ولا قولًا. أفاده البقاعي في نكته ١٠٦ أ.\nفي (جـ): «من».\nفي (ب): «الموقوف».\nقال السخاوي في فتح المغيث ١/ ١٢٠: «الاصطلاح في هذه اللفظة موافق للغة، قال أهلها: نميت الحديث إلى غيري نميًا: إذا أسندته ورفعته». وانظر: القاموس المحيط ٤/ ٣٩٧.\nأخرجه الحميدي (١١٠١)، وابن أبي شيبة ٥/ ٩٢، وأحمد ٢/ ٥٣٠، والبخاري ٤/ ٥٢ (٢٩٢٨) و٤/ ٢٣٨ (٣٥٨٧)، ومسلم ٨/ ١٨٤ (٢٩١٢)، وابن ماجه (٤٠٩٧)، والبيهقي ٩/ ١٧٥، والبغوي (٤٢٤٢).\nأخرجه الحميدي (١٠٤٤) و(١٠٤٥)، وأحمد ٢/ ٢٤٢ و٢٥٧ و٤١٨، والبخاري ٤/ ٢١٧ (٣٤٩٥)، ومسلم ٦/ ٢ (١٨١٨). قال النووي في الإرشاد ١/ ١٦٤: «فكل هذا وشبهه كناية عن رفع الحديث إلى رسول الله - صلى الله عليه وآله وسلم - وحكمه عند أهل العلم حكم المرفوع صريحًا».\nعبارة: «حكم ذلك عند أهل العلم» ساقطة من (جـ).\nفيما مضى من كلام ابن الصلاح، حاصله أنه ذكر فيما يتعلق بالصحابي أربع مسائل: الأولى: قولهُ: كنا نفعل كذا، أو كانوا يفعلون كذا ونحوها. الثانية: قوله: أُمِرنا بكذا ونحوه. الثالثة: قوله: مِنَ السُّنَّةِ كذا. الرابعة: يرفعه ويبلغ به ونحوها. ولَمَّا انتقل إلى ما يتعلق بالتابعي لم يذكر إلا حكم المسألة الرابعة فحسب، فأحببنا أن ننبّه على حكم ما سكت عنه: فأمّا المسألة الأولى: إذا قال التابعي: كنا نفعل؛ فليس بمرفوع قطعًا. ثمّ هَلْ لَهُ حكم المَوْقُوْف؟ إن لم يضفه إلى زمن الصحابة فليس بمرفوع بل هو مقطوع، وإن أضافه ففيه الاحتمالان. ="}],[613,"النوع التاسع معرفة المرسل"],[614,"(١)"],[615,"وصورَتُهُ (٢) التي لا خلافَ فيها حديثُ التابعيِّ الكبيرِ (٣) الذي لَقِيَ جماعةً مِنَ الصحابةِ وجالسَهُمْ، كـ: عُبَيْدِ اللهِ بنِ عَدِيِّ بنِ الخِيَارِ (٤)، ثُمَّ سعيدِ بنِ المسَيِّبِ (١) وأمثالِهما إذا قالَ: «قالَ رسولُ اللهِ - صلى الله عليه وآله وسلم -». والمشهورُ التَّسويةُ بينَ التابعينَ أجمعينَ في ذلكَ (٢) - رضي الله عنهم -، ولهُ صورٌ اختُلِفَ فِيْهَا أهِيَ مِنَ المرسَلِ أمْ لا؟","",{"fn":"انظر في المُرسَل: معرفة علوم الحديث: ٢٥، والكفاية: (٥٨ ت، ٢١ هـ)، والتمهيد ١/ ١٩، وجامع الأصول ١/ ١١٥، وإرشاد طلاب الحقائق ١/ ١٦٧ - ١٧٩، والمجموع شرح المهذب ١/ ٦٠، والاقتراح: ١٩٢، والتقريب: ٥٤ - ٥٧، والمنهل الروي: ٤٢، والخلاصة: ٦٥، والموقظة: ٣٨، وجامع التحصيل: ٢٣ وما بعدها، واختصار علوم الحديث: ٤٧، والبحر المحيط ٤/ ٤٠٣، والمقنع ١/ ١٢٩، وشرح التبصرة والتذكرة ١/ ٢٥٦، ونزهة النظر: ١٠٩، والمختصر: ١٢٨، وفتح المغيث ١/ ١٢٨، وألفية السيوطي: ٢٥ - ٢٩، وشرح السيوطي على ألفية العراقي: ١٥٩، وفتح الباقي ١/ ١٤٤، وتوضيح الأفكار ١/ ٢٨٣، وظفر الأماني: ٣٤٣، وقواعد التحديث: ١٣٣.\nللعلماء في تعريف المرسل وبيان صوره مناقشات، انظرها في: نكت الزركشي ١/ ٤٣٩، ومحاسن الاصطلاح: ١٣٠، والتقييد والإيضاح: ٧٠، وشرح التبصرة والتذكرة ١/ ٣٥٦، ونكت ابن حجر ٢/ ٥٤٠، والبحر الذي زخر: ١١٣ أ.\nقال ابن حجر ٢/ ٥٤٣: «ولم أر تقييده بالكبير صريحًا عن أحد، لكن نقله ابن عبد البر عن قوم». انظر: التمهيد ١/ ٢٠ - ٢١، وفتح المغيث ١/ ١٢٩.\nنقل الزركشي ١/ ٤٤١ عن بعضهم اعتراضهم على ابن الصلاح في تمثيله بابن الخيار؛ لأن جماعة ممن صنّف في الصحابة ذكره فيهم، كابن منده وابن حبان وأبي عمر. قلنا: ابن حبان ذكره في ثقاته ٣/ ٢٤٨ ضمن طبقات الصحابة؛ ولكنه أعاد ذكره في ٥/ ٦٤ في طبقات التابعين إشارة إلى وجود الخلاف الحاصل فِيهِ. ="}],[616,"إحداها (٣): إذا انقطعَ الإسنادُ قبلَ الوصولِ إلى التَّابِعيِّ (٤) فكانَ فيهِ روايةُ راوٍ لَمْ يسمَعْ مِنَ المذكورِ فوقَهُ، فالذي قَطَعَ بهِ الحاكمُ الحافظُ أبو عبدِ اللهِ (٥) وغيرُهُ مِنْ أهلِ الحديثِ أنَّ ذلكَ لا يُسمَّى مُرسَلًا، وأنَّ الإرسالَ مخصوصٌ بالتابعينَ، بلْ إنْ كانَ (٦) مَنْ سَقَطَ ذِكْرُهُ قبلَ الوصولِ إلى التابعيِّ (٧) شخصًا واحدًا سُمِّيَ مُنقَطِعًا فحسْبُ، وإنْ كانَ أكثرَ مِنْ واحدٍ سُمِّيَ مُعضَلًا، ويُسمَّى أيضًا منقطعًا، وسيأتي مثالُ ذلكَ إنْ شاءَ اللهُ تعالى.","",{"fn":"بكسر الياء وفتحها، جاء في القاموس وشرحه تاج العروس ٣/ ٩٠: «هو كمحدِّث: والد الإمام التابعي الجليل سعيد، له صحبة، روى عنه ابنه، ويفتح، ويحكون عنه أنه كان يقول: سيَّب اللهُ مَنْ سَيَّبَ أبي، والكسر حكاه عياض وابن المديني ...».\nانظر: جامع التحصيل: ٢٣ - ٣٢، ونكت ابن حجر ٢/ ٥٤٢ - ٥٥٨.\nفي (ب): «احدها».\nقال العراقي في التقييد: ٧١: «قوله: «قبل الوصول إلى التابعي» ليس بجيد، بل الصواب: قبل الوصول إلى الصحابي، فإنه لو سقط التابعي أيضًا كان منقطعًا لا مرسلًا عند هؤلاء، ولكن هكذا وقع في عبارة الحاكم فتبعه المصنّف».\nانظر: معرفة علوم الحديث ٢٦.\nفي (ع) هنا زيادة: «أكثر»، ولم ترد في شيء من النسخ الخطية أو (م) أو التقييد.\nفي (ب): «التابع»."}],[617,"والمعروفُ في الفقهِ وأصولِهِ أنَّ كُلَّ ذلكَ (١) يُسمَّى مُرْسلًا (٢) وإليهِ ذهبَ مِنْ أهلِ الحديثِ أبو بكرٍ الخطيبُ وقَطَعَ بهِ، وقالَ: «إلاَّ أنَّ أكثرَ ما يوصفُ بالإرسالِ مِنْ حيثُ الاستعمالُ ما رواهُ التابعيُّ عَنْ النبيِّ - صلى الله عليه وآله وسلم -، و(٣) أمَّا ما رواهُ تابعُ التابعيِّ (٤) عَنِ النبيِّ - صلى الله عليه وآله وسلم - فَيُسَمُّونَهُ المعْضَلَ (٥)، واللهُ أعلمُ."],[618,"الثانيةُ: قولُ الزُّهريِّ، وأبي حازمٍ، ويحيى بنِ سعيدٍ الأنصاريِّ، وأشباهِهِم مِنْ أصاغِرِ التابعينَ: «قالَ رسولُ اللهِ - صلى الله عليه وآله وسلم -»، حكى ابنُ عبدِ البرِّ (٦): أنَّ قومًا لا يُسَمُّونَهُ مُرْسَلًا بلْ منقطِعًا؛ لكونِهِم لَمْ يَلْقُوا مِنْ الصحابةِ إلاَّ الواحِدَ والاثنينِ (٧)، وأكثرُ روايتِهِم عَنِ التابعينَ."],[619,"قلتُ: وهذا المذهبُ (٨) فَرْعٌ لِمَذْهَبِ مَنْ لا يُسَمِّي المنقطعَ قَبْلَ الوصولِ إلى التابعيِّ مُرسلًا (٩)، والمشهورُ التسويةُ بينَ التابعينَ في اسمِ الإرسالِ كما تقدَّمَ (١) واللهُ أعلمُ.","",{"fn":"في (ب): «كل شيء من ذلك».\nقال البلقيني: «فائدة: قول ابن الحاجب وغيره من الأصوليين: «المرسل قول غير الصحابي، قال رسول الله - صلى الله عليه وآله وسلم -». لا يعم صورة سقوط الرجل قبل التابعي، ولا سقوطه مع التابعي إذا ذكر الصحابي، فيظهر بذاك توقف في نسبة ذلك إلى المعروف في أصول الفقه». المحاسن: ١٣٣.\nليست في (أ).\nسقطت من (م)، وفي (ع): «تابعي التابعي»، وأشار إلى أن في نسخة: «تابع التابعي».\nالكفاية (٥٨ ت، ٢١ هـ)، وعاد فأكده في (٥٤٦ ت، ٣٨٤ هـ).\nالتمهيد ١/ ٢١.\nجاء في حاشية (م): من أمالي ابن الصلاح: «قال المملي - رضي الله عنه -: قولي الواحد والاثنين كالمثال في قلة ذلك، وإلا فالزهري قد قيل إنه رأي عشرة من الصحابة وسمع منهم: أنسًا، وسهل بن سعيد، والسائب بن يزيد، ومحمود بن الربيع، وسُنَيْنًا أبا جميلة ... وغيرهم، ومع ذلك فأكثر روايته عن التابعين، والله أعلم». قلنا: كذا نقل هذه الحاشية البلقيني في المحاسن: ١٣٣، والزركشي في نكته ١/ ٤٥١، وطوَّل التعليق عليها، وانظر: التقييد والإيضاح ٧٢، ونكت ابن حجر ٢/ ٥٥٩.\nفي (أ): «مذهب».\nقال البلقيني: ١٣٥: «فيه نظر: فهذا المذهب أصل يتفرع عليه أنه لا يسمى المنقطع قبل الوصول إلى التابعي مرسلًا». قال ابن حجر ١/ ٥٦٠ جامعًا بين القولين: «يظهر لي أن ابن الصلاح لما رأى كثرة القائلين من المحدّثين بأن المنقطع لا يسمى مرسلًا؛ لأن المرسل يختص عندهم بما ظن منه سقوط الصحابي فقط، جعل قول من قال منهم: إن رواية التابعي الصغير إنما تسمى منقطعة لا مرسلة مفرعًا عنه؛ لأنه مما يظن أنه سقط منه الصحابي والتابعي أيضًا»."}],[620,"الثالثةُ: إذا قيلَ في الإسنادِ: «فلانٌ عَنْ رجلٍ أو عَنْ شيخٍ عَنْ فلانٍ» أو نحوُ ذلكَ؛ فالذي ذكرَهُ الحاكمُ في \" معرفةِ علومِ الحديثِ \" (٢) أنَّهُ لا يُسَمَّى مُرسلًا بلْ منقطِعًا، وهوَ في بَعْضِ المصنَّفاتِ المعتبرَةِ في أصولِ الفقهِ (٣) معدودٌ مِنْ أنواعِ المرسَلِ (١)، واللهُ أعلمُ.","",{"fn":"قال الزركشي ١/ ٤٥٩: «هو خلاف نص الشافعي في الرسالة أنه لا يقبل إلا مرسل كبار التابعين دون صغارهم». قلنا: أبعد الزركشي النجعة في تعقبه هذا، إذ كلام الشافعي في القبول وعدمه، وكلام ابن الصلاح هنا في التسوية بينهم في التسمية، والله أعلم.\nص ٢٨، وتابعه على هذا تلميذه البيهقي في سننه الكبرى ٣/ ٣٣٣ و٤/ ٥٤ و٧/ ١٣٤. قال ابن الملقن في المقنع ١/ ١٣٣: «وتبع الحاكم ابن القطان، فقال: إنه منقطع». وانظر: بيان الوهم والإيهام ٥/ ٢٠٨ (٢٤٢١). وما نقله عن الحاكم لم ينقله على وجهه، إذ شرط الحاكم لتسميته منقطعًا عدم التصريح باسمه في طريق أخرى. فأهمل ابن الصلاح هذا القيد، وحمّل الحاكم تبعة ذلك، وهو عدم تسميته مرسلًا، ثمّ لو سلّمنا جدلًا بأن الحاكم لا يسميه مرسلًا بل منقطعًا، فلا تمنع تسميته بالمنقطع من تسميته مرسلًا، فإن الحاكم صرّح في بدء النوع التاسع (٢٧) بالتغاير بينهما فقال: «معرفة المنقطع من الحديث وهو غير المرسل».\nأراد به كتاب البرهان لإمام الحرمين، إذ قال فيه ١/ ٦٣٣: «وقول الراوي: أخبرني رجل أو عدل موثوق به، من المرسل أيضًا». وتبعه الفخر الرازي في المحصول فقال ٢/ ٢٢٩: «إن الراوي إذا سمّى الأصل باسم لا يعرف به فهو كالمرسل». فقال الأبياري في شرح البرهان: «هذا مردود بلا خلاف، ولا يأتي فيه الخلاف في قبول المرسل إلا أن يكون قائله لا يروي إلا عن عدل، فلا فرق حينئذٍ بين أن يقول: حدّثني رجل، وحدّثني عدل موثوق به». قال الزركشي ١/ ٤٦١ معقبًا على الأبياري: «ونفيه الخلاف فيه مردود، وقد ذكر أبو علي الغساني - من أئمة الحديث - أنه نوع من المرسل، وهو قضية صنيع أبي داود في المراسيل». قلنا: أبو داود يورد أحاديث في كتابه \" المراسيل \" عن مبهمين وهذا يقتضي أنه يسمي ما كان على هذه الشاكلة مرسلًا، بل البيهقي زاد في سننه بأن جعل ما يرويه التابعي عن رجل من الصحابة مرسلًا!! قال ابن التركماني في الجوهر النقي ١/ ١٩٠ - ١٩١ معقبًا على البيهقي: «قدّمنا في باب تفريق الوضوء أن مثل هذا ليس بمرسل، بل هو متصل؛ لأنّ الصَّحَابَة كلهم عدول فَلا تضرهم الجهالة. ="}],[621,"ثُمَّ اعْلَمْ (٢) أنَّ حُكمَ المرسَلِ حُكْمُ الحديثِ الضعيفِ، إلاَّ أنْ يصحَّ مَخْرَجُهُ بمجيئِهِ مِنْ وجهٍ آخَرَ - كما سَبقَ بيانُهُ في نوعِ الحسَنِ (٣)، ولهذا احتجَّ الشافعيُّ - رضي الله عنه - بمرسلاتِ سعيدِ بنِ المسيِّبِ - رضي الله عنهما - فإنَّها وُجِدَتْ مسانيدَ مِنْ وجوهٍ أُخرَ ولا يختصُّ ذلكَ عِندَهُ بإرسالِ ابن المسيِّبِ كما سَبَقَ، ومَنْ أنكرَ هذا زاعمًا أنَّ الاعتمادَ حينئذٍ يقعُ على المسندِ دونَ المرسلِ، فيقعُ لغوًا لا حاجةَ إليهِ، فجوابُهُ: أنَّهُ بالمسندِ يتبيَّنُ (٤) صِحَّةُ الإسنادِ الذي فيهِ الإرسالُ حَتَّى يُحكَمَ لهُ مَعَ إرسالِهِ بأنَّهُ إسنادٌ صحيحٌ تقومُ بهِ الحجَّةُ على ما مهَّدنا سبيلَهُ في النوعِ الثاني (٥). وإنَّما يُنْكِرُ هذا مَنْ لا مذَاقَ لهُ في هذا الشأنِ."],[622,"وما ذَكَرْنَاهُ مِنْ سُقُوطِ الاحتجاجِ بالمرسلِ والحكْمِ بضَعْفِهِ هوَ المذهبُ الذي استقرَّ عليهِ آراءُ جماهيرِ حُفَّاظِ الحديثِ ونُقَّادِ الأثَرِ (٦)، وقدْ تداولوهُ في تصانِيفِهِمْ. وفي صدرِ \"صحيحِ مسلمٍ\": «المرسلُ في أصلِ قولِنا وقولِ أهلِ العلمِ بالأخبارِ ليسَ بحُجَّةٍ» (١).","",{"fn":"يتحصل - مما ذكره المصنّف هنا - مذهبان كلاهما خلاف ما حكي عن الأكثرين، وأهمل مذهبًا ثالثًا، وهو أنه متّصل في إسناده مجهول، حكاه الرشيد العطار في غرر الفوائد المجموعة: ١٣٠ عن الأكثرين، واختاره العلائي في جامع التحصيل: ٩٦. قلنا: انظر: نكت الزركشي ١/ ٤٥٩، ومحاسن الاصطلاح: ١٣٦، والتقييد والإيضاح: ٧٣، ونكت ابن حجر ٢/ ٥٦١.\n«ثم اعلم»: لم ترد في (أ) و(جـ).\nانظر: نكت الزركشي ١/ ٤٦٣، ونكت ابن حجر ٢/ ٥٦٥ - ٥٦٧.\nفي (ع) فقط: «تتبين».\nانظر: نكت الزركشي ١/ ٤٨٨.\nاعترض بعض العلماء منهم: العلاّمة مغلطاي على هذه الدعوى، وادّعى أن الجمهور على خلافه، وقد نقل اعتراضه وأجاب عنه الزركشي في نكته ١/ ٤٩١، وابن حجر ٢/ ٥٦٧."}],[623,"وابنُ عبدِ البرِّ: حافِظُ المغربِ ممَّنْ حَكَى ذلكَ عَنْ جماعةِ أصحابِ الحديثِ (٢)."],[624,"والاحتجاجُ بهِ مذهبُ مالكٍ وأبي حنيفةَ وأصحابِهِمارحمهم اللهفي طائفةٍ (٣)، واللهُ أعلمُ."],[625,"ثُمَّ إنَّا لَمْ نَعُدَّ في أنواعِ المرسَلِ (٤) ونحوِهِ، ما يُسَمَّى في أُصولِ الفِقْهِ مرسَلَ الصحابيِّ (٥)، مثلُ ما يرويهِ ابنُ عبَّاسٍ وغيرُهُ مِنْ أحداثِ الصحابةِ عَنْ رسولِ اللهِ - صلى الله عليه وآله وسلم - ولَمْ يَسمعوهُ منهُ؛ لأنَّ ذلكَ في حُكْمِ الموصولِ المسنَدِ؛ لأنَّ رِوايَتَهُم عنِ الصحابةِ، والجهالةُ بالصحابيِّ غيرُ قادحةٍ؛ لأنَّ الصحابةَ كُلَّهُمْ عدولٌ (١)، واللهُ أعلمُ.","",{"fn":"مقدمة صحيح مسلم ١/ ٢٤. وقد اعترض بعضهم على ابن الصلاح بأن مسلمًا حكى هذا القول على لسان خصمه، وليس هو قولًا له؟ قال الزركشي ١/ ٤٩٧: «إنه وإن حكاه عن لسان خصمه لكن لَمَّا لم يعترض عليه بشيء فكأنّه ارتضاه؛ فلهذا ساغ لابن الصلاح عزوه إليه، ويؤيده قول الترمذي: «الحديث إذا كان مرسلًا فإنه لا يصح عند أكثر أهل الحديث».\nالتمهيد ١/ ٦. ونقل الزركشي ١/ ٤٩٨ عن ابن خلفون أنه قال في المنتقى: «ولا اختلاف أعلمه بينهم أنه لا يجوز العمل بالمرسل إذا كان مرسله غير متحرز يرسل عن غير الثقات».\nقلنا: وهذا أيضًا قول الإمام أحمد في إحدى الروايتين، وإليه ذهب جمهور المعتزلة وهو اختيار الآمدي، وفصَّل عيسى بن أبان من أئمة الحنفية - فقبل مراسيل القرون الثلاثة الخيّرة ومرسل من هو من أئمة النقل مطلقًا، وهذا ما صحّحه النسفي. وبالغ قوم فعدّوا المرسل أقوى من المسند؛ لأن من أرسل فقد تكفل، ومن أسند فقد أحال، واحتجّوا: بحسن الظنّ بالمرسل وأنه لا يرسل إلا عن ثقة، فإنه إن كان عدلًا لم يجز له إسقاط الواسطة وهو يعلم أنه غير عدلٍ؛ لأن هذا قادح في عدالة المرسل. انظر: التبصرة في أصول الفقه ٣٢٦، والمحصول ٢/ ٢٢٤، شرح تنقيح الفصول ٣٧٩، وإحكام الأحكام ٢/ ١١٢، والمجموع ١/ ٦٠، وكشف الأسرار للنسفي ٢/ ٤٢، والإبهاج ٢/ ١١٢، والبحر المحيط ٤/ ٤٠٩. وانظر ردّ الخطيب البغدادي على أصحاب القول الثاني في الكفاية: (٥٥١ ت، ٣٨٧ هـ).\nانظر: نكت الزركشي ١/ ٥٠٠، والتقييد والإيضاح ٧٥.\nهذا مذهب الأستاذ أبي إسحاق الإسفراييني، والقاضي أبي بكر الباقلاني - إلا أن يخبر أنه لا يروي إلا عن الصحابة - واختاره الغزالي في المستصفى، ونقله ابن بطال عن الشافعي وصحّحه ابن برهان، وقال القاضي عبد الوهاب: إنه الظاهر من مذهب الشافعي وإليه ذهب أبو طالب والحسن الرصاص - من أئمة الزيدية -، وقال المنصور بالله - منهم -: أن عنعنة الصحابي محتملة للاتصال والانقطاع. انظر: التبصرة في أصول الفقه: ٣٢٦، والمستصفى ١/ ١٠٧، والمنخول: ٢٧٤، وجامع التحصيل: ٣٦، وتوضيح الأفكار ١/ ٣٣٥، ونكت ابن حجر ٢/ ٥٤٧، وشرح السيوطي: ١٦٢."}],[626,"النوع العاشر معرفة المنقطع"],[627,"(٢)"],[628,"وفِيهِ وفي الفَرْقِ بينَهُ وبينَ المرسَلِ مذاهبُ لأهلِ الحديثِ وغيرِهم: فمنها ما سبقَ في نوعِ المرسلِ عَنِ الحاكمِ - صاحبِ كتابِ \"معرفةِ أنواعِ علومِ الحديثِ\" (٣) مِنْ أنَّ المرسلَ مخصوصٌ بالتابعيِّ. وأنَّ المنقطعَ، منهُ: الإسنادُ الذي فيهِ قبلَ الوصولِ إلى التابعيِّ (٤) راوٍ لَمْ يَسمَعْ مِنَ الذي فوقَهُ، والساقِطُ بينَهُما غيرُ مذكورٍ لا مُعيَّنًا ولا مُبْهمًا، ومنهُ: الإسنادُ الذي ذُكِرَ فيهِ بعضُ رُواتِهِ بلفظٍ مُبْهَمٍ، نحوُ: رَجُلٍ أو شَيْخٍ أو غيرِهِما (٥)."],[629,"مثالُ الأوَّلِ: ما رُوِّيناهُ عَنْ عبدِ الرزَّاقِ، عَنْ سُفْيانَ الثَّوريِّ، عَنْ أبي إسحاقَ، عَنْ زَيْدِ بنِ يُثَيْعٍ (٦)، عَنْ حذيفةَ، قالَ: قالَ رسولُ اللهِ - صلى الله عليه وآله وسلم -: «إنْ وَلَّيْتُمُوْهَا أبا بكرٍ، فقويٌّ أمينٌ ... الحديثَ» (١).","",{"fn":"انظر: محاسن الاصطلاح: ١٤٢ - ١٤٣.\nانظر في المنقطع: معرفة علوم الحديث: ٢٧ - ٢٩، والكفاية: (٥٨ ت، ٢١ هـ)، والتمهيد ١/ ٢١، وإرشاد طلاب الحقائق ١/ ١٨٠ - ١٨٢، والتقريب: ٥٨، والاقتراح: ١٩٢ - ١٩٣، والمنهل الروي: ٤٦ - ٤٧، والخلاصة: ٦٨ - ٦٩، والموقظة: ٤٠، وجامع التحصيل: ٣١، واختصار علوم الحديث: ٥٠ - ٥١، والمقنع ١/ ١٤١، وشرح التبصرة والتذكرة ١/ ٢٧٣، ونزهة النظر: ١١٢، والمختصر: ١٣١ - ١٣٢، وفتح المغيث ١/ ١٤٩، وألفية السيوطي: ٢٤، وشرح السيوطي على ألفية العراقي: ١٦٣، وفتح الباقي ١/ ١٥٨، وتوضيح الأفكار ١/ ٣٢٣، وظفر الأماني: ٣٥٤ - ٣٥٥، وقواعد التحديث: ١٣٠.\nمعرفة علوم الحديث: ٢٥.\nقال الزركشي ٢/ ٦: «ليس بجيد، فإنه لو سقط التابعي كان منقطعًا أيضًا، فالأولى أن يقال: «قبل الصحابي». قال ابن السمعاني في القواطع: «المرسل والمنقطع واحد، ومنهم من فرّق بينهما وجعل المنقطع ما يكون بين الراويين رجل لم يذكر».\nمر بنا قبل قليل: أن علقنا هناك أن الذي عليه الأكثرون أنه متصل في إسناده مبهم.\nبضم الياء، ثُمَّ مثلثة مفتوحة، ثم ياء ساكنة، وقد تبدل الياء همزة فيقال: أُثيع. انظر: تهذيب الكمال ٣/ ٨٨، والتقريب (٢١٦٠)."}],[630,"فهذا إسنادٌ إذا تأمَّلَهُ الحديثِيُّ (٢) وَجَدَ صورَتَهُ صورَةَ المتَّصِلِ، وهوَ منقطعٌ في موضعينِ؛ لأنَّ عبدَ الرزَّاقِ لَمْ يسمعْهُ مِنَ الثوريِّ، وإنَّما سَمِعَهُ مِنَ النعمانِ بنِ أبي شيبةَ الْجَنَدِيِّ (٣)، عَنِ الثوريِّ، ولَمْ يَسْمَعْهُ الثوريُّ أيضًا مِنْ أبي إسحاقَ، إنَّما سَمِعَهُ مِنْ شَرِيكٍ، عَنْ أبي إسحاقَ (٤).","",{"fn":"قلنا: هكذا أورد ابن الصلاح متن هذا الحديث، وهو متابع فيه للحاكم، إذ أورده هكذا في معرفة علوم الحديث: ٢٨ - ٢٩، وهو اختصار مخلّ من حيث ما ذُكِر وما حُذِف والمتن الكامل الذي أورده الحاكم نفسه في المستدرك ٣/ ١٤٢: «إن وليتموها أبا بكر فزاهد في الدنيا راغب في الآخرة وفي جسمه ضعف، وإن وليتموها عمرَ فقويٌّ أمينٌ لا يخاف في الله لومة لائم، وإن وليتموها عليًا فهادٍ مهتدٍ يقيمكم على صراط مستقيم». والحديث أخرجه: العقيلي ٣/ ١١١، وابن عدي في الكامل ٥/ ٩٥٠ - ط دار الفكر و٦/ ٥٤٢ ط دار الكتب العلمية، والحاكم في المستدرك ٣/ ١٤٢، وفي معرفة علوم الحديث: ٢٩، وأبو نعيم في الحلية ١/ ٦٤، والخطيب في تاريخه ٣/ ٣٠٢، وابن الجوزي في العلل المتناهية: (٤٠٥). قلنا: عبد الرزاق رواه عن رجلين - ولكنهما شبه لا شيء - روى العقيلي بسنده ٣/ ١١١: أنه قِيلَ لعبد الرزاق: سمعت هذا من الثوري؟ قال: لا، حدّثني يحيى بن العلاء وغيره، ثُمَّ سألوه مرة ثانية، فقال: حدَّثنا النعمان بن أبي شيبة ويحيى بن العلاء عن سفيان الثوري». قلنا: قال الذهبي في الميزان ٢/ ٦١٢: «النعمان فيه جهالة ويحيى هالك ... والخبر منكر».\nهو المبتدئ في طلب الحديث، لا كما فهم بعضهم أنه أراد المحدّث. انظر: نكت ابن حجر ٢/ ٥٧٢.\nبفتح الجيم والنون كما في التقريب (٧١٥٧).\nهذه الطريق التي زيد فيها شريك أخرجها الحاكم في المعرفة: ٢٩، والخطيب في تاريخه ١١/ ٤٧، من طريق عبد السلام بن صالح - أبو الصلت الهروي - عن ابن نمير، عن سفيان، عن شريك، عن أبي إسحاق، عن زيد بن يثيع، عن حذيفة، به مرفوعًا. قال الخطيب ٣/ ٣٠٢: «لم يذكر فيه بين الثوري وأبي إسحاق شريكًا غير أبي الصلت عن ابن نمير». ونحن نعجب من اعتماد الحاكم على تفرد أبي الصلت هذا، ومتابعة ابن الصلاح للحاكم في هذا الاعتماد، وأبو الصلت هذا لا يعتد بموافقته، فكيف يحتمل تفرده!؟ قال أبو حاتم: لم يكن عندي بصدوق، وضرب أبو زرعة على حديثه. وقال العقيلي: رافضي خبيث. وقال ابن عدي: متهم. وقال النسائي: ليس بثقة، وقال الدارقطني: رافضي خبيث متهم». انظر: ميزان الاعتدال ٢/ ٦١٦."}],[631,"ومثالُ الثاني: الحديثُ الذي رُوِّيناهُ عَنْ أبي العلاءِ بنِ عبدِ اللهِ بنِ الشِّخِّيْرِ (١)، عَنْ"],[632,"رَجلينِ (٢)، عَنْ شَدَّادِ بنِ أوسٍ، عَنْ رسولِ اللهِ - صلى الله عليه وآله وسلم - في الدعاءِ في الصلاةِ: «اللَّهُمَّ إنِّي أسأَلُكَ الثباتَ في الأمرِ ... الحديثَ» (٣)، واللهُ أعلمُ."],[633,"ومنها: ما ذكرَهُ ابنُ عبدِ البرِّ - رحمه الله - وهوَ أنَّ المرسلَ مخصوصٌ بالتابعينَ، والمنقطعَ شاملٌ لهُ ولغيرِهِ، وهوَ عندَهُ: كُلُّ ما لا يتَّصِلُ إسنادُهُ سواءٌ كانَ يُعْزَى إلى النبيِّ - صلى الله عليه وآله وسلم -، أو إلى غيرِهِ (٤)."],[634,"ومنها: أنَّ المنقطعَ مثلُ المرسلِ (٥) وكلاهُما شامِلانِ لكلِّ ما لا يتَّصِلُ إسنادُهُ. وهذا المذهبُ أقربُ، وصار إليهِ طوائفُ مِنَ الفقهاءِ وغيرِهِم، وهو الذي ذكرَهُ الحافِظُ أبو بكرٍ الخطيبُ في \" كفايتِهِ \" (١). إلاَّ أنَّ أكثرَ ما يوصَفُ بالإرسالِ مِنْ حيثُ الاستعمالُ: ما رواهُ التابعيُّ عَنِ النبيِّ - صلى الله عليه وآله وسلم -، وأكثرُ ما يُوصَفُ بالانقطاعِ: ما رواهُ مَنْ دونَ التابعينَ عَنِ الصحابةِ، مثلُ (٢): مالكٍ، عَنِ ابنِ عمرَ، ونحوِ ذلكَ، واللهُ أعلمُ.","",{"fn":"بكسر الشين وتشديد الخاء المعجمتين، بوزن سِكِّيْت، واسمه: يزيد. انظر: التقريب (٧٧٤٠)، وتاج العروس ١٢/ ١٤٨.\nقال الزركشي ٢/ ٨: «كذا يقع في بعض نسخ كتاب الحاكم، والثابت في النسخ المعتمدة «عن رجل»، وكذا أخرج الترمذي والنسائي، وقالا: عن رجل من بني حنظلة». قال البلقيني: ١٤٥: «وجوابه أني وقفت على نسخة من \" علوم الحديث \" للحاكم أصل مسموعةٍ وفيها: «عن رجلين» في السند ثم في الكلام عليه. وهذا المثال يبيّن أن المنقطع ما سقط فيه رجل أو أبهم قبل الصحابي ولو كان التابعي. وهذا خلاف ما يقتضيه ما نقل عن المذهب الأول». قلنا: ما في المطبوع: ٢٧ - ٢٨ موافق لما ذكر البلقيني، ووقع خلافه في النسخة الخطية من المعرفة التي في خزانتنا ١٣ ب، وهو ما جزم به ابن الملقن في المقنع ١/ ١٤٢. وقد وقع الحديث في مسند أحمد ٤/ ١٢٥، ومعجم الطبراني الكبير (٧١٧٦) و(٧١٧٧)، وحلية الأولياء ١/ ٢٦٧ بلفظ: عن الحنظلي. في حين وقع في جامع الترمذي (٣٤٠٧) ومعجم الطبراني الكبير (٧١٧٥) بلفظ: «عن رجل من بني حنظلة»؛ لكن وقع في المعجم الكبير (٧١٧٩): «عن رجلين». فالله أعلم بالصواب.\nمضى تخريجه قبل قليل.\nالتمهيد ١/ ٢٠ - ٢١. قال البلقيني: ١٤٥: «فالمنقطع على هذا أعم من المرسل، فكل مرسل منقطع ولا عكس، وكلام الشافعي السابق ينطبق على هذا».\nقال الزركشي ١/ ٩: «هذا ظاهر كلام ابن السمعاني، وقد سمّى الشافعي في الرسالة المرسل منقطعًا، قال ابن حزم في الإحكام: «المرسل: هو الذي سقط بين أحد رواته وبين النبي - صلى الله عليه وآله وسلم - ناقل واحد فصاعدًا، وهو المنقطع أيضًا»."}],[635,"ومنها: ما حكاهُ الخطيبُ أبو بكرٍ (٣) عَنْ بَعضِ أهلِ العلمِ بالحديثِ، أنَّ المنقطعَ: ما رُوِيَ عَنِ التابعيِّ أوْ مَنْ دونَهُ موقوفًا عليهِ مِنْ قولِهِ أو فِعْلِهِ، وهذا غريبٌ بعيدٌ (٤)، والله أعلمُ."],[636,"النَّوْعُ (٥) الْحَادِي عَشَرَ"],[637,"مَعْرِفَةُ الْمُعْضَلِ (٦)"],[638,"وهوَ لَقَبٌ لنوعٍ خاصٍّ مِنَ المنقطِعِ، فكُلُّ مُعْضَلٍ مُنْقَطِعٌ، وليسَ كُلُّ مُنقطِعٍ مُعْضلًا. وقومٌ يُسَمُّونَهُ مُرسلًا كَمَا سَبَقَ، وَهُوَ عبارةٌ عَمَّا سَقَطَ مِنْ إسنادِهِ اثنانِ فصاعِدًا (١).","",{"fn":"(٥٨ - ٥٩ ت، ٢١ هـ).\nفي (م): «مثال ذلك».\nالكفاية (٥٩ ت، ٢١ هـ).\nقال الزركشي ٢/ ١٠: «فيه أمران: أحدها: أن هذا قول الحافظ أبي بكر أحمد بن هارون البرديجي، ذكره في جزء لطيف له. الثاني: أنه قد سبق في المقطوع الموقوف على التابعي أنه يعبر عنه بلفظه عن المنقطع غير الموصول، وهذا غير ذاك؛ لأن الكلام في إطلاق المنقطع على ما يطلق عليه المقطوع بزيادة «أو من دون التابعي»، وهذا هو الغريب». ومن ثمَّ استدرك عليه أقوالًا أخرى في تعريف المرسل فانظرها، وراجع المحاسن: ١٤٦.\nسقطت من (أ).\nانظر في المعضل: معرفة علوم الحديث: ٣٦، والكفاية: (٥٨ ت، ٢١ هـ)، والإرشاد ١/ ١٨٣، والتقريب: ٥٩، والاقتراح: ١٩٢، والمنهل الروي: ٤٧، والخلاصة: ٦٨، والموقظة: ٤٠، وجامع التحصيل: ٣٢ - ٩٦، واختصار علوم الحديث: ٥١، والمقنع ١/ ١٤٥، وشرح التبصرة والتذكرة ١/ ٢٧٣، ونزهة النظر: ١١٢، والمختصر: ١٣١، وفتح المغيث ١/ ١٤٩، وألفية السيوطي: ٢٤، وشرح السيوطي على ألفية العراقي: ١٦٣، وفتح الباقي ١/ ١٥٨، وتوضيح الأفكار ١/ ٣٢٣، وظفر الأماني: ٣٥٥، وقواعد التحديث: ١٣٠."}],[639,"وأصحابُ الحديثِ يقولونَ: أعْضَلَهُ فهو مُعضَلٌ - بفتحِ الضادِ - وهو اصطلاحٌ مُشكلُ المأخذِ مِنْ حيثُ اللغةُ، وبحثْتُ فوجدْتُ لهُ قولَهم: «أمرٌ عَضِيْلٌ»، أي: مُستَغْلَقٌ شديدٌ. ولا التفاتَ في ذلكَ إلى مُعْضِلٍ - بكسرِ الضادِ - وإنْ كانَ مِثْلَ عَضِيْلٍ في المعنى (٢)."],[640,"ومثالُهُ: ما يرويهِ تابعيُّ التابعيِّ قائلًا فيهِ: «قالَ رسولُ اللهِ - صلى الله عليه وآله وسلم -». وكذلكَ (٣) ما يرويهِ مَنْ دونَ تابعيِّ (٤) التابعيِّ «عَنْ رسولِ اللهِ - صلى الله عليه وآله وسلم -، أو عَنْ أبي بكرٍ وعُمَرَ وغيرِهِما» غيرَ ذاكرٍ للوسائطِ بينَهُ وبينهُم. وذكرَ أبو نصرٍ السِّجْزيُّ الحافظُ قولَ الراوي: «بلغني»","",{"fn":"هذا ينطبق على ما حكاه الحاكم في المعرفة: ٣٦ عن علي بن المديني، وقد أطلق ابن الصلاح هنا القول بسقوط اثنين من غير تفصيل بين أن يكونا من موضع واحد أو من موضعين، ومراده سقوطهما من موضع واحد بدلالة ما مثّل به، وإلا لكان سقوطهما من موضعين خارجًا عن تسمية «المعضل» في الاصطلاح؛ إذ أنهم يسمون ما هذه صورته منقطعًا في موضعين. قال ابن حجر ١/ ٥٧٥: «وجدت التعبير بالمعضل في كلام الجماعة من أئمة الحديث فيما لم يسقط منه شيء البتة». ثم ساق أمثلة على ذلك، وعقّبها بقوله: «فإذا تقرّر هذا فإما أن يكونوا يطلقون المعضل لمعنيين، أو يكون المعضل الذي عرّف به المصنّف، وهو المتعلق بالإسناد - بفتح الضاد -، وهذا الذي نقلناه من كلام هؤلاء الأئمة - بكسر الضاد -، ويعنون به المستغلق الشديد. وفي الجملة، فالتنبيه على ذلك كان متعينًا». وانظر: نكت الزركشي ٢/ ١٤، والتقييد والإيضاح: ٨١.\nجاءت في حاشية نسخة (ب) تعليقة نصّها: «قال المصنف - رحمه الله -: «دلَّنا قولهم: عضيل، على أن ماضيه: عَضِل، فيكون أعضله منه، لا من أعضل هو. وقد جاء: ظَلِمَ الليل وأظلمَ وأظلمه الله. وغطش الليل وأغطشه الله، والله تعالى أعلم». وهذه الحاشية بنصّها توجد في هامش (م)، ونقل نصها العراقي في التقييد: ٨٢. وفي هذا الاشتقاق مباحثات ومناقشات، انظرها في: نكت الزركشي ٢/ ١٥، ومحاسن الاصطلاح ١٤٧، والتقييد والإيضاح: ٨١، ونكت ابن حجر ٢/ ٥٨٠، والنكت الوفية: ١٢٦/ أ، وفتح المغيث ١/ ١٥١، والبحر الذي زخر: ١٠٩ ب، وتوضيح الأفكار ١/ ٣٢٧.\nفي (ب): «وكذا».\nفي (ب): «تابع»."}],[641,"- نحوُ قولِ مالكٍ: «بَلَغَني عَنْ أبي هريرةَ: أنَّ رسولَ اللهِ - صلى الله عليه وآله وسلم - قالَ: لِلْمَملوكِ طَعامُهُ وكِسْوتُهُ ... الحديثَ» (١)، وقالَ (٢): أصحابُ الحديثِ يُسَمُّونَهُ المعْضلَ.","",{"fn":"هذا البلاغ في الموطأ (رواية يحيى الليثي (٢٨٠٦)، ورواية أبي مصعب الزهري (٢٠٦٤)، ورواية سويد بن سعيد (٧٧٩)، وهو في موطأ عبد الله بن مسلمة القعنبي كما أسنده إليه الحاكم في معرفة علوم الحديث: ٣٧). قلنا: وقد روي موصولًا عن مالك: رواه إبراهيم بن طهمان، والنعمان بن عبد السلام. ورواية ابن طهمان: عند الحاكم في معرفة علوم الحديث: ٣٧، والخليلي في الإرشاد ١/ ١٦٤. ورواية النعمان: عند الخليلي في الإرشاد ١/ ١٦٤ - ١٦٥؛ كلاهما (إبراهيم بن طهمان والنعمان بن عبد السلام) عن مالك، عن محمد بن عجلان، عن أبيه، عن أبي هريرة، عن النبي - صلى الله عليه وآله وسلم - ... الحديث. وقد خولف فيه مالك فقد أسنده عن محمد بن عجلان: سفيان الثوري، عند الحميدي (١١٥٥)، وأحمد ٢/ ٢٤٧، ووهيب بن خالد عند أحمد ٢/ ٣٤٢، وسعيد بن أبي أيوب عند البخاري في الأدب المفرد (١٩٢)، والليث بن سعد عند البخاري في الأدب المفرد (١٩٣)، والبيهقي في الكبرى ٨/ ٦، وسفيان بن عيينة عند البغوي (٢٤٠٣)، لكن هؤلاء (سفيان الثوري، ووهيب، وسعيد بن أبي أيوب، والليث بن سعد، وسفيان بن عيينة) رووه عن ابن عجلان، عن بكير بن عبد الله الأشج، عن العجلان، عن أبي هريرة وروايتهم أصحّ. فقد توبع محمد بن عجلان على روايته، كما في رواية الجمع، فقد أخرجه مسلم ٥/ ٩٣ (١٦٦٢) من طريق عمرو بن الحارث، عن بكير بن عبد الله بن الأشج، عن العجلان. فلعل هذا هو السبب الذي جعل الإمام مالك يذكره بلاغًا في موطئه؛ لأنّه لم يضبطه جيدًا، وعجبًا أنّ الدكتور بشار عوّاد لم يتنبه إلى ذلك في تعليقه على موطّأ مالك في روايتيه (رواية أبي مصعب ورواية يحيى الليثي) بل لم يشر أبدًا إلى الرواية الموصولة من طريق مالك. قلنا: استشكل بعضهم كون هذا الحديث معضلًا؛ لجواز أن يكون الساقط بين مالك وأبي هريرة واحدًا فقط، لا سيّما وقد سمع مالك من جماعة من أصحاب أبي هريرة كسعيد المقبري ونعيم المجمر ومحمد بن المنكدر، فَلِمَ جعلَهُ معضلًا؟ الجواب: أن مالكًا قد وصله - كما تقدّم - خارج الموطأ فرواه عن محمد بن عجلان، عن أبيه، عن أبي هريرة، فتبين أن الساقط اثنان. وانظر: نكت الزركشي ٢/ ١٨، ومحاسن الاصطلاح: ١٤٩، والتقييد والإيضاح: ٨٢، ونكت ابن حجر ٢/ ٥٨٢.\nفي (ع) والتقييد زيادة: «أي: السجزي»."}],[642,"قلتُ: وقولُ المصَنِّفينَ مِنَ الفقهاءِ وغيرِهِم: «قالَ رسولُ اللهِ - صلى الله عليه وآله وسلم -: كذا"],[643,"وكذا» ونحو ذلكَ، كُلُّهُ مِنْ قَبيلِ المعضلِ؛ لِما تقدَّمَ. وسمَّاهُ الخطيبُ أبو بكرٍ الحافظُ"],[644,"في بعضِ كلامِهِ مُرْسلًا، وذلكَ عَلَى مَذهَبِ مَنْ يُسَمِّي كُلَّ مَا لا يتَّصِلُ مُرسلًا كَمَا"],[645,"سبقَ."],[646,"وإذا روى تابعُ التابعِ (١) عَنْ التابعِ (٢) حديثًا موقوفًا عليه، وهو حديثٌ"],[647,"متَّصِلٌ مسندٌ إلى رسولِ اللهِ - صلى الله عليه وآله وسلم - (٣)، فقدْ جَعَلَهُ الحاكِمُ (٤) أبو عبدِ اللهِ نوعًا مِنَ"],[648,"المعضلِ (٥)، مثالُهُ: «ما رُوِّيناهُ عَنِ الأعمشِ، عَنِ الشَّعبيِّ، قالَ: يُقالُ للرَّجُلِ يومَ القيامةِ: «عَمِلْتَ كذا وكذا، فيقولُ: ما عَمِلْتُهُ فَيُخْتَمُ على فيهِ ... الحديثَ» (٦)، فقدْ أعضَلَهُ الأعمشُ، وهوَ عِندَ الشَّعبيِّ: عَنْ أنسٍ، عَنْ رسولِ اللهِ - صلى الله عليه وآله وسلم - متَّصِلًا"],[649,"مُسْنَدًا (٧)."],[650,"قلتُ: هذا جَيِّدٌ حَسَنٌ؛ لأنَّ هَذَا الانقطاعَ بواحدٍ مضمومًا إلى الوقفِ يشتملُ عَلَى الانقطاعِ باثنينِ: الصحابيِّ ورسولِ اللهِ - صلى الله عليه وآله وسلم -، فذلكَ باستحقاقِ اسمِ الإعضالِ"],[651,"أَوْلَى، واللهُ أعلمُ.","",{"fn":"في (ب): «التابعي».\nفي (أ) و(ب): «التابعي».\nقال ابن حجر ٢/ ٥٨١: «مراده بذلك تخصيص هذا القسم الثاني من قسمي المعضل، بما اختلف الرواة فيه على التابعي، بأن يكون بعضهم وصله مرفوعًا، وبعضهم وقفه على التابعي، بخلاف القسم الأول فإنه أعم من أن يكون له إسناد آخر متصل أو لا».\nفي (جـ): «الحافظ».\nمعرفة علوم الحديث: ٣٧ - ٣٨.\nأخرجه من هذا الوجه معضلًا الحاكم في معرفة علوم الحديث: ٣٨.\nورواه من هذا الوجه متصلًا مسندًا: مسلم ٨/ ٢٦٧ (٢٩٦٩)، والنسائي في الكبرى (١١٦٥٣)، وابن أبي حاتم - كما في تفسير ابن كثير ٣/ ٥٧٧ - وابن أبي الدنيا في التوبة وابن مردويه في تفسيره - كما ذكره السيوطي في الدر المنثور ٧/ ٦٧ - ."}],[652,"تفريعات"],[653,"أحدُها: الإسنادُ المعنعنُ، وهو الذي يُقالُ فيه: «فلانٌ عَنْ فلانٍ» عَدَّهُ بعضُ الناسِ مِنْ قَبيلِ المرسَلِ والمنقطعِ حَتَّى يَبِيْنَ (١) اتِّصالُهُ بغيرِهِ. والصحيحُ والذي عليهِ العملُ: أنَّهُ مِنْ قَبيلِ الإسنادِ المتَّصِلِ (٢). وإلى هذا ذهبَ الجماهيرُ مِنَ أئمَّةِ الحديثِ وغيرِهِمْ، وأودَعَهُ المشترطونَ للصحيحِ في تصانيفِهِم فيهِ (٣) وقَبِلُوهُ، وكادَ (٤) أبو عمرَ بنُ عبدِ البرِّ الحافظُ يَدَّعِي إجماعَ أئمَّةِ الحديثِ على ذلكَ. وادَّعَى أبو عمرٍو الدانيُّ المقرِئُ الحافِظُ إجماعَ أهلِ النَّقلِ على ذلكَ (٥)، وهذا بشرطِ أنْ يكونَ الذينَ أُضيفَتِ العَنعنةُ إليهِم قدْ ثبَتَتْ مُلاقاةُ بعضِهِم بَعضًا مَعَ براءَتِهِم مِنْ وصْمَةِ (١) التَّدليسِ، فحينَئذٍ يُحْمَلُ على ظاهرِ الاتِّصالِ إلاَّ أنْ يَظْهَرَ فيهِ خلافُ ذلكَ.","",{"fn":"في (ع) والتقييد والشذا: «يتبين».\nقال الزركشي ٢/ ٢١: «حاصله حكاية قولين فيه: أحدهما: أنه من قبيل المرسل والمنقطع، وعبارة المازري في حكايته في شرح البرهان: ومِنَ الناس مَنْ لَمْ يرَ هذا تصريحًا بالمسند وتوقف فيه مخافة أن يكون مرسلًا. والثاني: أنه متصل بشرطين: وجود المعاصرة، مع البراءة من التدليس».\nسقطت من (ب) و(جـ).\nقال الزركشي ٢/ ٢٢: «لا حاجة لقوله: «كاد»، فقد ادَّعاه في أول كتابه التمهيد - ١/ ١٣ - وعبارته: «أجمع أهل العلم على قبول الإسناد المعنعن بثلاثة شروط: عدالة المخبرين، ولقاء بعضهم بعضًا، وأن يكونوا براء من التدليس. ولم يذكر ابن الصلاح الشرط الأول ظنًا أنه يؤخذ من الثالث». وانظر: التقييد: ٨٣. قال ابن حجر ٢/ ٥٨٣: «إنما عبّر هنا بقوله: «كاد»؛ لأن ابن عبد البرّ إنما جزم بإجماعهم على قبوله، ولا يلزم منه إجماعهم على أنه من قبيل المتصل».\nقال الزركشي ٢/ ٢٣: «ما نقله عن الداني وجدته في جزء له في علوم الحديث، فقال: «وما كان من الأحاديث المعنعنة التي يقول فيها ناقلوها: «عن» «عن» فهي أيضًا مسندة بإجماع أهل النقل، إذا عرف أن الناقل أدرك المنقول عنه إدراكًا بيّنًا». وسبق الزركشي إلى هذا العزو ابن رشيد في السنن الأبين: ٣٦. لكن البقاعي عزا هذا النقل إلى كتاب القراءات للداني. النكت الوفية ١٢٩ / ب. قلنا: وسبق الجميع إلى نقل الإجماع على الاتصال، الحاكم في المعرفة: ٣٤، والخطيب في الكفاية: (٤٢١ ت، ٢٩١ هـ)، فكان الأولى بابن الصلاح نقله عنهما فإنهما من أئمّة المحدّثين. وانظر: نكت الزركشي ٢/ ٢٤، ونكت ابن حجر ٢/ ٥٨٣. ثمَّ إنَّ في النقل عن أبي عمرو الداني اضطرابًا، فانظر ما كتبه محقّق شرح السيوطي على ألفية العراقي: ٦٧، وما علقناه على شرح التبصرة والتذكرة ١/ ٢٨٣."}],[654,"وكَثُرَ في عصرِنا وما قارَبَهُ بينَ المنتسبينَ إلى الحديثِ استعمالُ «عَنْ» في الإجازةِ، فإذا قالَ أحدُهُمْ: «قرأتُ على فلانٍ عَنْ فلانٍ» أو (٢) نحوَ ذلكَ فَظُنَّ بهِ (٣) أنَّهُ رواهُ عنهُ بالإجازةِ، ولا يُخْرِجُهُ ذلكَ مِنْ قبيلِ الاتِّصالِ على ما لا يخفَى، واللهُ أعلمُ."],[655,"الثاني: اختَلَفُوا في قولِ الراوي: «أنَّ فلانًا قالَ: كذا وكذا» هَلْ هوَ بمنزلةِ «عَنْ» في الحَمْلِ عَلَى الاتِّصالِ إذا ثبتَ التلاقي بينهُما حَتَّى يتبيَّنَ فيهِ الانقطاعُ؟ مثالُهُ: «مالِكٌ عَنِ الزُّهْرِيِّ: أنَّ سعيدَ بنَ المسيِّبِ قالَ: كذا». فَرُوِّيْنا عَنْ مالِكٍ - رضي الله عنه -: أنَّهُ كانَ يَرى «عَنْ فلانٍ» و«أنَّ فلانًا» سواءً. وعَنْ أحمدَ بنِ حنبلٍ - رضي الله عنه -: أنَّهُما ليسا سواءً (٤).","",{"fn":"يُقَالُ: وَصَمَهُ يَصِمُهُ وَصْمًا، أي: عابَهُ، والَوصْمَةُ: واحدةُ الوَصْمِ، أي: العيب والعار. انظر: اللسان ١٢/ ٦٣٩، ومتن اللغة ٥/ ٧٦٨.\nفي (ب): «و».\n«به» ليست في (ب). قال الزركشي ٢/ ٣١: «قال المصنّف: هو أمر من الظن». قال البقاعي: «فظُنَّ بهِ: هو فعل أمرٍ؛ وإنما أمر بالظن ولم يطلق الحكم؛ لأن في زمنه لم يكن تقرر الاصطلاح: أن ذلك للإجازة، وإنما كان قد فشا ذلك الاستعمال فيهم، وأما في هذا الزمان فمتى وجدنا محدِّثًا قال: حدَّثني فلان - مثلًا - عن فلان، فإنا نتحقق أن ذلك إجازة؛ لأنَّ الاصطلاح تقرر على ذلك». النكت الوفية ١٣٤ / أ.\nالكفاية: (٥٧٥ ت، ٤٠٧ هـ). قال الزركشي ٢/ ٣١: «حاصله حكاية قولين: أحدهما: أنهما سواء، ويؤيده أن لغة بني تميم إبدال العين من الهمزة. والثاني: أنهما ليسا سواء ونسبه لأحمد بن حنبل والذي حكاه الخطيب في الكفاية بإسناده إلى أبي داود قال: «سمعت أحمد بن حنبل، قيل له: إن رجلًا قال: عروة أن عائشة قالت: يا رسول الله، وعن عروة، عن عائشة، سواء، قال: كيف هذا سواء؟! ليس هذا بسواء. وإنما فرّق أحمد بين اللفظين في هذه الصورة؛ لأن عروة في اللفظ الأول لم يسند ذلك إلى عائشة، ولا أدرك القصة فكانت مرسلة، وأما اللفظ الثاني فأسند ذلك إليها بالعنعنة فكانت متصلة». قلنا: ولابن حجر تفصيل أطول فانظره في نكته ٢/ ٥٩٠، وارجع إلى شرح التبصرة والتذكرة ١/ ٢٨٦ وما بعدها."}],[656,"وحَكَى ابنُ عبدِ البرِّ (١) عَنْ جُمْهُورِ أهلِ العلْمِ: أنَّ «عَنْ» و«أنَّ» سواءٌ، وأنَّهُ لا اعتبارَ بالحروفِ والألفاظِ، وإنَّما هوَ باللِّقاءِ والمجالَسَةِ والسَّماعِ والمشاهدةِ"],[657,"- يعني: معَ السلامةِ مِنَ التدليسِ - فإذا كانَ سماعُ بعضِهِمْ مِنْ بَعْضٍ صحيحًا، كانَ حديثُ بعضِهِمْ عَنْ بَعْضٍ بأيِّ لفظٍ وَرَدَ: محمولًا على الاتِّصالِ حَتَّى يَتَبَيَّنَ فيهِ الانقطاعُ."],[658,"وحَكَى ابنُ عبدِ البرِّ (٢) عَنْ أبي بكرٍ البِرْدِيْجِيِّ (٣): أنَّ حرفَ «أنَّ» محمولٌ على الانقطاعِ حَتَّى يتبيَّنَ السَّماعُ في ذلكَ الخبرِ بعينِهِ مِنْ جِهَةٍ أخرى (٤). وقالَ: عِندي لا معنًى لهذا؛ لإجماعِهِم عَلَى أنَّ الإسنادَ المتَّصِلَ بالصحابيِّ سواءٌ فيهِ، قالَ: «قالَ رسولُ اللهِ - صلى الله عليه وآله وسلم -»، أو «أنَّ رسولَ اللهِ - صلى الله عليه وآله وسلم - قالَ:»، أو: «عَنْ رسولِ اللهِ - صلى الله عليه وآله وسلم - أنَّهُ قالَ»، أو:"],[659,"«سَمِعْتُ رسولَ اللهِ - صلى الله عليه وآله وسلم - يقولُ:»، واللهُ أعلمُ."],[660,"قُلتُ (٥): ووَجدْتُ مِثلَ ما حكاهُ عَنِ البِرْدِيجيِّ أبي بكرٍ الحافظِ، للحافظِ الفَحْلِ (١) يعقوبَ بنِ شيبَةَ (٢) في \" مسندِهِ \" الفحلِ، فإنَّهُ ذكرَ ما رواهُ أبو الزبيرِ عَنِ","",{"fn":"في التمهيد ١/ ١٢.\nالتمهيد ١/ ٢٦.\nبَرْدِيج: على وزن (فَعْليل) - بفتح أوله - بُليدة بينها وبين برذعة نحو أربعة عشر فرسخًا، ولهذا يقال له: البرديجي والبرذعي، فمن نحا بها نحو أوزان العرب كسر أولها؛ نظرًا إلى أنَّهُ لَيْسَ في كلامهم (فعليل) - بفتح الفاء - كما أشار إليه الصاغاني، فقال: بِرديج - بكسر أوله - بليدة بأقصى أذربيجان، والعامة يفتحون باءها. فالمراد أن مَن نطق بها على مقتضى تسميتها العجمية فتح الباء على الحكاية، ومن سلك بها مسلك أهل العربية كسر الباء». وانظر: الأنساب ١/ ٣٢٨، ومراصد الاطلاع ١/ ١٨١، ونكت الزركشي ٢/ ٣٣، ومحاسن الاصطلاح ١٥٤، ونكت ابن حجر ٢/ ٥٩٤، وتاج العروس ٥/ ٤٢٠. وجاءت حاشية للمصنّف بنحو هذا في حاشية (ب) و(جـ)، ونقلها كل من الزركشي، وابن حجر، ومحققة (م).\nوإلى نحو قول البرديجي ذهب الطحاوي في شرح المشكل ١٥/ ٤٦٣ (٦١٥٨) فقال: «الفرق فيما بين «عن» و«أنَّ» في الحديث: أنَّ معنى «عن» على السماع حتّى يُعلم سواه، وأنَّ معنى «أنَّ» على الانقطاع حتى يعلم ما سواه».\nسقطت من (ب) و(جـ)."}],[661,"ابنِ الحنفيَّةِ عَنْ عَمَّارٍ، قالَ: «أتيتُ النبيَّ - صلى الله عليه وآله وسلم - وهوَ يُصَلِّي فسَلَّمْتُ عليهِ، فردَّ عليَّ السلامَ» (٣) وجعلَهُ مسندًا موصولًا. وذكرَ: روايةَ قيسِ بنِ سَعْدٍ لذلكَ، عنْ عطاءِ بنِ أبي رَباحٍ، عنِ ابنِ الحنفيَّةِ: «أنَّ عَمَّارًا مرَّ بالنبيِّ - صلى الله عليه وآله وسلم - وهوَ (٤) يُصَلِّي»، فجعلَهُ مُرسلًا مِنْ حيثُ كونُهُ قالَ: «أنَّ عمَّارًا فَعَلَ»، ولَمْ يقلْ: «عَنْ عمَّارٍ» (٥)، واللهُ أعلمُ."],[662,"ثُمَّ إنَّ الخطيبَ (٦) مَثَّلَ هذهِ المسألَةَ بحديثِ نافعٍ عَنِ ابنِ عُمَرَ، عَنْ عُمَرَ: «أنَّهُ سألَ رسولَ اللهِ - صلى الله عليه وآله وسلم - أيَنَامُ أحدُنا وهوَ جُنُبٌ؟ ... الحديثَ» (٧). وفي روايةٍ أخرى عَنْ نافِعٍ، عَنِ ابنِ عمرَ: أنَّ عمرَ قالَ: «يا رسولَ اللهِ ... الحديثَ» (٨). ثُمَّ قالَ: «ظاهرُ الروايةِ الأولى يوجِبُ (٩) أنْ يكونَ مِنْ مسندِ عُمرَ، عَنْ النبيِّ - صلى الله عليه وآله وسلم -، والثانيةُ ظاهرُها يُوجِبُ أنْ يكونَ مِنْ مُسندِ ابنِ عُمَرَ، عنِ النبيِّ - صلى الله عليه وآله وسلم -».","",{"fn":"قال البقاعي: «ابن الصلاح يصف هذا الرجل بأنه فحل، إشارة إلى أنه قد بلغ العناية من معرفة هذا الفن، ويصف مسنده بالفحولة أيضًا، إشارة إلى أنه في غاية التحرير». النكت الوفية ١٣٢ / أ.\nهو الحافظ أبو يوسف يعقوب بن شيبة بن الصلت السدوسي البصري، نزيل بغداد، ت (٢٦٢ هـ). تاريخ بغداد ١٤/ ٢٨١، والمنتظم ٥/ ٤٣، وتذكرة الحفاظ ٢/ ٥٧٧.\nأخرجه أحمد ٤/ ٤٦٣ من طريق أبي الزبير عن محمد بن علي بن الحنفية، عن عمار، قال: أتيت ... .\n«وهو»: ليس في (جـ).\nأخرجه من هذه الطريق النسائي في الكبرى (١١١١) عن عمار: أنه سلم ... . وانظر: نكت الزركشي ٢/ ٣٤، وشرح التبصرة والتذكرة ١/ ٢٨٦.\nالكفاية: (٥٧٤ ت، ٤٠٦ - ٤٠٧ هـ).\nأخرجه من هَذَا الطريق بهذا اللفظ: عَبْد الرزاق (١٠٧٤) و(١٠٧٥) و(١٠٧٧)، وأحمد ١/ ١٦ و٣٥ و٤٤، والترمذي (١٢٠)، والنسائي في الكبرى (٩٠٥٩) و(٩٠٦٣)، وابن حبان (١٢١٦).\nأخرجه من هذا الطريق بهذا اللفظ: البخاري ١/ ٨٠ (٢٨٧)، ومسلم ١/ ١٧٠ (٣٠٦)، وابن حبان (١٢١٥)، والبيهقي ١/ ٢٠٠ و٢٠١، والبغوي (٢٦٤).\nفي (ب): «توجب»."}],[663,"قلتُ: ليسَ هذا المثالُ مماثلًا لِمَا نحنُ بصدَدِهِ؛ لأنَّ الاعتمادَ فيهِ في الحكمِ بالاتِّصالِ على مذهبِ الجمهورِ، إنَّما هوَ على اللُّقِيِّ (١) والإدراكِ، وذلكَ في هذا الحديثِ مُشْتركٌ متردِّدٌ لتَعَلُّقِهِ بالنبيِّ - صلى الله عليه وآله وسلم -، وبعُمَرَ - رضي الله عنه -، وصُحْبة الراوي ابنِ عمرَ لهما؛ فاقتضى ذلكَ مِنْ جِهَةٍ: كونَهُ رواهُ عَنِ النبيِّ - صلى الله عليه وآله وسلم -، ومِنْ جهةٍ أخرى، كونَهُ رواهُ عَنْ عمرَ، عنْ رسولِ اللهِ - صلى الله عليه وآله وسلم -، واللهُ أعلمُ (٢)."],[664,"الثالثُ: قَدْ ذكرْنا ما حكاهُ ابنُ عبدِ البرِّ مِنْ تعميمِ الحُكْمِ بالاتِّصالِ فيما يذكرُهُ الراوي عَمَّنْ لَقِيَهُ بأيِّ لفظٍ كانَ. وهكذا أطلقَ أبو بكرٍ الشافعيُّ الصَّيْرَفِيُّ (٣) ذلكَ فقالَ: «كُلُّ مَنْ عُلِمَ لَهُ سماعٌ مِنْ إنسانٍ فَحدَّثَ عنهُ فهوَ على السماعِ حَتَّى يُعْلَمَ أنَّهُ لَمْ يَسْمَعْ منهُ ما حكاهُ؛ وكلُّ مَنْ عُلِمَ لَهُ لقاءُ إنسانٍ فحدَّثَ عنهُ فحُكمُهُ هذا الحكمُ» (٤). وإنَّما قالَ هذا فيمَنْ لَمْ يَظهَرْ تدليسُهُ (٥).","",{"fn":"في (جـ) و(م): «اللقاء».\nقَالَ الزركشي ٢/ ٣٧: «قَدْ يقال: بَلْ للتمثيل وجه صَحِيْح، وَهُوَ أنَّهُ إذا كَانَ من مسند ابن عمر اقتضى أن عمر لَمْ يسند في المسند بلفظة «أن»، وكذلك لَمْ يدخل عمارًا في المسند في رِوَايَة «أن»، فجعله ابن شيبة مرسلًا بخلاف عمار، والراوي لهما واحد وَهُوَ ابن الحنفية». وانظر: التقييد والإيضاح: ٨٩.\nهو الإمام الأصولي أبو بكر محمد عبد الله الصيرفي. (ت٣٣٠ هـ). تاريخ بغداد ٥/ ٤٤٩، وطبقات الفقهاء: ١٢٠، وطبقات الشافعية الكبرى ٣/ ١٨٦.\nقال الزركشي ٢/ ٣٨: «رأيته مصرّحًا به في كتابه المسمّى بـ\"الدلائل والأعلام في أصول الأحكام\"».\nقَالَ الزركشي ٢/ ٣٨: «وقول ابن الصَّلاَح: «إنما قال هذا فيمن لم يظهر تدليسه»، يعني: لأنه قال قبل هذا الكلام: «ومن ظهر تدليسه عن غير الثقات لم يقبل خبره حتى يقول: «حدّثني وسمعت». وقال في موضع آخر: «متى قال المحدّث: حدَّثنا فلان عن فلان. قُبِلَ خبرُهُ؛ لأن الظاهر أنه حكى عنه، وإنما توقفنا في المدلّس؛ لعيب ظهر لنا منه، فإن لم يظهر فهو على سلامته، ولو توقفنا في هذا لتوقفنا في «حدّثنا» لإمكان أن يكون حدّث قبيلته وأصحابه، كقول الحسن: «خَطَبَنا فلانٌ بالبصرة»، ولم يكن حاضرًا؛ لأنه احتمال لاغٍ فكذلك من علم سماعه إذا كان غير مدلّس، وكذلك إذا قال الصحابي أبو بكر أو عمر: قال رسول الله - صلى الله عليه وآله وسلم - فهو محمول على السماع، والقائل بخلاف ذلك مغفَّل»."}],[665,"ومِنَ الحجَّةُ في ذلكَ وفي سائرِ البابِ أنَّهُ لوْ لَمْ يَكُنْ قَدْ سَمِعَهُ منهُ لكانَ بإطلاقِهِ الروايةَ عنهُ مِنْ غيرِ ذِكْرِ الواسطةِ بينَهُ وبينَهُ: مُدلِّسًا، والظاهرُ السلامةُ مِنْ وَصْمَةِ التدليسِ، والكلامُ فيمَنْ لَمْ يُعرَفْ بالتدليسِ."],[666,"ومِنْ أمثلةِ ذلكَ قولُهُ: «قالَ فلانٌ كذا وكذا»؛ مثلُ أنْ يقولَ نافِعٌ: «قالَ ابنُ عُمَرَ». وكذلكَ لو قالَ عنهُ: «ذَكَرَ، أو فَعَلَ، أو حَدَّثَ، أو كانَ يقولُ: كذا وكذا»، وما جانسَ ذلكَ فَكُلُّ ذلكَ محمولٌ ظاهرًا على الاتِّصالِ، وأنَّهُ تَلقَّى ذلكَ مِنهُ مِنْ غيرِ واسطةٍ بينهُما مَهْمَا ثَبَتَ لقاؤُهُ لهُ على الجمْلَةِ."],[667,"ثُمَّ مِنْهُمْ مَنِ اقتَصَرَ في هذا الشرطِ المشروطِ في ذلكَ ونحوِهِ على مطلقِ اللِّقاءِ أو السَّماعِ كما حكيناهُ آنِفًا. وقالَ فيهِ أبو عمرٍو المقرئُ (١): «إذا كانَ معروفًا بالروايةِ عنهُ». وقالَ فيهِ أبو الحسنِ القابسيُّ (٢): «إذا أدرَكَ المنقولَ عنهُ إدراكًا بيِّنًا»."],[668,"وذكرَ أبو المظفَّرِ السَّمْعانيُّ في العنعَنةِ: أنَّهُ يُشْتَرطُ طولُ الصُّحبةِ بينَهُمْ (٣). وأنكَرَ مسلمُ بنُ الحجَّاجِ في خُطْبَةِ \" صحيحِهِ \" (٤) على بعضِ أهلِ عصرِهِ (٥) حيثُ اشترطَ في العنعنةِ ثبوتَ اللِّقاءِ والاجتماعِ، وادَّعَى أنَّهُ قولٌ مُخْتَرَعٌ لَمْ يُسْبَقْ قائلُهُ إليهِ، وأنَّ القولَ الشائعَ المتَّفَقَ عليهِ بينَ أهلِ العلمِ بالأخبارِ قديمًا وحديثًا أنَّهُ يَكْفي في ذلكَ أنْ يَثْبُتَ كونُهما في عصرٍ واحدٍ، وإنْ لَمْ يأتِ في خبرٍ قَطُّ أنَّهُما اجتَمَعا أو تَشَافَها.","",{"fn":"هو الداني - كما في المحاسن: ١٥٧ - أبو عثمان بن سعيد بن عثمان الأموي الأندلسي. ت (٤٤٤هـ). معجم الأدباء ١٢/ ١٢٤، وسير أعلام النبلاء ١٨/ ٧٧. والداني: نسبة إلى دانية، مدينة بالأندلس من أعمال بلنسية. انظر: مراصد الاطلاع ٢/ ٥١٠.\nهو أبو الحسن علي بن محمد بن خلف المعافري الأندلسي. ت (٤٠٣ هـ). وفيات الأعيان ٣/ ٣٢٠، تذكرة الحفاظ ٣/ ١٠٧٩. والقابسي: نسبة إلى بلدة قابس، مدينة بإفريقية. انظر: اللباب ٣/ ٥، ومراصد الاطلاع ٣/ ١٠٥٤، وتاج العروس ١٦/ ٣٥٠. وحكى ابن خلكان عنه أنه قال: «سمّوني بالقابسي، وما أنا بالقابسي، وإنما السبب في ذلك أن عمي كان يشد عمامته شدة قابسية، فقيل لعمي: «قابسي»، واشتهرنا بذلك، وإلا فأنا قروي». وانظر: سير أعلام النبلاء ١٧/ ١٦١.\nقواطع الأدلة ١/ ٣٧٤.\nمقدمة صحيح مسلم ١/ ٢٣ - ٢٤.\nانظر: اختصار علوم الحديث لابن كثير ١/ ١٦٩، ونكت الزركشي ٢/ ٣٩، ومحاسن الاصطلاح: ١٥٨، ونكت ابن حجر ٢/ ٥٩٥."}],[669,"وفيمَا قالَهُ مسلمٌ نظرٌ، وقدْ قيلَ: إنَّ القولَ الذي ردَّهُ مسلمٌ هو الذي عليهِ أئمَّةُ هذا العِلْمِ: عليُّ بنُ المدينيِّ، والبخاريُّ، وغيرُهُما، واللهُ أعلمُ (١)."],[670,"قلتُ: وهذا الحكمُ لا أراهُ يستَمرُّ بعدَ المتقدِّمينَ فيما وُجِدَ (٢) مِنَ المصنِّفينَ في تصانيفِهِم، ممَّا ذكروهُ عَنْ مشايخِهِم قائلينَ فيهِ: «ذَكَرَ فلانٌ، قالَ فلانٌ» ونحوُ ذلكَ، فافهمْ كلَّ ذلكَ فإنَّهُ مُهِمٌّ عزيزٌ، واللهُ أعلمُ (٣)."],[671,"الرابعُ: التعليقُ الذي يَذكرُهُ أبو عبدِ اللهِ الحُميديُّ صاحبُ \"الجمعِ بينَ الصحيحينِ\" وغيرُهُ مِنَ المغاربةِ في أحاديثَ مِنْ \" صحيحِ البخاريِّ \" قَطَعَ إسنادَها، وقدِ استعملَهُ الدارَقطنيُّ (٤) مِنْ قبلُ: صُورتُهُ صورةُ الانقطاعِ وليسَ حُكْمُهُ حُكْمَهُ، ولا خارجًا ما وُجِدَ ذلكَ فيهِ منهُ، منْ قبيلِ الصحيحِ إلى قبيلِ الضعيفِ، وذلكَ لما عُرِفَ مِنْ شرطِهِ وحُكْمِهِ (٥) على ما نبَّهنا عليهِ في الفائدةِ السادسةِ مِنَ النوعِ الأوَّلِ (٦).","",{"fn":"انظر: نكت ابن حجر ٢/ ٥٩٥.\nفي نسخة (ب) إشارة إلى أن في نسخة: «مما وجدنا».\nقال ابن حجر ٢/ ٥٩٩: «يعني بالمصنفين غير المحدّثين، فتبين أن ما وجد في عبارات المتقدمين من هذه الصيغ، فهو محمول على السماع بشرطه إلا من عرف من عادته استعمال اصطلاح حادث فلا».\nانظر: الإلزامات ١٥١، ٢٨٣.\nاعترض عليه: بأنا نمنع أن يكون ذلك من شرط البخاري، فإنه سمّى كتابه المسند، فما لم يسنده لم يلتزم تصحيحه. ويؤيده أن ابن القطان الفاسي قال: إن البخاري فيما يعلق من الأحاديث في الأبواب غير مبال بضعف رواتها، فإنها غير معدودة فيما انتخب، وإنما يعد من ذلك ما وصل الأسانيد به فاعلم ذلك. والجواب: أن هذا من ابن الصلاح مبني على قاعدته السابقة في تعاليق البخاري المجزوم بها أنها في حكم المتصلة، وقد سبق بما فيه، ولا ينافيه تسميته بالمسند بل إدخاله لها بصيغة الجزم في الصحيح يدل على أنها مسندة، ولكن حذفه اختصارًا، ولا يظن بالبخاري أن يجزم القول فيما ليس بصحيح عمّن جزم به عنه، فأما إذا ذكر فيما أبرز من السند ضعيفًا، فإنه ليس صحيحًا عند البخاري. قلنا: هذا حاصل كلام الزركشي والعراقي، فانظر: النكت ٢/ ٤٤، والتقييد والإيضاح ٩٠.\nقال الزركشي ٢/ ٤٥: «الذي ذكره هناك تفصيل لا يوافق ما أطلقه هنا، فليتأمل». قلنا: ما أحال عليه ابن الصلاح سبق في: ص وقد أجاد الزركشي بتعقبه هذا، إذ ما سبق كلام على حكم التعليق ="}],[672,"ولا التفاتَ إلى أبي مُحَمَّدِ بنِ حزمٍ الظاهرِيِّ الحافظِ في ردِّهِ (١) ما أخرجَهُ البخاريُّ (٢) مِنْ حديثِ أبي عامرٍ أو أبي مالكٍ الأشعريِّ، عَنْ رسولِ اللهِ - صلى الله عليه وآله وسلم -: «لَيَكُونَنَّ في أُمَّتِي أقوامٌ يَسْتَحِلُّونَ الحريرَ (٣) والْخَمْرَ والْمَعَازِفَ ... الحديثَ» مِنْ جِهةِ أنَّ البخاريَّ أوردَهُ قائلًا فيهِ: قالَ هِشامُ بنُ عمَّارٍ، وساقَهُ بإسنادِهِ، فزَعَمَ ابنُ حَزْمٍ أنَّهُ منقطِعٌ فيما بينَ البخاريِّ وهِشامٍ (٤)، وجَعلَهُ جوابًا عَنِ الاحتجاجِ بهِ على تحريمِ المعازفِ. وأخطأَ في ذلكَ مِنْ وجوهٍ (٥)، والحديثُ صحيحٌ معروفُ الاتِّصالِ بشرطِ الصحيحِ (٦).","",{"fn":"انظر: المحلى ٩/ ٥٩.\nصحيح البخاري ٧/ ١٣٨ (٥٥٩٠).\nفي (أ) هنا: «الحر»، وكتب الناسخ في الحاشية: «الحِرَ والحِرَّ - بالتخفيف والتشديد - الزنى». قلنا: على الرغم من أن هذه الزيادة موافقة للمتن المروي في صحيح البخاري، إلاّ أنها لم ترد في شيء من النسخ الأخرى المعتمدة في التحقيق، فآثرنا عدم إثباتها، رعاية للأمانة العلمية، إذ إجماع النسخ على عدم ذكرها أورث ظنًا قويًا عندنا أن ابن الصلاح روى الحديث على معناه، ولم يذكرها، والله أعلم.\nقال العراقي في التقييد: ٩٠: «إنما قال ابن حزم في المحلى: هذا حديث منقطع لم يتصل فيما بين البخاري وصدقة بن خالد. انتهى. وصدقة بن خالد هو شيخ هشام بن عمار في هذا الحديث، وهذا قريب إلا أن المصنف لا يُجوِّز تغيير الألفاظ في التصانيف وان اتفق المعنى».\nقال النووي في شرح صحيح مسلم ١/ ١٤: «وهذا خطأ من ابن حزم من وجوه: أحدها: أنه لا انقطاع في هذا أصلًا من جهة أن البخاري لقي هشامًا وسمع منه، وقد قررنا في كتابنا \" علوم الحديث \": أنه إذا تحقق اللقاء والسماع مع السلامة من التدليس حمل ما يرويه عنه على السماع بأي لفظ كان، كما يحمل قول الصحابي قال رسول الله - صلى الله عليه وآله وسلم - على سماعه منه إذا لم يظهر خلافه، وكذا غير «قال» من الألفاظ. الثاني: أن هذا الحديث بعينه معروف الاتّصال بصريح لفظه من غير جهة البخاري. الثالث: أنه وإن كان ذلك انقطاعًا فمثل ذلك في الكتابين غير ملحق بالانقطاع القادح لما عرف من عادتهما وشرطهما».\nفقد وصله من طريق هشام بن عمار كل من: ابن حبان (٦٧١٩) قال: «أخبرنا الحسين بن عبد الله القطان، قال: حدّثنا هشام بن عمار». ="}],[673,"والبخاريُّ - رحمه الله - قدْ يفعلُ مِثْلَ ذلكَ؛ لكونِ ذلكَ الحديثِ معروفًا مِنْ جِهةِ الثِّقَاتِ عَنْ ذلكَ الشخصِ الذي عَلَّقَهُ عنهُ، وقدْ يَفعلُ ذلكَ؛ لكونِهِ قدْ ذكرَ ذلكَ الحديثَ في موضعٍ آخرَ مِنْ كِتابِهِ مُسْندًا مُتَّصِلًا، وقدْ يفعلُ ذلكَ لغيرِ ذلكَ منَ الأسبابِ التي لاَ يصحبُها خللُ الانقطاعِ، واللهُ أعلمُ (١).","",{"fn":"اعترض العلاّمة مغلطاي على المصنّف بأن كلامه هذا يحتاج إلى تثبت، فإنه ما رآه لغيره. قال ابن حجر ٢/ ٥٩٩ - ٦٠٠: «قلت: قد سبقه إلى ذلك الإسماعيلي، ومنه نقل ابن الصلاح كلامه، فإنه قال - في المدخل إلى المستخرج الذي صنّفه على صحيح البخاري - ما نصّه: كثيرًا ما يقول البخاري: «قال فلان وقال فلان عن فلان» فيحتمل أن يكون إعراضه عن التصريح بالتحديث لأوجه: أحدها: أن لا يكون قد سمعه عاليًا وهو معروف من جهة الثقات عن ذلك المروي عنه فيقول: قال فلان مقتصرًا على صحته وشهرته من غير جهته. والثاني: أن يكون قد ذكره في موضع آخر بالتحديث، فاكتفى عن إعادته ثانيًا. الثالث: أن يكون سمعه ممن ليس هو على شرط كتابه فنبّه على الخبر المقصود بذكر من رواه لا على وجه التحديث به عنه». ثمَّ ذكر ابن حجر الأسباب الحاملة للبخاري على إيراد ما ليس على شرطه في كتابه وقصرها على ثلاثة: أحدها: أن يكون كرره. والثاني: أن يكون أوردها في معرض المتابعة والاستشهاد. والثالث: أن يكون إيراده لذلك منبّهًا على موضع يوهم تعليل الرواية التي على شرطه."}],[674,"وما ذكرناهُ مِنَ الحكمِ في التعليقِ المذكورِ، فذلكَ فيما أورَدَهُ منهُ أصلًا ومقصودًا، لا فيما أورَدَهُ في مَعْرِضِ الاستشهادِ، فإنَّ الشواهدَ يُحتَملُ فيها ما ليسَ مِنْ شرطِ الصحيحِ مُعَلَّقًا كانَ أو موصولًا."],[675,"ثُمَّ إنَّ لَفْظَ التعليقِ وجدْتُهُ مستعملًا فيما حُذِفَ مِنْ مبتدإِ إسنادِهِ واحدٌ فأكثرُ (١)، حتَّى إنَّ بَعضَهُمُ استعملَهُ في حذفِ كُلِّ الإسنادِ، مثالُ ذلكَ: قولُهُ: «قالَ رسول اللهِ - صلى الله عليه وآله وسلم -: كذا وكذا، قالَ ابنُ عبَّاسٍ: كذا وكذا، روى أبو هريرةَ: كذا وكذا، قالَ سعيدُ بنُ المسيِّبِ عَنْ أبي هريرةَ: كذا وكذا، قالَ الزهريُّ، عَنْ أبي سلمةَ، عَنْ أبي هريرةَ، عَنِ النبيِّ - صلى الله عليه وآله وسلم -: كذا وكذا» (٢)، وهكذا إلى شيوخِ شيوخِهِ. وأمَّا ما أورَدَهُ كذلكَ عَنْ شيوخِهِ فَهُوَ مِنْ قَبِيْلِ ما ذكرناهُ قريبًا في الثالثِ مِنْ هذهِ التفريعاتِ (٣)."],[676,"وبَلَغَني عَنْ بعضِ المتأخِّرينَ مِنْ أهلِ المغربِ أنَّهُ جعلَهُ قسمًا مِنَ التعليقِ ثانيًا، وأضافَ (٤) إليهِ قولَ البخاريِّ - في غيرِ موضعٍ مِنْ كتابِهِ -: «وقالَ لي فلانٌ، وزادَنا (٥) فلانٌ» فوسمَ كلَّ ذلكَ بالتعليقِ المتَّصِلِ مِنْ حيثُ الظاهِرُ، المنفصِلِ مِنْ حيثُ المعنى، وقالَ: مَتَى رأيتَ البخاريَّ يقولُ: «وقالَ لي، وقالَ لنا»؛ فاعلَمْ أنَّهُ إسنادٌ لَمْ يَذكرْهُ للاحتجاجِ بهِ، وإنَّما ذكرَهُ للاستشهادِ بهِ. وكثيرًا ما يُعبِّرُ (٦) المحدِّثونَ بهذا اللفظِ عَمَّا جَرَى (٧) في المذاكراتِ والمناظراتِ، وأحاديثُ المذاكرةِ قَلَّمَا يَحتَجُّونَ بها (٨).","",{"fn":"في (جـ): «وأكثر».\nمن قوله: «قال الزهري ... إلى هنا»، ساقط من (م).\nقال الزركشي ٢/ ٥٣: «يعني: أنه ليس له حكم التعليق، بل حكمه حكم الإسناد المعنعن لسلامة البخاري من التدليس، وسبق أن المصنف خالف هذا في النوع الأول».\nفي (أ): «ومضاف».\nفي (م): «وروانا».\nفي (أ): «يعتبر».\nفي (ع) و(جـ): «مِنْهُمْ».\nقَالَ ابن حجر ٢/ ٦٠١: «لَمْ يصب هَذَا المغربي في التسوية بَيْنَ قوله: قَالَ فُلاَن، وبين قوله: قَالَ لي فُلاَن، فإن الفرق بَيْنَهُمَا ظاهر لا يحتاج إلى دليل فإن «قَالَ لي» مثل التصريح في السَّمَاع، و«قَالَ» المجردة ليست صريحة أصلًا. ="}],[677,"قلتُ: وما ادَّعاهُ على البخاريِّ مخالِفٌ لِمَا قالَهُ مَنْ هُوَ أقدمُ منهُ وأعرفُ بالبخاريِّ وهوَ العبدُ الصالِحُ أبو جَعفرِ بنِ حَمْدانَ النَّيْسابوريُّ (١)، فقدْ رُوِّيْنا عنهُ أنَّهُ قالَ: كُلُّ ما قالَ البخاريُّ: «قالَ لي فلانٌ» فهوَ عَرْضٌ ومُناولَةٌ (٢)."],[678,"قلتُ: وَلَمْ أجدْ لَفظَ التعليقِ مُستعملًا فيما سَقَطَ فيهِ بعضُ رِجالِ الإسنادِ مِنْ وَسَطِهِ أو مِنْ آخرِهِ، ولا في مثلِ قولِهِ: «يُروى عَنْ فلانٍ، ويُذكَرُ عَنْ فلانٍ»، وما أشبَهَهُ ممَّا ليسَ فيهِ جزمٌ على مَنْ ذكرَ ذلكَ عنهُ بأنَّهُ قالَهُ و(٣) ذكرَهُ (٤)."],[679,"وكأنَّ هذا التعليقَ مأخوذٌ مِنْ تعليقِ الجدارِ وتعليقِ الطلاقِ ونحوِهِ، لِما يشتركُ الجميعُ فيهِ مِنْ قطعِ الاتِّصالِ (٥)، واللهُ أعلمُ.","",{"fn":"هو أبو جعفر أحمد بن حمدان الحيري النيسابوري الإمام. ت (٣١١ هـ). تاريخ بغداد ٤/ ١١٥، وسير أعلام النبلاء ١٤/ ٢٩٩، والوافي بالوفيات ٦/ ٣٦٠.\nحكاه الذهبي عن الحاكم، عن ابنه أبي عمرو عنه. سير أعلام النبلاء ١٤/ ٣٠٠.\nفي (ب): «أو».\nقال العراقي في التقييد: ٩٣: «وقد سمّى غير واحد من المتأخرين ما ليس بمجزوم تعليقًا، منهم الحافظ أبو الحجاج المزي، كقول البخاري في باب مسِّ الحرير من غير لبس: «ويروى فيه عن الزبيدي، عن الزهري، عن أنس، عن النبي - صلى الله عليه وآله وسلم -، فذكره المزي في الأطراف، وعلّم عليه علامة التعليق للبخاري، وكذا فعل غير واحد من الحفاظ يقولون ذكره البخاري تعليقًا مجزومًا أو تعليقًا غير مجزوم به، إلا أنه يجوز أن هذا الاصطلاح متجدد، فلا لوم على المصنف في قوله: «إنه لم يجده». وانظر: تحفة الأشراف ١/ ٣٩٠ (١٥٣٣).\nاعترض على المصنف في كون تعليق الطلاق فيه قطع للاتصال. انظر: نكت الزركشي ٢/ ٥٥، ومحاسن الاصطلاح ١٦٢، ونكت ابن حجر ٢/ ٦٠٣."}],[680,"الخامسُ: الحديثُ الذي رواهُ بعضُ الثقاتِ مُرسلًا وبعضُهُم متَّصِلًا (١)، اختلفَ أهلُ الحديثِ في أنَّهُ ملحقٌ بقبيلِ الموصولِ أو بقبيلِ المرسلِ. مثالُهُ: حديثُ: «لا نِكَاحَ إلاَّ بوليٍّ» (٢)، رواهُ إسرائيلُ بنُ يونسَ في آخرينَ عَنْ جَدِّهِ أبي إسحاقَ السَّبِيعِيِّ (٣)، عَنْ أبي بُرْدَةَ، عَنْ أبيهِ (٤) أبي موسى الأشعريِّ، عَنْ رسولِ اللهِ - صلى الله عليه وآله وسلم - مُسْنَدًا هكذا متَّصِلًا، ورواهُ سفيانُ الثوريُّ وشعبةُ، عَنْ أبي إسحاقَ، عَنْ أبي بُرْدَةَ، عَنِ النبيِّ - صلى الله عليه وآله وسلم - مُرسلًا هكذا (٥).","",{"fn":"قال ابن حجر ٢/ ٦٠٥: «ما أدري ما وجه إيراد هذا في تفاريع المعضل، بل هذا قسم مستقل، وهو: تعارض الإرسال والاتصال والرفع والوقف. نعم ... لو ذكره في تفاريع الحديث المعلل لكان حسنًا، وإلاّ فمحلّ الكلام فيه في زيادة الثقات كما أشار إليه. وقد أجبت عنه بأنه لما قال: تفريعات، أراد أنها تنعطف على جميع الأنواع المتقدّمة، ومن جملتها: الموصول والمرسل والمرفوع والموقوف، فعلى هذا فالتعارض بين أمرين فرع عن أصلهما، والله أعلم».\nاعترض على المصنف في تمثيله بهذا الحديث؛ لأن الرواة - كما سيأتي في تخريجه مفصلًا - لم يتفقوا على إرساله من طريق شعبة وسفيان، بل منهم من وصله من طريقهما، ومنهم من أرسله من طريقهما. فانظر: نكت الزركشي ٢/ ٥٦، ونكت ابن حجر ٢/ ٦٠٥.\nبفتح السين وكسر الباء. انظر: تقريب التهذيب (٥٠٦٥).\nسقطت من (ب) و(م).\nهذا الحديث اختلف في وصله وإرساله، والراجح وصله - كما يأتي -: أولًا: تفرّد بإرساله شعبة وسفيان الثوري، واختلف عليهما فيه: فقد رواه عن شعبة موصولًا: النعمان بن عبد السلام، عند الحاكم في المستدرك ٢/ ١٦٩ عنه وعن سفيان الثوري مقرونين، والبيهقي في الكبرى ٧/ ١٠٩، ويزيد بن زريع، عند البزار في مسنده ٢/ ٩٤، والدارقطني في سننه ٣/ ٢٢٠، والبيهقي في سننه الكبرى ٧/ ١٠٩، ومالك بن سليمان، عند الخطيب البغدادي في تاريخ بغداد ٢/ ٢١٤، عنه وعن إسرائيل، وكذلك رواه عن شعبة موصولًا: محمد بن موسى الحرشي، ومحمد بن حصين كما ذكر الدارقطني في العلل ٧/ ٢٠٦، فهؤلاء خمستهم (النعمان بن عبد السلام، ويزيد بن زريع، ومالك بن سليمان، ومحمد بن موسى، ومحمد بن حصين) رووه عن شعبة، عن أبي إسحاق، عن أبي بردة عن أبي موسى، مرفوعًا. ورواه عن شعبة مرسلًا: ="}],[681,"فحَكَى الخطيبُ الحافِظُ (١): أنَّ أكثرَ أصحابِ الحديثِ يَرَوْنَ الْحُكْمَ في هذا وأشباهِهِ للمرسَلِ (٢)."],[682,"وعَنْ بَعضِهِمْ: أنَّ الحكمَ للأكثرِ (٣)."],[683,"وعَنْ بَعضِهِمْ: أنَّ الحكمَ للأحفظِ (٤)، فإذا كانَ مَنْ أرسَلَهُ أحفظُ ممَّنْ وصلَهُ فالحكمُ لِمَنْ أرسَلَهُ، ثُمَّ لا يَقْدَحُ ذلكَ في عدالةِ مَنْ وصَلَهُ وأهليَّتِهِ (٥).","",{"fn":"الكفاية: (٥٨٠ ت، ٤١١ هـ).\nانظر: نكت الزركشي ٢/ ٥٨، ونكت ابن حجر ٢/ ٦٠٣.\nنقله الحاكم عن أئمة الحديث. انظر: المدخل إلى الإكليل: ٤٠ - ٤١.\nنسب الحافظ ابن رجب القول به إلى الإمام أحمد. انظر: شرح علل الترمذي ٢/ ٦٣٥، ومجموع هذه الأقوال أربعة، أضاف إليها ابن السبكي قولًا خامسًا. انظر: جمع الجوامع ٢/ ١٢٤. لكن الأقوى والأصح هو عدم الإطلاق في قبول الزيادة من الثقة، بل القبول والرد دائر مع القرائن التي ترجح لدى الناقد الفهم أحد الجانبين، وفي هذا يقول الحافظ العلائي: «وأما أئمة الحديث فالمتقدمون منهم كيحيى بن سعيد القطان وعبد الرحمن بن مهدي، ومَنْ بعدهما كعلي ابن المديني وأحمد بن حنبل ويحيى بن معين وهذه الطبقة، وكذلك مَنْ بعدهم كالبخاري وأبي حاتم وأبي زرعة الرازيين ومسلم والنسائي والترمذي وأمثالهم، ثم الدارقطني والخليلي كل هؤلاء: يقتضي تصرفهم من الزيادة - قبولًا وردًّا - الترجيح بالنسبة إلى ما يقوى عند الواحد منهم في كل حديث ولا يحكمون في المسألة بحكم كلي يعمّ جميع الأحاديث، وهذا هو الحق الصواب». نظم الفرائد: ٣٧٦ - ٣٧٧، وانظر: نزهة النظر: ٩٦.\nالكفاية: (٥٨٠ ت، ٤١١ هـ)."}],[684,"ومنهمْ مَنْ قالَ: «مَنْ أسندَ حديثًا قدْ أرسَلَهُ الحفَّاظُ فإرسالُهُم لهُ يَقْدحُ في مُسْنِدِهِ، وفي عدالتِهِ وأهليَّتِهِ» (١)."],[685,"ومنهم مَنْ قالَ: «الحكمُ لِمَنْ أسندَهُ، إذا كانَ عدلًا ضابطًا فيُقْبَلُ خبرُهُ، وإنْ خالَفَهُ غيرُهُ سواءٌ كانَ المخالِفُ لهُ واحدًا أو جماعةً» (٢)، قالَ الخطيبُ: «هذا القولُ هوَ الصحيحُ» (٣)."],[686,"قلتُ: وما صحَّحَهُ هوَ الصحيحُ في الفقهِ وأصولِهِ (٤)."],[687,"وسُئِلَ البخاريُّ عنْ حديثِ: «لا نِكَاحَ إلاَّ بوليٍّ» المذكورَ، فحَكَمَ لِمَنْ وصَلَهُ، وقالَ: «الزيادةُ مِنَ الثِّقَةِ مقبولةٌ» (٥). فقالَ البخاريُّ هذا، مَعَ أنَّ مَنْ أرسلَهُ شُعبةُ وسفيانُ، وهما جَبَلانِ لهما مِنَ الحفظِ والإتقانِ الدرجةُ العاليةُ."],[688,"ويلتحقُ بهذا، ما إذا كانَ الذي وصَلَهُ هو الذي أرسلَهُ، وصَلَهُ في وقتٍ وأرسلَهُ في وقتٍ (٦). وهكذا إذا رفعَ بعضُهُمُ الحديثَ إلى النبيِّ - صلى الله عليه وآله وسلم - ووقَفَهُ بعضُهُم على الصحابيِّ أو رفَعَهُ واحدٌ في وقتٍ، ووقَفَهُ هوَ أيضًا في وقتٍ آخرَ، فالحكمُ على الأصحِّ (٧) في كلِّ ذلكَ لِمَا زادَهُ الثقةُ مِنَ الوصْلِ والرفعِ؛ لأنَّهُ مثبتٌ وغيرُهُ ساكتٌ، ولو كانَ نافيًا، فالْمُثْبِتُ مقدَّمٌ عليهِ؛ لأنَّهُ عَلِمَ ما خَفِيَ عليهِ (١)؛ ولهذا الفصلِ تَعَلُّقٌ بفَصْلِ زيادةِ الثقةِ في الحديثِ وسيأتي إنْ شاءَ اللهُ تعالى، وهو أعلمُ.","",{"fn":"الكفاية: (٥٨٠ ت، ٤١١ هـ).\nالكفاية: (٥٨٠ ت، ٤١١ هـ).\nالكفاية: (٥٨١ ت، ٤١١ هـ).\nقال ابن حجر ٢/ ٦١٢: «الذي صحّحه الخطيب: شرطه أن يكون الراوي عدلًا ضابطًا. وأما الفقهاء والأصوليون: فيقبلون ذلك من العدل مطلقًا، وبين الأمرين فرق كثير. وهنا شيء يتعين التنبيه عليه، وهو: أنهم شرطوا في الصحيح أن لا يكون شاذًا، وفسروا الشاذ: بأنه ما رواه الثقة فخالف من هو أضبط منه أو أكثر عددًا، ثم قالوا: تقبل الزيادة من الثقة مطلقًا، وبنوا على ذلك: أن من وصل معه زيادة فينبغي تقديم خبره على من أرسل مطلقًا، فلو اتفق أن يكون من أرسل أكثر عددًا أو أضبط حفظًا أوكتابًا على من وصل أيقبلونه أم لا؟ لا بدَّ من الإتيان بالفرق أو الاعتراف بالتناقض. والحق في هذا أن زيادة الثقة لا تقبل دائمًا، ومن أطلق ذلك عن الفقهاء والأصوليين فلم يصب، وإنما يقبلون ذلك إذا استووا في الوصف ولم يتعرض بعضهم لنفيها لفظًا ولا معنى».\nسنن البيهقي الكبرى ٧/ ١٠٨، والكفاية: (٥٨٢ ت، ٤١٣ هـ). وانظر: نكت الزركشي ٢/ ٦٢.\nقال الزركشي ٢/ ٦٥: «يريد الحكم بوصله لا مجيء كل الخلاف السابق فيه».\nوبه جزم السمعاني، والرازي وأتباعه، وانظر: البحر المحيط ٤/ ٣٤٠ - ٣٤١."}],[689,"النوع الثاني عشر معرفة التدليس، وحكم المدلس"],[690,"(٢)"],[691,"التدليسُ (٣) قِسمانِ (٤):","",{"fn":"قال العراقي في التقييد: ٩٥: «وما صحّحه المصنف هو الذي رجّحه أهل الحديث. وصحّح الأصوليون خلافه، وهو أن الاعتبار بما وقع منه أكثر، فإن وقع وصله أو رفعه أكثر من إرساله أو وقفه، فالحكم للوصل والرفع، وإن كان الإرسال أو الوقف أكثر فالحكم له».\nانظر في التدليس: معرفة علوم الحديث: ١٠٣، والمدخل إلى الإكليل: ٢٠، والكفاية: (٥٠٨ ت، ٣٥٥ هـ)، والتمهيد ١/ ١٥، وجامع الأصول ١/ ١٦٧، والإرشاد ١/ ٢٠٥، والتقريب: ٦٣، والاقتراح: ٢٠٩، والمنهل الروي: ٧٢، والخلاصة: ٧٤، والموقظة: ٤٧، وجامع التحصيل: ٩٧، واختصار علوم الحديث: ٥٣، والمقنع: ١/ ١٥٤، وشرح التبصرة والتذكرة ١/ ٣٠٣، ونزهة النظر: ١١٣، ومقدمة طبقات المدلسين: ١٣، والمختصر: ١٣٢، وفتح المغيث ١/ ١٦٩، وألفية السيوطي: ٣٣، وشرح السيوطي على ألفية العراقي: ١٧٣، وفتح الباقي ١/ ١٧٩، وتوضيح الأفكار ١/ ٣٤٦، وظفر الأماني: ٣٧٣، وقواعد التحديث: ١٣٢.\nالتدليس: مأخوذ من الدَّلَس - بالتحريك - وهو اختلاط الظلام الذي هو سبب لتغطية الأشياء عن البصر. قال ابن حجر: وكأنه أظلم أمره على الناظر لتغطية وجه الصواب فيه. ومنه التدليس في البيع، يقال: دلَّس فلان على فلان، أي: ستر عنه العيب الذي في متاعه كأنه أظلم عليه الأمر، وأصله مما ذكرنا - من الدَّلَس -. وهو في الاصطلاح راجع إلى ذلك من حيث إن مَن أسقط مِنَ الإسناد شيئًا فقد غطّى ذلك الذي أسقطه، وزاد في التغطية في إتيانه بعبارة موهمة، وكذا تدليس الشيوخ فإن الراوي يغطّي الوصف الذي يُعرف به الشيخ أو يغطّي الشيخ بوصفه بغير ما يشتهر به. انظر: نكت ابن حجر ٢/ ٦١٤، والنكت الوفية ١٣٧ / أ، وتاج العروس ١٦/ ٨٤.\nليس الأمر كما ذكر المصنف هنا، بل هناك أقسام أُخر أغفل المصنّف ذكرها، منها: تدليس التسوية، وتدليس القطع، وتدليس العطف، وغيرها. انظر في هذا وفي تفصيل هذه الأنواع: نكت الزركشي ٢/ ٩٨ و١٠١ وما بعدها، والتقييد والإيضاح: ٩٥، ونكت ابن حجر ٢/ ٦١٦، وقارن بـ: النكت الوفية ١٣٧ / أ."}],[692,"أحدُهُما: تدليسُ الإسنادِ: وهوَ أنْ يرويَ عَمَّنْ لَقِيَهُ ما لَمْ يَسْمَعْهُ منهُ، مُوهِمًا أنَّهُ سَمِعَهُ منهُ (١)، أو عَمَّنْ عاصَرَهُ ولَمْ يَلْقَهُ، مُوهِمًا أنَّهُ قَدْ لَقِيَهُ وَسَمِعَهُ منهُ. ثُمَّ قدْ يكونُ بينَهُما واحِدٌ وقدْ يكونُ أكثرُ. ومِنْ شَأنِهِ أنْ لا يقولَ في ذلكَ: «أخبرنا فلانٌ»، ولا"],[693,"«حدَّثنا»، وما أشبَهَهُما. وإنَّما يقولُ: «قالَ فلانٌ أو عَنْ فلانٍ»، ونحوَ ذلكَ (٢). مثالُ ذلكَ: «ما رُوِّيْنا عَنْ عليِّ بنِ خَشْرَمٍ (٣) قالَ: كُنَّا عندَ ابنِ عُيينةَ، فقالَ:"],[694,"«الزهريُّ»، فقيلَ لهُ: «حَدَّثَكُمُ الزهريُّ؟»، فسَكَتَ، ثُمَّ قالَ: «الزهريُّ»، فقيلَ لهُ: «سَمِعْتَهُ مِنَ الزهريِّ؟»، فقالَ: «لا، لَمْ أسمعْهُ مِنَ الزهريِّ، ولا ممَّنْ سَمِعَهُ مِنَ الزهريِّ، حدَّثَني عبدُ الرَّزَّاقِ، عَنْ مَعْمَرٍ، عَنِ الزهريِّ» (٤).","",{"fn":"هذا ليس من التدليس في شيء، على قول ابن حجر، بل هو من باب المرسل الخفي، وحاصل كلامهم أن في هذا الباب صورًا هي: ١ - الاتّصال: وهو الرواية عمّن عاصره وسمع منه، ما قد سمعه منه. ٢ - الانقطاع: وهو الرواية عمَّن لَم يعاصره أصلًا. ٣ - الإرسال الخفي: وهو الرواية عمَّن عاصره ولم يسمع منه. ٤ - التدليس: هو الرواية عمّن عاصره وسمع منه، ما لم يسمعه منه. وانظر: نكت الزركشي ٢/ ٦٨، والتقييد والإيضاح ٩٧، ونكت ابن حجر ٢/ ٦١٤، وأثر علل الحديث في اختلاف الفقهاء: ٦٠ وما بعدها.\nقال الزركشي ٢/ ٧٠: «أي: أن «فلانًا» ومثله، إن أسقط ذلك ويسمي الشيخ فقط، فيقول: «فلان» كما تراه في حكاية ابن عيينة».\nبمعجمتين، وزن: جَعْفَر. التقريب (٤٧٢٩).\nأسند هذه القصة الحاكم في المدخل إلى الإكليل: ٢٠ - ٢١، وفي معرفة علوم الحديث: ١٠٥، والخطيب في الكفاية: (٥١٢ ت، ٣٥٩ هـ). قال الزركشي ٢/ ٧٠: «هكذا مثّل هذا القسم، ثم حكى الخلاف فيمن عرف به هل يرد حديثه مطلقًا، أو ما لم يصرّح فيه بالاتصال؟ وهو يقتضي جريانه في ابن عيينة، وهو مردود، فإن ابن عبد البر حكى عن أئمة الحديث أنهم قالوا: يقبل تدليس ابن عيينة؛ لأنه إذا وقف أحال على ابن جريج ومعمر ونظرائهما. وقال الكرابيسي: دلّس ابن عيينة عن مثل معمر ومسعر بن كدام ومالك بن مغول. وقال الحاكم في سؤالاته للدارقطني: سُئِل عن تدليس ابن جريج، فقال: يتجنب تدليسه، فإنه وحش التدليس لا يدلس إلاّ فيما سمعه من مجروح، فأما ابن عيينة فإنه يدلّس عن الثقات. ="}],[695,"القسمُ الثاني: تدليسُ الشيوخِ، وهوَ أنْ يرويَ عَنْ شيخٍ حديثًا سَمِعَهُ مِنْهُ، فيُسَمِّيَهُ، أو يَكْنِيَهُ أو يَنْسُبَهُ، أو يَصِفَهُ بما لا يُعْرَفُ بهِ كيْ لا (١) يُعرَفُ (٢)، مِثالُهُ: ما رُويَ لنا عَنْ أبي بكرِ بنِ مجاهِدٍ الإمامِ المقرئِ أنَّهُ رَوَى عَنْ أبي بكرٍ عبدِ اللهِ بنِ أبي داودَ السِّجِسْتانيِّ، فقالَ: حدَّثَنا عبدُ اللهِ بنُ أبي عبدِ اللهِ، وروى عَنْ أبي بكرٍ محمدِ بنِ الحسنِ النَّقَّاشِ (٣) الْمُفَسِّرِ المُقرئِ فقالَ: «حدَّثَنا محمدُ بنُ سَنَدٍ، نسبَهُ إلى جدٍّ لهُ» (٤)، واللهُ أعلمُ."],[696,"أمَّا القسمُ الأوَّلُ فمكروهٌ جدًّا، ذمَّهُ أكثَرُ العلماءِ (٥)، وكانَ شُعبةُ مِنْ أشدِّهِم ذَمًّا لهُ، فرُوِّيْنا عَنِ الشافعيِّ الإمامِ، عنهُ (٦) أنَّهُ قالَ: «التدليسُ أخو الكَذِبِ» (٧). ورُوِّيْنا عنهُ أنَّهُ قالَ: «لأنْ أزنيَ أحبُّ إليَّ مِنْ أنْ أُدَلِّسَ» (١)، وهذا مِنْ شُعبَةَ إفراطٌ محمولٌ على المبالغةِ في الزَّجْرِ عنهُ والتَّنْفِيرِ (٢).","",{"fn":"في (جـ): «لئلاّ».\nقال الزركشي ٢/ ٧٦: «أي: لكونه ضعيفًا أو متأخر الوفاة قد شارك الراوي عنه جماعة دونه في السماع منه، أو يكون أصغر من الراوي سنًّا، أو تكون أحاديثه التي عنده كثيرة فلا يحب تكرار الرواية عنه». وانظر: محاسن الاصطلاح ١٦٧، ونكت ابن حجر ٢/ ٦١٥.\nبفتح النون والقاف المشدّدة، هذه النسبة إلى من ينقش السقوف والحيطان وغيرهما، وكان أبو بكر المذكور في مبدأ أمره يتعاطى هذه الصنعة فعرف بها، ت (٣٥١ هـ). ترجمته في: تاريخ بغداد ٢/ ٢٠١، وتاريخ دمشق ٥٢/ ٣٢٠، ووفيات الأعيان ٤/ ٢٩٨، وسير أعلام النبلاء ١٥/ ٥٧٣.\nقال الزركشي ٢/ ٨١: «يقتضي كراهة ذلك، ولهذا جعله تدليسًا، وحكى ابن الموّاق في \" بغية النقاد \" خلافًا في نسبة الرجل إلى جده، واختار التفصيل بين المشهور به فيجوز ذلك، وإلاَّ فلا؛ لِما فيه من إبهام أمرهم وتعمية طريق معرفتهم».\nقال الزركشي ٢/ ٨١: «أي: ومنهم من سهله، قال أبو بكر البزار في مسنده: التدليس ليس بكذب، وإنما هو تحسين لظاهر الإسناد».\nالضمير في قوله: «عنه» يعود على شعبة.\nرواه ابن عدي في كامله ١/ ١٠٧، والبيهقي في مناقب الشافعي ٢/ ٣٥، والخطيب في الكفاية: (٥٠٨ ت، ٣٥٥ هـ)."}],[697,"ثُمَّ اختلفُوا في قَبولِ روايةِ مَنْ عُرِفَ بهذا التدليسِ فجعلَهُ فريقٌ مِنْ أهلِ الحديثِ والفقهاءِ مجروحًا بذلكَ، وقالوا: لا تُقبَلُ روايتُهُ بحالٍ، بَيَّنَ السَّمَاعَ أوْ لَمْ يُبَيِّنْ (٣)."],[698,"والصحيحُ التفصيلُ: وأنَّ ما رواهُ المدلِّسُ بلفظٍ مُحتَملٍ لَمْ يُبَيِّنْ فيهِ السماعَ والاتِّصالَ، حُكْمُهُ حُكْمُ المرسَلِ وأنواعِهِ (٤)، وما رواهُ بلفظٍ مُبيِّنٍ للاتِّصالِ (٥)، نحوُ"],[699,"«سَمِعْتُ، وحدَّثَنا، وأخبَرَنا» وأشباهِها، فهو مقبولٌ محتجٌّ بهِ."],[700,"وفي \" الصحيحينِ \" وغيرِهِما مِنَ الكُتُبِ المعتمدةِ مِنْ حديثِ هذا الضَّرْبِ كثيرٌ جدًّا، كقتادةَ، والأعمشِ، والسُّفيَانَيْنِ، وهُشَيْمِ (٦) بنِ بَشِيْرٍ، وغيرِهِمْ (٧).","",{"fn":"رواه ابن أبي حاتم في تقدمة الجرح والتعديل ١/ ١٧٣، وابن عدي في الكامل ١/ ١٠٧، والخطيب في الكفاية: (٥٠٨ ت، ٣٥٦ هـ).\nقال البلقيني: «وهذا الذي قاله شعبة ظاهر، فإن آفة التدليس لها ضرر كبير في الدين، وهي أضر من أكل الربا، وقد جاءت أحاديث محتجّ بها تدلّ على أن أكل درهم من ربًا أشد من الزنا ... إلى آخر كلامه. محاسن الاصطلاح: ١٧٠، وانظر: النكت الوفية ١٤٢ / أ.\nانظر تعليقًا طويلًا مفيدًا للزركشي في نكته ٢/ ٨٦.\nقال الزركشي ٢/ ٩٢: «يستثنى من هذا ما إذا كان المدلِّس لا يدلِّس إلا عن ثقة، فإنه تقبل روايته وإن لم يُبيِّن السماع، كسفيان بن عيينة». قال ابن حجر ٢/ ٦٢٤: «وبذلك صرّح أبو الفتح الأزدي، وأشار إليه الفقيه أبو بكر الصيرفي في \" شرح الرسالة \". وجزم بذلك أبو حاتم بن حبان وأبو عمر بن عبد البر وغيرهما في حق سفيان بن عيينة».\nفي (ب) و(ع): «الاتصال».\nبالتَّصغيرِ، والده بَشِيْر: بوزن (عَظِيْم). تقريب التهذيب (٧٣١٢).\nقال الزركشي ٢/ ٩٢: «هكذا ذكره محتجًا به على قبول رواية المدلس إذا صرّح بالاتصال، وليس هذا من موضع النزاع، قال النووي في مختصره: «ما كان في الصحيحين وغيرهما من الكتب الصحيحة عن المدلسين بـ «عن» فمحمول عَلَى ثبوت سماعه من جهة أخرى». وكذا قَالَ الحَافِظ الحلبي في القِدْح المُعَلَّى: «إن المعنعنات الَّتِي في الصحيحين منزَّلة مَنْزِلة السماع». وتوقف في ذلك من المتأخرين الشيخ صدر الدين بن الوكيل، وقال في كتابه الإنصاف: «لعمر الله إن="}],[701,"وهذا؛ لأنَّ التدليسَ ليسَ كَذِبًا، وإنَّما هوَ ضَرْبٌ مِنَ الإيْهامِ بلفظٍ مُحْتَملٍ، والْحُكْمُ بأنَّهُ لا يُقْبَلُ مِنَ المدلِّسِ حَتَّى يُبَيِّنَ، قدْ أجراهُ الشافِعِيُّ - رضي الله عنه - فيمَنْ عَرَفناهُ دلَّسَ مرَّةً (١)، واللهُ أعلمُ."],[702,"وأمَّا القسمُ الثاني فأمرُهُ أخفُّ، وفيهِ تضْييعٌ للمَرْوِيِّ عنهُ، وتَوعِيرٌ لطريقِ معرفِتِهِ على مَنْ يطلُبُ الوقوفَ على حالِهِ وأهليَّتِهِ (٢). ويختلِفُ الحالُ في كراهَةِ ذلكَ بحسَبِ الغرضِ الحاملِ عليهِ، فقدْ يحمِلُهُ على ذلكَ كونُ شيخِهِ الذي غَيَّرَ سِمَتَهُ غيرَ ثقةٍ (٣)، أو كونُهُ متأخِّرَ الوفاةِ قدْ شاركَهُ في السماعِ منهُ جماعةٌ دُونَهُ، أو كونُهُ أصغرَ سِنًّا مِنَ الراوي عَنْهُ، أو كونُهُ كثيرَ الروايةِ عنهُ، فلا يُحِبُّ الإكثارَ مِنْ ذِكْرِ شَخْصٍ واحدٍ على صورةٍ واحدةٍ (١).","",{"fn":"«قلت: يشير إلى أن العادة في التدليس يثبت بمرة؛ لأنه نوع جرح. وقد رأيت نص الشافعي في الرسالة بذلك، فقال: «ومن عرفناه دلّس مرة فقد أبان لنا عورته في روايته، وليست تلك العورة بكذب فيرد بها حديثه، ولا نصيحة في الصدق فنقبل منه ما قبلناه من أهل النصيحة والصدق، فقلنا: لا يقبل من مدلّس حديثًا حتى يقول فيه: «حدَّثَني»، و«أخبرني». ومعناه: أنه إذا قال المدلس بلفظ محتمل السماع وعدمه لا يقبل منه حتّى يبين أنه سمعه منه أو سمعه ممّن سمعه منه، وقد حكم البيهقي بعدم قبول قول من دلّس مرة واحدة ... . ثمَّ إذا بيّن أنه سمعه ممّن أسند الخبر إليه قبل، وإن لم يبين أنه سمعه ممَّن سمعه منه فقد تأكّد فيه شيء فيه الخلاف». قاله بحروفه الزركشي ٢/ ٩٧ - ٩٨.\n«توعير الطريق قد يكون لامتحان الأذهان في استخراج المدلسات واختبار الحفظ، وقد يكون لغير ذلك، فتحصل المفسدة». المحاسن: ١٧١، وانظر: الاقتراح ٢١٤ - ٢١٥، ونكت الزركشي ٢/ ٩٨.\nكما فعل ذلك عطية العوفي إذ روى عن الكلبي -وهو ضعيف- كنَّاه أبا سعيد - وهو مشهور بأبي النضر -، يوهم أنه يروي عن أبي سعيد الخدري. انظر: الكفاية (٥٢١ ت، ٣٦٦ هـ)."}],[703,"وتَسَمَّحَ بذلكَ جماعةٌ مِنَ الرواةِ المصنِّفينَ، منهم: الخطيبُ أبو بكرٍ، فقدْ كانَ لَهِجًا (٢) بهِ في تصانِيْفِهِ (٣)، واللهُ أعلمُ.","",{"fn":"الأسباب الحاملة للرواة على التدليس متعددة، ولكنها تختلف بالنسبة للثقات عمّا هي عليه بالنسبة للضعفاء، فأمّا الأسباب الحاملة للثقات على التدليس فهي: ١ - الاختصار. ٢ - العلو بذكر ذلك الشيخ دون من دونه؛ لصحة روايته وجزمه بتحديث الثقات ذلك عنه. ٣ - وقوع منافرة بين الراوي والمروي عنه. وأما الأسباب الحاملة للضعفاء على التدليس فهي: ١ - تعمية الأمر على الباحث، كون المروي عنه ضعيفًا أو مجهولًا، فيتركون ذكره ويذكرون مَنْ فوقه. ٢ - تعمية الأمر على الباحث، كون المروي عنه ضعيفًا مشهور الضعف وله أسماء ونعوت متعددة، فيسمّوه بغير ما شهر به. ٣ - تعمية الأمر على الباحث، كون المروي عنه ضعيفًا قد اشترك مع آخر مقبول في الطبقة والكنية ورواية الراوي عن الاثنين. انظر: نكت الزركشي ٢/ ١٣٠ - ١٣٢.\nلَهِجَ بالأمرِ لَهَجًا: أُولِعَ بهِ فثابر عليه واعتاده، فهو لَهِج ولاهِج. ويقال: فلان مُلْهَجٌ بهذا الأمر، أي: مُولَعٌ به، واللَّهَجُ بالشيءِ: الولوعُ به. انظر: لسان العرب ٢/ ١٦٩، والمعجم الوسيط ٢/ ٨٤١.\nقال ابن الصلاح ص: «والخطيب الحافظ يروي في كتبه عن أبي القاسم الأزهري، وعن عبيد الله بن أبي الفتح الفارسي، وعن عبيد الله بن أحمد بن عثمان الصيرفي، والجميع شخص واحد من مشايخه. وكذلك يروي عن الحسن بن محمد الخلال، وعن الحسن بن أبي طالب، وعن أبي محمد الخلال، والجميع عبارة عن واحد. ويروي أيضًا عن أبي القاسم التنوخي، وعن علي بن المحسن، وعن القاضي أبي القاسم على بن المحسن التنوخي، وعن علي بن أبي علي المعدل، والجميع شخص واحد، وله من ذلك الكثير، والله أعلم»."}],[704,"النوع الثالث عشر معرفة الشاذ"],[705,"(١)"],[706,"رُوِّيْنا عَنْ يونُسَ بنِ عبدِ الأعلى قالَ: قالَ ليَ الشافِعِيُّ - رحمه الله -: «ليسَ (٢) الشاذُّ (٣) مِنَ الحديثِ أنْ يروِيَ الثِّقَةُ ما لا يرويَ غيرُهُ، إنَّما الشاذُّ: أنْ يرويَ الثِّقَةُ حديثًا يخالِفُ ما روَى الناسُ» (٤)."],[707,"وحَكَى الحافِظُ أبو يَعْلَى الخليليُّ القَزْوِينيُّ نحوَ هذا عَنِ الشافعيِّ وجماعةٍ مِنْ أهلِ الحِجازِ (٥). ثُمَّ قالَ: «الذي عليهِ حُفَّاظُ الحديثِ أنَّ الشاذَّ ما ليسَ لهُ إلاَّ إسنادٌ واحدٌ يَشذُّ بذلكَ شيخٌ، ثقةً كانَ أو غيرَ ثقةٍ، فما كانَ عَنْ غيرِ ثقةٍ فمتروكٌ لا يُقبَلُ، وما كانَ عَنْ ثقةٍ يُتَوَقَّفُ فيهِ ولا يُحْتَجُّ بهِ» (٦).","",{"fn":"انظر في الشاذ: معرفة علوم الحديث: ١١٩، وجامع الأصول ١/ ١٧٧، والإرشاد ١/ ٢١٣، والتقريب: ٦٧، والاقتراح: ١٩٧، والمنهل الروي: ٥٠، والخلاصة: ٦٩، والموقظة: ٤٢، ونظم الفرائد: ٣٦١، واختصار علوم الحديث: ٥٦، والمقنع ١/ ١٦٥، وشرح التبصرة والتذكرة ١/ ٣٢٠، ونزهة النظر: ٩٧، والمختصر: ١٢٤، وفتح المغيث ١/ ١٨٥، وألفية السيوطي: ٣٩، وشرح السيوطي على ألفية العراقي: ١٧٧، وفتح الباقي ١/ ١٩٢، وتوضيح الأفكار ١/ ٣٧٧، وظفر الأماني: ٣٥٦، وقواعد التحديث: ١٣٠.\nفي (جـ): «وليس».\nالشاذ لغة: المنفرد، يقال: شذَّ يَشُذُّ ويَشِذُّ - بضم الشين وكسرها - أي: انفرد عن الجمهور. وشذَّ الرجلُ: إذا انفرد عن أصحابه. وكذلك كلّ شيء منفرد فهو شاذٌّ. ومنه: هو شاذٌّ من القياس، وهذا مما يشذُّ عن الأصول، وكلمة شاذَّة ... وهكذا. انظر: الصحاح ٢/ ٦٤، وتاج العروس ٩/ ٤٢٣.\nرواه عن الشافعي: الحاكم في معرفة علوم الحديث: ١١٩، والخليلي في الإرشاد ١/ ١٧٦، والبيهقي في معرفة السنن والآثار ١/ ٨١ - ٨٢، والخطيب في الكفاية: (٢٢٣ ت، ١٤١ هـ).\nالإرشاد ١/ ١٧٦، وانظر: نكت الزركشي ٢/ ١٣٨.\nالإرشاد ١/ ١٧٦ - ١٧٧."}],[708,"وذَكَرَ الحاكِمُ أبو عبدِ اللهِ الحافِظُ أنَّ الشاذَّ هوَ الحديثُ الذي ينفَرِدُ (١) بهِ ثقةٌ مِنَ الثِّقاتِ وليسَ لهُ أصلٌ بمُتابِعٍ لذلكَ الثقةِ (٢). وذَكَرَ أنَّهُ يُغَايرُ المعلَّلَ مِنْ حيثُ إنَّ المعلَّلَ وُقِفَ على عِلَّتِهِ الدالَّةِ على جِهَةِ الوَهَمِ فيهِ، والشاذُّ لَمْ يُوقَفْ فيهِ عَلَى عِلَّتِهِ كذلكَ."],[709,"قُلْتُ: أمَّا ما حَكَمَ الشافِعيُّ عليهِ بالشذوذِ فلا إشكالَ (٣) في أنَّهُ شاذٌّ غيرُ مقبولٍ، وأمَّا ما حكيناهُ عَنْ غَيْرِهِ فَيُشْكِلُ بما ينفَرِدُ (٤) بهِ العدْلُ الحافظُ الضابطُ، كحديثِ:"],[710,"«إنَّما الأعمالُ بالنِّيَّاتِ» (٥)، فإنَّهُ حديثٌ فَرْدٌ، تفرَّدَ بهِ: عُمَرُ - رضي الله عنه - عَنْ رسولِ اللهِ - صلى الله عليه وآله وسلم - ثُمَّ تَفرَّدَ بهِ عَنْ عُمَرَ: عَلْقمةُ بنُ وقَّاصٍ، ثُمَّ عَنْ عَلْقمةَ: محمدُ بنُ إبراهيمَ، ثُمَّ عنهُ: يحيى بنُ سعيدٍ على ما هوَ الصحيحُ عِندَ أهلِ الحديثِ (٦).","",{"fn":"في (أ) و(ب): «يتفرد».\nمعرفة علوم الحديث: ١١٩.\n«فيه نظر لِمَا أبديته آخرًا، وعلى المصنّف إشكال أشد منه وذلك أنه يشترط في الصحيح أن لا يكون شاذًّا كما تقدّم، ويقول: إنه لو تعارض الوصل والإرسال قُدِّم الوصل مطلقًا سواء كان رواة الإرسال أكثر أو أقل، حفظ أم لا. ويختار في تفسير الشاذ أنه الذي يخالف راويه من هو أرجح منه. وإذا كان راوي الإرسال أحفظ ممن روى الوصل مع اشتراكهما في الثقة، فقد ثبت كون الوصل شاذًا، فكيف يحكم له بالصحة مع شرطه في الصحة أن لا يكون شاذًا؟ هذا في غاية الإشكال. ويمكن أن يجاب عنه بأن اشتراط نفي الشذوذ في شرط الصحة إنما يقوله المحدِّثون، وهم القائلون بترجيح رواية الأحفظ ... الخ». نكت ابن حجر ٢/ ٦٥٣ - ٦٥٤.\nفي (ع) والتقييد: «يتفرد».\nأخرجه الحميدي (٢٨)، وأحمد ١/ ٢٥، ٤٣، والبخاري ١/ ٢ (١)، و١/ ٢١ (٥٤)، و٣/ ١٩٠ (٢٥٢٩)، و٥/ ٧٢ (٣٨٩٨) و٧/ ٤ (٥٠٧٠)، و٨/ ١٧٥ (٦٦٨٩)، و٩/ ٢٩ (٦٩٥٣)، ومسلم ٦/ ٤٨ (١٩٠٧)، وأبو داود (٢٢٠١)، وابن ماجه (٤٢٢٧)، والترمذي (١٦٤٧)، والنسائي ١/ ٥٨ و٦/ ١٥٨ و٧/ ١٣ وفي الكبرى (٧٨) و(٤٧٣٦) و(٥٦٣٠)، وابن خزيمة (١٤٢) و(١٤٣) و(٤٥٥).\nاعترض عليه بأمرين: أحدهما: أن الخليلي والحاكم إنما ذكرا تفرد الثقة فلا يرد عليهما تفرد الحافظ لما بينهما من الفرقان. والأمر الثاني: أن حديث النيّة لَم ينفرد عمر به، بل رواه أبو سعيد الخدري وغيره عن النبي - صلى الله عليه وآله وسلم - فيما ذكره الدارقطني وغيره. انتهى ما اعترض به عليه. ="}],[711,"وأوضَحُ مِنْ ذلكَ في ذلكَ: حديثُ عبدِ اللهِ بنِ دينارٍ، عَنِ ابنِ عُمَرَ: «أنَّ النبيَّ - صلى الله عليه وآله وسلم - نَهَى عَنْ بَيْعِ الوَلاءِ وهِبَتِهِ (١» (٢)، تَفَرَّدَ بهِ عبدُ اللهِ بنُ دينارٍ (٣). وحديثُ مالكٍ، عَنِ الزهريِّ، عَنْ أنسٍ: «أنَّ النبيَّ - صلى الله عليه وآله وسلم - دَخَلَ مَكَّةَ وعلى رأسِهِ المِغْفَرُ (٤» (٥)، تَفَرَّدَ بهِ مالكٌ عنِ الزهريِّ (١). فكلُّ هذهِ مُخَرَّجَةٌ في الصحيحينِ معَ أنَّهُ ليسَ لها إلاَّ إسنادٌ واحدٌ تَفَرَّدَ بهِ ثقةٌ. وفي غرائبِ الصحيحِ أشباهٌ لذلكَ غيرُ قليلةٍ. وقد قالَ مسلمُ بنُ الحجَّاجِ: «للزهريِّ نحوُ (٢) تسعينَ حرفًا يرويهِ (٣) عَنِ النبيِّ - صلى الله عليه وآله وسلم - لا يُشاركُهُ فيها أحدٌ، بأسانيدَ جِيَادٍ» (٤)، واللهُ أعلمُ. فهذا الذي ذكرناهُ وغيرُهُ مِنْ مذاهِبِ أئمَّةِ الحديثِ يُبَيِّنُ لكَ أنَّهُ ليسَ الأمرُ في ذلكَ على الإطلاقِ الذي أتى بهِ الخليليُّ والحاكمُ (٥)، بلِ الأمرُ في ذلكَ على تفصيلِ نُبَيِّنَهُ فنقولُ:","",{"fn":"في (جـ): «أوهبته».\nأخرجه: مالك (٢٢٦٨)، والحميدي (٦٣٩)، وأحمد ٢/ ٩ و٧٩ و١٠٧، والدارمي (٢٥٧٥) و(٣١٦٠) و(٣١٦١)، والبخاري ٣/ ١٩٢ (٢٥٣٥)، و٨/ ١٩٢ (٦٧٥٦)، ومسلم ٤/ ٢١٦ (١٥٠٦)، وأبو داود (٢٩١٩)، وابن ماجه (٢٧٤٧)، والترمذي (١٢٣٦) و(٢١٢٦)، والنسائي ٧/ ٣٠٦، وفي الكبرى (٦٢٥٣) و(٦٢٥٤) و(٦٢٥٥)، والبيهقي ١٠/ ٢٩٢، وانظر: التمهيد ١٦/ ٣٣٣.\nقال مسلم عقب تخريجه: «الناس كلهم عيال على عبد الله بن دينار في هذا الحديث». وقال الترمذي عقب (١٢٣٦): «هذا حديث حسن صحيح لا نعرفه إلا من حديث عبد الله بن دينار، عن ابن عمر».\nفي (ع) والتقييد: «مغفر». والمِغْفَر - كَمِنْبَر - زَرَدٌ مِنَ الدرعِ ينسج على قدر الرأس، يلبس تحت القَلَنْسُوَةِ. انظر: التاج ١٣/ ٢٤٨.\nرواه مالك في الموطأ (١٢٧١)، ومن طريقه أخرجه: الحميدي (١٢١٢)، وابن أبي شيبة ١٤/ ٤٩٢، وأحمد ٣/ ١٠٩ و١٦٤ و١٨٠ و٢٢٤ و٢٣١ و٢٣٢ و٢٤٠، والدارمي (١٩٤٤) و(٢٤٦٠)، والبخاري ٣/ ٢١ (١٨٤٦) و٤/ ٨٢ (٣٠٤٤) و٥/ ١٨٨ (٤٢٨٦)، ومسلم ٤/ ١١١ (١٣٥٧)، وأبو داود (٢٦٨٥)، وابن ماجه (٢٨٠٥)، والترمذي (١٦٩٣)، وفي الشمائل (١١٢)، والنسائي ٥/ ٢٠٠ و٢٠١، وابن خزيمة (٣٠٦٣)، والطحاوي في شرح المشكل (٤٥١٩) و(٤٥٢٠)، وفي شرح المعاني ٢/ ٢٥٨، وأبو يعلى (٣٥٣٩) و(٣٥٤٠) و(٣٥٤٢)، وابن حبان (٣٧١٩) و(٣٧٢١) و(٣٨٠٥)، والبيهقي ٧/ ٥٩ و٨/ ٢٠٥، والبغوي (٢٠٠٦).\nقال الترمذي عقب تخريجه: «لا نعرف كبير أحد رواه غير مالك عن الزهري». قال ابن عبد البر في التمهيد ٦/ ١٥٩ - ١٦٠: «هذا حديث انفرد به مالك - رحمه الله - لا يحفظ عن غيره، ولم يروه أحد عن الزهري سواه من طريق يصح ... ولا يثبت أهل العلم بالنقل فيه إسنادًا غير حديث مالك». قال العراقي ١٠٥: «قد ورد من عدّة طرق غير طريق مالك من رواية ابن أخي الزهري وأبي أويس عبد الله بن عبد الله بن أبي عامر ومعمر والأوزاعي كلهم عن الزهري ...». وقد تتبع ابن حجر في نكته ٢/ ٦٥٦ - ٦٧٠، هذه الطرق فأوصلها إلى ثلاثة عشر طريقًا عن الزهري رويت عن غير مالك وأشار إليها ابن حجر في النكت الظراف ١/ ٣٨٩، ولكن هذه الطرق لا يصح منها شيء، كما بينه الدكتور بشار عواد في التعليق على تحفة الأشراف (١٥٢٧). وانظر: النكت الوفية ١٤٨ / ب.\nفي (ع) فقط هنا زيادة: «من»، وليست في شيء من النسخ المعتمدة؛ لكنها مثبتة في المطبوع من صحيح مسلم.\nفي (أ) و(ب): «يرويه كذا».\nصحيح مسلم ٥/ ٨٢، عقب (١٦٤٧). وقال الحاكم في معرفة علوم الحديث: ١٦٠: «تفرّد الزهري عن نيّف وعشرين رجلًا من التابعين لم يروِ عنهم غيره».\n«فيه نظر؛ لأن الخليلي ما حكم بشيء من جهة نفسه، بل ذكر قول الشافعي فقط. وقوله: «إن مراد الشافعي حكم الشاذ لا تعريفه، وأما الحاكم فقد عرّف الشاذ، والتعريف لا يعوّل عليه إلا من جهة الجمع أو المنع». فيقال: هذا غير جامع أو غير مانع؛ فإنه قال: إنه غير مانع لدخول الحديث الذي انفرد به الآحاد مع كونه ورد في الصحيح، فللحاكم أن يقول: لا يعتبر في ورود الحديث المنفرد في الصحيح؛ لأنه لم يحكم بصحته ولا بضعفه، بل بشذوذه، ولا يلزم من ذلك ضعفه؛ لأن التفرد ربما ينجبر بما يلحقه بالصحيح أو الحسن». نكت الزركشي ٢/ ١٥٣."}],[712,"إذا انفرَدَ الراوي بشيءٍ نُظِرَ فِيْهِ، فإنْ كانَ ما انفَرَدَ بهِ مخالفًا لِمَا رواهُ مَنْ هو أولى منهُ بالحفظِ لذلكَ وأضبطُ كانَ ما انفردَ بهِ شاذًّا مردودًا، وإنْ لَمْ تكُنْ (١) فيهِ مخالفةٌ لِمَا رواهُ غيرُهُ، وإنَّما هوَ أمرٌ رواهُ هوَ وَلَمْ يَرْوِهِ غيرُهُ، فَيُنْظَرُ في هذا الراوي المنفردِ، فإنْ كانَ عدلًا حافظًا موثوقًا بإتقانِهِ وضبطِهِ؛ قُبِلَ ما انفردَ بهِ ولَمْ يَقْدَحِ الانفرادُ فيهِ، كما فيما سبقَ مِنَ الأمثلةِ، وإنْ لَمْ يكنْ ممَّنْ يُوثَقُ بحفظِهِ وإتقانِهِ لذلكَ الذي انفردَ بهِ؛ كانَ انفرادُهُ (٢) خارمًا لهُ مُزَحْزِحًا لهُ عَنْ حَيِّزِ الصحيحِ."],[713,"ثُمَّ هوَ بعدَ ذلكَ دائرٌ بينَ مراتبَ متفاوتَةٍ (٣) بحسبِ الحالِ فيهِ: فإنْ كانَ المنفردُ بهِ غيرَ بعيدٍ مِنْ درجَةِ الحافظِ الضابطِ المقبولِ تفرُّدُهُ اسْتَحْسَنا حديثَهُ ذلكَ ولَمْ نَحطَّهُ (٤) إلى قبيلِ الحديثِ الضعيفِ، وإنْ كانَ بعيدًا مِنْ ذلكَ رَدَدْنا ما انفرَدَ بهِ، وكانَ مِنْ قبيلِ الشَّاذِّ المنكرِ (٥).","",{"fn":"في (ب) و(م): «يكن».\nفي (أ) و(ب): «انفراده به».\nفي (جـ): «متقاربة».\nفي (ب): «ينحط».\nولخطورة هذه المسألة وأهميتها في ميزان النقد الحديثي رأينا أنْ نُفصِّلَ في ذلك فنقول: لا يشترط في الخبر التعدّد بل خبر الواحد يكفي إذا استوفى شروطه، وهو الذي عليه جماهير المسلمين من صدر الإسلام وحتى يوم الناس هذا، وقد شذّ بعضهم فاشترط العدد، وقد أجاب الحافظ ابن حجر عن شبه هذا المذهب في النكت ١/ ٢٤٣ - ٢٤٧. فالجماهير من أهل العلم لا يشترطون العدد في الرواية بل يعمل بالحديث إن كان راويه عدلًا ضابطًا، وكان السند متصلًا، ولَم يكن في متن الحديث شذوذ أو علّة؛ لذا قَدْ تواترت النصوص عن الأئمة بعدم وجود ضرر في تفرد الرَّاوِي. (انظر عَلَى سبيل المثال: ميزان الاعتدال ١/ ٥٠٤ (١٨٩٤) ونصب الراية ٣/ ٧٤، وهدي الساري ص ٣٩٤، والفتح ٥/ ١١ و٥/ ٤٠٧ والتنكيل ١/ ١٠٤، وأثر علل الْحَدِيْث ص ١٣١)، وهذا إذا كَانَ الرَّاوِي مبرزًا في الحفظ أما إذا لَمْ يَكُنْ كَذَلِكَ، أو كَانَ قليل الطلب، أو إذا رَوَى عن المشهورين ما لا يعرفه ملازموهم فإن تفرّده عندئذ يوجب النظر والتأني. ونحن حينما ننظر في كتب العلل والتخريج نجد الأئمة النقّاد كثيرًا ما يعلون أحاديث الثقات بالتفرد والتفرد بحد ذاته لَيْسَ علّة لكنه يكشف عن العلّة بَلْ قَدْ يَكُوْن أحيانًا من أسباب العلة. ="}],[714,"فخَرَجَ مِنْ ذلكَ أنَّ الشاذَّ المردودَ قسمانِ:"],[715,"أحدُهُما: الحديثُ (١) الفردُ المخالفُ."],[716,"والثاني: الفردُ الذي ليسَ في راويهِ (٢) مِنَ الثقةِ والضبطِ ما يقعُ جابرًا لِمَا يوجبُهُ التفرُّدُ والشذوذُ مِنَ النَّكارةِ والضعفِ، واللهُ أعلمُ.","",{"fn":"ساقطة من (جـ).\nفي (أ): «رواته»."}],[717,"النوع الرابع عشر معرفة المنكر من الحديث"],[718,"(١)"],[719,"بَلَغَنا عَنْ أبي بكرٍ أحمدَ بنِ هارونَ البِرْديجيِّ الحافِظِ أنَّهُ: الحديثُ الذي ينفردُ بهِ الرجلُ ولا يُعْرَفُ مَتْنُهُ مِنْ غيرِ روايتِهِ، لا مِنَ الوجهِ الذي رواهُ منهُ، ولا مِنْ وجهٍ آخرَ (٢). فأطلقَ البِرْديجيُّ ذلكَ ولَمْ يُفَصِّلْ.","",{"fn":"«قد نوزع في إفراده بنوعٍ، وكلامهم يقتضي أنه: الحديث الذي انفرد به الراوي مخالفًا لِمَا رواهُ مَنْ هو أولى منه بالحفظ والإتقان، أو انفرد به من غير مخالفة لِمَا رواه أحد، لكن هذا التفرد نازل عن درجة الحافظ الضابط. يعرف من ذلك أن المنكر من أقسام الشاذّ فلم يحتج لإفراده». نكت الزركشي ٢/ ١٥٥. وللدكتور حمزة المليباري في كتابه \"نظرات جديدة في علوم الحديث\": ٣١، رأي آخر في المنكر، فقال: «وكذلك مصطلح «المنكر»، فإنه عند المتأخرين ما رواه الضعيف مخالفًا للثقات، غير أن المتقدمين لم يتقيّدوا بذلك، وإنما عندهم كل حديث لم يعرف عن مصدره: ثقة كان راويه أم ضعيفًا، خالف غيره أم تفرد. وهناك في كتب العلل والضعفاء أمثلة كثيرة توضح ذلك، وقد ذكرت بعضها في كتابي \" الحديث المعلول: قواعد وضوابط \" ص٦٦ - ص٧٧. فالمنكر في لغة المتقدمين أعمّ منه عند المتأخرين، وهو أقرب إلى معناه اللغوي، فإن المنكر لغة: نَكِرَ الأمرَ نكيرًا وأنكره إنكارًا ونُكْرًا، معناه: جهله. وجاء إطلاقه على هذا المعنى في مواضع من القرآن الكريم، كقوله تعالى: ﴿وَجَاءَ إِخْوَةُ يُوْسُفَ فَدَخَلُوا عَلَيْهِ فَعَرَفَهُمْ وَهُمْ لَهُ مُنْكِرُوْنَ﴾ (يوسف: ٥٨)، وقوله تعالى: ﴿يَعْرِفُوْنَ نِعْمَةَ اللهِ ثُمَّ يُنْكِرُوْنَهَا﴾ (النحل: ٨٣). وعلى هذا فإن المتأخرين خالفوا المتقدمين في مصطلح «المنكر» بتضييق ما وسعوا فيه». وانظر في المنكر: الإرشاد ١/ ٢١٩، والتقريب: ٦٩، والاقتراح: ١٩٨، والمنهل الروي: ٥١، والخلاصة: ٧٠، والموقظة: ٤٢، واختصار علوم الحديث: ٥٨، والمقنع ١/ ١٧٩، وشرح التبصرة والتذكرة ١/ ٣٢٩، ونزهة النظر: ٩٨، والمختصر: ١٢٥، وفتح المغيث ١/ ١٩٠، وألفية السيوطي: ٣٩ وشرح السيوطي على ألفية العراقي: ١٧٩، وفتح الباقي ١/ ١٩٧، وتوضيح الأفكار ٢/ ٣، وظفر الأماني: ٣٥٦، وقواعد التحديث: ١٣١، والحديث المعلول قواعد وضوابط: ٦٦ - ٧٧.\n«هذا لا يظهر فيه فرق بينه وبين ما سبق في أحد نوعي الشاذ، ومن تأمل كلام الأقدمين من أهل الحديث وجدهم إنما يطلقون النكارة على الحديث الذي يخالف رواية الحفاظ المتقنين. قال مسلم في مقدمة كتابه: «وعلامة المنكر في حديث المحدث إذا ما عرضت روايته للحديث على رواية غيره من أهل الحفظ والرضا خالفت روايته روايتهم أو لم تكد توافقها». انتهى. صحيح مسلم ١/ ٥. وكتاب الحافظ أبي أحمد بن عدي أصل في معرفة المنكرات من الأحاديث». نكت الزركشي٢/ ١٥٦ - ١٥٧."}],[720,"وإطلاقُ الحكمِ على التفرُّدِ بالرَّدِّ أو النكارةِ أو الشذوذِ، موجودٌ في كلامِ كثيرٍ مِنْ أهلِ الحديثِ (١)."],[721,"والصوابُ فيهِ التَّفْصيلُ الذي بيَّنَّاهُ آنِفًا في شرحِ الشاذِّ. وعندَ هذا نقولُ: المنكرُ ينقَسِمُ قسمينِ (٢) على ما ذكرناهُ في الشاذِّ فإنَّهُ بمعناهُ (٣)."],[722,"مِثَالُ الأوَّلِ - وهوَ المنفردُ المخالِفُ لِمَا رواهُ الثِّقَاتُ -: روايةُ مالكٍ عنِ الزهريِّ، عنْ عليِّ بنِ حسينٍ، عَنْ عُمَرَ بنِ عُثمانَ، عَنْ أُسَامةَ بنِ زيدٍ، عَنْ رسولِ اللهِ - صلى الله عليه وآله وسلم - قالَ: «لا يَرِثُ المسلمُ الكافِرَ، ولا الكافِرُ المسلِمَ» (٤)، فخالفَ مالكٌ غيرَهُ مِنَ الثِّقاتِ في قولِهِ: عُمَرَ بنِ عُثمانَ - بضمِّ العينِ -. وذكرَ مسلمٌ صاحبُ \" الصحيحِ \" في كتابِ","",{"fn":"«وهذا مما ينبغي التيقظ له، فقد أطلق الإمام أحمد والنسائي وغير واحد من النقاد لفظ «المنكر» على مجرد التفرد؛ لكن حيث لا يكون المتفرد في وزن مَن يحكم لحديثه بالصحة بغير عاضد يعضده». من إفادات ابن حجر في نكته ٢/ ٦٧٤.\nفي (أ): «إلى قسمين».\nقال ابن حجر في النزهة: ٩٩: «وقد غَفَل مَنْ سوَّى بينهما». قال المحقّق: «يشير بذلك إلى ابن الصلاح ومَن تابعه». وقال ابن الوزير - معقبًا على ابن الصلاح في تسويته بينهما -: «كان يليق أن لا يجعل نوعًا وحده». قلنا: وهذا تعقب مهم متجه؛ لأنهما لما كانا متماثلين في حقيقتهما عند ابن الصلاح ومن تبعه، كان الأولى دمجهما في مكان واحد، كما فعل الطيبي في خلاصته: ٦٩.\nالموطّأ (١٤٧٥): «رِوَايَة الليثي». وَقَدْ أخرجه عن مالك أبو مصعب الزهري (٣٠٦١)، وعبد الله بن مسلمة القعنبي عِنْدَ الجوهري (٢١٠)، والمزي في تهذيب الكمال ٢٢/ ١٥٥، وعبد الله بن وهب عند الجوهري (٢١٠)، والطحاوي في شرح المعاني ٣/ ٢٦٥، ومحمد بن الحسن (٧٢٨)، ومصعب بن عبد الله بن الزبير عند ابن عبد البرِّ في التمهيد ٩/ ١٦٢، وقد رواه عن الزهري غير مالك جماعة منهم: ١ - سفيان بن عيينة عند الحميدي (٥٤١)، وأحمد ٥/ ٢٠٠، والدارمي (٣٠٠٥) ومسلم ٥/ ٥٩ (١٦١٤)، وأبو داود (٢٩٠٩)، وابن ماجه (٢٧٢٩)، والترمذي (٢١٠٧)، والنسائي في الكبرى (٦٣٧٦)، وابن الجارود (٩٥٤)، والطبراني (٤١٢)، والبيهقي ٦/ ٢١٨. ٢ - ومحمد بن أبي حفصة عند أحمد ٥/ ٢٠١، والبخاري ٥/ ٣٨٧ حديث (٤٢٨٢)، والطبراني (٤١٢). ٣ - ومعمر بن راشد عند أحمد ٥/ ٢٠٨ و٢٠٩، والدارمي (٣٠٠٢)، والنسائي في الكبرى (٦٣٧٩)، والطبراني (٤١٢)، والبيهقي ٦/ ٢١٨. ="}],[723,"\" التمييزِ \": أنَّ كُلَّ مَنْ رواهُ مِنْ أصحابِ الزهريِّ، قالَ فيهِ: عَمْرُو بنُ عثمانَ - يعني: بفتحِ العينِ -. وذكرَ أنَّ مالِكًا كانَ يشيرُ بيدِهِ إلى دارِ عُمَرَ بنِ عُثمانَ، كأنَّهُ عَلِمَ أنَّهُمْ يخالِفونَهُ. وعَمْرٌو وعُمَرُ جميعًا: وَلَدُ (١) عُثمانَ (٢)، غيرَ أنَّ هذا الحديثَ إنَّما هو عَنْ (٣) عَمْرٍو - بفتحِ العينِ -، وحَكَمَ مسلمٌ وغيرُهُ على مالكٍ بالوهمِ فيهِ (٤)، واللهُ أعلمُ.","",{"fn":"في (ب) و(م): «ولدا» بألف التثنية.\nوهذا بإجماع من أهل النسب. انظر: نسب قريش: ١٠٤، وجمهرة أنساب العرب: ٧٥، والتمهيد ٩/ ١٦٠.\nليست في (أ) و(ب).\nقال الناقد الجهبذ الإمام الترمذي - بعد أن ساقه من طريق سفيان بن عيينة وهشيم، عن الزهري، عن علي بن حسين، عن عمرو بن عثمان: «هذا حديث حسن صحيح. هكذا رواه معمر وغير واحد عن الزهري نحو هذا. وروى مالك، عن الزهري، عن علي بن حسين، عن عمر بن عثمان، عن أسامة بن زيد، عن النبي - صلى الله عليه وآله وسلم - نحوه. وحديث مالك وَهَمٌ، وَهِمَ فيه مالك، وقد رواه بعضهم، عن مالك فقال: عن عمرو بن عثمان. وأكثر أصحاب مالك قالوا: عن مالك، عن عمر بن عثمان. ="}],[724,"ومثالُ الثاني - وهوَ الفردُ الذي ليسَ في راوِيْهِ (١) مِنَ الثقةِ والإتقانِ ما يُحْتَمَلُ مَعَهُ تَفَرُّدُهُ -: ما رُوِّيْناهُ مِنْ حديثِ أبي زُكَيْرٍ (٢) يحيى بنِ محمدِ بنِ قيسٍ، عنْ هِشامِ بنِ عُروةَ، عَنْ أبيهِ، عنْ عائشةَ - رضي الله عنها - أنَّ رسولَ (٣) اللهِ - صلى الله عليه وآله وسلم - قالَ: «كُلُوا البَلَحَ (٤) بالتَّمْرِ؛ فإنَّ الشيطانَ إذا رأى ذلكَ غاظَهُ، ويقولُ: عاشَ ابنُ آدمَ حتَّى أكلَ الجديدَ بالخَلَقِ!» (٥).","",{"fn":"في (ب): «رواته» بالجمع.\nبالتصغير - بضم الزاي المعجمة -. التقريب (٧٦٣٩).\nفي (جـ): «النبي».\nآخره حاء مهملة، أي: الخلال، وهو حمل النخل ما دام أخضر صغارًا كحِصرم العنب، واحدته: بلحة. لسان العرب ٢/ ٢٣١.\nأخرجه ابن ماجه (٣٣٣٠)، والنسائي في الكبرى (٦٧٢٤)، وأبو يعلى (٤٣٩٩)، وابن حبان في المجروحين ٣/ ١٢٠، والعقيلي في الضعفاء ٤/ ٤٢٧، وابن عدي في الكامل ٧/ ٢٦٩٨، والحاكم في المستدرك ٤/ ٢١، وفي معرفة علوم الحديث: ١٠٠ - ١٠١، والخليلي في الإرشاد (١١)، والخطيب في تاريخه ٥/ ٣٥٣. وقد استنكره أبو حاتم والنسائي والعقيلي وابن عدي والذهبي، وقال ابن حبان: «وهذا الكلام لا أصل له من كلام رسول الله - صلى الله عليه وآله وسلم -». وساقه ابن الجوزي في الموضوعات ٣/ ٢٥ - ٢٦، والسيوطي في الآلي المصنوعة ٢/ ٢٤٣ - ٢٤٤. وذكروا جميعًا أن البلية فيه من أبي زكير."}],[725,"تَفرَّدَ بهِ أبو زُكيرٍ، وهو شيخٌ صالِحٌ (١) أخرجَ عنهُ مسلمٌ في كتابهِ (٢) غيرَ أنَّهُ لَمْ يبلغْ مبلغَ مَنْ يُحتَمَلُ تَفَرُّدُهُ، واللهُ أعلمُ."],[726,"النوع الخامس عشر معرفة الاعتبار والمتابعات والشواهد"],[727,"(٣)"],[728,"هذهِ أمورٌ يَتَداولونها في نَظَرِهم في حالِ الحديثِ: هَلْ تَفَرَّدَ بهِ راويهِ أو لا؟، وهَلْ هُوَ معروفٌ أو لا؟، ذكرَ أبو حاتِمٍ محمدُ بنُ حِبَّانَ التميميُّ الحافظُ - رحمه الله - أنَّ طريقَ الاعتبارِ في الأخبارِ مثالُهُ: أنْ يَرويَ حمادُ بنُ سَلَمَةَ حديثًا لَمْ يُتابَعْ عليهِ، عَنْ أيُّوبَ، عنِ ابنِ سيرينَ، عَنْ أبي هريرةَ، عَنِ النبيِّ (٤) - صلى الله عليه وآله وسلم -، فَيُنْظَرَ هلْ روى ذلكَ ثِقَةٌ غيرُ (٥) أيّوبَ، عَنِ ابنِ سيرينَ؟ فإنْ وُجِدَ عُلِمَ أنَّ للخبرِ أصلًا يُرْجَعُ إليهِ، وإنْ لَمْ يوجدْ ذلكَ، فثقةٌ غيرُ ابنِ سيرينَ رواهُ عنْ أبي هريرةَ، وإلاَّ فصحابيٌّ غيرُ أبي هريرةَ رواهُ عَنِ النبيِّ - صلى الله عليه وآله وسلم -، فأيُّ ذلكَ وُجِدَ، يُعْلمُ بهِ أنَّ للحديثِ أصلًا يَرجِعُ إليهِ وإلاَّ فلاَ (٦).","",{"fn":"قول المصنف: إنه شيخ صالح. أخذه من كلام أبي يعلى الخليلي، فإنه كذلك في كتاب الإرشاد قاله العراقي في التقييد: ١٠٩. وانظر: الإرشاد في معرفة علماء الحديث ١/ ١٧٣. قال ابن حجر ٢/ ٦٨٠: «وقول الخليلي: إنه شيخ صالح. أراد به في دينه لا في حديثه لأن من عادتهم إذا أرادوا وصف الراوي بالصلاحية في الحديث قيدوا ذلك، فقالوا: صالح الحديث. فإذا أطلقوا الصلاح، فإنما يريدون به في الديانة. والله أعلم».\nفي المتابعات لا في الأصول. انظر المقنع ١/ ١٨٦، ومحاسن الاصطلاح: ١٨١، والتقييد والإيضاح: ١٠٩، وخلاصة تذهيب تهذيب الكمال ٤٢٨.\n«هذه العبارة توهم أن الاعتبار قسيم للمتابعة والشاهد، وليس كذلك، بل الاعتبار هو الهيأة الحاصلة في الكشف عن المتابعة والشاهد. وعلى هذا فكان حق العبارة أن يقول: معرفة الاعتبار للمتابعة والشاهد». أفاده ابن حجر ٢/ ٦٨١، وانظر: نكت الزركشي ٢/ ١٦٩، والنكت الوفية ١٥٢ / ب.\nفي (ب): «رسول الله».\nفي (ب): «عن».\nالإحسان في ترتيب صحيح ابن حبان ١/ ١٤٣ - ١٤٤، وطبعة دار الفكر ١/ ٦٣."}],[729,"قُلْتُ: فمثالُ المتابعةِ أنْ يرويَ ذلكَ الحديثَ بعينِهِ عَنْ أيُّوبَ غيرُ حمّادٍ، فهذهِ المتابعةُ التامَّةُ (١). فإنْ لَمْ يَرْوِهِ أحدٌ غيرُهُ، عَنْ أيوبَ، لكنْ رواهُ بعضُهُم عَنِ ابنِ سيرينَ أوْ عَنْ أبي هريرةَ، أو رواهُ غيرُ أبي هريرةَ، عنْ رسولِ اللهِ - صلى الله عليه وآله وسلم -، فذلكَ قدْ يُطلَقُ عليهِ اسمُ المتابعةِ أيضًا، لكنْ تَقْصُرُ (٢) عَنِ المتابَعَةِ الأُولى بحَسَبِ بُعْدِها مِنْها، ويجوزُ أنْ يُسَمَّى ذلكَ بالشاهدِ أيضًا (٣). فإنْ لَمْ يُرْوَ ذلكَ (٤) الحديثُ أصلًا مِنْ وجهٍ مِنَ الوجوهِ المذكورةِ، لكنْ رُوِيَ حديثٌ آخرُ بمعناهُ، فذلكَ الشاهِدُ من غيرِ متابعةٍ، فإنْ لَمْ يُرْوَ أيضًا بمعناهُ حديثٌ آخرُ، فقد تحقّقَ فيهِ التفرّدُ المطلقُ حينَئِذٍ."],[730,"وينقسمُ عندَ ذلكَ إلى: مردودٍ منكرٍ، وغيرِ مردودٍ كما سَبَقَ."],[731,"وإذا قالوا في مثلِ هذا: «تفَرَّدَ بهِ أبو هريرةَ، وتَفَرَّدَ بهِ عَنْ أبي هريرةَ ابنُ سيرينَ، وتَفَرَّدَ بهِ عَنِ ابنِ سيرينَ أيّوبُ، وتَفَرَّدَ بهِ عنْ أيوبَ حمَّادُ بنُ سَلَمَةَ» كانَ في ذلكَ إشعارٌ بانتفاءِ وجوهِ المتابعاتِ فيهِ."],[732,"ثُمَّ اعْلَمْ أنَّهُ قَدْ يدخلُ في بابِ المتابعةِ والاستشهادِ روايةُ مَنْ لا يحتجُّ بحديثِهِ وَحْدَهُ بلْ يكونُ معدودًا في الضعفاءِ (٥)، وفي كتابَيِ البخاريِّ ومسلمٍ جماعةٌ مِنَ الضعفاءِ ذَكَرَاهُم في المتابعاتِ والشواهِدِ، وليسَ كلُّ ضعيفٍ يَصْلُحُ لذلكَ، ولهذا يقولُ الدارقطنيُّ وغيرُهُ في الضعفاءِ: «فلانٌ يُعْتَبَرُ بهِ، وفلانٌ لا يُعْتَبَرُ بهِ»، وقدْ تَقَدَّمَ التنبيهُ على نحوِ ذلكَ، واللهُ أعلمُ.","",{"fn":"في حاشية نسخة (جـ) جاءت تعليقة نصّها: «وقد سمّى البيهقي في باب الدباغ ما وقع من ذلك عن شيخ شيخه متابعة، والله أعلم». وانظر: سنن البيهقي الكبرى ١/ ١٦.\nفي (ع) والتقييد فقط: «يقصر».\nفي حاشية (ب) تعليقة نصّها: «قال المصنف - رحمه الله تعالى -: سمّى الحاكم في المدخل ... إلى الصحيح المتابعات شواهد، والله تعالى أعلم». وقد ضمنها البلقيني: ١٨٣ في محاسنه، فيما أوردتها محققة الكتاب عن حاشية نسختين.\nفي (ب): «لذلك».\n«لا يقال: عطف الاستشهاد على المتابعة يقتضي تغايرهما، والحاكم في \" المدخل \" سَمَّى المتابعات شواهد. لأنا نقول: المغايرة صادقة، بأن لا يسمّي الشواهد متابعات، وأما تسمية المتابعة شاهدًا فهو موجود في قوله: ويجوز أن يسمى ذلك بالشاهد أيضًا». أفاده البلقيني في محاسنه: ١٨٣. وانظر: نكت الزركشي ٢/ ١٧١."}],[733,"مثالٌ للمتابعِ (١) والشاهدِ: رُوِّيْنا مِنْ حديثِ سفيانَ بنِ عُيينةَ، عَنْ عمرِو بنِ"],[734,"دينارٍ، عَنْ عطاءِ بنِ أبي رباحٍ، عَنِ ابنِ عبَّاسٍ، أنَّ النبيَّ - صلى الله عليه وآله وسلم - قالَ: «لَوْ أخَذُوا إِهَابَها فَدَبَغُوهُ فانتَفَعُوا بهِ» (٢)، ورواهُ ابنُ جريجٍ، عَنْ عمرٍو، عَنْ عطاءٍ ولَمْ يذكرْ فيهِ"],[735,"الدِّبَاغَ (٣)، فذكرَ الحافظُ أحمدُ البيهقيُّ لحديثِ ابنِ عيينةَ متابِعًا وشاهِدًا. أمَّا المتابعُ فإنَّ أسامةَ بنَ زيدٍ تابَعَهُ عَنْ عطاءٍ. وروى بإسنادِهِ عَنْ أسامةَ، عَنْ عطاءٍ، عَنِ ابنِ عبَّاسٍ، أنَّ رسولَ اللهِ - صلى الله عليه وآله وسلم - قالَ: «أَلاَ نَزَعْتُمْ جِلْدَها فَدَبَغْتُمُوهُ فاسْتَمْتَعْتُمْ بهِ» (٤)، وأمَّا الشاهِدُ فحديثُ عبدِ الرَّحْمَانِ بنِ وَعْلَةَ (٥)، عَنِ ابنِ عبَّاسٍ، قالَ: قالَ رسولُ اللهِ - صلى الله عليه وآله وسلم -: «أيُّما إهَابٍ (٦) دُبِغَ فقَدْ طَهُرَ» (٧)، واللهُ أعلمُ.","",{"fn":"في (ع) والتقييد والشذا ونكت الزركشي: «المتابع».\nأخرجه مسلم ١/ ١٩٠ (٣٦٣)، والنسائي ٧/ ١٧٢، وكذلك أخرجه الحميدي (٤٩١).\nعند أحمد ١/ ٣٦٦، ومسلم ١/ ١٩٠ – ١٩١ (٣٦٤)، والنسائي ٧/ ١٧٢. وهذا «يوهم أن رواية ابن جريج موافقة لرواية سفيان، وليس كذلك؛ لأن ابن جريج زاد في السند ميمونة فجعله من مسندها، وسفيان جعله من مسند ابن عباس، فهذا خلاف آخر غير إسقاط «الدباغ»، ولم يتعرض له المصنف». نكت الزركشي ٢/ ١٧٢. وانظر: التقييد والإيضاح ١٠٩، وشرح التبصرة والتذكرة ١/ ٣٤٣–٣٤٥، ونكت ابن حجر ٢/ ٦٨١–٦٨٥.\nأخرجه الطحاوي في شرح المعاني ١/ ٤٦٩، والدارقطني ١/ ٤٤، والبيهقي ١/ ١٦.\nبفتح الواو وسكون العين. تقريب التهذيب (٤٠٣٩).\nالإهاب: الجلد من البقر والغنم والوحش ما لم يدبغ. لسان العرب ٢/ ١٦.\nأخرجه: مسلم ١/ ١٩٠ عقيب (٣٦٣)، وأبو داود (٤١٢٣)، وابن ماجه (٣٦٠٩)، والترمذي (١٧٢٨)، والنسائي ٧/ ١٧٣. وأخرجه أيضًا: مالك (١٤٣٧) «رواية يحيى الليثي»، والشافعي ١/ ٢٣ و٢٦، وعبد الرزاق (١٩٠)، والطيالسي (٢٧٦١)، والحميدي (٤٨٦)، وابن أبي شيبة ٨/ ٣٧٨، وأحمد ١/ ٢١٩ و٢٧٠ و٢٧٩ و٢٨٠ و٣٤٣، والدارمي (١٩٩١) و(١٩٩٢)، وأبو عوانة ١/ ٢١٢، وأبو يعلى (٢٣٨٥)، والطحاوي ١/ ٤٦٩، وفي شرح المشكل (٣٢٤٣)، وابن حبان (١٢٨٧)، والطبراني في الصغير (٦٦٨)، والدارقطني ١/ ٤٦، والبيهقي ١/ ١٦ و١٧."}],[736,"النوع السادس عشر معرفة زيادات الثقات وحكمها"],[737,"(١)"],[738,"وذلكَ فنٌّ لطيفٌ تُسْتَحْسَنُ العِنايةُ بهِ. وقدْ كانَ أبو بكرِ بنُ زيادٍ النَّيْسابوريُّ (٢)، وأبو نُعَيْمٍ الْجُرْجَانيُّ (٣)، وأبو الوليدِ القرشيُّ (٤) الأئمّةُ مذكورينَ بمعرفة زياداتِ الألفاظِ الفقهيّةِ في الأحاديثِ (٥).","",{"fn":"لمعرفةٍ أكثرَ عن هذه المسألة، انظر: معرفة علوم الحديث: ١٣٠، والكفاية: ٥٩٧، وجامع الأصول ١/ ١٠٣، وإرشاد طلاب الحقائق ١/ ٢٢٥ - ٢٣١، والتقريب: ٧١ - ٧٢، والمنهل الروي: ٥٨، والخلاصة: ٥٦، ونظم الفرائد: ٣٧٠، واختصار علوم الحديث: ٦١، وشرح التبصرة والتذكرة ١/ ٣٤٦، ونزهة النظر: ٩٥، والمختصر: ١٧١، وفتح المغيث ١/ ١٩٩، وألفية السيوطي: ٥٣ - ٥٤، وشرح السيوطي على ألفية العراقي ١٨٧، وفتح الباقي ١/ ٢١١، وتوضيح الأفكار ٢/ ١٦، وقواعد التحديث: ١٠٧.\nهو أبو بكر عبد الله بن محمد بن زياد النيسابوري الأموي مولاهم الحافظ نزيل بغداد، توفي (٣٢٤هـ). تاريخ بغداد ١٠/ ١٢٠، وسير أعلام النبلاء ١٥/ ٦٥، وطبقات الشافعية ٣/ ١٠.\nهو أبو نعيم عبد الملك بن محمد بن عدي الجرجاني الحافظ. مولده (٢٤٢هـ)، وتوفي (٣٢٣هـ). تاريخ جرجان: ٢٣٥، وتاريخ بغداد ١٠/ ٤٢٨، وسير أعلام النبلاء ١٤/ ٥٤١.\nهو أبو الوليد حسان بن محمد بن أحمد النيسابوري الأموي الشافعي. ت (٣٤٩ هـ). سير أعلام النبلاء ١٥/ ٤٩٢، وطبقات الشافعية ٣/ ٢٢٦، والبداية والنهاية ١١/ ٢٣٦.\nانظر: معرفة علوم الحديث ١٣٠. وكان ينبغي على ابن الصلاح ألاّ يغفل ذكر ابن خزيمة، فقد قال ابن حبان - تلميذه - فيه في مقدمة المجروحين ١/ ٩٣: «لَمْ أرَ على أديم الأرض مَنْ كان يحسن صناعة السنن ويحفظ الصحاح بألفاظها، ويقوم بزيادة كل لفظة تزاد في الخبر ثقة حتى كأن السنن كلها نصب عينيه إلا محمد بن إسحاق بن خزيمة فقط». وقد استشكل العلاّمة مغلطاي هذا على المصنف؛ لعدم فهمه مغزى كلامه. ومراد ابن الصلاح الألفاظ التي تستنبط منها الأحكام الفقهية، لا ما زاده الفقهاء أنفسهم في الأحاديث، فإن هذا من المدرج لا من زيادات الثقات. انظر: نكت الزركشي ٢/ ١٧٤، ومحاسن الاصطلاح ١٨٥، ونكت ابن حجر ٢/ ٦٨٦."}],[739,"ومَذهبُ الجمهورِ مِنَ الفقهاءِ وأصحابِ الحديثِ فيما حكاهُ الخطيبُ أبو بكرٍ: أنَّ الزيادةَ مِنَ الثقةِ مقبولةٌ إذا تفرَّدَ بها (١)، سواءٌ كانَ ذلكَ مِنْ شخصٍ واحدٍ بأنْ رواهُ ناقصًا مرَّةً، ورواهُ مرَّةً أخرى وفيهِ تلكَ الزيادةُ، أو كانتِ الزيادةُ (٢) مِنْ غيرِ مَنْ رواهُ ناقصًا، خلافًا لِمَنْ ردَّ مِنْ أهلِ الحديثِ ذلكَ مُطْلَقًا (٣)، وخلافًا لِمَنْ ردَّ الزيادةَ منهُ وَقَبِلَها مِنْ غيرِهِ (٤). وقدْ قَدَّمنا (٥) عنهُ حكايتَهُ عَنْ أكثرِ أهلِ الحديثِ فيما إذا وصلَ الحديثَ قومٌ وأرسَلَهُ قومٌ أنَّ الحكمَ لِمَنْ أرسلَهُ مَعَ أنَّ وصلَهُ زيادةٌ مِنَ الثقةِ (٦)."],[740,"وقدْ رأيتُ تقسيمَ ما ينفردُ بهِ الثقةُ إلى ثلاثةِ أقسامٍ (٧):","",{"fn":"انظر: الكفاية (٥٩٧ ت، ٤٢٤ هـ). قلنا: في النقل عن الجمهور نظر؛ فَقَدْ قَالَ ابن دَقِيْقِ العِيْدِ في مقدّمة \"الإمام\" كَمَا نقل ابن حجر في النكت ٢/ ٦٠٤: «من حكى عن أهل الحديث أو أكثرهم أنّه إذا تعارض رواية مرسل ومسند أو رافع وواقف أو ناقص وزائد أنّ الحكم للزائد فلم يصب في هذا الإطلاق؛ فإن ذلك ليس قانونًا مطردًا وبمراجعة أحكامهم الجزئية يعرف صواب ما نقول» وقالَ العلائي: «كلام الأئمة المتقدمين في هذا الفن كعبد الرحمان بن مهدي، ويحيى بن سعيد القطّان، وأحمد بن حنبلٍ، والبخاري وأمثالهم يقتضي أنهم لا يحكمون في هذه المسألة بحكم كلي بل عملهم في ذلك دائر مع الترجيح بالنسبة إلى ما يقوى عند أحدهم في كل حديث». نظم الفرائد: ٣٧٦ - ٣٧٧، وما بعدها فهو بحث نفيس، وانظر: نكت الزركشي ٢/ ١٧٥.\nعبارة: «أو كانت الزيادة» سقطت من ب.\nكما حكاه الخطيب عنهم في الكفاية: (٥٩٧ ت، ٤٢٤ هـ).\nحكاه الخطيب عن جماعة من الشافعية. انظر: الكفاية (٥٩٧ ت، ٤٢٤هـ)، وشرح الزركشي ٤/ ٣٢٩.\nص: ١٨١.\n«قد يفرق بينهما على طريقة المحدّثين بأن الإرسال علة في السند، وليست الزيادة في المتن كذلك، وسيأتي ما يدل له، ولا يعترض بأن الذي ذكره الخطيب في ذلك: الجزم بأن الزيادة مقبولة تقدمت أو تأخرت، وليس في ذلك حكاية عن الأكثر. ... وليس لقائلٍ أن يقول: لا ريبة فيما إذا روى أولًا زائدًا، إنما الريبة فيما إذا روى ثانيًا بزيادة؛ لأنا نقول: كل منهما فيه الريبة، فاستويا». محاسن الاصطلاح: ١٨٦.\n«هذا التقسيم ليس على وجهه، فإن الأول والثاني لا مدخل لهما في زيادة الثقة بحسب الاصطلاح، فإن المسألة مترجمة بأن يروي الحديث جماعة ويتفرد بعضهم بزيادة فيه، والقسمان قد فرضهما في أصل الحديث لا في الزيادة فيه، وإنما هما قسما الشاذ بعينه على ما ذكره هناك فلا معنى لتكراره وإدخاله مسألة في أخرى ...». هكذا قال الزركشي ٢/ ١٨٩، وانظر: نكت ابن حجر ٢/ ٦٨٧."}],[741,"أحدُها: أنْ يَقَعَ مخالِفًا منافيًا لِمَا رواهُ سائرُ الثقاتِ، فهذا حكمُهُ الرَّدُّ كما سبَقَ في نوعِ الشاذِّ."],[742,"الثاني: أنْ لا يكونَ (١) فيهِ منافاةٌ ومخالفةٌ أصلًا لِمَا رواهُ غيرُهُ كالحديثِ الذي تفرَّدَ بروايةِ جملتِهِ ثقةٌ، ولا تَعَرُّضَ فيهِ لِمَا رواهُ الغيرُ بمخالفةٍ أصلًا، فهذا مقبولٌ، وقدِ ادَّعَى الخطيبُ (٢) فيهِ اتِّفاقَ العلماءِ عليهِ وسَبَقَ مثالُهُ في نوعِ الشاذِّ."],[743,"الثالثُ: ما يقعُ بينَ هاتينِ المرتبتينِ، مثلُ زيادةِ لفظةٍ في حديثٍ لَمْ يَذكرْها سائرُ مَنْ رَوَى ذلكَ الحديثَ."],[744,"مثالُهُ: ما رواهُ مالكٌ (٣)، عَنْ نافعٍ، عَنِ ابنِ عُمرَ: «أنَّ رسولَ اللهِ - صلى الله عليه وآله وسلم - فَرَضَ زَكاةَ الفِطْرِ مِنْ رَمَضَانَ على كُلِّ حُرٍّ أو عَبْدٍ، ذَكَرٍ أو أنثَى مِنَ المسلمينَ». فذَكَرَ أبو عيسى الترمذيُّ (٤) أنَّ مالكًا تفَرَّدَ مِنْ بينِ الثِّقاتِ بزيادةِ قولِهِ: «مِنَ المسلمينَ». وَرَوَى عُبَيْدُ اللهِ بنُ عُمَرَ، وأيوبُ، وغيرُهُما هذا الحديثَ، عَنْ نافعٍ، عَنِ ابنِ عُمَرَ دونَ هذهِ الزيادةِ (٥).","",{"fn":"في (جـ): «تكون».\nفي الكفاية: (٥٩٨ ت، ٤٢٥ هـ).\nالموطأ (٧٧٣). وأخرجه من طريق مالك: الشافعي ١/ ٢٥٠، والدارمي (١٦٦٨)، والبخاري ٢/ ١٦١ حديث (١٥٠٤)، ومسلم ٣/ ٦٨ حديث (٩٨٤)، وأبو داود (١٦١١)، وابن ماجه (١٨٢٦)، والترمذي (٦٧٦)، والنسائي ٥/ ٤٨، وابن خزيمة (٢٣٩٩) والطحاوي ٢/ ٤٤، وابن حبان (٣٣٠١)، والبيهقي ٤/ ١٦١، والبغوي (١٥٩٣).\nالجامع الكبير ٢/ ٥٤ عقب (٦٧٦).\nكتاب العلل للترمذي ٦/ ٢٥٣. قلنا: هكذا قال ابن الصلاح مقلّدًا في هذا الإمام الترمذي، وفيه نظر، إذ اعترض عليه الإمام النووي فقال في إرشاد طلاب الحقائق ١/ ٢٣٠ - ٢٣١: «لا يصح التمثيل بحديث مالك؛ لأنَّهُ لَيْسَ منفردًا، بَلْ وافقه في هَذِهِ الزيادة عن نافع: عمر بن نافع، والضحاك بن عثمان الأول في صَحِيْح البُخَارِيّ، والثاني في صَحِيْح مُسْلِم». وبنحوه قَالَ في التقريب والتيسير: ٧٢. ="}],[745,". . . . . . . . . . . . . . . . . . . . . ."],[746,". . . . . . . . . . . . . . . . . . . . . ."],[747,". . . . . . . . . . . . . . . . . . . . ."],[748,"فأخذَ بها غيرُ واحِدٍ مِنَ الأئمَّةِ واحتجُّوا بها، منهم: الشافعيُّ وأحمدُ - رضي الله عنهم -،"],[749,"واللهُ أعلمُ."],[750,"ومِنْ أمْثِلَةِ ذلكَ: حديثُ: «جُعِلَتْ لَنا (١) الأرضُ مَسجِدًا وجُعِلَتْ تُربَتُها لنا طَهُورًا». فهذهِ الزيادةُ تفَرَّدَ بها أبو مالكٍ سعدُ بنُ طارقٍ الأشجعيُّ (٢). وسائرُ الرواياتِ لَفظُهَا: «وجُعِلَتْ لنا الأرضُ مَسْجِدًا وطَهُورًا» (٣). فهذا وما أشبَهَهُ يُشْبِهُ القسمَ الأوَّلَ مِنْ حيثُ إنَّ ما رواهُ الجماعةُ عامٌّ، وما رواهُ المنفردُ بالزيادةِ مخصوصٌ، وفي ذلكَ مغايرةٌ في الصفةِ ونوعٌ مِنَ المخالفةِ يختَلِفُ بها الحكمُ. ويُشْبِهُ أيضًا القسمَ الثاني مِنْ حيثُ إنَّهُ لا منافاةَ بينَهُما.","",{"fn":"في (ب): «لي».\nأخرجه: الطيالسي (٤١٨)، وابن أبي شيبة ١١/ ٤٣٥، وأحمد ٥/ ٣٨٣، ومسلم ٢/ ٦٣ (٥٢٢)\nفهو مروي من حديث عدة من الصحابة منهم: ١ - جابر بن عبد الله، عند: ابن أبي شيبة ١/ ١٥٧، وأحمد ٣/ ٣٠٤، والدارمي (١٣٩٦)، والبخاري ١/ ٩١ (٣٣٥) و١/ ١١٩ (٤٣٨)، ومسلم ٢/ ٦٣ (٥٢١)، والنسائي ١/ ٢٠٩ و٢/ ٥٦، وفي الكبرى (٨١٥). من طريق سيار أبي الحكم، عن يزيد الفقير، عن جابر. ٢ - عبد الله بن عباس، عند: ابن أبي شيبة ١/ ١٥٧، وأحمد ١/ ٢٥٠ و٣٠١، وعبد بن حميد (٦٤٣). ٣ - أبو موسى الأشعري، عند: أحمد ٤/ ٤١٦. ٤ - أبو ذر الغفاري، عند: أحمد ٥/ ١٤٥ و١٤٧، والدارمي (٢٤٧٠)، وأبي داود (٤٨٩). ٥ - أبو هريرة، عند: أحمد ٢/ ٤١١، ومسلم ٢/ ٦٤ (٥٢٣)، والترمذي (١٥٥٣)، وابن ماجه (٥٦٧). ٦ - ابن عمر، عند: البزار (٣١١)، والطبراني في الكبير (١٣٥٢٢). وغيرهم. وانظر: شرح السيوطي ١٨٨ - ١٨٩، وأثر علل الحديث ١٦٤ - ٢٦٥. تنبيه: «هذا التمثيل ليس بمستقيم أيضًا؛ لأن أبا مالك قد تفرد بجملة الحديث عن ربعي بن حراش - رضي الله عنه - كما تفرد برواية جملته ربعي عن حذيفة - رضي الله عنه -. فإن أراد أن لفظة «تربتها» زائدة في هذا الحديث على باقي الأحاديث في الجملة، فإنه يُرَدُّ عليه: أنها في حديث علي - رضي الله عنه - أيضًا ... وإن أراد: أن أبا مالك تفرَّد بها، وأن رفقته عن ربعي - رضي الله عنه - لم يذكروها كما هو ظاهر كلامه، فليس بصحيح». نكت ابن حجر ٢/ ٧٠٠ - ٧٠١.\n، والنسائي في الكبرى (٨٠٢٢)، وابن خزيمة (٢٦٣) و(٢٦٤)، وأبو عوانة ١/ ٣٠٣، وابن حبان (١٦٩٧) و(٦٤٠٠)، والبيهقي ١/ ٢١٣."}],[751,"وأمَّا زيادةُ الوصلِ معَ الإرسالِ، فإنَّ بينَ الوصلِ والإرسالِ مِنَ المخالفةِ نحوَ ما ذكرناهُ، ويزدادُ ذلكَ بأنَّ الإرسالَ نوعُ قَدْحٍ في الحديثِ، فترجيحُهُ وتقديمُهُ مِنْ قَبيلِ تقديمِ الجرحِ على التعديلِ، ويجابُ عنهُ: بأنَّ الجرحَ قُدِّمَ لِمَا فيهِ مِنَ زيادةِ العِلْمِ، والزيادةُ هاهنا معَ مَنْ وَصَلَ، واللهُ أعلمُ (١)."],[752,"النوع السابع عشر معرفة الأفراد"],[753,"(٢)","",{"fn":"«ما قاله النسائي وغيره من أن من أرسل معه زيادة علم على من وصل؛ لأن الغالب في الألسنة الوصل، فإذا جاء الإرسال، عُلِم أن مع المرسل زيادة علم، وقد رجحه ابن القطان وغيره. معارض بأن الإرسال نقص في الحفظ، وذلك لما جبل عليه الإنسان من السهو والنسيان فتبين أن النظر الصحيح: أن زيادة العلم إنما هي مع من أسند». محاسن الاصطلاح: ١٩١.\nالأفراد - بفتح الهمزة -: جمع فرد. قال الميانشي: «الفرد: هو ما انفرد بروايته بعض الثقات عن شيخه، دون سائر الرواة عن ذلك الشيخ». ما لا يسمع المحدّث جهله: ٢٩ وعرَّفه الدكتور المليباري، فقال: «يراد بالتفرد: أن يروي شخص من الرواة حديثًا دون أن يشاركه الآخرون، وهو ما يقول فيه المحدّثون النقّاد: «حديث غريب»، أو: «تفرَّد به فلان»، أو: «هذا حديث لا يعرف إلا من هذا الوجه»، أو: «لا نعلمه يروى عن فلان إلا من حديث فلان»، أو نحو ذلك». الموازنة بين منهج المتقدمين والمتأخرين: ١٥. قلنا: وما ذكره الدكتور المليباري أعم من التعريف الأول وأدق؛ لأنه يشمل الثقة وغيره، وأما تعريف الميانشي فهو أخص، وهو المراد في البحث هنا؛ لأن تفرد الضعيف لا يعتد به أساسًا ما لم يتابع. قال الزركشي ٢/ ١٩٨: «وفيه صنّف الدارقطني كتاب الأفراد، ويستعمله الطبراني في معجمه الأوسط كثيرًا، ويحتاج لاتساع الباع في الحفظ، وكثيرًا ما يدّعي الحافظ التفرّد بحسب علمه، ويطلع غيره على المتابع». ="}],[754,"وقدْ سَبَقَ بيانُ المهمِّ مِنْ هذا النوعِ في الأنواعِ التي تليهِ قبلَهُ، لكنْ أفردتُهُ بترجمةٍ كما أفردَهُ الحاكمُ أبو عبد الله (١)، ولما بَقِيَ منهُ."],[755,"فنقولُ: الأفرادُ منقسمةٌ إلى ما هوَ فَرْدٌ مطلقًا، وإلى ما هوَ فَرْدٌ بالنِّسْبَةِ (٢) إلى جهةِ خاصَّةٍ (٣)."],[756,"أمَّا الأوَّلُ: فهوَ ما ينفرِدُ بهِ واحدٌ عَنْ كلِّ أحدٍ، وقدْ سبقتْ (٤) أقسامُهُ وأحكامُهُ قريبًا.","",{"fn":"معرفة علوم الحديث: ٩٦.\nفي (أ): «من النسبة».\nاعترض العلاّمة مغلطاي على ابن الصلاح، بأنه ذكر أنه تابع للحاكم في تقسيمه، والحاكم إنما قسمه إلى ثلاثة أقسام، فكان عليه أن يتابعه على هذا أيضًا. وقد أجاب ابن حجر في نكته ٢/ ٧٠٣ - ٧٠٩ بجواب طويل، فانظره فإنه مهمّ. تنبيه: للحافظ أبي الفضل محمد بن طاهر المقدسي تقسيم آخر للأفراد، ذكره في مقدمة ترتيبه لأطراف الغرائب والأفراد للدارقطني ١/ ٥٣، ومن أمعن فيها النظر وجدها راجعة في حقيقتها إلى ما ذكره المصنّف.\nفي (أ): «سقت»."}],[757,"وأمَّا الثاني: وهوَ ما هوَ فَرْدٌ بالنسبةِ، فمثلُ ما ينفردُ بهِ ثقةٌ عَنْ كلِّ ثقةٍ (١)، وحكمُهُ قريبٌ مِنْ حكمِ القسمِ الأوَّلِ، ومثلُ ما يقالُ فيهِ: «هذا حديثٌ تفرَّدَ بهِ أهلُ مكَّةَ (٢)، أو تفرَّدَ بهِ أهلُ الشامِ (٣)، أو أهلُ الكوفةِ (٤)، أو أهلُ خُراسانَ (٥) عَنْ غيرِهِم، أو لَمْ يروِهِ عَنْ فلانٍ غيرُ فلانٍ (٦)، وإنْ كانَ مرويًّا مِنْ وجوهٍ عنْ غيرِ فلانٍ، أو تفرَّدَ بهِ البصريونَ عَنِ المدنيِّينَ (١)، الخُرَاسانيُّونَ عَنِ المكِّيِّينَ» (٢)، وما أشبَهَ ذلكَ. ولسْنا نُطَوِّلُ بأمثلةِ ذلكَ فإنَّهُ مفهومٌ دونَها. وليسَ في شيءٍ مِنْ هذا ما يقتضي الحكمَ بضَعْفِ الحديثِ إلاَّ أنْ يُطلِقَ قائلٌ قولَهُ: «تفرَّدَ بهِ أهلُ مكَّةَ، أو تفرَّدَ بهِ البصريونَ عَنِ المدنيِّينَ»، أو نحوَ ذلكَ، على ما لَمْ يروِهِ إلاَّ واحدٌ مِنْ أهلِ مكَّةَ أو واحدٌ مِنَ البصريِّينَ ونحوُهُ، ويُضيفُهُ إليهم كما يُضافُ فعلُ الواحدِ مِنَ القبيلةِ إليها مَجَازًا، وقد فَعَلَ الحاكمُ (٣) أبو عبدِ اللهِ هذا فيما نحنُ فيهِ، فيكونُ الحكمُ فيهِ على ما سَبَقَ في القسمِ الأوَّلِ، واللهُ أعلمُ.","",{"fn":"مثاله: ما أخرجه البخاري ٢/ ٣٢ (١٠٠٢)، ومسلم ٢/ ١٣١ (٦٧٧) (٣٠١). من طريق عاصم الأحول، قال: سألت أنس بن مالك عن القنوت في الصلاة، قال: نعم، قلت: قبل الركوع أو بعده؟ قال: قبله». قال الزركشي ٢/ ٢٠١: «فعاصم ثقة، وقد تفرد عن سائر الرواة عن أنس في موضع القنوت، قال الأثرم: قلت لأحمد: يقول أحد في حديث أنس إن النبي - صلى الله عليه وآله وسلم - قنت قبل الركوع غير عاصم الأحول؟ فقال: ما علمت أحدًا يقوله غيره».\nمثاله: ما رواه الحاكم في المعرفة: ٩٨ من طريق ابن أبي مليكة، عن عائشة، أن رسول الله - صلى الله عليه وآله وسلم - خرج من عندها فقالت: يا رسول الله خرجت ... الحديث. قال الحاكم: «هذا حديث تفرّد به أهل مكة، وليس في رواته إلا مكي».\nمثاله: ما رواه الحاكم في المعرفة: ٩٨ من طريق ابن أنعم، عن عبد الرحمان بن رافع، عن ابن عمرو، عن النبي - صلى الله عليه وآله وسلم - أنه قال لأصحابه: «ألا إنه ستفتح عليكم أرض العجم ... الحديث». قال الحاكم: «تفرد بذكر تحريم الحمامات على النساء أهل الشام بهذا الإسناد».\nمثاله: ما رواه الحاكم في المعرفة: ٩٧ من طريق شريك عن أبي الحسناء، عن الحكم بن عتيبة، عن حنش، قال: كان علي - رضي الله عنه - يضحي بكبشين ... الحديث. قال الحاكم: «تفرّد به أهل الكوفة من أول الإسناد إلى آخره لم يشركهم فيه أحد».\nمثاله ما رواه الحاكم في المعرفة: ٩٨ - ٩٩ عن عبد الله بن بريدة، عن أبي بريدة، عن النبي - صلى الله عليه وآله وسلم - قال: القضاء ثلاثة ... الحديث. قال الحاكم: «هذا حديث تفرَّد به الخراسانيون، فإن رواته عن آخرهم مراوزة».\nمثاله: ما رواه الترمذي (٣٤٨٦) من طريق حماد بن عيسى الجهني، عن حنظلة بن أبي سفيان، عن سالم بن عبد الله بن عمر، عن أبيه، عن عمر ابن الخطاب، قال: كان رسول الله - صلى الله عليه وآله وسلم - إذا رفع يديه في الدعاء لم يحطّهما حتى يمسح بهما وجهه. قال الترمذي: «هذا حديث غريب لا نعرفه إلا من حديث حماد بن عيسى، وقد تفرّد به». وقال البزار في مسنده (١٢٩): «هذا الحديث إنما رواه عن حنظلة حماد بن عيسى، وهو ليّن الحديث، وإنما ضُعِّف حديثه بهذا الحديث ولم نجد بدًا من إخراجه، إذ كان لا يروى إلاَّ بهذا الإسناد أو من وجه آخر دونه»."}],[758,"النوع الثامن عشر معرفة الحديث المعلل"],[759,"(٤)"],[760,"ويُسَمِّيهِ أهلُ الحديثِ (٥): «المعلولَ»، وذلكَ منهم ومِنَ الفقهاءِ في قولِهِم في بابِ القياسِ: «العلَّةُ والمعلولُ»، مرذولٌ عندَ أهلِ العربيةِ واللُّغَةِ (٦).","",{"fn":"مثاله حديث عائشة مرفوعًا: «كلوا البلح بالتمر ...» المتقدم في نوع المنكر، فإن أبا زكير بصري وقد تفرد بهذا عن هشام بن عروة وهو مدني. قال الحاكم: «تفرد به أبو زكير عن هشام بن عروة، وهو من أفراد البصريين عن المدنيين». معرفة علوم الحديث: ١٠١.\nمثاله ما رواه الحاكم في المعرفة: ١٠١ من طريق إبراهيم عن علقمة عن ابن مسعود مرفوعًا قال: يقول الله عزوجل للدنيا: يا دنيا اخدمي من خدمني وأتعبي يا دنيا من خدمك». قال الحاكم: «هذا حديث من أفراد الخراسانيين عن المكيين».\nانظر: معرفة علوم الحَديث: ٩٦ وما بعدها.\nانظر في الحديث المعلل: معرفة علوم الحديث: ١١٢، وإرشاد طلاب الحقائق ١/ ٢٣٤ - ٢٤٨، والتقريب: ٧٥ - ٧٧، والمنهل الروي: ٥٢، والخلاصة: ٧٠، والموقظة: ٥١، واختصار علوم الحديث: ٦٣، وشرح التبصرة والتذكرة ١/ ٣٦٣، ونزهة النظر: ١٢٣، والمختصر: ١٣٤، وفتح المغيث ١/ ٢٠٩، وألفية السيوطي: ٥٥ - ٦٦، وشرح السيوطي على ألفية العراقي: ١٩٢، وفتح الباقي ١/ ٢٢٤، وتوضيح الأفكار ٢/ ٢٥، وظفر الأماني: ٣٦٣، وقواعد التحديث: ١٣١، وراجع كتاب: أثر علل الحديث في اختلاف الفقهاء.\nكالترمذي وابن عدي وأبي يعلى والدارقطني والحاكم والخليلي وغيرهم. انظر: فتح المغيث ١/ ٢١٠، وتدريب الراوي ١/ ٢٥١.\nوقد تبعه النووي، فقال: «إنه لحن»، واعتُرِض عليه بأنه قد حكاه جماعة من أهل اللغة. ="}],[761,"اعْلَمْ أنَّ معرفةَ علَلِ الحديثِ مِنْ أجلِّ علومِ الحديثِ وأدقِّها وأشرفِها، وإنَّما يَضْطَلِعُ (١) بذلكَ أهلُ الحِفْظِ والخِبْرَةِ والفَهْمِ الثَّاقِبِ (٢)، وهي عبارةٌ عَنْ أسبابٍ خفيَّةٍ غامِضَةٍ (٣) قادِحَةٍ فيهِ."],[762,"فالحديثُ المعلَّلُ: هو الحديثُ الذي اطُّلِعَ فيهِ على عِلَّةٍ تَقدَحُ في صحَّتِهِ مَعَ أنَّ ظاهِرَهُ السلامةُ منها (٤)."],[763,"ويتطرَّقُ ذلكَ إلى الإسنادِ الذي رجالُهُ ثقاتٌ، الجامعِ شروطَ الصِّحَّةِ مِنْ حيثُ الظاهِرُ. ويُسْتَعانُ على إدراكِها بتَفَرُّدِ الراوي، وبمخالفةِ غيرِهِ لهُ، معَ قرائِنَ (٥) تنضَمُّ إلى ذلكَ تُنَبِّهُ العارفَ بهذا الشأنِ على إرسالٍ في الموصولِ، أو وَقْفٍ في المرفوعِ، أو دُخُولِ حديثٍ في حديثٍ، أو وَهَمِ واهِمٍ بغيرِ ذلكَ بحيثُ يَغْلِبُ على ظنِّهِ ذلكَ، فيَحْكُمُ بهِ أو يتردَّدُ فيَتَوَقَّفُ فيهِ، وكلُّ ذلكَ مانعٌ مِنَ الحكمِ بصحَّةِ ما وُجِدَ ذلكَ فيهِ.","",{"fn":"جاءت في نسخة (أ) حاشية نصها: «يضطلع: تضلع امتلأ ريًّا حتى بلغ الماء أضلاعه»، والمراد هنا: الامتلاء من هذا العلم. وانظر: اللسان ٨/ ٢٢٩.\nأسند الحاكم في المعرفة ١١٣ عن أبي زرعة الرازي، أن رجلًا قال له: ما الحجة في تعليلكم الحديث؟ قال: الحجة أن تسألني عن حديث له علة فأذكر علته، ثم تقصد ابن وارة - يعني: محمد بن مسلم بن وارة - وتسأله عنه، ولا تخبره بأنك قد سألتني عنه، فيذكر علته، ثم تقصد أبا حاتم فيعلله، ثم تميّز كلام كلٍّ منّا على ذلك الحديث، فإن وجدت بيننا خلافًا في علته، فاعلم أن كلًا منّا تكلّم على مراده، وإن وجدت الكلمة متفقة فاعلم حقيقة هذا العلم، قال: ففعل الرجل فاتفقت كلمتهم عليه، فقال: أشهد أن هذا العلم إلهام».\nليست في (م).\nقال الحاكم: ١١٢ - ١١٣: «وإنما يعلل الحديث من أوجه ليس للجرح فيها مدخل، فإن حديث المجروح ساقط واهٍ، وعلة الحديث يكثر في أحاديث الثقات أن يحدّثوا بحديث له علة فيخفى عليهم علمه، فيصير الحديث معلولًا، والحجة فيه عندنا الحفظ والفهم والمعرفة لا غير». وانظر: نكت ابن حجر ٢/ ٧١٠.\nقال الزركشي ٢/ ٢٠٩: «اعلم أن للمحدثين أغراضًا في صناعتهم احتاطوا فيها لا يلزم الفقهاء اتباعهم على ذلك». ="}],[764,"وكثيرًا ما يُعَلِّلُونَ الموصولَ بالمرسلِ، مثلُ أنْ يجيءَ الحديثُ بإسنادٍ موصولٍ، ويجيءَ أيضًا بإسنادٍ منقطِعٍ أقوى مِنْ إسنادِ الموصولِ (١)، ولهذا اشتَمَلَتْ كُتُبُ عِلَلِ الحديثِ على جَمْعِ (٢) طُرُقِهِ. قالَ الخطيبُ أبو بكرٍ: «السبيلُ إلى معرفةِ عِلَّةِ الحديثِ: أنْ يُجْمَعَ بينَ طُرُقِهِ، ويُنْظَرَ في اختلافِ رُوَاتِهِ، ويُعْتَبَرَ بمكانِهِمْ (٣) مِنَ الحِفْظِ، ومنزلتِهِم في الإتقانِ والضبطِ» (٤)، ورُوِيَ عَنْ عليِّ بنِ المدينيِّ قالَ: «البابُ إذا لَمْ تُجْمَعْ (٥) طرقُهُ لَمْ يُتَبَيَّنْ خَطَؤُهُ» (٦)."],[765,"ثُمَّ قدْ تقعُ العِلَّةُ في إسنادِ الحديثِ - وهو الأكثرُ -، وقدْ تقعُ في متنِهِ (٧)، ثُمَّ ما يقعُ في الإسنادِ قدْ يقدحُ في صحَّةِ الإسنادِ والمتنِ جميعًا، كما في التعليلِ بالإرسالِ والوقْفِ، وقدْ يَقدحُ في صِحَّةِ الإسنادِ خاصَّةً من غيرِ قَدْحٍ في صِحَّةِ المتنِ.","",{"fn":"«ليس هذا من قبيل المعلول على اصطلاحه - وإن كانت علة في الجملة - إذ المعلول على اصطلاحه مقيد بالخفاء، والإرسال أو الانقطاع ليست علتها خفية». نكت ابن حجر ٢/ ٧٤٥.\nفي (جـ) و(م): «جميع».\nفي (أ): «مكانهم».\nالجامع لأخلاق الراوي وآداب السامع ٢/ ٢٩٥.\nفي (ب) و(جـ): «يجمع».\nالجامع لأخلاق الراوي ٢/ ٢١٢. وفيه أيضًا: عن الإمام أحمد بن حنبل: «الحديث إذا لم تجمع طرقه لم تفهمه، والحديث يفسّر بعضه بعضًا»، وقال ولد المصنف في طرح التثريب ٧/ ١٨١: «والحديث إذا جمعت طرقه تبين المراد منه، وليس لنا أن نتمسك برواية ونترك بقية الروايات».\nإذا وقعت العلة في الإسناد قد تقدح وقد لا تقدح، وإذا قدحت فقد تخصّه وقد تستلزم القدح في المتن. وكذا القول في المتن، فالأقسام على هذا ستة». نكت ابن حجر ٢/ ٧٤٦. ومن ثم مثّل لكل قسم."}],[766,"فَمِنْ أمثلةِ ما وقَعَتِ العِلَّةُ في إسنادِهِ مِنْ غيرِ قَدْحٍ في المتنِ: ما رواهُ الثِّقَةُ يَعْلَى ابنُ عُبَيْدٍ (١)، عَنْ سُفيانَ الثوريِّ، عَنْ عمرِو بنِ دينارٍ، عَنِ ابنِ عُمَرَ، عَنِ النبيِّ - صلى الله عليه وآله وسلم - قالَ:"],[767,"«البَيِّعَانِ بالخِيارِ ... الحديثَ». فهذا إسنادٌ متَّصِلٌ بنقلِ العدلِ عَنِ العدْلِ، وهوَ مُعلَّلٌ غيرُ صحيحٍ، والمتنُ على كلِّ حالٍ صحيحٌ، والعلَّةُ في قولِهِ: «عَنْ عمرِو بنِ دينارٍ» إنَّما هوَ عَنْ عبدِ اللهِ بنِ دينارٍ، عنِ ابنِ عُمرَ، هكذا رواهُ الأئمَّةُ مِنْ أصحابِ سفيانَ عنهُ (٢)، فوَهِمَ يَعلى بنُ عُبيدٍ (٣)، وعَدَلَ عَنْ عبدِ اللهِ بنِ دينارٍ إلى عَمْرِو بنِ دينارٍ، وكلاهُما ثِقَةٌ (٤).","",{"fn":"رواية يعلى بن عبيد أخرجها الطبراني في الكبير ١٢/ ٣٤٣ (١٣٦٢٩).\nوقفنا على ثمانية من أصحاب سفيان الثوري، رووه عنه على الصواب، وهم: - أبو نعيم الفضل بن دكين، عند أحمد ٢/ ١٣٥، والبيهقي ٥/ ٢٥٩، وابن عبد البر ١٤/ ٢٢. - عبد الرزاق الصنعاني، كما في مصنفه (١٤٢٦٥). - محمد بن يوسف الفريابي، عند البخاري ٣/ ٨٤. - قتيبة بن سعيد، عند النسائي ٧/ ٢٥٠. - ابن أبي عمر العدني، عند البيهقي ٥/ ٢٦٩. - أبو حذيفة موسى بن مسعود الفهري، عند الطحاوي في شرح المعاني ٤/ ١٢. - مؤمل بن إسماعيل، عند الطحاوي في شرح المعاني ٤/ ١٢. - مخلد بن يزيد الحراني، عند النسائي ٧/ ٢٥٠. تنبيه: وقع في المطبوع من سنن النسائي ٧/ ٢٥٠ في هذه الرواية الأخيرة: «عمرو بن دينار»، فكأن مخلدًا متابع ليعلى في روايته، والصواب أنه تحريف في الطباعة وأنه: «عبد الله». انظر: تحفة الأشراف ٥/ ٤٥٠ (٧١٥٥)، والمسند الجامع ١/ ٤٤٠ (٧٧٣٠)، وشرح السيوطي ١٩٣ - ١٩٤.\n«ما ذكره من توهيم يعلى سبقه إليه الدارقطني، وقال في علله الكبير: «هذا الحديث يرويه الثوري وشعبة، واختلف عنهما فروى ابن أبي عبد الرحمان المقرئ، عن أبيه، عن شعبة، عن عمرو بن دينار، عن ابن عمر، وكذلك رواه يعلى بن عبيد، عن عمرو بن دينار، وكلاهما وهم، والصحيح: عن الثوري، وعن شعبة، عن عبد الله بن دينار». نكت الزركشي ٢/ ٢١١.\nبعد هذا وردت في (جـ) زيادة نصها: «وعند هذا يظهر أن المعلل ليس من قبيل نوع الشاذ المقدم ذكره، فإن الشاذ يحكم بردّه بمجرد الشذوذ من غير توقف على بيان وجه الصواب، والعلة التي هي جهة الخطأ، والمعلل يُبُيِّنَ فيه العلة التي هي جهة الخطأ ويوضح فيه وجه الصواب في الحديث، كما في المثال الذي أوردناه»."}],[768,"ومثالُ العلَّةِ في المتنِ: ما انْفَرَدَ مسلمٌ (١) بإخراجِهِ في حديثِ أنسٍ مِنَ اللَّفظِ المصرَّحِ بنفي قراءَةِ: «بسمِ اللهِ الرحمنِ الرحيمِ» فعلَّلَ قومٌ (٢) روايةَ اللفظِ المذكورِ لَمَّا رأوا الأكثرينَ إنَّما قالوا فيهِ: «فكانوا يَسْتَفْتِحونَ القراءةَ بـ: «الحمدُ للهِ ربِّ العالمينَ» مِنْ غيرِ تعرُّضٍ لذكرِ البسمَلَةِ، وَهُوَ الَّذِي اتَّفَقَ البخاريُّ (٣) ومسلمٌ (٤) عَلَى إخراجِهِ في الصحيحِ، ورأوا أنَّ مَنْ رواهُ باللَّفظِ المذكورِ، رواهُ بالمعنى الَّذِي وقَعَ لهُ، فَفَهِمَ مِنْ قولِهِ: «كانوا يَستفتحونَ بـ: «الحمدُ للهِ» (٥)، أنَّهُم كانوا لا يُبَسْمِلُونَ، فرَوَاهُ على ما فَهِمَ، وأخطأَ؛ لأنَّ معناهُ أنَّ السورةَ التي كانوا يفتتحونَ بها مِنَ السُّورِ هيَ الفاتحةُ، وليسَ فيهِ تعرُّضٌ لذكرِ التسميةِ. وانضمَّ إلى ذلكَ أمورٌ (٦)، منها: أنَّهُ ثَبَتَ عَنْ أنسٍ أنَّهُ سُئِلَ عَنِ الافتتاحِ بالتسميةِ، فذَكَرَ أنَّهُ لا يَحفظُ فيهِ شيئًا عَنْ رسولِ اللهِ - صلى الله عليه وآله وسلم - (٧)،"],[769,"واللهُ أعلمُ."],[770,"ثُمَّ اعلمْ أنَّهُ قدْ يُطلقُ اسمُ العِلَّةِ على غيرِ ما ذكرناهُ من باقي الأسبابِ القادحةِ في الحديثِ الْمُخرِجةِ لهُ مِنْ حالِ الصِّحَّةِ إلى حالِ الضَّعْفِ، المانعةِ مِنَ العملِ بهِ، على ما هو مُقتضى لفظِ العِلَّةِ في الأصلِ (١)، ولذلكَ (٢) تجدُ (٣) في كتبِ عللِ الحديثِ الكثيرَ مِنَ الجرحِ بالكذبِ، والغفلَةِ، وسوءِ الحفظِ، ونحو ذلكَ مِنْ أنواعِ الجرحِ.","",{"fn":"٢/ ١٢ (٣٩٩).\nأراد به الدارقطني. انظر: سننه ١/ ٣١٦، ونكت ابن حجر ٢/ ٧٦٦.\n١/ ١٨٩ (٧٤٣).\n٢/ ١٢ (٣٩٩). كلاهما (البخاري ومسلم) من طريق شعبة عن قتادة عن أنس، به. لكن سياقيهما يختلفان.\nفي (أ) و(جـ): «بالحمد».\nللحافظ العراقي في التقييد والإيضاح: ١٢٢ وما بعدها تعليق طويل مفيد جدًا، فانظره.\nرواه الإمام أحمد في المسند ٣/ ١٦٦، وابن خزيمة (١٠١٠) إلا أنه اختصره وحذف منه موطن الشاهد، بدلالة رواية الدارقطني في السنن ١/ ٣١٦. قال الدارقطني: «هذا إسناد صحيح». وقال الهيثمي في المجمع ٢/ ١٠٨: «رجاله ثقات»."}],[771,"وسمَّى الترمذيُّ النَّسْخَ عِلَّةً مِنْ عِللِ الحديثِ (٤). ثُمَّ إنَّ بعضَهُمْ (٥) أطلقَ اسمَ العِلَّةِ على ما ليسَ بقادِحٍ مِنْ وجوهِ الخلافِ، نحوُ إرسالِ مَنْ أرسلَ الحديثَ الذي أسندهُ الثقةُ الضابطُ، حتَّى قالَ: «مِنْ أقسامِ الصحيحِ ما هوَ صحيحٌ معلولٌ» (٦)، كما قالَ"],[772,"بعضُهُم: «مِنَ الصحيحِ ما هوَ صحيحٌ شاذٌّ» (٧)، واللهُ أعلمُ.","",{"fn":"«مراده بذلك أن ما حققه من تعريف المعلول، قد يقع في كلامهم ما يخالفه، وطريق التوفيق بين ما حقّقه المصنف وبين ما يقع في كلامهم أن اسم العلة إذا أطلق على حديث لا يلزم منه أن يسمى الحديث معلولًا اصطلاحًا. إذ المعلول ما علته قادحة خفية والعلة أعم من أن تكون قادحة أو غير قادحة، خفية أو واضحة. ولهذا قال الحاكم: «وإنما يعلّ الحديث من أوجه ليس فيها للجرح مدخل» ...». نكت ابن حجر ٢/ ٧٧١. وقريب منه ما حققه علاّمة العراق الشيخ الدكتور هاشم جميل - حفظه الله - من: «أن المحدّثين إذا تكلّموا عن العلة باعتبار أن خلو الحديث منها يعد قيدًا لا منه لتعريف الحديث الصحيح، فإنهم في هذه الحالة يطلقون العلة ويريدون بها المعنى الاصطلاحي الخاص، وهو: السبب الخفي القادح. وإذا تكلموا في نقد الحديث بشكل عام فإنهم في هذه الحالة يطلقون العلة ويريدون بها: السبب الذي يعل الحديث به، سواء كان خفيًا أم ظاهرًا، قادحًا أم غير قادح». أثر علل الحديث في اختلاف الفقهاء: ١٧.\nفي (جـ): «وكذلك».\nكذا في جميع النسخ و(م)، وفي (ع)، والتقييد: «نجد» - بموحدة فوقية - ووقع في الشذا كما في (ع)، وأشار المحقق إلى نسخة توافق المثبت.\nانظر: شرح علل الترمذي لابن رجب ١/ ٢٨. وهو مقتضى صنيع ابن أبي حاتم في علله، انظر: رقم (١١٤) و(٢٤٦). وعلّق الزركشي في نكته ٢/ ٢١٥ على هذا الموضع بقوله: «لعلّ الترمذي يريد أنه علة في العمل بالحديث، لا أنه علة في صحته، لاشتمال الصحيح على أحاديث منسوخة، ولا ينبغي أن يجري مثل ذلك في التخصيص». وانظر: شرح التبصرة ١/ ٣٨٩، ونكت ابن حجر ٢/ ٧٧١.\nهو الخليلي في كتابه الإرشاد. وانظر: نكت الزركشي ٢/ ٢١٦، والتقييد: ١٢٤.\nانظر: الإرشاد ١/ ١٥٧ و١٦٠.\nانظر: المصدر السابق."}],[773,"النوع التاسع عشر معرفة المضطرب من الحديث"],[774,"(١)"],[775,"الْمُضْطَرِبُ (٢) مِنَ الحديثِ: هوَ الذي تَخْتَلِفُ الروايَةُ فيهِ، فَيَرْوِيْهِ بَعْضُهُم عَلَى وَجْهٍ، وبَعْضُهُم على وَجْهٍ آخرَ مخَالِفٍ لَهُ (٣). وإنَّمَا نُسَمِّيْهِ مُضْطَرِبًا إذا تَسَاوَتِ"],[776,"الروايتَانِ (٤)، أمَّا إذا تَرَجَّحَتْ إحْدَاهُما بحيثُ لاَ تُقَاوِمُها الأخرَى، بأنْ يكونَ رَاوِيْها أحْفَظَ، أوْ أكْثَرَ صُحْبَةً للمَروِيِّ عنهُ، أو غيرَ ذلكَ مِنْ وجوهِ التَّرْجِيحاتِ المعتَمَدَةِ، فالحكمُ للراجِحَةِ، ولاَ يُطْلَقُ عليهِ حينَئِذٍ وَصْفُ المضْطَرِبِ، ولاَ لَهُ حُكْمُهُ.","",{"fn":"انظر في المضطرب: الإرشاد ١/ ٢٤٩ - ٢٥٣، والتقريب: ٧٧ - ٧٨، والاقتراح: ٢١٩، والمنهل الروي: ٥٢، والخلاصة: ٧٦، والموقظة: ٥١، واختصار علوم الحديث: ٧٢، والمقنع ١/ ٢٢١، وشرح التبصرة والتذكرة ١/ ٣٩٠، ونزهة النظر: ١٢٦، والمختصر: ١٠٤، وفتح المغيث ١/ ٢٢١، وألفية السيوطي: ٦٧ - ٦٨، وشرح السيوطي على ألفية العراقي: ١٩٧، وفتح الباقي ١/ ٢٤٠، وتوضيح الأفكار ٢/ ٣٤، وظفر الأماني: ٣٩٢، وقواعد التحديث: ١٣٢.\nاسم فاعل من اضْطَرَبَ، مأخوذ لغةً من الاضطراب بمعنى: الحركة والاختلاف، يقال: اضطرب الموج، أي: ضرب بعضه بعضًا، فهو مضطرب. وينبغي التنبيه على أن الشائع تسميته بـ «المضطرِب» عَلَى وزن اسم الفاعل، وَهُوَ من باب الإسناد المجازي؛ لأن الاضطراب واقع فيه لا منه، إذ أنه اسم مكان، فيظهر فيه اضطراب الراوي أو الرواة فهو على الحقيقة «مضطرَب» -بفتح الراء-، ولو سمي كذلك لكان أظهر في المعنى الاصطلاحي. انظر: حاشية الأجهوري على شرح الزرقاني للبيقونية: ٧٢، وشرح الديباج المذهَّب: ٤٨، ولمحات في أصول الحديث: ٢٤٧، وأثر علل الحديث في اختلاف الفقهاء: ١٩٧.\n«قد يخرج ما لو حصل الاضطراب من راوٍ واحدٍ. وقد يقال فيه: نبنيه على دخوله من باب أولى، فإنه أولى بالرد من الاختلاف بين راويين. وينبغي أن يقال: «على وجه يؤثر؛ ليخرج ما لو روي الحديث عن رجل مرة، وعن آخر أخرى ...». نكت الزركشي ٢/ ٢٢٤.\n«كان ينبغي أن يقول: وإنما يؤثر الاضطراب إذا تساوت، وإلا فلا شك في الاضطراب عند الاختلاف تكافأت الروايات أم تفاوتت». نكت الزركشي ٢/ ٢٢٦."}],[777,"ثُمَّ قَدْ يَقَعُ الاضطرابُ في مَتْنِ الحديثِ، وقَدْ يقعُ في الإسنادِ، وقدْ يَقَعُ ذَلِكَ مِنْ رَاوٍ واحِدٍ، وقدْ يَقَعُ بَيْنَ رُوَاةٍ لَهُ جَمَاعَةٌ (١). والاضطرابُ مُوجِبٌ ضَعْفَ الحديثِ؛ لإشعارِهِ بأنَّهُ لَمْ يُضْبَطْ، واللهُ أعلمُ."],[778,"وَمِنْ أمْثِلَتِهِ: ما رُوِّيْنَاهُ عَنْ إسْمَاعيلَ بنِ أُمَيَّةَ، عنْ أبي عَمْرِو بنِ محَمَّدِ بنِ حُرَيْثٍ، عَنْ جَدِّهِ حُرَيْثٍ، عَنْ أبي هُرَيْرَةَ، عَنْ رَسُوْلِ اللهِ - صلى الله عليه وآله وسلم - في الْمُصَلِّي: «إذَا لَمْ يَجِدْ عَصًا يَنْصِبُهَا بَيْنَ يَدَيْهِ فَلْيَخُطَّ خَطًّا». فَرَواهُ بِشْرُ بنُ الْمُفَضَّلِ (٢)، ورَوْحُ بنُ القَاسِمِ (٣)، عَنْ إسْماعيلَ هَكَذا. ورَوَاهُ سُفيانُ الثَّوْرِيُّ (٤) عنهُ، عَنْ أبي عَمْرِو بنِ حُرَيْثٍ، عَنْ أبيهِ، عَنْ أبي هُرَيْرَةَ. ورَوَاهُ حُمَيْدُ بنُ الأسْوَدِ (٥)، عَنْ إسْمَاعيلَ، عَنْ أبي عَمْرِو بنِ محمدِ بنِ حُرَيْثِ بنِ سُلَيْمٍ، عَنْ أبيهِ، عَنْ أبِي هُرَيْرَةَ. ورَوَاهُ وُهَيْبٌ (٦) وعَبْدُ الوارِثِ (٧)، عَنْ إسْمَاعيلَ، عَنْ أبي عَمرِو بنِ حُرَيْثٍ، عَنْ جَدِّهِ حُرَيْثٍ. وقَالَ عبدُ الرَّزَّاقِ (٨)، عَنِ ابنِ جُرَيْجٍ: سَمِعَ إسْمَاعِيلَ، عَنْ حُرَيْثِ بنِ عَمَّارٍ، عَنْ أبِي هُرَيْرَةَ. وفيهِ مِنَ الاضطرابِ أكْثَرُ مَا ذَكَرْناهُ (٩)، واللهُ أعلم.","",{"fn":"للحافظ العلائي كلام جميل يشمل تعليل الحديث بالاضطراب وغيره. نقله الحافظ ابن حجر في نكته ١/ ٧٧٧، فراجعه تجد فائدة.\nعند أبي داود (٦٨٩)، وابن خزيمة (٨١٢). قلنا: وهو كذلك في رواية وهيب بن خالد عند عبد بن حميد (١٤٣٦).\nطريق روح ذكرها المزي في تهذيب الكمال ٨/ ٤١٩.\nعند أحمد ٢/ ٢٤٩ و٢٥٤ و٢٦٦، وابن خزيمة (٨١٢).\nعند ابن ماجه (٩٤٣).\nعند عبد بن حميد (١٤٣٦). ولكنَّ فيها خلافًا عما هنا أشرنا إليه قبل قليل.\nذكرها البيهقي في الكبرى ٢/ ٢٧١.\nالمصنف (٢٢٨٦).\nكرواية سفيان بن عيينة عند أحمد ٢/ ٢٤٩ وغيره، ورواية معمر بن راشد عند أحمد ٢/ ٢٤٩ و٢٥٤ و٢٦٦، وابن خزيمة (٨١٢). وكرواية ذواد بن علبة التي ذكرها المزي في التهذيب ٨/ ٤١٩. وفيه أيضًا اختلاف على سفيان بن عيينة في إسناده، واختلاف على عليّ بن المديني أيضًا. ="}],[779,"النَّوْعُ العِشْرُوْنَ (١)"],[780,"مَعْرِفَةُ الْمُدْرَجِ (٢) في الْحَدِيْثِ وَهوَ أقْسَامٌ: مِنْها ما أُدْرِجَ في حديثِ رَسُوْلِ اللهِ - صلى الله عليه وآله وسلم - مِنْ كَلاَمِ بَعْضِ رواتِهِ بأنْ يَذْكُرَ الصَّحَابيُّ أو مَنْ بَعْدَهُ عَقِيْبَ ما يَرْوِيهِ مِنَ الحديثِ كلاَمًا مِنْ عِندِ نفسِهِ، فيَرْوِيهِ مَنْ بَعدَهُ موصولًا بالحديثِ غيرَ فاصِلٍ بينهُما بذِكْرِ قائِلِهِ، فيلتَبِسُ الأمرُ فيهِ على مَنْ لاَ يَعْلَمُ حقيقةَ الحالِ، ويَتَوَهَّمُ أنَّ الجميعَ عن رَسُوْلِ اللهِ - صلى الله عليه وآله وسلم - (١).","",{"fn":"قال الزركشي ٢/ ٢٤١: «حقه أن يقول: «تمام العشرين» أو نحوه؛ فإن العشرين اسم للمجموع، وليس هو المراد هنا، وإنما المراد واحد منها وهو مكملها، وقد وقع التعبير بالتكميل في كلام الشافعي في الأم، وقد رجع المصنف إلى الصواب فيما سيأتي، إذ قال: النوع الموفِّي ثلاثين».\nالْمُدْرَجُ لغةً - بضم الميم وفتح الراء -: اسم مفعول من (أدرج)، تقول: أدرجت الكتاب إذا طويته، وتقول: أدرجت الميت في القبر إذا أدخلته فيه، وتقول: أدرجت الشيء في الشيء: إذا أدخلته فيه وضمنته إيَّاه. وفي اصطلاح المحدثين: هو ما كانت فيه زيادة ليست منه، أو بعبارة أوضح: هو الحديث ... الذي يعرف أن في سنده أو متنه زيادة ليست منه، وإنما هي من أحد الرواة من غير توضيح ... لهذه الزيادة». حاشية محيي الدين عبد الحميد على توضيح الأفكار ٢/ ٥٠، والتعليقات الأثرية لعلي حسن على المنظومة البيقونية: ٣٧. وانظر الاقتراح: ٢٢٣، والموقظة: ٥٣، وتاج العروس ٥/ ٥٥٥. وانظر في المدرج: معرفة علوم الحديث: ٣٩، والإرشاد ١/ ٢٥٤ - ٢٥٧، والتقريب: ٧٩ - ٨٠، والاقتراح: ٢٢٣، والمنهل الروي: ٥٣، والخلاصة: ٥٣، والموقظة: ٥٣، واختصار علوم الحديث: ٧٣، والمقنع ١/ ٢٢٧، ونزهة النظر: ١٢٤، وشرح التبصرة والتذكرة ١/ ٣٩٥، والمختصر: ١٤٥، وألفية السيوطي: ٧٣ - ٧٩، وشرح السيوطي على ألفية العراقي: ٢٠١، وفتح الباقي ١/ ٢٤٦، وتوضيح الأفكار ٢/ ٥٠، وظفر الأماني: ٢٤٨، وقواعد التحديث: ١٢٤."}],[781,"ومِنْ (٢) أمثلَتِهِ المشهورَةِ: مَا رُوِّيْنَاهُ في التَّشَهُّدِ عَنْ أبي خَيْثَمَةَ زُهَيْرِ بنِ معاويةَ عَنِ الحسَنِ بنِ الْحُرِّ، عَنِ القاسِمِ بنِ مُخَيْمِرَةَ (٣) عَنْ عَلْقَمَةَ، عَنْ عَبدِ اللهِ بنِ مسعودٍ؛ أنَّ رَسُوْلَ اللهِ - صلى الله عليه وآله وسلم - عَلَّمَهُ التَّشَهُّدَ في الصلاةِ فقالَ: «قُل: التَّحِيَّاتُ للهِ ... فَذَكَرَ التَّشَهُّدَ، وفي آخِرِهِ: أشْهَدُ أنْ لاَ إِلَهَ إلاَّ اللهُ، وأشْهَدُ أنَّ مُحَمَّدًا رَسُولُ اللهِ فإذا قُلْتَ هذا فَقَدْ قَضَيْتَ صَلاَتَكَ، إنْ شِئْتَ أنْ تقُومَ فَقُمْ، وإنْ شِئْتَ أنْ تَقْعُدَ فاقْعُدْ» (٤)."],[782,"هَكَذَا رَواهُ أبو خَيْثَمَةَ، عَنِ الحسَنِ بنِ الْحُرِّ، فأدْرَجَ في الحديثِ قَوْلَهُ: «فَإِذَا قلتَ هَذَا ... إلى آخرِهِ»، وإنَّما هَذَا مِنْ كَلاَمِ ابنِ مَسْعودٍ لاَ مِنْ كلاَمِ رَسُوْلِ اللهِ - صلى الله عليه وآله وسلم - (٥)."],[783,"ومِنَ الدليلِ عليهِ أنَّ الثِّقةَ الزَّاهِدَ (٦) عبدَ الرَّحْمَانِ بنَ ثابِتِ ثوبَانَ، رواهُ عَنْ راوِيْهِ (١) الحسَنِ بنِ الْحُرِّ كَذَلِكَ (٢)، واتَّفَقَ حُسَيْنٌ الْجُعْفيُّ (٣) وابنُ عَجْلاَنَ (٤) وغَيْرُهُما (٥) في روايَتِهِم عَنِ الحسَنِ بنِ الحرِّ على تَرْكِ ذِكْرِ هذا الكَلامِ في آخِرِ الحديثِ مَعَ اتِّفَاقِ كُلِّ مَنْ رَوَى التَّشَهُّدَ عَنْ عَلْقَمَةَ، وعَنْ غَيْرِهِ، عَنِ ابنِ مسعودٍ على ذلكَ، وروَاهُ شَبَابَةُ، عَنْ أبي خَيْثَمَةَ ففَصَلَهُ أيضًا (١).","",{"fn":"قَيَّد المصنف الإدراج بكونه عقب الحديث، وما نظَّره المصنف خلاف الواقع، نعم ... أكثر ما يدرج يكون عقب المتن، إلا أن الإدراج وقع في بدايات بعض الأحاديث وفي وسطها، ثم إن الإدراج يقع أيضًا في الإسناد كما يقع في المتن، وعلى هذا كله يدل صنيع الخطيب البغدادي في كتابه \"الفصل للوصل المدرج في النقل\". وانظر: نكت الزركشي ٢/ ٢٤١، والتقييد والإيضاح: ١٢٧، ونكت ابن حجر ٢/ ٨١١.\n«من» ليست في (أ).\nبضم الميم وفتح الخاء المعجمة وكسر الميم الثانية. شرح صحيح مسلم للنووي ١/ ٣٠٠، وكذا في الخلاصة: ٣١٤، ولكنه قال بفتح الميم الثانية.\nأخرجه من هذه الطريق: الطيالسي (٢٧٥)، وأحمد ١/ ٤٢٢، والدارمي (١٣٤٧)، وأبو داود (٩٧٠)، وابن حبان (١٩٦١)، والدارقطني ١/ ٣٥٣.\nنص على هذا غير واحد من الحفّاظ، منهم: الدارقطني في السنن ١/ ٣٥٣، وفي العلل (١٢٧٥)، والحاكم في معرفة علوم الحديث: ٣٩، والبيهقي في الكبرى ٢/ ١٧٤، والخطيب في الفصل: ١٠٤، ونقل النووي في الخلاصة ٦١ / ب اتفاق الحفّاظ على إدراجها. وانظر: تعليقاتنا على شرح التبصرة والتذكرة ١/ ٣٩٦ - ٤٠٠.\nقلنا: أما زهده فلا خلاف في أنه كان نهاية في الزهد والعبادة. وأما كونه «ثقة» فلعل اجتهاد المصنف فيه كان كذلك، وإلا ففيه خلاف في توثيقه، ولم يوثقه إلا قلّة، وإليك أقوال العلماء كما أوردها المزي في تهذيبه ٤/ ٣٨١: =\nفي (أ): «رواية».\nعند ابن حبان (١٩١٢)، والطبراني في الكبير (٩٩٢٤)، وفي مسند الشاميين (٦٤)، والدارقطني ١/ ٣٥٤، والحاكم في المعرفة: ٣٩ - ٤٠، والبيهقي ٢/ ١٧٥، والخطيب في الفصل: ١٠٨ - ١٠٩.\nعند ابن أبي شيبة ١/ ٢٩١، وأحمد ١/ ٤٥٠، وابن حبان (١٩٦٣)، والطبراني (٩٩٢٦)، والدارقطني ١/ ٣٥٢، والخطيب في الفصل: ١٠٩ - ١١٠.\nعند الطبراني (٩٩٢٣)، والدارقطني ١/ ٣٥٢، والخطيب في الفصل: ١١٠.\nكمحمد بن أبان كما ذكر روايته الدارقطني في سننه ١/ ٣٥٢ - ٣٥٣. قلنا: وقد رواه ابن حبان أيضًا (١٩٦٣) من طريق حسين الجعفي السابق، وزاد في آخره: «قال الحسن ابن الحر: وزادني فيه محمد بن أبان بهذا الإسناد، قال: فإذا قلت هذا أو فعلت هذا، فإن شئت فقم». وهذا يدل على أن محمد بن أبان كان ممن يدرج هذه الزيادة في الحديث المرفوع، إلا أن ابن حبان عقّب على هذه الرواية بقوله: «محمد بن أبان ضعيف، قد تبرأنا من عهدته في كتاب المجروحين». ولم يشر الدارقطني في علله إلى متابعة محمد بن أبان. ولعل هذا الخلاف في كون رواية ابن أبان متابعة لابن ثوبان أو لأبي خيثمة هي التي جعلت ابن الصلاح يضرب عن التصريح باسمه، واكتفى بالإشارة إلى وجودها بقوله: «وغيرهما». والله أعلم."}],[784,"ومِنْ أقْسَامِ المدرَجِ: أنْ يكونَ مَتْنُ الحديثِ عِنْدَ الراوي لَهُ (٢) بإسْنادٍ إلاَّ طَرَفًا منهُ، فإنَّهُ عِنْدَهُ بإسنادٍ ثانٍ، فَيُدْرِجُهُ مَنْ رَواهُ عنهُ على الإسنادِ الأوَّلِ ويَحْذفُ الإسْنَادَ الثَّانيَ، ويروِي جميعَهُ بالإسْنَادِ الأوَّلِ."],[785,"مِثَالُهُ: «حديثُ ابنِ عُيَيْنَةَ (٣) وزائِدَةَ بنِ قُدَامَةَ (٤) عَنْ عَاصِمِ بنِ كُلَيْبٍ، عَنْ أبيهِ، عَنْ وائِلِ بنِ حُجْرٍ في صِفَةِ صَلاَةِ رَسُوْلِ اللهِ - صلى الله عليه وآله وسلم -، وفي آخِرِهِ: «أنَّهُ جَاءَ في الشِّتَاءِ، فَرَآهُمْ يَرْفَعُونَ أيْدِيَهُمْ مِنْ تَحْتِ الثِّيَابِ»، والصَّوابُ: روايةُ مَنْ رَوَى عَنْ عاصِمِ بنِ كُلَيْبٍ بِهَذَا الإسْنَادِ صِفَةَ الصَّلاَةِ خاصَّةً، وفَصَلَ ذِكْرَ رَفْعَ الأيدي عنهُ، فرواهُ عَنْ عاصِمٍ، عَنْ عبدِ الجبَّارِ بنِ وائلٍ، عَنْ بعضِ أهلِهِ، عَنْ وائلِ بنِ حُجْرٍ (٥)."],[786,"ومِنْهَا: أنْ يُدْرِجَ في مَتْنِ حديثٍ بَعْضَ مَتْنِ حديثٍ آخَرَ مُخَالِفٍ للأوَّلِ في الإسْنَادِ.","",{"fn":"أخرجها الدارقطني في السنن ١/ ٣٥٣، والبيهقي في الكبرى ٢/ ١٧٤، والخطيب في الفصل: ١٠٨.\nساقطة من (جـ).\nعند الشافعي في المسند (١٩٧ بتحقيقنا)، والحميدي (٨٨٥)، والنسائي ٢/ ٢٣٦، والدارقطني ١/ ٢٩٠، والخطيب في الفصل: ٢٧٩.\nعند أحمد ٤/ ٣١١، والدارمي (١٣٦٤)، وابن الجارود (٢٠٨)، وابن حبان (١٨٥٧)، والطبراني في الكبير ٢٢ / (٨٢)، والخطيب في الفصل: ٢٧٩.\nوممن رواه على الصواب: زهير بن معاوية: عند أحمد ٤/ ٣١٨، والطبراني ٢٢ / (٨٤)، والخطيب في الفصل: ٢٨٤. شجاع بن الوليد: عند الخطيب في الفصل: ٢٨٤. قال موسى بن هارون الحمال: «وذاك - يعني: رواية سفيان وزائدة - عندنا وهم وإنما أدرج عليه، وهو من رواية عاصم، عن عبد الجبار بن وائل، عن بعض أهله، عن وائل. هكذا رواه مبينًا زهير بن معاوية وأبو بدر شجاع بن الوليد، فميزا قصة تحريك الأيدي من تحت الثياب، وفصلاها من الحديث وذكرا إسنادهما كما ذكرنا». ثم قال: «وهذه رواية مضبوطة اتفق عليه زهير وشجاع بن الوليد، وهما أثبت له رواية ممن روى «رفع الأيدي من تحت الثياب»، عن عاصم بن كليب، عن أبيه، عن وائل». نكت الزركشي ٢/ ٢٤٧ - ٢٤٨."}],[787,"مِثَالُهُ: روايَةُ سَعِيْدِ بنِ أبي مَرْيمَ (١)، عَنْ مَالِكٍ، عَنِ الزُّهْرِيِّ، عَنْ أنَسٍ: أنَّ رَسُوْلَ اللهِ - صلى الله عليه وآله وسلم - قالَ: «لاَ تَبَاغَضُوا، ولاَ تَحَاسَدُوا، ولاَ تَدَابَرُوا، ولاَ تَنَافَسُوا ... الحديثَ». فَقَولُهُ: «لا (٢) تَنَافَسُوا» أدْرَجَهُ ابنُ أبي مَريمَ (٣) مِنْ مَتْنِ حديثٍ آخَرَ رَواهُ مَالِكٌ (٤)، عَنْ أبي الزِّنَادِ، عَنِ الأعْرَجِ، عَنْ أبي هُرَيْرَةَ فيهِ: «لاَ تَجَسَّسُوا، ولاَ تَحَسَّسُوا، ولاَ تَنَافَسُوا، ولاَ تَحَاسَدُوا» (٥)، واللهُ أعلمُ.","",{"fn":"هو أبو محمد سعيد بن الحكم بن محمد الجمحي، مولاهم المصري، ثقة له غرائب، توفي سنة (٢٢٤ هـ). الثقات ٨/ ٢٦٦، وتذكرة الحفاظ ١/ ٣٩٢، وتقريب التهذيب (٢٢٨٦).\nفي (جـ): «ولا».\nوروايته أخرجها: الخطيب في الفصل: ٤٤٣، وابن عبد البر في التمهيد ٦/ ١١٦.\nفي الموطأ (٢٦٤٠) رواية الليثي. ومن طريقه الخطيب في الفصل: ٤٤٣.\nوالحديثان هكذا على الصواب عند رواة الموطأ، إذ رواه عن مالك: - عبد الله بن يوسف التنيسي، عند البخاري ٨/ ٢٣ (٦٠٦٦) و٨/ ٢٥ (٦٠٧٦). - عبد الله بن مسلمة القعنبي. عند أبي داود (٤٩١٠) و(٤٩١٧)، وأبي نعيم في الحلية ٣/ ٣٧٤، والخطيب في الفصل: ٤٤٣ - ٤٤٤. - قتيبة بن سعيد. عند أبي أحمد الحاكم في عوالي مالك (٧٢)، والخطيب في الفصل: ٤٤٤، والعلائي في بغية الملتمس (١٥١). - يحيى بن يحيى النيسابوري. عند مسلم ٨/ ٨ (٢٥٥٩) و٨/ ١٠ (٢٥٦٣). - أبو مصعب الزهري. كما في روايته للموطأ (١٨٩٤) و(١٨٩٥). - إسماعيل بن أبي أويس. عند البخاري في الأدب المفرد (٣٩٨) و(١٢٨٧). - سويد بن سعيد. كما في موطئه (٦٨١) و(٦٨٢). - عبد الله بن وهب. عند الطحاوي في شرح المشكل (٤٥٤) و(٤٥٧). - عبد الرحمان بن القاسم. في روايته للموطأ (٤). - الفضل بن دكين. عند ابن عبد البر في التمهيد ٦/ ١١٦. - محمد بن سليمان المصيصي لوين. عند أبي أحمد الحاكم في عوالي مالك (٧٦). - يحيى بن بكير. عند العلائي في بغية الملتمس (١٥١). - إسحاق بن عيسى الطباع. عند أحمد ٢/ ٤٦٥. - روح بن عبادة. عند أحمد ٢/ ٥١٧. - محمد بن الحسن الشيباني. كما في الموطأ (٨٩٦) بروايته. قال حمزة بن محمد الكناني: «لا أعلم أحدًا قال في هذا الحديث عن مالك: «ولا تنافسوا» غير سعيد ابن أبي مريم». التمهيد ٦/ ١١٦. قال الخطيب: «وقد وهم فيها ابن أبي مريم على مالك عن ابن شهاب، وإنما يرويها مالك في حديثه عن أبي الزناد». نكت الزركشي ٢/ ٢٤٩."}],[788,"ومِنْهَا: أنْ يَرْوِيَ الراوي حَدِيثًا عَنْ جَمَاعَةٍ بَيْنَهُمُ اخْتِلاَفٌ في إسْنَادِهِ، فَلاَ (١) يَذْكُرُ الاخْتِلاَفَ بَلْ يُدْرِجُ روَايَتَهُمْ عَلَى الاتِّفَاقِ."],[789,"مِثَالُهُ: روَايَةُ عَبْدِ الرَّحْمَانِ بنِ مَهْديٍّ (٢) ومُحَمَّدِ بنِ كَثيرٍ العَبْدِيِّ (٣)، عَنِ الثَّوْرِيِّ، عَنْ مَنْصُورٍ والأعْمَشِ ووَاصِلٍ الأحْدَبِ، عَنْ أبي وائِلٍ، عَنْ عَمْرِو بنِ شُرَحْبِيْلَ، عَنِ ابنِ مَسْعُودٍ، قلتُ: «يَا رَسُوْلَ اللهِ أيُّ الذَّنْبِ أعْظَمُ؟ ... الحديثَ»."],[790,"ووَاصِلٌ إنَّمَا رَوَاهُ، عَنْ أبي وائِلٍ، عَنْ عبدِ اللهِ، مِنْ غَيْرِ ذِكْرِ عَمْرِو بنِ شُرَحْبِيْلَ بينَهُما (٤)، واللهُ أعلمُ.","",{"fn":"في (ب): «ولا».\nعند أحمد ١/ ٤٣٤، والترمذي (٣١٨٢)، والخطيب في الفصل: ٤٨٥.\nعند الخطيب في الفصل: ٤٨٥.\nوطريق واصل رواه عنه جماعة، منهم: - شعبة. عند الطيالسي (٢٦٤)، وأحمد ١/ ٤٣٤ و٤٦٤، والترمذي (٣١٨٣)، والنسائي ٧/ ٩٠، والخطيب في الفصل: ٤٩٠. - مالك بن مغول. عند النسائي في الكبرى (٧١٢٥)، والخطيب في الفصل: ٤٩١. - مهدي بن ميمون. عند أحمد ١/ ٤٦٢، والخطيب في الفصل: ٤٩٢. - سعيد بن مسروق. عند الخطيب في الفصل: ٤٩٣. وقد فصل الإسنادين يحيى بن سعيد القطان في روايته عن سفيان كما أخرجها البخاري في صحيحه ٦/ ١٣٧ (٤٧٦١) و٨/ ٢٠٤ (٦٨١١)، والدارقطني في علله ٥/ ٢٢٢، والخطيب في الفصل: ٤٩٣، عن مسدد وعمرو بن علي مفرقين كلاهما عن يحيى، قال: حدثنا سفيان، قال: حدثني: منصور وسليمان - يعني: الأعمش - عن أبي وائل، عن أبي ميسرة، عن عبد الله ... قال يحيى: وحدثنا سفيان، قال: حدثني واصل، عن أبي وائل، عن عبد الله. لكن أخرج النسائي ٧/ ٨٩ هذا الحديث من طريق بندار، عن ابن مهدي، عن سفيان، عن واصل - وحده -، عن أبي وائل، عن عمرو بن شرحبيل، عن عبد الله. فزاد في السند عَمْرًا. قال العراقي في شرح التبصرة ١/ ٤١١: «وكأنَّ ابنَ مهدي لما حدَّثَ به عن سفيان، عن منصور، والأعمش، وواصل، بإسناد واحد ظنَّ الرواة عن ابن مهدي اتفاق طرقه، فربما اقتصر أحدهم على بعض شيوخ سفيان». ="}],[791,"واعْلَمْ أنَّهُ لاَ يَجُوزُ تَعَمُّدُ شيءٍ مِنَ الإدْرَاجِ المذكورِ. وهَذَا النَّوْعُ قَدْ صَنَّفَ فيهِ الخطيبُ أبو بَكرٍ كِتَابَهُ الموسُومَ بـ\" الفَصْلِ للوَصْلِ الْمُدرَجِ في النَّقْلِ \" فَشَفَى وَكَفَى (١)، واللهُ أعلمُ."],[792,"النوع الحادي والعشرون معرفة الموضوع"],[793,"(٢)","",{"fn":"قال البلقيني في محاسن الاصطلاح: ٢١٢: «ومع ذلك فقد ترك أشياء». وذكر ابن كثير هذا الكتاب باسم \" فصل الوصل لما أُدرج في النقل \". انظر: الباعث الحثيث ١/ ٢٢٤، والكتاب مطبوع متداول بأكثر من تحقيق.\nقال البقاعي في النكت والوفية ١٧٦/ ب: «الموضوع هو اسم مفعول من وَضَعَ الشيءَ يَضَعُهُ -بالفتح- وَضْعًا حطَّه إشارة إلى أنّ رتبته أن يكون دائمًا مُلقًى مطّرحًا لا يستحق الرفع». قلنا: ويشبه أن يكون من باب استعمال الأضداد في المعاني المتناقضة؛ إذ ما ينسب إلى النبي - صلى الله عليه وآله وسلم - يسمّى مرفوعًا، تعظيمًا لقدره ومراعاة لجهة نسبته إلى المصطفى - صلى الله عليه وآله وسلم -. أما المكذوب: فسُمِّيَ موضوعًا إشارةً إلى عدم استحقاقه وأخذه بنظر الاعتبار، بل منْزلته أن يبقى غير معبوءٍ به. ="}],[794,"وَهوَ الْمُخْتَلَقُ الْمَصْنُوعُ. اعْلَمْ أنَّ الحديثَ الْمَوْضُوْعَ شَرُّ الأحاديثِ الضَّعِيْفَةِ (١)، ولاَ تَحِلُّ رِوَايَتُهُ لأحَدٍ عَلِمَ حَالَهُ في أيِّ معنًى كَانَ إلاَّ مَقْرُونًا ببيَانِ وَضْعِهِ (٢)، بخِلاَفِ غَيْرِه مِنَ الأحاديثِ الضَّعِيْفَةِ التي يُحتَمل صِدقُها في الباطِنِ (١)، حيثُ جَازَ روَايَتُها في الترغيبِ والترهيبِ، عَلَى مَا نُبَيِّنُهُ قريبًا إنْ شَاءَ اللهُ تَعَالَى.","",{"fn":"يَرِدُ على المصنف هنا أمران ذكرهما الزركشي ٢/ ٢٥٣ - ٢٥٤: الأول: أن عبارته هذه قد سبقه بها الخطّابي، واستنكرها الناس؛ لأن الموضوع لا يُعدُّ حديثًا، واسم التفضيل إنما يستعمل في التفاضل بين معانٍ يجمعها معنى مشترك. ويمكن أن يقال أيضًا: كيف أفرده المصنف بنوع مستقل، وهو ليس من الأحاديث، فضلًا عن كونه نوعًا من أنواع علوم الحديث؟ ويمكن الإجابة: بأنه أراد القدر المشترك بينها، وهو ما يحدث به. الثاني: ما ذكره هنا يخالف ما ذكره في قسم الضعيف: بقوله: «ما عدم فيه جميع الصفات هو القسم الأَخِر الأرذل». والصواب: ما ذكره هنا. وانظر: التقييد والإيضاح: ١٣٠ - ١٣١، ونكت ابن حجر ٢/ ٨٣٨.\nبدليل ما أخرجه مسلم في مقدمة صحيحه ١/ ٧ وغيره من حديث سمرة بن جندب والمغيرة بن شعبة -رضي الله عنهما- عن النبي - صلى الله عليه وآله وسلم - قال: «مَنْ حدّث عني بحديث يرى أنه كذب فهو أحد الكاذبين». وضُبِطَت «يَرَى» بالفتح بمعنى: يقطع، وبالضمّ بمعنى: يظن. وكذا «الكاذبين» فيها روايتان: فتح الباء: بمعنى المثنى، وكسرها على إرادة الجمع. انظر شرح النووي على صحيح مسلم ١/ ٥٣. قال ابن حجر ٢/ ٨٣٩: «وكفى بهذه الجملة وعيدًا شديدًا في حقّ مَنْ روى الحديث فيظن أنه كذب، فضلًا عن أن يتحقق ذلك ولا يبينه؛ لأنه - صلى الله عليه وآله وسلم - جعل المحدِّثَ بذلك مشاركًا لكاذبه في وضعه». وقال مسلم في المقدمة ١/ ٦: «واعلم - وفقك الله تعالى - أن الواجب على كل أحد عرف التمييز بين صحيح الروايات وسقيمها، وثقات الناقلين لها، من المهتمين أن لا يروي منها إلا ما عرف صحة مخارجه. والستارة في ناقليه، وأن يتقي منها ما كان عن أهل التهم والمعاندين من أهل البدع»."}],[795,"وإنَّما يُعْرَفُ كَوْنُ الحدِيْثِ مَوضُوعًا بإقْرَارِ وَاضِعِهِ (٢)، أو مَا يَتَنَزَّلُ مَنْزِلَةَ إقْرَارِهِ (٣)، وقدْ يَفْهَمُونَ الوَضْعَ مِنْ قَريْنَةِ حَالِ الراوي (١) أو الْمَرويِّ (٢)، فقدْ (٣) وُضِعَتْ أحَاديثُ طويلَةٌ يَشْهَدُ بوضْعِهَا رَكَاكَةُ ألفَاظِهَا ومَعَانِيها (٤).","",{"fn":"«يريد جعل احتمال صدقها قيدًا في جواز العمل بها. لكن هل يشترط في هذا الاحتمال أن يكون قويًا بحيث يفوق احتمال كذبها أو يساويه أو لا؟ هذا محل نظر، والذي يظهر من كلام مسلم ربما دلَّ عليه الحديث المتقدم، بأن احتمال الصدق إذا كان احتمالًا ضعيفًا أنه لا يعتد به». أفاده ابن حجر في نكته ٢/ ٨٤٠.\nاعترض عليه العلاّمة ابن دقيق العيد في الاقتراح: ٢٣٤، فقال: «هذا كافٍ في ردِّهِ، لكنه ليس بقاطع في كونه موضوعًا؛ لجواز أن يكذب في هذا الإقرار بعينه». وأجاب عنه الزركشي في نكته ٢/ ٢٥٦ بقوله: «إن كان الحديث لا يعرف إلا من طريق ذلك الشخص كان إقراره بذلك مسقطًا لروايته، وقد حكم الشرع على المقرِّ بمقتضى إقراره، وإن كان يحتمل أن يكون في نفس الأمر خلافه فلا نظر إلى ذلك». قلنا: وقد فهم الحافظ الذهبي من كلام شيخه ابن دقيق العيد أن إقرار الواضع لا يعمل به أصلًا، فقال في الموقظة: ٣٧: «هذا فيه بعض ما فيه، ونحن لو افتتحنا باب التجويز والاحتمال البعيد لوقعنا في الوسوسة والسفسطة». كذا قال الذهبي!! وردّه الحافظ ابن حجر في نزهة النظر: ١١٨، فقال: «وفهم منه بعضهم أنه لا يعمل بذلك الإقرار أصلًا، وليس ذلك مراده، وإنما نَفَى القطعَ بذلك، ولا يلزم من نفيِ القطعِ نفيُ الحكم؛ لأن الحكم يقع بالظن الغالب وهو هنا كذلك، ولولا ذلك لما ساغ قتل المقرِّ بالقتل ولا رجم المعترف بالزنى، لاحتمال أن يكونا كاذبين فيما اعترفا به». وزاد الأمر إيضاحًا في نكته على كتاب ابن الصلاح ٢/ ٨٤٠ - ٨٤١، فقال: «كلام ابن دقيق العيد ظاهر في أنه لا يستشكل الحكم؛ لأن الأحكام لا يشترط فيها القطعيات، ولم يقل أحد أنه يقطع بكون الحديث موضوعًا بمجرد الإقرار، إلا أن إقرار الواضع بأنه وضع يقتضي موجب الحكم العمل بقوله، ... وهذا كله مع التجرد. أما إذا انضمّ إلى ذلك قرائن تقتضي صدقه في ذلك الإقرار كمن روى عن مالك، عن نافع، عن ابن عمر - رضي الله عنهما - حديث الأعمال بالنيات، فإنا نقطع بأنه ليس من رواية مالك ولا نافع ولا ابن عمر».\nقال ابن حجر ٢/ ٨٤٢: «يمثل لذلك بما رواه البيهقي في المدخل بسنده الصحيح، أنهم اختلفوا - بحضور أحمد بن عبد الله الجويباري - في سماع الحسن من أبي هريرة - رضي الله عنه -، فروى لهم حديثًا بسنده إلى النبي - صلى الله عليه وآله وسلم -، قال: «سمع الحسن من أبي هريرة - رضي الله عنه -». =\nمثّل الحافظ العراقي في التقييد: ١٣٢ لما يتنَزّل منْزلة إقرار الراوي بالتاريخ، قال: «كان يحدّث بحديث عن شيخ، ثم يسأل عن مولده، فيذكر تاريخًا يعلم وفاة ذلك الشيخ قبله، ولا يوجد ذلك الحديث إلا عنده». وتعقّبه تلميذه ابن حجر في نكته ٢/ ٨٤٢ بأن الأولى: «أن يمثل بالتاريخ لقول ابن الصلاح: «أو من قرينة حال الراوي» ...».\nقال ابن حجر ٢/ ٨٤٣: «هذا الثاني هو الغالب، وأما الأول، فنادر». وقال الإمام ابن دقيق العيد: «وأهل الحديث كثيرًا ما يحكمون بذلك باعتبار أُمور ترجع إلى المروي وألفاظ الحديث. وحاصله يرجع إلى أنه حصلت لهم لكثرة مزاولة ألفاظ الرسول - صلى الله عليه وآله وسلم - هيأة نفسانية، أو مَلَكة يعرفون بها ما يجوز أن يكون من ألفاظ النبي - صلى الله عليه وآله وسلم -، وما لا يجوز أن يكون من ألفاظه. كما سُئِل بعضهم: كيف تَعرف أن الشيخ كذّاب؟ فقال: إذا روى لا تأكلوا القرعة حتى تذبحوها، علمت أنه كذّاب». الاقتراح: ٢٣١ - ٢٣٢.\nفي (جـ): «وقد».\n«اعترض عليه بأن ركاكة اللفظ لا تدلّ على الوضع، حيث جوزت الرواية بالمعنى. نعم إن صرح الراوي بأن هذا صيغة لفظ الحديث، وكانت تخل بالفصاحة أو لا وجه لها في الإعراب، دلّ على ذلك. والذي يظهر أن المؤلف لم يقصد أن ركاكة اللفظ وحده تدل، كما تدل ركاكة المعنى. بل ظاهر كلامه أن الذي يدل هو مجموع الأمرين: ركاكة اللفظ والمعنى معًا». قاله ابن حجر في نكته ٢/ ٨٤٤، وانظر: نكت الزركشي ٢/ ٢٦١. قلنا: هناك أمور أخرى يعرف ويستدل بها على الوضع، منها: - أن يخالف أحكام العقل من غير قبول للتأويل. - أن يخالف الحسّ والمشاهدة. - أن يكون خبرًا عن أمر عظيم تتوافر الدواعي على نقله، ثم لا ينقله إلا واحد. - مناقضته لنص الكتاب أو السنة المتواترة أو الإجماع القطعي. - أن يصرح جمع كبير يمتنع في العادة تواطؤهم على الكذب، أو التقليد بتكذيب راويه. - الإفراط بالوعيد الشديد على فعل الأمر اليسير، أو الوعد العظيم على فعل صغير. وغيرها من الأدلة التي تقوي في نفس الناقد الحكم على ذلك الحديث بالوضع. وانظر: نكت الزركشي ٢/ ٢٦٥، ونكت ابن حجر ٢/ ٨٤٥."}],[796,"ولَقَدْ أكثرَ الذي جَمَعَ في هذا العصْرِ «الموْضُوعاتِ» في نحوِ مُجَلَّدَيْنِ، فأَوْدَعَ فِيْهَا كَثِيرًا مِمَّا لاَ دلِيْلَ عَلَى وَضْعِهِ (١)، وإنَّمَا حَقُّهُ أنْ يُذْكَرَ في مُطلَقِ الأحَاديثِ الضَّعِيْفَةِ."],[797,"والواضِعُونَ للحدِيْثِ أصْنَافٌ (٢)، وأعْظَمُهُم ضَرَرًا: قومٌ مِنَ المنْسُوبِيْنَ إلى الزُّهْدِ وَضَعُوا الحديثَ احْتِسَابًا فيما زَعَمُوا فتَقَبَّلَ (٣) النَّاسُ موضُوعَاتِهِم ثِقَةً منْهُم بِهِمْ ورُكُونًا إليهِم (٤). ثُمَّ نَهَضَتْ جَهَابِذَةُ (٥) الحديثِ بِكَشْفِ عُوَارِهَا (٦)، ومَحْوِ عَارِهَا، والحمْدُ للهِ. وفِيْما رُوِّيْنَا عَنِ الإمَامِ أبي بَكْرٍ السَّمْعَانِيِّ (٧) أنَّ بَعْضَ الكَرَّامِيَّةِ (١) ذَهَبَ إلى جوَازِ وَضْعِ الحديثِ في بابِ التَّرغِيْبِ والتَّرهِيْبِ (٢).","",{"fn":"مراده بهذا العلاّمة ابن الجوزي، وكتابه في \" الموضوعات \" مطبوع متداول. انظر: نكت الزركشي ٢/ ٢٧٧، ونكت ابن حجر ٢/ ٨٤٧.\nقال القاضي عياض: «منهم مَن وضع عليه ما لم يقله أصلًا، إمّا استخفافًا كالزنادقة، أو حسبةً بزعمهم، وتديّنًا كجهلة المتعبدين الذين وضعوا الأحاديث في الفضائل والرغائب، أو إغرابًا وسمعةً كفَسَقَةِ المحدِّثين، أو تعصّبًا واحتجاجًا كدعاة المبتدعة ومتعصبي المذاهب، أو اتِّباعًا لهوى فيما أرادوا، وطلب العذر لهم فيما راموه. وقد تعيّن جماعة من كلٍّ من هذه الطبقات عند أهل الصنعة وعلماء الرجال، ومنهم من لا يضع متن الحديث، ولكن ربما وضع للمتن الضعيف إسنادًا، ومنهم من يقلب الأسانيد ويزيد فيها، ويستعمل ذلك إما للإغراب على غيره أو لرفع الجهالة عن نفسه. ومنهم من يكذب ليدعي سماع ما لم يسمع ولقاء من لم يلق، ويحدث بأحاديثهم الصحيحة عنهم، ومنهم من يعمد إلى كلام الصحابة أو غيرهم وحِكَمِ العرب فينسبها للنبي - صلى الله عليه وآله وسلم - ترويجًا لها». نقله الزركشي في نكته ٢/ ٢٨٣ - ٢٨٤. وانظر: المجروحين ١/ ٦٢، والموضوعات ١/ ٣٦، ونكت ابن حجر ٢/ ٨٥٠، وتذكرة الموضوعات: ٥.\nفي (أ): «فقبل».\nقال الحافظ العراقي في شرح التبصرة والتذكرة ١/ ٤٢٠: «ولكن الواضعون ممَّن يُنْسَبُ للصلاح، وإن خَفِيَ حالهم على كثير من الناس، فإنّه لم يَخْفَ على جَهابِذَةِ الحديثِ، ونقّاده. فقاموا بأعباء ما حُمِّلُوا فتحمَّلوه، فكشفُوا عُوَارَها، ومَحْوا عَارَها. حتى لقد روينا عن سفيان قال: ما ستر اللهُ أحدًا يكذبٍ في الحديثِ ... الخ كلامه.\nجمع جِهْبَذ، وهو النَّقَّادُ الخبيرُ بغوامِضِ الأمورِ العارفُ بطرقِ النَّقْدِ. انظر: تاج العروس ٩/ ٣٩٢.\nمثلث العين، ومعناه: العيب والخرق والشق. انظر: تاج العروس ١٣/ ١٥٧.\nنقله العلاّمة ابن الجوزي في موضوعاته ١/ ٩٦، وأورد أيضًا شبه المجيزين للوضع وردها في بحث فريد مهم. وقال الزركشي ١/ ٢٨٣: «هذا قاله ابن السمعاني في المجلس الثالث من أماليه».\nنسبةً إلى محمد بن كرّام السجستاني، قال الذهبي في السير ١١/ ٥٢٣: «خُذِلَ حَتَّى التقط من المذاهب أردأها، ومن الأحاديث أوهاها». وكرّام: المشهور - بتشديد الراء - ضبطه الخطيب، وابن ماكولا، وابن السمعاني، وغير واحد، وهو الجاري على الألسنة. وقيل: كَرَام - بالتخفيف والفتح -، وقيل: كِرَام - بالكسر - على لفظ جمع كريم. انظر: ميزان الاعتدال ٤/ ٢١، ونكت الزركشي ٢/ ٢٨٨، ونكت ابن حجر ٢/ ٨٥٨، والنكت الوفية: ١٨٣ / أ.\nواستدلّوا لما ذهبوا إليه بحديث رواه يونس بن بكير، عن الأعمش، عن طلحة بن مصرّف، عن عمرو ابن شرحبيل، عن عبد الله بن مسعود يرفعه: «من كذب عليّ متعمدًا ليضلّ الناس فليتبوّأ مقعده من النار». قلنا: الدلالة لهم في هذا الحديث لما ذهبوا إليه منتفية من حيث الصنعة الحديثية، ومن حيث الدلالة. أما من حيث الصنعة فلما يأتي: - روي هذا الحديث عن يونس بن بكير من غير هذه الزيادة. أخرجه الحاكم في المدخل إلى الصحيح: ٩٨ - ٩٩. - هذا الطريق أخرجه البزار: (٢٠٩ كشف الأسرار)، والطحاوي في شرح المشكل (٤١٨)، وابن عدي في مقدمة الكامل ١/ ٨٤، والحاكم في المدخل إلى الصحيح: ٩٩ - ١٠٠، وابن الجوزي في الموضوعات ١/ ٩٧. قال الطحاوي: «هذا حديث منكر، وليس أحد يرفعه بهذا اللفظ غير يونس بن بكير، وطلحة ابن مصرِّف ليس في سنّه ما يدرك به عمرو بن شرحبيل تقدم وفاته، وقد حُدِّثَناه من غير حديث يونس بن بكير، فأدخل فيه بين طلحة وعمرو بن شرحبيل أبا عمار وهو غريب». وقال ابن عدي: «هذا اختلفوا فيه على طلحة بن مصرَّف: فمنهم من أرسله، ومنهم من قال: عن علي بدل عبد الله، ويونس بن بكير جوّد إسناده». وقد نبّه الحاكم في المدخل إلى الإكليل: ١٠٠ على خطأ يونس بن بكير في موضعين: الأول: أنه أسقط بين طلحة وعمرو رجلًا هو أبو عمار. الثاني: وصله بذكر ابن مسعود، وإنما هو مرسل. وقد أخرجه الطحاوي في شرح المشكل (٤١٩) من طريق أبي معاوية الضرير محمد بن خازم - من أحفظ الناس لحديث الأعمش (تقريب التهذيب ٥٨٤١) - عن الأعمش، عن طلحة، عن أبي عمار، عن عمرو بن شرحبيل مرفوعًا. ليس فيه ذكر لابن مسعود. ثم قال: «وقد وجدناه أيضًا من حديث الثوري، عن الأعمش كذلك غير أنه قال: عن عمرو ابن شرحبيل، عن رجل من أصحاب النبي عليه السلام». ثم رواه من هذه الطريق (٤٢٠). ="}],[798,"ثُمَّ إنَّ الوَاضِعَ رُبَّمَا صَنَعَ (١) كَلاَمًا مِنْ عِنْدِ نَفْسِهِ فَرَوَاهُ، ورُبَّمَا أخَذَ كَلاَمًا لِبَعْضِ الْحُكَمَاءِ أو غيرِهِمْ فَوَضَعَهُ على رَسُوْلِ اللهِ - صلى الله عليه وآله وسلم - (٢). ورُبَّمَا غَلِطَ غَالِطٌ فَوَقَعَ في"],[799,"شِبْهِ الوَضْعِ مِنْ غَيْرِ تَعَمُّدٍ كما وقَعَ لثَابِتِ بنِ موسَى الزَّاهِدِ في حديثِ: «مَنْ كَثُرَتْ صَلاَتُهُ باللَّيْلِ، حَسُنَ وَجْهُهُ بالنَّهَارِ» (٣).","",{"fn":"في (ب) و(م): «وضع».\nكحديث: «المعدة بيت الداء، الحمية رأس الدواء». قال السخاوي: «لا يصح رفعه إلى النبي - صلى الله عليه وآله وسلم - بل هو من كلام الحارث بن كلدة طبيب العرب أو غيره» المقاصد الحسنة (١٠٣٥). وقال السيوطي: «لا أصل له، إنما هو من كلام بعض الأطباء». الدرر المنتثرة (٣٧١). وانظر: زاد المعاد ٤/ ١٠٤، وشرح التبصرة ١/ ٤٢٨.\nرواه ابن ماجه (١٣٤٧). وراجع فيه: الضعفاء للعقيلي ١/ ١٧٦، والكامل ٢/ ٥٢٦، والموضوعات لابن الجوزي ٢/ ١٠٩، وتهذيب الكمال ٤/ ٣٧٨، والميزان ١/ ٣٦٧، والنكت الوفية: ١٨٦/ ب، والمقاصد: (١١٦٩) واللآلي ٢/ ١٨، والفوائد المجموعة: ٢٥. وقد أشبع الحافظ العراقي الكلام عليه في شرح التبصرة والتذكرة ١/ ٤٢٩ - ٤٣١، فراجعه مع ما علّقناه هناك."}],[800,"مِثَالٌ: «رُوِّيْنَا عَنْ أبي عِصْمَةَ وهوَ: نُوْحُ بنُ أبي مَرْيمَ (١) أنَّهُ قِيْلَ لَهُ: «مِنْ أيْنَ لَكَ عَنْ عِكْرِمَةَ، عَنِ ابنِ عَبَّاسٍ، في فَضَائِلِ القُرْآنِ سُورَةً سُوْرَةً؟»، فقالَ: «إنِّي رَأيْتُ النَّاسَ قَدْ أعْرَضُوا عَنِ القُرْآنِ واشْتَغَلُوا بِفِقْهِ أبي حَنِيْفَةَ، ومَغَازِي مُحَمَّدِ بنِ إسْحَاقَ، فَوَضَعْتُ هذهِ الأحَادِيْثَ حِسْبَةً» (٢)."],[801,"وهكذا حَالُ الحديثِ الطَّويلِ الذي يُرْوَى عَنْ أُبَيِّ بنِ كَعْبٍ، عَنِ النبيِّ - صلى الله عليه وآله وسلم - في فَضْلِ القُرْآنِ سُوْرَةً فَسُوْرَةً، بحثَ باحِثٌ (٣) عَنْ مَخْرَجِهِ حَتَّى انتَهَى إلى مَنِ اعترَفَ بأنَّهُ وجماعةً وضَعُوْهُ، وإنَّ أثَرَ الوَضْعِ لَبَيِّنٌ عليهِ. ولَقَدْ أخطأَ الواحِدِيُّ الْمُفَسِّرُ ومَنْ ذكَرَهُ مِنَ المفسِّرِيْنَ في إيدَاعِهِ تَفَاسِيْرَهُمْ (٤)، واللهُ أعلمُ.","",{"fn":"هو أبو عصمة نوح بن أبي مريم يزيد بن عبد الله المروزي، كان عالم أهل مرو، ويلقب بالجامع؛ لجمعه أنواع المعارف، وهو متهم بالوضع، توفي سنة (١٧٣ هـ). ميزان الاعتدال ٤/ ٢٧٩.\nرواه الحاكم في المدخل إلى الإكليل: ٤٨، وابن الجوزي في الموضوعات ١/ ٤١.\nأبهمه المصنف، وهو المؤمل بن إسماعيل. كما صُرِّحَ به في القصة التي ساقها الخطيب في الكفاية: (٥٦٧ ت، ٤٠١ هـ)، وابن الجوزي في الموضوعات ١/ ٢٤١. قال الزركشي ٢/ ٢٩٧: «كأن المصنف إنما أبهم الباحث لفضاضة فيه، فقد قال أبو حاتم الرازي: مؤمل بن إسماعيل كثير الخطأ، وقال البخاري: منكر الحديث». فيما يرى ابن حجر ٢/ ٨٦٢ أنه أبهمه اختصارًا. وانظر: التقييد والإيضاح: ١٣٤، واللآلي المصنوعة ١/ ٢٢٧، وتنْزيه الشريعة ١/ ٢٨٥.\n«كالثعلبي والزمخشري في ذكره، لكن الثعلبي والواحدي ذكراه بالإسناد، فخف حاله؛ لأنه يعرف أمره من الإسناد، بخلاف من ذكره بلا إسنادٍ وجزم به كالزمخشري، فإن خطأه أشد». نكت الزركشي ٢/ ٢٩٧ - ٢٩٨. وقال الحافظ العراقي: «وكل مَنْ أودع حديث أُبَيٍّ - المذكور - تفسيره، كالواحدي، والثَّعْلبي والزمخشري مخطئ في ذلك؛ لكن مَنْ أبرز إسناده منهم، كالثعلبي، والواحدي فهو أبسط لعذره، إذ أحال ناظره على الكشف عن سنده، وإن كان لا يجوز له السكوت عليه من غير بيانه، كما تقدّم. وأما مَنْ لم يُبْرِزْ سنَده، وأورده بصيغة الجزم فخطؤُه أفحش، كالزمخشري». شرح التبصرة والتذكرة ١/ ٤٢٤. وقال العلاَّمة ابن الجوزي في موضوعاته ١/ ٢٤٠: «وقد فرّق هذا الحديث أبو إسحاق الثعلبي في تفسيره فذكر عند كل سورة منه ما يخصها، وتبعه أبو الحسن الواحدي في ذلك ولا أعجب منهما؛ لأنهما ليسا من أصحاب الحديث، وإنما عجبت من أبي بكر بن أبي داود كيف فرقه على كتابه الذي صنّفه في فضائل القرآن، وهو يعلم أنه حديث محال، ولكن شره جمهور المحدّثين، فإن من عادتهم تنفيق حديثهم ولو بالبواطيل، وهذا قبيح منهم؛ لأنه قد صحّ عن رسول الله - صلى الله عليه وآله وسلم - أنه قال: «مَن حدّث عني بحديث يرى أنه كذب فهو أحد الكاذبين» ...»."}],[802,"النوع الثاني والعشرون معرفة المقلوب"],[803,"(١)"],[804,"هُوَ نَحْوُ حَدِيثٍ مَشْهُورٍ عَنْ سَالِمٍ، جُعِلَ عَنْ نَافِعٍ (٢) ليَصِيْرَ بذلكَ غَرِيبًا مَرْغُوبًا فيهِ (٣). وكذلكَ ما رُوِّيْنَا (٤) أنَّ البخاريَّ - رضي الله عنه - قَدِمَ بَغْدَادَ، فاجْتَمَعَ قَبْلَ مَجْلِسِهِ قومٌ مِنْ أصْحَابِ الحديثِ، وعمدُوا إلى مئةِ حديثٍ، فَقَلَبُوا مُتُونَهَا وأسَانِيْدَهَا، وجَعَلُوا مَتْنَ هَذا الإسنادِ لإسنادٍ آخَرَ، وإسنادَ هذا المتْنِ لِمَتْنٍ آخَرَ، ثُمَّ حَضَرُوا مَجْلِسَهُ وألْقَوْهَا عليهِ، فَلَمَّا فَرَغُوا مِنْ إلْقَاءِ تِلْكَ الأحادِيْثِ المقلوبَةِ التفَتَ إليْهِمْ فَرَدَّ كُلَّ مَتْنٍ إلى إسْنَادِهِ، وكُلَّ إسْنَادٍ إلى مَتْنِهِ، فأَذْعنُوا لَهُ بالفَضْلِ (٥).","",{"fn":"المقلوب لغة: هو مَنْ قَلَبَهُ إذا حَوَّلَه من حالٍ إلى حالٍ. ويقال أيضًا قَلَبَ فلانٌ الشيءَ إذا صرفَهُ عن وجهه. انظر: لسان العرب ١/ ٤٧٩، والنكت الوفية: ١٩٠/ ب، وتاج العروس ٤/ ٦٨. وانظر في المَقلوب: الإرشاد ١/ ٢٦٦ - ٢٧٢، والتقريب: ٨٦ - ٨٧، والاقتراح: ٢٣٦، والمنهل الروي: ٥٣، والخلاصة: ٧٦ والموقظة: ٦٠، واختصار علوم الحديث: ٨٧، وشرح التبصرة والتذكرة ١/ ٤٣٤، ونزهة النظر: ١٢٥، والمختصر: ١٣٦، وفتح المغيث ١/ ٢٥٣، وألفية السيوطي: ٦٩ - ٧٢، وشرح السيوطي على ألفية العراقي: ٢٢٥،، وفتح الباقي ١/ ٢٨٢، وتوضيح الأفكار ٢/ ٩٨، وظفر الأماني: ٤٠٥، وقواعد التحديث: ١٣٠.\nقال ابن حجر ٢/ ٨٦٤: «هذا تعريف بالمثال، وحقيقته: إبدال من يعرف برواية غيره». وزاد السخاوي: «عمدًا أو سهوًا». ويدخل فيه إبدال راوٍ أو أكثر من راوٍ حتى الإسناد كله. وانظر: نكت الزركشي ٢/ ٢٩٩، وفتح المغيث ١/ ٢٩٨، وتوضيح الأفكار ٢/ ٤٣ مع تعليق المحقق.\nقال ابن حجر ٢/ ٨٦٤: «قد يقع ذلك عمدًا إما بقصد الإغراب، أو لقصد الامتحان، وقد يقع وهمًا، فأقسامه ثلاثة وهي كلها في الإسناد، وقد يقع نظيرها في المتن، وقد يقع فيهما جميعًا».\nفي (م): «رويناه».\nرواها ابن عدي في جزء أسامي من روى عنهم البخاري من مشايخه: ٢/ أ. ومن طريقه رواه الخطيب في تاريخ بغداد ٢/ ٢٠. وانظر: وفيات الأعيان ٤/ ١٨٩، وسير أعلام النبلاء ١٢/ ٤٠٨، وطبقات الشافعية الكبرى ٢/ ٦، والبداية والنهاية ١/ ٢٥."}],[805,"ومِنْ أمْثِلَتِهِ -ويصلحُ مثالًا للمُعَلَّلِ (١) - ما رُوِّيْنَاهُ عَنْ إسْحَاقَ بنِ عِيْسَى الطَّبَّاعِ، قالَ: حَدَّثَنَا جَرِيْرُ بنُ حازِمٍ، عَنْ ثَابِتٍ، عَنْ أنَسٍ، قَالَ: قَالَ رَسُولُ اللهِ - صلى الله عليه وآله وسلم -: «إذا أُقِيْمَتِ الصَّلاَةُ فلاَ تَقُومُوا حَتَّى تَرونِي» (٢)، قالَ إسْحَاقُ بنُ عِيْسَى: فَأَتَيْتُ حَمَّادَ بنَ زَيْدٍ فَسَأَلْتُهُ عَنِ الحديثِ، فقالَ: وَهِمَ أبو النَّضْرِ إنَّمَا كُنَّا جَمِيْعًا في مَجْلِسِ ثابتٍ"],[806,"البُنَانِيِّ (٣)، وحَجَّاجُ بنُ أبي عُثْمَانَ مَعَنَا، فَحَدَّثَنا حَجَّاجٌ الصَّوَّافُ، عَنْ يَحْيَى بنِ أبي كَثِيْرٍ، عَنْ عَبْدِ اللهِ بنِ أبي قَتَادَةَ، عَنْ أبيهِ: أنَّ رَسُولَ اللهِ - صلى الله عليه وآله وسلم -، قالَ: «إذا أُقِيْمَتِ الصَّلاَةُ فلاَ تَقُومُوا حَتَّى تَرونِي» (٤). فَظَنَّ أبو النَّضْرِ أنَّهُ فيما حَدَّثَنا ثابِتٌ، عَنْ أنسٍ (٥)."],[807,"أبو (٦) النَّضْرِ: هُوَ جَرِيْرُ بنُ حازِمٍ (٧)، واللهُ أعلمُ.","",{"fn":"قال ابن حجر في نكته ٢/ ٨٧٤: «لا يختص بهذا المثال، بل كل مقلوب لا يخرج عن كونه معللًا أو شاذًا؛ لأنه إنما يظهر أمره بجمع الطرق واعتبار بعضها ببعض، ومعرفة من يوافق ممن يخالف فصار المقلوب أخص من المعلل والشاذ. والله أعلم».\nرواية جرير عند: الطيالسي (٢٠٢٨)، وعبد بن حميد (١٢٥٩)، والترمذي في علله (١٤٦).\nبضم الموحدة ونونين. تقريب التهذيب (٨١٠).\nالحديث من هذا الطريق، مرفوعًا: عبد الرزاق (١٩٣٢)، والحميدي (٤٢٧)، وابن أبي شيبة ١/ ٤٠٥، أحمد ٥/ ٢٩٦ و٣٠٣ و٣٠٤ و٣٠٥ و٣٠٧ و٣٠٨ و٣٠٩ و٣١٠، وعبد بن حميد (١٨٩)، والدارمي (١٢٦٤) و(١٢٦٥)، والبخاري ١/ ١٦٤ (٦٣٧) و(٦٣٨) و٢/ ٩ (٩٠٩)، ومسلم ٢/ ١٠١ (٦٠٤)، وأبو داود (٥٣٩) و(٥٤٠)، والترمذي (٥٩٢)، والنسائي ٢/ ٣١ و٨١، وابن خزيمة (١٦٤٤)، وابن حبان (٢٢٢٣)، والبيهقي ٢/ ٢٠، والبغوي (٤٤٠).\nانظر: العلل ومعرفة الرجال (١١٧٢)، والمراسيل لأبي داود: ٩٤، والترمذي عقب (٥١٧) وفي العلل الكبير (١٤٦)، والضعفاء الكبير ١/ ١٩٨.\nفي (ب): «وأبو».\nقال السيوطي في شرحه لألفية العراقي: ٢٢٨: «قد يكون القلب في المتن كحديث مسلم ٣/ ٩٣ (١٠٣١) في السبعة الذين يظلهم الله: «وَرَجُلٌ تَصَدَّقَ بصَدَقَةٍ أخْفَاهَا حَتَّى لاَ تعلَمَ يَمِيْنُهُ مَا تُنْفِقُ شِمَالُهُ»، فإنه انقلب على بعض الرواة، وإنما هُوَ: «حَتَّى لاَ تَعْلَمَ شِمَالُهُ مَا تُنْفِقُ يَمِيْنُهُ» ...». قال النووي في شرح صحيح مسلم ٣/ ٧١: «هكذا وقع في جميع نسخ مسلم في بلادنا وغيرها، وكذا نقله القاضي عن جميع روايات نسخ مُسْلِم: «لاَ تعلَمَ يَمِيْنُهُ مَا تُنْفِقُ شِمَالُهُ»، والصحيح المعروف: «حَتَّى لاَ تَعْلَمَ شِمَالُهُ مَا تُنْفِقُ يَمِيْنُهُ». وانظر: نكت الزركشي ٢/ ٣٠٥، ونكت ابن حجر ٢/ ٨٧٤."}],[808,"فصل"],[809,"قَدْ وَفَّيْنَا بِمَا سَبَقَ الوَعْدُ بشَرْحِهِ مِنَ الأنْوَاعِ الضَّعِيْفَةِ (١)، والحمدُ للهِ، فَلْنُنَبِّهَ الآنَ عَلَى أُمُورٍ مُهِمَّةٍ:"],[810,"أحَدُهَا: إذا رأيْتَ حَدِيْثًا بإسْنَادٍ ضَعِيْفٍ، فَلَكَ أنْ تَقُولَ: هَذَا ضَعِيْفٌ، وتَعْنِي أنَّهُ بذَلِكَ الإسْنَادِ ضعِيْفٌ، ولَيْسَ لَكَ أنْ تَقُولَ: هَذَا ضَعيفٌ، وتَعْني بهِ ضَعْفَ مَتْنِ الحديثِ، بناءً عَلَى مُجَرَّدِ ضَعْفِ ذلكَ الإسنَادِ؛ فَقَدْ يَكُونُ مَرْوِيًّا بإسْنَادٍ آخَرَ صَحِيْحٍ يَثْبُتُ بمثْلِهِ الحديثُ، بَلْ يَتَوَقَّفُ جَوَازُ ذَلِكَ عَلَى حُكْمِ إمَامٍ مِنَ أئِمَّةِ الحديثِ بأنَّهُ لَمْ يُرْوَ بإسْنَادٍ يثبْتُ بهِ (٢)، أو بأنَّهُ حديثٌ ضَعِيْفٌ، أو نَحْوِ هَذَا، مُفَسِّرًا وَجْهَ القَدْحِ فيهِ (٣). فإنْ أطْلَقَ وَلَمْ يُفَسِّرْ، فَفِيْهِ كَلاَمٌ يأتِي - إنْ شَاءَ اللهُ تَعَالَى (٤) -، فَاعْلَمْ ذَلِكَ فَإنَّهُ مِمَّا يُغْلَطُ فيهِ، واللهُ أعلمُ."],[811,"الثَّاني: يَجوزُ عِندَ أهلِ الحديثِ وغَيرِهِمُ التَّسَاهُلُ في الأسَانِيْدِ ورِوَايَةُ مَا سِوَى الموضوعِ مِنْ أنواعِ الأحاديثِ الضَّعِيْفَةِ مِنْ غَيْرِ اهْتِمَامٍ بِبَيَانِ ضَعْفِهَا فِيْمَا سِوَى صِفَاتِ اللهِ تَعَالَى وأحْكَامِ الشَّرِيْعَةِ مِنَ الحلاَلِ والحرَامِ وغَيْرِهُما. وَذَلِكَ كَالْمَوَاعِظِ، والقَصَصِ، وفَضَائِلِ الأعْمَالِ، وسَائِرِ فُنُونِ التَّرْغِيبِ والتَّرْهِيْبِ، وسَائِرِ مَا لاَ تَعَلُّقَ لهُ بالأحْكَامِ والعَقَائِدِ (١). ومِمَّنْ رُوِّيْنَا عَنْهُ التَّنْصِيْصُ عَلَى التَّسَاهُلِ في نَحْوِ ذَلِكَ: عَبْدُ الرَّحْمَانِ بنُ مَهْدِيٍّ (٢)، وأَحْمَدُ بنُ حَنْبَلٍ (٣) - رضي الله عنهما (٤) -.","",{"fn":"اعترض عليه بأنه شرح أنواعًا لا تستلزم الضعف كالمتصل والمسند والموقوف وغيرها. وأجاب الحافظ ابن حجر عن هذا الاعتراض بأن المصنف قال: «إنه يشرح أنواع الضعيف وهو قد فعل «ولم يقل: إنه لا يشرح إلا الأنواع الضعيفة حتى يعترض عليه بمثل المسند والمتصل وما أشبه ذلك مما لا يستلزم الضعف» ...». نكت ابن حجر ٢/ ٨٨٧.\nفي (ب): «بمثله».\nقال ابن حجر ٢/ ٨٨٧: «إذا بلغ الحافظ المتأهل الجهد وبذل الوسع في التفتيش على ذلك المتن من مظانه، فلم يجده إلا من تلك الطريق الضعيفة، فما المانع له من الحكم بالضعف بناءً على غلبة ظنه؟ وكذلك إذا وجد كلام إمام من أئمة الحديث قد جزم بأن فلانًا تفرد به، وعرف المتأخر أن فلانًا المذكور قد ضعف بتضعيف قادح، فما الذي يمنعه من الحكم بالضعف؟ والظاهر أن المصنف مشى على أصله في تعذر استقلال المتأخرين بالحكم على الحديث بما يليق به، والحق خلافه كما قدمناه».\nفي النوع الثالث والعشرين: ... ."}],[812,"الثَّالِثُ: إذا أردْتَ رِوَايةَ الحديثِ الضعيفِ بغَيْرِ إسْنادٍ فَلاَ تَقُلْ فيهِ: «قَالَ رسُولُ اللهِ - صلى الله عليه وآله وسلم - كَذا وكَذا»، وما أشْبَهَ هَذا مِنَ الألفَاظِ الجازِمةِ بأنَّهُ - صلى الله عليه وآله وسلم - قَالَ ذَلِكَ (٥)، وإنَّمَا تَقُولُ (٦) فيهِ: «رُوِيَ عَنْ رَسُولِ اللهِ - صلى الله عليه وآله وسلم - كَذَا وكَذَا، أوْ بَلَغَنا عَنْهُ كَذا وكَذا، أوْ وَرَدَ عَنهُ، أوْ جَاءَ عَنهُ، أوْ رَوَى بَعْضُهُمْ»، ومَا أشْبَهَ ذَلِكَ (٧)."],[813,"وهَكَذا الْحُكْمُ فيما تَشُكُّ في صِحَّتِهِ وضَعْفِهِ (٨)، وإنَّمَا تَقُولُ: «قَالَ رَسُولُ اللهِ - صلى الله عليه وآله وسلم -»، فيما ظَهَرَ لَكَ صِحَّتُهُ بطريقِهِ الذي أوْضَحْنَاهُ أوَّلًا (٩)، واللهُ أعلمُ.","",{"fn":"انظر: بحثًا موفقًا لمحقق شرح السيوطي: ٥٣ - ٦٣.\nرواه عنه الحاكم في المدخل إلى الإكليل: ٢٥، والبيهقي في المدخل إلى دلائل النبوة ١/ ٣٤، والخطيب في الجامع ٢/ ٩١ (١٢٦٥).\nرواه الخطيب في الكفاية: (٢١٣ ت، ١٣٤ هـ).\nقال البلقيني في المحاسن: ٢١٧: «زاد الخطيب السفيانين ويحيى بن محمد». وانظر: الكفاية (٢١٢ - ٢١٣ ت، ١٣٤ هـ).\nفي (ب): «كذا».\nفي (ب): «يقول».\nنبّه الزركشي هنا على أمور هي: - أن هذا يشمل الضعيف الذي لا يعمل به وهو الوارد في الأحكام، والضعيف الذي يعمل به وهو الوارد في الفضائل، ومن الناس من يتساهل فيما ورد في الفضائل فيجزم به، والأحوط المنع. - يشمل هذا الحكم الموضوع أيضًا عند عدم العلم بحاله، أما مع العلم فيجب التبيين. - أن قوله: «بغير إسناد» يقتضي أنه إذا روي بالإسناد يقال فيه بالجزم، وهو كذلك إتباعًا لما روي. - خُرِّجَ من هذا أنه لا يجوز رواية الضعيف إلا مع تبيينه، وقد حكاه العلاّمة أبو شامة عن جمع من المحدّثين والمحقّقين وأهل الفقه والأصول. انظر: نكت الزركشي ٢/ ٣٢٢ - ٣٢٤.\nنقل النووي اتفاق محقّقي المحدّثين وغيرهم على هذا، وأنه لا ينبغي الجزم بشيء ضعيف؛ لأنها صيغة تقتضي صحته عن المضاف إليه، فلا ينبغي أن تطلق إلا فيما صحَّ، قال: «وقد أهمل ذلك كثير من المصنفين من الفقهاء وغيرهم، واشتد إنكار البيهقي على من خالف ذلك، وهو تساهل قبيح جدًا من فاعله، إذ يقول في الصحيح: يذكر ويروى، وفي الضعيف: قال وروى، وهذا قلب للمعاني وحَيْدٌ عن الصواب. نقله محقق الإرشاد ١/ ٢٧١.\nقال الزركشي ٢/ ٣٢٤: «سكت المصنف عن عكس ذلك، وهو إذا أردت رواية الحديث الصحيح بغير إسناد فلا يأتي فيه بصيغة التمريض كـ «رُوِيَ» ونحوه، ووقع ذلك في عبارة الفقهاء، وليس يستحسن». قلنا: لم يسكت المصنف، وإنما أشار إليها إشارة واضحة مفهومة من آخر كلامه، مضمومة إلى السياق. والله أعلم."}],[814,"النوع الثالث والعشرون معرفة صفة من تقبل روايته، ومن ترد"],[815,"رِوَايَتُهُ"],[816,"ومَا يَتَعَلَّقُ بِذَلِكَ مِنْ قَدْحٍ وَجَرْحٍ وَتَوْثِيْقٍ وتَعْدِيْلٍ (١)"],[817,"أجْمَعَ جمَاهِيرُ أئِمَّةِ الحديثِ والفِقْهِ علَى أنَّهُ يُشْتَرَطُ فِيْمَنْ يُحْتَجُّ بِرِوَايتِهِ أنْ يَكُونَ عَدْلًا ضَابِطًا لِمَا يَرْوِيهِ."],[818,"وتَفْصِيْلُهُ:"],[819,"- أنْ يَكُونَ مُسْلِمًا."],[820,"- بَالِغًا."],[821,"- عَاقِلًا."],[822,"- سَالِمًا مِنْ أسْبَابِ الفِسْقِ وَخَوَارِمِ المرُوْءةِ (٢)."],[823,"- مُتَيَقِّظًا غَيْرَ مُغَفَّلٍ."],[824,"- حَافِظًا إنْ حَدَّثَ مِنْ حِفْظِهِ."],[825,"- ضَابِطًا لِكِتَابِهِ إنْ حَدَّثَ مِنْ كِتَابِهِ."],[826,"- وإنْ كَانْ يُحَدِّثُ بالمعنَى اشْتُرِطَ فيهِ مَعَ ذَلِكَ أنْ يَكُوْنَ عَالِمًا بِمَا يُحِيْلُ المعَاني واللهُ أعلَمُ. ونُوضِحُ (٣) هذِهِ الجمْلَةَ بمسَائِلَ:","",{"fn":"انظر في صفة مَن تقبل روايته ومَنْ تُرَدُّ: الإرشاد ١/ ٢٧٣ - ٣٣٣، والتقريب: ٩٠ - ١٠٠، والمنهل الروي: ٦٣، والخلاصة: ٨٨، واختصار علوم الحديث: ٩٢، وشرح التبصرة والتذكرة ٢/ ١، ونزهة النظر: ١٨٥ - ١٩٩، والمختصر: ١٥٥، وفتح المغيث ١/ ٢٦٢، وألفية السيوطي: ٩٦ - ١١٢، وشرح السيوطي على ألفية العراقي: ٢٣١، وفتح الباقي ١/ ٢٩٢، وتوضيح الأفكار ٢/ ١١٤، وظفر الأماني: ٧٨.\nانظر: محاسن الاصطلاح: ٣١٨، ونكت الزركشي ٣/ ٣٢٥، والتقييد والإيضاح: ١٣٦.\nفي (ب): «توضح»."}],[827,"إحْدَاهَا (١): عَدَالَةُ الرَّاوي تَارةً تَثْبُتُ بتَنصِيْصِ مُعدِّلَيْنِ عَلَى عَدَالَتِهِ، وتَارَةً تَثْبُتُ بالاسْتِفَاضَةِ (٢)، فَمَنِ اشْتَهَرتْ عَدَالَتُهُ بَيْنَ أهلِ النَّقْلِ أو نَحْوِهِم مِنْ أهلِ العِلْمِ وشَاعَ الثَّنَاء عليهِ بالثِّقَةِ والأمانةِ اسْتُغْنِيَ فيهِ بذلكَ (٣) عَنْ بَيِّنَةٍ شَاهِدَةٍ بعَدَالَتِهِ تَنْصِيْصًا."],[828,"وهَذَا هُوَ الصحيحُ في مَذْهَبِ الشَّافِعِيِّ، وعليهِ الاعتمادُ في فَنِّ أصُوْلِ الفِقْهِ. ومِمَّنْ ذَكَرَ ذَلِكَ مِنْ أهلِ الحديثِ أبو بَكْرٍ الخطيبُ الحافظُ (٤)، ومَثَّلَ ذَلِكَ بمالِكٍ،"],[829,"وشُعبةَ، والسُّفْيانَيْنِ، والأوْزَاعِيِّ، واللَّيْثِ، وابنِ المبارَكِ، ووكِيعٍ، وأحمدَ بنِ حنبلٍ، ويحيى بنِ مَعِينٍ، وعَلِيِّ بنِ المدِيْنِيِّ، ومَنْ جَرَى مَجْرَاهُم في نَبَاهَةِ الذِّكْرِ واستِقَامَةِ الأمرِ، فَلاَ يُسْألُ عَنْ عَدَالَةِ هَؤُلاَءِ وأمْثَالِهِمْ، وإنَّمَا يُسْألُ عَنْ عَدَالَةِ مَنْ خَفِيَ أمرُهُ عَلَى الطَّالِبِيْنَ."],[830,"وتَوَسَّعَ ابنُ عَبْدِ البرِّ الحافِظُ في هذا فقالَ (٥): «كُلُّ حَامِلِ عِلْمٍ مَعْرُوفِ العِنايةِ بهِ، فَهوَ عَدْلٌ مَحْمُولٌ في أمْرِهِ أبَدًا عَلَى العَدَالَةِ حَتَّى يَتَبَيَّنَ جَرْحُهُ، لِقَولِهِ - صلى الله عليه وآله وسلم -: «يَحْمِلُ هذا العِلْمَ مِنْ كُلِّ خَلَفٍ عُدُوْلُهُ» (٦)، وفيما قَالَهُ اتِّسَاعٌ غَيْرُ مَرْضِيٍّ (١)، واللهُ أعلمُ.","",{"fn":"في (ب) و(جـ): «أحدها».\nانظر: نكت الزركشي ٣/ ٣٢٧.\nفي (جـ): «لذلك».\nالكفاية: (١٤٧ ت، ٨٦ - ٨٧ هـ).\nينظر: التمهيد ١/ ٢٨، وجامع بيان العلم وفضله ٢/ ١٩٩.\nهذا الحديث مروي عن عدة من الصحابة - رضي الله عنهم - مرفوعًا، ومع ذلك فهو حديث ضعيف، وإليك البيان: الأول: وهو أشهرها، روي من حديث إبراهيم بن عبد الرحمان العذري، ورواه عنه: ١ - الوليد بن مسلم، عنه، عن الثقة من أشياخه، عن النبي - صلى الله عليه وآله وسلم -. أخرجه البيهقي في الكبرى ١٠/ ٢٠٩، وابن عدي ١/ ٢٤٩، وابن عساكر ٧/ ٣٨، من طريقين صرّح الوليد في أحدهما بالتحديث، وكذا شيخه، وهذا الطريق معلٌّ بأمرين: أولًا: جهالة العذري. ثانيًا: إبهام شيخه. ولعل قائلًا يقول: شيخه يروي عن رسول الله - صلى الله عليه وآله وسلم -، فلعله يكون صحابيًا، فالجهالة لا تضرّ بحاله؟ =\nووافقه عليه ابن الموّاق في كتابه \" بغية النقاد \". وقال المزي: «ما قاله ابن عبد البر هو في زماننا مرضي بل ربما يتعين». وقال ابن سيد الناس: «لست أرى ما قاله أبو عمر إلا مرضيًا». وقال ابن الجزري: «إنه الصواب». وقال الذهبي: «إنه الحق». ينظر: نكت الزركشي ٢/ ٣٣٠، والتقييد والإيضاح: ١٣٩، وفتح المغيث ١/ ٢٧٨. على أن ابن الوزير أفاض في تأييد ابن عبد البر في بحث طويل نفيس في كتابه \" الروض الباسم \": ٢١ - ٢٦، واقتبس الصنعاني جزءًا منه ضمنه كتابه توضيح الأفكار ٢/ ١٢٦ - ١٣٣."}],[831,"الثَّانِيَةُ: يُعْرَفُ كَوْنُ الرَّاوِي ضَابِطًا، بأنْ نَعْتَبرَ (١) رِوَاياتِهِ بروَاياتِ الثِّقَاتِ المعْرُوفِيْنَ بالضبْطِ والإتْقانِ، فَإنْ وَجَدْنا رِوَاياتِهِ موافقةً وَلَوْ مِنْ حَيْثُ المعْنَى لِرِوَاياتِهِم أو موافِقَةً لَهَا في الأغْلَبِ والمخالَفَةُ نَادِرَةٌ عَرَفْنا حِيْنَئِذٍ كَوْنَهُ ضَابِطًا ثَبْتًا، وإنْ وَجدْناهُ كثيرَ المخالَفةِ لهم عَرَفْنا اختِلاَلَ ضَبْطِهِ ولَمْ نَحْتَجَّ (٢) بحديثِهِ (٣)، واللهُ أعلمُ."],[832,"الثَّالِثَةُ: التعديلُ مقبولٌ مِنْ غيرِ ذِكْرِ سَبَبِهِ على المذهبِ الصحيحِ المشهورِ (٤)؛ لأنَّ أسْبَابَهُ كَثيرةٌ يَصْعُبُ ذِكْرُها، فَإنَّ ذَلِكَ يُحْوِجُ المعدِّلَ إلى أنْ يقولَ: لَمْ يَفْعَلْ كذا، ولَمْ يَرتكِبْ كَذا، فَعَلَ كَذا وكَذا فيُعَدِّدُ جميعَ ما يفسقُ بفِعلِهِ أو بتَرْكِهِ وذَلِكَ شَاقٌّ جِدًّا (٥)."],[833,"وأمَّا (٦) الْجَرْحُ فَإنَّهُ لاَ يُقْبَلُ إلاَّ مُفَسَّرًا مبَيَّنَ السَّبَبِ (٧)؛ لأنَّ الناسَ يَختَلِفُونَ فيما يَجْرَحُ وما لاَ يَجْرَحُ، فيَطلقُ أحدُهُمُ الْجَرْحَ بناءً على أمرٍ اعتَقَدَهُ جَرْحًا ولَيْسَ بجرْحٍ في نفسِ الأمرِ؛ فلاَ بُدَّ مِنْ بِيَانِ سَبِبِهِ لِيُنْظَرَ فيهِ: أهُوَ جَرْحٌ أمْ لاَ؟ وهذا ظاهرٌ مقرّرٌ في الفِقْهِ وأصُولِهِ (٨).","",{"fn":"في (أ) و(ب) و(م): «تعتبر»، وفي (جـ): «يعتبر».\nفي (أ) و(ب): «يحتج».\nانظر فيما يتعلق بالضبط: جامع الأصول ١/ ٧٢ - ٧٤، ونكت الزركشي ٢/ ٣٣٦.\nوهو الذي صَوَّبَه الخطيب البغدادي، واختاره أبو إسحاق الشيرازي، وصحّحه الزركشي، وقال: «هو المنصوص للشافعي»، وقال القرطبي: هو الأكثر من قول مالك. انظر: الكفاية: (١٦٥ ت، ٩٩ هـ)، واللمع: ٤٦، والبحر المحيط ٤/ ٢٩٣ - ٢٩٤.\nو«لأن المزكّي إن كان بصيرًا قُبِلَ جرحه وتعديله وإلاّ فلا، وهو قول القاضي أبي بكر، وقال إمام الحرمين: «إن كان المزكّي عالمًا بأسباب الجرح والتعديل اكتفينا بإطلاقه وإلا فلا»، والمختار ما قاله الغزالي: إنه ينظر في مذاهب الجارحين والمزكّين، فإن كانت مختلفة توقفنا عن قبول الجرح حتى يتبين وجهه، وما كان مطلقًا أو غير مقيد فلا يجرح به، ومما ينبغي في الجارح والمعدِّل: أن يكون عالمًا باختلاف المذاهب في ذلك». قاله الزركشي ٣/ ٣٣٨.\nفي (أ): «أما»، الواو ساقطة.\nقال العراقي في التقييد١٤٠: «وقد حكى القاضي أبو بكر عن الجمهور قبول جرح أهل العلم بهذا الشأن من غير بَيَان، واختاره إمام الحرمين، وأبو بكر الْخَطِيْب، والغزالي، وابن الخطيب».\nقال البلقيني في المحاسن: ٢٢١: «وذهب قوم إلى أنه لا يشترط ذلك، كما مرّ مثله في التعديل على المشهور. وأغْرَبَ مَنْ قَال: يكفي الإطلاق في الجرح دون التعديل. وقيل: إن كان عالمًا بالأسباب كفى الإطلاق فيهما، وإلا لم يكف واحد منهما. وتقرير الأدلة في فن الأصول»."}],[834,"وذَكَرَ الخطيبُ الحافِظُ (١): أنَّهُ مَذْهَبُ الأئِمَّةِ مِنْ حُفَّاظِ الحديْثِ ونُقَّادِهِ، مِثْلَ البخارِيِّ، ومُسْلِمٍ، وغَيْرِهِما؛ ولذلكَ احْتَجَّ البخاريُّ بجماعَةٍ سَبَقَ مِنْ غَيْرِهِ الجرحُ"],[835,"لَهُمْ (٢)، كَعِكْرِمَةَ مَوْلَى ابنِ عَبَّاسٍ - رضي الله عنهما -، وكَإسْمَاعِيْلَ بنِ أبي أُوَيْسٍ، وعَاصِمِ بنِ علِيٍّ، وعَمْرِو بنِ مَرْزُوقٍ، وغَيْرِهِمْ."],[836,"واحْتَجَّ مُسْلِمٌ بسُوَيْدِ بنِ سعيدٍ وجماعةٍ اشْتَهَرَ الطَّعْنُ فيهمْ، وهَكَذا فَعَلَ أبو دَاوُدَ السِّجِسْتَانِيُّ؛ وذَلِكَ دَالٌّ عَلَى أنَّهُمْ ذَهَبُوا إلى أنَّ الجرحَ لاَ يَثْبُتُ إلاَّ إذَا فُسِّرَ سَبَبُهُ. ومَذَاهِبُ النُّقَّادِ للرِّجَالِ غَامِضَةٌ مُخْتَلِفَةٌ (٣)."],[837,"وَعَقَدَ الخطيبُ (٤) بابًا في بَعْضِ أخْبَارِ مَنِ اسْتُفْسِرَ في جَرْحِهِ فَذَكَرَ ما لاَ يصلحُ جارِحًا، منها: عَنْ شُعْبَةَ أنَّهُ قِيْلَ لهُ: «لِمَ تَركْتَ حَدِيْثَ فُلاَنٍ؟»، فقَالَ: «رأيْتُهُ يَرْكُضُ عَلَى بِرْذَونٍ (٥)، فَتَرَكْتُ حَدِيْثَهُ» (٦). ومِنْها عَنْ مُسْلِمِ بنِ إبراهيمَ أنَّهُ سُئِلَ عَنْ حَدِيْثٍ لِصَالِحِ الْمُرِّيِّ (٧)، فَقَالَ: مَا يُصْنَعُ (٨) بصَالِحٍ؟ ذَكروهُ يومًا عِنْدَ حَمَّادِ بنِ سَلَمَةَ فامتَخَطَ حَمَّادٌ (٩)، واللهُ أعلمُ.","",{"fn":"الكفاية: (١٧٨ - ١٧٩ت، ١٠٨هـ). وانظر: البرهان ١/ ٥٦٠، والبحر المحيط ٤/ ٢٩٤.\nانظر: نكت الزركشي ٣/ ٣٣٨ وما بعدها.\nانظر: الكفاية: (١٧٩ - ١٨٠ ت، ١٠٨ - ١٠٩ هـ).\nالكفاية: (١٨١ - ١٨٧ ت، ١١٠ - ١١٤ هـ).\nيطلق على غير العربي من الخيل والبغال، ويعرف باسم: «الكديش». انظر: معجم متن اللغة ١/ ٢٦٩، والمعجم الوسيط ١/ ٤٨.\nرواه الخطيب في الكفاية: (١٨٢ ت، ١١٠ - ١١١ هـ).\nبضم الميم وتشديد الراء. تقريب التهذيب (٢٨٤٥).\nفي (أ) وتدريب الراوي ١/ ٣٠٦: «تصنع»، وكذا في نشرتي الكفاية: (١٨٥ ت، ١١٣ هـ)، وفي فتح المغيث ١/ ٣٣٢: «نصنع». ووردت في بعض النسخ الخطية حاشية للمصنف، وأوردها الزركشي في نكته ٣/ ٣٥٣ قائلًا: «ضبطه المصنف بضم الياء المثناة من تحت وفتح النون، وقال: هكذا في أصل موثوق به، فيه سماع الخطيب».\nالكفاية: (١٨٥ ت، ١١٣ هـ)."}],[838,"قُلْتُ: ولِقَائلٍ أنْ يَقُولَ: إنَّمَا يَعتمِدُ النَّاسُ في جَرْحِ الرواةِ ورَدِّ حَدِيْثِهِمْ، عَلَى الكُتُبِ التي صَنَّفَها أئِمَّةُ الحديثِ في الجرْحِ، أو في الجرْحِ والتَّعْدِيْلِ، وقَلَّمَا يَتَعَرَّضُونَ فيها لِبَيَانِ السَّبَبِ، بَلْ يَقْتَصِرُونَ عَلَى مُجَرَّدِ قَوْلِهِمْ: فُلاَنٌ ضَعِيْفٌ، وفُلاَنٌ لَيْسَ بِشَيءٍ، ونَحْوُ ذلكَ، أو هذا حديثٌ ضَعيفٌ، وهذا حديثٌ غيرُ ثابتٍ، ونَحْوُ ذلكَ؛ فاشتِرَاطُ بَيَانِ السبَبِ يُفْضِي إلى تَعْطِيْلِ ذَلِكَ، وسَدِّ بابِ الجَرْحِ في الأغْلَبِ الأكْثَرِ."],[839,"وَجَوابُهُ: أنَّ ذلكَ وإنْ لَمْ نَعْتَمِدْهُ (١) في إثباتِ الجرحِ والحكمِ بهِ، فَقَدْ اعْتَمَدْنَاهُ في أنْ توقَّفْنا عَنْ قَبُولِ حديثِ مَنْ قَالُوا فيهِ مِثْلَ ذَلِكَ، بِنَاءً عَلَى أنَّ ذَلِكَ أوقَعَ عِندنا فيهِم رِيْبَةً قويَّةً يُوْجِبُ مِثْلُها التَّوقُّفَ."],[840,"ثُمَّ مَنِ انْزَاحَتْ عنهُ الرِّيْبَةُ منهُمْ، بِبَحْثٍ عَنْ حَالِهِ أوْجَبَ الثِّقَةَ بِعَدَالَتِهِ، قَبِلْنا حَدِيْثَهُ ولَمْ نَتَوَقَّفْ (٢)، كالذينَ احْتَجَّ بِهِمْ صَاحِبَا \" الصَّحِيْحَيْنِ \" وغَيْرِهِما مِمَّنْ مَسَّهُمْ مثلُ هذا الجرحِ مِنْ غَيْرِهِمْ، فافْهَمْ ذَلِكَ فإنَّهُ مَخْلَصٌ حَسَنٌ (٣)، واللهُ أعلمُ.","",{"fn":"في (ب): «يعتمد»، وفي (جـ): «يعتمده».\nفي (ب): «يتوقف».\nقال البلقيني: ٢٢٢: «هذا الملخص فيه نظر». وقال الزركشي في نكته ٣/ ٣٥٤: «ما ذكره في الجواب من الملخص تبعه عليه النووي في شرح مسلم، وقال: «إن الجرح وإن لم يثبت بذلك، لكنه يوجب التوقف»، وفيه نظر؛ لأن الريبة لا توجب التوقف، ولهذا لَوْ ارتاب الْقَاضِي في الشهود فإنه يجوز لَهُ الحكم مَعَ قيام الريبة. ثُمَّ يرده مَا ذكره أولًا من إعراض البخاري عن أقوال الجارحين حيث لم يفسروا، فيقال: إذا لم يفسروا فهلا توقف كما قلتم هاهنا، وإنما الجواب أن كلام الأئمة المنتصبين لهذا الشأن المدونين فيه، أهل الإنصاف والديانة والنصح إنما يطلقون هذه الألفاظ بعد ثبوت أسبابها». وقال العراقي في التقييد: ١٤١ - ١٤٢: «إن الجمهور إنما يوجبون البيان في جرح من ليس عالمًا بأسباب الجرح والتعديل، وأما العالم بأسبابهما فيقبلون جرحه من غير تفسير». ثم قال: «وقال أبو بكر الخطيب في الكفاية بعد حكاية الخلاف: على أنا نقول أيضًا: إن كان الذي يرجع إليه في الجرح عدلًا مرضيًا في اعتقاده وأفعاله، عارفًا بصفة العدالة والجرح وأسبابهما، عالمًا باختلاف الفقهاء في ذلك قُبِلَ قوله فيمن جرحه مجملًا ولا يسأل عن سببه». وهذا ما ذهب إليه جمع من الأصوليين منهم: إمام الحرمين في البرهان ١/ ٤٠٠، فقال: «والذي أختاره أن الأمر في ذلك يختلف بالمعدِّل والجارح، فإن كان المعدِّل إمامًا موثوقًا به في الصناعة لا يليق بِهِ ="}],[841,"الرَّابِعَةُ: اخْتَلَفُوا في أنَّهُ: هَلْ يَثْبُتُ الجرحُ والتَّعْدِيْلُ بقَوْلِ واحِدٍ، أو لاَ بُدَّ مِنِ اثنينِ؟."],[842,"فَمِنْهُمْ مَنْ قَالَ: لاَ يَثبتُ ذَلِكَ إلاَّ باثْنَيْنِ كَما في الجرْحِ والتَّعْدِيْلِ في الشَّهَاداتِ، ومِنْهُمْ مَنْ قَالَ - وهوَ الصحيحُ الذي اخْتَارَهُ الحافِظُ أبو بَكْرٍ الخطيبُ (١) وغيرُهُ - أنَّهُ يَثْبُتُ بواحِدٍ؛ لأنَّ العدَدَ لَمْ يُشْتَرَطْ في قَبُولِ الخبَرِ، فَلَمْ يُشْتَرَطْ في جَرْحِ راويهِ وتعديْلِهِ بخِلاَفِ الشَّهاداتِ (٢)، واللهُ أعلمُ.","",{"fn":"الكفاية: (١٦٠ - ١٦١ ت، ٩٦ هـ).\nقال الحافظ العراقي في التقييد: ١٤٢ - ١٤٣: «فيه أمران: أحدهما: أنه حُكِيَ عن الأكثرين خلاف ما صحّحه المصنف، واختلف كلام الناقلين لذلك عنهم، فحكى الخطيب في الكفاية أن القاضي أبا بكر بن الباقلاني حكى عن أكثر الفقهاء من أهل المدينة ="}],[843,"الخامِسَةُ: إذا اجْتَمعَ في شَخْصٍ جَرْحٌ وتَعْديلٌ، فالجرْحُ مُقَدَّمٌ؛ لأنَّ المعَدِّلَ يُخْبِرُ عَمَّا ظَهَرَ مِنْ حالِهِ، والجارِحُ يُخْبِرُ عَنْ باطِنٍ خَفِيَ عَلَى المعَدِّلِ (١)، فإنْ كَانَ عَدَدُ المعدِّلِيْنَ أكْثَرَ فقَدْ قِيْلَ: التَّعْدِيْلُ أوْلَى (٢). والصحيحُ والذي عليهِ الجمْهُورُ: أنَّ الجرْحَ أوْلَى، لِمَا ذَكَرْنَاهُ (٣)، واللهُ أعلمُ."],[844,"السادِسَةُ: لاَ يُجْزِئُ التَّعْديلُ عَلَى الإبْهَامِ مِنْ غَيْرِ تَسْمِيَةِ المعَدَّلِ، فإذا قَالَ: حَدَّثَنِي الثِّقَةُ أوْ نَحْوُ ذلكَ مُقْتَصِرًا عليهِ لَمْ يُكْتَفَ بهِ فيما ذَكَرَهُ الخطيبُ الحافِظُ (٤)، والصَّيْرَفِيُّ الفَقِيْهُ وغيرُهُما (٥)، خِلافًا لِمَنِ اكْتَفَى بذلِكَ؛ وذَلِكَ لأنَّهُ قدْ يكونُ ثقةً عِنْدَهُ، وغيرُهُ قَدِ اطَّلَعَ عَلَى جَرْحِهِ بما هُوَ جارِحٌ عِنْدَهُ، أو بالإجْمَاعِ، فيُحْتَاجُ إلى أنْ يُسَمِّيَهُ حَتَّى يُعْرَفَ، بَلْ إضْرَابُهُ عَنْ تَسْمِيَتِهِ مُرِيْبٌ يُوقِعُ في القلوبِ فيهِ تَرَدُّدًا؛ فإنْ كَانَ القائِلُ لذَلِكَ عَالِمًا أجْزَأَ ذَلِكَ في حَقِّ مَنْ يُوَافقُهُ في مَذْهبِهِ، عَلَى ما اخْتارَهُ بَعضُ المحقِّقِينَ (١).","",{"fn":"هذا الذي اختاره وصحّحه، صحّحه الرازي والآمدي، وبه جزم الماوردي والروياني وابن القشيري، ونقل القاضي الإجماع عليه، وحكاه الخطيب والباجي عن الجمهور، ونسبه النووي إلى المحقّقين والجماهير. انظر: الكفاية: (١٧٧ت، ١٠٧ هـ)، والمحصول ٢/ ٢٠١، وشرح صحيح مسلم ١/ ٢٣١، وشرح التبصرة والتذكرة ٢/ ٢٨، وإحكام الأحكام ٢/ ٧٩، والبحر المحيط ٤/ ٢٩٧.\nوهذا المذهب خطّأه الخطيب في الكفاية: (١٧٧ ت، ١٠٧ هـ). وانظر: نكت الزركشي ٣/ ٣٦١.\n«وقيل: يرجح بالأحفظ. ثم تقديم الجارح مشروط عند الفقهاء بأن يطلق المعدِّل، فإن قال المعدّل: «عرفت السبب الذي ذكره الجارح، لكنه تاب وحسنت حالته» فإنه يقدم المعدّل. ومحل هذا في الرواية في غير الكذب على النبي - صلى الله عليه وآله وسلم - فإنه لا تقبل روايته وإن تاب». هكذا قال البلقيني: ٢٢٤.\nالكفاية: (٥٣١ ت، ٣٧٣ - ٣٧٤ هـ).\nكابن الصبّاغ والقفال الشاشي والروياني والماوردي وأبي الطيب الطبري وأبي إسحاق الشيرازي. نقله عنهم الزركشي في البحر المحيط ٤/ ٢٩١."}],[845,"وذَكَرَ الخطيبُ الحافِظُ (٢) أنَّ العَالِمَ إذا قالَ: «كُلُّ مَنْ رَوَيْتُ عنهُ فهوَ ثِقَةٌ وإنْ لَمْ أُسَمِّهِ»، ثُمَّ رَوَى عَمَّنْ لَمْ يُسَمِّهِ (٣)، فَإنَّهُ يَكُونُ مُزَكِّيًا لهُ، غيرَ أنَّا لاَ نَعْملُ بتَزْكِيَتِهِ هذهِ، وهذا عَلَى مَا قَدَّمناهُ، واللهُ أعلمُ."],[846,"السابِعَةُ: إذا رَوَى العَدْلُ عَنْ رَجُلٍ وسَمَّاهُ، لَمْ تُجْعَلْ (٤) رِوايتُهُ عَنهُ تَعْدِيلًا منهُ لهُ عِندَ أكثَرِ العلمَاءِ مِنْ أهلِ الحديثِ وغيرِهِمْ (٥)."],[847,"وقالَ بَعضُ أهلِ الحديثِ، وبعضُ أصحابِ الشَّافِعِيِّ: يُجْعَلُ (٦) ذَلِكَ تَعْدِيْلًا منهُ"],[848,"لهُ؛ لأنَّ ذَلِكَ يَتَضَمَّنُ التَّعديلَ (٧)."],[849,"والصحيحُ هوُ الأوَّلُ؛ لأنَّهُ يَجُوزُ أنْ يَرْوِيَ عَنْ غَيْرِ عَدْلٍ، فَلَمْ يَتَضَمَّنْ روايتُهُ عنهُ تعديلَهُ. وهَكَذَا نقولُ: إنَّ عَمَلَ العَالِمِ أوْ فُتْيَاهُ عَلَى وَفْقِ حديثٍ، ليسَ حُكْمًا منهُ بصِحَّةِ ذلكَ الحديثِ (٨).","",{"fn":"قال محقق شرح السيوطي: ٢٤٣: «هكذا أبهمه ابن الصلاح. قال السخاوي: «ولعله إمام الحرمين». (فتح المغيث ١/ ٢٨٩)، قلت: بل أغلب الظن أنه ابن الصبّاغ لما سيأتي من النقل عنه، وهو أقدم وفاة من إمام الحرمين».\nالكفاية: (١٥٥ ت، ٩٢ هـ).\nفي (جـ): «يسمِّ».\nفي (ع) والتقييد: «يجعل».\nوبه جزم الماوردي والروياني وأبو الحسن بن القطان، ونقله القاضي في التقريب عن الجمهور، وقال: «إنه الصحيح». انظر: البحر المحيط ٤/ ٢٩٠، ونكت الزركشي ٣/ ٣٦٧.\nفي (أ): «نجعل».\nوهذا مذهب الحنفية وإحدى الروايتين عن أحمد، وفي النقل عن الشافعي خلاف، ونسبه الشيرازي إلى بعض أصحاب الشافعي، وهو اختيار الآمدي، ونقله الأسنوي عن ابن الحاجب. انظر الكفاية: (١٥٠ ت، ٨٩ هـ)، واللمع: ٤٧، والتبصرة في أصول الفقه: ٣٣٩، وإحكام الأحكام ٢/ ٨٠، ونهاية السول ٣/ ٤٨، ودراسات في الجرح والتعديل: ٢٠٩.\nتعقبه الحافظ ابن كثير، فقال: «وفي هذا نظر، إذ لم يكن في الباب غير ذلك الحديث، أو تعرّض للاحتجاج به في فتياه أو حكمه، أو استشهد به عند العمل بمقتضاه». اختصار علوم الحديث ١/ ٢٩١، مع شرح أحمد شاكر وحاشية الشيخ ناصر. ="}],[850,"وكذَلِكَ مُخالَفَتُهُ للحديثِ ليسَتْ قَدْحًا منهُ في صِحَّتِهِ ولاَ في راويهِ، واللهُ أعلمُ."],[851,"الثَّامِنَةُ: في روايةِ المجهُولِ، وهوَ في غَرَضِنا هَاهنا أقسَامٌ:"],[852,"أحدُها: المجهُولُ العدالةِ مِنْ حيثُ الظَّاهِرُ والباطِنُ جميعًا، وروايتُهُ غيرُ مَقْبُولةٍ عِندَ الجماهِيْرِ عَلَى مَا نَبَّهْنا عليهِ أوَّلًا (١)."],[853,"الثَّاني: المجْهُولُ الذي جُهِلَتْ عَدَالَتُهُ البَاطِنَةُ، وهوَ عَدْلٌ في الظَّاهِرِ وهوَ المسْتُورُ، فَقَدْ قَالَ بَعْضُ أئِمَّتِنا (٢): المستُورُ مَنْ يَكونُ عَدْلًا في الظاهِرِ، ولاَ تُعْرَفُ عدَالَةُ باطِنِهِ. فهذا المجهُولُ يَحْتَجُّ بروايتِهِ بعضُ مَنْ رَدَّ روايةَ الأوَّلِ، وهوَ قَولُ بعضِ الشَّافِعِيَّيْنَ، وبهِ قَطَعَ منهُمُ الإمامُ سُلَيْمُ بنُ أيُّوبَ الرَّازيُّ، قالَ: «لأنَّ أمرَ الأخبارِ مَبْنِيٌّ عَلَى حُسْنِ الظَّنِّ بالرَّاوي؛ ولأنَّ روايةَ الأخبارِ تَكُونُ عندَ مَنْ يَتَعَذَّرُ عليهِ معرفَةُ العَدَالَةِ في الباطِنِ، فاقتُصِرَ فيها (١) علَى مَعرِفَةِ ذلكَ في الظَّاهِرِ، وتُفَارِقُ الشَّهَادَةَ، فإنَّها تكُونُ عِنْدَ الحكَّامِ، ولاَ يَتَعَذَّرُ عليْهِمْ ذَلِكَ، فاعْتُبِرَ (٢) فيها العدَالَةُ في الظَّاهِرِ والباطِنِ».","",{"fn":"«لأن مجرد الرواية عنه لا تكون تعديلًا». أفاده البقاعي. النكت الوفية: ٢١٥ / أ. وقال البلقيني: ٢٢٥: «أبو حنيفة يقبل مثل هذا». وقال الزركشي ٣/ ٣٧٤: «وظاهره حكاية خلاف فيه، وبه صرّح الخبازي من الحنفية، وإنما قَبِلَ أبو حنيفة ذلك في عصر التابعين لغلبة العدالة عليهم». ونسبه ابن الموّاق إلى أكثر أهل الحديث كالبزّار والدارقطني، وقال الدارقطني: من روى عنه ثقتان فقد ارتفعت جهالته وثبتت عدالته. انظر: فتح المغيث ١/ ٣٥١. وزاد ابن الملقن في المقنع ١/ ٢٥٦ أن قال: «إن كان الراوي عنه لا يروي إلا عن عدلٍ قُبِلَ، وإلاّ فلا». وانظر: شرح التبصرة والتذكرة ٢/ ٤٢ - ٤٣.\nقال الزركشي في نكته ٣/ ٣٧٤: «وهذا الذي أبهم الظاهر أنه إمام الحرمين، فإنه فسّر المستور بأنه الذي لم يظهر منه نقيض العدالة، ولم يتفق البحث في الباطن عن عدالته». وانظر: البرهان ١/ ٣٩٦. لكن الحافظ العراقي جزم بأنه البغوي، فقال: «هو أبو محمد اليغوي صاحب التهذيب، فهذا لفظه بحروفه». التقييد والإيضاح: ١٤٥، وشرح التبصرة والتذكرة ٢/ ٤٤، وانظر قول البغوي في: التهذيب في فقه الشافعي له ٥/ ٢٦٣."}],[854,"قُلْتُ: ويُشْبِهُ أنْ يكونَ العمَلُ على هذا الرأيِ في كثيرٍ مِنْ كُتُبِ الحديثِ"],[855,"المشهُورَةِ، في غيرِ واحِدٍ مِنَ الروَاةِ الذينَ تَقَادَمَ العهْدُ بهِمْ وتَعَذَّرَتْ الخِبْرَةُ الباطِنَةُ بهِمْ (٣)، واللهُ أعلمُ."],[856,"الثَّالِثُ: المجهُولُ العَيْنِ، وقَدْ يَقْبَلُ روايةَ المجهُولِ العدالةِ مَنْ لاَ يَقْبَلُ روايَةَ المجهُولِ العيْنِ (٤)."],[857,"وَمَنْ رَوَى عنهُ عَدْلاَنِ وعَيَّناهُ، فقدِ ارتَفَعَتْ عنهُ هذهِ الجهَالَةُ (٥).","",{"fn":"في (م): «منها».\nفي (ب): «فاعتبروا».\nانظر: نكت الزركشي ٣/ ٣٧٤، وشرح التبصرة والتذكرة ٢/ ٤٣ - ٤٥. وقال البقاعي في النكت الوفية: ٢١٥ / ب: «لم يبيّن وجه الشبه، وليس ببيّن، ولعلّه بناءً على مثل قوله: «إن البخاري ومسلمًا رويا عن مجهول العين مصيرًا منهما إلى أن الجهالة ترتفع برواية واحد». والبيّن في كلام أهل الفن أنهم لا يحتجون إلا بمصرَّح بتوثيقه، ولا فرق بين القديم والحديث، وما ذكره الشيخ بعده من كلام الشافعي بيّن في ذلك».\nانظر نكت الزركشي ٣/ ٣٧٩.\nومن ثم اختلف العلماء في الاحتجاج برواية مجهول العين، وهو من لم يروِ عنه إلا واحد، على خمسة مذاهب: الأول: لا تقبل روايته، وهو الصحيح الذي عليه أكثر أهل الحديث وغيرهم. الثاني: يقبل مطلقًا. وهو قول من لم يشترط في الراوي مزيدًا على الإسلام، ونقله أبو إسحاق الشيرازي في اللمع: ٤٦، والبلقيني في المحاسن: ٢٢٥ عن أبي حنيفة وأصحابه. وقد أفاض النسفي في كشف الأسرار ٢/ ٣٠ في التعليل لهذا المذهب. ولكن من يدقق النظر في كتب أصول الحنفية يجد أن مذهبهم تقييد ذلك بالقرون الثلاثة الأولى الفاضلة، وعليه فإن نسبة إطلاق القبول إليهم خطأ محض. الثالث: إن كان المنفرد بالرواية عنه لا يروي إلا عن عدل، واكتفينا في التعديل بواحد قُبِلَ وإلاّ فلا. الرابع: إن كان مشهورًا بغير العلم كالزهد والشجاعة قُبِل وإلا فلا. الخامس: إن زكّاه أحد أئمة الجرح والتعديل مع رواية ذلك المنفرد عنه قُبِل وإلا فلا. انظر في تفصيلات هذه المذاهب ونسبتها إلى القائلين بها: شرح التبصرة والتذكرة ٢/ ٣٨ - ٣٩."}],[858,"ذَكَرَ (١) أبو بكرٍ الخطيبُ البغداديُّ في أجوِبَةِ مسائِلَ سُئِلَ عَنها (٢) أنَّ (٣) المجهُولَ عندَ أصحابِ الحديثِ هوَ كُلُّ مَنْ لَمْ يَعْرِفْهُ (٤) العلماءُ، ومَنْ لَمْ يُعْرَفْ حَدِيثُهُ إلاَّ مِنْ جِهَةِ رَاوٍ واحدٍ، مِثْلُ: عَمْرِو ذِي مُرٍّ (٥)، وجَبَّارٍ الطَّائيِّ، وسعيدِ بنِ ذِي حُدَّانَ (٦)، لَمْ يَروِ عنهُمْ غَيرُ أبي إسْحَاقَ السَّبِيْعِيِّ (٧)، ومِثْلُ: الْهَزْهَازِ بنِ مَيْزَنٍ (٨) لاَ رَاوِيَ عنهُ غيرُ الشَّعْبيِّ، ومِثْلُ: جُرَيِّ (٩) بنِ كُلَيْبٍ، لَمْ يَرْوِ عنهُ إلاَّ قَتَادَةُ.","",{"fn":"في (ب) ونكت الزركشي: «وذكر».\nقال العراقي في التقييد: ١٤٧: «إن المصنف عزا ما ذكره عن الخطيب إلى أجوبة سُئِلَ عنها، والخطيب ذكر ذلك بجملته مع زيادة فيه في كتاب \" الكفاية \"، والمصنف كثير النقل منه فأبعد النجعة في عزوه ذلك إلى مسائل سئل عنها». قلنا: انظر: الكفاية: (١٤٩ - ١٥٠ ت، ٨٨ - ٨٩ هـ).\nليست في (أ).\nفي (ع) والتقييد: «تعرفه».\nفي (ب): «عمرو بن مُرّ»، وفي التاريخ الكبير ٦/ ٣٢٩، والطبقات لمسلم (١٣٧١): «عمرو بن ذي مُرّ»، وما أثبتناه موافق لما في مصادر ترجمته. انظر: تهذيب الكمال ٥/ ٤٧٧، وفروعه. وكلا الاسمين وردا في الميزان ٣/ ٢٦٠ و٢٩٤. قال البقاعي في النكت الوفية: ٢٠٩ / أ: «ذو مر: كأنه لقب له، وهو «ذو» الذي بمعنى: صاحب، ومُرّ: بضم الميم وتشديد الراء». وانظر: الوحدان لمسلم (١٣)، والكامل ٦/ ٢٤٤، وقال في التقريب (٥١٤٢): «مجهول».\nبضم الحاء المهملة، وتشديد الدال المهملة. انظر: الإكمال ٢/ ٦١، وتبصير المنتبه ١/ ٤١٦، وتاج العروس ٨/ ١٣،. وقال في التقريب (٢٣٠٠): «مجهول».\nقال ابن المديني: «لم يروِ عن هبيرة بن يريم، وهانئ بن هانئ إلا أبو إسحاق، وقد روى عن سبعين أو ثمانين لَمْ يروِ عنهم غيره». تهذيب الكمال ٥/ ٤٣٣. وقال الجوزجاني: «أما أبو إسحاق فروى عن قوم لا يعرفون، ولم ينتشر عنهم عند أهل العلم إلا ما حكى أبو إسحاق عنهم». أحوال الرجال (١٠٥). وقال أبو داود: «حدَّثَ أبو إسحاق عن مئة شيخ لا يحدّث عنهم غيره». سؤالات الآجري له ٣/ ١٧٥.\nقال العراقي في التقييد: ١٤٦: «إن الخطيب سمَّى والد هزهاز: ميزن - بالياء المثناة - وتبعه المصنف، والذي ذكره ابن أبي حاتم في كتاب \" الجرح والتعديل \": أنه مازن - بالألف - وفي بعض النسخ - بالياء -، ولعل بعضهم أماله في اللفظ فكتب بالياء، والله أعلم». وانظر: الجرح والتعديل ٩/ ١٢٢، ونكت الزركشي ٣/ ٣٩٠، وشرح التبصرة والتذكرة ٢/ ٣٩، والنكت الوفية ٢١١ / أ.\nبضم أوله، تصغير جرو. انظر: تقريب التهذيب (٩٢٠)، والخلاصة: ٦٢."}],[859,"قُلْتُ: قدْ رَوَى عَنِ الْهَزْهَازِ: الثَّوْرِيُّ أيضًا (١). قالَ الخطيبُ: «وأقَلُّ ما ترتَفِعُ (٢) بهِ الجهالةُ، أنْ يَروِيَ عَنِ الرجلِ اثْنانِ مِنَ المشهورِينَ بالعِلْمِ إلاَّ أنَّهُ لاَ يَثْبُتُ لَهُ حُكمُ العدالَةِ بروايَتِهِما عَنْهُ» (٣)، وهذا مِمَّا قَدَّمْنا بَيَانَهُ، واللهُ أعلمُ."],[860,"قُلْتُ (٤): قَدْ خَرَّجَ البخاريُّ في \" صَحِيْحِهِ \" حديثَ جماعةٍ ليسَ لَهُمْ غيرُ راوٍ واحِدٍ، منهُمْ: مِرْدَاسٌ (٥) الأسْلَمِيُّ لَمْ يَرْوِ عنهُ غيرُ قَيْسِ بنِ أبي حازِمٍ (١). وكَذَلِكَ خَرَّجَ مُسْلِمٌ حَدِيْثَ قَوْمٍ لاَ راوِيَ لَهُمْ غَيْرُ واحِدٍ، منهُم: رَبِيْعَةُ (٢) ... ابنُ كَعْبٍ الأسْلمِيُّ، لَمْ يَرْوِ عنهُ غَيْرُ أبي سَلَمَةَ بنِ عَبْدِ الرَّحْمَانِ (٣)؛ وذَلِكَ منهُما مصيرٌ إلى أنَّ الراويَ قَدْ يَخْرُجُ عَنْ كَوْنِهِ مَجْهُولًا مَرْدُودًا، بروَايةِ واحِدٍ عنهُ (٤). والخِلاَفُ في ذلكَ مُتَّجِهٌ نحوَ اتِّجَاهِ الخِلاَفِ المعرُوفِ في الاكتفاءِ بواحِدٍ في التَّعْدِيْلِ عَلَى مَا قَدَّمْناهُ (١)، واللهُ أعلمُ.","",{"fn":"قال الزركشي في نكته ٣/ ٣٨٩: «هذا سهو، فإن الثوري لم يروِ عن الشعبي، فكيف يروي عن شيخه؟! نبّه عليه الحافظ المزي. نعم ... روى عن الهزهاز: الجراح بن مليح، ذكره ابن أبي حاتم، وهو أصغر من الثوري وتأخر بعده مدة، فلعل الهزهاز تأخر بعد الشعبي». وانظر: الجرح والتعديل ٢/ ٥٣٦، والمقنع ١/ ٢٥٩، والتقييد والإيضاح: ١٤٦. قلنا: رواية الثوري نصّ عليها البخاري في تاريخه الكبير ٨/ ٢٥١ وذكر دليله على ذلك، وهو سنده الصحيح إلى سفيان. وجري روى عنه أيضًا: أبو إسحاق السبيعي وعاصم بن بهدلة. انظر: المؤتلف والمختلف ١/ ٤٨٧، وتوضيح المشتبه ٢/ ٣٠٢. والذي يظهر أنهما اثنان اتفقا في الاسم واسم الأب، واختلفا في النسبة، فقد نقل الحافظ المزي في تهذيب الكمال ١/ ٤٥٠ عن أبي داود تفريقه بينهما، فقال: «جري بن كليب صاحب قتادة سدوسي بصري لم يروِ عنه غير قتادة، وجري بن كليب كوفي روى عنه أبو إسحاق». وفرّق المزي بينهما فذكر في ترجمة السدوسي البصري من أشياخه: علي وبشير بن الخصاصية، وروى عنه قتادة، وذكر في ترجمة النهدي الكوفي أنه روى عن رجل من بني سليم، وروى عنه أبو إسحاق السبيعي وابنه يونس. وسبقه إلى نحو ذلك الأمير ابن ماكولا في الإكمال ٢/ ٧٥ - ٧٦ إلا أنه زاد عاصم بن بهدلة، ثم قال: «لعله الأول أو غيره». وتبع الذهبيُّ المزيَّ في ذلك. الكاشف ١/ ٢٩٢ (٧٧٥) و(٧٧٦). ويدل عليه أيضًا اختلاف بلدان الرواة فالبصري روى عنه قتادة، وهو أيضًا بصري، والكوفي روى عنه أبو إسحاق السبيعي وابنه يونس وعاصم بن أبي النجود، وكلهم كوفي، والله أعلم.\nفي (م): «يرتفع».\nالكفاية: (١٥٠ ت، ٨٨ - ٨٩ هـ). قال الزركشي ٣/ ٣٩٠: «هذا منازع فيه بما سبق من كلامهم، لا سيما إذا كان الراوي عنه من عادته لا يروي إلا عن عدل، والظاهر أن رواية إمام ناقل للشريعة عن رجل في مقام الاحتجاج كافٍ في تعريفه وتعديله، وقد سبق أن البزار وابن القطان على أن رواية الجلة عن الشخص تثبت له العدالة».\nهذا اعتراض من ابن الصلاح وإيراد على كلام الخطيب.\nبكسر أوله وسكون الراء. انظر: تقريب التهذيب (٦٥٥٣)، وتاج العروس ١٦/ ١١٨.\nقال المزي في تهذيب الكمال ٧/ ٦٧ (٦٤٤٨): «روى عنه زياد بن علاقة، وقيس بن أبي حازم». وتبعه عليه الزركشي في نكته ٣/ ٣٩١، والبلقيني في محاسنه: ٢٢٨، وابن الملقن في المقنع ١/ ٢٦٠. وتعقبه الحافظ العراقي في التقييد والإيضاح: ٣٥٢ بأن قال: «الصواب ما قاله ابن الصلاح فإن الذي روى عنه زياد بن علاقة هو مرداس بن عروة صحابي آخر، لا أعلم بين من صنّف في الصحابة في ذلك اختلافًا». قلنا: انظر: التاريخ الكبير ٧/ ٤٣٤ (١٩٠٢) و(١٩٠٣)، والجرح والتعديل ٨/ ٣٥٠ (١٦٠٧) و(١٦٠٨)، والثقات ٣/ ٣٩٨، والاستيعاب ٣/ ٤٣٨، والإصابة ٣/ ٣٩٩ و٤٠١. وحديثه الوحيد عند البخاري ٨/ ١١٤ (٦٤٣٤) ولفظه: «يذهب الصالحون الأول فالأول ويبقى حفالة كحفالة الشعير أو التمر لا يباليهم الله بالة»، قال أبو عبد الله البخاري: يقال: حفالة وحثالة، ورواه في ٥/ ١٥٧ (٤١٥٦) موقوفًا على مرداس. وممن جزم بتفرد قيس بالرواية عن مرداس الأسلميِّ: الأزديُّ في المخزون: ٢٦٦، والدارقطنيُّ في الإلزامات: ٧٨، والحازمي في شروط الأئمة الخمسة: ٣٨، وغيرهم.\nفي (ع): «ربيع»، خطأ.\nبل روى عنه أيضًا: حنظلة بن علي الأسلمي، وأبو عمران الجوني، ونعيم بن عبد الله الْمُجْمِر. انظر: تهذيب الكمال ٢/ ٤٧٣ (١٨٧١)، ونكت الزركشي ٣/ ٣٩١ - ٣٩٢، والشذا الفياح ١/ ٢٥٢، وشرح التبصرة والتذكرة ٢/ ٤١ - ٤٢، والإصابة ٣/ ٤٠١. وحديثه من رواية أبي سلمة عند مسلم ٢/ ٥٢ (٤٨٩)، وغيره. ورواية نعيم بن عبد الله المجمر عنه عند أحمد ٤/ ٥٩. ورواية أبي عمران الجوني عنه عند أحمد أيضًا ٤/ ٥٨.\nقال الزركشي ٣/ ٣٩٥: «وما قاله من بناء ذلك على هذا قد يمتنع، بل الظاهر أنه منهما مصير إلى أن الراوي معروف من غير هذه الرواية، أو أنه احتفّت به قرائن اقتضت ذلك، وهذا هو الأَلْيَقُ بالاحتياط منهما، لا سيّما على طريق البخاري، فإنه سلك الأحوط والتشديد، وفيما قاله المصنف منافاة لطريقته». وقال أبو العباس القرطبي: «التحقيق: أنه متى عرفت عدالة الرجل قُبِلَ خبره، سواء روى عنه واحد أم أكثر، وعلى هذا كان الحال في العصر الأول من الصحابة وتابعيهم، إلى أن تنطّع المحدّثون». نقله ابن الملقن في المقنع ١/ ٢٦٣. ="}],[861,"التاسِعَةُ: اخْتَلَفُوا في قَبُولِ روايةِ الْمُبْتدِعِ الذي لاَ يُكَفَّرُ في بدعَتِهِ (٢)، فمنْهُمْ مَنْ رَدَّ روَايَتَهُ مُطْلَقًا؛ لأنَّهُ فاسِقٌ ببدْعَتِهِ وكما اسْتَوَى في الكُفْرِ الْمُتَأَوِّلُ وغَيْرُ الْمُتَأَوِّلِ، يسْتَوي في الفِسْقِ الْمُتَأَوِّلُ وغَيْرُ الْمُتَأَوِّلِ (١).","",{"fn":"تعقّبه الحافظ ابن كثير، فقال: «توجيه جيد، لكن البخاري ومسلم إنما اكتفيا في ذَلِكَ برواية الواحد فقط؛ لأن هذين صحابيان، وجهالة الصَّحَابِيّ لا تضر بخلاف غيره». اختصار علوم الْحَدِيْث ١/ ٢٩٨.\nذَكَرَ المؤلف هنا الخلاف في قبول رِوَايَة المبتدع غَيْر الكافر ببدعته، وَلَمْ يتطرق إلى المبتدع الكافر ببدعته، مَعَ وجود خلاف أيضًا في قبول روايته، فَقَدْ نقل غَيْر واحد كابن الملقن في المقنع ١/ ٢٦٥، والسيوطي في شرح ألفية العراقي: ٢٤٩ عن ابن الصَّلاَح أنَّهُ نقل الاتفاق عَلَى رد رِوَايَة الكافر ببدعته. وأشار إلى نحوه ابن كَثِيْر في مختصره ١/ ٢٩٩، لَكِنْ دُوْنَ نسبته إلى ابن الصَّلاَح. ="}],[862,"ومِنْهُمْ مَنْ قَبِلَ روايَةَ المبتَدِعِ إذا لَمْ يَكُنْ مِمَّنْ يَسْتَحِلُّ الكَذِبَ في نُصْرَةِ مَذْهَبِهِ، أوْ لأهْلِ مَذْهَبِهِ، سَواءٌ كانَ داعِيَةً إلى بدْعَتِهِ (٢) أوْ لَمْ يَكُنْ (٣).","",{"fn":"حكاه الخطيب البغدادي عن الإمام مالك، والقاضي عياض عن الباقلاني وطائفة من الأصوليين والفقهاء والمحدّثين من السلف والخلف، وهو قول القاضي عبد الجبار الهمداني وأبي هاشم الجبائي من المعتزلة، والأستاذ أبي منصور الماتريدي وأبي إسحاق الشيرازي والغزالي والآمدي وابن الحاجب، ونقله غير واحد عن الأكثرين. انظر: الكفاية: (١٩٤ ت، ١٢٠ هـ)، واللمع: ٤٥، وإكمال المعلم ١/ ١٢٥، وإحكام الأحكام ٢/ ٦٦ و٧٥، والبحر المحيط ٤/ ٢٦٩، والإبهاج ٢/ ٣١٤. تنبيه: وقع في كلا نشرتي الكفاية قول الخطيب: «وممن لا يروى عنه ذلك مالك بن أنس»، والظاهر من سياق الكلام وموازنته بما قبله وما بعده أن كلمة (لا) مقحمة، ويؤكد هذا نقل الزركشي في البحر ٤/ ٢٧٠ عن الخطيب. ثم نقل الحاكم في المدخل إلى الإكليل: ٤٢، وغيره عن مالك القول بهذا.\nفي (جـ): «بدعة».\nقال الزركشي ٣/ ٣٩٦: «ما رجّحه من التفصيل نقله غيره عن نص الشافعي». قلنا: هو الخطيب، وانظر ما يأتي."}],[863,"وعَزَا بعضُهُمْ (١) هذا إلى الشَّافِعِيِّ لقولِهِ: «أقْبَلُ شَهَادَةَ أهلِ الأهْوَاءِ، إلاَّ"],[864,"الخطَّابِيَّةَ (٢) مِنَ الرَّافِضَةِ؛ لأنَّهُمْ يَرَوْنَ الشَّهَادَةَ بالزُّوْرِ لِمُوافِقِيْهِم» (٣)."],[865,"وقَالَ قومٌ: تُقْبَلُ روايَتُهُ إذا لَمْ يكُنْ داعِيَةً، ولاَ تُقْبَلُ إذا كَانَ داعيةً إلى بدعتِهِ. وهذا مَذهبُ الكثيرِ أوْ الأكثرِ مِنَ العُلَماءِ (٤).","",{"fn":"قال العراقي في التقييد: ١٤٩: «أراد ببعضهم: الحافظ أبا بكر الخطيب، فإنه عزاه للشافعي في كتاب \" الكافية \"». وانظر: الكفاية (١٩٤ ت، ١٢٠ هـ).\nالخطّابيّة - بتشديد الياء -: هم أصحاب أبي الخطّاب محمد بن أبي زينب الأسدي. انظر عنهم: الفرق بين الفرق: ١٨، والتعريفات: ٥٩، وتاج العروس ٢/ ٣٧٥.\nانظر: الأم ٦/ ٢٠٦. ورواه عنه ابن أبي حاتم في آداب الشافعي ومناقبه: ١٨٩، والبيهقي في مناقب الشافعي ١/ ٤٦٨، وفي السنن الكبرى ١٠/ ٢٠٨، والخطيب في الكفاية: (١٩٤ - ١٩٥ت، ١٢٠ هـ). قال البلقيني في المحاسن: ٢٢٩ معلّقًا: «لا يقال: الخطابية لا يجوّزون الكذب، ومن كذب عندهم خرج من مذهبهم، فإذا سمع بعضهم بعضًا قال شيئًا عرف أنه ممّن لا يجوّز الكذب، فاعتمد قوله لذلك وشهد بشهادته، فلا يكون شهد بالزور، إنما شهد بما يعرف أنه حق. لأنا نقول: ما بنى عليه شهادته أصل باطل، فوجب ردّ شهادته لاعتماده أصلًا باطلًا، وإن زعم هو أنه حق». وهذا المذهب حكاه الخطيب عن ابن أبي ليلى وسفيان الثوري وأبي يوسف القاضي، ونسب الحاكم في المدخل إلى الإكليل: ٤٢ القول به إلى أكثر أهل الحديث، وقال الرازي: «إنه الحق»، ونسبه إلى أبي الحسين البصري - صاحب \" المعتمد في أصول الفقه \" - من المعتزلة، وبه قال البيضاوي، ورجحه ابن دقيق العيد وأقره الذهبي. انظر: المحصول ٢/ ١٩٥، والاقتراح: ٣٣٣، والموقظة: ٨٥، ونهاية السول ٣/ ١٢٥، وظفر الأماني: ٤٦٣.\nانظر في بيان معنى الداعية: البحر المحيط ٤/ ٢٧٢. قال الخطيب: «وقال كثير من العلماء يقبل أخبار غير الدعاة من أهل الأهواء، فأما الدعاة فلا يحتجّ بأخبارهم». وحكاه عن الإمام أحمد، ونقل القاضي عياض الاتفاق عليه، وبه جزم سليم الرازي، وحكاه القاضي عبد الوهاب في الملخص عن مالك - وهو الصحيح من مذهبه -، والمختار عند الحنفية، وهو الذي نصّ عليه ابن حبان في مقدمة صحيحه. انظر: الإحسان بترتيب صحيح ابن حبان ١/ ٨٩، والكفاية: (١٩٥ ت، ١٢١ هـ)، وإكمال المعلم ١/ ١٢٥، وكشف الأسرار ٢/ ٤٦، والبحر المحيط ٤/ ٢٧١، ٢٨٣. ="}],[866,"وحَكَى بعضُ أصحابِ الشَّافِعِيِّ - رضي الله عنه - خِلاَفًا بينَ أصحابِهِ في قَبُولِ روايةِ المبتدِعِ إذا لَمْ يَدْعُ إلى بدعَتِهِ، وقالَ: أمَّا إذا كانَ داعِيَةً فَلا خِلافَ بينَهُمْ في عَدَمِ قَبُولِ روايتِهِ."],[867,"وقالَ أبو حاتِمِ بنِ حِبَّانَ البُسْتِيُّ -أحَدِ المصَنِّفِيْنَ مِنْ أئمَّةِ الحديْثِ-: «الدَّاعِيَةُ إلى البِدَعِ لاَ يَجُوزُ الاحْتِجَاجُ بهِ عِنْدَ أئِمَّتِنا قاطِبَةً لاَ أعْلَمُ بينَهُم فيهِ خِلاَفًا» (١)."],[868,"وهذَا المذْهَبُ الثالِثُ أعْدَلُهَا وأوْلاَهَا، والأوَّلُ بَعِيْدٌ مُبَاعِدٌ للشَّائعِ عَنْ أئمَّةِ الحديثِ، فإنَّ كُتُبَهُمْ طافِحَةٌ بالروايَةِ عَنِ الْمُبْتَدِعَةِ غَيْرِ الدُّعَاةِ (٢). وفي \" الصحيحينِ \" كثيرٌ مِنْ أحَادِيْثِهِمْ في الشَّوَاهِدِ والأُصُولِ (١)، واللهُ أعلمُ.","",{"fn":"المجروحين ٣/ ٦٣ - ٦٤. قال الزركشي في نكته ٣/ ٣٩٦: «أنه اقتصر في النقل عن ابن حبان في ردّ الداعية، وسكت عن الجانب الآخر، وقد نقل ابن حبان فيه الاتفاق على القبول». قلنا: ونص كلامه كما في ثقاته ٦/ ١٤٠ - ١٤١: «ليس بين أهل الحديث من أئمتنا خلاف أن الصدوق المتقن إذا كان فيه بدعة ولم يكن يدعو إليها أن الاحتجاج بأخباره جائز، فإذا دعا إلى بدعته سقط الاحتجاج بأخباره». قال العراقي في التقييد: ١٥٠: «وفيما حكاه ابن حبان من الاتفاق نظر، فإنه يُروَى عن مالك ردّ روايتهم مطلقًا». وقد تعقّب ابنَ حبانَ الحافظُ ابنُ حجر في النزهة: ١٣٧ - ١٣٨، فقال: «أغرب ابن حبان فادّعى الاتّفاق على قبول غير الداعية من غير تفصيل. نعم ... الأكثر على قبول غير الداعية، إلاّ إن روى ما يقوي بدعته فيردّ على المذهب المختار، وبه صرّح الحافظ أبو إسحاق إبراهيم بن يعقوب الجوزجاني شيخ أبي داود والنسائي في كتابه \" معرفة الرجال \" (ص٣٢)، فقال في وصف الرواة: «ومنهم زائغ عن الحق - أي: عن السنة - صادق اللهجة، فليس فيه حيلة، إلا أن يؤخذ من حديثه وألاّ يكون منكرًا إذا لَم يقوِّ به بدعته».\n«بل والدعاة، منهم: عمران بن حطان الخارجي، مادح عبد الرحمان بن ملجم قاتل علي ابن أبي طالب - رضي الله تعالى عنه - وهذا من أكبر الدعوة إلى البدعة، خرّج عنه البخاري، وزعم جماعة أنه من دعاة الشراة. ومنهم عبد الحميد بن عبد الرحمان أخرج له الشيخان، وقال فيه أبو داود السجستاني: «كان داعية إلى الإرجاء»، وغير ذلك. فالظاهر أنه لا فرق». نكت الزركشي ٣/ ٤٠١. ="}],[869,"العَاشِرَةُ: التَّائِبُ مِنَ الكَذِبِ في حديثِ النَّاسِ وغيرِهِ مِنْ أسْبَابِ الفِسْقِ، تُقْبَلُ روايتُهُ، إلاَّ التَّائبَ مِنَ الكَذِبِ مُتَعَمِّدًا في حديْثِ رَسُولِ اللهِ - صلى الله عليه وآله وسلم -، فإنَّهُ لاَ تُقْبَلُ روايَتُهُ"],[870,"أبَدًا، وإنْ حَسُنَتْ تَوْبَتُهُ عَلَى مَا ذُكِرَ عَنْ غَيرِ واحِدٍ مِنْ أهلِ العِلْمِ، منْهُمْ: أحْمَدُ بنُ حَنْبَلٍ (٢)، وأبو بكرٍ الْحُمَيْدِيُّ - شَيْخُ البخارِيِّ (٣) -."],[871,"وأطلَقَ الإمامُ أبو بكرٍ الصَّيْرَفِيُّ الشَّافِعِيُّ فيما وجدْتُ لهُ في \" شرحِهِ لرسَالَةِ الشافِعِيِّ \"، فقالَ: «كلُّ مَنْ أسْقَطْنا خَبَرَهُ مِنْ أهلِ النَّقْلِ بكَذِبٍ (٤) وَجَدْنا عليهِ، لَمْ نَعُدْ لقَبُولِهِ بتوبَةٍ تَظهَرُ، ومَنْ ضَعَّفْنا نَقْلَهُ لَمْ نَجْعَلْهُ قَوِيًّا بَعدَ ذَلِكَ، وذَكَرَ أنَّ ذَلِكَ مِمَّا افترَقَتْ فيهِ الروايةُ والشَّهادَةُ (٥). وذَكَرَ الإمَامُ أبو المظَفَّرِ السَّمْعَانيُّ المروزيُّ: «أنَّ (٦) مَنْ كَذَبَ في خَبَرٍ واحِدٍ، وجَبَ إسْقَاطُ ما تَقَدَّمَ مِنْ حَدِيثِهِ» (٧)، وهذا يُضَاهِي مِنْ حَيْثُ المعْنَى ما ذَكَرَهُ الصَّيْرَفِيُّ (٨)، واللهُ أعلمُ.","",{"fn":"سرد أسماءهم السيوطي في تدريب الراوي ١/ ٣٢٨ - ٣٢٩ فبلغوا ثلاثة وثمانين راويًا.\nرواه عنه الخطيب في الكفاية: (١٩٠ ت، ١١٧ هـ).\nرواه الخطيب أيضًا في الكفاية: (١٩١ ت، ١١٨ هـ).\nقال العراقي في التقييد: ١٥١: «ذكر المصنف أن أبا بكر الصيرفي أطلق الكذب، أي: فلم يخصه بالكذب في الحديث. والظاهر: أن الصيرفي إنما أراد الكذب في الحديث، بدليل قوله: «من أهل النقل»، وقد قيده بـ «المحدِّث» فيما رأيته في كتابه المسمّى بـ \" الدلائل والاعلام \"، فقال: وليس يطعن على المحدّث إلا أن يقول: تعمدت الكذب، فهو كاذب في الأول، ولا يقبل خبره بعد ذلك».\nانظرها في: إكمال المعلم ١/ ١٠٧، والفروق ١/ ٥، ومحاسن الاصطلاح: ٢٣١، والنكت الوفية: ٢٢٥ / أ، وتدريب الراوي ١/ ٣٣١ - ٣٣٤.\nبعد هذا في (ع) زيادة: «كل»، ولم ترد في شيء من النسخ التي اعتمدناها في التحقيق.\nانظر: قواطع الأدلة ١/ ٣٢٤، وبه قال الماوردي والروياني من الشافعية. انظر: البحر المحيط ٤/ ٢٨٤. قال البلقيني في محاسنه: ٢٣٢: «ما نقل عن الصيرفي يقرب منه ما قاله ابن حزم: من أسقطنا حديثه لم نعد لقبوله أبدًا، ومن احتججنا به لم نسقط روايته أبدًا. وكذا قاله ابن حبان في آخرين».\nقلنا: وهذا الذي اختاره ابن الصلاح ونقله عن الصيرفي وأبي المظفر السمعاني، نقله أيضًا الحازمي عن سفيان الثوري وابن المبارك ورافع بن الأشرس وأبي نعيم الفضل بن دكين. انظر: شروط الأئمة الخمسة: ٥٤. ="}],[872,"الحادِيَةَ عَشْرَةَ: إذا رَوَى ثقةٌ عَنْ ثِقَةٍ حدِيثًا ورُوْجِعَ (١) المروِيُّ عنهُ فَنَفَاهُ، فالمختارُ: أنَّهُ إنْ كَانَ جازِمًا بنفْيهِ بأنْ قالَ: ما رَويتُهُ، أو كَذَبَ عَلَيَّ، أو نَحْو ذَلِكَ فَقَدْ تَعَارَضَ الجزْمَانِ، والجاحِدُ هُوَ الأصْلُ، فَوَجَبَ رَدُّ حدِيْثِ فَرْعِهِ ذَلِكَ (٢)، ثُمَّ لاَ يَكُونُ ذَلِكَ جَرْحًا لهُ (١) يُوجِبُ ردَّ باقِي حديثِهِ؛ لأنَّهُ مُكَذِّبٌ لشَيْخِهِ أيضًا في ذلكَ، وليسَ قَبُولُ جَرْحِ شَيْخِهِ لهُ بأوْلَى مِنْ قَبُولِ جَرْحِهِ لشَيْخِهِ، فتَسَاقَطا.","",{"fn":"في (ب): «ورجع».\nنبّه الزركشي هنا على أمرين: الأول: ما ذكره من أنه المذهب: «المختار»، ليس من تصرفه كما تعقبه به بعضهم، فقد نقل الخطيب في الكفاية: (٢٢١ ت، ١٣٩ هـ)، وإمام الحرمين في البرهان ١/ ٤١٧، عن القاضي أبي بكر الباقلاني، ونقل الأخير عن القاضي أيضًا عزوه إلى الشافعي، ونسبه ابن السمعاني في القواطع إلى أصحاب الشافعي، بل نقل الهندي الإجماع عليه، وهذا من الهندي غلط، فإن في المسألة قولين: ="}],[873,"أمَّا إذا قالَ المروِيُّ عنهُ: لاَ أعرِفُهُ، أو لاَ أذْكُرُهُ، أوْ نحوَ ذلكَ، فذلكَ لاَ يُوجِبُ رَدَّ روايَةِ الراوي عنهُ (٢)."],[874,"ومَنْ رَوَى حَدِيثًا ثُمَّ نَسِيَهُ لَمْ يَكُنْ ذلكَ مُسْقِطًا للعَمَلِ بهِ عندَ جُمْهُورِ أهلِ الحديثِ وجمهورِ الفقهاءِ والمتكلِّمينَ، خلافًا لقَومٍ مِنْ أصحَابِ أبي حَنيْفَةَ صَارُوا إلى إسْقَاطِهِ بذلِكَ (٣)، وبَنَوَا عليهِ رَدَّهُمْ حديثَ سُليمانَ بنِ موسَى، عَنِ الزُّهريِّ، عَنْ عُرْوَةَ، عَنْ عَائشَةَ، عَنْ رَسُولِ اللهِ - صلى الله عليه وآله وسلم -: «إذا نُكِحَتِ المرْأَةُ بغَيْرِ إذْنِ وَلِيِّها فَنِكَاحُها باطِلٌ الحديثَ» (١)، مِنْ أجْلِ أنَّ ابنَ جُرَيْجٍ، قالَ: «لقِيْتُ الزهريَّ فسَألْتُهُ عَنْ هذا الحديثِ فَلَمْ يَعرِفْهُ» (٢). وكذا حديثُ ربيعَةَ الرأي، عَنْ سُهَيْلِ بنِ أبي صالِحٍ، عَنْ أبيهِ، عَنْ أبي هُرَيْرَةَ: «أنَّ النبيَّ (١) - صلى الله عليه وآله وسلم - قَضَى بشَاهِدٍ ويَمِيْنٍ» (٢)، فإنَّ عَبْدَ العزيزِ بنَ محمدٍ الدَّرَاوَرْدِيَّ قالَ: «لقِيْتُ سُهَيْلًا فسَألْتُهُ عَنْهُ فَلَمْ يَعرِفْهُ» (٣).","",{"fn":"«أي: بخلاف الشهادة على ما قاله الماوردي، فإن تكذيب الأصل جرح للفرع، والفرق غلظ باب الشهادة وضيقه». قاله الزركشي ٣/ ٤١٢.\nحكى ابن الأثير في مقدمة جامع الأصول ١/ ٨٩ - ٩٠ ثلاثة مذاهب: الأول: يعمل به. الثاني: لا يعمل به. الثالث: التفصيل بين أن يكون ميل الشيخ إلى تغليب النسيان فيقبل، أو يميل إلى تغليب جهله أصلًا فلا يقبل.\nوحكاه ابن الصباغ عن أصحاب أبي حنيفة. انظر: شرح التبصرة والتذكرة ٢/ ٥٤. قلنا: بل هو مذهب أكثرهم، منهم: الكرخي والدبوسي والبزدوي، وصوّبه النسفي منهم، وهو رواية عن الإمام أحمد، ونقل الرافعي عن القاضي ابن كج حكايته وجهًا لبعض الشافعية، وعينه شارح اللمع بأنه القاضي أبو حامد المروذي. انظر: اللمع: ٤٨، وإحكام الأحكام ٢/ ٩٢، وكشف الأسرار للبخاري ٣/ ٦٠، وفواتح الرحموت ٢/ ١٧٠، ونهاية السول ٣/ ١٥٦، والبحر المحيط ٤/ ٣٢٥، وشرح السيوطي: ٢٥٢.\nهذا حديث رواه: الشافعي في الأم ٥/ ١٣، والطيالسي (١٤٦٣)، وعبد الرزاق (١٠٤٧٢)، والحميدي (٢٢٨)، وابن أبي شيبة ٤/ ١٢٨، وأحمد ٦/ ٤٧ و١٦٥ و٢٦٠، والدارمي (٢١٩٠)، وأبو داود (٢٠٨٣) و(٢٠٨٤)، وابن ماجه (١٨٧٩)، والترمذي (١١٠٢)، وابن الجارود (٧٠٠)، والطحاوي في شرح المعاني ٣/ ٧، وابن حبان (٧٠٧٤)، والدارقطني ٣/ ٢٢١، والحاكم ٢/ ١٦٨، والبيهقي ٧/ ١٠٥، وابن حزم في المحلى ٩/ ٤٥١، والبغوي (٢٢٦٢)، كلهم من طريق ابن جريج، عن سليمان بن موسى، عن الزهري، عن عروة، عن عائشة، به.\nروى هذا اللفظ عن ابن جريج: أحمد ٦/ ٤٧، والبخاري في التاريخ الكبير ٤/ ٣٨، وفي الضعفاء الصغير (١٤٦)، والطحاوي في شرح المعاني ٣/ ٨، والعقيلي في ضعفائه الكبير ٢/ ١٤٠ (٦٣٢). وأورده الترمذي في جامعه ٢/ ٣٩٥ عقب (١١٠٢ م) بلفظ آخر، فقال: «وقد تكلم بعض أصحاب الحديث في حديث الزهري، عن عروة، عن عائشة، عن النبي - صلى الله عليه وآله وسلم -. قال ابن جريج: ثم لقيت الزهري فسألته فأنكره، فضعّفوا هذا الحديث من أجل هذا». فبهذا أصبح عندنا لفظان للزهري في إجابة السائلين له عن هذا الحديث: الأول: عدم التذكر، وهو قوله: «فلم يعرفه». الثاني: إنكاره أصلًا، وهو قوله: «فأنكره». أما اللفظ الثاني فقد اعترض بعض الناس على ابن الصلاح في تمثيله به؛ لأن مقتضى هذا اللفظ الإنكار، وهو خلاف ما نبحث فيه من عدم تذكر الشيخ للحديث لا إنكاره له؟ وقد أجاب الحافظ العراقي: بـ «أن الترمذي لم يروه، وإنما ذكره بغير إسنادٍ، والمعروف في الكتب المصنفة في العلل: «فلم يعرفه»، كما ذكره المصنف». التقييد والإيضاح: ١٥٢. وأما الثاني: فقد تفرد بذكر هذا اللفظ عن ابن جريج: إسماعيل بن إبراهيم المعروف بابن عُليّة، قال ابن معين في تاريخه ٣/ ٨٦ (رواية الدوري): «ليس يقول هذا إلا ابن عُلية، وابن عُلية عرض كتب ابن جريج على عبد المجيد بن عبد العزيز بن أبي روّاد فأصلحها له». ونقل الترمذي ٢/ ٣٩٥ عن ابن معين قوله: «وسماع إسماعيل بن إبراهيم، عن ابن جريج ليس بذاك، إنما صحّح كتبه على كتب عبد المجيد بن عبد العزيز بن أبي روّاد ما سمع من ابن جريج. وضعّف يحيى رواية إسماعيل بن إبراهيم، عن ابن جريج». وروى الأثرم عن الإمام أحمد: «قلت لأبي عبد الله: حديث الولي، الكلام الذي يزيد فيه إسماعيل؟ فَقَالَ: نعم ... لم أسمعه من أحد غيره، وَقَالَ أبو عَبْد الله: إسماعيل إنما سَمِعَ هَذَا بالبصرة، فكيف هَذَا؟ كالمنكر له إن شاء الله، قلت له: فذاك حديث ثبت عندك؟ فقال: ما أدري أخبرك. قال أبو بكر -يعني: الأثرم-: معنى هذا الكلام أن ابن جريج روى عن سليمان بن موسى، عن الزهري، عن عروة، عن عائشة، عن النبي - صلى الله عليه وآله وسلم - قال: «أيما امرأة نكحت بغير إذن وليها فنكاحها باطل»، فرواه إسماعيل بن إبراهيم، عن ابن جريج، فزاد فيه: «قال ابن جريج: فسألت الزهري عنه فلم يعرفه، فكأنه أنكر هذه الزيادة. =\nفي (ب) و(جـ): «رسول الله».\nرواه الشافعي في الأم ٢/ ١٧٩، وأبو داود (٣٦١٠) و(٣٦١١)، وابن ماجه (٢٣٦٨)، وابن الجارود (١٠٠٧)، وأبو يعلى (٦٦٨٣)، والطحاوي في شرح المعاني ٤/ ١٤٤، وابن حبان (٥٠٧٣)، والدارقطني ٤/ ٢١٣، والبيهقي ١٠/ ١٦٨، والبغوي (٢٥٠٣). كلهم من طريق ربيعة، عن سهيل، عن أبيه، عن أبي هريرة، به مرفوعًا.\nالذي في سنن أبي داود عقب (٣٦١٠) عن عبد العزيز بن محمد الدراوردي: «قال: فذكرت ذلك لسهيل فقال: أخبرني ربيعة، وهو عندي ثقة أني حدّثته إياه، ولا أحفظه، قال عبد العزيز: وقد كان أصابت سهيلًا علة أذهبت بعض عقله ونسي بعض حديثه، فكان سهيل بعدُ يحدّثه عن ربيعة عنه، عن أبيه». لكن اللفظ الذي ذكره ابن الصلاح هنا قريب جدًا من لفظ سليمان بن بلال، فروى أبو داود (٣٦١١) الحديث من طريق سليمان بن بلال، عن ربيعة «قال سليمان: فلقيت سهيلًا فسألته عن هذا الحديث، فقال: ما أعرفه، فقلت له: إن ربيعة أخبرني به عنك، قال: فإن كان ربيعة أخبرك عني، فحدّث به عن ربيعة عني». ولعل ابن الصلاح ذكر معنى مشترك بين لفظي سليمان والدراوردي، واقتصر على نسبته إلى الدراوردي."}],[875,"والصحيحُ ما عليهِ الجمهُورُ؛ لأنَّ المروِيَّ عنهُ بصَدَدِ السَّهْوِ والنِّسْيَانِ (١) والرَّاوي عنهُ ثقةٌ جازِمٌ فلاَ يُرَدُّ (٢) بالاحتمالِ روايتُهُ، ولهذا كانَ سُهَيْلٌ بَعْدَ ذَلِكَ يَقُولُ: حَدَّثَنِي رَبيْعَةُ عَنِّي عَنْ أبي، ويسُوقُ الحديثَ."],[876,"وَقَدْ رَوَى كَثيرٌ مِنَ الأكَابِرِ أحادِيْثَ نَسَوْها بعدَ ما حُدِّثُوا بها عَمَّنْ سَمِعَها منهُمْ، فكَانَ أحَدُهُمْ يقُولُ: حدَّثَنِي فلاَنٌ عَنِّي عَنْ فلانٍ بكذا وكذا. وجَمَعَ الحافِظُ الخطيبُ ذلكَ في كِتَابِ \"أخْبَارِ مَنْ حَدَّثَ ونَسِيَ\" (٣). ولأجْلِ أنَّ الإنْسانَ مُعَرَّضٌ للنِسْيانِ؛ كَرِهَ مَنْ كَرِهَ مِنَ العُلَماءِ الروَايةَ عَنِ الأحْيَاءِ، منْهُمُ الشَّافِعِيُّ - رضي الله عنه - قالَ لابنِ عَبدِ الحكمِ (٤):"],[877,"«إيَّاكَ والروايةَ عَنِ الأحياءِ» (٥)، واللهُ أعلمُ."],[878,"الثَّانيةَ عَشْرَةَ: مَنْ أخَذَ عَلَى التَّحدِيثِ (٦) أجْرًا، منعَ ذلِكَ مِنْ قَبُولِ رِوايتِهِ عِنْدَ قومٍ مِنْ أئمَّةِ الحديثِ، رُوِّيْنا عَنْ إسْحاقَ بنِ إبْرَاهِيمَ - هُوَ ابنُ رَاهَوَيْهِ (٧) - أنَّهُ سُئِلَ عَنِ المحدِّثِ يُحَدِّثُ بالأجْرِ؟ فقالَ: «لاَ يُكْتَبُ عنهُ» (٨).","",{"fn":"اعترض على ابن الصلاح بأن الراوي معرّض أيضًا لذلك، فينبغي أن يتساقطا، ويبقى النظر في أحدهما بمرجح خارجي. فأجاب العراقي: بـ «أن الراوي مثبت جازم، والمروي عنه ليس بنافٍ وقوعه، بل غير ذاكر، فقدم المثبت عليه». التقييد: ١٥٤. قلنا: وهذا الجواب هو فحوى كلام ابن الصلاح الآتي.\nفي (أ): «ترد».\nوذكره الذهبي في السير ١٨/ ٢٩٠ باسم: \" مَنْ حَدَّثَ ونَسِيَ \"، وقد لَخَّصه السيوطي وسمّاه: \" تذكرة المؤتسي فيمن حدَّث ونسي \". قال الزركشي في نكته ٣/ ٤١٥: «وقبله الدارقطني وضع فيه جزءًا». وسمّى ابن حجر كتاب الدارقطني \" مَنْ حدَّث ونسي \". نزهة النظر: ١٦٦.\nهو أبو عبد الله محمد بن عبد الحكم بن أعين المصري الفقيه، توفي سنة (٢٦٨ هـ). انظر: وفيات الأعيان ٤/ ١٩٣، والسير ١٢/ ٤٩٧، وميزان الاعتدال ٣/ ٦١١.\nهو في المدخل للبيهقي كما ذكر غير واحد، ولم نعثر عليه في المطبوع فلعله مما نقص منه. وانظر: مناقب الشافعي له ٢/ ٣٨، والكفاية: (٢٢٢ ت، ١٣٩ هـ)، ونكت الزركشي ٣/ ٤١٦، والتقييد والإيضاح: ١٥٤ - ١٥٥.\nفي (جـ): «الحديث».\nفي (أ) و(ب): «إسحاق بن إبراهيم» فقط، وكذا في (ع) والتقييد، والمثبت من (جـ) ومحاسن الاصطلاح والشذا الفياح.\nرواه الخطيب في الكفاية: (٢٤٠ ت، ١٥٣ - ١٥٤ هـ)."}],[879,"وعَنْ أحمدَ بنِ حَنبَلٍ (١)، وأبي حاتِمٍ الرازِيِّ (٢)، نحوُ ذلكَ. وتَرَخَّصَ أبو نُعَيْمٍ الفضلُ بنُ دُكَينٍ (٣) وعليُّ بنُ عبدِ العزيزِ المكِّيُّ (٤) وآخرونَ (٥) في أخْذِ العِوَضِ عَلَى التَّحْديثِ، وذَلِكَ شَبِيهٌ بأخْذِ الأُجْرَةِ عَلَى تَعْلِيْمِ القرآنِ ونَحْوِهِ، غَيْرَ أنَّ في هَذَا مِنْ حَيْثُ العُرْفُ خَرْمًا للمرُوءةِ، والظَّنُّ يُسَاءُ بفاعِلهِ إلاَّ أنْ يَقْتَرِنَ ذَلِكَ بعُذْرٍ يَنْفِي ذَلِكَ عنهُ، كمثلِ ما حَدَّثَنِيهُ الشيخُ أبو المظَفَّرِ عَنْ أبيهِ الحافِظِ أبي سَعْدٍ السَّمْعانيِّ أنَّ أبا الفَضْلِ محمدَ ابنَ ناصِرٍ السَّلاَمِيَّ ذَكَرَ أنَّ أبا الحسَيْنِ بنِ النَّقُّورِ (٦) فَعَلَ ذَلِكَ؛ لأنَّ الشيْخَ أبا إسْحاقَ الشِّيرازيَّ أفتاهُ بجوَازِ أخْذِ الأُجْرَةِ عَلَى التَّحْدِيْثِ؛ لأنَّ أصحابَ الحديثِ كَانُوا يَمْنَعُونَهُ عَنِ الكَسْبِ لِعِيَالِهِ (٧)، واللهُ أعلمُ."],[880,"الثَّالِثَةَ عَشْرَةَ: لاَ تُقْبَلُ روَايَةُ مَنْ عُرِفَ بالتَّسَاهُلِ في سَمَاعِ الحديثِ أوْ إسْماعِهِ كَمَنْ لاَ يُبَالِي بالنَّوْمِ في مجْلِسِ السَّماعِ (٨)، وكَمَنْ يُحَدِّثُ لاَ مِنْ أصلٍ مُقَابَلٍ صحيحٍ.","",{"fn":"انظر: الكفاية: (٢٤٠ ت، ١٥٣ - ١٥٤ هـ).\nانظر: المصدر السابق، مع نكت الزركشي ٣/ ٤١٧.\nرواه عنه الخطيب في الكفاية: (٢٤٣ ت، ١٥٥ هـ).\nانظر: المصدر السابق.\nمنهم: مجاهد، ويعقوب بن إبراهيم الدورقي. انظر: الكفاية: (٢٤٣ - ٢٤٤ ت، ١٥٥ - ١٥٦ هـ)، وانظر: بحثًا نفيسًا في استدلال بعضهم على جواز هذا بفعل أبي بكر، وردّ ابن الجوزي عليهم كما في نكت الزركشي ٣/ ٤١٨.\nهو أبو الحسين أحمد بن محمد بن أحمد البغدادي البزار، مولده سنة (٣٨١ هـ)، ووفاته سنة (٤٧٠ هـ). انظر: تاريخ بغداد ٤/ ٣٨١، والمنتظم ٨/ ٣١٤، وسير أعلام النبلاء ١٨/ ٣٧٣.\nانظر: تاريخ بغداد ٤/ ٣٨١، والمنتظم ٨/ ٣١٤، وسير أعلام النبلاء ١٨/ ٣٧٤.\nقيّد الزركشي بالنوم الذي يطغى على العقل، أما النعاس الذي لا يختل معه فهم الكلام، فلا بأس به لا سِيّما إذا صدر من فطن عالم بهذا الشأن. انظر: نكت الزركشي ٣/ ٤٢٣. واستدل بما حكاه الحافظ ابن كثير عن شيخه الحافظ أبي الحجاج المزي، أنه كان: يكتب في مجلس السماع، وينعس في بعض الأحيان، ويردّ على القارئ ردًّا جيّدًا بيّنًا واضحًا، بحيث يتعجب القارئ من نفسه، أنه يغلط فيما في يده وهو مستيقظ والشيخ ناعس، وهو أنبه منه!! ذلك فضل الله يؤتيه من يشاء. انظر: اختصار علوم الحديث ١/ ٣٤٠ - ٣٤١."}],[881,"ومِنْ هَذَا القَبيلِ مَنْ عُرِفَ بقَبُولِ التَّلْقِيْنِ (١) في الحديثِ (٢)، ولاَ تُقْبَلُ روايةُ مَنْ كَثُرَتِ الشَّواذُّ والمناكِيْرُ في حديثِهِ."],[882,"جَاءَ عَنْ شُعْبَةَ: أنَّهُ قالَ: «لاَ يَجِيْئُكَ الحديثُ الشَّاذُّ إلاَّ مِنَ الرَّجُلِ الشَّاذِّ» (٣). ولاَ تُقْبَلُ روايةُ مَنْ عُرِفَ بكَثْرَةِ السَّهْوِ في رواياتِهِ إذا لَمْ يُحَدِّثْ مِنْ أصْلٍ صحيحٍ (٤)، وكُلُّ هذا يَخْرِمُ الثقةَ بالراوي وبضبْطِهِ.","",{"fn":"التلقين - كما عرّفه الحافظ العراقي -: هو أن يُلَقَّنَ الشيء فيحدث به من غير أن يعلم أنه من حديثه. شرح التبصرة والتذكرة ٢/ ٥٩. وانظر عن التلقين وأسبابه وحكمه: النفح الشذي ١/ ٣٢٣، وسير أعلام النبلاء ١٠/ ٢١٠، والنكت الوفية: ٢٣٢ / ب، وفتح المغيث ١/ ٣٨٥، وتدريب الراوي ١/ ٣٣٩، وتوضيح الأفكار ٢/ ٢٥٧، وتوجيه النظر ٢/ ٥٧٣، وأثر علل الحديث: ١٢٠.\nوسبقه إلى نحو هذا الحكم أبو محمد بن حزم في الإحكام ١/ ١٤٢، فقال: «ومن صح أنه قبل التلقين -ولو مرة- سقط حديثه كله؛ لأنه لم يتفقه في دين الله عزوجل ولا حفظ ما سمع». وكذا الحافظ ابن القطان الفاسي، فقد نقل الزركشي عنه ٣/ ٤٢٤ أنه قال: «التلقين عيب يسقط الثقة لمن اتصف به، وقد كانوا يفعلون ذلك بالمحدّث تجربة لحفظه وضبطه وحذقه». وأسند الخطيب البغدادي في الكفاية: (٢٣٤ - ٢٣٥ ت، ١٤٩ هـ) عن أبي الأسود أنه قال: إذا سرّك أن تكذب صاحبك فلقنه». وعن سلمة بن علقمة أنه قال: «إذا سرّك أن تكذب أخاك فلقنه». وقد نازعهم في إطلاق القول بردّ حديث المتلقن الحافظ العلاّمة ابن دقيق العيد في شرح الإلمام، فيما نقله الزركشي في نكته ٣/ ٤٢٤، فقال: «مطلق التلقين والإجابة ليس دليلًا على اختلاف حال الراوي، فقد يلقنه الناقل ما لا علم له به، فيجيبه بالصواب عنده، وربما يتحققه. وليس تقدم تلقينه بالدليل على مجازفته في جوابه. نعم ... التلقين الباطل إذا عرف بطلانه، فأجاب الملقّن بما عرف بطلانه كان دليلًا على مجازفته لا على تعمده الكذب، فالكذب منه يقينًا يتوقف على أن يثبت أنه لُقِّن الباطل الذي عرف بطلانه فأجاب به، وأما الإجابة بما يلقن به من غير تحقيق إفادة، فإنما يجعله قدحًا بطريق التهمة أو بقرينة شهرت بالمجازفة وعدم التثبت».\nأسنده ابن عدي في الكامل ١/ ١٥١، والخطيب في الكفاية: (٢٢٤ ت، ١٤١ هـ).\nوضّح الزركشي في نكته ٣/ ٤٢٥ - ٤٢٦ هنا أمرين: ="}],[883,"ووَرَدَ عَنِ ابنِ المبَارَكِ (١)، وأحمدَ بنِ حَنبَلٍ (٢)، والْحُمَيْديِّ (٣)، وغَيْرِهِمْ أنَّ مَنْ غَلِطَ في حديثٍ وبُيِّنَ لَهُ غَلَطُهُ فَلَمْ يَرْجِعْ عنهُ وأصَرَّ على روايةِ ذلكَ الحديثِ سَقَطَتْ رواياتُهُ، ولَمْ يُكْتَبْ عنهُ (٤)."],[884,"وفي هذا نَظَرٌ (٥)، وهو غَيْرُ مُسْتَنْكَرٍ إذا ظَهَرَ أنَّ ذلكَ منهُ عَلَى جِهَةِ (٦) العِنادِ أو نحوِ ذلكَ (٧)، واللهُ أعلمُ.","",{"fn":"رواه عنه الخطيب في الكفاية: (٢٢٧ ت، ١٤٣ هـ).\nرواه عنه الخطيب: (٢٢٨ ت، ١٤٤ هـ).\nأسنده الخطيب عنه في الكفاية: (٢٢٨ ت، ١٤٤ هـ).\nكما روى الخطيب في الكفاية: (٢٣٧ ت، ١٥١ هـ) عن أبي حاتم الرازي، قال: «دخلت الكوفة فحضرني أصحاب الحديث، وقد تعلقوا بورّاق سفيان بن وكيع، فقالوا: أفسدت علينا شيخنا وابن شيخنا، قال فبعثت إلى سفيان بتلك الأحاديث التي أدخلها عليه ورّاقه يرجع عنها، فلم يرجع عنها فتركته».\nقال محقق المقنع ١/ ٢٨١: «يشير ابن الصلاح بهذا إلى أنه قد يوجد هذا الوصف في الثقات، يُبَيَّن خطؤهم فلا يرجعون لتيقنهم من صحة حفظهم، كما وقع لمالك - رحمه الله - في روايته عن عُمَرَ بن عثمان، وغيره يقول: عَمْرو بن عثمان، فَبُيِّنَ له فلم يرجع، كما تقدم في نوع المنكر».\nفي (جـ): «على وجه».\nقال العراقي: ١٥٦ - ١٥٧: «ما ذكره المصنف بحثًا قد نص عليه أبو حاتم بن حبان، فقال: «إن من بيّن له خطؤه وعَلِمَ، فلم يرجع وتمادى في ذلك كان كذابًا بعلم صحيح». فقيّد ابن حبان ذلك بكونه عَلِمَ خطأه، وإنما يكون عنادًا إذا علم الحق وخالفه. وقيَّد أيضًا بعض المتأخرين ذلك: بأن يكون الذي بيّن له غلطه عالمًا عند المبين له، أما إذا كان ليس بهذا المثابة عنده، فلا حرج إذن»."}],[885,"الرَّابِعَةَ عَشْرَةَ: أعْرَضَ النَّاسُ في هذهِ الأعْصَارِ المتأَخِّرَةِ عَنْ اعتِبارِ مجمُوعِ (١) مَا بَيَّنَّا مِنَ الشروطِ في رواةِ الحديثِ ومشايخِهِ، فَلَمْ يَتَقَيَّدُوا بها في رواياتِهِمْ؛ لِتَعَذُّرِ الوفاءِ بذلكَ عَلَى نحوِ ما تَقَدَّمَ، وكَانَ عليهِ مَنْ تَقَدَّمَ (٢). ووجْهُ ذلكَ ما قَدَّمْناهُ في أوَّلِ كِتَابِنا هذا مِنْ كَونِ المقْصودِ آلَ آخِرًا إلى المحافَظَةِ على خَصِيْصَةِ هذهِ الأمةِ في الأسانيدِ والمحاذرةِ مِنِ انْقِطاعِ سِلْسِلَتِها، فَلْيُعْتَبَرْ مِنَ الشروطِ المذكورَةِ ما يَلِيْقُ بهذا الغرضِ علَى تَجَرُّدِهِ، ولْيُكْتَفَ في أهْلِيَّةِ الشَّيْخِ بكَونِهِ مُسْلِمًا، بَالِغًا، عَاقِلًا، غَيْرَ مُتَظَاهِرٍ بالفِسْقِ والسُّخْفِ (٣)، وفي ضَبْطِهِ: بوجودِ سمَاعِهِ مُثْبَتًا بِخَطِّ غَيْرِ مُتَّهَمٍ وبروايَتِهِ مِن أصْلٍ موافِقٍ لأصْلِ شيْخِهِ. وقدْ سَبَقَ إلى نحوِ ما ذَكَرْناهُ الحافِظُ الفقِيْهُ أبو بَكْرٍ البيْهَقِيُّ - رَحِمَهُ اللهُ تَعَالَى - فإنَّهُ ذَكَرَ فيْمَا رُوِّيْنا (٤) عنهُ تَوَسُّعَ مَنْ تَوَسَّعَ في السَّماعِ مِنْ بعضِ مُحَدِّثي زَمَانِهِ الذينَ لاَ يَحْفَظُونَ حديْثَهُم، ولاَ يُحْسِنُونَ قِرَاءَتَهُ مِنْ كُتُبِهِمْ، ولاَ يَعْرِفُونَ مَا يُقْرَأُ عَلَيْهِمْ بَعْدَ أنْ تَكُونَ القِرَاءَةُ عَلَيْهِمْ مِنْ أصْلِ سَمَاعِهِمْ."],[886,"وَوَجْهُ ذلكَ: بأنَّ الأحاديْثَ التي قَدْ صَحَّتْ أو وقفَتْ بينَ الصِّحَّةِ والسَقَمِ قَدْ دُوِّنَتْ وكُتِبَتْ في الجوامِعِ التي جَمَعَها أئِمَّةُ الحديثِ، ولاَ يَجُوزُ أنْ يَذْهَبَ شيءٌ منها عَلَى جميْعِهِمْ، وإنْ جَازَ أنْ يَذْهَبَ عَلَى بعضِهِمْ لضَمانِ صَاحِبِ الشَّرِيْعَةِ حِفْظَها."],[887,"قَالَ (٥): «فَمَنْ جَاءَ اليَوْمَ بحَدِيْثٍ لاَ يُوجَدُ عندَ جميعِهِمْ لَمْ يُقْبَلْ منهُ، ومَنْ جَاءَ بحدِيْثٍ معرُوفٍ عندَهُمْ، فالذي يَرْوِيهِ لاَ يَنْفَرِدُ بروايَتِهِ، والحجَّةُ قائِمَةٌ بحديثِهِ بروايةِ غيرِهِ، والقَصْدُ مِنْ روَايَتِهِ والسَّمَاعِ منهُ، أنْ يَصِيْرَ الحديثُ مُسَلْسَلًا بـ «حَدَّثَنا وأخْبَرَنا»، وتَبْقَى هذهِ الكَرامَةُ التي خُصَّتْ بها هذهِ الأمَّةُ، شَرَفًا لنبيِّنا المصْطَفَى صَلَّى اللهُ عَلَيْهِ وَعَلَى آلِهِ وسَلَّمَ، واللهُ أعْلَمُ (١).","",{"fn":"في (جـ): «مجموع جملة».\nانظر في هذا: مشكل الحديث وبيانه لابن فورك: ١٧، وجامع الأصول ١/ ٣٥ - ٣٦، ونكت الزركشي ١/ ٤٥ و٣/ ٤٢٧.\nالسَّخْفُ والسُّخْفُ والسُّخْفَةُ والسَّخَافَةُ: ضعف العقل ورقّته ونقصانه، والسَّخِيْف: الناقص العقل. انظر: لسان العرب ٩/ ١٤٦، وتاج العروس ٢٣/ ٤٢١، ومتن اللغة ٣/ ١٢٣.\nكذا في جميع النسخ الخطية والتقييد، وفي (ع) و(م) والشذا: «رويناه».\nفي (ع) والتقييد: «قال البيهقي»."}],[888,"الخامِسَةَ عَشْرَةَ: في بَيَانِ الألفَاظِ المسْتَعْمَلَةِ بَيْنَ (٢) أهْلِ هَذَا الشَّأْنِ في الجرْحِ والتَّعْدِيْلِ."],[889,"وقدْ رَتَّبَها أبو محمَّدٍ عَبدُ الرَّحْمانِ بنُ أبي حاتِمٍ الرَّازيُّ في كِتَابهِ في \" الجرْحِ والتَّعْدِيْلِ \" (٣)، فأجَادَ وأحْسَنَ."],[890,"ونَحْنُ نُرَتِّبُها كذلِكَ، ونُوْرِدُ ما ذَكَرَهُ ونضيفُ إليهِ ما بَلَغَنا في ذلكَ عَنْ غيرِهِ إنْ شَاءَ اللهُ تَعَالَى (٤)."],[891,"أمَّا ألْفَاظُ التَّعْدِيلِ (٥) فَعَلَى مَرَاتِبَ:"],[892,"الأُوْلَى: قالَ ابنُ أبي حاتِمٍ: «إذا قِيْلَ للوَاحِدِ: إنَّهُ ثِقَةٌ (٦) أو مُتْقِنٌ، فَهُوَ مِمَّنْ يُحْتَجُّ بحدِيْثِهِ» (٧).","",{"fn":"عبارة: «والله أعلم» لم ترد في (أ) و(ب) و(جـ) والشذا، ولم ينقلها الحافظ العراقي ضمن نص ابن الصلاح الذي نقله في شرح التبصرة والتذكرة ٢/ ٦٢، وهي من (ع) و(م) والتقييد وإنما أثبتناها؛ لأن عادته أن يختم كل موضوع بقوله هذا.\nفي (ع) و(م) والتقييد: «من».\nالجرح والتعديل ٢/ ٣٧.\nومن جاء بعده قد زاد مراتب أخرى، انظر تفصيل ذلك في مقدمة ميزان الاعتدال ١/ ٤، وشرح التبصرة ٢/ ٦٤، والتقييد: ١٥٧، ومقدمة تقريب التهذيب: ٧٤، ونزهة النظر: ١٨٧، وفتح المغيث ١/ ٣٩٠، وتدريب الراوي ١/ ٣٤١، وتوضيح الأفكار ٢/ ٢٦١.\nانظر: نكت الزركشي ٣/ ٤٣٠ - ٤٣١.\nهناك رتبة أعلى ينبغي تقديمها وهي تكرار التوثيق، إما مع تباين الألفاظ كقولهم: «ثبت حجة، أو ثبت حافظ، أو ثقة ثبت، أو ثقة متقن، ونحوه. وإما مع إعادة اللفظ الأول، كقولهم: ثقة ثقة، ونحوها، فهذه أعلى المراتب في التوثيق كما قاله الذهبي في مقدمة الميزان ١/ ٤. ويرى بعض العلماء أن أعلى المراتب ما أتي بصيغة: «أفعل»، كأن يقال: «أوثق الخلق» و«أثبت الناس». نكت الزركشي ٣/ ٤٣١، وفتح المغيث ١/ ٣٦٣.\nالجرح والتعديل ٢/ ٣٧."}],[893,"قُلْتُ: وكَذَا إذا قِيْلَ ثَبْتٌ أوْ حُجَّةٌ (١)، وكَذَا إذا قِيْلَ في العَدْلِ: إنَّهُ حَافِظٌ أوْ ضَابِطٌ، واللهُ أعْلَمُ."],[894,"الثَّانيةُ: قَالَ ابنُ أبي حاتِمٍ: «إذا قِيْلَ: إنَّهُ صَدُوْقٌ، أوْ مَحَلُّهُ الصِّدْقُ (٢)، أوْ لاَ بأسَ بهِ، فَهوَ مِمَّنْ يُكْتَبُ حَدِيْثُهُ ويُنْظَرُ فيهِ، وهِيَ المنْزِلَةُ الثَّانِيَةُ» (٣)."],[895,"قُلْتُ: هذا كَما قالَ؛ لأنَّ هذهِ العِبَاراتِ لاَ تُشْعِرُ بشَرِيْطَةِ الضَّبْطِ، فَيُنْظَرُ في حَدِيْثِهِ ويُخْتَبَرُ حَتَّى يُعْرَفَ ضَبْطُهُ. وقَدْ تَقَدَّمَ بَيَانُ طرِيْقِهِ في أوَّلِ هذا النَّوْعِ. وإنْ لَمْ يَسْتَوْفِ النَّظَرَ المعرِّفَ لكوْنِ ذَلِكَ المحدِّثِ في نفسِهِ ضابطًا مُطْلَقًا، واحْتَجْنا إلى حديثٍ مِنْ حديثِهِ، اعتبَرْنا ذلكَ الحديثَ ونَظَرْنا: هَلْ لَهُ أصْلٌ مِنْ رِوَايةِ غَيْرِهِ؟ كما تَقَدَّمَ بيانُ طَرِيْقِ الاعتِبَارِ في النَّوْعِ الخامِسَ عَشَرَ."],[896,"ومشْهُورٌ عَنْ عَبْدِ الرَّحْمَانِ بنِ مَهْدِيٍّ (٤) - القُدْوَةِ في هذا الشَّأْنِ - أنَّهُ حدَّثَ، فقالَ: «حَدَّثَنا أبو خَلْدَةَ» (٥)، فقِيْلَ لهُ: «أكَانَ ثِقَةً؟»، فقالَ: «كَانَ صَدُوْقًا، وكَانَ مَأْمُوْنًا، وكَانَ خَيِّرًا - وفي روايةٍ: وكَانَ خِيَارًا - الثِّقَةُ شُعْبَةُ وسُفْيَانُ» (٦). ثُمَّ إنَّ ذلكَ مُخَالِفٌ لِمَا وَرَدَ عَنِ ابنِ أبي خَيْثَمَةَ، قالَ: «قُلْتُ ليَحْيَى بنِ مَعِيْنٍ (٧): إنَّكَ تَقُولُ: فُلانٌ ليسَ بهِ بأسٌ، وفلانٌ ضَعِيْفٌ؟ قَالَ: إذا قُلْتُ لكَ: ليسَ بهِ بأسٌ، فهوَ ثِقَةٌ، وإذا قُلْتُ لَكَ: هُوَ ضَعِيْفٌ، فَلَيْسَ هُوَ بثِقَةٍ، لاَ يُكْتَبُ (١) حَدِيْثُهُ» (٢).","",{"fn":"انظر: نكت الزركشي ٣/ ٤٣٢، ومحاسن الاصطلاح: ٢٣٧، والتقييد والإيضاح: ١٥٧.\nراجع التقييد والإيضاح: ١٥٨، وتدريب الراوي ١/ ٣٤٥، والنكت والوفية: ٢٣٦/ ب، ومباحث في علم الجرح والتعديل: ٣٩.\nالجرح والتعديل ٢/ ٣٧.\nانظر: محاسن الاصطلاح: ٢٣٨، والتقييد: ١٥٨.\nهو خالد بن دينار التميمي السعدي، وأبو خلدة البصري الخياط، مشهور بكنيته، تابعي صغير، توفي سنة (١٥٢ هـ). وخَلْدَة - بفتح المعجمة وسكون اللام -. انظر: الكاشف ١/ ٣٦٣، والتقريب (١٦٢٧).\nالكنى والأسماء للدولابي ١/ ١٦٥، والجرح والتعديل ٣/ ٣٢٨، والكفاية: (٥٩ - ٦٠ ت، ٢٢ هـ).\nراجع نكت الزركشي ٣/ ٤٣٣ - ٤٣٤."}],[897,"قُلْتُ: لَيْسَ في هذا (٣) حكَايَةُ ذلِكَ عَنْ غَيْرِهِ مِنْ أهْلِ الحديثِ، فإنَّهُ نَسَبَهُ إلى نَفْسِهِ خاصَّةً بخِلاَفِ ما ذَكَرَهُ ابنُ أبي حاتِمٍ، واللهُ أعلمُ."],[898,"الثَّالِثَةُ: قَالَ ابنُ أبي حاتِمٍ: «إذا قيلَ: شَيْخٌ (٤)، فهوَ بالمنْزِلَةِ الثَّالِثَةِ، يُكْتَبُ حدِيْثُهُ، ويُنْظَرُ فيهِ، إلاَّ أنَّهُ دُوْنَ الثَّانِيَةِ» (٥)."],[899,"الرَّابِعَةُ: قالَ: «إذا قِيْلَ: صَالِحُ الحديثِ، فإنَّهُ يُكْتَبُ حدِيْثُهُ للاعْتِبَارِ» (٦)."],[900,"قٌلْتُ: وقدْ جَاءَ عَنْ أبي جَعْفَرِ بنِ سِنَانٍ، قالَ: «كَانَ عَبْدُ (٧) الرحمانِ بنُ مَهْدِيٍّ رُبَّما جَرَى ذِكْرُ حديثِ الرجلِ فيهِ ضَعْفٌ، وهو رجلٌ صَدوقٌ، فيقولُ: رجلٌ صالِحُ الحديثِ» (٨). واللهُ أعلمُ."],[901,"وأمَّا ألفاظُهُمْ في الجرْحِ فهيَ أيضًا علَى مَرَاتِبَ:","",{"fn":"في (ع): «لا تكتب».\nالكفاية: (٦٠ ت، ٢٢ هـ).\nلم ترد في (ب).\nقال ابن القطان ٤/ ٦٢٧ عقب (٢١٨٤): «فأما قول أبي حاتم فيه: «شيخ» فليس بتعريف بشيء من حاله إلا أنه مقل ليس من أهل العلم، وإنما وقعت له رواية أخذت عنه. وقال الزركشي ٣/ ٤٣٤: «قال الحافظ جمال الدين المزي: المراد بقولهم: «شيخ» أنه لا يترك ولا يحتج بحديثه مستقلًا». وقال ابن القطان في الوهم والإيهام: «يعنون بذلك أنه ليس من طلبة العلم، وإنما هو رجل اتفقت له رواية في الحديث أو أحاديث أخذت عنه». وراجع مباحث في علم الجرح والتعديل: ٣٩ إذ ذكر هذا القول الأخير عن ابن القطان.\nالجرح والتعديل ٢/ ٣٧.\nالمصدر السابق.\nفي (ع): «عبدًا»، خطأ قبيح.\nالكفاية: (٦٠ ت، ٢٣ هـ)."}],[902,"أُوْلاَها: قَوْلُهُمْ: لَيِّنُ الحديثِ. قالَ ابنُ أبي حاتِمٍ: إذا أجابُوا في الرجلِ بـ: لَيِّنِ الحدِيثِ، فهوَ مِمَّنْ يُكْتَبُ حديثُهُ ويُنْظَرُ فيهِ اعتبارًا» (١)."],[903,"قُلْتُ: وسَأَلَ حَمْزَةُ بنُ يُوسُفَ السَّهْمِيُّ (٢) أبا الحسَنِ الدَّارقطنيَّ الإمامَ، فقالَ لهُ: «إذا قُلْتَ: فلانٌ لَيِّنُ أيْشٍ (٣) تُرِيْدُ بهِ؟ قالَ: لاَ يَكونُ سَاقِطًا مترُوكَ الحديثِ ولكنْ مجرُوحًا (٤) بشيءٍ لاَ يُسْقِطُ عَنِ العدالَةِ» (٥)."],[904,"الثَّانيةُ: قالَ ابنُ أبي حاتِمٍ: «إذا قَالُوا: ليسَ بقَوِيٍّ (٦)، فَهوَ بمَنْزِلَةِ الأوَّلِ في كَتْبِ حَدِيْثِهِ، إلاَّ أنَّهُ دُوْنَهُ» (٧)."],[905,"الثَّالِثَةُ: قالَ: «إذا قَالُوا: ضَعِيْفٌ، فهوَ دُوْنَ الثَّاني، لاَ يُطْرَحُ حديثُهُ بَلْ يُعْتَبَرُ"],[906,"بهِ» (٨)."],[907,"الرَّابِعَةُ: قَالَ: «إذا قَالُوا: مَتْرُوكُ الحديثِ، أوْ ذَاهِبُ الحديثِ، أو كَذَّابٌ فهوَ سَاقِطُ الحديثِ لاَ يُكْتَبُ حديثُهُ وهيَ المنْزِلَةُ الرَّابِعَةُ» (٩)."],[908,"قالَ الخطيبُ أبو بكرٍ: «أرفعُ العباراتِ في أحوالِ الرواةِ أنْ يُقَالَ: حُجَّةٌ أو ثِقَةٌ، وأدْوَنُها أنْ يُقَالَ: كَذَّابٌ، سَاقِطٌ» (١٠).","",{"fn":"الكفاية: (٦٠ ت، ٢٣ هـ).\nسؤلات السهمي: ٧٢.\nالمعنى: أي شيء.\nفي المطبوع من سؤلات السهمي: «ولكن يكون مجروحًا».\nالكفاية: (٦٠ ت، ٢٣ هـ).\nقال الذهبي في الموقظة: ٨٢: «وقد قيل في جماعات: «ليس بقوي» واحتجّ به، وهذا النسائي قد قال في عدة: «ليس بالقوي»، ويخرج لهم في كتابه قال: قولنا: ليس بالقوي ليس بجرح مفسد».\nالجرح والتعديل ٢/ ٣٧.\nالمصدر السابق.\nالمصدر نفسه.\nالكفاية: (٥٩ ت، ٢٢ هـ). تنبيه: بعد هذا في (ع): «الحديث»، ولم ترد في شيء من النسخ ولا (م)، بل ولا حتى في الكفاية."}],[909,"أخْبَرَنَا أبو بَكرِ بنُ عَبْدِ المنعِمِ الصَّاعِدِيُّ الفُرَاوِيُّ قِرَاءَةً عليهِ بنَيْسَابورَ، قَالَ: أخْبَرَنَا محمدُ بنُ إسْمَاعيلَ الفارِسِيُّ، قَالَ: أخْبَرَنَا أبو بكرٍ أحمدُ بنُ الحسينِ البيهقيُّ الحافِظُ، قالَ: أخْبَرَنَا أبو (١) الحسين بنُ الفَضْلِ، قَالَ: أخْبَرَنَا عَبْدُ اللهِ بنُ جَعْفَرٍ، قَالَ: حَدَّثَنا (٢) يَعقوبُ بنُ سُفيانَ، قَالَ: سَمِعْتُ أحمدَ بنَ صَالِحٍ، قَالَ: «لاَ يُتْرَكُ حديثُ رَجُلٍ حَتَّى يَجْتَمِعَ الجميعُ عَلَى تَركِ حديثِهِ. قدْ يُقَالُ: فُلانٌ ضَعِيْفٌ، فأمَّا أنْ يُقَالَ: فُلاَنٌ مَتْرُوكٌ فلاَ، إلاَّ أنْ يُجْمِعَ الجميعُ عَلَى تَرْكِ حَدِيْثِهِ (٣)."],[910,"ومِمَّا لَمْ يَشْرَحْهُ ابنُ أبي حاتِمٍ وغَيْرُهُ مِنَ الألفاظِ (٤) المستعملةِ في هذا البابِ"],[911,"قَوْلُهُمْ: فُلانٌ قَدْ رَوَى الناسُ عنهُ، فُلاَنٌ وَسَطٌ، فُلاَنٌ مُقَارَبُ الحديثِ (٥)، فلاَنٌ مُضْطَرِبُ الحديثِ، فُلاَنٌ لاَ يُحْتَجُّ بهِ (٦)، فُلاَنٌ مَجْهُولٌ، فُلاَنٌ لاَ شيءَ، فلاَنٌ ليسَ بذَاكَ - ورُبَّمَا قِيْلَ: لَيْسَ بذَاكَ (٧) القَوِيِّ - فُلاَنٌ فيهِ أو في حديثِهِ ضَعْفٌ - وهوَ في الجرْحِ أقَلُّ مِنْ قَوْلِهِمْ: فُلاَنٌ ضَعِيْفُ الحديثِ - فلاَنٌ مَا أعْلَمُ بهِ بَأْسًا - وهوَ في التَّعْديلِ دُونَ قَوْلِهِمْ: لاَ بأسَ بهِ، وما مِنْ لَفْظَةٍ منها ومِنْ أشْبَاهِها إلاَّ وَلَها نَظِيْرٌ شَرَحْناهُ أو أصْلٍ أصَّلْنَاهُ، يُتَنَبَّهُ (٨) إنْ شَاءَ اللهُ بهِ عليها، واللهُ أعلمُ.","",{"fn":"سقطت من (ع).\nفي (م): «أنبأنا».\nالكفاية: (١٨١ ت، ١١٠ هـ).\nانظر: التقييد والإيضاح: ١٦٠ - ١٦١.\nقال ابن العربي في عارضة الأحوذي ١/ ١٧ - ١٨: «يُروى - بفتح الراء وكسرها - وبفتحها قرأته، فمن فتح أراد: أن غيره يقاربه في الحفظ، ومن كسر أراد: أنه يقارب غيره، فهو في الأول مفعول، وفي الثاني فاعل، والمعنى واحد»، وقيل غير ذلك. انظر تفصيل ذلك في نكت الزركشي ٣/ ٤٣٥، والتقييد: ١٦٢، والنكت الوفية: ٢٣٦/ ب، ومحاسن الاصطلاح: ٢٤٠، وفتح المغيث ١/ ٣٩٤.\nانظر: التقييد: ١٦١.\nفي (أ) و(ب): «بذلك».\nفي (م): «ينبه»."}],[912,"النوع الرابع والعشرون معرفة كيفية سماع الحديث وتحمله وصفة ضبطه"],[913,"اعْلَمْ أنَّ طُرُقَ نَقْلِ الحديثِ وتَحَمُّلِهِ عَلَى أنواعٍ مُتَعدِّدَةٍ، ولنُقَدِّمْ عَلَى بَيَانِها بَيَانَ أُمُورٍ:"],[914,"أَحَدُها: يَصحُّ التَّحَمُّلُ قَبلَ وُجُودِ الأَهْلِيَّةِ فَتُقْبَلُ روايَةُ (١) مَنْ تَحَمَّلَ قَبْلَ الإسْلامِ وَرَوَى بَعْدَهُ، وكذَلِكَ روايَةُ مَنْ سَمِعَ قَبْلَ البُلُوغِ (٢) وَرَوَى بَعْدَهُ ومَنَعَ مِنْ ذَلِكَ قَومٌ فأخْطَؤُوا؛ لأنَّ الناسَ قَبِلُوا روايَةَ أحداثِ الصَّحابَةِ، كالحَسَنِ بنِ عليٍّ وابنِ عَبَّاسٍ، وابنِ الزُّبَيْرِ، والنُّعْمانِ بنِ بَشِيْرٍ، وأشْبَاهِهِمْ (٣)، مِنْ غَيْرِ فَرْقٍ بَيْنَ مَا تَحَمَّلُوهُ قَبْلَ البُلُوْغِ ومَا بَعْدَهُ (٤)، ولَمْ يَزَالُوا قَدِيْمًا وَحَدِيْثًا يُحْضِرُونَ الصِّبْيَانَ مجَالِسَ التَّحْدِيْثِ والسَّمَاعِ ويَعْتَدُّوْنَ برِوَايَتِهِمْ (٥) لِذَلِكَ، واللهُ أعلمُ."],[915,"الثَّاني: قَالَ أبو عبدِ اللهِ الزُّبَيْرِيُّ: «يُسْتَحَبُّ كَتْبُ الحديثِ في العشرينَ؛ لأنَّها مُجْتَمَعُ العقْلِ - قَالَ - وأُحِبُّ أنْ يَشْتَغِلَ دُوْنَها بحِفْظِ القُرْآنِ والفَرَائِضِ»."],[916,"وَوَرَدَ عَنْ سُفْيانَ الثَّوْرِيِّ، قَالَ: «كَانَ الرَّجُلُ إذا أرَادَ أنْ يَطْلُبَ الحديثَ تَعَبَّدَ قَبْلَ ذَلِكَ عِشْرينَ سَنَةً» (٦).","",{"fn":"للتمثيل على ذلك، انظر: نكت الزركشي ٣/ ٤٥٩.\nانظر: نكت الزركشي ٣/ ٤٦١.\nوقد بوّب الخطيب في الكفاية: (١٠٣ - ١١٩ ت، ٥٤ - ٦٦ هـ): «باب ما جاء في صحة سماع الصغير»، وأورد فيه جملة من الآثار التي حفظها صغار الصحابة، ومن بعدهم، وحدّثُوا بها بعد ذلك وقبلت عنهم».\nلذلك قال ابن الأثير في جامع الأصول ١/ ٧١: «أما إذا كان طفلًا عند التحمل، مميزًا بالغًا عند الرواية، فتقبل؛ لأن الخلل قد اندفع عن تحمله وأدائه».\nقال البلقيني في المحاسن: ٢٤١: «الاعتداد بتحملهم في حال الصبا، ليرووه بعد البلوغ، هو المعروف، وشذ قوم فجوّزوا رواية الصبي قبل بلوغه، وهو وجه عند الشافعية، والمشهور الأول. ولهم وجه آخر بالمنع من التحمل قبل البلوغ، وقد تقدّمت حكايته عن قوم». وانظر: نكت الزركشي ٣/ ٤٦٢ - ٤٦٣.\nالمحدّث الفاصل: ١٨٧، والكفاية: (١٠٤ ت، ٥٤ هـ)."}],[917,"وَقِيْلَ لِمُوسَى بنِ إسْحَاقَ: «كَيْفَ لَمْ تَكْتُبْ (١) عَنْ أبي نُعَيْمٍ؟» (٢)، فقالَ: «كَانَ أهلُ الكُوْفَةِ لاَ يُخْرِجُونَ أوْلاَدَهُمْ في طَلَبِ الحديثِ صِغَارًا حَتَّى يَسْتَكْمِلُوا عِشْرِينَ"],[918,"سَنَةً» (٣). وقَالَ مُوْسَى بنُ هَارُوْنَ: «أهْلُ البَصْرَةِ يَكْتبُونَ لِعَشْرِ سِنِيْنَ، وأهْلُ الكُوْفَةِ لِعِشْرِينَ، وأهلُ الشَّامِ لِثَلاَثِينَ» (٤)، واللهُ أعلمُ."],[919,"قُلْتُ: ويَنْبَغِي بَعْدَ أنْ صَارَ الملْحُوظُ إبْقَاءَ سِلْسِلَةِ الإسْنَادِ أنْ يُبَكَّرَ بإسْماعِ الصَّغِيْرِ في أوَّلِ زَمَانٍ يَصِحُّ فيهِ سَمَاعُهُ."],[920,"وأمَّا الاشْتِغَالُ بِكِتْبَةِ الحديثِ (٥)، وتَحْصِلِه، وضَبْطِهِ، وتَقْييدِهِ، فَمنْ حِيْنَ يَتَأَهَّلُ لِذَلِكَ وَيَسْتَعِدُّ لَهُ. وذَلِكَ يَخْتَلِفُ باخْتِلاَفِ الأشْخَاصِ، ولَيْسَ يَنْحَصِرُ في سِنٍّ (٦) مَخْصُوصٍ كَمَا سَبَقَ ذِكْرُهُ آنِفًا عَنْ قَوْمٍ، واللهُ أعلمُ."],[921,"الثَّالِثُ: اخْتَلَفُوا في أوَّلِ زَمَانٍ يَصِحُّ فيهِ سَمَاعُ الصَّغِيْرِ (٧)."],[922,"فَرُوِّيْنَا عَنْ مُوْسَى بنِ هَارُونَ الحمَّالِ (٨) - أحَدِ الْحُفَّاظِ النُّقَّادِ - أنَّهُ سُئِلَ: «مَتَى يَسْمَعُ الصَّبِيُّ الحديثَ؟»، فقالَ: إذَا فَرَّقَ بينَ البَقَرَةِ والدَّابَّةِ»، وَفِي روايةٍ: «بينَ البَقَرَةِ والحِمَارِ» (٩). وَعَنْ أحمدَ بنِ حَنْبَلٍ - رضي الله عنه - أنَّهُ سُئِلَ: «مَتَى يَجُوزُ سَمَاعُ الصَّبِيِّ للحديثِ؟» (١)، فقالَ: «إذا عَقَلَ وَضَبَطَ»، فَذُكِرَ لَهُ عَنْ رَجُلٍ أنَّهُ قَالَ: «لاَ يَجُوزُ سَمَاعُهُ حَتَّى يَكُونَ (٢) لَهُ خَمسَ عَشْرَةَ سَنَةً»، فأنْكَرَ قَوْلَهُ، وقَالَ: «بِئْسَ القَوْلُ!» (٣).","",{"fn":"في (أ): «ولم يكتب»، وفي (ب): «لا يكتب».\nانظر: نكت الزركشي ٣/ ٤٦٢ - ٤٦٣.\nالمحدّث الفاصل: ١٨٦، والكفاية: (١٠٤ ت، ٥٤ - ٥٥ هـ).\nالمحدّث الفاصل: ١٨٧، والكفاية: (١٠٤ ت، ٥٥ هـ).\nفي (ع): «بكتبه الحديث»، وما أثبتناه من (أ) و(ب) و(م) والشذا الفياح، وراجع حاشية المحاسن: ٢٤٢، وتاج العروس ٤/ ١٠٠ وما بعدها.\nفي (ب): «شخص».\nفصّل الزركشي ذلك في نكته ٣/ ٤٦٣ - ٤٦٨.\nتشير المصادر إلى أن (الحمّال) لقب لأبيه -وهو بالحاء المهملة وتشديد الميم-، هذه النسبة إلى حمل الأشياء وإنما سُمِّيَ حَمّالًا؛ لأنه حمل رجلًا في طريق مكة على ظهره، فانقطع به فيما يقال. وفي الأنساب ٢/ ٢٩٨: «وهارون كان بزازًا فتزهد فصار يحمل الأشياء بالأجرة ويأكل منها، وقيل: إنه لُقِّبَ بالحمّال؛ لكثرة ما حمل من العلم». وانظر: تهذيب الكمال ٧/ ٣٧٨ وسير أعلام النبلاء ١٢/ ١١٥، ولكنَّ كلام صاحب الأنساب ٢/ ٢٩٧ يُشْعِر أن هذا اللقب اشتهر به ابنه أيضًا وبقي عليه.\nانظر الروايتين في: الكفاية: (١١٧ - ١١٨ ت، ٥٦ هـ)."}],[923,"وأخْبَرَنِي الشيخُ أبو محمدٍ عَبدُ الرحمانِ بنُ عَبدِ اللهِ الأسديُّ عَنْ أبي محمدٍ عبدِ اللهِ ابن محمدٍ الأشِيريِّ، عَنِ القاضي الحافِظِ عِيَاضِ بنِ مُوْسَى السَّبْتِيِّ (٤) اليَحْصُبِيِّ (٥)،"],[924,"قالَ: «قَدْ حَدَّدَ أهْلُ الصَّنْعَةِ في ذَلِكَ أنَّ أَقَلَّهُ سِنُّ محمودِ بنِ الرَّبِيْعِ» (٦). وذَكَرَ روايةَ البخاريِّ في \" صحِيْحِهِ \" (٧) بَعْدَ أنْ تَرْجَمَ: «مَتى يَصِحُّ سَمَاعُ الصَّغِيْرِ؟» بإسْنادِهِ عَنْ محمودِ بنِ الرَّبيعِ، قَالَ: «عَقَلْتُ مِنَ النَّبِيِّ - صلى الله عليه وآله وسلم - مَجَّةً (٨) مَجَّهَا في وَجْهِي وأنَا ابنُ خَمسِ سِنِيْنَ مِنْ دَلْوٍ»، وفي روايةٍ أُخْرى: أنَّهُ كَانَ ابنُ أربعِ سِنِيْنَ (٩)."],[925,"قُلْتُ: التَّحْديدُ بخَمْسٍ هُوَ الذي اسْتَقَرَّ عليهِ عَمَلُ أهلِ الحديثِ المتأخِّرينَ، فيكْتبُونَ لابنِ خَمْسٍ فَصَاعِدًا سَمِعَ، ولِمَنْ لَمْ يَبْلُغْ خَمْسًا، حَضَرَ، أو أُحْضِرَ. والذي ينبغي في ذلكَ أنْ يُعْتَبَرَ (١) في كُلِّ صَغِيْرٍ حَالُهُ عَلَى الخصُوصِ، فإنْ وجَدْنَاهُ مُرْتَفِعًا عَنْ حَالِ مَنْ لاَ يَعْقِلُ فَهْمًا للخطابِ وَردًّا للجوابِ ونحوَ ذلكَ صَحَّحْنا سَماعَهُ، وإنْ كَانَ دُونَ خَمسٍ. وإنْ لَمْ يَكُنْ كذَلِكَ لَمْ نُصَحِّحْ سَمَاعَهُ، وإنْ كَانَ ابنُ خَمْسٍ، بَلِ ابنُ خَمْسِيْنَ.","",{"fn":"ارجع إلى تفصيل ذلك في نكت الزركشي ٣/ ٤٦٨ - ٤٧٠.\nفي (ب): «تكون».\nالكفاية: (١١٣ ت، ٦١ هـ) مع بعض الاختلاف.\nنسبة إلى سبتة - بفتح السين، وقيل بالكسر وسكون الباء - مدينة مشهورة بالمغرب. انظر: معجم البلدان ٣/ ١٨٢، والتاج ٤/ ٥٤٢.\nبفتح الياء المثناة، وسكون الحاء المهملة، وضم الصاد المهملة وفتحها وكسرها. وفيات الأعيان ٣/ ٤٨٥، والتاج ٢/ ٢٨٦.\nالإلماع: ٦٢.\nصحيح البخاري ١/ ٢٩ عقب (٧٧) باب: «حتى يصح سماع الصغير» و١/ ٥٦ عقب (١٨٩) باب: استعمال وضوء الناس. وأخرجه أيضًا مسلم في صحيحه ٢/ ١٢٦ (٣٣)، وابن ماجه (٦٦٠)، والنسائي في عمل اليوم والليلة (١١٠٨)، وابن خزيمة (١٧٠٩).\nمَجَّة - بفتح الميم وتشديد الجيم المعجمة -، والمجّ: هو إرسال الماء من الفم، وقيل: لا يسمّى مجًّا إلا إن كان على بعد. وفعله النبي - صلى الله عليه وآله وسلم - مع محمود إما مداعبة معه، أو ليبارك عليه بها، كما كان شأنه مع أولاد الصحابة. فتح الباري ١/ ١٧٢.\nالإلماع: ٦٣. وقال الحافظ ابن حجر في الفتح ١/ ١٧٣ عقب (١٨٧)، وذكر القاضي عياض في الإلماع وغيره أن بعض الروايات أنه كان ابن أربع، ولم أقف على هذا صريحًا في شيء من الروايات بعد التتبع التام، إلا إذا كان ذلك مأخوذًا من قول صاحب الاستيعاب ٣/ ٤٢٢: «إنه عقل مجة، وهو ابن أربع سنين أو خمس»."}],[926,"وقَدْ بَلَغَنا عَنْ إبراهِيْمَ بنِ سَعِيْدٍ الجوْهَرِيِّ، قالَ: «رأيتُ صَبِيًّا ابنَ أربَعِ سِنِيْنَ، قَدْ (٢) حُمِلَ إلى المأْمُونِ قَدْ قَرَأَ القُرآنَ، ونَظَرَ في الرَّأْيِ، غيرَ أنَّهُ إذا جاعَ يَبْكِي!» (٣)."],[927,"وعَنِ القاضي أبي محمدٍ عبدِ اللهِ بنِ محمدٍ الأصْبهانيِّ، قَالَ: «حَفِظْتُ القُرْآنَ ولِي خَمسُ سِنِيْنَ، وحُمِلْتُ إلى أبي بكرِ بنِ الْمُقْرِئِ لأسْمَعَ منهُ، ولِي أربَعُ سِنِيْنَ، فَقَالَ بَعْضُ الحاضرينَ: لاَ تُسَمِّعُوا (٤) لَهُ فيما قُرِئَ فإنَّهُ صَغيرٌ، فقالَ لي ابنُ المقْرِئِ: اقْرَأْ سُوْرَةَ الكَافرِيْنَ، فَقَرَأْتُها، فقالَ: اقْرَأْ سُوْرَةَ التَّكْويرِ، فقرأتُها، فقالَ لي غَيْرُهُ: اقْرَأْ سُوْرَةَ والمرْسَلاتِ، فقرَأْتُها، ولَمْ أغْلَطْ فيها، فقالَ ابنُ المقرِئِ: سَمِّعُوا لَهُ والعُهْدَةُ عَلَيَّ» (٥). وأمَّا حديثُ محمودِ بنِ الرَّبِيْعِ فيَدُلُّ على صِحَّةِ ذَلِكَ مِنِ ابنِ خَمْسٍ مِثْلِ محمودٍ، ولاَ يَدلُّ علَى انتفاءِ الصِّحَّةِ فيمَنْ لَمْ يَكُنْ ابنَ خمسٍ ولاَ عَلَى الصِّحَّةِ فيمَنْ كَانَ ابنَ خمسٍ ولَمْ يُميِّزْ تَمْييزَ محمودٍ - رضي الله عنه -، واللهُ أعلمُ.","",{"fn":"في (ج): «تعبر»، وفي (م) والشذا: «تعتبر».\nفي (ع) والتقييد: «وقد».\nهذه القصة أوردها الخطيب في الكفاية: (١١٧ ت، ٦٤ هـ) بسند ضعيف، فيه أحمد بن كامل القاضي، قال الذهبي في الميزان ١/ ١٢٩: «ليَّنه الدارقطني. وقال: كان متساهلًا ومشَّاه غيره، وكان من أوعية العلم، كان يعتمد على حفظه فيَهِمْ». قال العراقي في التبصرة والتذكرة ٢/ ٨٧: «والذي يغلب على الظن عدم صحة هذه الحكاية وقد رواها الخطيب في الكفاية بإسناده وفي سندها أحمد بن كامل القاضي، وكان يعتمد على حفظه فيهم، وقال الدارقطني كان متساهلًا». وقال في التقييد والإيضاح: ١٦٥: «أحسن المصنف في التعبير عن هذه الحكاية بقوله: بلغنا ولم يجزم بنقلها، فقد رأيت بعض الأئمة من شيوخنا يستبعد صحتها، ويقول على تقدير وقوعها لم يكن ابن أربع سنين، وإنما كان ضئيل الخلقة فيظن صغره. والذي يغلب على الظن عدم صحتها. وقد مال الزركشي في نكته ٣/ ٤٧١ إلى خلاف ما ذهب إليه العراقي، وانظر: تاريخ بغداد ٤/ ٣٥٦، وسير أعلام النبلاء ١٥/ ٥٤٤، وميزان الاعتدال ١/ ١٢٩، ولسان الميزان ١/ ٢٤٩.\nأي: لا تكتبوا له سماعًا.\nالكفاية: (١١٧ ت، ٦٤ - ٦٥ هـ)."}],[928,"بيان أقسام طرق نقل الحديث وتحمله"],[929,"ومَجَامِعُهَا (١) ثَمَانِيَةُ أقْسَامٍ:"],[930,"القِسْمُ (٢) الأوَّلُ: السَّمَاعُ مِنْ لَفْظِ الشَّيْخِ، وهوَ يَنقسمُ إلى إمْلاَءٍ، وتحديثٍ مِنْ غَيْرِ إمْلاَءٍ، وسَواءٌ كَانَ مِنْ حِفْظِهِ أوْ مِنْ كِتَابِهِ. وهَذَا القِسْمُ أرفَعُ الأَقْسَامِ (٣) عِنْدَ الجماهِيْرِ. وفِيْما نَرْوِيهِ عَنِ القاضِي عِياضِ بنِ موسَى السَّبْتِيِّ - أحَدِ المتَأَخِّرينَ المطَّلِعِينَ - قولُهُ: «لاَ خِلاَفَ أنَّهُ يَجُوزُ في هذا أنْ يَقُولَ السَّامِعُ منهُ: حَدَّثَنَا (٤)، وأخْبَرَنا، وأنْبَأَنَا، وسَمِعْتُ فُلاَنًا يَقُولُ، وقَالَ لَنا فُلاَنٌ، وذَكَرَ لَنا فُلاَنٌ» (٥)."],[931,"قُلْتُ: في هذا نَظَرٌ (٦)، ويَنْبَغِي فِيْما شَاعَ اسْتِعْمالُهُ مِنْ هذهِ الألْفَاظِ مَخْصُوصًا بِما سُمِعَ مِنْ غَيْرِ لَفْظِ الشَّيْخِ - عَلَى مَا نُبَيِّنُهُ إنْ شَاءَ اللهُ تَعَالَى - أنْ لاَ يُطْلَقَ فِيْما سُمِعَ مِنْ لَفْظِ الشَّيْخِ لِمَا فيهِ مِنَ الإيْهَامِ والإلْبَاسِ، واللهُ أعْلَمُ."],[932,"وذَكَرَ الحافِظُ أبو بَكْرٍ الخطِيْبُ: أنَّ أرْفَعَ العِباراتِ (٧) في ذَلِكَ: سَمِعْتُ، ثُمَّ: حدَّثَنا وحَدَّثَنِي، فإنَّهُ لاَ يَكَادُ أحَدٌ يَقُولُ: سَمِعْتُ في أحَادِيْثِ الإجَازَةِ والمكَاتَبَةِ ولاَ في تَدْلِيسِ مَا لَمْ يَسْمَعْهُ (٨). وكَانَ بَعْضُ أهْلِ العِلْمِ يَقُولُ فيما أُجِيْزَ لَهُ: حَدَّثَنا. وَرُوِيَ عَنِ الحسَنِ أنَّهُ كَانَ يَقُولُ: حَدَّثَنا أبو هُرَيرَةَ (٩)، ويَتَأَوَّلُ أنَّهُ حَدَّثَ أهْلَ المدِينَةِ، وكَانَ الحسَنُ إذْ ذَاكَ بهَا إلاَّ أنَّهُ لَمْ يَسْمَعْ مِنْهُ شَيْئًا.","",{"fn":"في (ب): «يجمعها».\nكلمة: «القسم» لَم ترد في (م).\nراجع: ما كتبه الزركشي ٣/ ٤٧٢ بخصوص هذا.\nانظر: نكت الزركشي ٣/ ٤٧٣.\nالإلماع: ٦٩.\nانظر: نكت الزركشي ٣/ ٤٧٤.\nانظر: نكت الزركشي ٣/ ٤٧٥ - ٤٧٦.\nالكفاية: (٤١٣ ت، ٢٨٤ هـ).\nالكفاية: (٤١٣ ت، ٢٨٤ هـ)، وانظر: نكت الزركشي ٣/ ٤٧٦ - ٤٧٨، وتعليقنا على شرح التبصرة ٢/ ٩٠ - ٩١."}],[933,"قُلْتُ: ومِنْهُمْ مَنْ أثْبَتَ لَهُ سَمَاعًا مِنْ أبي هُرَيْرَةَ (١)، واللهُ أعلَمُ."],[934,"ثُمَّ يَتْلُو ذَلِكَ قَوْلُ: أخْبَرَنا وَهوَ كَثِيْرٌ في الاسْتِعْمالِ، حَتَّى إنَّ جَمَاعةً مِنْ أهْلِ العِلْمِ كَانُوا لاَ يَكَادُونَ يُخْبِرُونَ عَمَّا سَمِعُوهُ مِنْ لَفْظِ مَنْ حَدَّثَهُمْ إلاَّ بقَوْلِهِمْ: أخْبَرَنا، مِنْهُم: حَمَّادُ بنُ سَلَمَةَ، وعَبْدُ اللهِ بنُ المبارَكِ، وهُشَيْمُ بنُ بَشِيْرٍ وعُبَيْدُ اللهِ بنُ مُوسَى، وعَبْدُ الرَّزَّاقِ بنُ هَمَّامٍ، ويَزِيْدُ بنُ هَارُونَ، وعَمْرُو بنُ عَوْنٍ ويَحْيَى بنُ يَحْيَى التَّمِيْمِيُّ، وإسْحاقُ بنُ رَاهَوَيْهِ، وأبو مَسْعُودٍ أحمدُ بنُ الفُرَاتِ، ومحمَّدُ بنُ أيُّوبَ الرَّازِيَّانِ،"],[935,"وغَيْرُهُمْ (٢). وذَكَرَ الخطيبُ عَنْ محمَّدِ بنِ رَافِعٍ، قَالَ: كَانَ عَبْدُ الرَّزَّاقِ يَقُولُ: أخْبَرَنا حَتَّى قَدِمَ أحمدُ بنُ حَنْبَلٍ وإسْحَاقُ بنُ رَاهَويهِ فقَالاَ لَهُ: قُلْ: «حَدَّثَنا»، فَكُلُّ مَا سَمِعْتَ مَعَ هَؤلاَءِ قالَ: «حَدَّثَنا»، وما كَانَ قَبْلَ ذَلِكَ قَالَ: «أخْبَرَنا» (٣). وعَنْ محمَّدِ بنِ أبي الفَوَارِسِ الحَافِظِ، قَالَ: هُشَيْمٌ، ويَزِيْدُ بنُ هَارُونَ، وعَبْدُ الرَّزَّاقِ لاَ يَقُولُونَ إلاَّ:"],[936,"«أخْبَرَنا»، فإذا رَأَيْتَ: «حَدَّثَنَا»، فَهُوَ مِنْ خَطَأِ الكَاتِبِ (٤)، واللهُ أعلمُ."],[937,"قُلْتُ: وَكَانَ هذا كُلُّهُ قَبْلَ أنْ يَشِيْعَ تَخْصِيْصُ أخْبَرَنا بما قُرِئَ عَلَى الشَّيْخِ، ثُمَّ يَتْلُو قَوْلَ أخْبَرَنا قَوْلُ أنْبَأَنَا ونَبَّأَنَا، وهوَ قَلِيْلٌ في الاسْتِعْمَالِ."],[938,"قُلْتُ: حَدَّثَنا وأخْبَرَنا أرفعُ مِنْ سَمِعْتُ مِنْ جِهَةٍ أُخْرَى، وهيَ أنَّهُ لَيْسَ في سَمِعْتُ دلاَلَةٌ عَلَى أنَّ الشَّيْخَ رَوَّاهُ الحديثَ وخَاطَبَهُ بهِ، وفي حدَّثَنا، وأخْبَرَنا دلاَلَةٌ عَلَى أنَّهُ خَاطَبَهُ بهِ ورَوَّاهُ لَهُ أوْ هُوَ مِمَّنْ فُعِلَ بهِ ذَلِكَ. سَأَلَ الخطِيْبُ أبو بَكْرٍ الحافِظُ (٥) شَيْخَهُ أبا بَكْرٍ البَرْقَانيَّ (٦) الفَقِيْهَ الحافِظَ - رَحِمَهُما اللهُ تَعَالَى - عَنِ السِّرِّ في كَوْنِهِ يَقُولُ فيما رَوَاهُ لَهُمْ عَنْ أبي القَاسِمِ عَبْدِ اللهِ بنِ إبرَاهِيْمَ الْجُرْجَانيِّ الآبَنْدُونِيِّ (١)، سَمِعْتُ ولاَ يَقُولُ حَدَّثَنا، ولاَ أخْبَرَنا فَذَكَرَ لهُ أنَّ أبا القاسِمِ كَانَ مَعَ ثِقَتِهِ وصَلاَحِهِ عَسِرًا (٢) في الرِّوَايَةِ ن فَكَانَ البَرْقَانيُّ يَجْلِسُ بحَيْثُ لاَ يَرَاهُ أبو القَاسِمِ ولاَ يَعْلَمُ بحضُورِهِ، فيَسْمَعُ منهُ (٣) ما يُحَدِّثُ بهِ الشَّخْصَ الدَّاخِلَ إليهِ فَلِذَلِكَ يَقُولُ: سَمِعْتُ ولاَ يَقُولُ: حَدَّثَنا، ولاَ أخْبَرَنا؛ لأنَّ قَصْدَهُ كَانَ الروايةُ للدَّاخِلِ إليهِ وَحْدَهُ. وأمَّا قَوْلَهُ، قَالَ لنا فُلاَنٌ (٤)، أو ذَكَرَ لنا فلانٌ فَهوَ مِنْ قَبِيْلِ قَوْلِهِ: حَدَّثَنا فُلاَنٌ؛ غَيْرَ أنَّهُ لاَئِقٌ بما سَمِعَهُ منهُ في المذَاكَرَةِ وهوَ بهِ أشْبَهُ مِنْ حَدَّثَنا.","",{"fn":"انظر: جامع التحصيل: ١٦٤، ونكت الزركشي ٣/ ٤٧٦ - ٤٧٨.\nهذا النص في الكفاية: (٤١٣ - ٤١٤ ت، ٢٨٤ - ٢٨٥ هـ).\nالكفاية: (٤١٥ ت - ٢٨٦ هـ).\nالمصدر السابق.\nالكفاية: (٤١٧ ت، ٢٨٧ هـ).\nقال الزركشي ٣/ ٤٨٧: «مثل هذه الحكاية ما روي عن النسائي أنه فيما رواه عن الحارث ابن مسكين يقول: قراءةً عليه وأنا أسمع، ولا يقول: أخبرنا ولا حدثنا فإن الحارث كان يتولى قضاء مصر، وبينه وبين النسائي خشونة لم يمكنه حضور مجلسه، فكان يتستر في موضع ويسمع حيث لا يراه أحد فلذلك تورع وتحرى»."}],[939,"وقَدْ حَكَيْنا في فَصْلِ التَّعْلِيْقِ عَقِيْبَ النَّوْعِ الحادِي عَشَرَ عَنْ كَثِيْرٍ مِنَ المحدِّثِيْنَ اسْتِعْمَالَ ذَلِكَ مُعَبِّرِيْنَ بهِ عَمَّا جَرَى بَيْنَهُمْ في المذَاكَرَاتِ والمنَاظَرَاتِ."],[940,"وأوْضَعُ العِبَاراتِ في ذَلِكَ أنْ يَقُولَ: قَالَ فُلاَنٌ، أوْ ذَكَرَ فُلاَنٌ مِنْ غَيْرِ ذِكْرِ قَوْلِهِ: لِي، ولَنا ونَحْوِ ذَلِكَ. وقَدْ قَدَّمْنَا فِي فَصْلِ الإسْنادِ المعَنْعَنِ أنَّ ذَلِكَ ومَا أشْبَهَهُ مِنَ الألْفَاظِ، مَحْمُولٌ عِنْدَهُم عَلَى السَّمَاعِ إذَا عُرِفَ لِقَاؤُهُ لَهُ وَسَمَاعُهُ مِنْهُ عَلَى الْجُمْلَةِ، لاَ سِيَّمَا إذَا عُرِفَ مِنْ حَالِهِ أنَّهُ لاَ يَقُولُ: قَالَ فُلاَنٌ، إلاَّ فيمَا سَمِعَهُ مِنْهُ."],[941,"وقَدْ كَانَ حَجَّاجُ بنُ محمَّدٍ الأَعْوَرُ يَرْوِي عَنِ ابنِ جُرَيْجٍ كُتُبَهُ، ويَقُولُ فيها: قَالَ ابنُ جُرَيْجٍ فَحَمَلَها النَّاسُ عَنْهُ واحْتَجُّوا برِوايَاتِهِ، وكَانَ قَدْ عُرِفَ مِنْ حَالِهِ أنَّهُ لاَ يَرْوِي إلاَّ مَا سَمِعَهُ (٥). وقَدْ خَصَّصَ الخطيبُ أبو بَكْرٍ الحافِظُ القَوْلَ بحَمْلِ ذَلِكَ عَلَى السَّمَاعِ بِمَنْ عُرِفَ مِنْ عَادَتِهِ مِثْلُ ذَلِكَ (٦)، والمحفُوظُ المعْرُوفُ مَا قَدَّمْنا ذِكْرَهُ، واللهُ أعْلَمُ.","",{"fn":"بالهمزة الممدودة، والباء الموحدة، وسكون النون، وضم الدال المهملة وفي آخرها النون، هذه النسبة إلى آبندون، وهي قرية من قرى جرجان. انظر: الأنساب ١/ ٥١، ومعجم البلدان ١/ ٥٠، وترجمته في السير ١٦/ ٢٦١.\nفي (م): «عسيرًا».\n«منه» ليست في (ب).\nقال الزركشي ٣/ ٤٧٩: «خالف في ذلك أبو عبد الله بن منده، فقال في جزء له: «إن البخاري حيث قال: قال لي فلان فهو إجازة وحيث قال: قال فلان فهو تدليس»، وهذا مردود عليه، ولما ذكر أبو الحسن بن القطان تدليس الشيوخ فقال: «وأما البخاري فذاك عنه باطل ولم يصحّ قطّ عنه». وانظر: بيان الوهم والإيهام ٥/ ٤٩٩ عقب (٢٧٢١)، وشرح التبصرة والتذكرة ٢/ ٩٤ - ٩٥.\nالكفاية: (٤٢٠ ت، ٢٩٠ هـ).\nالكفاية: (٤١٨ ت، ٢٨٩ هـ)."}],[942,"القِسْمُ الثَّاني مِنْ أقْسَامِ الأَخْذِ والتَّحَمُّلِ القِرَاءَةُ عَلَى الشَّيْخِ، وأكْثَرُ المحدِّثِيْنَ يُسَمُّونَهَا: عَرْضًا، مِنْ حَيْثُ إنَّ القَارئَ يَعْرِضُ عَلَى الشَّيْخِ مَا يَقْرَؤُهُ كَمَا يَعْرِضُ القُرْآنَ عَلَى الْمُقْرِئِ. وسَوَاءٌ كُنْتَ أنْتَ القَارِئَ، أَوْ قَرَأَ غَيْرُكَ وأَنْتَ تَسْمَعُ، أَوْ قَرَأْتُ مِنْ كِتابٍ أَوْ مِنْ حِفْظِكَ، أوْ كَانَ الشَّيْخُ يَحْفَظُ مَا يُقْرَأُ عليهِ، أوْ لاَ يَحْفَظُهُ لَكِنْ يُمْسِكُ أَصْلَهُ هُوَ أوْ ثِقَةٌ غَيْرُهُ. ولاَ خِلاَفَ أنَّهَا رِوَايَةٌ صَحِيْحَةٌ (١) إلاَّ مَا حُكِيَ عَنْ بَعْضِ مَنْ لاَ يُعْتَدُّ بخِلاَفِهِ (٢)، واللهُ أعْلَمُ."],[943,"واخْتَلَفُوا في أنَّها مِثْلُ السَّمَاعِ مِنْ لَفْظِ الشَّيْخَ في المرْتَبَةِ أوْ دُوْنَهُ أوْ فَوْقَهُ، فَنُقِلَ عَنْ أبي حَنِيْفَةَ (٣)، وابنِ أبي ذِئْبٍ (٤) وغَيْرِهِما تَرْجِيْحُ القِرَاءَةِ عَلَى الشَّيْخِ عَلَى السَّمَاعِ مِنْ لَفْظِهِ (٥)، ورُوِيَ ذَلِكَ عَنْ مَالِكٍ (٦) أيْضًا، ورُوِيَ عَنْ مَالِكٍ (٧) وغيرِهِ أنَّهُما سَوَاءٌ (٨). وقَدْ قِيْلَ: إنَّ التَّسْوِيَةَ بيْنَهُما مَذْهَبُ مُعْظَمِ عُلَمَاءِ الحجَازِ والكُوفَةِ، ومَذْهَبُ مَالِكٍ وأصْحَابِهِ وأشْيَاخِهِ مِنْ عُلَمَاءِ المدينةِ، ومَذْهَبُ البخَاريِّ وغَيْرِهِمْ (٩)."],[944,"والصحيحُ تَرجيحُ السَّمَاعِ (١٠) مِنْ لَفْظِ الشَّيْخِ، والحكْمُ بأنَّ القِرَاءَةَ عليهِ مَرْتَبَةٌ ثَانيةٌ، وقَدْ قِيْلَ: إنَّ هَذَا مَذْهَبُ جُمْهُورِ أهْلِ المشْرِقِ (١١)، واللهُ أعلمُ.","",{"fn":"الإلماع: ١٠٣.\nذهب جمع من السلف إلى عدم صحة القراءة على الشيخ، منهم: أبو عاصم النبيل، وعبد الرحمان ابن سلام الجمحي، ووكيع ومحمد بن سلام، ينظر: المحدّث الفاصل: ٤٢٠، والكفاية: (٣٩٥ - ٣٩٨ ت، ٢٧١ - ٢٧٣ هـ)، والإبهاج ٢/ ٣٢٢، ونكت الزركشي ٣/ ١٧٩، وفتح المغيث ٢/ ٢٥.\nالكفاية: (٤٠٠ ت، ٢٧٦ هـ)، والإلماع: ٧٣، وفي هذين المصدرين يظهر أن لأبي حنيفة أكثر من قول.\nالمحدّث الفاصل: ٥٢٢، والكفاية (٤٤٤ ت، ٣٠٩ هـ)، والإلماع: ٧١.\nانظر: نكت الزركشي ٣/ ٤٨٠.\nالكفاية: (٤٠١ ت، ٢٧٦ هـ)، والإلماع: ٧٣.\nصحيح البخاري ١/ ٢٢، والإلماع: ٧١.\nانظر: نكت الزركشي ٣/ ٤٨١.\nانظر: معرفة علوم الحديث: ٢٥٧ - ٢٥٨، والكفاية: (٣٩٣ - ٣٩٤، ٢٧٠ - ٢٧١ هـ)، والإلماع: ٧١.\nراجع نكت الزركشي ٣/ ٤٨٢.\nالإلماع: ٧٣."}],[945,"وأمَّا العِبَارَةُ عَنْهَا عندَ الروايةِ بها فهِيَ عَلَى مَرَاتِبَ، أجْوَدُها وأسْلَمُهَا أنْ يَقُولَ: قَرَأْتُ عَلَى فُلانٍ، أوْ قُرِئَ عَلَى فُلاَنٍ وأنَا أسْمَعُ فَأَقَرَّ بهِ، فَهَذا سَائِغٌ (١) مِنْ غَيْرِ إشْكَالٍ. ويَتْلُوَ ذَلِكَ مَا يَجُوزُ مِنَ العِبَاراتِ في السَّماعِ (٢) مِنْ لَفْظِ الشَّيْخِ مُطْلَقَةً، إذا أتَى بها هَاهُنا مُقَيَّدَةً بأنْ يَقُولَ: حَدَّثَنا فُلانٌ قِرَاءَةً عليْهِ، أوْ أخْبَرَنا قِرَاءَةً عليهِ ونَحْوَ ذَلِكَ، وكَذَلِكَ: أنْشَدَنا قِرَاءَةً عليهِ في الشِّعْرِ."],[946,"وأمَّا إطْلاَقُ حَدَّثَنا، وأخْبَرَنا في القِرَاءَ ةِ عَلَى الشَّيْخِ فَقَدِ اخْتَلَفُوا (٣) فيهِ عَلَى مَذَاهِبَ:"],[947,"فَمِنْ أهْلِ الحديْثِ مَنْ مَنَعَ مِنْهُما جَمِيْعًا، وقِيْلَ: إنَّهُ قَوْلُ ابنِ المبَارَكِ (٤)، ويَحْيَى بنِ يَحْيَى التَّمِيْمِيِّ (٥)، وأحْمَدَ بنِ حَنْبَلٍ (٦)، والنَّسَائيِّ (٧)، وغَيْرِهِمْ."],[948,"ومِنْهُمْ مَنْ ذَهَبَ إلى تَجْوِيْزِ (٨) ذَلِكَ، وأنَّهُ كالسَّمَاعِ مِنْ لَفْظِ الشَّيْخِ في جَوَازِ إطْلاَقِ: حَدَّثَنا، وأخْبَرَنا، وأنْبَأَنا. وقَدْ قِيْلَ: إنَّ هذا مَذْهَبُ مُعْظَمِ الحجَازِيِّيْنَ، والكُوفِيِّيْنَ، وقَوْلُ الزُّهْرِيِّ (٩) ومَالِكٍ (١٠)، وسُفيانَ بنِ عُيَينةَ (١١)، ويَحْيَى بنِ سَعِيْدٍ القَطَّانِ (١٢) في آخَرِينَ مِنَ الأَئِمَّةِ المتَقَدِّمِيْنَ، وهوَ مَذْهَبُ البخَارِيِّ - صَاحِبِ \"الصحيحِ\" - في جَمَاعَةٍ مِنَ المحدِّثِينَ، ومِنْ هَؤُلاَءِ مَنْ أجَازَ فيها أيْضًا أنْ يَقُولَ: سَمِعْتُ فُلاَنًا (١).","",{"fn":"في (ب): «شائع».\nانظر: نكت الزركشي ٣/ ٤٨٢.\nأي: من غير تقييد بقوله: «بقراءتي»، أو قراءة عليه، وما حكاه من المنع، قال القاضي أبو بكرٍ: إنه الصحيح، وصحّحه الغزالي في المستصفى ١/ ١٦٥، والآمدي في الإحكام ٢/ ٩٠، وانظر: نكت الزركشي ٣/ ٤٨٢ - ٤٨٣.\nينظر: المحدّث الفاصل: ٤٣٤، والكفاية: (٤٣٠ ت، ٢٩٨ هـ)، والإلماع: ١٢٥.\nالإلماع: ١٢٥.\nالمحدّث الفاصل: ٤٣٤، والكفاية: (٤٣١ ت، ٢٩٩ هـ)، والإلماع: ١٢٥.\nالإلماع: ١٢٥.\nحكاه الخطيب في جامعه ٢/ ٥٠ عن أكثر أهل العلم. وانظر: نكت الزركشي ٣/ ٤٨٣.\nالمحدّث الفاصل: ٤٢٨، والكفاية: (٤٣٩ ت، ٣٠٥ - ٣٠٦ هـ)، والإلماع: ١٢٣.\nجامع بيان العلم وفضله ٢/ ٢١٨، والإلماع: ١٢٣.\nصحيح البخاري ١/ ٢٣، والمحدّث الفاصل: ٥١٨، والكفاية: (٤٢٤ت، ٢٩٣هـ)، والإلماع: ١٢٤.\nالمحدّث الفاصل: ٥٢٢، والكفاية: (٤٤٤ ت، ٣٠٩ هـ)، والإلماع: ٧١."}],[949,"والمذهَبُ الثالِثُ: الفَرْقُ بينَهُما في ذَلِكَ، والمنْعُ مِنْ إطْلاَقِ: حَدَّثَنا، وتَجْوِيْزُ إطْلاَقِ: أخْبَرَنا، وهوَ مَذْهَبُ الشَّافِعِيِّ (٢) وأصْحَابِهِ، وهوَ مَنْقُولٌ عَنْ مُسْلِمٍ - صَاحِبِ \" الصحيحِ \" (٣) -، وجمهورِ أهْلِ المشْرِقِ."],[950,"وذَكَرَ صَاحِبُ كِتَابِ \"الإنْصَافِ\" محمَّدُ بنُ الحسَنِ التَّمِيْمِيُّ الجوْهَرِيُّ (٤) المِصْرِيُّ: أنَّ هذا مَذْهَبُ الأكْثَرِ مِنْ أصْحَابِ الحدِيْثِ الذِيْنَ لاَ يُحْصِيهِمْ أحَدٌ، وأنَّهُمْ جَعَلُوا: أخْبَرَنا عَلَمًا يَقُومُ مَقَامَ قَولِ (٥) قَائِلِهِ: «أنَا قَرَأْتُهُ عَلَيْهِ لاَ أنَّهُ لَفَظَ بهِ لِي». قَالَ: «ومِمَّنْ كَانَ يَقُولُ بهِ مِنْ أهْلِ زَمَانِنا أبو عَبْدِ الرَّحْمَانِ النَّسَائِيُّ في جَمَاعَةٍ مِثْلِهِ مِنْ مُحَدِّثِيْنا»."],[951,"قُلْتُ: وَقَدْ قِيْلَ: إنَّ أوَّلَ مَنْ أحْدَثَ الفَرْقَ بينَ هَذَيْنِ اللَّفْظَيْنِ ابنُ وَهْبٍ بمِصْرَ، وهَذَا يَدْفَعُهُ أنَّ ذَلِكَ مَرْوِيٌّ عَنِ ابنِ جُرَيْجٍ، والأوْزَاعِيِّ حَكَاهُ عَنْهُمَا الخطِيْبُ أبو بَكْرٍ (٦) إلاَّ أنْ يَعْنِي أنَّهُ أوَّلُ مَنْ فَعَلَ ذَلِكَ بِمِصْرَ، واللهُ أعْلَمُ."],[952,"قُلْتُ: الفَرْقُ بَيْنَهُما صَارَ هُوَ الشَّائِعَ الغَالِبَ عَلَى أهْلِ الحدِيْثِ (٧)، والاحْتِجَاجُ لِذَلِكَ مِنْ حَيْثُ اللُّغَةُ عَنَاءٌ وتَكَلُّفٌ؛ وخَيْرُ مَا يُقَالُ فيهِ: إنَّهُ اصْطِلاَحٌ مِنْهُمْ، أرَادُوا بهِ التَّمييزَ بينَ النَّوْعَيْنِ، ثُمَّ خُصِّصَ النَّوْعُ الأوَّلُ بِقَوْلِ: «حَدَّثَنا» لِقُوَّةِ إشْعَارِهِ بالنطْقِ والمشَافَهَةِ، واللهُ أعْلَمُ (٨).","",{"fn":"قال البلقيني في المحاسن: ٢٥١: «وممن جوّز إطلاق: حدثنا في ذلك عطاء والحسن، وأبو حنيفة وصاحباه، وزفر، ومنصور».\nالمحدّث الفاصل: ٤٢٥، والكفاية: (٤٣٥ ت، ٣٠٣ هـ)، والإلماع: ٧٣ و١٢٥.\nالإلماع: ٧٣ و١٢٥.\nهو أبو بكر محمد بن الحسن بن محمد بن أحمد التميمي المصري الجوهري، كان من المعاصرين للنسائي، له كتاب \" الإنصاف فيما بين الأئمة في حدّثنا وأنبأنا من الخلاف \". ينظر: فتح المغيث ٢/ ٣١.\nلم ترد في (ب).\nالكفاية: (٤٣٤ ت، ٣٠٢ هـ).\nبعد هذا في (ب): «المتأخرين».\nجملة: «والله أعلم» لم ترد في (م)."}],[953,"ومِنْ أحْسَنِ مَا يُحْكَى عَمَّنْ يَذْهَبُ هذا المذْهَبَ (١)، مَا حَكاهُ الحافِظُ أبو بَكْرٍ البَرْقَانيُّ عَنْ أبي حاتِمٍ محمدِ بنِ يَعْقُوبَ الهَرَوِيِّ - أحَدِ رُؤَسَاءِ أهلِ الحديثِ بخُرَاسَانَ - أنَّهُ قَرَأَ عَلَى بَعْضِ الشُّيوخِ عَنِ الفِرَبْرِيِّ (٢) \" صحيحَ البخاريِّ \"، وكانَ يَقُولُ لهُ في كُلِّ حديثٍ: «حَدَّثَكُمُ الفِرَبْرِيُّ» فلَمَّا فَرَغَ مِنْ الكِتَابِ، سَمِعَ الشَّيخَ يذكُرُ أنَّهُ إنَّما سَمِعَ الكِتَابَ مِنَ الفِرَبْرِيِّ قِرَاءَةً عليهِ، فأعَادَ أبو حاتِمٍ قِرَاءةَ الكِتَابِ كُلِّهِ، وقَالَ لهُ في جميعِهِ: «أخْبَرَكُمْ الفِرَبْرِيُّ» (٣)، واللهُ أعلمُ."],[954,"تفريعات"],[955,"الأوَّلُ: إذا كانَ أصْلُ الشَّيخِ عِندَ القِرَاءَةِ (٤) عليهِ بِيَدِ غَيْرِهِ وهوَ موثُوقٌ بهِ، مُرَاعٍ لِمَا يَقْرَأُ، أهْلٌ لذلِكَ، فإنْ كانَ الشَّيْخُ يَحْفَظُ ما يُقْرَأُ عليهِ فهوَ كَمَا لَوْ كَانَ أصْلُهُ بِيَدِ نَفْسِهِ، بَلْ أوْلَى لِتَعَاضُدِ ذِهْنَي شَخْصَيْنِ عليهِ، وإنْ كَانَ الشَّيْخُ لاَ يَحْفَظُ ما يُقْرَأُ عليهِ، فهذَا مِمَّا اختَلَفُوا فيهِ: فَرَأَى بعضُ أئِمَّةِ الأُصُولِ (٥) أنَّ هَذَا سَمَاعٌ غَيرُ صَحيحٍ، والمخْتَارُ أنَّ ذَلِكَ صَحيحٌ وبهِ عَمِلَ مُعْظَمُ الشُّيوخِ وأهْلِ الحديثِ. وإذا كانَ الأصْلُ بِيَدِ القَارِئِ وهوَ موثُوقٌ بهِ دِيْنًا ومَعْرِفَةً، فكذَلِكَ الحكْمُ فيهِ، وأوْلَى بالتَّصْحِيْحِ، وأمَّا إذا كَانَ أصْلُهُ بِيَدِ مَنْ لاَ يُوثَقُ بإمْسَاكِهِ لهُ، ولاَ يُؤْمَنُ إهْمَالُهُ لِمَا يَقْرَأُ، فَسَوَاءٌ كَانَ بِيَدِ القَارِئِ أوْ بِيَدِ غَيْرِهِ في أنَّهُ سَمَاعٌ غَيْرُ مُعْتَدٍّ به إذَا كانَ الشَّيخُ غَيرَ حافِظٍ للمَقْرُوءِ عليهِ، واللهُ أعلمُ.","",{"fn":"شكك الزركشي في هذه القصة في نكته ٣/ ٤٨٦ - ٤٨٧ ثم قال: «فكأن هذه الحكاية لم تصحّ». وانظر: محاسن الاصطلاح ٢٥٢ - ٢٥٣، وفتح المغيث ١/ ٤١٨.\nهو أبو عبد الله، محمد بن يوسف بن مطر الفِرَبْرِيُّ، راوي الجامع الصحيح عن البخاري، توفي سنة (٣٢٠ هـ). قال صاحب الأنساب ٤/ ٣٣٤ عن الفِرَبْرِيُّ: «بفتح الفاء والراء، وسكون الباء الموحدة وبعدها راء أخرى. هذه النسبة إلى فربر، وهي بلدة على طرف جيحون مما يلي بخارى»، ومثل هذا في وفيات الأعيان ٤/ ٢٩٠. وفي التاج ١٣/ ٣١١: «فِرَبْر، كِسَبْحل، وضُبِط بالفتح أيضًا، وذكر الحافظ في التبصير الوجهين»، وبالوجهين في سير أعلام النبلاء ١٥/ ١٢، ومعجم البلدان ٤/ ٢٤٥.\nهذه القصة في الكفاية: (٤٣٦ ت، ٣٠٣ - ٣٠٤ هـ)، وانظر: محاسن الاصطلاح ٢٥٢ - ٢٥٣.\nانظر التقييد والإيضاح: ١٧١.\nهذا الأصولي، هو أبو بكر الباقلاني ووافقه إمام الحرمين. الإلماع: ٧٥، والبرهان ١/ ٤١٣. قال الزركشي ٣/ ٤٨٨ «والعجب من المصنف في عزوه ذلك لبعض الأصوليين، وقد نقله الحاكم عن مالك وأبي حنيفة»."}],[956,"الثَّاني: إذا قَرَأَ القارِئُ على الشَّيْخِ قَائِلًا: أخْبَرَكَ فُلاَنٌ، أوْ قُلْتَ أخْبَرَنا فُلاَنٌ، أوْ نَحْوَ ذلكَ؛ والشَّيْخُ سَاكِتٌ مُصْغٍ إليهِ، فاهِمٌ لذَلِكَ، غَيرُ مُنْكِرٍ لهُ، فَهَذا كَافٍ في ذلكَ. واشْتَرطَ بعضُ الظَّاهِرِيَّةِ وغيرُهُمْ إقْرَارَ الشَّيْخِ نُطْقًا (١)، وبهِ قَطَعَ الشَّيخُ (٢) أبو إسْحاقَ الشِّيرازيُّ (٣)، وأبو الفتْحِ سُلَيْمٌ الرَّازيُّ، وأبو نَصْرَ بنُ الصَّبَّاغِ مِنَ الفُقَهَاءِ الشَّافِعِيِّيْنَ. قالَ أبو نَصْرٍ: لَيْسَ لَهُ أنْ يَقُولَ: «حدَّثَنِي» أو «أخْبَرَنِي» (٤)، ولهُ أنْ يَعْمَلَ بما قُرِئَ عليهِ، وإذا أرادَ روايَتَهُ عنهُ قَالَ: «قَرَأْتُ عليهِ، أوْ قُرِئَ عليهِ وهوَ يَسْمَعُ». وفي حِكَايةِ بَعضِ المصَنِّفِيْنَ للخِلاَفِ في ذَلِكَ أنَّ بعضَ الظَّاهِرِيَّةِ شَرَطَ إقْرَارَ الشَّيْخِ عِنْدَ تَمامِ السَّماعِ، بأنْ يَقُولَ القَارِئُ للشَّيْخِ: «هوَ (٥) كَما قَرَأْتُهُ عليكَ؟»، فيقولُ: «نَعَمْ». والصحيحُ أنَّ ذلِكَ غَيْرُ لاَزِمٍ، وأنَّ سُكُوتَ الشَّيْخِ عَلَى الوجْهِ المذكُورِ نازِلٌ مَنْزِلَةَ تَصْرِيْحِهِ بتَصْدِيْقِ القَارِئِ اكْتِفَاءً بالقَرَائِنِ الظَّاهِرَةِ، وهذا مَذْهَبُ الجماهِيْرِ مِنَ المحَدِّثِيْنَ والفُقَهَاءِ وغَيْرِهِمْ، واللهُ أعلمُ."],[957,"الثَّالِثُ: فيمَا نَرْوِيهِ عَنِ الحاكِمِ أبي عبدِ اللهِ الحافِظِ (٦) -رحمه الله- قالَ: «الذي أخْتَارُهُ في الروايةِ وعَهِدْتُ عليهِ أكثرَ مَشَايِخِي وأئِمَّةَ عَصْرِي أنْ يَقُولَ في الذي يأخُذُهُ مِنَ المحدِّثِ لَفْظًا وليْسَ مَعَهُ أحَدٌ «حَدَّثَنِي فُلانٌ»، وما يأخُذُهُ مِنَ المحَدِّثِ لَفْظًا ومعهُ غيرُهُ"],[958,"«حَدَّثَنا فُلاَنٌ». ومَا قَرَأَ عَلَى المحدِّثِ بنفسِهِ: «أخْبَرَنِي فُلاَنٌ»، وما قُرِئَ عَلَى المحدِّثِ وهوَ حَاضِرٌ «أخْبَرَنا فُلاَنٌ» (٧)."],[959,"وقَدْ رُوِّيْنا نَحْوَ مَا ذَكَرَهُ عَنْ عَبدِ اللهِ بنِ وَهْبٍ -صَاحِبِ مالِكٍ رضي الله عنهما- وهوَ حَسَنٌ رَائقٌ.","",{"fn":"في (ب): «مطلقًا».\nلم ترد في (أ).\nاللمع: ٤٨.\nقال الزركشي في النكت ٣/ ٤٨٩: «ما قاله ابن الصبّاغ من أنه لا يطلق: «حدّثنا»، ولا: «أخبرنا»، هو الصحيح عند الغزالي، وحكاه الآمدي عن المتكلمين وصحّحه وحكى تجويزه عن الفقهاء والمحدّثين، وصحّحه ابن الحاجب وحكاه عن الحاكم أنه مذهب الأئمة الأربعة، وبقيت هنا مسألة ملحّة: وهو أن يشير الشيخ بأصبعه أو رأسه إلى الإقرار ولا يتلفّظ، فجزم صاحب المحصول بأنه لا نقول في الأداء: حدَّثني ولا أخبرني ولا سمعت، وفيه نظر». وانظر: المستصفى ١/ ١٦٥، والإحكام ٢/ ٩٠ - ٩١، والمحصول ٤/ ٦٤٦.\nفي (م): «وهو».\nانظر: نكت الزركشي ٣/ ٤٩٠.\nمعرفة علوم الحديث: ٢٦٠."}],[960,"فإنْ شَكَّ في شيءٍ عندَهُ أنَّهُ مِنْ قَبيلِ: «حَدَّثَنا أو أخْبَرَنا» (١)، أو مِنْ قَبيلِ: «حدَّثني أو أخْبَرني» لتَرَدُّدِهِ في أنَّهُ كَانَ عِندَ التَّحَمُّلِ والسَّماعِ وحْدَهُ أو مَعَ غيرِهِ فَيَحْتَمِلُ أنْ نَقُولَ: ليقُلْ: «حَدَّثَني أو أخْبَرني»؛ لأنَّ عَدَمَ غَيْرِهِ هوَ الأَصْلُ. ولكِنْ ذَكَرَ عليُّ بنُ عبدِ اللهِ المدينيُّ الإمَامُ عَنْ شَيْخِهِ يَحْيَى بنِ سَعِيْدٍ القَطَّانِ الإمامِ، فِيْمَا إذا شَكَّ أنَّ الشَّيْخَ قالَ:"],[961,"«حَدَّثَني فُلاَنٌ»، أو قَالَ: «حَدَّثَنا فلانٌ» أنَّهُ يَقُولُ: «حَدَّثَنا»، وهذا يقتَضِي فيما إذا شَكَّ في سَماعِ نفْسِهِ في مِثلِ ذلكَ أنْ يَقُولَ: «حَدَّثَنا»."],[962,"وهو عِندي يَتَوَجَّهُ بأنَّ «حَدَّثَني» أكْمَلُ مَرْتَبَةً، و«حَدَّثَنا» أنقَصُ مَرْتَبةً، فَلْيَقْتًصِرْ - إذا شَكَّ - على الناقِصِ؛ لأنَّ عدمَ الزَّائِدِ هوَ الأصْلُ وهذا لَطِيْفٌ."],[963,"ثُمَّ وَجَدْتُ (٢) الحَافِظَ أحمدَ البَيْهَقيَّ - رحمه الله - قدِ اخْتَارَ بَعْدَ حِكَايَتِهِ قَوْلَ القَطَّانِ مَا قَدَّمْتُهُ."],[964,"ثُمَّ إنَّ هذا التفصيلَ مِنْ أصْلِهِ مُسْتَحَبٌّ، وليسَ بواجِبٍ، حكاهُ الخطيبُ الحافِظُ عَنْ أهلِ العِلْمِ كَافَةً (٣)، فَجَائِزٌ إذا سَمِعَ وَحْدَهُ أنْ يَقُولَ: «حدَّثَنا» أو نحوَهُ لِجَوَازِ ذَلِكَ للواحِدِ في كَلاَمِ العرَبِ، وجَائِزٌ إذا سَمِعَ في جَمَاعَةٍ أنْ يَقُولَ: «حَدَّثَني»؛ لأنَّ المحدِّثَ حَدَّثَهُ وحدَّثَ غَيْرَهُ، واللهُ أعلمُ."],[965,"الرَّابِعُ: رُوِّيْنا عَنْ أبي عبدِ اللهِ أحمدَ بنِ حَنْبَلٍ - رضي الله عنه - أنَّهُ قالَ (٤): اتَّبِعْ لَفْظَ الشَّيْخِ في قَوْلِهِ: «حَدَّثَنا، وحَدَّثَني، وسَمِعْتُ، وأخْبَرَنا»، ولاَ تَعْدُهُ (٥)."],[966,"قُلْتُ: لَيسَ لكَ فيما تَجدُهُ في الكُتُبِ المؤَلَّفَةِ مِنْ رِوَاياتِ (٦) مَنْ تَقَدَّمَكَ أنْ تُبَدِّلَ في نَفْسِ الكِتَابِ مَا قِيْلَ فيهِ: «أخْبَرَنا» بـ «حَدَّثَنا» ونحوِ ذلكَ، وإنْ كَانَ في إقَامَةِ أحدِهِما مَقَامَ الآخَرِ خِلاَفٌ وتَفْصِيلٌ سَبَقَ؛ لاحْتِمَالِ أنْ يَكُونَ مَنْ قَالَ ذَلِكَ مِمَّنْ لاَ يَرى التَّسْوِيةَ بَيْنَهُما، ولَوْ وَجَدْتَ مِنْ ذَلِكَ إسْنادًا عَرَفَتْ مِنْ مَذْهَبِ رجالِهِ التَّسْوِيةَ بَيْنَهُما فإِقَامَتُكَ أحدَهُما مَقَامَ الآخَرِ مِنْ بَابِ تجويزِ الرواية بالمعنَى. وذلكَ وإنْ كانَ فيهِ خِلاَفٌ مَعْرُوفٌ، فالذي نَرَاهُ: الامتناعُ مِنْ إجراءِ مِثلِهِ في إبْدَالِ مَا وُضِعَ في الكُتُبِ المصَنَّفَةِ والمجامِعِ المجموعةِ عَلى ما سَنَذْكُرُهُ إنْ شَاءَ اللهُ تَعَالَى. ومَا ذَكَرَهُ الخطيبُ أبو بكرٍ في \" كِفايتِهِ \" (١) مِنْ إجْرَاءِ ذَلِكَ الخِلاَفِ (٢) في هذا، فَمَحْمُولٌ عندَنا علَى مَا يَسْمَعُهُ الطَّالِبُ مِنْ لَفْظِ المحدِّثِ غيرَ موضوعٍ في كِتابٍ مُؤَلَّفٍ، واللهُ أعلمُ.","",{"fn":"انظر: نكت الزركشي ٣/ ٤٩١، والتقييد: ١٧٢.\nفي (ب): «وجدنا».\nالكفاية: (٤٢٥ ت، ٢٩٤ هـ)، قال الزركشي في نكته ٣/ ٤٩٢: «في نقل الإجماع نظر، قال ابن فارس: وهذا تشديد لا وجه له».\nالكفاية: (٤٢٣ ت، ٢٩٣ هـ).\nفي (أ) و(م) والتقييد والشذا: «تعدوه»، وكلاهما في (ج)، وفي حاشية (م) توجيه قوله (تعدوه) - أي: بإثبات الواو - بأن (لا): نافية، وليست ناهية.\nانظر: التقييد والإيضاح: ١٧٤ - ١٧٦."}],[967,"الخامِسُ: اخْتَلَفَ أهْلُ العِلْمِ في صِحَّةِ سَمَاعِ مَنْ يَنْسَخُ وَقْتَ القِرَاءَةِ (٣)، فَورَدَ عَنِ الإمامِ إبْرَاهِيمَ الحرْبِيِّ (٤)، وأبي أحمدَ بنِ عَدِيٍّ الحافِظِ (٥)، والأسْتَاذِ أبي إسْحَاقَ الإسْفِرَايِيْنِيِّ الفقيهِ الأُصُوليِّ وغيرِهِمْ نَفْيُ ذَلِكَ. وَرُوِّيْنا عَنْ أبي بَكْرٍ أحمدَ ابنِ إسْحَاقَ الصِّبْغِيِّ (٦) - أحَدِ أئِمَّةِ الشَّافِعِيِّيْنَ بِخُرَاسَانَ - أنَّهُ سُئِلَ عَمَّنْ يكتُبُ في السَّمَاعِ؟ فقَالَ: يَقُولُ: «حَضَرْتُ»، ولاَ يَقُلْ: «حَدَّثَنا، ولاَ أخْبَرَنا» (٧). ووَرَدَ عَنْ مُوسَى بنِ هَارُونَ الحمَّالِ تَجْويْزُ ذَلِكَ (٨). وَعَنْ أبي حاتِمٍ الرَّازِيِّ قَالَ: «كَتَبْتُ عِندَ عَارِمٍ (٩) وهوَ يَقْرَأُ، وكَتَبْتُ عِنْدَ عَمْرِو بنِ مَرْزُوقٍ وهوَ يَقْرَأُ». وعَنْ عَبدِ اللهِ بنِ المبَارَكِ أنَّهُ قُرِئَ عليهِ وهوَ يَنْسَخُ شَيْئًا آخَرَ غَيْرَ مَا يُقْرَأُ (١). ولاَ فَرْقَ بَيْنَ النَّسْخِ مِنَ السَّامِعِ والنَّسْخِ مِنَ المسْمِعِ.","",{"fn":"الكفاية: (٤٢٢ ت، ٢٩٢ هـ).\nانظر: نكت الزركشي ٣/ ٤٩٢.\nانظر: نكت الزركشي ٣/ ٤٩٤.\nرواه عنه الخطيب في الكفاية: (١٢٠ ت، ٦٦ هـ).\nرواه عنه الخطيب في الكفاية: (١٢٠ ت، ٦٦ هـ).\nبكسر الصاد المهملة، وسكون الباء المنقوطة بواحدة، وفي آخرها الغين المعجمة، هذه النسبة إلى الصِّبْغِ - الذي تُلَوَّنُ به الثِّياب -. وهو أبو بكر، أحمد بن إسحاق بن أيوب النيسابوري، توفي سنة (٣٤٢ هـ). انظر: الأنساب ٣/ ٥٣٠، وسير أعلام النبلاء ١٥/ ٤٨٣، والتاج ٢٢/ ٥١٤.\nرواه عنه الخطيب في الكفاية (١٢٠ ت، ٦٦ هـ).\nانظر: الروايات عنه في الكفاية (١٢٢ ت، ٦٧ - ٦٨ هـ).\nهو الحافظ: أبو النعمان محمد بن الفضل السدوسي البصري، توفي سنة (٢٢٤ هـ). انظر: الأنساب ٤/ ٨٨، والسير ١٠/ ٢٦٥."}],[968,"قُلْتُ: وخَيْرٌ مِنْ هذا الإطْلاَقِ: التفصِيْلُ، فَنَقُولُ: لاَ يَصِحُّ السَّمَاعُ إذا كَانَ النَّسْخُ بحَيْثُ يَمْتَنِعُ مَعَهُ فَهْمُ النَّاسِخِ لِمَا يُقْرَأُ، حَتَّى يَكُونَ الواصِلُ إلى سمْعِهِ كأنَّهُ صَوْتٌ غُفْلٌ، ويَصِحُّ إذا كَانَ بحيثُ لاَ يَمْتَنِعُ معَهُ الفَهْمُ، كَمِثْلِ ما رُوِّيْنا (٢) عَنِ الحَافِظِ العَالِمِ أبي الحسَنِ الدَّارقطنيِّ أنَّهُ حَضَرَ في حَدَاثَتِهِ مَجْلِسَ إسْمَاعِيْلَ الصَّفَّارِ فَجَلَسَ يَنْسَخُ جُزْءًا كَانَ مَعَهُ وإسْمَاعِيْلُ يُمْلِي، فَقَالَ لهُ بعضُ الحاضِرِيْنَ: «لاَ يَصِحُّ سَمَاعُكَ وأنْتَ تَنْسَخُ!»، فقالَ: «فَهْمِي للإمْلاَءِ خِلاَفُ فَهْمِكَ، ثُمَّ قَالَ: تَحْفَظُ كَمْ أمْلَى الشَّيْخُ مِنْ حديثٍ إلى الآنَ؟»، فقالَ: لاَ، فقالَ الدَّارقطنيُّ: «أمْلَى ثَمَانِيَةَ عَشَرَ حديثًا»، فَعُدَّتِ الأحاديثُ فَوُجِدَتْ كَمَا قَالَ. ثُمَّ قَالَ أبو الحسَنِ: «الحديثُ الأوَّلُ مِنْها عَنْ فُلاَنٍ، عَنْ فُلاَنٍ، ومَتْنُهُ كذا، والحديثُ الثاني عَنْ فُلاَنٍ، عَنْ فُلاَنٍ، ومَتْنُهُ كذا»، ولَمْ يَزَلْ يَذْكُرُ أسَانِيْدَ الأحاديثِ ومُتُونَها عَلَى ترْتِيبِها في الإمْلاَءِ حَتَّى أتَى عَلَى آخِرِهَا، فَتَعَجَّبَ النَّاسُ منهُ واللهُ أعلمُ."],[969,"السَّادِسُ: ما ذَكَرْناهُ في النَّسْخِ مِنَ التَّفْصِيلِ يَجْرِي مِثْلُهُ فيما إذا كَان الشَّيْخُ أو السَّامِعُ يَتَحَدَّثُ، أوْ كَانَ القَارِئُ خَفِيْفَ القِرَاءَةِ يُفْرِطُ (٣) في الإسْرَاعِ، أوْ كَانَ يُهَيْنِمُ (٤) بحيثُ يَخْفَى بعضُ الكَلِمِ (٥)، أوْ كَانَ السَّامِعُ بَعِيْدًا عَنِ القَارِئِ، ومَا أشْبَهَ ذَلِكَ."],[970,"ثُمَّ الظَّاهِرُ أنَّهُ يُعْفَى في كُلِّ ذَلِكَ عَنِ القَدْرِ اليَسِيْرِ، نحوِ الكَلِمَةِ والكَلِمَتَيْنِ. ويُسْتَحَبُّ للشَّيْخِ أنْ يُجِيْزَ لِجَمِيْعِ السَّامِعينَ (٦) روايَةَ جَمِيْعِ الجزْءِ أو الكِتابِ الذي سَمِعُوهُ وإنْ جَرَى عَلَى كُلِّهِ اسمُ السَّماعِ. وإذَا بَذَلَ لأحَدٍ مِنْهُمْ خَطَّهُ بذلِكَ كَتَبَ لهُ (١) «سَمِعَ مِنِّي هذا الكِتَابَ وأجَزْتُ لهُ روايَتَهُ عَنِّي» أو نحوَ هذا كَما كَانَ بعضُ الشُّيوخِ يَفعَلُ. وفيما نَرْويهِ عَنِ الفقيهِ أبي محمَّدِ بنِ أبي عبدِ اللهِ بنِ عَتَّابٍ الفقِيْهِ الأنْدلسيِّ، عَنْ أبيهِ","",{"fn":"الكفاية: (١٢١ ت، ٦٧ هـ).\nهذه الرواية في تاريخ بغداد ١٢/ ٣٤ - ٣٦، وسير أعلام النبلاء ١٦/ ٤٥٣.\nيقال: أفرط في الأمر، أي: جاوز فيه الحدّ، وفرط: قصَّر. انظر: الصحاح ٣/ ١١٤٨.\nيقال: هَيْنَمَ فلانٌ: تَكلَّمَ وأخْفَى كَلاَمَه، والهَيْنَمةُ: الصوتُ الخفي أو الكلام الخفي. انظر: لسان العرب ١٢/ ٦٢٤، والمعجم الوسيط ٢/ ٩٩٧.\nانظر: نكت الزركشي ٣/ ٤٩٦ - ٤٩٧.\nانظر: نكت الزركشي ٣/ ٤٩٧ - ٤٩٩."}],[971,"-رَحِمَهُما اللهُ- أنَّهُ قَالَ: «لاَ غِنى في السَّماعِ عَنِ الإجَازةِ؛ لأنَّهُ قَدْ يَغْلَطُ القَارئُ ويَغْفُلُ الشَّيْخُ، أو يَغْلَطُ الشَّيْخُ إنْ كَانَ القارئَ، ويَغْفُلُ السَّامِعُ، فَيَنْجَبِرُ لهُ ما فاتَهُ بالإجَازةِ» (٢)."],[972,"هَذَا الذي ذَكَرْناهُ تحقيقٌ حَسَنٌ، وقَدْ رُوِّيْنا عَنْ صَالِحِ بنِ أحمدَ بنِ حَنْبَلٍ قالَ: قُلْتُ لأبي: «الشَّيْخُ يُدْغِمُ الحرفَ يُعْرَفُ أنَّهُ كذا وكذا، ولاَ يُفْهَمُ عنهُ، تَرَى أنْ يُرْوَى ذَلِكَ عنهُ؟ قالَ: أَرْجُو ألاَّ يُضَيَّقَ هَذَا» (٣). وبَلَغَنا عَنْ خَلَفِ بنِ سَالمٍ الْمُخَرَّمِيِّ (٤)، قالَ: سَمِعْتُ ابنَ عُيَينةَ يَقُولُ: نا عَمْرُو بنُ دِيْنارٍ، يُرِيْدُ: حدَّثَنا عَمْرُو بنُ دِيْنارٍ، لكِنِ اقْتَصَرَ مِنْ «حَدَّثَنا» على النونِ والألفِ، فإذا قِيْلَ لهُ قُلْ: حدَّثَنا عَمْرٌو، قالَ: لاَ أقُولُ؛ لأنِّي لَمْ أسْمَعْ مِنْ قَولِهِ: حَدَّثَنا ثَلاَثَةَ أحرفٍ، وهيَ حَدَثَ؛ لِكَثْرَةِ الزِّحَامِ (٥)."],[973,"قُلْتُ: قَدْ كَانَ كَثيرٌ مِنْ أكَابِرِ المحدِّثِينَ يَعْظُمُ الجمْعُ في مجالَسِهِمْ جِدًّا حَتَّى رُبَّمَا بَلَغَ أُلُوفًا مُؤَلَّفَةً، ويُبَلِّغَهُمْ عَنْهُمُ المسْتَمْلُونَ، فيَكْتُبُونَ عَنْهُمْ بوَاسِطَةِ تَبْلِيْغِ المسْتَمْلِينَ، فأجازَ غيرُ واحِدٍ لَهُمْ روايةَ ذلكَ عَنِ الممْلِي."],[974,"رُوِّيْنَا عَنِ الأعْمشِ - رضي الله عنه - قالَ: «كُنَّا نَجْلِسُ إلى إبرَاهِيمَ فتَتَّسِعُ الحلقَةُ فَرُبَّما يُحَدِّثُ بالحدِيْثِ فَلاَ يَسْمَعُهُ مَنْ تَنَحَّى عنهُ، فيَسْأَلُ بَعْضُهُمْ بَعْضًا عَمَّا قالَ، ثُمَّ يَرْوونَهُ، ومَا سَمِعُوهُ مِنْهُ» (٦). وعَنْ حَمَّادِ بنِ زَيدٍ أنَّهُ سَأَلَهُ رَجُلٌ في مِثْلِ ذَلِكَ فقَالَ: «يا أبا إسْمَاعِيْلَ كَيْفَ قُلْتَ؟ فقالَ: اسْتَفْهِمْ مَنْ يَلِيْكَ» (١). وعَنِ ابنِ عُيَينةَ أنَّ أبا مُسْلِمٍ المسْتَمْلِي قالَ لهُ: «إنَّ النَّاسَ كَثِيْرٌ لاَ يَسْمَعُونَ»، قالَ: «تَسْمَعُ (٢) أنتَ؟»، قالَ:","",{"fn":"في (م): «كتب له أنه سمع ...».\nأسنده القاضي عياض في الإلماع: ٩٢.\nالكفاية: (١٢٤ ت، ٦٨ - ٦٩ هـ).\nبضم الميم وفتح المعجمة وتشديد الراء. التقريب (١٧٣٢)، والخلاصة: ١٠٦.\nالكفاية: (١٢٥ ت، ٦٩ هـ)، وانظر: محاسن الاصطلاح: ٢٥٩.\nالكفاية: (١٢٩ ت، ٧٢ هـ)."}],[975,"«نَعَمْ»، قالَ: «فَأَسْمِعْهُمْ» (٣)."],[976,"وأبَى آخَرُونَ ذَلِكَ. رُوِّيْنا عَنْ خَلَفِ بنِ تَميمٍ، قالَ: سَمِعْتُ مِنْ سُفْيَانَ الثَّوْرِيِّ عَشْرَةَ آلاَفِ حديثٍ أوْ نَحْوَها، فكنْتُ أسْتَفْهِمُ جَلِيْسِي، فَقُلْتُ لِزَائِدَةَ؟ فقَالَ لي: «لاَ تُحَدِّثْ مِنْهَا إلاَّ بما تَحْفَظُ بقَلْبِكَ وسَمْعِ أُذُنِكَ»، قالَ: «فألْقَيْتُها» (٤). وعَنْ أبي نُعَيْمٍ أنَّهُ كَانَ يَرَى - فيما سَقَطَ عنهُ مِنَ الحرفِ الواحدِ والاسمِ مِمَّا سَمِعَهُ مِنْ سُفْيانَ والأعْمَشِ، واسْتَفْهَمَهُ مِنْ أصْحَابِهِ - أنْ يَرْوِيَهُ عَنْ أصْحَابِهِ لاَ يَرَى غَيْرَ ذَلِكَ واسِعًا لهُ (٥)."],[977,"قُلْتُ: الأوَّلُ تَساهُلٌ بَعِيْدٌ، وقَدْ رُوِّيْنا عَنْ أبي عَبْدِ اللهِ بنِ مَنْده الحافِظِ الأصبهانيِّ أنَّهُ قالَ لواحِدٍ مِنْ أصحابِهِ: «يا فُلانُ، يَكْفِيكَ مِنَ السَّماعِ شَمُّهُ»، وهذا إمَّا مُتَأَوَّلٌ أو مَتْرُوكٌ عَلَى قَائِلِهِ. ثُمَّ وَجَدْتُ عَنْ عَبدِ الغَنِيِّ بنِ سَعيدٍ (٦) الحافِظِ، عَنْ حَمزَةَ بنِ محمَّدٍ الحافِظِ بإسْنادِهِ، عَنْ عبدِ الرَّحمانِ بنِ مَهدِيٍّ، أنَّهُ قالَ: «يَكْفِيْكَ منَ الحديثِ شَمُّهُ» (٧). قالَ عبدُ الغنيِّ: قالَ لنا حَمْزَةُ: «يعني: إذا سُئِلَ عَنْ أوَّلِ شَيءٍ عَرَفَهُ، وليسَ يَعْنِي التَّسَهُّلَ في السَّماعِ» (٨)، واللهُ أعلمُ.","",{"fn":"الكفاية: (١٢٧ ت، ٧١ هـ).\nما أثبتناه من جميع النسخ و(م)، وفي (ع): «أتسمع».\nالكفاية: (١٢٧ - ١٢٨ ت، ٧٢ هـ).\nالمحدّث الفاصل: ٣٨٥، والكفاية: (١٢٦ ت، ٧٠ هـ).\nالكفاية: (١٢٩ ت، ٧٣ هـ).\nفي (ج): «سعد» خطأ.\nانظر: شرح التبصرة والتذكرة ٢/ ١٢٥، والنكت الوفية ٢٥٣ / أ.\nانظر: شرح التبصرة والتذكرة ٢/ ١٢٥."}],[978,"السَّابِعُ: يَصِحُّ السَّماعُ مِمَّنْ هُوَ وراءَ حِجَابٍ (١)، إذا عُرِفَ صَوْتُهُ فيما إذا حَدَّثَ بلفْظِهِ، أو إذا عُرِفَ حُضُورُهُ بِمَسْمَعٍ مِنْهُ فيما إذا قُرِئَ عليهِ. ويَنْبَغِي أنْ يَجوزَ الاعْتِمادُ في مَعْرِفَةِ صَوْتِهِ وحضُورِهِ علَى خَبَرِ مَنْ يُوثَقُ بهِ. وقَد (٢) كانُوا يَسْمَعُونَ مِنْ عائِشَةَ وغَيرِها مِنْ أزْوَاجِ رسُولِ اللهِ (٣) - صلى الله عليه وآله وسلم - مِنْ وَرَاءِ حِجَابٍ، ويَرْوونَهُ عَنْهُنَّ اعتِمَادًا عَلَى الصَّوْتِ. واحْتَجَّ عبدُ الغَنيِّ بنُ سَعِيدٍ الحافِظُ في ذلكَ بقولِهِ - صلى الله عليه وآله وسلم -: «إنَّ بلاَلًا يُنَادي بِلَيْلٍ فَكُلُوا واشْرَبُوا حَتَّى يُناديَ ابنُ أُمِّ مَكْتُومٍ» (٤)، ورَوَى بإسْنَادِهِ عَنْ شُعْبَةَ أنَّهُ قَالَ: إذا حَدَّثَكَ المحدِّثُ فَلَمْ تَرَ وَجْهَهُ فَلاَ تَرْوِ عنهُ، فَلَعَلَّهُ شَيْطَانٌ قَدْ تَصَوَّرَ في صُورَتِهِ، يَقُولُ: «حَدَّثَنا وأخْبَرَنا» (٥). واللهُ أعلمُ."],[979,"الثَّامِنُ: مَنْ سَمِعَ مِنْ شَيْخٍ حديثًا ثُمَّ قالَ لهُ: لاَ تَرْوِهِ (٦) عَنِّي، أو: لاَ آذَنُ لَكَ في روايتِهِ عَنِّي، أو قالَ: لسْتُ أُخْبِرُكَ (٧) بهِ، أو رَجَعْتُ عَنْ إخْبَارِي إيَّاكَ بهِ، فلاَ تَرْوِهِ عَنِّي غَيرَ مُسْنِدٍ ذَلِكَ إلى أنَّهُ أخطأَ فيهِ، أوْ شَكَّ فيهِ ونحوِ ذَلِكَ، بلْ منَعَهُ مِنْ رِوَايتِهِ عنهُ مَعَ جَزْمِهِ بأنَّهُ حديثُهُ وروايتُهُ (١)، فذلِكَ غيرُ مُبْطلٍ لِسَماعِهِ، ولاَ مانِعٌ لهُ مِنْ روايتِهِ عنهُ (٢).","",{"fn":"انظر: نكت الزركشي ٣/ ٤٩٩.\nسقطت من (ع)، وهي ثابتة في جميع النسخ و(م).\nفي (أ): «النبي».\nأخرجه البخاري ١/ ١٦٠ و١٦١ و٣/ ٣٧ و٢٢٥ و٩/ ١٠٧، ومسلم ٢/ ٣ و٣/ ١٢٩. وأخرجه مالك (١٩٤)، والشافعي ٢/ ٢٧٥، والطيالسي (١٨١٩)، وعبد الرزاق (١٨٨٥)، والحميدي (٦١١)، وابن أبي شيبة ٣/ ٩، وأحمد ٢/ ٩ و١٢٣، وعبد بن حميد (٧٣٤)، والدارمي (١١٩٢)، والترمذي (٢٠٣)، والنسائي ٢/ ١٠، وأبو يعلى (٥٤٣٢)، وابن خزيمة (٤٠١)، والطحاوي في شرح المعاني ١/ ١٣٧، وابن حبان (٣٤٦٩)، والطبراني في الكبير (١٣١٠٦) والبيهقي ١/ ٣٨٠، والبغوي (٤٣٤).\nأسنده الرامهرمزي في المحدّث الفاصل: ٥٩٩، وابن عدي في مقدمة الكامل ١/ ١١٧. قال ابن كثير في \"اختصار علوم الحديث\": ١١٨: «هذا عجيب وغريب جدًا». وقال الزركشي في نكته ٣/ ٤٩٩: «إن فيه نظرًا؛ لأن الشيطان إذا جاز أن يتصور بصورة الإنسان فسواء وَرَاء حجاب أو مُشَافَهَة».\nقال الزركشي في نكته ٣/ ٥٠٠: «هذا ذكره الأئمة، منهم: ابن خلاّد في كتاب الفاصل وقال القاضي عياض رحمه الله تعالى: لا يقتضي النظر سواه؛ لأن منعه ألاَّ يحدِّث بما حدّثه به لا لعلة ولا لريبة في الحديث لا تؤثر؛ لأنه قد حدّثه فهو شيء لا يرجع فيه - قال -: ولا أعلم من قال بخلاف هذا، إلاَّ أن صاحب طبقات علماء إفريقية روى عن شيخ من جلة شيوخها، أنه أشهد بالرجوع عمَّا حدّثه لبعض أصحابه لأمر نقمه عليه، وكذلك فعل الفقيه المحدّث أبو بكر بن عطية؛ فإنه أشهد بالرجوع عمَّا حدّث به بعض أصحابه لهوى ظهره له منه. ولعل هذا صدر منهم تأديبًا لا لأنهم اعتقدوا صحة تأثيره، وقياس من قاس الإذن في الحديث وعدمه على الإذن في الشهادة وعدمها غير صحيح؛ لأن الشهادة على الشهادة لا تصح إلا مع الإشهاد، والإذن في الحديث لا يحتاج معه إلى ذلك باتفاق».\nفي (أ): «أجيزك»."}],[980,"وسَأَلَ الحافِظُ أبو سَعْدِ بنُ عَلِيَّكٍ (٣) النَّيْسَابُوريُّ الأسْتَاذَ أبا إسْحَاقَ الإسْفِرايِينِيَّ"],[981,"- رَحِمَهُما اللهُ - عَنْ مُحَدِّثٍ خَصَّ بالسَّمَاعِ قومًا، فَجَاءَ غيرُهُمْ وَسَمِعَ منهُ مِنْ غَيرِ عِلْمِ المحدّثِ بهِ، هلْ يَجُوزُ لهُ روايةُ ذلكَ عنهُ؟ فأجابَ بأنَّهُ يَجُوزُ، ولوْ قالَ المحدِّثُ: إنِّي أُخْبِرُكُمْ ولاَ أُخْبِرُ فُلاَنًا، لَمْ يَضُرَّهُ، واللهُ أعلمُ."],[982,"القِسْمُ الثَّالِثُ مِنْ أقْسَامِ طُرُقِ نَقْلِ الحدِيْثِ وَتَحَمُّلِهِ: الإجَازَةُ (٤)"],[983,"وهِيَ مُتَنوِّعَةٌ أنواعًا:"],[984,"أوَّلُها: أنْ يُجِيزَ لِمُعَيَّنٍ في مُعَيَّنٍ، مِثْلُ أنْ يَقُولَ: أجَزْتُ لَكَ الكِتَابَ الفُلاَنِيَّ، أو ما اشْتَمَلَتْ عليهِ فِهْرِستِي هذهِ، فهَذا أعلَى أنواعِ الإجَازةِ المجَرَّدَةِ عَنِ المنَاوَلَةِ. وزَعَمَ بَعْضُهُمْ (٥) أنَّهُ لاَ خِلاَفَ في جَوَازِهَا وَلاَ خَالَفَ فيها أهلُ الظَّاهِرِ، وإنَّمَا خِلاَفُهُمْ في غيرِ هذا النوعِ. وزادَ القاضِي أبو الوليدِ الباجِيُّ المالِكِيُّ فأطْلَقَ (٦) نَفْيَ الخِلاَفِ وقالَ: «لاَ خِلاَفَ في جَوازِ الروايةِ بالإجازَةِ مِنْ سَلَفِ هذهِ الأُمَّةِ وخَلَفِها»، وادَّعَى الإجماعَ مِنْ غَيْرِ تَفْصِيْلٍ، وحَكَى الخِلاَفَ في العَمَلِ بها (١).","",{"fn":"عبارة: «وروايته» سقطت من (م).\nينظر: المحدّث الفاصل: ٤٥١ - ٤٥٢، والكفاية: (٤٩٨ - ٤٩٩ ت، ٣٤٨ - ٣٤٩ هـ) والإلماع: ١١٠.\nهو الحافظ: أبو سعد، عبد الرحمان بن الحسين بن عليك النيسابوري، توفي سنة (٤٣١ هـ). سير أعلام النبلاء ١٧/ ٥٠٩، وقد حصل خلاف في ضبط لفظة (عليك) انظره في الإكمال ٦/ ٢٦٢، وتبصير المنتبه ٣/ ٩٦٦، ونزهة الألباب ٢/ ٣٥، وذكر من يعتمد قوله في الجرح والتعديل: ١٨٢ حاشية المحقق، وما أثبتناه هو أحد تلك الوجوه.\nانظر عن اشتقاق لفظ الإجازة، ومعانيها اللغوية: مقاييس اللغة ١/ ٤٩٤، ونكت الزركشي ٣/ ٥٠٢، وشرح التبصرة ٢/ ١٥٨، والنكت الوفية: ٢٦٠ / ب، وتاج العروس ١٥/ ٧٥، وحاشية توضيح الأفكار ٢/ ٣٠٩.\nهو القاضي عياض حكى ذلك في الإلماع: ٨٨.\nراجع: نكت الزركشي ٣/ ٥٠٢ - ٥٠٦."}],[985,"قُلْتُ: هذا باطِلٌ، فقَدْ خالَفَ في جَوَازِ الروايَةِ بالإجَازَةِ جَماعاتٌ مِنْ أهْلِ الحديثِ والفُقَهاءِ والأُصُوليينَ، وذلكَ إحْدَى الروايتَيْنِ عَنِ الشَّافِعِيِّ - رضي الله عنه - (٢)، رُويَ عَنْ صاحِبِهِ الرَّبيعِ بنِ سُلَيمانَ، قالَ: «كانَ الشَّافِعِيُّ لاَ يَرَى الإجَازَةَ في الحديثِ. قالَ الربيعُ: أنَا أُخَالِفُ الشَّافِعِيَّ (٣) في هذا». وقدْ قَالَ بإبْطَالِها جَمَاعةٌ مِنَ الشَّافِعِيِّينَ، منهُم: القَاضِيانِ حُسَيْنُ (٤) بنُ محمَّدٍ الْمَرْوَرُّوذِيُّ (٥)، وأبو الحسَنِ الماوَرْدِيُّ (٦) - وبهِ قَطَعَ الماوَرْدِيُّ في كتابِهِ \"الحَاوِي\" (٧) وعَزَاهُ إلى مَذْهَبِ الشَّافِعِيِّ - وقَالاَ جَمِيْعًا: «لَوْ جَازَتِ الإجَازَةُ لَبَطَلَتِ الرِّحْلَةُ». ورُوِيَ أيضًا هذا الكَلامُ عَنْ شُعْبَةَ (٨) وغيرِهِ."],[986,"ومِمَّنْ أبْطَلَها مِنْ أهْلِ الحديثِ الإمامُ إبْرَاهيمُ بنُ إسْحَاقَ الحربِيُّ (٩)، وأبو محمَّدٍ عبدُ اللهِ بنُ محمَّدٍ الأصْبَهانيُّ الملقَّبُ بـ: (أبي الشَّيْخِ) (١٠)، والحافِظُ أبو نَصْرٍ الوائِلِيُّ السِّجْزِيُّ. وحَكَى أبو نَصْرٍ فَسَادَها عَنْ بَعْضِ مَنْ لَقِيَهُ. قَالَ أبو نَصْرٍ: وسَمِعْتُ جَماعَةً مِنْ أهلِ العِلْمِ يَقُولُونَ: قَولُ المحدِّثِ: «قَدْ أجَزْتُ لَكَ أنْ تَرْوِيَ عَنِّي»، تَقْدِيْرُهُ: قَدْ أجَزْتُ لَكَ مَا لاَ يَجُوزُ في الشَّرْعِ؛ لأنَّ الشَّرْعَ لاَ يُبِيحُ روايةَ مَا لَمْ يَسْمَعْ (١).","",{"fn":"الإلماع: ٨٩.\nانظر: الكفاية: (٤٥٥ ت، ٣١٧ هـ)، والبحر المحيط ٤/ ٣٩٧.\nانظر: محاسن الاصطلاح: ٢٦٢.\nفي (م): «حسن» خطأ.\nنسبة إلى مَرْوَرُّوذ - بفتح الميم وسكون الراء المهملة، وفتح الواو وتشديد الراء المهملة المضمومة، وبعد الواو ذال معجمة -، وهي من أشهر مدن خراسان. انظر: وفيات الأعيان ١/ ٦٩، والأنساب ٥/ ١٤٥.\nبفتح الميم وسكون الألف وفتح الواو وسكون الراء، وفي آخرها دال مهملة، وهذه النسبة إلى بيع ماء الورد وعمله. انظر: الأنساب ٥/ ٦١، واللباب ٣/ ١٦٥.\nانظر: الحاوي ٢٠/ ١٤٦، وأدب القاضي، له ١/ ٣٨٧ - ٣٨٩، وروضة الطالبين ١١/ ١٥٧.\nمذهب شعبة في المنع حكاه الخطيب في الكفاية: (٤٥٤ ت، ٣١٦ هـ).\nالكفاية: (٤٥٣ ت، ٣١٥ - ٣١٦ هـ).\nالكفاية: (٤٥٤ - ٤٥٥ ت، ٣١٦ هـ)."}],[987,"قُلْتُ: ويُشْبِهُ هذا ما حَكَاهُ أبو بَكْرٍ محمَّدُ بنُ ثَابِتٍ الخُجَنْدِيُّ (٢) - أحَدُ مَنْ أبْطَلَ الإجازَةَ مِنَ الشَّافِعِيَّةِ - عَنْ أبي طَاهِرٍ الدَّبَّاسِ (٣) - أحَدِ أئِمَّةِ الحنَفِيَّةِ - قالَ: مَنْ قَالَ لِغَيْرِهِ: «أجَزْتُ لَكَ أنْ تَرْوِيَ عَنِّي مَا لَمْ تَسْمَعْ؛ فكأنَّهُ يَقُولُ: «أجَزْتُ لَكَ أنْ تَكْذبَ عَليَّ» (٤)."],[988,"ثُمَّ إنَّ الذي اسْتَقَرَّ عليهِ العَمَلُ، وقَالَ بهِ جَماهِيْرُ أهْلِ العِلْمِ مِنْ أهْلِ الحديثِ وغَيْرِهِمْ: القَوْلُ بتَجْويزِ الإجَازَةِ وإباحَةِ الروايَةِ بها (٥)، وفي الاحْتِجَاجِ لِذَلِكَ غُمُوضٌ. ويَتَّجهُ أنْ نَقُولَ: إذا أجازَ لهُ أنْ يَرْوِيَ عنهُ مَرْوِيَّاتِهِ فَقَدْ (٦) أخْبَرَهُ بها جُمْلَةً، فَهوَ كَمَا لوْ أخْبَرَهُ تَفْصِيْلًا، وإخْبَارُهُ بِهَا غَيْرُ مُتَوَقِّفٍ عَلَى التَّصْرِيْحِ نُطْقًا كَمَا في القِرَاءَةِ علَى الشَّيْخِ -كَما سَبَقَ -، وإنَّما الغَرَضُ حُصُولُ الإفْهَامِ والفَهْمِ وذَلِكَ يَحْصلُ بالإجازَةِ الْمُفْهِمَةِ، واللهُ أعلمُ.","",{"fn":"قال الزركشي ٣/ ٥٠٦: «وهذه مصادفة على المطلوب؛ لأن الذي يبيح الإجازة والرواية بالإجازة يمنع هذه المقدمة، وهذا عين النِّزاع الذي جعله السجزي دليلًا على منع الرواية بالإجازة، وهذا القول خارج من دأب العلماء».\nبضم الخاء المعجمة وفتح الجيم وسكون النون. انظر: الأنساب ٢/ ٣٧٧.\nمن قوله: «أحد من» إلى هنا سقط كله من (م).\nنقله الزركشي في البحر المحيط ٤/ ٣٩٦ وقال في النكت ٣/ ٥٠٧: «وهذا القول فيه نظر؛ لأن للإجازة والرواية شروطًا من تصحيح الخبر من المجيز بحيث يوجد في أصل صحيح سماعه عليه الموجز سماعًا منه من الشيوخ مع رعاية جميع شروط الرواية، وليس المراد بالإجازة الرواية عنه مطلقًا سوى عرف رواية الخبر عن المجيز به لا بل لا تجوز الرواية عن المجيز إلا بعد محض سماعه أو إما يوصي له بهذا الجزء وحفظه، فلا تكون الرواية عنه إذنًا في الكذب عليه».\nقال الإمام النووي في الإرشاد ١/ ٢٧١: «والمذهب الصحيح الذي استقرَّ عليه العمل، وقال به جماهير العلماء من المحدثين وغيرهم، جواز الرواية بها»، وذكر الخطيب أسماء كثير من العلماء الذين حكى عنهم الجواز في كفايته: (٤٤٩ - ٤٥٠ ت، ٣١٣ - ٣١٤ هـ). ونقل الزركشي في نكته ٣/ ٥٠٧ عن ابن منده في جزء الإجازة عن الزهري وابن جريج ومالك بن أنس والأوزاعي وأحمد بن حنبل، ثم نقل عن ابن منده قوله: «فهؤلاء أهل الآثار الذين اعتمد عليهم في الصحيح رأوا الإجازة صحيحة واعتدّوا بها ودوّنوها في كتبهم».\nفي (م): «وقد»."}],[989,"ثُمَّ إنَّهُ كَمَا تَجُوزُ الروايَةُ بالإجَازَةِ، يَجِبُ العَمَلُ بالْمَرْوِيِّ بها، خِلاَفًا لِمَنْ قَالَ مِنْ أهْلِ الظَّاهِرِ ومَنْ تابَعَهُمْ: إنَّهُ لاَ يَجِبُ العَمَلُ بهِ، وإنَّهُ جَارٍ مَجْرَى المرْسَلِ. وهذا باطِلٌ؛ لأنَّهُ لَيْسَ في الإجازَةِ مَا يَقْدَحُ في اتِّصَالِ المنْقُولِ بِهَا وَفِي الثِّقَةِ بهِ، واللهُ أعلمُ."],[990,"النَّوْعُ الثَّاني مِنْ أنواعِ الإجازَةِ: أنْ يُجِيْزَ لِمُعَيَّنٍ في غَيرِ مُعَيَّنٍ، مِثلُ أنْ يَقُولَ:"],[991,"«أجَزْتُ لَكَ، أو لَكُمْ جَمِيْعَ مَسْمُوعَاتي، أو جَمِيْعَ مَرْوِيَّاتِي»، وما أشْبَهَ ذَلِكَ، فالخِلاَفُ في هذا النوعِ أقْوَى وأكثَرُ. والجمهُورُ مِنَ العُلَماءِ مِنَ المحدَّثِينَ والفُقَهَاءِ وغَيْرِهِمْ عَلَى تَجْوِيْزِ الروايَةِ بها أيضًا، وعَلَى إيجابِ العَمَلِ بما رُوِيَ بها بِشَرْطِهِ (١)، واللهُ أعلمُ."],[992,"النَّوعُ الثَّالِثُ مِنْ أنواعِ الإجَازَةِ: أنْ يُجِيْزَ لغَيْرِ مُعَيَّنٍ بِوَصْفِ العُمُومِ، مِثْلُ أنْ يَقُولَ: «أجَزْتُ لِلْمُسْلِمِينَ، أوْ أجَزْتُ لِكُلِّ أحَدٍ (٢)، أوْ أجَزْتُ لِمَنْ أدْرَكَ زَمَانِي»، ومَا أشْبَهَ ذَلِكَ، فَهذا نَوعٌ تَكَلَّمَ فيهِ المتأخِّرُونَ مِمَّنْ جَوَّزَ أصْلَ الإجَازَةِ واخْتَلَفُوا في جَوَازِهِ: فإنْ كَانَ ذَلكَ مُقَيَّدًا بوَصْفٍ حاصِرٍ (٣) أوْ (٤) نحوِهِ فَهوَ إلى الجوَازِ أقرَبُ. ومِمَّنْ جَوَّزَ ذَلِكَ كُلَّهُ أبو بَكْرٍ الخطِيْبُ الحافِظُ (٥). ورُوِّيْنا عَنْ أبي عَبْدِ اللهِ بنِ مَنْدَه الحَافِظِ أنَّهُ قالَ: «أجَزَتُ لِمَنْ قَالَ لاَ إلَهَ إلاَّ اللهُ». وجَوَّزَ القَاضِي أبو الطَّيِّبِ الطَّبَرِيُّ"],[993,"- أحَدُ الفُقَهَاءِ المحَقِّقِيْنَ - فيما حَكَاهُ عنهُ الخطيبُ - الإجازَةَ لِجَميعِ المسلمينَ مَنْ كَانَ منهُمْ مَوْجُودًا عِندَ الإجَازَةِ (٦). وأجَازَ أبو محمَّدِ بنُ سَعِيْدٍ - أحَدُ الجِلَّةِ (٧) مِنْ شُيُوخِ الأندلسِ - لِكُلِّ مَنْ دَخَلَ قُرْطُبَةَ مِنْ طَلَبَةِ العِلْمِ (١). ووافَقَهُ عَلَى جَوَازِ ذلكَ جَماعَةٌ، منهُمْ: أبو عبدِ اللهِ بنِ عَتَّابٍ (٢) - رضي الله عنهم -. وأنْبَأَنِي مَنْ سَأَلَ الحازِمِيَّ (٣) أبا بَكْرٍ عَنِ الإجَازَةِ العَامَّةِ هذهِ فَكَانَ مِنْ جَوَابِهِ أنَّ مَنْ أدْرَكَهُ مِنَ الْحُفَّاظِ نحوُ أبي العَلاءِ الحافِظِ وغيرِهِ كَانُوا يَمِيلُونَ إلى الجوازِ، واللهُ أعلمُ.","",{"fn":"البحر المحيط ٤/ ٣٩٩ - ٤٠٠.\nفي الشذا: «واحد»، وقد سقطت عبارة: «أجزت للمسلمين» منه.\nفي (ب): «حاصل»، وفي (ج): «خاص حاضر».\nفي (ع): «ونحوه».\nفي (م): «الخطيب الحافظ أبو بكر».\nينظر: الإجازة للمعدوم والمجهول: ٨٠، والإلماع: ٩٨.\nيقال: قومٌ جِلَّةٌ، أي: سادة عظماء ذوو أخطار، ومشيخةٌ جِلَّةٌ، أي: مسانُّ، انظر: اللسان ١١/ ١١٧، ومتن اللغة ١/ ٥٥٨."}],[994,"قُلْتُ: وَلَمْ نَرَ ولَمْ نَسْمَعْ عَنْ أحَدٍ مِمَّنْ يُقْتَدَى بهِ أنَّهُ اسْتَعْملَ (٤) هذهِ الإجَازَةَ فَرَوَى بها، ولاَ عَنِ الشِّرْذِمَةِ (٥) المسْتَأْخِرَةِ الذينَ سَوَّغُوها، والإجازَةُ في أصْلِهَا ضَعْفٌ، وتَزْدادُ بهذا التَّوسُّعِ والاسْتِرْسَالِ ضَعْفًا كَثِيْرًا لاَ يَنْبَغِي احْتِمَالُهُ (٦)، واللهُ أعلمُ."],[995,"النَّوْعُ الرَّابِعُ مِنْ أنواعِ الإجَازَةِ: الإجازَةُ لِلْمَجْهُولِ أو بالمجْهُولِ ويَتَشَبَّثُ (٧) بذَيْلِها الإجَازَةُ المعَلَّقَةُ بالشَّرْطِ، وذَلِكَ مثلُ أنْ يَقُولَ: أجَزْتُ لمحمَّدِ بنِ خالِدٍ الدِّمَشْقِيِّ (٨)، وفي وَقْتِهِ ذلكَ جماعَةٌ مُشْتَرِكُونَ في هذا الاسمِ والنَّسَبِ، ثُمَّ لاَ يُعَيِّنُ المجازُلهُ منْهُمْ، أويَقُولَ: أجَزْتُ لِفُلاَنٍ أنْ يَرْوِيَ عَنِّي كِتَابَ السُّنَنِ، وهوَ يَرْوِي جماعَةً مِنْ كُتُبِ السُّنَنِ المعرُوفَةِ بذَلِكَ ثُمَّ (٩) لاَ يُعَيِّنُ. فَهَذِهِ إجَازَةٌ فاسِدَةٌ لاَ فَائِدَةَ لَهَا (١٠). وَلَيْسَ مِنْ هَذَا القَبِيْلِ مَا إذا أجَازَ لجماعَةٍ مُسَمَّيْنَ مُعَيَّنِينَ بأنْسَابِهِمْ، والمجيزُ جاهِلٌ بأعْيَانِهِمْ غيرُ عارِفٍ بهِمْ فهذا غيرُ قادِحٍ، كما لاَ يَقْدَحُ عَدَمُ مَعْرِفَتِهِ بهِ إذا حَضَرَ شَخْصُهُ في السَّمَاعِ منهُ، واللهُ أعلمُ.","",{"fn":"الإلماع: ٩٩.\nالإلماع: ٩٩.\nقال الزركشي في نكته ٣/ ٥١٧: «يشير إلى أبي عبد الله محمد بن سعيد الدبيثي، فإنه كتب إلى الحافظ أبي بكر الحازمي فسأله عن الرواية بالإجازة العامة وكيف يقول من أحب الرواية بها؟ فأجاب: «هذا مما وقع في كلام المتأخرين، ولم أرَ في اصطلاح المتقدمين من ذلك شيئًا» ثم ساق كلام الحازمي بطوله.\nناقش العراقي المصنف في هذا نقاشًا مستفيضًا في كتابه التقييد ١٨٢ - ١٨٣.\nالشِّرذمة: تطلق على القليل من الناس. انظر: مقاييس اللغة ٣/ ٢٧٣، والمستأخر نقيض المستقدم. اللسان ٤/ ١٢.\nقال العراقي في شرح التبصرة ٢/ ١٣٣: «ممن أجازها أبو الفضل أحمد بن الحسين بن خيرون البغدادي، وأبو الوليد بن رشيد المالكي، وأبو طاهر السلفي، وغيرهم. ورجَّحه أبو عمرو بن الحاجب، وصحَّحه النووي من زياداته في \" الروضة \"، وقد جمع بعضهم من أجاز هذه الإجازة العامة في تصنيف له، جمع فيه خلقًا كثيرًا رتبهم على حروف المعجم؛ لكثرتهم». وانظر: منتهى الوصول: ٨٣، وروضة الطالبين ١١/ ١٥٨.\nفي (م) والشذا: «تتشبث».\nفي تاريخ دمشق ٥٢/ ٣٧٩ - ٣٩١ جماعة باسم محمد بن خالد الدمشقي فانظره إن شئت.\n«ثم»: ساقطة من (م).\nتبعه النووي، كما في زوائده على الروضة ١١/ ١٥٨."}],[996,"وإنْ أجازَ لِلْمُسَمَّينَ (١) المنتَسِبينَ في الاسْتِجَازَةِ (٢)، ولَمْ يَعْرِفْهُمْ بأعْيَانِهِمْ ولاَ بأنْسَابِهِمْ، ولَمْ يَعْرِفْ عدَدَهُمْ ولَمْ يَتَصَفَّحْ أسْمَاءهُمْ واحِدًا فَوَاحِدًا، فينبَغِي أنْ يَصِحَّ ذَلِكَ أيْضًا، كما يَصِحُّ سَمَاعُ مَنْ حَضَرَ مَجْلِسَهُ للسَّماعِ منهُ، وإنْ لَمْ يَعْرِفْهُمْ أصْلًا ولَمْ يَعْرِفْ عَدَدَهُمْ ولاَ تَصَفَّحَ أشْخَاصَهُمْ واحِدًا واحِدًا."],[997,"وإذا قَالَ: أجَزْتُ لِمَنْ يَشَاءُ فُلاَنٌ، أو نحوَ ذَلِكَ، فهَذا فيهِ جهالةٌ وتَعْلِيقٌ بشَرْطٍ، فالظَّاهِرُ أنَّهُ لاَ يَصِحُّ، وبذَلِكَ أفْتَى القَاضِي أبو الطَّيِّبِ الطَّبَرِيُّ الشَّافِعِيُّ إذْ سَأَلَهُ الخطِيْبُ الحافِظُ عَنْ ذَلِكَ، وعَلَّلَ بأنَّهُ إجَازَةٌ لمجْهُولٍ، فَهوَ كَقَوْلِهِ: أجَزْتُ لِبَعْضِ النَّاسِ، مِنْ غَيْرِ تَعْيينٍ، وقَدْ يُعَلَّلُ ذَلِكَ أيضًا بما فيها مِنَ التَّعليقِ بالشَّرْطِ، فإنَّ مَا يَفْسُدُ (٣) بالجهالَةِ يَفْسُدُ (٤) بالتَّعليقِ، عَلَى مَا عُرِفَ عِنْدَ قَومٍ."],[998,"وحَكَى الخطيبُ عَنْ أبي يَعْلَى بنِ الفرَّاءِ الحنبَلِيِّ، وأبي الفَضْلِ بنِ عُمْرُوسٍ (٥) المالِكِيِّ: أنَّهُما أجَازَا ذَلِكَ، وهَؤُلاَءِ الثَّلاَثَةُ كَانُوا مَشَايِخَ مَذَاهِبِهِمْ ببَغَدَادَ إذْ ذَاكَ (٦). وهذهِ الجهالَةُ [الواقِعَةُ] (٧) تَرتَفِعُ في ثاني الحالِ عندَ وُجُودِ المشِيْئَةِ، بخلاَفِ الجهالَةِ الواقِعَةِ فيما إذا أجازَ لِبَعْضِ النَّاسِ. وإذا قالَ: أجَزْتُ لِمَنْ شَاءَ فَهوَ كَما لَوْ قَالَ: أجَزْتُ لِمَنْ شَاءَ فُلاَنٌ، بلْ هذهِ أكْثَرُ جَهَالَةً وانتِشَارًا مِنْ حَيْثُ إنَّهَا مُعَلَّقَةٌ بمَشيئةِ مَنْ لاَ يُحْصَرُ عَدَدُهُمْ بخِلاَفِ تِلْكَ. ثُمَّ هذا فيما إذا أجازَ لِمَنْ شَاءَ الإجَازَةَ منهُ لهُ.","",{"fn":"في (أ) و(ب): «المسلمين».\nفي (م): «الإجازة».\nفي (م): «يفسر».\nكذلك.\nعُمْرُوْس: ضبطه السمعاني في الأنساب ٤/ ٢١٠ - بفتح العين، ومثله في فتح المغيث ٢/ ٨١ وفتح الباقي ٢/ ٧٠، وضبطه الفيروزآبادي بضمّها، ثمَّ قالَ: وفتحه من لحن الْمُحَدِّثين. انظر: القاموس المحيط مع شرحه تاج العروس ١٦/ ٢٨١، وراجع ترجمة ابن عمروس في سير أعلام النبلاء ١٨/ ٧٣.\nالإجازة للمعدوم والمجهول: ٨١، وانظر: الإلماع: ١٠٢.\nمن نسخة (ب) فقط."}],[999,"فإنْ أجازَ لِمَنْ شَاءَ الروايَةَ عنهُ فهذا أوْلَى بالجوَازِ (١) مِنْ حيثُ إنَّ مُقْتَضَى كُلِّ إجَازَةٍ تَفْوِيْضُ الروايةِ بها إلى مَشيئةِ الْمُجَازِ لهُ، فَكَانَ هذا مَعَ كَوْنِهِ بصِيْغَةِ التَّعْلِيقِ، تَصْرِيْحًا بما يَقْتَضِيْهِ الإطْلاَقُ، وحِكَايَةً للحالِ لاَ تَعْلِيقًا في الحقيقَةِ. ولِهَذَا أجازَ بَعْضُ أئِمَّةِ الشَّافِعيِّيْنَ في البيعِ أنْ يَقُولَ: بِعْتُكَ هذا بكَذا إنْ شِئْتَ، فيقولُ: قَبِلْتُ (٢). وَوُجِدَ بخَطِّ الشَّيْخِ أبي الفَتْحِ محمَّدِ بنِ الحسَيْنِ الأَزْدِيِّ الموْصِلِيِّ الحافِظِ: أجزْتُ رِوايةَ ذَلِكَ لِجَميعِ مَنْ أحَبَّ أنْ يَرْوِيَ ذَلِكَ (٣) عَنِّي. أمَّا إذا قالَ: أجزْتُ لفُلاَنٍ كَذا وكَذا إنْ شَاءَ روايتَهُ عَنِّي، أو لَكَ إنْ شِئْتَ، أوْ أحْبَبْتَ، أوْ أرَدْتَ، فالأظْهَرُ الأَقْوَى أنَّ ذَلِكَ جَائِزٌ (٤)، إذْ قَدِ انْتَفَتْ فيهِ الجهَالَةُ وحقيقةُ التَّعليقِ، ولمْ يَبْقَ سِوَى صِيغَتِهِ، والعِلْمُ عِنْدَ اللهِ تَعَالَى."],[1000,"النَّوْعُ الْخَامِسُ مِنْ أنْوَاعِ الإجَازَةِ: الإجازَةُ للمَعْدُومِ، ولنذْكُرْ مَعَهُ (٥) الإجازةَ للطفْلِ الصغيرِ. هذا نوعٌ خاضَ فيهِ قومٌ مِنَ المتأخِّرِيْنَ واخْتلَفُوا في جَوازِهِ. ومِثَالُهُ أنْ يَقُولَ (٦): أجزْتُ لِمَنْ يُولَدُ لِفُلاَنٍ، فَإنْ عَطَفَ المعْدُومَ في ذلكَ علَى الموجودِ بأنْ قَالَ: أجَزْتُ لِفُلاَنٍ ومَنْ (٧) يُولَدُ لهُ أوْ أجَزْتُ لَكَ ولِوَلَدِكَ وعَقِبِكَ (٨) مَا تَنَاسَلُوا، كَان ذَلِكَ أقربَ إلى الجوَازِ مِنَ الأوَّلِ.","",{"fn":"انظر: التقييد: ١٨٥.\nراجع: نكت الزركشي ٣/ ٥٢٢، والتقييد والإيضاح: ١٨٥، وشرح التبصرة والتذكرة ٢/ ١٤١، وقارن بـ: فتح العزيز ٨/ ١٠٥، والمجموع ٩/ ١٧٠، ومغني المحتاج ٢/ ٢٣٤.\nلم ترد في (أ) و(ب).\nقال الزركشي في نكته ٣/ ٥٢٢: «هذا نظير مسألة البيع كما سبق، وبها يعتضد وجه الصحة هنا، وحكى ابن الأثير في مقدمة جامع الأصول في هذه الحالة خلافًا، قال: فمنع منها قوم؛ لأنها تحتمل فيعتبر فيه تعيين المجمل -قال- وهذا هو الأخذ بالاحتياط، والأولى بنجابة المحدّث وحفظه»، وانظر: جامع الأصول١/ ٨٣.\nفي (م): «معها».\nفي (م): «تقول».\nفي (ع): «ولمن»، وما أثبتناه من النسخ و(م).\nفي (ع): «ولعقبك»."}],[1001,"ولِمِثْلِ ذَلِكَ أجَازَ أصحَابُ الشَّافِعِيِّ في الوقْفِ (١) القسمَ الثانيَ دُونَ الأوَّلِ. وقدْ أجَازَ أصْحابُ مالِكٍ، وأبي حنيفةَ أوْ مَنْ قَالَ ذَلِكَ منْهُمْ -في الوقْفِ القسمينِ كِليهِما (٢) -. وَفَعَلَ هذا الثانيَ في الإجَازَةِ مِنَ المحدِّثينَ المتقدِّمينَ: أبو بكرٍ بنُ أبي دَاوُدَ السِّجْستانيُّ، فإنَّا رُوِّيْنا عنهُ أنَّهُ سُئِلَ الإجَازَةَ فقالَ: «قَدْ أجَزْتُ لَكَ ولأوْلاَدِكَ ولِحَبَلِ الْحَبَلَةِ»، يَعني: الذينَ لَمْ يُوْلَدُوا بَعْدُ (٣).","",{"fn":"قال الزركشي في نكته ٣/ ٥٢٣: «ولا حاجة إلى هذا، فالشافعي نفسه أجازه، ونص عليه في وصيته المكتتبة في الأم، فأوصى فيها أوصياء على أولاده الموجودين، ومن يحدثه الله تعالى له من الأولاد». وانظر: محاسن الاصطلاح: ٢٧١.\nانظر: الإجازة للمعدوم والمجهول: ٨١، والإلماع: ١٠٥.\nالكفاية: (٤٦٥ ت، ٣٢٥ هـ)، والإجازة للمعدوم والمجهول: ٧٦ ومن طريقه أورده الْقَاضِي عِيَاض في الإلماع: ١٠٥، قَالَ البلقيني في محاسن الاصطلاح: ٢٧١: «يحتمل أن يَكُوْن ذَلِكَ عَلَى سبيل المبالغة وتأكيد الإجازة، لا أن المراد بِهِ حقيقة اللفظ»."}],[1002,"وأمَّا الإجازَةُ للمَعْدُومِ ابْتِدَاءً مِنْ غَيْرِ عَطْفٍ عَلَى موجُودٍ، فقدْ أجَازَها الخطيبُ أبو بَكْرٍ الحافِظُ (١)، وذَكَرَ أنَّهُ سَمِعَ أبا يَعْلَى بنَ الفرَّاءِ الحنْبَليَّ، وأبا الفَضْلِ بنَ عُمْرُوْسٍ المالِكِيَّ يُجِيزانِ ذَلِكَ (٢). وحَكَى جَوازَ ذَلِكَ أيضًا أبو نَصْرِ بنُ الصَّبَّاغِ الفقيهُ (٣)، فقالَ: «ذَهَبَ قومٌ إلى أنَّهُ يَجُوزُ أنْ يُجِيزَ لِمَنْ لَمْ يُخْلَقْ»، قالَ: «وهَذَا إنَّما ذهَبَ إليهِ مَنْ يَعْتَقِدُ أنَّ الإجَازَةَ إذْنٌ في الروايَةِ، لاَ مُحَادَثَةٌ». ثُمَّ بَيَّنَ بُطْلاَنَ هذهِ الإجازَةِ، وهوَ الذي اسْتَقَرَّ عليهِ رَأْيُ شيخِهِ القاضِي أبي الطَّيِّبِ الطَّبَرِيِّ الإمَامِ (٤)، وذلكَ هُوَ الصحيحُ الذي لاَ يَنْبَغِي غَيْرُهُ؛ لأنَّ الإجازَةَ في حُكْمِ الإخْبَارِ جُمْلَةً بالْمُجَازِ عَلَى مَا قَدَّمناهُ في بيانِ صِحَّةِ أصْلِ الإجَازَةِ، فكما لاَ يَصِحُّ الإخْبَارُ للْمَعْدُومِ لاَ تَصِحُّ الإجازةُ للمعدومِ. ولَوْ قَدَّرنا أنَّ الإجازةَ إذْنٌ فَلاَ يَصِحُّ أيضًا ذلكَ للمعدومِ، كما لاَ يَصِحُّ الإذْنُ في بابِ الوكَالَةِ للمعْدُومِ؛ لوقُوعِهِ في حالَةٍ لاَ يَصِحُّ فِيْهَا المأذُونُ فيهِ مِنَ المأْذُونِ لهُ."],[1003,"وهَذَا أيضًا يُوجِبُ بُطْلاَنَ الإجَازَةِ للطِّفْلِ الصَّغِيْرِ الذي لاَ يَصِحُّ سَمَاعُهُ. قالَ الخطيبُ: «سألْتُ القاضِي أبا الطَّيِّبِ الطَّبَرِيَّ عَنِ الإجَازَةِ للطِّفْلِ الصَّغِيْرِ هَلْ يُعْتَبَرُ في صِحَّتِها سِنُّهُ أوْ تَمْييزُهُ (٥)، كَمَا يُعْتَبَرُ ذلكَ في صِحَّةِ سَمَاعِهِ؟ فقالَ: لاَ يُعْتَبَرُ ذَلِكَ. قَالَ: فَقُلْتُ لهُ: إنَّ بعضَ أصْحَابِنا قالَ: لاَ تَصِحُّ الإجَازَةُ لِمَنْ لاَ يَصِحُّ سَمَاعُهُ. فقَالَ: قَدْ يَصِحُّ أنْ يُجِيْزَ للغائِبِ عنهُ، ولاَ يَصِحُّ السَّماعُ لهُ» (١). واحْتَجَّ الخطِيبُ لِصَحَّتِها للطِّفْلِ بأنَّ الإجَازَةَ إنَّما هيَ إباحَةُ الْمُجِيْزِ للْمُجَازِ لهُ أنْ يَرْوِيَ عنهُ، والإباحَةُ تَصِحُّ للعاقِلِ وغيرِ العاقِلِ (٢).","",{"fn":"الكفاية: (٤٦٦ ت، ٣٢٥ - ٣٢٦ هـ)، والإجازة للمعدوم والمجهول: ٨١.\nالإجازة للمعدوم والمجهول: ٨١، والإلماع: ١٠٢.\nانظر: البحر المحيط ٤/ ٤٠١.\nالكفاية: (٤٦٦ ت، ٣٢٥ هـ)، والإجازة للمعدوم والمجهول: ٨٠.\nقال الزركشي في نكته ٣/ ٥٢٣: «وهذه المسألة منصوصة للشافعي فيما سبق عن الحافظ السِّلفي بسنده إلى الربيع أن الشافعي أتاه رجل يطلب الإجازة لابنه، فقال: كم لابنك؟ قال: ست سنين، قال: لا يجوز الإجازة له حتى يبلغ له سبع سنين. قال ابن زبر: وهو مذهب في الإجازة، قال السلفي: والذي أدركنا عليه الشيوخ في البلاد والحفّاظ أن الإجازة تصح لمن يجاز له صغيرًا كان أو كبيرًا»."}],[1004,"قَالَ: وعَلَى هذا رأيْنا كَافَّةَ شُيُوخِنا يُجِيزُونَ للأطْفَالِ الغُيَّبِ عَنْهُمْ، مِنْ غَيْرِ أنْ يَسْألُوا عَنْ مَبْلَغِ أسْنَانِهِمْ وحالِ تَمْييزِهِمْ، ولَمْ نَرَهُمْ أجَازُوا لِمَنْ لَمْ يَكُنْ مَوْلودًا في الحالِ (٣)."],[1005,"قُلْتُ (٤): كأنَّهُمْ رَأَوا الطِّفْلَ أهْلًا لِتَحَمُّلِ هذا النَّوْعِ مِنْ أنواعِ تَحَمُّلِ الحديثِ؛ لِيُؤَدِّيَ بهِ بَعْدَ حُصُولِ أهْلِيَّتِهِ، حِرْصًا عَلَى توسِيْعِ السبيلِ إلى بقاءِ الإسْنادِ الذي اخْتَصَّتْ بهِ هذهِ الأُمَّةُ، وتَقْريبِهِ (٥) مِنْ رَسُولِ اللهِ - صلى الله عليه وآله وسلم -، واللهُ أعْلَمُ (٦)."],[1006,"النَّوْعُ السَّادِسُ مِنْ أنواعِ الإجَازَةِ: إجازةُ مَا لَمْ يَسْمَعْهُ الْمُجِيْزُ ولَمْ يَتَحَمَّلْهُ أصْلًا بَعْدُ لِيَرْوِيَهُ المجازُ لهُ إذا تَحَمَّلَهُ المجيزُ بعدَ ذلكَ. أخْبَرَنِي مَنْ أُخْبِرَ عَنِ القَاضِي عِياضِ بنِ مُوْسَى - مِنْ فُضَلاَءِ وَقْتِهِ بالمَغْرِبِ -، قَالَ: «هذا لَمْ أرَ مَنْ تَكَلَّمَ عليهِ مِنَ المشَايخِ، ورأَيتُ بعضَ المتأخِّرِينَ والعَصْرِيِّينِ يَصْنَعُونَهُ» (٧)، ثُمَّ حَكَى عَنْ أبي الوليدِ يونُسَ بنِ مُغِيثٍ (٨) قَاضِي قُرْطُبَةَ أنَّهُ سُئِلَ الإجازَةَ لِجَمِيْعِ (٩) مَا رواهُ إلى تاريخِها وما يَرويهِ بعدُ، فامْتَنَعَ مِنْ ذلكَ. فَغَضِبَ السَّائلُ، فَقَالَ لهُ بعضُ أصْحابِهِ: يَا هذا يُعْطِيكَ مَا لَمْ يأْخُذْهُ، هذا مُحَالٌ؟ قَالَ عِيَاضٌ: «وهذَا هُوَ الصَّحِيحُ» (١٠).","",{"fn":"الكفاية: (٤٦٦ ت، ٣٢٥ هـ).\nالمصدر السابق.\nالكفاية: (٤٦٦ ت، ٣٢٦ هـ).\nفي (م): «قال المملي أبقاه الله».\nفي الشذا: «وتقربة».\nقوله: «والله أعلم» من (جـ) و(م).\nالإلماع: ١٠٦.\nترجمته في السِّيَر ١٧/ ٥٦٩.\nفي (ع): «بجميع»، وما أثبتناه من (ب) و(جـ) و(م).\nالإلماع: ١٠٦."}],[1007,"قُلْتُ: يَنْبَغِي أنْ يُبْنَى هَذَا عَلَى أنَّ الإجازةَ في حُكْمِ (١) الإخْبَارِ بالمجازِ جُمْلَةً أوْ هِيَ إذْنٌ، فَإنْ جُعِلَتْ في حُكْمِ الإخْبَارِ لَمْ تَصِحَّ هذهِ الإجَازَةُ، إذْ كَيفَ يُخْبِرُ بما لاَ خَبَرَ عِندَهُ منهُ. وإنْ جُعِلَتْ إذْنًا انْبَنَى هذا على الخِلاَفِ في تَصْحيحِ الإذْنِ في بابِ الوكالَةِ فيما لَمْ يَمْلِكْهُ الآذِنُ الموكِّلُ بَعْدُ، مِثْلُ أنْ يُوكِّلَ في بيعِ العبدِ الذي يريدُ أنْ يَشْتَرِيَهُ. وقَدْ أجَازَ ذلكَ بعضُ أصحابِ الشَّافعيِّ، والصحيحُ بُطْلانُ هذهِ الإجَازَةِ (٢). وعَلى هذا يَتَعَيَّنُ على مَنْ يُرِيْدُ أنْ يَرْوِيَ بالإجَازَةِ عَنْ شَيْخٍ أجَازَ لهُ جَمِيْعَ مَسْمُوعَاتِهِ مثلًا، أنْ يَبْحَثَ حَتَّى يَعْلَمَ أنَّ ذَاكَ (٣) الذي يُريدُ روايتَهُ عنهُ مِمَّا سَمِعَهُ قَبْلَ تارِيْخِ (٤) الإجازةِ. وأمَّا إذا قَالَ: أجَزْتُ لَكَ مَا صَحَّ ويَصِحُّ عِندَكَ مِنْ مَسْمُوعاتِي (٥)؛ فهذا ليسَ مِنْ هذا القبيلِ، وقَدْ فَعَلَهُ الدَّارقطنيُّ وغيرُهُ، وجائِزٌ أنْ يَرْوِيَ بذلكَ عنهُ مَا صَحَّ عندَهُ بَعْدَ الإجَازَةِ أنَّهُ سَمِعَهُ قَبْلَ الإجَازَةِ، ويَجُوزُ ذَلِكَ وإنِ اقْتَصَرَ على قولِهِ: مَا صَحَّ عِنْدَكَ، ولَمْ يَقُلْ: ومَا يَصِحُّ؛ لأنَّ المرادَ: أجَزْتُ لكَ أنْ تَرْوِيَ عَنِّي مَا صَحَّ عِنْدَكَ. فالمعتبرُ إذنْ فيهِ صِحَّةُ ذلكَ عِنْدَهُ حَالَةَ الروَايَةِ، واللهُ أعلمُ."],[1008,"النَّوْعُ السَّابِعُ مِنْ أنواعِ الإجازَةِ: إجَازَةُ الْمُجَازِ، مِثْلُ أنْ يَقولَ الشيخُ: أجزْتُ لَكَ مُجَازَاتِي، أوْ أجزتُ لكَ روايةَ مَا أُجِيزَ لِي روايتُهُ، فَمَنَعَ مِنْ ذلكَ بعضُ مَنْ لاَ يُعْتَدُّ بهِ مِنَ المتَأَخِّرينَ (٦). والصحيحُ والذي عليهِ العَمَلُ أنَّ ذلكَ جائِزٌ (٧)، ولاَ يُشْبِهُ ذَلكَ ما امْتَنَعَ مِنْ تَوْكِيْلِ الوكيلِ بغيرِ إذْنِ الموَكِّلِ. ووجَدْتُ عَنْ أبي عَمْرٍو السَّفَاقُسِيِّ الحافِظِ المغْرِبيِّ، قَالَ: سَمِعْتُ أبا نُعَيْمٍ الحافِظَ -يَعْنِي: الأصْبَهانيَّ (٨) - يَقُولُ: «الإجَازَةُ عَلَى الإجَازَةِ قَوِيَّةٌ جَائِزَةٌ».","",{"fn":"انظر: نكت الزركشي ٣/ ٥٢٣.\nقال النووي في التقريب: ١١٣: «وهذا هو الصواب»، وقال في الروضة ١١/ ١٥٨: «هي باطلة قطعًا».\nفي (م) والشذا: «ذلك».\nفي (ع) والتقييد: «تاريخ هذه الإجازة».\nانظر: نكت الزركشي ٣/ ٥٢٤ - ٥٢٥.\nراجع: المحاسن: ٢٧٤، ونكت الزركشي ٣/ ٥٢٥، وشرح التبصرة ٢/ ١٥٢.\nقال النووي في الروضة ١١/ ١٠٨: «وهو الصواب الذي قطع به الحفاظ الأعلام من أصحابنا وغيرهم».\nالأكثر والأشهر: فتح الهمزة، وقد تكسر. انظر: مراصد الاطلاع ١/ ٨٧."}],[1009,"وحَكَى الخطيبُ الحافِظُ (١) تَجْويزَ ذلكَ عَنِ الحافِظِ الإمامِ أبي الحسَنِ الدَّارقطنيِّ، والحافِظِ أبي العبَّاسِ المعروفِ بابنِ عُقْدَةَ (٢) الكُوفِيِّ وغيرِهِما، وقدْ كَانَ الفقيهُ الزَّاهِدُ نَصْرُ بنُ إبراهيمَ المقْدِسِيُّ يروي بالإجازةِ عَنْ الإجَازَةِ حَتَّى رُبَّمَا وَالَى في روايتِهِ بينَ إجَازَاتٍ ثَلاَثٍ (٣). ويَنْبَغِي لِمَنْ يَرْوِي بالإجَازَةِ عَنِ الإجَازَةِ أنْ يَتَأَمَّلَ كَيْفِيَّةَ إجازَةِ شَيْخِ شَيْخِهِ ومُقْتَضَاها؛ حَتَّى لا يَروِيَ بها ما لَمْ يَنْدَرِجْ تَحْتَهَا، فإذا كَانَ - مَثَلًا - صورةُ إجَازَةِ شَيْخِ شَيْخِهِ: أجَزْتُ لهُ ما صَحَّ عِندَهُ مِنْ سَمَاعاتِي، فَرَأَى شيئًا مِنْ مَسْمُوعاتِ شَيْخِ شيخِهِ فليسَ لهُ أنْ يَرْوِيَ ذلكَ عَنْ شَيخِهِ عنهُ، حَتَّى يَسْتَبِينَ أنَّهُ مِمَّا كَانَ قَدْ صَحَّ عِنْدَ شَيخِهِ كَوْنُهُ مِنْ سَمَاعاتِ (٤) شَيْخِهِ الذي تِلْكَ إجَازَتُهُ، ولاَ يَكْتَفِي بمجرَّدِ صِحَّةِ ذَلكَ عندَهُ الآنَ، عَمَلًا بلَفْظِهِ وتَقْييدِهِ، ومَنْ لاَ يَتَفَطَّنُ لِهذا وأمثالِهِ يَكثُرُ عِثَارُهُ، واللهُ أعلمُ."],[1010,"هذهِ أنواعُ الإجازَةِ التي تَمَسُّ الحاجةُ إلى بَيانِها، ويتَركُّبُ مِنْها أنواعٌ أُخَرُ، سيتعَرَّفُ المتأمِّلُ حُكْمَها مِمَّا أمْلَيْنَاهُ إنْ شَاءَ اللهُ تعَالَى."],[1011,"ثُمَّ إنَّا نُنَبِّهُ عَلَى أُمُورٍ:"],[1012,"أحدُها: رُوِّيْنا عَنْ أبي الحسينِ (٥) أحمدَ بنِ فارسٍ الأديبِ المصَنِّفِ - رحمه الله - قالَ: «معنى الإجازةِ في كَلاَمِ العربِ مَأْخُوذٌ مِنْ جَوَازِ الماءِ الذي يُسْقَاهُ المالُ مِنَ الماشيةِ والْحَرْثِ، يُقَالُ منهُ: اسْتَجَزْتُ فُلاَنًا فَأَجَازَنِي (١) إذا أسْقَاكَ ماءً لأرْضِكَ أوْ مَاشِيَتِكَ، كذلكَ طَالِبُ العِلْمِ يَسأَلُ العالِمَ أنْ يُجِيزَهُ عِلْمَهُ فيُجِيزَهُ إيَّاهُ» (٢).","",{"fn":"الكفاية: (٥٠٠ ت، ٣٥٠ هـ).\nهُوَ الحافظ أبو العَبَّاس أحمد بن مُحَمَّد بن سعيد الكوفي، تُوُفِّي سنة (٦٢٩ هـ)، وعُقْدة: لَقبٌ لأبيه النحوي محمد بن سعيد؛ ولُقِّب بذلك لتعقيده في التصريف، انظر: تاريخ بغداد ٥/ ١٤، والسِّيَر ١٥/ ٣٤٠، والتاج ٨/ ٣٩٩.\nقال البلقيني في المحاسن: ٢٧٥: «القرينة الحالية من إرادة إبقاء السلسلة، قاضية بأن كل مجيز بمقتضى ذلك، أذن لما أجازه أن يجيز، وذلك في الإذن في الوكالة جائز».\nفي (م): «مسموعات».\nفي (جـ) و(ع) والتقييد: «الحسن»، وكذا جاء في ترجمته من تاريخ الإسلام: ٣٠٩ حوادث (٣٩٥)، وأثبتنا ما في باقي النسخ، وهو الموافق لما جاء في مصادر ترجمته. انظر مثلًا: وفيات الأعيان ١/ ١١٨، والسِّيَر ١٧/ ١٠٣، وشذرات الذهب ٣/ ١٣٢، ومعجم المؤلفين ٢/ ٤١."}],[1013,"قُلْتُ: فَلِلْمُجِيزِ - عَلَى هذا - أنْ يَقولَ: أجَزْتُ فُلاَنًا مَسْمُوعَاتِي أو مَرْوِيَّاتِي، فَيُعَدِّيهِ بغيرِ حَرْفِ جَرٍّ، مِنْ غَيْرِ حَاجَةٍ إلى ذِكْرِ لَفْظِ الروايةِ أو نَحْوِ ذلكَ. ويَحْتاجُ إلى ذلكَ مَنْ يَجْعَلُ الإجازَةَ بمعْنَى التَّسْويغِ، والإذْنِ، والإبَاحَةِ، وذلكَ هُوَ المعروفُ، فيقولُ: أجزْتُ لفُلاَنٍ روايَةَ مَسْمُوعَاتِي مَثَلًا، ومَنْ يَقُولُ منهُمْ: أجزْتُ لهُ مَسْمُوعَاتِي، فَعَلَى سَبيلِ الحذْفِ (٣) الذي لاَ يَخْفَى نَظِيرُهُ، واللهُ أعلمُ."],[1014,"الثَّاني: إنَّمَا تُسْتَحْسَنُ الإجَازةُ إذا كَانَ المجيزُ عالِمًا بما يُجِيْزُ (٤)، والمجازُ لهُ مِنْ"],[1015,"أهلِ العِلْمِ؛ لأنَّها تَوَسُّعٌ (٥) وتَرْخِيصٌ يَتَأَهَّلُ لَهُ أهْلُ العِلْمِ لِمَسِيْسِ حاجَتِهِمْ إليها، وبَالَغَ بعضُهُمْ في ذَلكَ فجعَلَهُ شَرطًا فِيْهَا. وحَكَاهُ أبو العبَّاسِ الوليدِ بنُ بَكْرٍ المالِكِيُّ عَنْ"],[1016,"مالِكٍ - رضي الله عنه - (٦). وقالَ الحافِظُ أبو عُمَرَ: «الصحيحُ أنَّهَا لاَ تَجُوزُ إلاَّ لِمَاهِرٍ بالصِّناعَةِ، وفي شيءٍ مُعَيَّنٍ لاَ يُشْكِلُ إسْنَادُهُ» (٧)، واللهُ أعلمُ."],[1017,"الثَّالِثُ: يَنْبَغِي للْمُجِيْزِ إذا كَتَبَ إجَازَتَهُ أنْ يَتَلَفَّظَ بها (٨)، فَإنِ اقْتَصَرَ عَلَى الكِتَابةِ كَانَ ذلكَ إجَازَةً جَائِزَةً إذا اقتَرَنَ بقَصْدِ الإجَازَةِ، غيرَ أنَّها أنْقَصُ مَرْتَبَةً مِنَ الإجَازَةِ الملْفُوظِ بها. وغيرُ مُسْتَبْعَدٍ تصحيحُ ذلكَ بمجَرَّدِ هذهِ الكِتَابَةِ في بابِ الروايةِ التي جُعِلَتْ فيهِ القراءةُ على الشيخِ مَعَ أنَّهُ لَمْ يَلْفِظْ بما قُرِئَ عليهِ، إخْبَارًا منهُ بما قُرِئَ عليهِ، عَلَى مَا تَقَدَّمَ بيانُهُ، واللهُ أعلمُ.","",{"fn":"في التقييد: «فأجاز لي».\nهو بهذا السياق في كتابه \"مآخذ العلم\" كما أشار إلى ذلك الزركشي ٣/ ٥٢٧، والسخاوي في فتح المغيث ٢/ ٩٥، وهو أيضًا بحروفه إلى قوله: «أو ماشيتك» في مقاييس اللغة ١/ ٤٩٤، وانظر: مجمل اللغة ١/ ٢٠٢، له أيضًا مادة (جوز)، وقد أسنده عنه الخطيب بتمامه في الكفاية: (٤٤٦ ت، ٣١١ هـ)، وانظر: النكت الوفية ٢٦٠ / ب.\nقوله: «على سبيل الحذف»، يريد به أنه على حذف المضاف وإقامة المضاف إليه مقامه، وأصل العبارة: أجزت له رواية مسموعاتي، كما في حاشية توضيح الأفكار ٢/ ٣١١.\nانظر: نكت الزركشي ٣/ ٥٢٩ - ٥٣١.\nفي الشذا: «توسيع».\nالكفاية: (٤٥٥ ت، ٣١٧ هـ)، والإلماع: ٩٤ - ٩٥.\nجامع بيان العلم وفضله ٢/ ١٨٠، وينظر: الإلماع ٩٥ - ٩٦.\nنقل الزركشي في نكته ٣/ ٥٣١ عن ابن أبي الدم قوله: يعضد هذا أنه قال: تقوم الأفعال مقام الأقوال في نقل الملك، على تصحيح المعاطاة»."}],[1018,"القِسْمُ الرَّابِعُ مِنْ أقْسَامِ طُرُقِ تَحَمُّلِ الحدِيْثِ وتَلقِّيْهِ: الْمُنَاوَلَةُ:"],[1019,"وهِيَ عَلَى نَوْعَيْنِ:"],[1020,"أحدُهُما: المنَاوَلَةُ المقْرُونَةُ بالإجَازَةِ (١) وهيَ أعْلَى أنواعِ الإجَازَةِ (٢) على الإطلاقِ، ولَها صُورٌ، منها: أنْ يَدْفَعَ الشَّيْخُ إلى الطالِبِ أصْلَ سَماعِهِ أوْ فَرْعًا مُقَابَلًا بهِ (٣)، ويقولَ: «هذا سَماعِي، أوْ رِوايَتِي عَنْ فُلانٍ فارْوِهِ عَنِّي، أو أجزْتُ لَكَ روايَتَهُ عَنِّي»، ثُمَّ يُمَلِّكَهُ إيَّاهُ، أوْ يَقُولَ: «خُذْهُ وانْسَخْهُ وقَابِلْ بهِ ثُمَّ رُدَّهُ إليَّ»، أوْ نحوَ هذا."],[1021,"ومنها: أنْ يَجِيءَ الطالِبُ إلى الشيخِ بكِتابٍ أوْ جُزْءٍ مِنْ حديثِهِ فيَعْرِضَهُ عليهِ، فيتَأَمَّلَهُ الشيخُ وهوَ عارفٌ مُتَيَقِّظٌ، ثُمَّ يُعِيْدَهُ إليهِ، ويقُولَ لهُ: «وَقَفْتُ على ما فيهِ وهوَ حَدِيثي عَنْ فُلانٍ أو رِوَايَتِي عَنْ شُيُوخِي فيهِ، فَارْوِهِ عَنِّي، أوْ أجَزْتُ لَكَ روايَتَهُ عَنِّي». وهذا قدْ سَمَّاهُ غيرُ واحِدٍ مِنْ أئِمَّةِ الحديثِ: عَرْضًا، وقدْ سَبَقَتْ حِكَايَتُنا في القِرَاءَ ةِ على الشيخِ أنَّها تُسَمَّى عَرْضًا أيَضًا (٤)، فَلنُسَمِّ ذلكَ عَرْضَ القِرَاءَ ةِ، وهذا عَرْضَ المناولةِ، واللهُ أعلمُ (٥)."],[1022,"وهذهِ المناولَةُ المقْتَرِنَةُ (٦) بالإجازَةِ حالَّةٌ (٧) مَحَلَّ السَّمَاعِ عِنْدَ مَالِكٍ (٨)،"],[1023,"وجماعَةٍ مِنْ أئِمَّةِ أصْحَابِ الحديثِ (٩). وحَكَى الحاكِمُ أبو عبدِ اللهِ الحافِظُ"],[1024,"النَّيْسَابُورِيُّ (١٠) في عَرْضِ المناولَةِ المذْكورِ (١) عَنْ كَثيرٍ مِنَ المتَقَدِّمينَ أنَّهُ سَماعٌ. وهذا مُطَّرِدٌ في سَائِرِ مَا يُمَاثِلُهُ مِنْ صُوَرِ المناولَةِ المقرُونَةِ بالإجَازَةِ. فَمِمَّنْ حَكَى الحاكِمُ ذلكَ عنهُمْ: ابنُ شِهَابٍ الزُّهْرِيُّ، ورَبِيْعَةُ الرأيِ، ويَحْيَى بنُ سَعِيْدٍ الأنْصَارِيُّ، ومَالِكُ بنُ أنسٍ الإمامُ في آخرينَ مِنَ المدنِيِّينَ. ومُجَاهِدٌ، وأبو الزُّبَيْرِ، وابنُ عُيَيْنَةَ في جَماعَةٍ مِنَ المكِّيِّينَ. وعَلْقَمةُ وإبراهِيمُ النَّخَعِيَّانِ، والشَّعْبِيُّ في جَمَاعَةٍ مِنَ الكُوفِيِّينَ. وقَتَادَةُ وأبو العَالِيَةِ، وأبو الْمُتَوَكِّلِ النَّاجِيُّ في طَائِفَةٍ مِنَ البَصْرِيِّيْنَ. وابنُ وَهْبٍ، وابنُ القَاسِمِ، وأشْهَبُ في طَائِفَةٍ مِنَ المِصْرِيِّيْنَ. وآخَرُونَ مِنَ الشَّامِيِّيْنَ والْخُرَسَانِيِّيْنَ. ورَأَى الحاكِمُ طَائِفَةً مِنْ مَشَايِخِهِ عَلَى ذلكَ (٢)، وفي كَلاَمِهِ بعضُ التَّخليطِ مِنْ حيثُ كَوْنُهُ خَلَطَ بعضَ ما وَرَدَ في عَرْضِ القِرَاءَةِ بما ورَدَ في عَرْضِ المناولَةِ، وسَاقَ الجميعَ مَسَاقًا واحِدًا. والصحيحُ أنَّ ذَلِكَ غيرُ حالٍّ مَحَلَّ السَّماعِ، وأنَّهُ مُنْحَطٌّ عَنْ دَرَجَةِ التَّحْدِيثِ لَفْظًا والإخْبَارِ قِرَاءَةً (٣).","",{"fn":"قال الزركشي في نكته ٣/ ٥٣٢: «قد أنكر بعض الأصوليين إفراد المناولة عن الإجازة ... الخ».\nانظر: نكت الزركشي ٣/ ٥٣٢ - ٥٣٣.\nقال الزركشي في نكته ٣/ ٥٣٣: «نبّه بذلك على أن الشيخ لو سمع نسخة من كتاب مشهور فليس له أن يشير إلى نسخة أخرى من ذلك الكتاب، ويقول: سمعت هذا؛ لأن النُّسَخ تختلف مالم يعلم اتفاقهما بالمقابلة».\nلم ترد في (م).\nجملة: «والله أعلم»، لم ترد في (م).\nفي (م): «المقرونة».\nانظر: نكت الزركشي ٣/ ٥٣٣ - ٥٣٥.\nالكفاية: (٤٦٧ ت، ٣٢٧ هـ)، والإلماع: ٧٩.\nانظر: الكفاية: (٤٦٦ - ٤٦٧ ت، ٣٢٦ - ٣٢٧ هـ)، والإلماع: ٧٩.\nمعرفة علوم الحديث: ٢٥٧ - ٢٥٨."}],[1025,"وقدْ قَالَ الحاكِمُ في هذا العَرْضِ: «أمَّا فُقَهَاءُ الإسْلاَمِ (٤) الذينَ أفْتَوا في الحلاَلِ والحرَامِ فإنَّهُمْ لَمْ يَرَوْهُ سَمَاعًا، وبهِ قَالَ الشَّافِعِيُّ، والأوْزَاعِيُّ، والبُوَيْطِيُّ والْمُزَنِيُّ، وأبو حَنِيْفَةَ، وسُفْيَانُ الثَّوْرِيُّ، وأحمدُ بنُ حَنْبَلٍ، وابنُ المبَارَكِ، ويَحْيَى بنُ يَحْيَى، وإسْحَاقُ بنُ رَاهَوَيْهِ. قَالَ: وعليهِ عَهِدْنا أئِمَّتَنا وإليْهِ ذَهَبُوا وإليْهِ نَذْهَبُ» (٥)، واللهُ أعْلَمُ."],[1026,"ومِنْها: أنْ يُنَاوِلَ الشَّيْخُ الطالِبَ كِتَابَهُ ويُجُيزُ لهُ رِوايَتَهُ عنهُ، ثُمَّ يُمْسِكَهُ الشَّيْخُ عِندَهُ ولاَ يُمَكِّنَهُ منهُ، فَهَذا يَتَقَاعَدُ عَمَّا سَبَقَ؛ لِعَدَمِ احْتِواءِ الطَّالِبِ عَلَى مَا تَحَمَّلَهُ، وغَيْبتِهِ عنهُ، وجَائِزٌ لَهُ روايةُ ذَلِكَ عنهُ إذا ظَفِرَ بالكِتابِ، أوْ بِمَا هُوَ مُقَابَلٌ بهِ عَلَى وَجْهٍ يَثِقُ مَعَهُ بموافَقَتِهِ لِمَا تَنَاولَتْهُ الإجازَةُ، عَلَى (٦) مَا هُوَ مُعْتَبَرٌ في الإجَازاتِ المجرَّدَةِ عَنِ المناوَلَةِ.","",{"fn":"في (ب): «المذكورة».\nراجع: محاسن الاصطلاح: ٢٧٩.\nراجع: محاسن الاصطلاح: ٢٨٠.\nراجع: نكت الزركشي ٣/ ٥٣٥، والتقييد: ١٩٢، ومحاسن الاصطلاح: ٢٨١.\nمعرفة علوم الحديث: ٢٥٩ - ٢٦٠، وانظر: محاسن الاصطلاح: ٢٨١.\nفي (م): «مع»."}],[1027,"ثُمَّ إنَّ المناوَلَةَ في مِثْلِ هذا لاَ يَكَادُ يَظْهَرُ حُصُولُ مَزِيَّةٍ بها عَلَى الإجَازَةِ الواقِعَةِ في مُعَيَّنٍ كَذَلِكَ مِنْ غَيْرِ مناولةٍ، وقدْ صَارَ غَيْرُ واحِدٍ مِنَ الفُقَهَاءِ والأصُولِيِّيْنَ (١) إلى أنَّهُ لاَ تأثيرَ لَهَا ولاَ فَائِدَةَ، غيرَ أنَّ شُيوخَ أهلِ الحديثِ في القديمِ والحديثِ، أوْ مَنْ حُكِيَ ذَلِكَ عنهُ مِنْهُمْ يَرَوْنَ لِذَلِكَ مَزِيَّةً مُعْتَبَرَةً (٢)، والعِلْمُ عِنْدَ اللهِ تَبَارَكَ (٣) وتَعَالَى."],[1028,"ومِنْهَا أنْ يَأْتِيَ الطالِبُ الشَّيْخَ بكِتَابٍ أو جُزْءٍ، فيقُولَ: «هذا روايتُكَ فَنَاوِلْنِيْهِ وأجِزْ لي رِوَايَتَهُ»، فَيُجِيْبَهُ إلى ذلكَ مِنْ غيرِ أنْ يَنْظُرَ فيهِ ويَتَحَقَّقَ روَايَتَهُ لِجَمِيْعِهِ، فَهَذَا لاَ يَجُوزُ ولاَ يَصِحُّ. فإنْ كَانَ الطالِبُ مَوْثُوقًا بخَبَرِهِ ومَعْرِفَتِهِ جَازَ الاعْتِمَادُ عليهِ في ذَلكَ، وكانَ ذلكَ إجازَةً جَائِزَةً، كما جازَ في القِرَاءَةِ على الشيخِ الاعتمادُ عَلَى الطالِبِ حَتَّى (٤) يكونَ هُوَ القَارِئَ مِنَ الأصْلِ إذا كَانَ مَوْثُوقًا بهِ مَعْرِفَةً ودِيْنًا (٥). قالَ الخطيبُ أبو بكرٍ - رحمه الله -: «ولوْ قَالَ: حَدِّثْ بِمَا في هذا الكِتابِ عَنِّي إنْ كَانَ مِنْ حَدِيْثِي مَعَ بَرَاءتِي مِنَ الغَلَطِ والوَهَمِ، كَانَ ذَلِكَ جَائِزًا حَسَنًا» (٦)، واللهُ أعلَمُ."],[1029,"الثَّانِي: المناوَلَةُ المجَرَّدَةُ عَنِ الإجَازَةِ بأنْ يُنَاوِلَهُ الكِتَابَ - كَمَا تَقَدَّمَ ذِكْرُهُ أوَّلًا -، ويَقْتَصِرَ عَلَى قَوْلِهِ: «هذا مِنْ حَدِيْثِي أوْ مِنْ سَمَاعَاتِي»، ولاَ يَقُولَ: «ارْوِهِ عَنِّي أوْ أجَزْتُ لَكَ روايَتَهُ عَنِّي»، ونحوَ ذلكَ، فَهَذِهِ مُنَاوَلَةٌ مُخْتَلَّةٌ لاَ تَجُوزُ الروايَةُ بها (٧)، وعَابَها غيرُ واحِدٍ مِنَ الفُقَهَاءِ والأصُولِيِّيْنَ عَلَى المحدِّثِينَ (٨) الذينَ أجَازوها وسَوَّغُوا الروايةَ بها. وحَكَى الخطيبُ عَنْ طَائِفَةٍ مِنْ أهْلِ العِلْمِ أنَّهُمْ صَحَّحُوها وأجازُوا الروايةَ بها (٩)، وسَنَذكُرُ - إنْ شَاءَ اللهُ سبحانه وتعالى - قَوْلَ مَنْ أجَازَ الروايةَ بِمُجَرَّدِ إعْلاَمِ الشَّيْخِ الطالِبَ أنَّ هذا الكِتَابَ سَمَاعُهُ مِنْ فُلاَنٍ. وهَذا يَزِيْدُ عَلَى ذَلِكَ ويَتَرَجَّحُ بِمَا فيهِ مِنَ المناوَلَةِ، فإنَّها لاَ تَخْلُو مِنْ إشْعَارٍ بالإذْنِ في الروايَةِ، واللهُ أعلمُ.","",{"fn":"راجع: نكت الزركشي ٣/ ٥٣٧ - ٥٣٨.\nالإلماع: ٨٣.\nلم ترد في: (م).\nفي (أ): «حين».\nقال البلقيني في المحاسن: ٢٨٢: «لا سيّما إذا كان الكتاب مشهورًا كالبخاري أو مسلم أو نحوهما، فإنه يقرب من تمليكه له أو إعارته».\nالكفاية: (٤٦٩ ت، ٣٢٨ هـ).\nحكى الزركشي الاتفاق على هذا في البحر المحيط ٤/ ٣٩٥.\nراجع: نكت الزركشي ٣/ ٥٣٨ - ٥٣٩.\nالكفاية: (٤٩٤ - ٤٩٩ ت، ٣٢٧ - ٣٢٩ هـ)."}],[1030,"القول في عبارة الراوي بطريق المناولة والإجازة"],[1031,"حُكِيَ عَنْ قَومٍ مِنَ المتَقَدِّمينَ ومَنْ بَعْدَهُمْ أنَّهُمْ جَوَّزُوا إطْلاَقَ (١): «حَدَّثَنَا وأخْبَرَنَا» في الروايةِ بالمناولةِ، وحُكِيَ ذَلكَ عَنِ الزُّهْرِيِّ ومالكٍ وغَيرِهِما (٢)، وهوَ لاَئِقٌ بِمَذْهَبِ جَميعِ مَنْ سَبَقَتِ الحِكَايةُ عَنْهُمْ أنَّهُمْ جَعَلُوا عَرْضَ المناولةِ المقرونَةِ بالإجازَةِ سَمَاعًا. وحُكِيَ (٣) أيضًا عَنْ قَومٍ مِثْلُ ذلكَ في الروايةِ بالإجازَةِ، وكانَ الحافِظُ أبو نُعَيْمٍ الأصْبهانِيُّ (٤) - صَاحِبُ التَّصانيفِ الكَثِيرةِ (٥) في عِلْمِ الحدِيْثِ - يُطْلِقُ «أخْبَرَنَا» فيمَا يَرْوِيْهِ بالإجازَةِ (٦). رُوِّيْنا عنهُ أنَّهُ قَالَ: أنَا إذا قُلْتُ: «حَدَّثَنَا» فَهُوَ سَمَاعِي، وإذا قُلْتُ: «أخْبَرَنَا» على الإطلاَقِ، فَهُوَ إجَازَةٌ مِنْ غيرِ أنْ أَذْكُرَ فيهِ (١) «إجازَةً، أوْ كِتَابَةً، أوْ كَتَبَ إليَّ، أوْ أَذِنَ لِي في الروايَةِ عنهُ».","",{"fn":"نَكَّتَ عليه الزركشي٣/ ٥٣٩ فقال: «قضيته جوازه مقيدًا بلا خِلاف، لكن حكى ابن الحاجب- (المختصر ٢/ ٦٩ - ٧٠) في مختصره قولًا أنه لا يجوز مقيدًا أيضًا». وانظر: شرح التبصرة والتذكرة ٢/ ١٧٠ - ١٧٢.\nالمحدّث الفاصل: ٤٣٥، والرواية عن الزهري أسندها الخطيب في الكفاية: (٤٧٠ ت، ٣٢٩ هـ)، والرواية عن مالك أسندها الخطيب أيضًا في الكفاية: (٤٧٥ - ٤٧٦ ت، ٣٣٢ - ٣٣٣ هـ).\nفي (م): «ويحكى».\nقال الزركشي في نكته ٣/ ٥٤٠ - ٥٤١: «من أجل هذا أدخل ابن الجوزي في الضعفاء أبا نعيم وحكى عن أبي بكر الخطيب - فيما حكاه ابن طاهر - رأيت لأبي نعيم أشياء يتساهل فيها، مثل أن يقول في الإجازة: «أخبرنا» من غير أن يبيّنه». قلنا: ما قاله الخطيب فيه غلوٌّ وإسرافٌ، وقد ناقشه الذهبي في السِّيَر١٧/ ٤٦١فَقَالَ: «هذا شيء قلَّ أن يفعله أبو نُعَيْم، وكثيرًا ما يقول: كتب إليَّ الْخُلْدِيُّ. ويقول: كتب إليَّ أبو العبَّاس الأصم، وأخبرنا أبو الميمون بن راشد في كتابه، ولكني رأيته يقول في شيخه عبد الله بن جعفر بن فارس الذي سمع منه كثرًا وهو أكبر شيخ له: أخبرنا عبد الله بن جعفر فيما قرئ عليه فيوهم أنه سمعه، ويكون مما هو له بالإجازة، ثم إطلاق الإخبار على ما هو بالإجازة مذهب معروف قد غلب استعماله على محدثي الأندلس وتوسعوا فيه، وإذا أطلق ذلك أبو نعيم في مثل الأصم وأبي الميمون البجلي والشيوخ الذين قد علم أنه ما سمع منهم بل منهم إجازة، كان له سائغًا، والأحوط تجنّبُهُ فبطل ما تخيَّله الخطيب، وتوهمه، وما أبو نعيم بمُتَّهم بل هو صدوق عالم بهذا الفن».\nفي (أ): «الكبيرة».\nانظر: سير أعلام النبلاء ١٧/ ٤١٦، تذكرة الحفاظ ٣/ ١٠٩٦، ميزان الاعتدال ١/ ١١١، وطبقات السبكي ٤/ ٢٤، والوافي بالوفيات ٧/ ٨٣."}],[1032,"وكَانَ أبو عُبَيْدِ (٢) اللهِ الْمَرْزُبَانِيُّ (٣) الأخْبَارِيُّ - صَاحِبُ التَّصَانيفِ في عِلْمِ"],[1033,"الخبرِ - يَرْوِي أكْثَرَ مَا في كُتُبِهِ إجَازَةً مِنْ غَيْرِ سَمَاعٍ، ويَقُولُ في الإجَازَةِ: «أخْبَرَنا» ولاَ يُبَيِّنُهَا، وكَانَ ذلكَ فِيْمَا حَكَاهُ الخطيبُ مِمَّا عِيبَ بهِ (٤)."],[1034,"والصحيحُ والمختارُ الذي عليهِ عَمَلُ الجمهُورِ (٥) وإيَّاهُ اخْتَارَ أهْلُ التَّحَرِّي (٦) والورَعِ: المنعُ في ذلكَ مِنْ إطلاقِ: «حَدَّثَنا وأخْبَرَنا»، ونحوِهِما مِنَ العِبَاراتِ، وتَخْصِيصُ ذلكَ بِعِبَارَةٍ تُشْعِرُ بهِ بأنْ يُقَيِّدَ هذهِ العِبَاراتِ فيقُولَ: «أخْبَرنا أو حَدَّثَنا فُلاَنٌ مناوَلَةً وإجازَةً، أوْ أخْبَرنا إجازَةً (٧)، أوْ أخْبَرنا مناوَلَةً، أو أخْبَرنا إذْنًا، أوْ في إذْنِهِ، أوْ فيما أَذِنَ لي فيهِ، أوْ فيما أَطْلَقَ لي روايتَهُ عنهُ». أوْ يَقُولَ: «أجَازَ لي فُلاَنٌ، أوْ أجَازَنِي فُلاَنٌ كَذا وكَذا، أوْ ناوَلَني فُلاَنٌ»، وما (٨) أشْبَهَ ذلكَ مِنَ العِبَاراتِ. وخَصَّصَ قَومٌ الإجَازَةَ بعباراتٍ لَمْ يَسْلَمُوا فيها مِنَ التَّدليسِ أوْ طَرَفٍ منهُ، كعِبَارةِ مَنْ يَقُولُ في الإجَازَةِ: «أخْبَرَنا مُشَافَهَةً» إذا كَانَ قَدْ شَافَهَهُ بالإجَازَةِ لَفْظًا، وكَعِبَارَةِ مَنْ يَقُولُ: «أخْبَرَنا فُلاَنٌ كِتَابَةً، أوْ فيما كَتَبَ إليَّ (٩)، أوْ في كِتَابِهِ» إذا كانَ قَدْ أجَازَهُ بِخَطِّهِ. فَهَذا وإنْ تَعَارَفَهُ في ذلكَ طائِفَةٌ مِنَ المحدِّثِينَ المتأخِّرِينَ فلاَ يَخْلُو عَنْ طَرَفٍ مِنَ التَّدْلِيسِ؛ لِمَا فيهِ مِنَ الاشْتِرَاكِ والاشْتِبَاهِ بِما إذا كَتَبَ إليهِ ذلكَ الحديثَ بِعَيْنِهِ.","",{"fn":"ساقطة من (م).\nفي (جـ): «عبد الله».\nبفتح الميم وسكون الراء وضم الزاء. انظر: الأنساب ٥/ ١٣٩، ووفيات الأعيان ٤/ ٣٥٤.\nتاريخ بغداد ٣/ ١٣٥، وميزان الاعتدال ٣/ ٦٧٢، وتذكرة الحفاظ ٣/ ١٠٩٢، وسير أعلام النبلاء ١٦/ ٤٤٨، وطبقات المدلسين: ١٨.\nانظر: الكفاية: (٤٧٢ ت، ٣٣٠ هـ)، والإلماع: ١٣٢، وإحكام الأحكام ٢/ ٩١.\nفي الشذا: «التحرير».\nسقطت من (م).\nسقطت من (أ).\nسقطت من (ب)."}],[1035,"ووَرَدَ عَنِ الأوْزَاعِيِّ أنَّهُ خَصَّصَ الإجَازَةَ بِقَوْلِهِ: «خَبَّرَنا» بالتَّشْديدِ، والقِرَاءةَ عليهِ بقولِهِ: «أخْبَرَنا» (١)، واصْطَلَحَ قومٌ مِنَ المتأخِّرِينَ عَلَى إطْلاَقِ: «أنْبَأَنا» في الإجَازَةِ، وهوَ اختِيارُ الوليدِ بنِ بَكرٍ - صَاحبِ \" الوجازَةِ في الإجَازَةِ \" (٢) -. وقدْ كَانَ «أنْبَأَنا» عِنْدَ القَومِ فِيْمَا تَقَدَّمَ بِمَنْزِلَةِ «أخْبَرَنَا» وإلى هَذَا نَحَا الحافِظُ المتْقِنُ أبو بَكْرٍ البَيْهَقِيُّ إذْ كَانَ يَقُولُ: «أنْبَأَنِي فُلاَنٌ إجَازَةً» وفيهِ أيضًا رِعَايَةٌ لاصْطِلاَحِ المتأخِّرينَ، واللهُ أعلمُ."],[1036,"ورُوِّيْنا عَنِ الحاكِمِ (٣) أبي عبدِ اللهِ الحافِظِ - رحمه الله - أنَّهُ قَالَ (٤): «الذي أَخْتَارُهُ وعَهِدْتُ عليهِ أكثَرَ مَشايخي وأئِمَّةِ عَصْرِي أنْ يَقُولَ فيما عَرَضَ عَلَى المحدِّثِ فأجَازَ لهُ روايتَهُ شِفَاهًا: «أنْبَأَنِي فُلاَنٌ»، وفيمَا كَتَبَ إليهِ المحدِّثُ مِنْ مدينةٍ وَلَمْ يُشَافِهْهُ بالإجَازَةِ: «كَتَبَ إليَّ فُلاَنٌ» (٥)."],[1037,"ورُوِّيْنا عَنْ أبي عَمْرِو بنِ أبي جَعْفَرِ بنِ حَمْدانَ النَّيْسَابوريِّ، قَالَ سَمِعْتُ أبي يَقُولُ: كُلُّ مَا قَالَ البُخَارِيُّ: «قَالَ لي فُلاَنٌ»، فهوَ عَرْضٌ ومُنَاوَلَةٌ» (٦).","",{"fn":"أسنده الرامهرمزي في المحدّث الفاصل: ٤٣٢، والخطيب في الكفاية: (٤٣٤ ت، ٣٠٢ هـ)، والقاضي عياض في الإلماع: ١٢٧. قال العراقي في شرح التبصرة والتذكرة ٢/ ١٧٣: «ولم نجل من النِّزاع أنَّ خَبَّر وأخبر واحد من حيث اللغة، ومن حيث الاصطلاح المتعارف بين أهل الحديث».\nذكره البقاعي في نكته الوفية: ٢٦٧ / ب باسم: \" الوجازة في تجويز الإجازة \"، وكذا في تدريب الراوي ٢/ ٣٠، ومعجم المؤلفين ١٣/ ١٧٠، وكذا ذكره المصنف في مبحث إعلام الراوي: ٣٣٥، وانظر: الكفاية: (٤٧٤ ت، ٣٣٢ هـ).\nانتقد الزركشي هذا الصنيع فقال في نكته ٣/ ٥٤٣: «وفيه إبهام لِمَا تقرَّر أن قول الراوي: «قال لي فلان، أو سمعته منه» إطلاق لا يستعمل إلا في السماع، فكيف يقال مطلقًا: «قال لي» من غير تقييد ويكون مناولةً وعرضًا إلا أنه اصطلاح».\nمعرفة علوم الحديث: ٢٦٠.\nبعد هذا في (ع): «قال»، ولم ترد في شيء من النسخ ولا في (م).\nهذا القول تعقبه الحافظ ابن حجر في نكته على ابن الصلاح ٢/ ٦٠١، فقال: «فيه نظر؛ فقد رأيت في الصحيح عدة أحاديث قال فيها: قال لنا فلان، وأوردها في تصانيفه خارج الجامع بلفظ: «حدثنا»، ووجدت في الصحيح عكس ذلك، وفيه دليل على أنهما متردفان، والذي تبين لي بالاستقراء من صنيعه أنه لا يعبر في الصحيح بذلك إلا في الأحاديث الموقوفة أو المستشهد بها فيخرج ذلك حيث يحتاج إليه عن أصل مساق الكتاب». وانظر: الفتح ٢/ ١٨٨ و٩/ ٤٣٣ و١٠/ ١١."}],[1038,"قُلْتُ: ووَرَدَ عَنْ قَومٍ مِنَ الرواةِ التعبيرُ عَنْ الإجَازةِ بقولِ: «أخْبَرَنا فُلاَنٌ أنَّ فُلاَنًا حَدَّثَهُ أوْ أَخْبَرَهُ». وبَلَغَنا ذَلكَ عَنِ الإمامِ أبي سُلَيْمانَ الخطَّابيِّ أنَّهُ اخْتَارَهُ أوْ حَكَاهُ (١)، وهذا اصطلاحٌ بعيدٌ، بَعيدٌ (٢) عَنِ الإشْعَارِ بالإجَازَةِ، وهوَ فيمَا إذا سَمِعَ منهُ الإسْنَادَ فَحسبُ وأجازَ لهُ ما رواهُ قريبٌ، فإنَّ كَلِمَةَ «أنَّ» في قولِهِ: «أخْبَرَنِي فُلاَنٌ أنَّ فُلاَنًا أخْبَرَهُ» فيها إشعَارٌ بوجُودِ أصْلِ الإخْبَارِ، وإنْ أجْمَلَ المخْبِرُ بهِ ولَمْ يَذْكُرْهُ تَفْصِيلًا."],[1039,"قُلْتُ: وكَثيرًا ما يُعَبِّرُ الرواةُ المتأخِّرونَ عَنِ الإجَازَةِ الواقِعَةِ في روايةِ مَنْ فَوقَ الشَّيْخِ الْمُسْمِعِ بكَلمةِ «عَنْ»، فيقُولُ أحَدُهُمْ إذا سَمِعَ عَلَى شَيْخٍ بإجَازَتِهِ عَنْ شَيْخِهِ: «قَرَأْتُ عَلَى فُلاَنٍ عَنْ فُلاَنٍ»، وذَلِكَ قَريبٌ فيما إذا كانَ قَدْ سَمِعَ منهُ بإجَازَتِهِ عَنْ شَيخِهِ إنْ لَمْ يَكُنْ سَمَاعًا فإنَّهُ شَاكٌّ، وحَرْفُ «عَنْ» مشترَكٌ بينَ السَّماعِ والإجَازَةِ صَادِقٌ عليهِما، واللهُ أعلمُ."],[1040,"ثُمَّ اعْلَمْ أنَّ المنعَ مِنْ إطلاَقِ: «حَدَّثَنا وأخْبَرَنا» في الإجازَةِ لاَ يَزُولُ بإباحَةِ المجيزِ لذلكَ كما اعْتَادَهُ قومٌ مِنَ المشايخِ مِنْ قَولِهِمْ في إجَازَتِهِمْ لِمَنْ يُجِيْزُونَ لهُ، إنْ شَاءَ قالَ: «حَدَّثَنا»، وإنْ شَاءَ قالَ: «أخْبَرَنا»، فَليُعْلَمْ ذلكَ، والعِلْمُ عِنْدَ اللهِ تبارك وتعالى."],[1041,"القِسْمُ الْخَامِسُ مِنْ أقْسَامِ طُرُقِ نَقْلِ الحديثِ وتَلَقِّيْهِ: المكاتَبَةُ، وهيَ أنْ يَكْتُبَ الشَّيْخُ إلى الطالِبِ وهوَ غائِبٌ شَيئًا مِنْ حَدِيْثِهِ بِخَطِّهِ أوْ يَكتُبَ لهُ ذلكَ وهوَ حاضِرٌ. ويَلْتَحِقُ (٣) بذلكَ مَا إذا أمَرَ غيرَهُ بأنْ يَكْتُبَ لهُ ذلكَ عنهُ إليهِ، وهذا القِسْمُ يَنْقَسِمُ أيضًا إلى نوعَيْنِ:"],[1042,"أحدُهُما: أنْ تَتَجَرَّدَ (٤) المكَاتَبةُ عَنِ الإجَازَةِ."],[1043,"والثَّاني: أنْ تَقْتَرِنَ بالإجَازَةِ بأنْ يَكْتُبَ إليهِ ويَقُولَ: «أجَزْتُ لَكَ مَا كَتَبْتُهُ لكَ، أوْ ما كَتَبْتُ (٥) بهِ إليكَ»، أوْ نَحْوَ ذلكَ مِنْ عِبَارَاتِ الإجَازَةِ.","",{"fn":"انظر: الإلماع: ١٢٩، ونكت الزركشي ٣/ ٥٤٣ - ٥٤٥.\nلم ترد في (ب).\nفي (م): «ويلحق».\nفي (جـ): «يتجرد».\nفي (أ): «وما كتب به»."}],[1044,"أمَّا الأوَّلُ: وهوَ ما إذِ اقْتَصَرَ عَلَى المكاتَبَةِ فقَدْ أجَازَ الروايةَ بها كثيرٌ مِنَ المتَقَدِّمِينَ والمتَأَخِّرينَ، مِنْهُمْ: أيُّوبُ السِّخْتيانِيُّ (١)، ومَنْصُورٌ (٢)، واللَّيْثُ بنُ سَعْدٍ (٣)، وقَالَهُ غيرُ واحِدٍ مِنَ الشَّافِعِيِّينَ (٤)، وجَعَلَها أبو الْمُظَفَّرِ السَّمْعانِيُّ -مِنْهُمْ- أَقْوَى مِنَ الإجَازةِ (٥)، وإليهِ صارَ غيرُ واحدٍ مِنَ الأًصُوليِّيْنَ (٦). وأبَى ذلكَ قومٌ آخَرُونَ (٧)، وإليهِ صَارَ مِنَ الشَّافِعِيِّيْنَ القَاضِي الماوَرْدِيُّ، وقَطَعَ بهِ في كِتَابِهِ \"الحاوي\" (٨). والْمَذْهَبُ الأوَّلُ هُوَ الصحيحُ (٩) المشهُورُ بينَ أهلِ الحديثِ، وكَثِيْرًا مَا يُوجَدُ في مَسَانِيْدِهِمْ ومُصَنَّفَاتِهِمْ قَوْلُهُمْ: «كَتَبَ إليَّ فُلاَنٌ: قَالَ حَدَّثَنا فُلاَنٌ»، والمرادُ بهِ هذا. وذَلكَ مَعْمُولٌ بهِ عِنْدَهُمْ مَعْدُودٌ في المسنَدِ الموصولِ. وفيها إشعَارٌ قويٌّ بمعْنَى الإجَازَةِ، فَهِيَ وإنْ لَمْ تَقْتَرِنْ (١٠) بالإجَازَةِ لَفظًا فَقَدْ تَضَمَّنَتِ الإجَازَةَ مَعْنًى ثُمَّ يَكْفِي في ذلكَ أنْ يَعْرِفَ المكتُوبُ إليهِ خَطَّ الكَاتِبِ وإنْ لَمْ تَقُمِ البَيِّنَةُ عليهِ (١١). ومِنَ النَّاسِ مَنْ قَالَ: «الخَطُّ يُشْبِهُ الخَطَّ فَلاَ يَجُوزُ الاعْتِمادُ عَلَى ذلكَ» (١٢). وهذا غيرُ مَرْضِيٍّ؛ لأنَّ ذلكَ نادِرٌ، والظَّاهِرُ أنَّ خَطَّ الإنْسَانِ لاَ يَشْتَبِهُ بغَيْرِهِ ولاَ يَقَعُ فيهِ إلْبَاسٌ.","",{"fn":"نقله عنه الخطيب في الكفاية: (٤٨١ ت، ٣٣٧ هـ) و(٤٩٠ ت، ٣٤٣ - ٣٤٤ هـ)، والقاضي عياض في الإلماع: ٨٥.\nأسنده إليه الخطيب في الكفاية: (٤٨١ ت، ٣٣٧ هـ) و(٤٩٠ ت، ٣٤٣ - ٣٤٤ هـ)، والقاضي عياض في الإلماع: ٨٥.\nأسنده إليه الخطيب في الكفاية: (٤٩٠ - ٤٩١ ت، ٣٤٤ هـ).\nمنهم: الحسين بن إسماعيل المحاملي. الإلماع: ٨٤.\nقواطع الأدلة ١/ ٣٣٠.\nمنهم: الرازي. انظر: المحصول٢/ ١/٦٤٥، وأبو حامد الإسفراييني والمحاملي. انظر: نكت الزركشي ٣/ ٥٤٥.\nمنهم الغزالي في المستصفى ١/ ١٦٦، والآمدي في الإحكام ٢/ ٩٢.\n٢٠/ ١٤٧.\nانظر: الكفاية: (٤٨٩ ت، ٣٤٣ هـ)، والإلماع: ٨٥.\nفي (ب) و(جـ): «يقترن».\nقال البقاعي في النكت الوفية ٢٦٩ / أ: «أي: بشهادة اثنين أنهما رأياه يكتب ذلك فتكون شهادة على الفعل لا بالتخمين، بأنَّ هذا يشبه خطّه، فهو هو؛ لأنه يبعد كل البعد أن يوجد خطّ غير خطّه يحاكيه محاكاة يبعد معها التمييز».\nقاله الغزالي، ينظر: المستصفى ١/ ١٦٦، والبحر المحيط ٤/ ٤٩٢."}],[1045,"ثُمَّ ذَهَبَ غَيْرُ واحِدٍ مِنْ عُلَماءِ المحدِّثِيْنَ وأَكَابِرِهِمْ، منْهُمْ: اللَّيْثُ بنُ سَعْدٍ، ومَنْصُورٌ إلى جَوَازِ إطْلاَقِ «حَدَّثَنا وأخْبَرَنا» في الروايةِ بالمكاتَبَةِ (١)، والمختارُ قولُ مَنْ يَقُولُ فيها: «كَتَبَ إليَّ فُلاَنٌ: قالَ حَدَّثَنا فُلاَنٌ بِكَذَا وكَذَا»، وهذا هوَ الصحيحُ اللاَّئِقُ بِمَذْهَبِ أهْلِ التَّحَرِّي والنَّزَاهَةِ. وهَكَذَا لوْ قَالَ: «أخْبَرَنِي بهِ مُكَاتَبَةً، أوْ كِتَابَةً»، ونحوَ ذلكَ مِنَ العِبَاراتِ (٢)، واللهُ أعلمُ (٣)."],[1046,"أمَّا المكَاتَبةُ المقْرُونَةُ بِلَفْظِ الإجَازَةِ فَهِيَ في الصِّحَّةِ والقُوَّةِ شَبِيْهَةٌ بالمناولَةِ المقرُونَةِ بالإجَازَةِ، واللهُ أعلمُ."],[1047,"القِسْمُ السَّادِسُ مِنْ أقْسَامِ الأخْذِ ووُجُوهِ النَّقْلِ: إعْلاَمُ الراوي للطَّالِبِ بأنَّ هذا الحديثَ أوْ هذا الكِتابَ سَمَاعُهُ مِنْ فُلاَنٍ، أوْ روايَتُهُ مُقْتَصِرًا عَلَى ذلكَ مِنْ غيرِ أنْ يَقولَ: «ارْوِهِ عنِّي، أوْ أَذِنْتُ لَكَ في روايتِهِ»، أوْ نَحْوَ ذلكَ، فهَذا عِنْدَ كَثِيرينَ طَرِيقٌ مُجَوِّزٌ لِرِوايَةِ ذلكَ عنهُ ونَقْلِهِ. حُكِيَ ذلكَ عَنِ ابنِ جُرَيْجٍ وطَوَائِفَ مِنَ المحدِّثينَ والفُقَهَاءِ والأُصُولِيِّينَ والظَّاهِرِيِّيْنَ (٤)، وبهِ قَطَعَ أبو نَصْرِ بنُ الصَّبَّاغِ مِنَ الشَّافِعِيِّينَ (٥)، واخْتَارَهُ ونَصَرَهُ أبو العَبَّاسِ الوليدُ بنُ بَكْرٍ الغَمْرِيُّ (٦) المَالِكِيُّ (٧) في كِتَابِ \"الوِجَازَةِ في تَجْوِيْزِ الإجَازَةِ \"."],[1048,"وَحَكَى القَاضِي أبو محمَّدِ بنُ خَلاَّدٍ الرَّامَهُرْمُزِيُّ (٨) - صَاحبِ كِتابِ \" الفَاصِلِ بينَ الرَّاوِي والوَاعِي \" (٩) - عَنْ بعضِ أهلِ الظَّاهِرِ، أنَّهُ ذَهَبَ إلى ذلكَ واحْتَجَّ لهُ، وزادَ فقالَ: «لَوْ قَالَ لهُ (١): هذهِ رِوَايَتِي لَكِنْ لاَ تَرْوِها عَنِّي، كَانَ لهُ أنْ يَرْوِيَها عنهُ كما لَوْ سَمِعَ منهُ حَدِيثًا ثُمَّ قَالَ لهُ (٢): «لاَ تَرْوِهِ عَنِّي، ولاَ أُجِيْزُهُ لَكَ»، لَمْ يَضُرَّهُ ذَلِكَ». وَوَجْهُ مَذْهَبِ هَؤُلاَءِ اعْتِبَارُ ذلكَ بالقِرَاءَ ةِ عَلَى الشَّيخِ، فإنَّهُ إذا قَرَأَ عليهِ شَيْئًا مِنْ حَدِيثِهِ وأقَرَّ بأنَّهُ رِوَايَتُهُ عَنْ فُلاَنِ بنِ فُلاَنٍ (٣) جَازَ لهُ أنْ يَرْوِيَهُ عنهُ، وإنْ لَمْ يَسْمَعْهُ مِنْ لَفْظِهِ ولَمْ يَقُلْ لهُ: «ارْوِهِ عَنِّي، أوْ أَذِنْتُ لَكَ في رِوَايَتِهِ عَنِّي» (٤)، واللهُ أعلمُ.","",{"fn":"انظر: الكفاية: (٤٨٩ ت، ٣٤٣ هـ).\nانظر: الكفاية: (٤٨٨ ت، ٣٤٢ هـ).\nجملة: «والله أعلم» سقطت من ع، وهي من جميع النسخ الخطية.\nالإلماع: ١١٥.\nالبحر المحيط: ٤/ ٣٩٥.\nبفتح الغين، وسكون الميم، وفي آخرها الراء المهملة، هذه النسبة إلى غمر، وهم بطن من غافقة، وقد قيل: إن هذه النسبة بضم الغين أيضًا. الأنساب٤/ ٢٨٢، والتاج١٣/ ٢٦٦، وترجمته في سير أعلام النبلاء١٧/ ٦٥.\nالإلماع: ١٠٨.\nبفتح الراء والميم بينهما الألف، وضم الهاء وسكون الراء الأخرى، وضم الميم وفي آخرها الزاي، هذه النسبة إلى رامهرمز، وهي مدينة مشهورة بنواحي خوزستان. الأنساب ٣/ ٣٢، ومعجم البلدان ٣/ ١٧.\nكذا ذكره ياقوت في معجمه ٩/ ٥، وذكره غير واحد باسم: \" المحدّث الفاصل بين الراوي والواعي \". انظر: السِّيَر ١٦/ ٧٣، ونزهة النظر: ٤٧، وتدريب الراوي ١/ ٥٢، والرسالة المستطرفة: ٥٥و١٤٢."}],[1049,"والمختارُ ما ذُكِرَ عَنْ غَيْرِ واحِدٍ مِنَ المحدِّثِينَ وغَيْرِهِمْ، مِنْ أنَّهُ لاَ تَجُوزُ الروايةُ بذلكَ، وبهِ قَطَعَ الشَّيْخُ أبو حَامِدٍ الطُّوْسِيُّ (٥) مِنَ الشَّافِعِيِّينَ، ولَمْ يَذْكُرْ غَيْرَ ذلكَ؛ وهذا لأنَّهُ قَدْ يَكُونُ ذلكَ مَسْمُوعَهُ وروايَتَهُ، ثُمَّ لاَ يَأْذَنُ (٦) في روايتِهِ عنهُ؛ لِكَونِهِ لاَ يُجَوِّزُ روايَتَهُ لِخَلَلٍ يَعْرِفُهُ فيهِ وَلَمْ يُوجَدْ منهُ التَّلَفُّظُ بهِ، ولاَ مَا يَتَنَزَّلُ مَنْزِلَةَ تَلَفُّظِهِ بهِ (٧)، وهوَ تَلَفُّظُ القارِئِ عليهِ وهوَ يَسْمَعُ، ويُقِرُّ بهِ حَتَّى يَكُونَ قَولُ الراوي عنهُ السَّامِعِ ذلكَ: «حَدَّثَنا وأخْبَرَنا» صِدْقًا، وإنْ لَمْ يَأْذَنْ لهُ فيهِ. وإنَّما هذا (٨) كالشَّاهِدِ، إذا ذَكَرَ في غَيرِ مَجْلِسِ الحكمِ شَهَادتَهُ بشيءٍ فليسَ لِمَنْ يَسْمَعُهُ أنْ يَشْهَدَ عَلَى شَهَادَتِهِ، إذا لَمْ يَأْذَنْ لهُ ولَمْ يُشْهِدْهُ عَلَى شَهَادَتِهِ، وذلكَ مِمَّا تَسَاوَتْ فيهِ الشَّهَادَةُ والروايَةُ؛ لأنَّ المعنى يَجْمَعُ بَيْنَهُما في ذلكَ وإنِ افْتَرَقا (٩) في غيرِهِ."],[1050,"ثُمَّ إنَّهُ يَجبُ عليهِ العَمَلُ بما ذكَرَهُ لهُ إذا صَحَّ إسْنادُهُ وإنْ لَمْ تَجُزْ لهُ روايتُهُ عنهُ؛ لأنَّ ذلكَ يَكْفِي فيهِ صِحَّتُهُ في نفسِهِ، واللهُ أعْلَمُ.","",{"fn":"ساقطة من (أ).\nسقطت من (جـ).\nعبارة: «بن فلان» ساقطة من (أ).\nالمحدّث الفاصل: ٤٥١ - ٤٥٢، ونقله عنه الخطيب في الكفاية: (٤٩٨ - ٤٩٩ت، ٣٤٨ هـ)، والقاضي عياض في الإلماع: ١١٠.\nعنى بذلك الإمام الغزالي، وقوله في المستصفى ١/ ١٦٦، وإليه ذهب ابن حزم والماوردي وابن القطان والبيضاوي وابن السبكي والآمدي. ينظر: إحكام الأحكام ٢/ ٩١، والإبهاج ٢/ ٣٣٤، ونهاية السول ٣/ ١٩٦، ومحاسن الاصطلاح: ٢٩٠. وانظر: نكت الزركشي ٣/ ٥٤٩، وشرح التبصرة ٢/ ١٨٢.\nفي (ع): «ولا يأذن له»، وكلمة: «له» لم ترد في شيء من النسخ الخطية ولا (م).\nسقطت من (أ).\nفي (م): «هو».\nفي (أ) و(م) والشذا: «افترقتا»."}],[1051,"القِسْمُ السَّابِعُ مِنْ أقسَامِ الأَخْذِ والتَّحَمُّلِ: الوَصِيَّةُ بالكُتُبِ، بَأنْ (١) يُوصِيَ الراوي بِكِتابٍ يَرْوِيهِ عندَ موتِهِ أوْ سَفَرِهِ لِشَخْصٍ، فرُويَ عَنْ بعضِ السَّلَفِ (٢) - رضي الله عنهم - أنَّهُ جَوَّزَ بذلكَ روايةَ الْمُوصَى لهُ لذلكَ عَنِ الموصِي الراوي. وهذا بَعِيدٌ جِدًّا (٣)، وهوَ إمَّا زَلَّةُ عالِمٍ أو مُتَأَوَّلٌ على أنَّهُ أرادَ الروايةَ عَلَى سَبيلِ الوِجَادةِ التي يَأتِي شَرْحُها - إنْ"],[1052,"شَاءَ اللهُ تَعَالَى -."],[1053,"وقَدِ احْتَجَّ بعضُهُمْ لذلكَ فَشَبَّهَهُ بِقِسْمِ الإعْلاَمِ وقِسْمِ المناوَلَةِ، ولاَ يَصِحُّ ذلكَ فَإِنَّ لِقَوْلِ مَنْ جَوَّزَ الروايةَ بِمُجَرَّدِ الإعْلاَمِ والمنَاولَةِ مُسْتَنَدًا ذَكَرْنَاهُ لاَ يَتَقَرَّرُ مِثْلُهُ ولاَ قريبٌ (٤) منهُ هَاهُنا، واللهُ أعلمُ."],[1054,"القِسْمُ الثَّامِنُ: الوِجَادَةُ (٥): وهي مَصْدَرٌ لـ «وَجَدَ يَجِدُ» مُوَلَّدٌ غيرُ مَسْمُوعٍ مِنَ العَرَبِ (٦). رُوِّيْنا عَنِ الْمُعَافَى بنِ زَكَرِيَّا النَّهْرَوَانِيِّ (٧) العَلاَّمَةِ في العُلُومِ أنَّ الموَلَّدِينَ فَرَّعُوا قَوْلَهُمْ: «وِجَادَةً» فِيْمَا أُخِذَ مِنَ العِلْمِ مِنْ صَحِيْفَةٍ مِنْ غَيْرِ سَمَاعٍ ولاَ إجَازَةٍ وَلاَ مُنَاولةٍ، مِنْ تفريقِ العرَبِ بينَ مَصَادِرِ «وجَدَ»، للتَّمْيِيزِ بينَ المعانيَ المختَلِفةِ، يَعْنِي قَولَهُمْ:","",{"fn":"في (م): «أن» بدون باء.\nمنهم: ابن سيرين وأبو قلابة. ينظر: المحدّث الفاصل: ٤٥٩ - ٤٦٠، والكفاية: (٥٠٣ - ٥٠٤ ت، ٣٥٢ هـ)، والإلماع: ١١٥ - ١١٦، ونكت الزَّرْكَشِيّ ٣/ ٥٥١.\nوَقَدْ قَلَّدَ النوويُّ ابنَ الصلاحِ في هَذَا فَقَالَ: في التقريب: ١٢٠: «إنه لا يجوز»، وَقَدْ أنكر ابن أبي الدم عَلَى ابن الصَّلاح ردَّه عَلَى هَذَا فَقَالَ: «الوصية أرفع رتبة من الوجادة بلا خِلاَف، فإذا عمل بالوجادة فالوصية أولى». ينظر: نكت الزركشي ٣/ ٥٥٠ - ٥٥١، وتدريب الراوي ٢/ ٦٠، وفتح المغيث ٢/ ١٣٣.\nفي الشذا: «يتقرب».\nبكسر الواو. شرح التبصرة والتذكرة ٢/ ١٨٩، والتاج ٩/ ٢٦٠.\nقال: ابن كثير: «الوجادة ليست من باب الرواية، وإنما هي حكاية عما وجده في الكتاب. وقال الشيخ أحمد شاكر: «وإنما ذكر العلماء الوجادة في هذا الباب إلحاقًا به لبيان حكمها وما يتخذه الناقل في سبيلها». اختصار علوم الحديث: ١٢٨، والباعث الحثيث: ١٣٠.\nبفتح النون وسكون الهاء وفتح الراء المهملة والواو، وفي آخرها نون أخرى. الأنساب ٥/ ٤٤٦، وانظر: التاج ١٤/ ٣١٩. وترجمته في تاريخ بغداد ١٣/ ٢٣٠، ومعجم الأدباء ١٩/ ١٥١، والسيِّر ١٦/ ٥٤٤."}],[1055,"وَجَدَ ضَالَّتَهُ وِجْدَانًا، ومَطْلُوبَهُ وُجُودًا، وفِي الغَضَبِ: مَوْجِدَةً، وَفِي الغِنَى: وُجْدًا (١)، وفِي الْحُبِّ: وَجْدًا (٢)."],[1056,"مِثَالُ الوِجَادَةِ: أنْ يَقِفَ على كِتَابِ شَخْصٍ فيهِ أحاديثُ يَروِيها بِخَطِّهِ وَلَمْ يَلْقَهُ، أوْ لَقِيَهُ ولكِنْ لَمْ يَسْمَعْ منهُ ذلكَ الذي وَجَدَهُ بِخَطِّهِ، ولاَ لهُ منهُ إجَازَةٌ ولاَ نَحْوُها، فلَهُ أنْ يَقُولَ: وَجَدْتُ بِخَطِّ فُلاَنٍ (٣)، ويَذْكُرَ شَيْخَهُ، ويَسُوقَ سَائِرَ الإسْنَادِ والمتْنِ (٤)، أوْ يَقُولَ: وَجَدْتُ، أوْ قَرَأْتُ بِخَطِّ فُلاَنٍ عَنْ فُلاَنٍ، ويَذْكُرَ الذي حَدَّثَهُ ومَنْ فَوْقَهُ. هذا الذي اسْتَمَرَّ عليهِ العَمَلُ قَدِيمًا وحَدِيثًا، وهوَ مِنْ بابِ المنقَطِعِ والمرسَلِ (٥) غيرَ أنَّهُ أَخَذَ شَوْبًا مِنَ الاتِّصَالِ بقَوْلِهِ: وَجَدْتُ بخَطِّ فُلاَنٍ."],[1057,"ورُبَّما دَلَّسَ بعضُهُمْ فَذَكَرَ الذي وَجَدَ خَطَّهُ، وقَالَ (٦) فيهِ: عَنْ فُلاَنٍ، أوْ قَالَ فُلانٌ؛ وذَلكَ تَدليسٌ قَبيحٌ إذا كَانَ بحيثُ يُوهِمُ سَمَاعَهُ منهُ عَلَى مَا سَبَقَ في نوعِ التَّدليسِ. وجَازَفَ بعضُهُمْ فأطْلَقَ فيهِ: حَدَّثَنا وأَخْبَرَنا (٧)، وانْتُقِدَ ذلكَ عَلَى فاعِلِهِ. وإذا وَجَدَ حَدِيْثًا في تأليفِ شَخْصٍ وليسَ بخَطِّهِ، فَلَهُ أنْ يَقُولَ: ذَكَرَ فُلاَنٌ، أوْ قَالَ فلاَنٌ: أخْبَرَنا فُلاَنٌ، أوْ ذَكَرَ فُلاَنٌ عَنْ فُلاَنٍ. وهذا مُنْقَطِعٌ لَمْ يَأْخُذْ شَوْبًا مِنَ الاتِّصَالِ. وهَذا كُلُّهُ إذا وَثِقَ بأنَّهُ خَطُّ المذكورِ أوْ كِتابُهُ، فإنْ لَمْ يَكُنْ كَذَلِكَ فَلْيَقُلْ: بَلَغَنِي عَنْ فُلاَنٍ، أوْ وَجَدْتُ عَنْ فُلاَنٍ أوْ نَحْوَ ذَلِكَ مِنَ العِبَاراتِ، أوْ لِيُفْصِحْ بالمسْتَنَدِ (١) فيهِ بأنْ يقولَ مَا قَالَهُ بعضُ مَنْ تَقَدَّمَ: قَرَأْتُ في كِتَابِ فُلاَنٍ بخَطِّهِ، وأخْبَرَنِي فُلاَنٌ أنَّهُ بخَطِّهِ، أوْ يَقُولَ: وَجَدْتُ في كِتابٍ ظَنَنْتُ أنَّهُ بخَطِّ فُلاَنٍ، أو في كِتابٍ ذَكَرَ كَاتِبُهُ أنَّهُ فُلاَنُ بنُ فُلانٍ، أوْ في كِتابٍ قيلَ: إنَّهُ بخَطِّ فُلاَنٍ.","",{"fn":"ضبطه السيوطي في شرحه على ألفية العراقي: ٢٩٨ بالضم، قلنا: ويجوز ضبطه بالفتح، والكسر أيضًا، فهو مثلث. انظر: الصحاح ٢/ ٥٤٧، ومقاييس اللغة ٦/ ٨٦، ولسان العرب ٣/ ٤٤٥.\nوهناك مصادر أخرى للفعل لم يذكرها المصنف، انظرها في نكت الزركشي ٣/ ٥٥١، والتقييد والإيضاح: ٢٠٠، وشرح التبصرة ٢/ ١٨٩، وتاج العروس ٩/ ٢٥٣.\nقال الزركشي في نكته ٣/ ٥٥٣: «وهذا إنما يصح إذا تحقق أنه خطّه بأن كتبه بحضوره وهو يراه، أو قال له: هذا خطّي، وإلاّ فليقل: رأيتُ مكتوبًا بخطّ ظننت أنه خط فلان، فإن الخط قد يشبه الخط، وبذلك عبّر الغزالي في المستصفى». وانظر: المستصفى ١/ ١٦٦.\nبعد هذا في (ع): «معًا»، ولم ترد في شيء من النسخ ولا في (م).\nقال الزركشي في نكته ٣/ ٥٥٣: «وهكذا قال الحافظ رشيد الدين القرشي في الغرر المجموعة: «الوجادة داخلة في باب المقطوع عند علماء الرواية»، وقد يقال: بل عده من التعليق أولى من المرسل والمنقطع».\nفي (جـ): «فقال».\nمنهم: إسحاق بن راشد، رواه عنه الحاكم في معرفة علوم الحديث: ١١٠، ومن طريقه القاضي عياض في الإلماع: ١١٩. ومنهم المرزباني، وأبو نعيم الأصبهاني، وقد تقدم الكلام عنهما."}],[1058,"وإذا أرادَ أنْ يَنْقُلَ مِنْ كِتابٍ مَنْسُوبٍ إلى مُصَنِّفٍ فَلا يَقُلْ: قَالَ فُلاَنٌ كَذا"],[1059,"وكَذا، إلاَّ إذا وَثِقَ بِصِحَّةِ النُّسْخَةِ، بأنْ قَابَلَها هُوَ أوْ ثِقَةٌ غيرُهُ بأُصُولٍ مُتَعَدِّدَةٍ كَما نَبَّهَنا عليهِ في آخِرِ النَّوْعِ الأوَّلِ. وإذا لَمْ يُوجَدْ ذلكَ ونَحْوُهُ (٢) فَلْيَقُلْ: بَلَغَنِي عَنْ فُلاَنٍ أنَّهُ ذَكَرَ كذا وكذا، أوْ وَجَدْتُ في نُسْخَةٍ مِنَ الكِتابِ الفُلاَنِيِّ، وما أشْبَهَ هذا مِنَ العِبَاراتِ."],[1060,"وقَدْ تسَامَحَ أكْثَرُ النَّاسِ في هذهِ الأزْمَانِ بإطْلاَقِ اللفْظِ الجازِمِ في ذلكَ، مِنْ غيرِ تَحَرٍّ وتَثَبُّتٍ، فَيُطَالِعُ أحَدُهُمْ كِتابًا مَنْسُوبًا إلى مُصَنِّفٍ مُعَيَّنٍ، وينقُلُ منهُ عَنْهُ مِنْ غيرِ أنْ يَثِقَ بصِحَّةِ النُّسْخَةِ قَائِلًا: قَالَ فُلاَنٌ كذا وكذا، أوْ ذَكَرَ فُلاَنٌ كذا وكذا، والصوابُ مَا قَدَّمْناهُ."],[1061,"فإنْ كَانَ المطَالِعُ عَالِمًا فَطِنًا بحيثُ لاَ يَخْفَى عليهِ في الغالبِ مَوَاضِعُ الإسْقَاطِ والسَّقَطِ (٣) ومَا أُحِيْلَ عَنْ جِهَتهِ (٤) مِنْ (٥) غيرِها رَجَوْنا أنْ يَجُوزَ لهُ إطْلاَقُ (٦) اللَّفْظِ الجازِمِ فيما يَحْكِيْهِ مِنْ ذلكَ. وإلى هذا فيما أحسَبُ اسْتَرْوَحَ كَثِيرٌ مِنَ المصَنِّفِينَ فيما نَقَلُوهُ مِنْ كُتُبِ النَّاسِ، والعِلْمُ عِنْدَ اللهِ تعَالَى.","",{"fn":"في (ب): «بالمسند».\nفي (ب): «ولا نحوه».\nقال البقاعي: «قوله: مواضع الإسقاط - بالكسر - مصدر أسْقَطَ الشيءَ إذا ألْقَاهُ فالمراد المواضع التي ترك فيها كلام اختل به المعنى. والسَّقَطُ - محرّكًا - الرديء والخطأ في الكلام والكتاب والحساب». النكت الوفية ٢٧٣ / ب.\nأي: بضرب من التأويل. النكت الوفية ٢٧٣ / ب.\nفي (ع): «إلى»، وما أثبتناه من النسخ.\nفي (ع): «إطلاقه»."}],[1062,"هذا كُلُّهُ كَلاَمٌ في كَيْفِيَّةِ النَّقْلِ بطَرِيقِ الوِجَادَةِ."],[1063,"وأمَّا جَوازُ العَمَلِ اعْتِمَادًا على مَا يُوثَقُ بهِ مِنْهَا، فقَدْ رُوِّيْنا عَنْ بعضِ (١) المالِكِيَّةِ أنَّ مُعْظَمَ المحدِّثينَ والفُقَهَاءِ مِنَ المالِكيِّينَ وغَيْرِهِمْ لاَ يَرَوْنَ العَمَلَ بذلِكَ. وحُكِيَ عَنِ الشَّافِعِيِّ وطَائِفَةٍ مِنْ نُظَّارِ أصْحابِهِ جَوَازُ العَمَلِ بهِ (٢). قُلْتُ: قَطَعَ بعضُ المحقِّقِينَ (٣) مِنْ أصْحَابِهِ في أُصُولِ الفِقْهِ بِوُجُوبِ العَمَلِ بهِ عِنْدَ حُصُولِ الثِّقَةِ بهِ، وقالَ: «لَوْ عُرِضَ ما ذَكَرْناهُ على جُمْلَةِ المحدِّثينَ لأبَوهُ» (٤)، ومَا قَطَعَ بهِ هوَ الذي لاَ يَتَّجِهُ غيرُهُ في الأعْصارِ المتأخِّرةِ، فإنَّهُ لوْ تَوَقَّفَ العَمَلُ فيها على الروايةِ لانْسَدَّ بابُ العَمَلِ بالمنْقُولِ؛ لِتَعَذُّرِ شَرْطِ الروايةِ فيها على ما تَقَدَّمَ في النَّوعِ الأوَّلِ، واللهُ أعلمُ.","",{"fn":"هذا المبهم بيّنه الزركشي في نكته ٣/ ٥٥٤، وهو القاضي عياض في إلماعه: ١٢٠.\nالإلماع: ١٢٠، وقال: «وهو الذي نصره الجويني، واختاره غيره من أرباب التحقيق، وهذا مبنيٌّ على مسألة العمل بالمرسل». قلنا: انظر: البرهان ١/ ٤١٦ فقرة (٥٩٢)، وشرح التبصرة والتذكرة ٢/ ١٩٣، والنكت الوفية: ٢٧٢ / ب.\nعنى بذلك الجويني وكلامه في البرهان ١/ ٤١٦ فقرة (٥٩٢).\nقال البقاعي: «قوله: لأبَوْهُ، يعني: لما تقدّم من أنّ معظمهم لا يرون العمل به، هذا على تقدير: كونه بالباء الموحدة، ويحتمل أن يكون بالمثناة الفوقانية من الإتيان، يعني: لعملوا به لوضوح دليله، وَهُوَ أن مدار وجوب العمل بالحديث الوثوق بنسبته إلى الشارع - صلى الله عليه وآله وسلم - لا اتّصاله بالرواية». النكت الوفية ٢٧٣/أ."}],[1064,"النوع الخامس والعشرون في كتابة الحديث وكيفية ضبط الكتاب وتقييده"],[1065,"اخْتَلَفَ الصَّدْرُ الأوَّلُ - رضي الله عنهم - في كِتابَةِ الحديثِ، فَمِنهُمْ مَنْ كَرِهَ كِتَابَةَ الحديثِ والعِلْمِ وأمَرُوا بحفْظِهِ، وَمِنهُمْ مَنْ أجَازَ ذلكَ (١)."],[1066,"ومِمَّنْ رُوِّيْنا عنهُ كَرَاهَةَ ذلكَ: عُمَرُ (٢)، وابنُ مَسْعُودٍ، وزَيْدُ بنُ ثَابِتٍ، وأبو مُوْسَى، وأبو سَعِيْدٍ الْخُدْرِيُّ (٣) في جَمَاعَةٍ آخَرِيْنَ مِنَ الصحابَةِ والتَّابِعِينَ. ورُوِّيْنا عَنْ أبي سَعِيْدٍ الْخُدْرِيِّ أنَّ النبِيَّ - صلى الله عليه وآله وسلم - قالَ: «لاَ تَكْتُبُوا عَنِّي شَيْئًا إلاَّ القُرْآنَ، ومَنْ كَتَبَ عَنِّي شَيْئًا غيرَ القُرْآنِ فَلْيَمْحُهُ». أخرجَهُ مُسْلِمٌ (٤) في \" صحيحِهِ \". ومِمَّنْ رُوِّيْنا عنهُ إبَاحَةَ ذلكَ - أوْ فَعَلَهُ -: عَلِيٌّ (٥)، وابْنُهُ الحسَنُ (٦)، وأنَسٌ (٧)، وعبدُ اللهِ بنُ عَمْرِو بنِ العَاصِ (١) في جَمْعٍ (٢) آخَرِيْنَ مِنَ الصَّحابَةِ والتَّابعيْنَ - رضي الله عنهم - أجْمَعِينَ.","",{"fn":"في ذلك مناقشات ومباحثات طويلة تنظر في: تقييد العلم: ٢٨ - ١١٦، ونكت الزركشي ٣/ ٥٥٦، ومحاسن الاصطلاح: ٢٩٦.\nقال الزركشي ٣/ ٥٥٦: «هكذا قال ابن شاهين في كتاب الناسخ والمنسوخ. وقد جاء عن عمر الجواز، قال الحاكم في مستدركه ١/ ١٠٦: «قد صحت الرواية عن عمر بن الخطاب أنه قال: قيّدوا العلم بالكتابة».\nعقَّب الزركشي على ذلك فقال في نكته ٣/ ٥٥٨: «بل جاء عن أبي سعيد أنه استأذن النبي - صلى الله عليه وآله وسلم - في كتب الحديث فلم يأذن له، رواه الخطيب في كتاب تقييد العلم». قلنا: انظر: تقييد العلم: ٣٦، وقد رواه أيضًا الدارمي (٤٥٧)، والترمذي (٢٦٦٥) فعزوه إليهما أفضل.\nصحيح مسلم ٨/ ٢٢٩ (٣٠٠٤). وأخرجه أحمد ٣/ ١٢ و٢١ و٣٩ و٤٦ و٥٦، والدارمي (٤٥٦)، والنسائي في الكبرى (٨٠٠٨)، وفي فضائل القرآن (٣٣) جميعهم من طريق همام بن يحيى، عن زيد بن أسلم، عن عطاء بن يسار، عن أبي سعيد، به مرفوعًا.\nرواه عنه البخاري في صحيحه ١/ ٣٨ (١١١)، والخطيب البغدادي في تقييد العلم: ٨٨ - ٩١، وابن عبد البر في جامع بيان العلم ١/ ٧١.\nرواه عنه الخطيب البغدادي في تقييد العلم: ٩١، وابن عبد البر في جامع بيان العلم ١/ ٨٢.\nرواه عنه الدارمي (٤٩٧)، والرامهرمزي في المحدّث الفاصل: ٣٦٦ و٣٦٨، والخطيب البغدادي في تقييد العلم: ٩٤ - ٩٧، وابن عبد البر في جامع بيان العلم ١/ ٧٣، والقاضي عياض في الإلماع: ١٤٧."}],[1067,"ومِنْ صَحِيْحِ حَديثِ رَسُولِ اللهِ - صلى الله عليه وآله وسلم - الدَّالِّ عَلَى جَوَازِ ذلكَ: حَدِيثُ أبي شَاهٍ (٣) اليَمَنِيِّ في التِمَاسِهِ مِنْ رِسُولِ اللهِ أنْ يَكْتُبَ لَهُ شَيْئًا سَمِعَهُ مِنْ خُطْبَتِهِ (٤) عَامَ فَتْحِ مَكَّةَ، وقَولُهُ - صلى الله عليه وآله وسلم -: «اكْتُبُوا لأبي شَاهٍ» (٥). ولَعَلَّهُ - صلى الله عليه وآله وسلم - أَذِنَ في الكِتَابَةِ عنهُ لِمَنْ خَشِيَ عليهِ النِّسْيانَ (٦)، ونَهَى عَنِ الكِتَابَةِ عنهُ مَنْ وَثِقَ بحِفْظِهِ، مَخَافَةَ الاتِّكَالِ عَلَى الكِتابِ، أوْ نَهَى عَنْ كِتابَةِ ذلكَ عنهُ حينَ خَافَ عليهِم اخْتِلاَطَ ذلكَ بصُحُفِ القُرآنِ العَظيمِ (٧)، وأَذِنَ في كِتَابَتِهِ حِيْنَ أَمِنَ مِنْ ذَلِكَ. وأخْبَرَنا أبو الفَتْحِ ابنُ عبدِ الْمُنْعِمِ الفُرَاوِيُّ (١) قِرَاءةً عليهِ بنيْسَابُورَ - جَبَرَها اللهُ -، قَالَ: أخْبَرَنا أبو الْمَعَالِي الفَارِسِيُّ، قَالَ: أخْبَرَنا الحافِظُ أبو بَكْرٍ البَيْهَقِيُّ، قَالَ: أخْبَرَنا أبو الْحُسَيْنِ بنُ بِشْرَانَ، قَالَ: أخْبَرَنا أبو عَمْرِو بنُ السَّمَّاكِ، قَالَ: حَدَّثَنا حَنْبَلُ بنُ إسْحَاقَ، قَالَ: حَدَّثَنا سُلَيْمَانُ بنُ أحمدَ، قَالَ: حَدَّثَنا الوليدُ - هوَ ابنُ مُسْلِمٍ -، قَالَ: كَانَ الأوزاعِيُّ يَقُولُ: «كَانَ هذا العِلْمُ كَرِيْمًا يَتَلاَقَاهُ الرِّجَالُ بَينَهُمْ، فَلَمَّا دَخَلَ في الكُتُبِ دَخَلَ فيهِ غيرُ أهْلِهِ» (٢). ثُمَّ إنَّهُ زَالَ ذلكَ الخِلاَفُ وأجْمَعَ المسْلِمُونَ عَلَى تَسْوِيْغِ (٣) ذلكَ وإباحَتِهِ، ولَوْلاَ تَدْوِيْنُهُ في الكُتُبِ لَدَرَسَ في الأعْصُرِ الآخِرَةِ، واللهُ أعلمُ.","",{"fn":"رواه عنه الإمام أحمد في مسنده ٢/ ١٦٢، الدارمي (٤٩٠)، (٤٩٢)، وأبو داود (٣٦٤٦)، والحاكم في المستدرك ١/ ١٠٥ - ١٠٦، والخطيب البغدادي في تقييد العلم: ٧٤، ٨٢، وابن عبد البر في جامع بيان العلم ١/ ٧١، والقاضي في الإلماع: ١٤٦.\nفي (ب): «جماعة».\nقال البقاعي: «رأيت على حاشية كتاب ابن الصلاح بخطٍّ لا أعرفه ما صورته: وقع في \"المشارق\" المقروءة على الصنعاني والترمذي المقروءة على القاضي عياض وعليهما خطَّاهما بالتاء المثناة من فوق، والمحدثون من فضلاء مصر لا يروونه إلا بالهاء، وكذا سمعه الحافظ زين الدين العراقي». النكت الوفية ٢٧٤ / ب. قلنا: قال النووي في شرح صحيح مسلم ٣/ ٥٠٦: «هو بهاء تكون هاء في الوقف والدرج، ولا يقال بالتاء ...». وقال الحافظ ابن حجر في الفتح ١/ ٢٠٦: «هو بهاء منونة»، وقال في مكان آخر ١٢/ ٢٠٨: «وحكى السلفي أن بعضهم نطق بها بتاء في آخره وغلَّطه، وقال هو فارسي من فرسان الفرس الذين بعثهم كسرى إلى اليمن» وانظر: الإصابة ٤/ ١٠٠.\nفي (م): «خطبة».\nجزء من حديث طويل، أخرجه أحمد ٢/ ٢٣٨، والبخاري ١/ ٣٨ - ٣٩ (١١٢) و٣/ ١٦٤ - ١٦٥ (٢٤٣٤) و٩/ ٦ (٦٨٨٠)، ومسلم ٤/ ١١٠ - ١١١ (١٣٥٥)، وأبو داود (٢٠١٧) و(٣٦٤٩) و(٤٥٠٥) والترمذي (٢٦٦٧)، وابن حبان (٣٧١٥)، والدارقطني ٣/ ٩٦ - ٩٨ والبيهقي ٨/ ٥٢، وفي دلائل النبوة ٥/ ٨٤، والخطيب في الفقيه والمتفقه ١/ ٩١ كلهم من طريق يحيى ابن أبي كثير، عن أبي سلمة، عن أبي هريرة.\nانظر: نكت الزركشي ٣/ ٥٥٨ - ٥٦٥.\nقال البقاعي: «أي: بسبب أنه لم يكن اشتد ألف الناس له وكثر حُفَّاظه المعتنون به فلمّا ألفه الناس وعرفوا أساليبه وكمال بلاغته، وحُسن تناسب فواصله وغاياته صارت لهم ملكة يميزون بها عن غيره فلم يُخْشَ اخْتِلاطه بعد ذلك». النكت الوفية: ٢٧٨ / أ."}],[1068,"ثُمَّ إنَّ عَلَى كَتَبَةِ الحديثِ وطَلَبَتِهِ صَرْفَ الهِمَّةِ إلى ضَبْطِ مَا يَكْتُبُونَهُ أوْ يُحَصِّلُونَهُ بخَطِّ الغَيْرِ (٤) مِنْ مَرْوِيَّاتِهِمْ عَلَى الوجْهِ الذي رَوَوْهُ شَكْلًا ونَقْطًا يُؤْمَنُ مَعَهُما الالتباسُ، وكَثِيرًا ما يَتَهَاوَنُ بذلكَ الواثِقُ بذِهْنِهِ وتَيَقُّظِهِ وذلكَ وَخِيْمُ العاقِبَةِ، فإنَّ الإنْسَانَ مُعَرَّضٌ للنِّسْيانِ، وأوَّلُ ناسٍ أوَّلُ الناسِ (٥)، وإعْجَامُ المكتوبِ يَمْنَعُ مِنَ اسْتِعْجَامِهِ، وشَكْلُهُ يَمْنَعُ مِنْ إشْكَالِهِ، ثُمَّ لاَ يَنْبَغِي أنْ يَتَعَنَّى بتَقْييدِ الواضِحِ الذي لاَ يَكَادُ يَلْتَبِسُ (٦). وقَدْ أحْسَنَ مَنْ قَالَ: إنَّما يُشْكَلُ مَا يُشْكِلُ (١). وقَرَأْتُ بِخَطِّ صَاحِبِ كِتابِ \" سِماتِ الخطِّ ورُقُومِهِ \" عَلِيِّ بنِ إبْرَاهِيمَ البغْدَادِيِّ فيهِ أنَّ أهلَ العِلْمِ يَكْرَهُونَ الإعْجَامَ والإعْرَابَ إلاَّ في (٢) الْمُلْتَبِسِ. وحَكَى غيرُهُ عَنْ قَومٍ أنَّهُ يَنْبَغِي أنْ يُشْكَلَ مَا يُشْكِلُ ومَا لاَ يُشْكِلُ؛ وذلكَ لأنَّ المبتَدِئَ وغيرَ المتَبَحِّرِ في العِلْمِ لاَ يُمَيِّزُ ما يُشْكِلُ مِمَّا لاَ يُشْكِلُ، ولاَ صَوابَ الإعْرَابِ مِنْ خَطَئِهِ (٣)، واللهُ أعلمُ.","",{"fn":"هذه النسبة إلى فراوة، وهي بليدة مما يلي خوارزم، وضبطها بعضهم: بضم الفاء، وبعضهم بفتحها. انظر: الأنساب ٤/ ٦١٥، ووفيات الأعيان ٤/ ٢٩١، وتبصير المنتبه ٣/ ١١٠٠، ومعجم البلدان ٤/ ٢٤٥.\nأخرجه من طريق الوليد بن مسلم عن الأوزاعي الخطيب في تقييد العلم: ٦٤، وابن عبد البر في بيان العلم ١/ ٦٨. وأخرجه الدارمي (٤٧٣) من طريق ابن المبارك، عن الأوزاعي. وانظر: محاسن الاصطلاح: ٣٠٢.\nفي (م): «توسيع».\nقال الزركشي في نكته ٣/ ٥٦٨: «قد استنكر بعض أهل اللغة إدخال الألف واللام على (غير) ...». قلنا: انظر بيان ذلك في تهذيب الأسماء واللغات ٣/ ٦٥، والتاج ١٣/ ٢٨٥.\nإشارة إلى عجز بيت لأبي الفتح البستي، أوله: نَسِيْتُ وَعْدَكَ، والنِّسْيانُ مُغْتَفَرٌ ... فَاغْفِرْ فَأَوَّلُ نَاسٍ أوَّلُ الناسِ الغيث المسجم في شرح لامية العجم للصفدي ٢/ ٢٠٨، وانظر: نكت الزَّرْكَشِيّ ٣/ ٥٦٥، وفتح المغيث ٢/ ١٤٨.\nقال العراقي في التقييد: ٢٠٥: «اقتصر المصنف على ذكر كتابة اللفظة المشكلة في الحاشية مفردة مضبوطة، ولم يتعرض لتقطيع حروفها، وهو متداول بين أهل الضبط، وفائدته ظهور شكل الحرف بكتابته مفردًا، كالنون، والياء إذا وقعت في أول الكلمة، أو في وسطها. ونقله ابن دقيق العيد في الاقتراح (٢٨٦) عن أهل الإتقان»."}],[1069,"وهذا بيانُ أُمُورٍ مُفِيدَةٍ (٤) في ذلِكَ:"],[1070,"أحَدُها: يَنْبَغِي أنْ يَكُونَ اعْتِنَاؤُهُ - مِنْ بَيْنِ مَا يَلْتَبِسُ - بِضَبْطِ الْمُلْتَبِسِ مِنْ أسْمَاءِ النَّاسِ (٥) أكْثَرَ، فإنَّهَا لاَ تُسْتَدْرَكُ بالمعْنَى، ولاَ يُسْتَدَلُّ علَيْهَا بِمَا قَبْلُ ومَا بَعْدُ."],[1071,"الثَّانِي: يُسْتَحَبُّ في الألفَاظِ المشْكِلَةِ أنْ يُكَرَّرَ ضَبْطُهَا بأنْ يَضْبِطَها (٦) في مَتْنِ الكِتابِ ثُمَّ يَكْتُبَهَا قُبَالَةَ ذَلِكَ في الحاشِيَةِ مُفْرَدَةً مَضْبُوطَةً، فإنَّ ذلكَ أبْلَغُ في إبانَتِهَا وأبْعَدُ مِنْ التِبَاسِها، ومَا ضَبَطَهُ في أثْناءِ الأسْطُرِ رُبَّمَا دَاخَلَهُ نَقْطُ غيرِهِ وشَكْلِهِ مِمَّا (٧) فَوْقَهُ وتَحْتَهُ لاَ سِيَّمَا عِنْدَ دِقَّةِ الخطِّ، وضِيْقِ الأسْطُرِ، وبِهَذا جَرَى رَسْمُ جَمَاعَةٍ مِنْ أهْلِ الضَّبْطِ، واللهُ أعلمُ."],[1072,"الثَّالِثُ: يُكْرَهُ الخطُّ الدَّقِيقُ مِنْ غَيْرِ عُذْرٍ يَقْتَضِيْهِ (٨). رُوِّيْنَا عَنْ حَنْبَلِ بنِ إسْحَاقَ قالَ: رآني أحمدُ بنُ حَنْبَلٍ وأنا أَكْتُبُ خَطًّا دَقِيقًا، فقالَ: «لاَ تَفْعَلْ، أحْوَجَ مَا تَكُونُ إليهِ يَخُونُكَ» (٩)، وبَلَغَنا عَنْ بَعضِ المشَايِخِ أنَّهُ كَانَ إذا رأَى خَطًّا دَقِيْقًا قَالَ: هذا خَطُّ مَنْ لاَ يُوقِنُ بالخَلَفِ (١)، مِنَ اللهِ» (٢).","",{"fn":"المحدِّث الفاصل: ٦٠٨، والإلماع: ١٥٠، وانظر: نكت الزركشي ٣/ ٥٦٩.\nسقطت من (م).\nالإلماع: ١٥٠، وقال القاضي: «وهذا هو الصواب».\nفي (ب): «مقيدة».\nلأنه لا يدخله القياس ولا قبله شيء يدل عليه. الجامع لأخلاق الراوي ١/ ٢٦٩ - ٢٧٠، والإلماع: ١٦٤، ونكت الزركشي ٣/ ٥٧١، وشرح التبصرة ٢/ ٢٠٣.\nانظر: الاقتراح: ٣٨٦، ونكت الزركشي ٣/ ٥٧٢.\nفي (ب): «بما».\nانظر: أدب الإملاء والاستملاء: ١٦٧ - ١٦٨، ونكت الزركشي ٣/ ٥٧٢.\nأخرجه الخطيب في الجامع (٥٣٧)، وابن السمعاني في أدب الإملاء: ١٦٧."}],[1073,"والعُذْرُ في ذلكَ هوَ مثلُ أنْ لاَ يَجِدَ في الوَرَقِ سَعَةً، أوْ يَكُونَ رَحَّالًا يَحْتَاجُ إلى تَدْقِيقِ الخطِّ ليَخِفَّ عليهِ مَحْمَلُ كِتَابِهِ (٣)، ونحوِ هذا (٤)."],[1074,"الرَّابِعُ: يُخْتَارُ لهُ في خطِّهِ التَّحْقِيقُ دونَ الْمَشْقِ (٥) والتَّعليقِ (٦). بَلَغَنا عَنِ ابنِ قُتَيبةَ قالَ: قالَ عمرُ بنُ الخطَّابِ - رضي الله عنه -: «شَرُّ الكِتَابَةِ الْمَشْقُ، وشَرُّ القِرَاءةِ الْهَذْرَمَةُ (٧)، وأجْوَدُ الخطِّ أبْيَنُهُ» (٨)، واللهُ أعلمُ."],[1075,"الخَامِسُ: كَمَا تُضْبَطُ الحروفُ المعْجَمَةُ بالنَّقْطِ، كذلكَ يَنْبَغِي أنْ تُضْبَطَ المهْمَلاَتُ غيرُ المعجمَةِ بعَلاَمَةِ الإهْمَالِ؛ لِتَدُلَّ على عَدَمِ إعْجَامِها."],[1076,"وسَبيلُ النَّاسِ في ضَبْطِهَا مُخْتَلِفٌ، فمِنْهُمْ مَنْ يَقْلِبُ النُّقَطَ، فيَجْعَلُ النُّقَطَ الذي (٩) فَوْقَ المعجَمَاتِ (١٠) تحتَ مَا يُشَاكِلُها مِنَ المهْمَلاَتِ، فَيَنْقُطُ تحتَ الرَّاءِ، والصَّادِ، والطَّاءِ، والعينِ، ونحوِهَا مِنَ المهمَلاَتِ. وذَكَرَ بعضُ هَؤُلاَءِ أنَّ النُّقَطَ التي تحتَ السِّيْنِ المهْمَلَةِ تَكُونُ مَبْسُوطَةً صَفًّا، والتي فَوقَ الشِّيْنِ المعْجَمَةِ تَكُونُ كَالأَثَافِيِّ (١). ومِنَ النَّاسِ مَنْ يَجْعَلُ عَلاَمةَ الإهْمالِ فَوقَ الحروفِ المهمَلَةِ كَقُلاَمَةِ الظُّفْرِ مُضْجَعةٌ (٢) عَلى قَفَاها. ومِنْهُمْ مَنْ يَجْعَلُ تحتَ الحاءِ المهمَلَةِ حَاءً مُفْرَدَةً صَغِيرةً، وكذا تحتَ الدَّالِ، والطَّاءِ، والصَّادِ، والسِّيْنِ، والعَيْنِ، وسَائِرِ الحروفِ المهْمَلَةِ الملتَبِسَةِ مثلُ ذلكَ.","",{"fn":"قال الزركشي في نكته ٣/ ٥٧٢: «بفتحتين - أي: الخلف - ما يخلف من بعد، يشير إلى أن داعيته الحرص على ما عنده من الكاغد؛ إذ لو كان يعلم أنه مستخلف لوسع». قلنا: انظر عن الخلف: لسان العرب ٩/ ٨٩، والتاج ٢٣/ ٢٤٥.\nأخرجه الخطيب في الجامع لأخلاق الراوي وآداب السامع (٥٣٨).\nذكر الخطيب هذا الكلام في الجامع ١/ ٢٦١ وساقه المصنف بمعناه، ولم يصرح به.\nبعد هذا في (ع): «والله أعلم»، ولم ترد في شيء من النسخ ولا (م).\nالْمَشْق: السرعة في الكتابة. انظر: الصحاح ٤/ ١٥٥٥، ونكت الزركشي ٣/ ٥٧٢.\nقال البقاعي في نكته الوفية ٢٨١/أ: «الذي يظهر في تفسيره أنه خلط الحروف التي ينبغي تفرقتها، وذهاب أسنان ما ينبغي إقامة أسنانه، وطمس ما ينبغي إظهار بياضه ونحو ذلك». وانظر: فتح المغيث ٢/ ٢٥٠.\nالهذرمة: السرعة في القراءة. انظر: الصحاح ٥/ ٢٠٥٧.\nأخرجه الخطيب في الجامع (٥٤١).\nكذا في الأصول، ونقل هذا النص ابن طاهر الجزائري في توجيه النظر ٢/ ٧٨٠، وفيه: «النُّقَطَ التي ...».\nقال الزركشي في النكت ٣/ ٥٧٤: «خرج بقوله: «فوق» ما إذا كان النقط تحت المعجمات فلا يستحب ذلك كالحاء فإنها لو نقطت من تحتها لالتبست بالجيم. ورأيت مَن يُورِد هذا على المصنف، وهو خارج من هذا الموضع من كلامه. وأما الباء فلا تلتبس بالياء؛ لأنها بواحدة»."}],[1077,"فهذهِ وجُوهٌ مِنْ عَلاَماتِ الإهْمَالِ شائعَةٌ معرُوفَةٌ. وهُناكَ مِنَ العلاماتِ ما هوَ موجودٌ في كثيرٍ مِنَ الكُتُبِ القَدِيْمَةِ (٣) ولاَ يَفْطُنُ لهُ كَثِيرُونَ، كَعَلاَمَةِ مَنْ يَجْعَلُ فوقَ الحرفِ المهمَلِ خَطًّا صَغِيْرًا، وكَعَلاَمَةِ مَنْ يَجْعَلُ تحتَ الحرفِ المهملِ مِثْلَ الهمْزَةِ، واللهُ أعلمُ."],[1078,"السَّادِسُ: لاَ يَنْبَغِي أنْ يَصْطَلِحَ مَعَ نَفْسِهِ في كِتَابِهِ بِمَا لاَ يَفْهَمُهُ غيرُهُ فَيُوقِعَ غيرَهُ في حَيْرَةٍ، كَفعلِ مَنْ يَجْمَعُ في كِتَابِهِ بينَ رواياتٍ مختَلِفَةٍ ويَرْمِزُ إلى روايةِ كُلِّ راوٍ بحرفٍ واحِدٍ مِنِ اسْمِهِ أوْ حَرْفَيْنِ وما أشْبَهَ ذَلِكَ، فإنْ بَيَّنَ في أوَّلِ كِتَابِهِ أوْ آخِرِهِ مُرادَهُ بتلْكَ العلاَماتِ والرمُوزِ فَلاَ بأسَ. ومَعَ ذلكَ فالأَوْلَى أنْ يَجْتَنِبَ (٤) الرَّمْزَ ويَكْتُبَ عِنْدَ كُلِّ روايةٍ اسمَ راوِيْها بِكَمالِهِ مُخْتَصَرًا ولاَ يَقْتَصِرُ على العلاَمَةِ ببعضِهِ، واللهُ أعلمُ."],[1079,"السَّابِعُ: يَنْبَغِي أنْ يَجْعَلَ بينَ كُلِّ حديثينِ دارَةً تَفْصِلُ بينَهُما وتُمَيِّزُ (٥). ومِمَّنْ بَلَغَنا عنهُ ذلكَ مِنَ الأئِمَّةِ أبو الزِّنَادِ (٦)، وأحمدُ بنُ حَنْبَلٍ، وإبْرَاهيمُ بنُ إسْحَاقَ الحربيُّ، ومحمَّدُ بنُ جَريرٍ الطَّبَرِيُّ (١) - رضي الله عنهم -، واسْتَحَبَّ الخطيبُ الحافِظُ أنْ تَكُونَ الدَّاراتُ غُفْلًا، فإذا عارَضَ فَكُلُّ حديثٍ يَفْرُغُ مِنْ عَرْضِهِ يَنْقُطُ في الدَّارَةِ التي تليهِ نُقْطَةً أوْ يَخُطُّ في وَسَطِهَا خَطًّا. قالَ: «وقدْ كانَ بعضُ أهْلِ العِلْمِ لاَ يَعْتَدُّ مِنْ سَمَاعِهِ إلاَّ بِمَا كانَ كذلكَ أوْ في مَعْناهُ» (٢)، واللهُ أعلمُ.","",{"fn":"جمع أثفية -بضم الهمزة وكسرها-: وَهِيَ الحجارة الَّتِي تنصب، ويجعل القدر عَلَيْهَا، وياء الجمع مشدّدة، وَقَدْ تخفّف، وتجمع عَلَى أثافٍ أيضًا. انظر: اللسان ٩/ ٣، ونكت الزركشي ٣/ ٥٧٥، والتاج ٢٣/ ٥.\nفي (م): «مضطجعة».\nقال العراقي في التقييد: ٢٠٧: «اقتصر المصنف في هذه العلامة على جعل خط صغير فوق الحرف المهمل، وترك فيه زيادة ذكرها القاضي عياض في الإلماع (١٥٧)، حكى عن بعض أهل المشرق أنه يُعَلِّم فوق الحرف المهمل بخط صغير يشبه النبرة، فحذف المصنف منه ذكر النبرة، والمصنف إنما أخذ ضبط الحروف المهملة بهذه العلامات من الإلماع للقاضي عياض، وإذا كان كذلك فحذفه لقوله: يشبه النبرة يخرج هذه العلامة عن صفتها، فإن النبرة هي الهمزة كما قال الجوهري - الصحاح ٢/ ٨٢٢ - وصاحب المحكم ومقتضى كلام المصنف أنها كالنصبة لا كالهمزة».\nفي (ع) و(م) والشذا والتقييد: «يتجنب».\nالجامع لأخلاق الراوي ١/ ٢٧٢ قبيل (٥٧٠).\nالمحدّث الفاصل: ٦٠٦ (٨٨٢)، والجامع لأخلاق الراوي ١/ ٢٧٢ (٥٧١)."}],[1080,"الثَّامِنُ: يُكْرَهُ لهُ في مِثْلِ عبدِ اللهِ بنِ فُلاَنِ بنِ فُلانٍ، أنْ يَكْتُبَ «عَبْد» في آخِرِ سَطْرٍ، والباقِي في أوَّلِ السَّطْرِ الآخَرِ (٣). وكذلكَ يُكْرَهُ في «عبدِ الرَّحمانِ بنِ فُلاَنٍ» وفي سائِرِ الأسْماءِ المشتَمِلَةِ على التَّعْبيدِ للهِ تَعَالَى، أنْ يَكْتُبَ «عَبد» في آخِرِ سَطْرٍ، واسمَ «اللهِ» مَعَ سائِرِ النَّسَبِ في أوَّلِ السَّطْرِ الآخَرِ (٤). وهَكَذا يُكْرَهُ أنْ يَكْتُبَ «قالَ رَسُولُ» في آخِرِ سَطْرٍ ويَكْتُبَ في أوَّلِ السَّطْرِ (٥) الذي يليهِ «اللهِ صَلَّى اللهُ تعَالَى عليهِ وسَلَّمَ»، وما أشبَهَ ذلكَ (٦)، واللهُ أعلمُ."],[1081,"التَّاسِعُ: يَنْبَغِي لهُ أنْ يُحَافِظَ عَلَى كَتْبِهِ (٧) الصَّلاَةَ والتَّسْلِيمَ عَلَى رَسُولِ اللهِ"],[1082,"- صَلَّى اللهُ تَعَالَى عليهِ وآلِهِ وسَلَّمَ - عندَ ذِكْرِهِ (٨)، ولاَ يَسْأمُ مِنْ تَكْرِيرِ ذلكَ عندَ تَكَرُّرِهِ، فإنَّ ذلكَ مِنْ أكبرِ الفَوَائِدِ التي يَتَعَجَّلُها طَلَبَةُ الحديثِ وكَتَبتُهُ، ومَنْ أغْفَلَ ذلكَ حُرِمَ حَظًّا عَظِيمًا، وقَدْ رُوِّيْنا لأهْلِ ذَلِكَ مَنَاماتٍ صالِحَةً (٩). وما يَكْتُبُهُ مِنْ ذلكَ فَهوَ دُعَاءٌ يُثْبِتُهُ لاَ كَلاَمٌ يَرويهِ، فلذَلِكَ لاَ يَتَقَيَّدُ فيهِ بالروايَةِ ولاَ يَقْتَصِرُ فيهِ على ما في الأصْلِ.","",{"fn":"الجامع لأخلاق الراوي ١/ ٢٧٣.\nالمصدر السابق.\nانظر: الجامع لأخلاق الراوي ١/ ٢٦٨، ونكت الزركشي ٣/ ٥٧٥، والتقييد: ٢٠٨.\nينظر: الجامع لأخلاق الراوي ١/ ٢٦٨.\n«السطر» لم ترد في (ب).\nالجامع لأخلاق الراوي ١/ ٢٦٨.\nفي (ع) والشذا والتقييد: «كتبة»، وانظر: التاج ٤/ ١٠٠.\nانظر: نكت الزركشي ٣/ ٥٧٦ - ٥٧٩، والمحاسن: ٣٠٧.\nانظر بعضها في: الجامع لأخلاق الراوي ١/ ٢٧١ (٥٦٥) و(٥٦٦) و(٥٦٧)، وانظر: التعليق على شرح التبصرة ٢/ ٢١٦."}],[1083,"وهَكَذا الأمْرُ في الثَّنَاءِ عَلَى اللهِ سُبْحَانَهُ (١) عندَ ذِكْرِ اسْمِهِ، نَحْوُ: «عز وجل» و«تبارك وتعالى»، وما ضَاهَى ذلكَ. وإذا وُجِدَ شيءٌ مِنْ ذلكَ قَدْ جَاءَتْ بهِ الروايةُ كانتْ العِنَايَةُ بإثْبَاتِهِ وضَبْطِهِ أكْثَرَ، وما وُجِدَ في خَطِّ أبي عبدِ اللهِ أحمدَ بنِ حَنْبَلٍ (٢) - رضي الله عنه - مِنْ إغْفَالِ ذلكَ عندَ ذِكْرِ اسمِ النَّبِيِّ - صلى الله عليه وآله وسلم -، فَلَعَلَّ سَبَبَهُ أنَّهُ كَانَ يَرَى التَّقَيُّدَ في ذلكَ بالروايةِ، وعَزَّ عليهِ اتِّصَالُها في ذلكَ في جميعِ مَنْ فَوْقَهُ مِنَ الرواةِ."],[1084,"قَالَ الخطيبُ أبو بكْرٍ: «وبَلَغَنِي أنَّهُ كَانَ يُصَلِّي عَلَى النَّبِيِّ - صلى الله عليه وآله وسلم - نُطْقًا لا خَطًّا» (٣). قالَ: «وقَدْ خَالَفَهُ غيرُهُ مِنَ الأئِمَّةِ المتَقَدِّمِينَ في ذلكَ» (٤). ورُوِيَ عَنْ عَلِيِّ بنِ المدينيِّ، وعَبَّاسِ بنِ عبدِ العظِيمِ الْعَنْبَرِيِّ قَالاَ: «ما تَرَكْنا الصَّلاةَ عَلَى رَسُولِ اللهِ (٥) - صلى الله عليه وآله وسلم - في كُلِّ حديثٍ سَمِعْنَاهُ، ورُبَّما عَجِلْنا فَنُبَيِّضُ الكِتَابَ في كُلِّ حديثٍ حَتَّى نَرْجِعَ إليهِ» (٦)، واللهُ أعلمُ."],[1085,"ثُمَّ لِيتَجَنَّبْ (٧) في إثْبَاتِها نَقْصَيْنِ:"],[1086,"أحَدُهما: أنْ يَكْتُبَها مَنْقُوصَةً صُورةً رامِزًا إليها بحرْفَينِ أوْ نحوِ ذلكَ."],[1087,"والثَّانِي: أنْ يَكْتُبَها مَنْقُوصَةً مَعْنًى بأنْ لاَ يَكْتُبَ «وَسَلَّمَ»، وإنْ وُجِدَ ذلكَ في خَطِّ بعضِ المتَقَدِّمينَ (٨). سَمِعْتُ أبا القَاسِمِ مَنْصُورَ بنَ عَبدِ الْمُنْعِمِ (٩)، وأُمَّ المؤيّدِ بنتَ أبي القاسِمِ بقراءَتِي عليهِما قالاَ: سَمِعْنا أبا البَرَكَاتِ عبدَ اللهِ بنَ محمَّدٍ الفُرَاوِيَّ (١) لَفْظًا، قالَ: سَمِعْتُ المقْرِئَ ظَرِيفَ بنَ محمَّدٍ (٢)، يقولُ: سَمِعْتُ عبدَ اللهِ بنَ محمَّدِ بنِ إسحَاقَ الحافِظِ، قَالَ: سَمِعْتُ أَبِي يَقُولُ: سَمِعْتُ حَمْزةَ الكِنَانِيَّ (٣)، يقُولُ: كُنْتُ أكْتُبُ الحديثَ وكُنْتُ أكْتُبُ عندَ ذِكْرِ النبيِّ «صَلَّى اللهُ عليهِ»، ولاَ أكتبُ «وسَلَّمَ»، فَرَأَيْتُ النَّبِيَّ - صلى الله عليه وآله وسلم - في المنامِ فقالَ لي: ما لَكَ لاَ تُتِمُّ الصَّلاةَ عليَّ؟ قَالَ: فما كتبتُ بعدَ ذلكَ «صَلَّى اللهُ عليهِ» إلاَّ كتبْتُ «وسَلَّمَ» (٤).","",{"fn":"قال النووي: «وكذا التَّرَضِّي والتَّرَحُّم على الصحابة والعلماء وسائر الأخيار» انظر: التقريب: ١٢٥.\nقال الزركشي ٣/ ٥٧٩: «ويدل على ذلك أنه كان لا يرى تبديل لفظ النبي بالرسول في الرواية، وإن لم يختلف المعنى».\nقال البلقيني في المحاسن: ٣٠٨: «لا يقال: لعل سببه أن كان يكتب عجلًا لأمرٍ اعتاده، فيترك ذلك للعجلة لا للتقَيّد بالرواية وشبهها؛ لأنا نقول: ترك مثل هذا الثواب بسبب الاستعجال، لا ينبغي أن ينسب للعلماء الجبال».\nالجامع لأخلاق الراوي ١/ ٢٧١.\nفي (أ): «النبي».\nالجامع (٥٦٨).\nفي (أ): «ليجتنب»، وفي (جـ): «يتجنب».\nالمقصود به: الخطيب البغدادي. انظر: شرح التبصرة والتذكرة ٢/ ٢١٦.\nترجمته في السِّيَر ٢١/ ٤٩٤."}],[1088,"قُلْتُ (٥): ويُكْرَهُ أيْضًا الاقْتِصَارُ عَلَى قَوْلِهِ: «عليه السلام»، واللهُ أعلمُ بالصوابِ."],[1089,"العَاشِرُ: على الطَّالِبِ مُقَابَلَةُ (٦) كِتَابِهِ بأصْلِ سَمَاعِهِ (٧) وكِتَابُ شَيْخِهِ الذي يرويهِ عنهُ - وإنْ كانَ إجَازَةً -. رُوِّيْنا عَنْ عُرْوَةَ بنِ الزُّبَيْرِ - رضي الله عنهما - أنَّهُ قالَ لابْنِهِ هِشَامٍ: «كَتَبْتَ؟»، قالَ: «نَعَمْ»، قالَ: «عَرَضْتَ كِتَابَكَ؟» قالَ: «لا»، قالَ: «لَمْ تَكْتُبْ» (١).","",{"fn":"ترجمته في السِّيَر ٢٠/ ٢٢٧.\nترجمته في السِّيَر ١٩/ ٣٧٥.\nهو الحافظ أبو القاسم حمزة بن محمد بن علي بن العباس الكناني المصري، توفي سنة (٣٥٧ هـ). انظر: تاريخ دمشق ١٥/ ٢٣٩، والسِّيَر ١٦/ ١٧٩.\nانظر: تعليقنا على شرح التبصرة ٢/ ٢١٦.\nقبل هذا في جميع النسخ و(ع) والتقييد والشذا جاءت التعليقة الآتية: «وقع في الأصل، في شيخ المقرئ ظريف «عبد الله»، وإنما هو: «عبيد الله» بالتصغير، ومحمد بن إسحاق أبوه، هو أبو عبد الله ابن منده، فقوله: الحافظ إذن مجرور». قلنا: ولا يشك باحث ناقد فطن أن هذه التعليقة ليست من ابن الصلاح، بل هي من أحد النساخ لنسخ ابن الصلاح، ولعله كان من المبكرين، ثم درجت من بعد هذه الزيادة في علوم الحديث لابن الصلاح. وقد أحسنت بنت الشاطئ إذ جعلتها في الحاشية، وأشارت إلى أنها في حاشية نسخة من نسخها المعتمدة، وصاحب هذه الحاشية مخطئ في استدراكه على ابن الصلاح واستدراكه مبني على خطأ، وهو أن المترجمين لابن منده لم يشيروا إلى أن له ولدًا اسمه عبد الله بل ذكروا من أولاده عُبيد الله، ولعل المترجمين قصّروا في ذلك أو اكتفوا بما لابن منده من كنية، وهي أبو عبد الله. وانظر في ترجمة ابن منده: تاريخ الإسلام: ٣٢٠ وفيات سنة (٣٩٥)، والسِّيَر ١٧/ ٢٨، وتذكرة الحفاظ ٣/ ١٠٣١، وطبقات الحفاظ: ٤٠٨، وانظر: السِّيَر أيضًا ١٦/ ١٨٠.\nقال الزركشي ٣/ ٥٨٢: «ويقال: قابل بالكتاب قبالًا ومقابلة، أي: جعله قبالته، وجعل فيه كلمًا في الآخر، ومنه: منازل القوم تتقابل، أي: يقابل بعضها بعضًا، وهو بمعنى المعارضة، يقال: عارضت بالكتاب الكتاب، أي: جعلت ما في آخرها مثل ما في الآخر، مأخوذ من عارضته بالثوب إذا أعطيته وأخذت غيره».\nانظر: نكت الزركشي ٣/ ٥٨٠."}],[1090,"وَرُوِّيْنَا عَنِ الشَّافِعِيِّ (٢) الإمامِ، وعَنْ يَحْيَى بنِ أبي كَثِيْرٍ قالاَ: «مَنْ كَتَبَ ولَمْ يُعَارِضْ كَمَنْ دَخَلَ الخلاَءَ ولَمْ يَسْتَنْجِ». وعَنْ الأخَفَشِ قالَ: «إذا نُسِخَ الكِتَابُ ولَمْ يُعَارَضْ ثُمَّ نُسِخَ وَلَمْ يُعَارَضْ خَرَجَ أعْجَمِيًّا» (٣)."],[1091,"ثُمَّ إنَّ أفْضَلَ المعَارَضَةِ أنْ يُعَارِضَ الطَّالِبُ بنفْسِهِ كِتَابَهُ بِكِتَابِ (٤) الشَّيْخِ مَعَ الشَّيْخِ في حالِ تَحْدِيْثِهِ إيَّاهُ مِنْ كِتَابِهِ، لما يجمعُ ذلكَ مِنْ وجوهِ الاحْتِياطِ والإتْقَانِ مِنَ الجانِبَيْنِ. وما لَمْ تَجْتَمِعْ فيهِ هذهِ الأوْصَافُ نَقَصَ مِنْ مَرْتَبَتِهِ بقدَرِ ما فاتَهُ مِنْهَا. وما ذَكَرْناهُ أَوْلَى مِنْ إطْلاَقِ أبي الفَضْلِ الْجَارُودِيِّ الحافِظِ الْهَرَوِيِّ (٥) قَولَهُ: «أصْدَقُ المعارَضَةِ مَعَ نَفْسِكَ» (٦). ويُسْتَحَبُّ أنْ يَنْظُرَ معهُ في نُسْخَتِهِ مَنْ حَضَرَ مِنَ السَّامِعِيْنَ مِمَّنْ لَيْسَ معهُ نُسْخَةٌ لاَ سِيَّما إذا أرادَ النَّقْلَ مِنْها. وقَدْ رُوِيَ عَنْ يَحْيَى بنِ مَعِيْنٍ أنَّهُ سُئِلَ عَمَّنْ لَمْ ينظرْ (٧) في الكِتَابِ والمحدِّثُ يَقْرَأُ، هَلْ يَجُوزُ أنْ يُحَدِّثَ بذلكَ عنهُ؟، فقالَ: أمَّا عِنْدِي فَلاَ يَجُوزُ، ولَكِنْ عَامَّةُ الشُّيُوخِ هَكَذا سَمَاعُهُمْ» (١).","",{"fn":"أخرجه الرامهرمزي في المحدّث الفاصل: ٥٤٤، والخطيب في الجامع (٥٧٦)، والكفاية: ... (٣٥٠ت، ٢٣٧هـ) والقاضي عياض في الإلماع: ١٦٠، وابن السمعاني في أدب الإملاء: ٧٩. قال البقاعي: «يحتمل -وهو أظهر- أن يكون (لم) حرف جزم فيكون المعنى أن ما كتبه عَدَمٌ؛ لعدم نفعه، ويحتمل أن تكون استفهامية، وهو قريب من الأول». النكت الوفية: ٢٨٧/ب.\nقال العراقي في التقييد: ٢١٠: «إنما هو معروف عن الأوزاعي، وعن يحيى بن أبي كثير»، وبنحوه في نكت الزركشي ٣/ ٥٨٢. وإلى الأوزاعي أسنده ابن عبد البر في الجامع ١/ ٧٧ - ٧٨. وأسنده الرامهرمزي في المحدّث الفاصل: ٥٤٤، وابن عبد البر في الجامع ١/ ٧٧، والخطيب في الكفاية: (٣٥٠ ت، ٢٣٧ هـ)، وفي الجامع (٥٧٧)، وابن السمعاني في أدب الإملاء ٧٨ - ٧٩ إلى يحيى بن أبي كثير.\nأسنده الخطيب في الكفاية: (٣٥١ ت، ٢٣٧ - ٢٣٨ هـ)، وانظر: المحاسن: ٣١٠.\nانظر: المحاسن: ٣١٠.\nهو الحافظ أبو الفضل محمد بن أحمد بن محمد، الجارودي الهروي، توفي سنة (٤١٣ هـ). السير ١٧/ ٣٨٤.\nوهذا يختلف من حال شخص إلى آخر، فمن كان من عادته ألا يسهو عند نظره في الأصل والفرع فهذا يقابل بنفسه، ومن كان من عادته أن يسهو عند نظره فمقابلته مع الغير أولى. الاقتراح: ٢٩٦ - ٢٩٧، نكت الزركشي ٣/ ٥٨٣.\nانظر: نكت الزركشي ٣/ ٥٨٤."}],[1092,"قُلْتُ: وهذا مِنْ مَذاهِبِ أهْلِ التَّشْدِيْدِ في الروايَةِ، وسَيَأْتِي ذِكْرُ مَذْهَبِهِمْ (٢) إنْ شَاءَ اللهُ تَعَالَى. والصَّحِيْحُ أنَّ ذلكَ لاَ يُشْتَرَطُ وأنَّهُ يَصِحُّ السَّمَاعُ وإنْ لَمْ يَنْظُرْ أصلًا في الكِتابِ حالَةَ القِرَاءَ ةِ، وأنَّهُ لا (٣) يُشْتَرَطُ أنْ يُقَابِلَهُ بنفْسِهِ، بلْ يَكْفِيْهِ مُقَابلَةُ نُسْخَتِهِ بأصْلِ الرَّاوي وإنْ لَمْ يَكُنْ ذلكَ حالَةَ القِرَاءةِ، وإنْ كَانَتِ المقابَلَةُ على (٤) يَدَي غيرِهِ، إذا كَانَ ثِقَةً مَوْثُوقًا بضَبْطِهِ (٥)."],[1093,"قُلْتُ: وجَائِزٌ أنْ تَكُونَ مُقَابَلَتُهُ بفَرْعٍ قَدْ قُوبِلَ المقابلَةَ المشروطَةَ بأصْلِ شَيْخِهِ أصْلِ السَّمَاعِ، وكذلكَ إذا قَابَلَ بأصْلِ أصْلِ الشَّيْخِ (٦) المقَابَلْ بهِ أصْلُ الشَّيْخِ؛ لأنَّ الغَرَضَ المطْلُوبَ أنْ يَكُونَ كِتَابُ الطَّالِبِ مُطَابِقًا لأصْلِ سَمَاعِهِ وكِتَابِ شَيْخِهِ، فَسَوَاءٌ حَصَلَ ذلكَ بوَاسِطَةٍ أوْ بغَيْرِ واسِطَةٍ. ولاَ يُجْزِئُ ذلكَ عِنْدَ مَنْ قَالَ: «لاَ تَصِحُّ مُقَابَلَتُهُ مَعَ أحَدٍ غَيْرِ نَفْسِهِ، ولاَ يُقَلِّدُ غَيْرَهُ، ولاَ يَكُونُ بَيْنَهُ وبَيْنَ كِتَابِ الشَّيْخِ واسِطَةٌ (٧)، وليقَابِلْ نُسْخَتَهُ بالأصْلِ بنَفْسِهِ حَرْفًا حَرْفًا حَتَّى يَكُونَ عَلَى ثِقَةٍ ويَقِيْنٍ مِنْ مطابَقَتِها لهُ». وهذا مَذْهَبٌ مَتْرُوكٌ وهوَ مِنْ مَذَاهِبِ أهْلِ التَّشْدِيْدِ المرفُوضَةِ في أعْصَارِنا، واللهُ أعلمُ.","",{"fn":"الكفاية: (٣٥١ ت، ٢٣٨ هـ).\nفي (ب): «مذاهبهم».\nسقطت من (ب).\nكأنه ثَنَّى اليد؛ إشارة إلى الاعتناء بالمقابلة، أفاده البقاعي في نكته: ٢٨٩ / ب.\nقال البقاعي: «أي: قد يكون الإنسان ثقةً، أي: عدلًا ضابطًا لما يرويه، وهو ضعيف في الكتابة أو لا يعلمها أصلًا فلا يدفع ذلك مع كونه موثوقًا بضبطه في المقابلة، أي: قد جرب أمره فيها فوجد شديدًا». النكت الوفية: ٢٨٩ / ب.\nانظر: الاقتراح: ٢٩٧ - ٢٩٨، ونكت الزركشي ٣/ ٥٨٥.\nنقله القاضي عياض في الإلماع: ١٥٩."}],[1094,"أمَّا إذا لَمْ يُعَارِضْ كِتَابَهُ بالأصْلِ أصْلًا فَقَدْ سُئِلَ الأُسْتَاذُ أبو إسْحَاقَ الإسْفِرَايينيُّ عَنْ جَوَازِ رِوَايَتِهِ منهُ (١) فأجَازَ ذلكَ. وأجَازَهُ الحافِظُ أبو بَكْرٍ الخطِيبُ (٢) أيضًا وبَيَّنَ شَرْطَهُ، فَذَكَرَ أنَّهُ يُشْتَرَطُ أنْ تَكُونَ نُسْخَتُهُ نُقِلَتْ مِنَ الأصْلِ وأنْ يُبَيِّنَ عندَ الروايةِ أنَّهُ لَمْ يُعَارِضْ. وحَكَى عَنْ شَيخِهِ أبي بَكرٍ البَرْقَانِيِّ أنَّهُ سَأَلَ أبا بكرٍ الإسْمَاعِيلِيَّ: «هَلْ للرَّجُلِ أنْ يُحَدِّثَ بِمَا كَتَبَ عَنِ الشَّيْخِ ولَمْ يُعَارِضْ بأصْلِهِ؟»، فقالَ: «نَعَمْ، ولَكِنْ لاَ بُدَّ أنْ يُبَيِّنَ أنَّهُ لَمْ يُعَارِضَ» (٣). قالَ: وهذا هوَ مَذْهَبُ أبي بَكْرٍ البَرْقَانِيِّ، فإنَّهُ رَوَى لَنا أحَادِيْثَ كَثِيْرَةً قَالَ فيها: «أخْبَرَنا فُلاَنٌ، ولَمْ أُعَارِضْ بالأصْلِ» (٤)."],[1095,"قُلْتُ: ولاَ بُدَّ مِنْ شَرْطٍ ثَالِثٍ (٥)، وهوَ أنْ يَكُونَ ناقِلُ النُّسْخَةِ مِنَ الأصْلِ غَيْرَ سَقِيْمِ النَّقْلِ، بلْ صَحِيْحَ النَّقْلِ قَلِيْلَ السَّقْطِ، واللهُ أعلمُ."],[1096,"ثُمَّ إنَّهُ يَنْبَغِي أنْ يُرَاعِيَ في كِتَابِ شَيْخِهِ بالنِّسْبَةِ إلى مَنْ فَوْقَهُ مثلَ ما ذَكَرْنا أنَّهُ يُرَاعِيهِ مِنْ كِتَابِهِ، ولاَ يَكُونَنَّ (٦) كَطَائِفَةٍ مِنَ الطَّلَبَةِ إذا رَأَوْا سَماعَ شَيْخٍ لِكِتابٍ قَرَؤُوْهُ عليهِ مِنْ أيِّ نُسْخَةٍ اتَّفَقَتْ، واللهُ أعلمُ."],[1097,"الحادِي عَشَرَ: المخْتَارُ في كَيْفِيَّةِ تَخْرِيجِ السَّاقِطِ في الحواشِي ويُسَمَّى اللَّحَقَ (٧) - بفتحِ الحاءِ - وهوَ أنْ يُخَطَّ مِنْ مَوْضِعِ سُقُوطِهِ مِنَ السَّطْرِ: خَطًّا صَاعِدًا إلى فَوْقُ، ثُمَّ يَعْطِفَهُ بينَ السَّطْرَيْنِ عَطْفَةً يَسِيْرَةً إلى جِهَةِ الحاشِيَةِ التي يَكْتُبُ فيها اللَّحَقَ، ويَبْدَأَ في الحاشِيَةِ بِكَتْبِهِ (١) اللَّحَقَ مُقَابِلًا للخَطِّ المنعَطِفِ، وليَكُنْ ذلكَ في حاشِيَةِ ذَاتِ اليمينِ. وإنْ كَانتْ تَلِي وسَطَ الورقةِ إنِ اتَّسَعَتْ لهُ ولْيَكْتُبْهُ (٢) صَاعِدًا إلى أعْلَى الوَرَقَةِ، لاَ نازِلًا بهِ إلى أسْفَلَ.","",{"fn":"في (أ): «عنه».\nالكفاية: (٣٥٢ ت، ٢٣٩ هـ).\nالكفاية: (٣٥٣ ت، ٢٣٩ هـ).\nالمصدر السابق.\nانظر: نكت الزركشي ٣/ ٥٨٦.\nفي (م): «ولا يكون منه»، وفي الشذا: «ولا يكون».\nقال العراقي في شرح التبصرة والتذكرة ٢/ ٢٢٣: «أهل الحديث والكتَّابة يسمّون ما سقط من أصل الكتاب، فألحق بالحاشية أو بين السطور: اللَّحَق - بفتح اللام والحاء المهملة معًا -. وأمَّا اشتقاقه فيحتمل أنه من الإلحاق، قال الجوهري: اللَّحَق -بالتحريك- شيء يلحق بالأول، قال: واللَّحَق أيضًا من التمر الذي يأتي بعد الأول. وقال صاحب المحكم: اللَّحَق: كل شيء لَحِقَ شيئًا أو أُلحِقَ به من الحيوان والنبات وحمل النخل، ويحتمل أنه من الزيادة يدل عليه كلام صاحب المحكم فإنه قال: اللَّحَق: الشيء الزائد - ثم قال وقد وقع في شعر نسب إلى أحمد بن حنبل -بإسكان الحاء- ثُمَّ قال بعد إيراده: وكأنه خفَّف حركة الحاء؛ لضرورة الشعر». ="}],[1098,"قُلْتُ: وإذا كانَ اللَّحَقُ سطْرَيْنِ أوْ سُطورًا، فلاَ يَبْتَدِئْ بسطورِهِ مِنْ أسْفَلَ إلى أعلى بلْ يَبْتَدِئُ بِها مِنْ أعْلَى إلى أسْفَلَ، بحيثُ يكونُ مُنْتَهاها إلى جِهَةِ باطِنِ الورَقَةِ إذا كانَ التخريجُ في جِهَةِ اليمينِ، وإذا كانَ في جِهَةِ الشِّمالِ وَقَعَ مُنْتَهاها إلى جِهَةِ طَرَفِ الورقَةِ، ثُمَّ يكتُبُ عندَ انتِهَاءِ اللَّحَقِ «صَحَّ». ومِنْهُمْ مَنْ يَكْتُبُ مَعَ «صَحَّ» «رَجَعَ»، ومِنْهُمْ مَنْ يَكْتُبُ في آخِرِ اللَّحَقِ الكلمَةَ المتَّصِلَةَ بهِ دَاخِلَ الكِتابِ في موضِعِ التَّخْرِيجِ لِيُؤْذِنَ (٣) باتِّصَالِ الكَلاَمِ، وهذا اخْتِيارُ بعضِ أهْلِ الصَّنْعَةِ مِنْ أهْلِ المغربِ، واخْتِيارُ القاضِي أبي محمَّدِ بنِ خَلاَّدٍ - صاحِبِ كِتابِ \" الفَاصِلِ بينَ الراوي والواعي \" - مِنْ أهلِ المشْرِقِ مَعَ طَائِفَةٍ، وليسَ ذلِكَ بمَرْضِيٍّ إذْ رُبَّ كَلِمَةٍ تَجِيءُ في الكَلامِ مُكَرَّرَةً حَقيقَةً، فهذا التَّكْرِيْرُ يُوقِعُ بَعْضَ الناسِ في تَوَهُّمِ مِثْلِ ذَلِكَ في بعضِهِ، واخْتَارَ القاضِي ابنُ خَلاَّدٍ أيضًا في كِتابِهِ (٤) أنْ يَمُدَّ عَطْفَةَ خَطِّ التَّخْرِيجِ مِنْ موضِعِهِ حَتَّى يُلْحِقَهُ بأوَّلِ اللَّحَقِ في الحاشِيَةِ (٥). وهذا أيضًا غيرُ مَرْضِيٍّ، فإنَّهُ وإنْ كَانَ فيهِ زيادَةُ بيانٍ، فَهُوَ تَسْخِيمٌ للكِتابِ وتَسْوِيدٌ لهُ لاَ سِيَّما عندَ كَثْرَةِ الإلْحَاقاتِ، واللهُ أعلمُ (٦).","",{"fn":"في (أ) و(ع) و(م) والشذا والتقييد: «بكتبة».\nفي (ع): «فليكتبه»، وما أثبتناه من النسخ و(م).\nفي (جـ): «ليؤذنه».\nالمحدّث الفاصل: ٦٠٦.\nفي (م): «بالحاشية».\nجملة: «والله أعلم» لم ترد في (ب)."}],[1099,"وإنَّما اخْتَرْنا كِتْبَةَ اللَّحَقِ صاعِدًا إلى أعْلَى الورَقَةِ لِئَلاَّ (١) يَخْرُجَ بَعْدَهُ نَقْصٌ آخَرُ فَلا يَجِدُ ما يُقَابِلُهُ مِنَ الحاشِيَةِ فارِغًا لهُ لَوْ كَانَ كَتَبَ الأوَّلَ نازِلًا إلى أسْفَلَ، وإذا كتَبَ الأوَّلَ صَاعِدًا فما يَجِدُ بعدَ ذلكَ مِنْ نَقْصٍ يَجِدُ ما يُقَابِلُهُ مِنَ الحاشِيةِ فارِغًا لهُ. وقُلْنا أيْضًا: يُخَرِّجُهُ في جهَةِ اليمينِ؛ لأنَّهُ لوْ خَرَّجَهُ إلى جِهَةِ الشِّمالِ، فَرُبَّمَا ظَهَرَ بَعْدَهُ في السَّطْرِ نَفْسِهِ نَقْصٌ آخَرُ، فإنْ خَرَّجَهُ قُدَّامَهُ إلى جِهَةِ الشِّمالِ أيْضًا وَقَعَ بينَ التَّخْرِيجَيْنِ إشْكَالٌ، وإنْ خَرَّجَ الثانيَ إلى جِهَةِ اليمينِ التَقَتْ عَطْفَةُ تَخْرِيجِ جِهَةِ الشِّمَالِ وعَطْفَةُ تَخْرِيجِ جِهَةِ اليمينِ أوْ تَقَابَلَتا، فَأَشْبَهَ ذَلِكَ الضَّرْبَ عَلَى مَا بَيْنَهُما، بِخِلاَفِ مَا إذا خرَّجَ الأوَّلَ إلى جِهَةِ اليمينِ فإنَّهُ حِيْنَئذٍ يُخَرِّجُ الثَّانيَ إلى جِهَةِ الشِّمَالِ فَلاَ يَلْتَقِيانِ، ولاَ يَلْزَمُ إشْكَالٌ، اللَّهُمَّ إلاَّ أنْ يَتَأَخَّرَ النَّقْصُ إلى آخِرِ السَّطْرِ، فَلاَ وَجْهَ حِيْنَئذٍ إلاَّ تَخْرِيجُهُ إلى جِهَةِ الشِّمَالِ؛ لِقُرْبِهِ مِنْها ولانْتِفَاءِ العِلَّةِ المذْكُورَةِ مِنْ حَيْثُ إنَّا (٢) لاَ نَخْشَى ظُهُورَ نَقْصٍ بَعْدَهُ."],[1100,"وإذا كَانَ النَّقْصُ في أوَّلِ السَّطْرِ تَأَكَّدَ تَخْرِيجُهُ إلى جِهَةِ اليمينِ لِمَا ذَكَرْناهُ مِنَ القُرْبِ مَعَ مَا سَبَقَ."],[1101,"وأمَّا مَا يُخَرَّجُ في الحواشِي مِنْ شَرْحٍ أوْ تَنْبِيهٍ عَلَى غَلَطٍ أو اخْتِلاَفِ رِوَايةٍ أوْ نُسْخَةٍ أوْ نَحْوِ ذلكَ مِمَّا لَيْسَ في (٣) الأصْلِ، فَقَدْ ذَهَبَ القاضِي الحافِظُ عِياضٌ (٤) -رحمه الله - إلى أنَّهُ لاَ يُخَرَّجُ لِذَلِكَ خَطُّ تَخْريجٍ لِئَلاَّ (٥) يَدْخُلَ اللَّبْسُ ويُحْسَبَ مِنَ الأصْلِ، وأنَّهُ لاَ يُخَرَّجُ إلاَّ لِمَا هُوَ مِنْ نَفْسِ الأصْلِ، لَكِنْ رُبَّمَا جُعِلَ عَلَى الحرفِ المقْصُودِ بذلِكَ التَّخْريجِ عَلاَمةٌ كالضَّبَّةِ أوْ التَّصْحِيْحِ إيْذَانًا بهِ."],[1102,"قُلْتُ: التَّخْريجُ أوْلَى وأدَلُّ، وفي نفسِ هذا الْمُخَرَّجِ مَا يَمْنَعُ الإلْبَاسَ. ثُمَّ هذا التَّخْريجُ يُخَالِفُ التَّخْريجَ لِمَا هُوَ مِنْ نفسِ الأصْلِ في أنَّ خَطَّ ذلكَ التَّخْريجِ يَقَعُ بينَ الكلمتينِ اللَّتَيْنِ بَيْنَهُما سقَطَ السَّاقِطُ، وخطَّ هذا التَّخريجِ يَقَعُ على نَفسِ الكلمةِ التي مِنْ أجْلِها خُرِّجَ الْمُخَرَّجُ في الحاشِيَةِ، واللهُ أعلمُ.","",{"fn":"في (ب): «كي لا».\nكلمة: «إنا» ساقطة من (ب).\nفي (م): «من».\nالإلماع: ١٦٤.\nفي (ب): «كي لا»."}],[1103,"الثَّاني عَشَرَ: مِنْ شَأْنِ الْحُذَّاقِ الْمُتْقِنينَ: العِنَايَةُ بالتَّصحيحِ والتَّضْبِيبِ والتَّمْرِيضِ."],[1104,"أمَّا التَّصحيحُ: فَهوَ كِتابَةُ «صَحَّ» على الكَلاَمِ أوْ عِندَهُ، ولاَ يُفْعَلُ ذلكَ إلاَّ فيما صَحَّ روايةً ومعنًى، غيرَ أنَّهُ عُرْضَةٌ للشَكِّ أوْ الخِلاَفِ، فَيُكْتَبُ عليهِ «صَحَّ»؛ لِيُعْرَفَ أنَّهُ لَمْ يُغْفَلْ عنهُ، وأنَّهُ قَدْ ضُبِطَ وصَحَّ على ذلكَ الوجْهِ."],[1105,"وأمَّا التَّضْبِيبُ ويُسْمَّى أيضًا التَّمْرِيضَ (١): فَيُجْعَلُ على ما صَحَّ وُرُودُهُ كذلكَ مِنْ جِهَةِ النَّقْلِ، غيرَ أنَّهُ فَاسِدٌ لَفْظًا، أوْ مَعْنًى، أوْ ضَعِيفٌ، أوْ ناقِصٌ، مثلُ أنْ يَكُونَ غيرَ جائِزٍ مِنْ حيثُ العربيَّةُ، أوْ يَكُونَ شَاذًّا عِنْدَ أهلِهَا يَأْبَاهُ أكْثَرُهُمْ، أوْ مُصَحَّفًا، أوْ يَنْقُصَ مِنْ جُمْلَةِ الكَلاَمِ كَلِمَةً أوْ أكْثَرَ، وما أشْبَهَ ذَلكَ، فَيُمَدُّ على ما هذا سَبِيْلُهُ خَطٌّ: أوَّلُهُ مِثْلُ الصَّادِ ولاَ يُلْزَقُ بالكَلمَةِ الْمُعَلَّمِ عليها كَيْلاَ يُظَنَّ ضَرْبًا، وكأنَّهُ صَادُ التَّصْحِيحِ بِمَدَّتِها دونَ حائِها كُتِبَتْ كَذلكَ لِيُفَرَّقَ بينَ ما صحَّ مُطلقًا مِنْ جِهَةِ الروايَةِ وغيرِها، وبينَ ما صحَّ مِنْ جِهَةِ الروايَةِ دونَ غيرِها، فَلَمْ يُكَمَّلْ عليهِ التَّصْحيحُ، وكُتِبَ حَرْفٌ ناقِصٌ على حرفٍ ناقِصٍ؛ إشْعَارًا بِنَقْصِهِ ومَرَضِهِ مَعَ صِحَّةِ نَقْلِهِ ورِوايَتِهِ، وتَنْبيهًا بذلكَ لِمَنْ ينظرُ في كِتَابِهِ، على أنَّهُ قدْ وقَفَ عليهِ ونَقَلَهُ على ما هوَ عليهِ، ولَعَلَّ غيرَهُ قَدْ (٢) يُخَرِّجُ لهُ وَجْهًا صحيحًا، أوْ يَظْهَرُ لهُ بعدَ ذلكَ في صِحَّتِهِ ما لَمْ يَظْهَرْ له الآنَ. ولوْ غَيَّرَ ذلكَ وأصْلَحَهُ على ما عندَهُ، لَكَانَ مُتَعَرِّضًا لِمَا وَقَعَ فيهِ غيرُ واحِدٍ مِنَ المتَجَاسِرينَ الذينَ غَيَّرُوا، وظَهَرَ الصَّوابُ فيما أنْكَرُوهُ والفَسَادُ فيما أصْلَحُوهُ!."],[1106,"وأمَّا تَسْمِيَةُ ذلكَ ضَبَّةً (٣)، فَقَدْ بَلَغَنا عَنْ أبي القاسِمِ إبراهيمَ بنِ مُحَمَّدٍ اللُّغَوِيِّ المعْرُوفِ بابنِ الإفْلِيْلِيِّ (٤): أنَّ ذلكَ لِكَونِ الحرفِ مُقْفَلًا بها لاَ يَتَّجِهُ لِقِرَاءةٍ، كَما أنَّ الضَّبَّةَ مُقْفَلٌ بها (١)، واللهُ أعلمُ.","",{"fn":"قال ابن دقيق العيد في الاقتراح: ٣٠٠: «والتمريض حيث تكون اللفظة صحيحة في الرواية دون المعنى، فيكتب عليها صورة صاد صغيرة ممدودة نصف صح؛ إيذانًا بأن الصحة لَمْ تكمل فيه».\nسقطت من (ب).\nالضَّبَّة في الأصل: حديدة عريضة يُضَبَّبُ بها الباب والخشب، وتكون من صفر أو حديد أو نحو ذلك يشعب بها الإناء. انظر: التاج ٣/ ٢٣٣، ومتن اللغة ٣/ ٥٢٦.\nفي (ع) والتقييد: «الإقليلي» بالقاف، والصواب ما أثبت، قال ابن خلكان في وفياته ١/ ٥١: «بكسر الهمزة وسكون الفاء وكسر اللام وسكون الياء المثناة من تحتها وبعدها لام ثانية، هذه النسبة إلى الإفليل، وهي قرية في الشام كان أصله منها. ومثله في حاشية نسخة (ب)، ونكت الزركشي ٣/ ٥٨٧، وضبطها ياقوت في معجم البلدان ١/ ٢٣٢: أَفْلِيْلاء -بفتح الهمزة- وكذا في مراصد الاطلاع ١/ ١٠٢. وقد توفي الإفليلي سنة (٤٤١ هـ). وانظر: وفيات الأعيان ١/ ٥١، وشذرات الذهب ٣/ ٢٦٦."}],[1107,"قُلْتُ: ولأنَّها لَمَّا كانتْ على كَلامٍ فيهِ خَلَلٌ أشْبَهَتِ الضَّبَّةَ التي تُجْعَلُ على كَسْرٍ أوْ خَلَلٍ، فَاسْتُعِيرَ (٢) لَهَا اسْمُها، ومِثْلُ ذلكَ غيرُ مُسْتَنْكَرٍ في بابِ الاسْتِعَاراتِ (٣)."],[1108,"ومِنْ مَوَاضِعِ التَّضْبِيبِ أنْ يَقَعَ في الإسْنادِ إرْسَالٌ أو انْقِطَاعٌ، فَمِنْ عادَتِهِمْ تَضْبِيبُ مَوْضِعِ الإرْسَالِ والانْقِطَاعِ وذلكَ مِنْ قَبِيلِ ما سَبَقَ ذِكْرُهُ مِنَ التَّضْبِيبِ عَلَى الكَلاَمِ النَّاقِصِ. ويُوجَدُ في بعضِ أصُولِ الحديثِ القَدِيْمَةِ في الإسْنَادِ الذي يَجْتَمِعُ فيهِ جَمَاعَةٌ مَعْطُوفَةٌ أسْمَاؤُهُمْ بَعْضُهَا على بعضٍ عَلامةٌ تُشْبِهُ الضَّبَّةَ فيما بينَ أسْمَائِهِمْ، فَيَتَوَهَّمُ مَنْ لاَ خِبْرَةَ لهُ أنَّها ضَبَّةٌ وليسَتْ بضَبَّةٍ، وكأنَّها عَلامةُ وَصْلٍ فيما بينَها (٤)، أُثْبِتَتْ تَأْكِيدًا للعطْفِ، خَوفًا مِنْ أنْ تُجْعَلَ «عَنْ» مَكانَ الواوِ، والعِلْمُ عِندَ اللهِ تَعَالَى. ثُمَّ إنَّ بَعضَهُمْ رُبَّمَا اخْتَصَرَ عَلامةَ التَّصْحِيحِ فَجَاءتْ صُورَتُها تُشْبِهُ صُورَةَ التَّضْبِيبِ، والفِطْنَةُ مِنْ خَيْرِ ما أُوتِيهُ الإنسَانُ، واللهُ أعلمُ."],[1109,"الثَّالِثَ عَشَرَ: إذا وقَعَ في الكِتابِ ما ليسَ مِنهُ فإنَّهُ يُنْفَى عنهُ بالضَّرْبِ أو الحكِّ أو الْمَحْوِ، أوْ غيرِ ذلكَ. والضَّرْبُ خَيرٌ مِنَ الْحَكِّ والْمَحْوِ. رُوِّيْنا عَنِ القَاضِي أبي محمَّدِ بنِ خَلاَّدٍ - رحمه الله - قالَ: قالَ أصْحَابُنا: «الْحَكُّ تُهْمَةٌ» (٥). وأخْبَرَنِي مَنْ أُخْبِرَ عَنِ القَاضِي عِيَاضٍ قالَ: سَمِعْتُ شَيْخَنا أبا بَحْرٍ سُفيانَ بنَ العَاصِ (٦) الأسدِيَّ يَحْكِي عَنْ بَعْضِ شُيُوخِهِ أنَّهُ كَانَ يَقُولُ: «كَانَ الشُّيُوخُ يَكْرَهُونَ حُضُورَ السِّكِّيْنِ مَجْلِسَ السَّمَاعِ، حَتَّى لاَ يُبْشَرَ (١) شَيءٌ؛ لأنَّ مَا يُبْشَرُ مِنهُ رُبَّمَا يَصِحُّ في روايةٍ أُخْرَى. وقَدْ يُسْمَعُ الكِتابُ مَرَّةً أُخْرَى عَلَى شَيْخٍ آخَرَ يَكُونُ مَا بُشرَ وَحُكَّ مِنْ رِوايةِ هَذَا صَحيحًا في روايةِ الآخَرِ فَيَحْتاجُ إلى إلْحَاقِهِ بَعدَ أنْ بُشِرَ (٢)، وهوَ إذا خُطَّ عليهِ مِنْ روايةِ الأوَّلِ، وصَحَّ عِنْدَ الآخرِ، اكْتُفِيَ بِعَلامَةِ الآخَرِ عليهِ بِصِحَّتِهِ» (٣).","",{"fn":"الإلماع: ١٦٩.\nفي (ع): «استعير» من غير فاء، وما أثبتناه من النسخ و(م).\nاعترض الحافظ العراقي على ذلك. فانظر: التقييد: ٢١٤، وشرح التبصرة ٢/ ٢٢٩، والمحاسن: ٣١٦، وتوجيه النظر ٢/ ٧٨٤.\nفي (ب) و(جـ): «بينهما».\nالمحدّث الفاصل: ٦٠٦، وأخرجه الخطيب في الجامع (٥٨٧).\nفي (م) والشذا الفياح وعدد من المصادر: «العاصي»، وما أثبتناه من النسخ الخطية و(ع) والتقييد، ومثله في سير أعلام النبلاء ١٩/ ٥١٥، وفتح المغيث ٢/ ١٧٩، وشذرات الذهب ٤/ ٦١، وغيرها. قال العيني في عمدة القاري ٢/ ٨٩ تعليقًا على اسم «عمرو بن العاصي»، قال: «قوله: «العاصي» الجمهور على كتابته بالياء، وهو الفصيح عند أهل العربية، ويقع في كثير من الكتب بحذفها، وقد قرئ في السبع نحوه كالكبير المتعال والداع». وانظر: النكت الوفية ٢٩٥ / أ."}],[1110,"ثُمَّ إنَّهُم اخْتَلَفُوا في كَيْفيَّةِ الضَّرْبِ، فَرُوِّيْنا عَنْ أبي مُحَمَّدِ بنِ خَلاَّدٍ قَالَ: «أَجْودُ الضَّرْبِ أنْ لاَ يُطْمِسَ المضْرُوبَ عليهِ، بَلْ يَخُطَّ مِنْ فَوقِهِ خَطًّا جَيّدًا بَيِّنًا، يَدُلُّ على إبْطَالِهِ، ويُقْرَأُ مِنْ تَحْتِهِ ما خُطَّ عليهِ» (٤). ورُوِّيْنا عَنِ القاضِي عِيَاضٍ ما مَعْناهُ: أنَّ اخْتِياراتِ الضَّابِطِينَ اخْتَلَفَتْ في الضَّرْبِ، فأكْثَرُهُمْ على مَدِّ الخطِّ على المضروبِ عليهِ مُخْتَلِطًا بالكلماتِ المضروبِ عليها. ويُسَمَّى ذلكَ: «الشَّقَّ» (٥) أيضًا (٦).","",{"fn":"قال البقاعي في نكته الوفية ٢٩٥ / ب: «البَشْر: القَشْر، وهو أخذ وجه البشرة، وهو حقيقة الكشط». انظر: اللسان ٤/ ٦٠.\nبعد هذا في (ع): «وحك»، ولم ترد في شيء من النسخ ولا في (م)، ولا الشذا ولا التقييد.\nالإلماع: ١٧٠ - ١٧١.\nالمحدث الفاصل: ٦٠٦.\nقال العراقي في نكته: ٢١٦: «الشَّقُّ - بفتح الشين المعجمة وتشديد القاف - وهذا الاصطلاح لا يعرفه أهل المشرق، ولم يذكره الخطيب في الجامع ولا في الكفاية، وهو اصطلاح لأهل المغرب، وذكره القاضي عياض في الإلماع، ومنه أخذه المصنف، وكأنه مأخوذ من الشق، وهو الصدع أو من شق العصا، وهو التفريق، فكأنه فرق بين الكلمة الزائدة وبين ما قبلها وبعدها من الصحيح الثابت بالضرب عليها، والله أعلم. ويوجد في بعض نسخ علوم الحديث النشق - بزيادة نون مفتوحة في أوله وسكون الشين - فإن لم يكن تصحيفًا وتغييرًا من النسّاخ فكأنه مأخوذ من نشق الظبي في حبالته إذا علق فيها فكأنه إبطال لحركة الكلمة وإهمالها يجعلها في صورة وثاق يمنعها من التصرف، والله أعلم». وانظر: النكت الوفية ٢٩٥ / ب.\nالإلماع: ١٧١."}],[1111,"ومِنْهُمْ مَنْ لاَ يَخْلِطُهُ ويثْبِتُهُ فَوقَهُ لَكِنَّهُ يَعْطِفُ طَرَفَي الخَطِّ على أوَّلِ المضروبِ عليهِ وآخِرِهِ. ومنْهُمْ مَنْ يَسْتَقْبِحُ هذا ويَرَاهُ تَسْويدًا وتَطْلِيسًا، بَلْ يُحَوِّقُ (١) على أوَّلِ الكَلاَمِ المضروبِ عليهِ بنِصْفِ دائِرَةٍ، وكذلكَ في آخِرِهِ، وإذا كَثُرَ الكَلاَمُ المضروبُ عليهِ فَقَدْ يَفْعَلُ ذلكَ في أوَّلِ كُلِّ سَطْرٍ مِنْهُ وآخِرِهِ، وقَدْ يَكْتَفِي بالتَّحْوِيقِ على أوَّلِ الكَلاَمِ وآخِرِهِ أجْمَعَ. ومِنَ الأشْيَاخِ مَنْ يَسْتَقْبِحُ الضَّرْبَ والتَّحْوِيقَ ويَكْتَفِي بدائِرَةٍ صَغِيرةٍ أوَّلَ الزِّيادةِ وآخِرَهَا ويُسَمِّيْها صِفْرًا كَما يُسَمِّيْها أهْلُ الحِسَابِ. ورُبَّما كَتَبَ بعضُهُمْ عليهِ «لا» في أوَّلِهِ و«إلى» في آخِرِهِ (٢)، ومِثلُ هذا يَحْسُنُ فيما صَحَّ في رِوَايةٍ (٣)، وسَقَطَ في روايةٍ أُخْرَى، واللهُ أعلمُ."],[1112,"وأمَّا الضَّرْبُ على الحرفِ المكَرَّرِ فَقَدْ تَقَدَّمَ بالكَلاَمِ فيهِ القاضِي أبو مُحَمَّدِ بنِ خَلاَّدٍ الرَّامَهُرْمُزِيُّ -رحمه الله- عَلَى تَقدُّمِهِ، فَرُوِّيْنا عَنْهُ قالَ: قالَ بَعضُ أصْحَابِنا: «أُولاهُما بأنْ يُبْطِلَ الثَّانِي؛ لأنَّ الأوَّلَ كُتِبَ عَلَى صَوابٍ والثَّانِي كُتِبَ عَلَى الخطَأِ، والخطَأُ أوْلَى بالإبطَالِ. وقَالَ آخَرُونَ: إنَّما الكِتابُ عَلاَمةٌ لِمَا يُقْرَأُ فَأَوْلَى الحرفَيْنَ بالإبْقَاءِ أدَلُّهُما عليهِ وأجْوَدُهُما صُورَةً» (٤). وجَاءَ القَاضِي عِياضٌ (٥) آخِرًا فَفَصَّلَ تَفْصِلًا حَسَنًا، فرَأَى أنَّ تَكَرُّرَ الحرفِ إنْ كانَ في أوَّلِ سَطْرٍ فلْيُضْرَبْ عَلَى الثَّاني صِيانَةً لأوَّلِ السَّطْرِ عَنِ التَّسْوِيْدِ والتَّشْويهِ وإنْ كانَ في آخِرِ سَطْرٍ فلْيُضْرَبْ عَلَى أوَّلِهِما صِيانَةً لآخِرِ السَّطْرِ، فإنَّ سَلامةَ أوَائِلِ السُّطُورِ وأوَاخِرِها (٦) عَنْ ذلكَ أوْلَى. فإنِ اتَّفَقَ أحَدُهُما في آخِرِ سَطْرٍ والآخَرُ في أوَّلِ سَطْرٍ آخَرَ فلْيُضْرَبْ عَلَى الذي في آخِرِ السَّطْرِ، فإنَّ أوَّلَ السَّطْرِ أوْلَى بالمرَاعاةِ. فإنْ كَانَ التَّكَرُّرُ في المضافِ أو المضافِ إليهِ، أو في الصِّفَةِ، أو في الموصوفِ، أو نحوِ ذلكَ لَمْ نُرَاعِ (١) حِيْنَئذٍ أوَّلَ السَّطْرِ وآخِرَهُ، بَلْ نُراعِي (٢) الاتِّصَالَ بَيْنَ المضَافِ والمضَافِ إليهِ ونَحْوِهِما في الخطِّ فَلاَ نَفْصِلُ بالضَّرْبِ بَيْنَهُما، ونضرِبُ عَلَى الحرفِ المتَطَرِّفِ مِنَ المتَكَرِّرِ دونَ المتوسِّطِ.","",{"fn":"يقال: حَوَّق عليه، أي: حَلَّق وأحاطَ بحلقة أو دائرة. النكت الوفية: ٢٩٨/أ، وانظر: متن اللغة ٢/ ٢٠٢.\nالإلماع: ١٧١، قال البقاعي: «كذا فعل اليونيني في نسخته من البخاري فإنه يكتب عَلَى أول بعض الجمل: «لا»، وعلى آخرها: «إلى»، ويكتب عليها فيها بين ذلك رمز بعض الرواة فيفهم أن هذا الكلام ساقط في رواية صاحب الرمز ثابت في رواية من سواه». النكت الوفية: ٢٩٦ / أ، وانظر: مقدمة صحيح البخاري ١/ ١٠.\nما أثبتناه من جميع النسخ و(م)، وفي (ع): «فيما في صحَّ رواية» خطأ مركب.\nالمحدّث الفاصل: ٦٠٧، ونقله عنه الخطيب في الجامع ١/ ٢٧٦ - ٢٧٧، وانظر: الإلماع: ١٧٢.\nالإلماع: ١٧٢.\nفي (م): «أو آخرها»."}],[1113,"وأمَّا الْمَحْوُ فيقاربُ الكشْطَ في حُكْمِهِ الذي تَقَدَّمَ ذِكْرُهُ، وتَتَنَوَّعُ طُرُقُهُ. ومِنْ أغْرَبِها - مَعَ أنَّهُ أسْلَمُها - ما رُوِيَ عَنْ سحْنُونَ (٣) بنِ سَعِيدٍ التَّنُوخِيِّ الإمامِ المالِكِيِّ أنَّهُ كَانَ رُبَّما كَتَبَ الشَّيءَ ثُمَّ لَعِقَهُ (٤). وإلى هذا يُومِئُ ما رُوِّيْنا عَنْ إبراهِيمَ النَّخَعِيِّ (٥) - رضي الله عنه - أنَّهُ كانَ يَقُولُ: «مِنَ الْمُرُوءةِ أنْ يُرَى في ثوبِ الرجلِ وشَفَتَيْهِ (٦) مِدادٌ»، واللهُ أعلمُ."],[1114,"الرَّابِعَ عَشَرَ: لِيَكُنْ فيما تَختَلِفُ فيهِ الرواياتُ قَائِمًا بِضَبْطِ ما تَخْتَلِفُ فيهِ في كِتابِهِ جَيِّدَ التَّمْييزِ بَيْنها كَيْلاَ تَخْتَلِطَ وتَشْتَبِهَ فَيُفْسِدَ عليهِ أمرُها. وسَبيلُهُ أنْ يجعَلَ أوَّلًا مَتْنَ كِتَابِهِ عَلَى روايةٍ خاصَّةٍ، ثُمَّ ما كانتْ مِنْ زِيادةٍ لروايةٍ أُخْرَى ألْحَقَها، أوْ مِنْ نَقْصٍ أعْلَمَ عليهِ، أوْ مِنْ خِلافٍ كَتَبَهُ إمَّا في الحاشِيةِ وإمَّا (٧) في غَيْرِها، مُعَيِّنًا في كُلِّ ذلِكَ مَنْ رَواهُ، ذاكِرًا اسْمَهُ بِتَمامِهِ، فإنْ رَمَزَ إليهِ بحرْفٍ أوْ أكْثَرَ، فَعَلَيْهِ ما قَدَّمْنا ذِكْرَهُ مِنْ أنَّهُ يُبَيِّنُ المرادَ بذلكَ في أوَّلِ كِتَابِهِ أوْ آخِرِهِ كَيْلاَ يَطُولَ عَهْدُهُ بهِ فَيَنْسَى أوْ يَقَعَ كِتابُهُ إلى غَيْرِهِ فَيَقَعَ مِنْ رُمُوزِهِ في حَيْرَةٍ وَعَمى. وقَدْ يُدْفَعُ إلى الاقْتِصَارِ عَلَى الرُّمُوزِ عندَ كَثْرَةِ الرِّوَاياتِ المخْتَلِفَةِ، واكْتَفَى بعضُهُمْ في التَّمْيِيزِ بأنْ خَصَّ الرِّوَايةَ الملحَقَةَ (١) بالْحُمْرَةِ، فَعَلَ ذلكَ أبو ذَرٍّ (٢) الْهَرَوِيُّ مِنَ المشَارِقَةِ، وأبو الحسَنِ القَابِسِيُّ (٣) مِنَ المغَارِبَةِ، مَعَ كثيرٍ (٤) مِن المشايخِ وأهلِ التقييدِ، فإذا كانَ في الروايةِ الملحقةِ زيادةٌ عَلَى التي في متنِ الكتابِ كَتَبها بالْحُمْرَةِ، وإنْ كانَ فيها نَقْصٌ والزِّيادَةُ في الروايةِ التي في متنِ الكِتابِ حوَّقَ عليها بالْحُمْرَةِ، ثُمَّ عَلَى فاعِلِ ذلكَ تَبْيينُ مَنْ لهُ الروايةُ الْمُعَلَّمَةُ بالْحُمْرَةِ في أوَّلِ الكِتابِ أوْ آخِرِهِ عَلَى ما سَبَقَ، واللهُ أعلمُ.","",{"fn":"في (أ) و(ب): «يراع».\nفي (أ) و(ب): «يراعي».\nبفتح السين المهملة وضمها وسكون الحاء المهملة وضم النون، وبعد الواو نون ثانية. انظر: وفيات الأعيان ٣/ ١٨٢.\nالإلماع: ١٧٣.\nانظر: وفيات الأعيان ٣/ ١٨٢، نسبته إلى النَّخَع -بفتح النون والخاء المعجمة وبعدها عين مهملة - وهي قبيلة كبيرة من مَذْرحج باليمن. انظر: وفيات الأعيان ١/ ٢٥.\nانظر: نكت الزركشي ٣/ ٥٨٩.\nفي (جـ): «أو»."}],[1115,"الخامِسَ عَشَرَ: غَلَبَ عَلَى كَتَبَةِ الحديثِ الاقْتِصَارُ عَلَى الرَّمْزِ في قَوْلِهِمْ: «حَدَّثَنا» و«أخْبَرَنا» غيرَ أنَّهُ شَاعَ ذَلِكَ وظَهَرَ حَتَّى لاَ يَكادُ يَلْتَبِسُ. أمَّا «حَدَّثَنا» فَيُكْتَبُ منها شَطْرُها الأخيرُ، وهوَ الثَّاءُ والنونُ والأَلِفُ. ورُبَّما اقْتُصِرَ عَلَى الضَّميرِ مِنها وهوَ النُّونُ والألفُ (٥). وأمَّا «أخْبَرَنا» فَيُكْتَبُ منها الضَّميرُ المذكُورُ مَعَ الألِفِ أوَّلًا. وليسَ بحسَنٍ ما يَفْعَلُهُ (٦) طائِفَةٌ مِنْ كِتابَةِ «أخْبَرَنا» بألِفٍ مَعَ عَلامةِ «حَدَّثَنا» المذكورةِ أوَّلًا، وإنْ كانَ الحافِظُ البَيْهَقِيُّ مِمَّنْ فَعَلَهُ. وَقَدْ يُكْتَبُ في عَلامةِ «أخْبَرَنا»: رَاءٌ بعدَ الألِفِ، وفي علامةِ «حَدَّثَنا»: دَالٌ في أوَّلِها، ومِمَّنْ رأيْتُ في خَطِّهِ الدالَ في عَلامةِ «حَدَّثَنا»","",{"fn":"في (أ): «المختلفة».\nهو الإمام الحافظ أبو ذر عبد الله بن أحمد بن مُحَمَّد بن عبد الله الأنصاري الهروي المالكي، ت (٤٣٤هـ). تذكرة الحفاظ ٣/ ١١٠٣ (٩٩٧).\nهو الإمام الحافظ الفقيه أبو الحسن علي بن مُحَمَّد بن خلف المعافري، ت (٤٠٣ هـ). تذكرة الحفاظ ٣/ ١٠٧٩ (٩٨٢).\nالإلماع: ١٨٩ - ١٩٠.\nقال البلقيني في المحاسن: ٣٢٠: «فيه إبهام إلا عَلَى طريقة من لا يفرق بينهما»، ومراده في ذلك: أن اختصار «حدثنا» بـ «نا» فِيهِ التباس بـ «أخبرنا»؛ لذلك لا بد من التفرقة بينهما في حالة الاختصار.\nفي (م) والشذا: «تفعله»."}],[1116,"الحافِظُ أبو عبدِ اللهِ الحاكِمُ، وأبو عبدِ الرحمانِ السُّلَمِيُّ (١)، والحافِظُ أحمدُ البَيْهَقِيُّ - رضي الله عنهم -، واللهُ أعلمُ."],[1117,"وإذا كانَ لِلْحَديثِ إسْنَادانِ أوْ أكْثَرُ، فإنَّهُمْ يَكْتُبونَ عندَ الانْتِقَالِ مِنْ إسْنَادٍ"],[1118,"إلى إسْنادٍ، ما صُورَتُهُ (٢) «ح» وهي حاءٌ مفردةٌ مهملةٌ، ولَمْ يأتْنا عَنْ أحَدٍ مِمَّنْ"],[1119,"يُعْتَمَدُ بيانٌ لأمْرِها، غيرَ أنِّي (٣) وَجَدْتُ بِخَطِّ الأسْتَاذِ الحافِظِ أبي عُثْمانَ الصَّابُونِيِّ، والحافِظِ أبي مُسْلِمٍ عُمَرَ بنِ عَلِيٍّ اللَّيْثِيِّ البُخَارِيِّ، والفَقِيْهِ المحدِّثِ أبي سعَدٍ (٤) الخلِيليِّ - رحمهم الله - في مكانِهَا بدلًا عنها «صَحَّ» صَرِيحةً، وهذا يُشْعِرُ بكوْنِها رَمْزًا إلى"],[1120,"«صَحَّ». وحَسُنَ إثْبَاتُ «صَحَّ» هاهنا؛ لِئَلاَّ يُتَوَهَّمَ أنَّ حديثَ هذا الإسْنادِ سَقَطَ، ولِئَلاَّ يُرَكَّبَ الإسْنادُ الثاني عَلَى الإسْنادِ الأوَّلِ فَيُجْعَلا إسْنادًا واحِدًا."],[1121,"وحَكَى لي بعضُ مَنْ جَمَعَتْنِي وإيَّاهُ الرِّحْلَةُ بِخُراسَانِ عَمَّنْ وَصَفَهُ بالفَضْلِ مِنَ الأصْبَهَانِيِّيْنَ أنَّها حَاءٌ مُهملَةٌ مِنَ التَّحويلِ، أي: مِنْ إسْنادٍ إلى إسْنادٍ آخَرَ. وذَاكَرْتُ فيها بعضَ أهلِ العِلْمِ مِنْ أهلِ المغربِ (٥)، وحَكَيْتُ لهُ عَنْ بعضِ مَنْ لَقِيْتُ مِنْ أهلِ الحديثِ أنَّها حاءٌ مهملةٌ، إشَارةً إلى قَوْلِنا «الحديثَ»، فقالَ لي: أهلُ المغربِ (٦) وما عرَفْتُ بَيْنَهُم اخْتِلاَفًا يَجْعلونَها حاءً مهملةً، ويقولُ أحدُهُمْ إذا وصَلَ إليها «الحديثَ». وذَكَرَ لي أنَّهُ سَمِعَ بعضَ البَغْدَادِيِّيْنَ يَذْكُرُ أيضًا أنَّها حاءٌ مهملةٌ، وأنَّ مِنْهُمْ مَنْ يَقُولُ إذا انتَهَى إليها في القراءةِ: «حا» ويَمُرُّ.","",{"fn":"هو أبو عبد الرحمان مُحَمَّد بن الحسين بن مُحَمَّد السلمي الصوفي النيسابوري، توفي سنة (٤٢١ هـ). تاريخ بغداد ٢/ ٢٤٨، وتذكرة الحفاظ ٣/ ١٠٤٦.\nانظر: نكت الزركشي ٣/ ٥٩٥.\nفي (م): «إنَّني».\nفي (ب): «سعيد»، والمثبت من باقي النسخ و(م) والشذا والتقييد، وقد نقل الحافظ العراقي هذا النص في شرح التبصرة والتذكرة ٢/ ٢٤٩، وفيه: «سعيد»، ولعله مُحَمَّد بن أحمد بن مُحَمَّد، أبو سعد الخليلي التوقاني المتوفى (٥٤٨ هـ). مترجم له في طبقات الشافعية الكبرى ٦/ ٨٥.\nفي الشذا: «الغرب».\nفي الشذا: «الغرب»."}],[1122,"وسَالْتُ أنَا الحافِظَ الرَّحَّالَ أبا مُحَمَّدٍ عَبدَ القادِرِ بنَ عبدِ اللهِ الرُّهَاوِيَّ (١)"],[1123,"- رحمه الله - عنها، فَذَكَرَ أنَّهَا حاءٌ مِنْ حَائِلٍ، أي: تَحُولُ بَيْنَ الإسْنادَيْنِ. قالَ: ولا يَلفِظُ بِشَيءٍ عندَ الانتِهَاءِ إليْها في القِرَاءةِ، وأنْكَرَ كَوْنَها مِنَ «الحديثِ» وغيرِ ذلكَ، ولَمْ يَعْرِفْ غَيرَ هذا عَنْ أحَدٍ مِنْ مَشَايِخِهِ، وفِيْهِم عَدَدٌ كانُوا حُفَّاظَ الحدِيثِ في وَقْتِهِ."],[1124,"قالَ المؤَلِّفُ: وأخْتَارُ أنَّا (٢) - واللهُ الموفِّقُ - أنْ يَقُولَ القارِئُ عندَ الانْتِهَاءَ إليها: «حا» ويَمُرُّ، فإنَّهُ أحْوَطُ الوُجُوهِ وأعْدُلُهَا، والعِلْمُ عندَ اللهِ تَعَالَى."],[1125,"السَّادِسَ عَشَرَ: ذَكَرَ الخطيبُ الحافِظُ أنَّهُ يَنْبَغِي للطَّالِبِ أنْ يَكْتُبَ بَعْدَ (٣) البَسْمَلةِ اسْمَ الشَّيْخِ الذي سَمِعَ الكِتَابَ منهُ وكُنْيَتَهُ ونَسَبَهُ، ثُمَّ يَسُوقَ مَا سَمِعَهُ منهُ عَلَى لفظِهِ. قالَ: وإذا كَتَبَ الكِتابَ المسْمُوعَ فيَنْبَغِي أنْ يَكتُبَ فوقَ سَطْرِ التَّسْمِيةِ أسماءَ مَنْ سَمِعَ معهُ وتاريخَ وَقْتِ السَّمَاعِ وإنْ أحَبَّ كَتْبَ ذَلِكَ في حاشِيةِ أوَّلِ وَرَقَةٍ مِنَ الكِتابِ، فَكُلًاّ قَدْ فَعَلَهُ شُيُوخُنا (٤)، واللهُ أعلمُ (٥)."],[1126,"قُلْتُ: كِتْبَةُ التَّسْمِيعِ حيثُ (٦) ذَكَرَهُ أحْوطُ لهُ وأحْرَى بأنْ لاَ يَخْفَى عَلَى مَنْ يَحتاجُ إليهِ، ولاَ بأسَ بكتبتِهِ آخِرَ الكِتابِ وفي ظَهْرِهِ، وحيثُ لاَ يَخْفى موضِعُهُ. ويَنْبَغِي أنْ يَكُونَ التَّسْمِيعُ بخَطِّ شَخْصٍ موثُوقٍ بهِ غيرِ مَجْهولِ الخطِّ، ولاَ ضَيْرَ حِيْنَئذٍ في أنْ لاَ يَكْتُبَ الشَّيْخُ الْمُسْمِعُ خَطَّهُ بالتصحيحِ. وهَكَذا لاَ بأسَ عَلَى صاحِبِ الكِتابِ إذا كانَ مَوثُوقًا بهِ، أنْ يَقْتَصِرَ عَلَى إثْباتِ سَماعِهِ بخَطِّ نفسِهِ، فَطَالَمَا فَعَلَ الثِّقَاتُ ذلكَ.","",{"fn":"ولد بـ «الرُّها» - بضم أوله - في سنة (٥٣٦ هـ)، وتوفي بحرّان سنة (٦١٢ هـ). انظر: سير أعلام النبلاء ٢٢/ ٧١، ومعجم البلدان ٣/ ١٠٦.\nلم ترد في (أ).\nفي (ب): «عند».\nالجامع لأخلاق الراوي وآداب السامع ١/ ٢٦٨، وأدب الإملاء والاستملاء: ١٧١.\nجملة: «والله أعلم» من (ب) و(م).\nفي (ع) والتقييد: «جنب». وانظر: النكت الوفية: ٣٠٠ / ب."}],[1127,"وَقَدْ حَدَّثَنِي بِمَرْوَ الشَّيْخُ أبو الْمُظَفَّرِ بنُ الحافِظِ أبي سَعْدٍ (١) الْمَرْوَزِيُّ (٢) عَنْ"],[1128,"أبيهِ عَمَّنْ حَدَّثَهُ مِنَ الأصبَهانِيَّةِ أنَّ عبدَ الرَّحْمَانِ بنَ أبي عبدِ اللهِ بنِ مَنْدَه قرَأَ ببغْدَادَ"],[1129,"جُزْءًا عَلَى أبي أحمدَ الفَرَضِيِّ (٣) وسَأَلَهُ خَطَّهُ لِيَكُونَ حُجَّةً لهُ. فقالَ لهُ أبو أحمدَ:"],[1130,"«يا بُنَيَّ! عليكَ بالصِّدْقِ، فإنَّكَ إذا عُرِفْتَ بهِ لاَ يُكَذِّبُكَ أحَدٌ، وتُصَدَّقُ فيما تَقُولُ وتَنْقُلُ، وإذا كَانَ غيرَ ذلكَ فلوْ قِيْلَ لَكَ: ما هذا خَطُّ أبي أحمدَ الفَرَضِيِّ، ماذَا تَقُولُ"],[1131,"لَهُمْ؟»."],[1132,"ثُمَّ إنَّ عَلَى كاتِبِ التَّسْمِعِ التَّحَرِّيَ والاحْتِياطَ، وبيانَ السَّامِعِ والمسْمُوعِ منهُ"],[1133,"بلفْظٍ غيرِ مُحْتَملٍ (٤) ومُجَانَبَةَ التَّسَاهُلِ فيمَنْ يُثْبِتُ اسْمَهُ، والحذَرَ مِنْ إسْقاطِ اسْمِ"],[1134,"واحِدٍ (٥) منهُم لغَرَضٍ فاسِدٍ. فإنْ كَانَ مُثْبِتُ السَّماعِ غيرَ حاضِرٍ في جميعِهِ، لكنْ أثْبَتَهُ مُعْتَمِدًا عَلَى إخْبَارِ مَنْ يَثِقُ بخبَرِهِ مِنْ حاضِرِيهِ، فلاَ بأسَ بذَلِكَ إنْ شَاءَ اللهُ تَعَالَى."],[1135,"ثُمَّ إنَّ مَنْ ثَبَتَ سَماعُهُ في كِتابِهِ فَقَبيحٌ بهِ كِتْمانُهُ إيَّاهُ ومَنْعُهُ مِنْ نَقْلِ سَماعِهِ ومِنْ نَسْخِ الكِتابِ. وإذا أعارَهُ إيَّاهُ فلاَ يُبْطِئُ بهِ. رُوِّينا عَنِ الزُّهْرِيِّ أنَّهُ قالَ: «إيَّاكَ وغُلُولَ الكُتُبِ». قيلَ لهُ: «وما غُلُولُ الكُتُبِ؟»، قالَ: «حَسْبُهَا عَلَى (٦) أصْحَابِهَا» (٧).","",{"fn":"في (ب): «سعيد».\nبفتح الميم وسكون الراء وفتح الواو وبعدها زاي معجمة، نسبة إلى مَرْو. انظر: الأنساب ٥/ ١٤٩، ومراصد الاطلاع ٣/ ١٢٦٢.\nيقال للعالم بالفرائض: الفارض والفريض والفَرَضي. تاج العروس ١٨/ ٤٨٢، وترجمته في تاريخ بغداد ١٠/ ٣٨٠، والسير ١٧/ ٢١٢.\nفي (ب): «مجهول».\nفي (م): «أحد».\nفي (ع): «عن»، وما أثبتناه من النسخ و(م).\nأخرجه الخطيب في الجامع لأخلاق الراوي وآداب السامع (٤٨٣)، والسمعاني في أدب الإملاء والاستملاء: ١٧٦."}],[1136,"وَرُوِّيْنا عَنِ الفُضَيْلِ بنِ عِيَاضٍ - رضي الله عنه - أنَّهُ قالَ: «ليسَ مِنْ فَعَالِ (١) أهْلِ الورَعِ ولاَ مِنْ فَعَالِ الْحُكَماءِ، أنْ يأخُذَ سَمَاعَ رَجُلٍ فَيَحْبِسَهُ عنهُ، ومَنْ فَعَلَ ذلكَ فقدْ ظَلمَ نفسَهُ» (٢). وفي روايةٍ: «ولاَ مِنْ فَعَالِ (٣) العُلماءِ أنْ يأخُذَ سَماعَ رَجُلٍ وكتابَهُ فيَحْبِسَهُ عليهِ» (٤). فإنْ مَنعَهُ إيَّاهُ فَقَدْ (٥) رُوِّيْنا أنَّ رَجُلًا ادَّعَى عَلَى رجُلٍ بالكُوفَةِ سَمَاعًا منعَهُ إيَّاهُ فَتَحَاكَما إلى قاضِيها حَفْصِ بنِ غِيَاثٍ، فقالَ لصَاحِبِ الكِتابِ: «أخرِجْ إلينا كُتُبَكَ، فما كَانَ مِنْ سَماعِ هذا الرَّجُلِ بِخَطِّ يَدِكَ ألزَمناكَ، وما كانَ بِخَطِّهِ أعْفيناكَ منهُ» (٦). قالَ ابنُ خَلاَّدٍ: «سَأَلْتُ أبا عبدِ اللهِ الزُّبَيْرِيَّ عَنْ هذا، فقالَ لاَ يجيءُ في هذا البابِ حُكْمٌ أحْسنُ مِنْ هذا؛ لأنَّ خَطَّ صاحِبِ الكِتابِ دالٌّ عَلَى رِضَاهُ باسْتِماعِ صاحِبِهِ معهُ» (٧)، قالَ ابنُ خَلاَّدٍ: وقالَ غيرُهُ: «ليسَ بشَيءٍ» (٨)."],[1137,"ورَوَى الخطيبُ الحافِظِ أبو بَكْرٍ عَنْ إسْماعيلَ بنِ إسْحاقَ القَاضِي (٩) أنَّهُ تُحُوكم إليهِ في ذلكَ فأطْرَقَ مَلِيًّا ثُمَّ قالَ للْمُدَّعَى عليهِ: «إنْ كانَ سَمَاعُهُ في كِتابِكَ بخَطِّكَ فَيَلْزَمُكَ أنْ تُعيرَهُ، وإنْ كانَ سَماعُهُ في كِتابِكَ بِخَطِّ غيرِكَ فأنتَ أعلمُ»."],[1138,"قُلْتُ: حَفْصُ بنُ غِيَاثٍ مَعْدُودٌ في الطَّبَقَةِ الأُوْلَى مِنْ أصْحَابِ أبي حَنِيفَةَ، وأبو عبدِ اللهِ الزُّبَيْرِيُّ مِنْ أئِمَّةِ أصْحابِ الشَّافِعِيِّ، وإسْماعِيلُ بنُ إسْحاقَ لِسَانُ أصْحَابِ مَالِكٍ وإمَامُهُمْ، وقَدْ تَعَاضَدَتْ (١) أقَوَالُهُمْ في ذَلِكَ، ويَرْجِعُ حاصِلُها إلى أنَّ سَماعَ غيرِهِ إذا ثَبَتَ في كِتَابِهِ برِضَاهُ فيلزَمُهُ إعَارَتُهُ إيَّاهُ. وقَدْ كانَ لاَ يَبِيْنُ (٢) لي وَجْهُهُ (٣)، ثُمَّ وَجَّهْتُهُ بأنَّ ذَلِكَ بِمَنْزِلَةِ شَهادةٍ لهُ عِندَهُ، فعليهِ أدَاؤُها بما حَوَتْهُ (٤) وإنْ كانَ فيهِ بَذْلُ مالِهِ، كَما يَلْزمُ مُتَحَمِّلَ الشَّهَادةِ أدَاؤُها، وإنْ كانَ فيهِ بَذْلُ نَفْسِهِ بالسَّعْيِ إلى مَجلِسِ الْحُكْمِ لأدائِهَا، والعِلْمُ عِندَ اللهِ تبارك وتعالى (٥).","",{"fn":"في (أ): «أفعال».\nالجامع لأخلاق الراوي وآداب السامع (٤٨٥). وانظر: النكت الوفية: ٣٠٢ / أ.\nفي (أ): «أفعال».\nالجامع لأخلاق الراوي وآداب السامع (٤٨٦). وانظر: النكت الوفية: ٣٠٢ / أ.\nانظر: نكت الزركشي ٣/ ٥٩٥ - ٥٩٦.\nالجامع لأخلاق الراوي ١/ ٢٤١ (٤٨١).\nالمحدّث الفاصل: ٥٨٩ رقم (٨٣٨).\nالمصدر السابق.\nانظر: نكت الزركشي ٣/ ٥٩٦ - ٥٩٨."}],[1139,"ثُمَّ إذا نَسَخَ الكِتابَ فلاَ يَنْقُلْ سَمَاعَهُ إلى نُسْخَتِهِ إلاَّ بعدَ المقابَلةِ (٦) المرضيَّةِ. وهكذا لاَ يَنْبَغِي لأحَدٍ أنْ يَنْقُلَ سَماعًا إلى شيءٍ مِنَ النُّسَخِ أو يُثْبِتَهُ فيها عِندَ السَّمَاعِ ابْتَداءً إلاَّ بعدَ المقابَلَةِ المرْضِيَّةِ بالمسْمُوعِ كَيْلاَ يَغتَرَّ أحَدٌ بتِلْكَ النُّسْخَةِ غيرِ المقَابَلَةِ إلاَّ أنْ يُبَيِّنَ مَعَ النَّقْلِ وعِنْدَهُ كَونَ النُّسْخَةِ غيرَ مقابَلَةٍ، واللهُ أعلمُ.","",{"fn":"في (م): «تعارضت».\nفي (أ): «لا يتبين».\nقال الزركشي في نكته ٣/ ٥٩٨ - ٥٩٩: «وقد وجّهه غيره بأن مثل ذَلِكَ من المصالح العامة المحتاج إليها مع وجود علاقة بينهما تقتضي إلزامه بإسعافه في مقصده، أصله إعارة الجدار لوضع جذوع الجار بالعارية مع دوام الجذوع في الغالب، فلأن يلزم صاحب الكتاب مع عدم دوام العارية أولى».\nأي: مع ما حوته من بذل مال ونفس. النكت الوفية: ٣٠٢ / أ.\nوللبلقيني توجيه آخر، انظره في: محاسن الاصطلاح: ٣٢٥.\nقال الزركشي ٣/ ٥٩٩: «وإذا قابله علم علاقة ذَلِكَ، وإن كان في السماع يكتب: بلغ في المجلس الأول أو الثاني هكذا»."}],[1140,"النوع السادس والعشرون في صفة رواية الحديث وشرط أدائه، وما يتعلق بذلك"],[1141,"(١)"],[1142,"وَقدْ سَبَقَ بَيَانُ كثيرٍ مِنْهُ في ضِمْنِ النَّوْعَيْنِ قَبْلَهُ."],[1143,"شَدَّدَ قَومٌ في الرِّوايةِ فأفْرَطُوا، وتَسَاهَلَ فيها آخَرُونَ فَفَرَّطُوا، ومِنْ مَذَاهِبِ التَّشْدِيدِ مَذهبُ مَنْ قَالَ: «لاَ حُجَّةَ إلاَّ فيما رَواهُ الراوي مِنْ حِفْظِهِ وتَذَكُّرِهِ»، وذَلِكَ مَرْوِيٌّ عَنْ مالِكٍ (٢)، وأبي حنيفَةَ (٣) - رضي الله عنهما -. وذَهَبَ إليهِ مِنْ أصحابِ الشَّافِعِيِّ أبو بَكْرٍ الصَّيْدَلاَنِيُّ (٤) الْمَرْوَزِيُّ."],[1144,"ومِنها: مَذْهَبُ مَنْ أجازَ الاعتِمَادَ في الروايةِ عَلَى كِتابِهِ، غيرَ أنَّهُ لو أعارَ كِتابَهُ وأخْرَجَهُ مِنْ يَدِهِ لَمْ يَرَ الروايَةَ منهُ لغَيْبَتِهِ عنهُ."],[1145,"وقَدْ سَبَقَتْ حِكَايَتُنا لِمَذَاهِبَ عَنْ أهْلِ التَّسَاهُلِ، وإبْطَالُها في ضِمْنِ ما تَقَدَّمَ مِنْ شَرْحِ وُجُوهِ الأخْذِ والتَّحَمُّلِ."],[1146,"ومِنْ أهْلِ التَّسَاهُلِ قَوْمٌ سَمِعُوا كُتُبًا مُصَنَّفَةً وتَهَاوَنُوا، حَتَّى إذا طَعَنُوا في السِّنِّ واحْتِيْجَ إليهِمْ، حَمَلَهُمُ الجهْلُ والشَّرَهُ عَلَى أنْ رَوَوْهَا مِنْ نُسَخٍ مُشْتَراةٍ أوْ مُسْتَعارةٍ"],[1147,"غيرِ (٥) مُقَابَلَةٍ، فَعَدَّهُمُ الحاكِمُ أبو عبدِ اللهِ الحافِظُ في طَبَقَاتِ الْمَجْرُوحينَ. قَالَ: «وهُمْ يَتَوَهَّمُونَ أنَّهُمْ في روَايَتِها صَادِقُونَ». قالَ (١): «وهذا مِمَّا كَثُرَ في الناسِ وتَعَاطَاهُ قَومٌ مِنْ أكابِرِ العُلَماءِ والمعْرُوفينَ بالصَّلاَحِ» (٢).","",{"fn":"انظر في صفة مَن تقبل روايته ومَنْ تُرَدُّ: إرشاد طلاب الحقائق ١/ ٢٧٣ - ٣٣٣، والتقريب: ٩٠ - ١٠٠، والمنهل الروي: ٦٣، والخلاصة: ٨٨، واختصار علوم الحديث: ٩٢، ومحاسن الاصطلاح: ٢١٨، وشرح التبصرة ٢/ ١، والتقييد والإيضاح: ١٣٦، ونزهة النظر: ١٨٥ - ١٩٩، والمختصر: ١٥٥، وفتح المغيث ١/ ٢٦٢، وألفية السيوطي: ٩٦ - ١١٢، وفتح الباقي ١/ ٢٩٢، وتوضيح الأفكار ٢/ ١١٤، وظفر الأماني: ٧٨.\nالكفاية: (٣٣٧ ت، ٢٢٧ هـ)، والإلماع: ١٣٦.\nالكفاية: (٣٤٢ ت، ٢٣١ هـ).\nفي (أ): «الصديق»، وهو خطأ، والصيدلاني توفي نحو سنة (٤٢٧ هـ). انظر: ترجمته في: طبقات الشافعية لابن هداية الله: ١٥٢.\nفي (م): «غير صحيحة ولا مقابلة»."}],[1148,"قُلْتُ: ومِنَ المتَسَاهِلينَ عبدُ اللهِ بنُ لَهِيْعَةَ (٣) المصريُّ، تُرِكَ الاحْتِجَاجُ بروايَتِهِ مَعَ جَلاَلَتِهِ؛ لِتَسَاهُلِهِ (٤). ذُكِرَ عَنْ يَحْيَى بنِ حَسَّانَ (٥) أنَّهُ رَأَى قَوْمًا مَعَهُمْ جُزْءٌ سَمِعُوهُ مِنِ ابنِ لَهِيْعَةَ، فَنَظَرَ فيهِ فإذا ليسَ فيهِ حديثٌ واحِدٌ مِنْ حديثِ ابنِ لَهِيْعَةَ، فجاءَ إلى ابنِ لَهِيْعَةَ فأخْبَرَهُ بذلكَ، فَقَالَ: «ما أصْنَعُ، يَجِيئونِي بِكتابٍ فَيَقُولونَ هذا مِنْ حدِيْثِكَ؛ فَأُحَدِّثُهُمْ بهِ» (٦)."],[1149,"ومِثْلُ هذا واقِعٌ مِنْ شُيُوخِ زَمَانِنا (٧)، يَجِيءُ إلى أحَدِهِمْ الطَّالِبُ بِجُزْءٍ أوْ كِتابٍ فَيَقُولُ: هذا رُوايَتُكَ (٨)، فَيُمَكِّنُهُ مِنْ قِرَاءتِهِ عليهِ مُقَلِّدًا لهُ مِنْ غيرِ أنْ يَبْحَثَ بحيثُ يَحْصُلُ (٩) لهُ الثِّقَةُ بِصِحَّةِ ذلكَ.","",{"fn":"في (أ) و(م) والشذا: «وقال».\nالمدخل إلى الإكليل: ٥٧، ونقله عنه ابن الأثير الجزري في جامع الأصول ١/ ١٤٣.\nبفتح اللام وكسر الهاء، عَلَى وزن (شريعة). انظر: التقريب (٣٥٦٣)، وتاج العروس ٢٢/ ١٧٧.\nانظر: طبقات ابن سعد ٧/ ٢٠٤، تاريخ البُخَارِيّ الصغير ٢/ ٢٠٧، والجرح والتعديل ٥/ ١٤٥، والكامل لابن عدي ٥/ ٢٣٧، وجامع الأصول ١/ ١٤٤، وتهذيب الكمال ٤/ ٢٥٢، والكاشف ١/ ٥٩٠، ولسان الميزان ٧/ ٢٦٨.\nنقل الزركشي في نكته ٣/ ٦٠٠ عن المزي قوله: «هذه الحكاية فيها نظر؛ لأن ابن لهيعة من الأئمة الحفاظ لا يكاد يخفى عليه مثل هذا، وإنما تكلم فيه من تكلم بسبب من الرواة عنه فمنهم من هو عدل كابن المبارك ونحوه، ومنهم من هو غير عدل».\nالمجروحين ٢/ ١٣.\nقال الزركشي في نكته ٣/ ٦٠١: «إلحاقه شيوخ زماننا بمن سلف فيه نظر؛ لأن المقصود منهم بقاء السلسلة فقط، وأما الإسناد فغير منظور إليه في هذا الزمان».\nفي (ب): «من روايتك».\nفي (م) والشذا: «تحصل»."}],[1150,"والصَّوابُ ما عليهِ الجمهُورُ، وهوَ التَّوَسُّطُ بَيْنَ الإفْرَاطِ والتَّفْرِيطِ، فإذا قامَ (١) الراوي في الأخْذِ والتَّحَمُّلِ بالشرطِ الذي تَقَدَّمَ شَرْحُهُ، وقابَلَ كِتابَهُ وضَبَطَ سَماعَهُ عَلَى الوجهِ الذي سَبَقَ ذِكْرُهُ جازَتْ لهُ الروايةُ منهُ. وإنْ أعارَهُ وغابَ عنهُ إذا كان الغالبُ مِنْ أمرِهِ سَلامَتَهُ مِنَ التَّغْييرِ والتَّبْدِيْلِ (٢)، لاَ سِيَّما إذا كانَ مِمَّنْ لاَ يَخْفَى عليهِ في الغالبِ"],[1151,"- لَوْ غُيِّرَ شيءٌ مِنْهُ وبُدِّلَ - تَغييرُهُ وتَبْديلُهُ؛ وذَلِكَ لأنَّ الاعتِمَادَ في بابِ الروايةِ عَلَى غالبِ الظَّنِّ، فإذا حَصَلَ أجْزَأَ، ولَمْ يُشْتَرَطْ مَزِيْدٌ عليهِ، واللهُ أعلمُ."],[1152,"تفريعات"],[1153,"أحدُهَا: إذا كانَ الراوي ضَرِيرًا ولَمْ يَحْفَظْ حَدِيْثَهُ مِنْ فَمِ مَنْ حَدَّثَهُ، واسْتَعَانَ بالمأْمُونينَ في ضَبْطِ سَمَاعِهِ وحِفْظِ كِتَابِهِ، ثُمَّ عِندَ روايتِهِ في القراءةِ منهُ عليهِ، واحْتَاطَ في ذلكَ عَلَى حَسَبِ حالِهِ بحيثُ يحصُلُ معهُ الظَّنُّ بالسلامةِ مِنَ التَّغييرِ صَحَّتْ روايتُهُ، غيرَ أنَّهُ أَوْلَى بالخِلاَفِ والمنْعِ مِنْ مِثْلِ ذلكَ مِنَ البَصِيْرِ (٣)."],[1154,"قال الخطيبُ الحافِظُ: «والسَّماعُ مِنَ البَصِيرِ الأُمِّيِّ والضَّريرِ اللذينِ لَمْ يَحْفَظا مِنَ المحدِّثِ ما سَمِعَاهُ منهُ لَكِنَّهُ كُتِبَ لَهُما بِمَثَابَةٍ واحدَةٍ، قَدْ (٤) مَنَعَ منهُ غيرُ واحِدٍ مِنَ العُلَماءِ ورَخَّصَ فيهِ بعضُهُمْ» (٥)، واللهُ أعلمُ.","",{"fn":"في (ع): «قاهم».\nما أثبتناه من النسخ و(م)، وفي (ع): «من التبديل والتغيير».\nقال البلقيني في المحاسن: ٣٢٨: «قد يمنع الأولوية من جهة تقصير البصير، فيكون الأعمى أولى بالجواز؛ لأنه أتى باستطاعته».\nفي (ع) والتقييد: «وقد».\nالكفاية: (٣٣٨ ت، ٢٢٨ هـ)، قال الزركشي في نكته ٣/ ٦٠١: «هما وجهان لأصحاب الشَّافِعِيّ حكاهما الرافعي في كتاب الشهادات، وقال: إن الجمهور عَلَى القبول، قال: وهذا الخلاف فيما سمعه بعد العمى، فأمّا ما سمعه قبله فله أن يرويه بلا خلاف، وذكر الخطيب أن علة المانعين هي جواز الادخال عليهما ما ليس من حديثهما، قال: وهي العلة التي ذكرها مالك فيمن له كتب وسماعه صحيح فيها غير أنَّهُ لا يحفظ ما تضمنت»."}],[1155,"الثانِي: إذا سَمِعَ كِتابًا ثُمَّ أرادَ روايَتَهُ مِنْ نُسْخَةٍ ليسَ فيها سَمَاعُهُ (١)، ولاَ هيَ مُقابلةٌ بِنُسْخةِ سَماعِهِ، غيرَ أنَّهُ سُمِعَ منها عَلَى شَيْخِهِ، لَمْ يَجُزْ لهُ ذلكَ. قَطَعَ بهِ الإمامُ أبو نَصْرِ (٢) بنُ الصَّبَّاغِ الفقيهُ (٣) فيما بَلَغَنا عنهُ. وكذلكَ لوْ كانَ فيها سَماعُ شَيْخِهِ أوْ رَوَى منها ثِقَةٌ عَنْ شَيْخِهِ، فَلاَ تَجُوزُ (٤) لهُ الروايةُ منها اعْتِمادًا عَلَى مجرَّدِ ذلكَ، إذا لاَ يُؤْمَنُ أنْ تَكُونَ (٥) فيها زَوَائِدُ ليسَتْ في نسخَةِ سَماعهِ. ثُمَّ وَجَدْتُ الخطيبَ (٦) قَدْ حَكَى مِصْدَاقَ (٧) ذلكَ عَنْ أكْثَرِ أهْلِ الحديثِ، فَذَكَرَ فيما إذا وجَدَ أصْلَ المحدِّثِ ولَمْ يُكْتَبْ فيهِ سَماعُهُ، أوْ وجَدَ نُسْخَةً كُتِبَتْ عَنِ الشَّيْخِ تَسْكُنُ نَفسُهُ إلى صِحَّتِها أنَّ عَامَّةَ أصحابِ الحديثِ مَنَعُوا مِنْ روايتِهِ مِنْ ذَلِكَ. وجاءَ عَنْ أيُّوبَ (٨) السِّخْتيانِيِّ، ومُحَمَّدِ بنِ بكرٍ البُرْسَانِيِّ (٩) التَّرَخُّصُ فيهِ."],[1156,"قُلْتُ: اللَّهُمَّ إلاَّ أنْ تَكُونَ (١٠) لهُ إجازةٌ مِنْ شَيْخِهِ عامَّةٌ لِمَرْوِيَّاتِهِ أوْ نحوُ ذَلِكَ، فَيَجُوزُ لهُ حِيْنَئذٍ الروايةُ منها؛ إذْ ليسَ فيهِ أكْثَرُ مِنْ روايةِ تِلْكَ الزِّيَاداتِ بالإجازةِ بلَفْظِ: أَخْبَرَنَا أو حَدَّثَنا مِنْ غيرِ بَيانٍ للإجازةِ فِيْهَا، والأمْرُ في ذلكَ قريبٌ يَقَعُ مِثْلُهُ في مَحَلِّ التَّسَامُحِ. وقدْ حَكَيْنا فِيْمَا تَقَدَّمَ أنَّهُ لاَ غِنَى (١١) في كُلِّ سَمَاعٍ عَنِ الإجازَةِ؛ لِيَقَعَ ما يَسْقُطُ في السَّماعِ عَلَى وجهِ السَّهْوِ وغيرِهِ مِنْ كَلِماتٍ أوْ أكْثَرَ، مَرْوِيًّا بالإجازةِ وإنْ لَمْ يُذْكَرْ لَفْظُها. فإنْ كانَ الذي في النُّسْخَةِ سَمَاعُ شَيْخِ شَيْخِهِ، أو هِيَ مَسْمُوعَةٌ عَلَى شَيْخِ شَيْخِهِ، أوْ مَرْوِيَّةٌ عَنْ شَيْخِ شَيْخِهِ فَيَنْبَغِي لهُ حِيْنَئذٍ في روايتِهِ منها أنْ تَكُونَ (١) لهُ إجازةٌ شامِلَةٌ مِنْ شَيْخِهِ، ولِشَيْخِهِ إجازَةٌ شَامِلةٌ مِنْ شَيْخِهِ، وهذا تَيْسِيْرٌ (٢) حَسَنٌ هَدَانا اللهُ لهُ -ولهُ الحمدُ- والحاجَةُ إليهِ مَاسَّةٌ في زَمَانِنا جِدًّا، واللهُ أعلمُ.","",{"fn":"انظر: التقييد والإيضاح: ٢٢٢.\nفي (ع): «النصر».\nسقطت من (ع)، وهي من جميع النسخ و(م).\nفي (أ) و(ب) و(جـ) والشذا: «يجوز»، وما أثبتناه من (ع) والتقييد.\nفي النسخ و(م): «يكون».\nالكفاية: (٣٧٦ - ٣٧٧ ت، ٢٥٧ هـ).\nانظر: نكت الزركشي ٣/ ٦٠٢.\nفي (ع): «أيوبي».\nبضم الباء الموحدة، وسكون الراء، بعدها السين المهملة، وفي آخرها النون، هذه النسبة إلى بني برسان، وهم بطن من الأزد. الأنساب ١/ ٣٣٥.\nفي (أ) و(جـ) و(م) والشذا: «يكون»، وما أثبتناه من (ب) و(ع) والتقييد.\nفي (ع) والتقييد: «لا غناء»."}],[1157,"الثَّالِثُ: إذا وجَدَ الحافظُ في كتابهِ خلافَ ما يَحْفَظُهُ (٣) نَظَرَ: فإنْ كانَ إنَّما حَفِظَ ذَلِكَ مِنْ كِتابِهِ فلْيَرْجِعْ إلى ما في كِتابِهِ، وإنْ كانَ حَفِظَهُ مِنْ فَمِ المحدِّثِ فَلْيَعْتَمِدْ حِفْظَهُ دُونَ ما في كِتابهِ إذا لَمْ يَتَشَكَّكْ، وحَسَنٌ أنْ يَذْكُرَ الأمرينِ في روايتِهِ، فَيَقُولَ: حِفْظِي كذا، وفي كِتابِي كذا، هَكَذا فَعَلَ شُعْبَةُ (٤) وغيرُهُ، وهَكَذا إذا خالَفَهُ فيما يَحفظُهُ بعضُ الحفَّاظِ، فَلْيَقُلْ: حِفْظِي كذا وكذا، وقالَ فيهِ فُلاَنٌ أو قالَ فيهِ غيري كذا وكذا، أوْ شِبْهَ هذا مِنَ الكَلامِ. كذَلِكَ فَعَلَ سُفيانُ الثَّوْرِيُّ وغيرُهُ (٥)، واللهُ أعلمُ."],[1158,"الرَّابِعُ: إذا وَجَدَ سَماعَهُ في كِتابِهِ وهوَ غيرُ ذاكرٍ (٦) لسماعِهِ ذلكَ، فَعَنْ أبي حَنِيْفَةَ وبَعضِ أصحابِ الشَّافِعِيِّ (٧): أنَّهُ لاَ يَجُوزُ (٨) لهُ روايتُهُ. ومَذْهَبُ الشَّافِعِيِّ وأكْثَرِ أصْحابِهِ، وأبي يُوسُفَ، ومُحَمَّدٍ أنَّهُ يَجُوزُ لهُ روايتُهُ (٩).","",{"fn":"في (ب) و(جـ): «يكون».\nفي الشذا: «تبيين».\nراجع نكت الزركشي ٣/ ٦٠٢.\nانظر الرواية عن شعبة في الكفاية: (٣٣٣ - ٣٣٤ ت، ٢٢٤ هـ).\nانظر: الكفاية (٣٣٤ ت، ٢٢٥ هـ).\nراجع: نكت الزركشي ٣/ ٦٠٣ - ٦٠٦.\nمذهب أبي حنيفة وبعض أصحاب الشافِعي حكاه القاضي عياض في الإلماع: ١٣٩.\nفي (ع) والتقييد: «لا تجوز»، وما أثبتناه من (أ) و(ب) و(جـ) و(م) والشذا.\nحكاه القاضِي عِيَاض في الإلماع: ١٣٩، ونسبه الْخَطِيْب في الكفاية: (٥٣٩ ت، ٣٨٠ هـ) إلى عامة أصحاب الْحَدِيْث والفقهاء من أصحاب مالك والشّافعي وجمهور المتكلمين."}],[1159,"قُلْتُ: هذا الخِلاَفُ يَنْبَغِي أنْ يُبْنَى عَلَى الخِلاَفِ السَّابِقِ قَرِيبًا في جَوازِ اعْتِمادِ الراوي عَلَى كتابِهِ في ضَبْطِ ما سَمِعَهُ، فإنَّ ضَبْطَ أصْلِ السَّماعِ كَضَبْطِ المسمُوعِ، فَكَما كانَ الصحيحُ وما عليهِ أكثَرُ أهلِ الحديثِ: تَجْوِيْزَ الاعْتِمادِ عَلَى الكتابِ الْمَصُونِ في ضَبْطِ المسمُوعِ حَتَّى يَجوزَ لهُ أنْ يَرويَ ما فيهِ، وإنْ كانَ لا يَذْكُرُ أحاديثَهُ حَدِيثًا حَدِيثًا."],[1160,"كَذَلِكَ لِيَكُنْ هذا إذا وُجِدَ شَرْطُهُ، وهوَ: أنْ يَكونَ السَّماعُ بخَطِّهِ أوْ بِخَطِّ مِنْ يَثِقُ بهِ (١) والكِتابُ مَصُونٌ بِحَيْثُ يَغْلِبُ عَلَى الظَّنِّ سَلامةُ ذَلِكَ مِنْ تَطَرُّقِ التَّزْوِيرِ والتَّغْييرِ إليهِ عَلَى نحوِ ما سَبَقَ ذِكْرُهُ في ذَلِكَ."],[1161,"وهذا إذا لَمْ يَتَشَكَّكَ فيهِ وسَكَنَتْ نفسُهُ إلى صِحَّتِهِ، فإنْ تَشَكَّكَ فيهِ لَمْ يَجُزِ الاعْتِمادُ عليهِ (٢)، واللهُ أعلمُ."],[1162,"الخامِسُ: إذا أرادَ رِوايَةَ ما سَمِعَهُ عَلَى معناهُ دونَ لَفْظِهِ (٣)، فإنْ لَمْ يَكُنْ عالِمًا عارفًا بالألْفَاظِ ومَقَاصِدِها، خَبيرًا بِما يُحِيْلُ مَعَانِيها، بَصِيْرًا بِمَقَاديرِ التَّفَاوِتِ بَيْنَهَا، فلاَ خِلاَفَ (٤) أنَّهُ لاَ يَجُوزُ لهُ ذَلِكَ، وعليهِ أنْ لاَ يَرْوِيَ ما سَمِعَهُ إلاَّ عَلَى اللفظِ الذي سَمِعَهُ مِنْ غيرِ تَغْييرٍ."],[1163,"فأمَّا إذا كَانَ عَالِمًا عَارِفًا بذَلِكَ فَهَذا مِمَّا اخْتَلَفَ فيهِ السَّلَفُ وأصْحابُ الحديثِ وأرْبَابُ الفِقْهِ والأصُولِ، فَجَوَّزَهُ أكْثَرُهُمْ، ولَمْ يُجَوِّزْهُ (٥) بعضُ المحدِّثِينَ، وطَائِفَةٌ مِنَ الفُقَهَاءِ والأصُولِيِّيْنَ مِنَ الشَّافِعِيَّينَ وغَيْرِهِمْ. ومَنَعَهُ بَعضُهُمْ في حديثِ رَسُولِ اللهِ - صلى الله عليه وآله وسلم - وأجَازَهُ في غيرِهِ.","",{"fn":"انظر: نكت الزركشي ٣/ ٦٠٦ - ٦٠٧.\nانظر: نكت الزركشي ٣/ ٦٠٧ - ٦٠٨.\nانظر: نكت الزركشي ٣/ ٦٠٨ - ٦١١.\nوممن نقل مثل هذا الخطيب في الكفاية: (٣٠٠ت، ١٩٨هـ)، والقاضي عياض في الإلماع: ١٧٤.\nعبارة: «أكثرهم، ولم يجوزه» سقطت من (م)."}],[1164,"والأصَحُّ جَوَازُ ذلكَ في الجميعِ إذا كانَ عالِمًا بِمَا وَصَفْناهُ، قَاطِعًا بأنَّهُ أدَّى مَعْنَى اللَّفْظِ الذي بَلَغَهُ؛ لأنَّ ذلكَ هُوَ الذي تَشْهَدُ (١) بهِ أحْوَالُ الصَّحَابَةِ والسَّلَفِ الأوَّلِينَ وكَثيرًا مَا كَانُوا يَنْقُلُونَ مَعْنًى واحِدًا في أمْرٍ واحِدٍ بألْفَاظٍ مُخْتَلِفَةٍ (٢)، وما ذلكَ إلاَّ لأَنَّ مُعَوَّلَهُمْ كَانَ عَلَى المعنى دُونَ اللَّفْظِ."],[1165,"ثُمَّ إنَّ هذا الاخْتِلاَفَ لاَ نَرَاهُ جارِيًا (٣)، ولاَ أجْرَاهُ النَّاسُ - فيما نَعْلَمُ - فِيْما تَضَمَّنَتُهُ بُطُونُ الكُتُبِ، فليسَ لأحدٍ أنْ يُغَيِّرَ لفظَ شيءٍ مِنْ كِتَابِ مُصَنِّفٍ ويُثْبِتَ بَدَلَهُ فيهِ لَفْظًا آخَرَ بِمَعْناهُ، فإنَّ الروايةَ بالْمَعْنَى رَخَّصَ فيها مَنْ رَخَّصَ لِمَا كانَ عليْهِمْ في ضَبْطِ الألْفَاظِ والجمُودِ عليها مِنَ الْحَرَجِ والنَّصَبِ، وذَلِكَ غيرُ مَوْجُودٍ فيما اشْتَمَلَتْ عليهِ بُطُونُ الأوْرَاقِ والكُتُبِ؛ ولأنَّهُ إنْ مَلَكَ تَغْييرَ اللَّفْظِ فليسَ يَمْلكَ تغْييرِ تَصْنِيفِ غيرِهِ، واللهُ أعلمُ."],[1166,"السَّادِسُ: يَنْبَغِي لِمَنْ رَوَى (٤) حَدِيْثًا بالمعْنَى أنْ يُتْبِعَهُ بأنْ يَقُولَ: أوْ كَما قالَ، أوْ نَحْوِ هذا، وما أشْبَهَ ذلكَ مِنَ الألْفَاظِ."],[1167,"رُوِيَ ذَلِكَ مِنَ (٥) الصَّحابةِ عَنِ ابنِ مَسْعُودٍ، وأبي الدَّرْداءِ وأنَسٍ - رضي الله عنهم - (٦). قالَ الخطيبُ: «والصحابَةُ أربابُ اللِّسَانِ وأَعْلَمُ الخلْقِ بِمَعَانِي الكَلامِ، ولَمْ يَكُونُوا يَقُولونَ ذَلِكَ إلاَّ تَخَوُّفًا مِنَ الزَّلَلِ لِمَعْرِفَتِهِمْ بما في الروايةِ عَلَى المعنى مِنَ الخطَرِ» (٧)."],[1168,"قُلْتُ: وإذا اشْتَبَهَ عَلَى القارئِ فيما يَقْرَؤهُ لَفْظَةٌ فَقَرَأَها عَلَى وجهٍ يَشُكُّ فيهِ، ثُمَّ قالَ: أوْ كما قالَ؛ فهذا حَسَنٌ، وهوَ الصَّوابُ في مِثْلِهِ؛ لأنَّ قولَهُ: «أوْ كما قالَ»، يَتَضَمَّنُ إجازَةً مِنَ الراوي وإذْنًا في روايةِ صَوابِهَا عنهُ إذا بانَ. ثُمَّ لاَ يُشْتَرَطُ إفْرَادُ ذَلِكَ بلَفظِ الإجازةِ لِمَا بَيَّنَّاهُ قريبًا، واللهُ أعلمُ.","",{"fn":"في (أ) و(ب): «يشهد».\nانظر: شرح التبصرة والتذكرة ٢/ ٢٦٤ - ٢٦٦.\nانظر: نكت الزركشي ٣/ ٦١١ - ٦١٢.\nفي (ع) والتقييد: «يروي».\nفي (أ): «عن».\nالروايات عنهم خرجناها في التقريب للنووي.\nالجامع لأخلاق الراوي وآداب السامع ٢/ ٣٤، قال البلقيني في المحاسن ٣٣٣: «ليس في النقل عن هؤلاء، أنهم جَوَّزوا نقل الحديث بالمعنى كما فهمه بعض من لا يصح فهمه»."}],[1169,"السَّابِعُ: هَلْ يَجُوزُ اخْتِصَارُ الحديثِ الواحدِ (١) وروايةُ بعضِهِ دُونَ بعضٍ؟"],[1170,"اخْتَلَفَ أهلُ العِلْمِ فيهِ:"],[1171,"- فَمِنْهُمْ: مَنْ مَنَعَ مِنْ (٢) ذَلِكَ مُطْلَقًا بِنَاءً عَلَى القَوْلِ بالمنْعِ مِنَ النَّقْلِ بالمعنى مُطْلَقًا، ومِنْهُم مَنْ مَنَعَ ذَلِكَ مَعَ تَجْوِيزِهِ النَّقْلَ بالمعنى إذا لَمْ يكُنْ قدْ رواهُ عَلَى التَّمامِ مَرَّةً أُخْرَى ولَمْ يَعْلَمْ أنَّ غيرَهُ قدْ رواهُ عَلَى التَّمامِ."],[1172,"- وَمِنْهُمْ مَنْ جَوَّزَ ذَلِكَ وأطْلَقَ ولَمْ يُفَصِّلْ. وقَدْ رُوِّيْنا عَنْ مُجَاهِدٍ أنَّهُ قالَ: انْقُصْ مِنَ الحديثِ ما شِئْتَ ولاَ تَزِدْ فيهِ (٣)."],[1173,"والصحيحُ التَّفْصِيلُ، وأنَّهُ يجوزُ ذَلِكَ مِنَ العَالِمِ العَارِفِ، إذا كانَ ما تركَهُ مُتَميِّزًا عَمَّا نَقَلَهُ، غيرَ مُتَعَلِّقٍ بهِ بحيثُ لاَ يَخْتَلُّ البَيَانُ ولاَ تَخْتَلِفُ الدلاَلَةُ فيما نَقَلَهُ بتَرْكِ ما تَرَكَهُ (٤)، فهذا يَنْبَغِي أنْ يُجَوَّزَ وإنْ لَمْ يَجُزِ النَّقْلُ بالمعنى؛ لأنَّ الَّذِي نَقَلَهُ والذي تَرَكَهُ - والحالَةُ هذهِ - بِمَنْزِلَةِ خَبَرَيْنِ مُنْفَصِلَينِ في أمْرَيْنِ لاَ تَعَلُّقَ لأحَدِهِما بالآخَرِ (٥)."],[1174,"ثُمَّ هذا إذا كانَ رفيعَ المنْزِلَةِ بحيثُ لاَ يَتطرَّقُ إليهِ في ذلكَ تُهْمَةُ نَقْلِهِ أوَّلًا تَمامًا (٦) ثُمَّ نَقْلِهِ ناقِصًا، أوْ نَقْلِهِ أوَّلًا نَاقِصًا ثُمَّ نَقْلِهِ تامًّا. فأمَّا إذا لَمْ يَكُنْ كذلكَ، فَقَدْ ذَكَرَ الخطيبُ الحافِظُ أنَّ مَنْ رَوى حديثًا عَلَى التمامِ، وخافَ إنْ رواهُ مَرَّةً أُخْرَى عَلَى النُّقْصانِ أنْ يُتَّهَمَ بأنَّهُ زادَ في أوَّلِ مرَّةٍ مَا لَمْ يَكُنْ سَمِعَهُ، أو أنَّهُ نَسِيَ في الثاني باقِيَ الحديثِ لِقِلَّةِ ضَبْطِهِ وكَثْرَةِ غَلَطِهِ، فَوَاجِبٌ عليهِ أنْ يَنْفِيَ هذهِ الظِّنَّةَ عَنْ نَفْسِهِ (٧).","",{"fn":"راجع: نكت الزركشي ٣/ ٦١٢.\nسقطت من (م).\nأسنده الخطيب في الكفاية: (٢٨٩ ت، ١٨٩ هـ).\nانظر: محاسن الاصطلاح: ٣٣٤.\nانظر: المصدر السابق.\nفي (م): «تامًّا».\nالكفاية: (٢٩٣ ت، ١٩٣ هـ)."}],[1175,"وذَكَرَ الإمامُ أبو الفتْحِ سُلَيْمُ (١) بنُ أيُّوبَ الرَّازِيُّ الفقيهُ: «أنَّ مَنْ رَوَى بعضَ الخبرِ، ثُمَّ أرادَ أنْ يَنْقُلَ تَمَامَهُ وكَانَ مِمَّنْ يُتَّهَمُ بأنَّهُ زادَ في حديثِهِ، كانَ ذلكَ عُذْرًا لهُ في تَرْكِ الزيادةِ وكِتْمانِها» (٢)."],[1176,"قُلْتُ: مَنْ كَانَ هذا حالَهُ فليسَ لهُ مِنَ الابْتِدَاءِ أنْ يَرْوِيَ الحديثَ غيرَ تامٍّ، إذا كانَ قَدْ تَعَيَّنَ عليهِ أداءُ تَمَامِهِ؛ لأنَّهُ إذا رواهُ أوَّلًا نَاقِصًا أخْرَجَ باقِيَهُ عَنْ (٣) حَيِّزِ الاحْتِجاجِ بهِ، ودارَ بَيْنَ ألاَّ يَرْوِيَهُ (٤) أصْلًا فَيُضَيِّعَهُ رَأْسًا، وبَيْنَ أنْ يَرْويَهُ مُتَّهَمًا فيهِ، فَيُضَيِّعَ ثَمَرَتَهُ؛ لِسُقُوطِ الْحُجَّةِ فيهِ، والعِلْمُ عندَ اللهِ تَعَالَى."],[1177,"وأمَّا تَقْطِيعُ الْمُصَنِّفِ مَتْنَ الحديثِ الواحِدِ (٥) وتَفْرِيْقُهُ في الأبْوابِ، فَهُوَ إلى الجوازِ أقْرَبُ، ومِنَ المنْعِ أبْعَدُ. وقَدْ فَعَلَهُ مالِكٌ، والبخَارِيُّ وغيرُ واحِدٍ مِنْ أئِمَّةِ الحديثِ ولاَ يَخْلُو مِنْ كَرَاهِيَةٍ (٦)، واللهُ أعلمُ."],[1178,"الثَّامِنْ: يَنْبَغِي لِلْمُحَدِّثِ ألاَّ يَرْوِيَ حَدِيْثَهُ بِقِرَاءةِ لَحَّانٍ (٧) أوْ مُصَحِّفٍ. رُوِّيْنا عَنِ النَّضْرِ بنِ شُمَيْلٍ أنَّهُ قالَ: «جَاءتْ هذهِ الأحاديثُ عَنِ الأصْلِ مُعربةً». وأخْبَرَنا أبو بكرِ ابنُ أبي المعالِي الفَرَاويُّ قِراءةً عليهِ، قالَ: أخْبَرَنا الإمامُ أًبُو (١) جَدِّي أبو عبدِ اللهِ مُحَمَّدُ ابنُ الفَضْلِ الفَرَاوِيُّ، قالَ أخْبَرَنا أبو الحسَيْنِ (٢) عبدُ الغَافِرِ بنُ مُحَمَّدٍ الفارسِيُّ، قالَ: أخْبَرَنا الإمامُ أبو سُلَيمانَ حَمْدُ (٣) بنُ مُحَمَّدٍ الخَطَّابِيُّ (٤)، قالَ حَدَّثَني مُحَمَّدُ بنُ مُعاذٍ، قالَ: أخْبَرَنا بعضُ أصحابِنَا، عَنْ أبي دَاوُدَ السِّنْجِيِّ (٥). قالَ: سَمِعْتُ الأصْمَعِيَّ يَقُولُ: «إنَّ أَخْوَفَ ما أَخَافُ (٦) عَلَى طالبِ العِلْمِ إذا لَمْ يَعْرِفِ النَّحْوَ أنْ يَدْخُلَ في جُمْلَةِ (٧) قولِ النبيِّ - صلى الله عليه وآله وسلم -: «مَنْ كَذَبَ عليَّ فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ» (٨)؛ لأنَّهُ - صلى الله عليه وآله وسلم - لَمْ يَكُنْ يَلْحَنُ، فَمَهْمَا رَوَيْتَ عنهُ وَلَحَنْتَ فيهِ، كَذَبْتَ عليهِ (٩).","",{"fn":"بالتصغير، انظر ترجمته في: وفيات الأعيان ٢/ ٣٩٧، وطبقات الشافعية لابن هداية: ١٤٧.\nالبحر المحيط ٤/ ٣٦٢.\nفي (ب) و(م): «من».\nفي (ع) بعد هذا: «إذًا»، ولم ترد في شيء من النسخ ولا في الشذا ولا التقييد.\nانظر: نكت الزركشي ٣/ ٦١٧ - ٦٢٠.\nخالفه النووي في التقريب: ١٣٥ فقال: «وما أظنه يوافق عليه»، وقد عقد الخطيب في الكفاية: (٢٩٤ - ٢٩٥ ت، ١٩٣ - ١٩٤ هـ) بابًا سمّاه: «ما جاء في تقطيع المتن الواحد وتفريقه في الأبواب». نقل فيه آثارًا عن الأئمة في جواز ذلك.\nقال الزركشي في نكته ٣/ ٦٢٠: «وتعبيره باللّحّان بصيغ: «فَعَّال» يقتضي تصويره بالكثير، وهو كذلك؛ إذ لَمْ يسلم من اللحن أحد». وقال ابن فارس: «اللَّحْنُ - بسكون الحاء - إمالة الكلام عن جهته الصحيحة في العربية، يقال: لَحَنَ لَحْنًا ...». مقاييس اللغة ٥/ ٢٣٩. وفي الصحاح ٦/ ٢١٩٣: «اللَّحْنُ: الخطأ في الإعراب، يقال: فلان لَحَّانٌ ولَحَّانَةٌ، أي: كثير الخطأ»."}],[1179,"قلتُ: فحقٌّ عَلَى طالبِ الحديثِ أنْ يَتعلَّمَ منَ النحوِ واللُّغةِ ما يتخلَّصُ بهِ منْ شَيْنِ اللَّحْنِ والتحريفِ ومَعَرَّتِهما.","",{"fn":"«أبو»، ساقطة من (أ) و(ع). وانظر: السير ٤/ ٤٩٤.\nفي (ع) و(م): «الحسن» خطأ، وانظر: ترجمته في: سير أعلام النبلاء ١٨/ ١٩.\nبفتح الحاء وسكون الميم عَلَى صورة المصدر، وفي نسخة (ب): «أحمد»، قال ابن خلكان: «وقد سمع في اسم أبي سليمان حَمْدٍ المذكور أحمد أيضًا - بإثبات الهمزة - والصحيح الأول ...». وفيات الأعيان ٢/ ٢١٥، وانظر: سير أعلام النبلاء ١٧/ ٢٦، والرسالة المستطرفة: ٤٤.\nبفتح الخاء المعجمة وتشديد الطاء المهملة. انظر: الأنساب ٢/ ٥٣٥.\nهذه النسبة إلى سنج - بكسر السين المهملة وسكون النون، وفي آخرها جيم، وهي قرية كبيرة من قرى مرو. الأنساب ٣/ ٣٤٢.\nقال الصنعاني: «وإنما قال الأصمعي: «أخاف»، ولم يجزم؛ لأن من لَمْ يعلم بالعربية وإن لحن لَمْ يكن متعمدًا الكذب». توضيح الأفكار ٢/ ٣٩٤.\nجاء في حاشية (ب) عبارة نصها: «قال المصنف: «قوله: في جملة، أي: في عموم». وكذا في حاشية (م) عن نسخة (غ).\nحديث صحيح متواتر، خَرَّجناه بتوسع في التعليق عَلَى شرح التبصرة ١/ ١٧٥.\nأخرجه ابن حبان في روضة العقلاء (٢٢٣)، والخطابي في غريب الحديث ١/ ٦٣، والقاضي عياض في الإلماع: ١٨٣ - ١٨٤."}],[1180,"رُوِّيْنا (١) عنْ شُعبةَ قالَ: «مَنْ طلبَ الحديثَ وَلَمْ يُبْصِرِ العربيَّةَ فَمَثَلُهُ مَثَلُ (٢) رَجلٍ عليهِ بُرْنُسٌ (٣) ليسَ لهُ رأسٌ»، أو كما قالَ."],[1181,"وعنْ حمَّادِ بنِ سَلَمَةَ، قالَ: «مَثَلُ (٤) الذي يطلُبُ الحديثَ ولاَ يَعْرِفُ النَّحْوَ، مَثَلُ الحمارِ عليهِ مِخْلاَةٌ (٥) لاَ شعيرَ فيها» (٦)."],[1182,"وأمَّا التصحيفُ فسبيلُ السلامةِ منهُ، الأخْذُ مِنْ أفواهِ أهلِ العِلْمِ والضَّبْطِ (٧)، فإنَّ مَنْ حُرِمَ ذَلِكَ وكانَ أخْذُهُ وتعلُّمُهُ مِنْ بُطُونِ الكُتُبِ كانَ مِنْ شَأْنِهِ التَّحريفُ، ولَمْ يُفْلِتْ مِنَ التَّبديلِ والتَّصحيفِ، واللهُ أعلمُ."],[1183,"التاسِعُ: إذا وقعَ في روايتِهِ لَحْنٌ أو تحريفٌ، فقدِ اخْتلفُوا؛ فمنهم مَنْ كانَ يَرَى أنَّهُ يرويهِ عَلَى الخطأ كما سَمِعَهُ، وذهبَ إلى ذَلِكَ مِنَ التَّابعينَ مُحَمَّدُ بنُ سيرينَ، وأبو مَعْمَرٍ عبدُ اللهِ بنُ سَخْبَرَةَ (٨). وهذا غُلُوٌّ في مذهبِ اتِّباعِ اللَّفْظِ والمنعِ مِنَ الروايةِ بالمعنى. ومنهمْ مَنْ رَأَى تَغييرَهُ وإصلاحَهُ وروايتَهُ عَلَى الصوابِ، رُوِّيْنا ذَلِكَ عَنِ الأوزاعيِّ (٩)، وابنِ المباركِ (١٠) وغيرِهِما (١١)، وهوَ مذهبُ الْمُحَصِّلِينَ (١٢) والعلماءِ منَ المحدِّثينَ، والقولُ بهِ في اللَّحْنِ الذي لا يختلِفُ بهِ المعنى وأمثالِهِ، لاَزمٌ عَلَى مذهبِ تجويزِ روايةِ الحديثِ بالمعنى (١). وقدْ سَبَقَ أنَّهُ قولُ الأكثرينَ (٢).","",{"fn":"رواه عنه الخطيب في الجامع ٢/ ٣٦ رقم (١٠٧٣).\nفي (ب): «كمثل».\nالبُرْنُس: كل ثوب رأسه منه ملتزق به. اللسان ٦/ ٢٦\nسقطت من (أ).\nالمخلاة: ما يجعل فيه الحشيش ونحوه. الصحاح ٦/ ٢٣٣٢.\nأخرجه الخطيب في الجامع ٢/ ٣٦ رقم (١٠٧٤).\nفي (م) والتقييد: «أو الضبط».\nبفتح المهملة وسكون المعجمة وفتح الموحدة. التقريب (٣٣٤١)، والخلاصة: ١٩٩، وانظر: الروايات عنهم في الكفاية: (٢٨٥ ت، ١٨٦ هـ).\nانظر: الكفاية (٢٩٦ ت، ١٩٥ هـ)، والجامع ٢/ ٢٣.\nانظر: الكفاية (٢٩٧ ت، ١٩٦ هـ)\nوإليه ذهب الأعمش، والشعبي، وحماد بن سلمة، ويحيى بن معين، وأحمد بن صالح، والحسن بن مُحَمَّد الزعفراني، وعلي بن المديني، وغيرهم. انظر: الكفاية (٢٩٥ - ٣٠٠ ت، ١٩٤ - ١٩٧ هـ).\nفي (ب): «المخلصين»."}],[1184,"وأمَّا إصْلاحُ ذَلِكَ وتغييرُهُ (٣) في كتابِهِ وأصْلِهِ، فالصوابُ تَرْكُهُ، وتقريرُ ما وقَعَ في الأصْلِ عَلَى ما هوَ عليهِ معَ التَّضْبيبِ عليهِ، وبيانِ الصوابِ خارجًا في الحاشيةِ، فإنَّ ذَلِكَ أجمعُ للمصلحةِ وأنْفَى للمَفْسَدةِ."],[1185,"وقدْ رُوِّيْنا أنَّ بعضَ أصحابِ الحديثِ رُئِيَ في المنامِ، وكأنَّهُ قدْ مَرَّ منْ شَفَتِهِ أو لسانِهِ شيءٌ، فقيلَ لهُ في ذَلِكَ، فقالَ: «لفظةٌ مِنْ حديثِ رسولِ اللهِ -صَلَّى اللهُ تَعَالَى عليهِ وعلى آلهِ وسَلَّمَ - غَيَّرْتُها برأْيِي فَفُعِلَ بي هذا» (٤)."],[1186,"وكثيرًا ما نَرَى ما يتوهَّمُهُ كثيرٌ منْ أهلِ العِلْمِ خطأ - ورُبَّما غيَّرُوهُ - صَوَابًا ذا وجهٍ صحيحٍ، وإنْ خَفِيَ واسْتُغْرِبَ لاَ سِيَّما فيما يَعُدُّونَهُ خطأً مِنْ جِهَةِ العربيَّةِ؛ وذلكَ لِكَثْرَةِ لُغَاتِ العربِ وتَشَعُّبِها."],[1187,"ورُوِّيْنا عنْ عبدِ اللهِ بنِ أحمدَ بنِ حنبلٍ، قالَ: «كانَ إذا مَرَّ بأبي لَحْنٌ فاحشٌ غَيَّرَهُ، وإذا كانَ لَحْنًا سَهْلًا تَرَكَهُ، وقالَ: كذا قالَ الشَّيْخُ!» (٥)."],[1188,"وأخْبَرَنِي بعضُ أشْياخِنا عَمَّنْ أخْبَرَهُ عَنِ القاضِي الحافِظِ عياضٍ بِمَا مَعْناهُ"],[1189,"واخْتِصَارُهُ (٦): أنَّ الذي اسْتَمَرَّ عليهِ (٧) عَمَلُ أكْثَرِ الأشْيَاخِ، أنْ يَنْقُلُوا الروايَةَ كما وَصَلَتْ إليهِمْ، ولاَ يُغَيِّرُوها في كُتُبِهِمْ، حَتَّى في أحرفٍ مِنَ القُرْآنِ استَمَرَّتِ (٨) الرواية فيها في الكُتُبِ عَلَى خِلافِ التلاوةِ الْمُجْمِعِ عليها ومنْ غيرِ أنْ يجيءَ ذَلِكَ في الشَّواذِّ.","",{"fn":"راجع: محاسن الاصطلاح: ٣٣٨.\nالمصدر السابق.\nراجع: نكت الزركشي ٣/ ٦٢٣.\nانظر: المقنع ١/ ٣٧٩.\nأخرجه الخطيب بسنده إلى الإمام أحمد. الكفاية: (٢٨٦ - ٢٨٧ ت، ١٨٧ هـ).\nفي (ب): «واختاره».\nفي (م): «عليه استمر».\nفي (جـ): «واستمرت»، وفي الشذا: «واشتهرت»."}],[1190,"ومنْ ذَلِكَ ما وَقَعَ في \" الصحيحينِ \" و\" الموطّأِ \" وغيرِهَا، لكِنَّ أهلَ المعرفةِ مِنهُمْ يُنَبِّهُونَ عَلَى خَطَئِها عِندَ السَّماعِ (١) والقِرَاءةِ، وفي حواشي الكُتُبِ، مَعَ تَقْرِيرِهِمْ ما في الأُصُولِ عَلَى ما بَلَغَهُمْ."],[1191,"ومِنْهُمْ مَنْ جَسَرَ عَلَى تغييرِ الكُتُبِ وإصْلاَحِها، مِنْهُمْ: أبو الوليدِ هِشامُ بنُ أحمدَ الكِنانِيُّ الوَقَّشِيُّ (٢)؛ فإنَّهُ لِكَثرةِ مُطالَعَتِهِ وافْتِنانِهِ وثُقُوبِ فَهْمِهِ وحِدَّةِ ذِهْنِهِ جَسَرَ عَلَى الإصلاحِ كثيرًا، وغَلِطَ في أشْيَاءَ مِنْ ذَلِكَ. وكذلكَ غيرُهُ مِمَّنْ سَلَكَ مَسْلَكَهُ."],[1192,"والأَوْلَى سَدُّ بابِ التَّغْييرِ والإصْلاحِ؛ لِئَلاَّ يَجْسُرَ عَلَى ذَلِكَ مَنْ لاَ يُحْسِنُ، وهوَ أسْلمُ (٣) مَعَ التَّبيينِ فيذكُرُ ذَلِكَ عندَ السماعِ كما وقعَ، ثُمَّ يذكُرُ وجهَ صوابِهِ: إمَّا مِنْ جِهَةِ العربيَّةِ، وإمَّا مِنْ جِهَةِ الروايةِ، وإنْ شَاءَ قَرَأَهُ أوَّلًا عَلَى الصَّوابِ ثُمَّ قالَ: «وَقَعَ عندَ شَيْخِنا، أو في روايتِنا، أو مِنْ طريقِ فُلانٍ كذا وكذا». وهذا أَوْلَى مِنَ الأوَّلِ كَيْلاَ يُتَقَوَّلَ عَلَى رسولِ اللهِ - صلى الله عليه وآله وسلم - ما لَمْ يَقُلْ."],[1193,"وأصْلَحُ ما يُعْتَمَدُ عليهِ في (٤) الإصْلاحِ أنْ يَكُونَ ما يُصْلَحُ بهِ الفَاسِدُ قَدْ"],[1194,"وَرَدَ في (٥) أحاديثَ أُخَرَ، فإنَّ ذاكِرَهُ آمِنٌ مِنْ أنْ يَكُونَ مُتَقَوِّلًا عَلَى رسولِ اللهِ - صلى الله عليه وآله وسلم - ما لَمْ يَقُلْ (٦)، واللهُ أعلمُ."],[1195,"العاشِرُ: إذا كانَ الإصْلاحُ بزِيادَةِ شيءٍ قَدْ سَقَطَ فإنْ لَمْ يَكُنْ في ذَلِكَ مُغَايرةٌ في المعنى فالأمْرُ فيهِ عَلَى ما سَبَقَ، وذلكَ كَنحوِ ما رُوِيَ عَنْ مالكٍ - رضي الله عنه - أنهُ قيلَ لهُ: «أرأيْتَ حديثَ النبيِّ - صلى الله عليه وآله وسلم - يُزَادُ فيهِ الواوُ والألِفُ، والمعنى واحدٌ؟»، فقالَ: «أرجو أنْ يَكُونَ خَفِيْفًا» (٧).","",{"fn":"في (ع) والتقييد: «عِنْدَ الرواية والسماع و...».\nنسبة إلى وَقَّشَ - بالفتح وتشديد القاف - مدينة بالأندلس. انظر: السير ١٩/ ١٣٥، ومراصد الاطلاع ٣/ ١٤٤٢.\nفي (م): «والطريق الأول أسلم».\nفي (م): «من».\nفي (م): «من».\nالإلماع: ١٨٥ - ١٨٧.\nأخرجه ابن عبد البر في جامع بيان العلم وفضله ١/ ٨٠ - ٨١ بإسْناده إلى الإمام مالك، والخطيب في الكفاية: (٣٦٨ت، ٢٥٠هـ)، وفي كفاية الخطيب: (٢٨٨ - ٢٨٩ت، ١٨٨ - ١٨٩هـ) روايات أُخْرَى عن مالك، ليس فيها موضع الشاهد، والسائل هو - أشهب - كما في جامع بيان العلم، والكفاية."}],[1196,"وإنْ كانَ الإصْلاحُ بالزِّيادَةِ يَشْتَمِلُ عَلَى معنًى مُغايرٍ لِمَا (١) وقَعَ في الأصْلِ تأكَّدَ فيهِ الحكْمُ بأنَّهُ يَذكُرُ ما في الأصْلِ مَقْرونًا بالتنبيهِ عَلَى ما سَقَطَ ليسْلَمَ مِنْ مَعَرَّةِ (٢) الخطأِ، ومِنْ أنْ يَقولَ عَلَى شيخِهِ ما لَمْ يَقُلْ."],[1197,"حَدَّثَ أبو نُعَيمٍ الفَضْلُ بنُ دُكَيْنٍ عَنْ شَيْخٍ لهُ بحديثٍ قالَ فيهِ: «عَنْ بُحَيْنَةَ»، فقالَ أبو نُعَيمٍ: إنَّما هُوَ «ابنُ بُحَيْنَةَ»، ولكنَّهُ قالَ: «بُحَيْنَةَ» (٣)."],[1198,"وإذا كانَ مَنْ دُونَ موضِعِ الكلامِ الساقِطِ معلومًا أنَّهُ قدْ أُتِيَ بهِ وإنَّما أسْقطَهُ مَنْ بعدَهُ ففيهِ وَجْهٌ آخَرُ، وهوَ أنْ يُلحَقَ الساقِطُ في موضِعِهِ مِنَ الكِتابِ مَعَ كَلِمَةِ «يعني» كما فَعَلَ الخطيبُ الحَافِظُ (٤)؛ إذْ رَوَى عَنْ أبي عُمَرَ (٥) بنِ مَهدِيٍّ، عَنِ القاضِي الْمَحَامِلِيِّ بإسْنادِهِ، عَنْ عُرْوَةَ، عَنْ عَمْرةَ بنتِ عبدِ الرَّحمانِ - يَعْنِي (٦) - عنْ عائشةَ أنَّها قالتْ: «كانَ رسولُ اللهِ - صلى الله عليه وآله وسلم - يُدْنِي إليَّ رأْسَهُ فأُرَجِّلُهُ» (٧)."],[1199,"قالَ الخطيبُ (٨): «كانَ في أصْلِ ابنِ مَهديٍّ: «عَنْ عَمْرَةَ أنَّها قالتْ: كانَ رسُولُ اللهِ - صلى الله عليه وآله وسلم - يُدْنِي إليَّ رأسَهُ»، فأَلْحَقْنا فيهِ ذِكْرَ عائِشةَ إذْ لَمْ يَكُنْ منهُ بُدٌّ، وعَلِمْنا أنَّ الْمَحَامِلِيَّ كذلكَ رواهُ، وإنَّمَا سَقَطَ مِنْ كتابِ شيخِنا أبي عُمَرَ (٩)، وقُلْنا فيهِ: «يعني (١٠):","",{"fn":"في (ب): «كما».\nفي (ب): «معرفة»، ومن معاني المعرّة، الجناية والمسبَّة، والإثم، والأمر القبيح والمكروه. انظر: تاج العروس ١٣/ ٥ - ٢٠.\nأخرجه الخطيب في الكفاية: (٣٦٩ ت، ٢٥١ هـ).\nالكفاية: (٣٧١ - ٣٧٢ ت، ٢٥٢ - ٢٥٣ هـ).\nفي (أ): «عَمْرو».\nفي (أ) والتقييد: «تعني»، والضمير فيه لأبي عمر بن مهدي.\nأخرجه مالك في الموطأ (٨٦٦) عن ابن شهاب، عن عروة بن الزبير، عن عمرة عن عائشة، به. ومن طريق ما لك أخرجه أحمد ٦/ ١٠٤ و١٨١ و٢٨٢، ومسلم ١/ ١٦٧، وأبو داود (٢٤٦٧)، والبيهقي ٤/ ٣١٥، وابن عبد البر في التمهيد ٨/ ٣١٧.\nالكفاية: (٣٧١ ت، ٢٥٣ هـ).\nفي (ب): «عمرو».\nفي (ب) والتقييد: «تعني»."}],[1200,"عَنْ عائشةَ - رضي الله عنها -»؛ لأجْلِ أنَّ ابنَ مَهْدِيٍّ لَمْ يَقُلْ لنا ذَلِكَ، وهكذا رأيْتُ غيرَ واحدٍ مِنْ شُيُوخِنا يَفْعَلُ في مِثْلِ هذا. ثُمَّ ذَكَرَ بإسْنادِهِ عَنْ أحمدَ بنِ حَنْبَلٍ - رضي الله عنه - قالَ: «سَمِعْتُ وَكِيعًا يقُولُ: أنا أسْتَعِينُ في الحديثِ بـ «يَعْني» (١)."],[1201,"قلتُ: وهذا إذا كانَ شَيخُهُ قَدْ رواهُ لهُ عَلَى الخطأِ. فأمَّا إذا وجَدَ ذَلِكَ في كتابِهِ وغَلَبَ عَلَى ظَنِّهِ أنَّ ذَلِكَ مِنَ الكِتابِ لاَ مِنْ شَيخِهِ فَيَتَّجِهُ هاهنا إصلاحُ ذَلِكَ في كِتابِهِ وفي روايتِهِ عندَ تَحْديثِهِ بهِ معهُ ذَكَرَ أبو دَاوُدَ (٢) أنَّهُ قالَ لأحمدَ بنِ حنبلٍ: «وجدْتُ في كِتابي: حَجَّاجٌ، عَنْ جُرَيْجٍ، عَنْ أبي الزُّبيرِ، يَجوزُ لي أنْ أُصْلِحَهُ: ابنُ جُرَيْجٍ؟ فقالَ: أرجو أنْ يَكونَ هذا لاَ بأْسَ بهِ، واللهُ أعلمُ» (٣)."],[1202,"وهذا مِنْ قبيلِ ما إذا دَرَسَ (٤) مِنْ كِتابِهِ بعضُ الإسْنادِ أو المتنِ فإنَّهُ يجوزُ لهُ اسْتِدْراكُهُ مِنْ كِتابِ غيرِهِ إذا عَرَفَ صِحَّتَهُ وسكَنَتْ نفسُهُ إلى أنَّ ذَلِكَ هوَ الساقِطُ مِنْ كِتابِهِ، وإنْ كانَ في المحدِّثينَ مِنْ لاَ يستجيزُ ذَلِكَ. ومِمَّنْ فَعَلَ ذَلِكَ نُعَيْمُ بنُ حمَّادٍ فيما رُوِيَ عَنْ يحيى بنِ مَعينٍ عنهُ (٥). قالَ الخطيبُ الحافِظُ: «ولوْ بَيَّنَ ذَلِكَ في حالِ الروايةِ كانَ أَوْلَى» (٦)."],[1203,"وهكذا الحكمُ في اسْتِثْباتِ (٧) الحافِظِ ما شَكَّ مِنْ كِتابِ غيرِهِ أو مِنْ حِفْظِهِ، وذَلِكَ مَرْوِيٌّ عَنْ غيرِ واحدٍ من أهلِ الحديثِ، منهُمْ: عاصِمٌ (٨)، وأبو عَوانَةَ (٩)، وأحمدُ بنُ حنبلٍ (١). وكانَ بعضُهُمْ (٢) يُبَيِّنُ ما ثَبَّتَهُ فيهِ غيرُهُ، فيقولُ: «حدَّثنا فُلاَنٌ وثَبَّتَنِي فُلانٌ» كما رُوِيَ عَنْ يَزيدَ بنِ هارونَ (٣) أنَّهُ قالَ: «أخبرنا عاصِمٌ وثَبَّتَنِي شُعْبَةُ عَنْ عبدِ اللهِ بنِ سَرْجِسَ» (٤).","",{"fn":"الكفاية: (٣٧١ - ٣٧٢ ت، ٢٥٣ هـ).\nالكفاية: (٣٦٩ - ٣٧٠ ت، ٢٥١ هـ).\nجملة: «والله أعلم» سقطت من (ع)، هي من جميع النسخ و(م).\nدرس هنا بمعنى: بلي وانمحى. انظر: اللسان ٦/ ٧٩، والمعجم الوسيط ١/ ٢٧٩.\nروايته في الكفاية: (٣٧٣ ت، ٢٥٤ هـ).\nالكفاية: (٣٧٣ ت، ٢٥٤ هـ).\nفعله أبو داود في سننه عقب حديث الحكم بن حزن الكلفي (١٠٩٦)، فقال: «ثَبَّتَنِي في شيء منه بعض أصحابنا»، قال الزركشي في نكته ٣/ ٦٢٤: «هذا مما تفترق فيه الرواية والشهادة».\nالكفاية: (٣٢٤ ت، ٢١٦ هـ).\nالمصدر السابق."}],[1204,"وهكذا الأمرُ فيما إذا وَجَدَ في أصْلِ كِتابِهِ كَلِمَةً مِنْ غريبِ العربيَّةِ (٥) أوْ غيرِها غيرَ مُقَيَّدَةٍ وأشْكَلَتْ عليهِ، فجائِزٌ أنْ يَسْأَلَ عنها أهلَ العِلْمِ بها ويَرْويها عَلَى ما يُخْبِرُونَهُ بهِ. رُوِيَ مثلُ ذَلِكَ عنْ إسحاقَ بنِ راهَوَيْهِ (٦)، وأحمدَ بنِ حَنْبَلٍ (٧) وغيرِهِما (٨) - رضي الله عنهم -،"],[1205,"واللهُ أعلمُ."],[1206,"الحادي عَشَرَ: إذا كانَ الحديثُ عندَ (٩) الراوي عنِ اثْنَينِ (١٠) أو أكثَرَ، وبَيْنَ روايَتِهما تَفاوتٌ في اللفظِ، والمعنى واحدٌ، كانَ لهُ أنْ يَجْمَعَ بينَهُما في الإسْنادِ، ثُمَّ يَسُوقَ الحديثَ عَلَى لَفْظِ أحدِهِما خاصَّةً، ويقُولَ: أخبرنا فُلانٌ وفلاَنٌ، واللَّفْظُ لفُلاَنٍ، أو وهذا لَفْظُ فُلاَنٍ قالَ أو قالا: أخبرنا فُلانٌ، أو ما أشبهَ ذَلِكَ مِنَ العِباراتِ.","",{"fn":"الكفاية: (٣٢٥ ت، ٢١٧ هـ).\nقال الخطيب في الكفاية: (٣٢٥ ت، ٢١٧ هـ): «وكان بعض السلف يبين ما ثبّته فيه غيره، فيقول: حدّثني فلان، وثبَّتني فلان».\nالكفاية: (٣٢٦ ت، ٢١٨ هـ).\nبفتح المهملة وسكون الراء وكسر الجيم بعدها مهملة. التقريب (٣٣٤٥)، والخلاصة: ١٩٩.\nفي (أ): «غريب الحديث والعربية».\nانظر: الكفاية (٣٧٤ - ٣٧٥ ت، ٢٥٥ هـ).\nانظر: ما أورده الخطيب عنه بسنده في الكفاية: (٣٧٥ ت، ٢٥٦ هـ).\nمِنْهُم: الأوزاعي، وابن المبارك، وعفان بن مُسْلِم وسفيان بن عيينة، انظر: الكفاية: (٣٤٧ - ٣٧٦ ت، ٢٥٥ - ٢٥٦ هـ).\nفي (م): «عن».\nانظر: نكت الزركشي ٣/ ٦٢٤ - ٦٢٥."}],[1207,"ولِمُسْلِمٍ (١) صاحبِ \"الصحيحِ\" معَ هذا في ذَلِكَ عبارةٌ أُخْرَى حَسَنةٌ، مثلُ قولِهِ: «حَدَّثَنا أبو بَكْرِ بنُ أبي شَيْبَةَ، وأبو سَعيدٍ الأشَجِّ؛ كِلاهُما عَنْ أبي خالدٍ، قالَ أبو بكرٍ: حَدَّثَنا أبو خالِدٍ الأحْمَرُ، عَنِ الأعمشِ وساقَ الحديثَ». فإعادتُهُ ثانيًا ذِكْرَ أحدِهِما خاصَّةً إشْعارٌ (٢) بأنَّ اللَّفْظَ المذكورَ لهُ."],[1208,"وأمَّا إذا لَمْ يَخُصَّ لَفْظَ أحدِهِما بالذِّكْرِ، بلْ أخَذَ مِنْ لَفْظِ هذا ومِنْ لَفْظِ ذاكَ (٣)، وقالَ: «أخبرنا فُلاَنٌ وفُلاَنٌ -وتَقَارَبا في اللفْظِ- قالا: أخبرنا فُلانٌ»، فهذا غيرُ مُمْتَنِعٍ عَلَى مذهبِ تَجويزِ الروايةِ بالمعنى."],[1209,"وقولُ أبي داودَ صاحِبِ \" السُّنَنِ \": «حَدَّثَنا مُسَدَّدٌ، وأبو تَوْبَةَ - المعنى -"],[1210,"قالا (٤): حَدَّثَنا أبو الأحْوصِ» (٥) معَ أشْباهٍ (٦) لهذا في كِتابِهِ، يَحْتَمِلُ أنْ يَكُونَ مِنْ قَبيلِ الأوَّلِ، فيكونَ اللفْظُ لِمُسَدَّدٍ ويُوافِقُهُ أبو تَوبَةَ في المعنى، ويَحْتَمِلُ أنْ يَكُونَ مِنْ قَبيلِ الثاني، فلا يكونُ قدْ أورَدَ لَفْظَ أحَدِهِما خاصَّةً، بلْ رواهُ بالمعنى عَنْ كِلَيْهِما، وهذا الاحْتِمالُ يَقْرُبُ (٧) في قولِهِ: «حَدَّثَنا مسلمُ بنُ إبراهِيمَ، ومُوسَى بنُ إسْماعِيلَ - المعنى واحدٌ - قالا: حَدَّثَنا أبانُ».","",{"fn":"صحيح مسلم ٢/ ١٣٣ ط إستانبول، و١/ ٤٦٥ (٦٧٣)، ط مُحَمَّد فؤاد عبد الباقي.\nفي (ب): «إشعارًا».\nفي (ب) و(جـ): «ذَلِكَ».\nفي (ع): «قال».\nسنن أبي داود (٣٧٥).\nانظر: لهذه الأشباه عَلَى سبيل المثال (٦٠٣) و(١٠٩٤).\nعقّب عليه الزركشي ٣/ ٦٢٦ بقوله: «هذا الاحتمال الثاني، عجيب إذ يلزم منه ألا يكون رواه بلفظ لواحد من شيخيه، وهو بعيد، ولذلك قال: «أنا فلان وفلان»، وتقاربا في اللفظ، فليس هو منحصرًا في أن روايته عن كل منهما بالمعنى وأن المأتي به لفظ ثالث غير لفظيهما، والأحوال كلها آيلة في الغالب إلى أنَّهُ لا بدَّ أن يسوق الحديث عَلَى لفظ روي له برواية واحد، والباقي بمعناه»."}],[1211,"وأمَّا إذا جَمَعَ بَيْنَ جماعةِ رواةٍ قدِ اتَّفَقُوا (١) في المعْنَى، وليسَ ما أوْرَدَهُ لَفْظَ كُلِّ واحدٍ منهم، وسَكَتَ عَنِ البيانِ لذلكَ، فهذا مِمَّا عِيْبَ بهِ البخاريُّ أوْ غيرُهُ (٢)، ولاَ بأسَ بهِ عَلَى مُقْتَضَى مذهبِ تَجْويزِ الروايةِ بالمعنى."],[1212,"وإذا سَمِعَ كِتابًا مُصَنَّفًا (٣) مِنْ جماعَةٍ، ثُمَّ قابَلَ نُسْخَتَهُ بأصْلِ بَعْضِهِمْ دُونَ بعضٍ، وأرادَ أنْ يَذْكُرَ جَمِيعَهُمْ في الإسنادِ ويقولَ: «واللفظُ لِفُلانٍ» كما سَبَقَ، فهذا يَحْتَمِلُ أنْ يجوزَ كالأوَّلِ؛ لأنَّ ما أوْرَدَهُ قدْ سَمِعَهُ بنَصِّهِ مِمَّنْ ذَكَرَ أنَّهُ بلَفْظِهِ، ويَحْتَمِلُ أنْ لا يجوزَ؛ لأنَّهُ لاَ عِلْمَ عندَهُ بكَيْفِيَّةِ روايةِ الآخرينَ حَتَّى يُخْبِرَ عنها، بخلافِ ما سَبَقَ فإنَّهُ اطَّلَعَ عَلَى روايةِ غيرِ مَنْ نَسَبَ اللَّفْظِ إليهِ، وعَلَى مُوافَقَتِها (٤) مِنْ حيثُ المعنى فأَخْبَرَ بذلكَ (٥)، واللهُ أعلمُ."],[1213,"الثاني عَشَرَ: ليسَ لهُ أنْ يَزيدَ في نَسَبَ مَنْ فوقَ شيخِهِ مِنْ رِجَالِ الإسْنادِ عَلَى ما ذكَرَهُ شيخُهُ مُدْرَجًا (٦) عليهِ مِنْ (٧) غيرِ فَصْلٍ مُمَيَّزٍ، فإنْ أتَى بِفَصْلٍ (٨) جَازَ، مثلُ أنْ يَقُولَ: «هُوَ ابنُ فُلانٍ الفُلانِيُّ» أو «يَعْنِي: ابنَ فُلاَنٍ»، ونحوَ ذلكَ. وذَكَرَ الحافِظُ الإمامُ أبو بكرٍ البَرْقَانِيُّ - رحمه الله - في كِتابِ \" اللُّقَطِ \" (٩) لهُ بإسنادِهِ عنْ عليِّ بنِ المدينِيِّ، قالَ: إذا حَدَّثَكَ الرجلُ فقالَ: حَدَّثَنا فُلانٌ، ولَمْ يَنْسُبْهُ فأحبَبْتَ أنْ تَنْسُبَهُ فقُلْ: «حَدَّثَنا فُلانٌ أنَّ فُلانَ بنَ فُلانٍ حدَّثَهُ» (١٠)، واللهُ أعلمُ.","",{"fn":"انظر: نكت الزركشي ٣/ ٦٢٦.\nفي الشذا: «وغيره» بالواو.\nانظر: نكت الزركشي ٣/ ٦٢٧ - ٦٢٨.\nفي (ع) و(م) والتقييد: «موافقتهما» بالتثنية.\nراجع: المحاسن: ٣٤٥ ففيها تفصيل.\nراجع محاسن الاصطلاح هامش (١).\nفي (ع): «عَلَى».\nفي (ب): «بلفظ».\nفي (أ) و(ب): «اللفظ» بالفاء، وفي (جـ) و(ع) و(م) والتقييد والشذا الفياح ونكت الزركشي: «اللقط» بالقاف، وراجع شرح التبصرة والتذكرة ٢/ ٢٨٥ هامش (٤).\nأسنده الخطيب في الكفاية: (٣٢٣ ت، ٢١٥ هـ)."}],[1214,"وأمَّا إذا كانَ شيخُهُ قدْ ذَكَرَ نَسَبَ شيخِهِ أوْ صِفَتَهُ في أوَّلِ كِتابٍ أوْ جُزْءٍ عندَ أوَّلِ حديثٍ منهُ، واقْتَصَرَ فيما بَعْدَهُ مِنَ الأحاديثِ عَلَى ذِكْرِ اسمِ الشَّيْخِ أوْ بَعضِ نَسَبِهِ. مِثالُهُ: أنْ أروِيَ جُزْءًا عَنِ الفَراوِيِّ وأقُولَ (١) في أوَّلِهِ: «أخبرنا أبو بكرِ منصُورُ بنُ"],[1215,"عبدِ المنعِمِ بنِ عبدِ اللهِ الفَرَاوِيُّ، قالَ: أخْبَرَنا (٢) فُلانٌ». وأقُولَ في باقِي أحاديثِهِ:"],[1216,"«أخبرنا (٣) منصورٌ، أخبرنا منصورٌ» فهلْ يجوزُ لِمَنْ سَمِعَ ذلكَ الجزءَ مِنِّي أنْ يَرْوِيَ عَنِّي الأحاديثَ التي بعدَ الحديثِ الأوَّلِ مُتَفَرِّقَةً، ويقُولَ في كُلِّ واحِدٍ منها: «أخبرنا فُلانٌ قالَ: أخبرنا أبو بكرٍ منصورُ بنُ عبدِ المنعِمِ بنِ عبدِ اللهِ الفَراوِيُّ، قالَ: أخبرنا فُلانٌ»، وإنْ لَمْ أذْكُرْ (٤) لهُ ذَلِكَ في كُلِّ واحدٍ منها اعْتِمادًا عَلَى ذِكْري لهُ أوَّلًا. فهذا قدْ حَكَى الخطيبُ الحافِظُ عَنْ أكْثَرِ أهلِ العِلْمِ أنَّهُمْ أجازُوهُ. وعَنْ بَعْضِهِمْ أنَّ الأَوْلَى أنْ يَقولَ: «يعني: ابنَ فُلانٍ» (٥). ورَوَى بإسْنادِهِ عَنْ أحمدَ بنِ حَنْبَلٍ - رضي الله عنه - أنَّهُ كانَ إذا جاءَ اسمُ الرجُلِ (٦) غيرَ مَنْسُوبٍ قالَ: «يَعْنِي: ابنَ فُلانٍ» (٧)."],[1217,"ورَوَى عَنِ البَرْقَانِيِّ بإسْنادِهِ عَنْ عليِّ بنِ المدينيِّ ما قَدَّمْنا ذِكْرَهُ عنهُ، ثُمَّ ذَكَرَ أنَّهُ هكذا رأى أبا بكرٍ أحمدَ بنَ عليٍّ الأصبهانِيَّ نَزِيْلَ نَيْسابورَ يَفْعَلُ - وكانَ أحَدَ الْحُفَّاظَ الْمُجَوِّدِيْنَ ومِنْ أهلِ الوَرَعِ والدِّيْنِ - وأنَّهُ سَأَلَهُ عَنْ أحاديثَ كَثِيْرَةٍ رَوَاها لهُ قالَ فيها: «أخبرنا أبو عَمْرِو بنُ حَمْدانَ أنَّ أبا يَعْلَى أحمدَ بنَ عليِّ بنِ الْمُثَنَّى الموصِلِيَّ أخْبَرَهُمْ، وأخْبَرنا أبو بكرِ بنُ الْمُقْرِئِ أنَّ إسْحاقَ بنَ أحمدَ بنِ نافِعٍ؛ حَدَّثَهُمْ، وأخبرنا أبو أحمدَ الحافِظُ أنَّ أبا يوسُفَ مُحَمَّدَ بنَ سُفْيانَ الصَّفَّارَ أخبرهُمْ»، فذَكَرَ لهُ أنَّهَا أحاديثُ سَمِعَهَا قراءةً عَلَى شُيُوخِهِ في جُمْلَةِ نُسَخٍ نَسَبُوا الذينَ حَدَّثُوهُمْ بها في أوَّلِها، واقْتَصَرُوا في بقيَّتِها عَلَى ذِكْرِ أسْمائِهِمْ (١).","",{"fn":"في (ع): «فأقول».\nفي (م): «أنبأنا».\nفي (م): «أنبأنا»، وكذا ما بعدها. وكأنه سهو من المحققة الفاضلة إذ لَمْ تميز بَيْنَ: «أخبرنا» و«أنبأنا» في أن الأولى تختصر والثانية لا تختصر.\nفي (جـ): «يذكر».\nالكفاية: (٣٢٣ ت، ٢١٥ هـ).\nكلمة: «الرجل» لَمْ ترد في (ب).\nأخرجه الخطيب في الكفاية: (٣٢٣ ت، ٢١٥ هـ)."}],[1218,"قالَ: وكانَ غيرُهُ يقُولُ في مِثْلِ هذا: «أخبرنا فُلانٌ، قالَ: أخبرنا فُلانٌ، هوَ ابنُ فُلانٍ» (٢)، ثُمَّ يَسُوقُ نَسَبَهُ إلى مُنْتَهَاهُ. قالَ (٣): «وهذا الذي أسْتَحِبُّهُ؛ لأنَّ قَوْمًا مِنَ الرواةِ كانُوا يَقُولُونَ فيما أُجِيْزَ لهمْ: «أخبرنا فُلانٌ أنَّ فُلانًا حَدَّثَهُمْ» (٤)."],[1219,"قُلتُ: جميعُ هذهِ الوجوهِ جائِزٌ، وأوْلاَها أنْ يَقُولَ: «هوَ ابنُ فُلانٍ أو يعني: ابنَ فُلانٍ»، ثُمَّ أنْ يَقُولَ: «إنَّ فُلاَنَ بنَ فُلانٍ»، ثُمَّ أنْ يَذْكُرَ المذكُورَ في أوَّلِ الجزْءِ بعَيْنِهِ مِنْ غيرِ فَصْلٍ، واللهُ أعلمُ."],[1220,"الثَّالِثَ عَشَرَ: جَرَتِ العادةُ بحذْفِ «قالَ» (٥) ونَحْوِهِ فيما بَيْنَ رجالِ الإسْنادِ خَطًّا (٦)، ولا بُدَّ مِنْ ذِكْرِهِ حالَةَ القراءةِ لَفظًا. ومِمَّا قَدْ يُغْفَلُ عنهُ مِنْ ذَلِكَ ما إذا كان في أثناءِ الإسْنادِ: «قُرِئَ عَلَى فُلانٍ: أأخْبَرَكَ فُلانٌ؟» فَيَنبَغِي للقَارِئِ أنْ يَقُولَ فيهِ:"],[1221,"«قيلَ لهُ: أخبركَ فُلانٌ». وَوَقَعَ في بعضِ ذَلِكَ: «قُرِئَ عَلَى فُلانٍ: حَدَّثَنا فلانٌ»، فهذا يُذْكَرُ فيهِ: «قالَ»، فَيُقَالُ: «قُرِئَ عَلَى فُلانٍ، قالَ: حَدَّثنا (٧) فلانٌ»، وقدْ جاءَ هذا مُصَرَّحًا بهِ خَطًّا هكذا في بعضِ ما رُوِّيْناهُ (٨).","",{"fn":"الكفاية: (٣٢٣ ت، ٢١٦ هـ).\nالكفاية: (٣٢٣ ت، ٢١٦ هـ).\nالضمير في (قال) للخطيب البغدادي.\nالكفاية: (٣٢٣ ت، ٢١٥ - ٢١٦ هـ).\nانظر: نكت الزركشي ٣/ ٦٢٨.\nفي (أ): «خطأ» بالهمزة.\nفي (م): «أخبرنا».\nفي (أ): «روينا»."}],[1222,"وإذا تَكَرَّرَتْ كَلِمَةُ: «قالَ» كما في قولِهِ في كِتابِ البخاريِّ: «حَدَّثَنا صالِحُ بنُ حَيَّانَ، قالَ: قالَ عامِرٌ الشَّعْبِيُّ» (١)، حذفُوا إحْداهُما (٢) في الخطِّ وعلى القارِئِ أنْ يَلْفِظَ بهِمَا جميعًا، واللهُ أعلمُ."],[1223,"الرَّابِعَ عَشَرَ: النُّسَخُ المشْهُورَةُ المشْتَمِلَةُ عَلَى أحاديثَ بإسْنادٍ واحِدٍ، كَنُسْخَةِ: هَمَّامِ بنِ مُنَبِّهٍ، عَنْ أبي هُرَيْرَةَ»، رِوايةِ عبدِ الرَّزَّاقِ، عَنْ مَعْمَرٍ، عنهُ، ونحْوِها مِنَ النُّسَخِ والأجْزَاءِ. مِنْهُمْ مَنْ يُجَدِّدُ ذِكْرَ الإسْنادِ في أوَّلِ كُلِّ حديثٍ منها، ويُوجَدُ هذا في كثيرٍ مِنَ الأُصُولِ القدِيْمةِ، وذلكَ أحْوَطُ. ومِنْهُمْ مَنْ يَكْتَفِي بذِكْرِ الإسْنادِ في أوَّلِها عندَ أوَّلِ حديثٍ منها، أو في أوَّلِ كُلِّ مَجْلِسٍ مِنْ مَجالِسِ سَماعِها، ويُدْرِجُ الباقِيَ عليهِ، ويقولُ في كُلِّ حديثٍ بَعْدَهُ «وبالإسْنادِ» أو «وبهِ»، وذلكَ هوَ الأغْلَبُ الأكْثَرُ، وإذا أرادَ مَنْ كَانَ سَمَاعُهُ عَلَى هذا الوجْهِ تَفريقَ تِلْكَ الأحاديثِ ورِوايةَ كُلِّ حديثٍ منها بالإسنادِ المذكورِ في أوَّلِها، جازَ لهُ ذلكَ عندَ الأكْثَرِينَ، مِنْهُمْ: وكِيعُ بنُ الجرَّاحِ (٣)، ويحيى بنُ مَعِيْنٍ (٤)، وأبو بَكْرٍ الإسْماعِيْلِيُّ (٥). وهذا؛ لأنَّ الجميعَ مَعطوفٌ عَلَى الأوَّلِ، فالإسْنادُ المذكورُ أوَّلًا في حُكْمِ المذكورِ في كُلِّ حديثٍ، وهوَ بِمَثَابةِ تقطِيعِ المتنِ الواحِدِ في أبوابٍ بإسْنادِهِ المذكورِ في أوَّلِهِ، واللهُ أعلمُ."],[1224,"ومِنَ المحدِّثِينَ مَنْ أبى إفْرَادَ شَيءٍ مِنْ تِلْكَ الأحادِيثِ الْمُدْرَجَةِ بالإسْنادِ المذكورِ أوَّلًا ورَآهُ تَدلِيْسًا. وسَأَلَ بعضُ أهلِ الحديثِ الأسْتاذَ أبا إسْحاقَ الإسْفرايينِيَّ الفقيهَ الأصُولِيَّ عَنْ ذَلِكَ؟ فقالَ: «لا يَجُوزُ» (٦).","",{"fn":"صحيح البُخَارِيّ ١/ ٣٥ (٩٧).\nفي (ع): «إحديهما».\nالكفاية: (٣٢٢ ت، ٢١٤ - ٢١٥ هـ).\nالمصدر السابق.\nالكفاية: (٣٢٢ ت، ٢١٥ هـ).\nقال السخاوي في فتح المغيث ٢/ ٢٥٢: «ومنع منه الأستاذ أبو إسحاق الإسفراييني في الأسئلة التي سأله عنها الحافظ أبو سعد بن عليك، وقال: إنه لا يجوز أن يذكر الإسناد في كل حديث منها لمن سماعه عَلَى هذا الوصف»."}],[1225,"وعلى هَذَا مَنْ كانَ سماعُهُ عَلَى هَذَا الوجْهِ فَطَرِيْقُهُ أنْ يُبَيِّنَ ويَحْكِيَ ذَلِكَ كَمَا جَرَى، كَمَا فَعَلَهُ مُسْلِمٌ في \"صحيحِهِ\" (١) في «صحيفةِ هَمَّامِ بنِ مُنَبِّهٍ»، نحوُ قَولِهِ:"],[1226,"«حَدَّثَنا مُحَمَّدُ بنُ رافِعٍ، قالَ: حَدَّثَنا عبدُ الرَّزَّاقِ، قالَ: أخبرنا مَعْمَرٌ، عنْ هَمَّامِ بنِ مُنَبِّهٍ، قالَ: هذا ما حَدَّثَنا أبو هُرَيرةَ وذَكَرَ أحادِيْثَ، مِنْها: «وقالَ رَسولُ اللهِ - صلى الله عليه وآله وسلم -: إنَّ أدْنَى مَقْعَدِ أحدِكُمْ في الجنَّةِ أنْ يَقُولَ لهُ: تَمَنَّ ... الحديثَ». وهكذا فَعَلَ كَثيرٌ مِنَ المؤَلِّفِينَ (٢)، واللهُ أعلمُ."],[1227,"الخامِسَ عَشَرَ: إذا قَدَّمَ ذِكْرَ المتنِ عَلَى الإسنادِ أو ذِكْرَ المتنِ وبعضِ الإسنادِ ثُمَّ ذَكَرَ الإسْنادَ عَقِيْبَهُ (٣) عَلَى الاتِّصَالِ، مِثلُ أنْ يَقولَ: «قالَ رسولُ اللهِ - صلى الله عليه وآله وسلم - كذا وكذا»، أو يقولَ: «رَوَى عُمَرُ بنُ دِينارٍ، عَنْ جابِرٍ، عَنْ رَسُولِ اللهِ - صلى الله عليه وآله وسلم - كذا وكذا»، ثُمَّ يقولَ: «أخبرنا بهِ فُلانٌ، قالَ: أخبرنا فلانٌ»، ويَسُوقَ الإسنادَ حَتَّى يَتَّصِلَ بِما قَدَّمَهُ، فهذا يَلْتَحِقُ بما إذا قَدَّمَ (٤) الإسْنادَ في كونِهِ يَصِيْرُ بهِ مُسْنِدًا للحديثِ لا مُرْسِلًا لهُ، فلَوْ أرادَ مَنْ سَمِعَهُ منهُ هكذا أنْ يُقَدِّمَ الإسْنادَ ويُؤَخِّرَ المتنَ ويُلَفِّقَهُ كذلكَ فقدْ وَرَدَ عَنْ بَعْضِ مَنْ تَقَدَّمَ مِنَ المحدِّثِينَ أنَّهُ جَوَّزَ ذَلِكَ."],[1228,"قُلتُ: يَنْبَغِي أنْ يَكونَ فيهِ خِلافٌ نحوُ الخِلافِ في تَقْدِيْمِ (٥) بعضِ مَتْنِ الحديثِ عَلَى بعضٍ. وقدْ حَكَى الخطيبُ المنعَ مِنْ ذَلِكَ عَلَى القولِ بأنَّ الرِّوَايةَ عَلَى المعنَى"],[1229,"لا تَجوزُ، والجوازَ عَلَى القولِ بأنَّ الروايةَ عَلَى المعنى تجوزُ، ولا فَرْقَ بينَهُما في ذَلِكَ،"],[1230,"واللهُ أعلمُ."],[1231,"وأمَّا ما يَفْعلُهُ بعضُهُمْ مِنْ إعادَةِ ذِكْرِ الإسْنادِ في آخِرِ الكِتابِ أو الجزْءِ بعدَ ذِكْرِهِ أوَّلًا، فهذا لا يَرْفَعُ الخِلاَفَ الذي تَقَدَّمَ ذِكْرُهُ في إفْرَادِ كُلِّ حديثٍ بذلكَ الإسْنادِ عندَ روايَتِها؛ لِكَونِهِ لاَ يَقَعُ مُتَّصِلًا بِكُلِّ واحدٍ منها، ولَكِنَّهُ يُفِيْدُ (١) تأكِيْدًا واحْتِياطًا ويَتَضَمَّنُ إجازَةً بالِغَةً مِنْ أعلى أنواعِ الإجازاتِ، واللهُ أعلمُ.","",{"fn":"صحيح مسلم ١/ ١١٤ عقيب (١٨٢).\nانظر: نكت الزركشي ٣/ ٦٢٩ - ٦٣٠، ومحاسن الاصطلاح: ٣٤٩.\nفي الشذا: «عقبه».\nفي بعض النسخ ضبط مبنيًا للمجهول.\nراجع: نكت الزركشي ٣/ ٦٣٠ - ٦٣١."}],[1232,"السَّادِسَ عَشَرَ: إذا رَوَى الْمُحَدِّثُ الحديثَ بإسْنادٍ ثُمَّ أتْبَعَهُ بإسْنادٍ آخَرَ، وقالَ عندَ انتِهَائِهِ: «مِثْلَهُ» فأرادَ الراوي عنهُ أنْ يَقْتَصِرَ عَلَى الإسْنادِ الثاني ويَسُوقَ لَفْظَ الحديثِ المذكورِ عَقِيبَ الإسْنادِ الأوَّلِ، فالأظْهَرُ المنْعُ مِنْ ذَلِكَ (٢)."],[1233,"ورُوِّينا عَنْ أبي بكرٍ الخطيبِ الحافِظِ - رحمه الله - قالَ: «كانَ شُعْبَةُ لاَ يُجِيزُ ذَلِكَ. وقالَ بعضُ أهلِ العِلْمِ: يجوزُ ذَلِكَ إذا عُرِفَ (٣) أنَّ المحدِّثَ ضَابِطٌ مُتَحَفِّظٌ يذهبُ إلى تَمييزِ الألفاظِ وعدِّ الحروفِ. فإنْ لَمْ يُعْرَفْ ذَلِكَ منهُ، لَمْ يَجُزْ ذَلِكَ. وكانَ غيرُ واحدٍ مِنْ أهلِ العِلْمِ إذا (٤) رَوَى مِثلَ هذا يُورِدُ الإسْنادَ ويَقُولُ: «مِثْلُ حديثٍ قَبْلَهُ، مَتْنُهُ كذا وكذا»، ثُمَّ يَسُوقُهُ. وكذلكَ إذا كانَ المحدِّثُ قدْ قالَ نحوَهُ، قالَ: «وهذا هوَ الذي أختارُهُ» (٥)."],[1234,"أخبرنا أبو أحمدَ عبدُ الوهابِ (٦) بنُ أبي منصورٍ عليِّ بنِ عليٍّ البغدادِيُّ شيخُ الشُّيوخِ بها بقراءَتي عليهِ بها، قالَ: أخبرنا والدِي - رحمه الله -، قالَ: أخبرنا أبو مُحَمَّدٍ عبدُ اللهِ بنُ مُحَمَّدٍ الصَّرِيْفِينِيُّ (٧)، قالَ: أخبرنا أبو القاسِمِ بنُ حَبَابَةَ (٨)، قالَ: حَدَّثَنا أبو القاسِمِ عبدُ اللهِ بنُ مُحَمَّدٍ البغويُّ، قالَ: حَدَّثَنا عَمْرُو بنُ مُحَمَّدٍ النَّاقِدُ، قالَ: حَدَّثَنا وكيعٌ قالَ: قالَ شُعْبَةُ: «فُلانٌ عنْ فُلانٍ، مِثْلَهُ لا يُجْزِئُ، قالَ وكيعٌ: وقالَ سُفيانُ الثَّوْرِيُّ: يُجْزِئُ» (١).","",{"fn":"في (جـ): «يقيد».\nانظر: نكت الزركشي ٣/ ٦٣١، ومحاسن الاصطلاح ٣٥٢.\nفي نسخة (أ) حاشية نصها: «كذا ضبط في الأصل الذي فيه السماع عَلَى الخطيب»، يعني: بضم العين، ومثلها في الشذا الفياح.\nفي (ع): «إذا إذا».\nالكفاية: (٣١٩ ت، ٢١٢ هـ).\nفي (ب): «أحمد بن عبد الوهاب»، وهو خطأ، والصواب ما أُثْبِت كما في باقي النسخ ومصادر ترجمته. انظر: السير ٢١/ ٥٠٢.\nبفتح الصاد المهملة وكسر الراء وسكون الياء المنقوطة من تحتها باثنتين والفاء بَيْنَ الياءين، وفي آخرها النون، هذه النسبة إلى صريفين. انظر: الأنساب ٣/ ٥٤٥، وترجمته في السير ١٨/ ٣٣٠.\nبفتح الحاء، واسمه عبيد الله. تاج العروس ٢/ ٢٢٧."}],[1235,"وأمَّا إذا قالَ: نحوَهُ، فهوَ في ذَلِكَ عِنْدَ بعضِهِمْ كما إذا قالَ: مِثْلَهُ. نُبِّئْنا بإسْنادٍ عَنْ وكيعٍ، قالَ: قالَ سُفْيانُ: «إذا قالَ: نحْوَهُ، فهوَ حديثٌ. وقالَ شُعْبَةُ: «نَحْوَهُ» شَكٌّ (٢). وعَنْ يحيى بنِ مَعينٍ أنَّهُ أجازَ ما قَدَّمنا ذِكْرَهُ في قَوْلِهِ: «مِثْلَهُ»، ولَمْ يُجِزْهُ في قَوْلِهِ: «نحوَهُ» (٣). قالَ الخطيبُ: «وهذا القولُ عَلَى مذهبِ مَنْ لَمْ يُجِزْ الروايةَ عَلَى المعنى فأمَّا عَلَى مذهبِ مَنْ أجازَها فلا فَرْقَ بَيْنَ: مِثْلَهُ ونحْوَهُ» (٤). واللهُ أعلمُ."],[1236,"قلتُ: هذا لهُ تَعَلُّقٌ بما رُوِّيْناهُ (٥) عَنْ مسعودِ بنِ عليٍّ السِّجْزِيِّ (٦) أنَّهُ سَمِعَ الحاكِمَ أبا عبدِ اللهِ الحافِظَ يَقُولُ: «إنَّ مِمَّا يَلْزمُ الحَدِيْثِيَّ مِنَ الضَّبْطِ والإتْقَانِ أنْ يُفَرِّقَ بَيْنَ أنْ يَقُولَ: مِثْلَهُ، أو يَقُولَ: نَحْوَهُ، فلا يَحِلُّ لهُ أنْ يَقُولَ: مِثْلَهُ إلاَّ بَعْدَ أنْ يَعْلَمَ أنَّهُما عَلَى لَفْظٍ (٧) واحدٍ، ويَحِلُّ لهُ أنْ يَقُولَ: نَحْوَهُ إذا كانَ عَلَى مِثْلِ مَعَانيهِ»، واللهُ أعلمُ."],[1237,"السَّابِعَ عَشَرَ: إذا ذَكَرَ الشَّيْخُ إسنادَ الحديثِ، ولَمْ يَذْكُرْ مِنْ مَتْنِهِ إلاَّ طَرَفًا ثُمَّ قالَ: «وذكرَ الحديْثَ» أو قالَ: «وذكرَ الحَديثَ بِطولِهِ» فأرادَ الراوي عنهُ أن يرويَ عنهُ الحديثَ بكمالِهِ وبطُولهِ فهذا أولى بالمنعِ مما سبقَ ذِكْرُهُ في قولِهِ: «مِثْلَهُ» أو «نَحْوَهُ». فطريقُهُ أنْ يُبَيِّنَ ذَلِكَ بأنْ يَقْتَصَّ ما ذكرَهُ الشَّيْخُ عَلَى وجهِهِ، ويَقولَ (٨): «قال: وذكرَ الحديثَ بطُولِهِ». ثُمَّ يَقُولَ: «والحديثُ بطُولِهِ هوَ كذا وكذا»، ويسوقَهُ إلى آخرِهِ.","",{"fn":"أخرج الخطيب معناه في الكفاية: (٣١٩ ت، ٢١٣ هـ).\nأسنده الخطيب في الكفاية: (٣٢٠ ت، ٢١٣ هـ).\nأسنده الخطيب في الكفاية: (٣٢٠ - ٣٢١ ت، ٢١٣ - ٢١٤ هـ).\nالكفاية: (٣٢١ ت، ٢١٤ هـ).\nفي (ب) و(ج): «روينا».\nسؤالات مسعود: ١٢٣.\nفي (أ): «معنى».\nفي (ع) والتقييد: «فيقول»."}],[1238,"وسألَ بعضُ أهلِ الحديثِ أبا إسْحاقَ إبراهِيمَ بنَ مُحَمَّدٍ الشَّافِعِيَّ المقَدَّمَ في الفقهِ والأُصُولِ عَنْ ذَلِكَ، فقالَ: «لاَ يَجوزُ لِمَنْ سَمِعَ عَلَى هذا الوصفِ أنْ يرويَ الحديثَ بما فيهِ مِنَ الألفاظِ عَلَى التفصيلِ»."],[1239,"وسألَ أبو بكرٍ البَرْقانِيُّ الحافِظُ الفقيهُ أبا بكرٍ الإسْماعِيْلِيَّ الحافِظَ الفَقيهَ عَمَّنْ قَرَأَ إسْنادَ حديثٍ عَلَى الشَّيْخِ، ثُمَّ قالَ: «وذكرَ الحديثَ»، هلْ يَجوزُ أنْ يُحَدِّثَ بجميعِ الحديثِ؟ فقالَ: إذا عَرَفَ المحدِّثُ والقارئُ ذَلِكَ الحديثَ فأرْجُو أنْ يَجُوزَ ذَلِكَ والبيانُ أَوْلَى أنْ يَقُولَ كما كَانَ (١)."],[1240,"قلتُ: إذا جَوَّزْنا ذَلِكَ، فالتحقيقُ فيهِ أنَّهُ بطريقِ الإجازَةِ فيما لَمْ يَذْكُرْهُ الشَّيْخُ، لكنَّها إجازَةٌ أكِيدةٌ قَويَّةٌ مِنْ جِهاتٍ عديدةٍ، فجازَ لهذا مَعَ كونِ أوَّلِهِ سماعًا إدراجُ الباقي عليهِ من غيرِ إفرادٍ لهُ بلفظِ الإجازَةِ (٢)، واللهُ أعلمُ."],[1241,"الثَّامِنَ عَشَرَ: الظَّاهِرُ أنَّهُ لا يَجُوزُ تَغييرُ «عَنِ النبيِّ» إلى «عَنْ رسولِ اللهِ - صلى الله عليه وآله وسلم -»، وكذا بالعكسِ، وإنْ جازَتِ الروايةُ بالمعنى، فإنَّ شَرْطَ ذَلِكَ ألاَّ يَخْتَلِفَ المعنى، والمعنى في هذا مختلِفٌ (٣). وثبتَ عَنْ عبدِ اللهِ بنِ أحمدَ بنِ حَنْبَلٍ أنَّهُ رأَى أباهُ إذا كانَ في الكِتابِ «النبيُّ» فقالَ المحدِّثُ: «عَنْ رسولِ اللهِ - صلى الله عليه وآله وسلم -»، ضَرَبَ وكَتَبَ: «عَنْ رسولِ اللهِ - صلى الله عليه وآله وسلم -» (٤) وقالَ الخطيبُ أبو بكرٍ: «هذا غيرُ لازمٍ، وإنَّما اسْتَحَبَّ أحمدُ اتِّباعَ المحدِّثِ في لفظِهِ، وإلاَّ فمذهبُهُ الترخيصُ في ذَلِكَ» (٥)، ثُمَّ ذكرَ بإسْنادِهِ عَنْ صالِحِ بنِ أحمدَ بنِ حَنْبَلٍ، قالَ: «قلتُ لأبي: يكونُ في الحديثِ: قالَ رسولِ اللهِ - صلى الله عليه وآله وسلم - فيجعلُ الإنسانُ: قالَ النبيُّ - صلى الله عليه وآله وسلم -، قالَ: أرجو ألاَّ يكونَ بهِ بأسٌ» (٦). وذكرَ الخطيبُ بسَنَدِهِ (٧) عَنْ حمَّادِ بنِ سَلَمَةَ أنَّهُ كانَ يُحَدِّثُ وبينَ يديهِ عَفَّانُ وبَهْزٌ، فجَعَلا يُغَيِّرانِ: «النبيَّ - صلى الله عليه وآله وسلم -» مَنْ «رسولِ اللهِ - صلى الله عليه وآله وسلم -»، فقالَ لهما حمَّادٌ: أمَّا أنتُما فلا تَفْقَهانِ أبدًا» (١)، واللهُ أعلمُ.","",{"fn":"الكفاية: (٤٤٥ ت، ٣١١ هـ).\nقال البلقيني في المحاسن: ٣٥٥: «وعلى تقدير الإجازة، لا يكون أولى بالمنع من: مثله، ونحوه، إذا كان الحديث بطوله معلومًا لهما كما ذكر «الإسماعيلي»، بل يكون أولى بالجواز».\nراجع: نكت الزركشي ٣/ ٦٣٣، والتقييد والإيضاح: ٢٣٩.\nأسنده الخطيب في الكفاية: (٣٦٠ ت، ٢٤٤ هـ).\nالكفاية: (٣٦٠ ت، ٢٤٤ هـ).\nأسنده الخطيب في الكفاية: (٣٦٠ ت، ٢٤٤ هـ).\nفي (جـ): «سنده»."}],[1242,"التاسعَ عَشَرَ: إذا كانَ سَمَاعُهُ عَلَى صفةٍ فيها بعضُ الوَهْنِ (٢) فَعَليهِ أنْ يَذْكُرَها في حالَةِ الروايةِ، فإنَّ في إغفالِها نوعًا من التَّدْلِيسِ، وفيما مَضَى لنا أمثِلَةٌ لذلكَ. ومِنْ أمْثِلَتِهِ ما إذا حَدَّثَهُ المحدِّثُ مِنْ حِفْظِهِ في حالةِ المذاكَرَةِ فَلْيَقُلْ: حَدَّثَنا فُلانٌ مُذَاكَرَةً، أو حَدَّثَناهُ في الْمُذاكَرةِ، فقدْ كانَ غيرُ واحدٍ مِنْ مُتَقدِّمي العلماءِ يَفْعَلُ ذَلِكَ. وكانَ جماعَةٌ مِنْ حُفَّاظِهِمْ يمنعونَ مِنْ أنْ يُحمَلَ عَنْهُمْ في الْمُذاكَرةِ شيءٌ، مِنْهُم: عبدُ الرحمانِ بنُ"],[1243,"مَهديٍّ (٣) وأبو زُرْعَةَ الرازِيُّ (٤). رُوِّيْناهُ عَنِ ابنِ المبارَكِ (٥) وغيرِهِ. وذلكَ لِمَا يَقَعُ فيها مِنَ المساهَلَةِ مَعَ أنَّ الحِفْظَ خَوَّانٌ، ولذلكَ امْتَنَعَ جَمَاعَةٌ مِنْ أعلامِ الحفَّاظِ مِنْ روايةِ ما يَحْفَظونَهُ إلاَّ مِنْ كُتُبِهِمْ، مِنْهُم: أحمدُ بنُ حَنْبَلٍ - رضي الله عنهم - أجمعينَ (٦)، واللهُ أعلمُ."],[1244,"العِشرونَ: إذا كانَ الحديثُ عَنْ رَجلينِ أحدُهُما مَجروحٌ، مثلُ أنْ يكونَ عَنْ ثابِتٍ البُنَانِيِّ (٧)، وأبانَ بنِ أبي عَيَّاشٍ (٨)، عَنْ أنسٍ فلا يُسْتَحْسَنُ إسْقاطُ المجروحِ مِنَ الإسْنادِ والاقْتِصارُ عَلَى ذِكْرِ الثِّقَةِ، خوفًا مِنْ أنْ يَكُونَ فيهِ عَنِ المجروحِ شيءٌ لَمْ يَذْكُرْهُ الثِّقَةُ، قالَ نحوًا مِنْ ذَلِكَ أحمدُ بنُ حَنْبَلٍ (١)، ثُمَّ الخطيبُ أبو بكرٍ (٢). قالَ الخطيبُ:","",{"fn":"أخرجه الخطيب في الكفاية: (٣٦١ ت، ٢٤٤ - ٢٤٥ هـ)، وانظر: محاسن الاصطلاح ٣٥٦.\nفال الزركشي في نكته ٣/ ٦٣٤: «ظاهره الوجوب، وعبارة الخطيب: أستحب أن يقول: حدثناه في المذاكرة». وانظر: الجامع لأخلاق الراوي ٢/ ٣٧.\nانظر: بعض الآثار الواردة عنه في ذَلِكَ مسندة في الجامع لأخلاق الراوي وآداب السامع (١١١٠) و(١١١١).\nانظر: ما أسنده الخطيب في الجامع (١١١٢) و(١١١٣).\nانظر: بعض الآثار الواردة عنه في هذا الموضوع في الجامع (١١١٢).\nلذلك قال الإمام علي بن المديني: «ليس في أصحابنا أحفظ من أبي عبد الله أحمد بن حَنْبَلٍ، وبلغني أنَّهُ لا يحدث إلا من كتاب، ولنا فيه أسوة». وانظر: مزيدًا من ذَلِكَ في الجامع ٢/ ١٢ - ١٣.\nانظر ترجمته في: تهذيب الكمال ١/ ٤٠٢ (٧٩٧).\nانظر ترجمته في: تهذيب الكمال ١/ ٩٥ (١٣٨)."}],[1245,"«وكانَ مسلمُ بنُ الحجَّاجِ (٣) في مثلِ هذا رُبَّما أسْقَطَ المجروحَ مِنَ الإسْنادِ ويَذْكُرُ الثِّقَةَ، ثُمَّ يَقُولُ: «وآخرُ» كِنايَةً عَنِ المجروحِ». قالَ: «وهذا القولُ لا فائدةَ فيهِ» (٤)."],[1246,"قلتُ: وهكذا يَنْبَغِي إذا كانَ الحديثُ عَنْ رَجلَينِ ثِقَتَيْنِ ألاَّ يُسْقِطَ أحدَهُما منهُ؛ لِتَطَرُّقِ مثلِ الاحْتِمالِ المذكورِ إليهِ، وإنْ كانَ محذورُ الإسْقاطِ فيهِ أقَلَّ، ثُمَّ لاَ يَمتنعُ ذَلِكَ في الصورتينِ امْتِناعَ تحريمٍ؛ لأنَّ الظاهِرَ اتِّفَاقُ الروايتينِ (٥)، وما ذُكِرَ مِنَ الاحْتِمالِ نادِرٌ بعيدٌ فإنَّهُ مِنَ الإدْراجِ الذي لا يجوزُ تَعَمُّدُهُ كما سَبَقَ في نوعِ المدرجِ، واللهُ أعلمُ."],[1247,"الحادي والعِشْرونَ: إذا سَمِعَ بَعْضَ حديثٍ مِنْ شيخٍ، وَبَعْضَهُ مِنْ شيخٍ آخرَ فَخَلَطَهُ ولَمْ يُمَيِّزْهُ وعَزَى الحديثَ جُملةً إليهِما مُبَيِّنًا أنَّ عَنْ أحدِهِما بعضَهُ، وعَنِ الآخَرِ بَعْضَهُ فذلكَ جائِزٌ كما فعلَ الزُّهْرِيُّ (٦) في حديِ الإفْكِ حيثُ رواهُ عَنْ عُرْوَةَ، وابنِ الْمُسَيِّبِ، وعلقمةَ بنِ وقَّاصٍ اللَّيْثِيِّ، وعُبَيْدِ اللهِ بنِ عبدِ اللهِ بنِ عُتبةَ، عَنْ عائِشَةَ"],[1248,"- رضي الله عنها - وقالَ: «وكُلُّهُمْ حَدَّثَني طائفةً مِنْ حديثِها قالوا: قالتْ: ... الحديثَ (٧). ثُمَّ إنَّهُ ما مِنْ شيءٍ مِنْ ذَلِكَ الحديثِ إلاَّ وهوَ في الحكْمِ كأنَّهُ رواهُ عَنْ أحَدِ الرجلَينِ عَلَى الإبهامِ، حتَّى إذا كانَ أحدُهُما مجروحًا لَمْ يَجُزْ الاحْتِجاجُ بشيءٍ من ذَلِكَ الحديثِ، وغيرُ جائِزٍ لأحَدٍ بعدَ اخْتِلاطِ ذَلِكَ، أنْ يُسْقِطَ ذِكْرَ أحَدِ الراويَينِ (٨) ويَرْويَ الحديثَ عَنِ الآخَرِ وَحْدَهُ، بلْ يَجِبُ ذِكْرُهُما جميعًا مَقْرُونًا بالإفصاحِ بأنَّ بعضَهُ عَنْ أحدِهِما، وبعضَهُ عَنِ الآخَرِ، واللهُ أعلمُ.","",{"fn":"الكفاية: (٥٣٧ ت، ٣٧٨ هـ).\nانظر: الكفاية (٥٣٧ - ٥٣٨ ت، ٣٧٧ - ٣٧٨ هـ).\nوكذلك صنع الإمام البخَاري والنسائي، انظر: تهذيب الكمال ٤/ ٢٥٥ - ٢٥٦ ترجمة عبد الله بن لهيعة.\nالكفاية: (٣٧٨ هـ، ٥٣٧ ت)، قلنا: وقد تعقبه الزركشي في نكته ٣/ ٦٣٤ فقالَ: «بل له فائدةٌ وهو الإعلام بأنه رواه عن رجلين، وأن المذكور لم ينفرد، وفيه تتبع الطرق». وانظر: محاسن الاصطلاح: ٢٥٧.\nفي (أ) و(ب) والشذا والتقييد: «الراويين».\nقال الزركشي في نكته ٣/ ٦٣٥: «ما ذكره في حديث الإفك قد تقدم أن الزُّهْرِيّ قال فيه - بعد أن ذكر ما ذكر: الذي حَدَّثَني عروة عن عائشة. وساقه من طريق عروة -، وقد تقدم مافيه».\nصحيح البخاري ٣/ ٢١٩ و٤/ ٤٠ و٥/ ١١٠ و١٤٨ و٦/ ٩٥ و٩٦ و٨/ ١١٢ و١١٨ و١٦٨ و١٧٢ و٩/ ١٣٩ و١٧٦.\nفي (جـ): «الرِّوَايَتَيْنِ»."}],[1249,"النوع السابع والعشرون معرفة آداب المحدث"],[1250,"وقَدْ مَضَى طَرَفٌ مِنها اقْتَضَتْهُ الأنْواعُ التي قَبْلَهُ."],[1251,"عِلْمُ الحديثِ عِلْمٌ شَريفٌ، يُناسِبُ مَكارِمَ الأخْلاَقِ ومَحَاسِنَ الشِّيَمِ (١)، ويُنافِرُ مَسَاوِئَ (٢) الأخلاقِ ومَشَايِنَ الشِّيَمِ، وهوَ مِنْ عُلُومِ الآخِرَةِ لا مِنْ عُلُومِ الدنيا (٣). فَمَنْ أرادَ التَّصَدِّي لإسْماعِ الحديثِ أو لإفادَةِ شيءٍ مِنْ عُلُومِهِ، فَلْيُقَدِّمْ تَصْحِيْحَ النِّيَّةِ وإخْلاَصَها وليُطَهِّرْ قَلْبَهُ مِنَ الأغراضِ الدُّنْيَوِيَّةِ وأدناسِها، وليَحْذَرْ بَلِيَّةَ حُبِّ الرِّيَاسَةِ ورُعُوناتِها."],[1252,"وَقَدِ اخْتُلِفَ في السِّنِّ الذي إذا بلغَهُ اسْتُحِبَّ لهُ التَّصَدِّي لإسْماعِ الحديثِ والانْتِصَابِ لرِوايتِهِ."],[1253,"والذي نَقُولُهُ إنَّهُ متى احْتِيجَ إلى ما عِنْدَهُ (٤)، اسْتُحِبَّ لهُ التَّصَدِّي لرِوايتِهِ ونَشْرِهِ في أيِّ سِنٍّ كانَ. ورُوِّيْنا عَنِ القاضِي الفاضِلِ أبي مُحَمَّدِ بنِ خَلاَّدٍ -رحمه الله- أنَّهُ قالَ (٥): «الذي يَصِحُّ عِنْدِي مِنْ طريقِ الأثَرِ والنَّظَرِ في الحدِّ الذي إذا بلَغَهُ الناقِلُ حَسُنَ بهِ أنْ يُحَدِّثَ، هُوَ أنْ يَسْتَوفِيَ الخمسينَ؛ لأنَّها انْتِهاءُ الكُهُولَةِ وفيها مُجْتَمَعُ الأشُدِّ.","",{"fn":"قال الزركشي ٣/ ٦٣٦: «هذه مقالة معنوية، إلا فالذي يقابل الشين الزين لا المحاسن، قال في الصحاح: الشين خلاف الزين، يقال: شانه يشينه، والمشاين: المعايب والمقابح ... انتهى. وقد كرّر الشيم ثلاث مرات، مرتين باللفظ، ومرة بالمعنى، وهو الأخلاق، لكن قيل: الشيم: الطبائع». وانظر: الصحاح ٥/ ١٩٦٤، ٢١٤٧.\nفي (أ) و(ب): «مساوي» بلا همز، قال الزركشي في نكته ٣/ ٦٣٧: «قال صاحب تثقيف اللسان: ويقولون: ظهرت مساويه، والصواب: مساوئه بالهمز. وقد استدرك أبو إسحاق الأجدابي عليه، قال: الأصل الهمز كما ذكرته، وترك الهمز جائز عَلَى لغة من يقول في الخاطئين: الخاطين، وهي لغة معروفة».\nقال الزركشي في نكته ٣/ ٦٣٧: «مراد أنَّهُ عبادة لذاته لا صناعة».\nفي (جـ): «إلى طلب ما عنده ...».\nالمحدّث الفاصل: ٣٥٢، ونقله عنه القاضي في الإلماع: ٢٠٠، والخطيب في الجامع ١/ ٣٢٣ (٧١٦)."}],[1254,"قالَ سُحَيْمُ بنُ وُثَيْلٍ (١):"],[1255,"أخُو خَمْسِيْنَ مُجْتَمِعٌ أَشُدِّي ... ونَجَّذَنِي مُدَاوَرَةُ الشُّؤُونِ (٢)"],[1256,"قالَ: «وليسَ بِمُنْكَرٍ أنْ يُحَدِّثَ عِندَ اسْتِيْفاءِ الأرْبَعينَ؛ لأنَّها حَدُّ الاسْتواءِ ومُنْتَهى الكَمالِ؛ نُبِّئَ رسولُ اللهِ - صلى الله عليه وآله وسلم - وهوَ ابنُ أربعينَ، وفي الأربعينَ تَتَناهَى عَزِيْمَةُ الإنْسَانِ وقُوَّتُهُ ويَتَوَفَّرُ عَقْلُهُ ويَجُودُ رَأْيُهُ» (٣)."],[1257,"وأنْكَرَ القاضِي عِيَاضٌ ذَلِكَ عَلَى ابنِ خَلاَّدٍ، وقالَ: «كَمْ مِنَ السَّلَفِ الْمُتَقَدِّمِينَ ومَنْ بَعْدَهُمْ (٤) مِنَ المحدِّثِينَ مِنْ لَمْ يَنْتَهِ إلى هذا السِّنِّ (٥) وماتَ قَبلَهُ، وقدْ نَشَرَ مِنَ الحديثِ والعِلْمِ ما لاَ يُحْصَى. هذا عُمَرُ بنُ عبدِ العزيزِ تُوفِّيَ وَلَمْ يُكْمِلِ الأرْبَعينَ، وسَعيدُ بنُ جُبيرٍ لَمْ يَبلُغِ الخمْسِينَ. وكذلكَ إبراهيمُ النَّخَعِيُّ، وهذا مالِكُ بنُ أنسٍ جلَسَ للنَّاسِ ابنَ نَيِّفٍ وعِشْرينَ، وقيلَ: ابنُ سَبْعَ عَشْرَةَ، والنَّاسُ مُتَوَافِرُونَ وشُيُوخُهُ أحياءٌ. وكذلكَ مُحَمَّدُ بنُ إدْريسَ الشَّافِعِيُّ قَدْ أُخِذَ عنهُ العِلْمَ في سِنِّ الحدَاثَةِ وانتَصَبَ لِذَلِكَ» (٦)، واللهُ أعلم.","",{"fn":"هو سحيم بن وثيل - بالمثلثة مصغّر - الرياحي، شاعر مخضرم، قال ابن دريد: عاش في الجاهلية أربعين وفي الإسلام ستين. انظر: الإصابة ٢/ ١١٠.\nهو في الكامل ١/ ٣٠٤، والصحاح ٢/ ٥٧١، وأساس البلاغة: ٦١٩، واللسان ٣/ ٥١٣، وتاج العروس ٩/ ٤٨٥. وقوله: «أخو خمسين»، أي: أنا أخو خمسين سنة، واجتماع الأشد: عبارة عن كمال القوى في البدن والعقل، ومعنى: نجذني، أي: جعلني ذا تجربة وخبرة، يقال: رجل منجِّذ - بضم الميم وفتح الجيم أو كسرها - الذي جَرَّب الأمور وعرفها وأحكمها، وهو المجرّب، قال اللحياني: المنجذ هو الذي أصابته البلايا. والمداورة: المعالجة والمزاولة، والشؤون: الأمور، يعني: مداولة الأمور ومعالجتها. انظر: اللسان ٣/ ٥١٣، وحاشية الإلماع: ٢٠٠.\nالمحدّث الفاصل: ٣٥٢، ونقله عنه الخطيب في الجامع لأخلاق الراوي وآداب السامع (٧١٦)، والقاضي عياض في الإلماع: ٢٠٠.\nعبارة: «ومن بعدهم» سقطت من (م).\nفي الشذا: «الشيء».\nالإلماع: ٢٠ - ٢٠٤."}],[1258,"قلتُ: ما ذكرَهُ ابنُ خَلاَّدٍ غيرُ مُسْتَنْكَرٍ، وهوَ مَحمولٌ عَلَى أنَّهُ قالَهُ فِيْمَنْ يَتَصَدَّى للتَّحْدِيثِ ابْتِداءً مِنْ نَفْسِهِ مِنْ غَيرِ بَراعَةٍ (١) في العِلْمِ تَعَجَّلَتْ لهُ قَبْلَ السِّنِّ الذي ذَكَرَهُ. فهذا إنَّما يَنْبَغِي لهُ ذَلِكَ بعدَ اسْتِيْفاءِ السِّنِّ المذكُورِ فإنَّهُ مِظَنَّةُ الاحتياجِ إلى ما عِنْدَهُ."],[1259,"وأمَّا الذينَ ذَكَرَهُمْ عياضٌ مِمَّنْ حَدَّثَ قَبْلَ ذَلِكَ، فالظَّاهِرُ أنَّ ذَلِكَ لبراعَةٍ مِنْهُم في العِلْمِ تَقَدَّمَتْ، ظَهَرَ لهُمْ مَعَها الاحْتِياجُ إليهِمْ فَحَدَّثُوا قبلَ ذَلِكَ، أو لأنَّهُم سُئِلُوا ذَلِكَ إمَّا بصريحِ السُّؤَالِ، وإمَّا بقَرِيْنَةِ الحالِ."],[1260,"وأمَّا السِّنُّ الذي إذا بلَغَهُ المحدِّثُ انْبَغَى (٢) لهُ الإمْسَاكُ عَنِ التَّحْدِيْثِ فَهُوَ السِّنُّ الذي يُخْشَى عليهِ فيهِ مِنَ الْهَرَمِ والْخَرَفِ، ويُخافُ عليهِ فيهِ أنْ يُخَلِّطَ (٣)، ويروى ما ليسَ مِنْ حديثِهِ والنَّاسُ في بُلُوغِ هذا السِّنُّ يَتَفاوتُونَ بحسبِ اخْتِلافِ أحْوَالِهِمْ، وهكذا إذا عَمِيَ وخَافَ أنْ يُدْخَلَ عليهِ ما ليسَ مِنْ حَدِيْثِهِ فليُمْسِكْ عَنِ الروايةِ. وقالَ ابنُ خَلاَّدٍ: «أعْجَبُ إليَّ أنْ يُمْسِكَ في الثمانينَ؛ لأنَّهُ حَدُّ الْهَرَمِ؛ فإنْ كانَ عَقْلُهُ ثَابِتًا ورَأْيُهُ مُجْتَمِعًا يَعْرِفُ حديثَهُ ويَقُومُ بهِ وتَحرَّى أنْ يُحَدِّثَ احْتِسَابًا رَجَوْتُ لهُ خَيْرًا» (٤)."],[1261,"ووَجْهُ ما قالَهُ أنَّ مَنْ بَلَغَ الثَّمَانِينَ ضَعُفَ حَالُهُ في الغالِبِ، وخِيفَ عليهِ الاخْتِلالُ والإخْلالُ أوْ أنْ لاَ يُفْطَنَ لهُ إلاَّ بعدَ أنْ يَخْلِطَ كما اتُّفِقَ لِغَيْرِ واحِدٍ مِنَ الثِّقَاتِ، مِنْهُم: عبدُ الرَّزَّاقِ، وسَعيدُ بنُ أبي عَرُوبةَ. وقدْ حدَّثَ خَلْقٌ بَعْدَ مُجاوزَةِ هذا السِّنِّ فَسَاعَدَهُمُ التَّوْفِيقُ وصَحِبَتْهُمْ السَّلامَةُ، مِنْهُم: أنَسُ بنُ مالِكٍ وسَهْلُ بنُ سَعْدٍ، وعبدُ اللهِ بنُ أبي أوْفَى مِنَ الصحابةِ، ومالِكٌ، واللَّيثُ، وابنُ عُيينةَ، وعليُّ ابنُ الجعْدِ (٥)، في عددٍ جَمٍّ مِنَ المتَقَدِّمينَ والمتَأَخِّرينَ. وفيهم (٦) غيرُ واحدٍ حَدَّثُوا بعدَ اسْتِيْفاءِ مئةِ سَنَةٍ، مِنْهُم:","",{"fn":"في (أ): «من غير براعة له ...».\nفي (أ) و(ب): «ابتغى».\nقال القاضي عياض في الإلماع: ٢٠٤: «الحد في ترك الشَّيْخ التحديث التغير، وخوف الهرم».\nالمحدّث الفاصل: ٣٥٤ رقم (٢٨٩).\nفي (جـ): «الجعدي».\nفي (جـ): «ومنهم»."}],[1262,"الحسَنُ بنُ عَرَفةَ، وأبو القاسمِ البَغَويُّ، وأبو إسحاقَ الْهُجَيْمِيُّ (١)، والقاضي أبو الطَّيِّبِ الطَّبَريُّ (٢) - رضي الله عنهم - أجمعينَ، واللهُ أعلمُ."],[1263,"ثُمَّ إنَّهُ لا يَنْبَغِي للمُحَدِّثِ أنْ يُحَدِّثَ بِحَضْرَةِ مَنْ هوَ أوْلَى منهُ (٣) بذلكَ. وكانَ (٤) إبراهيمُ والشَّعْبيُّ إذا اجْتَمعا لَمْ يَتَكَلَّمْ إبراهيمُ بشيءٍ (٥). وزادَ بعضُهُمْ فَكَرِهَ الروايةَ ببلَدٍ فيهِ مِنَ المحدِّثينَ مَنْ هوَ أوْلَى منهُ لِسِنِّهِ أو لغيرِ ذَلِكَ. رُوِّيْنا عَنْ يحيى بنِ مَعينٍ، قالَ:"],[1264,"«إذا حدَّثْتُ في بلدٍ فيهِ مثلُ أبي مُسْهِرٍ (٦) فيجبُ لِلِحْيَتِي أنْ تُحْلَقَ» (٧). وعنهُ أيضًا:"],[1265,"«إنَّ الذي يُحَدِّثُ بالبَلْدَةِ وفيها مَنْ هوَ أوْلَى بالتحديثِ منهُ (٨) أحْمَقُ» (٩)."],[1266,"ويَنْبَغِي للمحدِّثِ إذا التُمِسَ منهُ ما يَعْلَمُهُ عندَ غيرِهِ في بَلَدِهِ أوْ غيرِهِ بإسنادٍ أعلى مِنْ إسنادِهِ، أوْ أرْجَحَ مِنْ وَجْهٍ آخَرَ أنْ يُعْلِمَ الطَّالِبَ بهِ ويُرْشِدَهُ إليهِ، فإنَّ الدينَ النصيحةُ. ولاَ يَمْتَنِعُ (١٠) مِنْ تَحْدِيثِ أحَدٍ لِكَوْنِهِ غيرَ صحيحِ النِّيَّةِ فيهِ؛ فإنَّهُ يُرجَى لهُ حُصُولُ النِّيَّةِ مِنْ بَعْدُ. رُوِّيْنا عَنْ مَعْمَرٍ (١١) قالَ كانَ يُقَالُ: «إنَّ الرجلَ لَيَطْلُبُ العِلْمَ لغيرِ اللهِ فَيَأْبَى عليهِ العِلمُ حَتَّى يكونَ للهِ عز وجل» (١).","",{"fn":"انظر قصته في: نكت الزركشي ٣/ ٦٤١، وشرح التبصرة والتذكرة ٢/ ٣٠٩.\nانظر: نكت الزركشي ٣/ ٦٣٨ - ٦٤٢.\nقال الزركشي في نكته ٣/ ٦٤٢: «سُئِل أين ابن المبارك وسفيان بن عيينة حاضر، فقال: نهينا أن نتكلم عِنْدَ أكابرنا، فقلت - القائل هو الزركشي -: إلاَّ بإذنه، وقد بوّب ابن عبد البر بابًا في فتوى الصغير بَيْنَ يدي الكبير بإذنه».\nفي (أ) و(جـ): «كان» بلا واو.\nانظر: الجامع لأخلاق الراوي ١/ ٣٢٠ وفيه زيادة كلمة: «لسنه».\nهو الإمام عبد الأعلى بن مسهر بن عبد الأعلى الدمشقي (ت ٢١٨ هـ)، انظر: طبقات ابن سعد ٧/ ٤٧٣، وتاريخ بغداد ١١/ ٧٢، والسير ١٠/ ٢٢٨.\nالجامع لأخلاق الراوي وآداب السامع (٧٠١).\nبعد هذا في (ع) زيادة: «فهو»، وهي لَمْ ترد في النسخ ولا (م).\nأخرجه الخطيب في الجامع (٧٠٠)، وفي التاريخ ١١/ ٧٤.\nانظر: نكت الزركشي ٣/ ٦٤٢ - ٦٤٥.\nبفتح الميم وإسكان العين، كَمَسْكَن، هو الإمام الحافظ أبو عروة مَعْمَرُ بن راشد الأزْدي البصري ثم اليماني الصَّنعاني، ولد سنة (٩٥ هـ) بالبصرة، وسكن اليمن ومات فيها سنة (١٥٣ هـ). انظر: تهذيب الأسماء واللغات ٢/ ١٠٧، والسير ٧/ ٥، والتاج ١٣/ ١٤٥."}],[1267,"وليكُنْ حريصًا عَلَى نَشْرِهِ مُبْتَغِيًا جَزِيْلَ أجْرِهِ. وقدْ كانَ في السَّلَفِ - رضي الله عنهم - مَنْ"],[1268,"يَتألَّفُ (٢) الناسَ عَلَى حديثِهِ، مِنْهُم: عُرْوةُ بنُ الزبيرِ -رضي الله عنهما- واللهُ أعلمُ (٣)."],[1269,"وليقتَدِ بِمَالِكٍ - رضي الله عنه - فيما أخْبَرَناهُ أبو القاسِمِ الفَرَاويُّ بِنَيْسَابورَ، قالَ: أخْبَرَنا (٤) أبو المعالِي الفارِسِيُّ، قالَ: أخبرنا أبو بكرٍ البَيْهَقِيُّ الحافِظُ، قالَ: أخبرنا أبو عبدِ اللهِ الحافِظُ، قالَ: أخبرني إسماعيلُ بنُ مُحَمَّدِ بنِ الفَضْلِ بنِ مُحَمَّدٍ الشَّعْرَانِيُّ، قالَ: حَدَّثَنا جَدِّي، قالَ: حَدَّثَنا إسماعيلُ بنُ أبي أُوَيْسٍ، قالَ: «كانَ مالكُ بنُ أنسٍ إذا أرادَ أنْ يُحَدِّثَ تَوَضَّأَ (٥)، وجَلَسَ عَلَى صَدْرِ فِراشِهِ وسَرَّحَ لِحْيَتَهُ، وتَمَكَّنَ في جُلُوسِهِ بِوَقارٍ وهَيْبَةٍ، وحدَّثَ»، فقِيلَ لهُ في ذَلِكَ؟ فقالَ: أُحِبُّ أنْ أُعَظِّمَ حديثَ رسُولِ اللهِ - صلى الله عليه وآله وسلم - (٦) ولاَ أُحَدِّثُ إلاَّ عَلَى طَهَارَةٍ مُتَمَكِّنًا. وكانَ يَكْرَهُ أنْ يُحَدِّثَ في الطريقِ، أو هوَ قائِمٌ، أو يَسْتَعْجِلَ. وقالَ: أُحِبُّ أنْ أتَفَهَّمَ ما أُحَدِّثُ بهِ عَنْ رسُولِ اللهِ - صلى الله عليه وآله وسلم -»."],[1270,"ورُوِيَ أيضًا عنهُ أنَّهُ كانَ يَغْتَسِلُ لِذَلِكَ ويَتَبَخَّرُ، ويَتَطَيَّبُ، فإنْ رَفَعَ أحدٌ صَوْتَهُ في مَجْلِسِهِ زَبْرَهُ (٧)، وقالَ: قالَ اللهُ تَعَالَى: ﴿يَا أيُّهَا الَّذِيْنَ آمَنُوا لاَ تَرْفَعُوا أصْواتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ﴾ (٨)، فَمَنْ رَفَعَ صَوتَهُ عِنْدَ حديثِ رسولِ اللهِ - صلى الله عليه وآله وسلم - فكأنَّما رَفَعَ صَوْتَهُ فوقَ صَوتِ رسولِ اللهِ - صلى الله عليه وآله وسلم - (٩).","",{"fn":"أخرجه عبد الرزاق في مصنفه ١١/ ٢٥٦ رقم (٢٠٤٧٥)، والخطيب في جامعه (٧٧٥).\nروى الخطيب في جامعه١/ ٣٤٠ (٧٧٨) عن الزُّهْرِيّ قال، قال: «كان عروة يتألف الناس عَلَى حديثه».\nجملة: «والله أعلم» سقطت من (ع)، وهي من النسخ و(م).\nفي (م): «حَدَّثَنا».\nانظر: نكت الزركشي ٣/ ٦٤٥.\nفي (جـ) بعد هذا زيادة: «بذلك».\nفي (م): «زجره»، والمعنى واحد، فالزبر: الانتهار، يقال: زَبَرَهُ عن الأمر زَبْرًا انتهره، والزَّبر أيضًا: الزَّجْرُ والمنع والنَّهْي، يقال: زَبَرَهُ عن الأمر زَبْرًا: نهاه ومنعه. انظر: اللسان ٤/ ٣١٥، وتاج العروس ١١/ ٣٩٩.\nالحجرات: ٢.\nأخرجه الخطيب في الجامع (٩٦١)، وانظر: تفسير الطبري ٢٦/ ٧٤، والدر المنثور ٧/ ٥٤٧."}],[1271,"ورُوِّيْنا أو بَلَغَنا عَنْ مُحَمَّدِ بنِ أحمدَ بنِ عبدِ اللهِ الفقيهِ (١) أنَّهُ قالَ: «القارئُ لِحَدِيثِ رسولِ اللهِ - صلى الله عليه وآله وسلم - إذا قامَ لأحَدٍ فإنَّهُ تُكْتَبُ عليهِ خَطِيئةٌ». ويُسْتَحَبُّ لهُ مَعَ أهلِ مَجْلِسِهِ ما وَرَدَ عَنْ حَبِيْبِ بنِ أبي ثابِتٍ أنَّهُ قالَ: «إنَّ مِنَ السُّنَّةِ إذا حَدَّثَ الرجلُ القومَ أنْ يُقْبِلَ عَلَيْهِمْ جَمِيعًا» (٢)، واللهُ أعلمُ."],[1272,"ولاَ يَسْرُدُ الحديثَ سَرْدًا يَمْنَعُ السامِعَ مِنْ إدْراكِ بَعْضِهِ. وليَفْتَتِحْ مَجْلِسَهُ ولْيخَتَتِمْهُ بذِكْرٍ ودُعاءٍ يَليقَ بالحالِ. ومِنْ أبْلَغِ (٣) ما يَفْتَتِحُهُ بهِ أنْ يقُولَ: الحمدُ للهِ رَبِّ العالمينَ أكملُ الحمدِ عَلَى كُلِّ حالٍ، والصلاةُ والسلامُ الأتَمَّانِ عَلَى سَيِّدِ المرسلينَ، كُلَّما ذَكرَهُ (٤) الذاكِرُونَ، وكُلَّما غَفَلَ عَنْ ذِكْرِهِ (٥) الغافِلُونَ، اللَّهُمَّ صَلِّ عليهِ وعلى آلِهِ وسائِرِ النَّبيِّينَ وآلِ كُلٍّ، وسائِرِ الصَّالِحينَ، نِهايَةَ ما يَنْبَغِي أنْ يَسْأَلَهُ السَّائِلُونَ."],[1273,"ويُسْتَحَبُّ لِلْمُحَدِّثِ العارِفِ عَقْدُ مَجْلِسٍ لأملاءِ (٦) الحديثِ، فإنَّهُ مِنْ أعلى مَراتِبِ الرَّاوِينَ (٧)، والسماعُ فيهِ مِنْ أحْسَنِ وُجُوهِ التَّحَمُّلِ وأقْواهَا، ولْيَتَّخِذْ مُسْتَمْلِيًا يُبَلِّغُ عنهُ إذا كَثُرَ الجمعُ، فذلكَ دَأْبُ أكابِرِ المحدِّثِيْنَ المتَصَدِّيْنَ لِمِثْلِ ذَلِكَ. ومِمَّنْ رُوِيَ عنهُ ذَلِكَ: مالِكٌ، وشُعْبَةُ، ووكِيْعٌ، وأبو عاصِمٍ، ويَزِيدُ بنُ هارونَ في عددٍ كثيرٍ مِنَ الأعلامِ السَّالِفينَ (١). وليَكُنْ مُسْتَمْلِيهِ مُحَصِّلًا مُتَيَقِّظًا، كَيْلا يَقَعَ في مِثْلِ ما رُوِّينا أنَّ يَزِيدَ بنَ هارونَ (٢) سُئِلَ عَنْ حديثٍ، فقالَ: «حَدَّثَنا بهِ عِدَّةٌ، فصاحَ بهِ مُسْتَمْلِيهِ: يا أبا خالدٍ! عِدَّةُ ابنُ مَنْ؟ فقالَ لهُ: عِدَّةُ ابنُ فَقَدْتُكَ!» (٣).","",{"fn":"هو الإمام أبو زيد المروزي، راوي صحيح البخاري، عن الفربري، توفي سنة (٣٧١ هـ). انظر: السير: ١٦/ ٣١٣.\nأخرجه الخطيب في الجامع (٩٨١).\nقال الزركشي مُعَقِّبًا عَلَى هذا الكلام: «اعلم أن المأثور في التحميد والصلاة أفضل من هذا، وقد ورد في التحميد سنن مشهورة فينبغي اتِّباعها، وكذلك تتبع السنة الصحيحة في الصلاة عَلَى النبي - صلى الله عليه وآله وسلم -، وقد نبّه عَلَى هذا النووي - رَحِمَهُ اللهُ تَعَالَى - ...». نكت الزركشي ٣/ ٦٤٦، وانظر: روضة الطالبين ١١/ ٦٥ - ٦٦.\nفي (جـ): «ذكرك»، وفي (م): «ذكر».\nفي (جـ): «ذكرك».\nانظر: نكت الزركشي ٣/ ٦٤٦ - ٦٤٩.\nفي (جـ): «الراويين»."}],[1274,"وليَسْتَمْلِ عَلَى موضِعٍ مُرْتَفَعٍ (٤) مِنْ كُرْسِيٍّ أو نَحْوِهِ، فإنْ لَمْ يجدْ اسْتَمْلَى قائِمًا. وعليهِ أنْ يَتْبَعَ لَفْظَ المحدِّثِ فَيُؤَدِّيَهُ عَلَى وجْهِهِ (٥) مِنْ غيرِ خِلاَفٍ. والفائِدَةُ في اسْتِمْلاءِ الْمُسْتَمْلِي، توصُّلُ مَنْ يَسْمَعُ لَفْظَ الْمُمْلِي عَلَى بُعْدٍ منهُ إلى تَفَهُّمِهِ وتَحَقُّقِهِ بإبْلاَغِ الْمُسْتَمْلِي. وأمَّا مَنْ لَمْ يَسْمَعْ إلاَّ لَفْظَ الْمُسْتَمْلِي، فليسَ يستفيدُ بذلكَ جَوازُ روايتِهِ لذلكَ عَنِ الممْلِي مُطْلَقًا مِنْ غيرِ بيانٍ للحالِ فيهِ، وفي هذا كلامٌ قدْ تَقَدَّمَ في النوعِ الرابِعِ والعِشْرينَ."],[1275,"ويُسْتَحبُّ افْتِتاحُ المجلسِ بقراءةِ قارئٍ لشيءٍ مِنَ القُرآنِ العظيمِ (٦)، فإذا فَرَغَ اسْتَنْصَتَ الْمُسْتَملِي أهلَ المجلِسِ (٧) إنْ كانَ فيهِ لَغْطٌ (٨) ثُمَّ يُبَسْمِلُ، ويَحْمدُ اللهَ تَبَارَكَ وتَعَالَى، ويُصَلِّي (١) عَلَى رسولِهِ (٢) ويَتَحَرَّى الأبْلَغَ في ذَلِكَ ثُمَّ يقبلُ عَلَى المحدِّثِ ويَقُولُ: مَنْ ذَكَرْتَ أو ما ذَكَرْتَ رَحِمَكَ (٣) اللهُ أو غَفَرَ اللهُ لك أو نحوَ ذَلِكَ. وكُلَّما انتَهَى إلى ذِكْرِ النَّبيِّ - صلى الله عليه وآله وسلم - صَلَّى عليهِ. وذَكَرَ الخطيبُ أنَّهُ يَرْفَعُ صَوتَهُ بذلكَ (٤)، وإذا انتَهَى إلى ذِكْرِ الصحابيِّ قالَ: - رضي الله عنه -. ويحسُنُ بالمحدِّثِ الثَّناءُ عَلَى شيخِهِ في حالةِ الروايةِ عنهُ بما هو أهلٌ لهُ فقدْ فَعَلَ ذَلِكَ غيرُ واحدٍ مِنَ السَّلَفِ والعلماءِ كما رُوِيَ عَنْ عطاءِ بنِ أبي رَباحٍ أنَّهُ كانَ إذا حدَّثَ عنِ ابنِ عَبَّاسٍ - رضي الله عنهما - قالَ: «حَدَّثَني البَحْرُ» (٥). وعنْ وكيعٍ أنَّهُ قالَ: «حَدَّثَنا سُفيانُ أميرُ المؤمنينَ في الحديثِ» (٦). وأهمُّ مِنْ ذَلِكَ الدعاءُ لهُ عِنْدَ ذِكْرِهِ، فلا يَغْفَلَنَّ عنهُ.","",{"fn":"الجامع لأخلاق الراوي ٢/ ٥٥ - ٥٦.\nانظر: نكت الزركشي ٣/ ٦٤٩.\nأخرجه الخطيب في الجامع ٢/ ٦٧ (١٢٠١)، وابن السمعاني في أدب الإملاء: ٩٠.\nقيّد ابن السمعاني ذَلِكَ بما إذا كثر عدد من يحضر السماع، وكانوا بحيث لا يرون وجه المستملي، فيستحب أن يجلس عَلَى منبر أو غيره حَتَّى ترى الجماعة وجهه ويبلغهم صوته. وانظر: أدب الإملاء: ٥٠، ونكت الزركشي ٣/ ٦٥٠.\nقال الزركشي: «عبارة الخطيب: ويستحب له ألا يخالف، وكذا قال ابن السمعاني في أدب الإملاء، ثم صرّح بالوجوب فقال: ويستحب للمستملي ألا يخالف لفظ المملي في التبليغ عنه، بل يلزمه ذَلِكَ، خاصة إذا كان الراوي من أهل الدراية والمعرفة بأحكام الرواية». نكت الزركشي ٣/ ٦٥٠، وانظر: الجامع لأخلاق الراوي ٢/ ٦٧، وأدب الإملاء: ١٠٥.\nانظر: أدب الإملاء: ٩٨، ونكت الزركشي ٣/ ٦٥٠ - ٦٥١، وشرح التبصرة ٢/ ٣١٧.\nانظر: نكت الزركشي ٣/ ٦٥١.\nجاء في حاشية نسخة (جـ) مقالة نصها: «لفظ: بالتسكين أفصح، وبالتحريك أشهر، وكل كلمة عَلَى ثلاثة أحرف، ووسطها حرف حلق؛ فإنه يجوز فيه التسكين والفتح إلا في النحو، العلم عَلَى علم العربية، فلا يجوز إلا بالتسكين»، وبنحوها في حاشية (م). والمراد باللفظ: الأصوات المبهمة المختلطة، والجَلَبة لا تُفْهم. انظر اللسان ٧/ ٣٩١، وتاج العروس٢٠/ ٧٤."}],[1276,"ولا بأسَ بذِكْرِ مَنْ يَرْوِي عنهُ بما يُعْرَفُ بهِ:"],[1277,"- مِنْ لَقَبٍ: كَغُنْدَرٍ لَقَبُ مُحَمَّدِ بنِ جَعْفَرٍ - صاحِبِ شُعْبَةَ -، ولُوَيْنٌ (٧) لَقَبُ مُحَمَّدِ بنِ سُليمانَ المِصِّيْصِيِّ (٨)."],[1278,"- أو نِسْبةٍ إلى أُمٍّ عُرِفَ بها: كَيَعْلَى بنِ مُنْيَةَ (٩) الصحابيِّ، وهوَ ابنُ أُمَيَّةَ، ومُنْيَةُ: أُمُّهُ، وقيلَ: جَدَّتُهُ أُمُّ أبيهِ.","",{"fn":"ينظر: الجامع ٢/ ٦٩، وأدب الإملاء: ٩٨.\nفي (ع): «رسول الله».\nانظر: نكت الزركشي ٣/ ٦٥٢ - ٦٥٣.\nالجامع لأخلاق الراوي ٢/ ١٠٣، وكذا قال السمعاني في أدب الإملاء: ٦٣.\nأخرجه الخطيب في الجامع لأخلاق الراوي وآداب السامع (١٢٤٥).\nأخرجه الخطيب في الجامع لأخلاق الراوي وآداب السامع (١٢٥٠).\nلُوَيْن: بالتصغير. التقريب (٥٩٢٥). وانظر: سبب هذه التسمية في الجامع ٢/ ٧٥، والسير ١١/ ٥٠١، ونكت الزركشي ٣/ ٦٥٤.\nبكسر الميم - وقيل: بفتحها - وكسر الصاد وتشديدها، وياء ساكنة، وبعدها صاد ثانية مهملة، وقيل: بتخفيف الصادين، هذه النسبة إلى بلدة كبيرة عَلَى ساحل بحر الشام، يقال لها: المصيصة. انظر: الأنساب ٥/ ٢٠١، ووفيات الأعيان ١/ ١٢٧، ومراصد الاطلاع ٣/ ١٢٨٠، والتاج ١٨/ ١٦١. وقال الزركشي في نكته ٣/ ٦٥٥: «والمصيصي بالتشديد والتخفيف، فمن فتح الميم خفّف الصاد».\nبضم الميم وسكون النون بعدها تحتانية مفتوحة. التقريب (٧٨٣٩)، وانظر: نكت الزركشي ٣/ ٦٥٥."}],[1279,"- أو وَصْفٍ بِصَفَةِ نَقْصٍ في جَسَدِهِ عُرِفَ بها: كَسُليمانَ الأعْمَشِ، وعاصِمٍ الأحْوَلِ، إلاَّ ما يكرهُهُ مِنْ ذَلِكَ، كما في إسماعيلَ بنِ إبراهيمَ المعروفِ بابنِ عُلَيَّةَ وهيَ أُمُّهُ، وقيلَ: أمُّ أُمِّهِ."],[1280,"رُوِّيْنا عَنْ يحيى بنِ مَعِيْنٍ أنَّهُ كانَ يَقُولُ: «حَدَّثَنا إسْماعِيلُ بنُ عُلَيَّةَ، فَنَهاهُ أحمدُ بنُ حَنْبَلٍ، وقالَ: قُلْ: إسْماعيلُ بنُ إبراهيمَ، فإنَّهُ بَلَغَنِي أنَّهُ كانَ يَكرهُ أنْ يُنْسِبَ إلى أُمِّهِ، فقالَ: قدْ قَبِلْنا مِنْكَ يا مُعَلِّمَ الخيْرِ» (١)."],[1281,"وقَدِ اسْتُحِبَّ للمُمْلِي أنْ يَجْمَعَ في إمْلائِهِ بينَ الروايةِ عَنْ جماعَةٍ مِنْ شُيُوخِهِ مُقَدِّمًا للأعْلَى إسْنادًا أو الأولى مِن وَجْهٍ آخَرَ. ويُمْلي عَنْ كُلِّ شَيْخٍ مِنْهُم حديثًا واحدًا ويَختارُ ما علا سَنَدُهُ وقَصُرَ مَتْنُهُ فإنَّهُ أحسَنُ وألْيَقُ، ويَنْتَقِي ما يمليهِ ويَتَحَرَّى المستفادَ منهُ، ويُنَبِّهُ عَلَى ما فيهِ مِنْ فائِدَةٍ وعُلُوٍّ وفَضيلةٍ، ويَتَجَنَّبُ ما لاَ تَحْتَمِلُهُ عُقُولُ الحاضِرِينَ، وما يُخْشَى فيهِ مِنْ دُخُولِ الوَهَمِ عليْهِمْ في فَهْمِهِ. وكانَ مِنْ عادةِ غيرِ واحدٍ مِنَ المذكُورينَ خَتْمُ الإمْلاَءِ بشيءٍ مِنَ الحِكَاياتِ والنَّوادِرِ والإنشاداتِ بأسَانِيدِها وذَلِكَ حسَنٌ. (٢)"],[1282,"وإذا قَصَّرَ المحدِّثُ عَنْ تَخْريجِ ما يُمْليهِ فاستعانَ ببعضِ حُفَّاظِ وَقْتِهِ فَخَرَّجَ لهُ فلا بأسَ بذلكَ. قالَ الخطيبُ: «كانَ جماعةٌ مِنْ شُيوخِنا يفعلونَ ذَلِكَ» (٣). وإذا نَجِزَ (٤) الإملاءُ فلا غِنًى (٥) عَنْ مُقَابلتِهِ وإتْقانِهِ وإصْلاحِ (٦) ما فَسَدَ منهُ بِزَيْغِ القَلَمِ وطُغْيانِهِ.","",{"fn":"الجامع لأخلاق الراوي وآداب السامع (١٢٣٧).\nوقد عقد الخطيب في جامعه ٢/ ١٢٩ - ١٣١ بابًا سمّاه «ختم المجلس بالحكايات ومستحب النوادر والإنشادات» ساق فيه عددًا من الآثار، وانظر لزامًا: محاسن الاصطلاح: ٣٦٦، ونكت الزركشي ٣/ ٦٥٧.\nالجامع لأخلاق الراوي ٢/ ٨٨.\nفي نسخة (ب) حاشية نصها: «قال المصنف - رَحمه الله تَعالى -: نجز -بكسر الجيم- بمعنى انقضى، فأما بالفتح كما تقول العامة فمعناه حضر، وليس هذا موضعه»، وكذا في حاشية نسخة (جـ) و(م). وانظر: الصحاح ٣/ ٨٩٧، واللسان ٥/ ٤١٣ ونكت الزركشي ٣/ ٦٦٠، والتقييد: ٢٥٠.\nفي (أ) و(ع) والتقييد: «غناء».\nفي (م): «إصلاح» بلا واو."}],[1283,"هذهِ عُيُونٌ مِنْ آدابِ المحدِّثِ اجْتَزَأنا بها مُعرضينَ عَنِ التَّطويلِ بما ليسَ مِنْ مهمَّاتِها أو هوَ ظاهِرٌ ليسَ مِنْ مشْتَبهاتِها، واللهُ الموفِّقُ (١)، وهوَ أعلمُ."],[1284,"النوع الثامن والعشرون معرفة آداب طالب الحديث"],[1285,"(٢)"],[1286,"وقَدِ انْدَرَجَ طَرَفٌ منهُ في ضِمْنِ ما تَقَدَّمَ."],[1287,"فأوَّلُ ما عليهِ: تحقيقُ الإخْلاَصِ، والحَذَرُ مِنْ أنْ يَتَّخِذَهُ وُصْلَةً إلى شيءٍ مِنَ الأغراضِ الدُّنيويَّةِ. رُوِّيْنا عَنْ حَمَّادِ بنِ سَلَمَةَ - رضي الله عنه - أنَّهُ قالَ: «مَنْ طَلَبَ الحديثَ لغيرِ اللهِ مُكِرَ بهِ» (٣)، وروِّيْنا عَنْ سُفْيانَ الثَّورِيِّ - رضي الله عنه - قالَ (٤): «ما أعلمُ عَمَلًا هُوَ أفضلُ مِنْ طَلَبِ الحديثِ لِمَنْ أرادَ اللهَ بهِ» (٥). ورُوِّيْنا نحْوَهُ عِنِ ابنِ المبارَكِ - رضي الله عنه - ومِنْ أقربِ الوجوهِ في إصلاحِ النِّيَّةِ فيهِ ما رُوِّيْنا عَنْ أبي عَمْرٍو إسْماعِيلَ بنِ نُجَيْدٍ أنَّهُ سَأَلَ أبا جَعفَرٍ أحمدَ بنِ حَمْدانَ، وكانا عَبْدَيْنِ صالِحَيْنِ، فقالَ لهُ: «بأيِّ نِيَّةٍ أكْتُبُ الحديثَ؟ فقالَ: ألَسْتُمْ تَرْوونَ (٦) أنَّ عِنْدَ ذِكْرِ الصالِحِينَ تَنْزِلُ الرَّحْمَةُ؟ قالَ: نَعَمْ. قالَ: فرسُول الله - صلى الله عليه وآله وسلم - رأسُ الصَّالِحينَ».","",{"fn":"بعد هذا في (ع): «المعين»، ولم ترد في النسخ ولا (م).\nانظر في ذلك: الإلماع: ٤٥ وما بعدها، والإرشاد ١/ ٥٢١ ٥٢٨، والتقريب: ١٤٦ - ١٤٩، والاقتراح: ٢٨٠ - ٢٨٤، والمنهل الروي: ١٠٨، واختصار علوم الحديث: ١٥٧ - ١٥٨، والشذا الفياح: ١/ ٤٠٠ - ٤١٨، والمقنع ١/ ٤٠٧ - ٤١٨، وشرح التبصرة ٢/ ٣٣٢، ونزهة النظر: ٢٠٤، وفتح المغيث ٢/ ٣١١ - ٣٤٦، والتدريب ٢/ ١٤٠ - ١٥٨، وفتح الباقي ٢/ ٢٢٣، وقواعد التحديث: ٢٣٣ - ٢٣٦.\nأخرجه أبو نعيم في الحلية ٦/ ٢٥١، وابن عبد البر في الجامع ١/ ١٩١، والخطيب في الجامع (١٩).\nأخرجه ابن عبد البر في جامع بيان العلم وفضله ١/ ٥٩، والخطيب في الجامع (١٤)، وفي شرف أصحاب الحديث: ٨١ بمعناه.\nانظر: نكت الزركشي ٣/ ٦٦١ - ٦٦٣.\nفي الشذا والتقييد: «ترون أنَّ عِنْدَ»."}],[1288,"وليسْأَلِ اللهَ تبارك وتعالى التَّيْسِيْرَ والتَّأييدَ والتَّوْفيقَ والتَّسْديدَ، وليَأْخَذْ نَفْسَهُ بالأخلاقِ الزَّكِيَّةِ والآدابِ الرْضِيَّةِ (١). فَقَدْ رُوِّيْنا عَنْ أبي عاصِمٍ النَّبيلِ قالَ: «مَنْ طَلَبَ هذا الحديثَ فقدْ طلبَ أعلى أمورِ الدِّينِ، فيجبُ أنْ يكونَ خَيْرُ النَّاسِ» (٢)."],[1289,"وفي السِّنِّ الذي يُسْتَحَبُّ فيهِ الابتداءُ بسماعِ الحديثِ وبِكِتْبتِهِ (٣) اخْتِلافٌ سَبَقَ بيانُهُ في أوَّلِ النَّوعِ الرَّابِعِ والعِشْرِينَ. وإذا أخذَ فيهِ فَلْيُشَمِّرْ عَنْ ساقِ جُهْدِهِ واجْتِهادِهِ، ويَبْدأْ بالسَّماعِ مِنْ أسْنَدِ شُيوخِ (٤) مِصْرِهِ ومِنَ الأوْلَى فَالأَوْلَى مِنْ حيثُ العِلْمُ أو الشُّهْرَةُ أو الشَّرَفُ أوْ غيرُ ذَلِكَ. وإذا فَرَغَ مِنْ سَماعِ العَوالِي والمهمَّاتِ التي ببلَدِهِ فَلْيَرْحَلْ إلى غيرِهِ."],[1290,"رُوِّيْنا عَنْ يَحْيَى بنِ مَعِيْنٍ أنَّهُ قالَ: «أربَعَةٌ لاَ تُؤْنِسْ مِنْهُم رُشْدًا: حارسُ الدَّرْبِ، ومُنادِي القاضي، وابنُ المحدِّثِ، ورجلٌ يَكْتُبُ في بلدِهِ ولا يَرْحَلُ في طَلَبِ الحديثِ» (٥). ورُوِّيْنا عَنْ أحمدَ بنِ حَنْبَلٍ - رضي الله عنه - أنَّهُ قيلَ لهُ: «أيَرْحَلُ الرجلُ في طَلَبِ العِلُوِّ؟ فقالَ: بَلَى واللهُ شديدًا، لقَدْ كانَ علقَمةُ والأسْودُ يَبْلُغُهُما الحديثُ عَنْ عُمَرَ - رضي الله عنه - فلا يُقْنِعُهُما حَتَّى يَخْرُجا إلى عُمَرَ فيَسْمعانَهُ (٦) منهُ»، واللهُ أعلمُ."],[1291,"وعنْ إبراهيمَ بنِ أدْهَمَ - رضي الله عنه - أنَّهُ قالَ: «إنَّ اللهَ تَعَالَى يَدْفَعُ البلاءَ عَنْ هذهِ الأُمَّةِ برحلةِ أصْحابِ الحديثِ» (٧)."],[1292,"ولا يَحْمِلَنَّهُ الحرصُ والشَّرَهُ عَلَى التَّسَاهُلِ في السماعِ والتَّحَمُّلِ والإخلاَلِ بما يُشْتَرَطُ عليهِ (٨) في ذَلِكَ عَلَى ما تَقَدَّمَ شَرْحُهُ.","",{"fn":"في (ع) والتقييد: «المرضية».\nأخرجه الخطيب في الجامع (٦)\nفي (جـ) و(م) والشذا: «بكتبه».\nانظر: نكت الزركشي ٣/ ٦٦٣ - ٦٦٤.\nأخرجه الحاكم في معرفة علوم الحديث: ٩، والخطيب في الجامع (١٦٨٥)، وفي الرحلة، له: ٤٧.\nهكذا في جميع النسخ.\nأسنده الخطيب في الرحلة: ٤٧، وفيه: «يرفع» مكان: «يدفع».\nانظر: الجامع ٢/ ٢٤٥ (٧٤٠)."}],[1293,"ولْيَسْتَعْمِلْ ما يَسْمَعُهُ مِنَ الأحَادِيثِ الوارِدَةِ بالصَّلاةِ والتَّسْبيحِ وغيرِهِما مِنَ الأعمالِ الصَّالِحَةِ فذَلِكَ زَكاةُ الحديثِ عَلَى ما رُوِّيْناهُ (١) عَنْ العَبْدِ الصالِحِ بِشْرِ بنِ الحارِثِ"],[1294,"الحافِي (٢) - رضي الله عنه -، ورُوِّيْنا عنهُ أيضًا أنَّهُ قالَ: «يا أصحابَ الحديثِ! أدُّوا زكاةَ هذا الحديثِ، اعْمَلُوا مِنْ كُلِّ مِئَتَي حديثٍ بِخَمْسةِ أحاديثَ» (٣). ورُوِّيْنا عَنْ عَمْرِو بنِ قَيْسٍ الْمُلائِيِّ (٤) - رضي الله عنه - قالَ: إذا بَلَغَكَ شيءٌ مِنَ الخيرِ فاعْمَلْ بهِ - ولوْ مَرَّةً - تَكُنْ مِنْ أهلِهِ» (٥). ورُوِّيْنا عَنْ وكِيعٍ، قالَ: «إذا أردْتَ أنْ تَحفظَ الحديثَ فاعْمَلْ بهِ» (٦). وَلْيُعَظِّمْ شَيخَهُ ومَنْ يَسْمَعُ (٧) منهُ، فذَلِكَ مِنْ إجْلالِ الحديثِ والعِلْمِ، ولاَ يُثْقِلُ عليهِ ولاَ يُطَوِّلُ بحيثُ يُضْجِرُهُ، فإنَّهُ يُخْشَى عَلَى فاعِلِ ذَلِكَ أنْ يُحْرَمَ الانْتِفاعَ. وقَدْ رُوِّيْنا عَنِ الزُّهْرِيِّ أنَّهُ قالَ: «إذا طالَ المجْلِسُ، كانَ لِلشَّيْطانِ فيهِ نَصِيبٌ» (٨)."],[1295,"ومَنْ ظَفِرَ مِنَ الطَّلَبةِ بِسَماعِ شَيْخٍ فَكَتَمَهُ غيرَهُ لِيَنْفردَ بهِ عَنْهُم، كانَ جَدِيْرًا بأنْ لا يَنْتَفِعَ بهِ، وذَلِكَ مِنَ اللُّؤْمِ الذي يَقَعُ فيهِ جَهَلَةُ الطَّلَبَةِ الوُضَعاءِ. ومِنْ أوَّلِ فائِدَةِ طَلَبِ الحديثِ الإفادةُ. رُوِّيْنا عَنْ مالِكٍ - رضي الله عنه - أنَّهُ قالَ (٩): «مِنْ بَرَكَةِ الحديثِ إفادَةُ بَعضِهِمْ بَعْضًا» (١٠). ورُوِّيْنا عَنْ إسْحاقَ بنِ إبراهِيمَ بنِ راهَوَيْهِ أنَّهُ قالَ لبعضِ مَنْ سَمِعَ منهُ في جماعَةٍ: «انْسَخْ مِنْ كِتابِهِم ما قدْ قَرَأْتُ، فقالَ: إنَّهُمْ لا يُمَكِّنُونَني، قالَ إذَنْ واللهِ","",{"fn":"في (ع): «روينا»، وما أثبتناه من النسخ و(م).\nهو الإمام العالم، والعبد الصالح، أبو نصر بشر بن الحارث بن عبد الرحمان المروزي المشهور بـ «بشر الحافي»، كَانَ من كبار الصالحين والأتقياء والورعين، ولد سنة (١٥٠ هـ)، وقيل: (١٥٢ هـ)، وتوفي سنة (٢٢٧ هـ). تاريخ بغداد ٧/ ٦٩، وسير أعلام النبلاء ١٠/ ٤٧١، وتهذيب التهذيب ١/ ٤٤٤.\nالجامع لأخلاق الراوي ١/ ١٤٤ رقم (١٨١)، وأدب الإملاء: ١١٠.\nبضم الميم وتخفيف اللام والمد. التقريب (٥١٠٠)، وانظر: الأنساب ٥/ ٣١٨.\nأخرجه أبو نعيم في الحلية ٥/ ١٠٢، والخطيب في الجامع (١٨٢).\nأخرجه الخطيب في الجامع (١٧٨٨) و(١٧٨٩).\nفي (جـ): «سَمِعَ».\nأسنده الخطيب في الجامع (١٣٨٥)، وانظر: أدب الإملاء: ٦٨.\nانظر: نكت الزركشي ٣/ ٦٦٤.\nانظر: الجامع للخطيب ٢/ ١٥٠."}],[1296,"لاَ يُفْلِحُونَ (١)، قدْ رأيْنا أقْوامًا مَنَعُوا هذا السَّماعَ فواللهِ ما أفْلَحُوا ولا أنْجَحُوا»."],[1297,"قُلْتُ: وقَدْ رأيْنا نحنُ أقوامًا مَنَعُوا السَّماعَ فما أفْلَحُوا ولا أنْجَحُوا، ونَسْأَلُ اللهَ العافيةَ، واللهُ أعلمُ."],[1298,"ولاَ يَكُنْ مِمَّنْ يَمْنَعُهُ الحياءُ أو الكِبَرُ عَنْ كَثِيرٍ مِنْ الطَلَبِ. وقدْ رُوِّيْنا (٢) عَنْ مُجَاهِدٍ - رضي الله عنه - أنَّهُ قالَ: «لا يَتَعَلَّمْ مُسْتَحِيٍ (٣) ولا مُسْتَكْبِرٌ»."],[1299,"ورُوِّيْنا عَنْ عُمَرَ بنِ الخطَّابِ وابنِهِ - رضي الله عنهما - أنَّهُما قالا: «مَنْ رَقَّ وَجْهُهُ رَقَّ عِلْمُهُ» (٤). ولا يأْنَفُ مِنْ أنْ يَكْتُبَ عَمَّنْ (٥) دُونَهُ (٦) ما يَسْتَفِيدُهُ منهُ. رُوِّيْنا عَنْ وكيعِ بنِ الجرَّاحِ - رضي الله عنه - أنَّهُ قالَ: «لا يَنْبُلُ الرجُلُ مِنْ أصحابِ الحديثِ حَتَّى يَكْتُبَ عَمَّنْ هوَ فَوْقَهُ وعَمَّنْ هوَ مِثْلُهُ، وعَمَّنْ هوَ دُونَهُ» (٧)، وليسَ بِمُوَفَّقٍ مِنْ ضَيَّعَ شيئًا مِنْ وَقْتِهِ في الاسْتِكْثارِ مِنَ الشُّيُوخِ لِمُجَرَّدِ اسمِ الكَثْرَةِ وصِيْتِها. وليسَ مِنْ ذَلِكَ قَوْلُ أبي حاتِمٍ الرَّازِيِّ: «إذا كَتَبْتَ فَقَمِّشْ (٨)، وإذا حَدَّثْتَ فَفَتِّشْ» (٩).","",{"fn":"في (أ): «لا يفلحون أبدًا».\nصحيح البخاري ١/ ٤٤ عقيب (١٢٩) مجزومًا بهِ. قال الحافظ: «وصله أبو نعيم في الحلية من طريق علي بن المديني، عن ابن عيينة، عن منصور، عنه، وهو إسناد صحيح على شرط البخاري» (الفتح عقيب ١٣٠). قلنا: وهو في سنن الدرامي (٥٥٧)، وحلية الأولياء ٣/ ٢٨٧، والفقيه والمتفقه ٢/ ١٤٤. والمدخل للبيهقي (٤١٠).\nفي (م): «لا يَتَعَلَّمْ العِلْمَ مُسْتَحِيٍ ولا مُسْتَكْبِرٌ».\nأسنده إليه الدارمي ١/ ١٣٧ رقم (٥٥٦)، والبيهقي في المدخل (٤٠٨). وتفسير قول بعضهم: «من رق وجهه عِنْدَ السؤال رق علمه عِنْدَ الرجال»، ومنه قول علي: «قرنت الهيبة بالخيبة والحياء بالحرمان». نكت الزركشي ٣/ ٦٦٦.\nفي (أ): «عمن هو».\nانظر: نكت الزركشي ٣/ ٦٦٦ - ٦٦٧.\nأخرجه الخطيب في الجامع (١٦٥٥).\nالقَمْش: جمع الشيء من هاهنا وهاهنا، وكذلك التقميش. انظر: الصحاح ٣/ ١٠١٦، وتاج العروس ١٧/ ٣٤٠.\nأخرجه الخطيب في الجامع (١٦٧٠)."}],[1300,"وَلْيَكْتُبْ وَلْيَسْمَعْ ما يَقَعُ إليهِ مِنْ كِتابٍ أوْ جُزْءٍ عَلَى التمامِ، ولاَ يَنْتَخِبْ، فقدْ قالَ ابنُ المبارَكِ - رضي الله عنه -: «ما انْتَخَبْتُ عَلَى عالِمٍ قَطُّ إلاَّ نَدِمْتُ» (١)."],[1301,"ورُوِّيْنا عنهُ أنَّهُ قالَ: «لا يُنْتَخَبُ عَلَى عالِمٍ إلاَّ بِذَنْبٍ». ورُوِّيْنا أو بَلَغَنا عَنْ يَحْيَى بنِ مَعِينٍ أنَّهُ قالَ: «سَيَنْدَمُ المنْتَخِبُ في الحديثِ حينَ لا تَنْفَعُهُ النَّدامةُ» (٢)."],[1302,"فإنْ ضاقَتْ بهِ الحالُ عَنِ الاستِيعابِ، وأُحْوِجَ إلى الانتِقَاءِ والانْتِخابِ تَوَلَّى ذَلِكَ بنفسِهِ إنْ كانَ أهْلًا مُمَيِّزًا عارِفًا بما يَصْلُحُ للانْتِقاءِ والاخْتِيارِ. وإنْ كانَ قاصِرًا عَنْ ذَلِكَ اسْتَعانَ ببعْضِ الْحُفَّاظِ لِيَنْتَخِبَ لهُ. وقدْ كانَ جماعَةٌ مِنَ الْحُفَّاظِ مُتَصَدِّيْنَ للانْتِقاءِ عَلَى الشُّيُوخِ والطَّلَبَةِ تَسْمَعُ وتَكْتُبُ بانْتِخابِهِمْ، مِنْهُم: إبراهيمُ بنُ أرُومَةَ (٣) الأصْبَهانِيُّ، وأبو عبدِ اللهِ الْحُسَيْنُ بنُ مُحَمَّدٍ المعروفُ بِعُبَيْدٍ العِجْلِ (٤)، وأبو الحسَنِ الدَّارقطْنيُّ، وأبو بكرٍ الجِعَابِيُّ (٥) في آخَرِينَ. وكانتْ العَادَةُ جارِيَةً برَسْمِ الحَافِظِ علامةً في أصْلِ الشَّيْخِ عَلَى ما يَنْتَخِبُهُ، فكانَ النُّعَيْمِيُّ (١) أبو الحسَنِ يُعَلَّمُ بِصَادٍ مَمْدُودَةٍ، وأبو مُحَمَّدٍ الخلاَّلُ (٢) بِطاءٍ ممدودةٍ، وأبو الفَضْل الفَلَكيُّ (٣) بصورةِ همزتينِ، وكُلُّهُم يُعلِّمُ بِحِبْرٍ في الحاشيةِ اليُمنى من الورقةِ، وَعَلَّمَ الدارقطنيُّ في الحاشيةِ اليُسرى بِخَطٍ عريضٍ بالحمرةِ. وكانَ أبو القاسمِ اللالكائيُّ (٤) الحافظُ يُعلِّمُ بخطٍّ صغيرٍ بالحُمرةِ عَلَى أوَّلِ إسنادِ الحديثِ (٥) ولا حَجْرَ في ذلكَ ولِكُلٍ الخيارُ.","",{"fn":"أسنده الخطيب في الجامع (١٤٧١).\nانظر: الجامع ٢/ ١٨٧.\nفي (أ) و(ب) و(م) و(ع) والتقييد والشذا الفياح ومطبوع الجامع ٢/ ١٥٧: «أرمة». وكذا في (جـ) وكتب فوقها: «أورمة»، ولكن في مصادر ترجمته: «أورمة». انظر: الجرح والتعديل ٢/ ٨٨، وتاريخ بغداد ٦/ ٤٢، وتذكرة الحفاظ ٢/ ٦٢٨، والسير ١٣/ ١٤٥، وذكر من يعتمد قوله في الجرح والتعديل للذهبي: ١٨٠، وطبقات الحفاظ: ٢٨١، وشذرات الذهب ٢/ ١٥١، وانظر: تعليقنا عَلَى شرح التبصرة ٢/ ٣٤٦.\nكلمة «العجل» نعت لعبيد، وليس مضافًا إليه، فهو لقب له عَلَى النعت لا الإضافة كما ضبطه ابن الصلاح في إملائه عَلَى مقدمته. انظر: النوع الثاني والخمسين: ٥٢٩ هامش (١) طبعة بنت الشاطئ، وذكر من يعتمد قوله: ١٨٧ مع تعليق محققه.\nفي (م) و(ع) والتقييد: «الجعاني» بالنون، وهو خلاف لما جاء في النسخ الخطية والشذا، وما في النسخ الخطية موافق لما جاء في مصادر ترجمته. انظر: تاريخ بغداد ٣/ ٢٦، وتذكرة الحفاظ ٣/ ٩٢٥، والسير ١٦/ ٨٨، وميزان الاعتدال ٣/ ٦٧٠، وشذرات الذهب ٣/ ١٧، وتاج العروس ٢/ ١٦٤. قال في الأنساب ٢/ ٩١: «بكسر الجيم وفتح العين المهملة، وفي آخرها الباء الموحدة»، فقطعت جهيزة قول كل خطيب."}],[1303,"ثُمَّ لاينْبَغِي لطالبِ الحديثِ أن يقتصرَ عَلَى سَماعِ الحديثِ وكَتْبِهِ دونَ مَعْرِفَتِهِ وَفَهْمِهِ، فيكونَ قد أتعبَ نَفْسَهُ مِنْ غيرِ أن يظفرَ بطائلٍ، وبغيرِ أنْ يحصلَ في عدادِ أهلِ الحديثِ، بل لَمْ يَردْ عَلَى أنْ صارَ مِنَ المتشبِهينَ المنقوصينَ المُتَحَلّينَ بما هُمْ منهُ عاطِلونَ."],[1304,"قُلْتُ: أنْشَدَنِي أبو المُظَفَّرِ بنُ الحافظِ أبي سعْدٍ السمعانيِّ - رحمه الله - لَفْظًا بمدينةِ مَرْوَ، قالَ: أنْشَدَنا والدِي لَفْظًا أو قِراءةً عليهِ، قالَ: أنْشَدَنا مُحَمَّدُ بنُ ناصرٍ السَّلاميُّ (٦) منْ لفظِهِ، قالَ: أنْشَدَنا الأديبُ الفاضلُ فارسُ بنُ الحُسينِ لِنَفْسِهِ:"],[1305,"يا طَالبَ العِلْمِ الذي ... ذهبَتْ بِمُدَّتِهِ الرِّوايهْ"],[1306,"كُنْ في الرِّوايةِ ذَا العِنا ... يَةِ بالروايةِ والدِّرايهْ"],[1307,"وَاروِ القليلَ وراعِهِ ... فالعِلمُ لَيسَ لَهُ نِهَايهْ وليُقَدِّمِ (١) العنايَةَ بـ\" الصَحِيحَينِ \"، ثُمَّ بـ\" سُنَنِ أبي داودَ \"، و\" سُنَنِ النَّسائِيِّ \" و\" كتابِ التِّرمذِيِّ \"، ضَبْطًَا لِمُشْكِلِها وَفَهْمًا لِخَفيِّ مَعانيها، ولا يُخْدَعَنَّ عنْ كتابِ \" السُنَنِ الكَبيرِ \" للبيهقيِّ فإنا لا نعلمُ مِثْلَهُ في بابِه.","",{"fn":"بضم النون وفتح العين المهملة وسكون الياء المنقوطة باثنتين من تحتها، هذه النسبة إلى نعيم، وهو اسم لبعض أجداده. الأنساب ٥/ ٤٠٨، وترجمته في تاريخ بغداد ١١/ ٣٣١، والسير ١٧/ ٤٤٥.\nبفتح الخاء المعجمة، وتشديد اللام ألف، هذه النسبة إلى عمل الخل أو بيعه. الأنساب ٢/ ٤٨٢، وترجمته في تاريخ بغداد ٧/ ٤٢٥، والسير ١٧/ ٥٩٣.\nبفتح الفاء واللام، وفي آخرها الكاف، هذه النسبة إلى الفلك ومعرفته وحسابه، وترجمته في تذكرة الحفاظ ٣/ ١١٢٥، والسير ١٧/ ٥٠٢.\nبفتح اللام ألف واللام والكاف بعدها الألف، وفي آخرها الياء آخر الحروف، هذه النسبة إلى بيع اللوالك، وهي التي تلبس في الأرجل. الأنساب ٥/ ٥٨٤، وترجمته في تاريخ بغداد ١٤/ ٧٠، والسير ١٧/ ٤١٩.\nانظر هذه العلامات في الجامع ٢/ ١٥٨ - ١٥٩.\nبفتح السين المهملة واللام ألف المخففة وبعدها ميم، هذه النسبة إلى مدينة السلام بغداد. انظر: الأنساب ٣/ ٣٧٤، ووفيات الأعيان ٤/ ٢٩٤، والسير٢٠/ ٢٦٥."}],[1308,"ثُمَّ بِسائرِ ما تَمَسُّ حاجةُ صاحِبِ الحديثِ إليهِ منْ كُتُبِ المساندِ (٢)، كـ\" مُسْنَدِ أحمدَ \"، ومنْ كُتبِ الجوامِعِ المُصَنَّفةِ في الأحكامِ المشتمِلةِ عَلَى المسانيدِ وغيرها. و\" مُوَطَّأُ مالكٍ \" هوَ المُقَدَّمُ (٣) منها. ومِنْ كتبِ عِللِ الحديثِ ومنْ أجودِها: كتابُ \" العللِ \" عَنْ أحمدَ بنِ حَنْبلٍ، وكتابُ \" العللِ \" عنِ الدارَقُطْنيِّ. ومنْ كُتُبِ معرفةِ الرجالِ وتواريخِ المُحَدِّثينَ، ومِنْ أفْضَلِها: \" تاريخُ البخاريِّ الكبيرِ \"، و\" كتابِ الجرحِ والتعديلِ \" لابن أبي حاتِمٍ."],[1309,"ومِنْ كُتُبِ الضَبْطِ لِمُشْكِلِ الأسماءِ، ومنْ أكملِها \" كتابُ الإكمالِ \" لأبي نَصْرِ بنِ مَاكُوْلا."],[1310,"وليكُنْ كلّما مَرَّ بهِ اسمٌ مُشْكِلٌ، أو كلمةٌ منْ حديثٍ مشْكِلَةٌ بَحَثَ عنهاوأودعَها قَلْبَهُ، فإنهُ يجتمِعُ لهُ بذلكَ عِلْمٌ كثيرٌ فيُ يُسْرٍ. وليَكُنْ تحفُّظُهُ (٤) للحديثِ عَلَى التدريجِ، قَليلًا قليلًا معَ الأيامِ والليالي فذلكَ أحرى بأنْ يُمَتَّعَ بِمحفوظهِ."],[1311,"وممنْ وَرَدَ ذلكَ عنهُ منْ حُفَّاظِ الحديثِ المُتقدِّمينَ: شُعبةُ، وابنُ عُلَيَّةَ، ومَعْمَرٌ. ورُوِّينا عنْ مَعْمَرٍ، قالَ: سَمِعْتُ الزُّهريِّ يقولُ: «منْ طلَبَ العِلْمَ جُمْلَةً، فاتهُ جُملةً، وإنَّما يُدْرَكُ العِلمُ حديثًا وحديثينِ» (٥).","",{"fn":"في (ع) والتقييد: «ولتقدم».\nفي (ب) و(جـ): «المسانيد».\nفي (جـ): «المتقدم».\nفي (ب): «حفظه»، والمثبت من باقي النسخ، جاء في أساس البلاغة: ١٣٣: «احتفظ بالشيء، وتحفّظَ به: عُني بحفظه».\nأخرجه الخطيب في الجامع (٤٥٠)."}],[1312,"وليكنِ الإتقانُ منْ شأنهِ، فقدْ قالَ عبدُ الرحمانِ بنِ مَهْدِيٍّ: «الحِفْظُ: الإتقانُ» (١)."],[1313,"ثُمَّ إنَ المُذاكرةَ بما يتحفَّظُهُ منْ أقوى أسبابِ الإمتاعِ بهِ. رُوِّينا عنْ عَلْقمةَ النَّخَعيِّ قالَ: «تَذَاكَروا الحديثَ، فإنَّ حياتَهُ ذِكرُهُ» (٢)، وعن إبراهيمَ النَّخَعيِّ قالَ: «مَنْ سَرَّهُ أن يَحْفَظَ الحديثَ فليُحدِّثْ بهِ، وَلَوْ أنْ يُحَدِّثَ بهِ مَنْ لايَشْتهيهِ» (٣)."],[1314,"وليَشْتَغِلْ بالتخريجِ والتأليفِ والتَّصنيفِ إذا استعدَّ لِذَلِكَ وتأهَّلَ لهُ، فإنهُ كما قالَ الخطيبُ الحافظُ: يُثَبِّتُ الحِفْظَ، ويُذَكِّي القلبَ، ويشْحَذُ الطَّبعَ، ويجيدُ البيانَ، ويكشِفُ المُلْتَبِسَ، ويُكسِبُ (٤) جميلَ الذكرِ، ويخلِّدُهُ إلى آخرِ الدهرِ (٥)، وقَلَّما يَمْهَرُ في عِلْمِ الحديثِ وَيَقِفُ عَلَى غوامِضِهِ ويَسْتَبينُ الخَفِيَّ مِنْ فوائِدهِ إلاَّ مَنْ فَعَلَ ذلكَ. وَحَدَّثَ الصُّوريُّ (٦) الحافِظُ مُحَمَّدُ بنُ عليٍّ قالَ: رأيتُ أبا مُحَمَّدٍ عبدَ الغنيِّ بنَ سعيدٍ الحافظَ في المنامِ، فقالَ: يا أبا عبدِ اللهِ! خَرِّجْ وصَنِّفْ قَبْلَ أنْ يُحَالَ بَيْنَكَ وبَيْنَهُ. هذا أنا تَرانِي قَدْ حِيْلَ بَيْنِي وبينَ ذَلِكَ (٧)."],[1315,"ولِلْعلماءِ بالحديثِ في تَصْنيفِهِ طَرِيقتانِ:"],[1316,"إحْداهُما: التَّصْنيفُ عَلَى الأبوابِ، وهو تَخريجُهُ عَلَى أحكامِ الفقهِ وغيرِها، وتَنْوِيْعُهُ أنواعًا، وجمعُ ما وَرَدَ في كُلِّ حُكْمٍ وكُلِّ نوعٍ في بابٍ فبابٍ.","",{"fn":"أخرجه الخطيب في الجامع (١٠٣٧).\nأخرجه الرامهرمزي في الْمُحَدِّث الفاصل: ٥٤٦، وابن عبد البر في بيان جامع العلم ١/ ١٠١، والخطيب في الجامع لأخلاق الراوي (١٨٢١).\nأخرجه الخطيب في الجامع (١٨٢٢)، وابن عبد البر ١/ ١٠١ من جامع بيان العلم.\nفي (أ): «يكتب».\nالجامع لأخلاق الراوي ٢/ ٢٨٠.\nتوفي سنة (٤٤١ هـ). انظر: تاريخ بغداد ٣/ ١٠٣، والأنساب ٣/ ٥٧٠، والسير ١٧/ ١٢٧.\nأخرجه الخطيب في الجامع (١٨٦١)."}],[1317,"والثَّانِيَةُ: تَصنيفُهُ عَلَى المسانِيدِ، وجمعُ حديثِ كُلِّ صَحابيٍّ وَحْدَهُ وإنِ اخْتَلَفتْ أنواعُهُ، ولِمَنِ اخْتارَ ذَلِكَ أنْ يُرَتِّبَهُمْ (١) عَلَى حروفِ المعجمِ في أسْمائِهِمْ، ولهُ أنْ يُرَتِّبَهُم عَلَى القبائِلِ، فَيَبْدأَ ببني هاشِمٍ ثُمَّ بالأقْرَبِ نَسَبًا مِنْ رَسولِ اللهِ - صلى الله عليه وآله وسلم -، ولهُ أنْ يُرَتِّبَ عَلَى سَوَابِقِ الصَّحابَةِ، فَيَبْدأَ بالعَشَرَةِ، ثُمَّ بأهْلِ بَدْرٍ، ثُمَّ بأهلِ الْحُديْبِيَةِ، ثُمَّ بِمَنْ أسْلَمَ وهَاجَرَ بينَ الْحُديْبِيَةِ وفَتْحِ مَكَّةَ، ويَخْتِمُ بأصَاغِرِ الصَّحَابَةِ كأبي الطُّفَيْلِ ونِظرائِهِ، ثُمَّ بالنِّسَاءِ، وهذا أحْسَنُ، والأوَّلُ أسْهلُ. وفي ذَلِكَ مِنْ وُجوهِ التَّرْتيبِ غيرُ ذَلِكَ."],[1318,"ثُمَّ إنَّ مِنْ أعلى المراتِبِ في تَصنيفِهِ تَصنيفَهُ مُعَلَّلًا (٢)، بأنْ يَجْمَعَ في كُلِّ حديثٍ طُرُقَهُ واخْتِلافَ الرواةِ فيهِ، كما فَعَلَ يَعْقُوبُ بنُ شَيْبَةَ في \" مُسندِهِ \". ومِمَّا يَعْتَنُونَ بهِ في التَّأليفِ جَمْعُ الشُّيُوخِ، أي: جَمْعُ حديثِ شُيوخٍ مَخْصُوصِينَ كُلُّ واحِدٍ مِنْهُم عَلَى انفرَادِهِ. قالَ عُثمانُ بنُ سَعِيدٍ الدارميُّ: «يُقَالُ مَنْ لَمْ يَجْمَعْ حديثَ هَؤُلاءِ الخمسَةِ فهوَ مُفْلِسٌ في الحديثِ: سُفْيَانُ، وشُعْبَةُ، ومالِكٌ، وحَمَّادُ بنُ زَيْدٍ، وابنُ عُيينةَ، وهمْ أصُولُ الدينِ» (٣)."],[1319,"وأصْحابُ الحديثِ يَجْمَعُونَ حديثَ خَلقٍ كثيرٍ غيرَ الذينَ ذَكَرَهُمُ الدارميُّ، مِنْهُم: أيُّوبُ السّختيانيُّ، والزُّهْرِيُّ، والأوْزاعِيُّ، ويَجْمَعُونَ أيضًا التَّراجِمَ، وهيَ أسانِيدُ يَخصُّونَ (٤) ما جاءَ بها بالجمْعِ والتأليفِ، مثلُ: تَرْجَمةِ مالِكٍ عَنْ نافِعٍ، عَنِ ابنِ عُمَرَ، وتَرْجَمةِ سُهَيْلِ بنِ أبي صَالِحٍ، عَنْ أبيهِ، عَنْ أبي هُرَيْرَةَ، وتَرجَمةِ هِشَامِ بنِ عُرْوةَ، عَنْ أبيهِ، عَنْ عائشَةَ، في أشباهٍ لِذَلِكَ كثيرةٍ، ويَجْمَعُونَ أيْضًا أبوابًا مِنْ أبوابِ الكُتُبِ الْمُصَنَّفَةِ الجامِعَةِ للأحْكامِ فَيُفْرِدونَها بالتَّأْلِيفِ، فَتَصِيْرُ كُتُبًا مُفْرَدَةً، نحوُ: بابِ رُؤْيةِ اللهِ - عَزَّوَجَلَّ -، وبابِ رَفْعِ اليدينِ، وبابِ القراءةِ خَلْفَ الإمامِ، وغيرِ ذَلِكَ. ويُفْرِدونَ أحاديثَ فَيَجْمَعُونَ طُرُقَها في كُتُبٍ مُفْرَدةٍ، نحوُ: طُرُقِ حديثِ قَبْضِ العِلْمِ، وحديثِ الغُسْلِ (١) يَومَ الْجُمُعَةِ، وغيرِ ذَلِكَ. وكثيرٌ مِنْ أنواعِ كِتابنا هذا قَدْ أفرَدُوا أحاديْثَهُ بالْجَمْعِ والتَّصْنِيفِ.","",{"fn":"في الشذا: «يرتبه»، وكذا ما بعدها.\nفي (أ) و(ع): «في تصنيفه معللًا».\nأخرجه الخطيب في الجامع (١٩٠٧).\nفي (ب): «يحصون»."}],[1320,"وعليهِ في كُلِّ ذَلِكَ، تَصْحِيحُ القَصْدِ والْحَذَرُ مِنْ قَصْدِ المكاثَرَةِ ونَحْوِهِ. بَلَغَنا عَنْ حَمْزَةَ بنِ مُحَمَّدٍ الكِنانِيِّ (٢) أنَّهُ خَرَّجَ حديثًا واحِدًا مِنْ نَحوِ مِئتَي طريقٍ، فأعْجبَهُ ذَلِكَ، فرأى يَحْيى بنَ مَعينٍ في مَنامِهِ، فَذَكَرَ لهُ ذَلِكَ، فقالَ لهُ: «أخْشَى أنْ يَدْخُلَ هذا تَحْتَ: ﴿ألْهَاكُمُ التَّكَاثُرُ﴾ (٣») (٤)."],[1321,"ثُمَّ لِيحذَرْ أنْ يُخرِجَ إلى الناسِ ما يُصَنِّفُهُ إلاَّ بَعْدَ تَهْذِيْبِهِ وتَحْريرِهِ وإعادةِ النَّظَرِ فيهِ وتَكْرِيْرِهِ (٥). وليتَّقِ أنْ يَجْمَعَ ما لَمْ يَتَأَهَّلْ بَعْدُ لاجْتِناءِ ثَمَرَتِهِ واقْتِنَاصِ فائِدةِ جَمْعِهِ؛ كَيْلا يَكونَ حُكْمُهُ مَا رُوِّيْناهُ (٦) عَنْ عليِّ بنِ المدينِيِّ، قالَ: إذا رأيْتَ الْحَدَثَ أوَّلَ مَا يَكْتُبُ الحدِيثُ يجمعُ حديثَ «الغُسْلِ» وحديثَ: «مَنْ كَذَبَ»؛ فاكْتُبْ عَلَى قَفَاهُ لا يُفْلِحُ» (٧)."],[1322,"ثُمَّ إنَّ هذا الكتابَ مَدْخَلٌ إلى هذا الشَّأنِ، مُفْصِحٌ عَنْ أُصُولِهِ وفُروعِهِ، شارِحٌ (٨) لمصطلحاتِ أهلهِ ومقاصِدِهم ومُهمَّاتهِم التي ينْقُصُ المُحَدِّثُ بالجهلِ بها نقْصًا فاحِشًَا، فهو إن شاءَ اللهُ جديرٌ بأنْ تُقَدَّمَ العنايةُ بهِ، ونسألُ اللهَ سبحانَهُ فَضْلَهُ العظيمَ، واللهُ أعلمُ.","",{"fn":"في (جـ): «غسل».\nفي (ب) و(جـ): «الكتاني» بالتاء، وهو خلاف ما جاء في (أ) و(ع) و(م) والتقييد والشذا الفياح، ومصادر ترجمته. انظر: تاريخ دمشق ١٥/ ٢٣٩، وتذكرة الحفاظ ٣/ ٩٣٢، والسير ١٦/ ١٧٩، وشذرات الذهب ٣/ ٢٣.\nالتكاثر: ١.\nأخرجه ابن عبد البر في بيان جامع العلم ٢/ ١٣٢، وهو في تذكرة الحفاظ ٣/ ٩٣٣، والسير ١٦/ ١٨٠.\nانظر: الجامع لأخلاق الراوي ٢/ ٢٨٣.\nفي (ب): «روينا».\nأخرجه الخطيب في الجامع ٢/ ٣٠١ (١٩١٢).\nفي (م): «شارع»."}],[1323,"النوع التاسع والعشرون معرفة الإسناد العالي والنازل"],[1324,"(١)"],[1325,"أصْلُ الإسْنادِ أوَّلًا خَصِيصَةٌ (٢) فاضِلةٌ مِنْ خَصَائِصِ هذهِ الأُمَّةِ (٣)، وسُنَّةٌ بالِغَةٌ مِنَ السُّنَنِ المؤَكَّدةِ. رُوِّيْنا مِنْ غيرِ وَجْهٍ عَنْ عبدِ اللهِ بنِ المبارَكِ - رضي الله عنه -، أنَّهُ قالَ: «الإسْنادِ مِنَ الدِّيْنِ، لَوْلاَ الإسْنادُ لَقَالَ مَنْ شَاءَ ما شَاءَ» (٤)."],[1326,"وطَلَبُ العُلُوِّ فيهِ سُنَّةٌ أيضًا، ولِذَلِكَ اسْتُحِبَّتِ الرِّحْلَةُ فيهِ - عَلَى ما سَبَقَ ذِكْرُهُ (٥) -. قالَ أحمدُ بنُ حَنْبَلٍ - رضي الله عنه -: «طَلَبُ الإسْنادِ العالِي سُنَّةٌ عَمَّنْ سَلَفَ» (٦)."],[1327,"وقَدْ رُوِّيْنا أنَّ يَحْيَى بنَ مَعِينٍ - رضي الله عنه - قيلَ لهُ في مَرَضِهِ الذي ماتَ فيهِ: «ما تَشْتَهِي؟ قالَ بيتٌ خالي وإسْنادٌ عالِي» (٧).","",{"fn":"انظر في ذلك: معرفة علوم الحديث: ٥ - ١٤، والجامع لأخلاق الراوي ١/ ١١٥ وما بعدها، وجامع الأصول ١/ ١١٠ - ١١٥، والإرشاد: ٥٢٩ - ٥٣٧، والتقريب: ١٥٠ - ١٥٢، والاقتراح: ٣٠١ - ٣٠٨، واختصار علوم الحديث: ١٥٩ - ١٦٤، والشذا الفياح ٢/ ٤١٩ - ٤٣٤، والمقنع ٢/ ٤٢١ - ٤٢٦، وشرح التبصرة ٢/ ٣٦٠، ونزهة النظر: ١٥٦، وفتح المغيث ٣/ ٣ - ٢٦، وتدريب الراوي ٢/ ١٥٩ - ١٧٢، وفتح الباقي ٢/ ٢٥٦، وتوضيح الأفكار ٢/ ٣٩٥ - ٤٠١.\nبفتح الخاء وكسر الصاد المخففة بوزن فعيلة كما ضبطها الحافظ الدمياطي في تعليقه عَلَى علوم الحديث لابن الصلاح. وللسيوطي رسالة \" ألوية النصر في أن خِصِّيْصى بالقصر - بكسر الخاء والصاد المشددة - يرد بها عَلَى السخاوي، كما في حاشية تدريب الراوي ٢/ ١٥٩، وانظر: لسان العرب ٧/ ٢٤، وتاج العروس ١٧/ ٥٥٠، والمعجم الوسيط ١/ ٢٣٨.\nانظر: شرف أصحاب الحديث: ٤٠ - ٤٣، والملل والنحل ٢/ ٨١ - ٨٤، والإرشاد ٢/ ٥٢٩ للنووي، وتدريب الراوي ٢/ ١٥٩، وفتح المغيث ٣/ ٤، والباعث الحثيث: ١٥٩.\nأسنده إليه مسلم في مقدمة صحيحه ١/ ١٥، والرَّامهرمزي في الْمُحَدِّث: ٢٠٩، والحاكم في معرفة علوم الحديث: ٦، والخطيب في الجامع (١٦٤٣)، وفي شرف أصحاب الحديث: ٤١، وابن عبد البر في التمهيد ١/ ٥٦.\nراجع: محاسن الاصطلاح: ٣٧٩.\nأخرجه الخطيب في الجامع (١١٧).\nهكذا رسم في النسخ الخطية و(ع) و(م) والتقييد والشذا ومجموعة من المصادر التي أوردته بإثبات ياء المنقوص من (خالي، وعالي)."}],[1328,"قلتُ: العُلُوُّ يُبْعِدُ الإسْنادَ مِنَ الخللِ؛ لأنَّ كُلَّ رَجُلٍ مِنْ رِجالِهِ يحتملُ أنْ يَقَعَ الخللُ مِنْ جِهَتِهِ سَهْوًا أوْ عَمْدًا، ففي قِلَّتِهِمْ قِلَّةُ جِهاتِ الخللِ، وفي كَثْرَتِهِمْ كَثْرَةُ جِهاتُ الخللِ، وهذا جَلِيٌّ واضِحٌ."],[1329,"ثُمَّ إنَّ عُلُوَّ المطلوبِ في رِوايةِ الحديثِ عَلَى أقْسامٍ خَمْسَةٍ (١):"],[1330,"أوَّلُها: القُرْبُ مِنْ رَسُولِ اللهِ - صلى الله عليه وآله وسلم - بِإِسْنادٍ نظيفٍ غيرِ ضعيفٍ، وذَلِكَ مِنْ أجَلِّ أنواعِ العُلُوِّ. وقَدْ رُوَّيْنا عَنْ مُحَمَّدِ بنِ أسْلَمَ الطُّوسِيِّ الزَّاهِدِ (٢) العَالِمِ - رضي الله عنه - أنَّهُ قالَ:"],[1331,"«قُرْبُ الإسْنادِ قُرْبٌ أو قُرْبَةٌ إلى اللهِ عَزَّوَجَلَّ» (٣). وهذا كما قالَ؛ لأنَّ قُرْبَ الإسْنادِ قُرْبٌ إلى رَسُولِ اللهِ - صلى الله عليه وآله وسلم -، والقُرْبُ إليهِ قُرْبٌ إلى (٤) اللهِ عَزَّوَجَلَّ."],[1332,"الثَّاني: - وهوَ الذي ذَكَرَهُ الحاكمُ أبو عبدِ اللهِ الحافِظُ (٥) -: القُرْبُ مِنْ إمامٍ مِنْ أئِمَّةِ الحديثِ وإنْ كَثُرَ العددُ مِنْ ذَلِكَ الإمامِ إلى رسولِ اللهِ - صلى الله عليه وآله وسلم -. فإذا وُجِدَ ذَلِكَ في إسْنادٍ، وُصِفَ بالعُلُوِّ نَظَرًا إلى قُرْبِهِ مِنْ ذَلِكَ الإمامِ وإنْ لَمْ يَكُنْ عاليًا بالنسْبَةِ إلى رسولِ اللهِ - صلى الله عليه وآله وسلم -. وكلامُ الحاكِمِ يُوهِمُ أنَّ القُرْبَ مِنْ رَسُولِ اللهِ لا يُعَدُّ مِنَ العُلُوِّ المطلوبِ أصْلًا؛ وهذا غَلَطٌ مِنْ قائِلِهِ؛ لأنَّ القُرْبَ منهُ - صلى الله عليه وآله وسلم - بإسْنادٍ نَظِيْفٍ غيرِ ضَعِيْفٍ أوْلَى بذلكَ. ولا يُنازِع في هذا مَنْ لهُ مُسْكَةٌ (٦) مِنْ مَعرفةٍ، وكأنَّ الحاكِمَ أرادَ بكلامِهِ ذَلِكَ إثباتَ العُلُوِّ للإسْنادِ بِقُرْبِهِ (١) مِنْ إمامٍ، وإنْ لَمْ يكُنْ قَريبًا إلى رسولِ اللهِ - صلى الله عليه وآله وسلم -، والإنكارَ عَلَى مَنْ يُراعي في ذَلِكَ مُجَرَّدَ قُرْبِ الإسنادِ إلى رسولِ اللهِ - صلى الله عليه وآله وسلم - وإنْ كانَ إسنادًا ضَعِيْفًا، ولهذا مَثَّلَ ذَلِكَ بحديثِ أبي هُدْبةَ، ودِينارٍ، والأشَجِّ، وأشْبَاهِهِمْ (٢)، واللهُ أعلمُ.","",{"fn":"كما قسمه أبو الفضل مُحمد بن طاهر في جزء له اسمه: \" العلو والنزول \" ص ٥٧، وتبعه في ذَلِكَ المصنف كما أشار إلى ذَلِكَ الحافظ العراقي في شرح التبصرة والتذكرة ٢/ ٣٦٢.\nهو الإمام أبو الحسن مُحمد بن أسلم بن سالم بن يزيد الكندي الطوسي الزاهد، صاحب المسند والأربعين، توفي سنة ٢٤٢ هـ، حلية الأولياء ٩/ ٢٣٨، وشذرات الذهب ٢/ ١٠٠، والرسالة المستطرفة: ٦٤.\nأخرجه الخطيب في الجامع (١١٥).\nفي (م) والشذا: «من».\nمعرفة علوم الحديث: ١١.\nيُقال: رجلٌ ذو مُسْكَةٍ ومُسْكٍ، أي: رأي وعقل يُرجَعُ إليهِ، وفُلانٌ لا مُسْكَةَ لهُ، أي: لا عَقْل له، ويقال: ما بفلانٍ مُسْكَة، أي: ما به قوة ولا عقل، ويُقَال: فيهِ مُسْكَةٌ مِنْ خَيْرٍ، أي: بقيَّة، وليسَ لأمرِهِ مُسْكَةٌ، أي: أثر أو أصل يُعَوَّلُ عليهِ. انظر: اللسان ١٠/ ٤٨٨، والمعجم الوسيط ٢/ ٨٧٠."}],[1333,"الثَّالِثُ: العُلُوُّ (٣) بالنِّسبةِ إلى روايةِ \" الصحيحينِ \"، أو أحدِهِما، أو غيرِهِما مِنَ الكُتُبِ المعروفةِ المعتمَدةِ، وذَلِكَ ما اشتهرَ آخِرًا مِنَ الموافَقاتِ، الأبدالِ، والمسَاواةِ، والمصافحةِ. وقَدْ كَثُرَ اعْتِناءُ المحدِّثينَ المتأخِّرينَ بهذا النوعِ، ومِمَّنْ وجدْتُ هذا النوعَ في كَلامِهِ أبو بكرٍ الخطيبُ الحافِظُ وبعضُ شُيُوخِهِ، وأبو نَصْرِ ابنُ ماكُولا (٤)، وأبو عبدِ اللهِ الْحُمَيْدِيُّ، وغيرُهُمْ مِنْ طَبَقَتِهِمْ ومِمَّنْ جاءَ بَعْدَهُمْ."],[1334,"أمَّا الموافَقَةُ: فهيَ أنْ يَقَعَ لكَ الحديثُ عَنْ شَيْخِ مُسْلِمٍ فيهِ مَثَلًا عاليًا بعددٍ أقَلَّ مِنَ العدَدِ الذي يَقَعُ لكَ بهِ ذَلِكَ الحديثُ عَنْ ذَلِكَ الشَّيْخِ إذا رَوَيْتَهُ عَنْ مُسْلِمٍ عنهُ."],[1335,"وأمَّا البَدَلُ: فَمِثْلُ أنْ يَقَعَ لكَ هذا العُلُوُّ عَنْ شيخٍ غَيْرِ شَيْخِ مُسْلِمٍ، هوَ مِثلُ شيخِ مُسْلِمٍ في ذَلِكَ الحديثِ. وقدْ يُرَدُّ البَدَلُ إلى الموافَقَةِ، فيُقَالُ فيما ذكَرْناهُ: إنَّهُ موافقةٌ عالِيةٌ في شَيْخِ شَيْخِ مُسْلِمٍ وَلَوْ لَمْ يكُنْ ذَلِكَ عاليًا فهوَ أيضًا مُوافقةٌ وبَدَلٌ، لَكِنْ لاَ يُطْلَقُ عليهِ اسمُ الموافقةِ والبدَلِ لِعَدَمِ الالتِفاتِ إليهِ."],[1336,"وأمَّا المسَاواةُ: فهيَ في أعْصارِنا أنْ يقلَّ العدَدُ في إسْنادِكَ لا إلى شَيْخِ مُسْلِمٍ وأمثالِهِ، ولا إلى شَيْخِ شَيْخِهِ، بلْ إلى مَنْ هوَ أبعدُ مِنْ ذَلِكَ كالصَّحَابِيِّ أوْ مَنْ قارَبَهُ، ورُبَّما كانَ إلى رسولِ اللهِ - صلى الله عليه وآله وسلم - بحيثُ يَقَعُ بَيْنَكَ وبَيْنَ الصَّحابيِّ مَثَلًا مِنَ العَدَدِ مِثْلُ ما وقَعَ مِنَ العدَدِ بَيْنَ مُسْلِمٍ وبَيْنَ ذَلِكَ الصَّحابيِّ فَتَكُونُ (٥) بذلكَ مُسَاوِيًا لِمُسْلِمٍ مَثَلًا في قُرْبِ الإسْنادِ وعدَدِ رِجَالِهِ.","",{"fn":"في (م): «لقربه».\nانظر: محاسن الاصطلاح: ٣٨٢ - ٣٨٤، وشرح التبصرة ٢/ ٣٦٢.\nانظر: التقييد والإيضاح: ٢٥٨ - ٢٥٩.\nبفتح الميم وبعد الألف كاف مضمومة، وبعدها واو ساكنة ثُمَّ لام ألف. وفيات الأعيان ٣/ ٣٠٦، وترجمته في السير ١٨/ ٥٦٩.\nفي (جـ): «فيكون»."}],[1337,"وأمَّا المصَافَحَةُ (١): فهيَ أنْ تَقَعَ هذهِ المساواةُ - التي وصَفْناها - لشَيخِكَ لا لكَ فيقعَ ذَلِكَ لكَ مُصَافحَةً، إذْ تَكُونُ كَأَنَّكَ لَقِيْتَ مُسْلِمًا في ذَلِكَ الحديثِ وصَافحتَهُ بهِ، لِكَوْنِكَ قدْ لَقِيْتَ شَيْخَكَ المساوي لِمُسْلِمٍ. فإنْ كانتْ المساواةُ لِشَيْخِ شَيْخِكَ كانتِ المصَافَحةُ لِشَيْخِكَ، فَتَقُولُ: كأنَّ شَيْخِي سَمِعَ مُسْلِمًا وصَافَحَهُ. وإنْ كانَتِ المسَاواةُ لِشَيْخِ شَيْخِ (٢) شَيْخِكَ، فالمصَافَحةُ لِشَيْخِ شَيْخِكَ، فتقولُ فيها: كأنَّ شَيْخَ شَيْخِي سَمِعَ مُسْلِمًا وصَافَحَهُ، ولكَ (٣) ألاَّ تَذكرَ لكَ في ذَلِكَ نِسْبَةً، بلْ تَقُولُ: كأنَّ فُلانًا سَمِعَهُ مِنْ مُسْلِمٍ، مِنْ غيرِ أنْ تَقُولَ فيهِ: شَيْخِي أو شَيْخُ شَيْخِي."],[1338,"ثُمَّ لا يخفَى عَلَى المتأَمِّلِ أنَّ في المساواةِ والمصَافَحةِ الواقِعَتَينِ لكَ لا يَلْتَقِي إسْنادُكَ وإسْنادُ مُسْلِمٍ أو نحوِهِ إلاَّ بَعيدًا عَنْ شَيْخِ مُسْلِمٍ، فيلْتَقِيانِ في الصحابيِّ أو قَرِيْبًا منهُ، فإنْ كَانتِ المصَافَحَةُ التي تَذْكُرُها ليستْ لكَ بلْ لِمَنْ فَوقَكَ مِنْ رِجالِ إسْنادِكَ أمْكَنَ الْتِقَاءُ الإسْنادَيْنِ فيها في شَيْخِ مُسْلِمٍ أو أشْباهِهِ وداخَلَتِ المصَافَحةُ حِيْنَئذٍ الموافقةُ، فإنَّ مَعْنَى الموافقةِ راجِعٌ إلى مُسَاواةٍ ومصَافَحةٍ مَخْصُوصَةٍ؛ إذْ حاصِلُها أنَّ بعضَ مَنْ تَقَدَّمَ مِنْ رواةِ إسْنادِكَ العالِي سَاوَى أو صَافَحَ مُسْلِمًا أو البخَارِيَّ؛ لِكَونِهِ سَمِعَ مِمَّنْ سَمِعَ مِنْ شَيْخِهِما مَعَ تَأَخُّرِ طَبَقَتِهِ عَنْ طَبَقَتِهِما. ويوجدُ في كثيرٍ منَ العوالي المخرَّجةِ لِمَنْ تَكَلَّمَ أوَّلًا في هذا النوعِ وطَبَقَتِهِمْ: المصافَحَاتُ مَعَ الموفَقَاتِ والأبدالِ لِمَا ذَكَرْناهُ. ثُمَّ اعْلَمْ أنَّ هذا النوعَ مِنَ العُلُوِّ عُلُوٌّ تابِعٌ لِنُزولٍ؛ إذْ لولا نُزُولُ ذَلِكَ الإمامِ في إسنادِهِ لَمْ تَعْلُ أنتَ في"],[1339,"إسْنادِكَ (٤). وكُنْتُ قَدْ قَرَأْتُ بِمَرْوَ عَلَى شَيخِنا المكْثِرِ أبي المظَفَّرِ عبدِ الرحيمِ بنِ الحافِظِ المصَنِّفِ أبي سَعْدٍ السَّمعانيِّ - رَحِمَهُما اللهُ - في أرْبِعِي (٥) أبي البركاتِ الفَرَاوِيِّ حديثًا ادَّعَى فيهِ أنَّهُ كأنَّهُ سَمِعَهُ هوَ أو شَيْخُهُ مِنَ البُخَارِيِّ، فقالَ الشَّيْخُ أبو الْمُظَفَّرِ: «ليسَ لكَ بعالٍ، ولكِنَّهُ للبُخارِيِّ نازِلٌ». وهذا حَسَنٌ لَطِيْفٌ يَخْدِشُ وَجْهَ هذا النَّوعِ مِنَ العُلُوِّ، واللهُ أعلمُ.","",{"fn":"سميت مصافحة؛ لأن العادة جرت في الغالب في المصافحة بَيْنَ المتلاقيين. انظر: نزهة النظر: ١٥٩، وفتح المغيث ٣/ ١٨.\nلَمْ ترد في (ب).\nفي (أ): «وذلك».\nراجع: محاسن الاصطلاح: ٣٨٦.\nفي نسخة (ب): «أربعين»، وفي حاشية (م) تعليق نصه: «لعلها من أربعين حديثًا رواها أبو البركات، حذفت النون للإضافة»."}],[1340,"الرَّابِعُ: مِنْ أنواعِ العُلُوِّ العُلُوُّ المسْتَفادُ مِنْ تَقَدُّمِ وَفَاةِ الراوي، مِثالُهُ ما أروِيهِ عنْ شيخٍ أخبرَنِي بهِ عَنْ واحدٍ عَنِ البَيْهَقِيِّ الحافِظِ عَنِ الحاكِمِ أبي عبدِ اللهِ الحافِظِ أعلى مِنْ روايتي لِذَلِكَ عَنْ شيخٍ أخبرَنِي بهِ عَنْ (١) واحدٍ عَنْ أبي بكرِ (٢) بنِ خَلَفٍ عَنِ الحاكِمِ وإنْ تَسَاوَى الإسْنادانِ في العددِ لِتَقَدُّمِ وَفَاةِ البَيْهَقِيِّ عَلَى وفاةِ ابنِ"],[1341,"خَلَفٍ؛ لأنَّ البَيْهَقِيَّ ماتَ سنةَ ثَمانٍ وخَمْسِينَ وأربَعِ مئةٍ، وماتَ ابنُ خَلَفٍ"],[1342,"سنةَ سَبْعٍ وثَمانِينَ وأربعِ مِئةٍ. ورُوِّيْنا عَنْ أبي يَعْلَى الخليلِ بنِ عبدِ اللهِ الخليليِّ الحافِظِ"],[1343,"- رحمه الله - قالَ: «قَدْ يَكونُ الإسْنادُ يَعْلُو عَلَى غيرِهِ بِتَقَدُّمِ موتِ راويهِ وإنْ كانا مُتَسَاوِيَينِ في العدَدِ» (٣)، ومَثَّلَ ذَلِكَ مِنْ حديثِ نفسِهِ بمِثْلِ مَا ذَكَرْناهُ. ثُمَّ إنَّ هَذَا كَلامٌ (٤) في العُلُوِّ المنبني (٥) عَلَى تَقَدُّمِ الوفاةِ المستفادِ مِنْ نِسْبَةِ شيخٍ إلى شيخٍ، وقياسِ راوٍ براوٍ. وأمَّا العُلُوُّ المستفادُ مِنْ مُجَرَّدِ تَقَدُّمِ وفاةِ شيخِكَ مِنْ غيرِ نَظَرٍ إلى قياسِهِ براوٍ آخَرَ، فقدْ حَدَّهُ بعضُ أهلِ هَذَا الشأْنِ بِخَمْسِينَ سنةً، وذلكَ مَا رُوِّيْناهُ عَنْ أبي عليٍّ الحافِظِ النَّيْسابوريِّ، قالَ: سَمِعْتُ أحمدَ بنَ عُميرٍ الدِّمَشْقِيَّ (٦) - وكانَ مِنْ أركانِ الحديثِ - يَقُولُ: «إسْنادُ خَمْسِينَ سنةً مِنْ موتِ الشَّيْخِ إسْنادُ عُلُوٍّ» (١). وفيما نروي عَنْ أبي عبدِ اللهِ بنِ مَنْدَه الحافِظِ قالَ: «إذا مَرَّ عَلَى الإسنادِ ثَلاثُونَ سَنَةً فهوَ عالٍ». وهذا أوسَعُ مِنَ الأوَّلِ، واللهُ أعلمُ.","",{"fn":"سقطت من (م).\nفي (ع): «أبي بكر عبد الله بن خلف»، وكلمة: «عبد الله»، لَمْ ترد في شيء من النسخ الخطية ولا (م) ولا التقييد ولا الشذا، وهو مخالف لما في مصادر ترجمته فقد ذكرت المصادر أنّه: الإمام، أبو بكر، أحمد بن علي بن عبد الله بن عمر بن خلف الشيرازي، ثُمَّ النيسابوري، توفي سنة (٤٨٧ هـ). انظر: سير أعلام النبلاء ١٨/ ٤٧٨، وشذرات الذهب ٣/ ٣٧٩.\nالإرشاد ١/ ١٧٩.\nفي (ب): «الكلام».\nفي (ب): «المبتنى».\nكتب في نسخة (جـ) فوقه: «هو ابن جَوْصَا الحافظ». انظر: ترجمته في تاريخ دمشق ٥/ ١٠٩، وسير أعلام النبلاء ١٥/ ١٥."}],[1344,"الخامِسُ: العُلُوُّ المستفادُ مِنْ تَقَدُّمِ السَّماعِ. أَنْبَؤُنا (٢) عَنْ مُحَمَّدِ بنِ ناصِرٍ الحافِظِ، عَنْ مُحَمَّدِ بنِ طَاهِرٍ الحافظِ قالَ: «مِنَ العُلُوِّ تَقَدُّمُ السَّماعِ» (٣)."],[1345,"قُلْتُ (٤): وكثَيْرٌ مِنْ هذا يَدْخُلُ في النوعِ المذكورِ قَبْلَهُ، وفيهِ ما لا يدخُلُ في ذَلِكَ بلْ يَمْتازُ عنهُ. مِثْلُ أنْ يَسْمَعَ شَخْصانِ مِنْ شَيْخٍ واحدٍ، وسماعُ أحَدِهِما مِنْ سِتِّينَ سنةً مَثَلًا، وسَماعُ الآخَرِ مِنْ أربَعِينَ سنةً. فإذا تساوى السندُ إليهما في العَدَدِ، فالإسنادُ إلى الأوَّلِ الذي تقدمَ سماعُهُ أعلى."],[1346,"فهذِهِ أنواعُ العلوِّ عَلَى الأستقصاءِ والأيضاحِ الشافي، وللهِ سبحانه وتعالى الحمدُ كُلُّهُ."],[1347,"وأما مارُوِّيناهُ عنِ الحافظِ أبي الطّاهرِ (٥) السِّلفيِّ رحمه الله مِنْ قولِهِ في أبياتٍ لهُ:"],[1348,"بل عُلُوُّ الحديثِ بَيْنَ أُولي الحِفْ ... ظِ والإتقانِ صِحَّةُ الإسنادِ (٦)"],[1349,"وما رُوِّيناهُ عنِ الوزيرِ نِظامِ المُلكِ (٧) مِن قولِهِ: «عندي أنَّ الحديثَ العالي: ماصحَّ عنْ رسولِ اللهِ - صلى الله عليه وآله وسلم - وإن بلغَتْ رواتُهُ مِئةً». فهذا ونحوُهُ ليسَ مِنْ قبيلِ المتعارَفِ إطلاقُهُ بينَ أهلِ الحديثِ، وإنما هُوَ عُلُّوٌّ منْ حيثُ المعنى فَحَسْبُ، واللهُ أعلمُ.","",{"fn":"أسنده إليه ابن عساكر في تاريخه ٥/ ١١٣.\nفي (م): «أُنبئنا».\nفي مسألة العلو والنزول: ٧٦.\nفي (أ): «قال المملي».\nفي (م) والتقييد والشذا الفياح: «طاهر».\nأوردها الامام الذهبي في السير ٢١/ ٣٧ هكذا: بل علو الحديث عِنْدَ أولي الإتـ ... قانِ والحفظ صِحَّة الإسناد\nانظر ترجمته في السير ١٩/ ٦٤."}],[1350,"فصل"],[1351,"وأما النُّزولُ فهوَ ضِدُّ العُلُوِّ. وما منْ قسمٍ مِنْ أقسامِ العُلُوِّ الخمسةِ إلا وضِدُّهُ قسمٌ منْ أقسامِ النزولِ."],[1352,"فهوَ إذن خمسةُ أقسامٍ، وتَفْصيلُها يُدْرَكُ مِنْ تفصيلِ أقسامِ العُلوِّ عَلَى نحوِ ما تَقَدَّمَ شرحُهُ."],[1353,"وأما قولُ الحاكمِ أبي عبدِ اللهِ: «لعَلَّ قائلًا يقولُ: النزولُ ضِدُّ العُلُوِّ. فَمَنْ"],[1354,"عَرَفَ العُلوَّ فَقَدْ عرفَ ضِدَّهُ، وليسَ كذلكَ؛ فإنَ للنزولِ مراتبَ لا يَعْرِفُها إلا أهلُ الصَّنْعَةِ (١) ... إلى آخرِ كلامهِ. فهذا ليسَ نَفْيًا لكونِ النُّزولِ ضِدًَّا (٢) للعُلُوِّ عَلَى الوجهِ الذي ذكرتُهُ، بل نَفْيًا لكَوْنِهِ يُعْرَفُ بِمَعْرِفةِ العُلُوِّ. وذلكَ يَليقُ بما ذَكَرَهُ هوَ في مَعرِفَةِ العُلُوِّ، فإنَّهُ قَصَّرَ في بيانِهِ وتَفْصِيلِهِ، وليسَ كذلكَ ما ذكرنَاهُ نحنُ في العُلُوِّ؛ فإنَّهُ مُفَصَّلٌ تَفْصيلًا مُفْهِمًا لِمَرَاتِبِ النُّزُولِ، والعِلْمُ عندَ اللهِ تبارك وتعالى."],[1355,"ثُمَّ إنَّ النُّزُولَ مَفْضُولٌ مَرْغُوبٌ عنهُ، والفضيلةُ لِلْعُلُوِّ عَلَى ما تَقَدَّمَ بيانُهُ ودَليلُهُ. وحَكَى ابنُ خَلاَّدٍ عَنْ بعضِ أهلِ النَّظَرِ أنَّهُ قالَ: «التَّنَزُّلُ (٣) في الإسنادِ أفضَلُ» (٤)، واحْتجَّ لهُ بما مَعْناهُ أنَّهُ يجبُ الاجْتِهادُ والنَّظَرُ في تَعْدِيلِ كُلِّ راوٍ وتَخْريجِهِ (٥)، فَكُلَّما زادُوا كانَ الاجْتِهادُ أكثَرَ وكانَ الأجْرُ أكثرَ. وهذا مَذْهَبٌ ضَعِيفٌ، ضَعِيفُ الْحُجَّةِ."],[1356,"وَقَدْ رُوِّيْنا عَنْ عَلِيِّ بنِ المدينِيِّ، وأبي عمرٍو المستَمْلِي النَّيْسابوري، أنَّهَما قالا: «النُّزُولُ شُؤْمٌ» (٦)، وهذا ونحوُهُ مِمَّا جاءَ في ذمِّ النُّزُولِ مَخْصُوصٌ ببعضِ النُّزُولِ، فإنَّ النُّزُولَ إذا تَعَيَّنَ دُونَ العُلُوِّ طريقًا إلى فائدةٍ راجِحَةٍ عَلَى فائدَةِ العُلُوِّ فَهوَ مُختارٌ غيرُ مَرذولٍ، واللهُ أعلمُ.","",{"fn":"معرفة علوم الحديث: ١٢.\nفي (ب): «ضد العلو».\nفي (أ): «النزول».\nالمحدّث الفاصل: ٢١٦.\nفي (أ) و(جـ) و(م): «تجريحه».\nأخرجه الخطيب في الجامع (١١٩)."}],[1357,"النوع الموفي ثلاثين معرفة المشهور من الحديث"],[1358,"(١)"],[1359,"ومَعْنى الشُّهْرةِ مَفْهُومٌ (٢)، وهوَ مُنْقَسِمٌ إلى صَحِيحٍ، كَقَولِهِ - صلى الله عليه وآله وسلم -: «إنَّما الأعْمالُ بالنِّيَّاتِ» (٣)، وأمثالِهِ، وإلى غيرِ صَحيحٍ (٤)، كَحَديثِ: «طَلَبُ العِلْمِ فَرِيضَةٌ عَلَى كُلِّ مُسْلِمٍ» (٥). وكما بَلَغَنا عَنْ أحمدَ بنِ حَنْبَلٍ (٦) - رضي الله عنه - أنَّهُ قالَ: «أربعَةُ أحاديثَ تَدُورُ عَنْ رَسُولِ اللهِ - صلى الله عليه وآله وسلم - في الأسْواقِ ليسَ لها أصْلٌ: «مَنْ بَشَّرَنِي بِخُرُوجِ آذَارَ بَشَّرْتُهُ بالْجَنَّةِ» (١)، و«مَنْ آذَى ذِمِّيًّا فأنا خَصْمُهُ يَومَ القِيَامةِ» (٢)، و«يَومُ نَحْرِكُمْ يَومُ صَومِكُمْ» (٣)، و«لِلسَّائِلِ حَقٌّ، وإنْ جاءَ عَلَى فَرَسٍ» (٤).","",{"fn":"انظر في معرفة المشهور: معرفة علوم الحديث: ٩٢ - ٩٤، والإرشاد ٢/ ٥٣٨ - ٥٤٤، والتقريب: ١٥٢ - ١٥٣، والاقتراح: ٣١٠، واختصار علوم الحديث: ١٦٥ - ١٦٦ والشذا الفياح ٢/ ٤٣٤ - ٤٤٥، والمقنع ٢/ ٤٢٧ - ٤٤٠، وفتح الباقي ٢/ ٢٦٥ - ٢٧٧، ونزهة النظر: ٦٢ - ٧١، وفتح المغيث ٣/ ٢٧ - ٤١، وتدريب الراوي ٢/ ١٧٣ - ١٧٩، وتوضيح الأفكار ٢/ ٤٠١ - ٤١١، وظفر الأماني: ٣٩ - ٧٦.\nيعني: لغة، انظر: عن ذَلِكَ: مقاييس اللغة ٣/ ٢٢٢، والصحاح ٢/ ٧٠٥، واللسان ٤/ ٤٣١، وتاج العروس ١٢/ ٢٦٢. وأما في الاصطلاح فقد اختلفت عبارة المحدّثين في تعريفه، وقد عَرّفه ابن حجر فقال: «ما له طرق محصورة بأكثر من اثنين». انظر: النّزهة ٦٢، وراجع تدريب الراوي ٢/ ١٧٣، والمقنع ٢/ ٤٢٧، حاشية المحقق، ومحاسن الاصطلاح: ٣٨٩، وتوجيه النظر ١/ ١١١.\nأخرجه البخاري في صحيحه ١/ ٢ (١) من حديث عمر بن الخطاب. قال البلقيني في محاسن الاصطلاح: ٣٨٩: «قد تقدم في الشاذ أنّه مما انفرد به عمر - رضي الله عنه -، وعنه علقمة وعن علقمة مُحَمَّد بن إبراهيم، ومثل ذَلِك كيف يمثل للمشهور؟ وجوابه أن المراد ما اشتهر وإن لَمْ يصل نقلته في جَمِيْع المراتب إلى ثلاثة».\nقال البلقيني في المحاسن: ٣٨٩: «المراد ما لَمْ يبلغ رتبة الصحيح».\nللسيوطي جزء لطيف في طرق هذا الحديث، بلغت خمسين طريقًا، وهو مطبوع.\nهذا النص عن أحمد أورده ابن الجوزي في الموضوعات ٢/ ٢٣٦ قال: «ونقلت من خط القاضي أبي يعلى محمد بن الحسين بن الفراء، قال: نقلت من خط أبي حفص البرمكي، قال: سمعت أبا بكر أحمد بن محمد الصيدلاني، يقول: سمعت أبا بكر المروزي يقول: سمعت أبا عبد الله أحمد بن حنبل، يقول ... فذكره."}],[1360,"ويَنقسِمُ مِنْ وَجْهٍ آخَرَ إلى ما هوَ مَشْهورٌ بَيْنَ أهلِ الحديثِ وغيرِهِمْ (٥)، وكَقَولِهِ - صلى الله عليه وآله وسلم -: «الْمُسْلِمُ مَنْ سَلِمَ المسْلِمونَ مِنْ لِسانِهِ ويَدِهِ» (٦)، وأشْباهِهِ، وإلى ما هوَ مَشْهورٌ بَيْنَ أهلِ الحديثِ خاصَّةً دُونَ غيرِهِمْ، كالذي رُوِّيْناهُ عَنْ مُحَمَّدِ بنِ عبدِ اللهِ الأنْصَارِيِّ، عَنْ سُلَيْمانَ التَّيْمِيِّ، عَنْ أبي مِجْلَزٍ (١)، عَنْ أنَسٍ: «أنَّ رَسُولَ اللهِ - صلى الله عليه وآله وسلم - قَنَتَ شَهْرًا بَعدَ الرُّكُوعِ يَدْعُو عَلَى رِعْلٍ (٢)، وذَكْوانَ» (٣). فهذا مَشْهورٌ بَيْنَ أهلِ الحديثِ مُخَرَّجٌ في الصحيحِ، ولهُ رواةٌ عَنْ أَنَسٍ غيرُ أبي مِجْلَزٍ، ورواةٌ (٤) عَنْ أبي مِجْلَزٍ غيرُ التَّيْمِيِّ، ورواةٌ عَنِ التَّيْمِيِّ غيرُ الأنصاريِّ (٥)، ولا يَعلمُ ذَلِكَ إلاَّ أهلُ الصَّنْعَةِ. وأمَّا غيرُهُمْ فَقَدْ يَستغربونَهُ (٦) مِنْ حيثُ إنَّ التَّيْمِيَّ يَرْوي عَنْ أنَسٍ وهوَ هاهنا يَرْوي عَنْ واحدٍ عَنْ أنَسٍ (٧).","",{"fn":"لا أصل له، انظر تذكرة الموضوعات: ١١٦، واللآلئ المصنوعة ٢/ ٧٨.\nبهذا اللفظ أخرجه الخطيب في تاريخه ٨/ ٣٧٠ من طريق العباس بن أحمد المذكر، قال: حَدَّثَنا داود بن علي بن خلف، قال: حَدَّثَنا إسحاق بن إبراهيم الحنظلي، حَدَّثَنا عيسى بن يونس، عن الأعمش، عن شقيق، عن عبد الله. واستنكره وذكر الحمل فيه على المذكر وساقه ابن الجوزي في الموضوعات ٢/ ٢٣٦ بسنده عن شيخه القزاز، عن الخطيب، وانظر تنزيه الشريعة ٢/ ١٨١، واللآلئ ٢/ ٧٨، والأسرار: ٤٨٢.\nلا أصل له، انظر كشف الخفاء ٢/ ٣٩٨.\nأخرجه أحمد ١/ ٢٠١، وأبو داود (١٦٦٥)، والطبراني في الكبير (٢٨٩٣)، والبيهقي ٧/ ٢٣، وابن عبد البر في التمهيد ٥/ ٢٩٦، وأبو نعيم في الحلية ٨/ ٣٧٩ من طريق فاطمة بنت الحسين، عن أبيها مرفوعا، وأخرجه مالك في الموطأ (٢٨٤٦) عن زيد بن أسلم، مرفوعًا: «اعطوا السائل وإن جاء على فرس» قال ابن عبد البر في التمهيد ٥/ ٢٩٤: «لا أعلم في إرسال هذا الحديث خلافا بين رواة مالك وليس في هذا اللفظ مسند صحيح يحتج به فيما علمت».\nوقد يراد بالمشهور ما اشتهر عَلَى الألسنة، وقد أفرد له العلماء مؤلفات، انظرها في الرسالة المستطرفة: ١٩١، ومقدمة المقاصد الحسنة، والمشهور قد يكون صحيحًا، وقد يكون حسنًا أو ضعيفًا أو موضوعًا أو لا أصل له.\nأخرجه أحمد ٢/ ٣٧٩، والترمذي (٢٦٢٧)، والنسائي ٨/ ١٠٤ - ١٠٥، وابن حبان (١٨٠)، والحاكم ١/ ١٠، من حديث أبي هريرة، وقال الترمذي: «حسن صحيح». وأخرجه البخاري ١/ ١٠، ومسلم ١/ ٤٨، والترمذي (٢٥٠٤) و(٢٦٢٨) والنسائي ٨/ ١٠٦ - ١٠٧ من حديث أبي موسى بنحوه."}],[1361,"ومِنَ المشْهُورِ المتواتِرُ الذي يَذْكُرُهُ أهلُ الفقهِ وأُصُولِهِ (٨)، وأهلُ الحديثِ لا يَذْكرُونَهُ باسْمِهِ الخاصِّ الْمُشْعِرِ بِمَعْناهُ الخاصِّ، وإنْ (٩) كانَ الحافِظُ الخطيبُ قدْ ذَكَرَهُ (١٠) ففي كَلامِهِ ما يُشْعِرُ بأنَّهُ اتَّبَعَ فيهِ غيرَ أهلِ الحديثِ، ولَعَلَّ ذَلِكَ لِكَوْنِهِ لا تَشْمَلُهُ صِناعَتُهُمْ ولا يكادُ يوجَدُ في رواياتِهِمْ، فإنَّهُ عبارةٌ عَنِ الخبرِ الذي يَنْقُلُهُ مَنْ يَحْصُلُ العِلْمُ بِصِدْقِهِ ضَرُورةً، ولاَ بُدَّ في إسنادِهِ مِنِ اسْتِمرارِ هذا الشَّرْطِ في رُواتِهِ مِنْ أوَّلِهِ إلى مُنْتَهاهُ (١١).","",{"fn":"بكسر الميم وسكون الجيم وفتح اللام بعدها زاي، وهو لاحق بن حُمَيْد بن سَعيد السّدوسي البصري. التقريب (٧٤٩٠).\nرِعْل - بكسر الراء وسكون العين المهملة -، وذكوان - بفتح الذال المعجمة وسكون الكاف وبعد الألف نون، غير منصرف: هما قبيلتان من سُلَيْم - بضم السين المهملة -. انظر: الصحاح ٤/ ١٧١٠، وعمدة القاري ٧/ ٢٠، وشرح السيوطي عَلَى سنن النسائي ٢/ ٢٠٠.\nصحيح البخاري ٢/ ٣٢ و٥/ ١٣٦. وصحيح مسلم ٢/ ١٣٦. وكذلك أخرجه أحمد ٣/ ١١٦ و٢٠٤، والنسائي ٢/ ٢٠٠ جميعهم من حديث سليمان التيمي، عن أبي مجلز، عن أنس، فذكره.\nفي (م) والتقييد: «رواه» بالهاء وكذا ما بعدها.\nانظر تخريج الروايات في تعليقنا عَلَى شرح التبصرة ٢/ ٣٩٠.\nفي (م): «يستغربون».\nراجع: المحاسن: ٣٩٢، وقارن بما في معرفة علوم الحديث للحاكم: ٩٣ - ٩٤.\nراجع: المحاسن: ٣٩٢، والتقييد: ٢٦٥.\nفي (م): «فإن».\nالكفاية: (٥٠ ت، ١٦ هـ).\nانظر عن موضوع المتواتر: الكفاية (٥٠ ت، ١٦ هـ)، والبرهان ١/ ٣٦٨ فقرة (٤٩١)، والمستصفى ١/ ١٣٢، والمحصول ٢/ ١٠٨، والبحر المحيط ٤/ ٢٣١، ونزهة النظر: ٥٣، وتدريب الراوي ٢/ ١٧٦، مقدمة لقط اللالىء: ١٧، وظفر الأماني: ٣٩، وتوجيه النظر ١/ ١٠٧، ومقدمة نظم المتناثر: ١١. ولا بدّ من الإشارة إلى أنَّ العلماء أفردوا الأحاديث المتواترة بمؤلفات مفردة، مِنْهُم: السيوطي وابن طولون والزبيدي والكتاني وغيرهم. انظر: الرسالة المستطرفة ١٩٤."}],[1362,"ومَنْ سُئِلَ عَنْ إبْرَازِ (١) مِثالٍ لِذَلِكَ فيما يُرْوَى مِنَ الحديثِ أعياهُ تَطَلُّبُهُ، وحديثُ: «إنَّمَا الأعْمالُ بالنِّيَّاتِ» (٢) ليسَ مِنْ ذَلِكَ بِسَبيلٍ، وإنْ نَقَلَهُ عَدَدُ التَّواتُرِ وزِيادَةٌ؛ لأنَّ ذَلِكَ طَرَأَ عليهِ في وَسَطِ إسْنادِهِ ولَمْ يُوجَدْ في أوائِلِهِ عَلَى ما سَبَقَ ذِكْرُهُ."],[1363,"نَعَمْ ... حديثُ: «مَنْ كَذَبَ عليَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ» (٣) نراهُ مِثالًا لِذَلِكَ، فإنَّهُ نَقَلَهُ مِنَ الصَّحَابَةِ - رضي الله عنهم - العَدَدُ الْجَمُّ، وهوَ في \" الصحيحينِ \" مَرْوِيٌّ عَنْ جَماعَةٍ مِنْهُم. وذَكَرَ أبو بَكْرٍ البَزَّارُ (٤) الحافِظُ الجليلُ في \" مُسْنَدِهِ \" أنَّهُ رواهُ عَنْ رَسُولِ اللهِ - صلى الله عليه وآله وسلم - نَحْوٌ مِنْ أربَعِينَ رَجلًا مِنَ الصَّحابةِ. وذَكَرَ بعضُ الْحُفَّاظِ أنَّهُ رواهُ عنهُ - صلى الله عليه وآله وسلم - اثنانِ وستُّونَ نَفْسًا (٥) مِنَ الصحابَةِ، وفيهم العَشَرَةُ المشْهُودُ لهم بالجنَّةِ. قالَ: وليسَ في (٦) الدُّنيا حديثٌ اجْتَمَعَ عَلَى روايتهِ العَشَرَةُ غيرَهُ، ولا يُعْرَفُ حديثٌ يُرْوَى عَنْ أكْثَر مِنْ سِتِّينَ نَفْسًا مِنَ الصَّحابَةِ عَنْ رَسُولِ اللهِ - صلى الله عليه وآله وسلم - إلاَّ هذا الحديثُ الواحِدُ (٧)."],[1364,"قُلْتُ (٨): وبَلَغَ بِهِمْ بعضُ أهلِ الحديثِ أكثرَ مِنْ هذا العَدَدِ، وفي بعضِ ذَلِكَ عَدَدُ التَّواتُرِ. ثُمَّ لَمْ يَزَلْ عدَدُ رواتِهِ في ازْدِيادٍ وهَلُمَّ جَرًّا عَلَى التَّوالِي والاسْتِمرارِ، واللهُ أعلمُ.","",{"fn":"راجع: التقييد والإيضاح: ٢٦٦.\nسَبَقَ تخريجه.\nحديث صحيح متواتر، وقد خرّجناه مفصّلًا في تحقيقنا لشرح التبصرة والتذكرة، ولا بدَّ من الإشارة إلى أن هذا الحديث قد جمع طرقه غير واحد من العلماء مِنْهُم: الحافظ الطبراني، وجزؤه مطبوع.\nانظر: البحر الزخار ٣/ ١٨٨.\nقال ابن الجوزي في الموضوعات ١/ ٥٦: «وقد رواه من الصحابة عن رسول الله - صلى الله عليه وآله وسلم - أحد وستون نفسًا».\nفي (م): «وليس لهم في».\nانظر: الموضوعات ١/ ٥٦، وقد عقّب الحافظ العراقي عَلَى هذا الكلام فقال في شرح التبصرة ٢/ ٣٩٣: «منقوض بحديث المسح عَلَى الخفين، فقد رواه أكثر من ستين من الصحابة، ومنهم العشرة». وانظر: التقييد: ٢٧٠، ومحاسن الاصطلاح: ٣٩٣، والمقنع: ٢/ ٤٣٧.\nفي نسخة (ب): «قال المملي»."}],[1365,"النوع الحادي والثلاثون معرفة الغريب والعزيز من الحديث"],[1366,"(١)"],[1367,"رُوِّيْنا عَنْ أبي عبدِ اللهِ بنِ مَنْدَه الحافِظِ الأصْبانِيِّ أنَّهُ قالَ: «الغريبُ مِنَ الحديثِ، كَحَدِيثِ الزُّهْرِيِّ وَقَتَادةَ وأشْبَاهِهِما مِنَ الأئِمَّةِ مِمَّنْ يُجْمَعُ حديثُهُمْ، إذا انفردَ الرجلُ عَنْهُم بالحديثِ يُسَمَّى غَرِيْبًا. فإذا رَوَى عَنْهُم رجلانِ وثَلاثةٌ واشْتركُوا في حديثٍ يُسَمَّى عَزِيزًا. فإذا رَوَى الجماعَةُ عَنْهُم حديثًا سُمِّي (٢) مَشْهورًا» (٣)."],[1368,"قُلتُ (٤): الحديثُ الذي يَتَفَرَّدُ (٥) بهِ بعضُ الرواةِ يُوصَفُ بالغريبِ، وكذلكَ الحديثُ الذي يَتَفَرَّدُ فيهِ بعضُهُمْ بأمْرٍ لا يذكُرُهُ فيهِ غيرُهُ إمَّا في مَتْنِهِ، وإمَّا في إسْنادِهِ. وليسَ كُلُّ ما يُعَدُّ مِنْ أنواعِ الأفْرادِ مَعْدُودًا مِنْ أنواعِ الغريبِ، كما في الأفرادِ المضافةِ إلى البلادِ عَلَى ما سَبَقَ شَرْحُهُ."],[1369,"ثُمَّ إنَّ الغريبَ ينقسمُ إلى صحيحٍ، كالأفرادِ الْمُخَرَّجَةِ في الصحيحِ، وإلى غيرِ صحيحٍ وذَلِكَ هوَ الغالِبُ عَلَى الغرائِبِ. رُوِّيْنا عَنْ أحمدَ بنِ حَنْبَلٍ - رضي الله عنه - أنَّهُ قالَ غيرَ مَرَّةٍ: «لا تَكْتُبُوا هذهِ الأحاديثَ الغرائبَ فإنَّها مَنَاكِيرُ وعَامَّتُها عَنِ الضُّعَفاءِ» (٦).","",{"fn":"انظر في معرفة الغريب والعزيز: معرفة علوم الحديث: ٩٤ - ٩٦ وجامع الأصول ١/ ١٧٤ - ١٧٨، والإرشاد ٢/ ٥٤٥ - ٥٤٩، والتقريب: ١٥٣ - ١٥٥، والاقتراح: ٣٠٩ - ٣١٠، والموقظة: ٤٣، واختصار علوم الحديث: ١٦٦ - ١٦٧، والشذا الفياح ٢/ ٤٤٦ - ٤٥٠، والمقنع ٢/ ٤٤١ - ٤٤٢، وفتح الباقي ٢/ ٢٦٥ - ٢٧٧، ونزهة النظر: ٦٤ - ٧١، وطبعة عتر ٢٤ - ٢٨، وفتح المغيث ٣/ ٢٧ - ٤١، وتدريب الراوي ٢/ ١٨٠ - ١٨٣، وتوضيح الأفكار ٢/ ٤٠١ - ٤١١، وظفر الأماني: ٦٨ - ٧٦.\nفي (ب): «يسمى».\nذكره الحافظ ابن طاهر المقدسي في شروط الأئمة: ٢٣. وانظر: شرح التبصرة ٢/ ٣٧٩ وتعليقنا عليه.\nفي (أ): «قال الشَّيْخ - رضي الله عنه -».\nفي (م) والشذا: «ينفرد».\nأخرجه ابن عدي في مقدمة الكامل ١/ ١١١، وابن السمعاني في أدب الإملاء: ٥٨، ونحوه في الكفاية: (٢٢٤ ت، ١٤١ هـ)، ونحو قول الإمام أحمد عن كثير من العلماء، انظر: الجامع ٢/ ١٠٠ - ١٠١، والكفاية: (٢٢٣ - ٢٢٧ ت، ١٤٠ - ١٤١ هـ)، والمحدّث الفاصل: ٥٦١ - ٥٦٥."}],[1370,"ويَنْقَسِمُ الغريبُ أيضًا مِنْ وجهٍ آخَرَ، فمنهُ ما هُوَ غريبٌ (١) مَتْنًا وإسْنادًا وهوَ الحديثُ الذي تَفَرَّدَ بروايةِ مَتْنِهِ راوٍ واحدٌ."],[1371,"ومنهُ ما هوَ غريبٌ إسْنادًا لا مَتْنًا كالحديثِ الذي مَتْنُهُ مَعروفٌ مَرْوِيٌّ عَنْ جَمَاعةٍ مِنَ الصَّحابةِ إذا تَفَرَّدَ (٢) بعضُهُمْ بروايتِهِ عَنْ صَحَابِيٍّ آخَرَ كانَ غَريبًا مِنْ ذلكَ الوجهِ معَ أنَّ مَتْنَهُ غيرُ غريبٍ. ومِنْ ذَلِكَ غرائبُ الشُّيُوخِ في أسانيدِ المتونِ الصحيحةِ (٣). وهذا الذي يَقُولُ فيهِ التِّرْمِذِيُّ: «غريبٌ مِنْ هذا الوجْهِ». ولا أرى هذا النوعَ يَنْعَكِسُ، فلا يُوجدُ إذَنْ ما هوَ غريبٌ مَتْنًا وليسَ غريبًا إسْنادًا إلاَّ إذا اشْتَهَرَ الحديثُ الفَرْدُ عَمَّنْ تَفَرَّدَ بهِ فرَواهُ عنهُ عددٌ كثيرونَ فإنَّهُ يَصِيرُ غريبًا مَشْهُورًا، وغريبًا مَتْنًا وغيرَ غريبٍ إسْنادًا لكنْ بالنَّظَرِ إلى أحدِ طَرَفَي الإسنادِ، فإنَّ إسنادَهُ مُتَّصِفٌ بالغرابةِ في طَرَفِهِ الأوَّلِ مُتَّصِفٌ بالشُّهْرَةِ في طَرَفِهِ الآخَرِ، كحَديثِ: «إنَّمَا الأعْمالُ بالنِّيَّاتِ» (٤)، وكسَائِرِ الغرائِبِ التي اشْتَمَلَتْ عليها التَّصَانيفُ المشْتَهرَةُ (٥)، واللهُ أعلمُ."],[1372,"النوع الثاني والثلاثون معرفة غريب الحديث"],[1373,"وهوَ عِبارةٌ عَمَّا وَقَعَ في مُتُونِ الأحاديثِ مِنَ الألفاظِ الغامِضَةِ البَعيدةِ مِنَ الفَهْمِ لِقِلَّةِ اسْتِعْمالِها."],[1374,"هذا فَنٌّ مُهِمٌّ يَقْبُحُ جَهْلُهُ بأهلِ الحديثِ خاصَّةً ثُمَّ بأهلِ العِلْمِ عامَّةً، والخوضُ فيهِ ليسَ بالْهَيِّنِ، والخائِضُ فيهِ حَقِيْقٌ بالتَّحَرِّي جديرٌ بالتَّوَقِّي. رُوِّيْنا عَنِ الميْمُونِيِّ، قالَ:","",{"fn":"انظر: التقييد والإيضاح: ٢٧٣.\nفي (ب): «انفرد».\nانظر: محاسن الاصطلاح: ٣٩٦.\nسَبَقَ تخريجه.\nفي (أ): «المشهرة»، وفي (م): «المشهورة»."}],[1375,"سُئِلَ أحمدُ بنُ حَنْبَلٍ عَنْ حَرْفٍ مِنْ غريبِ الحديثِ، فقالَ: «سَلُوا أصْحابَ الغريبِ، فإنِّي أكرَهُ أنْ أتَكَلَّمَ في قَوْلِ رَسُولِ اللهِ - صلى الله عليه وآله وسلم - بالظَّنِّ فأُخْطِئَ (١») (٢)."],[1376,"وبَلَغَنا عَنِ التَّارِيخِيِّ مُحَمَّدِ بنِ عبدِ الملكِ، قالَ: حَدَّثَني أبو قِلابةَ عبدُ الملكِ بنُ مُحَمَّدٍ، قالَ: قُلْتُ للأصْمَعِيِّ: «يا أبا سَعِيْدٍ مَا مَعْنَى قَولِ رَسُولِ اللهِ - صلى الله عليه وآله وسلم -: «الجارُ أحَقُّ بِسَقَبِهِ» (٣)، فقالَ: أنا لا أُفَسِّرُ حديثَ رسُولِ اللهِ - صلى الله عليه وآله وسلم - ولَكِنَّ العَرَبَ تَزعُمُ أنَّ السَّقَبَ: اللَّزِيقُ» (٤). ثُمَّ إنَّ غيرَ واحدٍ مِنَ العلماءِ صَنَّفُوا في ذَلِكَ فأحْسَنوا."],[1377,"ورُوِّيْنا (٥) عَنِ الحاكِمِ أبي عبدِ اللهِ الحافِظِ قالَ: «أوَّلُ مَنْ صَنَّفَ الغريبَ في الإسلامِ النَّضْرُ بنُ شُمَيْلٍ» (٦). ومِنْهُم مَنْ خالَفَهُ فقالَ: «أوَّلُ مَنْ صَنَّفَ فيهِ أبو عُبَيْدَةَ مَعْمَرُ بنُ المثَنَّى»، وكتابَاهُما صَغِيرانِ (٧). وصَنَّفَ بعدَ ذَلِكَ أبو عُبَيْدٍ القاسِمُ بنُ سَلاَّمٍ كِتابَهُ المشهورَ فَجَمَعَ وأجادَ واسْتَقْصَى فَوَقَعَ مِنْ أهلِ العِلْمِ بِمَوْقِعٍ جَلِيلٍ، وصَارَ قُدْوَةً في هذا الشَّأْنِ. ثُمَّ تَتَبَّعَ القُتَبِيُّ (٨) ما فاتَ أبا عُبَيدٍ فوضَعَ فيهِ كِتابَهُ المشهورَ ثُمَّ تَتَبَّعَ أبو سُلَيْمانَ الخطَّابِيُّ ما فاتَهُما فوضَعَ في ذَلِكَ كِتابَهُ المشهورَ.","",{"fn":"انظر: العلل للإمام أحمد برواية المروذي: ٢١٧ رقم (٤١٣).\nفي (جـ) و(م): «فسأخطئ».\nأخرجه الحميدي (٥٥٢)، وأحمد ٦/ ١٠ و٣٩٠، والبخاري ٣/ ١١٥ و٩/ ٣٥ و٣٦ و٣٧، وأبو داود (٣٥١٦)، وابن ماجه (٢٤٩٥)، والنسائي ٧/ ٣٢٠ والبغوي ٨/ ٢٤٢ من حديث أبي رافع. وأخرجه ابن أبي شيبة ٧/ ١٦٨، وأحمد ٤/ ٣٨٩ و٣٩٠، وابن ماجه (٢٤٩٦)، والنسائي ٧/ ٣٢٠، والطحاوي ٤/ ٣٢٤، والدارقطني ٤/ ٢٢٤، وابن الجارود (٦٤٥)، والبيهقي ٦/ ١٠٥ من حديث الشريد بن سويد. وجاء في بعض ألفاظ الحديث: «بصقبه» بالصاد وهما بمعنىً؛ قَالَ ابن الأثير في النهاية ٢/ ٣٧٧: «السقب بالسين والصاد في الاصل: القرب، يقال: سقبت الدار وأسقبت، أي: قربت».\nانظر: شرح السنة ٨/ ٢٤٢.\nفي (م): «روينا» بلا واو.\nمعرفة علوم الحديث: ٨٨.\nانظر: شرح التبصرة والتذكرة ٢/ ٣٩٦ - ٣٩٧.\nفي (أ) و(ب) و(م) والشذا والتقييد: «القتيبي». وقُتَيْبَةُ: هِيَ تصغير قِتيبة - بكسر القاف - وَهِيَ واحدة الأقتاب، والأقتاب: الأمعاء، وبها سمّي الرجل، والنِّسبة إليه قُتَبِيّ - بضم القاف وفتح التاء المنقوطة من فوقها باثنتين وكسر الباء المنقوطة بواحدة - والمراد به أبو أحمد، عبد الله بن مسلم بن قتيبة الدِّينوري. انظر: الأنساب ٤/ ٤٣١، ووفيات الأعيان ٣/ ٤٤، وسير أعلام النبلاء ١٣/ ٢٩٦."}],[1378,"فهذهِ الكُتُبُ الثلاثَةُ أُمَّهاتُ الكُتُبِ المؤَلَّفَةِ في ذَلِكَ (١). وورَاءها مَجامِعُ تَشتملُ من ذَلِكَ عَلَى زوائدَ وفوائدَ كثيرةٍ ولا يَنبغي أنْ يُقَلِّدَ منها إلاَّ ما كانَ مُصَنِّفُوها أئِمَّةً جِلَّةً."],[1379,"وأَقْوَى ما يُعْتَمدُ عليهِ في تفسيرِ غريبِ الحديثِ: أنْ يُظْفَرَ بهِ مُفَسَّرًا في بعضِ رِواياتِ الحديثِ، نحوُ ما رُوِيَ في حديثِ ابنِ صَيَّادٍ (٢) أنَّ النبيَّ - صلى الله عليه وآله وسلم - قالَ لهُ: «قَدْ خَبَأْتُ لكَ (٣) خَبِيئًا، فما هوَ؟ قالَ: الدُّخُّ» (٤). فهذا خَفِيَ مَعْناهُ وأعضَلَ. وفَسَّرَهُ قومٌ بِمَا لا يَصِحُّ. وفي \"معرفةِ علومِ الحديثِ\" للحاكِمِ أنَّهُ الدُّخُّ بمعنى الزَّخِّ (٥) الَّذِي هوَ الجِماعُ (٦)، وهذا تَخْلِيطٌ فاحِشٌ يُغِيْظُ العَالِمَ والمؤمِنَ (٧) وإنَّما مَعْنى الحديثِ أنَّ النبيَّ - صلى الله عليه وآله وسلم - قالَ لهُ: قدْ أضْمَرْتُ لكَ ضَمِيرًا، فما هوَ؟ فقالَ الدُّخُّ -بضمِّ الدالِ (٨) - يَعْنِي: الدُّخَانَ، والدُّخُّ: هوَ الدُّخَانُ في لُغَةٍ (٩)، إذْ في بعضِ رواياتِ الحديثِ ما نَصُّهُ: ثُمَّ قالَ رسُولُ اللهِ - صلى الله عليه وآله وسلم -:"],[1380,"«إنِّي قَدْ خَبَأْتُ لكَ خَبِيئًا، وخَبَأَ لهُ: ﴿يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِيْنٍ﴾ (١٠). فقالَ ابن صَيَّادٍ: هوَ الدُّخُّ، فقالَ رسولُ اللهِ - صلى الله عليه وآله وسلم -: «اخْسَأْ، فَلَنْ تَعْدُوَ قَدْرَكَ». وهذا ثابتٌ صحيحٌ خَرَّجَهُ التِّرمِذِيُّ (١) وغيرُهُ (٢)، فَأَدْرَكَ ابنُ صَيَّادٍ مِنْ ذَلِكَ هذهِ الكَلِمَةَ فَحَسْبُ، عَلَى عادةِ الكُهَّانِ في اخْتِطافِ بعضِ الشيءِ مِنَ الشَّيَاطِينِ مِنْ غيرِ وُقُوفٍ عَلَى تمامِ البيانِ. ولهذا قالَ لهُ: «اخْسَأْ، فَلَنْ تَعْدُوَ قَدْرَكَ»، أي: فلا مَزِيدَ لكَ عَلَى قَدْرِ إدْراكِ","",{"fn":"وهذه الأمهات مطبوعة متداولة.\nويقال له: «ابن صائد» أيضًا. انظر: الإصابة ٣/ ١٣٣.\nفي (م): «خبيئًا لك».\nصحيح البخاري ٨/ ٤٩ (١٣٥٤) و(١٣٥٥)، وصحيح مسلم ٨/ ١٨٩ (٢٩٣٠) من حديث ابن عمر.\nفي (م): «الذخ» بالذال المعجمة.\nهو في مخطوطة معرفة علوم الحديث للحاكم (الورقة: ٨٢) من نسحتنا الخطية الخاصة، وقد سقط من موضعه في المطبوعة: ٩١. وكثرة هذه السقوطات في هذا الكتاب جعلتنا نأخذ عَلَى عاتقنا إعادة طبعه محقّقًا تحقيقًا علميًا رصينًا رضيًا - يسّر الله إتمامه وطبعه -.\nانظر: تعقّب الحافظ العراقي عَلَى الحاكم في شرح التبصرة ٢/ ٤٠٤، وانظر: تاج العروس ٧/ ٢٤٩.\nوبفتحهما أيضًا. انظر: النهاية ٢/ ١٠٧، واللسان ٣/ ١٤، والتاج ٧/ ٢٤٨.\nانظر: الصحاح ١/ ٤٢٠، والمقاييس ٢/ ٢٦٦.\nالدخان: ١٠."}],[1381,"الكُهَّانِ (٣)، واللهُ أعلمُ."],[1382,"النَّوْعُ الثَّالِثُ والثَّلاَثُونَ"],[1383,"مَعْرِفَةُ الْمُسَلْسَلِ (٤) مِنَ الْحَدِيْثِ"],[1384,"التَّسَلْسُلُ مِنْ نُعوتِ الأسانيدِ: وهو عبارةٌ عَنْ تتَابُعِ رجالِ الإسنادِ وتوارُدِهِمْ فيهِ، واحدًا بعدَ واحدٍ، عَلَى صِفَةٍ أو حالَةٍ واحدةٍ.","",{"fn":"جامع الترمذي (٢٢٤٩)، وقال في (٢٢٣٥): «حسن صحيح».\nأخرجه عبد الرزاق (٢٠٨١٧)، وأحمد ٢/ ١٤٨ و١٤٩، والبخاري ٢/ ١١٧ (١٣٥٤) و٤/ ٨٥ (٣٠٥٥) و٨/ ٤٩ (٦١٧٣) و١٥٧ (٦٦١٨)، وفي الأدب المفرد (٩٥٨) ومسلم ٨/ ١٩٢ (٢٩٣٠) و١٩٣ (٢٩٣٠) (٩٦) (٩٧)، وأبو داود (٤٣٢٩)، وابن حبان (٦٧٩٤)، والطبراني في الأوسط (٩٢٧٦)، وابن منده في الإيمان (١٠٤٠)، والبغوي (٤٢٧٠).\nراجع: محاسن الاصطلاح ٤٠٠.\nانظر في المسلسل: معرفة علوم الحديث: ٢٩ - ٣٤، والإرشاد ٢/ ٥٥٤ - ٥٥٨، والتقريب: ١٥٥ - ١٥٦، والاقتراح: ٢٠١ - ٢٠٥، والموقظة: ٤٣ - ٤٤، واختصار علوم الحديث: ١٦٨ - ١٦٩ والشذا الفياح ٢/ ٤٥٦ - ٤٥٩، والمقنع ٢/ ٤٤٧ - ٤٤٩، وشرح التبصرة والتذكرة ٢/ ٤٠٥، ونزهة النظر (١٦٧) وطبعة عتر: ٦٤ - ٦٥، وفتح المغيث ٣/ ٥٣ - ٥٨، وتدريب الراوي ٢/ ١٨٧ - ١٨٩، وشرح السيوطي عَلَى ألفية العراقي: ١٥٨، وفتح الباقي ٢: ٢٨٤ - ٢٨٩، وتوضيح الأفكار ٢/ ٤١٤ - ٤١٦، وظفر الأماني: ٢٨٧ - ٣٢٣. والمسلسل: اسم مفعول، يقال: سلسل الأشياء، وصل بعضها ببعض، كأنها سلسلة، والماء ونحوه: صَبَّهُ شيئًا فَشيئًا في حدور واتصال، وتسلسل: تتابع، يقال: تسلسل الماءُ: جرى في حدور واتصال، وشيء مسلسل متصل بعضه ببعض. انظر: المقاييس ٣/ ٦٠، واللسان ١١/ ٣٤٥، والمعجم الوسيط ١/ ٤٤٢."}],[1385,"ويَنْقَسِمُ ذَلِكَ إلى ما يكونُ صِفَةً للروايةِ والتَّحَمُّلِ، وإلى ما يكونُ صِفَةً للرواةِ أو حالةً لهم. ثُمَّ إنَّ صِفَاتِهِمْ في ذَلِكَ وأحْوالَهُمْ أقْوالًا وأفْعَالًا ونَحْوَ ذَلِكَ تَنْقِسِمُ إلى ما لا نُحْصِيهِ. ونَوَّعَهُ الحاكِمُ أبو عبدِ اللهِ الحافِظُ إلى ثَمَانِيَةِ أنواعٍ (١) والذي ذَكَرَهُ فيها إنَّما هوَ صُورٌ وأمْثِلَةٌ ثَمانِيَةٌ. ولا انْحِصارَ لِذَلِكَ في ثَمانيةٍ كما ذَكَرْناهُ (٢)."],[1386,"ومِثَالُ ما يَكونُ صِفَةً للرِّوايةِ والتَّحَمُّلِ ما يَتَسَلْسَلُ بـ: سَمِعْتُ فلانًا قالَ: سَمِعْتُ فلانًا إلى آخِرِ الإسنادِ. أو يَتَسَلْسَلُ (٣) بـ: حَدَّثَنا أو أخْبَرَنا إلى آخِرِهِ، ومِنْ ذَلِكَ أخْبَرَنا واللهِ فُلانٌ، قالَ: أخْبَرَنا واللهِ فُلانٌ إلى آخِرِهِ."],[1387,"ومِثَالُ ما يَرْجِعُ إلى صِفاتِ الرواةِ وأقْوالِهِمْ ونحْوِها إسْنادُ حديثِ: «اللَّهُمَّ أعِنِّي عَلَى شُكْرِكَ وذِكْرِكَ وحُسْنِ عِبَادَتِكَ» (٤)، الْمُتَسَلْسِلُ بِقَوْلِهِمْ: إنِّي أُحِبُّكَ فَقُلْ، وحديثُ التَّشْبِيْكِ باليَدِ (٥)، وحديثُ العَدِّ في اليَدِ (٦)، في أشْباهٍ لِذَلِكَ نَرْوِيْها وتُرْوَى كَثِيرةً، وخيرُها ما كانَ فيهِ دلالةٌ عَلَى اتِّصَالِ السَّماعِ وعدمِ التَّدْلِيسِ."],[1388,"ومِنْ فَضيلةِ التسَلْسُلِ اشْتِمالُهُ عَلَى مَزيدِ الضَّبْطِ مِنَ الرواةِ، وقَلَّما تَسْلَمُ المسَلْسَلاتُ مِنْ ضَعْفٍ، أعْنِي: في وَصْفِ التَّسَلْسُلِ لا في أصلِ المتنِ. ومِنْ المسَلْسَلِ ما يَنْقَطِعُ تَسَلْسُلُهُ في وسَطِ إسْنادِهِ وذَلِكَ نَقْصٌ فيهِ وهوَ كالمسَلْسَلِ بأوَّلِ حديثٍ سَمِعْتُهُ (١) عَلَى ما هوَ الصَّحيحُ في ذَلِكَ، واللهُ أعلمُ.","",{"fn":"معرفة علوم الحديث: ٢٩.\nجملة: «ولا انحصار لذلك في ثمانية كما ذكرناه» سقطت من (م).\nفي (م): «ليسلسل».\nأخرجه أحمد ٥/ ٢٤٤ و٢٤٧، وأبو داود (١٥٢٢)، والنسائي ٣/ ٥٣، وفي الكبرى ... (١٢٢٦) (٩٩٣٧) وفي عمل اليوم والليلة (١٠٩) من طريق حيوة بن شريح، قال: سمعت عقبة بن مسلم، قال: حدثني أبو عبد الرحمان الحُبُلي، عن الصنابحي، عن معاذ بن جبل، به وفي آخره: «وأوصى بذلك معاذٌ الصنابحيَّ، وأوصى الصنابحيُّ أبا عبد الرحمان، وأوصى أبو عبد الرحمان عقبةَ بن مسلم».\nمخرج في شرح التبصرة والتذكرة ٢/ ٤٠٦ هـ (٥).\nأخرجه الحَاكِم في معرفة علوم الحديث: ٣٢ - ٣٣."}],[1389,"النوع الرابع والثلاثون معرفة ناسخ الحديث ومنسوخه"],[1390,"(٢)"],[1391,"هذا فَنٌّ مُهِمٌّ مُسْتَصْعَبٌ. رُوِّيْنا عَنِ الزُّهْرِيِّ - رضي الله عنه - أنَّهُ قالَ: «أعْيا الفُقَهاءَ وأعْجَزَهُمْ أنْ يَعْرِفُوا ناسِخَ حديثِ رسُولِ اللهِ - صلى الله عليه وآله وسلم - مِنْ مَنْسُوخِهِ» (٣).","",{"fn":"هو حديث عبد الله بن عمرو: «الراحمون يرحمهم الرحمان ... الخ»، قال الحافظ العراقي في شرح التبصرة والتذكرة ٢/ ٤١٣: وقد وقع لنا - بإسناد متصل - التسلسل إلى آخره، ولا يصح ذلك». وقد رواه مسلسلًا اللكنوي في ظفر الأماني ٢٨٧ - ٢٨٨ من طريق الحافظ العراقي. وقد أخرجه بدون التسلسل الحميدي (٥٩١) و(٥٩٢)، وابن أبي شيبة ٨/ ٣٨٨، وأحمد ٢/ ١٦٠، والبخاري في تاريخه الكبير ٩/ ٦٤ (٥٧٤)، وأبو داود (٤٩٤١)، والحاكم ٤/ ١٥٩، والبيهقي ٩/ ٤١، والخطيب في تاريخه ٣/ ٢٦٠ و٤٣٨ جميعهم من طريق سفيان، عن عمرو بن دينار، عن أبي قابوس، عن عبد الله بن عمرو، قال: قال رسول الله - صلى الله عليه وآله وسلم -: «الراحمون يرحمهم ... الحديث». ولا بد من الإشارة إلى أن كثيرًا من الحفاظ قد أفردوا هذا الحديث بجزء مفرد. انظر من ذلك المجلس الأول من مجالس ابن ناصر الدين الدمشقي.\nانظر فيه: معرفة علوم الحديث: ٨٥ - ٨٨، وجامع الأصول ١/ ١٤٥ - ١٥٢، والإرشاد ٢/ ٥٥٩ - ٥٦٥، والتقريب: ١٥٧ - ١٥٨، واختصار علوم الحديث: ١٦٩ - ١٧٠، والشذا الفياح ٢/ ٤٦٠ - ٤٦٦، والمقنع ٢/ ٤٥٠ - ٤٦٨، شرح التبصرة والتذكرة ٢/ ٤١٤، نزهة النظر: ١٠٥ - ١٠٦، وطبعة عتر: ٣٩، وفتح المغيث ٣/ ٥٩ - ٦٦، وتدريب الراوي ٢/ ١٨٩ - ١٩٢، وشرح السيوطي عَلَى ألفية العراقي: ١٦١، وفتح الباقي ٢/ ٢٨٩ - ٢٩٥، وتوضيح الأفكار ٢/ ٤١٦ - ٤١٩. قال الحافظ العراقي في شرح التبصرة والتذكرة ٢/ ٤١٤: «النسخ يطلق لغة عَلَى الإزالة، وعلى التحويل. وأما نسخ الأحكام الشرعية، وهو المحدود هنا فهو عبارة عن رفع الشارع حكمًا من أحكامه سابقًا، بحكم من أحكامه لاحق». ثُمَّ شرع في شرح هذا التعريف، فراجعه. وانظر عن معاني النسخ اللغوية: الصحاح ١/ ٤٣٣، وتاج العروس ٧/ ٣٥٥.\nأخرجه ابن شاهين في ناسخ الحديث ومنسوخه (٣)، والحازمي في الاعتبار: ١٨."}],[1392,"وكَانَ للشَّافِعِيِّ - رضي الله عنه - فيهِ يَدٌ طُولَى وسَابِقَةٌ أُوْلَى. رُوِّيْنا عَنْ مُحَمَّدِ بنِ مُسْلِمِ بنِ وارَةَ (١) - أحَدِ أئِمَّةِ الحديثِ - أنَّ أحمدَ بنَ حَنْبَلٍ قالَ لهُ وقدْ قَدِمَ مِنْ مِصْرَ (٢): «كَتَبْتَ كُتُبَ الشَّافِعِيِّ؟ فقالَ: لا. قالَ فَرَّطْتَ، ما عَلِمْنا المجْمَلَ مِنَ المفَسَّرِ ولا ناسِخَ حديثِ رسُولِ اللهِ - صلى الله عليه وآله وسلم - مِنْ مَنْسُوخِهِ حَتَّى جَالَسْنا الشَّافِعِيَّ»."],[1393,"وفيمَنْ عَانَاهُ مِنْ أهلِ الحديثِ مَنْ أدخَلَ فيهِ ما ليسَ منهُ لِخَفاءِ مَعْنَى النَّسْخِ وشَرْطِهِ. وهوَ عبارةٌ عَنْ رَفْعِ الشَّارِعِ حُكْمًا منهُ مُتَقَدِّمًا بِحُكْمٍ منهُ مُتَأَخِّرٍ (٣). وهذا حَدٌّ وَقَعَ لنا سالِمٌ مِنِ اعْتِراضاتٍ وَرَدَتْ عَلَى غيرِهِ (٤)."],[1394,"ثُمَّ إنَّ ناسِخَ الحديثِ ومَنْسُوخِهِ يَنْقَسِمُ أقْسَامًا:"],[1395,"فمِنْها ما يُعْرَفُ بِتَصْرِيحِ رَسُولِ اللهِ - صلى الله عليه وآله وسلم - بهِ. كَحَدِيثِ بُرَيْدَةَ (٥) الذي أخرجَهُ مُسْلِمٌ في \" صَحِيْحِهِ \"؛ أنَّ رسُولَ اللهِ - صلى الله عليه وآله وسلم - قالَ: «كُنْتُ نَهَيْتُكُمْ عَنْ زِيارَةِ القُبُورِ، فَزُورُوها» (٦) في أشْباهٍ لِذَلِكَ.","",{"fn":"ترجمته في تاريخ دمشق ٥٥/ ٣٨٨، والسير ١٣/ ٢٨.\nأخرجه أبو نعيم في الحلية ٩/ ٩٧، والحازمي في الاعتبار: ٣.\nقال العراقي في التقييد والإيضاح: ٢٨٧: «هذا الذي حده به المصنف، تبع فيه القاضي أبا بكر الباقلاني، فإنه حده برفع الحكم واختاره الآمدي وابن الحاجب قال الحازمي: وقد أطبق المتأخرون عَلَى ما حده به القاضي أنه الخطاب الدال عَلَى ارتفاع الحكم الثابت بالخطاب المتقدم عَلَى وجه لولاه لكان ثابتًا مع تراخيه عنه، قال الحازمي: وهذا حدٌ صحيح ... انتهى. وقد اعترض عليه بأن التعبير برفع الحكم ليس بجيد؛ لأن الحكم قديم لا يرتفع، والجواب عنه أنَّهُ إنما المراد برفع الحكم قطع تعلقه بالمكلف، واعترض صاحب المحصول أيضًا عَلَى هذا الحد بأوجه أخر في كثير منها نظر ليس هذا موضع إيرادها». وانظر: البحر المحيط ٤/ ٦٥، والاعتبار: ٥.\nاعترض ابن الملقن عَلَى هذا التعريف بعدة اعتراضات، ينظر: المقنع ٤/ ٤٥١ - ٤٥٢.\nهو بريدة بن الحُصَيْب -بمهملتين- مصغرًا، أبو سَهْل الأسلمي صَحابي أسلم قبل بدر. التقريب (٦٦٠).\nصحيح مسلم ٣/ ٦٥ (٩٧٧) و٦/ ٨٢ (١٩٧٧) (٣٧) و٦/ ٩٨ (٩٧٧) (٦٣)، وانظر تفصيل تخريجه في شرح التبصرة ٢/ ٤١٧."}],[1396,"ومنها ما يُعْرَفُ بِقَوْلِ الصَّحَابِيِّ، كما رَواهُ التِّرْمِذِيُّ (١) وغيرُهُ عنْ أُبَيِّ بنِ كَعْبٍ أنَّهُ قالَ: «كانَ الماءُ مِنَ الماءِ رُخْصَةً في أوَّلِ الإسلامِ ثُمَّ نُهِيَ عنها»، وكما خَرَّجَهُ النَّسَائِيُّ (٢) عَنْ جابِرِ بنِ عبدِ اللهِ قالَ: «كانَ آخِرَ الأمْرينِ مِنْ رسولِ اللهِ - صلى الله عليه وآله وسلم - تَرْكُ الوضوءِ مِمَّا مَسَّتِ النَّارُ» في أشْباهٍ لِذَلِكَ."],[1397,"ومنها ما عُرِفَ بالتَّاريخِ، كحديثِ شَدَّادِ بنِ أوْسٍ وغيرِهِ، أنَّ رسول اللهِ - صلى الله عليه وآله وسلم - قالَ: «أفْطَرَ الحاجِمُ والمحْجُومُ» (٣)، وحديثُ ابنِ عبَّاسٍ: «أنَّ النبيَّ - صلى الله عليه وآله وسلم - احْتَجَمَ وهوَ صَائِمٌ» (٤)، بَيَّنَ (٥) الشَّافِعِيُّ أنَّ الثَّانيَ ناسِخٌ للأوَّلِ مِنْ حيثُ إنَّهُ رُوِيَ في حديثِ شَدَّادٍ أنَّهُ كانَ مَعَ النبيِّ - صلى الله عليه وآله وسلم - زَمانَ الفَتْحِ فَرَأَى رَجُلًا يَحْتَجِمُ في شَهْرِ رَمَضَانَ فقالَ: «أفْطَرَ الحاجِمُ والمحْجُومُ». ورُوِيَ في حديثِ ابنِ عبَّاسٍ أنَّهُ - صلى الله عليه وآله وسلم - احْتَجَمَ وهوَ مُحْرِمٌ صَائِمٌ؛"],[1398,"فبانَ بذلكَ أنَّ الأوَّلَ كانَ زَمَنَ الفَتْحِ في سنةِ ثَمانٍ، والثَّاني في حِجَّةِ الوداعِ في"],[1399,"سَنَةِ عَشْرٍ.","",{"fn":"جامع الترمذي (١١٠)، وأخرجه الشافعي ١/ ٣٥ و٣٦، وأحمد ٥/ ١١٥ و١١٦، والدارمي (٧٦٥) و(٧٦٦)، وابن ماجه (٦٠٩)، وابن خزيمة (٢٢٥) و(٢٢٦)، وابن الجارود (٩١)، والطحاوي ١/ ٧، وابن حبان (١١٧٣) و(١١٧٩)، والطبراني في الكبير (٥٣٨)، والدارقطني ١/ ١٢٦، والبيهقي ١/ ١٦٥.\nسنن النسائي ١/ ١٠٨، وأخرجه أبو داود (١٩٢)، وابن خزيمة (٤٣).\nأخرجه أحمد ٤/ ١٢٣ و١٢٤، والدارمي (١٧٣٧)، وأبو داود (٢٣٦٨) و(٢٣٦٩)، وابن ماجه (١٦٨١)، والنسائي في الكبرى (٣١٣٨) و(٣١٥٥).\nأخرجه الشافعي ١/ ٢٥٥، والطيالسي (٢٧٠٠)، وعبد الرزاق (٧٥٤١)، والحميدي (٥٠١)، وعلي بن الجعد (١٠٤)، وابن أبي شيبة ٣/ ٥١، وأحمد ١/ ٢١٥ و٢٢٢، وأبو داود (٢٣٧٣)، والترمذي (٧٧٧)، وأبو يعلى (٢٤٧١)، والطحاوي ٢/ ١٠١، والطبراني (١٢١٣٧)، والدارقطني ٢/ ٢٣٩، والبيهقي ٤/ ٢٦٣. وانظر: التعليق على جامع الترمذي ٢/ ١٣٩.\nفي (ب): «ثم بيّن»، وفي (م): «فبيّن»."}],[1400,"ومنها ما يُعْرَفُ بالإجماعِ كَحديثِ: قَتْلِ شَارِبِ الخمْرِ في المرَّةِ الرَّابِعةِ (١) فإنَّهُ منسوخٌ عُرِفَ نَسْخُهُ بانْعِقادِ الإجماعِ عَلَى ترْكِ العَمَلِ (٢) بهِ. والإجماعُ لا يَنْسَخُ ولا يُنْسَخُ (٣) ولكنْ يَدلُّ عَلَى وجودِ ناسِخٍ غيرِهِ (٤)، واللهُ أعلمُ بالصَّوابِ (٥)."],[1401,"النَّوْعُ الْخَامِسُ والثَّلاَثُونَ"],[1402,"مَعْرِفَةُ الْمُصَحَّفِ (٦) مِنْ أسَانِيْدِ الأَحَادِيْثِ ومُتُونِهَا"],[1403,"هذا فَنٌّ جليلٌ إنَّما يَنْهَضُ بأعْبائِهِ الْحُذَّاقُ مِنَ الحفَّاظِ، والدارقطنيُّ مِنْهُم، ولهُ فيهِ تَصْنِيْفٌ مُفِيْدٌ. ورُوِّيْنا عَنْ أبي عبدِ اللهِ أحمدَ بنِ حَنْبَلٍ - رضي الله عنه - أنَّهُ قالَ: «ومَنْ يَعْرَى مِنَ الخطأِ والتَّصْحيفِ!؟».","",{"fn":"مخرج بتوسع في كتاب شرح التبصرة ٢/ ٤١٩.\nفي (ب): «العلم».\nلَمْ ترد في (أ) و(ب).\nراجع: محاسن الاصطلاح ٤٠٨.\n«بالصواب» لم ترد في (ب).\nانظر في هذا: معرفة علوم الحديث: ١٤٦ - ١٥٢، والإرشاد ٢/ ٥٦٦ - ٥٧٠ والتقريب: ١٥٨ - ١٥٩، واختصار علوم الحديث: ١٧٠ - ١٧٤، والشذا الفياح ٢/ ٤٦٧ - ٤٧٠، والمقنع ٢/ ٤٦٩ - ٤٧٩، وشرح التبصرة والتذكرة ٢/ ٤٢٢ - ٤٣١، ونزهة النظر: ١٢٧ - ١٢٨، وطبعة عتر: ٤٩، وفتح المغيث ٣/ ٦٧ - ٧٤، وتدريب الراوي ٢/ ١٩٣ - ١٩٥، وشرح السيوطي عَلَى ألفية العراقي: ١٥٦، وفتح الباقي ٢/ ٢٩٥، ٣٠١، وتوضيح الأفكار ٢/ ٤١٩ - ٤٢٢، وظفر الأماني: ٢٨٢ - ٢٨٧. ولا بدَّ من الإشارة إلى أن المتقدمين - ومنهم ابن الصلاح، ومتابعوه - كانوا يطلقون المصحّف والمحرّف جميعًا عَلَى شيء واحد، ولكن الحافظ ابن حجر جعلهما شيئين وخالف بينهما، وقد جرى عَلَى اصطلاحه السيوطي. قال ابن حجر في النزهة: ١٢٧: «إن كانت المخالفة بتغيير حرف أو حروف مع بقاء صورة الخط في السياق فإن كان ذَلِكَ بالنسبة إلى النَّقْط فالمصحف، وإن كان بالنسبة إلى الشَّكْل فالمحرّف». انظر: تدريب الراوي ٢/ ١٩٥، وألفية السيوطي: ٢٠٣، وتوضيح الأفكار ٢/ ٤١٩ مع حاشية محيي الدين عبد الحميد."}],[1404,"فَمِثالُ التَّصْحيفِ في الإسنادِ: حديثُ شُعْبَةَ عَنِ العَوَّامِ بنِ مُرَاجِمٍ (١)، عَنْ أبي عُثْمانَ النَّهْدِيِّ (٢)، عَنْ عُثْمَانَ بنِ عَفَّانَ، قالَ: قالَ رسولُ اللهِ - صلى الله عليه وآله وسلم -: «لَتُؤَدُّنَّ الحقوقَ إلى أهلِهَا ... الحديثَ» (٣). صَحَّفَ فيهِ يَحْيَى بنُ مَعينٍ، فقالَ: «ابنُ مُزَاحِمٍ» - بالزاي والحاءِ (٤) - فَرُدَّ عليهِ، وإنَّما هُوَ: «ابنُ مُرَاجِمٍ» - بالراءِ المهملةِ والجيمِ -. ومنهُ ما رُوِّيْناهُ عَنْ أحمدَ بنِ حَنْبَلٍ، قالَ: حَدَّثَنا مُحَمَّدُ بنُ جَعْفَرٍ، قالَ: حَدَّثَنا شُعْبَةُ، عَنْ مالكٍ بنِ عُرْفُطَةَ، عَنْ عبدِ خَيْرٍ، عَنْ عائِشَةَ: «أنَّ رسُولَ اللهِ - صلى الله عليه وآله وسلم - نَهَى عَنِ الدُّبَّاءِ (٥) والْمُزَفَّتِ» (٦). قالَ أحمدُ: «صَحَّفَ شُعبةُ فيهِ، وإنَّما هُوَ خالدُ بنُ عَلْقمةَ» (٧). وقَدْ رواهُ زَائِدَةُ بنُ قُدَامةَ وغيرُهُ عَلَى ما قالَهُ أحمدُ."],[1405,"وبَلَغَنا عَنِ الدَّارَقُطْنِيِّ أنَّ ابنَ جريرٍ الطَّبَريَّ قالَ فيمنْ رَوَى عَنِ النبيِّ - صلى الله عليه وآله وسلم - مِنْ بني سُلَيْمٍ: «ومِنْهُم عُتْبَةُ بنُ البُذَّرِ» (٨)، قالَهُ بالباءِ والذَّالِ المعجمةِ ورَوَى حديثًا (٩)، وإنَّما هُوَ «ابنُ النُّدَّرِ» بالنُّونِ والدَّالِ غيرِ المعجمةِ (١٠).","",{"fn":"انظر: الإكمال ٧/ ١٨٦.\nبفتح النون وسكون الهاء. التقريب (٤٠١٧).\nأخرجه الدارقطني في العلل ٣/ ٦٤ - ٦٥ س٢٨٧، وفي المؤتلف والمختلف ٣/ ٢٠٧٨ - ٢٠٧٩.\nفي (ب): «والحاء المهملة».\nالدباء: القرع، واحدها دُبَّاءة، كانوا ينتبذون فيها فتُسرع الشدة في الشراب، وتحريم الانتباذ في هذه الظروف كان في صدر الإسلام ثُمَّ نسخ، وهو المذهب، وذهب مالك وأحمد إلى بقاء التحريم. والمزفت: هو الإناء الذي طلي بالزفت، وهو نوع من القار ثُمَّ انتُبِذَ فيه. انظر: النهاية ٢/ ٩٦ و٣٠٤.\nأخرجه أحمد في المسند ٦/ ٢٤٤، وفيه: «قال أبو عبد الرحمان عبد الله بن أحمد: قال أبي: إنما هو خالد بن علقمة الهمداني، وهم شعبة».\nانظر: ما سبق، وانظر: علله ١/ ١٨٢.\nفي (ع): «الندر» خطأ.\nالمؤتلف والمختلف ١/ ١٨٢.\nبالنون المضمومة، وفتح الدال المهملة المشددة. انظر: الإكمال ١/ ٢١٨، وتبصير المنتبه ١/ ٧٠، وشرح التبصرة ٢/ ٤٢٦، والتقريب (٤٤٤٣)."}],[1406,"ومِثَالُ التَّصْحِيفِ في المتنِ: ما رواهُ ابنُ لَهِيْعةَ عَنْ كِتابِ موسَى بنِ عُقْبةَ إليهِ بإسْنادِهِ عَنْ زَيْدِ بنِ ثابِتٍ: «أنَّ رسولَ اللهِ - صلى الله عليه وآله وسلم - احْتَجَمَ في المسْجِدِ» (١)، وإنَّما هوَ بالرَّاءِ: «احْتَجَرَ في المسجدِ بِخُصٍّ أوْ حَصِيْرٍ، حُجْرَةً يُصَلِّي فيها». فَصَحَّفَهُ ابنُ لَهِيْعةَ؛ لِكونِهِ أخَذَهُ مِنْ كِتابٍ بِغَيْرِ سَماعٍ. ذَكَرَ ذَلِكَ مُسْلِمٌ في كِتابِ \" التمييز \" (٢) لهُ. وبَلَغَنا عَنِ الدَّارَقُطْنِيِّ في حديثِ أبي سُفيانَ، عَنْ جابِرٍ قالَ: «رُمِيَ أُبَيٌّ (٣) يومَ الأحْزابِ عَلَى أكْحَلِهِ (٤) فَكَواهُ رسولُ اللهِ - صلى الله عليه وآله وسلم -» (٥): أنَّ غُنْدرًا قالَ فيهِ: «أبي»، وإنَّما هوَ «أُبَيٌّ»، وهوَ (٦) ابنُ كَعْبٍ. وفي حديثِ أنَسٍ: «ثُمَّ يخْرُجُ مِنَ النَّارِ مَنْ قالَ: لا إلهَ إلاَّ اللهُ، وكانَ في قَلْبِهِ مِنَ الخيرِ ما يَزِنُ ذَرَّةً»، قالَ فيهِ شُعبةُ: «ذُرَةً» - بالضمِّ والتخفيفِ (٧) -، ونُسِبَ فيهِ إلى التَّصحيفِ. وفي حديثِ أبي ذَرٍّ: «تُعِينُ الصَّانِعَ»، قالَ فيهِ هِشَامُ بنُ عُرْوَةَ - بالضَّادِ المعجمةِ - وَهُوَ تصحيفٌ، والصوابُ ما رواهُ الزُّهْرِيُّ","",{"fn":"أخرجه البخاري ٨/ ٣٤ (٦١١٣)، ومسلم ٢/ ١٨٨ (٧٨١). وأخرجه البخاري أيضًا ١/ ١٨٦\nالتمييز: ١٨٧، وقال: «هذه رواية فاسدة من كل جهة، فاحش خطؤها في المتن والإسناد جميعًا، وابن لهيعة المصحف في متنه المغفل في إسناده». وانظر: الأباطيل للجورقاني ٢/ ٩.\nقال النووي: «بضم الهمزة وفتح الباء وتشديد الياء، هكذا صوابه، وكذا هو في الروايات والنسخ، وهو أُبي بن كعب، وصحفه بعضهم، فقال: بفتح الهمزة وكسر الباء وتخفيف الياء، وهو غلط فاحش؛ لأن أبا جابر استشهد يوم أحد قَبْلَ الأحزاب بأكثر من سنة». شرح صحيح مسلم ٥/ ٥٧.\nالأكحل: هو عِرْق في اليد في وسط الذراع. انظر: اللسان ١١/ ٥٨٦.\nأخرجه أحمد ٣/ ٣٠٣ و٣٠٤ و٣١٥ و٣٧١، وعبد بن حميد (١٠١٨)، ومسلم ٧/ ٢٢ (٢٢٠٧)، وأبو دواد (٣٨٦٤)، وابن ماجه (٣٤٩٣)، وأبو يعلى (٢٢٨٧) و(٢٢٨٨)، وأبو عوانة في الإتحاف ٣/ ١٧٢، والطحاوي في شرح المعاني ٤/ ٣٢١، والحاكم ٤/ ٢١٤ و٤١٧، والبيهقي ٩/ ٣٤٢.\nفي (م) والشذا: «وإنما هو أُبَيّ بن كعب»، وفي (ع) والتقييد: «وإنما هو أُبَيّ وهو أُبَيّ بن كعب».\nأخرجه أحمد ٣/ ١١٦ و١٧٣ و٢٧٦، وعبد بن حميد (١١٧٣)، وأخرجه البخاري ١/ ١٧ (٤٤) و٩/ ١٤٩ (٧٤١٠)، ومسلم ١/ ١٢٥ (١٩٣) (٣٢٥)، وابن ماجه (٤٣١٢)، والترمذي (٢٥٩٣).\n، و٩/ ١١٧ (٧٢٩٠)، ومسلم ٢/ ١٨٨ بلفظ: «اتَّخذَ حُجْرةً»."}],[1407,"«الصَّانِعَ» - بالصادِ المهملة (١) -: ضدُّ الأَخْرَقِ (٢). وبَلَغَنا عَنْ أبي زُرْعةَ الرَّازِيِّ أنَّ يَحْيَى ابنَ سَلاَّمٍ (٣) - هوَ المفَسِّرُ - حدَّثَ عَنْ سَعِيدِ بنِ أبي عَرُوبةَ عَنْ قَتادَةَ في قَولِهِ تَعَالَى: ﴿سَأُرِيْكُمْ دَارَ الفَاسِقِيْنَ﴾ (٤)، قالَ: «مِصْرُ» واسْتَعْظَمَ أبو زُرْعةَ هذا واسْتَقْبَحهُ وذَكَرَ أنَّهُ في تفسيرِ سَعيدٍ عَنْ قَتَادةَ «مَصِيْرُهُمْ» (٥)."],[1408,"وبَلَغَنا عَنِ الدَّارَقُطْنِيِّ أنَّ مُحَمَّدَ بنَ المثَنَّى أبا مُوسَى العَنَزِيَّ (٦) حَدَّثَ بحديثِ النبيِّ - صلى الله عليه وآله وسلم -: «لا يأتِي أحدُكُمْ يَومَ القِيامةِ بِبَقَرَةٍ لها خُوارٌ» (٧)، فقالَ فيهِ: «أو شَاةٍ تَنْعَرُ» (١) - بالنُّونِ - وإنَّما هوَ: «تَيْعَرُ» (٢) - بالياءِ المثناةِ مِنْ تحتُ -. وأنَّهُ قالَ لهمْ يومًا: «نَحْنُ قَوْمٌ لنا شرَفٌ، نحنُ مِنْ عَنَزَةَ (٣)، قَدْ صَلَّى النبيُّ - صلى الله عليه وآله وسلم - إلينا»، يُرِيدُ ما رُوِيَ «أنَّ النبيَّ - صلى الله عليه وآله وسلم - صَلَّى إلى عَنَزَةَ» (٤)، تَوَهَّمَ أنَّهُ صَلَّى إلى قَبِيلَتِهِمْ، وإنَّما العَنَزَةُ هاهنا حَرْبَةٌ نُصِبَتْ بَيْنَ يَدَيْهِ فَصَلَّى إليها (٥).","",{"fn":"قال الحافظ العراقي في شرح التبصرة والتذكرة ٢/ ٤٢٣: «وكقول هشام بن عروة في حديث أبي ذر: «تعين ضايعًا» بالضاد المعجمة، والياء آخر الحروف، والصواب بالمهملة والنون»، ومثله في تدريب الراوي ٢/ ١١٤. وهذا جزء من حديث أخرجه البخاري ٣/ ١٨٨ (٢٥١٨)، ومسلم ١/ ٦٢ (٨٤) من طريق هشام بن عروة، عن أبيه، عن أبي مُرَاوح، عن أبي ذرٍّ، قال: قلتُ: يا رسول الله ... وفيهما: «تعين صانعًا»، وعند مسلم أيضًا بلفظ: «فتعين الصانع»، هكذا في الأصول المطبوعة لـ\" الصحيحين \": «صانعًا» - بالصاد المهملة والنون - ومثل ذَلِكَ في مسند الحميدي (١٣١)، ومسند الإمام أَحْمَد ٥/ ١٥٠ و٥/ ١٧١، وفي فتح الباري ٥/ ١٤٨: «ضائعًا»، وفي عمدة القاري ١٣/ ٧٩: «ضايعًا». وانظر تفصيل ذَلِكَ في: شرح مسلم للنووي ١/ ٢٧١، وفتح الباري ٥/ ١٤٩، وعمدة القاري ١٣/ ٨٠.\nالأخرق: هو الذي ليس بصانع ولا يحسن العمل، يقال: رجل أخرق: لا صنعة له، والجمع: خُرْق - بضم ثُمَّ سكون - وامرأةٌ خرقاء كذلك. انظر: فتح الباري ٥/ ١٤٩.\nهو أبو زكريا، يحيى بن سلام بن أبي ثعلبة البصري، نزيل المغرب بإفريقية، توفي سنة (٢٠٠ هـ). انظر: الجرح والتعديل ٩/ ١٥٥، والكامل ٩/ ١٢٣، وميزان الاعتدال ٤/ ٣٨٠، والسير ٩/ ٣٩٦.\nالأعراف: ١٤٥.\nفي (ب): «مصر»، وهذا القول ذكرته كتب التفسير عن مجاهد، والذي ذكروه عن قتادة أنه قال: «منازلهم»، وقال أيضًا: «الشام»، وقال أيضًا: «مصر». انظر: تفسير الطبري ٩/ ٤١، وتفسير البغوي ٢/ ٢٣٤، والبحر المحيط ٤/ ٣٨٩، والدر المنثور ٣/ ٥٦٢، والقصة في الضعفاء لأبي زرعة ٢/ ٣٤٠.\nبفتح النون والزاي. التقريب (٦٢٦٤)، والأنساب ٤/ ٢٢١.\nخار يَخُورُ خُوَارًا - بالضم - صاح، والخُوَار: هو صياح البقر في الأصل، ثُمَّ توسعوا فيه فأطلقوه عَلَى صياح جميع البهائم. انظر: التاج ١١/ ٢٣١."}],[1409,"وأظْرَفُ (٦) مِنْ هذا ما رُوِّيْناهُ عَنِ الحاكِمِ أبي عبدِ اللهِ عَنْ أعرابيٍّ زَعَمَ أنَّهُ - صلى الله عليه وآله وسلم - كانَ إذا صَلَّى نُصِبَتْ بَيْنَ يَديهِ شاةٌ، أي: صَحَّفَها عَنْزَةً - بإسْكانِ النُّونِ (٧) -. وعَنِ الدَّارَقُطْنِيِّ أيضًا: أنَّ أبا بكرٍ الصُّولِيَّ (٨) أمْلَى في الجامِعِ حديثَ أبي أيُّوبَ: «مَنْ صَامَ رَمَضانَ وأتْبَعَهُ سِتًّا مِنْ شَوَّالٍ» (١)، فقالَ فيهِ: «شَيْئًا» بالشِّيْنِ والياءِ (٢). وأنَّ أبا بكرٍ الإسْماعِيليَّ (٣) الإمامَ كانَ فيما بَلَغَهُمْ عنهُ يَقُولُ في حديثِ عائِشَةَ عَنِ النبيِّ - صلى الله عليه وآله وسلم - في الكُهَّانِ: «قَرَّ الزُّجاجَةِ» بالزاي، وإنَّما هُوَ (٤) «قَرَّ الدَّجاجةِ» (٥) بالدالِ. وفي حديثٍ يُروَى عنْ مُعاويةَ بنِ أبي سُفيانَ قالَ: «لَعَنَ رسولُ اللهِ - صلى الله عليه وآله وسلم - الذينَ يُشَقِّقُونَ الخُطَبَ تَشْقِيْقَ الشِّعْرِ» (٦). ذَكَرَ الدَّارَقُطْنِيُّ عَنْ وَكيعٍ أنَّهُ قالهُ مَرَّةً بالحاءِ المهملَةِ (٧)، وأبو نُعَيمٍ شاهِدٌ، فَرَدَّهُ عليهِ بالخاءِ المعجمةِ المضمومةِ. وقرأْتُ بِخَطِّ مُصَنِّفٍ أنَّ ابنَ شاهِينَ قالَ في جامعِ المنصورِ في الحديثِ: «إنَّ النبيَّ - صلى الله عليه وآله وسلم - نَهَى عَنْ تَشْقِيقِ الْحَطَبِ» فقالَ بعضُ الملاَّحينَ: يا قومُ، فكيفَ نعملُ والحاجَةُ ماسَّةٌ؟","",{"fn":"الجامع لأخلاق الراوي ١/ ٢٩٥ (٦٣١). وهذا الجزء أخرجه الحميدي (٨٤٠)، وأحمد ٥/ ٤٢٣، والدارمي (١٦٧٦) و(٢٤٩٦)، والبخاري ٨/ ١٦٢ (٦٦٣٧)، ومسلم ٦/ ١٢ (١٨٣٢) (٢٧)، ونَعَر يَنْعَِرُ، كـ: «منع وضرب»: صاحَ وصَوَّتَ بخَيْشُومِهِ. تاج العروس ١٤/ ٢٥٧.\nتَعَرَ، كـ: «منع»، أي: صاحَ يَتْعَرُ تَعْرًا. انظر: التاج ١٠/ ٢٨٦.\nبفتح العين المهملة والنون. انظر: الأنساب ٤/ ٢٢١، وتاج العروس ١٥/ ٢٤٨.\nهذه إشارة إلى حديث ورد عن جماعة من الصحابة. انظر مثلًا: مسند أحمد ٤/ ٣٠٨، وصحيح البخاري ٢/ ٢٥ (٩٧٣)، وصحيح مسلم ٢/ ٥٥ (٥٠١) (٢٤٦)، وابن ماجه (١٣٠٤).\nانظر: الصحاح ٣/ ٨٨٧، والتاج ١٥/ ٢٤٧.\nفي ب (وأطرف) بالطاء المهملة.\nأخرجه الحاكم في معرفة علوم الحديث: ١٤٨ - ١٤٩.\nهو محمد بن يحيى بن عبد الله بن العباس بن محمد بن صول، أبو بكر المعروف بالصوليِّ، كان أحد العلماء بفنون الآداب، حسن المعرفة بأخبار الملوك وأيام الخلفاء، ومآثر الأشراف، وطبقات الشعراء، توفي سنة خمس وثلاثين وثلاث مئة. انظر: تاريخ بغداد ٣/ ٤٢٧، ومعجم الأدباء ١٩/ ١٠٩، والسير ١٥/ ٣٠١. والصولي: بضم الصاد المهملة، وفي آخرها اللام، هذه النسبة إلى صول، وهو اسم لبعض أجداده. الأنساب ٣/ ٥٧٢.\nحديث أبي أيوب: أخرجه الطيالسي (٥٩٤)، وعبد الرزاق (٧٩١٨)، والحميدي (٣٨١) و(٣٨٢)، وابن أبي شيبة ٣/ ٩٧، وأحمد ٥/ ٤١٧ و٤١٩، وعبد بن حميد (٢٢٨)، والدارمي (١٧٦١). ومسلم ٣/ ١٦٩ (١١٦٤)، وأبو داود (٢٤٣٣). وابن ماجه (١٧١٦)، والترمذي (٧٥٩)، والطحاوي في شرح المشكل (٢٣٣٧) و(٢٣٣٨)، وابن حبان (٣٦٣٤)، والبيهقي ٤/ ٣٩٢، والبغوي (١٧٨٠).\nتاريخ بغداد ٣/ ٤٣١.\nإنَّ حمل ذلك التصحيف على الإسماعيلي وحده فيه نظر، فقد اختلف فيه رواة الصحيح. انظر: تفصيل ذلك في شرح النووي ٥/ ٨٤، وفتح الباري ١٠/ ٢٢٠.\nلَمْ ترد في (ب) و(م).\nقرَّ الدجاجة، أي: صوتها إذا قطعته، يقال: قرَّتِ الدجاجةُ تقُرُّ قَرًّا وقَريرًا إذا قطعت صوتها. انظر: جامع الأصول ٥/ ٦٤، وتاج العروس ١٣/ ٣٩١.\nالجامع ١/ ٢٩٢ رقم (٦١٩)، يعني: «الخُطب»، والحديث في مسند الإمام أحمد ٤/ ٩٨ قال: حدثنا وكيع، قال: حدثنا سفيان، عن جابر، عن عمرو بن يحيى، عن معاوية، قال: «لعن رسول الله - صلى الله عليه وآله وسلم - الذين يُشَقِّقُونَ الكلام تشقيق الشِّعْرِ» وهو كذلك في مجمع الزوائد ٨/ ١١٦. وأخرجه الطبراني في الكبير ١٩/ ٣١١ حديث (٨٤٨) من طريق أبي نعيم، عن سفيان، ولفظه: «لعن رسول الله - صلى الله عليه وآله وسلم - الذين يشَقِّقُون الْخُطَب تَشْقِيقَ الشِّعْر»، وهو كذلك في المجمع ٢/ ١٩١، والحديث ضعيف لتفرد جابر الجعفي به.\nأي: الحطب - بالحاء المهملة المفتوحة بدل الخاء المعجمة المضمومة -."}],[1410,"قُلْتُ: فَقَدِ انْقَسَمَ التَّصْحِيفُ إلى قِسْمَيْنِ: أحَدُهُما في المتْنِ، والثاني في الإسنادِ."],[1411,"ويَنْقَسِمُ قِسْمَةً أُخْرَى إلى قِسْمَينِ:"],[1412,"أحدُهُما: تَصْحِيفُ البَصَرِ، كما سَبَقَ عَنِ ابنِ لَهِيْعَةَ وذلكَ هوَ الأكثرُ."],[1413,"والثاني: تَصْحِيفُ السَّمْعِ، نحوُ حديثٍ لـ «عاصِمٍ الأحْوَلِ» رواهُ بعضُهُمْ فقالَ: «عَنْ واصِلٍ الأحْدَبِ» فَذَكَرَ الدَّارَقُطْنِيُّ أنَّهُ مِنْ تَصْحِيفِ السَّمْعِ لا مِنْ تَصْحِيفِ"],[1414,"البَصَرِ، كأَنَّهُ ذَهَبَ - واللهُ أعلمُ - إلى أنَّ ذَلِكَ مِمَّا لا يشتبهُ مِنْ حيثُ الكِتابَةُ وإنَّما أخْطَأَ فيهِ سَمْعُ مَنْ رواهُ."],[1415,"ويَنْقَسِمُ قِسْمةً ثالِثَةً:"],[1416,"- إلى تصحيفِ اللَّفظِ وهو الأكثرُ."],[1417,"- وإلى تصحيفِ يتعلَّقُ بالمعنى دُونَ اللفْظِ، كمثلِ ما سَبَقَ عَنْ مُحَمَّدِ بنِ المثنَّى في الصلاةِ إلى عَنَزَةَ. وتسميةُ بعضِ ما ذَكَرْناهُ تَصْحِيفًا مَجازٌ، واللهُ أعلم."],[1418,"وكثيرٌ مِنَ التَّصْحيفِ المنقولِ عَنِ الأكَابِرِ الجِلَّةِ لهم فيهِ أعْذارٌ لَمْ يَنْقُلها ناقِلُوهُ (١)، ونسألُ اللهَ التَّوفيقَ والعِصْمةَ، واللهُ أعلمُ."],[1419,"النوع السادس والثلاثون معرفة مختلف الحديث"],[1420,"(٢)","",{"fn":"في (م): «ناقلوها».\nانظر فيه: معرفة علوم الحديث: ١٢٢ - ١٢٨، وإرشاد طلاب الحقائق ٢/ ٥٧١ - ٥٧٥ والتقريب: ١٥٩ - ١٦١، واختصار علوم الحديث: ١٧٤ - ١٧٥، والشذا الفياح ٢/ ٤٧١ - ٤٧٦، والمقنع ٢/ ٤٨٠ - ٤٨٢، وفتح المغيث ٣/ ٧٥ - ٧٨، وتدريب الراوي ٢/ ١٩٦ - ٢٠٢، وتوضيح الأفكار ٢/ ٤٢٣ - ٤٢٦. ولا بدَّ من الإشارة إلى أن المراد بـ «مختلف الْحَدِيْث» يختلف في الاصطلاح باختلاف ضبط كلمة: «مختلف» فَمِنَ المحدِّثين مَنْ ضبطها - بكسر اللام - عَلَى وزن اسم الفاعل. ويكون المراد بـ «مختلف الْحَدِيْث» عَلَى هَذَا: «الْحَدِيْث الَّذِي عارضه - ظاهرًا - مثله». ="}],[1421,"وإنَّمَا يَكْمُلُ لِلْقِيامِ بهِ الأئِمَّةُ الجامِعونَ بَيْنَ صِناعَتَي: الحديثِ والفِقْهِ، الغَوَّاصُونَ عَلَى المعاني الدقيقةِ (١)."],[1422,"اعْلَمْ أنَّ ما يُذْكَرُ في هذا البابِ يَنْقَسِمُ إلى قِسْمَينِ:"],[1423,"أحدُهُما أنْ يُمْكِنَ الجَمْعُ بَيْنَ الحديثينِ ولا يتعذَّرُ إبداءُ وَجْهٍ يَنْفِي تَنافِيَهُما، فيتَعَيَّنُ حِيْنَئذٍ المصيرُ إلى ذَلِكَ والقولُ بهما معًا."],[1424,"ومِثَالُهُ حديثُ: «لا عَدْوَى ولا طِيَرَةَ» (٢) معَ حديثِ: «لا يُورِدُ مُمْرِضٌ (٣) عَلَى مُصِحٍّ» (٤)، وحديثُ: «فِرَّ مِنَ المجذومِ (٥) فِرَارَكَ مِنَ الأسَدِ» (٦). وَجْهُ الجمْعِ (٧) بينَهُما أنَّ هذهِ الأمراضَ لا تُعْدِي بِطَبْعِها ولكِنَّ اللهَ تبارك وتعالى جَعَلَ مُخَالَطَةَ المريضِ بها للصَّحيحِ سَبَبًا لإعدائِهِ مَرَضَهُ (٨). ثُمَّ قَدْ يتَخَلَّفُ ذَلِكَ عَنْ سَبَبِهِ كما في سائِرِ الأسْبابِ.","",{"fn":"انظر: محاسن الاصطلاح ٤١٤، وشرح التبصرة والتذكرة ٢/ ٤٣٣.\nأخرجه البخاري ٧/ ١٧٩ (٥٧٧٢)، ومسلم ٧/ ٣١ (٢٢٢٠) (١٠٢). والطِّيَرة - بكسر الطاء وفتح الياء وقد تسكن - هي التشاؤم بالشيء، وكان ذلك يَصُدُّهم عن مقاصدهم، فنفاه الشرع وأبطله ونهى عنه، وأخبر أنه ليس له تأثير في جَلْب نَفْع أو دَفْع ضرّ. انظر: النهاية ٣/ ١٥٢.\nالممرض - بضم الميم الأولى وسكون الثانية وكسر الراء بعدها ضاد معجمة -: هو اسم فاعل. والمصح - بضم الميم وكسر الصاد المهملة وتشديد الحاء -. انظر: عمدة القاري ٢١/ ٢٨٨.\nأخرجه البخاري ٧/ ١٧٩ (٥٧٧١)، ومسلم ٧/ ٣١ (٢٢٢١) من حديث أبي هريرة.\nالْجُذام: مرض وخيم ربما انتهى إلى تقطّع أطراف اليد وسقوطها عن تقرح، ويفسد مزاج الأعضاء وهيأتها. متن اللغة ١/ ٤٩٦.\nأخرجه البخاري ٧/ ١٦٤ (٥٧٠٧).\nللعلماء مسالك متعددة في الجمع بين هذه الأحاديث. انظر: فتح الباري ١٠/ ١٦٠.\nفي الشذا: «مرضًا»."}],[1425,"فَفِي الحديثِ الأوَّلِ نَفَى - صلى الله عليه وآله وسلم - ما كانَ يَعْتَقِدُهُ الجاهِلِيُّ (١) مِنْ أنَّ ذَلِكَ يُعْدِي بِطَبْعِهِ ولهذا قالَ: «فَمَنْ أعْدَى الأوَّلَ؟». وفي الثاني أعلَمَ بأنَّ اللهَ سُبْحانَهُ جَعَلَ ذَلِكَ سَبَبًا لِذَلِكَ، وحَذَّرَ مِنَ الضَّرَرِ الَّذِي يَغْلِبُ وجُودُهُ عِنْدَ وجُودِهِ بِفِعْلِ اللهِ سبحانه وتعالى، ولهذا في الحديثِ أمثالٌ كثيرةٌ (٢). وكتابُ \" مُختلِفِ الحديثِ \" لابنِ قُتَيْبَةَ في هَذَا المعنى، إنْ لَمْ يكنْ قدْ أحسَنَ فيهِ مِنْ وجْهٍ، فَقَدْ أسَاءَ في أشْياءَ منهُ قَصُرَ باعُهُ فِيْهَا، وأتَى بِمَا غيرُهُ أَوْلَى وأقْوَى. وقَدْ رُوِّيْنا عَنْ مُحَمَّدِ بنِ إسْحاقَ بنِ خُزَيمةَ الإمامِ أنَّهُ قالَ: «لا أعرِفُ أنَّهُ رُوِيَ عَنِ النبيِّ (٣) - صلى الله عليه وآله وسلم - حديثانِ -بإسْنادَينِ صحيحينِ- مُتَضَادَّيْنِ، فَمَنْ كانَ عِنْدَهُ فليَأْتِنِي بهِ لأُؤَلِّفَ بَيْنَهُما» (٤)."],[1426,"القِسْمُ الثَّانِي: أنْ يَتَضَادَّا بحيثُ لا يُمْكِنُ الْجَمْعُ بَيْنَهُما، وذَلِكَ عَلَى ضَرْبَينِ:"],[1427,"أحَدُهُما: أنْ يَظْهَرَ كَونُ أحَدِهِما ناسِخًا والآخَرُ مَنْسُوخًا، فَيُعْمَلُ بالنَّاسِخِ ويُتْرَكُ المنسُوخُ."],[1428,"والثَّاني: أنْ لا تَقُومَ دلالةٌ عَلَى أنَّ الناسِخَ أيُّهُما والمنسُوخَ أيُّهُما، فَيُفزَعَ حِيْنَئذٍ إلى التَّرْجِيحِ ويُعْمَلَ بالأرْجَحِ منْهُما والأثْبَتِ، كالتَّرْجِيحِ بِكَثْرَةِ الرُّواةِ، أوْ بِصِفاتِهِمْ في خمسينَ وَجْهًا مِنْ وُجُوهِ التَّرْجِيحاتِ وأكثرَ (٥)، ولِتَفصِيلها موضِعٌ غيرُ (٦) ذا، واللهُ سُبْحانَهُ أعلمُ.","",{"fn":"في (م): «الجاهل».\nراجع: محاسن الاصطلاح ٤١٥.\nفي (م) و(جـ): «عن رسول الله».\nانظر: شرح التبصرة والتذكرة ٢/ ٤٣٣.\nذكرها الحازمي في كتابه الاعتبار: ٧ - ١٥، وسردها العراقي في شرح التبصرة ٢/ ٤٣٥ - ٤٣٨، وانظر: الكفاية (٦٠٩ - ٦١٠ ت، ٤٣٤ - ٤٣٦ هـ).\nوقد ذكر الحافظ العراقي ما يزيد على المئة، فلتراجع في التقييد: ٢٨٦، وانظر: شرح التبصرة ٢/ ٤٣٥."}],[1429,"النوع السابع والثلاثون معرفة المزيد في متصل الأسانيد"],[1430,"(١)"],[1431,"مِثَالُهُ: ما رُوِيَ عَنْ عبدِ اللهِ بنِ المباركِ، قالَ: حَدَّثَنا (٢) سُفْيانُ، عَنْ"],[1432,"عبدِ الرَّحمانِ بنِ يَزيدَ بنِ جابِرٍ، قالَ: حَدَّثَني بُسْرُ (٣) بنُ عُبَيْدِ اللهِ، قالَ سَمِعْتُ أبا إدْرِيْسَ، يَقُولُ: سَمِعْتُ واثِلَةَ بنَ الأسْقَعِ، يقولُ: سَمِعْتُ أبا مَرْثِدٍ (٤) الغَنَوِيَّ (٥)، يقولُ سَمِعْتُ رسولَ اللهِ - صلى الله عليه وآله وسلم -، يقولُ: «لاَ تَجْلِسُوا عَلَى القُبُورِ ولا تُصَلُّوا إليها» فَذِكْرُ سُفيانَ في هذا الإسنادِ زيادةٌ وَوَهَمٌ (٦)، وهكذا ذِكْرُ أبي إدْرِيسَ: أمَّا الوَهَمُ في ذِكْرِ سُفْيانَ فَمِمَّنْ دُونَ ابنِ المبارَكِ (٧)؛ لأنَّ جماعةً ثِقَاتٍ (٨) رَوَوْهُ عَنِ ابنِ المباركِ عَنِ ابنِ جابرٍ نفسِهِ، ومِنْهُم مَنْ صَرَّحَ فيهِ بلفظِ الإخْبارِ بَيْنَهُما. وأمَّا ذِكْرُ أبي إدْريسَ فيهِ فابنُ المباركَ مَنْسُوبٌ فيهِ إلى الوَهَمِ؛ وذلكَ لأنَّ جماعةً مِنَ الثقاتِ رَوَوْهُ عَنِ ابنِ جابرٍ فلمْ يَذكروا أبا إدْرِيسَ بَيْنَ بُسْرٍ وواثِلَةَ. وفيهم مَنْ صَرَّحَ فيهِ بسماعِ بُسْرٍ مِنْ واثلةَ. قالَ أبو حاتِمٍ الرازيُّ:","",{"fn":"انظر في هذا النوع: الإرشاد ٢/ ٥٧٦ - ٥٨٠، والتقريب: ١٦١ - ١٦٢، واختصار علوم الحديث: ١٧٦ - ١٧٧، والشذا الفياح ٢/ ٤٧٧ - ٤٧٨، والمقنع ٢/ ٤٨٣ - ٤٨٦، وشرح التبصرة والتذكرة ٢/ ٤٤٠، وفتح المغيث ٣/ ٧٩ - ٨٢، وتدريب الراوي ٢/ ٢٠٣ - ٢٠٤، وشرح السيوطي على ألفية العراقي: ١٧٠، وفتح الباقي ٢/ ٣٠٦ - ٣١٠، وتوضيح الأفكار ٢/ ٦٤ - ٦٧. قال ابن كثير: هو أن يزيد راوٍ في الإسناد رجلًا لَمْ يذكُرْهُ غيرُهُ. وقال ابن حجر: هو ما كانت المخالفة فيه بزيادة راوٍ في أثناء الإسناد، ومن لَمْ يزدها أتقن ممن زادها. قال: وشرطه أن يقع التصريح بالسماع في موضع الزيادة، وإلاَّ فمتى كان معنعنًا - مثلًا - ترجحت الزيادة. انظر: اختصار علوم الحديث ٢/ ٤٨٥، ونزهة النظر: ١٢٦.\nفي (م): «أخبرنا».\nفي (جـ): «بشر» بالشين المعجمة، وهو خطأ، صوابه ما أثبت، وهو الموافق لمصادر ترجمته، فهو بضم الباء وبالسين المهملة. انظر: الإكمال ١/ ٢٦٨، وتهذيب الكمال ١/ ٣٤١.\nبفتح الميم وسكون الراء بعدها مثلثة. التقريب (٥٦٦٦).\nبفتح الغين المعجمة والنون، وكسر الواو. الأنساب ٤/ ٢٨٨.\nيُقال: وَهِمَ يَوْهَمُ وَهَمًا - بالتحريك - إذا غلِطَ. انظر: النهاية ٥/ ٢٣٤.\nبعد هذا في (ع): «لا من ابن المبارك»، ولم ترد في شيء من النسخ الخطية ولا (م).\nالطرق والروايات مفصلة في شرح التبصرة ٢/ ٤٤٤ - ٤٤٦."}],[1433,"«يُرَوْنَ أنَّ ابنَ المباركِ وَهِمَ في هذا (١)، قالَ: وكثيرًا ما يُحَدِّثُ بُسْرٌ عَنْ أبي إديسَ فَغَلِطَ ابنُ المباركِ وظَنَّ أنَّ هذا مِمَّا رُوِيَ عَنْ أبي إدرِيسَ عَنْ واثِلَةَ، وقَدْ سَمِعَ هذا بُسْرٌ مِنْ واثِلَةَ نفسِهِ» (٢)."],[1434,"قلتُ: قدْ ألَّفَ الخطيبُ الحافظُ في هذا النوعِ كِتابًا سَمَّاهُ كتابَ \" تَمْييزِ المزيدِ في مُتَّصِلِ الأسَانِيدِ \". وفي كثيرٍ مِمَّا ذَكَرَهُ نَظَرٌ؛ لأنَّ الإسْنادَ الخالِيَ عَنِ الرَّاوِي الزائِدِ، إنْ كانَ بلفظَةِ «عَنْ» في ذَلِكَ فينْبَغِي أنْ يُحْكَمَ بإرْسالِهِ، ويُجْعَلَ مُعَلَّلًا بالإسْنادِ الَّذِي ذُكِرَ فيهِ الزائِدُ؛ لما (٣) عُرِفَ في نوعِ المعلَّلِ، وكما يأتِي ذِكْرُهُ إنْ شاءَ اللهَ تَعَالَى في النوعِ الذي يليهِ. وإنْ كانَ فيهِ تَصريحٌ بالسماعِ أو بالإخْبارِ كما في المثالِ الذي أوْردناهُ، فجائِزٌ أنْ يَكونَ قد سَمِعَ ذَلِكَ مِنْ رجلٍ عنهُ، ثُمَّ سَمِعَهُ منهُ نَفسُهُ، فيكونُ بُسْرٌ في هذا الحديثِ قدْ سَمِعَهُ مِنْ أبي إدْريسَ عَنْ واثِلةَ، ثُمَّ لَقِيَ واثلةَ فسَمِعَهُ منهُ كما جاءَ مِثْلُهُ مُصَرَّحًا بهِ في غيرِ هذا، اللَّهُمَّ إلاَّ أنْ تُوجدَ قرينةٌ تدلُّ عَلَى كونِهِ وَهَمًا، كَنَحْوِ ما ذكرَهُ أبو حاتِمٍ في المثالِ المذكورِ. وأيضًا فالظَّاهِرُ مِمَّنْ وقَعَ لهُ مِثْلُ ذَلِكَ أنْ يَذْكُرَ السَّماعَيْنِ، فإذا لَمْ يَجِئْ عنهُ ذِكْرُ ذَلِكَ حَمَلْناهُ عَلَى الزيادةِ المذكورةِ (٤)، واللهُ أعلمُ.","",{"fn":"العلل لابنه ١/ ٨٠ (٢١٣).\nنقله ابن أبي حاتم في علله ١/ ٨٠ عن أبيه. وانظر: العلل أيضًا ١/ ٣٤٩.\nفي (م): «كما».\nراجع: محاسن الاصطلاح: ٤١٨."}],[1435,"النوع الثامن والثلاثون معرفة المراسيل الخفي إرسالها"],[1436,"(١)"],[1437,"هذا نوعٌ مُهِمٌّ عظيمُ الفائدةِ يُدْرَكُ بالاتِّسَاعِ في الروايةِ والجمْعِ لِطُرُقِ الأحاديثِ مَعَ المعرفَةِ التامَّةِ، ولِلْخَطيبِ الحافِظِ فيهِ كِتابُ \" التَّفْصِيلِ لِمُبْهَمِ المراسِيلِ \" (٢). والمذكورُ في هذا البابِ منهُ ما عُرِفَ فيهِ الإرْسالُ بمعرفَةِ عَدَمِ السَّماعِ مِنَ الراوي فيهِ أوْ عَدَمُ اللقَاءِ، كما جاءَ في الحديثِ المرْوِيِّ عَنِ العَوَّامِ بنِ حَوْشَبٍ، عَنْ عبدِ اللهِ بنِ أبي أوْفَى، قالَ: «كانَ النبيُّ - صلى الله عليه وآله وسلم - إذا قالَ بِلالٌ: قَدْ قَامَتِ الصَّلاةُ نَهَضَ وكَبَّرَ» (٣). رُوِيَ فيهِ عَنْ أحمدَ بنِ حَنْبَلٍ أنَّهُ قالَ: «العَوَّامِ لَمْ يَلْقَ ابنَ أبي أوْفَى» (٤). ومنهُ ما كانَ الْحُكْمُ بإرْسَالِهِ مُحالًا عَلَى مَجِيئهِ مِنْ وجْهٍ آخَرَ بزِيادَةِ شَخْصٍ واحِدٍ أوْ أكثَرَ في الموضِعِ المدَّعَى فيهِ الإرْسالُ، كالحديثِ الذي سَبَقَ ذِكْرُهُ في النوعِ العاشِرِ عَنْ عبدِ الرَّزَّاقِ، عَنِ الثَّورِيِّ، عنْ أبي إسْحاقَ، فإنَّهُ حُكِمَ فيهِ بالانْقِطاعِ والإرْسَالِ بَيْنَ عبدِ الرَّزَّاقِ والثَّورِيِّ؛ لأنَّهُ رُوِيَ عَنْ عبدِ الرَّزَّاقِ، قالَ: حَدَّثَني النُّعْمانُ بنُ أبي شَيْبَةَ الْجَنَدِيُّ (٥) عَنِ الثَّوْرِيِّ، عَنْ أبي إسْحاقَ. وحُكِمَ أيضًا فيهِ بالإرْسالِ بَيْنَ الثَّوْرِيِّ وأبي إسْحاقَ؛ لأنَّهُ رُوِيَ عَنِ الثَّوْرِيِّ، عَنْ شَرِيكٍ، عَنْ أبي إسْحاقَ (١)، وهذا وما سَبَقَ في النوعِ الذي قبلَهُ يَتَعَرَّضانِ؛ لأنْ يُعْتَرضَ بِكُلِّ واحِدٍ منهُما عَلَى الآخَرِ، عَلَى ما تَقَدَّمَتْ الإشَارةُ إليهِ، واللهُ أعلمُ.","",{"fn":"انظر في هذا النوع: الكفاية في علم الرواية: (٥٤٦ ت - ٣٨٤ هـ)، والإرشاد ٢/ ٥٨١ - ٥٨٣، التقريب: ١٦٢، واختصار علوم الحديث: ١٧٧ - ١٧٨، والشذا الفياح ٢/ ٤٧٩ - ٤٨٢، والمقنع ٢/ ٤٨٧ - ٤٨٩، ونزهة النظر ١٠٩ - ١١٢، وطبعة عتر: ٤٣ - ٤٤، وفتح المغيث ٣/ ٧٩ - ٨٢، وتدريب الراوي ٢/ ٢٠٥ - ٢٠٦.\nانظر: شرح التبصرة والتذكرة ٢/ ٤٤٤.\nأخرجه البزار ١/ ٢٥٢ (كشف)، والبيهقي ٢/ ٢٢، وقال عقيبه: «وهذا لا يرويه إلا الحجاج بن فروخ، وكان يحيى بن معين يضعفه». انظر: مجمع الزوائد ٢/ ١٠٣.\nجامع التحصيل: ٢٤٩ (٥٩٦).\nبفتح الجيم والنون. التقريب (٧١٥٧)."}],[1438,"النوع التاسع والثلاثون معرفة الصحابة - رضي الله عنهم - أجمعين"],[1439,"(٢)"],[1440,"هذا عِلْمٌ كبيرٌ قَدْ ألَّفَ الناسُ فيهِ كُتُبًا كَثيرةً (٣)، ومِنْ أجَلِّها (٤) وأكْثَرِها فوائِدَ كتابُ \" الاستِيعَابِ \" لابنِ عبدِ البرِّ لولا ما شَانَهُ بهِ مِنْ إيرادِهِ كَثيرًا مِمَّا"],[1441,"شَجَرَ بَيْنَ الصحابةِ وحكاياتِهِ عَنِ الأخبارِيِّيْنَ لا المحدِّثينَ. وغالبٌ عَلَى الأخبارِيِّينَ الإكْثَارُ والتخليطُ فيما يَرْوُونَهُ.","",{"fn":"بعدها في (م) وحاشية الشذا الفياح: «وما رواه بكر بن بكار وغيره عن المسعودي، عن عبد الكريم ابن مالك الجزري، عن عبد الرحمان بن أبي ليلى عن علي: «أمرني رسول الله - صلى الله عليه وآله وسلم - أن أتصدق بلحوم البدن وجلالها وجلودها»، فهذا قد حكم فيه بالإرسال بين عبد الكريم الجزري وابن أبي ليلى، وبأن بينهما مجاهدًا؛ ولأن ابن عيينة وإسرائيل بن يونس وغيرهما رووه عن عبد الكريم، عن مجاهد، عن ابن أبي ليلى». وهذا النص الطويل لا نظنه لابن الصلاح بل هو لأحد المحشين، وإلا كيف نفسر عدم وجوده في نسخنا الخطية والتقييد ولا في من اختصر الكتاب أو شرحه، ولم نجد أحدًا نسب ذَلِكَ لابن الصلاح.\nانظر في ذلك: معرفة علوم الحديث: ٢٢ - ٢٥، والكفاية: (٩٣ - ١٠٢ ت، ٤٦ - ٥٢ هـ -)، والإرشاد ٢/ ٥٨٤ - ٦٠٥، والتقريب: ١٦٢ - ١٦٥، واختصار علوم الحديث: ١٧٩ - ١٩١، والشذا الفياح ٢/ ٤٨٣ - ٥١٨، والمقنع ٢/ ٤٩٠ - ٥٠٥، وشرح التبصرة والتذكرة ٣/ ٥ - ٥٦، وفتح المغيث ٣/ ٨٣ - ١٣٨، وتدريب الراوي ٢/ ٢٠٦ - ٢٣٣، وشرح السيوطي على ألفية العراقي: ١٧١، وفتح الباقي ٣/ ٢ - ٤٤، وتوضيح الأفكار ٢/ ٤٢٦ - ٤٧١، وظفر الأماني ٤٩٦ - ٥١٣.\nانظر: الإصابة ١/ ٢ - ٣، وشرح التبصرة ٣/ ٥، والرسالة المستطرفة: ١٢٦.\nفي (ب) و(جـ) و(م) والشذا الفياح: «أحلاها»، وما أثبتناه من (أ) و(ع) والتقييد."}],[1442,"وأنا أُوْرِدُ نُكَتًا نافِعَةً - إنْ شَاءَ اللهُ تَعَالَى - قدْ كانَ يَنْبَغِي لِمُصَنِّفي كُتُبِ الصَّحابةِ أنْ يُتَوِّجُوها بها مُقَدِّمينَ لها في فواتِحِها:"],[1443,"إحْداها: اختلَفَ أهلُ العِلْمِ في أنَّ الصَّحابيَّ مَنْ (١)؟ فالمعروفُ مِنْ طريقةِ أهلِ الحديثِ أنَّ كُلَّ مُسْلِمٍ رأى رسُولَ اللهِ - صلى الله عليه وآله وسلم - فَهُوَ مِنَ الصحابةِ. قالَ البُخَارِيُّ في \" صحيحهِ \": «مَنْ صَحِبَ النبيَّ - صلى الله عليه وآله وسلم - أوْ رآهُ مِنَ المسْلِمِيْنَ فَهُوَ مِنَ أصْحَابِهِ» (٢). وبَلَغَنا عَنْ أبي الْمُظَفَّرِ السَّمْعانيِّ الْمَرُوزِيِّ أنَّهُ قالَ: «أصْحابُ الحديثِ يُطْلِقُونَ اسمَ الصَّحابةِ عَلَى كُلِّ مَنْ رَوَى عنهُ حديثًا أو كَلِمةً، ويَتَوَسَّعُونَ حَتَّى يَعدُّونَ مَنْ"],[1444,"رآهُ رُؤْيةً، مِنَ الصحابةِ؛ وهذا لِشَرَفِ مَنْزِلَةِ النبيِّ - صلى الله عليه وآله وسلم -، أعطَوا كُلَّ مَنْ رآهُ حُكْمَ الصُّحْبَةِ». وذَكَرَ أنَّ اسمَ الصحابِيِّ مِنْ حيثُ اللغَةُ والظَّاهِرُ: يقعُ عَلَى مَنْ طَالَتْ صُحْبَتُهُ للنَّبِيِّ - صلى الله عليه وآله وسلم - وكَثُرَتْ مُجالَسَتُهُ لهُ عَلَى طريقِ التَّبَعِ لهُ والأخْذِ عنهُ. قالَ: «وهذا طريقُ الأُصُولِيِّيْنَ» (٣)."],[1445,"قلتُ: وقَدْ رُوِّيْنا عَنْ سَعِيْدِ بنِ المسَيِّبِ أنَّهُ كانَ: «لاَ يَعُدَّ الصَّحابِيَّ إلاَّ مَنْ أقامَ مَعَ رسولَ اللهِ - صلى الله عليه وآله وسلم - سَنَةً وسَنَتَيْنِ وغَزَا معهُ غَزْوَةً أوْ غَزْوَتَيْنِ» (٤)، وكأنَّ المرادَ بهذا - إنْ صَحَّ عنهُ - راجعٌ إلى المحْكِيِّ عَنِ الأُصُولِيِّيْنَ، ولَكِنْ في عبارتِهِ ضيقٌ يُوجِبُ أنْ لا يُعَدَّ مِنَ الصحابةِ جريرُ بنُ عبدِ اللهِ البَجَلِيُّ، ومَنْ شَاركَهُ في فَقْدِ ظَاهِرِ ما اشْتَرَطَهُ فيهم مِمَّنْ لا نَعْرِفُ خلافًا في عَدِّهِ مِنَ الصَّحابَةِ (١). ورُوِّيْنا عَنْ شُعْبَةَ، عَنْ مُوْسَى السَّبَلاَنِيِّ (٢)","",{"fn":"في (م): «من هو؟».\nصحيح البُخَارِيّ ٥/ ٢ قبيل (٣٦٤٩)، وأورده الخطيب مسندًا في الكفاية: (٩٩ ت - ٥١ هـ).\nانظر مثلًا: مختصر ابن الحاجب ٢/ ٦٧، والمستصفى ١/ ١٦٥، وإحكام الأحكام ١/ ٢٧٥، وفواتح الرحموت ٢/ ١٥٨، وظفر الأماني: ٣٠٤ قال ابن الملقن في المقنع ٢/ ٤٩١: «لكن رجح ابن الحاجب الأصولي الأول، وعبر بقوله: «من رآه رسول الله - صلى الله عليه وآله وسلم - بدل من رأي، وما رجحه موافق للمعروف عِنْدَ المحدّثين، ويدخل في تفسيره ابن أم مكتوم الأعمى وغيره ... بخلاف الأول. انظر: منتهى الوصول لابن الحاجب: ٨١.\nأسنده إليه الخطيب في الكفاية: (٩٩ ت، ٥٠ هـ) من طريق ابن سعد عن الواقدي محمد بن عمر، عن طلحة بن محمد بن سعيد بن المسيب، عن أبيه، قال: كان سعيد يقول: فذكره. وهذا سند ضعيف جدًا لشدة ضعف الواقدي. قال العراقي في شرح التبصرة ٣/ ١٢ - ١٣: «ولا يصح هذا عن ابن المسيب، ففي الإسناد إليه محمد بن عمر الواقدي: ضعيف في الحديث»."}],[1446,"- وأثْنَى عليهِ خَيْرًا - قالَ: أتَيْتُ أنَسَ بنَ مالكٍ فقلْتُ: هَلْ بَقِيَ مِنْ أصْحابِ رَسُولِ اللهِ - صلى الله عليه وآله وسلم - أحَدٌ غيرُكَ؟ قالَ: بَقِيَ ناسٌ مِنَ الأعْرابِ قَدْ رَأَوْهُ، فأمَّا مَنْ صَحِبَهُ فلا (٣). إسْنادُهُ جيِّدٌ، حدَّثَ بهِ مُسْلِمٌ بِحَضْرَةِ أبي زُرْعَةَ."],[1447,"ثُمَّ إنَّ كَوْنَ الواحِدِ مِنْهُم صَحابيًّا تارَةً يُعْرَفُ بالتَّواتُرِ (٤)، وتارَةً بالاسْتِفاضَةِ القاصِرَةِ عَنِ التواتُرِ، وتارَةً بأنْ يُرْوَى عَنْ آحادِ الصَّحابَةِ أنَّهُ صَحابِيٌّ، وتارَةً بقَوْلِهِ وإخْبَارِهِ عَنْ نَفسِهِ بَعْدَ ثُبُوتِ عَدَالَتِهِ بأنَّهُ صَحَابِيٌّ (٥)، واللهُ أعلمُ."],[1448,"الثَّانِيَةُ: لِلصَّحَابَةِ بأسْرِهِمْ خَصِيْصَةٌ، وهيَ أنَّهُ لا يُسْألُ عَنْ عَدَالَةِ أحَدٍ مِنْهُم، بلْ ذَلِكَ أمرٌ مفروغٌ منهُ لِكَوْنِهِمْ عَلَى الإطْلاقِ مُعَدَّلِيْنَ بِنُصُوصِ الكِتابِ والسُّنَّةِ وإجْماعِ مَنْ يُعْتَدُّ بهِ في الإجماعِ مِنَ الأمَّةِ."],[1449,"قالَ اللهُ تبارك وتعالى: ﴿كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ﴾ (٦) الآيةَ. قيلَ"],[1450,"اتَّفَقَ المفسرونَ عَلَى أنَّهُ وارِدٌ في أصْحابِ رسولِ اللهِ - صلى الله عليه وآله وسلم - (٧)، وقال تَعَالَى: ﴿وَكَذَلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا لِتَكُوْنُوا شُهَدَاءَ عَلَى النَّاسِ﴾ (٨)، وهذا خِطابٌ مَعَ الموجُودِينَ حِيْنَئذٍ (١). وقالَ سبحانه وتعالى: ﴿مُحَمَّدٌ رَسُوْلُ اللهِ والَّذِيْنَ مَعَهُ أشِدَّاءُ عَلَى الكُفَّارِ﴾ (٢) الآيةَ.","",{"fn":"راجع: محاسن الاصطلاح ٤٢٤.\nكذا في (أ) و(ج) و(ع) و(م) والشذا، وفي التقييد: «السيلاني» بالياء المثناة من تحت، ومثله في شرح التبصرة ٣/ ١٢، والجرح والتعديل ٨/ ١٦٩. وفي (ب): «السلاني». راجع: التقييد والإيضاح: ٣٩٩، والأنساب ٣/ ٣٩٢، وتهذيب الكمال ١/ ٢٩١، واللباب ٢/ ١٧٠، والباعث الحثيث ٢/ ٤٩٤.\nأسنده ابن عساكر في تاريخ دمشق ٩/ ٣٧٩، وهو في تهذيب الكمال للمزي ٣/ ٢٧٦.\nراجع محاسن الاصطلاح ٤٢٧، والتقييد والإيضاح ٢٩٩.\nانظر: الكفاية (١٠٠ ت، ٥٢ هـ).\nآل عمران: ١١٠.\nلَمْ نرَ أحدًا نقل الاتفاق في ذلك، وانظر: تفسير الطبري ٤/ ٢٩، وتفسير البغوي ١/ ٤٩١، وزاد المسير ١/ ٤٣٩، وتفسير ابن كثير ١/ ٥٣٠، والدر المنثور ٢/ ٢٩٤.\nالبقرة: ١٤٣."}],[1451,"وفي نُصُوصِ السُّنَّةِ الشاهِدةِ بذلكَ كثرةٌ، منها حديثُ أبي سَعِيْدٍ المتَّفَقُ عَلَى صِحَّتِهِ؛ أنَّ رسُولَ اللهِ - صلى الله عليه وآله وسلم - قالَ: «لا تَسُبُّوا أصْحابِي، فوَالَّذي نَفْسِي بيدِهِ، لوْ أنَّ أحَدَكُمْ أنْفَقَ مِثْلَ أُحُدٍ ذَهَبًا ما أدْرَكَ مُدَّ (٣) أحَدِهِمْ ولا نَصِيْفَهُ» (٤). ثُمَّ إنَّ الأُمَّةَ مُجْمِعَةٌ عَلَى تَعْدِيلِ جَمِيْعِ الصَّحَابَةِ (٥)، ومَنْ لاَبَسَ الفِتَنَ مِنْهُم فكذلكَ بإجْماعِ العلماءِ الَّذِينَ يُعْتَدُّ بهم في الإجماعِ، إحْسانًا للظَّنِّ بهم ونَظَرًا إلى ما تمهَّدَ لهم مِنَ المآثِرِ، وكأَنَّ اللهَ سبحانه وتعالى أتاحَ (٦) الإجماعَ عَلَى ذَلِكَ لِكَوْنِهِمْ نَقَلَةَ الشَّرِيْعَةِ (٧)، واللهُ أعلمُ."],[1452,"الثَّالِثَةُ: أكْثَرُ الصَّحَابَةِ حَدِيثًا عَنْ رسُولِ اللهِ - صلى الله عليه وآله وسلم - أبو هُرَيْرَةَ (٨). رُوِيَ ذَلِكَ عَنْ سَعِيدِ بنِ أبي (٩) الحسَنِ، وأحمدَ بنِ حَنْبَلٍ، وذَلِكَ مِنَ الظاهِرِ الذي لا يَخْفَى عَلَى حَدِيْثِيٍّ، وهوَ أوَّلُ صَاحِبِ حديثٍ (١). بَلَغَنا عَنْ أبي بكرِ بنِ أبي داودَ السِّجسْتانِيِّ قالَ: «رأيْتُ أبا هُرَيْرَةَ في النومِ وأنا بِسَجستانَ أُصَنِّفُ حديثَ أبي هُرَيْرَةَ، فقُلْتُ (٢): إنِّي لأُحِبُّكَ، فقالَ: أنا أوَّلُ صَاحِبِ حديثٍ كانَ في الدُّنْيا».","",{"fn":"انظر: تفسير البغوي ١/ ١٧٤.\nالفتح: ٢٩.\nالْمُدُّ - بضم الميم - مكيال معروف، وإنما قَدَّره به؛ لأنه أقل ما كانوا يتصدقون به في العادة. وحكى الخطّابي أنَّهُ روي بفتح الميم قال: والمراد به: الفضل والطول. والنصيف بوزن رغيف، هو النصف كما يقال: عشر عشير، وقيل: النصيف هنا مكيال يكال به، وهو دون المد. انظر: النهاية ٤/ ٣٠٨، وفتح الباري ٧/ ٣٤، وعمدة القاري ١٦/ ١٨٨.\nأخرجه الطيالسي (٢١٨٣)، وعلي بن الجعد (٧٦٠) و(٣٥٥٣)، وابن أبي شيبة ١٢/ ١٧٤، وأحمد ٣/ ١١ و٥٤، وفي الفضائل (٥) و(٦) و(٧)، وعبد بن حميد (٩١٨)، والبخاري ٥/ ١٠، ومسلم ٧/ ١٨٨، وأبو داود (٤٦٥٨)، وابن أبي عاصم (٩٨٨) إلى (٩٩١)، والترمذي (٣٨٦١)، والبزار (٢٧٦٨)، وأبو يعلى (١٠٨٧) و(١١٩٨)، وابن حبان (٦٩٩٤)، والخطيب البغدادي ٧/ ١٤٤، والبغوي (٣٥٩) من حديث أبي سعيد الخدري.\nلذا قال الحافظ ابن حجر في الإصابة ١/ ١١: «والقول بالتعميم هو الذي صرح به الجمهور، وهو المعتبر».\nتاح له الشيء، وأتيح له الشيء، أي: قُدّرَ لهُ، وأتاح له الشىء، أي قدره له. الصحاح ١/ ٣٥٦.\nراجع التقييد: ٣٠١.\nراجع: محاسن الاصطلاح ٤٢٩، وشرح التبصرة ٣/ ٢١.\nسقطت من (م)."}],[1453,"وَعَنْ أحمدَ بنِ حَنْبَلٍ أيضًا - رضي الله عنه - قالَ: «سِتَّةٌ مِنْ أصْحابِ النبيِّ - صلى الله عليه وآله وسلم - أكثروا الروايةَ عنهُ وَعُمِّروا: أبو هُريرةَ، وابنُ عُمَرَ، وعائشةُ، وجابِرُ بنُ عبدِ اللهِ، وابنُ عبَّاسٍ، وأنَسٌ، وأبو هُرَيْرَةَ أكْثَرُهُمْ حديثًا وحَمَلَ عنهُ الثِّقاتُ»."],[1454,"ثُمَّ إنَّ أكثَرَ الصحابةِ فُتْيا تُرْوَى ابنُ عباسٍ. بَلَغَنا عَنْ أحمدَ بنِ حَنْبَلٍ قالَ: «ليسَ أحَدٌ مِنْ أصْحابِ النبيِّ - صلى الله عليه وآله وسلم - يُرْوَى عنهُ في الفتْوى أكثرَ مِنِ ابنِ عَبَّاسٍ»."],[1455,"ورُوِّيْنا عَنْ أحمدَ بنِ حَنْبَلٍ أيضًا أنَّهُ قِيلَ لهُ: «مَنِ العَبادِلَةُ؟»، فقالَ: «عبدُ اللهِ ابنُ عَبَّاسٍ، وعبدُ اللهِ بنُ عُمَرَ، وعبدُ اللهِ بنُ الزُّبَيرِ، وعبدُ اللهِ بنُ عَمْرٍو». قيلَ لهُ:"],[1456,"«فابنُ مَسعودٍ؟»، قالَ: «لا، ليسَ عبدُ اللهِ بنُ مسعودٍ مِنَ العبادلةِ» (٣). قالَ الحافِظُ أحمدُ البَيْهَقِيُّ فيما رُوِّيْناهُ عنهُ وقرأْتُهُ بِخَطِّهِ: «وهذا لأنَّ ابنَ مسعودٍ تَقَدَّمَ مَوْتُهُ، وهؤلاءِ عاشُوا حَتَّى احتِيْجَ إلى عِلْمِهِمْ، فإذا اجْتَمَعُوا عَلَى شيءٍ قيلَ: هذا قَوْلُ العبادِلَةِ، أوْ: هذا فِعْلُهُمْ» (٤)."],[1457,"قُلْتُ: ويَلْتَحِقُ بابنِ مَسعودٍ في ذَلِكَ سائِرُ العبادِلَةِ الْمُسَمَّيْنَ بعبدِ اللهِ مِنَ الصحابةِ، وهُمْ نَحْوُ مِئَتَيْنِ وعِشْرِينَ نَفْسًا (٥)، واللهُ أعلمُ."],[1458,"ورُوِّيْنا عَنْ عليِّ بنِ عبدِ اللهِ المدينيِّ قالَ: «لَمْ يَكُنْ مِنْ أصحابِ النبيِّ - صلى الله عليه وآله وسلم - أحَدٌ لهُ أصْحابٌ يَقُومونَ بقَوْلِهِ في الفِقْهِ إلاَّ ثَلاثَةٌ: عبدُ اللهِ بنُ مسعودٍ، وزيدُ بنُ ثابِتٍ، وابنُ عبَّاسٍ - رضي الله عنهم -، كانَ لِكُلِّ رجلٍ مِنْهُم أصحابٌ يَقُومونَ بقَولِهِ ويُفْتونَ النَّاسَ» (١)، وَرُوِّيْنا عَنْ مَسْروقٍ قالَ: «وَجَدْتُ عِلْمَ أصْحابِ النبيِّ - صلى الله عليه وآله وسلم - انتهى إلى سِتَّةٍ: عُمَرَ، وعَلِيٍّ، وأُبَيٍّ، وزيدٍ، وأبي الدَّرْداءِ، وعبدِ اللهِ بنِ مَسْعودٍ. ثُمَّ انتهى عِلْمُ هَؤلاءِ السِّتَّةِ إلى اثْنَيْنِ: عليٍّ، وعبدِ اللهِ» (٢). رُوِّيْنا نَحْوَهُ عَنْ مُطَرِّفٍ (٣) عَنِ الشَّعْبِيِّ عَنْ مَسْرُوقٍ، لكنْ ذَكَرَ أبا موسَى بدَلَ أبي الدَّرْدَاءِ (٤). ورُوِّيْنا عَنِ الشَّعْبِيِّ قالَ: «كانَ العِلْمُ يُؤْخَذُ عَنْ سِتَّةٍ مِنْ أصحابِ رسولِ اللهِ - صلى الله عليه وآله وسلم -، وكانَ عُمَرُ، وعبدُ اللهِ، وزيدٌ، يُشْبِهُ عِلْمُ بعضِهِمْ بَعضًا، وكانَ يَقْتَبِسُ بَعضُهُمْ مِنْ بَعضٍ، وكانَ عليٌّ، والأشْعَريُّ، وأُبَيٌّ، يُشْبِهُ عِلْمُ بعضِهِمْ بَعضًا، وكانَ يَقْتَبِسُ بَعضُهُمْ مِنْ بَعضٍ» (٥). ورُوِّيْنا عَنِ الحافِظِ أحمدَ البَيْهَقِيِّ أنَّ الشَّافِعِيَّ ذَكَرَ الصَّحابَةَ في \" رسالتِهِ \" القديمةِ وأثْنَى عليهِمْ بما هُمْ أهلُهُ، ثُمَّ قالَ: «وهُمْ فَوْقَنا في كُلِّ عِلْمٍ، واجْتِهادٍ، وَوَرَعٍ، وعَقْلٍ، وأمْرٍ اسْتُدْرِكَ بهِ عِلْمٌ واسْتُنْبِطَ بهِ، وآراؤُهُمْ لنا أحمدُ وأوْلَى بنا مِنْ آرَائِنا عِنْدَنا لأنْفُسِنا»، واللهُ أعلمُ.","",{"fn":"قال الشافعي رحمه الله: «أبو هريرة أحفظ من روى الحديث في دهره». الرسالة: ٢٨١، وانظر: تهذيب الأسماء واللغات ٢/ ٢٧٠.\nفي (أ): «فقلت له».\nنقله النووي في تهذيب الأسماء واللغات ١/ ٢٦٧.\nنقله النووي في تهذيب الأسماء واللغات ١/ ٢٦٧.\nراجع: محاسن الاصطلاح ٤٣٠، والتقييد والإيضاح ٣٠٣، وفي الإصابة أسماء كثيرة ممن اسمه عبد الله. انظر: ٢/ ٢٧٣ - ٣٨٧ منه."}],[1459,"الرَّابِعَةُ: رُوِّيْنا عَنْ أبي زُرْعَةَ الرَّازِيِّ أنَّهُ سُئِلَ عَنْ عِدَّةِ (٦) مَنْ رَوَى عَنِ النبيِّ - صلى الله عليه وآله وسلم -، فقالَ: «ومَنْ يَضْبِطُ هذا؟ شَهِدَ مَعَ النبيِّ - صلى الله عليه وآله وسلم - حَجَّةَ الوداعِ أربعونَ ألِفًا، وشَهِدَ معهُ تَبُوكَ سَبعونَ ألفًا (٧). ورُوِّيْنا عَنْ أبي زُرْعَةَ أيضًا أنَّهُ قيلَ لهُ: «ألَيْسَ يُقَالَ: حديثُ النبيِّ - صلى الله عليه وآله وسلم - أربَعةُ آلاَفِ حديثٍ؟»، قالَ: «ومَنْ قالَ ذا؟ قَلْقَلَ اللهَ أنْيَابَهُ! هذا قولُ الزَّنَادِقَةِ، ومَنْ يُحْصِي حدِيثَ رسولِ اللهِ - صلى الله عليه وآله وسلم -، قُبِضَ رسُولُ اللهِ - صلى الله عليه وآله وسلم - عَنْ مِئَةِ ألْفٍ وأربَعَةَ عَشَرَ ألِفًا مِنَ الصحابةِ مِمَّنْ رَوى عنهُ، وسَمِعَ منهُ، وفي روايةٍ مِمَّنْ رآهُ وسَمِعَ منهُ». فقِيْلَ لهُ: يا أبا زُرْعَةَ! هؤلاءِ أينَ كانُوا وأينَ سَمِعُوا منهُ؟ قالَ: «أهلُ المدينةِ، وأهلُ مَكَّةَ، ومَنْ بينَهُما، والأعرابُ، ومَنْ شَهِدَ معهُ حَجَّةَ الوداعِ كُلٌّ رآهُ وسَمِعَ منهُ بِعَرَفَةَ» (١).","",{"fn":"العلل لابن المديني: ٤٥، ورواه عنه البيهقي في المدخل (١٥٥)، والخطيب في الجامع ٢/ ٢٨٨ (١٨٨٤).\nأخرجه ابن سعد في طبقاته ٢/ ٣٥١، وابن المديني في العلل: ٤٤، ويعقوب بن سفيان في المعرفة والتاريخ ١/ ٤٨١.\nبضم الميم، وفتح الطاء المهملة وكسر الراء المشددة كَمُحَدِّث. انظر: الإكمال ٧/ ٢٠٠، وتاج العروس ٢٤/ ٨٥.\nطبقات ابن سعد ٢/ ٣٥١.\nأخرجه أبو خيثمة في العلم (٩٤)، والبيهقي في المدخل (١١٩).\nراجع: التقييد والإيضاح: ٣٠٥.\nأخرجه الخطيب في الجامع (١٨٩٣)."}],[1460,"قُلْتُ (٢): ثُمَّ إنَّهُ اخْتُلِفَ في عدَدِ طَبَقَاتِهِمْ وأصْنافِهِمْ، والنَّظَرُ في ذَلِكَ إلى السَّبْقِ بالإسْلامِ والهِجْرَةِ وشُهُودِ المشاهَدِ الفاضِلَةِ مَعَ رَسُولِ اللهِ - صلى الله عليه وآله وسلم - بآبَائِنا وأُمَّهَاتِنا وأنْفُسِنا هوَ - صلى الله عليه وآله وسلم - وجَعَلَهُمُ الحاكِمُ (٣) أبو عبدُ اللهِ اثْنَتَي عَشْرَةَ (٤) طَبَقَةً، ومنهُمْ مَنْ زادَ عَلَى ذَلِكَ، ولَسْنا نُطَوِّلُ بتفصِيلِ ذَلِكَ، واللهُ أعلمُ."],[1461,"الخامِسَةُ: أفْضَلُهُمْ عَلَى الإطْلاَقِ أبو بكرٍ، ثُمَّ عُمَرَ (٥)، ثُمَّ إنَّ جُمْهُورَ السَّلَفِ عَلَى تقدِيمِ عُثْمانَ عَلَى عليٍّ، وقَدَّمَ أهلُ الكُوفةِ مِنْ أهلِ السُّنَّةِ عَلِيًّا عَلَى عُثْمانَ، وبهِ قالَ مِنْهُم: سُفْيانُ الثَّوْرِيُّ (٦) أوَّلًا ثُمَّ رَجَعَ إلى تقديمِ عُثْمانَ (٧)، رَوَى ذَلِكَ عنهُ وعَنْهُم الخطَّابِيُّ (٨). ومِمَّنْ نُقِلَ عنهُ مِنْ أهلِ الحديثِ تقديمُ عليٍّ عَلَى عُثْمانَ مُحَمَّدُ بنُ إسْحاقَ ابنِ خُزَيْمةَ (٩). وتقديمُ عُثْمانَ هوَ الذي اسْتَقَرَّتْ عليهِ مَذاهِبُ أصْحابِ الحديثِ وأهلِ السُّنَّةِ (١٠)، وأمَّا أفضلُ أصْنافِهِمْ صِنْفًا فقَدْ قالَ أبو مَنْصورٍ البغداديُّ التَّمِيميُّ: أصْحابُنا مُجْمِعونَ عَلَى أنَّ أفضَلَهم الخلفاءُ الأربَعَةُ، ثُمَّ السِّتَّةُ الباقُونَ إلى تَمامِ العَشَرَةِ، ثُمَّ البَدْرِيونَ، ثُمَّ أصحابُ أُحُدٍ، ثُمَّ أهلُ بَيْعَةِ الرِّضْوانِ بالْحُدَيْبِيَةِ (١).","",{"fn":"أسنده إليه الخطيب في الجامع (١٨٩٤).\nفي (ع): «قال المؤلف»، وما أثبتناه من النسخ و(م).\nمعرفة علوم الحديث: ٢٢ - ٢٤.\nفي (جـ): «اثني عشر»، وفي (ع): «اثنتي عشر طبقة».\nعبارة: «ثُمَّ عمر» لَمْ ترد في (م).\nأسنده إليه الخطابي في معالم السنن ٧/ ١٨.\nقال الخطابي في المعالم ٧/ ١٨: «وقد نبئت عن سفيان أنه قال في آخر قوليه: «أبو بكر وعمر وعثمان وعلي» ...».\nفي (م): «روى ذلك عنه جماعة ومنهم الخطابي».\nنقله عنه الخطابي في معالم السنن ٧/ ١٨.\nقال العراقي في شرح التبصرة والتذكرة ٣/ ٣٣: «والذي استقر عليه أهل السنة تقديم عثمان، لما روى البخاري، وأبو داود، والترمذي من حديث ابن عمر، قال: «كنا في زمن النبي - صلى الله عليه وآله وسلم - لا نعدل بأبي بكر أحدًا، ثم عمر، ثم عثمان». والحديث في صحيح البخاري ٥/ ٥ (٣٦٥٥) و٥/ ١٨ (٣٦٩٨)، وسنن أبي داود (٤٦٢٧)، وجامع الترمذي (٣٧٠٧)."}],[1462,"قلتُ: وفي نصِّ القُرْآنِ تَفضيلُ (٢) السَّابِقِينَ الأوَّلِينَ مِنَ المهاجِرِيْنَ والأنْصَارِ، وهُمُ الذِيْنَ صَلُّوا إلى القِبْلَتَيْنِ في قَوْلِ سَعِيْدِ بنِ المسيِّبِ (٣) وطائِفَةٍ (٤). وفي قَوْلِ الشَّعْبِيِّ: هُمُ الذِينَ شَهِدُوا بَيْعَةَ الرِّضْوانِ (٥). وعَنْ مُحَمَّدِ بنِ كَعْبٍ القُرَظِيِّ (٦) وعَطَاءِ بنِ يَسارٍ أنَّهُما قالاَ: هُمْ أهلُ بَدْرٍ (٧)، رَوَى ذَلِكَ عَنْهُما ابنُ عبدِ البرِّ فيما وَجَدْناهُ عنهُ، واللهُ أعلمُ."],[1463,"السَّادِسَةُ: اختَلَفَ السَّلَفُ في أوَّلِهِمْ إسْلامًا، فقيلَ: أبو بكرٍ (٨) الصِّدِّيقُ، رُوِيَ ذَلِكَ عَنِ ابنِ عباسٍ (٩)، وحَسَّانَ بنِ ثابتٍ (١٠)، وإبراهيمَ النَّخَعِيِّ (١١)، وغيرِهِمْ (١). وقيلَ: عليٌّ أوَّلُ مَنْ أسلَمَ، رُوِيَ ذَلِكَ عنْ زيدِ بنِ أرْقَمَ (٢)، وأبي ذَرٍّ (٣)، والمقْدَادِ (٤) وغيرِهِمْ (٥). قالَ الحاكِمُ أبو عبدِ اللهِ: «لا أعلمُ خِلافًا بَيْنَ أصحابِ التَّوارِيخِ (٦) أنَّ عليَّ بنَ أبي طالِبٍ أوَّلُهُمْ إسْلامًا»، واسْتُنْكِرَ هذا مِنَ الحاكِمِ. وقيلَ: أوَّلُ مَنْ أسلمَ زيدُ بنُ حارِثَةَ. وذَكَرَ مَعْمَرٌ نحوَ ذَلِكَ عَنِ الزُّهْرِيِّ (٧). وقيلَ: أوَّلُ مَنْ أسلمَ خديجةُ أُمُّ المؤمِنينَ، رُوِيَ ذَلِكَ مِنْ وُجُوهٍ عَنِ الزُّهْرِيِّ (٨)، وهوَ قَوْلُ قَتَادَةَ (٩)، ومُحَمَّدِ بنِ إسْحاقَ بنِ يَسارٍ (١٠)، وجماعةٍ. ورُوِيَ أيضًا عَنِ ابنِ عبَّاسٍ (١١). وادَّعَى الثَّعْلَبِيُّ المفَسِّرُ فيما رُوِّيْناهُ أو بَلَغَنا عنهُ اتِّفَاقَ العلماءِ عَلَى أنَّ أوَّلَ مَنْ أسلمَ خديجةُ، وأنَّ اختِلاَفَهُمْ إنَّما هوَ في أوَّلِ مَنْ أسْلمَ بعدَها.","",{"fn":"أصول الدين لأبي منصور البغدادي: ٣٠٤. والحديبية - بضم الحاء وفتح الدال المهملتين، وياء ساكنة، وكسر الباء الموحدة وياء مخففة مفتوحة كـ: دُوَيْهِيَة، وَقَدْ تُشدَّد ياؤها أيضًا -. انظر: عمدة القاري ١٧/ ٢١٢، ومراصد الاطلاع ١/ ٣٨٦، وتاج العروس ٢/ ٢٤٦.\nإشارة إلى قوله تَعَالَى: ﴿السَّابِقُونَ الأَوَّلُونَ مِنَ المهَاجِرِيْنَ والأنْصَارِ﴾. التوبة: ١٠٠.\nأخرجه الطبري في تفسيره ١١/ ٧، وابن عبد البر في الاستيعاب ١/ ٦.\nمنهم: ابن سيرين. انظر: الاستيعاب ١/ ٦ - ٧.\nأخرجه الطبري في تفسيره ١١/ ٦، وابن عبد البر في الاستيعاب ١/ ٧.\nبضم القاف، وفتح الراء المهملة. انظر: الأنساب ٤/ ٤٥٤.\nأخرجه ابن عبد البر في الاستيعاب ١/ ٧.\nراجع: التقييد والإيضاح: ٣٠٨.\nالاستيعاب ٢/ ٢٨.\nالمصدر السابق.\nالاستيعاب ٢/ ٢٤٥."}],[1464,"والأوْرَعُ (١٢) أنْ يُقَالَ: أوَّلُ مَنْ أسْلمَ مِنَ الرِّجالِ الأحرارِ: أبو بكرٍ، ومِنَ الصِّبْيانِ أو الأحداثِ: عليٌّ، ومِنَ النِّساءِ: خديجةُ، ومِنَ الموالِي: زيدُ بنُ حارِثةَ، ومِنَ العبيدِ: بلالٌ، واللهُ أعلمُ."],[1465,"السَّابعةُ: آخِرُهُمْ عَلَى الإطلاقِ موتًا: أبو الطُّفَيْلِ عامرُ بنُ واثِلَةَ (١٣)، ماتَ سنةَ مئةٍ مِنَ الهِجرةِ. وأمَّا بالإضافَةِ إلى النَّواحي، فآخِرُ مَنْ ماتَ مِنْهُم بالمدينةِ: جابرُ بنُ عبدِ اللهِ، رواهُ أحمدُ بنُ حَنْبَلٍ عَنْ قَتادةَ، وقيلَ: سَهْلُ بنُ سَعْدٍ (١٤)، وقيلَ: السَّائبُ ابنُ يَزيدَ (١٥)، وآخِرُ مَنْ ماتَ مِنْهُم بِمَكَّةَ عبدُ اللهِ بنُ عُمَرَ، وقيلَ: جابرُ بنُ عبدِ اللهِ.","",{"fn":"كابن المنكدر وربيعة وصالح بن كيسان وعثمان بن محمد. الإصابة ٢/ ٣٤٣ - ٣٤٤.\nالاستيعاب ٣/ ٢٧.\nالمصدر السابق.\nالمصدر نفسه.\nكسلمان الفارسي وخباب وجابر وأبي سعيد الخدري. الاستيعاب ٣/ ٢٧.\nراجع: التقييد ٣٠٨.\nالاستيعاب ١/ ٥٢٨.\nالاستيعاب ١/ ٥٤٨ و٤/ ٢٨٢.\nالاستيعاب ٤/ ٢٨٢.\nالمصدر السابق.\nالاستيعاب ٤/ ٢٨٢.\nنُسِبَ هذا القول لأبي حنيفة كما أشار إلى ذلك ابن الملقن في المقنع ٢/ ٥٠١، والسيوطي في التدريب ٢/ ٢٢٨.\nراجع: التقييد ٣١٢.\nالثقات ٣/ ١٦٨.\nالإصابة ٢/ ١٢."}],[1466,"وذَكَرَ عليُّ بنُ المدينيِّ أنَّ أبا الطُّفَيلِ بِمَكَّةَ ماتَ فهوَ إذَنْ الآخِرُ بها (١). وآخِرُ مَنْ ماتَ مِنْهُم بالبَصْرَةِ أنَسُ بنُ مالِكٍ. قالَ أبو عُمَرَ بنُ عبدِ البرِّ: «ما أعلمُ أحدًا ماتَ بعدَهُ مِمَّنْ رَأَى رَسولَ اللهِ - صلى الله عليه وآله وسلم - إلاَّ أبا الطُّفَيلِ» (٢). وآخِرُ مَنْ ماتَ مِنْهُم بالكُوفَةِ: عبدُ اللهِ بنُ أبي أوْفَى، وبالشَّامِ: عبدُ اللهِ بنُ بُسْرٍ، وقِيْلَ: بلْ أبو أُمامَةَ. وتَبَسَّطَ (٣) بعضُهُمْ فقالَ: «آخِرُ مَنْ ماتَ مِنْ أصحابِ رَسُولِ اللهِ - صلى الله عليه وآله وسلم - بِمِصْرَ: عبدُ اللهِ بنُ الحارِثِ بنِ جَزْءٍ (٤) الزُّبَيْدِيُّ، وبِفِلَسْطِيْنَ (٥): أبو أُبَيِّ بنُ أُمِّ حَرَامٍ، وبِدِمَشْقَ: واثِلَةُ بنُ الأسْقَعِ، وبِحِمْصَ: عبدُ اللهِ بنُ بُسْرٍ (٦)، وباليَمامَةِ: الهِرْماسُ (٧) بنُ زَيادٍ، وبالْجَزِيْرَةِ (٨): العُرْسُ (٩) بنُ عَمِيْرَةَ (١٠)، وبإفْرِيقِيَّةَ (١١): رُوَيْفِعُ (١٢) بنُ ثابتٍ، وبالبادِيَةِ في الأعْرابِ: سَلَمَةُ بنُ الأكْوَعِ، - رضي الله عنهم - أجمعينَ»."],[1467,"وفي بعضِ ما ذَكَرْناهُ خِلافٌ لَمْ نَذْكُرْهُ، وقولُهُ في رُوَيْفِعٍ بإفْرِيقِيَّةَ لا يَصِحُّ إنَّما ماتَ في حاضِرَةِ بَرْقَةَ (١٣) وقَبْرُهُ بها، ونَزَلَ سَلَمةُ إلى المدينةِ قَبْلَ مَوْتِهِ بِلَيالٍ فَمَاتَ بها، واللهُ أعلمُ.","",{"fn":"راجع: محاسن الاصطلاح ٤٣٦، والتقييد والإيضاح ٣١٥.\nالاستيعاب ١/ ٧٣.\nراجع: التقييد ٣١٥.\nبفتح الجيم وسكون الزاي بعدها همزة، والزُّبيدي - بضم الزاي - التقريب (٣٢٦٢).\nبكسر الفاء وفتح اللام وسكون السين. انظر: مراصد الاطلاع ٣/ ١٠٤٢.\nبضم الباء الموحدة وإسكان السين المهملة. انظر: الإكمال ١/ ٢٦٨، والتقريب (٣٢٢٨).\nبكسر الهاء وإسكان الراء وآخره سين مهملة. انظر: تاج العروس ١٧/ ٣٢.\nهي ما بين دجلة والفرات من العراق. انظر: اللسان ٤/ ١٣٣.\nبضم أوله وسكون الراء بعدها مهملة. التقريب (٤٥٥٢).\nبفتح العين المهملة وكسر الميم. انظر: فتح المغيث ٣/ ١١٩.\nبكسر الهمزة. انظر: مراصد الاطلاع ١/ ١٠٠.\nبضم الراء وكسر الفاء مصغر. انظر: فتح المغيث ٣/ ١٢٠.\nبفتح أوله. انظر: مراصد الاطلاع ١/ ١٨٦."}],[1468,"النوع الموفي أربعين معرفة التابعين"],[1469,"(١)"],[1470,"هذا وَمَعرفةُ الصحابةِ أصْلٌ أصِيْلٌ يُرْجَعُ إليهِ في معرفةِ المرسَلِ والمسْنَدِ. قالَ الخطيبُ الحافِظُ: «التَّابِعِيُّ مَنْ صَحِبَ الصَّحَابِيَّ» (٢)."],[1471,"قُلتُ: ومطلقُهُ مَخْصُوصٌ بالتَّابِعِ بإحْسَانٍ، ويُقَالُ لِلْواحِدِ مِنْهُم: تابِعٌ وتابِعِيٌّ. وكَلامُ الحاكِمِ أبي عبدِ اللهِ (٣) وغيرُهُ مُشْعِرٌ بأنَّهُ يَكْفِي فيهِ أنْ يسمَعَ مِنَ الصَّحابِيِّ أوْ يَلْقاهُ وإنْ لَمْ تُوجدْ الصُّحْبَةُ العُرْفِيَّةُ. والاكْتِفاءُ في هذا بِمُجَرَّدِ اللِّقَاءِ والرؤْيَةِ (٤) أقربُ منهُ في الصحابِيِّ نَظَرًا إلى مُقْتَضى اللَّفْظَيْنِ فيهما (٥)."],[1472,"وهذهِ مُهِمَّاتٌ في هذا النوعِ:"],[1473,"إحْدَاها: ذَكَرَ الحافِظُ أبو عبدِ اللهِ أنَّ التَّابِعينَ عَلَى خَمْسَ عَشْرَةَ طَبَقَةً:"],[1474,"الأُوْلَى: الَّذِينَ لَحِقُوا العَشَرَةَ: سَعيدُ بنُ المسَيِّبِ، وقيسُ بنُ أبي حازِمٍ، وأبو عُثْمانَ النَّهْدِيُّ (٦)، وقيسُ بنُ عُبادٍ (٧)، وأبو سَاسَانَ حُضَيْنُ (٨) بنُ المنذِرِ، وأبو وائِلٍ، وأبو رَجَاءِ العُطَارِدِيُّ (١) وغيرُهُمْ (٢). وعليهِ في بعضِ هؤلاءِ إنْكارٌ، فإنَّ سَعيدَ بنَ المسَيِّبِ ليسَ بهذهِ المثابةِ؛ لأنَّهُ وُلِدَ في خِلافةِ عُمَرَ، ولَمْ يَسْمَعْ مِنَ أكثَرِ العَشَرَةِ. وقدْ قالَ بعضُهُمْ: لا تَصِحُّ (٣) لهُ رِوايةٌ عَنْ أحَدٍ مِنَ العَشَرَةِ إلاَّ سَعْدَ ابنَ أبي وَقَّاصٍ (٤).","",{"fn":"انظر في ذلك: معرفة علوم الحديث: ٤١ - ٤٦، والإرشاد ٢/ ٦٠٦ - ٦١٦، والتقريب: ١٦٥ - ١٦٧، واختصار علوم الحديث: ١٩١ - ١٩٤، والشذا الفياح ٢/ ٥١٩ - ٥٣٤، والمقنع ٢/ ٥٠٦ - ٥١٧، وفتح المغيث ٣/ ١٣٩ - ١٥٦، وتدريب الراوي ٢/ ٢٣٤ - ٢٤٣، وتوضيح الأفكار ٢/ ٤٧١ - ٤٧٣، وظفر الأماني: ٥١٣ - ٥١٤.\nالكفاية: (٥٩ ت، ٢٢ هـ)، وانظر: التقييد ٣١٧.\nمعرفة علوم الحديث: ٤٢.\nفي (ب): «والرواية».\nراجع: محاسن الاصطلاح ٤٤٤.\nبفتح النون وسكون الهاء. التقريب (٤٠١٧).\nبضم المهملة وتخفيف الموحدة. التقريب (٥٥٨٢).\nفي (ب) و(م) والتقييد: «حصين» بالصاد المهملة خطأ، والصواب ما أثبت فهو بضم الحاء المهملة، وفتح الضاد المعجمة، مصغر. انظر: الإكمال ٢/ ٤٨١، وتهذيب الكمال ٢/ ٢١٩، وتبصير المنتبه ١/ ٤٤٤، والتقريب (١٣٩٧)."}],[1475,"قُلْتُ: وكانَ سَعْدٌ آخِرَهُمْ مَوْتًا. وذَكَرَ الحاكِمُ قبلَ كَلامِهِ المذكورِ: أنَّ سَعِيْدًا أدْرَكَ عُمَرَ فَمَنْ بَعْدَهُ إلى آخِرِ العَشَرَةِ (٥)، وقالَ: ليسَ في جماعَةِ التَّابِعينَ مَنْ أدْرَكَهُمْ وسَمِعَ مِنْهُم غيرُ سَعِيدٍ، وقيسِ بنِ أبي حازِمٍ (٦)، وليسَ ذَلِكَ عَلَى ما قالَ كما ذَكَرْناهُ. نَعَمْ، قَيسُ بنُ أبي حازِمٍ سَمِعَ العَشَرَةَ ورَوَى عَنْهُم. وليسَ في التَّابِعينَ أحَدٌ رَوَى عَنِ العَشَرَةِ سِواهُ، ذَكَرَ ذَلِكَ عبدُ الرَّحمانِ بنُ يُوسُفَ بنِ خِرَاشٍ (٧) الحافِظُ فيما رُوِّيْنا أوْ بَلَغَنا عنهُ. وعنْ أبي داودَ السِّجستانِيِّ أنَّهُ قالَ: رَوَى عَنِ التِّسْعَةِ ولَمْ يَرْوِ عَنْ عبدِ الرَّحْمانِ بنِ عَوْفٍ (٨).","",{"fn":"بضم العين وفتح الطاء وكسر الراء والدال المهملات. انظر: الأنساب ٤/ ١٨٤.\nمعرفة علوم الحديث: ٤٢، وانظر: محاسن الاصطلاح: ٤٤٥.\nراجع: التقييد والإيضاح: ٣٢٠.\nهذا القول ليس بشيء، فحديثه عن عثمان وعلي في الصحيحين. تهذيب الكمال ٣/ ١٩٩، وصح عنه أنه قال: «شهدت عليًا وعثمان». أخرجه أحمد في العلل: ٢٠٥٣. وكذلك رأى عمر وسمع منه، لكنه كان صغيرًا، ولم يكن سماعه منه لشيء كثير؛ لذا نفاه من نفاه، وقد صح عنه أنَّهُ قال: «ولدت لسنتين مضتا من خلافة عمر». المراسيل: ٧٣. وأخرج البخاري في التاريخ الصغير ١/ ٥٦ و٢١٦ عنه قال: «إني لأذكر يوم نعى عمر بن الخطاب النعمان بن مقرن عَلَى المنبر». وقد قال الإمام أحمد حين سأله أبو طالب صاحبه: «سعيد عن عمر حجة؟ قَالَ: هو عندنا حجة، قد رأى عمر وسمع منه، إذا لَمْ يُقْبَل سعيد عن عمر فمن يقبل؟». الجرح والتعديل ٤/ ٦١.\nمعرفة علوم الحديث: ٢٥.\nالمصدر السابق.\nتاريخ دمشق ٤٩/ ٤٦١ ذكره مسندًا، وهو في تهذيب الكمال ٦/ ١٣٠ (٥٤٨٥).\nسؤالات الآجري (٤٥)، وأورده عن الآجري ابن عساكر في تاريخ دمشق ٤٩/ ٤٦١."}],[1476,"ويَلِي هؤلاءِ: التَّابِعُونَ الَّذِينَ وُلِدُوا في حياةِ رَسُولِ اللهِ - صلى الله عليه وآله وسلم - مِنْ أبْناءِ الصَّحابَةِ (١)، كَعَبْدِ اللهِ بنِ أبي طَلْحَةَ، وأبي أُمامةَ أسْعَدَ بنِ سَهْلِ بنِ حُنَيْفٍ (٢)، وأبي إدْرِيْسَ الْخَوْلاَنِيِّ (٣) وغيرِهِمْ."],[1477,"الثَّانِيةُ: الْمُخَضْرَمُونَ (٤) مِنَ التَّابِعينَ هُمُ الَّذِيْنَ أدركوا الجاهِلِيَّةَ وحياةَ رَسُولِ اللهِ - صلى الله عليه وآله وسلم - وأسْلَمُوا ولا صُحْبَةَ لهم، واحدُهُمْ مُخَضْرَمٌ -بِفَتْحِ الرَّاءِ- كأنَّهُ خُضْرِمَ، أي: قُطِعَ عَنْ نُظَرائِهِ الَّذِينَ أدْركُوا الصُّحْبَةَ وغيرَها. وذَكَرَهُمْ مُسْلِمٌ فَبَلَغَ بِهِمْ عِشْرينَ نَفْسًا (٥)، مِنْهُم: أبو عَمْرٍو الشَّيْبانِيُّ، وسُوَيْدُ بنُ غَفَلةَ (١) الكِنْدِيُّ، وعَمْرُو بنُ مَيْمُونٍ الأَوْدِيُّ، وعَبْدُ خَيْرِ بنُ يَزِيْدَ الْخَيْوَانِيُّ (٢)، وأبو عُثْمانَ النَّهْدِيُّ، وعبدُ الرحمانِ بنُ مَلٍّ (٣)، وأبو الحلالِ العَتَكِيُّ (٤): رَبيعةُ بنُ زُرارةَ. ومِمَّنْ لَمْ يَذْكُرْهُ مُسْلِمٌ مِنْهُم: أبو مُسْلِمٍ الْخَوْلاَنيُّ: عبدُ اللهِ بنُ ثُوَبٍ (٥)، والأحْنَفُ بنُ قَيسٍ، واللهُ أعلمُ (٦).","",{"fn":"تعقبه البلقيني في المحاسن: ٤٤٦ فقال: «هذا الكلام ليس بمستقيم معنًى ولا نقلًا: أما المعنى، فكيف يجعل من ولد في حياة رسول الله يلي من ولد بعده - صلى الله عليه وآله وسلم -؟ والصواب أن يكون من ولد في حياته مقدمًا، وأن تلك الطبقة تليه، لا أنَّهُ يليها». وأما النقل، فلم يذكر الحاكم ذلك، ولكنه عد المخضرمين ثم قال: «ومن التابعين بعد المخضرمين طبقة ولدوا في زمان رسول الله ولم يسمعوا منه ...». وانظر: معرفة علوم الحديث: ٤٤.\nبضم الحاء وفتح النون. انظر: الإكمال ٢/ ٥٥٩.\nبضم الخاء المعجمة وسكون الواو. انظر: الأنساب ٢/ ٤٨٧.\nقال العراقي في التقييد والإيضاح: ٣٢٢: «اقتصر المصنف عَلَى أن المخضرم مأخوذ من الخضرمة، وهي القطع، وأنه بفتح الراء، والذي رجّحه العسكري في اشتقاقه غير ما ذكره المصنف، فقال في كتاب الأوائل المخضرمة من الإبل التي نتجت من العراب، واليمانية فقيل: رجل مخضرم إذا عاش في الجاهلية والإسلام قال: وهذا أعجب القولين إليَّ قلت (القائل هو العراقي): فكأنه مأخوذ من الشيء المتردد بين أمرين هل هو من هذا أو من هذا، قال الجوهري: لحم مخضرَم - بفتح الراء - لا يدرى من ذكر هو أم أنثى. قال: والمخضرم أيضًا: الشاعر الذي أدرك الجاهلية والإسلام مثل لبيد، ورجل مخضرم النسب أي: دَعِيّ، وقال صاحب المحكم: رجل مخضرم إذا كان نصف عمره في الجاهلية ونصفه في الإسلام. ورجل مخضرم أبوه أبيض وهو أسود. ورجل مخضرم: ناقص الحسب، وقيل: هو الذي ليس بكريم النسب، وقيل: هو الدعي ... فالمخضرم عَلَى هذا متردد بين الصحابة لإدراكه زمن الجاهلية والإسلام وبين التابعين لعدم رؤية النبي - صلى الله عليه وآله وسلم - فهو متردد بين أمرين ...». وانظر: الصحاح ٥/ ١٩١٤، والمحكم ٥/ ٢٠٠، ولسان العرب ١٢/ ١٨٥، وشرح التبصرة والتذكرة ٣/ ٦٥ مع تعليقنا عليه.\nذكرهم نقلًا عن الإمام مسلم الحاكم في معرفة علوم الحديث: ٤٤ - ٤٥، وانظر: التقييد والإيضاح: ٣٢٤، وشرح التبصرة ٣/ ٦٧، ومحاسن الاصطلاح ٤٥٢."}],[1478,"الثَّالِثَةُ: مِنْ أكَابِرِ التَّابِعِينَ، الفُقَهاءُ السَّبْعَةُ (٧) مِنْ أهلِ المَديْنَةِ، وهم: سعيدُ ابنُ المُسيِّبِ، والقاسمُ بنُ مُحَمَّدٍ، وعُرْوَةُ بنُ الزبيرِ، وخارجةُ بنُ زَيدٍ، وأبو سلمةَ بنُ"],[1479,"عبدِ الرحمانِ، وعبيدُ اللهِ بنُ عبدِ اللهِ بنِ عُتْبَةَ، وسُليمانُ بنُ يَسارٍ. رُوِّيْنا عَنِ الحافِظِ أبي عبدِ اللهِ أنَّهُ قالَ: «هَؤلاءِ الفُقَهاءُ السَّبْعةُ عِنْدَ الأكْثرِ مِنْ عُلماءِ الحِجازِ» (٨). ورُوِّيْنا عَنِ ابنِ المباركِ قالَ: «كانَ فقهاءُ أهلِ المدينةِ الذِينَ يُصْدِرُونَ عَنْ رأْيهِمْ سَبْعةً» (٩)، فَذَكَرَ هَؤلاءِ إلاَّ أنَّهُ لَمْ يَذْكُرْ أبا سَلَمةَ بنَ عبدِ الرَّحمانِ، وذَكَرَ بَدَلَهُ سالِمَ بنَ عبدِ اللهِ بنِ عُمَرَ. ورُوِّيْنا عَنْ أبي الزِّنادِ تَسْمِيَتَهُمْ في كِتابِهِ عَنْهُم فَذَكَرَ هؤلاءِ إلاَّ أنَّهُ ذَكَرَ أبا بَكرِ بنَ عبدِ الرحمانِ بَدَلَ أبي سَلَمةَ وسَالِمٍ (١٠)."],[1480,"الرَّابِعَةُ: وَرَدَ عَنْ أحمدَ بنِ حَنْبَلٍ أنَّهُ قالَ: «أفْضَلُ التَّابعينَ: سَعِيدُ بنُ الْمُسَيِّبِ. فقيلَ لهُ: فَعَلْقَمَةُ والأسْودُ؟، فقالَ: سَعِيدُ بنُ الْمُسَيِّبِ، وَعَلْقَمَةُ، والأسْودُ» (١١).","",{"fn":"بفتح المعجمة والفاء واللام. الخلاصة: ١٥٩.\nبفتح الخاء المعجمة وسكون الياء المعجمة باثنتين من تحتها، وفي آخرها النون. الأنساب ٢/ ٤٩٤.\nمَُِل بلام ثقيلة، والميم مثلثة، والنَّهدي: بفتح النون وسكون الهاء. التقريب (٤٠١٧).\nبفتح العين المهملة والتاء المنقوطة بنقطتين من فوق، وكسر الكاف. انظر: الأنساب ٤/ ١٢٩.\nبضم المثلثة وفتح الواو بعدها موحدة. التقريب (٨٣٦٧).\nراجع: محاسن الاصطلاح ٤٥٣، وشرح التبصرة ٣/ ٦٧.\nراجع: محاسن الاصطلاح ٤٥٤.\nمعرفة علوم الحديث: ٤٣.\nأخرجه الفسوي في المعرفة ١/ ٣٢٥، والبيهقي في المدخل (١٥٧)، والذهبي في السير ٤/ ٤٦١.\nأخرجه الفسوي في المعرفة ١/ ٣٢٥، والحاكم في معرفة علوم الحديث: ٤٣، والبيهقي في المدخل (١٥٦).\nتهذيب الكمال ٣/ ٢٠٠."}],[1481,"وعنهُ أنَّهُ قالَ: «لا أعلمُ في التَّابِعينَ مِثْلَ أبي عُثْمانَ النَّهْدِيِّ، وقيسِ بنِ أبي حازِمٍ». وعنهُ أنَّهُ قالَ: «أفْضَلُ التَّابِعينَ: قيسٌ، وأبو عُثْمانَ وعلقَمةُ، ومَسْرُوقٌ. هؤلاءِ كانوا فاضِلينَ ومِنْ عِلْيَةِ (١) التَّابِعينَ»."],[1482,"وأعْجَبَنِي ما وَجَدْتُهُ عَنِ الشَّيْخِ أبي عبدِ اللهِ بنِ خَفِيْفٍ الزَّاهِدِ الشِّيْرازِيِّ (٢) في كِتابٍ لهُ، قالَ: «اخْتَلَفَ النَّاسُ في أفْضلِ التَّابِعينَ، فأهلُ المدينةِ يَقُولُونَ: سَعِيدُ ابنُ الْمُسَيِّبِ، وأهلُ الكُوفَةِ يَقُولُونَ: أُوَيْسٌ القَرَنِيُّ (٣)، وأهلُ البصرَةِ يَقُولُونَ: الحَسَنُ البَصْرِيُّ» (٤). وبَلَغَنا عَنْ أحمدَ بنِ حَنْبَلٍ قالَ: «ليسَ أحَدٌ أكثَرَ فَتْوى مِنَ الحسَنِ، وعَطَاءٍ، يَعْنِي: مِنَ التَّابِعينَ». وقالَ أيضًا: «كانَ عَطَاءٌ مُفْتِي مَكَّةَ والحَسَنُ مُفْتِي البَصْرَةَ، فهَذانِ أكْثَرَ النَّاسُ (٥) عَنْهُم رأْيَهُمْ». وبَلَغَنا عَنْ أبي بكرِ ابنِ أبي داودَ قالَ:"],[1483,"«سَيِّدَتا التَّابِعِينَ مِنَ النِّسَاءِ حَفْصَةُ بِنْتُ سِيْرِيْنَ، وعَمْرَةُ بنتُ عبدِ الرَّحْمانِ، وثالُثُتُهما"],[1484,"- وليْسَتْ كَهُما - أُمُّ الدَّرْدَاءِ» (٦)، واللهُ أعلمُ."],[1485,"الخامِسةُ: رُوِّيْنا عَنِ الحَاكِمِ (٧) أبي عبدِ اللهِ قالَ: «طَبَقَةٌ تُعَدُّ في التَّابِعِينَ ولَمْ يَصِحَّ سَماعُ أحَدٍ (٨) مِنْهُم مِنَ الصحابةِ، مِنْهُم: إبراهيمُ بنُ سُوَيْدٍ النَّخَعِيُّ الفقيهُ - وليسَ بإبراهيمَ بنِ يَزِيدَ النَّخَعِيِّ الفقيهِ (٩) -، وبُكَيرُ بنُ أبي السَّمِيطِ (١٠)، وبُكَيرُ ابنُ عبدِ اللهِ بنِ الأشَجِّ، وذَكَرَ غيرَهُمْ»، قالَ: «وطَبقةٌ عِدادُهُمْ عِنْدَ الناسِ في أتْباعِ التَّابِعِينَ وقدْ لَقوا الصَّحابةَ، مِنْهُم: أبو الزِّنادِ عبدُ اللهِ بنُ ذَكْوانَ لَقِيَ عبدَ اللهِ بنَ عُمَرَ وأنَسًا، وهِشامُ بنُ عُرْوَةَ وقدْ أُدْخِلَ عَلَى عبدِ اللهِ بنِ عُمَرَ وجابِرِ بنِ عبدِ اللهِ، وموسَى بنُ عُقْبَةَ، وقدْ أدْرَكَ أنسَ بنَ مالكٍ، وأمَّ خالِدِ بنتَ خالدِ بنِ سَعيدِ بنِ العاصِ» (١)، وفي بعضِ ما قالَهُ مَقَالٌ.","",{"fn":"رَجلٌ عليٌّ، أي: شريف رفيع، وجمعه: عِلْيَة مثل: صَبِيّ وصِبْيَة، يُقال: فلان من عِلْيَة الناس، أي: من أشرفهم وجِلَّتِهم لا من سِفلتهم. انظر: الصحاح ٦/ ٢٤٣٥، واللسان ١٥/ ٨٦.\nترجمته في سير أعلام النبلاء ١٦/ ٣٤٢.\nأويس - بالتصغير -، والقَرَني: بفتح القاف والراء بعدها نون. التقريب (٥٨١).\nراجع: التقييد والإيضاح ٣٢٦.\nفي (م): «الناس فتيًا عندهم».\nقال البلقيني في محاسن الاصطلاح: ٤٥٦: «المراد أم الدرداء الصغرى التابعية، واسمها هجيمة».\nانظر: التقييد والإيضاح: ٣٢٧.\nفي (أ): «واحد».\n«الفقيه»، لَمْ ترد في (م).\nالسميط - بفتح السين المهملة -، ويقال - بالضم -، انظر: التقريب (٧٥٦)، والخلاصة: ٥٢."}],[1486,"قُلْتُ: وقومٌ عُدُّوا مِنَ التَّابعينَ وهم مِنَ الصَّحابةِ، ومِنْ أعجبِ ذَلِكَ عَدُّ الحاكِمِ أبي عبدِ اللهِ النُّعْمانَ وسُوَيْدًا ابني (٢) مُقَرَّنٍ المزَنِيَّ في التَّابعينَ عِنْدَ ما ذكَرَ الإخوةَ مِنَ التَّابعينَ (٣) وهما صَحابِيَّانِ مَعْروفانِ مَذْكُورانِ في الصحابةِ، واللهُ أعلمُ."],[1487,"النَّوْعُ الْحَادِي والأرْبَعُونَ"],[1488,"مَعْرِفَةُ الأكَابِرِ الرُّوَاةِ (٤) عَنِ الأصَاغِرِ (٥)"],[1489,"ومِنَ الفَائدةِ فيهِ ألاَّ يُتَوَهَّمَ كَونُ المرْوِيِّ عنهُ أكبرَ أوْ أفضلَ مِنَ الراوي نَظَرًا إلى أنَّ الأغلبَ كَوْنُ المرْوِيِّ عنهُ كذلكَ فيُجْهَلُ بذلكَ مَنْزِلَتُهما. وقدْ صَحَّ عَنْ عائِشَةَ - رضي الله عنها - قالتْ: «أمرَنا رسُولُ اللهِ - صلى الله عليه وآله وسلم - أنْ نُنَزِّلَ النَّاسَ مَنَازِلهمُ» (٦).","",{"fn":"معرفة علوم الحديث: ٤٥.\nفي (ب): «ابنا».\nمعرفة علوم الحديث: ١٥٤.\nفي (ب): «من الرواة».\nانظر في هذا: معرفة علوم الحديث: ٤٨ - ٤٩، والإرشاد ٢/ ٦١٧ - ٦١٩، والتقريب: ١٦٧ - ١٦٨، واختصار علوم الحديث: ١٩٥ - ١٩٦، والشذا الفياح ٢/ ٥٣٥ - ٥٤٠، والمقنع ٢/ ٥١٨ - ٥٢٠، وشرح التبصرة ٣/ ٧٣ - ٧٦، ونزهة النظر: ١٦٠ - ١٦١، وطبعة عتر: ٦٢، وفتح المغيث ٣/ ١٥٧ - ١٥٩، وتدريب الراوي ٢/ ٢٤٣ - ٢٤٥، وشرح السيوطي على ألفية العراقي: ١٩٨، وفتح الباقي ٣/ ٦٤ - ٦٥، وتوضيح الأفكار ٢/ ٤٧٣ - ٤٧٤.\nهكذا قال المصنف - رحمه الله -، وقد تعقّبه الحافظ العراقي في التقييد ٣٢٨ - ٣٢٩، فقال: «جزم المصنِّف بصحة حديث عائشة، وفيه نظر فإن مُسلمًا - رحمه الله - ذكره في مقدمة صحيحه بغير إسناد ="}],[1490,"ثُمَّ إنَّ ذَلِكَ يَقَعُ عَلَى أضْرُبٍ:"],[1491,"منها: أنْ يَكونَ الرَّاوي أكبَرَ سِنًّا وأقْدَمَ طَبَقةً مِنَ الْمَرْوِيِّ عنهُ، كالزُّهْرِيِّ، ويحيى ابنِ سعيدٍ الأنصارِيِّ، في روايَتِهما عَنْ مالِكٍ، وكأبي القاسِمِ عُبَيْدِ اللهِ (١) بنِ أحمدَ الأزْهَرِيِّ - مِنَ المتَأَخِّرينَ، أحَدِ شُيُوخِ الخطيبِ - رَوَى عَنِ الخطيبِ في بعضِ تَصَانِيفِهِ، والخطيبُ إذْ ذاكَ في عُنْفُوانِ شَبَابِهِ وطَلَبِهِ."],[1492,"ومنها أنْ يَكُونَ الرَّاوي أكبَرَ قَدْرًا مِنَ المَرْوِيِّ عنهُ بأنْ يَكونَ حافِظًا عالِمًا والمَرْوِيُّ عنهُ شَيخًا راوِيًا فَحَسْبُ، كمالِكٍ في روايتِهِ عَنْ عبدِ اللهِ بنِ دينارٍ، وأحمدَ بنِ حَنْبَلٍ، وإسْحاقَ بنِ رَاهَوَيْهِ في روايَتِها عَنْ عُبَيْدِ اللهِ (٢) بنِ مُوْسَى (٣)، في أشباهٍ لِذَلِكَ كَثيرَةٍ."],[1493,"ومنها: أنْ يَكونَ الرَّاوِي أكبرَ مِنَ الوَجْهَينِ جَمِيعًا، وذلكَ كَرِوايةِ كثيرٍ مِنَ العُلَماءِ والحُفَّاظِ عَنِ أصْحابِهِمْ وتَلاَمِذَتِهِمْ، كَعَبْدِ الغَنِيِّ الحافِظِ في روايتِهِ عَنْ مُحَمَّدِ بنِ عليٍّ الصُّوْرِيِّ (٤) وكَرِوايةِ أبي بكرٍ البَرْقانيِّ عنْ أبي بكرٍ الخطيبِ، وكروايةِ الخطيبِ عنْ أبي نَصْرِ بنِ ماكولا، ونظائِرُ ذلكَ كثيرةٌ. وينْدَرِجُ تحتَ هذا النوعِ ما يُذكَرُ مِنْ رِوايةِ الصَّحابِيِّ عَنِ التَّابِعِيِّ، كرِوايةِ العَبادِلَةِ وغَيرِهِمْ (١) مِنَ الصَّحابَةِ عَنْ كَعْبِ الأحبَارِ. وكذلكَ روايةُ التَّابِعيِّ عَنْ تابِعِ التَّابِعِ، كما قَدَّمناهُ مِنْ روايةِ الزُّهْرِيِّ والأنصَارِيِّ عَنْ مالِكٍ، وكَعَمْرِو بنِ شُعَيْبِ (٢) بنِ مُحَمَّدِ بنِ عبدِ اللهِ بنِ عَمْرِو بنِ العاصِ لَمْ يَكُنْ مِنَ التَّابِعِينَ، وَرَوَى عنهُ أكْثَرُ مِنْ عِشْرينَ نَفْسًا مِنَ التَّابِعينَ جَمَعَهمْ عبدُ الغَنِيِّ بنُ سَعيدٍ الحافِظُ في كُتَيِّبٍ لهُ. وقرأْتُ بخَطِّ الحافِظِ أبي مُحَمَّدٍ (٣) الطَّبَسِيِّ (٤) في تخريجٍ لهُ قالَ: ... «عَمْرُو بنُ شُعَيْبٍ ليسَ بتَابِعِيٍّ وقدْ رَوَى عنهُ نَيِّفٌ وسَبْعُونَ رَجُلًا مِنَ التَّابِعينَ» (٥)، واللهُ أعلمُ.","",{"fn":"في (ب) و(جـ) والتقييد: «عبد الله» مكبرًا، والصواب ما أثبت، وهو الموافق لما في مصادر ترجمته. انظر: تاريخ بغداد ١٠/ ٣٨٥، والأنساب ١/ ١٢٩، والسير ١٧/ ٥٧٨، وشذرات الذهب ٣/ ٢٥٥.\nفي (أ): «عبد الله» مكبرًا، وهو خطأ مخالف لما في باقي النسخ، ومصادر ترجمته.\nمعرفة علوم الحديث: ٤٩.\nبضم الصاد المهملة وسكون الواو. انظر: الأنساب ٣/ ٥٧٠، ومراصد الاطلاع ٢/ ٨٥٦.\nقال البلقيني في المحاسن: ٤٦٠: «يدخل في قوله: وغيرهم، ما حكاه عنه عمر وعلي وأبوهريرة وجماعة من الصحابة».\nراجع: التقييد ٣٣١، وانظر: أثر علل الحديث في اختلاف الفقهاء ٨٥ - ٨٩.\nهكذا في جميع النسخ، وكذا نقله الحافظ العراقي عنه في شرح التبصرة ٣/ ٧٥، وابن الملقن في المقنع ٢/ ٥١٩، ولكن هذا مخالفٌ لما جاء في مصادر ترجمته إذ ذكرت أنَّهُ أبو الفضل، مُحَمَّد بن أحمد بن أبي جعفر الطبسي، فهو اسمه وليس كنيته، انظر الأنساب ٤/ ٢٦، والسير ١٨/ ٥٨٨، وشذرات الذهب ٣/ ٣٦٧.\nفي (أ): «الطيسي» وهو خطأ، والصواب ماأثبت. والطَّبَسي: بفتح الطاء المهملة والباء المنقوطة بواحدة، والسين المهملة، هذه النسبة إلى طبس، وهي مدينة بَيْنَ نيسابور وأصبهان وكرمان. انظر الأنساب ٤/ ٢٦، وتاج العروس ١٦/ ١٩٣.\nانظر تهذيب الكمال ٥/ ٤٢٤، وشرح التبصرة ٣/ ٧٥."}],[1494,"النَّوْعُ الثَّانِي والأَرْبَعُونَ"],[1495,"مَعْرِفَةُ الْمُدَبَّجِ (١) ومَا عَدَاهُ (٢) مِنْ رِوَايَةِ الأقْرَانِ بَعْضُهُمْ عَنْ بَعْضٍ وَهُمُ المتَقَارِبُونَ في السِّنِّ والإسْنادِ. ورُبَّما اكْتَفَى الحاكِمُ أبو عبدِ اللهِ فيهِ بالتَّقارُبِ في الإسنادِ، وإنْ لَمْ يوجَدْ التقارُبُ في السِّنِّ (١).","",{"fn":"بضم الميم، وفتح الدال المهملة وتشديد الباء الموحدة المفتوحة، وآخره جيم، قال الحافظ العراقي في التقييد: ٣٣٤: «ما المناسبة المقتضية لتسمية هذا النوع بالمدبج؟ ومن أي شيء اشتقاقه؟ لَمْ أرَ من تعرض لِذَلِكَ إلا أن الظاهر أنَّهُ سمي بذلك لحسنه فإن المدبج لغة هو المزين. قال صاحب المحكم الدبج النقش والتزيين فارسي معرب قال: وديباجة الوجه حسن بشرته، ومنه تسمية ابن مسعود الحواميم ديباج القرآن، وإذاكان هذا منه، فإن الإسناد الذي يجتمع فيه قرينان أو أحدهما أكبر والآخر من رواية الأصاغر عن الأكابر إنما يقع ذَلِكَ غالبًا فيما إذا كانا عالمين أو حافظين أو فيهما أو في أحدهما نوع من وجوه الترجيح حَتَّى عدل الراوي عن العلو للمساواة أو النزول لأجل ذَلِكَ فحصل للإسناد بذلك تحسين وتزيين كرواية أحمد بن حَنْبَلٍ عن يحيى بن معين، ورواية ابن معين عن أحمد وإنمايقع رواية الأقران غالبًا من أهل العلم المتميزين بالمعرفة، ويحتمل أن يقال: إن القرينين الواقعين في المدبج في طبقة واحدة بمنزلة واحدة فشبها بالخدين، فإن الخدين يقال لهما الديباجتان كما قاله صاحب المحكم والصحاح، وهذا المعنى يتجه عَلَى ما قاله الحاكم وابن الصلاح أن المدبج مختصٌ بالقرينين، ويحتمل أنَّهُ سمي بذلك لنزول الإسناد، فإنهما إن كانا قرينين نزل كل منهما درجة، وإن كان من رواية الأكابر عن الأصاغر نزل درجتين، وقد روينا عن يحيى بن معين، قال: الإسناد النازل قرحة في الوجه، وروينا عن علي بن المديني وأبي عمرو المستملي قالا: النزول شؤمٌ، فعلى هذا لايكون المدبج مدحًا له ويكون ذَلِكَ من قولهم رجل مدبج قبيح الوجه والهامة حكاه صاحب المحكم، وفيه بعد. والظهر أنَّهُ إنما هو مدح لهذا النّوع أو يكون من الاحتمال الثاني، والله أعلم». انتهى وانظر المستدرك ٢/ ٤٣٧، والجامع لأخلاق الراوي ١/ ١٢٣، ١٢٤، والصحاح ١/ ٣١٢، ولسان العرب ٢/ ٦٥، ونزهة النظر: ١٦٠ وفتح المغيث ٣/ ١٦٠، وتدريب الراوي ٢/ ٢٤٧. وانظر في المدبج: معرفة علوم الحديث: ٢١٥ - ٢٢٠، والإرشاد ٢/ ٦٢٠ - ٦٢٢، والتقريب: ١٦٨، والاقتراح: ٣١١ - ٣١٣، واختصار علوم الحديث: ١٩٧، والشذا الفياح ٢/ ٥٤١ - ٥٤٦، والمقنع ٢/ ٥٢١ - ٥٢٣، وشرح التبصرة ٣/ ٧٦ - ٧٩، ونزهة النظر ١٥٩ - ١٦٠، وطبعة عتر: ٦١ - ٦٢، وفتح المغيث ٣/ ١٦٠ - ١٦٢، وفتح الباقي ٣/ ٦٧ - ٦٩، وتدريب الراوي ٢/ ٢٤٦ - ٢٤٨، وتوضيح الأفكار ٢/ ٤٧٥ - ٤٧٦.\nفي (جـ): «وما سواه»."}],[1496,"اعْلَمْ أنَّ رِوايَةَ القَرِينِ عَنِ القَرِيْنِ تَنْقَسِمُ:"],[1497,"فَمِنْها الْمُدَبَّجُ، وهوَ أنْ يَرْوِيَ القَرِينانِ كُلُّ واحِدٍ مِنْهُما عَنِ الآخَرِ. مِثَالُهُ في الصَّحَابةِ: عائشَةُ وأبو هُرَيرةَ رَوَى كُلُّ واحِدٍ مِنْهُما عَنِ الآخَرِ. وفي التَّابعينَ: رِوايَةُ الزُّهْرِيِّ عَنْ عُمَرَ بنِ عبدِ العزيزِ وروايةُ عمرَ عنِ الزهريِّ. وفي أتباعِ التابعينَ: روايةُ مالكٍ عنِ الأوزاعيِّ، وروايةُ الأوزاعيِّ عنْ مالكٍ. وفي أتباعِ الأتباعِ:"],[1498,"روايةُ (٢) أحمدَ بنِ حَنْبَلٍ عنْ عليِّ بنِ المدينيِّ وروايةُ عليٍّ عنْ أحمدَ. وذكرَ الحاكمُ في هذا روايةَ أحمدَ بنِ حَنْبَلٍ عنْ عبدِ الرزاقِ، وروايةَ عبدِ الرزاقِ عنْ أحمدَ (٣) وليسَ هذا بمرضيٍّ. ومنها غيرُ المدبَّجِ (٤)، وهوَ أن يرويَ أحدُ القرينَينِ عَنِ الآخَرِ ولايرويَ الآخرُ عنهُ فيما نعلمُ. مثالُهُ: روايةُ سليمانَ التَّيْمِيِّ عن مِسْعَرٍ (٥)، وهما قرينانِ، ولانعلمُ لِمسْعَرٍ روايةً عنِ التَّيْمِيِّ. ولذلكَ أمثالٌ كثيرةٌ، واللهُ أعلمُ.","",{"fn":"معرفة علوم الحديث: ٢١٥.\nسقطت من (م).\nمعرفة علوم الحديث: ٢١٨.\nانظر نقد العراقي لذلك في التقييد: ٣٣٥.\nبكسر الميم وسكون السين وفتح العين المهملة. انظر: الإكمال ٧/ ١٩١، والخلاصة: ٣٧٤، وتاج العروس ١٢/ ٣٠."}],[1499,"النوع الثالث والأربعون معرفة الإخوة والأخوات من العلماء والرواة"],[1500,"(١)"],[1501,"وذَلِكَ إحدى مَعَارِفِ أهْلِ الحدِيْثِ الْمُفْرَدَةِ بالتَّصْنِيفِ. صَنَّفَ فيها عَلِيُّ بنُ المدينيِّ، وأبو عبدِ الرَّحْمَانِ النَّسَوِيُّ (٢) وأبو العبَّاسِ السَّرَّاجُ (٣) وغَيْرُهُمْ."],[1502,"فَمِنْ أَمْثِلَةِ الأخَوَيْنِ مِنَ الصَّحَابةِ: عبدُ اللهِ بنُ مَسْعودٍ، وعُتبةُ بنُ مَسْعُودٍ هما أَخَوانِ. زَيْدُ بنُ ثَابِتٍ ويَزِيْدُ بنُ ثابِتٍ أخَوَانِ. عَمْرُو بنُ العاصي (٤) وهِشَامُ بنُ العاصِي أخَوانِ (٥)."],[1503,"ومِنَ التَّابِعينَ (٦): عَمْرُو بنُ شُرَحْبِيْلَ أبو مَيْسَرةَ، وأخُوهُ أرقَمُ بنُ شُرَحْبِيْلَ، كِلاهُما مِنْ أفَاضِلِ أصْحابِ ابنِ مَسعودٍ. هُزَيْلُ بنُ شُرَحْبِيلَ وأرْقَمُ بنُ شُرَحْبِيلَ أخَوَانِ آخَرَانِ مِنْ أصْحابِ ابنِ مَسْعُودٍ (٧) أيضًا."],[1504,"ومِنْ أمْثِلَةِ ثَلاَثَةِ الإِخوَةِ: سَهْلٌ، وعَبَّادٌ، وعُثْمانُ، بَنُو حُنَيْفٍ (٨) إخْوَةٌ ثَلاَثَةٌ. عَمْرُو بنُ شُعَيْبٍ، وعُمَرُ، وشُعَيْبٌ، بَنُو شُعَيْبِ بنِ مُحَمَّدِ بنِ عبدِ اللهِ بنِ عَمْرِو بنِ العاصي إخْوَةٌ ثَلاثةٌ.","",{"fn":"انظر في ذلك: معرفة علوم الحديث: ١٥٢ - ١٥٧، والإرشاد ٢/ ٦٢٣ - ٦٣١، والتقريب: ١٦٩، واختصار علوم الحديث: ١٩٨ - ١٩٩، والشذا الفياح ٢/ ٥٤٧ - ٥٥٧، والمقنع ٢/ ٥٢٤ - ٥٣٤، وشرح التبصرة ٣/ ٧٩ - ٨٥، ونزهة النظر: ٢٠٤، وطبعة عتر: ٧٩، وفتح المغيث ٣/ ١٦٣ - ١٦٩، وتدريب الراوي ٢/ ٢٤٩ - ٢٥٣، وشرح السيوطي على ألفية العراقي: ٢٠١، وفتح الباقي ٣/ ٦٩ - ٨٣، وتوضيح الأفكار ٢/ ٤٧٦ - ٤٧٧.\nنسبة إلى بلدة بخراسان يقال لها: نسا، ويقال في النسبة إليها النَّسائيّ أيضًا. الأنساب ٥/ ٣٨٠.\nبفتح السين وتشديد الراء، وفي آخرها الجيم، هذا منسوب إلى عمل السرج، وهو الذي يوضع على الفرس. انظر: الأنساب ٣/ ٢٦٥.\nفي النسخ و(م): «العاص»، وكذا ما بعدها.\nراجع: محاسن الاصطلاح: ٤٦٧.\nراجع: التقييد: ٣٣٧.\nراجع: محاسن الاصطلاح: ٤٦٩.\nراجع: محاسن الاصطلاح: ٤٧٠."}],[1505,"ومِنْ أمْثِلَةِ الأرْبَعَةِ: سُهَيْلُ بنُ أبي صالحٍ السَّمَّانِ (١) الزَّيَّاتِ (٢)، وإخْوَتُهُ: عبدُ اللهِ - الذي يُقالُ لهُ: عَبَّادٌ -، ومُحَمَّدٌ، وصَالِحٌ."],[1506,"ومِنْ أمْثِلَةِ الْخَمْسَةِ (٣): ما نَرْوِيْهِ عَنِ الحاكِمِ أبي عبدِ اللهِ، قالَ سَمِعْتُ أبا عليٍّ الحسَيْنَ بنَ عليٍّ الحافِظَ غيرَ مَرَّةٍ يَقُولُ: «آدَمُ بنُ عُيَيْنَةَ، وعِمْرانُ بنُ عُيَيْنَةَ، ومُحَمَّدُ بنُ عُيَيْنَةَ، وسُفْيانُ بنُ عُيَيْنَةَ، وإبْرَاهِيمُ بنُ عُيَيْنَةَ حَدَّثُوا عَنْ آخِرِهِمْ» (٤)."],[1507,"ومِثَالُ السِّتَّةِ (٥): أوْلادُ سِيْرِيْنَ سِتَّةٌ تَابِعِيُّونَ وَهُمْ: مُحَمَّدٌ، وأَنَسٌ، ويَحْيَى، ومَعْبَدٌ، وحَفْصَةُ، وكَرِيمةُ، ذَكَرَهُمْ هَكَذا أبو عبدِ الرَّحْمانِ النَّسَوِيُّ ونَقَلْتُهُ مِنْ كِتابِهِ بخطِّ الدَّارَقُطنيِّ - فيما أحسِبُ -. ورُوِيَ ذَلِكَ أيضًا عَنْ يَحْيَى بنِ مَعِيْنٍ، وهَكَذا ذَكَرَهُمْ الحاكِمُ في كِتابِ \" المعرفةِ \" (٦) لكِنْ ذَكَرَ فيما نَرْوِيْهِ مِنْ \" تارِيخِهِ \" بإسْنادِنا عنهُ أنَّهُ سَمِعَ أبا عليٍّ الحافِظَ يَذْكُرُ بَنِي سِيْرِيْنَ خَمْسَةَ إخْوَةٍ، مُحَمَّدُ بنُ سِيْرِيْنَ (٧)، وأَكْبَرُهُمْ مَعْبَدُ بنُ سِيْرِيْنَ، ويَحْيَى بنُ سِيْرِيْنَ، وخالِدُ بنُ سِيْرِيْنَ (٨)، وأنَسُ بنُ سِيْرِيْنَ، وأصْغَرُهُمْ حَفْصَةُ بنتُ سِيْرِيْنَ."],[1508,"قُلْتُ: وقَدْ رُوِيَ عَنْ مُحَمَّدٍ (٩)، عَنْ يَحْيَى، عَنْ أنَسٍ، عَنْ أنَسِ بنِ مالِكٍ: أنَّ رَسُولَ اللهِ قالَ: «لَبَّيْكَ حَقًّا حَقًّا تَعَبُّدًا ورِقًّا» (١٠).","",{"fn":"بفتح السين المهملة وتشديد الميم وفي آخرها النون هذه النسبة إلى بيع السمن. الأنساب ٣/ ٣١٦.\nبفتح الزاي وتشديد الياء المنقوطة باثنتين من تحتها، وفي آخرها التاء المنقوطة باثنتين من فوقها، هذه النسبة إلى بيع الزيت. الأنساب ٣/ ٢٠٤.\nراجع: التقييد ٣٣٨، ومحاسن الاصطلاح ٤٧٣.\nمعرفة علوم الحديث: ١٥٥.\nراجع: التقييد ٣٣٩، ومحاسن الاصطلاح ٤٧٣.\nمعرفة علوم الحديث: ١٥٣.\nجملة: «خمسة إخوة محمد بن سيرين». سقطت من (م).\nعبارة: «خالد بن سيرين». سقطت من (م) و(ب).\nراجع: محاسن الاصطلاح ٤٦٧.\nأخرجه البزار ٢/ ١٣ (كشف الأستار) مرفوعًا وموقوفًا، وأبهم شيخه في المرفوع (مجمع الزوائد ٣/ ٢٢٣) والرامهرمزي في المحدث: ٦٢٤ (٩٠٤)، والصوري في فوائده: ٧٧ (٣٦)، والخطيب في = =تاريخه ١٤/ ٢١٥ (سقط منه ذكر أنس بن سيرين، وكلام الخطيب بعده يقتضي ذكره)، و١٤/ ٢١٦ وابن النجار في ذيل تاريخ بغداد ١٧/ ٨٢، من طرق عن الحكم بن سنان والنضر بن شميل -منفردين- كلاهما عن محمد بن سيرين، عن أخيه يحيى بن سيرين، عن أخيه أنس بن سيرين، عن أنس بن مالك به مرفوعًا."}],[1509,"وهذهِ غَريبةٌ عَايَا بها بعضُهُمْ فقالَ: أيُّ ثَلاَثَةِ إخْوَةٍ رَوَى بَعْضُهُمْ عَنْ بَعْضٍ؟."],[1510,"ومِثَالُ السَّبْعَةِ (١): النُّعْمانُ بنُ مُقَرِّنٍ، وإخْوَتُهُ مَعْقِلٌ، عَقِيْلٌ، وسُوَيْدٌ، وسِنانٌ، وعَبْدُ الرَّحمانِ، وسَابِعٌ لَمْ يُسَمَّ لنا (٢)، بَنُو مُقَرِّنٍ الْمُزَنِيُّونَ سَبْعَةُ إخْوَةٍ هاجَرُوا وصَحِبُوا رَسُولَ اللهِ - صلى الله عليه وآله وسلم -، ولَمْ يُشَارِكْهُمْ (٣) - فِيْمَا ذَكَرَهُ ابنُ عبدِ البرِّ (٤) وجماعَةٌ - في هذهِ المكرُمَةِ غيرُهُمْ. وقَدْ قيلَ: إنَّهُمْ شَهِدُوا الخنْدَقَ كُلُّهُمْ (٥). وقَدْ يَقَعُ في الإخْوَةِ ما فيهِ خِلافٌ في مِقْدارِ عَدَدِهِمْ. ولَمْ نُطَوِّلْ بِمَا زادَ عَلَى (٦) السَّبْعَةِ لِنَدْرَتِهِ ولِعَدَمِ الحاجَةِ إليهِ في غَرَضِنا هاهنا (٧)، واللهُ أعلمُ."],[1511,"النوع الرابع والأربعون معرفة رواية الآباء عن الأبناء"],[1512,"(٨)","",{"fn":"انظر: التقييد: ٣٤٠.\nقال ابن الملقن ٢/ ٥٢٩: «والذي لَمْ يُسَمَّ هو نُعَيم بن مُقَرِّنٍ». وقال الحافظ العراقي: «سَمَّاهُ ابن فتحون في ذيل الاستيعاب عبد الله بن مقرن ...». شرح التبصرة ٣/ ٨٢ والتعليق عليه، وانظر: التقييد: ٣٤١، الإصابة ٢/ ٣٧٣.\nفي (ب): «ولم يشاركهم أحد».\nالاستيعاب ٣/ ٤١٢.\nذكره ابن سعد في الطبقات ٦/ ٢٠.\nفي (جـ): «عن».\nانظر: التقييد: ٣٤٣.\nانظر في ذلك: الإرشاد ٢/ ٦٣٢ - ٦٣٦، والتقريب: ١٧٠ - ١٧١، واختصار علوم الحديث: ١٩٩ - ٢٠٢، والشذا الفياح ٢/ ٥٥٨ - ٥٦٢، والمقنع ٢/ ٥٣٥ - ٥٣٩، وشرح التبصرة والتذكرة ٣/ ٨٥، ونزهة النظر: ١٦٠ - ١٦١، وطبعة عتر: ٦٢، وفتح المغيث ٣/ ١٧٠ - ١٨٢، وتدريب الراوي ٢/ ٢٥٤ - ٢٥٥، وشرح السيوطي على ألفية العراقي: ٢٠٦، وفتح الباقي ٣/ ٨٣ - ١٠٠، وتوضيح الأفكار ٢/ ٤٧٧ - ٤٨٠."}],[1513,"ولِلْخَطيبِ الحافِظِ في ذَلِكَ كِتابٌ (١) رُوِّينا فيهِ عنِ العبَّاسِ بنِ عبدِ المُطَّلِبِ عَنِ ابنهِ الفضلِ رضي الله عنهما أنَّ رسولَ اللهِ - صلى الله عليه وآله وسلم - «جَمَعَ بَيْنَ الصَّلاتَينِ بِالْمُزْدَلِفةِ» (٢). ورُوِّيْنا فيهِ عَنْ وائِلِ بنِ داودَ، عَنِ ابنِهِ بكرِ بنِ وائلٍ - وهُما ثِقَتانِ (٣) - أحاديثَ منها عَنِ ابنِ عُيَينةَ، عَنْ وائِلِ بنِ داودَ، عَنِ ابنِهِ بكرٍ، عَنِ الزُّهْرِيِّ، عَنْ سَعيدِ بنِ المسَيِّبِ، عَنْ أبي هُرَيْرَةَ قالَ: قالَ رسُولُ اللهِ - صلى الله عليه وآله وسلم -: «أخِّرُوا الأحْمالَ فإنَّ اليَدَ مُعَلَّقَةٌ (٤) والرِّجْلَ مُوْثَقَةٌ» (٥). قالَ الخطيبُ: «لا يُرْوَى عَنِ النبيِّ - صلى الله عليه وآله وسلم - فيما نعلمُهُ إلاَّ مِنْ جِهَةِ بكرٍ وأبيهِ».","",{"fn":"اسمه: \" رواية الآباء عن الأبناء \". الرسالة المستطرفة: ١٦٣، وانظر: شرح التبصرة ٣/ ٨٥، وفتح المغيث ٣/ ١٧٠.\nبالضم ثُمَّ السكون، ودال مهملة مفتوحة، ولام مكسورة. انظر: مراصد الاطلاع ٣/ ١٢٦٥. والحديث لم نجده بهذا السند، وهو في كتاب الخطيب: \" رواية الآباء عن الأبناء \" وهو مفقود، لم نقف عليه مطبوعًا ولا مخطوطًا، وحديث: «جمع النبي - صلى الله عليه وآله وسلم - بالمزدلفة» ثابت من حديث أسامة بن زيد عند أحمد في المسند ٥/ ٢٠٢، ومسلم ٤/ ٧٤.\nانظر في الأول: الثقات لابن حبان ٧/ ١٦١. أما الثاني فقد نقل ابن حجر في التهذيب ١/ ٤٨٨ قول الحاكم النيسابوري: «وائل وابنه ثقتان». والمصنف ابن الصلاح مقلد للحاكم في هذا إذ لَمْ يطلق أحد التوثيق له غير ابن حبان. وانظر: تهذيب الكمال ١/ ٣٧٦، وتهذيب التهذيب ١/ ٤٨٨، والتقريب (٧٥٢).\nفي النسخ و(م) والشذا: «معلقة» بالعين المهملة، وكذا في شرح التبصرة ٣/ ٨٦، والمقنع ٢/ ٥٣٥، ومثله في كثير من المصادر التي أخرجته. وفي (ع) والتقييد: «مغلقة» بالغين المعجمة، وكذا في مسند أبي يعلى (٥٨٥٢)، واختصار علوم الحديث ٢/ ٥٤٦، وتدريب الراوي ٢/ ٢٥٤، وفتح المغيث ٣/ ١٤٨، بل قد نص المناوي على ذلك في فيض القدير ١/ ٢١٣، وكذا في بعض الكتب التي ذكرته مثل الكنز ٩/ ٦٢، والسلسلة الصحيحة (١١٣٠)، وموسوعة أطراف الحديث ١/ ٨٢.\n- أخرجه الترمذي في العلل الكبير (٧٠٦)، والبزار (١٠٨١) كشف الأستار، وأبو يعلى في مسنده (٥٨٥٢)، والطبراني في الأوسط (٤٥٠٨)، والبيهقي في الكبرى ٦/ ١٢٢، والخطيب في تاريخ بغداد ١٣/ ٤٥، كلهم من طريق قيس ابن الربيع، عن بكر بن وائل، عن الزهري، عن سعيد بن المسيب، عن أبي هريرة مرفوعًا. ="}],[1514,"ورُوِّيْنا فيهِ عَنْ مُعْتَمِرِ بنِ سُلَيْمانَ التَّيْمِيِّ قالَ: حَدَّثَنِي أبي، قالَ: حَدَّثَتْنِي أنتَ عَنِّي عَنْ أيُّوبَ، عَنِ الحسَنِ، قالَ: وَيْحٌ (١): كَلِمَةُ رَحْمَةٍ. وهذا ظَرِيفٌ (٢) يَجْمَعُ أنواعًا. ورُوِّيْنا فيهِ عَنْ أبي عُمَرَ حَفْصِ بنِ عُمَرَ الدُّوْرِيِّ الْمُقْرِئِ عَنِ ابنِهِ أبي جَعْفَرٍ مُحَمَّدِ بنِ حَفْصٍ سِتَّةَ عَشَرَ حَدِيثًا أوْ نَحْوَ ذَلِكَ، وذَلِكَ أكثَرُ ما رُوِّيْناهُ (٣) لأبٍ، عنِ ابنِهِ."],[1515,"وآخِرُ (٤) ما رُوِّيْناهُ مِنْ هذا النَّوْعِ وأقْرَبُهُ عَهْدًا ما حَدَّثَنِيهِ أبو الْمُظَفَّرِ عبدُ الرَّحِيمِ بنُ الحافِظِ أبي سَعْدٍ الْمَروزِيِّ بها - رَحِمَهُما اللهُ - مِنْ لَفْظِهِ قالَ: أنْبَأنِي والِدِي عَنِّي فيما قرأْتُ بِخَطِّهِ قالَ: حَدَّثَني وَلَدِي أبو الْمُظَفَّرِ عبدُ الرَّحيمِ مِنْ لَفْظِهِ وأصْلِهِ، فَذَكَرَ بإسْنادِهِ عَنْ أبي أُمامةَ: أنَّ رسُولَ اللهِ - صلى الله عليه وآله وسلم - قالَ: «أحْضِرُوا مَوائِدَكُمُ البَقْلَ، فإنَّهُ مَطْرَدَةٌ للشَّيْطانِ مَعَ التَّسْمِيَةِ» (٥)!. وأمَّا الحديثُ الذي رُوِّيْناهُ عَنْ (٦) أبي بكرٍ الصِّدِّيْقِ، عَنْ عائِشَةَ، عَنْ رسُولِ اللهِ - صلى الله عليه وآله وسلم - أنَّهُ قالَ: «في الْحَبَّةِ السَّوْدَاءِ شِفَاءٌ مِنْ كُلِّ دَاءٍ»، فَهُوَ غَلَطٌ مِمَّنْ رَوَاهُ (٧)، إنَّما هُوَ عَنْ أبي بكرِ بنِ أبي عَتِيقٍ، عَنْ عائِشَةَ (٨) وهوَ عبدُ اللهِ بنُ مُحَمَّدِ بنِ عبدِ الرَّحمانِ بنِ أبي الصِّدِّيْقِ. وهَؤلاءِ (٩) هُمُ الذينَ قالَ فيهم موسى بنُ عُقْبَةَ:","",{"fn":"انظر: الصحاح ١/ ٤١٧، وتاج العروس ٧/ ٢٢٠.\nفي (أ) و(جـ): «طريق»، وفي (م): «طريف» بالطاء المهملة.\nفي (ع): «روينا»، وما أثبتناه من جميع النسخ و(م).\nانظر: محاسن الاصطلاح ٤٧٨، التقييد ٣٤٥.\nأخرجه ابن حبان في المجروحين ٢/ ١٨٦، وأبو نعيم في أخبار أصفهان ٢/ ٢١٦، وابن الجوزي في الموضوعات ٢/ ٢٩٨ من طريق مكحول، عن أبي أمامة، به. قال ابن الجوزي: «هذا حديث لا أصل له، وعلته العلاء بن سلمة»، وقال ابن حبان: «كان العلاء يروي الموضوعات عن الثقات لا يحل الاحتجاج به».\nانظر: التقييد والإيضاح ٣٤٦.\nساقه هكذا المنجنيقي في كتابه: \" رواية الأكابر عن الأصاغر \"، كما قال ابن حجر في فتح الباري ١٠/ ١٤٣ - ١٤٤.\nهكذا رواه البخاري ٧/ ١٦٠ (٥٦٨٧)، وابن ماجه (٣٤٤٩)، والمزي في تهذيب الكمال ٨/ ٨١.\nانظر: التقييد والإيضاح: ٣٤٦."}],[1516,"«لا نَعرِفُ أربعةً أدْرَكُوا النبيَّ - صلى الله عليه وآله وسلم - هُمْ وأبْناؤُهُمْ إلاَّ هؤلاءِ الأربعةَ»، فَذَكَرَ أبا بكرٍ الصِّدِّيْقَ، وأباهُ، وابنَهُ عبدَ الرَّحْمانِ، وابنَهُ مُحَمَّدًا أبا عَتِيقٍ، واللهُ أعلمُ."],[1517,"النوع الخامس والأربعون معرفة رواية الأبناء عن الآباء"],[1518,"(١)"],[1519,"ولأبي نَصْرٍ الوَايلِيِّ (٢) الحافِظِ في ذَلِكَ كِتابٌ (٣) وأهَمَّهُ ما لَمْ يُسَمَّ فيهِ الأبُ أو الْجَدُّ، وهوَ نَوْعَانِ:"],[1520,"أحَدُهُما: رِوايةُ الابنِ عَنِ الأبِ عَنِ الْجَدِّ، نحوُ عَمْرِو بنِ شُعَيْبٍ عَنْ أبيهِ، عَنْ جَدِّهِ. ولهُ بهذا الإسْنادِ نُسْخَةٌ كَبيرَةٌ أكثَرُها فِقْهِيَّاتٌ جِيَادٌ (٤). وشُعَيبٌ هوَ ابنُ مُحَمَّدِ بنِ عبدِ اللهِ بنِ عَمْرِو بنِ العاصِ (٥). وقَدْ احْتَجَّ أكْثَرُ أهْلِ الحديْثِ (٦) بحديثِهِ حَمْلًا لِمُطْلَقِ الْجَدِّ فيهِ عَلَى الصَّحابِيِّ عبدِ اللهِ بنِ عَمْرِو بنِ العاصِ دُونَ ابنِهِ مُحَمَّدٍ والِدِ شُعَيبٍ ظَهَرَ لهم مِنْ إطْلاقِهِ (٧) ذَلِكَ.","",{"fn":"انظر في ذلك: الإرشاد ٢/ ٦٣٢ - ٦٣٦، والتقريب: ١٧٠ - ١٧١، واختصار علوم الحديث: ١٩٩ - ٢٠٢، والشذا الفياح ٢/ ٥٥٨ - ٥٦٢، والمقنع ٢/ ٥٣٥ - ٥٣٩، وشرح التبصرة والتذكرة ٣/ ٨٥، ونزهة النظر: ١٦٠ - ١٦١، وطبعة عتر: ٦٢، وفتح المغيث ٣/ ١٧٠ - ١٨٢، وتدريب الراوي ٢/ ٢٥٤ - ٢٥٥، وشرح السيوطي على ألفية العراقي: ٢٠٦، وفتح الباقي ٣/ ٨٣ - ١٠٠، وتوضيح الأفكار ٢/ ٤٧٧ - ٤٨٠.\nفي (أ): «الوائلي». قال في الأنساب ٥/ ٤٧٤، بفتح الواو وكسر الياء المنقوطة باثنين من تحتها وبعدها لام. وكذا في فتح المغيث ٣/ ١٥٣.\nانظر: الرسالة المستطرفة: ١٦٣.\nانظر: شرح التبصرة والتذكرة ٣/ ٩٤ مع التعليق عليه.\nفي (ع): «العاصي».\nانظر: محاسن الاصطلاح: ٤٨٠.\nانظر: محاسن الاصطلاح: ٤٨١."}],[1521,"ونَحْوُ بَهْزِ بنِ حَكِيمٍ، عَنْ أبيهِ، عَنْ جَدِّهِ، رَوَى بهذا الإسْنَادِ نُسْخَةً كَبيرةً (١) حَسَنَةً، وجَدُّهُ هوَ مُعاوِيَةُ بنُ حَيْدَةَ القُشَيْرِيُّ (٢)."],[1522,"وطَلْحَةُ بنُ مُصَرِّفٍ (٣)، عَنْ أبيهِ، عَنْ جَدِّهِ، وجَدُّهُ عَمْرُو بنُ كَعْبٍ اليَامِيُّ (٤)، ويُقالُ: كَعْبُ بنُ (٥) عَمْرٍو."],[1523,"ومِنْ أطْرَفِ (٦) ذَلِكَ (٧)، رِوايةُ أبي الفَرَجِ عبدِ الوهابِ التَّمِيْمِيِّ الفقيهِ الحنْبَلِيِّ. وكانَتْ لهُ ببغْدادَ في جامِعِ المنصُورِ حَلْقَةً للوَعْظِ والفتوَى - عَنْ أبيهِ في تِسْعَةٍ مِنْ آبائِهِ نسَقًا، أخْبَرَنِي بذلكَ الشَّيْخُ أبو الحسَنِ مُؤَيّدُ بنُ مُحَمَّدِ بنِ عليٍّ النَّيْسَابُورِيُّ بِقِرَاءَتِي عليهِ بها، قالَ: أخبَرَنا أبو مَنْصُورٍ عبدُ الرَّحمانِ بنُ مُحَمَّدٍ الشَّيْبانِيُّ في كِتابِهِ إلينا، قالَ: أخبَرَنا الحافِظُ أبو بكرٍ أحمدُ بنُ عليٍّ، قالَ: حَدَّثَنا عبدُ الوهابِ بنُ عبدِ العزِيزِ بنِ الحارِثِ بنِ أسَدِ بنِ اللَّيْثِ بنِ سُلَيْمانَ بنِ الأسْوَدِ بنِ سُفْيانَ بنِ يَزِيْدَ بنِ أُكَيْنَةَ بنِ عبدِ اللهِ التَّمِيْمِيُّ مِنْ لَفْظِهِ قالَ: سَمِعْتُ أبي يَقُولُ، سَمِعْتُ أبي يَقُولُ، سَمِعْتُ أبي يَقُولُ، سَمِعْتُ أبي يَقُولُ، سَمِعْتُ أبي يَقُولُ، سَمِعْتُ أبي يَقُولُ، سَمِعْتُ أبي يَقُولُ، سَمِعْتُ أبي يَقُولُ، سَمِعْتُ أبي يَقُولُ، سَمِعْتُ عليَّ بنَ أبي طالِبٍ، وقَدْ سُئِلَ عَنِ الحنَّانِ المنَّانِ، فقالَ: «الحنَّانُ الذي يُقْبِلُ عَلَى مَنْ أعْرضَ عنهُ، والمنَّانُ الذي يَبْدَأُ بالنَّوالِ قبلَ السُّؤَالِ» (٨). آخِرُهُمْ أُكَيْنةُ - بالنُّونِ - وهوَ السَّامِعُ عليًّا - رضي الله عنه -. حَدَّثَني أبو الْمُظَفَّرِ عبدُ الرَّحِيمِ ابنُ الحافِظِ أبي سَعْدٍ السَّمعانِيِّ بمرْوِ الشَّاهجانِ عَنْ أبي النَّضَرِ (٩) عَبْدِ الرَّحمانِ بنِ عبدِ الجبَّارِ الفَامِيِّ (١)، قالَ: سَمِعْتُ السَّيِّدَ أبا القَاسِمِ مَنْصُورَ بنَ مُحَمَّدٍ العَلَوِيَّ، يقُولُ: الإسْنادُ بعضُهُ عَوَالٍ وبعضُهُ مَعالٍ. وقَوْلُ الرَّجُلِ: «حَدَّثَني أبي عنْ جَدِّي» مِنَ المعَالِي (٢).","",{"fn":"في (ب): «كثيرة».\nانظر: محاسن الاصطلاح ٤٨٢.\nبصاد مهملة، وراء مكسورة، وآخره فاء. الإكمال ٧/ ١٩٨.\nبفتح الياء المنقوطة من تحتها باثنتين، هذه النسبة إلى يام، وهو بطن من همدان. الأنساب ٥/ ٥٩٤.\nفي (ع): «بين» خطأ.\nفي التقييد: «أظرف» بالظاء المعجمة.\nانظر: التقييد ٣٤٧.\nأخرجه الخطيب في تاريخه ١١/ ٣٢، وانظر: شرح التبصرة والتذكرة ٣/ ٩٩ مع التعليق عليه.\nكذا في (أ) و(ب) و(م) و(ع) والتقييد والشذا: بالضاد المعجمة، ومثله في السير ٢٠/ ٢٩٧، وفي (جـ): «النصر» بالصاد المهملة، ومثله في الأنساب ٤/ ٣١٨، وتذكرة الحفاظ ٤/ ١٣٠٩، والعبر ٤/ ١٢٤، وطبقات الحفاظ ٤٧١، وشذرات الذهب ٤/ ١٤٠."}],[1524,"الثَّاني: روايةُ الابنِ عَنْ أبيهِ دونَ الْجَدِّ وذلكَ بابٌ واسِعٌ، وهوَ نحوُ روايةِ أبي العُشَرَاءِ (٣) الدَّارميِّ عَنْ أبيهِ، عَنْ رسولِ اللهِ - صلى الله عليه وآله وسلم - وحديثُهُ معروفٌ (٤). وقَدِ اختَلَفُوا فيهِ، فالأشْهَرُ أنَّ أبا العُشَرَاءِ هوَ أسَامةُ بنُ مالِكٍ بنِ قِهْطَمٍ، وهوَ فيما نقلْتُهُ منْ"],[1525,"خَطِّ البَيْهَقِيِّ وغيرِهِ بكسرِ القافِ، وقيلَ: قِحْطَمٌ - بالحاءِ (٥) - وقيلَ: هوَ عُطَارِدُ بنُ بَرْزٍ - بتسكينِ الرَّاءِ -، وقيلَ: بتحريكِهَا أيضًا، وقيلَ: ابنُ بَلْزٍ (٦)"],[1526,"- باللامِ -، وفي اسْمِهِ واسْمِ أبيهِ مِنَ الخِلافِ غيرُ ذَلِكَ، واللهُ أعلمُ.","",{"fn":"في (ب): «القاضي»، والصواب ما أثبت، قال السمعاني: بفتح الفاء، وفي آخرها الميم، هذه النسبة إلى الحرفة، وهي لمن يبيع الأشياء من الفواكه اليابسة، ويقال له: البقال. وهو الموافق لمصادر ترجمته، ولم يصفه أحد بأنه كان قاضيًا.\nانظر: محاسن الاصطلاح ٤٨٥.\nبضم أوله وفتح المعجمة والراء والمد. التقريب (٨٢٥١).\nأخرجه ابن أبي شيبةَ ٥/ ٣٩٣، وأحمد ٤/ ٣٤، والدارمي (١٩٧٨)، والبخاريُّ في تاريخه الكبير ٢/ ٢٢، وأبو داود (٢٨٢٥)، وابن ماجه (٣١٨٤) والترمذي (١٤٨١)، والنسائي ٧/ ٢٢٨، وأبو يعلى (١٥٠٣) و(١٥٠٤)، وابن عدي في الكامل ١/ ٢٠٩، والطبراني في الكبير (٦٧١٩) و(٦٧٢٠)، و(٦٧٢١)، وأبو نعيم في الحلية ٦/ ٢٥٧، والبيهقي ٩/ ٢٤٦، والخطيب في تاريخه ١/ ٤١٣، من طريق حماد بن سلمة، عن أبي العشراء، عن أبيه، قال: قلت: يا رسول الله أما تكون الذكاة إلا في الحلق واللُّبَّة؟ قَالَ: «لَوْ طعنت في فخذها لأجزأ عنك»، قَالَ التِّرْمِذِيّ: «هَذَا حَدِيْث غريب لا نعرفه إلا من حَدِيْث حماد بن سلمة، ولا نعرف لأبي الشعراء، عن أبيه غَيْر هذا الحديث». وقال الخطابي في معالم السنن ٤/ ٢٨٠: «وأبو العشراء الدارمي لا يدري مَن أبوه، ولم يرو عنه غير حماد بن سلمة». وقال البُخَارِيّ في تاريخه الكبير (٢/ ٢٢ الترجمة ١٥٥٧): «في حديثه واسمه وسماعه من أبيه، نظر».\nانظر: الأسامي والكنى لأحمد (٧٧)، والتاريخ الكبير ٢/ ٢١ (١٥٥٧)، وكنى مسلم (٢٦٦٧)، والكنى والأسماء للدولابي ٢/ ٣١، وتسمية من يعرف بكنيته لأبي الفتح الأزدي (١٩٤)، وإيضاح الإشكال: ٦١، وتهذيب مستمر الأوهام: ٣٣٧، وشرح التبصرة والتذكرة ٣/ ٩٣.\nذكره الإمام البخاري في التاريخ الكبير ٢/ ٢١ (١٥٥٧)."}],[1527,"النَّوْعُ السَّادِسُ والأَرْبَعُونَ"],[1528,"مَعْرِفَةُ مَنِ اشْتَرَكَ في الرِّوَايَةِ عَنْهُ رَاوِيَانِ (١) مُتَقَدِّمٌ وَمُتَأَخِّرٌ"],[1529,"تَبَايَنَ (٢) وَقْتُ وَفَاتَيْهِما تَبَايُنًا شَدِيْدًا فَحَصَلَ بَيْنَهُمَا أَمَدٌ بَعِيْدٌ وإنْ كَانَ الْمُتَأَخِّرُ مِنْهُمَا غَيْرَ مَعْدُودٍ مِنْ مُعَاصِرِي الأَوَّلِ وَذَوِي طَبَقَتِهِ (٣)"],[1530,"ومِنْ فَوائدِ ذَلِكَ تَقْرِيرُ حَلاوَةِ عُلُوِّ الإسْنادِ في القُلُوبِ. وقَدْ أفْرَدَهُ الخطيبُ الحافِظُ في كِتابٍ حَسَنٍ سَمَّاهُ كِتابَ: \" السَّابِقِ واللاَّحِقِ \"."],[1531,"ومِنْ أمثَلتِهِ أنَّ مُحَمَّدَ بنَ إسْحَاقَ الثَّقَفِيَّ السَّرَّاجَ النَّيْسَابُوريَّ رَوَى عنهُ البُخَارِيُّ الإمامُ في \" تاريخِهِ \" ورَوَى عنهُ أبو الحسِيْنِ (٤) أحمدُ بنُ مُحَمَّدٍ الخفَّافُ (٥) النَّيْسَابُوريُّ وبَيْنَ وفَاتَيْهِما مئةٌ وسبعٌ وثلاثُونَ سَنَةً أو أكْثَرُ، وذَلِكَ أنَّ البُخَارِيَّ ماتَ سَنَةَ سِتٍّ وخَمْسِينَ ومِئَتَينِ، وماتَ الخفَّافُ سَنَةَ ثَلاثٍ وتِسْعِيْنَ وثلاثِ مئةٍ، وقيلَ: ماتَ في سنةِ أربعٍ أوْ خمسٍ وتِسعينَ وثلاثِ مئةٍ (٦). وكذلكَ مالِكُ بنُ أنَسٍ الإمامُ: حَدَّثَ عنهُ الزُّهْرِيُّ وزَكَرِيّا بنُ دُوَيدٍ (٧) الكِنْدِيُّ وبَيْنَ وفَاتَيْهِما مِئةٌ وسَبْعٌ وثلاثُونَ سَنَةً أوْ أكْثَرُ إذْ ماتَ مالِكُ بنُ أنَسٍ سنةَ تِسْعٍ وتسعينَ ومئةٍ، وماتَ الزُّهْرِيُّ سنةَ أربعٍ وعِشرينَ ومئةٍ. ولَقَدْ حَظِيَ مالِكٌ بكَثيرٍ مِنْ هذا النوعِ، واللهُ أعلمُ.","",{"fn":"سَمَّاه ابن كثير والعراقي وابن حجر والسخاوي وغيرهم: السابق واللاحق. انظر: اختصار علوم الحديث ٢/ ٥٥٩، وشرح التبصرة ٣/ ١٠٢، ونزهة النظر: ١٦٢، وفتح المغيث ٣/ ١٥٨.\nفي (جـ): «تباعد».\nانظر في ذلك: الإرشاد ٢/ ٦٤٠ - ٦٤٢، والتقريب: ١٧١، واختصار علوم الحديث: ٢٠٥، والشذا الفياح ٢/ ٥٧٠ - ٥٧٢، محاسن الاصطلاح: ٤٩١، والمقنع ٢/ ٥٤٧ - ٥٤٨، وشرح التبصرة والتذكرة ٣/ ١٠٢، ونزهة النظر: ١٦٢، وطبعة عتر: ٦٢، وفتح المغيث ٣/ ١٨٣ - ١٨٦، وتدريب الراوي ٢/ ٢٦٢ - ٢٦٣، وشرح السيوطي على ألفية العراقي: ٢١٣، وفتح الباقي ٣/ ١٠١، وتوضيح الأفكار ٢/ ٤٨٠ - ٤٨١.\nكذا في النسخ و(م) والشذا والتقييد، وكثير من مصادر ترجمته، وفي (ع): «الحسن»، ومثله في شذرات الذهب ٣/ ١٤٥، ولعله تصحيف.\nبفتح الخاء المعجمة وتشديد الفاء الأولى، هذه الحرفة لعمل الخفاف التي تلبس. الأنساب ٢/ ٤٤٢.\nانظر: السابق واللاحق: ٣٢٥.\nبدالين مهملتين، الأولى مضمومة تليها واو مفتوحة، ثُمَّ مثناة تحت ساكنة. انظر: المؤتلف والمختلف للدراقطني ٢/ ١٠٠٨، والإكمال ٣/ ٣٨٧."}],[1532,"النَّوْعُ السَّابِعُ والأَرْبَعُونَ"],[1533,"مَعْرِفَةُ مَنْ لَمْ يَرْوِ عَنْهُ إلاَّ رَاوٍ وَاحِدٌ (١) مِنَ الصَّحَابَةِ والتَّابِعِيْنَ فَمَنْ بَعْدَهُمْ (٢)"],[1534,"ولِمُسْلِمٍ فيهِ كِتابٌ لَمْ أرَهُ (٣)، ومِثَالُهُ مِنَ الصَّحابةِ: وَهْبُ بنُ خَنْبَشٍ (٤) وهوَ في كِتَابَي الحاكِمِ وأبي نُعَيْمٍ الأصْبهانِيِّ في \" معرفَةِ عُلُومِ الحديثِ \": هَرِمُ بنُ خَنْبَشٍ، وهوَ روايةُ دَاودَ الأوْدِيِّ عَنِ الشَّعْبِيِّ وذلكَ خَطَأٌ صحابيٌّ لَمْ يَرْوِ عنهُ غيرُ الشَّعْبِيِّ. وكذلكَ عامِرُ بنُ شَهْرٍ، وعُرْوةُ بنُ مُضَرِّسٍ (٥)، ومُحَمَّدُ بنُ صَفْوانَ الأنْصَارِيُّ، ومُحَمَّدُ بنُ صيْفِيِّ الأنصارِيُّ (٦) - وليْسا بواحِدٍ وإنْ قالَهُ بعضُهُمْ - صَحابِيُّونَ لَمْ يَرْوِ عَنْهُم غيرُ الشَّعْبِيِّ (٧). وانفرَدَ (٨) قيسُ بنُ أبي حازِمٍ بالروايةِ عَنْ أبيهِ. وعَنْ دُكَيْنِ بنِ سعيدٍ الْمُزَنِيِّ، والصُّنَابِحِ (١) بنِ الأعْسَرِ، ومِرْدَاسِ (٢) بنِ مالِكِ الأسَلمِيِّ، وكُلُّهُمْ صَحابةٌ.","",{"fn":"ويطلق عليه أيضًا مصطلح: «الوُحْدَان» - بضم الواو - جمع واحد. انظر: تدريب الراوي ٢/ ١٥٠، وشرح ألفية السيوطي لأحمد شاكر ٢٥١، وتوضيح الأفكار ٤٨١.\nانظر في ذلك: معرفة علوم الحديث ١٥٧ - ١٦١، والإرشاد ٢/ ٦٤٣ - ٦٥٠، والتقريب: ١٧١ - ١٧٣، واختصار علوم الحديث: ٢٠٦ - ٢٠٨، والشذا الفياح ٢/ ٥٧٣ - ٥٧٩، والمقنع ٢/ ٥٤٩ - ٥٦١، وشرح التبصرة والتذكرة ٣/ ١٠٤، وفتح المغيث ٣/ ١٨٧ - ١٨٩ وتدريب الراوي ٢/ ٢٦٤ - ٢٦٨، وشرح السيوطي على ألفية العراقي: ٢١٣، وفتح الباقي ٣/ ١٠٣ - ١٠٧، وتوضيح الأفكار ٢/ ٤٨١ - ٤٨٢.\nقال الحافظ العراقي في شرح التبصرة ٣/ ١٠٥: «وصَنَّف فيهِ مسلمٌ كتابه المسمَّى بكتاب \" المنفردات والوُحْدان \"، وعندي به نسخة بخطِّ محمد بن طاهر المقدسي، ولم يره ابنُ الصلاح كما ذكر». قلنا: وهذا الكتاب مطبوع، وقد حصل خلاف في اسمه. انظره في مقدمة محقق كتاب التمييز لمسلم: ١٠٩.\nبفتح الخاء المعجمة - وتكسر - بعدها نون ساكنة وياء مفتوحة معجمة بواحدة وآخره شين معجمة. انظر: الإكمال ٢/ ٣٤١، وتاج العروس ١٧/ ١٩٥.\nبمعجمة ثُمَّ راء مشددة مكسورة ثُمَّ مهملة. التقريب (٤٥٦٨).\nانظر: التقييد ٣٥١.\nانظر: محاسن الاصطلاح ٤٩٢.\nانظر: التقييد ٣٥٢."}],[1535,"وقُدَامةُ بنُ عبدِ اللهِ الكِلابيُّ مِنْهُم، لَمْ يَرْوِ عنهُ غيرُ أيْمَنَ بنِ نابِلٍ. وفي الصَّحابةِ جَماعَةٌ لَمْ يَرْوِ عَنْهُم غيرُ أبنائِهِمْ، مِنْهُم: شَكَلُ (٣) بنُ حُمَيْدٍ لَمْ يَرْوِ عنهُ غيرُ ابنِهِ شُتَيْرٍ (٤)، ومِنْهُم الْمُسَيِّبِ بنُ حَزْنٍ (٥) القُرَشِيُّ لَمْ يَرْوِ عنهُ غيرُ ابنِهِ سَعيدِ بنِ المسَيِّبِ، ومُعَاوِيةُ بنُ حَيْدَةَ لَمْ يَرْوِ عنهُ غيرُ ابنِهِ حَكيمٍ والِدُ بَهْزٍ، وقُرَّةُ بنُ إياسٍ لَمْ يَرْوِ عنهُ غيرُ ابنِهِ مُعاوِيةَ، وأبو ليْلَى الأنصَارِيُّ لَمْ يَرْوِ عنهُ غيرُ ابنِهِ عبدِ الرَّحمانِ بنِ أبي لَيْلَى."],[1536,"ثُمَّ إنَّ الحاكِمَ (٦) أبا عبدِ اللهِ حَكَمَ في \" المدخلِ إلى كِتابِ الإكلِيلِ \" (٧) بأنَّ أحَدًا مِنْ هذا القَبِيلِ لَمْ يُخَرِّجْ عنهُ البُخَارِيُّ ومُسْلِمٌ في \" صَحِيحهما \"، وأُنْكِرَ ذَلِكَ عليهِ ونُقِضَ عليهِ بإخْراجِ (٨) البُخَارِيِّ في \" صحيحهِ \" حديثَ قيسِ بنِ أبي حازِمٍ عَنْ مِرْداسٍ الأسْلَمِيِّ: «يَذْهَبُ الصَّالِحُونَ الأوَّلُ فالأوَّلُ» (٩)، ولا رَاوِيَ لهُ غيرُ قَيْسٍ. وبإخْرَاجِهِ بلْ بإخْرَاجِهِما حديثَ المسَيِّبِ بنِ حَزْنٍ في وَفَاةِ أبي طَالِبٍ (١٠) مَعَ أنَّهُ لا رَاوِيَ لهُ غيرُ ابنِهِ، وبإخْرَاجِهِ حديثَ الحسَنِ البَصْرِيِّ عَنْ عَمْرِو بنِ تَغْلِبَ: «إنِّي لأُعْطِي الرَّجُلَ والذي أدَعُ أحبُّ إليَّ» (١١)، ولَمْ يَرْوِ عَنْ عَمْرٍو غيرُ الحسَنِ. وكَذَلِكَ أخْرَجَ مُسْلِمٌ في \"صَحيحِهِ\" حديثَ رافِعِ بنِ عَمْرٍو الغِفَارِيِّ، ولَمْ يَرْوِ عنهُ غيرُ عبدِ اللهِ بنِ الصَّامِتِ (١)، وحديثَ أبي رِفَاعةَ العَدَوِيِّ ولَمْ يَرْوِ عنهُ غيرُ حُمَيْدِ بنِ هِلاَلٍ العَدَوِيِّ (٢)، وحديثَ الأغَرِّ الْمُزَنِيِّ: «إنَّهُ لَيُغَانُ عَلَى قَلْبِي» (٣)، ولَمْ يَرْوِ عنهُ غيرُ أبي بُرْدَةَ في أشْياءَ كَثِيْرَةٍ عِنْدَهُما في كِتابَيْهِما عَلَى هذا النَّحْوِ، وذَلِكَ دَالٌّ عَلَى مَصِيرِهِما إلى أنَّ الرَّاوِيَ قَدْ يَخْرُجُ عَنْ كَوْنِهِ مَجْهُولًا مَرْدُودًا بِرِوايةِ واحِدٍ عنهُ، وقَدْ قَدَّمْتُ هذا في النَّوعِ الثَّالِثِ والعِشْرِينَ.","",{"fn":"بضم أوله ثُمَّ نون وموحدة ومهملة. التقريب (٢٩٥٣).\nبكسر أوله وسكون الراء. التقريب (٦٥٥٣).\nشَكَل بفتحتين. التقريب (٢٨٢٠).\nبالتصغير. التقريب (٢٨٤٧).\nبفتح المهملة وسكون الزاي. التقريب (٦٧٧٤).\nوتابعه تلميذه البيهقي في ذلك. انظر: السنن الكبرى ٤/ ١٠٥.\nالمدخل: ٣٣.\nانظر: التقييد ٣٥٣.\nأخرجه البخاري ٨/ ١١٤ (٦٤٣٤)، والبيهقي ١٠/ ١٢٢.\nأخرجه البُخَارِيّ ٢/ ١١٩ (١٣٦٠)، ومسلم ١/ ٤٠ (٢٤).\nصحيح البخاري ٢/ ١٣ (٩٢٣) و٤/ ١١٤ (٣١٤٥) و٩/ ١٩١ (٧٥٣٥)، وهو عند أحمد في المسند ٥/ ٦٩ كلاهما من طريق جرير بن حازم، عن الحسن، قال: حدثنا عمرو بن تغلب ... . وأخرج له البخاري ٤/ ٥١ حديثًا آخر من طريق جرير عن الحسن، قال: حدثنا عمرو بن تغلب مرفوعًا: «إن من أشراط الساعة أن تقاتلوا قومًا ينتعلون نعال الشعر وإن من أشراط الساعة أن تقاتلوا قومًا عراض الوجوه، كأن وجوههم المجان المطرقة»."}],[1537,"ثُمَّ بَلَغَنِي عَنْ أبي عُمَرَ بنِ عبدِ البرِّ الأندلسِيِّ وِجَادَةً، قالَ: «كُلُّ مَنْ لَمْ يرْوِ عنهُ إلاَّ رَجُلٌ واحِدٌ فَهُوَ عِنْدَهُمْ مَجْهُولٌ إلاَّ أنْ يَكُونَ رَجُلًا مَشْهُورًا في غيرِ حَمْلِ العِلْمِ كاشْتِهارِ مالِكِ بنِ دِينارٍ بالزُّهْدِ، وعَمْرِو بنِ مَعْدِيْ كَرِبٍ بالنَّجْدَةِ» (٤)."],[1538,"واعْلَمْ أنَّهُ قَدْ يُوجدُ في بعضِ مَنْ ذَكَرْنا تَفَرُّدُ راوٍ واحِدٍ عنهُ خِلافٌ في تَفَرُّدِهِ، ومِنْ ذَلِكَ قُدَامَةُ بنُ عبدِ اللهِ، ذَكَرَ ابنُ عبدِ البرِّ أنَّهُ رَوَى عنهُ أيضًا حُمَيْدُ بنُ كِلاَبٍ (٥)، واللهُ أعلمُ."],[1539,"ومِثَالُ هذا النَّوعِ في التَّابعينَ: أبو العُشَراءِ الدَّارِمِيُّ لَمْ يَرْوِ عنهُ - فيما نَعْلَمُ (٦) - غيرُ حَمَّادِ بنِ سَلَمةَ. ومَثَّلَ الحاكِمُ لهذا النَّوعِ في التَّابعينَ بـ: مُحَمَّدِ بنِ أبي سُفْيانَ الثَّقَفِيِّ وذَكَرَ أنَّهُ لَمْ يَرْوِ عنهُ غيرُ الزُّهْرِيِّ فِيْمَا يُعْلَمُ (٧)، قالَ: وكَذَلِكَ تَفَرَّدَ الزُّهْرِيُّ عَنْ نَيِّفٍ وعِشْرِينَ رَجُلًا مِنَ التَّابعينَ لَمْ يَرْوِ عَنْهُم غيرُهُ، وكَذَلِكَ عَمْرُو بنُ دِيْنارٍ تَفَرَّدَ عَنْ جَماعةٍ مِنَ التَّابعينَ، وكَذَلِكَ يَحْيَى بنُ سَعِيْدٍ الأنْصَارِيِّ، وأبو إسْحاقَ السَّبِيْعِيُّ، وهِشَامُ بنُ عُرْوَةَ وغيرُهُمْ (٨)، وسَمَّى الحاكِمُ مِنْهُم في بعضِ المواضِعِ فيمَنْ تَفَرَّدَ عَنْهُم عَمْرُو بنُ دينارٍ: عبدَ الرَّحمانِ بنَ مَعْبَدٍ، وعبدَ الرَّحمانِ بنَ فَرُّوخٍ (١)، وفِيْمَنْ تَفَرَّدَ عَنْهُم الزُّهْرِيُّ عَمْرَو بنَ أبانَ بنِ عُثْمانَ، وسِنانَ بنَ أبي سِنانٍ الدُّؤَلِيَّ. وفيْمَنْ تَفرَّدَ عنهُمْ يَحْيَى (٢): عبدَ اللهِ بنَ أنيسٍ الأنصاريَّ. ومثَّلَ في أتْباعِ التَّابِعينَ بالمِسْوَرِ بنِ رِفَاعةَ القُرَظِيِّ وذَكَرَ أنَّهُ لَمْ يَرْوِ عنهُ غيرُ مالِكٍ. وكذلكَ تَفَرَّدَ مالِكٌ عَنْ زُهَاءِ عَشَرةٍ مِنَ شُّيُوخِ المدينةِ (٣).","",{"fn":"صحيح مسلم ٣/ ١١٦ (١٠٦٧) (١٥٨).\nصحيح مسلم ٣/ ١٥ (٨٧٦).\nأخرجه مسلم ٢/ ٧٢ (٢٧٠٢).\nانظر: محاسن الاصطلاح ٤٩٦.\nالاستيعاب ٣/ ٢٦٢.\nفي (أ) و(جـ): «يعلم».\nفي (أ): «نعلم».\nمعرفة علوم الحديث: ١٦٠."}],[1540,"قُلْتُ: وأخْشَى أنْ يَكُونَ الحاكِمُ في تَنْزِيلِهِ بَعضِ مَنْ ذَكَرَهُ بالْمَنْزِلَةِ التي جَعَلَهُ فيها، مُعْتَمِدًا عَلَى الحِسْبانِ والتَّوَهُّمِ، واللهُ أعلمُ."],[1541,"النوع الثامن والأربعون معرفة من ذكر بأسماء مختلفة أو نعوت متعددة"],[1542,"فَظَنَّ مَنْ لاَ خِبْرَةَ لَهُ بِهَا أَنَّ تِلْكَ الأَسْمَاءَ أَو النُّعُوْتَ لِجَمَاعَةٍ مُتَفَرِّقِيْنَ (٤)"],[1543,"هذا فنٌ عويصٌ والحاجةُ إليه حاقَّةٌ، وفيهِ إظهارُ (٥) تدليس المدلِّسينَ؛ فإنَّ أكثرَ ذلكَ إنما نَشَأَ منْ (٦) تَدليسهم. وَقَدْ صَنَّفَ عبدُ الغنيِّ بنُ سعيدٍ الحافظُ المِصريُّ (٧) وغيُرُه في ذلكَ (٨)."],[1544,"مثالُهُ: مُحَمَّدُ بنُ السَّائبِ الكلبيُّ صاحبُ التَّفسيرِ هوَ أبو النّضْرِ الذي رَوَى عنهُ مُحَمَّدُ بنُ إسحاقَ بنِ يَسارٍ حديثَ تَميمٍ الدَّاريِّ (١)، وَعديِّ بنِ بَدَّاءٍ (٢)، وهو حمَّادُ بنُ السائبِ الذي روى عنهُ أبو أسامةَ حديثَ: «ذكاةُ كلِّ مَسْكٍ دِباغُهُ» وهو أبو سعيدٍ الذي يروي عنهُ عَطيَّةُ العوْفيُّ التَّفسيرَ يُدَلِّسُ بهِ موهمًا أنَّهُ أبو سعيدٍ الخُدْريُّ.","",{"fn":"بفتح الفاء وتشديد الراء المضمومة ثُمَّ خاء معجمة. التقريب (٣٩٧٩).\nفي (ب): «يحيى بن سعيد».\nمعرفة علوم الحديث: ١٦٠.\nانظر في ذلك: الإرشاد ٢/ ٦٥١ - ٦٥٥، والتقريب: ١٧٣، واختصار علوم الحديث: ٢٠٨ - ٢٠٩، والشذا الفياح ٢/ ٥٨٠ - ٥٨٣، والمقنع ٢/ ٥٦٢ - ٥٦٤، وشرح التبصرة ٣/ ١٠٨ - ١١٤، ونزهة النظر: ١٩٤، وطبعة عتر: ٧٥ - ٧٦، وفتح المغيث ٣/ ١٩٠ - ١٩٤، وتدريب الراوي ٢/ ٢٦٨ - ٢٧١ وشرح السيوطي عَلَى ألفية العراقي: ٢١٦، وفتح الباقي ٣/ ١١٢، وتوضيح الأفكار ٢/ ٤٨٢، وظفر الأماني: ١١١.\nفي (ج): «وفيه فيفتح اظهار».\nفي (أ): «عن».\nفي (ب): «البصري».\nوكتابه \" إيضاح الإشكال\" كما أشار إليه الحافظ في شرح التبصرة ٣/ ١٠٩."}],[1545,"ومثالُهُ أيضًا: سالِمٌ الرَّاوي عن أبي هُريرةَ وأبي سعيدٍ الخُدْريِّ وعائشةَ - رضي الله عنهم - هوَ سالِمٌ أبو عبد اللهِ المَدينيُّ، وهوَ سالِمٌ مَوْلَى مالكِ بنِ أوسِ بنِ الحدَثَانِ (٣) النَّصْريِّ (٤)، وهوَ سالِمٌ مولَى شَدَّادِ بنِ الهادِ النَّصْرِيِّ، وهوَ في بعضِ الرِّواياتِ مُسَمًّى بـ: سالِمٍ مَوْلَى النَّصْرِيِّيْنَ، وفي بعضِها بـ: سالِمٍ مولَى الْمَهْرِيِّ، وهوَ في بَعْضِها سالِمٌ سَبَلاَنُ، وفي بعضِها أبو عبدِ اللهِ مولَى شَدَّادِ بنِ الهادِ، وفي بعضِها سالِمٌ أبو عبدِ اللهِ الدَّوْسِيُّ، وفي بعضِها سالِمٌ مولَى دَوْسٍ، ذكَرَ ذَلِكَ كُلَّهُ عبدُ الغنيِّ بنُ سَعيدٍ (٥)."],[1546,"قُلْتُ: والخطيبُ الحافِظُ يَرْوِي في كُتُبهِ عَنْ أبي القاسِمِ الأزْهَرِيِّ، وعَنْ عُبيدِ اللهِ (٦) ابنِ أبي الفَتْحِ الفارِسِيِّ، وعَنْ عُبيدِ اللهِ بنِ أحمدَ بنِ عُثمانَ الصَّيْرَفِيِّ، والجميعُ شَخْصٌ واحِدٌ مِنْ مَشَايخِهِ. وكذلكَ يَرْوِي عَنِ الحسَنِ بنِ مُحَمَّدٍ الخَلاَّلِ، وعنِ الحسَنِ بنِ أبي طالبٍ، وعَنْ أبي مُحَمَّدٍ الخَلاَّلِ، والجميعُ عبارةٌ عَنْ واحِدٍ (١). ويَرْوِي أيضًا عَنْ أبي القاسِمِ التَّنُوخِيِّ (٢)، وعَنْ عليِّ (٣) بنِ الْمُحَسِّنِ (٤)، وعَنِ القَاضِي أبي القاسِمِ عليِّ بنِ الْمُحَسِّنِ التَّنُوخِيِّ، وعَنْ عليِّ بنِ أبي عليٍّ (٥) الْمُعَدَّلِ، والجميعُ شخصٌ واحِدٌ. ولهُ مِنْ ذَلِكَ الكثيرُ، واللهُ أعلمُ.","",{"fn":"هذا الحديث يتعلق بقصة وقعت لتميم وعدي. أخرجه الترمذي (٣٠٥٩)، والطبري في تفسيره ٧/ ١١٥، وأبو نعيم في معرفة الصحابة (١٢٢٣) وابن الأثير في أسد الغابة ٤/ ٥.\nأخرجه بهذا السند الحاكم في المستدرك ٤/ ١٢٤، والخطيب في موضح أوهام الجمع والتفريق ٢/ ٣٥٧ - ٣٥٨ من طريق نعيم بن حماد، قال: حدثنا أبو أسامة، قال: حدثنا حماد بن السائب، قال: حدثنا إسحاق بن عبد الله بن الحارث، قال: سمعت ابن عباس، فذكره. وقال الحاكم: «صحيح الإسناد ولم يخرجاه»، ولم يتعقبه الذهبي.\nبفتح الموحدة وتشديد المهملة مع المد. عون المعبود ٣/ ٣٣٧، وتحفة الأحوذي ٨/ ٤٢٧.\nفي (ب): «النضري»، والصواب ما أثبت، وهو الموافق لمصادر ترجمته، قال في الأنساب٥/ ٣٩١: «النصري - بفتح النون وسكون الصاد المهملة وفي آخرها راء مهملة -: هذه النسبة إلى بني نصر بن معاوية ... وذكر منهم: مالك بن أوس».\nفي كتابه: «إيضاح الإشكال»، وانظر: تهذيب الكمال ٣/ ٩٧، والتقريب (٢١٧٧).\nفي (جـ): «عَبْد الله» مكبرًا، وَالصَّوَاب مَا أثبت، وَهُوَ الموافق لما في مصادر ترجمته. انظر: تاريخ بغداد ١٠/ ٣٨٥، والسير ١٧/ ٥٧٨، وشذرات الذهب ٣/ ٢٥٥."}],[1547,"النوع التاسع والأربعون معرفة المفردات الآحاد من أسماء الصحابة ورواة الحديث والعلماء"],[1548,"وَأَلْقَابِهِمْ وكُنَاهُمْ (٦)"],[1549,"هذا نوعٌ مَليحٌ عَزيزٌ (٧) يُوجَدُ في كُتُبِ الحفَّاظِ المصَنَّفَةِ في الرِّجالِ، مَجمُوعًا مُفَرَّقًا (٨) في أوَاخِرِ أبْوَابِها، وأُفْرِدَ أيضًا بالتَّصْنِيفِ، وكِتابُ أحمدَ بنِ هَارُونَ البِرْدِيجِيِّ البَرْذَعِيِّ الْمُتَرَجَمُ بـ\" بالأسْماءِ المفردةِ \" مِنْ أشْهَرِ كِتَابٍ في ذَلِكَ. ولَحِقَهُ في كَثِيرٍ منهُ اعْتِرَاضٌ واسْتِدْرَاكٌ مِنْ غيرِ واحِدٍ مِنَ الحفَّاظِ، مِنْهُم: أبو عبدِ اللهِ بنُ بُكَيْرٍ.","",{"fn":"وانظر ترجمته في: تاريخ بغداد ٧/ ٤٢٥، والسير ١٧/ ٥٩٣.\nبفتح التاء وضم النون المخففة، وفي آخرها الخاء المعجمة. الأنساب ١/ ٥٠٧.\nفي (ب): «علي بن عبد المحسن»، وهو مخالف لما في النسخ ومصادر ترجمته. انظر: تاريخ بغداد ٢/ ١١٥، ومعجم الأدباء ١٧/ ٩٢، والسير ١٧/ ٦٤٩.\nبضم الميم وفتح الحاء المهملة وكسر السين المهملة المشددة، وبعدها نون. وفيات الأعيان ٤/ ١٦٢.\nكلمة: «علي» ساقطة من (ب) و(جـ)، وهو مخالف لباقي النسخ ومصادر ترجمته.\nانظر في هذا النوع: معرفة علوم الحديث: ١٧٧ - ١٨٢، والإرشاد ٢/ ٦٥٦ - ٦٦٧، والتقريب: ١٧٤ - ١٧٥، واختصار علوم الحديث: ٢١٠ - ٢١٤، والشذا الفياح ٢/ ٥٨٤ - ٥٩٥، والمقنع ٢/ ٥٦٥ - ٥٧٠، وشرح التبصرة ٣/ ١١٤، ونزهة النظر: ١٩٩ - ٢٠٠، وطبعة عتر: ٧٧ - ٧٨، وفتح المغيث ٣/ ١٩٥ - ١٩٨، وتدريب الراوي ٢/ ٢٧١ - ٢٧٨، وفتح الباقي ٣/ ١١٢، وتوضيح الأفكار ٢/ ٤٨٢ - ٤٨٣، وظفر الأماني: ١١٧ - ١١٨.\nفي (ب): «غزير».\nفي (ع): «مجموعًا ومفرقًا»."}],[1550,"فَمِنْ ذَلِكَ ما وَقَعَ في كونِهِ ذَكَرَ أسماءً كثيرةً عَلَى أنَّها آحَادٌ وهيَ مَثَانٍ ومَثَالِثٌ. وأكْثَرُ مِنْ ذَلِكَ وعلى ما فَهِمْنا مِنْ شَرْطِهِ لا يلْزِمُهُ ما يُوجدُ مِنْ ذَلِكَ في غيرِ أسماءِ الصَّحابةِ والعُلَماءِ ورُوَاةِ الحديثِ، ومِنْ ذَلِكَ أفْرَادٌ ذَكَرَها اعْتُرِضَ عليهِ فيها بأنَّها ألْقَابٌ لا أسَامِي، منها:"],[1551,"- الأجْلَحُ الكِنْدِيُّ، إنَّمَا هُوَ لَقَبٌ لِجَلَحَةٍ (١) كَانتْ بهِ، واسْمُهُ يَحْيَى، ويَحْيَى كَثيرٌ."],[1552,"- ومنها: صُغْدِيُّ (٢) بنُ سِنانٍ، اسْمُهُ عُمَرُ، وصُغْدِيٌّ لَقَبٌ، ومَعَ ذَلِكَ فَلَهُمْ صُغَدِيٌّ غيرُهُ. وليسَ يَرِدُ هذا عَلَى ما ترجمْتُ بهِ هذا النَّوعَ، والحَقُّ أنَّ هذا فَنٌّ يَصْعُبُ الحُكْمُ فيهِ، والحاكِمُ فيهِ عَلَى خَطَرٍ مِنَ الخَطَأ والانْتِقَاضِ؛ فإنَّهُ حَصْرٌ في بابٍ واسِعٍ شَديدِ الانْتِشَارِ."],[1553,"فَمِنْ أمْثِلَةِ ذَلِكَ المسْتَفَادِةِ:"],[1554,"- أجْمَدُ (٣) بنُ عُجَيَّانَ الْهَمْدَانِيُّ - بالجيمِ - صَحابيٌّ ذَكَرَهُ ابنُ يُونُسَ، وعُجَيَّانُ كُنَّا نَعْرِفُهُ بالتَّشْديدِ عَلَى وَزِنِ عُلَيَّانَ. ثُمَّ وَجدْتُهُ بخطِّ ابنِ الفُرَاتِ - وهوَ حُجَّةٌ - عُجْيَانَ - بالتَّخفيفِ - عَلَى وَزنِ سُفْيانَ."],[1555,"- أَوْسَطُ بنُ عَمْرٍو البَجَلِيُّ، تابِعِيٌّ."],[1556,"- تَدُومُ بنُ صُبْحٍ (٤) الكَلاَعيُّ عَنْ تُبَيْعِ بنِ عامِرٍ الكَلاَعيِّ، ويُقَالُ فيهِ: يَدُومُ"],[1557,"- بالياءِ - وصَوابُهُ - بالتَّاءِ المثَنَّاةِ مِنْ فَوْقُ -."],[1558,"- جُبَيْبُ بنُ الحارِثِ صَحَابِيٌّ - بالجيمِ وبالباءِ الموحَّدَةِ المكرَّرَةِ."],[1559,"- جِيْلاَنُ بنُ فَرْوَةَ - بالجيمِ المكْسُورةِ - أبو الجَلْدِ (٥) الأخْبَارِيُّ تابعيٌّ."],[1560,"- الدُّجيْنُ بنُ ثابتٍ: - بالجيمِ مُصَغَّرًا -.","",{"fn":"الجلَحَة - محركة -: نوع من سقوط الشعر، والأجلح من الناس: هو الذي انحسر الشعر عن جانبي رأسه. انظر: الصحاح ١/ ٣٥٩، والنهاية ١/ ٢٨٤، وتاج العروس ٦/ ٣٤٢.\nبضم أوله وسكون المعجمة وتحتانية ثقيلة. انظر: نزهة الألباب ١/ ٣٦٦و٤٢٦، وراجع: التقييد ٣٥٩.\nفي (ع) والتقييد: «أحمد» بالحاء المهملة، وهو تصحيف. انظر الإكمال ١/ ١٧، وقارن بمحاسن الاصطلاح: ٥٠١.\nفي (م) والتقييد والشذا: «صبيح» بالتصغير.\nضبطه النووي في الإرشاد ٢/ ٦٥٨، بفتح الجيم وإسكان اللام، أما في المنهل الراوي: ١٣٣ فقال: بفتح الجيم واللام."}],[1561,"- أبو الغُصْنِ، قيلَ: إنَّه جُحَا المعروفُ، والأصحُّ أنهُ غيرُهُ (١)."],[1562,"- زِرُّ بنُ حُبَيْشٍ (٢) التابعيُّ الكبيرُ (٣)."],[1563,"- سُعَيْرُ بنُ الخِمْسِ (٤)، انْفَردَ في اسْمِهِ واسْمِ أبيهِ."],[1564,"- سَنْدَرٌ الْخَصِيُّ مَوْلَى زِنْبَاعِ الْجُذَامِيُّ لهُ صُحْبَةٌ (٥)."],[1565,"- شَكَلُ بنُ حُمَيْدٍ الصَّحابِيُّ - بفَتْحَتَيْنِ -."],[1566,"- شَمْعُونُ بنُ زَيْدٍ أبو رَيْحانَةَ-بالشِّيْنِ المنقوطةِ والعَينِ المهملةِ، ويُقَالُ: بالغينِ المعجمةِ -. قالَ أبو سَعيدِ بنِ يُونُسَ: وهوَ عِنْدِي أصَحُّ، أحَدُ الصَّحَابةِ الفُضَلاءِ."],[1567,"- صُدَيُّ بنُ عَجْلانَ أبو أُمامَةَ الصَّحابِيُّ."],[1568,"- صُنَابِحُ بنُ الأعْسَرِ الصَّحَابِيُّ، ومَنْ قالَ فيهِ: صُنابِحِيٌّ فَقَدْ أخْطأَ (٦)."],[1569,"- ضُرَيْبُ بنُ نُقَيْرِ بنِ سُمَيْرٍ - بالتَّصْغِيْرِ - فيها كُلُّها، أبو السَّلِيْلِ (٧) القَيْسِيُّ البَصْريُّ، رَوَى عَنْ مُعَاذَةَ العَدَوِيَّةِ وغيرِها، ونُقَيْرٌ أبوهُ - بالنُّونِ والقافِ - وقيلَ: بالفاءِ واللامِ: نُفَيْلٌ."],[1570,"- عَزْوانُ بنُ زَيْدٍ الرَّقَاشِيُّ - بعينٍ غيرِ مُعجمةٍ، عَبْدٌ صَالِحٌ تَابِعِيٌّ (٨)."],[1571,"- قَرثَعٌ الضَّبِّيُّ - بالثَّاءِ المثَلَّثةِ -."],[1572,"- كَلَدَةُ بنُ حَنْبَلٍ - بفتحِ اللاَّمِ - صَحابِيٌّ.","",{"fn":"انظر: التقييد ٣٦١.\nزِر - بكسر أوله وتشديد الراء -، وحبيش بمهملة وموحدة ومعجمة مصغرًا. التقريب (٢٠٠٨).\nانظر: التقييد ٣٦١.\nفي (ب): «الخميس»، والصواب ما أثبت، قال في التقريب (٢٤٣٢): «سُعير، آخره راء، مصغر ابن الخِمْس - بكسر المعجمة وسكون الميم ثُمَّ مهملة -. انظر: تهذيب الكمال ٣/ ٢١٢، والتقييد: ٣٦٢.\nانظر: التقييد: ٣٦٢.\nانظر: التقييد: ٣٦٣.\nبفتح المهملة وكسر اللام. التقريب (٢٩٨٤).\nانظر: التقييد: ٣٦٤."}],[1573,"- لُبَيُّ بنُ لَبَا الأسدِيُّ الصَّحابِيُّ - باللاَّمِ فيهما، والأوَّلُ مُشَدَّدٌ مُصَغَّرٌ عَلَى وِزَانِ أُبَيٍّ، والثَّاني مُخَفَّفٌ مُكَبَّرٌ عَلَى وَزْنِ عَصًا - فاعْلِمْهُ فإنَّهُ يُغْلَطُ فيهِ."],[1574,"- مُسْتَمِرُّ بنُ الرَّيَّانِ، رَأَى أنَسًا (١)."],[1575,"- نُبَيْشَةُ الخَيْرِ (٢)، صَحَابِيٌّ."],[1576,"- نَوْفٌ البِكَالِيُّ (٣)، تَابِعِيٌّ، مِنْ بِكَالٍ بَطْنٌ مِنْ حِمْيَرٍ - بكسرِ الباءِ وتخفيفِ الكَافِ، وغَلَبَ عَلَى ألسِنَةِ أهلِ الحديثِ فيهِ فَتْحُ الباءِ وتَشْدِيْدُ الكافِ."],[1577,"- وَابِصَةُ بنُ مَعْبَدٍ الصَّحَابِيُّ."],[1578,"- هُبَيْبُ بنُ مُغْفِلٍ، مصغَّرٌ - بالباءِ الموحَّدةِ المكرَّرةِ - صَحابِيٌّ، ومُغْفِلٌ - بالغينِ المنقُوطَةِ السَّاكِنةِ -."],[1579,"- هَمَذَانُ - بَرِيْدُ عُمَرَ بنِ الخطَّابِ -: ضَبَطَهُ ابنُ بُكَيْرٍ وغيرُهُ -بالذَّالِ المعجمةِ-، وضَبَطَهُ بعضُ مَنْ ألَّفَ عَلَى كِتابِ البِرْدِيْجِيِّ - بالدَّالِ المهملَةِ وإسكانِ الميمِ -."],[1580,"وأمَّا الكُنى الْمُفْرَدَةُ، فمِنها:"],[1581,"- أبو العُبَيْدَيْنِ - مُصَغَّرٌ مُثَنًّى - واسمُهُ: معاويةُ بنُ سَبْرَةَ (٤) منْ أصحابِ ابنِ مسعودٍ، لهُ حديثانِ أو ثلاثةٌ."],[1582,"- أبو العُشَراءِ الدَّارِميُّ، وقدْ سَبَقَ."],[1583,"- أبو الْمُدِّلَّةِ - بكسرِ الدَّالِ المهملةِ وتشديدِ اللامِ (٥)، ولَمْ يُوقَفُ عَلَى اسْمِهِ، رَوَى عنهُ الأعمشُ وابنُ عُيَيْنَةَ وجماعَةٌ، ولا نَعْلَمُ أحَدًا تابَعَ أبا نُعَيْمٍ الحافظَ في قَولِهِ (٦):","",{"fn":"انظر: التقييد: ٣٦٤.\nانظر: المصدر السابق.\nانظر: المصدر نفسه.\nبفتح المهملة وسكون الموحدة. التقريب (٦٧٥٦).\nذكر النووي في التقريب: ١٧٥ أنه بفتح اللام المشددة، ومثله في المنهل الروي: ١٣٤، والمقنع ٢/ ٥٦٩، ولكن في الخلاصة: ٤٥٩، قال: «بكسر اللام».\nقال البلقيني في محاسن الاصطلاح: ٥٠٥: «لَمْ ينفرد أبو نعيم بذلك، فقد سبقه إليه ابن حبان». قلنا: انظره في ثقاته ٥/ ٧٢."}],[1584,"إنَّ اسْمَهُ: عُبَيْدُ اللهِ (١) بنُ عبدِ اللهِ المدَنِيُّ (٢)."],[1585,"- أبو مُرَايَةَ العِجْلِيُّ، عَرَفْناهُ بضمِّ الميمِ وبعدَ الألِفِ ياءٌ مُثَنَّاةٌ مِنْ تحتُ واسْمُهُ: عبدُ اللهِ بنُ عَمْرٍو، تابِعِيٌّ، رَوَى عنهُ قَتَادَةُ."],[1586,"-أبو مُعَيْدٍ- مُصَغَّرٌ، مخَفَّفُ الياءِ -حَفْصُ بنُ غَيْلانَ الْهَمْدانِيُّ، عَنْ مَكْحُولٍ وغيرِهِ."],[1587,"وأمَّا الأفْرَادُ مِنَ الألْقَابِ فَمِثَالُها:"],[1588,"- سَفِيْنَةُ مَوْلَى رَسُولِ اللهِ - صلى الله عليه وآله وسلم - مِنَ الصَّحَابةِ، لَقَبٌ (٣) فَرْدٌ، واسْمُهُ: مِهْرانُ عَلَى خِلافٍ فيهِ."],[1589,"- مِنْدَلُ (٤) بنُ عليٍّ، وهوَ بكسرِ الميمِ (٥) عَنِ الخطيبِ وغيرِهِ، ويقُولُونَهُ كثيرًا بفتْحِها، وهوَ لَقَبٌ، واسْمُهُ: عَمْرٌو."],[1590,"- سُحْنُونُ (٦) بنُ سعيدٍ التَّنوخِيُّ القَيْرَوانِيُّ - صاحِبُ \" المدوَّنَةِ \" - عَلَى مَذْهَبِ مالِكٍ، لَقَبٌ فَرْدٌ، واسْمُهُ: عبدُ السَّلامِ."],[1591,"- ومِنْ ذَلِكَ مُطَيَّنٌ (٧) الحضْرَمِيُّ.","",{"fn":"هكذا في (أ) و(ب) و(ع) والتقييد: «عبيد الله» مصغر، ومثله في الإرشاد ٢/ ٦٦٥، والتقريب (١٧٥)، واختصار علوم الحديث ٢/ ٥٨٩، والمقنع ٢/ ٥٦٩. وكذا في مصادر ترجمته. انظر: الثقات ٥/ ٧٢، وتهذيب الكمال ٨/ ٤٢٢، ولكن وقع في (جـ): «عبد الله» مكبر، ومثله في تهذيب التهذيب ١٢/ ٢٢٧، وتقريب التهذيب (٨٣٤٩) في جميع طبعاته ولعله تصحيف. انظر: الكاشف ٢/ ٤٥٨، حاشية المحقق، وكتابنا \" كشف الإيهام \" ٢/ ٣٤٠، ولا بد من الإشارة إلى أن العبارة جاءت في (م) هكذا: «إن اسمه عبيد الله المدني»، فلعل فيها سقطًا.\nانظر: التقييد: ٣٦٦.\nلُقِّب بذلك؛ لكونه حمل شيئًا كثيرًا في السفر. التقريب (٢٤٥٨).\nقَالَ الحافظ ابن حجر في التقريب (٦٨٨٣): «مثلث الميم، ساكن الثَّانِي». وانظر: التقييد والإيضاح: ٣٦٧.\nفي (ع) زيادة: «روى»، وهي زيادة سقيمة أتلفت النص وأحالت المعنى.\nبضم السين وفتحها. وفيات الأعيان ٣/ ١٨٢، والتقريب (١٧٥)، والمقنع ٢/ ٥٧٠.\nبضم الميم، وفتح الطاء المهملة، وتشديد الياء المفتوحة، لُقِّب بذلك؛ لأن أبا نعيم الفضل بن دكين الملائي مرَّ عليه، وهو يلعب مع الصِبْيَان بالطين، وقد طيَّنوه، فقال له: يا مطين قد آن لك أن تسمع الحديث. انظر: الإكمال ٧/ ٢٠١، والأنساب ٥/ ٢١٦، واللباب ٣/ ٢٢٧."}],[1592,"- ومُشْكُدَانَةُ (١) الْجُعْفِيُّ في جَماعَةٍ آخَرِينَ سَنَذْكُرُهُمْ في نوعِ الألْقَابِ - إنْ شَاءَ اللهُ تَعَالَى -، واللهُ أعلمُ."],[1593,"النوع الموفي خمسين معرفة الأسماء والكنى"],[1594,"(٢)"],[1595,"كُتُبُ الأسْماءِ والكُنَى كَثِيرةٌ، منها: كِتابُ عليِّ بنِ المدينيِّ، وكِتابُ مُسْلِمٍ، وكِتابُ النَّسائيِّ، وكِتابُ الحاكِمِ الكبيرِ أبي أحمدَ الحافِظِ، ولابنِ عبدِ البرِّ في أنواعٍ منهُ كُتُبٌ لَطِيفةٌ رائِقَةٌ (٣). والمرادُ بهذهِ التَّرْجمةِ بيانُ أسْماءِ ذَوِي الكُنَى. والمصنِّفُ في ذَلِكَ يُبَوِّبُ كِتابَهُ عَلَى الكُنَى مُبَيِّنًا أسْماءَ أصْحابِها. وهذا فَنٌّ مَطْلُوبٌ لَمْ يَزَلْ أهلُ العِلْمِ بالحديثِ يُعْنَونُ بهِ ويَتَحَفَّظُونَهُ ويَتَطَارَحُونَهُ فيما بَيْنَهُمْ ويَتَنَقَّصُونَ (٤) مَنْ جَهِلَهُ وقدْ ابْتَكَرْتُ فيهِ تَقْسِيمًا حَسَنًا، فأقُولُ: أصْحَابُ الكُنَى فيها عَلَى ضُرُوبٍ:"],[1596,"أحَدُها: الذِينَ سُمُّوا بالكُنَى فأسْماؤُهُمْ كُناهُمْ لا أسْماءَ لهُمْ غيرُها، ويَنْقَسِمُ هَؤُلاءِ (٥) إلى قِسْمَينِ:"],[1597,"أحَدُهُما: مَنْ لهُ كُنيةٌ أخْرَى سِوَى الكُنْيَةِ التي هيَ اسْمُهُ، فَصَارَ كأنُّ للكُنِيةِ كُنيةً، وذَلِكَ طريفٌ عَجيبٌ (١). هذا كأبي بكرِ بنِ عبدِ الرَّحمانِ (٢) بنِ الحارِثِ بنِ هِشَامٍ المخْزُومِيِّ أحَدِ فُقَهَاءِ المدينةِ السَّبْعةِ وكانَ يُقَالُ لهُ: «راهِبُ قُرَيْشٍ»، اسْمُهُ: أبو بَكْرٍ، وكُنْيَتُهُ: أبو عبدِ الرَّحمانِ. وكذلكَ أبو بكرِ بنُ مُحَمَّدِ بنِ (٣) عَمْرِو بنِ حَزْمٍ الأنْصَاريُّ، يُقَالُ: إنَّ اسْمَهُ: أبو بكرٍ، وكُنْيَتُهُ: أبو مُحَمَّدٍ، ولا نَظِيْرَ لِهَذَينِ في ذَلِكَ، قالَهُ الخطيبُ. وقَدْ قيلَ: إنَّهُ لا كُنيةَ لابنِ حَزْمٍ (٤) غيرُ الكُنيةِ التي هيَ (٥) اسْمُهُ.","",{"fn":"بضم الميم الأولى وسكون الشين المعجمة، وضم الكاف الثانية - وقيل: بفتحها أيضًا -. انظر: السير ١١/ ١٥٦، والمنهل الروي: ١٢٠، والمقنع ٢/ ٥٩٠، والتقريب (٣٤٩٣)، وتدريب الراوي ٢/ ١٥٩.\nانظر في ذلك: معرفة علوم الحديث: ١٧٧ - ١٩٠، الإرشاد ٢/ ٦٦٨ - ٦٧٨، والتقريب: ١٧٥ - ١٧٧، واختصار علوم الحديث: ٢١٥ - ٢١٨، والشذا الفياح ٢/ ٥٩٦ - ٦٠٤، والمقنع ٢/ ٥٧١ - ٥٨٠، وشرح التبصرة ٣/ ١١٣ - ١٢٨، ونزهة النظر ١٩٤، وطبعة عتر: ٧٥ - ٧٦، وفتح المغيث ٣/ ١٩٩ - ٢٠٥، وتدريب الراوي ٢/ ٢٧٨ - ٢٨٦، ... وشرح السيوطي على ألفية العراقي: ٢١٩، وفتح الباقي ٣/ ١١٥ - ١٢٣، وتوضيح الأفكار ٢/ ٤٨٢ - ٤٨٣.\nانظر: محاسن الاصطلاح: ٥٠٨.\nفي (ب) و(م): «ينتقصون».\nسقطت من (ع)."}],[1598,"الثَّاني مِنْ هَؤُلاءِ: مَنْ لا كُنْيَةَ لهُ غيرُ الكُنيةِ التي هيَ اسْمُهُ. مِثَالُهُ: أبو بِلالٍ الأشْعَرِيُّ الرَّاوي عَنْ شَرِيْكٍ وغيرِهِ، رُوِيَ عنهُ أنَّهُ قالَ: ليسَ لي اسْمٌ؛ اسْمِي وكُنْيَتِي واحِدٌ (٦). وهَكَذا أبو حَصِيْنِ بنُ يَحْيَى بنِ سُلَيْمانَ الرَّازِيُّ -بفتحِ الحاءِ-. روَى عنهُ جَماعَةٌ مِنْهُم: أبو حاتِمٍ الرَّازيُّ، وسَأَلَهُ: هَلْ لكَ اسمٌ؟ فقَالَ: لا، اسْمِي وكُنْيَتِي واحِدٌ (٧)."],[1599,"الضَّرْبُ الثَّانِي: الذِينَ عُرِفُوا بِكُناهُمْ ولَمْ يُوقَفْ عَلَى أسْمائِهِمْ ولا عَلَى حالِهِمْ فيها، هلْ هي (٨) كُناهُمْ أوْ غيرُها؟ مِثَالُهُ مِنَ الصَّحَابةِ:"],[1600,"- أبو أُنَاسٍ -بالنُّونِ- الكِنانِيُّ، ويُقَالُ: الدِّيْلِيُّ (٩) مِنْ رَهْطِ أبي الأسْودِ الدِّيْلِيِّ، ويُقَالُ فيهِ: الدُّؤَلِيُّ - بالضَّمِّ والهمزةُ مفتوحَةٌ - في النَّسَبِ عِنْدَ بعضِ أهلِ العربِيَّةِ، ومَكْسُورَةٌ عِنْدَ بعضِهِمْ عَلَى الشُّذُوذِ فيهِ (١٠).","",{"fn":"في (أ): «وهذا طريق ...».\nراجع: التقييد: ٣٦٨، ومحاسن الاصطلاح: ٥٠٩.\n«ابن» ساقطة من (ع).\nفي (م): «حزام».\n«هي» ساقطة من (ع).\nالجرح والتعديل ٨/ ٣٥٠ (١٥٦٦).\nالجرح والتعديل ٨/ ٣٦٤ (١٦٦٣).\n«هي» ساقطة من (ع).\nفي (ع) والتقييد: «الدئلي».\nانظر: الاشتقاق: ٣٢٥، والأنساب ٢/ ٥٦٩ و٥٩٠، والسير ٤/ ٨٥، وشرح المفصل لابن يعيش ١٠/ ١٤٥، وشرح ابن عقيل ٢/ ٤٩٤، والتقريب (٧٩٤٠)."}],[1601,"- وأبو مُوَيْهِبَةَ مَوْلَى رَسُولِ اللهِ - صلى الله عليه وآله وسلم -."],[1602,"- وأبو شَيْبَةَ الْخُدْرِيُّ الذي ماتَ في حِصَارِ القُسْطَنْطِيْنِيَّةِ ودُفِنَ هُنَاكَ مَكانَهُ."],[1603,"ومِنْ غيرِ الصَّحَابةِ:"],[1604,"- أبو الأَبْيَضِ الرَّاوِي عَنْ أنَسِ بنِ مَالِكٍ (١)."],[1605,"- أبو بكرِ بنُ نافِعٍ مَوْلَى ابنِ عُمَرَ، رَوَى عنهُ مالِكٌ وغيرُهُ."],[1606,"- أبو النَّجِيبِ مَوْلَى عبدِ اللهِ بنِ عَمْرِو بنِ العَاصِ (٢) - بالنُّونِ المفتوحةِ في أوَّلِهِ، وقيلَ: بالتَّاءِ المضمومةِ باثنتينِ مِنْ فوقُ (٣) -."],[1607,"- أبو حَرْبِ بنِ أبي الأسْودِ الدِّيلِيُّ (٤)."],[1608,"- أبو حَرِيْزٍ الْمَوْقِفِيُّ (٥)، والْمَوْقِفُ مَحَلَّةٌ بِمِصْرَ. روَى عنهُ ابنُ وَهْبٍ وغيرُهُ، واللهُ أعلمُ."],[1609,"الضَّرْبُ الثَّالِثُ: الذِيْنَ لُقِّبُوا بالكُنَى ولَهُمْ غيرُ ذَلِكَ كُنًى وأسْماءٌ، مِثَالُهُ:"],[1610,"- عليُّ بنُ أبي طالِبٍ - رضي الله عنه -، يُلَقَّبُ بأبي تُرَابٍ، ويُكْنَى أبا الحسَنِ."],[1611,"- أبو الزِّنادِ عبدِ اللهِ بنِ ذَكْوَانَ، كُنْيَتُهُ: أبو عبدِ الرَّحمانِ، وأبو الزِّنَادِ لَقَبٌ. وذَكَرَ الحافِظُ أبو الفَضْلِ (٦) الفَلَكِيُّ - فيما بَلَغَنا عنهُ - أنَّهُ كانَ يَغْضَبُ مِنْ أبي الزِّنادِ وكانَ عالِمًا مُفْتَنًا (٧)."],[1612,"- أبو الرِّجَالِ مُحَمَّدُ بنُ عبدِ الرَّحمانِ الأنصَارِيُّ، كُنْيَتُهُ: أبو عبدِ الرَّحْمانِ، وأبو الرِّجالِ لَقَبٌ لُقِّبَ بهِ؛ لأنَّهُ كانَ لهُ عَشَرَةُ أوْلادٍ كُلُّهُمْ رِجالٌ.","",{"fn":"انظر: التقييد: ٣٦٩.\nفي (ع): «العاصي».\nانظر: التقييد: ٣٧٠.\nانظر: المحاسن: ٥١١.\nبفتح الميم والواو الساكنة، والقاف المكسورة. انظر: الأنساب ٥/ ٣٠٤، ومراصد الاطلاع ٣/ ١٣٣٥.\nتاريخ دمشق ٢٨/ ٥١، ونقل أيضًا عن علي بن المديني القول نفسه.\nفي (ب): «مفسرًا»، وفي (أ) و(جـ): «مُفتيًا»، ومثله في المقنع ٢/ ٥٧٦."}],[1613,"- أبو تُمَيْلَةَ -بِتَاءٍ مَضْمُومةٍ مُثَنَّاةٍ مِنْ فَوْقُ- يَحْيَى بنُ واضِحٍ الأنْصَارِيُّ المرُوزِيُّ، يُكْنَى: أبا مُحَمَّدٍ، وأبو تُمَيْلَةَ لَقَبٌ، وثَّقَهُ يَحْيَى بنُ مَعينٍ وغيرُهُ، وأنْكَرَ أبو حاتِمٍ الرَّازِيُّ (١) عَلَى البُخَارِيِّ إدْخالَهُ إيَّاهُ في كِتابِ \" الضُّعَفَاءِ \"."],[1614,"- أبو الآذانِ الحافِظُ عُمَرُ بنُ إبرَاهِيمَ، يُكْنَى أبا بَكْرٍ، وأبو الآذَانِ لَقَبٌ لُقِّبَ بهِ؛ لأنَّهُ كانَ كبيرَ الأُذُنَيْنِ."],[1615,"- أبو الشَّيْخِ الأصْبهانِيُّ عبدُ اللهِ بنُ مُحَمَّدٍ الحافِظُ كُنْيَتُهُ أبو مُحَمَّدٍ، وأبو الشَّيْخِ لَقَبٌ."],[1616,"- أبو حَازِمٍ العَبْدَوِيُّ (٢) الحافِظُ عُمَرُ بنُ أحمدَ، كُنْيَتُهُ: أبو حَفْصٍ، وأبو حازِمٍ لَقَبٌ، وإنَّما اسْتَفَدْناهُ مِنْ كِتابِ الفَلَكِيِّ في \" الألقابِ \" (٣)، واللهُ أعلمُ."],[1617,"الضَّرْبُ الرَّابِعُ: مَنْ لهُ كُنْيتانِ أو أكْثَرُ. مِثَالُ ذَلِكَ:"],[1618,"- عبدُ الملكِ بنُ عبدِ العزيزِ بنِ جُرَيْجٍ (٤) كانتْ لهُ كُنْيَتانِ: أبو خالدٍ، وأبو الوليدِ."],[1619,"- عبدُ اللهِ بنُ عُمَرَ بنِ حَفْصٍ العُمَرِيُّ أخو عُبيدِ اللهِ رُوِيَ أنَّهُ كانَ يُكْنَى أبا القاسِمِ فَتَرَكَهَا واكْتَنَى أبا عبدِ الرَّحْمانِ. وكانَ لِشَيْخِنا منصُورِ بنِ أبي المعَالِي النَّيْسابوريِّ"],[1620,"- حفيدِ الفرَاوِيِّ - ثَلاثُ كُنًى: أبو بكرٍ، وأبو الفَتْحِ، وأبو القَاسِمِ، واللهُ أعلمُ.","",{"fn":"الجرح والتعديل ٩/ ١٩٤، وفيه: «هو ثقة في الحديث، أدخله البُخَارِيّ في كتاب الضعفاء يحول من هناك»، وقد تعقَّبه الذهبي في الميزان ٤/ ٤١٣ فقال: «وقد وهم أبو حاتم إذ زعم أن البُخَارِيّ تكلم فيه وذكره في الضعفاء فلم أرَ ذَلِكَ، ولا كان ذَلِكَ فإن البُخَارِيّ قد احتج به، ولولا أن ابن الجوزي ذكره في الضعفاء لما أوردته». وقال في السير ٩/ ٢١١ بعد أن وَهَّم أبا حاتم: «ولم أرَ ذِكرًا لأبي تميلة في كتاب الضعفاء للبخاري، لا في الكبير ولا في الصغير».\nقال في الأنساب ٤/ ١٠٩: «بفتح العين المهملة، وسكون الباء الموحدة، وفتح الدال المهملة، وقيل في هذه النسبة: عبدويي، وهذه النسبة إلى عبدويه، فإن قيل كما يقول النحويون: عبدويه، فالنسبة إليه عبدوي -بفتح الدال-، وإن قيل: كما يقول المحدِّثون: عبدويه -بضم الدال- فالنسبة إليه عبدويي».\nاسمه: \" معرفة ألقاب المحدِّثين \"، كما قال السمعاني في الأنساب ٤/ ٣٧٩، وانظر: ترجمته في السير ١٧/ ٥٠٢.\nفي (ع) والتقييد: «جريج» بالحاء المهملة، وهو تصحيف."}],[1621,"الضَّرْبُ الخامِسُ: مَنِ اخْتُلِفَ في كُنْيَتِهِ فَذُكِرَ لهُ عَلَى الاخْتِلافِ كُنْيتانِ أوْ أكْثَرُ، واسمُهُ مَعْرُوفٌ، ولِعَبْدِ اللهِ بنِ عَطاءٍ الإبْرَاهِيْمِيِّ الْهَرَوِيِّ - مِنَ المتأخِّرِينَ - فيهِ مُخْتَصَرٌ. مِثَالُهُ:"],[1622,"- أُسَامةُ بنُ زَيْدٍ، حِبُّ رَسُولِ اللهِ - صلى الله عليه وآله وسلم -، قيلَ: كُنْيَتُهُ أبو زيدٍ، وقيلَ: أبو مُحَمَّدٍ، وقيلَ: أبو عبدِ اللهِ، وقيلَ: أبو خارِجةَ."],[1623,"- أُبَيُّ بنُ كَعْبٍ، أبو المنْذِرِ، وقيلَ: أبو الطُّفَيْلِ (١)."],[1624,"- قَبِيْصَةُ بنُ ذُؤَيْبٍ، أبو إسْحاقَ، وقيلَ: أبو سَعِيْدٍ."],[1625,"- القَاسِمُ بنُ مُحَمَّدِ بنِ أبي بكرٍ الصِّدِّيقِ: أبو عبدِ الرَّحْمانِ، وقيلَ: أبو مُحَمَّدٍ."],[1626,"- سُلَيْمانُ بنُ بِلالٍ المدنِيُّ: أبو بِلالٍ، وقيلَ: أبو مُحَمَّدٍ (٢). وفي بعضِ مَنْ ذُكِرَ في هذا القسمِ مَنْ هُوَ في نفسِ الأمْرِ مُلتحقٌ بالضَّرْبِ الذي قَبْلَهُ، واللهُ أعلمُ."],[1627,"الضَّرْبُ السَّادِسُ: مَنْ عُرِفَتْ كُنْيَتُهُ واخْتُلِفَ في اسْمِهِ. مِثَالُهُ مِنَ الصَّحابةِ:"],[1628,"- أبو بَصْرَةَ الغِفَارِيُّ عَلَى لَفْظِ البَصْرَةِ البلْدَةِ، قيلَ: اسمهُ جَمِيلُ بنُ بَصْرَةَ"],[1629,"- بالجيمِ -، وقيلَ: حُمَيْلٌ - بالحاءِ المهملةِ المضمومةِ - وهوَ الأصَحُّ (٣)."],[1630,"- أبو جُحَيْفَةَ السُّوائِيُّ (٤)، قيلَ: اسمُهُ وَهْبُ بنُ عبدِ اللهِ، وقيلَ: وَهْبُ اللهِ بنُ عبدِ اللهِ (٥).","",{"fn":"انظر: محاسن الاصطلاح ٥١٣.\nلَمْ يذكر أحد ممن ترجم له أنه يكنى بأبي بلال، وإنما هو: «أبو أيوب»، وانظر: الجرح والتعديل ٤/ ١٠٣، وتهذيب الكمال ٣/ ٢٦٦ (٢٤٨٠)، والكاشف ١/ ٤٥٧ (٢٠٧٣) مع حاشية المحقق. وانظر: تعقب العراقي في التقييد ٣٧٢.\nانظر: الإكمال ٢/ ١٢٧، وتبصير المنتبه ١/ ٢٦٤.\nبضم المهملة والمد. التقريب (٧٤٧٩).\nهكذا مثّل به المصنِّف، والذي وقفنا عليه في كتب تراجم الخلاف في اسم أبيه: أهو عبد الله أم وهب؟ إلاَّ أنَّ النووي ذكر أن عليًا كان يُسميه: وهب الخير، ووهب الله. وأشار محقق الجرح والتعديل إلى وقوع مثل هذا في إحدى النسخ، فالله أعلم بالصواب. الجرح والتعديل ٩/ ٢٢، والاستيعاب ٤/ ٣٦، وتهذيب الأسماء واللغات ٢/ ٢٠١، والسير ٣/ ٢٠٢."}],[1631,"- أبو هُرَيْرَةَ الدَّوْسِيُّ، اخْتُلِفَ في اسْمِهِ واسْمِ أبيهِ (١) اختلافٌ كثيرٌ جِدًّا لَمْ يُخْتَلَفْ مِثْلُهُ في اسْمِ أحَدٍ في الجَاهِلِيَّةِ والإسْلامِ، وذَكَرَ ابنُ عبدِ البرِّ أنَّ فيهِ نحوَ عِشْرينَ قَوْلَةً في اسْمِهِ واسْمِ أبيهِ، وأنَّهُ لِكَثْرَةِ الاضْطِرابِ لَمْ يَصِحَّ عِنْدَهُ في اسْمِهِ شيءٌ يُعْتَمَدُ عليهِ إلاَّ أنَّ عبدَ اللهِ أو عبدَ الرَّحْمَانِ هوَ الذي يَسْكُنُ إليهِ القَلْبُ في اسْمِهِ في الإسلامِ (٢)، وذَكَرَ عَنْ مُحَمَّدِ بنِ إسْحاقَ: «أنَّ اسْمَهُ عبدُ الرَّحْمانِ بنُ صَخْرٍ» (٣)، قالَ (٤): وعلى هذا اعْتَمَدَتْ طَائِفةٌ ألَّفَتْ في الأسْماءِ والكُنَى (٥)، قالَ: وقالَ أبو أحمدَ الحاكِمُ: أصَحُّ شيءٍ عِنْدَنا في اسْمِ أبي هُرَيْرَةَ: عبدُ الرَّحمانِ بنُ صَخْرٍ (٦)."],[1632,"ومِنْ غَيْرِ الصَّحابةِ:"],[1633,"- أبو بُرْدَةَ بنُ أبي مُوْسَى الأشْعَرِيُّ أكْثَرُهُمْ عَلَى أنَّ اسْمَهُ عامِرٌ، وعَنْ ابنِ مَعِيْنٍ أنَّ اسْمَهُ: الحارِثُ (٧)."],[1634,"- أبو بكرِ بنُ عَيَّاشٍ، راوِي قِراءةِ عاصِمٍ، اخْتُلِفَ في اسْمِهِ عَلَى أحَدَ عَشَرَ قَوْلًا، قالَ ابنُ عبدِ البرِّ: «إنْ صَحَّ لهُ اسْمٌ فهوَ شُعْبَةُ لا غيرُ، وهوَ الذي صَحَّحَهُ أبو زُرْعَةَ» (٨)."],[1635,"قالَ ابنُ عبدِ البرِّ: «وقيلَ: اسْمُهُ كُنْيَتُهُ وهذا أصَحُّ إنْ شَاءَ اللهُ؛ لأنَّهُ رُوِيَ عنهُ أنَّهُ قالَ: ما لِيَ اسْمٌ غيرُ أبي بكرٍ» (٩)، واللهُ أعلمُ.","",{"fn":"راجع: المحاسن: ٥١٥.\nالاستيعاب ٤/ ٢٠٧.\nالاستيعاب ٤/ ٢٠٦.\nيعني: ابن عبد البر.\nالاستيعاب ٤/ ٢٠٦.\nالاستيعاب ٤/ ٢٠٨، وانظر: الإرشاد ٢/ ٦٧٥.\nتاريخ يحيى بن معين رواية الدوري ٣/ ٤٢٦.\nالاستغناء ١/ ٤٤٥.\nالمصدر السابق."}],[1636,"السَّابِعُ (١): مَنِ اخْتُلِفَ في كُنْيَتِهِ واسْمِهِ معًا، وذلكَ قَليلٌ. مِثَالُهُ:"],[1637,"- سَفِيْنَةُ مَوْلَى رَسُولِ (٢) اللهِ - صلى الله عليه وآله وسلم -، قيلَ: اسمُهُ عُمَيْرٌ، وقيلَ: صالِحٌ، وقيلَ: مِهْرَانُ، وكُنْيَتُهُ: أبو عبدِ الرَّحمانِ، وقيلَ: أبو البَخْتَرِيِّ، واللهُ أعلمُ."],[1638,"الثَّامِنُ (٣): مَنْ لَمْ يُخْتَلَفْ في كُنيتِهِ واسْمِهِ وعُرِفا جَمِيْعًا واشْتُهِرا. ومِنْ أمثِلَتِهِ: أئِمَّةُ المذَاهِبِ ذَوُو أبي عبدِ اللهِ: مالِكٌ، ومُحَمَّدُ بنُ إدريسَ الشَّافِعِيُّ، وأحمدُ بنُ حَنْبَلٍ، وسُفيانُ الثَّوريُّ، وأبو حنيفةَ النُّعمانُ بنُ ثابِتٍ في خَلْقٍ كَثِيْرٍ."],[1639,"التَّاسِعُ (٤): مَنِ اشْتَهَرَ بكُنْيَتِهِ دُونَ اسْمِهِ، واسْمُهُ مَعَ ذَلِكَ غيرُ مَجْهولٍ عِنْدَ أهلِ العِلْمِ بالحديثِ. ولابنِ عبدِ البرِّ تَصْنيفٌ مَليحٌ فيمَنْ بعدَ الصَّحابةِ مِنْهُم: مِثَالُهُ:"],[1640,"- أبو إدْريسَ الخَوْلانِيُّ (٥) اسمُهُ: عائِذُ اللهِ بنُ عبدِ اللهِ."],[1641,"- أبو إسحاقَ السَّبِيعِيُّ، اسْمُهُ: عَمْرُو بنُ عبدِ اللهِ."],[1642,"أبو الأشْعَثِ الصَّنْعانِيُّ -صَنْعاءُ دِمَشْقَ (٦) -، اسْمُهُ: شَرَاحِيلُ بنُ آدَةَ - بهمزةٍ ممدُودَةٍ بعدَها دالٌ مُهملةٌ مَفْتوحةٌ مُخَفَّفةٌ، ومِنْهُم مَنْ شَدَّدَ الدَّالَ ولَمْ يَمُدَّ (٧) -."],[1643,"- أبو الضُّحَى مُسْلِمُ بنُ صُبَيحٍ - بضمِّ الصَّادِ المهملةِ -."],[1644,"- أبو حازمٍ الأعْرَجُ الزَّاهِدُ الرَّاوي عَنْ سَهْلِ بنِ سَعْدٍ وغيرِهِ، اسْمُهُ: سَلَمَةُ بنُ دِينارٍ ومَنْ لاَ يُحْصَى، واللهُ أعلمُ.","",{"fn":"في (م): «الضرب السابع».\nفي (ع): «رسوله» خطأ.\nفي (م): «الضرب الثامن».\nفي (م): «الضرب التاسع».\nبفتح الخاء المعجمة وسكون الواو وفي آخرِها النون. الأنساب ٢/ ٤٧٨.\nفي (ع): «من صنعاء دمشق».\nفي (م) والشذا والتقييد: «لَمْ يمده»."}],[1645,"النوع الحادي والخمسون معرفة كنى المعروفين بالأسماء دون الكنى"],[1646,"وهذا مِنْ وَجْهٍ ضِدُّ النَّوْعِ (١) الذي قَبْلَهُ، ومِنْ شَأْنِهِ أنْ يُبَوَّبَ عَلَى الأسْماءِ ثُمَّ تُبَيَّنَ كُناهَا بِخِلاَفِ ذاكَ، ومِنْ وَجْهٍ آخَرَ يَصْلُحُ لأنْ يُجْعَلَ قِسْمًا مِنْ أقْسَامِ مِنْ حيثُ كَونُهُ قِسْمًا مِنْ أقْسَامِ أصْحابِ الكُنَى، وقَلَّ مَنْ أفْرَدَهُ بالتَّصْنِيفِ، وبَلَغَنا أنَّ لأبي حاتِمِ بنِ حِبَّانَ البُسْتِيِّ فيهِ كِتابًا. ولنَجْمَعْ في التَّمْثِيْلِ جَماعاتٍ في كُنيةٍ واحدَةٍ تَقْريبًا عَلَى الضَّابِطِ."],[1647,"فَمِمَّنْ يُكْنَى بأبي مُحَمَّدٍ مِنْ هذا القَبِيْلِ مِنَ الصَّحَابةِ - رضي الله عنهم - أجمعِيْنَ:"],[1648,"- طَلْحَةُ بنُ عُبيدِ (٢) اللهِ التَّيْمِيُّ (٣)."],[1649,"- عبدُ الرَّحْمانِ بنُ عَوْفٍ الزُّهْرِيُّ."],[1650,"- الحسَنُ بنُ عَلِيِّ بنِ أبي طَالِبٍ الهاشِمِيُّ."],[1651,"- ثَابِتُ بنُ قَيْسِ بنِ الشَّمَّاسِ (٤)."],[1652,"- عبدُ اللهِ بنُ زيدٍ - صاحِبُ الأذَانِ (٥) - الأنْصَارِيَّانِ."],[1653,"- كَعْبُ بنُ عُجْرَةَ."],[1654,"- الأشْعَثُ بنُ قَيْسٍ."],[1655,"- مَعْقِلُ بنُ سِنانٍ الأشْجَعِيُّ."],[1656,"- عبدُ اللهِ بنُ جَعْفَرِ بنِ أبي طَالِبٍ (٦).","",{"fn":"في (ع): «ضد هذا النوع».\nفي (ب): «عبد الله» مكبر، وهو تصحيف. انظر: طبقات ابن سعد ٣/ ٢١٤، والمعجم الكبير ١/ ١١٠، وتاريخ دمشق ٢٥/ ٥٤.\nفي (ب) و(جـ): «التميمي»، وهو تصحيف فهو تيمي كما في مصادر ترجمته.\nبمعجمة وميم مشددة وآخره مهملة. التقريب (٨٢٥).\nحديثه في الأذان أخرجه أحمد ٤/ ٤٢، وابن خزيمة (٣٧٣)، وغيرهما.\nانظر: التقييد والإيضاح: ٣٧٥، والإصابة ٢/ ٢٨٩، وقارن بـ: الجرح والتعديل ٥/ ٢١، والثقات لابن حبان ٣/ ٢٠٧."}],[1657,"- عبدُ اللهِ بنُ بُحَيْنَةَ."],[1658,"- عبدُ اللهِ بنُ عَمْرِو بنِ العَاصِ (١)."],[1659,"- عبدُ الرَّحمانِ بنُ أبي بَكرٍ الصِّدِّيْقِ."],[1660,"- جُبَيْرُ بنُ مُطْعِمٍ."],[1661,"- الفَضْلُ بنُ العَبَّاسِ بنِ عبدِ المطَّلِبِ."],[1662,"- حُوَيْطِبُ بنُ عبدِ العُزَّى."],[1663,"- مَحْمُودُ بنُ الرَّبِيعِ."],[1664,"- عبدُ اللهِ بنُ ثَعْلَبَةَ بنِ صُعَيْرٍ."],[1665,"ومِمَّنْ يُكْنَى مِنْهُم بأبي عبدِ اللهِ:"],[1666,"- الزُّبَيْرُ بنُ العَوَّامِ."],[1667,"- الْحُسَيْنُ (٢) بنُ عليِّ بنِ أبي طالِبٍ."],[1668,"- سلْمانُ الفَارِسِيُّ."],[1669,"- عَامِرُ بنُ رَبِيْعةَ العَدَوِيُّ."],[1670,"- حُذَيْفَةُ بنُ اليَمَانِ."],[1671,"- كَعْبُ بنُ مَالِكٍ."],[1672,"- رافِعُ بنُ خَدِيْجٍ."],[1673,"- عُمَارَةُ بنُ حَزْمٍ (٣)."],[1674,"- النُّعْمانُ بنُ بَشِيْرٍ."],[1675,"- جابِرُ بنُ عبدِ اللهِ."],[1676,"- عُثْمانُ بنُ حُنَيْفٍ (٤).","",{"fn":"في (ع): «العاصي».\nفي (جـ): «الحسن»، وهو تصحيف، فأبو عبد الله هو الحسين. انظر تهذيب الكمال ٢/ ١٨٣، والإصابة ١/ ٣٣٢.\nانظر: التقييد والإيضاح: ٣٧٥.\nانظر: التقييد والإيضاح: ٣٧٦."}],[1677,"- حَارِثَةُ بنُ النُّعْمانِ. وهَؤُلاَءِ السَّبْعَةُ أنْصَارِيُّونَ."],[1678,"- ثَوْبَانُ مَوْلَى رَسُولِ اللهِ - صلى الله عليه وآله وسلم -."],[1679,"- المغيرَةُ بنُ شُعْبَةَ."],[1680,"- شُرَحْبِيلُ بنُ حَسَنَةَ."],[1681,"- عَمْرُو بنُ العَاصِ (١)."],[1682,"- مُحَمَّدُ بنُ عبدِ اللهِ بنِ جَحْشٍ."],[1683,"- مَعْقِلُ بنُ يَسَارٍ، وعَمْرُو بنُ عامِرٍ المُزَنِيَّانِ."],[1684,"ومِمَّنْ يُكْنَى مِنْهُم بأبي عبدِ الرَّحمانِ:"],[1685,"- عبدُ اللهِ بنُ مَسْعُودٍ."],[1686,"- مُعَاذُ بنُ جَبَلٍ."],[1687,"- زَيْدُ بنُ الخَطَّابِ - أخو عُمَرَ بنِ الخَطَّابِ -."],[1688,"- عبدُ اللهِ بنُ عُمَرَ بنِ الخَطَّابِ."],[1689,"- مُحَمَّدُ بنُ مَسْلَمَةَ الأنْصَارِيُّ."],[1690,"- عُوَيْمُ بنُ سَاعِدَةَ - عَلَى وزنِ نُعَيْمٍ -."],[1691,"- زيدُ بنُ خالِدٍ الْجُهَنِيُّ."],[1692,"- بِلاَلُ بنُ الحارِثِ الْمُزَنِيُّ."],[1693,"- مُعَاوِيةُ بنُ أبي سُفْيانَ."],[1694,"- الحارِثُ بنُ هِشَامٍ المخزُومِيُّ."],[1695,"- المِسْوَرُ بنُ مَخْرَمَةَ."],[1696,"وفي بعضِ مَنْ ذَكَرْناهُ مِنْ قَبْلُ (٢)، في كُنيتِهِ غيرُ ما ذَكرناهُ، واللهُ أعلمُ.","",{"fn":"في (ع): «العاصي».\nفي (جـ): «قُبيل»، وَفِي (ع) والتقييد: «قِيلَ»، والمثبت من (أ) و(ب) و(م) والشذا."}],[1697,"النَّوعُ الثَّانِي والْخَمْسُوْنَ"],[1698,"مَعْرِفَةُ أَلْقَابِ (١) الْمُحَدِّثِيْنَ وَمَنْ يُذْكَرُ مَعَهُمْ (٢)"],[1699,"وَفيها كَثْرَةٌ. ومَنْ لا يَعْرِفُها يُوشِكُ أَنْ يَظُنَّها أسامِيَ وأنْ يَجْعَلَ مَنْ ذُكِرَ باسمِهِ فِي مَوْضِعٍ وبِلقبِهِ فِي موضعٍ شَخْصَينِ، كَمَا اتَّفَقَ لكثيرٍ مِمَّن ألَّفَ. وَمِمَّنْ صنَّفَها: أَبُو بَكْرٍ أَحْمَدُ بنُ عَبْدِ الرَّحمانِ الشِّيرازيُّ الحافظُ ثُمَّ أَبُو الفَضْلِ ابنُ الفَلَكيِّ الحافظُ. وَهِيَ تَنْقَسِمُ إلى مَا يَجوزُ التَّعريفُ بِهِ وَهُوَ مَا لا يَكْرَهُهُ المُلَقَّبُ، وإلى مَا لاَ يَجُوزُ وَهُوَ مَا يَكْرَهُهُ المُلَقَّبُ (٣). وهذا أُنْمُوذَجٌ مِنْها مُخْتَارٌ."],[1700,"رُوِّينا عَنْ عَبْدِ الغَنِّي بنِ سَعيدٍ الحَافِظِ أَنَّهُ قَالَ: رَجُلانِ جَلِيلانِ لَزِمَهُما لَقَبانِ قَبيحَانِ: معاويةُ بنُ عَبْدِ الكريمِ الضَّالُ (٤)؛ وإنَّما ضَلَّ فِي طَرِيقِ مكَّةَ، وعبدُ اللهِ بنُ مُحَمَّدٍ الضَّعِيفُ (٥)؛ وإنَما كَانَ ضَعِيْفًا فِي جِسْمِهِ لا فِي حَدِيثِهِ (٦). قُلْتُ: وثالثٌ، وَهُوَ عَارِمٌ (٧) أَبُو النُّعْمَانِ مُحَمَّدُ بنُ الفَضْلِ السَّدوسيُّ (٨) وَكَانَ عَبْدًا صَالِحًا بَعِيدًا عَنِ (١) العَرَامِةِ (٢)، والضَّعِيفُ هُوَ الطَّرَسُوسِيُّ (٣) أَبُو مُحَمَّدٍ سَمِعَ أبا مُعاويةَ الضَّرِيرِ وغيرَهُ، كَتَبَ عَنْهُ أَبُو حَاتِمٍ الرازيُّ وزَعَمَ أَبُو حَاتِمِ بنُ حِبَّانَ أنَّهُ قِيلَ لهُ: الضَّعِيفُ لإتقانِهِ وضَبْطِهِ (٤).","",{"fn":"وهذه الألقاب تكون تارة بألفاظ الأسماء كأشهب، وبالصنائع والحرف كالبقال وبالصفات كالأعمش، والكنى كأبي بطن والأنساب إلى القبائل والبلدان وغيرها. انظر: فتح المغيث ٣/ ١٧٨.\nانظر في ذلك: معرفة علوم الحديث: ٢١٠ - ٢١٥، الإرشاد ٢/ ٦٨٦ - ٦٩٥، والتقريب: ١٧٨ - ١٨٠ والاقتراح: ٣١٥ - ٣١٧، واختصار علوم الحديث: ٢٢٠ - ٢٢٣، والشذا الفياح ٢/ ٦١١ - ٦١٦، والمقنع ٢/ ٥٨٣ - ٥٩١، وشرح التبصرة ٣/ ١٢٨ - ١٣٣، ونزهة النظر: ٢٠٢، وطبعة عتر: ٧٨، وفتح المغيث ٣/ ٢٠٦ - ٢١٠، وتدريب الراوي ٢/ ٢٨٩ - ٢٩٦، وشرح السيوطي على ألفية العراقي: ٢٢٢، وفتح الباقي ٣/ ١٢٣ - ١٢٧، وتوضيح الأفكار ٢/ ٤٨٢ - ٤٨٣، وظفر الأماني: ١١٨.\nراجع محاسن الاصطلاح ٥٢١.\nالأنساب ٨/ ٣٧٠، واللباب ٢/ ٢٥٧، نزهة الألباب ١/ ٤٣٥.\nالأنساب ٨/ ٢٩٥، واللباب ٢/ ٢٦٤، ونزهة الألباب ١/ ٤٣٦.\nأورد هذا القول السمعاني في الأنساب ٨/ ٣٩٥.\nانظر: الجامع لأخلاق الرّاوي ٢/ ٧٥ عقيب (١١٢٥)، والأنساب ٤/ ٨٨، والإكمال ٦/ ٢٠.\nبضم الدال المهملة والواو بين السينين المهملتين أولاهما مفتوحة. الأنساب ٣/ ٢٥٨."}],[1701,"- غُنْدَرٌ (٥): لَقَبُ مُحَمَّدِ بنِ جَعْفَرٍ البَصْريِّ أبي بَكْرٍ. وَسبَبُهُ مَا (٦) رُوِّينا أنَّ ابنَ جُرَيجٍ قَدِمَ البَصْرةَ فحدَّثَهُم بحديثٍ عنِ الحَسَنِ البَصْرِيِّ فأنكروهُ عَلَيْهِ وشَغَّبوا وأكثَرَ مُحَمَّدُ بنُ جَعْفَرٍ مِنَ الشَّغَبِ عَلَيْهِ، فقالَ لَهُ: اسكُتْ يا غُنْدَرُ! - وأهلُ الحجازِ يُسَمَّونَ المُشَغِّبَ غُنْدَرًا - (٧) ثُمَّ كَانَ بَعْدَهُ غَنَادِرةٌ كُلٌّ مِنْهُمْ يُلَقَّبُ بِغُنْدَرٍ، مِنْهُمْ: مُحَمَّدُ بنُ جَعْفَرٍ الرَّازِيُّ (٨) أَبُو الحُسَين (٩) غُنْدَرٌ رَوَى عَنْ أبي حاتمٍ الرَّازِيِّ وغيرِه، ومنهم: مُحَمَّدُ ابنُ جَعْفَرٍ أَبُو بَكْرٍ البغداديُّ غُنْدَرٌ الحافظُ الجَوَّالُ حدَّثَ عَنْهُ أَبُو نُعَيْمٍ الحافظُ وغيرُهُ. ومنهم: مُحَمَّدُ بنُ جَعْفَرِ بنُ دُرَّانَ البغداديُّ أَبُو الطَّيِّبِ رَوَى عَنْ أبي خَلِيفةَ الجُمَحيِّ وغيرِهِ، وآخرونَ لُقِّبوا بذلكَ مِمَّنْ لَيْسَ بمحمّدِ بنِ جَعْفَرٍ (١٠).","",{"fn":"في (ع) والتقييد: «من» وما أثبتناه من النسخ و(م).\nهي الفساد كما قاله النّوويّ، أو الشراسة كما قاله المحب الطبري، وهي النفور وسوء الخلق، ويجوز أن تكون مما ذكره ابن سيده حيث قال: «عرم يعرم عَرامةً وعُرامةً اشتدّ، وعند القزّاز: بلغ منزلةً» المقنع ٢/ ٥٨٤، وانظر: التقريب (١٧٨)، واللسان ١٢/ ٣٩٥ ومحاسن الاصطلاح ٥٢٢، ومتن اللغة ٤/ ٨٥. وقال ابن الجارود في المنتقى (١٩٨): «حدّثنا محمّد بن يحيى، قال: حدّثنا أبو النّعمان محمّد بن الفضل السدودسي، ولقبه عارم وكان بعيدًا عن العرامة ثقة صدوقًا مسلمًا ...».\nبفتح الطاء، والراء المهملتين، والواو بين السينين المهملتين الأولى مضمومة، والثانية مكسورة، هذه النسبة إلى طرسوس: وهي من بلاد الثغر بالشام. الأنساب ٤/ ٣٩.\nالثّقات ٨/ ٣٦٣.\nبضم الغين المعجمة وسكون النون وفتح الدال المهملة، انظر: الأنساب ٤/ ٢٨٧، ونزهة الألباب ٢/ ٥٧، ومحاسن الاصطلاح: ٥٢٢، وتاج العروس ١٣/ ٢٦٩.\nسقطت من (م).\nمعرفة علوم الحديث: ٢١٢، والجامع ٢/ ٧٤ (١٢٢٤)، وتهذيب الكمال ٦/ ٢٦٥ (٥٧٠٩)، ونزهة الألباب ٢/ ٥٨ (٢١٠١).\nفي (ب): «أبو بكر الرّازيّ».\nفي (أ): «أبو الحسن».\nذكر الحافظ ابن حجر في نزهة الألباب ٢/ ٥٨ - ٥٩ أحد عشر راويًا لقب بغندر."}],[1702,"- غُنْجَارٌ (١): لَقَبُ عِيسَى بنِ مُوسى التَّيْميِّ (٢) أبي أَحْمَدَ البخاريِّ مُتَقدِّمٌ حَدَّثَ عَنْ مَالِكٍ والثَّوريِّ وغَيرِهما لُقِّبَ بغُنْجَارٍ لِحُمْرةِ وَجْنَتَيهِ (٣). وغُنْجارٌ آخرُ متأخِّرٌ وَهُوَ أَبُو عَبْدِ اللهِ مُحَمَّدُ بنُ أَحْمَدَ البخاريُّ الحافِظُ صاحبُ \" تاريخ بُخارى \" ماتَ سنةَ"],[1703,"ثنتَيْ (٤) عَشْرَةَ وأَرْبعِ مئةٍ، واللهُ أعلمُ."],[1704,"- صَاعِقَةُ: هُوَ أَبُو يَحْيَى مُحَمَّدُ بنُ عَبْدِ الرَّحيمِ الحَافظُ رَوَى عَنْهُ البُخَارِيُّ وغيرُهُ. قَالَ أَبُو عَلِيٍّ الحافظُ: «إنَّما لُقِّبَ صاعِقَةُ لِحفْظِهِ وشِدَّةِ مُذاكَراتِهِ ومُطالَبَتِهِ» (٥)."],[1705,"- شَبَابٌ (٦): لَقَبُ خَلِيفَةَ بنِ خَيَّاطٍ العُصْفُرِيُّ (٧) صاحبِ \" التاريخِ \" سَمِعَ غُنْدَرًا وغيرَهُ."],[1706,"- زُنَيْجٌ (٨) بالنُّونِ والجيمِ: لَقَبُ أبي غَسَّانَ محمدِ بنِ عَمْرٍو [الأصْبَهانيِّ] (٩) الرَّازِيِّ رَوَى عَنْهُ مُسْلِمٌ وغيرُهُ."],[1707,"- رُسْتَهْ (١٠): لَقَبُ عَبْدِ الرَّحمانِ بنِ عُمَرَ الأصْبَهانيِّ.","",{"fn":"بضم الغين وسكون النون وفي آخرها الراء، انظر: الأنساب ٤/ ٢٨٤، ونزهة الأباب ٢/ ٥٦، وتاج العروس ١٣/ ٢٦٧.\nفي (ج) و(م): «التميمي» ويقال له ذلك أيضًا. انظر: تهذيب الكمال ٥/ ٥٦٠.\nالأنساب ٤/ ٢٨٤، ومعرفة علوم الحديث: ٢١٣.\nفي التقييد: «اثنتي».\nأخرجه الخطيب في تاريخ بغداد ٢/ ٣٦٣، وفي الجامع (١٢٢٨) عن ابن داود الكرخي، قال: «سمي صاعقة؛ لأنه كان جيد الحفظ»، وهو في تذكرة الحفاظ ٢/ ٥٥٣.\nبفتح الشين وتخفيف المعجمة كسحاب. انظر: الإكمال ٥/ ١٥، ونزهة الألباب ١/ ٣٩٣، والتاج ٣/ ٩٨.\nبضم العين وسكون الصاد المهملتين وضم الفاء بعدها راءٌ مهملة هذه نسبةٌ إلى العصفر وبيعه وشرائه وهو شيءٌ تصبغ به الثياب. الأنساب ٤/ ١٧٨.\nبضم الغين المعجمة وسكون النون وفتح الدال المهملة. انظر: الأنساب ٤/ ٢٨٧، ونزهة الألباب ٢/ ٥٧، ومحاسن الاصطلاح ٥٢٢، وتاج العروس ١٣/ ٢٦٩.\nليست في النسخ ولا (م) ولا في الشذا وهي من (ع) والتقييد.\nقال البلقيني: «رسته بلسانهم النبات من القمح وغيره في ابتدائه، وهو بضم الراء وإسكان المهملة وفتح التاء المثناة من فوق، وآخره هاءٌ ساكنةٌ». محاسن الاصطلاح ٥٢٤. وبنحو هذا التعليق في حاشية (ب) و(ج)، وانظر: الإكمال ٤/ ٧٢، والتبصير ٢/ ٦٠٣، والتقريب (٣٩٦٢)، والمنهل الرّوي ١١٩، والتاج ٤/ ٥٢٥."}],[1708,"- سُنَيدٌ (١): لَقَبُ الحُسَينِ بنِ داودَ المِصِّيصيِّ صاحبِ التفسيرِ رَوَى عَنْهُ (٢) أَبُو زُرْعَةَ وأبو حاتِمٍ الحافِظانِ وغيرُهما."],[1709,"- بُنْدَارٌ (٣): لَقَبُ مُحَمَّدِ بنِ (٤) بَشَّارٍ البَصْريِّ رَوَى عَنْهُ البُخَارِيُّ وَمُسْلِمٌ والناسُ. قَالَ ابنُ الفَلَكِي: إنَّما لُقِّبَ بهذا؛ لأنَّهُ كَانَ بُندَارَ الحَدِيْثِ (٥)."],[1710,"- قَيْصَرُ: لَقَبُ أبي النَّضْرِ هَاشِمِ بنِ القاسمِ المعْروفِ، رَوَى عَنْهُ أَحْمَدُ بنُ حَنْبَلٍ وغيرُهُ."],[1711,"- الأَخْفَشُ: لَقَبُ جَمَاعَةٍ مِنْهُمْ: أَحْمَدُ بنُ عِمْرَانَ البَصْريُّ النَّحْوِيُّ مُتقدِّمٌ رَوَى عَنْ زيدِ بنِ الحُبَابِ وغيرِهِ وله \"غريبُ المُوَطَّأِ \". وَفِي النَّحْويْينَ أَخافِشُ ثلاثةٌ مَشْهورُونَ:"],[1712,"أَكْبرُهُم: أَبُو الخَطَّابِ عَبْدُ الحَميدِ بنِ عَبْدِ المجيدِ وَهُوَ الذي ذَكَرَهُ سِيبَوَيْهِ فِي"],[1713,"\" كِتابهِ \"."],[1714,"والثَّانِي: سَعِيْدُ بنُ مَسْعَدةَ أبو الحسَنِ الذي يُروَى عنهُ كِتابِ سِيْبَوَيْهِ، وَهُوَ صاحبُهُ."],[1715,"والثَّالِثُ: أَبُو الحَسَنِ عَلِيُّ بنُ سُلَيمانَ صَاحِبُ أَبَوَي العَبَّاسِ النَّحْوِيَّيْنِ: أَحْمَدَ بنِ يَحْيَى المُلقَّبِ بِثَعْلَبٍ، ومُحَمَّدِ بنِ يَزيدَ الملقَّبِ بالمُبَرَِّدِ (٦)."],[1716,"- مُرَبَّعٌ (٧): بفتحِ الباءِ المشدَّدةِ، هُوَ مُحَمَّدُ بنُ إِبْرَاهِيمَ الحافظُ البغداديُّ.","",{"fn":"بنون ثمّ دال مصغرًا (التقريب ٢٦٤٦).\nفي (أ) و(ب): «عنهما».\nبضم الباء الموحدة وسكون النون وفتح الدال المهملة، وفي آخرها الراء هذه النسبة إلى من يكون مكثرًا من شيءٍ يشتري منه من هو أسفل منه أو أخف حالًا وأقل مالًا منه، ثُمَّ يبيع ما يشتري منه غيره. الأنساب ١/ ٤٢١ وانظر: الإكمال ١/ ٣٥٦ وقال في التاج ١٠/ ٢٥١: «وبندار معناه الحافظ»، ومثله في السير ١٢/ ١٤٤.\nساقطة من (م).\nانظر: تهذيب الكمال ٦/ ٢٤٧ (٥٦٧٥).\nبضم الميم وفتح الباء الموحدة، والراء المشددة، وبعدها دال مهملة. وفيات الأعيان ٤/ ٣٢١.\nبضم الميم وفتح الراء وتشديد الباء الموحدة المفتوحة كمعظم. انظر: الإكمال ٧/ ١٨١، والتبصير ٤/ ١٢٧٢ وتاج العروس ٢١/ ٥٢."}],[1717,"- جَزَرَةُ (١): لَقَبُ صالحِ بنِ مُحَمَّدٍ البغداديِّ الحافظِ لُقِّبَ بذلكَ مِن أجلِ أنَّهُ سَمِعَ مِنْ بعضِ الشِّيوخِ مَا رُوِيَ عَنْ عبدِ اللهِ بنِ بُسْرٍ أنَّهُ كَانَ يَرْقِيَ بِخَرَزةٍ فَصَحَّفَهَا وَقَالَ: جَزَرَةً بالجيمِ فَذَهبتْ عَلَيْهِ (٢) وَكَانَ ظريفًا (٣) لَهُ نوادرُ تُحكَى."],[1718,"- عُبَيْدٌ العِجْلُ (٤): لقبُ أبي عَبْدِ اللهِ الحُسَينِ بنِ محمدِ بنِ حاتِمٍ (٥) البَغْداديِّ الحَافِظِ."],[1719,"- كِيْلَجَةُ (٦): هُوَ مُحَمَّدُ بنُ صالحٍ البغداديُّ الحافظُ."],[1720,"- مَا غَمَّهُ: بلفظِ النَّفيِّ لِفعلِ الغَمِّ هُوَ لَقَبُ عَلاَّنِ بنِ عَبْدِ الصَّمدِ، وَهُوَ عَلِيُّ بنُ الحَسَنِ بنِ عبدِ الصَّمدِ البغداديُّ الحافظُ، ويُجمعُ فِيهِ بَيْن اللَّقَبَينِ فَيُقالُ: عَلاَّنٌ مَا غَمَّهُ. وهؤلاءِ البَغداديونَ الخمسةُ (٧) رُوِّينا أنَّ (٨) يَحْيَى بنَ مَعِينٍ هُوَ لَقَّبَهُم وهُم مِنْ كبارِ أصْحابِهِ وحُفَّاظِ الحديثِ (٩)."],[1721,"- سَجَّادةُ: المشْهورُ (١٠): هُوَ الحَسَنُ بنُ حَمَّادٍ سَمِعَ وَكِيعًا وغيرَهُ."],[1722,"- مُشْكُدَانَةُ (١١): ومَعْناهُ بالفارسيةِ: حَبَّةُ المِسْكِ أَوْ وِعاءُ المِسْكِ لَقَبُ عبدِ اللهِ ابنِ عُمَرَ بنِ محمدِ بنِ أبانَ.","",{"fn":"بفتح الجيم والزاي والراء، وفي الإرشاد للنووي ٢/ ٦٩٣: «بفتح الجيم وكسرها»، انظر: الإكمال ٧/ ٤٦١، والمقنع ٢/ ٥٨٩، والمنهل الروي: ١٢٠، والتاج ١٠/ ٤١٦.\nمعرفة علوم الحَدِيْث: ٢١٣، وتاريخ بغداد٩/ ٣٢٢ - ٣٢٣ وتذكرة الحفاظ٢/ ٦٤٢، ونزهة الألباب١/ ١٧٠.\nفي (أ) و(ب): «طريفًا» بالطاء المهملة.\nينون عبيد، ويضم العجل صفة له، ولا يقال بالإضافة فهي هنا مكروهة الصورة، وقد تقدم بيان ذلك.\nفي (م): «حامد» وهو مخالف لما في النسخ الخطية والشذا والتقييد ومصادر ترجمته. انظر: تاريخ بغداد ٨/ ٩٣، والسير ١٤/ ٩٠، والشذرات ٢/ ٢١٦.\nبكسر الكاف وفتح اللام، وضبطت الكاف بالفتح أيضًا، انظر: الإرشاد للنووي ٢/ ٦٩٤، واللسان ٢/ ١٦٢، والمنهل الروي ١٢٠، وتاج العروس ٦/ ١٧٥.\nفي (أ): «الخمسة البغداديون» يعني بهم: مربعًا، وجزرة وعبيدًا العجل، وكيلجة، وما غمّه.\nفي (م): «عن».\nمعرفة علوم الحديث ٢١٢، وتاريخ بغداد ١/ ٣٨٨.\nفي نسخة (ب) حاشية نصها: «قال المصنف: إنما قلت المشهور؛ لأن ثمّ سجادة آخر اسمه الحسين بن أحمد، وروى عنه ابن عدي الجرجاني الحافظ وغيره، والله أعلم» ونحوها في نسخة (م) و(ع).\nبضم الميم الأولى وسكون الشين المعجمة، وضم الثانية - وقيل: بفتحها أيضًا - كما تقدم."}],[1723,"- مُطَيَّنٌ (١): بِفَتْحِ الياءِ، لَقَبُ أبي جَعْفَرٍ الحَضْرَميِّ خَاطَبَهُما بِذَلِكَ أَبُو نُعَيْمٍ الفَضْلُ بنُ دُكَينٍ فَلُقِّبا بِهِما (٢)."],[1724,"- عَبْدَانُ: لَقَبٌ لجماعةٍ:"],[1725,"أَكْبَرُهُم: عَبْدُ اللهِ بنُ عُثْمَانَ المَرْوَزيُّ -صاحبُ ابنِ المباركِ- وراوَيتُهُ. رُوِّينا عَنْ مُحَمَّدِ بنِ طاهرٍ المَقْدسيِّ أنَّهُ إنما قِيلَ لَهُ: عَبْدَانُ؛ لأنَّ كُنْيَتَهُ أَبُو عَبْدِ الرَّحمانِ، واسْمَهُ عَبْدُ اللهِ، فاجتمَعَ فِي كُنْيَتِهِ واسْمِهِ العَبْدانِ (٣)، وهذا لا يَصِحُّ بَلْ ذَلِكَ من تغْيّيرِ العامّةِ للأسامي وكَسْرِهم لها فِي زمانِ صِغَرِ المُسَمَّى أَوْ نَحْوِ ذَلِكَ، كَمَا قالوا فِي عليٍّ: «عَلاَّنٌ» وَفِي أَحْمَدَ ابنِ يوسُفَ السُّلميِّ وغيرِهِ «حَمْدَانُ»، وَفِي وَهْبِ بنِ بَقِيَّةَ الواسطيِّ: «وَهْبَانُ»، واللهُ أعلمُ."],[1726,"النوع الثالث والخمسون معرفة المؤتلف والمختلف"],[1727,"مِنَ الأَسْمَاءِ والأَنْسَابِ"],[1728,"وَمَا يَلْتَحِقُ بِهَا (٤)"],[1729,"وَهُوَ مَا يأْتَلِفُ أي يتَّفِقُ (٥) فِي الخَطِّ صُورَتُهُ، وتَخْتَلِفُ فِي اللَّفْظِ صِيغتُهُ. هَذَا فَنٌّ جليلٌ، مَن لَمْ يَعْرِفْهُ مِنَ المُحدِّثينَ كَثُرَ عثَارُهُ، وَلَمْ يَعْدَمْ مُخَجِّلًا، وَهُوَ مُنْتَشَرٌ لا ضَابِطَ فِي أكْثَرِهِ يُفْزَعُ إِليهِ؛ وإنّمَا يُضْبَطُ بالحِفْظِ تَفْصيلًا. وَقَدْ صُنِّفَتْ فِيهِ كُتُبٌ (٦) مُفيدةٌ، ومِنْ أَكْمَلِها \" الإكْمالُ \" لأبي نَصْرِ بنِ ماكُوْلا عَلَى إعْوازٍ فِيهِ (١). وهذه أشياءُ مِمّا دَخَلَ مِنْهُ تَحْتَ الضَّبطِ مِمّا يَكْثُرُ ذِكْرُهُ. والضَّبْطُ فِيْهَا عَلَى قِسْمَيْنِ عَلَى العُمُومِ وعَلى الخُصُوصِ.","",{"fn":"بضم الميم وفتح الطاء المهملة وتشديد الياء المفتوحة كما تقدم.\nانظر معرفة علوم الحديث ٢١٢، والجامع ٢/ ٧٥ و٧٦ (١٢٢٥) و(١٢٢٩).\nمعجم البلدان ١/ ٤٠٥.\nانظر في ذلك: الإرشاد ٢/ ٦٩٦ - ٧٢٩، والتقريب: ١٨٠ - ١٨٥، والاقتراح: ٣١٣ - ٣١٤، والمنهل الروي: ١٢١ - ١٢٧، والموقظة: ٩٢، واختصار علوم الحديث: ٢٢٣ - ٢٢٦، والشذا الفياح ٢/ ٦١٧ - ٦٦١، والمقنع ٢/ ٥٩٢ - ٦١٣، وشرح التبصرة ٣/ ١٣٣، ونزهة النظر: ١٧٦، وطبعة عتر: ٦٨، وفتح المغيث ٣/ ٢١١ - ٢٤٤، وتدريب الراوي ٢/ ٢٩٧ - ٣١٥، وشرح السيوطي على ألفية العراقي: ٢٢٢، وفتح الباقي ٣/ ١٢٣ - ١٢٧، وتوضيح الأفكار ٢/ ٤٨٧ - ٤٨٨، وظفر الأماني: ٩٨ - ١٠٢.\nفي (ع): «تتفق».\nبعد هذا في (ع): «كثيرة» ولم ترد في شيء من النسخ ولام."}],[1730,"فمنْ القِسْمِ الأَوَّلِ:"],[1731,"- سَلاَّمٌ وسَلاَمٌ: جَمِيْعُ مَا يَرِدُ عَلَيْكَ مِنْ ذَلِكَ فَهُوَ بتَشْديدِ اللاّم إلاّ خَمْسَةً وهُم: سَلاَمٌ والدُ عبدِ اللهِ بنِ سَلاَمٍ الإسرائيليِّ الصَّحَابيِّ، وسَلاَمٌ والدُ مُحَمَّدِ بنِ سَلاَمٍ البِيكَنْديِّ (٢) البُخَارِيِّ شَيْخُ البُخَارِيِّ لَمْ يَذْكُرْ فِيهِ الخَطِيبُ (٣) وابنُ مَاكُوْلا (٤) غَيْرَ التَّخْفِيفِ. وَقَالَ: صَاحِبُ المَطالِعِ (٥): مِنْهُمْ مَنْ خَفَّفَ ومِنْهُمْ مَنْ ثَقَّلَ، وَهُوَ الأكْثَرُ."],[1732,"قُلْتُ: التَّخْفيفُ أثْبَتُ، وَهُوَ الّذي ذَكَرَهُ غُنْجارٌ فِي \" تاريخِ بُخارى \" وَهُوَ أَعْلمُ بأهلِ بِلادِهِ (٦). وسَلاَمُ بنُ مُحَمَّدِ بنِ ناهِضٍ المَقْدسيُّ، رَوَى عَنْهُ أَبُو طَالبٍ الحافِظُ والطَّبَرانيُّ. وسَمّاهُ الطَّبَرانيُّ (٧)؛ سَلامةَ. وسَلاَمٌ جَدُّ مُحَمَّدِ بنِ عَبْدِ الوَهَابِ بنِ سَلاَمٍ المُتَكَلِّمِ الجُبَّائيِّ (٨) أَبي عَلِيٍّ المُعْتَزِليِّ (٩). وَقَالَ المُبرِّدُ فِي \" كاملِهِ \": «لَيْسَ فِي العَرَبِ سَلاَمٌ مُخفَّفُ اللامِ إلاَّ والدَ عَبْدِ اللهِ بنِ سَلاَمٍ، وسَلاَمَ بنُ أبي الحُقَيقِ. قَالَ: وزادَ آخرونَ سَلاَمَ بنَ مِشْكَمٍ خَمَّارًا كَانَ فِي الجاهِليةِ، والمعروفُ فِيهِ التَّشْديدُ» (١)، واللهُ أعلمُ.","",{"fn":"قال البلقيني: «قد استدرك عليه الحافظ بن عبد الغني بن نقطة كتابًا ذيّل به على الأصل، وهو قريب منه، وفيه فوائد كثيرة، وقد صنّف في ذلك جماعة من المتأخرين». محاسن الاصطلاح: ٥٢٨. قلنا: ينظر عن المؤلفات في ذلك: بحوث في تاريخ السّنّة: ١٣٥، ومقدمة محقق المؤتلف والمختلف للدارقطني ١/ ٦٩ - ٨٢.\nنسبة إلى بيكند - بالكسر وفتح الكاف وسكون النون - بلدة بين بخارى وجيحون. انظر: الأنساب ١/ ٤٥٦، ومعجم البلدان ١/ ٥٣٣.\nتلخيص المتشابه ١/ ١٢٧.\nالإكمال ٤/ ٤٠٥.\nهو كتاب \"مطالع الأنوار على صحاح الآثار\" لابن قرقول المتوفى سنة (٥٦٩ هـ) والكتاب مازال مخطوطًا - حسب علمنا - وله عدة نسخ خطية، انظرها في الفهرس الشامل ٣/ ١٥١٩.\nانظر: محاسن الاصطلاح: ٥٢٩.\nالمعجم الصغير ١/ ١٧٤.\nبضم الجيم وتشديد الباء المفتوحة المنقوطة بواحدة من تحت. الأنساب ٢/ ٣٦.\nانظر: محاسن الاصطلاح: ٥٣٩، والتقييد: ٣٨١."}],[1733,"- عُمَارَةُ وعِمَارَةُ: لَيْسَ لَنَا عِمَارةُ بكَسرِ العَيْنِ إلاَّ أُبَيَّ بنَ عِمَارَةَ مِنَ الصَّحَابَةِ (٢)، ومِنْهُمْ مَن ضَمَّهُ ومَنْ عَدَاهُ عُمَارَةُ بالضمِّ، واللهُ أعلمُ."],[1734,"- كَرِيزٌ وكُرَيْزٌ: حَكَى أَبُو عَلِيٍّ الغَسَّانيُّ فِي كِتَابِهِ \" تَقْييدِ المُهملِ \" عَنْ محمدِ بنِ وَضَّاحٍ أنَّ كَرِيزًا بفتحِ الكافِ فِي خُزَاعَةَ، وكُرَيْزًا بِضمِّها فِي عَبْدِ شَمْسٍ بنِ عبدِ مَنَافٍ. قُلْتُ: وكُرَيْزٌ بضمِّها موجودٌ أَيْضًَا فِي غَيْرِهِما. ولا نَسْتَدْرِكُ فِي المَفْتُوحِ بأيوبَ بنِ كُرَيْزٍ الرَّاوِي عَنْ عَبْدِ الرحمانِ بنِ غَنْمٍ (٣)، لكونِ عَبْدِ الغنيِّ ذَكَرَهُ بالفَتْحِ؛ لأنَّهُ بالضمِّ، كَذلِكَ ذَكَرَهُ الدَّارَقُطْنِيُّ (٤) وغيرُهُ (٥)."],[1735,"- حِزَامٌ -بالزَّاي- فِي قُرَيشٍ، وَحَرَامٌ -بالرَّاءِ المُهْمَلَةِ- فِي الأنْصَارِ (٦)، واللهُ أعلمُ."],[1736,"ذَكَرَ أَبُو عَلِيِّ بنُ البَرَدانيِّ (٧): أنَّهُ سَمِعَ الخَطيبَ الحافِظَ يَقُولُ: العَيْشِيُّونَ: بَصْرِيُّونَ، والعَبْسِيُّونَ: كُوفِيُّونَ، والعَنْسيُّونَ: شَامِيُّونَ."],[1737,"قُلْتُ: وَقَدْ قَالَهُ قَبْلَهُ الحاكِمُ أَبُو عَبْدَ اللهِ وهذا عَلَى الغَالبِ: الأَوَّلُ بالشِّينِ المُعْجَمَةِ، والثَّانِي بالباءِ المُوَحَّدةِ، والثَّالثُ بالنّونِ والسِّينِ فيهما غيرِ مُعْجَمَةٍ (٨)."],[1738,"- أَبُو عُبَيْدَةَ: كُلُّهُ بالضَّمِّ. بَلَغَنَا عنِ الدَّارَقُطْنِيِّ (٩) أنَّهُ قَالَ: لا نَعْلَمُ أَحَدًا يُكْنَى أبا عَبَيْدَةَ بِالفَتْحِ (١٠).","",{"fn":"انظر: المحاسن: ٥٣٠.\nانظر: التقييد: ٣٨٢.\nبفتح المعجمة وسكون النون. التقريب (٣٩٧٨).\nالمؤتلف والمختلف ٤/ ١٩٥٧.\nانظر: الإكمال ٧/ ١٦٨، وثقات ابن حبان ٦/ ٥٤، والمؤتلف والمختلف لعبد الغني: ١٠٨.\nانظر: التقييد: ٣٨٤، والمحاسن: ٥٣١.\nبفتح الباء الموحدة والراء، والدال المهملة، وفي آخرها النون، هذه النسبة إلى بردان، وهي قرية من قرى بغداد. الأنساب ١/ ٣٢٦.\nفي (أ) و(م) بعد هذا: «والله أعلم».\nالمؤتلف والمختلف ٣/ ١٥٠٦.\nجاء في نسخة (م) حاشية نصها: «قول الدّارقطنيّ محمول على أنه أراد الكنية. وأما الأسماء فقد نقل ابن الطحان نحو أحد عشر رجلًا كلهم اسمه: عبيدة - بفتح العين - ونحو تسع رجال بالضم. فلينظر ما مراده، والله أعلم». ="}],[1739,"وهذهِ أَشْياءُ اجتَهَدتُ فِي ضَبْطِها مُتَتبِّعًا مَن ذَكَرَهُم الدَّارَقُطْنِيُّ، وَعَبْدُ الغَنيِّ، وابنُ مَاكُوْلاَ."],[1740,"مِنْها: السَّفْرُ - بإسكانِ الفاءِ - والسَّفَرُ بِفَتْحِهَا وَجَدْتُ الكُنى مِنْ ذَلِكَ بالفَتْحِ والبَاقي بالإسكانِ. ومِنَ المَغاربةِ مَن سَكَّنَ الفاءَ مِن أبي السَّفْرِ سعيدِ بنِ يُحْمِدَ (١)، وذَلِكَ خلافُ مَا يَقُولُهُ أَصْحَابُ الحَدِيْثِ، حَكَاهُ الدَّارَقُطْنِيُّ (٢) عَنْهُمْ."],[1741,"- عِسْلٌ بكسرِ العَين المُهْمَلَة وإسكانِ السينِ المُهْمَلَةِ، وَعَسَلٌ بفتحِهما: وجدْتُ الجميعَ مِنَ القَبِيلِ الأَوَّلِ ومِنْهُمْ: عِسْلُ بنُ سُفْيانَ، إلاّ عَسَلَ بنَ ذَكْوانَ الأخباريَّ البَصْريَّ فإنَّهُ بِالفَتْحِ، ذَكَرَهُ الدَّارَقُطْنِيُّ وغيرُهُ وَوَجدْتُهُ بِخَطِّ الإمامِ أبي مَنْصورٍ الأزْهَريِّ فِي كِتابِهِ \" تَهْذيبِ اللُّغَةِ \" بالكَسْرِ والإسْكانِ أَيْضًَا، ولا أُراهُ ضَبَطَهُ (٣)، واللهُ أعلمُ."],[1742,"- غَنَّامٌ: - بالغَيْنِ المُعْجَمَةِ والنُّونِ المُشَدَّدَةِ -، وعَثَّامٌ: - بِالعَيْنِ المُهْمَلَةِ والثّاءِ المُثَلَّثةِ المشدَّدةِ -: لا نَعْرِفُ (٤) مِنَ القَبيلِ الثَّانِي غَيْرَ عَثَّامِ بنِ عَلِيٍّ العامريِّ الكوفيِّ والدِ عليِّ بنِ عَثَّامٍ الزاهدِ والباقونَ مِنَ الأَوَّلِ مِنْهُمْ: غَنَّامُ بنُ أوسٍ صَحَابِيٌّ بَدْريٌّ، واللهُ أعلمُ."],[1743,"- قُمَيرٌ وقَمِيرٌ: الجميعُ بضمِّ القَافِ ومنهُم: مكّيُّ بنُ قُمَيْرٍ عَنْ جَعْفَرِ بنِ سُليمانَ إلاّ امْرأةَ مَسْروقِ بنِ الأَجْدَعِ: قَمِيرَ بنتَ عَمْرٍو فإنَّها بِفَتْحِ القافِ وَكسْرِ المِيمِ، واللهُ أعلمُ."],[1744,"- مِسْوَرٌ ومُسَوَّرٌ: أما مُسَوَّرٌ بضمِّ الميمِ وتَشْديدِ الواو وفَتْحِهَا (٥)، فَهُوَ مُسوَّرُ بنُ يزيدَ المالكيُّ الكاهليُّ لَهُ صُحبةٌ. وَمُسَوَّرُ بنُ عَبْدِ الملكِ اليَرْبوعيُّ رَوَى عَنْهُ مَعْنُ بنُ عِيسى ذَكَرَهُ البُخَارِيُّ. ومَنْ سِواهُما فِيْمَا نَعْلَمُ بِكَسْرِ الميمِ وإسْكانِ السينِ، واللهُ أعلمُ.","",{"fn":"في (أ): «محمّد» وهو خطأ قال في التقريب (٢٤١٣): «يحمد، بضم الياء التحتانية، وكسر الميم».\nالمؤتلف والمختلف ٣/ ١١٨٥.\nقال البلقيني في المحاسن: ٥٣٤: «كشفت على ذلك في نسختين، فلم يوجد الاسم بالكلية».\nفي الشذا (يعرف).\nفي (ع) والتقييد «وبفتحها»."}],[1745,"- الحَمَّالُ والجَمَّالُ: لا نَعْرِفُ فِي رُواةِ الحديثِ أَوْ فِيمَنْ ذُكِرَ مِنْهُمْ فِي كُتُبِ الحَدِيْثِ المُتَدَاوَلةِ؛ الحمَّالَ بالحاءِ المُهْمَلةِ صفةً لا اسمًا إلاّ هارونَ بنَ عبدِ اللهِ الحمَّالَ والدَ موسى بنِ هارونَ الحمَّالِ الحافظِ. حَكَى عَبْدُ الغنيِّ الحافظُ أنَّهُ كَانَ: بزَّازًا فلمَّا تَزَهَّدَ حَمَلَ (١). وَزَعَمَ الخليليُّ وابنُ الفَلَكيِّ أنّهُ لُقِّبَ بالحمَّالِ لِكَثْرَةِ مَا حَمَلَ مِنَ العِلْمِ (٢)، ولا أَرى مَا قالاهُ يَصِحُّ (٣). وَمَن عَداهُ فالجمَّالُ بالجيمِ مِنْهُمْ مُحَمَّدُ بنُ مِهْرَانَ الجَمَّالُ حَدَّثَ عَنْهُ البُخَارِيُّ وَمُسْلِمٌ وغيرُهما، واللهُ أعلمُ."],[1746,"وَقَدْ يُوجَدُ فِي هَذَا البَابِ مَا يُؤْمَنُ فِيهِ مِنَ الغَلَطِ ويكُونُ الّلافِظُ فِيهِ مُصيبًا كَيْفَما قَالَ، مثلُ: عيسى بنِ أبي عِيسى الحَنَّاطِ، وهوَ أيضًا: الخبَّاطُ والخيَّاطُ إلاَّ أنَّهُ اشْتَهَرَ بـ: عيسى الحنَّاطِ - بالحاءِ والنونِ -، كَانَ خَيَّاطًا للثِّيابِ. ثُمَّ تَرَكَ ذَلِكَ وصارَ حَنَّاطًا يبيعُ الحِنطَةَ. ثُمَّ ترَكَ ذَلِكَ وصَارَ خَبَّاطًا يَبيعُ الخَبَطَ (٤) الذِي تَأْكُلُهُ الإبلُ (٥) وكذلكَ مُسْلِمٌ الخَبَّاطُ - بالباءِ المَنْقُوطَةِ بِواحِدَةٍ - اجْتَمَعَ فِيهِ الأَوْصَافُ الثَّلاثةُ؛ حَكَى اجتماعَها فِي هذَيْنِ الشَّخْصَينِ الإمامُ الدَّارَقُطْنِيُّ (٦)، واللهُ أعلمُ."],[1747,"القِسْمُ الثَّانِي: ضَبْطُ مَا فِي \" الصَّحِيحَيْنِ \" أَوْ مَا فِيهِمَا مَعَ \" المُوطَّأ \" مِنْ ذَلِكَ الخُصُوصِ. فمِنْ ذَلِكَ بَشَّارٌ: بالشِّينِ المَنْقُوطَةِ والدُ بُنْدَارٍ مُحَمَّدِ بنِ بَشَّارٍ. وَسَائِرُ مَنْ في الكِتَابَينِ يَسَارٌ بالياءِ المثنّاةِ فِي أوَّلِهِ والسِّينِ المُهْمَلَةِ، ذَكَرَ ذَلِكَ أَبُو عَلِيٍّ الغَسَّانيُّ فِي كِتابِهِ، وفِيهِمَا جَميعًا سَيَّارُ بنُ سَلامَةَ، وسَيَّارُ بنُ أبِي سَيَّارٍ (٧) وَرْدَانُ، ولكن لَيْسَا عَلَى هذِهِ الصُّورَةِ وإن قَارَبا، واللهُ أعلمُ.","",{"fn":"مشتبه النسبة: ١٩.\nذكره السمعاني في الأنساب ٢/ ٢٩٧، وابن الأثير في اللباب ١/ ٣٨٤ ولم ينسباه لأحد.\nانظر: المحاسن: ٥٣٦.\nالخبط - محركة - ما تسقط من ورق الشجر بالخبط أو النّفض وهو نوع من العلف. انظر اللسان ٧/ ٢٨١، والمعجم الوسيط ١/ ٢١٦.\nينظر: الاستيعاب ٢/ ٣٦٥ - ٣٦٦.\nالمؤتلف والمختلف ٢/ ٩٣٩ - ٩٤٠.\nوقيل في اسمه غير ذلك، انظر: تهذيب الكمال ٣/ ٣٥١."}],[1748,"جَمِيْعُ مَا فِي \"الصَّحِيحَينِ\" و\"الموَطَّأ\" مِمَّا هُوَ عَلَى صُورَةِ بِشْرٍ فَهُوَ بِالشِّينِ المَنْقُوطَةِ وكَسْرِ البَاءِ (١)، إلا أَرْبَعةً فإنَّهُم بالسِّينِ المُهْمَلَةِ وضَمِّ الباءِ. وهُمْ: عَبْدُ اللهِ بنُ بُسْرٍ المازِنيُّ مِنَ الصَّحَابَةِ، وبُسْرُ بنُ سعيدٍ، وبُسْرُ بنُ عُبَيْدِ اللهِ الحَضْرميُّ، وبُسْرُ ابنُ مِحْجَنٍ الدَّيْلِيُّ. وَقَدْ قِيلَ فِي ابنِ مِحْجَنٍ بِشْرٌ بالشِّينِ المَنْقُوطَةِ حَكَاهُ أَحْمَدُ بنُ صالحٍ المِصْريُّ عَنْ جماعةٍ من وَلَدِهِ وَرَهْطِهِ (٢). وبالأوّلِ قَالَ مَالكٌ والأكثرُ، واللهُ أعلمُ."],[1749,"وَجَميعُ مَا فِيْهَا عَلَى صُورةِ بَشيرِ - بالياءِ المثنّاةِ مِنْ تحتُ قَبْلَ الرَّاءِ، فَهُوَ بالشِّينِ المَنْقوطةِ والبَاءِ الموَحَّدةِ المفْتُوحةِ - إلاَّ أربعةً. فاثْنانِ مِنْهُمْ بِضمِّ الباءِ وفَتْحِ الشَّينِ المعجمةِ وهما: بُشَيْرُ بنُ كَعْبٍ العَدَوِيُّ، وبُشَيْرُ بنُ يَسارٍ. والثالثُ يُسَيْرُ بنُ عَمْرٍو وَهُوَ بالسِّينِ المُهْمَلَةِ، وأوّلُهُ ياءٌ مُثْناةٌ من تَحْتُ مضمومةٌ، ويُقَالُ فِيهِ أَيْضًَا: أُسَيرٌ. والرابعُ قَطَنُ بنُ نُسَيْرٍ وَهُوَ بالنُّونِ المَضْمُومةِ والسِّينِ المُهْمَلَةِ، واللهُ أعلمُ."],[1750,"كُلُّ مَا فِيْهَا (٣) عَلَى صُورةِ يَزِيدَ فَهُوَ بالزَّاي واليَاءِ المُثنّاة مِن تحتُ؛ إلاّ ثلاثةً: أَحَدُها بُرَيِدُ بنُ عَبْدِ اللهِ بنِ أبي بُرْدَةَ فإنّهُ بِضمِّ الباءِ الموحَّدةِ وبالرّاءِ المُهْمَلَةِ، وَالثّاني مُحَمَّدُ بنُ عَرْعَرَةَ بنُ البِرِنْدِ فإنَّهُ بالباءِ الموَحَدةِ والراءِ المُهْمَلَةِ المكْسوْرَتَينِ وَبَعْدَها نونٌ ساكِنَةٌ. وَفِي كِتَابِ \" عُمْدةِ المُحدِّثينَ \" (٤) وغيرِهِ أنَّهُ بِفَتحِ الباءِ والراءِ والأوّلُ أَشْهَرُ، وَلَمْ يَذْكُرِ ابنُ مَاكُوْلاَ غيرَهُ. والثَّالثُ عَلِيُّ بنُ هَاشِمِ بنِ البَرِيدِ فإنَّهُ بِفَتْحِ الباءِ الموَحَّدةِ والرَّاءِ المُهْمَلَةِ المكْسورةِ والياءِ المثنّاةِ من تحتُ، واللهُ أعلمُ.","",{"fn":"انظر: التقييد ٣٩١.\nوقال ابن عبد البرِّ: إن عبد الله بن جعفر والِد عليِّ بن المديني روى حديثه عن زيد بن أسلم فقال: «بشر» بالمعجمة، وقال الطحاوي: سمعت إبراهيم البرُلسي، يقول: سمعت أحمد بن صالح بجامع مصر يقول: سمعت جماعة من ولده ومن رهطه فما اختلف اثنان أنه بشر، كما قال الثوري - يعني: بالمعجمة - وقال الحافظ ابن حبان في ثقاته ٤/ ٧٩: «ومن قال بشر فقد وهم». وقال الإمام أحمد في مسنده ٤/ ٣٣٨: حدثنا وكيع، قال: حدثنا سفيان - هو الثوري - عن زيد بن أسلم، عن بشر أو بسر، عن أبيه، فذكر حديثه فيحتمل أن يكون الشك فيه من وكيع. وقال ابن أبي حاتم في الجرح ٢/ ٤٢٣: «ويقال بشر، وبسر أصح، برفع الباء والسين». ومع أن الإمام الذهبي ذكره في الميزان ١/ ٣٠٩، والكاشف ١/ ٢٦٦ (٥٦٣) باسم بُسُر بالمهملة؛ لكنه قال في تاريخ الإسلام ٣/ ٣٤٥: «والأصح أنه بشر بالكسر وشين معجمة، وقال مالك وغيره: بالضم والإهمال». انظر: تهذيب الكمال ٤/ ٧٧ والتعليق عليه.\nانظر: التقييد: ٣٩٢.\nهو كتابٌ للحافظ عبد الغني بن عبد الواحد الجماعيلي المقدسي المتوفي سنة (٦٠٠ هـ). انظر كشف الظنون ٢/ ١١٧١."}],[1751,"كُلُّ مَا يأتي فِيْهَا مِنَ البَرَاءِ فَهُوَ بتَخْفيفِ الرّاءِ إلاَّ أبا مَعْشَرٍ البَرَّاءَ، وأبا العاليةِ البَرَّاءَ فإنَّهُما بِتَشْديد الرّاءِ. والبَرَّاءُ الَّذي يَبْرِي العُودَ (١)، واللهُ أعلمُ."],[1752,"لَيْسَ فِي \" الصَّحِيْحَينِ \" و\" المُوَطِّأ \" جَارِيةُ - بالجِيمِ - إلاّ جَارِيةَ (٢) بنَ قُدامَةَ، ويَزِيدَ بنَ جَاريةَ. ومَنْ عَداهُما فَهُوَ حَارِثَةُ بالحاء والثاءِ، واللهُ أعلمُ."],[1753,"لَيْسَ فِيْهَا حَرِيزٌ بالحاءِ فِي أوَّلِهِ والزّاي فِي آخرِهِ، إلاّ حَرِيزَ بنَ عُثْمَانَ الرَّحَبيَّ (٣) الحِمْصيَّ، وأبو حَرِيزٍ عَبْدُ اللهِ بنُ الحُسَينِ القَاضِي الرَّاوِي عَنْ عِكْرِمةَ وغَيرِهِ ومَنْ عَدَاهُما جَرِيرٌ بالجيمِ. وَرُبَّما اشتَبهَا بِحُدَيْرٍ بالدَّالِ وَهُوَ فِيْهَا والدُ عِمْرَانَ بنِ حُدَيْرٍ وَوَالِدُ زَيْدٍ وزِيَادٍ ابني حُدَيْرٍ، واللهُ أعلمُ."],[1754,"لَيْسَ فِيْهَا حِرَاشٌ بالحاءِ المُهْمَلَةِ إلاّ والدَ رِبْعيِّ بنِ حِرَاشٍ (٤) وَمَنْ بَقِيَ مِمَّن اسمُهُ عَلَى هذِهِ الصُّورةِ فَهُوَ خِرَاشٌ بالخاءِ المُعْجَمَةِ، واللهُ أعلمُ."],[1755,"لَيْسَ فِيْهَا حَصِينٌ بِفَتْحِ الحَاءِ إلاّ فِي أَبِي حَصِينٍ عُثْمَانَ بنِ عَاصِمٍ الأَسديِّ وَمَنْ عَدَاهُ حُصَيْنٌ بِضَمِّ الحاء وَجَميعُهُ بالصَّادِ المُهْمَلَةِ إلاّ حُضَيْنَ بنَ المُنْذِرِ أبا سَاسَانَ فإنَّهُ بالضَّادِ المُعْجَمَةِ (٥)، واللهُ أعلمُ."],[1756,"كُلُّ مَا فِيْهَا مِنْ حَازِمٍ، وأبي حَازِمٍ فَهُوَ بالحاءِ المُهْمَلَةِ إلاّ مُحَمَّدَ بنَ خَازِمٍ أبا مُعاوِيةَ الضَّرِيرَ (٦) فإنَّهُ بخاءٍ مُعْجَمَةٍ، واللهُ أعلمُ.","",{"fn":"انظر: اللسان ١٤/ ٧٠.\nانظر: التقييد والإيضاح ٣٩٣، وشرح التبصرة والتذكرة ٣/ ١٥٦.\nبفتح الراء والحاء المهملة بعدها موحدة. التقريب (١١٨٤).\nبعد هذا في (ج): «جد عبد الله حنظلة بن حراس».\nقال المزي في تهذيب الكمال ٦/ ٥٥٧: «ولا أعرف من يسمّى حضينًا بالضاد غيره وغير من ينسب إليه من ولده».\nانظر: محاسن الاصطلاح ٥٤١."}],[1757,"الذي فِيْهَا مِن حَبَّانَ بالحَاءِ (١) المفْتُوحَةِ والباءِ الموحَّدةِ المشدَّدةِ: حَبَّانُ بنُ مُنْقَذٍ والدُ واسِعِ بنِ حَبَّانَ، وَجَدُّ مُحَمَّدِ بنِ يَحْيَى بنِ حَبَّانَ، وَجَدُّ حَبَّانَ بنِ وَاسِعِ بنِ حَبَّانَ. وحَبَّانُ بنُ هِلاَلٍ مَنْسُوبًا وغَيْرَ مَنْسُوبٍ عَنْ شُعْبَةَ، وعَنْ وُهَيْبٍ، وعنْ هَمَّامِ بنِ يَحْيَى، وعنْ أبانَ بنِ يزيدَ، وَعَنْ سُليمانَ بنِ المُغيرةِ، وعَنْ أبي عَوَانَةَ. والذي فِيْهَا مِنْ حِبَّانَ بِكَسْرِ الحاءِ حِبَّانُ بنُ عَطِيَّةَ، وحِبَّانُ بنُ مُوسى وَهُوَ حِبَّانُ غَيْرُ منسوبٍ عَنْ عَبْدِ اللهِ؛ هُوَ ابنُ المبَارَكٍ، وابنُ العَرِقَةِ اسمُهُ أَيْضًَا: حِبَّانُ، ومن عَدَا هؤلاءِ فَهُوَ حَيَّانُ باليَاءِ المثنّاةِ مِنْ تحتُ، واللهُ أعلمُ."],[1758,"الَّذي فِي هَذِهِ الكُتُبِ مِنْ خُبَيْبٍ (٢) بالخَاءِ المُعْجَمَةِ المضْمُومَةِ خبَيْبُ بنُ عَدِيٍّ، وخُبَيْبٍ بنُ عَبْدِ الرَّحمانِ بنِ خُبَيْبِ بنِ يَسَافَ وَهُوَ خُبَيْبٌ غَيْرُ مَنْسوبٍ عَنْ حَفْصِ بنِ عاصمٍ وعَنْ عَبْدِ اللهِ بنِ مُحَمَّدِ بنِ مَعْنٍ (٣)، وأبو خُبَيْبٍ عَبْدُ اللهِ بنُ الزُّبَيْرِ، وَمَن عدَاهُم فبالحاءِ المُهْمَلَةِ، واللهُ أعلمُ."],[1759,"لَيْسَ فِيْهَا حُكَيْمٌ بالضَّمِّ إلاّ حُكَيْمُ بنُ عَبْدِ اللهِ، ورُزَيْقٌ (٤) بنُ حُكَيْمٍ، واللهُ أعلمُ."],[1760,"كُلُّ مَا فِيْهَا مِنْ رَبَاحٍ فَهُوَ بالباءِ الموَحَّدةِ إلاّ زيادَ بنَ رياحٍ (٥) وَهُوَ أَبُو قَيْسٍ، الرَّاوِي عَنْ أبِي هُرَيْرَةَ فِي أشْراطِ السّاعةِ (٦) ومُفَارَقَةِ (٧) الجَماعةِ فإنَّهُ بالياءِ المثنّاةِ من تحتُ (٨) عِنْدَ الأَكْثَرِيْنَ (٩). وَقَدْ حَكَى البُخَارِيُّ فِيهِ الوَجْهَيْنِ بالباءِ والياءِ (١٠)، واللهُ أعلمُ.","",{"fn":"في (ب): «بالحاء المهملة المفتوحة».\nعبارة: «من خبيب» سقطت من (م).\nفي (م): «معين».\nرزيق -بالتصغير-، ابن حكيم، كذلك، ويقال فيه: بتقديم الزاي، وفي أبيه بالتكبير. التقريب (١٩٣٥).\nراجع التقييد ٣٩٤.\nصحيح مسلم ٨/ ٢٠٢ (٢٩٤٧).\nصحيح مسلم ٦/ ٢١ (١٨٤٨).\nفي (ع): «تحث» بالثاء.\nانظر: المحاسن ٥٤٤.\nالذي ذكره البخاريّ في تاريخه الكبير ٣/ ٣٥١ (١١٩٠) بالباء الموحدة فقط، لكن نقل الإمام النّوويّ في شرح صحيح مسلم ٤/ ٥١٥ فقال: وقاله البخاريّ: بالمثناة والموحدة، وقاله الجماهير: بالمثناة لا غير»."}],[1761,"زُبَيْدٌ وزُيَيْدٌ (١): لَيْسَ فِي \" الصَّحِيحَينِ \" إلاّ زُبيدٌ بالبَاءِ الموحَّدَةِ وَهُوَ زُبَيدُ بنُ الحارثِ الياميُّ. وليسَ فِي \" المُوطَّأ \" مِن ذَلِكَ إلا زُيَيْدٌ بياءيْنِ مثَنَّاتَيْنِ مِن تحتُ وَهُوَ زُيَيْدُ بنُ الصَّلْتِ (٢) يُكْسَرُ (٣) أَوَّلُهُ ويُضمُّ، واللهُ أعلمُ."],[1762,"فِيْهَا: سَلِيمٌ بفَتْحِ السِّينِ واحدٌ وَهُوَ سَليمُ بنُ حَيّانَ ومَنْ عَداهُ فِيْهَا فَهُوَ سُلَيمٌ بالضَّمِّ، واللهُ أعلمُ."],[1763,"وَفِيْهَا سَلْمُ بنُ زَرِيرٍ (٤)، وسَلْمُ بنُ قُتَيْبَةَ، وَسَلْمُ بنُ أَبِي الذَّيَّالِ (٥)، وسَلْمُ بنُ"],[1764,"عَبْدِ الرَّحمانِ، هَؤُلاَءِ الأَرْبَعةُ بإسكانِ الّلامِ. ومَنْ عَداهُم سالمٌ بالأَلِفِ، واللهُ أعلمُ."],[1765,"وَفِيْهَا سُرَيْجُ بنُ يونُسَ، وسُرَيْجُ بنُ النُّعمانِ، وأحمدُ بنُ أَبِي سُرَيجٍ، هَؤُلاَء الثلاثةُ بالجيمِ والسِّينِ المُهْمَلَةِ، ومَنْ عَداهُم فِيْهَا فَهُوَ بالشِّينِ المنْقُوطَةِ والحاءِ المُهْمَلَةِ واللهُ أعلمُ."],[1766,"وَفِيْهَا سَلْمانُ (٦) الفارِسيُّ، وسَلْمانُ بنُ عامرٍ، وسَلْمانُ الأغرُّ، وعبدُ (٧) الرحمانِ ابنُ سَلْمانَ، ومَنْ عَدا هَؤُلاَءِ الأربعةِ سُلَيْمانُ بالياءِ (٨). وأبو حَازِمٍ (٩) الأشجعيُّ - الرَّاوِي عَنْ أَبِي هُرَيْرَةَ -، وأبو رَجَاءٍ مَوْلَى (١٠) أَبِي قِلاَبةَ كُلُّ واحدٍ مِنْهُمَا اسمُهُ سَلمانُ بغيرِ ياءٍ لكنْ ذُكِرَا بالكُنْيةِ، واللهُ أعلمُ.","",{"fn":"في (ع) والتقييد: «زبيد».\nوحديثه في الموطأ (١٢٢) رواية الليثي.\nفي (م) والشذا والتقييد «بكسر».\nبفتح الزاي وراءين. التقريب (٢٤٦٦).\nانظر: التقييد ٣٩٦.\nقال العراقي في شرح التبصرة ٣/ ١٧١: «وذكر ابن الصّلاح هنا: سلمان وسليمان ولا يشتبهان لزيادة ياء التصغير في الثّاني فلهذا أسقطته».\nفي (ب): «عبيد».\nيستدرك أيضًا: «سلمان بن ربيعة الباهلي» فقد أخرج له مسلم في صحيحه ٣/ ١٠٣ (١٠٥٦) نبه على ذلك العراقي في التقييد ٣٩٧.\nهو سلمان، أبو حازم الأشجعي، الكوفيّ: ثقة، مات على رأس المئة (التقريب ٢٤٧٩).\nهو سلمان، أبو رجاء، مولى أبي قلابة الجرمي، البصري: صدوق (التقريب ٢٤٨٠)."}],[1767,"فِيْهَا سَلِمةُ بكسرِ الّلام عَمْرُو بنُ سَلِمَةَ الجَرْمِيُّ إمامُ قَوْمِهِ، وَبَنُو سَلِمةَ القبيلةُ مِنَ الأَنْصَارِ والباقي سَلَمةُ بفتحِ الّلامِ غَيْرَ أنَّ عَبْدَ الخَالِقِ بنَ سَلِمَةَ فِي \" كِتابِ مُسْلِمٍ \" ذُكِرَ فِيهِ الفَتْحُ (١) والكسرُ (٢)، واللهُ أعلمُ."],[1768,"وَفِيْهَا سِنَانُ بنُ أَبِي سِنَانٍ الدُؤَليُّ (٣)، وسِنَانُ بنُ سَلَمةَ، وسِنَانُ بنُ رَبَيعَةَ أَبُو رَبِيعةَ، وأحمدُ بنُ سِنَانٍ، وأُمُّ سِنَانٍ، وأبو سِنَانٍ ضِرَارُ بنُ مُرَّةَ الشَّيبَانيُّ وَمَنْ عَدَا هَؤُلاَءِ السِّتَّةِ شَيْبَانُ بالشِّينِ المنْقوطَةِ واليَاءِ، واللهُ أعلمُ."],[1769,"عَبِيدةُ بِفَتْحِ العَيْنِ لَيْسَ فِي الكُتُبِ الثَّلاثَةِ إلاّ عَبِيدةَ السَّلْمانيَّ (٤)، وعَبِيدةَ بنَ حُمَيْدٍ، وعَبِيدةَ بنَ سُفْيَانَ، وعامرَ بنَ عبِيدةَ الباهليَّ. وَمَن عَدَا هَؤُلاَءِ الأربعةِ فعُبَيْدةُ بالضَّمِّ، واللهُ أعلمُ."],[1770,"عُبَيْدٌ بغيرِ هاءِ التَّأنيثِ هُوَ بالضمِّ حَيْثُ (٥) وَقَعَ فِيْهَا. وكَذلِكَ عُبَادةُ بالضَّمِّ حَيْثُ وَقَعَ إلاّ مُحَمَّدَ بنَ عَبَادَةَ الواسطيَّ (٦) منْ شُيوخِ البُخَارِيِّ فإنَّهُ بِفَتْحِ العَينِ وتَخْفِيفِ البَاءِ، واللهُ أعلمُ."],[1771,"عَبْدَةُ هُوَ بإسكانِ الباءِ حيثُ وَقَعَ فِي هذِهِ الكُتُبِ إلاّ عامِرَ بنَ عَبَدَةَ فِي خُطْبةِ"],[1772,"\" كِتَابِ مُسْلِمٍ \" (٧)، وإلاّ بَجَالةَ بنَ عَبَدَةَ (٨)، عَلَى أنَّ فِيْهِمَا خَلافًا، مِنْهُمْ مَنْ سَكَّنَ الباءَ مِنْهُمَا أَيْضًَا. وَعِندَ بَعْضِ رُواةِ مُسْلِمٍ عامرُ بنُ عَبْدٍ، بَلا هَاءٍ، ولا يَصِحُّ (٩)،"],[1773,"واللهُ أعلمُ.","",{"fn":"انظر: محاسن الاصطلاح: ٥٤٩.\nحكى فيه الوجهين ابن ماكولا في الإكمال ٤/ ٣٣٦، وانظر: التقريب (٣٧٧٨).\nانظر: التقييد ٣٩٨.\nبسكون اللام، ويقال بفتحها. التقريب (٤٤١٢).\nفي (ج): «حيثما».\nهو محمّد بن عبادة البختري الأسدي: ثقة صدوق. انظر: الإكمال ٦/ ٢٧، وتهذيب الكمال٦/ ٣٦٣ (٥٩١٦)\nصحيح مسلم ١/ ٩ عقيب (٧).\nانظر: الإكمال ٦/ ٢٩ فقد قيّده بالفتح.\nقال العراقي في شرح التبصرة ٣/ ١٧٥ نقلًا عن القاضي عياض: «هو وهم»."}],[1774,"عَبَّادٌ هُوَ فِيْهَا بفَتْحِ العَينِ وتَشْدِيدِ الباءِ إلاَّ قَيْسَ بنَ عُبَادٍ فإنَّهُ بِضَمِّ العَينِ وتخْفيفِ الباءِ، واللهُ أعلمُ."],[1775,"لَيْسَ فِيْهَا عُقَيْلٌ بضَمِّ العَيْنِ إلاّ عُقَيْلَ بنَ خالدٍ، وَيَحْيَى بنَ عُقَيلٍ، وَبنُو عُقَيلٍ للقَبِيلةِ (١). ومَنْ عَدا هَؤُلاَءِ عَقِيلٌ بِفَتحِ العَينِ، واللهُ أعلمُ."],[1776,"وليسَ فِيْهَا وَافِدٌ بالفاءِ أَصْلًا وجميعُ مَا فِيْهَا وَاقِدٌ بالقَافِ، واللهُ أعلمُ."],[1777,"ومِنَ الأَنْسَابِ ذَكَرَ (٢) القاضِي الحافظُ عِياضٌ أنّهُ لَيْسَ فِي هذِهِ الكتبِ الأُبُلِيُّ بالباءِ الموَحّدةِ أي المضمومةِ، وَجميعُ مَا فِيْهَا عَلَى هذِهِ الصُّورةِ فإنّما هُوَ الأيْلِيُّ (٣) بالياءِ المَنْقُوْطَةِ باثْنتَينِ من تَحْتُ."],[1778,"قُلْتُ: رَوَى مُسْلِمٌ الكَثيرَ عَنْ شَيْبَانَ بنِ فَرُّوخٍ وَهُوَ أُبُليٌّ (٤) بالباءِ الموحّدةِ، لَكِنْ إذَا لَمْ يَكُنْ فِي شيءٍ منْ ذَلِكَ منسوبًا لَمْ يلحقْ عياضًا مِنْهُ تخطِئةٌ، واللهُ أعلمُ (٥)."],[1779,"لا نَعْلَمُ فِي \" الصَّحِيْحَيْنِ \" البَزَّارَ بالرّاءِ المُهْمَلَةِ فِي آخرِهِ إلاّ خَلَفَ بنَ هِشَامٍ البَزَّارَ، والحسَنَ بنَ الصَّبَّاحِ البَزَّارَ (٦)، وأمّا مُحَمَّدُ بنُ الصَّبَّاحِ البَزَّازُ وغيرُهُ فِيهما فَهُوَ بِزَايَيْنِ، واللهُ أعلمُ."],[1780,"وَلَيْسَ فِي \" الصَّحِيْحَيْنِ \" و\" المُوَطَّأِ \" النَّصْرِيُّ بالنُّونِ والصَّادِ المُهْمَلَةِ إلاّ ثلاثةً: مالكُ بنُ أَوْسِ بنُ الحَدَثَانِ النَّصْريُّ، وَعَبدُ الواحِدِ بنُ عَبْدِ اللهِ النَّصْرِيُّ، وسَالمٌ مَوْلَى النَّصْرِيِّيْنَ، وسَائِرُ مَا فِيْهَا عَلَى هذِهِ الصُّورَةِ فَهُوَ بَصْرِيٌّ بالباءِ الموحَّدَةِ، واللهُ أعلمُ.","",{"fn":"في (ج): «القبيلة».\nانظر: التقييد ٤٠٠.\nالأيلي: نسبة إلى أيلة، وهذه بلدة على ساحل بحر القلزم (الأحمر حاليا) مما يلي ديار مصر خرج منها جماعة من العلماء الفضلاء. انظر: مراصد الاطلاع ١/ ١٣٨، والأنساب ١/ ٢٤٦.\nهو شيبان بن فروخ بن أبي شيبة الحبطي الأبلي - بضم الهمزة والموحدة وتشديد اللام، توفّي سنة (٢٣٥ أو ٢٣٦ هـ). تقريب التهذيب (٢٨٣٤).\nانظر: محاسن الاصطلاح ٥٤٨.\nاستدرك على المصنف ابن الملقن في المقنع ٢/ ٦٠٩ قال: «قلت: وإلا يحيى بن محمّد بن السكن بن حبيب وبشر بن ثابت فبالراء أيضًا». وانظر: شرح التبصرة والتذكرة ٣/ ١٧٩، والتقييد والإيضاح: ٤٠١."}],[1781,"لَيْسَ فِيْهَا التَّوَّزيُّ بفَتْحِ التَّاءِ والمُثَنّاةِ مِنْ فَوْقُ والواوِ المُشَدَّدَةِ المفتوحةِ والزّاي إلاَّ أَبُو يَعْلَى التَّوَّزيُّ مُحَمَّدُ بنُ الصَّلْتِ فِي كِتَابِ البُخَارِيِّ فِي بَابِ الرِّدَّةِ (١). وَمنْ عَداهُ فَهُوَ الثَّوْرِيُّ بالثَّاءِ المثلَّثَةِ، ومِنْهُم: أبو يَعْلَى مُنْذِرُ بنُ يَعْلَى الثَّوْرِيُّ خَرَّجَا عَنْهُ، واللهُ أعلمُ."],[1782,"سَعِيدُ الجُرَيْريُّ (٢)، وعَبَّاسُ الجُرَيرِيُّ، والجُرَيرِيُّ غَيْرُ مُسَمًّى عَنْ أَبِي نَضْرَةَ، هَذَا مَا فِيْهَا بالجيمِ المَضْمُوْمَةِ. وَفِيْهَا الحَرِيريُّ بالحاءِ المُهْمَلَةِ يَحْيَى بنُ بِشْرٍ شَيْخُ البُخَارِيِّ وَمُسْلِمٍ، واللهُ أعلمُ."],[1783,"[وَفِيْهَا الجَرِيرِيُّ بِفَتحِ الجِيمِ يَحْيَى بنُ أَيُّوبَ الجَرَيرِيُّ فِي كِتَابِ البُخَارِيِّ مِنْ وُلِدَ جَرِيرِ بنِ عبدِ اللهِ، واللهُ أعلمُ] (٣)."],[1784,"الجَارِيُّ (٤) فِيْهَا بالجِيمِ شَخْصٌ واحدٌ وَهُوَ سَعْدٌ مَنْسوبٌ إلى الجارِ؛ مَرْفأُ (٥) السُّفُنِ بِسَاحِلِ المدينةِ (٦) وَمَنْ عَداهُ الحارِثيُّ بالحاءِ والثاءِ، واللهُ أعلمُ."],[1785,"الحِزَامِيُّ حَيْثُ وَقَعَ فِيْهَا فَهُوَ بالزَّايِ غَيْرِ المُهْمَلَةِ (٧)، واللهُ أعلمُ."],[1786,"السَّلَميُّ: إذَا جَاءَ فِي الأَنْصارِ فَهُوَ بِفَتْحِ السِّينِ نِسْبةً إلى بَنِي سَلِمةَ مِنْهُمْ. وَمنهُم جَابرُ بنُ عَبْدِ اللهِ وأبو قَتادةَ. ثُمَّ إنَّ أَهْلَ العَرَبيَّةِ يَفْتَحونَ اللامَ مِنْهُ فِي النَّسَبِ كَمَا فِي النَّمَريِّ والصَّدَفيِّ وبابِهما. وأكثرُ أَهْل الحَدِيْثِ (١) يقُولُونهُ بكسْرِ اللامِ عَلَى الأَصْلِ وَهُوَ لَحْنٌ (٢)، واللهُ أعلمُ.","",{"fn":"صحيح البخاريّ ٨/ ٢٠٢ (٦٨٠٣).\nانظر: التقييد ٤٠١، والمحاسن ٥٤٩.\nما بين المعكوفتين لم يرد في النسخ، وهو من الشذا و(م) والتقييد.\nالجاري بفتح الجيم والراء المهملة، هذه النسبة إلى الجار، وهي بليدة على الساحل قرب مدينة رسول الله. الأنساب ٢/ ٢٨.\nالمرفأ: بفتح الميم -ويضم- وإسكان الراء وفتح الفاء مهموز مقصور، قال الجوهري: أرفأت السفينة: قرّبتها من الشطّ. قال: وذلك الموضع مرفأٌ. انظر الصحاح ١/ ٥٣، وتاج العروس ١/ ٢٤٧، وشرح التبصرة ٣/ ١٨٦.\nفي (م) والشذا زيادة (بجدّة).\nانظر: محاسن الاصطلاح: ٥٥، وشرح التبصرة والتذكرة ٣/ ١٨٥."}],[1787,"لَيْسَ فِي \" الصَّحِيْحَيْنِ \" و\" المُوَطَّأِ \" الهَمَدَانيُّ بالذالِ المَنْقُوْطَةِ (٣). وجميعُ مَا فِيْهَا عَلَى هذِهِ الصُّورةِ فَهُوَ الهَمْدَانيُّ بالدالِ المُهْمَلَةِ وسُكونِ الميمِ وَقَدْ قَالَ أَبُو نَصْرِ ابنُ مَاكُوْلاَ: «الهَمدانيُّ فِي المُتَقدِّمينَ بسِكُونِ المِيمِ أكثرُ وبِفَتْحِ الميمِ فِي المتأخّرِينَ أكثرُ» (٤) وَهُوَ كَمَا قَالَ، واللهُ أعلمُ."],[1788,"هذِهِ جملةٌ لَوْ رَحَلَ الطَّالِبُ فِيْهَا لَكَانَتْ رِحْلةً رابحةً إنْ شَاءَ اللهُ تَعَالَى. ويحقُّ عَلَى الحَدِيثيِّ إيداعُها فِي سُويْدَاءِ قلْبِهِ. وَفِي بَعْضها مِنْ خَوْفِ الانتقاضِ مَا تَقَدَّمَ فِي الأَسْماءِ المُفْرَدةِ وأَنا فِي بَعْضِها مُقلِّدٌ كِتَابَ القاضِي عياضٍ (٥) ومُعْتَصِمٌ باللهِ فِيهِ وَفِي جَمِيْعِ أمرِي، وَهُوَ سُبْحَانَهُ أعلمُ."],[1789,"النوع الرابع والخمسون معرفة المتفق والمفترق"],[1790,"(٦) مِنَ الأسْمَاءِ والأَنْسابِ وَنَحوِها هَذَا النَّوعُ مُتَّفِقٌ لَفْظًا وَخَطًّا بِخِلافِ النَّوعِ الذي قَبْلَهُ، فإنَّ فِيهِ الاتِّفاقَ فِي صُورَةِ الخطِّ مَعَ الافْتِراقِ فِي اللَّفْظِ. وهذا مِن قَبِيلِ مَا يُسَمَّى فِي أُصُولِ الفِقْهِ: المُشْتَركُ. وزَلَقَ بِسَبَبِهِ غَيْرُ واحِدٍ مِنَ الأكابرِ وَلَمْ يَزَلِ الاشْتراكُ مِنْ مَظانِّ الغَلَطِ فِي كُلِّ علمٍ. ولِلخَطِيبِ فِيهِ كتابُ \" المتَّفِقِ والمُفْتَرِقِ \" وَهُوَ مَعَ أنّهُ (١) كتابٌ حَفِيلٌ غَيْرُ مُستوفٍ لِلأقْسامِ التي أذكرُها إنْ شاءَ اللهُ تَعَالَى.","",{"fn":"الإكمال ٧/ ٤٩١، وقال السمعاني في الأنساب ٣/ ٣٠٣: «هذه النسبة بفتح السين المهملة وفتح اللام إلى بني سلمة ... وهذه النسبة عند النحويين، وأصحاب الحديث يكسرون اللام على غير قياس النحويين». وبنحوه في اللباب ٢/ ١٢٩.\nولكن ذكر النوويّ في الإرشاد ٢/ ٧٢٨ أنها لغة قليلة، ونصه في التقريب ١٨٥: «إنه يجوز في لُغَية» وفي الأنساب ٣/ ٣٠٣: «وهذه النسبة وردت على خلاف القياس كما في سفرة سفري، وكما في نمرة نمري، وهذه النسبة عند النحويين، وأصحاب الحديث يكسرون اللام على غير قياس النحويين» انظر: شرح المفصل ٥/ ١٤٥، وأوضح المسالك: ٢٩٢، والمقرب: ٤١٣.\nانظر: المحاسن ٥٥١.\nالإكمال ٧/ ٤١٩.\nيعني به مشارق الأنوار على صحاح الآثار، وهو مطبوع متداول.\nانظر في ذلك: الإرشاد ٢/ ٧٣٠ - ٧٤٣، والتقريب: ١٨٥ - ١٨٨، والاقتراح: ٣١٤ - ٣١٥، والمنهل الروي ١٢٧ - ١٢٩، واختصار علوم الحديث: ٢٢٧ - ٢٢٩، والشذا الفياح ٢/ ٦٦٢ - ٦٨٢، والمقنع ٢/ ٦١٤ - ٦٢١، وشرح التبصرة ٣/ ١٩٠، ونزهة النظر: ١٧٥ - ١٧٦، وطبعة عتر: ٦٨، وفتح المغيث ٣/ ٢٤٥ - ٢٥٨، وتدريب الراوي ٢/ ٣١٦ - ٣٢٩، وفتح الباقي ٣/ ٢٠٠، وتوضيح الأفكار ٢/ ٤٨٨ - ٤٩٣، وظفر الأماني: ٨٩ - ٩٨."}],[1791,"فأحدُها: المُفْتَرِقُ مِمَّنْ اتَّفَقَتْ أَسْماؤُهم وأَسْماءُ آبائِهِم."],[1792,"مثالُهُ: الخَليلُ بنُ أَحْمَدَ (٢): سِتَّةٌ، وفاتَ الخطيبَ مِنْهُمْ الأربعةُ الأخيرةُ. فأوّلُهم: النَّحْوِيُّ البَصْرِيُّ - صاحبُ العَرُوضِ - حَدَّثَ عَنْ عاصمٍ الأَحْولِ وغيرِهِ. قَالَ أَبُو العَبَّاسِ المُبَرِّدُ: «فَتِّشَ المُفتِشُونَ فَما وَجَدُوا (٣) بعدَ نَبيِّنا - صلى الله عليه وآله وسلم - مَنْ اسمُهُ أَحْمَدُ، قَبْلَ أبي الخَليلِ بنِ أَحْمَدَ». وَذكرَ التَارِيخيُّ (٤) أَبُو بكرٍ أنّهُ لَمْ يَزلْ يَسْمعُ النَّسَّابِينَ والأخْبَارِيِّيْنَ يقولونَ: إنَّهُم لَمْ يَعْرِفوا غَيرَهُ. واعتُرِضَ عَلَيْهِ بأبي السَّفَرِ سعيدِ بنِ أَحْمَدَ احتجاجًا بقولِ يَحْيَى بنِ مَعِينٍ فِي اسمِ أبيهِ فإنّهُ أَقْدمُ. وأجابَ بأنَّ أكثرَ أَهْلِ العلمِ إنَّما قَالوا فِيهِ سَعيدُ بنُ يُحْمِدَ (٥)، واللهُ أعلمُ."],[1793,"والثاني: أَبُو بِشْرٍ المُزَنيُّ بَصْرِيٌّ أَيْضًَا حَدَّثَ عَنِ المُسْتَنِيرِ بنِ أخْضَرَ عَنْ مُعَاويةَ بنِ قُرَّةَ. رَوَى عَنْهُ العَبَّاسُ العَنْبَرِيُّ وجَمَاعةٌ."],[1794,"والثالثُ (٦): أصبهانيٌّ رَوَى عَنْ رَوْحِ بنِ عُبَادةَ وغيرِهِ.","",{"fn":"في (ب): «مع كونه».\nانظر: التقييد: ٤٠٦.\nفي (ع) والتقييد والشذا و(ج) و(م): «وجد».\nبفتح التاء وكسر الراء، هذه النسبة إلى التاريخ. انظر الأنساب ١/ ٤٦٥.\nقال ابن الملقن في المقنع ٢/ ٦١٥: «يعترض بـ أحمد بن حفص بن المغيرة الصحابي عَلَى أحد الأقوال في اسمه، وأما أحمد بن عجيان الصّحابيّ فهو بالجيم، ومن ادعى أنه بالحاء فقد صحفه». وانظر: محاسن الاصطلاح ٥٥٣، والإصابة ١/ ٢٢ و٤/ ١٣٩.\nقال العراقي في شرح التبصرة ٣/ ١٩٤: «وقد أسقطت من الستة الذين ذكرهم ابن الصّلاح واحدًا، وهو الخليل بن أحمد، أصبهانيٌّ يروي عن روح بن عبادة؛ لأنَّهُ وهم فِيْهِ، وإنما هُوَ الخليل بن محمّد، ووهم فِيْهِ قبله ابن الجوزي، وأبو الفضل الهروي، فإنه عده فيمن اسمه الخليل ابن أَحْمَد، وَهُوَ في تاريخ أصبهان لأبي نُعَيْم عَلَى الصّواب: الخليل بن محمّد أبو العباس العجلي»، وانظر: تاريخ أصبهان ١/ ٣٠٧ - ٣٠٨."}],[1795,"والرابعُ: أَبُو سَعيدٍ السِّجْزِيُّ الْقَاضِي الفقيهُ الحَنَفيُّ المشهورُ بِخُراسانَ حَدَّثَ عَنِ ابنِ خُزَيمةَ، وابنِ صاعِدٍ (١)، والبَغَويِّ، وَغَيرهِم مِنَ الحُفَّاظِ المُسْنِدينَ."],[1796,"والخامسُ: أَبُو سَعيدٍ البُسْتِيُّ القَاضِي المُهَلَّبيُّ فاضِلٌ رَوَى عَنِ الخليلِ السِّجْزيِّ المذكورِ وحَدَّثَ عنْ أَحْمَدَ بنِ المُظَفَّرِ البَكْرِيِّ عَنِ ابنِ أبي خَيثمةَ بـ \" تاريخهِ \" وعَنْ غَيرِهما، حَدَّثَ عَنْهُ البَيْهَقِيُّ الحافظُ."],[1797,"والسادسُ: أَبُو سعيدٍ البُسْتيُّ أَيْضًَا الشَّافِعيُّ فاضلٌ مُتَصِّرفٌ فِي عُلومٍ. دَخَلَ الأندلسَ، وَحَدَّثَ، وُلِدَ سنةَ ستِّينَ وثلاثِ مئةٍ. رَوَى عَنْ أبِي حامدٍ الإسفرايينيِّ وغيرِهِ. وَحَدَّثَ عَنْهُ أَبُو العَبَّاسِ العُذريُّ وغيرُهُ، واللهُ أعلمُ."],[1798,"القِسمُ الثَّانِي: المُفْتَرِقُ مِمَّنْ اتَّفَقتْ أسماؤهم وأَسماءُ آبائِهم وأجدادِهم أَو أكثرُ مِنْ ذَلِكَ."],[1799,"ومِنْ أمثلتِهِ: أَحْمَدُ بنُ جَعْفَرِ بنِ حَمْدَانَ أَرْبَعَةٌ كُلُّهم فِي عَصْرٍ واحدٍ."],[1800,"أحَدُهُمُ: القَطِيعيُّ (٢) البغداديُّ أَبُو بَكْرٍ الرَّاوِي عَنْ عَبْدِ اللهِ بنِ أَحْمَدَ بنِ حَنْبَلٍ."],[1801,"الثَّانِي: السَّقَطيُّ (٣) البَصْريُّ أَبُو بَكْرٍ يَرْوِي أَيْضًَا عَنْ عَبْدِ اللهِ بنِ أَحْمَدَ ولكنّهُ (٤) عَبْدُ اللهِ ابنُ أَحْمَدَ بنِ إِبْرَاهِيمُ الدَّوْرَقيُّ. الثَّالِثُ: دِيْنَوَرِيٌّ رَوَى عَنْ عَبْدِ اللهِ بنِ مُحَمَّدِ بنِ سِنَانٍ عَنْ مُحَمَّدِ بنِ كَثِيْرٍ صاحبِ سُفيانَ الثوريِّ. والرابعُ: طَرَسُوسيٌّ رَوَى عَنْ عَبْدِ اللهِ بنِ جابرٍ الطَّرَسُوسيِّ \" تأريخَ مُحَمَّدِ بنِ عِيسى الطَّبَّاعِ \"."],[1802,"مُحَمَّدُ بنُ يعقوبَ بنِ يوسفَ النَّيْسَابُوْرِيُّ اثْنَانِ كِلاهما فِي عَصْرٍ واحدٍ وكلاهما يَرْوِي عَنْهُ الحَاكِمُ أَبُو عَبْدِ اللهِ وغيرُهُ. فأحدُهما: هُوَ المعروفُ بأبي العَبَّاسِ الأصَمِّ. والثاني: هُوَ أَبُو عَبْدِ اللهِ بنُ الأَخْرَمِ الشَّيْبانيُّ ويُعْرَفُ بالحافظِ دُوْنَ الأَوَّلِ، واللهُ أعلمُ.","",{"fn":"هو يحيى بن محمّد بن صاعد، أبو محمّد مولى أبي جعفر المنصور، كان أحد حفّاظ الحديث، وهو عالم بالعلل والرجال توفّي سنة (٣١٨ هـ). انظر: تاريخ بغداد ١٤/ ٢٣١، والسير ١٤/ ٥٠١.\nبفتح القاف وكسر الطاء المهملة وسكون الياء. انظر: الأنساب ٤/ ٥٠٧.\nبفتح السين المهملة وفتح القاف وكسر الطاء المهملة. انظر: الأنساب ٣/ ٢٨٦.\nفي (م): «ولكن»."}],[1803,"القِسْمُ الثَّالِثُ: مَا اتَّفَقَ مِنْ ذَلِكَ فِي الكُنيةِ والنِّسْبَةِ معًا."],[1804,"مثالُهُ: أَبُو عِمْرَانَ الجَوْنِيُّ اثنانِ؛ أحدُهما: التَّابِعيُّ عَبْدُ الملكِ بنُ حَبِيبٍ. والثاني: اسمُهُ موسى بنُ سَهْلٍ بَصْريٌّ سَكَنَ بغدادَ رَوَى عَنْ هِشَامِ بنِ عَمَّارٍ وغيرِهِ رَوَى عَنْهُ"],[1805,"دَعْلَجُ بنُ أَحْمَدَ وغيرُهُ."],[1806,"وَمِمّا يُقارِبهُ (١) أَبُو بَكْرِ بنُ عَيَّاشٍ ثلاثةٌ: أَوَّلُهم: القارِئُ المحدِّثُ وَقَدْ سَبَقَ ذِكْرُ الخِلافِ فِي اسمِهِ. والثاني: أَبُو بَكْرِ بنُ عَيَّاشٍ الحِمْصيُّ الَّذِي حَدَّثَ عَنْهُ جَعْفَرُ بنُ"],[1807,"عَبْدِ الواحدِ الهاشميُّ وَهُوَ مجهولٌ، وجعفرٌ غَيْرُ ثِقَةٍ (٢). والثالثُ: أَبُو بكرِ بنُ عَيَّاشٍ السُّلَمِيُّ البَاجُدَّائيُّ (٣) صاحبُ كِتَابِ \" غَرِيبِ الحَدِيْثِ \" (٤) واسمُهُ حُسَيْنُ بنُ عيّاشٍ ماتَ سنة أربعٍ ومئتينِ بِباجُدَّا رَوَى عَنْهُ عَلِيُّ ابنُ جَميلٍ الرَّقِّيُّ وغيرُهُ (٥)، واللهُ أعلمُ."],[1808,"القِسْمُ الرابعُ: عَكْسُ هَذَا (٦).","",{"fn":"انظر: المحاسن: ٥٥٦.\nالمتفق والمفترق ل ١٧٨ / ب.\nقال صاحب الأنساب ١/ ٢٥٥: «بفتح الباء الموحدة والجيم وبينهما الألف والدال المشددة المهملة، هذه النسبة إلى باجدا، وهي قرية من نواحي بغداد» ومثله في معجم البلدان ١/ ٣١٣، واللباب ١/ ١٠٢ ومراصد الاطلاع ١/ ١٤٧. وقال في التقريب (١٣٣٩) بموحدة وجيم مضمومة ودال ثقيلة وبعد الألف همزة» وكذا في الخلاصة ٨٤، ومثل هذا الضّبط في النسخ الخطية و(ع) والشذا وتهذيب الكمال ولكنه ضبط قلم، والمثبت منها. وانظر: التعليق على تهذيب الكمال ٢/ ١٩٨، والباعث الحثيث ٢/ ٦٣٠.\nذكره الخطيب في كتابه المتفق والمفترق ١٧٨/ب، والمزي في تهذيب الكمال ٢/ ١٩٨، وابن حجر في تهذيب التهذيب ٢/ ٣٦٢، والذهبي في الكاشف ١/ ٣٣٤، وصاحب معجم المؤلفين ٤/ ٤٠ وغيرهم ولابد من الإشارة إلى أنّ هذا المؤلّف وكتابه لم يذكرهم ابن الأثير في مقدمة نهايته مع أنه ذكر أوائل من صنف في هذا الفن، وكذلك لم يذكرهما محققا النهاية مع أنه من المتقدمين.\nترجمته في تهذيب الكمال ٢/ ١٩٨ (١٣١١)، والميزان ٤/ ٥٠٣ (١٠٠١٧).\nانظر: المحاسن: ٥٥٦، والتقييد: ٤٠٩."}],[1809,"ومثالُهُ: صَالحُ بنُ أبِي صالحٍ أربعةٌ (١). أحدُهم: مَوْلَى التَّوأَمَةِ (٢) بنتِ أميّةَ بنِ خَلَفٍ. والثاني: أبوهُ (٣) أبو صالحٍ السَّمَّانُ ذَكْوَانُ الرَّاوِي عَنْ أبي هُرَيْرَةَ. والثالثُ: صالحُ بنُ أبي صالحٍ السَّدُوسيُّ (٤) رَوَى عَنْ عَلِيٍّ وعَائشةَ، رَوَى عَنْهُ خَلاّدُ بنُ عَمْرٍو. والرابعُ: صالحُ بنُ أبي صالحٍ (٥) مَوْلَى عَمْرِو بنِ حُرَيْثٍ، رَوَى عَنْ أبي هُرَيْرَةَ، رَوَى عَنْهُ أَبُو بَكْرِ بنُ عَيَّاشٍ (٦)، واللهُ أعلمُ."],[1810,"القسمُ الخامسُ: المُفْتَرِقُ مِمّنْ اتفقتْ أسماؤُهم وأسماءُ آبائِهم ونسبتُهم."],[1811,"مثالُهُ: مُحَمَّدُ بنُ عَبْدِ اللهِ الأنصاريُّ (٧) اثنانِ مُتَقارِبانِ فِي الطّبقةِ. أحدُهما: هُوَ الأنْصاريُّ المشهورُ الْقَاضِي أَبُو عَبْدِ اللهِ الذي (٨) رَوَى عَنْهُ البُخَارِيُّ والناسُ. والثاني: كنيتُهُ أَبُو سَلَمةَ (٩) ضعيفُ الحديثِ، واللهُ أعلمُ.","",{"fn":"قال العراقي في شرح التبصرة ٣/ ٢٠١: «ولم يذكر الخطيب في كتابه إلا الثلاثة الأولين»، وانظر: المتفق والمفترق ١٩ - ٢٠ (أ) و(ب).\nقال الخطيب في المتفق والمفترق ٢٠ / أ: «يقال: إنّ التوأمة كانت ولدت معها أخت لها في بطن، فسميت تلك باسم، وسميت هذه التوأمة».\nعبارة التقريب للنووي ١٨٧ أوضح مما هنا إذ قال: «والذي أبوه أبو صالح السمان» يعني: صالح بن أبي صالح السمان، وأبو صالح اسمه: ذكوان، وهو والد صالح، والمقصود بالكلام الابن كما هو واضح. انظر: المتفق والمفترق ٢٠ / أ، وتهذيب الكمال ٣/ ٤٢٩.\nانظر مصادر ترجمته: التاريخ الكبير ٤/ ٢٨٣ (٢٨٢٤)، والثقات ٤/ ٣٧٧.\nوقد ضعفه يحيى بن معين، وجهله النّسائيّ. تاريخ يحيى بن معين (رواية الدارمي) ١/ ١٣٤ (٤٣٦).\nوقد استدرك الحافظ العراقي في شرح التبصرة ٣/ ٢٠٣ فقال: «ومما لم يذكراه صالح بن أبي صالح الأسدي، روى عن الشّعبيّ، روى عنه زكريا بن أبي زائدة» وعلل الحافظ عدم ذكره من ابن الصّلاح بقوله: «وإنما لم يذكراه؛ لكونه متأخر الطبقة عن الأربعة المذكورين».\nانظر: التقييد: ٤٠٦.\nهو القاضي أبو عبد الله محمّد بن عبد الله بن المثنى بن عبد الله بن أنس بن مالك الأنصاري، شيخ البخاريّ توفّي سنة ٢١٥ هـ. تاريخ بغداد ٥/ ٤٠٨، والسير ٩/ ٥٣٢.\nهو محمّد بن عبد الله بن زياد الأنصاري، أبو سلمة، أحد الضعفاء لا يحتج بحديثه. انظر: المجروحين ٢/ ٢٦٦، والضعفاء للعقيلي ٤/ ٩٦، وتهذيب الكمال ٦/ ٣٧٠ (٥٩٣٦)."}],[1812,"القِسْمُ السَّادِسُ: مَا وَقَعَ فِيهِ الاشتراكُ فِي الاسمِ خاصّةً أَوْ الكُنيةِ خاصّةً وأشكَلَ مَعَ ذَلِكَ لكونِهِ لَمْ يُذْكَرُ بغيرِ ذَلِكَ."],[1813,"مِثالُهُ: مَا رُوِّيناهُ عنِ ابنِ خَلاَّدٍ القاضِي الحافظِ قَالَ: «إذَا قَالَ عارِمٌ «حَدَّثَنَا حَمَّادٌ» فَهُوَ حَمَّادُ بنُ زَيْدٍ، وكذلكَ سُليمانُ بنُ حَرْبٍ. وإذا قَالَ التَّبُوذَكيُّ (١) «حَدَّثَنَا حمادٌ» فَهُوَ حَمَّادُ بنُ سَلَمَةَ (٢)، وكذلكِ الحَجَّاجُ بنُ مِنْهالٍ. وإذا قَالَ عَفّانُ «حَدَّثَنَا حَمَّادٌ» أمكَنَ أنْ يكونَ أحَدَهُما» (٣). ثُمَّ وَجَدْتُ عَنْ محمدِ بنِ يَحْيَى الذُّهْليِّ عَنْ عَفَّانَ قَالَ: إذَا قُلْتُ لكم «حَدَّثَنَا حَمَّادٌ» وَلَمْ أَنْسُبْهُ فَهُوَ ابنُ سَلَمَةَ. وَذَكَرَ مُحَمَّدُ بنُ يَحْيَى فيمَنْ سِوى التَّبُوذَكيِّ مَا ذَكَرَهُ ابنُ خَلاَّدٍ."],[1814,"ومِنْ ذَلِكَ مَا رُوِّيناهُ عَنْ سَلَمَةَ بنِ سُليمانَ (٤) أنّه حَدَّثَ يومًا فَقَالَ: «أَخْبَرَنَا عَبْدُ اللهِ» فقِيلَ لَهُ: ابنُ مَنْ؟ فَقَالَ: يا سُبْحانَ اللهِ! أمَا تَرْضَوْنَ فِي كلِّ حَدِيثٍ حَتَّى أقولَ: «حَدَّثَنَا عَبْدُ اللهِ بنُ المباركِ أَبُو عَبْدِ الرحمانِ الحَنْظَليُّ الَّذِي مَنْزِلُهُ فِي سِكّةِ صُغْدٍ». ثُمَّ قَالَ سَلَمَةُ: إذَا قِيلَ بمكَّةَ: «عَبْدُ اللهِ» فَهُوَ ابنُ الزُّبَيْرِ. وإذا قِيلَ بالمدينةِ: «عَبْدُ اللهِ» فَهُوَ ابنُ عُمَرَ. وإذا قِيلَ بالكُوفةِ: «عَبْدُ اللهِ» فَهُوَ عَبْدُ اللهِ بنُ مَسْعُودٍ. وإذا قِيلَ بالبَصْرَةِ: «عَبْدُ اللهِ» فَهُوَ ابنُ عَبَّاسٍ. وإذا قِيلَ بخُراسانَ «عبدُ اللهِ» فَهُوَ ابنُ المُباركِ. وَقَالَ الحافظُ أَبُو يَعْلَى الخليليُّ القَزْوِينيُّ: «إذَا قَالَ المِصْريُّ: «عَنْ عَبْدِ اللهِ» ولا يَنسُبُهُ فَهُوَ ابنُ عَمْرٍو يَعْنِي ابنَ العاصِ (٥)، وإذا قَالَ المَكِّيُّ: «عَنْ عَبْدِ اللهِ» ولا يَنْسبُهُ فَهُوَ ابنُ عَبَّاسٍ» (٦).","",{"fn":"بفتح التاء المعجمة بنقطتين من فوق، وضم الباء المنقوطة بواحدة والذال المعجمة المفتوحة بعد الواو، والتبوذكي أي: بياع السماد، وهذه النسبة إلى بيع السماد. وقيل: التبوذكي هو الذي يبيع ما في بطون الدجاج والطيور من الكبد والقلب والقانصة» الأنساب ١/ ٤٧٠.\nانظر: التقييد ٤١٠، وراجع تهذيب الكمال ٢/ ٢٨١، والسير ٧/ ٤٦٤.\nالمحدث الفاصل ٢٨٤.\nأورده الخطيب بسنده في الجامع ٢/ ٧٣ (١٢١٩).\nفي (ج): «العاصي».\nالإرشاد ١/ ٤٤٠، وراجع التقييد والإيضاح: ٤١٣."}],[1815,"وَمِنْ ذَلِكَ أَبُو حَمْزَةَ بالحاءِ والزّاي عَنْ ابنِ عَبَّاسٍ إذَا أطلقَ. وَذَكَرَ (١) بَعْضُ الحُفَّاظِ أنَّ شُعْبَةَ رَوَى عَنْ سبعةٍ كُلُّهُم أَبُو حمزةَ عَنْ ابنِ عَبَّاسٍ، وكُلُّهُمْ أبو حمزةَ بالحاءِ والزايِ إلاَّ واحدًا فإنَّهُ بالجيمِ وَهُوَ أَبُو جَمْرَةَ نَصْرُ بنُ عِمْرانَ الضُّبَعِيُّ (٢). ويُدركُ فِيهِ الفرقُ بَيْنَهم بأنَّ شُعْبَةَ إذَا قَالَ: «عَنْ أبي جَمْرَةَ (٣) عنِ ابنِ عَبَّاسٍ» وأطلَقَ فَهُوَ عَنْ نَصْرِ بنِ عِمْرانَ، وإذا رَوَى عَنْ غَيْرهِ فَهُوَ يذكُرُ اسمَهُ أَوْ نسبَهُ، واللهُ أعلمُ."],[1816,"القِسْمُ السابعُ: المُشْتَرَكُ المتَّفِقُ فِي النِّسْبةِ خاصّةً."],[1817,"ومنْ أمثلتِهِ: الآمُلِيُّ والآمُليُّ. فالأوَّلُ إلى آمُلِ (٤) طَبَرِسْتَانَ (٥). قَالَ أَبُو سَعْدٍ (٦) السَّمْعانِيُّ: «أكثرُ أَهْلِ العلمِ منْ أَهْلِ طَبَرِسْتَانَ منْ آمُلَ» (٧). والثاني: إلى آمُلِ جَيْحُونَ (٨). شُهِرَ بالنَّسْبةِ إليها عَبْدُ اللهِ بنُ حَمَّادٍ الآمُلِيُّ (٩)، رَوَى عَنْهُ البُخَارِيُّ فِي \" صَحِيْحِهِ \" (١٠). وذَكرَهُ الحافظُ أَبُو عَلِيٍّ الغَسَّانيُّ ثُمَّ الْقَاضِي عِياضٌ (١١) المغْرِبيانِ منْ أنّه مَنْسوبٌ إلى آمُلِ طَبَرِسْتَانَ فَهُوَ خَطَأٌ، واللهُ أعلمُ.","",{"fn":"انظر: التقييد: ٤١٤.\nبضم المعجمة وفتح الموحدة بعدها مهملة، انظر: التقريب (٧١٢٢).\nفي (ب) و(ج): «حمزة».\nآمل: بالمد وضم الياء. الأنساب ١/ ٦٢.\nبفتح أوله وثانيه وكسر الراء كما نص على ذلك في معجم البلدان ٤/ ١٣، وكذا في تاج العروس ١٢/ ٤١٣، ولكنه قال بفتح الراء.\nفي (أ) و(ب): «سعيد» خطأ.\nالأنساب ١/ ٦٢.\nبالفتح ثمّ السكون، انظر معجم البلدان ٢/ ١٩٦.\nبالمد وتخفيف الميم المضمومة. التقريب (٣٢٨١). قال ياقوت في معجم البلدان ١/ ٥٩: «هي آمل الشط ... هكذا يقولها العجم على الاختصار والعجمة». وآمل الشط هي آمل جيحون، انظر: تبصير المنتبه ١/ ٤٩ - ٥٠.\nقال العراقي في شرح التبصرة ٣/ ٢٠٨: «لم يرو البخاريّ في صحيحه عنه مصرحًا بنفسه، ولا بأبيه وإنما حدّث في موضع، عن عبد الله - غير منسوب - عن يحيى بن معين، وفي موضع آخر: عن عبد الله - غير منسوب - عن سليمان بن عبد الرحمن»، وانظر: التقييد: ٤١٥.\nمشارق الأنوار ١/ ٦٩."}],[1818,"ومِنْ ذَلِكَ الحَنَفِيُّ والحَنَفِيُّ. فالأول: نِسْبةً إلى بني حَنِيفَةَ، والثاني: نِسْبةً"],[1819,"إلى مَذْهَبِ أبي حَنَيْفَةَ. وَفِي كُلٍّ مِنْهُمَا كَثْرةٌ وشُهْرةٌ. وَكَانَ مُحَمَّدُ بنُ طاهرٍ المقدسيُّ وكثيرٌ مِنْ أَهْلِ العلمِ (١) والحديث (٢) وغيرِهم يُفَرِّقُونَ بَيْنَهُمَا فَيَقُولُونَ فِي المَذْهَبِ:"],[1820,"«حَنِيفيٌّ» بالياءِ وَلَمْ أجدْ ذَلِكَ عَنْ أحدٍ مِنَ النَّحْوِيِّينَ إلاّ عَنْ أبي بَكْرِ بنِ الأنبارِيِّ"],[1821,"الإمامِ، قَالَهُ فِي كتابِهِ \" الكافي \" (٣)، ولمُحَمَّدِ بنِ طاهرٍ فِي هَذَا القسمِ كِتَابُ \" الأنْسابِ المُتَّفِقَةِ \"."],[1822,"ووراءَ هذِهِ الأقسامِ أقسامٌ أُخَرُ لا حاجةَ بنا إلى ذِكْرِها."],[1823,"ثُمَّ إنّ مَا يُوجَدُ مِنَ المتَّفِقِ المُفْتَرِقِ غَيْرَ مَقْرُونٍ ببيانٍ، فالمُرادُ بِهِ قَدْ يُدْرِكُ بالنَّظرِ فِي رِواياتِهِ، فكثيرًا مَا يأتي مُميَّزًا فِي بَعْضِها وَقَدْ يُدْركُ بالنَّظَرِ فِي حالِ الرَّاوِي والمَرْوِيِّ عَنْهُ ورُبَّما قالوا فِي ذَلِكَ بظنٍّ لا يَقْوى حَدَّثَ القاسمُ المُطَرِّزُ يومًا بحديثٍ «عَنْ أبي هَمَّامٍ أَوْ غيرِهِ عنِ الوليدِ (٤) بنِ مسلمٍ عَنْ سُفيانَ». فقالَ لَهُ أَبُو طالبِ بنِ نَصْرٍ الحافظُ: مَنْ سفيانُ هَذَا؟ فقالَ: هَذَا الثوريُّ. فقالَ لَهُ أَبُو طالبٍ: بَلْ هُوَ ابنُ عُيَيْنَةَ. فقالَ لَهُ المُطَرِّزُ: مِن أينَ قلتَ؟ فقالَ: لأنَّ الوليدَ قَدْ رَوَى عنِ الثوريِّ أحاديثَ معدودةً محفوظةً وَهُوَ مَلِيءٌ بابنِ عُيَيْنَةَ (٥)، واللهُ أعلمُ.","",{"fn":"«العلم» من (ع» والتقييد فقط.\nالأنساب المتفقة ٤٦.\nذكره النديم في الفهرست: ٨٢، وياقوت في معجم الأدباء ١٨/ ٣١٢ وغيرهما، ولا نعلم عنه غير اسمه. وما ذهب إليه أبو بكر بن الأنباري نصره السيوطي إذ قال: والصّواب معه، وقد اخترته في كتاب جمع الجوامع في العربية، فقد قال - صلى الله عليه وآله وسلم -: «بعثت بالحنيفية السمحة» فأثبت الياء في اللفظة المنسوبة إلى الحنفية فلا مانع من ذلك». تدريب الرّاوي ٢/ ٣٢٨، وانظر: المقرب ٤١٦، وأوضح المسالك: ٢٩٤، وجمع الجوامع مع شرحه همع الهوامع ٦/ ١٦٢.\nانظر: التقييد: ٤١٦.\nانظر: التقييد والإيضاح: ٤١٦ - ٤١٧."}],[1824,"النوع الخامس والخمسون نوع يتركب من النوعين اللذين قبله"],[1825,"(١)"],[1826,"وَهُوَ أنْ يُوجَدَ الاتِّفاقُ الْمذكُورُ فِيْ النَّوع الذي فَرَغْنا منهُ آنفًا، فِيْ اسْمَي شَخْصَيْنِ أَوْ كُنْيَتِهِما التي عُرِفا بها، وَيوجَدُ (٢) فِيْ نَسَبِهِما أَوْ نِسْبَتِهما الاختلافُ والائتلافُ المذْكُورانِ فِي النَّوعِ الذي قَبْلَهُ، أَوْ عَلَى العكسِ منْ هَذَا بأنْ يخْتَلِفَ ويأتلِفَ أسماؤها ويتفقَ (٣) نسبتُهما أَوْ نَسَبُهما اسمًا أَوْ كُنيةً. ويلتحِقُ بالمؤْتلِفِ والمُختلفِ فِيهِ: مَا يتقاربُ ويَشْتبهُ وإنْ كَانَ مختلفًا فِي بعضِ حُروفِهِ فِي صورةِ الخطِّ. وصَنَّفَ الخطيبُ الحافِظُ (٤) فِي ذَلِكَ كتابَهُ الذي سمّاهُ (٥) كتابَ \" تَلْخِيصِ المُتَشَابِهِ فِي الرَّسْم \" (٦) وَهُوَ منْ أحسنِ كُتبِهِ لَكِنْ لَمْ يُعْرِبْ (٧) باسمِهِ الذي سَمّاهُ بِهِ عَنْ مَوْضُوْعِهِ كَمَا أَعْرَبنا عَنْهُ (٨)."],[1827,"فمِنْ أَمثلةِ الأَوَّلِ: مُوسى بنُ عَلِيٍّ (٩) بفَتْحِ العَينِ ومُوسى بن عُلِيٍّ (١٠) بضمِّ العَينِ. فمِنَ الأَوَّلِ جَمَاعَةٌ مِنْهُمْ أَبُو عيسى الخُتَّليُّ (١١) الذي رَوَى عَنْهُ أَبُو بكرِ بنِ مِقْسَمٍ المُقْرِئُ وأبو عَلِيٍّ الصَّوَّافُ وغيرُهما (١). وأما الثَّانِي (٢): فَهُوَ موسى بنُ عُلَيٍّ ابنِ رَباحٍ اللَّخْمِيُّ المِصْرِيُّ، عُرِفَ بالضَّمِّ فِي اسمِ أبيهِ. وَقَدْ رُوِّينا عَنْهُ تحريجَهُ (٣) مَنْ يقولُهُ بالضمِّ.","",{"fn":"انظر في ذلك: الإرشاد ٢/ ٧٤٩ - ٧٥٠، والتقريب: ١٨٩، والمنهل الروي: ١٣٠، واختصار علوم الحديث: ٢٣٠ - ٢٣١، والشذا الفياح ٢/ ٦٩٣ - ٦٩٤، والمقنع ٢/ ٦٢٥، وشرح التبصرة ٣/ ٢١٠، ونزهة النظر: ١٨٠ - ١٨٤، وطبعة عتر: ٧٠، وفتح المغيث ٣/ ٢٦٤ - ٢٦٥، وتدريب الراوي ٢/ ٣٣٤ - ٣٣٥، وفتح الباقي ٣/ ٢١٧ - ٢٢٢، وتوضيح الأفكار ٢/ ٤٩٥.\nفي (م) والشذا: «أو يوجد».\nفي (م) و(ب) والشذا: «وتتفق».\nسقطت من (م).\nفي (م) والشذا: «أسماه».\nطبع بمجلدين في دمشق عن دار طلاس، بتحقيق سكينة الشهابي ١٩٨٥ م.\nفي (ب) و(ج): «يعرف».\nسقطت من (م).\nانظر: التقييد: ٤١٧.\nانظر: تلخيص المتشابه ١/ ٥٤.\nبضم الخاء والتاء المشددة، انظر: الأنساب ٢/ ٣٧٢."}],[1828,"ويُقالُ: إنَّ أهلَ مِصْرَ كانوا يَقُولونَهُ بالفَتْحِ لِذلِكَ، وأهلَ العراقِ كانوا يقولونَهُ بالضَّمِّ (٤). وَكَانَ بعضُ الحُفَّاظِ يجعلُهُ بالفَتحِ اسمًا لَهُ وبالضمِّ لَقَبًا (٥) واللهُ أعلمُ."],[1829,"ومِنَ المتَّفِقِ مِنْ ذَلِكَ: المختلفُ المؤتلفُ فِي النِّسبةِ، محمدُ بنُ عَبْدِ اللهِ المُخَرِّميُّ بضمّ الميمِ الأولى وكَسْرِ الرَّاءِ المُشدَّدةِ. مَشْهُورٌ صاحبُ حَدِيثٍ نُسِبَ إلى المُخَرِّمِ منْ بغدادَ (٦). ومحمدُ بنُ عبدِ اللهِ المَخْرَمِيُّ (٧) بفتحِ الميمِ الأولى وإسكانِ الخاءِ المعجمةِ غَيْرُ مشهورٍ. رَوَى عنِ الشَّافِعيِّ الإمام (٨)، واللهُ أعلمُ."],[1830,"ومِمَّا يتقاربُ ويَشْتَبِهُ (٩) مَعَ الاختلافِ فِي الصُّورةِ: ثورُ بنُ يَزِيدَ الكَلاَعيُّ الشَّاميُّ. وثَوْرُ بنُ زَيْدٍ - بلا ياءٍ فِي أوّلِهِ - الدِّيليُّ المَدَنيُّ وهذا الذي رَوَى عَنْهُ مَالِكٌ وحديثُهُ فِي \" الصَّحِيحَيْنِ \" معًا. والأوّلُ حديثُهُ عِنْدَ مُسْلِمٍ (١٠) خاصّةً، واللهُ أعلمُ.","",{"fn":"قال العراقي في شرح التبصرة ٣/ ٢١١: «فالأول: بفتح العين مكبرًا، وهم جماعة متأخرون، ليس في الكتب الستة منهم أحد، ولا في تاريخ البخاريّ، ولا في كتاب ابن أبي حاتم إلا الثّاني ... موسى بن عليّ، أبو عليّ الصواف».\nانظر: التقييد: ٤١٩.\nفي (أ) و(ب) و(م): «تخريجه» خطأ، وروي عنه هو ما اسنده التّرمذي عقب (٧٧٣) قال: «لا أجعل أحدًا في حلّ يصغر اسمي» وانظر: شرح التبصرة ٣/ ٢١١ وتعليقنا عليه.\nقاله محمّد بن سعد في طبقاته ٧/ ٥١٥ نبه عليه العراقي في التقييد: ٤١٩، وفي شرح التبصرة ٣/ ٢١١ - ٢١٢\nنسبه العراقي في شرح التبصرة ٣/ ٢١٢، والتقييد: ٤١٩ للدارقطني.\nانظر: الأنساب ٥/ ١٠٥.\nالأنساب ٥/ ١٠٥.\nفي (ع): «الإمام الشّافعيّ».\nقال العراقي في شرح التبصرة ١/ ٢١٦: «وقد أدخل فيه الخطيب وابن الصّلاح ما لا يأتلف خطه ك: ثور ابن يزيد وثور بن زيد وعمرو بن زرارة، وعمر بن زرارة فلم أذكره لعدم الاشتباه في الغالب».\nانظر: تعقب الحافظ العراقي لذلك في التقييد: ٤٢٠."}],[1831,"ومِنَ المتَّفِقِ فِي الكُنيةِ المُختلِفِ المؤتلِفِ (١) فِي النِّسْبةِ (٢): أَبُو عَمْرٍو الشَّيْبانيُّ وأبو عَمْرٍو السَّيْبانيُّ تابِعِيَّانِ يَفْتَرِقانِ فِي أنَّ الأَوَّلَ بالشِّينِ المعجمةِ والثاني بالسِّينِ المهملةِ، واسمُ الأَوَّلِ سَعْدُ بنُ إياسٍ ويُشاركُهُ فِي ذَلِكَ أَبُو عَمْرٍو الشَّيْبانيُّ اللُّغويُّ إسحاقُ بنُ مِرَارٍ (٣). وأما الثَّانِي: فاسمَهُ زُرْعَةُ وَهُوَ والدُ يَحْيَى بنِ أبي عَمْرٍو السَّيْبَانيِّ الشَّاميِّ، واللهُ أعلمُ."],[1832,"وأمَّا القسمُ الثَّانِي: الذي هُوَ عَلَى العكْسِ فمن أَمْثِلَتِهِ بأنواعهِ: عَمْرُو ابنُ زُرَارَةَ بفتحِ العينِ، وعُمَر بنُ زُرَارَةَ بضمِّ العَينِ. فالأولُ: جماعةٌ مِنْهُمْ:"],[1833,"أَبُو مُحَمَّدٍ النَّيْسَابوريُّ (٤) الذي رَوَى عَنْهُ مُسْلِمٌ (٥). والثاني يُعرَفُ"],[1834,"بالحَدَثيِّ (٦) وَهُوَ الذي يَرْوِي عَنْهُ البَغَوِيُّ (٧) المَنِيْعِيُّ (٨). وبَلَغنا عَنِ الدَّارَقُطْنِيِّ أنّهُ «منْ مدينةٍ فِي الثَّغْرِ يُقالُ لها: الحَدَثُ» (٩). ورُوِّينا عَنْ أبِي أَحْمَدَ الحافِظِ الحَاكِم أنّهُ منْ أَهْلِ الحَدِيثةِ (١٠) منسوبًا إليها (١١)، واللهُ أعلمُ.","",{"fn":"في (م) والشذا: «المختلف والمؤتلف».\nانظر التقييد: ٤٢١.\nقال ابن حجر في التقريب (٨٢٧٥): «بكسر الميم وتخفيف الراء»، وقال البلقيني في محاسن الاصطلاح: ٥٦٣: «في ميم مرار: الكسر، على مثال: ضرار، والفتح مثال: سراب والتشديد على مثال: عمّار». ونحوه في الإرشاد ٢/ ٧٤٧ والمقنع ٢/ ٦٢٣، وشرح التبصرة ٣/ ٢١٤.\nعمرو بن زرارة بن واقد الكلابي، أبو محمّد بن أبي عمرو النيسابوري: ثقة ثبت توفّي سنة (٢٣٨هـ). انظر: تهذيب الكمال ٥/ ٤١٤ (٤٩٥٧).\nاستدرك على المصنف العراقي في التقييد: ٤٢١، وابن الملقن في المقنع ٢/ ٦٢٣ أن البخاريّ روى عنه أيضًا، وانظر تهذيب الكمال ٥/ ٤١٥.\nبفتح الحاء والدال المهملتين ثمّ بثاء مثلثة، نسبة إلى الحد، وهي قلعةٌ حصينة. انظر: مراصد الاطلاع ١/ ٣٨٥.\nهو أبو القاسم البغويّ، انظر ترجمته في السير ١٤/ ٤٤.\nبفتح الميم وسكون الياء هذه النسبة إلى منيع، وهو اسمٌ لبعض أجداده. انظر: الأنساب ٥/ ٢٩٣.\nسؤالات البرقاني (٣٥٤).\nبفتح أوله وكسر ثانيه، وياء ساكنة وثاء مثلثة. انظر مراصد الاطلاع ١/ ٣٨٦.\nأسنده السمعاني في الأنساب ٢/ ٢٢٤."}],[1835,"عُبيدُ اللهِ بنُ أبي عَبْدِ اللهِ، وعبدُ اللهِ بنُ أبي عبدِ اللهِ. الأَوَّلُ: هُوَ ابنُ الأغرِّ سَلمانُ أبي عَبْدِ اللهِ صاحبِ أبي هُرَيْرَةَ رَوَى عَنْهُ مَالِكٌ. والثاني: جماعةٌ مِنْهُمْ:"],[1836,"عَبْدُ اللهِ بنُ أبي عَبْدِ اللهِ المُقْرِئُ الأصبهانيُّ رَوَى عَنْهُ أَبُو الشَّيْخِ الأصبهانيُّ، واللهُ أعلمُ."],[1837,"حَيَّانُ الأسديُّ بالياءِ المُشَدَّدةِ المُثَنَّاةِ منْ تحتُ. وَحنَانٌ بالنونِ الخفيفةِ، الأَسَديُّ. فَمنِ الأَوَّلِ: حَيَّانُ بنُ حُصَيْنٍ التَّابِعيُّ الرَّاوِي عَنْ عَمَّارِ بنِ ياسرٍ. والثاني: هُوَ حنَانٌ الأسديُّ منْ بني أسدِ بنِ شُرَيْكٍ بضمِّ الشِّينِ وَهُوَ عمُّ مُسَرْهَدٍ والِدُ مُسَدَّدٍ ذَكَرَهُ الدَّارَقُطْنِيُّ يَرْوِي عَنْ أبي عثمانَ النهديِّ، واللهُ أعلمُ."],[1838,"النوع السادس والخمسون معرفة الرواة المتشابهين في الاسم والنسب المتمايزين بالتقديم والتأخير في الابن والأب"],[1839,"(١)"],[1840,"مثالُهُ: يَزِيدُ بنُ الأسْوَدِ والأسودُ بنُ يَزِيدَ. فالأولُ: يزيدُ بنُ الأسودِ الصَّحَابيُّ الخُزَاعيُّ، ويزيدُ بنُ الأسودِ الجُرَشيُّ (٢) أَدْركَ الجاهليةَ وأسلمَ وسَكَنَ الشامَ وذُكِرَ بالصَّلاحِ حَتَّى اسْتسْقى بِهِ معاويةُ فِي أَهْلِ دِمشقَ فَقَالَ: «اللَّهُمَّ إنَّا (٣) نَستشفِعُ إليكَ اليومَ بخيرِنا وأفضلِنا». فَسُقوا للوقتِ، حَتَّى كادوا لا يبلغونَ مَنازلَهم (٤)، والثاني: الأسودُ بنُ يزيدَ النَّخَعيُّ التابعيُّ الفاضلُ.","",{"fn":"انظر في ذلك: الإرشاد ٢/ ٧٤٩، والتقريب: ١٨٩، والمنهل الروي: ١٣٠، واختصار علوم الحديث: ٢٣٠، والشذا الفياح ٢/ ٦٩٣، والمقنع ٢/ ٦٢٥، وشرح التبصرة ٣/ ٢١٧، ونزهة النظر: ٧٠، وطبعة عتر: ١٨٠، وفتح المغيث ٣/ ٢٦٤، وتدريب الراوي ٢/ ٣٣٤، وفتح الباقي ٣/ ٢٢٣، وتوضيح الأفكار ٢/ ٤٩٥.\nفي (ج): «الحرشي» بالحاء المهملة، وهو تصحيفٌ. قال صاحب الأنساب: ٢/ ٦٨: «بضم الجيم وفتح الراء، وفي آخرها الشين المعجمة».\nسقطت من (م).\nأسند هذه القصة ابن عساكر في تاريخ دمشق ٦٥/ ١١٢."}],[1841,"ومِنْ ذَلِكَ الوليدُ بنُ مُسْلِمٍ وَمُسْلِمُ بنُ الوليدِ. فَمِنَ الأَوَّلِ الوليدُ بنُ مُسْلِمٍ البَصْريُّ التابعيُّ الرَّاوِي عَنْ جُنْدَبِ بنِ عَبْدِ اللهِ البَجَليِّ. والوليدُ بنُ مسلمٍ الدِّمشقيُّ المشْهُورُ صاحبُ الأوزاعيِّ رَوَى عَنْهُ أَحْمَدُ بنُ حنبلٍ والناسُ. والثاني: مُسْلِمُ بنُ الوليدِ بنِ رَباحٍ المَدَنيُّ حَدَّثَ عَنْ أَبِيهِ وغَيْرِه، رَوَى عَنْهُ عبدُ العزيزِ الدَّرَاوَرْدِيُّ وغيرُهُ وَذَكَرَهُ البُخَارِيُّ فِي \" تأريخِهِ \" (١) فَقَلبَ اسمَهُ ونسبَهُ فَقَالَ: «الوليدُ بنُ مُسْلِمٍ» وأُخِذَ عَلَيْهِ ذَلِكَ (٢)."],[1842,"وَصنَّفَ الخطيبُ الحافظُ فِي هَذَا النوعِ كِتابًا سمّاهُ \" كتابَ رافعِ الارتيابِ فِي المَقْلُوبِ مِنَ الأسماءِ والأنسابِ \". وهذا الاسمُ رُبَّما أوهمَ اختصاصَهُ بما وَقَعَ فِيهِ مِثْلُ الغَلَطِ المذكورِ فِي هَذَا المثالِ الثَّانِي وليسَ ذَلِكَ شَرْطًا فِيهِ وأكثرُهُ لَيْسَ كَذلِكَ، فما ترجمناهُ بِهِ إذن أَوْلَى، واللهُ أعلمُ."],[1843,"النوع السابع والخمسون معرفة المنسوبين إلى غير آبائهم"],[1844,"(٣)"],[1845,"وذَلِكَ عَلَى ضُروبٍ:","",{"fn":"تاريخه ٨/ ٣٥٣ الترجمة (٢٥٣٤).\nوممن أخذ عليه أبو زرعة وأبو حاتم الرازيان، كما روى عبد الرحمان بن أبي حاتم في كتابه \" بيان خطأ البخاريّ في تاريخه \" عن أبي زرعة فقال في كتابه: ١٣٠ بعد أن ساق قول البخاريّ معقبًا عليه: «الوليد ابن مسلم بن أبي رباح مولى آل أبي ذباب، وإنما هو مسلم بن الوليد بن رباح. سمعت أبي يقول كما قال. وقال أيضًا في كتابه الجرح والتعديل ٨/ ١٩٧ الترجمة (٨٦٤) بعد أن ترجم لمسلم ابن الوليد: «وكان البخاريّ أخرج هذا الاسم في باب الوليد بن مسلم بن أبى رباح فقال أبو زرعة: إنما هو مسلم بن الوليد، وكذا قال أبي» انتهى.\nانظر في ذلك: الإرشاد ٢/ ٧٥١ - ٧٥٧، والتقريب: ١٩٠ - ١٩١، والمنهل الروي: ١٣٠، واختصار علوم الحديث: ٢٣١ - ٢٣٤، والشذا الفياح ٢/ ٦٩٥ - ٦٩٩، والمقنع ٢/ ٦٢٦ - ٦٢٩، وشرح التبصرة ٣/ ٢١٩ - ٢٢٤، ونزهة النظر: ١٩٥، وطبعة عتر: ٧٦، وفتح المغيث ٣/ ٢٦٦ - ٢٦٩، وتدريب الراوي ٢/ ٣٣٦ - ٣٣٩، وشرح السيوطي على ألفية العراقي: ٢٥٥، وفتح الباقي ٣/ ٢٢٤ - ٢٢٧، وتوضيح الأفكار ٢/ ٤٩٥، وظفر الأماني: ١١٢ - ١١٣."}],[1846,"أحدُها: مَنْ نُسِبَ إلى أمِّهِ، مِنْهُمْ: مُعَاذٌ، ومُعَوِّذٌ، وعَوْذٌ، بَنُو عَفْراءَ هِيَ أمُّهُم، وأبُوهُمْ: الحارثُ بنُ رِفَاعةَ الأنصاريُّ. وذكَرَ ابنُ عبدِ البرِّ أَنّهُ يُقالُ فِي عَوْذٍ: عَوْفٌ (١) وَأنّه الأكثرُ (٢) بِلاَلُ بنُ حَمَامَةَ المُؤذِّنُ، حَمَامَةُ أمُّهُ، وأبُوهُ (٣): رَبَاحٌ. سُهَيْلٌ وأخواهُ سَهْلٌ وصَفْوَانُ بَنُو بَيْضَاءَ هِيَ أُمُّهم واسمُها: دَعْدٌ، واسمُ أبيهم: وَهْبٌ. شُرَحْبِيْلُ بنُ حَسَنةَ هِيَ أمُّهُ، وأبوهُ: عبدُ اللهِ بنُ المُطَاعِ الكِنْديُّ. عبدُ اللهِ بنُ بُحيْنةَ هِيَ أمُّهُ، وأبُوهُ: مَالِكُ بنُ القِشْبِ (٤) الأزْدِيُّ الأَسديُّ. سَعْدُ بنُ حَبْتَةَ (٥) الأنصاريُّ هِيَ أمُّهُ، وأبوهُ: بَحِيرُ بنُ مُعاويةَ جدُّ أبي يُوسُفَ القاضِي. هؤلاءِ صحابةٌ - رضي الله عنهم -."],[1847,"ومِنْ غيرِهم: مُحَمَّدُ بنُ الحَنَفِيَّةِ هِيَ أمُّهُ واسمُها خَوْلَةُ، وأبُوهُ: عَلِيُّ بنُ أبي طالبٍ - رضي الله عنه -. إسماعيلُ بنُ عُليَّةَ هِيَ أمُّهُ (٦)، وأبُوهُ: إِبْرَاهِيمُ أَبُو إسحاقَ. إِبْرَاهِيمُ بنُ هَرَاسَةَ (٧)، قَالَ عَبْدُ الغنِيِّ بنُ سعيدٍ: هِيَ أمُّهُ، وأبوهُ سَلَمَةُ، واللهُ أعلمُ."],[1848,"الثَّانِي: مَنْ نُسِبَ إلى جَدَّتِهِ، مِنْهُمْ: يَعْلَى بنُ مُنْيَةَ (٨) الصَّحَابيُّ، هِيَ فِي"],[1849,"قَوْلِ الزُّبَيْرِ بنِ بَكَّارٍ جدَّتُهُ أمُّ أبيهِ، وأبوهُ، أُمَيَّةُ (٩). ومِنْهُمْ: بَشِيرُ بنُ الخَصَاصِيَةِ (١) الصَّحَابيُّ هُوَ بَشِيرُ بنُ مَعْبَدٍ، والخَصَاصِيةُ هِيَ أمُّ الثالثِ منْ أَجدادِهِ. ومِنْ أحدثِ ذَلِكَ عَهْدًا: شَيْخُنا أَبُو أَحْمَدَ عَبْدُ الوهَّابِ بنُ عَلِيٍّ البغداديُّ يُعْرَفُ بابنِ سُكَيْنَةَ، وهيَ أمُّ أبيهِ، واللهُ أعلمُ.","",{"fn":"وذكر ابن كثير أنه يقال له: «عون» أيضًا اختصار علوم الحديث ٢/ ٦٣٨.\nالاستيعاب ٣/ ١٣١.\nفي (ج): «رباح أبوه».\nبكسر القاف وسكون المعجمة بعدها موحدة التقريب (٣٥٦٧)، وتاج العروس ٤/ ٣٥.\nبفتح الحاء وإسكان الباء الموحدة بعدها مثناة من فوق. الإرشاد ٢/ ٧٥٢.\nانظر: المحاسن ٥٦٧.\nفي (ج) حاشية نصها: «قال المصنف - رحمه الله - وجدت بخط الفاضل أبي الحسن بن المنادي هراسة بفتح الهاء في بعض تصانيفه» ومثله في حاشية (م).\nبضم الميم وسكون النون، وبعدها تحتانية مفتوحة (التقريب ٧٨٣٩).\nقال العراقي في التقييد والإيضاح ٤٢٤ - ٤٢٥: «اقتصر المصنف على قول الزّبير بن بكار، وكذلك جزم به ابن ماكولا، وقد ضعفه ابن عبد البر وغيره قال ابن عبد البر لم يصب الزّبير. والذي عليه الجمهور أنها أمه، وهو قول عليّ بن المديني وعبد الله بن عبد الله بن مسلمة القعنبي، ويعقوب بن شيبة، وبه جزم البخاريّ في التاريخ الكبير، وابن أبي حاتم في الجرح والتعديل ومحمد بن جرير الطبري وابن قانع، والطبراني وابن حبان في الثّقات وابن منده في معرفة الصّحابة، وآخرون، وحكاه الدّارقطنيّ عن أصحاب الحديث، ورجحه ابن عبد البر والمزي فقال في التهذيب والأطراف أيضًا: هي أمه ويقال: جدته، وكذا ذكره المصنف في النّوع السابع والعشرين على الصّواب» قلنا: انظر: الجرح والتعديل ٩/ ٣٠١، والثقات ٣/ ٤٤١، والاستيعاب ٣/ ٦٦٢، والإكمال ٧/ ٢٩٦، وتهذيب الكمال ٨/ ١٨١."}],[1850,"الثالثُ: مَنْ نُسِبَ إلى جَدِّهِ، مِنْهُمْ: أَبُو عُبَيْدَةَ بنُ الجَرَّاحِ أحدُ العَشَرَةِ هُوَ عامرُ ابنُ عَبْدِ اللهِ بنِ الجَرَّاحِ. حَمَلُ (٢) بنُ النَّابِغةِ الهُذَليُّ الصَّحَابيُّ هُوَ حَمَلُ بنُ مَالِكِ بنِ النابغةِ. مُجَمَّعُ (٣) بنُ جاريةَ الصَّحَابيُّ هُوَ مُجمَّعُ بنُ يزيدَ بنِ جاريةَ. ابنُ"],[1851,"جُرَيْجٍ، هُوَ عبدُ الملكِ بنُ عبدِ العزيزِ بنِ جُرَيْجٍ. بَنُو الماجِشُونَ - بكسرِ الجيمِ- (٤) مِنْهُمْ: يُوسفُ بنُ يعقوبَ بنِ أبي سَلَمَةَ المَاجِشُونَ. قَالَ أَبُو عَلِيٍّ الغَسَّانيُّ: هُوَ لَقَبُ يعقوبَ بنِ أبي سلمةَ وجَرَى عَلَى بَنِيْهِ وَبَنِي أخيهِ عبدِ اللهِ بنِ أبي سَلَمَةَ. قلتُ: والمختارُ فِي مَعناهُ أنّهُ الأبْيضُ الأحمرُ (٥)، واللهُ أعلمُ."],[1852,"ابنُ أبي ذِئْبٍ هُوَ: مُحَمَّدُ بنُ عَبْدِ الرحمانِ بنِ المغيرةِ بنِ أبي ذئْبٍ. ابنُ أبي ليلى الفقيهُ هُوَ: مُحَمَّدُ بنُ عبدِ الرحمانِ بنِ أبي ليلى. ابنُ أبي مُلَيْكَةَ (٦) هُوَ: عبدُ اللهِ بنُ"],[1853,"عُبَيْدِ اللهِ بنِ أبي مُلَيكةَ. أَحْمَدُ بنُ حَنْبَلٍ الإمامُ هُوَ: أَحْمَدُ بنُ مُحَمَّدِ بنِ حَنْبَلٍ، أَبُو عَبْدِ اللهِ. بَنُو أبي شَيْبَةَ: أَبُو بَكْرٍ وعُثمانُ الحافظانِ وأخوهما القاسمُ، أَبُو شَيْبَةَ هُوَ جَدُّهم واسمُهُ: إِبْرَاهِيمُ بنُ عثمانَ واسطيٌّ، وأبوهُم: مُحَمَّدُ بنُ أبي شيبةَ. ومن المتأخرينَ: أَبُو سعيدِ بنُ يونسَ - صاحبُ \" تاريخِ مِصْرَ \" هُوَ: عَبْدُ الرحمانِ بنُ أَحْمَدَ بنِ يُونُسَ بنِ"],[1854,"عَبْدِ الأعلَى الصَّدَفيُّ (٧)، واللهُ أعلمُ.","",{"fn":"بمعجمة مفتوحة وصادين مهملتبن بعد الثّانية تحتانية التقريب (٧٢٢) ونصّ على تخفيف الياء النّوويّ في الإرشاد ٢/ ٧٥٤، وابن الملقن في المقنع ٢/ ٦٢٧ وغيرهما.\nبفتح أوّله والميم. انظر: الخلاصة ٩٤.\nقال ابن حجر: «بضم أوله وفتح الجيم وتشديد الميم المكسورة، التقريب (٦٤٨٧) وقال النّوويّ: «بفتح الميم الثانية وكسرها». الإرشاد ٢/ ٧٥٥، ومثله في المقنع ٢/ ٦٢٨.\nأشار الزبيدي في التاج ١٧/ ٣٧٤ إلى أن الجيم مثلث.\nانظر معانيه الأخرى في تاج العروس ١٧/ ٣٧٤.\nمليكة بالتصغير. التقريب (٣٤٥٤).\nبفتح الصاد والدال المهملتين. انظر: الأنساب ٣/ ٥٣٧."}],[1855,"الرابعُ: مَن نُسِبَ إلى رَجُلٍ غيرِ أبيهِ هُوَ مِنْهُ بسَبَبٍ، مِنْهُمْ: المِقْدادُ بنُ الأسودِ وَهُوَ: المقدادُ بنُ عَمْرِو بنِ ثَعْلَبةَ الكِنْدِيُّ، وَقِيلَ: البَهْرَانِيُّ (١) كَانَ فِي حِجْرِ الأَسودِ بنِ عَبْدِ يَغُوثَ الزُّهْريِّ وَتَبَنَّاهُ فنُسِبَ إِليهِ. الحَسَنُ بنُ دِينارٍ هُوَ: ابنُ وَاصِلٍ، ودِينارٌ: زَوْجُ أُمِّهِ، وَكأنَّ هَذَا خَفِيَ عَلَى ابنِ أبي حاتِمٍ حيثُ قَالَ فِيهِ: الحَسَنُ بنُ دِينارِ بنِ وَاصِلٍ، فَجَعَلَ وَاصِلًا جَدَّهُ (٢)، واللهُ أعلمُ."],[1856,"النوع الثامن والخمسون معرفة النسب التي باطنها على خلاف ظاهرها"],[1857,"الَّذِي هُوَ السَّابِقُ إلى الفَهْمِ مِنْهَا (٣) مِنْ ذَلِكَ: أَبُو مَسْعُودٍ البَدْرِيُّ، عُقْبَةُ بنُ عَمْرٍو، لَمْ يَشْهدْ بَدْرًا فِي قولِ الأكثرِ (٤)، ولكنْ نَزَلَ بَدْرًا فنُسِبَ إليها (٥)."],[1858,"- سُلَيمانُ بنُ طَرْخَانَ التَّيْمِيُّ: نَزَلَ فِي تَيْمٍ وليسَ مِنْهُمْ، وَهُوَ مَوْلَى بنِي مُرَّةَ."],[1859,"- أَبُو خالدٍ الدَّالانيُّ (٦) يزيدُ بنُ عَبْدِ الرحمانِ هُوَ أسديٌّ مَوْلَى لبنِي أَسدٍ، نَزَلَ فِي بنِي دَالانَ بَطْنٌ منْ هَمْدَانَ (٧) فنُسِبَ إليهم.","",{"fn":"بفتح الباء وسكون الهاء وفتح الراء. انظر: الأنساب ١/ ٤٤١.\nالجرح والتعديل ٣/ ١١ رقم (٣٧).\nانظر في ذلك: الإرشاد ٢/ ٧٥٨ - ٧٦١، والتقريب: ١٩١ - ١٩٢، والمنهل الروي: ١٣١، واختصار علوم الحديث: ٢٣٤ - ٢٣٦، والشذا الفياح ٢/ ٧٠٠ - ٧٠٢، والمقنع ٢/ ٦٣٠ - ٦٣١، وشرح التبصرة ٣/ ٢٢٤ - ٢٢٨، ونزهة النظر: ١٩٦، وطبعة عتر: ٧٦، وفتح المغيث ٣/ ٢٧٠ - ٢٧٣، وتدريب الراوي ٢/ ٣٤٠ - ٣٤١، وشرح السيوطي على ألفية العراقي: ٢٥٧، وفتح الباقي ٣/ ٢٢٧ - ٢٢٩، وتوضيح الأفكار ٢/ ٤٩٦ - ٤٩٧، وظفر الأماني: ١١٤.\nمنهم: الزّهريّ، ومحمد بن إسحاق، والواقدي، وابن سعد، وابن معين، وابن عبد البر والسمعاني. قال ابن عبد البر: «ولا يصح شهوده بدرًا». وقال البخاريّ: «شهد بدرًا». واختاره أبو عبيد القاسم بن سلام، وبه جزم مسلم، انظر: طبقات ابن سعد ٦/ ١٦.\nانظر: المحاسن ٥٧٠.\nبفتح الدال المشددة انظر: الأنساب ٢/ ٥١٣.\nبفتح الهاء وسكون الميم، انظر تاج العروس ٩/ ٣٤٧."}],[1860,"- إبراهيمُ بنُ يزيدَ الخُوزيُّ (١) لَيْسَ مِنَ الخُوزِ إنّما نَزَلَ شِعْبَ الخُوزِ بمكَّةَ."],[1861,"- عَبْدُ الملكِ بنُ أبي سُلَيمانَ العَرْزَميُّ نَزَلَ جَبَّانَةَ (٢) عَرْزَمٍ بالكُوفةِ وَهِيَ قَبِيْلَةٌ معدودةٌ فِي فَزَارةَ فقِيلَ عَرْزَميٌّ (٣)، بتقديم الراءِ المهملةِ عَلَى الزّاي."],[1862,"- مُحَمَّدُ بنُ سِنَانٍ العَوَقيُّ (٤) أَبُو بَكْرٍ البَصْريُّ باهليٌّ، نَزَلَ فِي العَوَقَةِ - بالقافِ والفتحِ - وهُمْ بَطْنٌ منْ عَبْدِ القَيْسِ، فنُسِبَ إليهم."],[1863,"- أَحْمَدُ بنُ يوسُفَ السُّلَميُّ جليلٌ، رَوَى عَنْهُ مُسْلِمٌ وغَيْرُهُ: هُوَ أَزْدِيٌّ عُرِفَ بالسُّلَمِيِّ؛ لأنَّ أُمَّهُ كَانَتْ سُلَميَّةً ثَبَتَ ذَلِكَ عَنْهُ (٥)."],[1864,"- وأبو عَمْرِو بنُ نُجَيْدٍ (٦) السُّلَمِيُّ كَذلِكَ، فإنّهُ حَافِدُهُ (٧). وأبو عبدِ الرحمانِ السُّلَميُّ مُصَنِّفُ الكُتبِ للصُّوفيَةِ: كَانَتْ أمُّهُ ابنةَ أبي عَمْرٍو المذكورِ فنُسِبَ سُلَمِيًّا وَهُوَ أَزْديٌّ أَيْضًَا جدُّهُ ابنُ عَمِّ أَحْمَدَ بنِ يوسفَ."],[1865,"وَيقْرُبُ منْ ذَلِكَ ويلتحقُ بِهِ مِقْسَمٌ مَوْلَى ابنِ عَبَّاسٍ هُوَ مَوْلَى عبدِ اللهِ بنِ الحارثِ بنِ نَوْفَلٍ (٨) لَزِمَ ابنَ عَبَّاسٍ، فقِيْلَ لَهُ مَوْلَى ابنِ عَبَّاسٍ، لِلُزومِهِ إيَّاهُ."],[1866,"- يَزِيدُ الفَقِيرُ (٩) أَحَدُ التابعينَ وُصِفَ بِذَلِكَ؛ لأَنَّهُ أُصِيبَ فِي فَقَارِ ظَهْرِهِ (١٠)، فكانَ يألمُ مِنْهُ حَتَّى يَنْحَنِي لَهُ.","",{"fn":"بضم الخاء المعجمة وبالزاء. الإرشاد ٢/ ٧٥٩، والمقنع ٢/ ٦٣٠.\nجبّانة: بالفتح، ثمّ التشديد، والجبان في الأصل الصحراء، وأهل الكوفة يسمون المقبرة الجبانة. وبالكوفة محال تسمّى بها، فمنها جبّانة كندة ... وجبانة عرزم ...». مراصد الاطلاع ١/ ٣١٠.\nبفتح العين المهملة، وإسكان الراء، بعدها زاي مفتوحة. الإرشاد ٢/ ٧٥٩.\nبفتح العين والواو وبالقاف. الإرشاد ٢/ ٧٥٩، والمقنع ٢/ ٦٣١.\nتهذيب الكمال ١/ ٩١، وقد ذكره السمعاني في الأنساب ٣/ ٣٠٢ ولم يبين ذلك.\nبضم النون وفتح الجيم. انظر: الإكمال ١/ ١٨٨.\nفي (ب): «فإنه في حفيده». والحافد والحفيد: ولد الولد. انظر: المعجم الوسيط ١/ ١٨٤.\nانظر: الطبقات لابن سعد ٥/ ٢٩٥، والتاريخ الكبير ٨/ ٣٣ (٢٠٥٧).\nبفتح الفاء بعدها قاف، قيل له ذلك؛ لأنه كان يشكو فقار ظهره. التقريب (٧٧٣٣).\nفي القاموس مع شرحه التاج ١٣/ ٣٣٧: «الفقير: الكسير الفقار». وانظر: نزهة الألباب ٢/ ٧٢، والإكمال ٧/ ٦٩، والتقريب (٧٧٣٣)."}],[1867,"- خالدُ الحَذَّاءُ (١) لَمْ يَكُنْ حَذَّاءً ووُصِفَ بِذَلِكَ لجلوسِهِ فِي الحذَّائينَ (٢)، واللهُ أعلمُ."],[1868,"النوع التاسع والخمسون معرفة المبهمات"],[1869,"(٣)"],[1870,"أيْ مَعْرِفَةُ أسماءِ مَنْ أُبهِمَ ذِكْرُهُ فِي الحَدِيْثِ مِنَ الرِّجَالِ والنِّساءِ. وصنَّفَ فِي ذَلِكَ عَبْدُ الغَنِيِّ بنُ سَعيدٍ الحافظُ (٤) والخطيبُ (٥) وغيرُهما (٦). ويُعرَفُ ذَلِكَ بورودِهِ مُسَمًّى فِي بعضِ الرواياتِ، وكثيرٌ مِنْهُمْ لَمْ يُوقَفْ عَلَى أسمائِهم. وَهُوَ عَلَى أقسامٍ:"],[1871,"مِنْها: -وَهُوَ منْ أَبْهمِهَا- مَا قِيلَ فِيهِ: «رَجُلٌ» أَوْ «امرَأَةٌ». ومنْ أمثِلَتِهِ: حَدِيثُ ابنُ عَبَّاسٍ - رضي الله عنه - أَنَّ رجُلًا قَالَ: يا رَسُوْلَ اللهِ! الحَجُّ كُلَّ عامٍ (٧)؟ وهذا الرجُلُ هُوَ الأقرعُ ابنُ حابِسٍ بَيَّنَهُ ابنُ عَبَّاسٍ فِي رِوَايَةٍ أُخرَى (١). حَدِيثُ أبي سَعِيدٍ الخُدْريِّ فِي ناسٍ (٢) مِنْ أصْحابِ رَسُوْلِ اللهِ - صلى الله عليه وآله وسلم - مَرُّوا بِحيٍّ فَلَمْ يُضَيِّفُوهُمْ فلُدِغَ سيِّدُهُمْ فَرَقَاهُ رَجُلٌ مِنْهُمْ بفاتِحةِ الكتابِ عَلَى ثلاثينَ شاةً، الحَدِيْثَ (٣). الرَّاقِي هُو الراوِي أبو سَعيدٍ","",{"fn":"بفتح المهملة وتشديد الذال المعجمة. التقريب (٣٥٣).\nكذا في نزهة الألباب ١/ ١٩٧، وفي الأنساب ٤/ ٩٦: «يقال إنه ما حذا نعلًا قط ولا باعها، ولكنه تزوج امراة فنزل عليها في الحذائين فنسب إليها».\nانظر في ذلك: الإرشاد ٢/ ٧٦٢ - ٧٦٨، والتقريب: ١٩٢ - ١٩٣، والمنهل الروي: ١٣٦، واختصار علوم الحديث: ٢٣٦ - ٢٣٧، والشذا الفياح ٢/ ٧٠٣ - ٧١٢، والمقنع ٢/ ٦٣٢ - ٦٤٣، وشرح التبصرة ٣/ ٢٢٨ - ٢٣٧، وفتح المغيث ٣/ ٢٧٤ - ٢٧٨، وتدريب الراوي ٢/ ٣٤٢ - ٣٤٨، وشرح السيوطي على ألفية العراقي: ٢٥٨، وفتح الباقي ٣/ ٢٣٠ - ٢٣٣، وتوضيح الأفكار ٢/ ٤٩٧ - ٤٩٨.\nاسم كتابه: \" الغوامض والمبهمات \" توجد منه نسخة خطية. انظر: الفهرس الشامل ٢/ ١١٣٥.\nاسم كتابه: \" الأسماء المبهمة في الأنباء المحكمة \" وقد طبع.\nمنهم: ابن بشكوال، واسم كتابه: \" غوامض الأسماء المبهمة الواقعة في متون الأحاديث المسندة \"، وقد طبع. قال العراقي في شرح التبصرة ٣/ ٢٢٨: «وهو أكبر كتاب» وقال ابن الملقن في المقنع ٢/ ٦٣٢: «وأكثر من جمع فيه».\nالرّواية المبهمة أخرجها الطيالسيّ (٢٦٦٩)، وأحمد ١/ ٢٩٢ و٣٠١ و٣٢٣ و٣٢٥، والدارمي (١٧٩٦)، وابن الجارود (٤١٠)، والدارقطني ٢/ ٢٨١، والخطيب في الأسماء المبهمة: ١٣، وابن بشكوال في الغوامض ٢/ ٥٢٧."}],[1872,"الخُدْرِيُّ (٤). حَدِيثُ أنسٍ أَنَّ رَسوْلَ اللهِ - صلى الله عليه وآله وسلم - رَأى حَبْلًا مَمْدُودًا بَيْنَ سَارِيَتَيْنِ فِي المَسْجِدِ، فسألَ عَنْهُ فقالوا: «فلانةُ تُصَلِّي فإذا غُلِبَتْ تَعَلَّقَتْ بِهِ» (٥). قِيلَ: إنّها زَيْنَبُ بنتُ جَحْشٍ (٦) زوجُ (٧) رَسُوْلِ اللهِ - صلى الله عليه وآله وسلم -، وَقِيلَ: أختُها حَمْنةُ بنتُ جَحْشٍ (٨)، وَقِيلَ: مَيْمُونةُ بنتُ الحارثِ أمُّ المؤمنينَ (٩). المرأةُ الَّتِي سألتْ رَسُوْلَ اللهِ - صلى الله عليه وآله وسلم - عنِ الغُسْلِ مِنَ الحَيْضِ فَقَالَ: «خُذِي فِرْصَةً (١) مِنْ مَِسْكٍ ...» (٢) هِيَ أسماءُ بنتُ يزيدَ بنِ السَّكَنِ الأَنْصاريّةُ وَكَانَ (٣) قَالَ لها: خَطِيبةُ النِّساءِ. وَفِيْ رِوَايَةٍ لمسلمٍ (٤) تَسْميتُها: أسماءُ بنتُ شَكَلٍ، واللهُ أعلمُ.","",{"fn":"هذه الرّواية أخرجها ابن أبي شيبة ٤/ ٨٥، وأحمد ١/ ٢٥٥ و٢٩٠ و٣٥٢ و٣٧٠ و٣٧١، وعبد بن حميد (٦٧٧)، والدارمي (١٧٩٥)، وأبو داود (١٧٢١)، وابن ماجه (٢٨٨٦)، والنّسائيّ ٥/ ١١١، والدارقطني ٢/ ٢٧٩ و٢٨٠، والحاكم ١/ ٤٤١، والبيهقي ٤/ ٣٢٦، والخطيب في الأسماء المبهمة: ١٣، وابن بشكوال ٢/ ٥٢٧ - ٥٢٨، والمزي في التهذيب ٣٢/ ٨٧.\nفي (ج): «أناس».\nأخرجه البخاريّ ٣/ ١٢١ (٢٢٧٦) و٦/ ٢٣١ (٥٠٠٧) و٧/ ١٧٠ (٥٧٣٦) و١٧٣ (٥٧٤٩)، ومسلم ٧/ ١٩ (٢٢٠١) (٦٥) و٢٠ (٢٢٠١) (٦٦)، وأبو داود (٣٤١٩)، وابن ماجه (٢١٥٦)، والترمذي (٢٠٦٣) و(٢٠٦٤)، والنّسائيّ في الكبرى (٧٥٢٣).\nانظر تعقب الحافظ العراقي في التقييد: ٤٢٧ - ٤٢٨ على المصنف.\nأخرجه البخاريّ ٢/ ٦٧ (١١٥٠)، ومسلم ٢/ ١٨٩ (٧٨٤)، وأبو داود (١٣١٢)، وابن ماجه (١٣٧١)، والنّسائيّ ٣/ ٢١٨، وابن خزيمة (١١٨٠)، وأبو عوانة ٢/ ٣٢٤، وابن حبان (٢٤٨٣)، والبغوي (٩٤٢).\nالوارد في الحديث أنها زينب فقط، ولم يحدد ذلك، ولم يرد تحديدها في شيءٍ من طرق الحديث، وقيل ورد تحديدها بأنها زينب بنت جحش عند ابن أبي شيبة ولم يوجد ذلك، قال الحافظ ابن حجر: «ولم أر ذلك في شيءٍ من الطرق صريحًا. ووقع في شرح الشّيخ سراج الدين ابن الملقن أن ابن أبي شيبة رَوَاهُ كذلك، لكني لم أر في مسنده ومصنفه زيادة على قوله «قالوا لزينب». الفتح ٣/ ٣٦ وبنحو قول الحافظ ابن حجر قال العيني في \" عمدة القاري \" ٧/ ٢٠٨.\nفي (ب) و(م): (النّبيّ).\nهي في مسند الإمام أحمد ٣/ ١٨٤ و٢٥٦، وسنن أبي داود (١٣١٢)، ومسند أبي يعلى (٣٨٣١).\nأخرج هذه الرّواية ابن خزيمة (١١٨١)، وقد حكم بشذوذها الحافظ ابن حجر في الفتح ٣/ ٣٦."}],[1873,"ومنها: مَا أُبهمَ بأنْ قِيلَ فِيهِ: «ابنُ فلانٍ»، أَوْ: «ابنُ الفلانِيِّ»،"],[1874,"أَوْ: «ابنةُ فلانٍ»، أَوْ نحوُ ذَلِكَ. منْ ذَلِكَ حَدِيثُ أمِّ عَطِيَّةَ: ماتَتْ إحدَى (٥) بناتِ رَسُوْلِ اللهِ - صلى الله عليه وآله وسلم - فَقَالَ: «اغْسِلْنَها بماءٍ وسِدْرٍ ... الحَدِيْثَ» (٦)، هِيَ زَيْنَبُ زوجةُ أبي العاصِ (٧) بنِ الرَّبيعِ أكبرُ بَنَاتِهِ - صلى الله عليه وآله وسلم -، وإنْ كَانَ قَدْ قِيلَ: أكبرُهُنَّ رُقَيَّةُ،"],[1875,"واللهُ أعلمُ.","",{"fn":"في نسخة (ب) حاشية نصها: (الفرصة -بكسر الفاء- هي القطعة، وروي من مسك -بفتح الميم-، والكسر أصح، والله أعلم». قلنا: قال في النهاية ٣/ ٤٣١: «الفرصة - بكسر الفاء -: قطعة من صوف، أو قطن، أو خرقة»، أما كلمة مسك فانظر في ضبطها: فتح الباري ١/ ٤١٤ - ٤١٥.\nأخرجه البخاريّ ١/ ٨٥ (٣١٤)، و١/ ٨٦ (٣١٥) و٩/ ١٣٤ (٧٣٥٧)، ومسلم ١/ ١٧٩ (٣٣٢) (٦٠).\nفي (ج) و(م): «فكان».\nصحيح مسلم ١/ ١٧٩ - ١٨٠ (٣٣٢) (٦١)، وانظر: غوامض الأسماء المبهمة ١/ ٤٦٩ - ٤٧٠، وشرح التبصرة ٣/ ٢٣٠.\nساقطة من (ع).\nأخرجه مالك (٥٩٢)، والحميدي (٣٦٠)، وأحمد ٥/ ٨٤ و٦/ ٤٠٧، والبخاري ٢/ ٩٣ (١٢٥٣) و٢/ ٩٤ (١٢٥٨) و٢/ ٩٥ (١٢٦٣)، ومسلم ٣/ ٤٧ (٩٣٩) (٣٦)، وأبو داود (٣١٤٢) و(٣١٤٦)، وابن ماجه (١٤٥٨)، والترمذي (٩٩٠)، والنّسائيّ ٤/ ٢٨ و٣١ و٣٢ و٣٣، وابن الجارود (٥١٨) و(٥١٩)، وابن حبان (٣٠٢٨) و(٣٠٢٩)، وطبعة الرسالة (٣٠٣٢) و(٣٠٣٣)، والطبراني في الكبير ٢٥/ حديث\nفي (م): «العاصي».\nو(٨٨) و(٨٩) و(٩٠) و(٩١) و(٩٣) و(٩٤) و(٩٥) و(٩٦) و(٩٩) و(١٦٦)، والبيهقي ٣/ ٣٨٩، والبغوي (١٤٧٢)."}],[1876,"- ابنُ اللُّتْبِيَّةِ: ذَكَرَ صاحبُ \"الطبقاتِ\" مُحَمَّدُ بنُ سَعْدٍ أَن اسْمَهُ عَبْدُ اللهِ (١) وهذهِ نِسْبةٌ إلى بنِي لُتْبٍ - بضمِّ اللامِ وإسكانِ التاءِ المُثنَّاةِ مِنْ فَوْقُ - بَطْنٌ مِنَ الأسْدِ -بإسكانِ السينِ- وهُمْ الأزدُ (٢)، وَقِيلَ فِيهِ: ابنُ الأُتْبِيَّةِ بالهمزةِ ولاَ صِحَةَ لَهُ."],[1877,"- ابنُ مِرْبَعٍ الأَنْصَاريُّ الذي أرْسَلَهُ رَسُوْلُ اللهِ - صلى الله عليه وآله وسلم - إلى أَهْلِ عَرَفَةَ (٣) وَقَالَ: «كُونُوا عَلَى مَشَاعِرِكُمْ» (٤)، اسمُهُ زَيْدٌ. وَقَالَ الواقديُّ، وكاتِبُهُ ابنُ سَعْدٍ: اسمُهُ عبدُ اللهِ."],[1878,"- ابنُ أُمِّ مَكْتُومٍ الأَعْمَى (٥) المُؤَذِّنُ: اسمُهُ عَبْدُ اللهِ بنُ زائدةَ، وَقِيلَ: عَمْرو بنُ قَيْسٍ، وَقِيلَ: غَيْرُ ذَلِكَ. وأمُّ مَكْتُومٍ اسمُها: عاتِكَةُ بنتُ عَبْدِ اللهِ."],[1879,"الابنةُ التي أرادَ بنُو هِشَامِ بنِ المُغيرةِ أنْ يُزَوِّجُوهَا منْ عَلِيِّ بنِ أبي طالبٍ - رضي الله عنه - هِيَ العَوْراءُ بنتُ أبي جَهْلِ بنِ هِشَامٍ (٦)، واللهُ أعلمُ."],[1880,"ومنها: العَمُّ والعَمَّةُ ونحوُهما: منْ ذَلِكَ رَافِعُ بنُ خَدِيجٍ (٧) عَنْ عَمِّهِ فِي حَدِيثِ المُخَابَرَةِ (٨)، عمُّهُ هُوَ ظُهَيرُ بنُ رَافِع الحارثيُّ الأنْصَارِيُّ. زيادُ بنُ عِلاَقةَ (٩)، عَنْ عَمِّهِ: هُوَ قُطْبةُ بنُ مَالِكٍ الثَّعْلبيُّ بالثاءِ المثلثةِ. عَمَّةُ جابرِ بنِ عَبْدِ اللهِ التي جَعَلَتْ تَبْكِي أباهُ يومَ أُحدٍ (١) اسمُها: فاطمةُ بنتُ عَمْرِو بنِ حَرَامٍ (٢) وَسمَّاها الواقديُّ هِنْدًا (٣)، واللهُ أعلمُ.","",{"fn":"هو عبد الله بن اللتبية الأزدي الذي استعمله النّبيّ - صلى الله عليه وآله وسلم - على الصدقة. انظر تجريد أسماء الصّحابة ١/ ٣٣٢ (٣٥١١)، والثقات ٣/ ٢٣٨.\nانظر: التاج ٧/ ٣٨٢.\nانظر: التقييد: ٤٢٩.\nأخرجه الحميدي (٥٧٧)، وأحمد ٤/ ١٣٧، وأبو داود (١٩١٩)، وابن ماجه (٣٠١١)، والترمذي (٨٨٣)، والنّسائيّ ٥/ ٢٥٥، وابن خزيمة (٢٨١٨) و(٢٨١٩).\nانظر: التقييد: ٤٣٠.\nبعد هذا في (ع): «ابن المغيرة» ولم ترد في النسخ ولا (م).\nأوله خاء معجمة مفتوحة - انظر: الإكمال ٢/ ٣٩٨.\nصحيح البخاريّ ٣/ ١٤١ (٢٣٣٩)، وصحيح مسلم ٥/ ٢٣. والمخابرة: قال ابن الأثير: «قيل: هي المزارعة على نصيب معيّن كالثلث والرّبع وغيرهما». النهاية ٢/ ٧، وانظر الأقوال الأخرى في تفسيرها: التهذيب للبغوي ٤/ ٤٧٦، وتهذيب الأسماء واللغات ٣/ ٨٧، وتاج العروس ١١/ ١٢٨.\nبكسر المهملة وبالقاف. التقريب (٢٠٩٢)."}],[1881,"ومنها: الزَّوجُ والزَّوْجَةُ: منْ ذَلِكَ: حَدِيثُ (٤) سُبَيْعَةَ الأسلميِّةَ أَنَّها وَلَدَتْ بَعْدَ وفاةِ زوجِها بليالٍ، زَوجُها (٥): هُوَ سَعْدُ بنُ خَوْلَةَ (٦) الذي رَثَى لَهُ"],[1882,"رَسُوْلُ اللهِ - صلى الله عليه وآله وسلم - أنْ ماتَ بمكَّةَ وَكَانَ بَدْريًا (٧). بَرْوَعُ (٨) بنتُ وَاشِقٍ وَهِيَ بفتحِ الباءِ عِنْدَ أَهْلِ اللُّغةِ (٩) وشاعَ فِي ألسنةِ أَهْلِ الحَدِيْثِ كَسْرُها، زَوْجُها اسمُهُ هِلاَلُ بنُ مُرَّةَ الأشجعيُّ عَلَى مَا رُوَّيناهُ منْ غَيْرِ وَجْهٍ. زوجةُ عَبْدِ الرحمان بنِ الزَّبَيْرِ - بفتح الزّاي - التي كانتْ تَحْتَ رِفَاعَةَ بنِ سَمْوَالٍ (١٠) القُرَظيِّ فَطَلَّقها. اسمُها تَمِيْمَةُ بنتُ وَهْبٍ، وَقِيلَ: تُمَيْمَةُ - بضمِّ التاءِ - وَقِيلَ: سُهَيْمَةُ، واللهُ أعلمُ.","",{"fn":"أخرجه الحميدي (١٢٦١)، وأحمد ٣/ ٣٠٧، والبخاري ٢/ ٩١ (١٢٤٤) و٢/ ١٠٢ (١٢٩٣) و٤/ ٢٦ (٢٨١٦) و٥/ ١٣١ (٤٠٧٩)، ومسلم ٧/ ١٥٢ (٢٤٧١) (١٣٠)، والنّسائيّ ٤/ ١١ و١٣.\nانظر: شرح التبصرة والتذكرة ٣/ ٢٣٤، والتعليق عليه.\nانظر: مغازيه ١/ ٢٦٦، والإشارات إلى بيان الأسماء المبهمات: ٥٩٧.\nصحيح مسلم ٤/ ٢٠٠ - ٢٠١ (١٤٨٤).\nهذه الكلمة سقطت من (م).\nوهكذا سمي في سنن أبي داود (٢٣٠٦).\nالإصابة ٢/ ٢٤.\nقبل هذا في (ع): «زوج». لم ترد في النسخ ولا في (م) ولا الشذا ولا التقييد.\nانظر: الصحاح ٣/ ١١٨٣، وتهذيب الأسماء واللغات ٢/ ٣٣٢، ولسان العرب ٨/ ٨، وتاج العروس ٢٠/ ٣١٨.\nهكذا في جميع النسخ و(ع) والتقييد، وفي (م) والشذا (سموأل) بعد الواو همزة. وما في النسخ الخطية و(ع) والتقييد مثله في الموطأ (١٥١٦)، وجامع الأصول ١١/ ٥٠٠، وتهذيب الأسماء واللغات ١/ ١٩١، وتجريد أسماء الصحابة ١/ ١٨٤. وما في (م) والشذا مثله في تهذيب الكمال ٣/ ١٥، والإصابة ١/ ٥١٨. وهذا الاسم اختلف في ضبطه، قال في أوجز المسالك ٩/ ٣٧٥: «اختلف في ضبطه، فقال النّوويّ في تهذيبه بسين مهملة تفتح وتكسر ثمّ ميم ساكنة، وهكذا في الزرقاني بكسر السين وإسكان الميم. وضبطه الحافظ في الفتح: سموأل بفتح المهملة والميم وسكون الواو وبعدها همز ثمّ لام» ="}],[1883,"النوع الموفي ستين معرفة تواريخ الرواة"],[1884,"(١)"],[1885,"وفيها مَعْرِفَةُ وَفَياتِ الصَّحَابَةِ والمُحَدِّثِيْنَ والعلماءِ ومواليدِهم، ومقادِيرُ أعمارِهم ونحوِ ذَلِكَ."],[1886,"رُوِّيْنَا عَنْ سُفْيَانَ الثوريِّ أَنّهُ قَالَ: «لَمَّا استعملَ الرُّواةُ الكذبَ، استَعْمَلْنا لَهُمُ التاريخَ» (٢) أَوْ كَمَا قَالَ (٣). ورُوِّينا عَنْ حَفْصِ بنِ غِياثٍ أنَّهُ قَالَ: «إذَا اتَّهمتُمُ الشَّيْخَ فحاسِبُوهُ بالسِّنَّيْنِ» (٤) يعني: احْسِبُوا سِنَّهُ وسِنَّ مَنْ كَتَبَ عَنْهُ. وهذا كنحوِ مَا رُوِّيناهُ عَنْ إِسْمَاعِيْلَ بنِ عَيَّاشٍ قَالَ: «كنتُ بالعراقِ فأتاني أَهْلُ الحَدِيْثِ، فقالوا: هاهنا رَجُلٌ يحدِّثُ عَنْ خالدِ بنِ مَعْدَانَ فأتيتُهُ فقلْتُ: أيَّ سنةٍ كتبتَ عَنْ خالدٍ بنِ مَعْدانَ؟ فَقَالَ: سنةَ ثلاثَ عَشْرَةَ يَعْنِي ومئةٍ، فقلْتُ: أنتَ تَزعُمُ أنَّكَ سَمِعْتَ مِنْ خالدِ بنِ مَعْدَانَ بَعْدَ مَوْتِهِ بسَبْعِ سِنينَ: قَالَ إِسْمَاعِيْلُ: «ماتَ خالدٌ سَنةَ سِتٍّ ومئةٍ» (١). قلتُ: وَقَدْ رُوِّينا عَنْ عُفَيْرِ بنِ مَعْدَانَ قِصَّةً نحوَ هذِهِ جَرَتْ لَهُ مَعَ بَعْضِ مَنْ حَدَّثَ عَنْ خالدِ مَعْدَانَ ذَكَرَ عُفَيْرٌ فِيْهَا (٢) أَنَّ خالدًا ماتَ سَنَةَ أَرْبعٍ ومئةٍ (٣).","",{"fn":"انظر في ذلك: معرفة علوم الحديث: ٢٠٢ - ٢١٠، والإرشاد ٢/ ٧٦٩ - ٧٨١، والتقريب: ١٩٤ - ١٩٧، والمنهل الروي ١٤٥، واختصار علوم الحديث: ٢٣٧ - ٢٤٢، والشذا الفياح ٢/ ٧١٣ - ٧٣٨، والمقنع ٢/ ٦٤٤ - ٦٥٦، وشرح التبصرة والتذكرة ٣/ ٢٣٧، وفتح المغيث ٣/ ٢٨٠ - ٣١٣، وتدريب الراوي ٢/ ٣٤٩ - ٣٦٧، وشرح ألفية السيوطي عَلَى ألفية العراقي: ٢٦٢، وفتح الباقي ٣/ ٢٣٤ - ٢٥٩، وتوضيح الأفكار ٢/ ٤٩٨ - ٥٠٠، وظفر الأماني: ١٠٤.\nأسنده ابن عدي في مقدمة الكامل ١/ ١٦٩، ومن طريقه الخطيب في الكفاية: (١٩٣ت، ١١٩هـ).\nجملة: «أو كما قال» ساقطة من (م).\nأسنده الخطيب في الكفاية (١٩٣ ت، ١١٩ - ١٢٠ هـ). قال الحافظ العراقي في شرح التبصرة ٣/ ٢٣٨: «بالسنين: بفتح النون المشددة تثنية سنٍّ، وهو العمر» وكذا في حاشية إحدى نسخ المقنع الخطية ٢/ ٦٤٤ وفتح المغيث ٣/ ٢٣٨."}],[1887,"ورُوِّينا عنِ الحاكمِ أبي عَبْدِ اللهِ قَالَ: «لما قَدِمَ عَلَينا أَبُو جَعْفرٍ مُحَمَّدُ بنُ حاتِمٍ الكَشِّيُّ (٤) وحَدَّثَ عَنْ عَبْدِ بنِ حُمَيْدٍ سألتُهُ عَنْ مَوْلدِهِ فَذَكَرَ أنَّهُ وُلِدَ سنةَ ستِّين ومئتَينِ، فَقُلتُ لأصحابِنا: سَمِعَ هَذَا الشَّيْخُ منْ عَبْدِ بنِ حُمَيْدٍ بَعْدَ مَوْتِهِ بثلاثَ عَشْرَةَ سَنةً» (٥)."],[1888,"وَبَلَغَنا عَنْ أبِي عَبْدِ اللهِ الحُمَيْديِّ الأندلسيِّ أَنَّهُ قَالَ مَا تَحْرِيرُهُ: «ثلاثةُ أشياءَ مِنْ عُلومِ الحَدِيْثِ يجبُ تقديمُ التَّهَمُّمِ (٦) بها: العِلَلُ، وأحسَنُ كتابٍ وُضِعَ فِيهِ \" كتابُ الدَّارَقُطْنِيِّ \"؛ والمؤتَلِفُ والمُخْتلِفُ (٧)، وأحسَنُ كتابٍ وُضِعَ فِيهِ \" كتابُ ابنِ مَاكُوْلاَ \"؛ وَوَفَيَاتُ الشُّيوخِ، وليسَ فِيهِ كتابٌ."],[1889,"قلتُ: فِيْهَا غَيْرُ كِتَابٍ ولكنْ منْ غَيْرِ استقصاءٍ وتَعْمِيمٍ، وتواريخُ المُحَدِّثِيْنَ مُشْتَمِلَةٌ عَلَى ذِكْرِ الوَفَياتِ؛ ولذلكَ ونَحْوِهِ سُمِّيَتْ: تَوَارِيخَ. وأمَّا مَا فِيْهَا مِنَ الجَرْحِ والتَّعْديلِ ونحوِهما فَلا يُناسِبُ هَذَا الاسمَ، واللهُ أعلمُ.","",{"fn":"هذه الرّواية أخرجها الحاكم في المدخل ٦٠ - ٦١، والخطيب في الجامع ١/ ١٣٢.\nفي (م): «منها» وفي (ع): «فيهًا».\nأخرجها يعقوب بن سفيان في المعرفة ١/ ١٥٢، والخطيب في الكفاية (١٩٢ - ١٩٣ ت، ١١٩ هـ).\nبفتح الكاف والشين المشددة المعجمة، نسبة إلى قرية قريبة من سمرقند ويقال أيضًا: بكسر الكاف والسين المهملة المشددة، غير أن المشهور الأول. انظر: الأنساب ٤/ ٦٢٥و ٦٣٢، ومراصد الاطلاع ٣/ ١١٦٥ و١١٦٧، وتاج العروس ١٧/ ٣٦٣.\nالمدخل إلى الإكليل ٦١، والجامع في آداب الرّاوي ١/ ١٣٢.\nفي (ب) و(ع): «التهم» والمثبت من باقي النسخ و(م) والتقييد والشذا، ومثله في المقنع ٢/ ٦٤٥، وشرح التبصرة ٣/ ٢٣٩. والتهمّم: الطّلب، يقال: ذهبت أتهمّمه، أي: أطلبه، وتهمّم الشيء: طلبه، أو الاهتمام والعناية، يقال: اهتمّ الرجل بالأمر: عني بالقيام به. انظر: اللسان ١٢/ ٦٢٢، والمعجم الوسيط ٢/ ٩٩٥ وحاشية محاسن الاصطلاح: ٥٧٨.\nهكذا في النسخ و(ع) والتقييد والشذا، وفي (م): «المؤتلف والمختلف» بلا واو."}],[1890,"ولنذكُرْ مِنْ ذَلِكَ عُيُونًا:"],[1891,"أحدُها: الصَّحِيحُ فِي سِنِّ سَيِّدِنا سَيِّدِ البَشَرِ رَسُوْلِ اللهِ - صلى الله عليه وآله وسلم - وصاحِبَيْهِ: أبي بكرٍ وعُمَرَ، ثلاثٌ وسِتُّونَ سَنَةً (١). وقُبِضَ (٢) - صلى الله عليه وآله وسلم - يومَ الاثنَينِ (٣) ضُحَىً لاثنتي عَشْرَةَ ليلةً خَلَتْ منْ شَهْرِ رَبِيعٍ الأَوَّلِ سَنَةَ إحدَى عَشْرَةَ مِنَ الهَجْرةِ. وتُوُفِّيَ أَبُو"],[1892,"بَكْرٍ (٤) فِي جُمَادَى الأولَى سَنَةَ ثلاثَ عَشْرَةَ. وعُمَرُ فِي ذي الحِجَّةِ سنةَ ثلاثٍ وعشرينَ. وعُثمانُ فِي ذي الحِجَّةِ سنةَ خَمْسٍ وثلاثينَ وَهُوَ ابنُ اثنتين وثمانينَ سنةً، وَقِيلَ: ابنُ تِسعينَ، وَقِيلَ غيرُ ذَلِكَ (٥). وعَلِيٌّ: فِي شهرِ رمضانَ سنةَ أربعينَ وَهُوَ ابنُ ثلاثٍ وستينَ، وَقِيلَ: ابنُ أربعٍ وستينَ، وَقِيلَ: ابنُ خمسٍ وستينَ (٦). وطَلْحةُ والزُّبَيْرُ جميعًا فِي جُمَادَى الأُولى سنةَ ستٍّ وثلاثينَ، ورُوِّينا عنِ الحَاكِمِ أبي عَبْدِ اللهِ أَنَّ سِنَّهما كَانَ واحدًا، كانا ابْنَي أربعٍ وستينَ (٧)، وَقَدْ قِيلَ غَيْرُ مَا ذَكَرَهُ الحاكمُ. وسَعْدُ بنُ أبي وَقَّاصٍ (٨) سنةَ خمسٍ وخمسينَ عَلَى الأصحِّ وَهُوَ ابنُ ثلاثٍ وسبعينَ سنةً. وسعيدُ بنُ زَيْدٍ (٩) سنةَ إحْدَى وخمسينَ وَهُوَ ابنُ ثلاثٍ أَوْ أربعٍ وسبعينَ. وعبدُ الرحمانِ بنُ عَوْفٍ سنةَ اثنتين وثلاثينَ وَهُوَ ابنُ خمسٍ وسبعينَ سنةً. وأبو عُبَيْدةَ بنُ الجرَّاحِ سنةَ ثماني عَشْرَةَ وَهُوَ ابنُ ثمانٍ وخمسينَ سنةً وَفِي بعضِ مَا ذكرْتُهُ خلافٌ لَمْ أذكُرْهُ، واللهُ أعلمُ.","",{"fn":"انظر: المحاسن: ٥٧٨.\nانظر: التقييد: ٤٣٣.\nفي (ع) والتقييد: «وقبض رسول الله يوم الاثنين». وما أثبتناه من جميع النسخ و(م).\nانظر: التقييد: ٤٣٥.\nانظر في ذلك الاستيعاب ٣/ ٨١.\nانظر: التاريخ الكبير ٦/ ٢٥٩، وتاريخ دمشق ٤٢/ ٥٧٠، وتهذيب الكمال ٥/ ٤٦١.\nمعرفة علوم الْحَدِيْث: ٢٠٣.\nانظر: التقييد: ٤٣٦، ومحاسن الاصطلاح: ٥٧٩.\nفي (ب): «يزيد» وهو مخالف لباقي النسخ ومصادر ترجمته."}],[1893,"الثَّانِي: شَخْصانِ (١) مِنَ الصَّحَابَةِ عَاشَا فِي الجاهليَّةِ سِتِّينَ سنةً، وَفِي الإسلام ستّينَ سنةً، ومَاتَا بالمدينةِ سنةَ أربعٍ وخمسينَ: أحدُهما: حَكِيمُ بنُ حِزَامٍ (٢) وَكَانَ مَوْلِدَهُ فِي جَوْفِ الكَعبةِ قَبْلَ عام الفيلِ بثلاثَ عَشْرَةَ سنةً. والثاني: حَسَّانُ بنُ ثابتِ بن المُنْذِرِ ابنِ حَرَامٍ (٣) الأنصاريُّ، وَرَوى ابنُ إسحاقَ أنّهُ وأَباهُ ثابتًا والمُنْذِرَ وحَرَامًا عاشَ كُلُّ واحدٍ مِنْهُمْ عشرينَ ومئةَ سنةٍ (٤). وذكر أَبُو نُعَيْمٍ الحافظُ أَنَّهُ لا يُعرَفُ في العَرَبِ مثلُ ذلكَ لغيرِهم. وَقَدْ قِيلَ: إِنَّ حَسَّانَ ماتَ سنةَ خمسينَ (٥)، واللهُ أعلمُ."],[1894,"الثَّالِثُ: أَصْحَابُ المَذَاهِبِ الخمسةِ المَتْبُوعةِ - رضي الله عنهم -:"],[1895,"فسُفْيَانُ (٦) بنُ سعيدٍ الثوريُّ أَبُو عَبْدِ اللهِ ماتَ بلا خلافٍ بالبَصْرةِ سنةَ إحدَى وسِتِّينَ ومئةٍ وَكَانَ مولِدُهُ سنةَ سبعٍ وتسعينَ (٧)."],[1896,"ومالكُ بنُ أنسٍ - رضي الله عنه - تُوُفِّيَ بالمدينةِ سنةَ تسعٍ وسبعينَ ومئةٍ قبلَ الثمانينَ بسنةٍ. واختُلِفَ فِي ميلادِهِ، فقِيلَ: فِي سنةِ ثلاثٍ وتسعينَ، وَقِيلَ: سنةَ إِحدَى، وَقِيلَ: سنةَ أربعٍ، وَقِيلَ: سنةَ سبعٍ (٨)."],[1897,"وأبو حَنَيْفَةَ -رحمه الله- ماتَ سنةَ خمسينَ ومئة ببغدادَ وَهُوَ ابنُ سبعينَ سنةً (٩)."],[1898,"والشافعيُّ - رحمه الله - ماتَ فِي آخرِ رَجَبٍ سنةَ أربعٍ ومئتينِ بِمِصْرَ وَوُلِدَ سنةَ خمسينَ ومئةٍ (١٠).","",{"fn":"انظر: التقييد: ٤٣٦.\nانظر: التاريخ الكبير ٣/ ١١، وسير أعلام النبلاء ٣/ ٤٤.\nبفتح المهملة والراء. التقريب (١١٩٧).\nوكذا قال التّرمذي في كتاب: تسمية أصحاب رسول الله - صلى الله عليه وآله وسلم - (١٢٤).\nانظر: محاسن الاصطلاح: ٥٨١.\nفي (م): «سفيان» من غير فاءٍ.\nانظر: طبقات ابن سعد ٦/ ٣٧١، وتاريخ بغداد ٩/ ٧١، وراجع محاسن الاصطلاح: ٥٨٣.\nانظر: سير أعلام النبلاء ٨/ ٣٠.\nالتاريخ الكبير ٨/ ٨١، وثقات ابن حبان ٩/ ٣١، وتاريخ بغداد ١٣/ ٤٢١.\nثقات ابن حبان ٩/ ٣١، تاريخ بغداد ٢/ ٧٠."}],[1899,"وأحمدُ بنُ مُحَمَّدِ بنِ حَنْبَلٍ ماتَ ببغدادَ فِي شَهْرِ ربيعٍ الآخرِ سنةَ إحدَى وأربعينَ ومئتينِ وَوُلِدَ سنةَ أربعٍ وستينَ ومئةٍ (١)، واللهُ أعلمُ."],[1900,"الرابعُ: أصحابُ كُتُبِ الحَدِيْثِ الخمسةِ المُعتَمَدَةِ - رضي الله عنهم -. فالبخاريُّ أَبُو عَبْدِ اللهِ وُلِدَ يومَ الجُمُعةِ بَعْدَ صلاةِ الجُمعة لثلاثَ عَشْرَةَ خَلَتْ منْ شَوَّالٍ سنةَ أربعٍ وتسعينَ ومئةٍ وماتَ بِخَرْتَنْكَ (٢) قريبًا منْ سَمَرْقَنْدَ (٣) ليلةَ عيدِ الفِطْرِ سنةَ ستٍ وخمسينَ ومئتينِ فكانَ (٤) عُمُرُهُ اثنتينِ وستينَ سنةً إلاَّ ثلاثةَ عَشَرَ يومًا (٥)."],[1901,"وَمُسْلِمُ بنُ الحَجَّاجِ النَّيْسابوريُّ (٦) ماتَ بها لخَمْسٍ بَقِينَ منْ رَجَبٍ سنةَ إحْدَى وستينَ ومئتينِ وَهُوَ ابنُ خَمْسٍ وخمسينَ سنةً (٧)."],[1902,"وأبو داودَ السِّجِسْتانيُّ سُليمانُ بنُ الأشْعَثِ ماتَ بالبَصْرةِ فِي شَوَّالٍ سَنَةَ خَمْسٍ وسبعينَ ومئتينِ (٨)."],[1903,"وأبو عيسى مُحَمَّدُ بنُ عيسى السُّلَميُّ التِّرْمِذِيُّ ماتَ بها لثلاثَ عَشْرَةَ مَضَتْ منْ رَجَبٍ سنةَ تسعٍ وسبعينَ ومئتينِ (٩).","",{"fn":"انظر: تاريخ بغداد ٤/ ٤٢٢، ومحاسن الاصطلاح ٥٨٤.\nبالفتح ثمّ السكون، وفتح التاء المثناة من فوق ونون ساكنة وكاف. انظر: الأنساب ٢/ ٣٩١، ومعجم البلدان ٢/ ٣٥٦ وهي قرية بينها وبين سمرقند ثلاثة فراسخ. قال العراقي في شرح التبصرة ٣/ ٢٧٠: «ذكر ابن دقيق العيد في شرح الإلمام: أنها بكسر الخاء، والمعروف فتحها، وكذا ذكره السمعاني».\nبفتحتين. انظر: معجم البلدان ١/ ٧٤.\nفي (ج): «وكان».\nتاريخ بغداد ٢/ ٦، ووفيات الأعيان ٤/ ١٨٨، وسير أعلام النبلاء ١٢/ ٣٩١.\nانظر: التقييد ٤٣٨.\nانظر: تاريخ بغداد ١٣/ ١٠٣، وزاد المزي في تهذيب الكمال ٧/ ٩٧ قولًا آخر فقال: «ولد سنة أربع ومئتين» فعلى هذا يكون عمره سبعًا وسبعين سنة، وجزم الذهبي في العبر ٢/ ٢٣ بأنه عاش ستين سنةً.\nتاريخ بغداد ٩/ ٥٦.\nوفيات الأعيان ٤/ ٢٧٨، سير أعلام النبلاء ١٣/ ٢٧٧."}],[1904,"وأبو عَبْدِ الرحمانِ أَحْمَدُ بنُ شُعَيْبٍ النَّسَويُّ (١) ماتَ سنةَ ثلاثٍ وثلاثِ مئةٍ (٢)، واللهُ أعلمُ."],[1905,"الخامِسُ: سَبعةٌ مِنَ الحُفَّاظِ فِي سَاقَتِهِمْ (٣) أحسَنُوا التَّصنيفَ وعَظُمَ الانتفاعُ بِتَصَانِيفِهِم فِي أعصارِنا."],[1906,"أَبُو الحَسَنِ عَلِيُّ بنُ عُمَرَ الدَّارَقُطْنِيُّ البَغْداديُّ ماتَ بها فِي ذي القَعْدةِ سنةَ خمسٍ وثمانينَ وثلاثِ مئةٍ وُلِدَ (٤) فِي ذي القعْدةِ سنةَ ستٍّ وثلاثِ مئةٍ (٥). ثُمَّ الحَاكِمُ أَبُو عبدِ اللهِ بنُ البَيِّعِ (٦) النَّيْسابوريُّ ماتَ بها فِي صَفَرٍ سَنَةَ خَمْسٍ وأربعِ مئةٍ، ووُلِدَ بها فِي شَهْرِ ربيعٍ الأَوَّلِ سنةَ إحدَى وعشرينَ وثلاثِ مئة (٧). ثُمَّ أَبُو مُحَمَّدٍ عَبْدُ الغنيِّ بنُ سعيدٍ الأزديُّ حافظُ مِصْرَ وُلِدَ فِي ذي القِعْدَةِ سنةَ اثنتينِ وثلاثينَ وثلاثِ مئةٍ، وماتَ بِمِصْرَ فِي صَفَرٍ سنةَ تسعٍ وأربعِ مئةٍ (٨). ثُمَّ أَبُو نُعَيْمٍ أَحْمَدُ بنُ عَبْدِ اللهِ الأصبهانيُّ الحافظُ وُلِدَ سنةَ أربعٍ وثلاثينَ وثلاثِ مئةٍ، وماتَ فِي صَفَرٍ سنةَ ثلاثينَ وأربعِ مئةٍ بأصبهانَ (٩)."],[1907,"ومِنَ الطبقةِ الأُخرى: أَبُو عُمَرَ بنُ عَبْدِ البَرِّ النَّمَريُّ حافظُ أَهْلِ المغربِ وُلِدَ فِي شَهْرِ ربيعٍ الآخرِ سنةَ ثمانٍ وستينَ وثلاثِ مئةٍ، وماتَ بِشَاطِبَةَ منْ بلادِ الأندلسِ فِي شهرِ ربيعٍ الآخِرِ سنةَ ثلاثٍ وستينَ وأربعِ مئةٍ (١٠). ثُمَّ أَبُو بَكْرٍ أَحْمَدُ بنُ الحُسَينِ البَيْهَقِيُّ وُلِدَ سنةَ أربعٍ وثمانينَ وثلاثِ مئةٍ، وماتَ بِنَيْسابورَ فِي جُمَادَى الأُولَى سنةَ ثمانٍ وخمسينَ وأربعِ مئةٍ ونُقِلَ إلى بَيْهَقَ فَدُفِنَ بها (١). ثُمَّ أَبُو بَكْرٍ أَحْمَدُ بنُ عَلِيٍّ الخطيبُ البغداديُّ وُلِدَ فِي جُمَادَى الآخرةِ سنةَ اثنتينِ وتِسْعِينَ وثلاثِ مئةٍ وماتَ ببغدادَ فِي ذي الحِجَّةِ سنةَ ثلاثٍ وستينَ وأربعِ مئةٍ (٢)، رحمهم الله وإيانا والمسلمينَ أجمعينَ (٣)، واللهُ أعلمُ.","",{"fn":"ويقال: النّسائيّ كما تقدم.\nوفيات الأعيان ١/ ٧٨.\nساقتهم: أي مؤخرهم، من ساقة الجيش. انظر: الصحاح ٤/ ١٤٩٩.\nفي (ج): «وولد».\nتاريخ بغداد ١٢/ ٤٠.\nقال السمعاني في الأنساب ١/ ٤٥٥: «بفتح الباء الموحدة، وكسر الياء المشددة».\nتاريخ بغداد ٥/ ٤٧٣.\nوفيات الأعيان ٣/ ٢٢٣، وتذكرة الحفاظ ٣/ ١٠٤٨.\nوفيات الأعيان ١/ ٩١، وسير أعلام النبلاء ١٧/ ٤٦٣.\nسير أعلام النبلاء ١٨/ ١٥٩."}],[1908,"النوع الحادي والستون معرفة الثقات والضعفاء من رواة الحديث"],[1909,"(٤)","",{"fn":"الأنساب ١/ ٤٦٢.\nتاريخ دمشق ٥/ ٣٩.\nقال البلقيني: «ليس المراد استيعاب أصحاب التصانيف في الحديث، ولا ذكر غالبهم ولا كثيرهم؛ بل ذَلِكَ بحسب ما اتفق، أو لاشتهار تصانيف هؤلاء. وثمّ تصانيف في الحديث - مشهورة وغير مشهورة، لمتقدم ومتأخرٍ - لم تذكر». محاسن الاصطلاح: ٥٨٦. وقال ابن كثير: قلت وكان ينبغي أن يذكر مع هؤلاء جماعة اشتهرت تصانيفهم بين الناس، ولا سيما عند أهل الحديث كالطبراني: وقد توفّي سنة ستين وثلاث مئة صاحب المعاجم الثلاثة وغيرها، والحافظ أبي يعلى الموصلي، والحافظ أبي بكر البزّار، وإمام الأئمة محمّد بن إسحاق بن خزيمة توفّي سنة إحدى عشرة وثلاث مئة، صاحب الصّحيح، وكذلك أبو حاتم محمّد بن حبّان البستي، صاحب الصّحيح أيضًا، وكانت وفاته أربع وخمسين وثلاث مئة، والحافظ أبو أحمد ابن عدي صاحب الكامل توفّي سنة سبع وستين وثلاث مئة). اختصار علوم الحديث مع الباعث ٢/ ٦٦٢. وقال ابن الملقن: ومن الحفاظ: أبو بكر أحمد بن إيراهيم الإسماعيلي الجرجاني، ولد سنة سبع وسبعين ومئتين، ومات سنة إحدى وسبعين وثلاث مئة، وأبو القاسم الطبراني، صاحب المعاجم وغيرها من المؤلفات مات سنة ستين وثلاث مئة، وأبو بكر أحمد بن محمّد البرقاني، ولد سنة ست وثلاثين وثلاث مئة، ومات سنة خمس وعشرين وأربع مئة، وأبو عبد الله بن أبي نصر فتوح الحميدي، صاحب الجمع الصحيحين، مات سنة ثمان وثمانين وأربع مئة، وأبو محمّد الحسين بن مسعود البغويّ محيّ السّنّة مات سنة ست عشرة وخمس مئة) المقنع ٢/ ٦٥٦.\nانظر في ذلك: الإرشاد ٢/ ٧٧٢ - ٧٨٦، والتقريب: ١٩٧ - ١٩٨، والمنهل الروي: ١٣٧، واختصار علوم الحديث: ٢٤٢ - ٢٤٣، والشذا الفياح ٢/ ٧٣٩ - ٧٤٣، والمقنع ٢/ ٦٥٧ - ٦٦١، وشرح التبصرة والتذكرة ٣/ ٢٧٧، وفتح المغيث ٣/ ٣١٤ - ٣٣٠، وتدريب الراوي ٢/ ٣٦٨ - ٣٧٠، وشرح السيوطي عَلَى ألفية العراقي ٢٧٠، وفتح الباقي ٣/ ٢٥٩ - ٢٦٣، وتوضيح الأفكار ٢/ ٥٠٠ - ٥٠٢."}],[1910,"هَذَا مِنْ أجَلِّ نوعٍ وأفْخَمِهِ فإنّهُ المَِرْقَاةُ (١) إلى مَعْرِفَةِ صِحَّةِ الحَدِيْثِ وسَقَمِهِ ولأهلِ المَعْرِفَةِ بالحديثِ فِيهِ تصانيفُ كثيرةٌ."],[1911,"مِنْها: مَا أُفرِدَ فِي الضُّعفاءِ: ككتابِ \" الضُّعَفاءِ \" للبخاريِّ، و\" الضُّعفاءِ \" للنَّسائيِّ، و\" الضُّعفاء \" للعُقَيْليِّ وغيرِها."],[1912,"ومنها: فِي الثِّقاتِ فَحَسْبُ: ككتابِ \" الثِّقاتِ \" لأبي حاتِمِ بنِ حِبَّانَ."],[1913,"ومنها: مَا جُمِعَ فِيهِ بَيْنَ الثِّقاتِ والضُّعفاءِ: ك\" تأريخِ البُخَارِيّ \"، و\" تاريخُ بنُ أبي خَيْثَمَةَ \" - وما أغْزَرَ فَوَائِدَهُ -، وكتابِ \" الجَرْحِ والتَّعديلِ \" لابنِ أبي حاتِمٍ الرَّازِيِّ (٢)."],[1914,"رُوِّينا عنْ صالحِ بنِ محمدٍ الحافظِ جَزَرَةَ قَالَ: أَوَّلُ مَنْ تكَلَّمَ فِي الرِّجَال: شُِعبةُ ابنُ الحَجَّاجِ، ثُمَّ تَبِعَهُ يَحْيَى بنُ سعيدٍ القَطَّانُ، ثُمَّ بَعْدَهُ أَحْمَدُ بنُ حَنْبَلٍ، ويَحْيَى بنُ مَعِينٍ (٣). وهؤلاءِ قلتُ: يعني أنّهُ أَوَّلُ مَنْ تَصدَّى لِذلِكَ وعُنِيَ بِهِ وإلاّ فالكلامُ فيهِم (٤) جَرْحًا وتَعديلًا مُتقدِّمٌ ثابتٌ عنْ رَسُوْلِ اللهِ - صلى الله عليه وآله وسلم - ثُمَّ عَنْ كثيرٍ مِنَ الصَّحَابَةِ والتابعينَ فمَنْ بَعْدَهم وجُوِّزَ ذَلِكَ صَونًا للشَّريعةِ ونَفْيًا للخطأِ والكَذِبِ عَنْهَا (٥)."],[1915,"وكما جازَ الجَرْحُ فِي الشُّهودِ جازَ فِي الرُّواةِ. وَرُوِّيتُ (٦) عَنْ أبي بَكْرِ بنِ خَلاَّدٍ قَالَ: قلتُ ليَحْيَى بنِ سعيدٍ: أما تخشَى أنْ يكونَ هؤلاءِ الذينَ تركتَ حديثَهم خُصَماءَكَ عِنْدَ اللهِ يومَ القيامةِ؟ فَقَالَ: لأَنْ يكونوا خُصَمَائي أحَبَّ إليَّ مِنْ أنْ يكونَ خَصْمي رسولَ اللهِ - صلى الله عليه وآله وسلم - يَقُولُ لي: «لِمَ لَمْ تَذُبَّ الكَذِبَ عَنْ حديثي» (٧). ورُوِّينا أَوْ بَلَغَنا أنَّ أبا ترابٍ النَّخْشَبِيَّ (١) الزاهدَ سَمِعَ مِنْ أَحْمَدَ بنِ حَنْبَلٍ شيئًا منْ ذَلِكَ فَقَالَ لَهُ: «يا شيخُ! لا تغتاب (٢) العُلَمَاءَ. فَقَالَ لَهُ: وَيْحَكَ! هَذَا نَصِيحَةٌ لَيْسَ هَذَا غِيبَةً» (٣). ثُمَّ إنَّ عَلَى الآخِذِ فِي ذَلِكَ أنْ يتَّقيَ اللهَ تبارك وتعالى وَيَتَثبَّتَ ويَتوقَّى التَّساهلَ كَيْلا يَجْرَحَ سَلِيمًا ويَسِمَ بريئًا (٤) بسِمَةِ (٥) سَوْءٍ يَبْقَى عَلَيْهِ الدهرَ عَارُها (٦). وأحسبُ أبا مُحَمَّدٍ عَبْدَ الرحمانِ بنَ أبي حاتِمٍ وَقَدْ قِيلَ: إِنّهُ كَانَ يُعَدُّ مِنَ الأبدالِ منْ مِثلِ مَا ذَكَرناهُ خافَ، فِيْمَا رُوِّيناهُ أَوْ بَلَغَنا (٧) أنَّ يوسُفَ بنَ الحُسَينِ الرازيَّ وَهُوَ الصُّوفيُّ دَخَلَ عَلَيْهِ وَهُوَ يَقرأُ كتابَهُ فِي \" الجَرْحِ والتَّعْدِيلِ \". فَقَالَ لَهُ: كم مِنْ هؤلاءِ القَوْمِ قَدْ حَطُّوا رواحِلَهم فِي الجنَّةِ منذُ مئةِ سنةٍ ومئتي سنةٍ وأنتَ تَذْكُرُهُمْ وتغتابهم؟ فَبَكَى عَبْدُ الرَّحمانِ (٨). وبَلَغَنا أَيْضًَا أنَّهُ حُدِّثَ، وَهُوَ يَقْرأُ كتابَهُ ذَلِكَ عَلَى النَّاسِ عَنْ يَحْيَى بنِ مَعِينٍ أنّهُ قَالَ: «إنا لَنَطْعُنُ عَلَى أقوامٍ لعلَّهم قَدْ حَطُّوا رِحَالَهم فِي الجنَّةِ منذُ أكثرَ مِنْ مئتي سنةٍ». فَبَكى عَبْدُ الرحمانِ وارتَعَدَتْ يَدَاهُ حَتَّى سَقَطَ الكتابُ منْ يَدِهِ (٩).","",{"fn":"المرقاة - بالفتح والكسر - الدّرجة، يقال: ترقّى في العلم، أي: رقي فيه درجةً درجة، انظر: اللسان ١٤/ ٣٣٢.\nانظر كلامًا نافعًا عن هذه الكتب: بحوث في تاريخ السّنّة ٩٠ - ١٢٣.\nالجامع لأخلاق الرّاوي وآداب السامع (١٦١٢)، وراجع المحاسن ٥٨٩.\nفي (ع) والتقييد: «فيه» وما أثبتناه من النسخ و(م) والشذا.\nراجع شرح التبصرة والتذكرة ٣/ ٢٧٩.\nفي (ب): «روينا».\nأورده ابن عدي بسنده في مقدمة الكامل ١/ ١٨٦، والخطيب في الكفاية: (٩٠ ت، ٤٤ هـ).\nهو أبو تراب عسكر بن الحصين النخشبي، توفّي سنة (٢٤٥ هـ)، انظر السير ١١/ ٥٤٥.\nهكذا في الأصول الخطية و(م) و(ع) والشذا والكفاية (٩٢ ت، ٤٥ هـ) والمقنع ٢/ ٦٥٩، وشرح التبصرة ٣/ ٢٧٩، ومثله في طبقات الحنابلة ١/ ٢٤٩. وظاهر السياق أنه نهيٌ فالقياس: «لا تغتب». وجاء في حاشية المحاسن ٥٩٠: «أنّ توجيهه أن تكون لا: نافية، خرجت إلى النهي». وضبط النص في التقييد هكذا: «لا تغتابُ العلماءُ» ضبط قلمٍ، وجاءت الرّواية في اختصار علوم الحديث ٢/ ٦٦٦ بلفظ: «أتغتاب العلماء؟!». وفي فتح المغيث ٣/ ٢٦٦ بلفظ: «لا تغتب الناس». وفي تدريب الرّاوي ٢/ ٣٩٩ بلفظ: «لا تغتب الْعُلَمَاء»، وقارن بحاشية محقق الرفع والتكميل: ٥٤.\nأخرجه الخطيب في الكفاية: (٩٢ ت، ٤٥ هـ)، وراجع المحاسن: ٥٩٠.\nفي (ب) و(ع) والتقييد: «بريًا» بتسهيل الهمزة وتشديد الياء، وهو جائز أيضًا.\nفي (م): «بسمعة».\nقال ابن دقيق العيد في الاقتراح: ٣٤٤: «أعراض المسلمين حفرة من حفر النار وقف على شفيرها طائفتان من الناس المحدّثون والحكام».\nفي (ع) والتقييد: «بلغناه».\nأخرج هذه القصة الخطيب في الكفاية: (٨٢ - ٨٣ ت، ٣٨ هـ) وتكملة القصة كما في الكفاية: «فبكى عبد الرحمان وقال: يا أبا يعقوب لو سمعت هذه الكلمة قبل تصنيفي هذا الكتاب لما صنفته».\nأخرجها الخطيب في الجامع (١٦١٣)."}],[1916,"قلتُ (١): وَقَدْ أخطأَ فِيهِ غَيْرُ واحدٍ عَلَى غَيْرِ واحدٍ فجَرَحُوهُم بما لا صِحَّةَ لَهُ. ومِنْ ذَلِكَ: جَرْحُ أبي عَبْدِ الرحمانِ النَّسائيِّ لأحمدَ بنِ صالحٍ وَهُوَ حافظٌ إمامٌ ثِقَةٌ (٢) لا يَعْلَقُ بِهِ جَرْحٌ أخرجَ عَنْهُ البُخَارِيُّ فِي \" صحيحِهِ \". وقدْ كَانَ منْ أَحْمَدَ إلى النَّسائيِّ جَفاءٌ أفسَدَ قلبَهُ عَلَيْهِ. وَرُوِّينا عَنْ أبي يَعْلَى الخليليِّ الحافظِ قَالَ: «اتَّفقَ الحُفَّاظُ عَلَى أنَّ كلامَهُ فِيهِ تحامُلٌ ولا يَقْدَحُ كلامُ أمثالِهِ فِيهِ» (٣)."],[1917,"قلتُ: النَّسائيُّ إمامٌ حُجَّةٌ فِي الجَرْحِ والتَّعْدِيلِ، وإذا نُسِبَ مِثْلُهُ إلى مثلِ هَذَا كَانَ وَجْهُهُ أنَّ عَيْنَ السُّخْطِ تُبدِي مَسَاوِيَ (٤) لها فِي الباطنِ مَخارِجُ صَحِيْحَةٌ تُعْمَى عَنْهَا بحِجابِ السُّخْطِ، لا أنَّ ذَلِكَ يقعُ منْ مثلِهِ تَعَمُّدًا لِقَدْحٍ يَعْلَمَ بطلانَهُ (٥)، فاعلمْ هَذَا فإنَّهُ منِ النُّكَتِ النَّفيسةِ المهمّةِ."],[1918,"وَقَدْ مَضَى الكلامُ فِي أحكامِ الجَرْحِ والتَّعدِيلِ فِي النَّوعِ الثَّالِثِ والعشرينَ، واللهُ أعلمُ."],[1919,"النوع الثاني والستون معرفة من خلط في آخر عمره من الثقات"],[1920,"(٦)","",{"fn":"في (ع) والتقييد: «قال المؤلف».\nفي (ع) والتقييد: «وهو إمام حافظ ثقة».\nالإرشاد ١/ ٤٢٤.\nفي (ع): «مساوئ» بالهمز؛ وكلاهما جائز كَمَا تقدم، ثمّ إن هَذَا الكلام إشارة إلى قَوْل الشّافعيّ: وعين الرّضا عن كلّ عيبٍ كليلةٌ ... ولكنّ عين السّخط تبدي المساويا\nانظر: المحاسن: ٥٩١.\nانظر في ذلك: الإرشاد ٢/ ٧٨٧ - ٧٩٦، والتقريب: ١٩٨، والمنهل الروي: ١٣٧، واختصار علوم الحديث: ٢٤٤ - ٢٤٥، والشذا الفياح ٢/ ٧٤٤ - ٧٨٠، والمقنع ٢/ ٦٦٢ - ٦٦٧، وشرح التبصرة ٣/ ٢٨٣، وفتح المغيث ٣/ ٣٣١ - ٣٥٠، وتدريب الراوي ٢/ ٣٧١ - ٣٨٠، وشرح السيوطي عَلَى ألفية العراقي: ٢٧٣، وفتح الباقي ٣/ ٢٦٣ - ٢٧٤، وتوضيح الأفكار ٢/ ٥٠٢ - ٥٠٣."}],[1921,"هَذَا فَنٌّ عَزيزٌ مُهِمٌّ عَزِيزٌ لَمْ أعلمْ أحدًا أفردَهُ بالتَّصْنِيفِ (١) واعتَنى بِهِ مَعَ كونِهِ حَقِيقًا بِذَلِكَ جدًّا."],[1922,"وهُمْ مُنقَسِمونَ: فمنهم مَنْ خَلَطَ لاختلاطِهِ وخَرَفِهِ. ومنهم مَنْ خَلَطَ لذهابِ بَصَرِهِ أَوْ لغير ذَلِكَ. والحكمُ فيهم: أنَّهُ يُقبَلُ حَدِيثُ مَنْ أُخِذَ عَنْهُمْ قَبْلَ الاختلاطِ ولا يُقبَلُ حَدِيثُ مَنْ أُخِذَ عَنْهُمْ بَعْدَ الاختلاطِ أَوْ أُشكِلَ أمرُهُ فلم يُدْرَ هل أُخِذَ عَنْهُ قبلَ الاختلاطِ أَوْ بَعْدَهُ؟"],[1923,"فمنهم: عَطَاءُ بنُ السَّائِبِ: اختَلَطَ فِي آخرِ عُمُرِهِ، فاحتجُّ أَهْلُ العلمِ بروايةِ الأكابرِ عَنْهُ، مِثْلُ: سفيانَ الثوريِّ وشُعبةَ (٢)؛؛ لأنَّ سماعَهم منهُ كَانَ فِي الصِّحَّةِ، وتركُوا الاحتجاجَ بروايةِ مَنْ سَمِعَ مِنْهُ آخرًا. وَقَالَ يَحْيَى بنُ سَعِيْدٍ القَطَّانُ فِي شُعْبةَ:"],[1924,"«إلاَّ حَدِيثَينِ كَانَ شعبةُ يقولُ: سَمِعتُهما بِأَخَرَةٍ (٣) عَنْ زاذانَ» (٤).","",{"fn":"قال السخاوي في فتح المغيث ٣/ ٢٧٨: «وأفرد للمختلطين كتابًا الحافظ أبو بكر الحازمي حسبما ذكره في تصنيفه تحفة المستفيد، ولم يقف عليه ابن الصّلاح». وقال الحافظ العراقي في شرح التبصرة ٣/ ٢٨٤: «وبسبب كلام ابن الصّلاح، أفرده شيخنا الحافظ صلاح الدين العلائي بالتصنيف في جزء حدّثنا به، ولكنه اختصره ولم يبسط الكلام فيه، ورتبهم على حروف المعجم». قلنا: ثمّ صنف بعده الحافظ سبط ابن العجمي جزءً صغرًا سماه: \" الاغتباط بمن رمي بالاختلاط \" ثمّ تلاه ابن الكيّال فصنف كتابًا سماه: \" الكواكب النيرات في معرفة من اختلط من الرواة الثقات \". وهذه الكتب كلها مطبوعة - ولله الحمد - عدا كتاب الحازمي.\nقال العراقي في التقييد: ٢٤٤: «قد يفهم من كلامه في تمثيله بسفيان وشعبة من الأكابر أنّ غيرهما من الأكابر سمع منه في الصّحّة، وقد قال يحيى بن معين: جميع من روى عن عطاء روى عنه في الاختلاط إلا شعبة وسفيان. وقال أحمد بن حنبل سمع منه قديمًا شعبة وسفيان. وقال أبو حاتم الرّازيّ: قديم السّماع من عطاء سفيان وشعبة. وقد استثنى غير واحد من الأئمة مع شعبة وسفيان حماد بن زيد ... واستثنى الجمهور أيضًا رواية حماد بن سلمة عنه أيضًا. فممن قاله يحيى ابن معين وأبو داود والطحاوي وحمزة الكناني ...».\nيقال: (تغير بآخره) بمد الهمزة وكسر الخاء والراء، بعدها: هاء. و(تغيّر بآخِرة) بمد الهمزة أيضًا وكسر الخاء وفتح الراء، بعدها تاء مربوطة. و(تغير بأَخَرَة) بفتح الهمزة والخاء والراء، بعدها تاء مربوطة. أي اختلّ ضبطه وحفظه في آخر عمره وآخر أمره. أفاده محقق كتاب قواعد في علوم الحديث: ٢٤٩. قلنا: وانظر: لسان العرب ٤/ ١٤، والتاج ١٠/ ٣٦.\nأسندها الخطيب في الكفاية: (٢١٩ ت، ١٣٧ - ١٣٨ هـ)."}],[1925,"أَبُو إسحاقَ السَّبِيعيُّ: اختلَطَ أَيْضًَا (١)، ويُقالُ إِن سَمَاعَ سفيانَ بنِ عُيَيْنَةَ مِنْهُ بَعْدَ مَا اختلطَ، ذَكَرَ ذَلِكَ أَبُو يَعْلَى (٢) الخليليُّ (٣)."],[1926,"سعيدُ (٤) بنُ إياسٍ الجُرَيْرِيُّ: اختلَطَ وتَغَيَّرَ حِفْظُهُ قَبْلَ مَوْتِهِ. قَالَ أَبُو الوليدِ الباجيُّ المالكيُّ: قَالَ النَّسائيُّ: «أُنكِرَ أيامَ الطَّاعونِ، وَهُوَ أثْبَتُ عندنا منْ خالدٍ الحَذَّاءِ مَا سُمِعَ مِنْهُ قَبْلَ أيامِ الطاعونِ» (٥)."],[1927,"سعيدُ بنُ أبي عَرُوبةَ: قَالَ يَحْيَى بنُ مَعِيْنٍ: «خَلَطَ سَعِيدُ بنُ أبي عَرُوبةَ بَعْدَ هزيمةِ إِبْرَاهِيمَ بنِ عَبْدِ اللهِ بنِ حَسَنِ بنِ حَسَنٍ سنةَ اثنتينِ (٦) وأربعينَ يعني ومئةٍ (٧). ومَنْ سَمِعَ مِنْهُ بَعْدَ ذَلِكَ فليسَ بشيءٍ. ويزيدُ بنُ هارونَ صَحِيْحُ السَّمَاعِ مِنْهُ سمِعَ مِنْهُ بواسطٍ وَهُوَ يريدُ الكُوفةَ. وأثْبَتُ الناسِ سَمَاعًا مِنْهُ عَبْدَةُ بنُ سُلَيمانَ» (١). قلتُ: وممّنْ عُرِفَ أنهُ سَمِعَ مِنْهُ بَعْدَ اختلاطِه وكِيعٌ، والمُعَافَى بنُ عِمْرانَ المَوْصِليُّ. بَلَغَنا عنِ ابنِ عَمَّارٍ المَوْصِليِّ أَحَدِ الحُفَّاظِ أنَّهُ قَالَ: «ليستْ روايتُهما عَنْهُ بشيءٍ إنّما سماعُهما بَعْدَ مَا اختلَطَ». وَقَدْ رُوِّينا عَنْ يَحْيَى بنِ مَعِينٍ أنَّهُ قَالَ لوكيعٍ: «تُحَدِّثُ عَنْ سعيدِ بنِ أبي عَرُوبةَ وإنّما سَمِعتَ مِنْهُ فِي الاختلاطِ؟» فَقَالَ: «رأيتَني حَدَّثْتُ عَنْهُ إلاَّ بحديثٍ مُسْتَوٍ؟» (٢).","",{"fn":"قال العراقي في التقييد والإيضاح: ٤٤٥: «فيه أمور، أحدها: أن صاحب الميزان أنكر اختلاطه فقال: شاخ ونسي، ولم يختلط. قال: وقد سمع منه سفيان بن عيينة، وقد تغير قليلًا. الأمر الثّاني: إن المصنف ذكر كون سماع بن عيينة منه بعدما اختلط بصيغة التمريض، وهو حسنٌ؛ فإن بَعْض أهل العِلْم أخذ ذَلِكَ من كلام لابن عيينة ليس صريحًا في ذَلِكَ قال يعقوب الفسوي قال ابن عيينة: حدّثنا أبو إسحاق في المسجد ليس معنا ثالث. قال الفسوي فقال بعض أهل العلم كان قد اختلط، وإنما تركوه مع ابن عيينة لاختلاطه. الأمر الثّالث: إن المصنف لَمْ يذكر أحدًا قيل عنه إن سماعه منه بعد الاختلاط إلا ابن عيينة ... الأمر الرابع: إنه قد أخرج الشيخان في الصحيحين لجماعة من روايتهم عن أبي إسحاق، وهم إسرائيل بن يونس بن أبي إسحاق وزكريا بن أبي زائدة وزهير بن معاوية وسفيان الثوري، وأبو الأحوص سلام بن سليم وشعبة وعمر بن أبي زائدة ويوسف بن أبي إسحاق وأخرج البخاريّ من رواية جرير بن حازم عنه. وأخرج مُسْلِم من رواية إسماعيل بن أبي خالد ورقبة بن مصقلة وسليمان بن مهران الأعمش وسليمان بن معاذ وعمار بن زريق ومالك بن مغول ومسعر بن كدام عنه. وقد تقدم أن إسرائيل وزكريا وزهير سمعوا منه بأخرة».\nفي (ع): «أن يعلى» خطأ.\nالإرشاد ١/ ٣٥٥.\nفي (ج): «سعد» وهو مخالف للنسخ الأخرى، ومصادر ترجمته. والجريري: بضم الجيم. انظر: التقريب (٢٢٧٣).\nالكواكب النيرات ١٧٨.\nفي (ج) والشذا: «ثنتين».\nللحافظ اعتراضات تراجع في التقييد: ٤٤٨ ومن تلك الاعتراضات رده قول ابن معين في أنّ الهزيمة كانت سنة اثنتين وأربعين ومئة فالمعروف أنها في سنة خمس وأربعين ومئة هذا ما عليه الجمهور. انظر: تاريخ الطبري ٩/ ٢٠ وتاريخ الإسلام ٣٦ (حوادث ١٤٥) والبداية والنهاية ١٠/ ٦٨، وشرح التبصرة ٣/ ٢٨٨."}],[1928,"المَسْعُودِيُّ ممَّنْ اختَلَطَ (٣) وَهُوَ عَبْدُ الرحمانِ بنُ عَبْدِ اللهِ بنِ عُتبةَ بنِ عَبْدِ اللهِ بنِ مَسْعُودٍ الهُذَلِيُّ وَهُوَ أخو أبي العُمَيْسِ عُتبةَ المَسْعُودِيِّ. ذَكَرَ الحاكمُ أَبُو عَبْدِ اللهِ فِي كتابِ \" المُزَكِّينَ للرُّواةِ \" عَنْ يَحْيَى بنِ مَعِينٍ أَنّه قَالَ: «مَنْ سَمِعَ مِنَ المَسْعُودِيِّ فِي زمانِ أبي جَعْفَرٍ فَهُوَ صَحِيْحُ السَّمَاعِ، ومن سَمِعَ مِنْهُ فِي أيام المَهْدِيِّ فليسَ سماعُهُ بشيءٍ» (٤). وذَكَرَ حَنْبَلُ بنُ إسحاقَ عَنْ أَحْمَدَ بنِ حَنْبَلٍ أنّه قَالَ: «سَمَاعُ عاصمٍ - هُوَ ابنُ عَلِيٍّ - وأبي النَّضْرِ وهؤلاءِ مِنَ المَسْعُودِيِّ بَعْدَ مَا اختلَطَ» (٥)."],[1929,"رَبِيعةُ الرَّأْيِ بنُ أبي عَبْدِ الرحمانِ أستاذُ مالكٍ: قِيلَ إنَّهُ تغيَّرَ فِي آخرِ عُمرِهِ وتُرِكَ الاعتمادُ عَلَيْهِ لِذلِكَ (٦)."],[1930,"صالحُ بنُ نَبْهانَ مَوْلَى التَّوْأَمَةِ (٧) بنتِ أميَّةَ بنِ خَلَفٍ: رَوَى عَنْهُ ابنُ أبي ذِئبٍ والناسُ. قَالَ أَبُو حاتِمِ بنُ حِبَّانَ: «تغيَّرَ فِي سنةِ خَمْسٍ وعشرينَ ومئةٍ، واختَلَطَ حديثُهُ الأخيرُ بحديثِهِ القديم وَلَمْ يتميَّزْ. فاستَحَقَّ التَّركَ» (٨).","",{"fn":"أسنده إلى يحيى بن معين ابن عدي في الكامل ٤/ ٤٤٦.\nأسنده الخطيب في الكفاية: (٢١٧ ت، ١٣٦ هـ) قال البلقيني في المحاسن: ٥٩٥: «من هذه الحكاية يوجد أنه إذا حدّث بحديث مستوٍ كان جائزًا».\nللعراقي في هذا اعتراضات عدة راجعها في التقييد ٤٥٢ - ٤٥٤.\nأسنده الخطيب في تاريخ بغداد ١٠/ ٢٢١.\nأسنده الخطيب في تاريخ بغداد ١٠/ ٢٢٠ وتمامه: «إلا أنهم احتملوا السّماع منه فسمعوا».\nللحافظ العراقي اعتراضٌ مطول على هذا راجعه في التقييد: ٤٥٥.\nبفتح المثناة وسكون الواو بعدها همزة مفتوحة. التقريب (٢٨٩٢).\nالمجروحين ١/ ٣٦٦. قال العراقي في التقييد والإيضاح: ٤٥٦: «اقتصر المصنف من أقوال من تكلم في صالح بالاختلاط على حكاية كلام ابن حبان فاقتضى ذلك ترك جميع حديثه، وليس ="}],[1931,"حُصَيْنُ بنُ عَبْدِ الرحمانِ الكُوفيُّ مِمَّنْ اختَلَطَ وَتغيَّرَ، ذَكَرَهُ النَّسائيُّ (١) وغيرُهُ، واللهُ أعلمُ."],[1932,"عبدُ الوهَّابِ الثَّقَفِيُّ: ذَكَرَ ابنُ أبي حاتِمٍ الرَّازِيُّ عَنْ يَحْيَى بنِ مَعِينٍ أَنّهُ قَالَ: «اختَلَطَ بِأَخَرَةٍ» (٢)."],[1933,"سفيانُ بنُ عُيَيْنَةَ: وَجَدْتُ عَنْ مُحَمَّدِ بنِ عَبْدِ اللهِ بنِ عَمَّارٍ المَوْصِليِّ أنّهُ سَمِعَ يَحْيَى بنَ سعيدٍ القطانِ يَقُولُ: «أشهدُ أنَّ سفيانَ بنَ عُيَيْنَةَ اختلَطَ سنةَ سبعٍ وتسعينَ فمَنْ سَمِعَ مِنْهُ فِي هذِهِ السنةِ وبعدَ هَذَا فسماعُهُ لا شيءَ». قلتُ تُوُفِّيَ بَعْدَ ذَلِكَ بنحوِ سنتينِ سنةَ تسعٍ وتسعينَ ومئةٍ (٣).","",{"fn":"الضعفاء والمتروكون (١٣٠). وللحافظ العراقي في التقييد: ٤٥٦ - ٤٥٨ مناقشات طويلة حول هذه الترجمة.\nالجرح والتعديل ٦/ ٧١ (٣٦٩). قال العراقي في التقييد: ٤٥٨: «لم يبين المصنف مقدار مدة اختلاطه ولا من ذكر أنه سمع منه في الصّحّة أو في الاختلاط. فأما مقدار مدة اختلاطه فقال عقبة بن مكرم العمي: اختلط قبل موته بثلاث سنين أو أربع سنين. وكانت وفاته سنة أربع وتسعين ومئة بتقديم التاء على السين، وهو قول عمرو بن عليّ الفلاس، وأبو موسى الزمن وبه جزم ابن زبر وابن قانع والذهبي في العبر والمزي في التهذيب، وقيل سنة أربع وثمانين وبه صدَّر ابن حبان كلامه. أما الذين سمعوا منه في الصّحّة فجميع من سمع منه إنما سمع منه في الصّحّة قبل اختلاطه. قال الذهبي في الميزان: ما ضرر تغير حديثه فإنه ما حدث بحديث في زمن التغير، ثمّ استدل على ذلك بقول أبي داود تغير جرير بن حازم وعبد الوهاب الثقفي، فحجب الناس عنهما».\nقال العراقي في التقييد والإيضاح: ٤٥٩: «فيه أمور أحدها: إن المصنف لم يبين من سمع منه في سنة سبع وتسعين وما بعدها، وقد سمع منه في هذه السّنّة محمّد بن عاصم صاحب ذاك الجزء العالي كما هو مؤرخ في الجزء المذكور. وهكذا ذكره أيضًا صاحب الميزان، قال: فأما سنة ثمان وتسعين ففيها مات، ولم يلقه فيها أحد فإنه توفّي قبل قدوم الحاج بأربعة أشهر، قال: ويغلب على ظني أن سائر شيوخ الأئمة الستة سمعوا منه قبل سنة سبع. الأمر الثّاني: إن هذا الذي ذكره المصنف عن محمّد بن عبد الله بن عمّار عن القطان قد استبعده صاحب الميزان فقال: وأنا أستبعده وأعده غلطًا من ابن عمّار؛ فإن القطان مات في="}],[1934,"عَبْدُ الرزاقِ بنُ هَمَّامٍ: ذَكَرَ أَحْمَدُ بنُ حَنْبَلٍ أنَّهُ عَمِيَ فِي آخرِ عُمُرِهِ فكانَ يُلَقَّنُ فَيَتَلَقَّنُ، فسَماعُ منْ سَمِعَ مِنْهُ بَعْدَ مَا عَمِيَ لا شيءَ (١). وَقَالَ النسائيُّ: «فِيهِ نَظَرٌ لمنْ كَتَبَ عَنْهُ بِأَخَرَةٍ» (٢)."],[1935,"قلتُ: وعلى هَذَا يُحْمَلُ (٣) قَوْلُ عَبَّاسِ بنِ (٤) عَبْدِ العَظِيمِ، لمّا رَجَعَ مِنْ صَنْعَاءَ: «واللهِ لَقَدْ تَجشَّمْتُ إلى عَبْدِ الرزاقِ، وإنّهُ لَكَذَّابٌ، والواقديُّ أصدَقُ مِنْهُ» (٥)."],[1936,"قلتُ: قَدْ وَجَدْتُ - فِيْمَا رُوِيَ عنِ الطَّبَرانيِّ عَنْ إسحاقَ بنِ إِبْرَاهِيمَ الدَّبَرِيِّ (٦) عَنْ عَبْدِ الرزاقِ - أحاديثَ اسْتَنْكَرتُها (٧) جِدًّا، فَأَحَلْتُ أمرَها عَلَى ذَلِكَ، فإنَّ سَمَاعَ الدَّبَريِّ مِنْهُ متأخّرٌ جِدًّا. قَالَ إِبْرَاهِيمُ الحَرْبيُّ: «ماتَ عَبْدُ الرزاقِ وللدَّبَريِّ سِتُّ سِنينَ أَوْ سبعُ سِنينَ» (٨) ويَحْصُلُ أَيْضًَا نظرٌ فِي كثيرٍ مِنَ العَوَالِي (٩) الواقعةِ عمَّنْ تأخَّرَ سَماعُهُ مِنْ سُفيانَ بنِ عُيَيْنَةَ وأشباهِهِ.","",{"fn":"فصل الحافظ العراقي في التقييد: ٤٥٩ - ٤٦٠ فذكر من سمع من عبد الرزاق بعد التغير.\nالضعفاء والمتروكون للنسائي (٣٧٩).\nفي (ج): «نحمل».\nساقطة من (م).\nالكامل ٦/ ٥٣٨.\nبفتح الدال المهملة والياء المنقوطة بنقطة من تحت والراء المهملة بعدها، هذه النسبة إلى الدبر، وهي قرية من قرى صنعاء اليمن. الأنساب ٢/ ٥١٦.\nفي (ج): «استكثرتها».\nالكواكب النيرات ٢٧٢ - ٢٨٢.\nفي النسخ و(م) والتقييد: «ويحصل أيضًا في نظر من كثير من العوالي ... الخ». وفي الشذا «ويحل أيضًا في نظر في كثير من العوالي ... الخ». والمثبت من (ع) ومثله في المقنع ٢/ ٦٦٦، وشرح التبصرة ٣/ ٢٩٧."}],[1937,"عارمٌ مُحَمَّدُ بنُ الفَضْلِ أَبُو النُّعْمانِ (١): اختَلَطَ بأَخَرَةٍ، فما رَواهُ عَنْهُ البُخَارِيُّ، ومُحَمَّدُ بنُ يَحْيَى الذُّهْليُّ وغيرُهما مِنَ الحُفَّاظِ يَنْبغِي أنْ يكونَ مأخوذًا عَنْهُ قَبْلَ اختلاطِهِ."],[1938,"أَبُو قِلاَبةَ عَبْدُ الملكِ بنُ مُحَمَّدِ بنِ عَبْدِ اللهِ الرَّقَاشِيُّ (٢): رُوِّينا عنِ الإمامِ ابنِ خُزَيمةَ أَنَّهُ قَالَ: «حَدَّثَنَا أَبُو قِلاَبةَ بالبَصْرةِ قَبْلَ أنْ يَختلِطَ ويخرجَ إلى بغدادَ» (٣). وممَّنْ بَلَغَنا عَنْهُ ذَلِكَ مِنَ المتأخِّرينَ أَبُو أَحْمَدَ (٤) الغِطْرِيفيِّ (٥) الجُرجانيِّ، وأبو طاهرٍ حفيدُ الإمامِ ابنِ خُزَيمةَ: ذَكَرَ الحافظُ أَبُو عَلِيٍّ البَرْدَعِيُّ (٦) ثُمَّ السَّمرقنديُّ فِي \" معجمِهِ \" أنّهُ بَلَغَهُ أنَّهما اختَلَطا فِي آخرِ عُمُرِهِما."],[1939,"وأبو بكرِ بنِ مَالِكٍ القَطِيعيُّ راوي مسندَ أَحْمَد وغيرَهُ اختلَّ فِي آخرِ عُمُرِهِ وخَرِفَ حَتَّى كَانَ لا يَعرِفُ شيئًا مما يُقرأ عَلَيْهِ (٧)."],[1940,"واعلمْ أَنَّ مَنْ كَانَ مِنْ هَذَا القَبِيلِ مُحْتَجًّا بروايتهِ فِي \" الصحيحينِ \" أَوْ أحدِهما فإنّا نَعْرِفُ عَلَى الجملةِ أنَّ ذَلِكَ ممّا تَميَّزَ وَكَانَ مأخوذًا عَنْهُ قَبْلَ الاختلاطِ، واللهُ أعلمُ.","",{"fn":"فصّل الحافظ العراقي في التقييد: ٤٦١ - ٤٦٢ مدة اختلاطه ومن سمع منه قبل الاختلاط وبعده.\nانظر: التقييد والإيضاح: ٤٦٢ - ٤٦٣.\nأسنده الخطيب في تاريخه ١٠/ ٤٢٦.\nانظر: التقييد: ٤٦٣.\nبكسر الغين المعجمة، وسكون الطاء وكسر الراء وسكون الياء. انظر: الأنساب ٤/ ٢٧٣.\nفي (أ) و(ج) و(ع) والتقييد: «البرذعي» بالذال المعجمة. قال في القاموس (مع شرحه التاج) ٢٠/ ٣١٥: «برذعة (بالذال المعجمة) بلد بأذربيجان، وإهمال ذاله أكثر». وفي معجم البلدان ١/ ٣٧٩: «برذعة (بالمعجمة)، وقد رواه أبو سعد بالدال المهملة والعين مهملة عند الجميع: بلد في أقصى أذربيجان» وكلاهما بفتح الباء الموحدة وسكون الراء وفتح ما بعد الراء. وانظر: الأنساب ١/ ٣٢٧ و٣٣٠.\nنفى العراقي صحّة ذلك في نقاش طويل مع ابن الصّلاح، راجعه في التقييد والإيضاح: ٤٦٥."}],[1941,"النوع الثالث والستون معرفة طبقات الرواة والعلماء"],[1942,"(١)"],[1943,"وذلكَ مِنَ المهمّاتِ التي افْتَضَحَ بِسَبَبِ الجَهْلِ بِها غَيْرُ واحدٍ مِنَ المُصنِّفينَ وغيرِهم."],[1944,"و\" كتابُ الطَّبَقاتِ الكبيرِ \" لمحمدِ بنِ سَعْدٍ كاتبِ الواقديِّ كِتَابٌ حَفِيلٌ كثيرٌ الفوائدِ، وَهُوَ ثقةٌ غَيْرَ أنّه كثيرُ الروايةِ فِيهِ عنِ الضُّعَفاءِ. ومنهم: الواقديُّ، وَهُوَ مُحَمَّدُ ابنُ عُمَرَ الذي لا يَنْسُبُهُ (٢)."],[1945,"والطبقةُ فِي اللُّغَةِ: عبارةٌ عنِ القَوْمِ المُتشابِهينَ (٣)، وعِندَ هَذَا فرُبَّ شَخْصينِ يكونانِ منْ طَبَقةٍ واحدةٍ لتشابهِهما بالنِّسْبةِ إلى جِهَةٍ، ومنْ طَبَقَتيْنِ بالنِّسْبةِ إلى أُخرى"],[1946,"لا يتشابهانِ فِيْهَا. فأنسُ بنُ مالكٍ الأنصاريُّ وغيرُهُ منْ أصاغرِ الصَّحابةِ مَعَ العَشَرةِ وغيرِهم منْ أكابرِ الصَّحَابَةِ مِنْ طبقةٍ واحدةٍ إذَا نَظَرنا إلى تَشَابهِهم فِي أصلِ صفةِ الصُّحبةِ."],[1947,"وعلى هَذَا فالصَّحابةُ بأسرِهِم طبقةٌ أُولَى، والتابعونَ طبقةٌ ثانيةٌ، وأتباعُ التابعينِ طَبَقةٌ ثالثةٌ، وَهَلُمَّ جَرًّا. وإذا نَظرنا إلى تَفاوتِ الصحابةِ فِي سَوابقِهم ومَراتِبهم كانوا عَلَى مَا سَبَقَ ذِكْرُهُ بَضْعَ عَشْرَةَ طَبَقةً، ولا يكونُ عِنْدَ هَذَا أنسٌ وغيرُهُ منْ أصاغرِ الصَّحَابَةِ منْ طبقةِ العَشَرَةِ مِنَ الصَّحَابَةِ بَلْ دُونَهم بِطَبَقَاتٍ. والباحثُ الناظرُ فِي هَذَا الفَنِّ يَحْتاجُ إلى مَعْرِفَةِ المواليدِ والوَفَياتِ ومَنْ أَخذُوا عَنْهُ ومَنْ أَخَذَ عَنْهُمْ ونحوِ ذَلِكَ، واللهُ أعلمُ.","",{"fn":"انظر في ذلك: الإرشاد ٢/ ٧٩٧ - ٧٩٩، والتقريب: ١٩٩، والمنهل الروي: ١١٥، واختصار علوم الحديث: ٢٤٥، والشذا الفياح ٢/ ٧٨١ - ٧٨٢، والمقنع ٢/ ٦٦٨ - ٦٦٩، وشرح التبصرة والتذكرة ٣/ ٣٠١، وفتح المغيث ٣/ ٣٥١ - ٣٥٤، وتدريب الراوي ٢/ ٣٨٠ - ٣٨٢، فتح الباقي ٣/ ٢٧٤ - ٢٧٦، وتوضيح الأفكار ٢/ ٥٠٣ - ٥٠٤، وظفر الأماني: ١٠٣ - ١٠٤.\nانظر: محاسن الاصطلاح ٥٩٩.\nانظر: الصحاح ٤/ ١٥١٢، والمحكم ٦/ ١٧٨، وتاج العروس ٢٦/ ٥٠، وانظر عن نظام الطبقات في كتب المحدّثين والمؤرخين تقدمة سير أعلام النبلاء ١/ ٩٨، ومقدمة تحقيق طبقات خليفة: ٤٦، وبحوث في تاريخ السُّنَّة: ٧٥."}],[1948,"النَّوْعُ الرَّابِعُ وَالسِّتُّوْنَ"],[1949,"مَعْرِفَةُ الْمَوَالِي (١) مِنَ الرُّوَاةِ وَالعُلَمَاءِ (٢)"],[1950,"وأهمُّ ذَلِكَ مَعْرِفَةُ المَوَالِي المَنْسُوبينَ إلى القبائلِ بوَصْفِ الإطلاقِ، فإنَّ الظاهرَ فِي المَنسُوبِ إلى قَبِيلةٍ كَمَا إذَا قِيلَ: «فُلاَنٌ القُرَشِيُّ» أنَّهُ مِنْهُمْ صَلِيْبَةً (٣)، فإذن بَيانُ مَنْ قِيلَ فِيهِ: قُرَشيٌّ من أجلِ كونِهِ مَوْلَى لهم مُهِمٌّ.","",{"fn":"الموالي: جمع مولىً، واسم المولى: يقع على معانٍ كثيرة، قال ابن الأثير: هو الرب والمالك والسّيد والمنعم والمعتق والناصر والمحب والتابع والجار وابن العم والحليف والعقيد والصّهر والعبد والمعتق والمنعم عليه. وأكثرها قد جاءت في الحديث فيضاف كلّ واحد إلى ما يقتضيه الحديث الوارد فيه، وكلّ من ولي أمرًا أو قام به فهو مولاه ووليّه». ثمّ ذكر صورة الاختلاف فيها واستدل لكل منها. النهاية ٥/ ٢٢٨، وانظر الصحاح ٦/ ٢٥٢٩، والمقاييس ٦/ ١٤١، واللسان ١٥/ ٤٠٩. ونقول موضحين: الولاء في اللغة القرابة، والعلاقة التي تكون بين اثنين أو أكثر والولاء بأنواعه من محاسن الإسلام، فكلما زادت الروابط والعلاقات بين الناس كان ذلك أدعى إلى المحبة والوفاق وعدم التنازع والخصام. ولابد أن نشير إلى أن الأصل في نسبة الرّاوي إلى قبيلة أن يكون منهم صليبة، كقولهم: قرشي، أي: من أولاد قريش، وإذا نسبوا إليها من ينتمي إليها بالولاء أضافوا كلمة مولى، فقالوا: مولى قريش، أو القرشي مولاهم. والولاء أنواع ثلاثة: النّوع الأول: ولاء العتاقة، وهو ما يكون بين المعتق والمعتق وقد كان معروفًا في الجاهلية فجاء الإسلام فأقره، وشرط له بعض الشروط وهذا النّوع هو الأكثر. النّوع الثّاني: ولاء التناصر والتعاون، وقد كان في الجاهلية، ولكن الإسلام جعله تناصرًا على الحق والخير لا على البغي والظلم وتقاطع الأرحام. النّوع الثّالث: ولاء الإسلام فكل من أسلم على يدي شخص فولاؤه له، وهذا مما ابتدع في الإسلام، ولم يكن معروفًا من قبل. وقد ضرب المصنف أمثلة لكل نوع. انظر: منهج النقد: ١٧٥، والوسيط في علوم الحديث ٢/ ٦٨٨.\nانظر في ذلك: معرفة علوم الحديث: ١٩٦ - ٢٠٢، الإرشاد ٢/ ٨٠٠ - ٨٠٣، والتقريب: ١٩٩ - ٢٠٠، والمنهل الروي: ١٣٥، واختصار علوم الحديث: ٢٤٦ - ٢٤٧، والشذا الفياح ٢/ ٧٨٣ - ٧٨٧، والمقنع ٢/ ٦٧٠ - ٦٧٣، وشرح التبصرة والتذكرة ٣/ ٣٠٤، وفتح المغيث ٣/ ٣٥٥ - ٣٥٨، وتدريب الراوي ٢/ ٣٨٢ - ٣٨٤، وشرح السيوطي عَلَى ألفية العراقي: ٢٧٧، وفتح الباقي ٣/ ٢٧٦ - ٢٧٨، وتوضيح الأفكار ٢/ ٥٠٤.\nجاء في نسخة (ب) حاشية نصها: «الصليبة: الخالص النسب» والمراد من ولد الصلب أي: من صلبهم ونسبهم. انظر: فتح المغيث ٣/ ٢٩٦، والمعجم الوسيط ١/ ٥١٩."}],[1951,"واعْلمْ أَنَّ فيهم مَنْ يُقالُ فِيهِ: «مَوْلَى فَلانٍ» أَوْ: «لبني فلانٍ». والمرادُ بِهِ مَوْلَى العَتَاقَةِ وهذا هُوَ الأغلبُ فِي ذَلِكَ."],[1952,"ومنهم منْ أُطلِقَ عَلَيْهِ لفظُ «المَوْلَى» والمرادُ بِهِ وَلاءُ الإسلامِ."],[1953,"ومنهم أَبُو عبدِ اللهِ البُخَارِيُّ فَهُوَ مُحَمَّدُ بنُ إسماعيلَ الجُعْفِيُّ (١) مَوْلاَهُمْ نُسِبَ إلى وِلاءِ الجُعْفيِّينَ؛ لأنَّ جَدَّهُ - وأظنُّهُ الذي يُقالُ لَهُ: الأحنفُ (٢) - أسلمَ وَكَانَ مجوسِيًّا عَلَى يَدِ اليَمَانِ بنِ أخنسَ الجُعْفيِّ (٣) جدِّ عَبْدِ اللهِ بنِ مُحَمَّدٍ المُسْنَدِيِّ (٤) الجُعْفِيِّ أحدِ شُيوخِ البُخَارِيِّ. وكذلك الحَسَنُ بنُ عيسى المَاسَرْجِسيُّ (٥) مَوْلَى عَبْدِ اللهِ بنِ المُبَارَكِ إنَّما ولاؤهُ لَهُ منْ حَيْثُ كونُهُ أسلمَ -وَكَانَ نَصْرانيًا- عَلَى يَدَيهِ."],[1954,"ومنهمْ مَنْ هُوَ مَوْلَىً بوَلاءِ الحِلْفِ والموالاةِ كمالكِ بنِ أنسٍ الإمامِ، وَنَفَرُهُ هُمْ أَصْبَحِيُّونَ حِمْيَريُونَ صَلِيْبَةً (٦) وهُمْ مَوَالٍ لِتَيْمِ قُرَيْشٍ بالحِلْفِ، وَقِيلَ، لأنَّ جَدَّهُ مَالِكَ بنَ أبي عامرٍ كَانَ عَسِيفًا عَلَى طَلْحةِ بنِ عُبَيدِ اللهِ التَّيْميِّ (٧) أيْ أَجِيرًا، وطَلْحَةُ يَخْتَلِفُ (٨) بالتِّجارَةِ فقِيلَ: «مَوْلَى التَّيْمِيّينَ» لِكَوْنِهِ مَعَ طلحةَ بنِ عُبَيْدِ اللهِ التَّيْمِيِّ."],[1955,"وهذا قِسْمٌ رابعٌ فِي ذَلِكَ وَهُوَ نَحْوُ مَا أسلفناهُ فِي مِقْسَمٍ أَنّهُ قِيلَ فِيهِ: «مَوْلَى ابنُ عَبَّاسٍ» لِلزومِهِ إيّاهُ (٩).","",{"fn":"بضم الجيم وسكون العين المهملة. الأنساب ٢/ ٩٤.\nالذي ذكره غير واحد ممن ترجم للبخاري أن جد البخاريّ: «المغيرة» هو الذي كان مجوسيًا؛ فأسلم عَلَى يدي يمان الجعفي. انظر: تاريخ بغداد ٢/ ٦، الأنساب ٢/ ٩٤، السير ١٢/ ٣٩٢، هدي الساري: ٤٧٧.\nاللباب ١/ ٢٨٤.\nبضم الميم، وسكون السين المهملة، وفتح النون، الأنساب ٥/ ١٨٣.\nبفتح الميم والسين المهملة، وسكون الواو، وكسر الجيم. الأنساب ٥/ ٤٨.\nأي: من صلبهم ونسبهم، كما تقدم.\nفي (ع) و(م) والشذا فقط.\nيقال: اختلف إلى المكان، أي: تردّد. انظر: المعجم الوسيط ١/ ٢٥١.\nانظر: محاسن الاصطلاح: ٦٠٣."}],[1956,"وهذه أمثلةٌ للمنسوبينَ إلى القَبائِلِ منْ مَوَالِيهم (١):"],[1957,"أَبُو البَخْتَريُّ (٢) الطائيُّ سعيدُ بنُ فَيْرُوزَ التابعيُّ هُوَ مَوْلَى طَيّءٍ. أَبُو العاليةِ رُفَيْعٌ (٣) الرِّياحِيُّ التَّميميُّ التَّابِعيُّ كَانَ مَوْلَى امرأةٍ منْ بني رِياحٍ. عَبْدُ الرحمانِ بنُ هُرْمُزَ الأعرجُ الهاشميُّ أَبُو داودَ الرَّاوِي عَنْ أبي هُرَيْرَةَ وابنِ بُحَيْنَةَ وغيرِهما هُوَ مَوْلَى بني هاشِمٍ. الليثُ بنُ سَعْدٍ المِصْريُّ الفَهْمِيُّ (٤) مَوْلاهُمْ. عَبْدُ اللهِ بنُ المباركِ المَرْوزيُّ الحَنْظَلِيُّ (٥) مَوْلاهُمْ."],[1958,"عَبْدُ اللهِ بنُ وَهْبٍ المِصْريُّ القُرَشيُّ مَوْلاَهُمْ. عَبْدُ اللهِ بنُ صالحٍ المِصْريُّ كاتبُ اللَّيثِ الجُهنيُّ مَوْلاَهُمْ."],[1959,"ورُبَّما نُسِبَ إلى القَبِيلةِ مَوْلَى مَوْلاَهَا كأبي الحُبابِ (٦) سَعيدِ بنِ يَسارٍ الهاشميِّ الرَّاوِي عَنْ أبي هُرَيْرَةَ وابنِ عُمَرَ كَانَ مَوْلَى لِمَوْلَى بني هَاشِمٍ؛ لأنَّهُ مَوْلَى شُقْرَانَ (٧) مَوْلَى رَسُوْلِ اللهِ - صلى الله عليه وآله وسلم -."],[1960,"رَوِّينا عنِ الزُّهْرِيّ قَالَ: قَدِمْتُ عَلَى عَبْدِ الملكِ بنِ مَرْوانَ، فَقَالَ: مِنْ أينَ قَدِمْتَ يا زُهْرِيُّ؟ قُلْتُ: مِنْ مَكَّةَ. قَالَ: فَمَنْ خَلَّفتَ بِهَا يَسودُ أهلَها؟ قُلْتُ: عَطَاءُ بنُ أبي رَبَاحٍ. قَالَ: فَمِنَ العَرَبِ أَمْ مِنَ المَوَالِي؟ قَالَ قُلْتُ: مَنَ المَوَالِي (١). قَالَ: وَبِمَ سَادَهُمْ؟ قُلْتُ: بالدِّيانةِ والرِّوايةِ. قَالَ: إنَّ أَهْلَ الدِّيانةِ والرِّوايةِ لَيَنْبغِي أَنْ يُسَوَّدُوا. قَالَ فَمَنْ يَسُودُ أهلَ اليَمَنِ؟ قَالَ قُلْتُ: طاوُسُ بنُ كَيْسانَ. قَالَ: فَمِنَ العَرَبِ أَمْ مِنَ المَوَالِي؟ قَالَ قُلْتُ: مَنَ المَوَالِي قَالَ: وَبِمَ سَادَهُمْ؟ قُلْتُ: بِمَا سَادَهُم بِهِ عَطَاءٌ. قَالَ: إِنَّهُ لَيَنْبَغِي قَالَ: فمَنْ يَسُودُ أَهْل مِصْرَ؟ قَالَ قُلْتُ: يَزِيدُ ابنُ أبي حَبِيبٍ. قَالَ: فَمِنَ العَرَبِ أَمْ مِنَ المَوَالِي؟ قَالَ قُلْتُ (٢): مَنَ المَوَالِي. قَالَ: فَمَنْ يسُودُ أَهْلَ الشَّامِ؟ قَالَ قُلْتُ: مَكْحُولٌ. قَالَ: فَمِنَ العَرَبِ أَمْ مِنَ المَوَالِي؟ قَالَ قُلْتُ: مَنَ المَوَالِي عبدٌ نُوبِيٌّ (٣) أعتَقَتْهُ امرأةٌ منْ هُذيْلٍ. قَالَ: فَمَنْ يَسُودُ أهْلَ الجَزِيْرَةِ؟ قُلتُ (٤): مَيْمُونُ بنُ مِهْرَانَ. قَالَ: فَمِنَ العَرَبِ أَمْ","",{"fn":"انظر: التقييد: ٤٦٧.\nبفتح الموحدة والمثناة بينهما معجمة. التقريب (٢٣٨٠).\nرفيع بالتصغير، والرياحي: بكسر الراء والتحتانية. (التقريب ١٩٥٣).\nبفتح الفاء وسكون الهاء. الأنساب ٤/ ٣٩٢.\nبفتح الحاء المهملة وسكون النون وفتح الظاء المعجمة. الأنساب ٢/ ٣٢٦.\nبضم المهملة وموحدتين. التقريب (٢٤٢٣).\nبضم أوله وسكون القاف (التقريب ٢٨١٤)."}],[1961,"مِنَ المَوَالِي؟ قَالَ قُلْتُ: مَنَ المَوَالِي. قَالَ: فمَنْ يَسُودُ أهلَ خُرَاسَانَ؟ قَالَ: قُلْتُ: الضَّحَّاكُ بنُ مُزَاحِمٍ. قَالَ: فَمِنَ العَرَبِ أَمْ مِنَ المَوَالِي؟ قَالَ قُلْتُ: مَنَ المَوَالِي. قَالَ: فَمَنْ يَسُودُ أهلَ البَصْرَةِ؟ قَالَ قُلْتُ: الحَسَنُ بنُ أبي الحَسَنِ. قَالَ: فَمِنَ العَرَبِ أَمْ مِنَ المَوَالِي؟ قَالَ قُلْتُ: مَنَ المَوَالِي. قَالَ: وَيْلَكَ! فَمَنْ يَسُودُ أهلَ الكُوفَةِ؟ قال"],[1962,"قلتُ: إبراهيمُ النَّخَعيُّ. قَالَ: فَمِنَ العَرَبِ أَمْ مِنَ المَوَالِي؟ قَالَ قُلْتُ: مَنَ العَرَبِ. قالَ: وَيْلَكَ يا زُهْرِيُّ! فَرَّجْتَ عَنِّي، واللهِ لَتَسُودَنَّ المَوَالِي (٥) على العَرَبِ حتى يُخْطَبَ لها على المَنَابِرِ والعَرَبُ تَحْتَها. قال قلت: يا أميرَ المؤمنينِ! إنَّما هو أمرُ الله وَدِينُهُ، مَنْ حَفِظَهُ سَادَ ومَنْ ضَيَّعهُ سَقَطَ (٦)."],[1963,"وفيما نَرْوِيهِ عَنْ (٧) عَبْدِ الرحمانِ بنِ زَيْدِ بنِ أسلَمَ قَالَ: «لمّا ماتَ العَبَادلةُ صارَ الفِقْهُ فِي جميعِ البُلدانِ إلى المَوَالي، إلاَّ المدينةَ، فإنَّ اللهَ خصَّهَا بِقُرَشيٍّ فكانَ فقيهُ أهلِ المدينةِ سعيدَ بنَ المُسَيِّبِ غيرَ مُدَافَعٍ».","",{"fn":"عبارة: «من الموالي» ساقطة من (ب).\nساقطة من (ج).\nبضم النون وفي آخرها الباء المنقوطة بواحدة، هذه النسبة إلى بلاد النوبة وهو السودان. انظر: الأنساب ٥/ ٤٣٠.\nفي (أ): «قال: قلت».\nساقطة من (أ).\nهذه القصة أسندها الحاكم في معرفة علوم الحديث: ١٩٨ - ١٩٩، من طريق الوليد بن محمد المُوقّري، عن الزهري، وقد أعلها إمام المؤرخين -الذهبي- في السير ٥/ ٨٥، فقال: «الحكاية منكرة، والوليد واهٍ».\nسقطت من (م)."}],[1964,"قُلْتُ: وَفِي هَذَا (١) بعضُ المَيْلِ، فَقَدْ كَانَ حينئذٍ مِنَ العَرَبِ غَيْر ابنِ المُسِّيبِ فُقَهَاءُ أئمَّةٌ مشاهيرُ، مِنْهُمْ: الشَّعْبيُّ، والنَّخَعيُّ (٢)، وجميعُ الفُقَهاءِ السَّبْعةِ الذينَ مِنْهُمْ ابنُ المسيِّبِ عَرَبٌ إلاَّ سُلَيْمانَ بنَ يَسَارٍ، واللهُ أعلمُ."],[1965,"النوع الخامس والستون معرفة أوطان الرواة وبلدانهم"],[1966,"(٣)"],[1967,"وذلكَ ممَّا يَفْتَقِرُ حُفَّاظُ الحديثِ إلى مَعْرِفَتِهِ فِي كثيرٍ مِنْ تصرُّفاتِهم، وَمِنْ مَظَانِّ ذِكرِهِ \" الطَّبَقَاتُ \" لابنِ سَعْدٍ. وَقَدْ كانتِ العَرَبُ إنَّما تَنْتَسِبُ (٤) إلى قَبائِلها، فلمّا جاءَ إلى الإسلامِ وغَلَبَ عليهم سُكْنى القُرَى والمدائنِ حَدَثَ فِيْمَا بَيْنَهم الانتسابُ إلى الأوطانِ، كَمَا كانتِ العَجَمُ تَنتَسِبُ (٥)، وأضاعَ كثيرٌ مِنْهُمْ أنسابَهم (٦)؛ فَلَمْ يبقَ لَهُمْ غيرُ الانتسابِ إلى أوطانِهم. ومَنْ كَانَ مِنَ النَّاقِلَةِ (٧) منْ بَلَدٍ إلى بَلَدٍ، وأرادَ الجَمْعَ بَيْنَهُمَا فِي الانتسابِ فَليَبْدَأْ بالأوَّلِ (٨) ثُمَّ بالثاني المُنتقِلِ إِليهِ، وحَسَنٌ أنْ يُدْخِلَ عَلَى الثَّانِي كلمةَ «ثُمَّ» فيُقالُ فِي النَّاقِلَةِ مِنْ مِصْرَ إلى دَمَشْقَ مثلًا: «فُلاَنٌ المَصْرِيُّ ثُمَّ الدِّمَشْقِيُّ» (١). ومَنْ كَانَ مِنْ أَهْلِ قَرْيَةٍ مِنْ قُرَى بَلْدَةٍ فجائزٌ أنْ يَنتَسِبَ إلى القَرْيَةِ وإلى البَلْدَةِ أَيْضًَا وإلى الناحيةِ التي مِنْها تِلْكَ البلدةُ أَيْضًَا (٢).","",{"fn":"لم ترد في (أ) و(ب).\nانظر: محاسن الاصطلاح: ٦٠٦.\nانظر في ذلك: معرفة علوم الحديث ١٩٠ - ١٩٦، الإرشاد ٢/ ٨٠٤ - ٨١٥، والتقريب ٢٠٠ - ٢٠١، والمنهل الروي: ١٣٩، واختصار علوم الحديث ٢٤٨ - ٢٤٩، والشذا الفياح ٢/ ٧٨٨ - ٧٩٢، والمقنع ٢/ ٦٧٤ - ٦٧٨، وفتح المغيث ٣/ ٣٥٩ - ٣٦٢، وفتح الباقي ٣/ ٢٧٨ - ٢٨٠، وتدريب الراوي ٢/ ٣٨٤ - ٣٨٥، وتوضيح الأفكار ٢/ ٥٠٤ - ٥٠٦، وظفر الأماني: ١٠٥.\nفي (أ): «تنسب».\nفي (أ): «تنسب»، وفي (م) والشذا زيادة «إلى أوطانهم» بعد تنتسب.\nانظر: تهذيب الأسماء واللغات ١/ ١٣.\nالناقلة ضد القاطنين، قال في اللسان: «الناقلة من الناس: خلاف القطّان»، والمراد الذين دأبهم الانتقال من مكان إلى آخر. انظر: لسان العرب ١١/ ٦٣٤، ومتن اللغة ٥/ ٥٣٧\nفي (ج): «بالأولى»."}],[1968,"ولنقتدِ بالحاكمِ أبي عبدِ اللهِ الحافظِ فَنَروِي أحاديثَ بأسانيدِها مُنبِّهينَ عَلَى بلادِ رواتِها، ومُستحسَنٌ مِنَ الحافظِ أنْ يورِدَ الحَدِيْثَ بإسنادِهِ ثُمَّ يَذْكُرَ أوطانَ رجالِهِ واحِدًا فَوَاحِدًا وهكذا غيرَ ذَلِكَ مِنْ أحوالهِم."],[1969,"أخبرني الشَّيْخُ المُسْنَدُ المُعَمَّرُ (٣) أَبُو حَفْصٍ عُمَرُ بنُ مُحَمَّدِ بنِ المُعَمَّرِ - رحمه الله - بقراءتي عَلَيْهِ ببغدادَ، قَالَ أخْبَرَنا أَبُو بَكْرٍ مُحَمَّدُ بنُ عَبْدِ الباقي بنِ مُحَمَّدٍ الأنصاريُّ، قَالَ أخْبَرنا أَبُو إسحاقَ إِبْرَاهِيمُ بنُ عُمَرَ بنِ أَحْمَدَ البَرْمَكِيُّ، قَالَ أخبَرنا أَبُو مُحَمَّدٍ عَبْدُ اللهِ بنُ إِبْرَاهِيمَ بنِ أيُوبَ بنِ مَاسِي (١)، قَالَ حَدَّثَنَا أَبُو مُسْلِمٍ إِبْرَاهِيمُ بنُ عَبْدِ اللهِ الكَجِّيُّ (٢)، قَالَ: حَدَّثَنَا (٣) مُحَمَّدُ بنُ عبدِ اللهِ الأنصارِيُّ، قالَ: حَدَّثَنا (٤) سُليمانُ التَّيْمِيُّ عنْ أنسٍ قَالَ: قَالَ رَسُوْلُ اللهِ - صلى الله عليه وآله وسلم -: «لا هِجْرةَ بَيْنَ المُسلِمينَ فَوْقَ ثَلاَثَةِ أيَّامٍ أَوْ قَالَ: ثَلاَثِ لَيالٍ» (٥).","",{"fn":"راجع: محاسن الاصطلاح ٦٠٧.\nقال الإمام النّوويّ: «عادة الأئمة الحذّاق المصنفين في الأسماء والأنساب أن ينسبوا الرجل النسب العام ثمّ الخاص ليحصل في الثّاني فائدة لم تكن في الأوّل فيقولون مثلًا: فلان بن فلان القريشي الهاشمي؛ لأنه لا يلزم من كونه قرشيًا كونه هاشميًا ولا يعسكون فيقولون الهاشمي القرشي فإنه لا فائدة في الثّاني حِيْنَئذٍ فإنه يلزم من كونه هاشميًا كونه قرشيًا، فإن قيل فينبغي ألا يذكروا القريشي بل يقتصروا عَلَى الهاشمي فالجواب أنَّهُ قد يخفى عَلَى بعض الناس كون الهاشمي قرشيًا ويظهر هذا الخفاء في البطون الخفية كالأشهل من الأنصار فيقال: الأنصاري الأشهلي، ولو اقتصروا عَلَى الأشهلي لَمْ يعرف كثير من الناس أن الأشهلي من الأنصار أم لا وكذا ما أشبهه فذكروا العام ثمّ الخاص لدفع هذا الوهم وقد يقتصرون عَلَى الخاص وقد يقتصرون عَلَى العام وهذا قليل ثمّ إنهم قد ينسبون إلى البلد بعد القبيلة فيقولون القريشي المكي أو المدني وإذا كان له نسب إلى بلدين بأن يستوطن أحدهما ثمّ الآخر نسبوه غالبًا إليهما وقد يقتصرون عَلَى أحدهما وإذا نسبوه إليهما قدموا الأوّل فقالوا: المكي الدمشقي والأحسن المكي ثمّ الدمشقي وإذا كان من قرية بلدة نسبوه تارة إلى القرية وتارة إلى البلد وتارة إليهما وحينئذ يقدمون البلدة؛ لأنها أعم كَمَا سَبَقَ في القبائل فيقولون فيمن هُوَ من أهل (حرستا) قَرْيَة من قرى الغوطة الَّتِي في كورة من كور دمشق فُلاَن الدِّمَشْقِيّ الحرستاني، وَقَدْ يقولون في مِثْلَهُ فُلاَن الشامي الدِّمَشْقِيّ الحرستاني فينسبونه إلى الإقليم ثمّ البلدة ثمّ القَرْيَة، وَقَدْ ينسبونه إلى الكورة فيقولون الغوطي الحرستاني أو الشامي الدِّمَشْقِيّ الغوطي الحرستاني. ثمّ قَالَ: وينسبون إلى القبيلة مَوْلاَهُمْ لقوله - صلى الله عليه وآله وسلم - مَوْلَى القوم من أنفسهم» وسواء كَانَ مَوْلَى عتاقة وَهُوَ الأكثر أو مَوْلَى حلف ومناصرة أو مَوْلَى إسلام بأن أسلم عَلَى يد واحد من الجعفيين، وَقَدْ ينسبون إلى القبيلة مَوْلَى مولاها. الأسماء واللغات ١/ ١٣، وانظر محاسن الاصطلاح: ٦٠٧.\nانظر ترجمته في السير ٢١/ ٥٠٧."}],[1970,"أخبرني الشَّيْخُ المُسْنِدُ أَبُو الحَسَنِ المُؤيَّدُ بنُ مُحَمَّدِ بنِ عَلِيٍّ المُقْرِئُ - رحمه الله - بقراءتي عَلَيْهِ بنَيْسابورَ عَوْدًا عَلَى بَدْءٍ منْ ذَلِكَ مَرَّةً عَلَى رَأْسِ قَبْرِ مُسْلِمِ بنِ الحَجَّاجِ، قَالَ أَخْبَرَنَا فقيهُ الحَرَمِ أَبُو عَبْدِ اللهِ مُحَمَّدُ بنُ الفَضْل الفُراويُّ عِنْدَ قَبْرِ مُسْلِمٍ أَيْضًَا (ح) (٦) وأخبرتْني أُمُّ المُؤيَّدِ زينبُ بنتُ أبي القاسمِ عَبْدِ الرحمانِ ابنِ الحَسَنِ الشَّعْريِّ بقراءتي عَلَيْهَا بنَيسابورَ مَرَّةً وبقراءةِ غَيْري مَرَّةً رَحِمَها اللهُ، قُلْتُ أَخبركِ إِسْمَاعِيْلُ بنُ أبي القاسم بنِ أبي بكرٍ القارئُ قراءةً عَلَيْهِ، قَالَ أخبرنا أَبُو حَفْصٍ عُمَرُ بنُ أَحْمَدَ بنِ مَسْرُورٍ، قَالَ أَخْبَرَنَا أَبُو عَمْرٍو إِسْمَاعِيْلُ بنُ نُجَيْدٍ السُّلميُّ، قَالَ أَخْبَرَنَا أَبُو مُسْلِمٍ إِبْرَاهِيمُ بنُ عَبْدِ اللهِ الكَجِّيُّ، قَالَ حَدَّثَنَا (١) مُحَمَّدُ ابنُ عَبْدِ اللهِ الأنصاريُّ، قَالَ حَدَّثَنِي حُمَيْدٌ الطَّوِيلُ عَنْ أنسِ بنِ مَالِكٍ قَالَ: قَالَ رَسُوْلُ اللهِ - صلى الله عليه وآله وسلم -: «انْصُرْ أَخَاكَ ظَالِمًا أَوْ مَظْلُومًا» قُلْتُ: «يا رَسُوْلَ اللهِ! أنْصُرُهُ مَظْلُومًا، فكيفَ أَنْصُرُهُ ظَالِمًا؟» قَالَ: «تَمْنَعُهُ مِنَ الظُّلْمِ، فَذلِكَ نَصْرُكَ إِيَّاهُ» (٢).","",{"fn":"في الشذا: «ماس».\nضبطه صاحب الأنساب ٤/ ٥٩٢: «بفتح الكاف والجيم المشددة، هذه النسبة إلى الكج، وهو الجص» وذكره صاحب التاج ٦/ ١٧١ بالضم.\nفي (م): «أخبرنا».\nفي (م): «أخبرنا».\nأخرجه مالك في الموطأ (يحيى الليثي (٢٦٣٩)، وأبو مصعب الزّهريّ (١٨٩٤)، وسويد ابن سعيد (٦٨١)، وعبد الرحمان بن القاسم (٤»، والطيالسي (٢٠٩١)، وعبد الرزاق (٢٠٢٢٢)، والحميدي (١١٨٣)، وأحمد ٣/ ١١٠ و١٦٥ و١٩٩ و٢٠٩ و٢٢٥، والبخاري ٨/ ٢٣ (٦٠٦٥) و٢٥ (٦٠٧٦) وفي الأدب المفرد (٣٩٨)، ومسلم ٨/ ٨ (٢٥٥٩) (٢٣) و٩ (٢٥٥٩) (٢٣)، وأبو داود (٤٩١٠)، والترمذي (١٩٣٥)، وأبو يعلى (٣٥٤٩) و(٣٥٥٠) و(٣٥٥١) و(٣٦١٢)، وأبو عوانة كما في إتحاف المهرة ٢/ ٣٠٥ و٣٠٦، والطحاوي في شرح مشكل الآثار (٤٥٤) و(٤٥٥)، وابن حبان (٥٦٧٠) وفي ط الرسالة (٥٦٦٠)، والطبراني في الأوسط (٧٨٧٠)، وأبو نعيم في الحلية ٣/ ٣٧٤ وفي أخبار أصبهان ١/ ٢٥٧، والبيهقي في السّنن ٧/ ٣٠٣ و١٠/ ٢٣٢ وفي شعب الإيمان (٦٦١٥) و(٦٦١٦)، وابن عبد البر في التمهيد ٦/ ١١٦، والبغوي (٣٥٢٢)، عن أنس به.\nهذه حاء التحويل، وقد سقطت من (م)."}],[1971,"الحديثانِ عاليانِ فِي السَّمَاعِ مَعَ نَظَافةِ (٣) السَّنَدِ وصحَّةِ المَتْنِ، وأنسٌ فِي الأَوَّلِ، فمن دُونَهُ إلى أبي مُسْلِمٍ بَصْريونَ، ومَنْ بعدِ أبي مُسْلِمٍ إلى شَيْخِنا فِيهِ بغداديونَ. وَفِي الحَدِيْثِ الثَّانِي أنسٌ فمَنْ دُونَهُ إلى أبي مُسْلِمٍ كَمَا ذَكَرناهُ بصريونَ، ومَنْ بَعْدَهُ مِنَ ابنِ نُجَيْدٍ إلى شَيْخِنا (٤) نَيْسابوريونَ."],[1972,"أخبرَني الشَّيْخُ الزَّكِيُ أَبُو الفَتْحِ مَنْصُورُ بنُ عَبْدِ المُنعِمِ بنِ أبي البركاتِ بنِ الإمامِ أبي عَبْدِ اللهِ مُحَمَّدِ بنِ الفَضْلِ (٥) الفُرَاوِيُّ بقراءتي عَلَيْهِ بِنَيْسابورَ -رحمه الله- قَالَ: أَخْبَرَنَا جَدِّي أَبُو عَبْدِ اللهِ مُحَمَّدُ بنُ الفَضْلِ، قَالَ: أَخْبَرَنَا أَبُو عُثمانَ سعيدُ ابنُ مُحَمَّدٍ البَحِيريُّ - رحمه الله - قَالَ: أَخْبَرَنَا أَبُو سعيدٍ مُحَمَّدُ بنُ عَبْدِ اللهِ بنِ حَمْدُونَ، قَالَ: أَخْبَرَنَا أَبُو حاتِم مَكِّيُّ بنُ عَبْدانَ، قَالَ: أَخْبَرَنَا عَبْدُ الرحمانِ بنُ بِشْرٍ قَالَ: أَخْبَرَنَا عَبْدُ الرَّزاقِ (٦)، قَالَ: أَخْبَرَنَا ابنُ جُرَيجٍ، قَالَ: أخبرني عَبْدَةُ بنُ أبي لُبَابَةَ أنَّ وَرَّادًا مَوْلَى المُغِيرَةِ بنِ شُعْبَةَ أخبرَهُ: أنَّ المُغِيرةَ بنَ شُعبةَ كَتَبَ إلى مُعاويةَ كَتَبَ ذَلِكَ الكِتَابَ لَهُ وَرَّادٌ، إنّي سَمِعْتُ رَسُوْلَ اللهِ - صلى الله عليه وآله وسلم - يقولُ حِيْنَ يُسَلِّمُ: «لا إلهَ إلاَّ اللهُ وَحْدَهُ لا شَرِيكَ لَهُ، لَهُ المُلْكُ وله الحَمْدُ، اللَّهُمَّ لا مانعَ لِمَا أعْطَيْتَ، ولا مُعْطِيَ لِمَا مَنَعْتَ، ولا يَنْفَعُ ذا الجَدِّ مِنْكَ الجدُّ» (١).","",{"fn":"في (م): «أخبرنا».\nأخرجه أحمد ٣/ ٩٩ و٢٠١، وعبد بن حميد (١٤٠١)، والبخاري ٣/ ١٦٨ (٢٤٤٣) و(٢٤٤٤) و٩/ ٢٨ (٦٩٥٢)، والتّرمذي (٢٢٥٥)، وأبو يعلى (٣٨٣٨)، وابن حبان (٥١٧٥) و(٥١٧٦) وط الرسالة (٥١٦٧) و(٥١٦٨)، والطبراني في الصغير (٥٧٦)، وأبو نعيم في الحلية ٣/ ٩٤ و١٠ و٤٠٥ وفي تاريخ أصبهان ٢/ ١٥، والقضاعي في مسند الشهاب (٦٤٦)، والبيهقي ٦/ ٩٤ و١٠/ ٩، والبغوي (٣٥١٦)، وابن عساكر في تاريخ دمشق ٢/ ٣٩ و٥/ ٣٣١. من طرق عن أنس، به. وأخرجه عبد بن حميد (١٤٠١)، وأبو يعلى (٣٨٣٨) من طريق يزيد بن هارون عن سليمان التيمي عن الحسن مرسلًا.\nفي (ع) والتقييد: «لطافة» وما أثبتناه من النسخ و(م) والشذا.\nفي الشذا: «شيخينا».\nفي (ج): «ابن أبي الفضل».\nفي مصنفه (٣٢٢٤)."}],[1973,"المُغِيرَةُ بنُ شُعْبَةَ وَوَرَّادٌ وعَبْدَةُ: كُوفيونَ، وابنُ جُرَيْجٍ: مَكِّيٌّ، وعبدُ الرزاقِ: صَنعانيٌّ يَمَانٍ (٢)، وعبدُ الرحمانِ بنُ بِشْرٍ فَشَيْخُنا ومَنْ بَيْنَهُمَا أجمعونَ: نيسابوريونَ."],[1974,"وللهِ سبحانَهُ الحَمْدُ الأتَمُّ عَلَى مَا أسبَغَ مِنْ إفضالِهِ، والصَّلاةُ والسَّلامُ الأفضلانِ عَلَى سَيِّدِنا مُحَمَّدٍ وآلِهِ وعلى سائِرِ النَّبيينَ وآلِ كُلٍّ، نِهايةَ مَا يَسألُ السائلونَ وغَايةَ مَا يأمُلُ الآملونَ. آمِيْنَ، آمِيْنَ، آمِيْنَ (٣).","",{"fn":"وأخرجه الحميدي (٧٦٢)، وأحمد ٤/ ٢٤٥ و٢٤٧ و٢٥٠ و٢٥١ و٢٥٤ و٢٥٥، وعبد بن حميد (٣٩٠) و(٣٩١)، والدارمي (١٣٥٦)، والبخاري ١/ ٢١٤ (٨٤٤) و٨/ ٩٠ (٦٣٣٠) و١٢٤ (٦٤٧٣) و١٥٧ (٦٦١٥) و٩/ ١١٧ (٧٢٩٢) وفي الأدب المفرد (٤٦٠)، ومسلم ٢/ ٩٥ (٥٩٣) (١٣٧) و٩٦ (٥٩٣) (١٣٨)، وأبو داود (١٥٠٥)، والنّسائيّ ٣/ ٧٠و٧١ وفي الكبرى (١٢٦٤) و(١٢٦٥) و(١٢٦٦) و(٩٩٥٧) و(٩٩٥٨) وفي عمل اليوم والليلة (١٢٩) و(١٣٠)، وابن خزيمة (٧٤٢)، والطبراني في الأوسط (٣٧٠٩) وأبو نعيم في الحلية ٧/ ٢٤٤، والخطيب في تاريخ بغداد ١٠/ ٢٧١ - ٢٧٢، والبغوي (٧١٥) عن المغيرة بن شعبة، به.\nفي (أ) و(ب) والشذا: «يماني» وكلاهما جائز في النسبة إلى اليمن، فالألف عوض من ياء النسب. انظر: الصحاح ٦/ ٢٢١٩، والأنساب ٥/ ٦٢٢.\nقوله: «آمين، آمين، آمين» ساقطة من (أ) والشذا والتقييد. وفي (ب): «آمين يا رب العالمين». تنبيه: جاء في خاتمة نسخة (ب): «وقع الفراغ من تحرير كتاب \" علوم الحديث \" بحمد الله تعالى ومنّه، يوم الأربعاء غرة شوال سنة سبع وثمان مئة برباط النورية بالشُّونيزيّة بجانب الغربي من مدينة السلام بغداد - عمّرها الله تَعَالَى مع سائر بلاد المسلمين آمين - عَلَى يد أضعف عباد الله تَعَالَى وأحوجهم إلى عفوه وغفرانه مُحَمَّد بن عبد الرحمان بن مُحَمَّد بن عبد الرحمان الإسفراييني تاب الله عليه توبة نصوحًا وغفر له ولوالديه ولمشايخه وللمحسنين إليه ويرحم الله عبدًا قال آمينًا». ="}],[1975,". . . . . . . . . . . . . . . . . . . . . . ."]])